-- Daily push notifications (pregnancy_day_notifications, mommy_day_notifications) translated into
-- es, fr, hi, id, ja, ko, nl, pl, pt, sv, vi, zh (owner request 2026-11-12; human-quality translation, not machine/Gemini). Batch 20261112230000_push_notifications_i18n_wave2.
-- Only empty cells are filled; existing text is never overwritten. Tables already CDC enrolled and writer guarded.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '300s';
DO $$ BEGIN
  IF (SELECT count(*) FROM _anacan_gcp_migration.guarded_relations WHERE schema_name = 'public'
      AND table_name IN ('pregnancy_day_notifications', 'mommy_day_notifications')) <> 2 THEN
    RAISE EXCEPTION 'PUSH_I18N_GUARD_MISSING'; END IF;
END $$;
UPDATE public.mommy_day_notifications SET body_es = 'Elige el parque más cercano y disfruta del día.', body_fr = 'Choisissez le parc le plus proche et profitez de la journée.', body_hi = 'सबसे नज़दीकी पार्क चुनिए और दिन का आनंद लीजिए।', body_id = 'Pilih taman terdekat dan nikmati hari ini.', body_ja = 'いちばん近い公園を選んで、1日を楽しみましょう。', body_ko = '가장 가까운 공원을 골라 하루를 즐겨 보세요.', body_nl = 'Kies het dichtstbijzijnde park en geniet van de dag.', body_pl = 'Wybierz najbliższy park i ciesz się dniem.', body_pt = 'Escolha o parque mais próximo e aproveite o dia.', body_sv = 'Välj närmaste park och njut av dagen.', body_vi = 'Hãy chọn công viên gần nhất và tận hưởng một ngày thật vui.', body_zh = '去最近的公园，享受这一天吧。' WHERE id = '0e6fe355-3307-4562-8e24-f479625f3ff6' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿A veces le abrigas poco y otras demasiado? No dudes más. Mira Tiempo y ropa y vístele con confianza.', body_fr = 'Parfois trop peu couvert, parfois trop chaudement habillé ? N''hésitez plus. Consultez Météo et tenue et habillez-le en toute confiance.', body_hi = 'कभी बहुत कम कपड़े, कभी बहुत गरम कपड़े पहना देती हैं? झिझकिए मत। मौसम और कपड़े देखिए और भरोसे से कपड़े पहनाइए।', body_id = 'Kadang terlalu tipis, kadang terlalu tebal pakaiannya? Jangan ragu. Cek Cuaca dan Pakaian dan pakaikan baju dengan percaya diri.', body_ja = '寒くさせすぎたり、厚着させすぎたりしていませんか？迷わないで。「天気と服装」をチェックして、自信をもって服を着せましょう。', body_ko = '가끔은 너무 얇게, 가끔은 너무 두껍게 입히나요? 망설이지 마세요. 날씨와 옷차림을 확인하고 자신 있게 입혀 주세요.', body_nl = 'Kleed je je baby soms te koud en soms te warm aan? Twijfel niet. Kijk in Weer en kleding en kleed hem met vertrouwen aan.', body_pl = 'Czasem ubierasz go za lekko, a czasem za ciepło? Nie wahaj się. Sprawdź Pogodę i ubiór i ubieraj go z pewnością.', body_pt = 'Umas vezes agasalha-o de menos, outras vezes de mais? Não hesite. Veja o Tempo e Roupa e vista-o com confiança.', body_sv = 'Klär du ibland barnet för tunt och ibland för varmt? Tveka inte. Kolla Väder och kläder och klä på barnet med trygghet.', body_vi = 'Lúc thì mặc cho bé quá mỏng, lúc lại quá ấm? Đừng do dự. Xem Thời tiết và trang phục rồi tự tin mặc đồ cho bé.', body_zh = '有时穿得太少，有时又穿得太多？别犹豫，查看天气穿衣，放心给宝宝穿吧。' WHERE id = '4085929a-ec71-4c5c-a693-62bb796910ba' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un gran comilón 🥣', body_es = '¿Ya se come el puré con ganas? ¡Se está haciendo mayor!', title_fr = 'Un vrai petit gourmand 🥣', body_fr = 'Il mange déjà sa purée avec plaisir ? Il grandit !', title_hi = 'नन्हा खाऊ 🥣', body_hi = 'अब वह प्यूरी मज़े से खाता है? वह बड़ा हो रहा है!', title_id = 'Si pemakan lahap 🥣', body_id = 'Ia sudah makan puree dengan lahap? Ia sedang tumbuh!', title_ja = '小さな食いしんぼう 🥣', body_ja = 'もうペーストをおいしそうに食べていますか？ぐんぐん大きくなっています！', title_ko = '꼬마 먹보 🥣', body_ko = '이제 퓌레를 맛있게 잘 먹나요? 아기가 자라고 있어요!', title_nl = 'Een kleine smulpaap 🥣', body_nl = 'Eet je baby de hapjes nu met plezier? Hij wordt groot!', title_pl = 'Mały wielki smakosz 🥣', body_pl = 'Już z apetytem je przeciery? Rośnie!', title_pt = 'Um grande comilão 🥣', body_pt = 'Já come o puré com gosto? Está a crescer!', title_sv = 'En stor liten matglad 🥣', body_sv = 'Äter barnet redan purén med förtjusning? Barnet växer!', title_vi = 'Bé ham ăn 🥣', body_vi = 'Bé đã ăn món nghiền ngon lành? Bé đang lớn đấy!', title_zh = '小小吃货 🥣', body_zh = '宝宝已经开开心心地吃果泥了？宝宝在长大！' WHERE id = 'baf623af-022a-4483-b233-e77e915f194b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Creamos el hábito de beber agua. 💧', body_es = 'No olvides ofrecerle agua junto con la alimentación complementaria.', title_fr = 'On prend l''habitude de boire de l''eau. 💧', body_fr = 'N''oubliez pas de lui proposer de l''eau avec les repas solides.', title_hi = 'पानी पीने की आदत डाल रहे हैं 💧', body_hi = 'ऊपरी आहार के साथ पानी देना मत भूलिए।', title_id = 'Membangun kebiasaan minum air. 💧', body_id = 'Jangan lupa menawarkan air bersamaan dengan MPASI.', title_ja = 'お水を飲む習慣をつけよう。💧', body_ja = '離乳食と一緒にお水をあげるのを忘れずに。', title_ko = '물 마시는 습관 만들기 💧', body_ko = '이유식과 함께 물을 주는 것도 잊지 마세요.', title_nl = 'We leren water drinken. 💧', body_nl = 'Vergeet niet om naast de bijvoeding ook water aan te bieden.', title_pl = 'Uczymy się pić wodę. 💧', body_pl = 'Nie zapominaj podawać wody razem ze stałymi pokarmami.', title_pt = 'Estamos a criar o hábito de beber água. 💧', body_pt = 'Não se esqueça de oferecer água juntamente com a comida.', title_sv = 'Vi skapar en vana att dricka vatten. 💧', body_sv = 'Glöm inte att erbjuda vatten tillsammans med smakportionerna.', title_vi = 'Tập thói quen uống nước. 💧', body_vi = 'Đừng quên cho bé uống nước cùng với bữa ăn dặm.', title_zh = '培养喝水的习惯 💧', body_zh = '吃辅食时别忘了给宝宝喝点水。' WHERE id = 'f175db80-862d-40e7-9aed-5b0a0c4423e3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coales