UPDATE public.mommy_day_notifications SET title_es = 'Intentos de gatear 🐢', body_es = '¿Se pone de rodillas y se balancea adelante y atrás? ¡Se está preparando para gatear!', title_fr = 'Premiers essais pour ramper 🐢', body_fr = 'Il se tient à genoux et se balance d''avant en arrière ? Il se prépare à ramper !', title_hi = 'खिसकने की कोशिशें 🐢', body_hi = 'घुटनों पर टिककर आगे-पीछे झूलता है? वह खिसकने की तैयारी कर रहा है!', title_id = 'Mencoba merangkak 🐢', body_id = 'Ia bertumpu pada lutut dan bergoyang maju mundur? Ia sedang bersiap merangkak!', title_ja = 'はいはいへの挑戦 🐢', body_ja = 'ひざで立って、前後にゆらゆらしていますか？はいはいの準備をしています！', title_ko = '기어가기 도전 🐢', body_ko = '무릎을 꿇고 앞뒤로 흔들흔들하나요? 기어갈 준비를 하고 있어요!', title_nl = 'Pogingen om te kruipen 🐢', body_nl = 'Zit je baby op handen en knieën en wiegt hij heen en weer? Hij maakt zich klaar om te kruipen!', title_pl = 'Próby raczkowania 🐢', body_pl = 'Stoi na kolanach i kołysze się w przód i w tył? Szykuje się do raczkowania!', title_pt = 'Tentativas de rastejar 🐢', body_pt = 'Põe-se de joelhos e balança para a frente e para trás? Está a preparar-se para rastejar!', title_sv = 'Krypförsök 🐢', body_sv = 'Står barnet på knäna och gungar fram och tillbaka? Det förbereder sig för att krypa!', title_vi = 'Tập trườn 🐢', body_vi = 'Bé chống gối và đung đưa tới lui? Bé đang chuẩn bị để bò đấy!', title_zh = '尝试爬行 🐢', body_zh = '宝宝跪着前后摇晃？宝宝正在为爬行做准备！' WHERE id = '3ad2c870-178d-449f-aabd-6c01acacefd8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coale