UPDATE public.mommy_day_notifications SET title_es = 'Deja salir tus emociones 📝', title_fr = 'Libérez vos émotions 📝', title_hi = 'अपनी भावनाओं को बाहर आने दीजिए 📝', title_id = 'Lepaskan perasaan Anda 📝', title_ja = '気持ちを解き放とう 📝', title_ko = '감정을 자유롭게 풀어 주세요 📝', title_nl = 'Laat je gevoelens de vrije loop 📝', title_pl = 'Uwolnij emocje 📝', title_pt = 'Liberte as emoções 📝', title_sv = 'Släpp fram känslorna 📝', title_vi = 'Hãy giải phóng cảm xúc 📝', title_zh = '释放你的情绪 📝' WHERE id = 'ec24c154-30dc-40d8-8aed-20579933d8fb' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La calma de la noche 🛀', title_fr = 'La sérénité du soir 🛀', title_hi = 'रात का सुकून 🛀', title_id = 'Ketenangan malam 🛀', title_ja = '夜のやすらぎ 🛀', title_ko = '밤의 평온 🛀', title_nl = 'De rust van de nacht 🛀', title_pl = 'Spokój nocy 🛀', title_pt = 'A calma da noite 🛀', title_sv = 'Nattens ro 🛀', title_vi = 'Sự bình yên của màn đêm 🛀', title_zh = '夜晚的宁静 🛀' WHERE id = '39e6032f-d2bf-40b5-98db-1f2ab3a5a379' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora del cuento de papá 📖', title_fr = 'L''heure du livre avec papa 📖', title_hi = 'पापा का किताब वाला समय 📖', title_id = 'Jam baca ayah 📖', title_ja = 'パパの絵本タイム 📖', title_ko = '아빠의 책 읽기 시간 📖', title_nl = 'Papa''s voorleesuurtje 📖', title_pl = 'Czytanie z tatą 📖', title_pt = 'A hora do livro com o pai 📖', title_sv = 'Pappas sagostund 📖', title_vi = 'Giờ đọc sách của bố 📖', title_zh = '爸爸的故事时间 📖' WHERE id = '491d12b8-51d5-4984-8dda-d40fbb4e95c8' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Tira los juguetes al suelo una y otra vez? 🧸', body_es = 'Está aprendiendo la relación causa-efecto. Para juguetes nuevos, echa un vistazo a los Productos recomendados.', title_fr = 'Il jette souvent ses jouets par terre ? 🧸', body_fr = 'Il apprend la relation de cause à effet. Pour de nouveaux jouets, consultez les Produits recommandés.', title_hi = 'खिलौने बार-बार नीचे फेंकता है? 🧸', body_hi = 'वह कारण और परिणाम का रिश्ता सीख रहा है। नए खिलौनों के लिए सुझाए गए प्रोडक्ट देख सकती हैं।', title_id = 'Sering melempar mainan ke lantai? 🧸', body_id = 'Ia sedang belajar tentang sebab dan akibat. Untuk mainan baru, Anda bisa melihat Produk Rekomendasi.', title_ja = 'おもちゃをよく床に落としますか？🧸', body_ja = 'これは原因と結果の関係を学んでいるのです。新しいおもちゃは「おすすめ商品」でチェックできます。', title_ko = '장난감을 자꾸 바닥에 던지나요? 🧸', body_ko = '원인과 결과를 배우고 있는 거예요. 새 장난감은 추천 제품에서 찾아볼 수 있어요.', title_nl = 'Gooit je baby vaak speeltjes op de grond? 🧸', body_nl = 'Zo leert je kleintje oorzaak en gevolg. Voor nieuwe speeltjes kun je kijken bij Aanbevolen producten.', title_pl = 'Często rzuca zabawki na podłogę? 🧸', body_pl = 'W ten sposób uczy się związku przyczyny i skutku. Nowe zabawki znajdziesz w Polecanych produktach.', title_pt = 'Atira os brinquedos ao chão muitas vezes? 🧸', body_pt = 'Está a aprender a relação de causa e efeito. Para brinquedos novos, pode ver os Produtos Recomendados.', title_sv = 'Kastar barnet ofta leksakerna på golvet? 🧸', body_sv = 'Barnet lär sig om orsak och verkan. Kika i Rekommenderade produkter efter nya leksaker.', title_vi = 'Bé hay ném đồ chơi xuống đất? 🧸', body_vi = 'Bé đang học về quan hệ nhân quả đấy. Mẹ có thể xem Sản phẩm gợi ý để tìm đồ chơi mới.', title_zh = '总把玩具扔到地上？🧸', body_zh = '这是宝宝在学习因果关系。想找新玩具，可以看看推荐商品。' WHERE id = '61f15500-8617-42e1-b833-c482f6ae935c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorando con la boca 🦷', body_es = '¿Lo muerde todo con ganas, sobre todo sus deditos? ¡El Seguimiento de dentición te avisa! Es hora de preparar mordedores limpios.', title_fr = 'Exploration par la bouche 🦷', body_fr = 'Il mâchouille tout intensément, surtout ses doigts ? Le Suivi des dents vous prévient ! C''est le moment de préparer des anneaux de dentition propres.', title_hi = 'मुँह से खोजबीन 🦷', body_hi = 'हर चीज़, खासकर अपनी उँगलियाँ, ज़ोर-ज़ोर से चबा रहा है? दाँत निकलने का ट्रैकर संकेत दे रहा है! साफ़ टीथिंग रिंग तैयार करने का समय है।', title_id = 'Menjelajah lewat mulut 🦷', body_id = 'Ia mengunyah semua benda, terutama jarinya sendiri, dengan gigih? Pelacak Tumbuh Gigi memberi tanda! Saatnya menyiapkan teether yang bersih.', title_ja = 'お口で探検 🦷', body_ja = 'なんでも、とくに自分の指をしきりにかんでいますか？「歯の生え始めトラッカー」からのお知らせです！清潔な歯固めリングを用意するときです。', title_ko = '입으로 탐험 중 🦷', body_ko = '무엇이든, 특히 자기 손가락을 열심히 깨무나요? 이앓이 기록이 알려 주고 있어요! 깨끗한 치아발육기를 준비할 때예요.', title_nl = 'Ontdekken met de mond 🦷', body_nl = 'Kauwt je baby fanatiek op alles, vooral op de eigen vingers? De Tandjestracker waarschuwt! Tijd om schone bijtringen klaar te leggen.', title_pl = 'Odkrywanie buzią 🦷', body_pl = 'Intensywnie gryzie wszystko, zwłaszcza własne paluszki? Narzędzie do śledzenia ząbkowania ostrzega! Czas przygotować czyste gryzaki.', title_pt = 'Exploração pela boca 🦷', body_pt = 'Mastiga tudo com força, sobretudo os próprios dedos? O Registo de Dentição está a dar o alerta! É hora de preparar argolas de dentição limpas.', title_sv = 'Upptäcktsfärd med munnen 🦷', body_sv = 'Tuggar barnet intensivt på allt, särskilt sina egna fingrar? Tandspåraren varnar! Dags att ta fram rena bitringar.', title_vi = 'Khám phá bằng miệng 🦷', body_vi = 'Bé gặm mọi thứ, nhất là ngón tay của mình? Theo dõi mọc răng đang báo hiệu! Đến lúc chuẩn bị vòng gặm nướu sạch rồi.', title_zh = '用嘴探索世界 🦷', body_zh = '什么都使劲啃，尤其是自己的手指？出牙追踪在提醒你啦！该准备干净的牙胶了。' WHERE id = '92d9f590-3160-4e15-966d-3ee82f9db1d0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fuerza de la unión 💬', body_es = 'Esta tarde entra en la Comunidad Anacan y comenta el desarrollo de tu peque con mamás que están en el mismo mes que tú.', title_fr = 'La force de l''entraide 💬', body_fr = 'Ce soir, rejoignez la Communauté Anacan et échangez sur le développement de vos bébés avec les mamans qui en sont au même mois que vous.', title_hi = 'साथ की ताकत 💬', body_hi = 'आज शाम Anacan कम्युनिटी में आइए और अपने ही महीने वाली माँओं के साथ विकास के अनुभव बाँटकर चर्चा कीजिए।', title_id = 'Kekuatan kebersamaan 💬', body_id = 'Malam ini, masuklah ke Komunitas Anacan dan diskusikan perkembangan si kecil bersama ibu-ibu yang berada di bulan yang sama.', title_ja = '支え合う力 💬', body_ja = '今夜はAnacanコミュニティを開いて、同じ月齢の赤ちゃんを育てるママたちと成長の様子をシェアして話し合いましょう。', title_ko = '함께하는 힘 💬', body_ko = '오늘 저녁 Anacan 커뮤니티에 들어가 같은 개월 수의 엄마들과 아기의 성장 과정을 나누고 이야기해 보세요.', title_nl = 'De kracht van samen 💬', body_nl = 'Ga vanavond naar de Anacan Community en praat met moeders van baby''s van dezelfde maand over hoe hun kleintjes groeien.', title_pl = 'Siła wsparcia 💬', body_pl = 'Dziś wieczorem wejdź do Społeczności Anacan i porozmawiaj o rozwoju maluszka z mamami dzieci w tym samym miesiącu.', title_pt = 'A força da união 💬', body_pt = 'Esta noite, entre na Comunidade Anacan e partilhe e discuta o desenvolvimento do bebé com mães que estão no mesmo mês.', title_sv = 'Gemenskapens kraft 💬', body_sv = 'Gå in i Anacans Community i kväll och diskutera utvecklingen med mammor som har barn i samma månad som ditt.', title_vi = 'Sức mạnh của sự đồng cảm 💬', body_vi = 'Tối nay hãy vào Cộng đồng Anacan, chia sẻ và trao đổi về quá trình phát triển của bé với những bà mẹ có con cùng tháng tuổi.', title_zh = '团结的力量 💬', body_zh = '今晚进入Anacan社区，和同月龄宝宝的妈妈们分享、讨论宝宝的发育吧。' WHERE id = '02654c5d-e5dc-4168-b20f-e995771e2a24' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Siéntete orgullosa de ti 👏', body_es = 'Mira a tu alrededor y piensa en todo el camino recorrido. El miedo de las primeras semanas se ha convertido en una confianza de madre total. ¡Eres increíble!', title_fr = 'Soyez fière de vous 👏', body_fr = 'Regardez autour de vous et pensez au chemin parcouru. Les peurs des premières semaines sont devenues une vraie confiance de maman. Vous êtes formidable !', title_hi = 'खुद पर गर्व कीजिए 👏', body_hi = 'कमरे में नज़र डालिए और सोचिए कि आपने कितना लंबा सफ़र तय किया है। पहले हफ़्तों का डर अब एक माँ के पूरे आत्मविश्वास में बदल गया है। आप कमाल की हैं!', title_id = 'Banggalah pada diri Anda 👏', body_id = 'Lihat sekeliling dan renungkan sejauh apa Anda telah melangkah. Ketakutan di minggu-minggu pertama kini berubah menjadi rasa percaya diri seorang ibu. Anda luar biasa!', title_ja = '自分をほめてあげて 👏', body_ja = '部屋を見渡して、ここまでの道のりを振り返ってみて。最初の数週間の不安は、もうすっかりママとしての自信に変わりました。あなたはすばらしい！', title_ko = '스스로를 자랑스러워하세요 👏', body_ko = '방을 둘러보며 얼마나 먼 길을 왔는지 생각해 보세요. 첫 몇 주의 두려움이 이제 엄마로서의 확신으로 바뀌었어요. 정말 멋져요!', title_nl = 'Wees trots op jezelf 👏', body_nl = 'Kijk om je heen en denk na over hoe ver je bent gekomen. De angst van de eerste weken is veranderd in echt moederlijk zelfvertrouwen. Je bent geweldig!', title_pl = 'Bądź z siebie dumna 👏', body_pl = 'Rozejrzyj się i pomyśl, jak długą drogę przeszłaś. Strach z pierwszych tygodni zamienił się w prawdziwą matczyną pewność siebie. Jesteś wspaniała!', title_pt = 'Orgulhe-se de si 👏', body_pt = 'Olhe à sua volta e pense no caminho que já fez. O medo das primeiras semanas transformou-se numa verdadeira confiança de mãe. É fantástica!', title_sv = 'Var stolt över dig själv 👏', body_sv = 'Se dig omkring och tänk på hur långt du har kommit. Rädslan från de första veckorna har blivit en riktig mammatrygghet. Du är fantastisk!', title_vi = 'Hãy tự hào về mình 👏', body_vi = 'Nhìn quanh và nghĩ xem mẹ đã đi được bao xa. Nỗi lo của những tuần đầu giờ đã thành sự tự tin của một người mẹ thực thụ. Mẹ thật tuyệt vời!', title_zh = '为自己骄傲 👏', body_zh = '环顾房间，想想你已经走了多远。最初几周的恐惧，已经变成了满满的妈妈自信。你太棒了！' WHERE id = '158eaa65-78bb-40d6-8e0b-a66fa8dda6b3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dedos de los pies a la boca 👣', body_es = '¡Ha descubierto sus pies e intenta llevárselos a la boca! Haz una foto de este momento tan gracioso y especial para enviársela a tus seres queridos.', title_fr = 'Les orteils dans la bouche 👣', body_fr = 'Il découvre ses pieds et essaie de les mettre dans sa bouche ! Photographiez ce moment drôle et merveilleux pour l''envoyer à vos proches.', title_hi = 'पैर की उँगलियाँ मुँह में 👣', body_hi = 'उसने अपने पैर खोज लिए हैं और उन्हें मुँह तक ले जाने की कोशिश कर रहा है! विकास के इस मज़ेदार और शानदार पल को अपनों को भेजने के लिए ज़रूर रिकॉर्ड कीजिए।', title_id = 'Jari kaki masuk mulut 👣', body_id = 'Ia menemukan kakinya dan mencoba memasukkannya ke mulut! Abadikan momen perkembangan yang lucu dan luar biasa ini untuk dikirim ke orang-orang tersayang.', title_ja = '足の指をお口に 👣', body_ja = '自分の足を発見して、口に入れようとしていますか！このおもしろくてすてきな成長の瞬間を、家族に送れるようにぜひ撮っておきましょう。', title_ko = '발가락이 입속에 👣', body_ko = '자기 발을 발견하고 입으로 가져가려 해요! 이 귀엽고 멋진 성장의 순간을 사진으로 찍어 가족에게 보내 주세요.', title_nl = 'Teentjes in de mond 👣', body_nl = 'Je baby heeft de voetjes ontdekt en probeert ze in de mond te stoppen! Leg dit grappige, geweldige moment zeker vast om naar je dierbaren te sturen.', title_pl = 'Paluszki u stóp w buzi 👣', body_pl = 'Odkrył swoje stópki i próbuje włożyć je do buzi! Koniecznie uwiecznij ten zabawny i wspaniały moment rozwoju, żeby wysłać go bliskim.', title_pt = 'Dedos dos pés na boca 👣', body_pt = 'Descobriu os pés e tenta levá-los à boca! Fotografe sem falta este momento divertido e fantástico para enviar aos seus próximos.', title_sv = 'Tårna i munnen 👣', body_sv = 'Barnet har upptäckt sina fötter och försöker stoppa dem i munnen! Fotografera det här roliga och fantastiska utvecklingsögonblicket och skicka till dina nära.', title_vi = 'Ngón chân trong miệng 👣', body_vi = 'Bé phát hiện ra đôi chân và cố đưa vào miệng! Nhất định phải chụp lại khoảnh khắc phát triển vừa buồn cười vừa tuyệt vời này để gửi cho người thân nhé.', title_zh = '脚趾放进嘴里 👣', body_zh = '宝宝发现了自己的脚，还想把它放进嘴里！一定要拍下这个有趣又精彩的成长瞬间，发给亲友看看。' WHERE id = '50a6a489-6955-49c4-9f2c-e768f813dd17' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Energía para mamá 🔋', body_es = 'Mientras tu bebé mama, tú también quemas calorías. Busca ya en Recetas saludables una sopa ligera que ayude a aumentar la leche.', title_fr = 'De l''énergie pour maman 🔋', body_fr = 'Quand bébé tète, vous aussi vous brûlez des calories. Regardez tout de suite dans les Recettes saines une soupe légère qui favorise la lactation.', title_hi = 'माँ के लिए ऊर्जा 🔋', body_hi = 'बच्चा जितना दूध पीता है, आपकी भी उतनी कैलोरी खर्च होती है। अभी सेहतमंद रेसिपी में दूध बढ़ाने वाले हल्के सूप की रेसिपी देखिए।', title_id = 'Energi untuk Bunda 🔋', body_id = 'Saat bayi menyusu, Anda juga membakar kalori. Segera cek resep sup ringan pelancar ASI di Resep Sehat.', title_ja = 'ママのためのエネルギー 🔋', body_ja = '赤ちゃんが母乳を飲むたび、あなたのカロリーも使われています。すぐに「ヘルシーレシピ」で、母乳によくて軽いスープのレシピをチェックしましょう。', title_ko = '엄마를 위한 에너지 🔋', body_ko = '아기가 젖을 먹는 동안 엄마의 칼로리도 소모돼요. 지금 건강한 레시피에서 젖 분비를 돕는 가벼운 수프 레시피를 확인해 보세요.', title_nl = 'Energie voor mama 🔋', body_nl = 'Terwijl je baby drinkt, verbrand jij ook calorieën. Zoek in Gezonde recepten meteen een licht soepje dat de melkproductie bevordert.', title_pl = 'Energia dla mamy 🔋', body_pl = 'Gdy maluszek ssie pierś, ty też tracisz kalorie. Od razu sprawdź w Zdrowych przepisach lekką zupę wspierającą laktację.', title_pt = 'Energia para a mãe 🔋', body_pt = 'Enquanto o bebé mama, também gasta calorias. Veja já nas Receitas Saudáveis uma sopa leve que ajuda a produzir leite.', title_sv = 'Energi till mamma 🔋', body_sv = 'När barnet ammar förbrukar du också kalorier. Kolla direkt in ett lätt, mjölkökande sopprecept i Hälsosamma recept.', title_vi = 'Năng lượng cho mẹ 🔋', body_vi = 'Khi bé bú, mẹ cũng tiêu hao calo. Xem ngay một công thức súp nhẹ giúp lợi sữa trong Công thức lành mạnh nhé.', title_zh = '妈妈的能量 🔋', body_zh = '宝宝吃奶时，你也在消耗热量。现在就去健康食谱里看看清淡又催奶的汤吧。' WHERE id = '4d4822a8-2d08-4775-b1d8-71202fa22509' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Actualiza los últimos datos en el Seguimiento del desarrollo, mira la gráfica de crecimiento sano de tu bebé y siéntete orgullosa.', body_fr = 'Mettez à jour les dernières mesures dans le Suivi de développement, regardez la courbe de croissance de votre bébé et soyez fière.', body_hi = 'ग्रोथ ट्रैकर सेक्शन में ताज़ा माप अपडेट कीजिए, बच्चे के सेहतमंद विकास का चार्ट देखिए और गर्व महसूस कीजिए।', body_id = 'Perbarui data terbaru di Pelacak Perkembangan, lalu lihat grafik pertumbuhan sehat bayi Anda dan rasakan bangganya.', body_ja = '「発達トラッカー」で最新の記録を更新して、赤ちゃんの健やかな成長グラフを見て誇らしい気持ちになりましょう。', body_ko = '성장 기록 섹션에서 최근 수치를 업데이트하고 아기의 건강한 성장 그래프를 보며 뿌듯함을 느껴 보세요.', body_nl = 'Werk de nieuwste gegevens bij in de Groeitracker, bekijk de gezonde groeicurve van je baby en wees trots.', body_pl = 'Zaktualizuj najnowsze dane w sekcji Śledzenie rozwoju, spójrz na zdrowy wykres rozwoju maluszka i bądź dumna.', body_pt = 'Atualize os últimos dados no Registo de Desenvolvimento, veja o gráfico de crescimento saudável do bebé e orgulhe-se.', body_sv = 'Uppdatera de senaste värdena i Utvecklingsspåraren, titta på barnets sunda utvecklingskurva och känn dig stolt.', body_vi = 'Cập nhật chỉ số mới nhất trong mục Theo dõi phát triển, rồi ngắm biểu đồ phát triển khỏe mạnh của bé và tự hào nhé.', body_zh = '在发育追踪里更新最新数据，看看宝宝健康的成长曲线，为宝宝骄傲吧。' WHERE id = 'dac4f6ca-f7b7-40a3-a427-dece1b15eaf7' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Intentos insistentes 🐢', body_es = '¿Se enfada al intentar avanzar a rastras boca abajo? ¡Ya quiere moverse! Anímale con juguetes a impulsarse hacia delante.', title_fr = 'Des efforts obstinés 🐢', body_fr = 'Sur le ventre, il essaie de ramper vers l''avant et s''énerve ? Il veut déjà bouger ! Encouragez-le à avancer avec des jouets.', title_hi = 'ज़िद्दी कोशिशें 🐢', body_hi = 'पेट के बल रहते हुए आगे खिसकने की कोशिश में चिढ़ जाता है? वह अब चलना-फिरना चाहता है! खिलौनों से उसे आगे बढ़ने के लिए प्रेरित कीजिए।', title_id = 'Usaha pantang menyerah 🐢', body_id = 'Ia kesal karena mencoba merayap maju saat tengkurap? Ia sudah ingin bergerak! Pancing ia maju dengan mainan.', title_ja = 'あきらめない挑戦 🐢', body_ja = 'うつぶせで前に進もうとして、怒っていますか？もう動きたくてたまらないのです！おもちゃで前へ進むよう応援してあげましょう。', title_ko = '끈기 있는 도전 🐢', body_ko = '엎드린 채 앞으로 기어가려다 짜증을 내나요? 이제 움직이고 싶은 거예요! 장난감으로 앞으로 나아가도록 응원해 주세요.', title_nl = 'Volhardende pogingen 🐢', body_nl = 'Raakt je baby gefrustreerd als hij op de buik vooruit probeert te kruipen? Hij wil al bewegen! Moedig hem met speeltjes aan om zich naar voren te trekken.', title_pl = 'Uparte próby 🐢', body_pl = 'Leżąc na brzuszku, próbuje pełzać do przodu i się złości? Już chce się ruszać! Zachęcaj go zabawkami, by sięgał do przodu.', title_pt = 'Tentativas persistentes 🐢', body_pt = 'De barriga para baixo, tenta rastejar para a frente e fica irritado? Já quer mexer-se! Incentive-o com brinquedos a puxar-se para a frente.', title_sv = 'Envisa försök 🐢', body_sv = 'Blir barnet frustrerat när det försöker åla framåt på mage? Det vill redan röra sig! Locka det framåt med leksaker.', title_vi = 'Nỗ lực bền bỉ 🐢', body_vi = 'Khi nằm sấp, bé cố trườn về phía trước rồi bực bội? Bé đã muốn di chuyển rồi! Hãy dùng đồ chơi khích lệ bé rướn người về phía trước nhé.', title_zh = '坚持不懈 🐢', body_zh = '趴着想往前爬却爬不动，急得发脾气？宝宝已经想要移动了！用玩具鼓励宝宝往前够吧。' WHERE id = '648c9f9b-15f6-49e6-933c-3da395b58c88' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Los mordedores entran en acción! 💧', body_es = 'Quiere llevárselo todo a la boca. Echa un vistazo al Blog para saber más sobre seguridad y desarrollo.', title_fr = 'Les anneaux de dentition à la rescousse ! 💧', body_fr = 'Il veut tout porter à sa bouche. Consultez les Blogs pour en savoir plus sur la sécurité et le développement.', title_hi = 'टीदर काम पर! 💧', body_hi = 'वह हर चीज़ मुँह में डालना चाहता है। सुरक्षा और विकास के बारे में और जानने के लिए ब्लॉग देखिए।', title_id = 'Teether beraksi! 💧', body_id = 'Ia ingin memasukkan semua benda ke mulut. Baca Blog kami untuk tahu lebih banyak soal keamanan dan perkembangannya.', title_ja = '歯固めの出番！💧', body_ja = '赤ちゃんはなんでも口に入れたがります。安全と発達についてもっと知るには、ブログをのぞいてみましょう。', title_ko = '치발기 출동! 💧', body_ko = '아기는 무엇이든 입으로 가져가고 싶어 해요. 안전과 발달에 대해 더 알고 싶다면 블로그를 살펴보세요.', title_nl = 'Bijtringen schieten te hulp! 💧', body_nl = 'Je kleintje wil alles in de mond stoppen. Kijk in de Blogs voor meer over veiligheid en ontwikkeling.', title_pl = 'Gryzaki ruszają do akcji! 💧', body_pl = 'Chce wszystko wkładać do buzi. Zajrzyj na Blog, by dowiedzieć się więcej o bezpieczeństwie i rozwoju.', title_pt = 'Mordedores ao ataque! 💧', body_pt = 'Quer levar tudo à boca. Para saber mais sobre segurança e desenvolvimento, espreite os Blogues.', title_sv = 'Bitringarna gör nytta! 💧', body_sv = 'Barnet vill stoppa allt i munnen. Kika i Bloggar för att lära dig mer om säkerhet och utveckling.', title_vi = 'Gặm nướu vào cuộc! 💧', body_vi = 'Bé muốn cho mọi thứ vào miệng. Hãy xem mục Blog để tìm hiểu thêm về an toàn và sự phát triển của bé.', title_zh = '牙胶上场！💧', body_zh = '宝宝什么都想往嘴里放。去博客看看，了解更多关于安全和发育的知识。' WHERE id = '903de81c-9443-4b1e-8662-d8cbed1ca54e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hoy no se limpia 🛑', body_es = '¿Estás cansada? Díselo a tu pareja. Hoy no hay comida casera ni limpieza. ¡Hoy es simplemente el día libre de mamá!', title_fr = 'Pas de ménage aujourd''hui 🛑', body_fr = 'Fatiguée ? Dites-le à votre conjoint. Aujourd''hui, pas de cuisine, pas de ménage. Aujourd''hui, c''est le jour de repos de maman !', title_hi = 'आज सफ़ाई की छुट्टी 🛑', body_hi = 'थक गई हैं? अपने साथी को बताइए। आज न घर का खाना, न सफ़ाई। आज बस माँ की छुट्टी का दिन है!', title_id = 'Hari ini tidak ada bersih-bersih 🛑', body_id = 'Lelah? Beri tahu pasangan Anda. Hari ini tidak ada masak, tidak ada bersih-bersih. Hari ini adalah hari libur Bunda!', title_ja = '今日はお掃除なし 🛑', body_ja = '疲れていますか？パートナーに伝えましょう。今日は手料理もお掃除もなし。今日はママの休日です！', title_ko = '오늘은 청소 금지 🛑', body_ko = '지쳤나요? 배우자에게 말하세요. 오늘은 집밥도 청소도 없어요. 오늘은 엄마가 쉬는 날이에요!', title_nl = 'Vandaag geen schoonmaak 🛑', body_nl = 'Ben je moe? Zeg het tegen je partner. Vandaag geen kookwerk en geen schoonmaak. Vandaag is gewoon mama''s rustdag!', title_pl = 'Dziś bez sprzątania 🛑', body_pl = 'Jesteś zmęczona? Powiedz o tym partnerowi. Dziś bez gotowania i bez sprzątania. Dziś po prostu dzień odpoczynku mamy!', title_pt = 'Hoje não há limpezas 🛑', body_pt = 'Está cansada? Diga ao seu companheiro. Hoje não há comida caseira nem limpezas. Hoje é simplesmente o dia de descanso da mãe!', title_sv = 'Ingen städning i dag 🛑', body_sv = 'Är du trött? Säg till din partner. I dag blir det ingen hemlagad mat och ingen städning. I dag är det helt enkelt mammas vilodag!', title_vi = 'Hôm nay không dọn dẹp 🛑', body_vi = 'Mẹ mệt rồi? Hãy nói với bố. Hôm nay không nấu nướng, không dọn dẹp. Hôm nay chỉ là ngày nghỉ của mẹ!', title_zh = '今天不打扫 🛑', body_zh = '累了吗？告诉你的伴侣。今天不做饭、不打扫，今天就是妈妈的休息日！' WHERE id = '9dd94bee-b76e-43ec-94c9-51937e10ad6e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué falta en casa? 🛒', body_es = '¿Se acabó el champú o el aceite para bebé? No hace falta pensarlo. Rellena la Lista de la compra y el resto es cosa de tu pareja.', title_fr = 'Que manque-t-il à la maison ? 🛒', body_fr = 'Plus de shampooing ou d''huile pour bébé ? Inutile d''y réfléchir. Remplissez la Liste de courses, le reste, c''est le travail de votre partenaire.', title_hi = 'घर में क्या कम है? 🛒', body_hi = 'शैम्पू खत्म हो गया या बेबी ऑयल? सोचने की ज़रूरत नहीं। शॉपिंग लिस्ट भर दीजिए, बाकी आपके साथी का काम है।', title_id = 'Apa yang habis di rumah? 🛒', body_id = 'Sampo atau minyak bayi habis? Tak perlu dipikirkan. Isi saja Daftar Belanja, sisanya tugas pasangan Anda.', title_ja = '家で足りないものは？🛒', body_ja = 'シャンプーやベビーオイルが切れた？考えこまなくて大丈夫。「買い物リスト」に入れたら、あとはパートナーの出番です。', title_ko = '집에 뭐가 떨어졌나요? 🛒', body_ko = '샴푸가 떨어졌나요, 베이비 오일인가요? 고민할 필요 없어요. 쇼핑 목록을 채우면 나머지는 배우자의 몫이에요.', title_nl = 'Wat ontbreekt er in huis? 🛒', body_nl = 'Shampoo of babyolie op? Je hoeft er niet over na te denken. Vul het Boodschappenlijstje aan, de rest is de taak van je partner.', title_pl = 'Czego brakuje w domu? 🛒', body_pl = 'Skończył się szampon albo oliwka dla dziecka? Nie musisz o tym myśleć. Uzupełnij Listę zakupów, resztą zajmie się partner.', title_pt = 'O que falta em casa? 🛒', body_pt = 'Acabou o champô ou o óleo de bebé? Não precisa de pensar. Preencha a Lista de Compras, o resto é com o seu companheiro.', title_sv = 'Vad saknas hemma? 🛒', body_sv = 'Har schampot eller babyoljan tagit slut? Du behöver inte fundera. Fyll i Inköpslistan, resten är din partners jobb.', title_vi = 'Nhà mình còn thiếu gì? 🛒', body_vi = 'Hết dầu gội hay dầu em bé rồi? Mẹ không cần nghĩ nhiều. Cứ điền vào Danh sách mua sắm, phần còn lại là việc của bố.', title_zh = '家里缺什么？🛒', body_zh = '洗发水还是婴儿油用完了？不用多想，填好购物清单，剩下的交给伴侣吧。' WHERE id = '1a9e3246-5c48-4c5d-9be8-b35243065267' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Filtra los ruidos 🤫', body_es = 'Los ruidos de la calle impiden el sueño profundo. Mira el Medidor de sonido y, si hace falta, usa ruido blanco de fondo.', title_fr = 'Filtrez les bruits 🤫', body_fr = 'Les bruits de la rue empêchent un sommeil profond. Consultez le Sonomètre et, si besoin, utilisez un bruit blanc en fond sonore.', title_hi = 'आवाज़ों को छानिए 🤫', body_hi = 'सड़क से आने वाली आवाज़ें गहरी नींद में बाधा डालती हैं। साउंड मीटर देखिए और ज़रूरत हो तो पीछे व्हाइट नॉइज़ चलाइए।', title_id = 'Saring kebisingan 🤫', body_id = 'Suara dari jalan bisa mengganggu tidur nyenyak. Cek Pengukur Suara dan gunakan white noise di latar belakang bila perlu.', title_ja = '音をシャットアウト 🤫', body_ja = '外からの音が深い眠りのじゃまになります。「サウンドメーター」を見て、必要ならホワイトノイズを流しましょう。', title_ko = '소음을 걸러 내요 🤫', body_ko = '바깥에서 들려오는 소리가 깊은 잠을 방해해요. 소음 측정기를 확인하고 필요하면 배경 백색소음을 활용하세요.', title_nl = 'Filter de geluiden 🤫', body_nl = 'Geluiden van de straat verstoren de diepe slaap. Kijk op de Geluidsmeter en gebruik zo nodig witte ruis op de achtergrond.', title_pl = 'Odfiltruj dźwięki 🤫', body_pl = 'Hałas z ulicy przeszkadza w głębokim śnie. Sprawdź Miernik dźwięku i w razie potrzeby włącz w tle biały szum.', title_pt = 'Filtre os sons 🤫', body_pt = 'Os sons da rua atrapalham o sono profundo. Veja o Medidor de Som e, se for preciso, use ruído branco em fundo.', title_sv = 'Filtrera bort ljuden 🤫', body_sv = 'Ljud från gatan stör den djupa sömnen. Titta på Ljudmätaren och använd vitt brus i bakgrunden om det behövs.', title_vi = 'Lọc bớt tiếng ồn 🤫', body_vi = 'Tiếng ồn ngoài đường làm bé khó ngủ sâu. Hãy xem Đo âm thanh và dùng tiếng ồn trắng làm nền nếu cần.', title_zh = '过滤噪音 🤫', body_zh = '街上的声音会打扰宝宝深睡。看看噪音测量，必要时播放白噪音作为背景音。' WHERE id = '6e836ffa-475e-446a-bc5a-eddbd0eeeec4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Guapa y auténtica 💇‍♀️', body_es = 'Puede que tengas una mancha en la camiseta y el pelo revuelto. Pero a los ojos de tu bebé eres lo más bonito del mundo. No te juzgues.', title_fr = 'Belle et vraie 💇‍♀️', body_fr = 'Votre t-shirt a peut-être une tache, vos cheveux sont peut-être en bataille. Mais aux yeux de votre bébé, vous êtes la plus belle au monde. Ne vous jugez pas.', title_hi = 'खूबसूरत और सच्ची 💇‍♀️', body_hi = 'आपकी कमीज़ पर दाग हो सकता है, बाल बिखरे हो सकते हैं। लेकिन बच्चे की नज़र में आप दुनिया की सबसे खूबसूरत इंसान हैं। खुद को दोष मत दीजिए।', title_id = 'Cantik dan apa adanya 💇‍♀️', body_id = 'Mungkin ada noda di baju Anda dan rambut berantakan. Tapi di mata bayi Anda, Anda sosok tercantik di dunia. Jangan terlalu keras pada diri sendiri.', title_ja = 'ありのままで美しい 💇‍♀️', body_ja = '服にシミがあって、髪がぼさぼさかもしれません。でも赤ちゃんの目には、あなたが世界でいちばん美しい人です。自分を責めないで。', title_ko = '아름답고 진짜인 나 💇‍♀️', body_ko = '셔츠에 얼룩이 있고 머리가 헝클어졌을 수도 있어요. 하지만 아기 눈에는 세상에서 가장 아름다운 사람이에요. 자신을 탓하지 마세요.', title_nl = 'Mooi en echt 💇‍♀️', body_nl = 'Misschien zit er een vlek op je shirt en zit je haar door de war. Maar in de ogen van je baby ben jij het mooiste wezen ter wereld. Wees niet te streng voor jezelf.', title_pl = 'Piękna i prawdziwa 💇‍♀️', body_pl = 'Możesz mieć plamę na bluzce i potargane włosy. Ale w oczach maluszka jesteś najpiękniejszą istotą na świecie. Nie obwiniaj się.', title_pt = 'Bonita e verdadeira 💇‍♀️', body_pt = 'Pode ter uma nódoa na camisola e o cabelo despenteado. Mas aos olhos do bebé é o ser mais bonito do mundo. Não se culpe.', title_sv = 'Vacker och äkta 💇‍♀️', body_sv = 'Tröjan kan ha en fläck och håret kan vara rufsigt. Men i barnets ögon är du den vackraste i världen. Döm inte dig själv.', title_vi = 'Xinh đẹp và chân thật 💇‍♀️', body_vi = 'Áo mẹ có thể dính vết bẩn, tóc mẹ có thể rối bù. Nhưng trong mắt bé, mẹ là người đẹp nhất thế giới. Đừng tự trách mình nhé.', title_zh = '美丽又真实 💇‍♀️', body_zh = '衣服上可能有污渍，头发可能乱糟糟。但在宝宝眼里，你是世界上最美的人。别责怪自己。' WHERE id = 'e31b222d-5c34-45e3-b291-c3f8c8989d13' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Crea una rutina perfecta controlando las tomas y los ratos despierto con la herramienta Seguimiento de tomas.', body_fr = 'Suivez les heures de repas et d''éveil avec l''outil Suivi des repas et créez un rythme parfait.', body_hi = 'फ़ीडिंग ट्रैकर टूल से खाने और जागने के समय पर नज़र रखकर एक बढ़िया रूटीन बनाइए।', body_id = 'Bangun rutinitas yang sempurna dengan memantau waktu menyusu dan waktu terjaga lewat Pelacak Menyusui.', body_ja = '授乳記録ツールで授乳と起きている時間を記録して、ぴったりの生活リズムをつくりましょう。', body_ko = '수유 기록 도구로 수유 시간과 깨어 있는 시간을 기록하며 완벽한 일과를 만들어 보세요.', body_nl = 'Volg de voedings- en wakkere tijden met de Voedingstracker en bouw een perfect ritme op.', body_pl = 'Śledź pory karmienia i czuwania w narzędziu do śledzenia karmienia i ułóż idealny rytm dnia.', body_pt = 'Acompanhe os horários de alimentação e os períodos acordado com o Registo de Alimentação e crie uma rotina perfeita.', body_sv = 'Skapa en perfekt rutin genom att följa matnings- och vakentider med verktyget Matningskoll.', body_vi = 'Hãy xây dựng nếp sinh hoạt hoàn hảo bằng cách theo dõi giờ bú và giờ thức của bé với công cụ Theo dõi cữ bú.', body_zh = '用喂养记录追踪喂奶和清醒时间，建立完美作息吧。' WHERE id = '29aebaa9-a1ae-4a00-8854-a771800bf560' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La entrega de papá 💖', body_es = 'Él también ha trabajado todo el día, pero ahora le toca el turno de papá. Míralo acostar al bebé con cuidado y disfruta de esa felicidad.', title_fr = 'Le dévouement de papa 💖', body_fr = 'Lui aussi a travaillé toute la journée, mais c''est maintenant son tour de papa. Regardez-le coucher bébé avec délicatesse et savourez ce bonheur.', title_hi = 'पापा का समर्पण 💖', body_hi = 'उन्होंने भी दिनभर काम किया है, पर अब पापा की बारी है। वे बच्चे को कितने ध्यान से सुलाते हैं, दूर से देखिए और इस खुशी का आनंद लीजिए।', title_id = 'Pengorbanan ayah 💖', body_id = 'Ia juga sudah bekerja seharian, tapi sekarang giliran tugas ayah. Lihat dari jauh betapa hati-hatinya ia menidurkan bayi, dan nikmati kebahagiaan ini.', title_ja = 'パパのがんばり 💖', body_ja = 'パパも1日中働いてきたけれど、今はパパの番。赤ちゃんをそっと寝かしつける姿を少し離れて見守り、幸せをかみしめましょう。', title_ko = '아빠의 헌신 💖', body_ko = '아빠도 하루 종일 일했지만 지금은 아빠 당번이에요. 아기를 조심스레 재우는 모습을 곁에서 지켜보며 행복을 만끽하세요.', title_nl = 'De toewijding van papa 💖', body_nl = 'Hij heeft ook de hele dag gewerkt, maar nu is het tijd voor papadienst. Kijk van een afstandje hoe voorzichtig hij de baby in slaap brengt en geniet van dit geluk.', title_pl = 'Poświęcenie taty 💖', body_pl = 'On też pracował cały dzień, ale teraz zmiana taty. Popatrz z boku, jak ostrożnie usypia maluszka, i delektuj się szczęściem.', title_pt = 'A dedicação do pai 💖', body_pt = 'Ele também trabalhou o dia todo, mas agora é o turno do pai. Veja de longe com que cuidado ele adormece o bebé e saboreie a felicidade.', title_sv = 'Pappas uppoffring 💖', body_sv = 'Han har också jobbat hela dagen, men nu är det pappas tur. Titta på avstånd när han varsamt söver barnet och njut av lyckan.', title_vi = 'Sự tận tụy của bố 💖', body_vi = 'Bố cũng đã làm việc cả ngày, nhưng giờ là ca trực của bố. Hãy đứng ngoài ngắm bố nhẹ nhàng ru bé ngủ và tận hưởng niềm hạnh phúc ấy.', title_zh = '爸爸的付出 💖', body_zh = '他也工作了一整天，但现在轮到爸爸值班了。在一旁看他小心翼翼地哄宝宝睡觉，品味这份幸福吧。' WHERE id = '3942c763-be60-481b-bb4e-1a53687a8d34' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Aquí estoy! 👀', body_es = 'Llámale por su nombre desde una esquina de la habitación. Verás cómo se gira enseguida hacia el sonido y te mira. ¡Su oído y su atención van genial!', title_fr = 'Je suis là ! 👀', body_fr = 'Appelez-le par son prénom depuis un coin de la pièce. Vous le verrez aussitôt se tourner vers le son et vous regarder. Son audition et son attention sont parfaites !', title_hi = 'मैं यहाँ हूँ! 👀', body_hi = 'कमरे के एक कोने से उसे नाम लेकर पुकारिए। आप देखेंगी कि वह तुरंत आवाज़ की ओर मुड़कर आपको देखता है। सुनने और ध्यान की क्षमता बढ़िया है!', title_id = 'Aku di sini! 👀', body_id = 'Panggil namanya dari sudut kamar. Anda akan melihat ia langsung menoleh ke arah suara dan menatap Anda. Pendengaran dan perhatiannya sempurna!', title_ja = 'ここにいるよ！👀', body_ja = '部屋のすみから名前を呼んでみましょう。すぐに声のほうを向いて、あなたを見るはずです。聞く力も注意力もばっちりです！', title_ko = '저 여기 있어요! 👀', body_ko = '방 한쪽에서 아기 이름을 불러 보세요. 바로 소리 나는 쪽으로 돌아 엄마를 바라볼 거예요. 청각과 집중력이 아주 좋아요!', title_nl = 'Ik ben hier! 👀', body_nl = 'Roep je baby vanuit een hoek van de kamer bij zijn naam. Je ziet hem meteen naar het geluid draaien en naar je kijken. Gehoor en aandacht zijn perfect!', title_pl = 'Tu jestem! 👀', body_pl = 'Zawołaj go po imieniu z drugiego kąta pokoju. Zobaczysz, jak od razu odwraca się w stronę głosu i na ciebie patrzy. Słuch i uwaga są doskonałe!', title_pt = 'Estou aqui! 👀', body_pt = 'Chame-o pelo nome de um canto do quarto. Vai vê-lo virar-se logo para o som e olhar para si. A audição e a atenção estão ótimas!', title_sv = 'Här är jag! 👀', body_sv = 'Ropa barnets namn från ett hörn av rummet. Du kommer att se hur det genast vänder sig mot ljudet och tittar på dig. Hörsel och uppmärksamhet är perfekta!', title_vi = 'Con ở đây nè! 👀', body_vi = 'Hãy gọi tên bé từ một góc phòng. Mẹ sẽ thấy bé quay ngay về phía tiếng gọi và nhìn mẹ. Thính giác và sự chú ý của bé thật tuyệt vời!', title_zh = '我在这儿！👀', body_zh = '在房间的一角叫宝宝的名字，你会看到宝宝立刻转向声音看着你。听力和注意力都发育得很好！' WHERE id = '3cd07d9d-076c-4523-8ba1-47b8737d6bbf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Te adora! 🥰', body_es = '¿Te mira fijamente mientras mama o come? Está descubriendo tus rasgos y te quiere muchísimo.', title_fr = 'Il est fou de vous ! 🥰', body_fr = 'Pendant la tétée ou le repas, il vous fixe des yeux ? Il découvre les traits de votre visage et vous aime tellement !', title_hi = 'वह आप पर फ़िदा है! 🥰', body_hi = 'दूध पीते या खाते समय आपको एकटक देखता है? वह आपके चेहरे की बनावट को पहचान रहा है और आपसे बहुत प्यार करता है!', title_id = 'Ia tergila-gila pada Anda! 🥰', body_id = 'Saat menyusu atau makan, ia menatap Anda lekat-lekat? Ia sedang mengenali wajah Anda dan sangat menyayangi Anda!', title_ja = '赤ちゃんはあなたに夢中！🥰', body_ja = '授乳中や食事中に、じっとあなたを見つめていますか？あなたの顔立ちを探検していて、あなたが大好きなのです！', title_ko = '아기는 엄마에게 푹 빠졌어요! 🥰', body_ko = '젖을 먹거나 밥을 먹으며 엄마를 뚫어지게 바라보나요? 엄마의 얼굴을 탐색하며 엄마를 무척 사랑하고 있어요!', title_nl = 'Je kleintje is gek op je! 🥰', body_nl = 'Kijkt je baby je tijdens het drinken of eten strak aan? Hij ontdekt je gezicht en houdt zielsveel van je!', title_pl = 'On cię uwielbia! 🥰', body_pl = 'Podczas ssania lub jedzenia wpatruje się w ciebie? Poznaje rysy twojej twarzy i bardzo cię kocha!', title_pt = 'Está apaixonado por si! 🥰', body_pt = 'Enquanto mama ou come, fica de olhos fixos em si? Está a descobrir os traços do seu rosto e gosta muito de si!', title_sv = 'Barnet är tokigt i dig! 🥰', body_sv = 'Stirrar barnet på dig när det ammar eller äter? Det utforskar dina ansiktsdrag och älskar dig så mycket!', title_vi = 'Bé mê mẹ lắm đấy! 🥰', body_vi = 'Khi bú hay ăn, bé cứ nhìn chằm chằm vào mẹ? Bé đang khám phá từng đường nét trên gương mặt mẹ và yêu mẹ vô cùng!', title_zh = '宝宝超爱你！🥰', body_zh = '宝宝吃奶或吃饭时一直盯着你看？宝宝在探索你的面容，而且非常爱你！' WHERE id = '25015c8c-0ca6-43bc-a465-c8490ee6d808' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un poco de calma 🛋️', body_es = 'Tras un día difícil, anota tus emociones en el Diario de ánimo. Escribir y desahogarte es el mejor psicólogo gratuito.', title_fr = 'Un peu de réconfort 🛋️', body_fr = 'Après une journée difficile, notez vos émotions dans le Journal d''humeur. Écrire et vider son cœur, c''est le meilleur psy gratuit.', title_hi = 'थोड़ा सुकून 🛋️', body_hi = 'मुश्किल दिन के बाद अपनी भावनाएँ मूड डायरी में लिखिए। याद रखिए, लिखकर मन हल्का करना सबसे अच्छी मुफ़्त थेरेपी है।', title_id = 'Sedikit kelegaan 🛋️', body_id = 'Setelah hari yang berat, catat perasaan Anda di Buku Harian Suasana Hati. Ingat, menulis dan meluapkan isi hati adalah terapi gratis terbaik.', title_ja = '少しのやすらぎ 🛋️', body_ja = '大変な1日のあとは、「気分日記」に気持ちを書きとめましょう。書いて気持ちを吐き出すことは、いちばんの無料のカウンセリングです。', title_ko = '잠깐의 휴식 🛋️', body_ko = '힘든 하루를 보낸 뒤 기분 일기에 감정을 적어 보세요. 글로 쓰며 마음을 비우는 것이 가장 좋은 무료 심리상담이에요.', title_nl = 'Een beetje rust 🛋️', body_nl = 'Schrijf na een zware dag je gevoelens op in je Stemmingsdagboek. Opschrijven en je hart luchten is de beste gratis psycholoog.', title_pl = 'Trochę wytchnienia 🛋️', body_pl = 'Po trudnym dniu zapisz swoje emocje w Dzienniku nastroju. Pamiętaj, że pisanie i wyrzucenie z siebie emocji to najlepszy darmowy psycholog.', title_pt = 'Um pouco de conforto 🛋️', body_pt = 'Depois de um dia difícil, registe as suas emoções no Diário de Humor. Escrever e desabafar é o melhor psicólogo gratuito.', title_sv = 'Lite vila 🛋️', body_sv = 'Efter en tuff dag, skriv ner dina känslor i Humördagboken. Att skriva och lätta på hjärtat är den bästa gratis psykologen.', title_vi = 'Một chút thư thái 🛋️', body_vi = 'Sau một ngày vất vả, hãy ghi lại cảm xúc vào Nhật ký tâm trạng. Viết ra để trút bỏ lòng mình chính là liều thuốc tâm lý miễn phí tốt nhất.', title_zh = '放松一下 🛋️', body_zh = '辛苦一天后，在心情日记里记下你的感受。要知道，写下来、倾诉出来就是最好的免费心理疏导。' WHERE id = '565cbb4c-39dd-4c69-980a-b02d63f6cdb4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Sus cacas tienen un color diferente o le ha salido un pequeño sarpullido? Antes de alarmarte, escribe a Anacan AI y conoce las causas principales.', body_fr = 'Ses selles ont une couleur inhabituelle ou il a une petite éruption ? Avant de paniquer, écrivez à Anacan AI pour connaître les causes principales.', body_hi = 'उसके मल का रंग अलग है या शरीर पर हल्के दाने हैं? घबराने से पहले Anacan AI को लिखिए और संभावित कारण जानिए।', body_id = 'Warna tinjanya berbeda atau ada ruam kecil di tubuhnya? Sebelum panik, tanyakan ke Anacan AI dan pahami kemungkinan penyebabnya.', body_ja = 'うんちの色がいつもと違う、または体に小さな発疹がある？あわてる前にAnacan AIに聞いて、考えられる原因を知りましょう。', body_ko = '변 색이 평소와 다르거나 몸에 작은 발진이 있나요? 당황하기 전에 Anacan AI에게 물어 기본적인 원인을 알아보세요.', body_nl = 'Heeft de poep een andere kleur of zit er een uitslagje op het lijfje? Schrijf naar Anacan AI voordat je in paniek raakt en ontdek de mogelijke oorzaken.', body_pl = 'Kupka ma inny kolor albo na ciele pojawiła się drobna wysypka? Zanim wpadniesz w panikę, napisz do Anacan AI i poznaj możliwe przyczyny.', body_pt = 'As fezes têm uma cor diferente ou há uma pequena erupção no corpo? Antes de entrar em pânico, escreva ao Anacan AI e conheça as causas principais.', body_sv = 'Har bajset en annan färg eller har barnet lite utslag? Innan du får panik, skriv till Anacan AI och ta reda på de grundläggande orsakerna.', body_vi = 'Phân của bé có màu khác lạ hay trên người bé có nốt phát ban nhỏ? Trước khi hoảng hốt, hãy hỏi Anacan AI để biết những nguyên nhân cơ bản.', body_zh = '大便颜色不一样，或者身上有小疹子？先别慌，问问Anacan AI，了解可能的原因。' WHERE id = 'f0338702-1ba5-495b-840d-9ad790085c24' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Manos a la obra 👐', body_es = '¿Intenta agarrar objetos grandes con las dos manos a la vez? Anota este detalle en el Seguimiento del desarrollo y compruébalo dándole una pelota blandita.', title_fr = 'Des mains au travail 👐', body_fr = 'Il essaie d''attraper de gros objets avec les deux mains à la fois ? Notez ce détail dans le Suivi de développement et testez avec un ballon souple.', title_hi = 'नन्हे हाथ काम पर 👐', body_hi = 'दोनों हाथों से एक साथ बड़ी चीज़ें पकड़ने की कोशिश करता है? ग्रोथ ट्रैकर में यह बात दर्ज कीजिए और उसे एक नरम गेंद देकर आज़माइए।', title_id = 'Tangan-tangan sibuk 👐', body_id = 'Ia mencoba menggenggam benda besar dengan kedua tangan sekaligus? Catat di Pelacak Perkembangan dan coba berikan bola lembut.', title_ja = 'お手てが大忙し 👐', body_ja = '両手で同時に大きなものをつかもうとしていますか？「発達トラッカー」に記録して、やわらかいボールを渡して試してみましょう。', title_ko = '열일하는 두 손 👐', body_ko = '두 손으로 동시에 큰 물건을 잡으려 하나요? 성장 기록에 이 모습을 남기고 말랑한 공을 건네 확인해 보세요.', title_nl = 'Handjes aan het werk 👐', body_nl = 'Probeert je baby grote voorwerpen met twee handjes tegelijk te pakken? Noteer het in de Groeitracker en probeer het uit met een zachte bal.', title_pl = 'Rączki przy pracy 👐', body_pl = 'Próbuje chwytać duże przedmioty obiema rączkami naraz? Zapisz to w Śledzeniu rozwoju i sprawdź, podając mu miękką piłkę.', title_pt = 'Mãos à obra 👐', body_pt = 'Tenta agarrar objetos grandes com as duas mãos ao mesmo tempo? Assinale este detalhe no Registo de Desenvolvimento e experimente dar-lhe uma bola macia.', title_sv = 'Händerna i arbete 👐', body_sv = 'Försöker barnet greppa stora föremål med båda händerna samtidigt? Anteckna det i Utvecklingsspåraren och testa med en mjuk boll.', title_vi = 'Đôi tay bận rộn 👐', body_vi = 'Bé cố dùng cả hai tay để cầm đồ vật lớn cùng lúc? Hãy ghi lại điều này trong Theo dõi phát triển và đưa cho bé một quả bóng mềm để thử nhé.', title_zh = '小手忙不停 👐', body_zh = '宝宝在尝试用两只手同时抓大东西？在发育追踪里记下这个细节，给宝宝一个软球试试吧。' WHERE id = '5996a5e8-c639-4f34-8f02-ccaebf8a96eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Tiene frío o calor? ⛅', body_es = '¿Vestirle siempre es un problema? Deja que la herramienta Tiempo y ropa te diga exactamente cuántas capas ponerle. No te calientes la cabeza.', title_fr = 'Il a froid ou trop chaud ? ⛅', body_fr = 'L''habillage, toujours un casse-tête ? Laissez l''outil Météo et tenue vous dire exactement combien de couches lui mettre. Ne vous fatiguez pas.', title_hi = 'ठंड लग रही है या गर्मी? ⛅', body_hi = 'कपड़े पहनाना हमेशा एक पहेली है? मौसम और कपड़े टूल आपको ठीक-ठीक बताएगा कि कितनी परतें पहनानी हैं। दिमाग मत थकाइए।', title_id = 'Kedinginan atau kepanasan? ⛅', body_id = 'Memilih baju selalu jadi teka-teki? Biarkan fitur Cuaca dan Pakaian memberi tahu dengan tepat berapa lapis pakaian yang perlu. Jangan bikin pusing.', title_ja = '寒い？それとも暑い？⛅', body_ja = '服選びはいつも悩みのたね？「天気と服装」ツールが、何枚重ねればいいかを正確に教えてくれます。頭を悩ませないで。', title_ko = '추울까요, 더울까요? ⛅', body_ko = '옷 입히기가 늘 고민인가요? 날씨와 옷차림 도구가 몇 겹을 입혀야 할지 정확히 알려 줄 거예요. 머리 아프게 고민하지 마세요.', title_nl = 'Te koud of te warm? ⛅', body_nl = 'Is aankleden altijd een puzzel? Laat de tool Weer en kleding je precies vertellen hoeveel laagjes nodig zijn. Breek je hoofd er niet over.', title_pl = 'Zimno mu czy gorąco? ⛅', body_pl = 'Ubieranie to zawsze problem? Niech narzędzie Pogoda i ubiór dokładnie powie ci, ile warstw założyć. Nie męcz głowy.', title_pt = 'Tem frio ou calor? ⛅', body_pt = 'Vestir o bebé é sempre um problema? Deixe a ferramenta Tempo e Roupa dizer-lhe com precisão quantas camadas deve vestir. Não canse a cabeça.', title_sv = 'Fryser eller är varm? ⛅', body_sv = 'Är klädseln alltid ett problem? Låt Väder och kläder säga exakt hur många lager barnet ska ha. Belasta inte hjärnan i onödan.', title_vi = 'Bé lạnh hay nóng? ⛅', body_vi = 'Mặc đồ cho bé lúc nào cũng là bài toán khó? Để công cụ Thời tiết và trang phục cho mẹ biết chính xác cần mặc mấy lớp. Mẹ đừng phải nghĩ nhiều.', title_zh = '冷还是热？⛅', body_zh = '穿衣总是难题？让天气穿衣工具准确告诉你该穿几层，别再费脑筋了。' WHERE id = '6dd3138c-1bd5-4dac-80d8-a5b5ffa166ee' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La magia de la voz de mamá 🎶', body_es = 'Ninguna app puede sustituir la nana de una madre. Esta noche, simplemente abrázale contra tu pecho y cántale bajito su nana favorita.', title_fr = 'La magie de la voix de maman 🎶', body_fr = 'Aucune application ne remplace la berceuse d''une maman. Ce soir, serrez-le simplement contre vous et chantez doucement sa berceuse préférée.', title_hi = 'माँ की आवाज़ का जादू 🎶', body_hi = 'कोई भी ऐप माँ की लोरी की जगह नहीं ले सकता। आज शाम बस उसे सीने से लगाइए और धीरे से उसकी पसंदीदा लोरी गाइए।', title_id = 'Keajaiban suara ibu 🎶', body_id = 'Tidak ada aplikasi yang bisa menggantikan nina bobo seorang ibu. Malam ini, cukup dekap ia di dada dan nyanyikan pelan lagu kesukaannya.', title_ja = 'ママの声の魔法 🎶', body_ja = 'どんなアプリも、ママの子守唄にはかないません。今夜はただ胸に抱きよせて、お気に入りの子守唄をそっと歌ってあげましょう。', title_ko = '엄마 목소리의 마법 🎶', body_ko = '어떤 앱도 엄마의 자장가를 대신할 수 없어요. 오늘 밤은 아기를 가슴에 꼭 안고 가장 좋아하는 자장가를 나지막이 불러 주세요.', title_nl = 'De magie van mama''s stem 🎶', body_nl = 'Geen app kan het slaapliedje van een moeder vervangen. Houd je kleintje vanavond gewoon tegen je borst en zing zachtjes zijn lievelingsliedje.', title_pl = 'Magia głosu mamy 🎶', body_pl = 'Żadna aplikacja nie zastąpi kołysanki mamy. Dziś wieczorem po prostu przytul go do piersi i cichutko zaśpiewaj jego ulubioną kołysankę.', title_pt = 'A magia da voz da mãe 🎶', body_pt = 'Nenhuma app substitui a canção de embalar da mãe. Esta noite, aconchegue-o ao peito e cante baixinho a canção de que ele mais gosta.', title_sv = 'Mammaröstens magi 🎶', body_sv = 'Ingen app kan ersätta mammas vaggvisa. I kväll, håll bara barnet tätt intill bröstet och sjung tyst den vaggvisa barnet tycker mest om.', title_vi = 'Phép màu từ giọng mẹ 🎶', body_vi = 'Không ứng dụng nào thay được lời ru của mẹ. Tối nay chỉ cần ôm bé vào lòng và khẽ hát bài ru bé thích nhất.', title_zh = '妈妈声音的魔力 🎶', body_zh = '没有任何应用能取代妈妈的摇篮曲。今晚就把宝宝抱在怀里，轻轻唱宝宝最爱的那首吧。' WHERE id = 'a1ca42ca-05ed-42dc-af4a-99af31043623' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Curiosidad por los sabores? 🍽️', body_es = '¿Mira atentamente tu plato y tu boca mientras comes? ¡Poco a poco empieza el interés por los alimentos sólidos (alimentación complementaria)!', title_fr = 'Curieux des saveurs ? 🍽️', body_fr = 'Quand vous mangez, il regarde attentivement votre assiette et votre bouche ? L''intérêt pour les aliments solides (la diversification) commence doucement !', title_hi = 'स्वाद में दिलचस्पी? 🍽️', body_hi = 'आपके खाते समय वह ध्यान से आपकी प्लेट और मुँह को देखता है? ठोस आहार (ऊपरी आहार) में दिलचस्पी धीरे-धीरे शुरू हो रही है!', title_id = 'Penasaran dengan rasa? 🍽️', body_id = 'Saat Anda makan, ia memperhatikan piring dan mulut Anda dengan saksama? Ketertarikan pada makanan padat (MPASI) perlahan mulai muncul!', title_ja = '味に興味しんしん？🍽️', body_ja = 'あなたが食事をしているとき、お皿や口元をじっと見ていますか？離乳食への興味が少しずつ芽生えています！', title_ko = '맛이 궁금한가요? 🍽️', body_ko = '엄마가 식사할 때 접시와 입을 유심히 바라보나요? 고형식(이유식)에 대한 관심이 조금씩 생기고 있어요!', title_nl = 'Nieuwsgierig naar smaken? 🍽️', body_nl = 'Kijkt je baby aandachtig naar je bord en je mond als je eet? De interesse in vast voedsel (bijvoeding) begint langzaam!', title_pl = 'Ciekawy smaków? 🍽️', body_pl = 'Gdy jesz, uważnie patrzy na twój talerz i buzię? Powoli rodzi się zainteresowanie stałymi pokarmami (rozszerzaniem diety)!', title_pt = 'Curioso com os sabores? 🍽️', body_pt = 'Enquanto come, ele olha atentamente para o seu prato e para a sua boca? O interesse pelos alimentos sólidos (diversificação alimentar) está a começar aos poucos!', title_sv = 'Nyfiken på smaker? 🍽️', body_sv = 'Tittar barnet uppmärksamt på din tallrik och din mun när du äter? Intresset för fast föda (smakportioner) börjar sakta vakna!', title_vi = 'Tò mò về hương vị? 🍽️', body_vi = 'Khi mẹ ăn, bé chăm chú nhìn đĩa và miệng mẹ? Sự quan tâm đến thức ăn đặc (ăn dặm) đang dần bắt đầu!', title_zh = '对味道好奇？🍽️', body_zh = '你吃饭时宝宝专注地盯着你的盘子和嘴巴？宝宝对固体食物（辅食）的兴趣正在慢慢萌芽！' WHERE id = 'b0613bc2-510c-4582-8829-fd09f1ed2898' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La rutina de la noche es el billete del tren del sueño.🚂', body_es = 'Baño templado, masaje y habitación a oscuras... No rompas nunca esta rutina.', title_fr = 'La routine du soir, c''est le billet pour le train du sommeil. 🚂', body_fr = 'Bain tiède, massage et pièce assombrie... Ne brisez jamais cette routine.', title_hi = 'शाम का रूटीन नींद की ट्रेन का टिकट है 🚂', body_hi = 'गुनगुना स्नान, मालिश और कमरे में अँधेरा... इस रूटीन को कभी मत तोड़िए।', title_id = 'Rutinitas malam adalah tiket kereta menuju tidur.🚂', body_id = 'Mandi air hangat, pijat, dan kamar yang diredupkan... Jangan pernah lewatkan rutinitas ini.', title_ja = '夜のルーティンは、ねんね列車の切符です。🚂', body_ja = 'ぬるめのお風呂、マッサージ、部屋を暗くする...このルーティンは決して崩さないで。', title_ko = '저녁 루틴은 꿈나라 기차표예요.🚂', body_ko = '따뜻한 목욕, 마사지, 어두운 방... 이 루틴은 절대 깨지 마세요.', title_nl = 'De avondroutine is je kaartje voor de slaaptrein.🚂', body_nl = 'Een lauw badje, een massage en een verduisterde kamer... Doorbreek deze routine nooit.', title_pl = 'Wieczorna rutyna to bilet do pociągu snu. 🚂', body_pl = 'Ciepła kąpiel, masaż i przyciemniony pokój... Nigdy nie łam tej rutyny.', title_pt = 'A rotina da noite é o bilhete para o comboio do sono.🚂', body_pt = 'Banho morno, massagem e quarto escurecido... Nunca quebre esta rotina.', title_sv = 'Kvällsrutinen är biljetten till sömntåget.🚂', body_sv = 'Ett ljummet bad, massage och ett mörkt rum... Bryt aldrig den här rutinen.', title_vi = 'Nếp sinh hoạt buổi tối là tấm vé lên chuyến tàu giấc ngủ.🚂', body_vi = 'Tắm nước ấm, mát-xa và làm tối phòng... Đừng bao giờ phá vỡ nếp sinh hoạt này nhé.', title_zh = '晚间作息是睡眠列车的车票 🚂', body_zh = '温水澡、按摩、调暗房间……千万别打乱这套作息。' WHERE id = 'cd2a678b-9234-4910-9725-95b0b9e3443e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Con las prisas del día, no comas de pie. 🥑', body_es = 'Prepara una ensalada fácil de Recetas saludables, siéntate y disfrútala.', title_fr = 'Dans la course du quotidien, ne déjeunez pas debout. 🥑', body_fr = 'Préparez une salade facile des Recettes saines, asseyez-vous et savourez-la.', title_hi = 'रोज़ की भागदौड़ में खड़े-खड़े लंच मत कीजिए 🥑', body_hi = 'सेहतमंद रेसिपी से एक आसान सलाद बनाइए और बैठकर मज़े से खाइए।', title_id = 'Jangan makan siang sambil berdiri di tengah kesibukan. 🥑', body_id = 'Buat salad mudah dari Resep Sehat, lalu duduk dan nikmati setiap suapannya.', title_ja = '毎日のバタバタの中で、お昼ごはんを立ったまま食べないで。🥑', body_ja = '「ヘルシーレシピ」からかんたんなサラダをつくって、座ってゆっくり味わいましょう。', title_ko = '바쁜 하루 속에서도 점심을 서서 먹지 마세요. 🥑', body_ko = '건강한 레시피에서 간단한 샐러드를 만들어 앉아서 맛있게 드세요.', title_nl = 'Eet in de dagelijkse drukte niet staand je lunch. 🥑', body_nl = 'Maak een makkelijke salade uit Gezonde recepten, ga zitten en geniet ervan.', title_pl = 'W codziennym biegu nie jedz obiadu na stojąco. 🥑', body_pl = 'Przygotuj prostą sałatkę ze Zdrowych przepisów, usiądź i zjedz ją z przyjemnością.', title_pt = 'Na correria do dia, não almoce de pé. 🥑', body_pt = 'Prepare uma salada fácil das Receitas Saudáveis, sente-se e coma com prazer.', title_sv = 'Ät inte lunchen stående i vardagsstressen. 🥑', body_sv = 'Gör en enkel sallad från Hälsosamma recept, sätt dig ner och njut av maten.', title_vi = 'Đừng đứng ăn trưa giữa những bộn bề mỗi ngày. 🥑', body_vi = 'Hãy làm một món salad đơn giản từ Công thức lành mạnh, rồi ngồi xuống thưởng thức thật ngon miệng.', title_zh = '再忙也别站着吃午饭 🥑', body_zh = '从健康食谱里做一份简单的沙拉，坐下来好好享用吧。' WHERE id = 'cfb5c864-525c-4db1-869c-94c18824f78e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Foto de carcajadas 📸', body_es = '¡Cada día se ríe más! Abre la Sesión de fotos del bebé y captura una carcajada alegre que espante cualquier mal rollo del día.', title_fr = 'Le cliché des éclats de rire 📸', body_fr = 'Il rit chaque jour davantage ! Ouvrez la Séance photo bébé et capturez un joyeux éclat de rire qui chassera les ondes négatives de la journée.', title_hi = 'खिलखिलाहट का फ़्रेम 📸', body_hi = 'वह हर दिन ज़्यादा हँसता है! बेबी फ़ोटोशूट खोलिए और ऐसी खिलखिलाती तस्वीर लीजिए जो दिन की सारी उदासी दूर कर दे।', title_id = 'Jepretan tawa 📸', body_id = 'Ia makin sering tertawa setiap hari! Buka Sesi Foto Bayi dan abadikan tawa riang yang mengusir semua hal negatif hari ini.', title_ja = '笑顔のショット 📸', body_ja = '赤ちゃんは日に日によく笑うようになっています！「ベビーフォトセッション」を開いて、今日のモヤモヤを吹き飛ばすような楽しい笑顔を撮りましょう。', title_ko = '웃음 가득한 한 컷 📸', body_ko = '아기가 날마다 더 많이 웃어요! 아기 사진 촬영을 열고 오늘의 우울함을 날려 버릴 즐거운 웃음을 담아 보세요.', title_nl = 'Een lachfoto 📸', body_nl = 'Je baby lacht elke dag meer! Open Babyfotoshoot en maak een vrolijke lachfoto die alle negativiteit van vandaag verdrijft.', title_pl = 'Kadr pełen śmiechu 📸', body_pl = 'Śmieje się coraz więcej! Otwórz Sesję zdjęciową dziecka i uchwyć radosny śmiech, który odpędzi dzisiejsze smutki.', title_pt = 'Foto de gargalhada 📸', body_pt = 'Ri-se cada dia mais! Abra a Sessão Fotográfica do Bebé e tire uma foto de uma gargalhada alegre que afaste o lado negativo do dia.', title_sv = 'Skrattbild 📸', body_sv = 'Barnet skrattar mer för varje dag! Öppna Babyfotografering och ta en glad skrattbild som jagar bort dagens negativitet.', title_vi = 'Khoảnh khắc cười giòn 📸', body_vi = 'Bé cười nhiều hơn mỗi ngày! Mở Chụp ảnh cho bé và ghi lại một tràng cười vui vẻ để xua tan mọi điều tiêu cực hôm nay nhé.', title_zh = '笑声快照 📸', body_zh = '宝宝一天比一天爱笑！打开宝宝写真，拍下一张开怀大笑的照片，赶走今天的坏情绪。' WHERE id = '3325dc87-cd45-494c-a42f-d923bde10bc2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un cuento reconfortante 🪄', body_es = 'Crea en Cuentos inteligentes la historia de un pequeño héroe que se prepara para su 5.º mes y llena la habitación de un ambiente dulce.', title_fr = 'Un conte réconfortant 🪄', body_fr = 'Dans les Contes intelligents, créez l''histoire d''un petit héros qui se prépare à son 5e mois et apportez une douce ambiance dans la chambre.', title_hi = 'सुकून देने वाली कहानी 🪄', body_hi = 'स्मार्ट कहानियों में 5वें महीने की तैयारी कर रहे नन्हे हीरो की कहानी बनाइए और कमरे में मीठा माहौल भर दीजिए।', title_id = 'Dongeng penghibur 🪄', body_id = 'Di Dongeng Pintar, buat kisah pahlawan kecil yang bersiap menyambut bulan ke-5, dan hadirkan suasana manis di kamar.', title_ja = '心がやすらぐお話 🪄', body_ja = '「スマートおはなし」で、もうすぐ生後5か月になる小さなヒーローのお話をつくって、部屋をやさしい雰囲気で包みましょう。', title_ko = '마음을 달래 주는 동화 🪄', body_ko = '스마트 동화에서 이제 곧 5개월이 되는 작은 주인공의 이야기를 만들어 방 안을 달콤한 분위기로 채워 보세요.', title_nl = 'Een troostend sprookje 🪄', body_nl = 'Maak in Slimme sprookjes het verhaal van een kleine held die zich klaarmaakt voor de 5e maand en vul de kamer met een lieve sfeer.', title_pl = 'Kojąca bajka 🪄', body_pl = 'W Mądrych bajkach stwórz historię o małym bohaterze, który szykuje się na 5. miesiąc, i wypełnij pokój słodką atmosferą.', title_pt = 'Uma história reconfortante 🪄', body_pt = 'Nas Histórias Inteligentes, crie a história de um pequeno herói a preparar-se para o 5.º mês e encha o quarto de um ambiente doce.', title_sv = 'En tröstande saga 🪄', body_sv = 'Skapa sagan om den lilla hjälten som gör sig redo för 5:e månaden i Smarta sagor och fyll rummet med en mysig stämning.', title_vi = 'Câu chuyện vỗ về 🪄', body_vi = 'Trong Truyện cổ tích thông minh, hãy tạo câu chuyện về người hùng nhỏ đang chuẩn bị bước sang tháng thứ 5 và mang đến cho căn phòng một bầu không khí ngọt ngào.', title_zh = '治愈的故事 🪄', body_zh = '在智能故事里创作一个即将满5个月的小英雄的故事，给房间增添温馨的氛围。' WHERE id = '37ba096d-4d60-4d73-9c8d-1e0fc44ce8b8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Tu bebé no se calma y estás agotadísima? 🛑', body_es = 'Deja a tu bebé de forma segura en la cuna y vete 5 minutos a otra habitación. Tú también tienes derecho a respirar.', title_fr = 'Bébé ne se calme pas et vous êtes épuisée ? 🛑', body_fr = 'Posez bébé en sécurité dans son lit et allez 5 minutes dans une autre pièce. Vous aussi, vous avez le droit de respirer.', title_hi = 'बच्चा शांत नहीं हो रहा और आप बेहद थक गई हैं? 🛑', body_hi = 'बच्चे को सुरक्षित रूप से पालने में लिटाइए और 5 मिनट के लिए दूसरे कमरे में चली जाइए। आपको भी साँस लेने का हक है।', title_id = 'Si kecil tidak mau tenang dan Anda sangat lelah? 🛑', body_id = 'Letakkan bayi dengan aman di boks, lalu pindahlah ke ruangan lain selama 5 menit. Anda juga berhak bernapas.', title_ja = '赤ちゃんが泣きやまなくて、もうくたくた？🛑', body_ja = '赤ちゃんを安全にベビーベッドに寝かせて、5分だけ別の部屋へ。あなたにもひと息つく権利があります。', title_ko = '아이가 진정하지 않고 너무 지쳤나요? 🛑', body_ko = '아기를 아기 침대에 안전하게 눕히고 5분 동안 다른 방에 가 있으세요. 엄마도 숨 쉴 권리가 있어요.', title_nl = 'Wordt je baby niet rustig en ben je doodmoe? 🛑', body_nl = 'Leg je baby veilig in het bedje en ga 5 minuten naar een andere kamer. Jij hebt ook recht om op adem te komen.', title_pl = 'Maluszek się nie uspokaja, a ty jesteś strasznie zmęczona? 🛑', body_pl = 'Połóż maluszka bezpiecznie w łóżeczku i przejdź na 5 minut do innego pokoju. Ty też masz prawo złapać oddech.', title_pt = 'O bebé não se acalma e está terrivelmente cansada?  🛑', body_pt = 'Deixe o bebé em segurança no berço e vá para outra divisão durante 5 minutos. Também tem direito a respirar.', title_sv = 'Barnet lugnar sig inte och du är helt slutkörd?  🛑', body_sv = 'Lägg barnet tryggt i spjälsängen och gå in i ett annat rum i 5 minuter. Du har också rätt att andas.', title_vi = 'Bé không chịu nín và mẹ đã kiệt sức?  🛑', body_vi = 'Hãy đặt bé an toàn vào nôi và sang phòng khác 5 phút. Mẹ cũng có quyền được thở.', title_zh = '宝宝哄不好，你累坏了？🛑', body_zh = '把宝宝安全地放进婴儿床，去另一个房间待5分钟。你也有喘口气的权利。' WHERE id = '0b47b1a5-bf87-49ea-bae7-b0bb8b0e46f2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Analizador de llanto 😭', body_es = 'Vuelves a la habitación y otra vez llora. ¡No te desgastes! Usa enseguida el Análisis del llanto y cálmale atendiendo a lo que de verdad necesita.', title_fr = 'Analyseur de pleurs 😭', body_fr = 'Vous revenez dans la pièce et il pleure encore. Ne vous épuisez pas ! Faites écouter ses pleurs à l''Analyse des pleurs, répondez au bon besoin et apaisez-le.', title_hi = 'आवाज़ विश्लेषक 😭', body_hi = 'आप कमरे में लौटीं और वह फिर रो रहा है। हिम्मत मत हारिए! तुरंत क्राइंग एनालिसिस से उसकी आवाज़ सुनवाइए और सही ज़रूरत पूरी करके उसे शांत कीजिए।', title_id = 'Penganalisis suara 😭', body_id = 'Anda kembali ke kamar dan ia menangis lagi. Jangan putus asa! Segera perdengarkan tangisannya ke Analisis Tangisan dan tenangkan ia dengan memenuhi kebutuhannya yang tepat.', title_ja = '泣き声アナライザー 😭', body_ja = '部屋に戻ったら、また泣いている。すり減らないで！すぐに「泣き声分析」に泣き声を聞かせて、本当に必要なことをかなえて落ち着かせてあげましょう。', title_ko = '울음 분석기 😭', body_ko = '방에 돌아왔는데 또 울고 있나요? 지치지 마세요! 바로 울음 분석으로 소리를 들려주고 알맞은 필요를 채워 달래 주세요.', title_nl = 'Geluidsanalyse 😭', body_nl = 'Je komt terug in de kamer en je baby huilt weer. Raak niet uitgeput! Laat Huilanalyse meteen meeluisteren, geef je baby wat hij echt nodig heeft en kalmeer hem.', title_pl = 'Analizator dźwięku 😭', body_pl = 'Wróciłaś do pokoju, a on znów płacze. Nie poddawaj się! Od razu pozwól Analizie płaczu posłuchać dźwięku i uspokój go, odpowiadając na jego prawdziwą potrzebę.', title_pt = 'Analisador de som 😭', body_pt = 'Voltou ao quarto e ele está outra vez a chorar. Não desanime! Ponha já a Análise do Choro a ouvir e acalme-o respondendo à necessidade certa.', title_sv = 'Ljudanalys 😭', body_sv = 'Du kom tillbaka in i rummet och barnet gråter igen. Tappa inte orken! Låt Gråtanalys lyssna på ljudet direkt och lugna barnet genom att möta rätt behov.', title_vi = 'Phân tích âm thanh 😭', body_vi = 'Mẹ quay lại phòng và bé lại khóc. Đừng gục ngã! Cho Phân tích tiếng khóc nghe ngay, đáp ứng đúng nhu cầu và dỗ bé nín nhé.', title_zh = '声音分析 😭', body_zh = '回到房间，宝宝又在哭。别崩溃！马上用哭声分析听一听，满足宝宝真正的需求，让宝宝安静下来。' WHERE id = '1f6b52bc-5331-4372-8c65-f0f6ee109098' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las manos siempre en la boca 🦷', body_es = '¿Lo muerde todo con fuerza? Unas gasas templadas y limpias le aliviarán las encías.', title_fr = 'Les mains toujours dans la bouche 🦷', body_fr = 'Il mâchouille tout avec force ? Des linges tièdes et propres soulageront ses gencives.', title_hi = 'हाथ मुँह से निकलते ही नहीं 🦷', body_hi = 'हर चीज़ ज़ोर से चबा रहा है? गुनगुने और साफ़ कपड़े उसके मसूड़ों को आराम देंगे।', title_id = 'Tangan terus di mulut 🦷', body_id = 'Ia mengunyah semua benda dengan kuat? Kain hangat yang bersih akan terasa nyaman di gusinya.', title_ja = 'お手てがいつもお口に 🦷', body_ja = 'なんでも力いっぱいかんでいますか？清潔なぬるめのガーゼが歯ぐきを楽にしてくれます。', title_ko = '손이 입에서 떨어지지 않아요 🦷', body_ko = '무엇이든 세게 깨무나요? 따뜻하고 깨끗한 천이 잇몸을 편안하게 해 줄 거예요.', title_nl = 'Handjes steeds in de mond 🦷', body_nl = 'Kauwt je baby fel op alles? Lauwe, schone doekjes doen het tandvlees goed.', title_pl = 'Rączki ciągle w buzi 🦷', body_pl = 'Mocno gryzie wszystko? Ciepła, czysta pieluszka tetrowa przyniesie ulgę jego dziąsłom.', title_pt = 'As mãos não saem da boca 🦷', body_pt = 'Mastiga tudo com força? Paninhos mornos e limpos vão fazer bem às gengivas.', title_sv = 'Händerna lämnar aldrig munnen 🦷', body_sv = 'Tuggar barnet häftigt på allt? Ljumna, rena tygtrasor gör gott för tandköttet.', title_vi = 'Tay không rời miệng 🦷', body_vi = 'Bé gặm mọi thứ thật mạnh? Một chiếc khăn ấm, sạch sẽ giúp nướu bé dễ chịu hơn.', title_zh = '小手不离嘴 🦷', body_zh = '什么都使劲啃？温暖干净的纱布能舒缓宝宝的牙龈。' WHERE id = '90149fde-54c0-4d98-ba95-374230a626e1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Heroínas de la noche 🦸‍♀️', body_es = 'Lo sabemos, despertarte por la noche te deja sin fuerzas. Escribe tu cansancio en el Diario de ánimo y pide a tu pareja que te apoye.', title_fr = 'Les héros de la nuit 🦸‍♀️', body_fr = 'Les réveils nocturnes vous épuisent, nous le savons. Écrivez votre fatigue dans le Journal d''humeur et demandez à votre conjoint de vous soutenir.', title_hi = 'रात की हीरो 🦸‍♀️', body_hi = 'हम जानते हैं, रात में बार-बार जागना आपको थका देता है। अपनी थकान मूड डायरी में लिखिए और अपने साथी से सहारा माँगिए।', title_id = 'Pahlawan malam 🦸‍♀️', body_id = 'Kami tahu, sering terbangun di malam hari sangat menguras tenaga. Tuliskan rasa lelah Anda di Buku Harian Suasana Hati dan minta dukungan dari pasangan.', title_ja = '夜のヒーロー 🦸‍♀️', body_ja = '夜中に何度も起こされてへとへとですよね。「気分日記」に疲れを書いて、パートナーにサポートをお願いしましょう。', title_ko = '밤의 영웅들 🦸‍♀️', body_ko = '밤에 깨는 일이 엄마를 지치게 한다는 걸 알아요. 기분 일기에 피로를 적고 배우자에게 도움을 요청하세요.', title_nl = 'Helden van de nacht 🦸‍♀️', body_nl = 'We weten dat het ''s nachts opstaan je uitput. Schrijf je vermoeidheid op in je Stemmingsdagboek en vraag je partner om steun.', title_pl = 'Nocne bohaterki 🦸‍♀️', body_pl = 'Wiemy, że nocne pobudki odbierają ci siły. Zapisz swoje zmęczenie w Dzienniku nastroju i poproś partnera o wsparcie.', title_pt = 'Heroínas da noite 🦸‍♀️', body_pt = 'Sabemos que acordar à noite a deixa sem forças. Escreva o seu cansaço no Diário de Humor e peça apoio ao seu companheiro.', title_sv = 'Nattens hjältar 🦸‍♀️', body_sv = 'Vi vet att nattuppvaknandena tar all din kraft. Skriv ner din trötthet i Humördagboken och be din partner om stöd.', title_vi = 'Những người hùng ban đêm 🦸‍♀️', body_vi = 'Chúng mình biết những lần thức đêm khiến mẹ kiệt sức. Hãy viết sự mệt mỏi vào Nhật ký tâm trạng và nhờ bố hỗ trợ mẹ nhé.', title_zh = '夜间英雄 🦸‍♀️', body_zh = '我们知道夜醒让你精疲力竭。把疲惫写进心情日记，请伴侣给你一些支持。' WHERE id = '6065edb3-ae62-4429-96cf-e894b4e2c7d8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Me ves? 🧸', body_es = 'Esconde un juguete a medias bajo una manta. ¿Lo busca y lo encuentra? ¡Es un gran paso para entender que los objetos siguen existiendo!', title_fr = 'Tu me vois ? 🧸', body_fr = 'Cachez un jouet à moitié sous une couverture. Le cherche-t-il et le trouve-t-il ? C''est un superbe progrès pour comprendre la permanence de l''objet !', title_hi = 'आप मुझे देख रही हैं? 🧸', body_hi = 'किसी खिलौने को कंबल के नीचे आधा छिपाइए। क्या वह उसे ढूँढ लेता है? चीज़ों के स्थायी होने को समझने की दिशा में यह शानदार कदम है!', title_id = 'Bisa lihat aku? 🧸', body_id = 'Sembunyikan setengah mainan di bawah selimut. Apakah ia mencari dan menemukannya? Ini langkah perkembangan luar biasa untuk memahami bahwa benda tetap ada!', title_ja = 'わたしが見える？🧸', body_ja = 'おもちゃを毛布の下に半分だけ隠してみましょう。探して見つけられるかな？見えなくてもものはあると理解する、すばらしい成長の一歩です！', title_ko = '저 보여요? 🧸', body_ko = '장난감을 담요 밑에 반쯤 숨겨 보세요. 찾아내나요? 대상 영속성을 이해하는 멋진 발달 단계예요!', title_nl = 'Zie je me? 🧸', body_nl = 'Verstop een speeltje half onder een dekentje. Gaat je baby zoeken en vindt hij het? Een geweldige stap in het begrijpen dat dingen blijven bestaan!', title_pl = 'Widzisz mnie? 🧸', body_pl = 'Schowaj zabawkę do połowy pod kocykiem. Czy jej szuka i ją znajduje? To wspaniały krok w rozwoju, by zrozumieć stałość przedmiotu!', title_pt = 'Estás a ver-me? 🧸', body_pt = 'Esconda um brinquedo até meio debaixo da manta. Ele procura-o e encontra-o? É um passo fantástico para perceber que os objetos continuam a existir!', title_sv = 'Ser du mig? 🧸', body_sv = 'Göm en leksak halvvägs under en filt. Letar barnet efter den och hittar den? Det är ett fantastiskt utvecklingssteg mot att förstå att föremål finns kvar!', title_vi = 'Mẹ có thấy con không? 🧸', body_vi = 'Giấu một nửa món đồ chơi dưới chăn. Bé có tìm ra không? Đây là bước phát triển tuyệt vời để bé hiểu rằng đồ vật vẫn tồn tại dù không nhìn thấy!', title_zh = '看得见我吗？🧸', body_zh = '把玩具半藏在毯子下面。宝宝会去找吗？这是理解物体恒存的一大发育进步！' WHERE id = 'ad21218a-5e7d-436c-9c74-264990c096bd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El paseo es imprescindible ⛅', body_es = 'Mira la herramienta Tiempo y ropa, viste a tu bebé y pasead por el parque al menos 20 minutos. Os hace falta a los dos.', title_fr = 'La promenade, c''est indispensable ⛅', body_fr = 'Consultez l''outil Météo et tenue, habillez bébé et promenez-vous au parc au moins 20 minutes. Vous en avez besoin tous les deux.', title_hi = 'सैर ज़रूरी है ⛅', body_hi = 'मौसम और कपड़े टूल देखिए, बच्चे को कपड़े पहनाइए और कम से कम 20 मिनट पार्क में घूमिए। यह आप दोनों के लिए ज़रूरी है।', title_id = 'Jalan-jalan itu wajib ⛅', body_id = 'Cek fitur Cuaca dan Pakaian, pakaikan baju si kecil, dan jalan-jalanlah di taman setidaknya 20 menit. Ini penting bagi Anda dan dia.', title_ja = 'お散歩は欠かせない ⛅', body_ja = '「天気と服装」ツールをチェックして赤ちゃんに服を着せ、公園を最低20分お散歩しましょう。あなたにも赤ちゃんにも必要な時間です。', title_ko = '산책은 꼭 필요해요 ⛅', body_ko = '날씨와 옷차림 도구를 확인하고 아기에게 옷을 입혀 공원에서 최소 20분 걸어 보세요. 엄마와 아기 모두에게 꼭 필요해요.', title_nl = 'Wandelen is een must ⛅', body_nl = 'Kijk in de tool Weer en kleding, kleed je baby aan en wandel minstens 20 minuten in het park. Dat hebben jullie allebei echt nodig.', title_pl = 'Spacer to podstawa ⛅', body_pl = 'Sprawdź narzędzie Pogoda i ubiór, ubierz maluszka i spaceruj po parku co najmniej 20 minut. To koniecznie potrzebne i tobie, i jemu.', title_pt = 'O passeio é obrigatório ⛅', body_pt = 'Veja a ferramenta Tempo e Roupa, vista o bebé e passeie no parque pelo menos 20 minutos. Faz falta a si e a ele.', title_sv = 'Promenaden är ett måste ⛅', body_sv = 'Kolla Väder och kläder, klä på barnet och promenera i parken i minst 20 minuter. Det behöver både du och barnet.', title_vi = 'Nhất định phải đi dạo ⛅', body_vi = 'Xem công cụ Thời tiết và trang phục, mặc đồ cho bé và đi dạo trong công viên ít nhất 20 phút. Cả mẹ và bé đều rất cần điều này.', title_zh = '一定要散步 ⛅', body_zh = '查看天气穿衣工具，给宝宝穿好衣服，去公园至少走20分钟。这对你和宝宝都很必要。' WHERE id = 'faba44da-b2fb-4aa7-a374-4d5f04ad9d27' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lista como un médico 🤖', body_es = '¿Hay algo en los movimientos de tu bebé que te parece raro? En vez de leer noticias que asustan en internet, recibe una respuesta precisa de Anacan AI.', title_fr = 'Aussi malin qu''un médecin 🤖', body_fr = 'Quelque chose vous semble étrange dans ses mouvements ? Plutôt que de lire des histoires effrayantes sur Internet, obtenez une réponse précise d''Anacan AI.', title_hi = 'डॉक्टर जितना समझदार 🤖', body_hi = 'बच्चे की हरकतों में कुछ अजीब लग रहा है? इंटरनेट पर डरावनी खबरें पढ़ने के बजाय Anacan AI से सटीक जवाब पाइए।', title_id = 'Cerdas seperti dokter 🤖', body_id = 'Ada gerakan si kecil yang terasa aneh bagi Anda? Daripada membaca berita menakutkan di internet, dapatkan jawaban akurat dari Anacan AI.', title_ja = 'お医者さんのように賢い 🤖', body_ja = '赤ちゃんの動きで気になることがありますか？ネットで怖い話を読むより、Anacan AIで正確な答えを受け取りましょう。', title_ko = '의사처럼 똑똑하게 🤖', body_ko = '아이의 움직임에 이상하게 느껴지는 점이 있나요? 인터넷에서 무서운 이야기를 읽는 대신 Anacan AI에게서 정확한 답을 받아 보세요.', title_nl = 'Zo slim als een dokter 🤖', body_nl = 'Vind je iets vreemd aan de bewegingen van je kleintje? Lees geen enge verhalen op internet, maar krijg een precies antwoord van Anacan AI.', title_pl = 'Mądry jak lekarz 🤖', body_pl = 'Coś w ruchach maluszka wydaje ci się dziwne? Zamiast czytać w internecie straszne historie, uzyskaj dokładną odpowiedź od Anacan AI.', title_pt = 'Inteligente como um médico 🤖', body_pt = 'Há algo nos movimentos do bebé que lhe parece estranho? Em vez de ler notícias assustadoras na internet, peça uma resposta precisa ao Anacan AI.', title_sv = 'Smart som en läkare 🤖', body_sv = 'Är det något i barnets rörelser som känns konstigt? I stället för att läsa skrämmande nyheter på nätet, få ett exakt svar från Anacan AI.', title_vi = 'Thông minh như bác sĩ 🤖', body_vi = 'Có điều gì trong cử động của bé khiến mẹ thấy lạ? Thay vì đọc những tin đáng sợ trên mạng, hãy nhận câu trả lời chính xác từ Anacan AI.', title_zh = '像医生一样聪明 🤖', body_zh = '宝宝的动作有什么让你觉得奇怪？与其在网上看吓人的消息，不如向Anacan AI要个准确答案。' WHERE id = '46a6fe4d-c7d7-4c66-88f8-3a6a534cd295' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Nana de papá 👨‍🍼', body_es = 'Con el Modo pareja, las notificaciones le llegan a tu pareja. Que esta noche sea él quien lea el cuento y cante la nana. Tú solo mira.', title_fr = 'Une berceuse de papa 👨‍🍼', body_fr = 'Avec le mode Partenaire, les notifications vont à votre conjoint. Ce soir, c''est lui qui lit le conte et chante la berceuse. Vous, contentez-vous de regarder.', title_hi = 'पापा की लोरी 👨‍🍼', body_hi = 'पार्टनर मोड में सूचनाएँ आपके साथी को जाने दीजिए। आज रात सोने से पहले कहानी और लोरी वही सुनाएँ, और आप बस देखिए।', title_id = 'Nina bobo dari ayah 👨‍🍼', body_id = 'Di Mode Pasangan, biarkan notifikasi masuk ke pasangan Anda. Malam ini, biar ia yang membacakan dongeng dan menyanyikan nina bobo. Anda cukup menonton.', title_ja = 'パパの子守唄 👨‍🍼', body_ja = '「パートナーモード」で通知をパートナーに届けましょう。今夜は寝る前のお話と子守唄をパパにおまかせして、あなたは見守り役に。', title_ko = '아빠의 자장가 👨‍🍼', body_ko = '파트너 모드에서는 알림이 배우자에게 가요. 오늘 밤은 배우자가 잠들기 전 동화와 자장가를 맡게 하고, 엄마는 지켜보기만 하세요.', title_nl = 'Een slaapliedje van papa 👨‍🍼', body_nl = 'Laat in de Partnermodus de meldingen naar je partner gaan. Laat hem vanavond het sprookje voorlezen en het slaapliedje zingen. Jij kijkt gewoon toe.', title_pl = 'Kołysanka od taty 👨‍🍼', body_pl = 'W trybie Partnera powiadomienia trafią do partnera. Dziś wieczorem niech to on przeczyta bajkę i zaśpiewa kołysankę na dobranoc. A ty tylko patrz.', title_pt = 'Uma canção de embalar do pai 👨‍🍼', body_pt = 'No Modo Parceiro, as notificações vão para o seu companheiro. Esta noite, é ele quem conta a história e canta a canção de embalar. A mãe só assiste.', title_sv = 'Vaggvisa från pappa 👨‍🍼', body_sv = 'Låt aviseringarna gå till din partner i Partnerläget. I kväll får han läsa sagan och sjunga vaggvisan inför sömnen. Du kan bara titta på.', title_vi = 'Lời ru của bố 👨‍🍼', body_vi = 'Ở Chế độ đối tác, thông báo sẽ được gửi đến bố. Tối nay hãy để bố kể chuyện và hát ru đưa bé vào giấc ngủ. Còn mẹ chỉ cần ngắm thôi.', title_zh = '爸爸的摇篮曲 👨‍🍼', body_zh = '开启伴侣模式，让通知发给伴侣。今晚让他来讲睡前故事、唱摇篮曲，你只管在一旁看着。' WHERE id = 'ac9907ff-b075-4451-8252-dbc842968901' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Te mira con una gran sonrisa y dice sílabas distintas. Ahora mismo te está dando el concierto matutino más bonito, ¡escúchale con atención!', body_fr = 'Il vous regarde et prononce différentes syllabes avec un grand sourire. Il vous donne en ce moment le plus beau concert du matin, écoutez bien !', body_hi = 'आपको देखकर बड़ी मुस्कान के साथ अलग-अलग अक्षर बोलता है। वह इस समय कमरे में सबसे प्यारा सुबह का कॉन्सर्ट दे रहा है, ध्यान से सुनिए!', body_id = 'Ia menatap Anda sambil mengucapkan berbagai suku kata dengan senyum lebar. Ia sedang memberi konser pagi terindah di kamar, dengarkan baik-baik!', body_ja = 'あなたを見て、満面の笑みでいろいろな音を出していますか？今、部屋でいちばんすてきな朝のコンサートを開いています。よく聞いてあげて！', body_ko = '엄마를 보며 활짝 웃고 여러 소리를 내나요? 지금 방 안에서 가장 아름다운 아침 콘서트가 열리고 있어요, 귀 기울여 들어 보세요!', body_nl = 'Kijkt je baby je aan en zegt hij met een grote glimlach allerlei lettergrepen? Hij geeft nu het mooiste ochtendconcert in de kamer, luister goed!', body_pl = 'Patrzy na ciebie i z szerokim uśmiechem wymawia różne sylaby. Właśnie daje w pokoju najpiękniejszy poranny koncert, posłuchaj uważnie!', body_pt = 'Olha para si com um grande sorriso e diz sílabas diferentes. Está a dar-lhe o mais bonito concerto da manhã, ouça com atenção!', body_sv = 'Barnet tittar på dig och säger olika stavelser med ett stort leende. Just nu ger det den vackraste morgonkonserten i rummet, lyssna noga!', body_vi = 'Bé nhìn mẹ, cười thật tươi và bập bẹ những âm khác nhau. Bé đang tổ chức buổi hòa nhạc buổi sáng tuyệt vời nhất ngay trong phòng đấy, hãy lắng nghe thật kỹ!', body_zh = '宝宝看着你，咧嘴笑着发出各种音节？宝宝正在为你开一场最美的早晨音乐会，好好听吧！' WHERE id = 'aedfce5f-449d-49c9-8f9b-a5ac88f1e750' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Dudas sobre la rutina de sueño? 🤖', body_es = 'Escribe en la Comunidad Anacan tus dudas sobre los cambios de sueño hacia el 5.º mes y recibe el apoyo de otras mamás.', title_fr = 'Des doutes sur le rythme de sommeil ? 🤖', body_fr = 'Posez vos questions sur les changements de sommeil à l''approche du 5e mois dans la Communauté Anacan et recevez le soutien d''autres mamans.', title_hi = 'नींद के रूटीन को लेकर उलझन? 🤖', body_hi = '5वें महीने के आसपास नींद में बदलाव को लेकर अपने सवाल Anacan कम्युनिटी में लिखिए और दूसरी माँओं से सहारा पाइए।', title_id = 'Ragu soal jadwal tidur? 🤖', body_id = 'Tulis pertanyaan Anda tentang perubahan tidur menjelang bulan ke-5 di Komunitas Anacan dan dapatkan dukungan dari ibu-ibu lain.', title_ja = 'ねんねのリズムで迷っていますか？🤖', body_ja = '生後5か月ごろの睡眠の変化について、Anacanコミュニティで質問して、ほかのママたちから支えてもらいましょう。', title_ko = '수면 패턴이 고민인가요? 🤖', body_ko = '5개월 무렵의 수면 변화에 대한 질문을 Anacan 커뮤니티에 남기고 다른 엄마들의 응원을 받아 보세요.', title_nl = 'Twijfels over het slaapritme? 🤖', body_nl = 'Stel je vragen over slaapveranderingen rond de 5e maand in de Anacan Community en krijg steun van andere moeders.', title_pl = 'Masz wątpliwości co do rytmu snu? 🤖', body_pl = 'Zadaj pytania o zmiany snu w okolicach 5. miesiąca w Społeczności Anacan i otrzymaj wsparcie od innych mam.', title_pt = 'Tem dúvidas sobre a rotina de sono? 🤖', body_pt = 'Escreva na Comunidade Anacan as suas perguntas sobre as mudanças no sono perto do 5.º mês e receba o apoio de outras mães.', title_sv = 'Osäker på sömnrutinen? 🤖', body_sv = 'Skriv dina frågor om sömnförändringar inför 5:e månaden i Anacans Community och få stöd från andra mammor.', title_vi = 'Mẹ còn băn khoăn về giấc ngủ của bé? 🤖', body_vi = 'Hãy đăng câu hỏi về những thay đổi giấc ngủ khi bé gần 5 tháng trong Cộng đồng Anacan và nhận sự hỗ trợ từ các bà mẹ khác.', title_zh = '对睡眠作息拿不准？🤖', body_zh = '关于快满5个月时的睡眠变化，把问题发到Anacan社区，获得其他妈妈的支持吧。' WHERE id = '46db3cbc-ae0b-4520-b12e-5586db9977cf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Control del sonido 🤫', body_es = 'A finales del cuarto mes, dormirse a veces se complica. Abre el Medidor de sonido, comprueba el límite de ruido y asegúrate de que la habitación esté a oscuras.', title_fr = 'Contrôle du bruit 🤫', body_fr = 'L''endormissement devient parfois plus difficile à la fin du quatrième mois. Ouvrez le Sonomètre, vérifiez le niveau sonore et faites bien le noir dans la pièce.', title_hi = 'आवाज़ पर नज़र 🤫', body_hi = 'चौथे महीने के आखिर में कभी-कभी सोना मुश्किल हो जाता है। साउंड मीटर खोलिए, आवाज़ की सीमा जाँचिए और कमरे में पूरा अँधेरा ज़रूर कीजिए।', title_id = 'Kontrol suara 🤫', body_id = 'Menjelang akhir bulan keempat, tertidur kadang jadi lebih sulit. Nyalakan Pengukur Suara, cek batas suara, dan pastikan kamar benar-benar gelap.', title_ja = '音のチェック 🤫', body_ja = '生後4か月の終わりごろは、寝つきが悪くなることもあります。「サウンドメーター」をオンにして音の目安をチェックし、部屋をしっかり暗くしましょう。', title_ko = '소리 관리 🤫', body_ko = '4개월 말쯤에는 잠들기가 가끔 어려워져요. 소음 측정기를 켜서 소리 한도를 확인하고 방을 꼭 어둡게 해 주세요.', title_nl = 'Geluidscontrole 🤫', body_nl = 'Aan het eind van de vierde maand gaat in slaap vallen soms moeilijker. Zet de Geluidsmeter aan, controleer het geluidsniveau en maak de kamer zeker donker.', title_pl = 'Kontrola dźwięku 🤫', body_pl = 'Pod koniec czwartego miesiąca zasypianie bywa trudniejsze. Włącz Miernik dźwięku, sprawdź poziom hałasu i koniecznie zaciemnij pokój.', title_pt = 'Controlo do som 🤫', body_pt = 'No fim do 4.º mês, adormecer às vezes fica mais difícil. Abra o Medidor de Som, verifique o limite de ruído e escureça bem o quarto.', title_sv = 'Ljudkoll 🤫', body_sv = 'I slutet av fjärde månaden kan det ibland bli svårare att somna. Öppna Ljudmätaren, kolla ljudnivån och se till att rummet är mörkt.', title_vi = 'Kiểm soát âm thanh 🤫', body_vi = 'Cuối tháng thứ tư, việc vào giấc đôi khi khó hơn. Hãy mở Đo âm thanh, kiểm tra ngưỡng âm thanh và nhớ làm tối phòng nhé.', title_zh = '声音控制 🤫', body_zh = '第四个月末，入睡有时会变难。打开噪音测量，检查音量上限，一定要让房间暗下来。' WHERE id = 'b203fb94-1780-44e0-8f8f-1e6840729e68' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Eres la mejor! 💖', body_es = 'Nadie es perfecto, pero la mejor madre para tu bebé eres precisamente tú.', title_fr = 'Vous êtes la meilleure ! 💖', body_fr = 'Personne n''est parfait, mais pour votre bébé, la meilleure maman, c''est vous.', title_hi = 'आप सबसे अच्छी हैं! 💖', body_hi = 'कोई भी इंसान परफ़ेक्ट नहीं होता, लेकिन आपके बच्चे के लिए सबसे अच्छी माँ आप ही हैं।', title_id = 'Anda yang terbaik! 💖', body_id = 'Tidak ada manusia yang sempurna, tapi bagi bayi Anda, Andalah ibu terbaik.', title_ja = 'あなたは最高！💖', body_ja = '完璧な人はいません。でも赤ちゃんにとって最高のママは、まさにあなたです。', title_ko = '엄마가 최고예요! 💖', body_ko = '완벽한 사람은 없지만, 아기에게 가장 좋은 엄마는 바로 당신이에요.', title_nl = 'Jij bent de beste! 💖', body_nl = 'Niemand is perfect, maar voor je baby ben jij de allerbeste mama.', title_pl = 'Jesteś najlepsza! 💖', body_pl = 'Nie ma ludzi idealnych, ale dla twojego maluszka najlepszą mamą jesteś właśnie ty.', title_pt = 'É a melhor! 💖', body_pt = 'Ninguém é perfeito, mas a melhor mãe para o seu bebé é precisamente a senhora.', title_sv = 'Du är bäst! 💖', body_sv = 'Ingen människa är perfekt, men för ditt barn är just du den bästa mamman.', title_vi = 'Mẹ là tuyệt nhất! 💖', body_vi = 'Không ai hoàn hảo cả, nhưng với bé, mẹ chính là người mẹ tốt nhất.', title_zh = '你是最棒的！💖', body_zh = '没有完美的人，但对宝宝来说，你就是最好的妈妈。' WHERE id = 'd7985574-7fae-4ef9-b025-2442a8b0b3a6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Recarga energía 🍲', body_es = 'Si tú estás sana, tu bebé también. Elige en Recetas saludables una rica magdalena que te dé fuerzas y disfrútala con tu café.', title_fr = 'Faites le plein d''énergie 🍲', body_fr = 'Si vous êtes en forme, il l''est aussi. Choisissez dans les Recettes saines un délicieux cake qui vous donnera de l''énergie et savourez-le avec votre café.', title_hi = 'ऊर्जा जमा कीजिए 🍲', body_hi = 'आप सेहतमंद हैं, तो वह भी सेहतमंद है। सेहतमंद रेसिपी से ताकत देने वाले किसी स्वादिष्ट केक की रेसिपी चुनिए और कॉफ़ी के साथ मज़ा लीजिए।', title_id = 'Isi ulang energi 🍲', body_id = 'Kalau Anda sehat, ia juga sehat. Pilih resep kue lezat penambah tenaga dari Resep Sehat dan nikmati bersama kopi Anda.', title_ja = 'エネルギーをチャージ 🍲', body_ja = 'あなたが元気なら、赤ちゃんも元気。「ヘルシーレシピ」から元気が出るおいしいマフィンのレシピを選んで、コーヒーと一緒に楽しみましょう。', title_ko = '에너지 충전 🍲', body_ko = '엄마가 건강해야 아기도 건강해요. 건강한 레시피에서 힘이 나는 맛있는 머핀 레시피를 골라 커피와 함께 즐겨 보세요.', title_nl = 'Laad je energie op 🍲', body_nl = 'Als jij gezond bent, is je baby dat ook. Kies uit Gezonde recepten een lekker, krachtgevend cakerecept en geniet ervan bij je koffie.', title_pl = 'Zgromadź energię 🍲', body_pl = 'Gdy ty jesteś zdrowa, on też jest zdrowy. Wybierz w Zdrowych przepisach smaczną babeczkę, która doda ci sił, i delektuj się nią przy kawie.', title_pt = 'Acumule energia 🍲', body_pt = 'Se a mãe está saudável, o bebé também está. Escolha nas Receitas Saudáveis um queque saboroso que lhe dê forças e aproveite-o com um café.', title_sv = 'Ladda energi 🍲', body_sv = 'Mår du bra, mår barnet bra. Välj ett gott kakrecept som ger dig kraft från Hälsosamma recept och njut av det till kaffet.', title_vi = 'Nạp năng lượng 🍲', body_vi = 'Mẹ khỏe thì bé cũng khỏe. Chọn một công thức bánh nướng ngon lành giúp mẹ thêm sức từ Công thức lành mạnh và thưởng thức cùng tách cà phê nhé.', title_zh = '储备能量 🍲', body_zh = '你健康，宝宝才健康。从健康食谱里挑一款给你力量的美味蛋糕，配着咖啡享用吧。' WHERE id = '2e9ea238-ddc7-4932-b1bd-be8b8ed87bc9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Maestra de cuentos inteligentes 🪄', body_es = 'Esta noche, crea en Cuentos inteligentes una historia especial y emotiva sobre lo rápido que tu peque está creciendo hacia su 5.º mes.', title_fr = 'Le conteur intelligent 🪄', body_fr = 'Ce soir, dans les Contes intelligents, créez une histoire unique et émouvante sur la vitesse à laquelle votre bout de chou grandit vers son 5e mois.', title_hi = 'स्मार्ट कहानीकार 🪄', body_hi = 'आज रात स्मार्ट कहानियों में एक खास, भावुक कहानी बनाइए कि आपका नन्हा कितनी तेज़ी से 5वें महीने की ओर बढ़ रहा है।', title_id = 'Pendongeng pintar 🪄', body_id = 'Malam ini, di Dongeng Pintar, buat kisah istimewa dan menyentuh tentang betapa cepatnya si kecil tumbuh menuju bulan ke-5.', title_ja = 'かしこいお話の名人 🪄', body_ja = '今夜は「スマートおはなし」で、赤ちゃんが5か月に向けてぐんぐん成長していく様子を描いた、心にしみる特別なお話をつくりましょう。', title_ko = '스마트한 이야기꾼 🪄', body_ko = '오늘 밤 스마트 동화에서 아기가 5개월을 향해 얼마나 빨리 자랐는지 담은 특별하고 감동적인 이야기를 만들어 보세요.', title_nl = 'Slimme verhalenverteller 🪄', body_nl = 'Maak vanavond in Slimme sprookjes een bijzonder, ontroerend verhaal over hoe snel je kleintje naar de 5e maand groeit.', title_pl = 'Mądra mistrzyni opowieści 🪄', body_pl = 'Dziś wieczorem stwórz w Mądrych bajkach wyjątkową, wzruszającą historię o tym, jak szybko maluszek rośnie w stronę 5. miesiąca.', title_pt = 'Mestre das histórias inteligentes 🪄', body_pt = 'Esta noite, crie nas Histórias Inteligentes uma história especial e emotiva sobre a rapidez com que o pequenino está a chegar ao 5.º mês.', title_sv = 'Smart sagoberättare 🪄', body_sv = 'I kväll, skapa en personlig och känslosam saga i Smarta sagor om hur snabbt den lilla har vuxit fram till 5:e månaden.', title_vi = 'Người kể chuyện thông minh 🪄', body_vi = 'Tối nay, trong Truyện cổ tích thông minh, hãy tạo một câu chuyện riêng đầy cảm xúc về việc bé lớn nhanh thế nào để bước sang tháng thứ 5.', title_zh = '智能讲故事大师 🪄', body_zh = '今晚在智能故事里创作一个专属的温情故事，讲讲小宝贝如何飞快地长到5个月。' WHERE id = 'd25e75e7-0029-43b9-b1e7-c401d6b9ca28' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rumbo a la independencia 🤸‍♂️', body_es = '¿Ya se gira con facilidad de espaldas a boca abajo? Sus músculos se desarrollan muy rápido. Ponle a menudo sobre la alfombra para que se mueva a gusto.', title_fr = 'Vers l''autonomie 🤸‍♂️', body_fr = 'Il se retourne déjà facilement du dos sur le ventre ? Ses muscles se développent vite. Posez-le régulièrement sur le tapis pour qu''il bouge à son aise.', title_hi = 'आत्मनिर्भरता की ओर 🤸‍♂️', body_hi = 'क्या वह अब आसानी से पीठ से पेट के बल पलट जाता है? उसकी मांसपेशियाँ तेज़ी से विकसित हो रही हैं। आराम से हिलने-डुलने के लिए उसे नियमित रूप से मैट पर रखिए।', title_id = 'Menuju kemandirian 🤸‍♂️', body_id = 'Ia sudah mudah berguling dari telentang ke tengkurap? Ototnya berkembang pesat. Letakkan ia secara rutin di atas alas bermain agar leluasa bergerak.', title_ja = 'ひとりでできるに向かって 🤸‍♂️', body_ja = 'もう仰向けからうつぶせにすいすい寝返りしていますか？筋肉がぐんぐん発達しています。自由に動けるように、こまめにマットの上に寝かせてあげましょう。', title_ko = '독립을 향해 🤸‍♂️', body_ko = '이제 등에서 배로 쉽게 뒤집나요? 근육이 빠르게 발달하고 있어요. 편하게 움직일 수 있도록 매트 위에 자주 눕혀 주세요.', title_nl = 'Op weg naar zelfstandigheid 🤸‍♂️', body_nl = 'Rolt je baby al makkelijk van rug naar buik? De spiertjes ontwikkelen zich snel. Leg hem regelmatig op een speelkleed, zodat hij vrij kan bewegen.', title_pl = 'W stronę samodzielności 🤸‍♂️', body_pl = 'Już swobodnie przewraca się z pleców na brzuch? Jego mięśnie szybko się rozwijają. Regularnie kładź go na dywanie, by mógł się swobodnie ruszać.', title_pt = 'Rumo à independência 🤸‍♂️', body_pt = 'Já se vira facilmente de costas para a barriga? Os músculos estão a desenvolver-se depressa. Ponha-o regularmente no tapete para se mexer à vontade.', title_sv = 'Mot självständighet 🤸‍♂️', body_sv = 'Vänder sig barnet redan lätt från rygg till mage? Musklerna utvecklas snabbt. Lägg barnet regelbundet på mattan så att det kan röra sig fritt.', title_vi = 'Hướng tới tự lập 🤸‍♂️', body_vi = 'Bé đã lật từ ngửa sang sấp dễ dàng? Cơ bắp của bé đang phát triển nhanh. Hãy thường xuyên đặt bé trên thảm để bé thoải mái vận động.', title_zh = '迈向独立 🤸‍♂️', body_zh = '宝宝已经能轻松地从仰躺翻到趴着了？肌肉发育得很快。经常把宝宝放在地垫上，让宝宝自在活动吧。' WHERE id = '6a21d9c4-96ab-4453-9d5f-d8979016e2cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Suelta la culpa 🛑', body_es = '¿Hoy se te acabó la paciencia y alzaste la voz? No te sientas mal. No eres un robot incansable. Mañana lo vuelves a intentar.', title_fr = 'Lâchez la culpabilité 🛑', body_fr = 'Aujourd''hui, vous avez perdu patience et haussé le ton ? Ne vous sentez pas mal. Vous n''êtes pas un robot infatigable. Demain, vous réessaierez.', title_hi = 'अपराध-बोध छोड़िए 🛑', body_hi = 'आज आपका धैर्य जवाब दे गया और आवाज़ ऊँची हो गई? बुरा मत मानिए। आप कोई न थकने वाली रोबोट नहीं हैं। कल फिर कोशिश कीजिएगा।', title_id = 'Buang rasa bersalah 🛑', body_id = 'Hari ini kesabaran Anda habis dan Anda meninggikan suara? Jangan merasa bersalah. Anda bukan robot yang tak kenal lelah. Besok Anda bisa mencoba lagi.', title_ja = '罪悪感は手放して 🛑', body_ja = '今日はがまんの限界で、声を荒らげてしまった？自分を責めないで。あなたは疲れを知らないロボットではありません。明日またやり直せます。', title_ko = '죄책감은 내려놓으세요 🛑', body_ko = '오늘 인내심이 바닥나서 목소리를 높였나요? 자책하지 마세요. 지치지 않는 로봇이 아니잖아요. 내일 다시 해 보면 돼요.', title_nl = 'Laat het schuldgevoel los 🛑', body_nl = 'Was je geduld vandaag op en verhief je je stem? Voel je niet schuldig. Je bent geen onvermoeibare robot. Morgen probeer je het gewoon opnieuw.', title_pl = 'Porzuć poczucie winy 🛑', body_pl = 'Dziś skończyła ci się cierpliwość i podniosłaś głos? Nie czuj się źle. Nie jesteś niezniszczalnym robotem. Jutro spróbujesz znowu.', title_pt = 'Largue a culpa 🛑', body_pt = 'Hoje perdeu a paciência e levantou a voz? Não se sinta mal. Não é um robô incansável. Amanhã volta a tentar.', title_sv = 'Släpp skuldkänslorna 🛑', body_sv = 'Tog tålamodet slut i dag och du höjde rösten? Må inte dåligt. Du är ingen outtröttlig robot. I morgon kan du försöka igen.', title_vi = 'Gạt bỏ cảm giác tội lỗi 🛑', body_vi = 'Hôm nay mẹ hết kiên nhẫn và lỡ to tiếng? Đừng tự trách mình. Mẹ đâu phải là robot không biết mệt. Ngày mai mẹ có thể thử lại.', title_zh = '放下愧疚感 🛑', body_zh = '今天没了耐心，提高了嗓门？别难过。你不是不知疲倦的机器人。明天再试一次就好。' WHERE id = 'c057830d-8790-40ec-a09d-53a252d3ee15' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No estás sola 💬', body_es = 'Echa un vistazo a lo que escriben otras mamás de bebés de 5 meses en la Comunidad Anacan. ¡En todas las casas hay el mismo caos, la misma falta de sueño y el mismo amor!', title_fr = 'Vous n''êtes pas seule 💬', body_fr = 'Jetez un œil à ce qu''écrivent les autres mamans de bébés de 5 mois dans la Communauté Anacan. Dans tous les foyers, le même chaos, le même manque de sommeil et le même amour !', title_hi = 'आप अकेली नहीं हैं 💬', body_hi = 'Anacan कम्युनिटी में 5 महीने के बच्चों की दूसरी माँओं ने क्या लिखा है, एक नज़र डालिए। हर घर में वही अफ़रा-तफ़री, वही जागी रातें और वही प्यार है!', title_id = 'Anda tidak sendirian 💬', body_id = 'Intip apa yang ditulis ibu-ibu lain dengan bayi 5 bulan di Komunitas Anacan. Di setiap rumah ada kekacauan yang sama, kurang tidur yang sama, dan cinta yang sama!', title_ja = 'ひとりじゃない 💬', body_ja = 'Anacanコミュニティで、ほかの5か月の赤ちゃんのママたちの投稿をのぞいてみましょう。どの家にも同じカオス、同じ寝不足、そして同じ愛があります！', title_ko = '혼자가 아니에요 💬', body_ko = 'Anacan 커뮤니티에서 다른 5개월 아기 엄마들의 글을 살펴보세요. 어느 집이나 똑같은 혼돈, 똑같은 잠 부족, 똑같은 사랑이 있어요!', title_nl = 'Je bent niet alleen 💬', body_nl = 'Kijk eens wat andere moeders van 5 maanden oude baby''s schrijven in de Anacan Community. In elk huis dezelfde chaos, hetzelfde slaaptekort en dezelfde liefde!', title_pl = 'Nie jesteś sama 💬', body_pl = 'Zajrzyj, co piszą inne mamy 5-miesięcznych maluchów w Społeczności Anacan. W każdym domu ten sam chaos, to samo niewyspanie i ta sama miłość!', title_pt = 'Não está sozinha 💬', body_pt = 'Espreite o que escrevem outras mães de bebés de 5 meses na Comunidade Anacan. Em todas as casas há o mesmo caos, a mesma falta de sono e o mesmo amor!', title_sv = 'Du är inte ensam 💬', body_sv = 'Kika på vad andra mammor till 5 månader gamla barn skriver i Anacans Community. I alla hem finns samma kaos, samma sömnbrist och samma kärlek!', title_vi = 'Mẹ không đơn độc 💬', body_vi = 'Hãy xem những gì các bà mẹ có con 5 tháng khác chia sẻ trong Cộng đồng Anacan. Nhà nào cũng có cùng sự bừa bộn, cùng những đêm mất ngủ và cùng một tình yêu!', title_zh = '你并不孤单 💬', body_zh = '看看Anacan社区里其他5个月宝宝的妈妈们写了什么。每个家里都是一样的混乱、一样的缺觉、一样的爱！' WHERE id = 'fd786e6d-a723-4c95-b0ff-52e01e6ccb8a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te pierdas sus señales de sueño 🥱', body_es = 'Si se queda con la mirada perdida, déjalo todo enseguida. Llévale a la cama antes de que se cierre su ventana de sueño.', title_fr = 'Ne manquez pas les signaux de sommeil 🥱', body_fr = 'S''il fixe le vide, laissez tout tomber. Emmenez-le au lit sans manquer sa fenêtre de sommeil.', title_hi = 'नींद के संकेत मत चूकिए 🥱', body_hi = 'अगर वह शून्य में एकटक देख रहा है, तो तुरंत काम छोड़ दीजिए। नींद का समय चूके बिना उसे बिस्तर पर ले जाइए।', title_id = 'Jangan lewatkan tanda mengantuk 🥱', body_id = 'Kalau ia menatap kosong ke satu arah, segera tinggalkan pekerjaan Anda. Bawa ia ke tempat tidur sebelum jendela tidurnya terlewat.', title_ja = 'ねんねのサインを見逃さないで 🥱', body_ja = 'ぼーっと宙を見つめていたら、すぐに手を止めて。眠りのタイミングを逃さないうちにベッドへ連れて行きましょう。', title_ko = '졸음 신호를 놓치지 마세요 🥱', body_ko = '아기가 허공을 멍하니 바라본다면 하던 일을 바로 멈추세요. 수면 타이밍을 놓치기 전에 잠자리로 데려가세요.', title_nl = 'Mis de slaapsignalen niet 🥱', body_nl = 'Staart je baby in het niets? Laat dan meteen alles vallen. Breng hem naar bed voordat het slaapvenster voorbij is.', title_pl = 'Nie przegap sygnałów senności 🥱', body_pl = 'Jeśli wpatruje się w pustkę, od razu rzuć wszystko. Zanieś go do łóżeczka, zanim przegapisz okno snu.', title_pt = 'Não perca os sinais de sono 🥱', body_pt = 'Se ficar de olhar perdido no vazio, largue logo o que está a fazer. Leve-o para a cama sem perder a janela de sono.', title_sv = 'Missa inte sömnsignalerna 🥱', body_sv = 'Stirrar barnet tomt ut i luften? Släpp allt direkt. Bär barnet till sängen innan sömnfönstret stängs.', title_vi = 'Đừng bỏ lỡ tín hiệu buồn ngủ 🥱', body_vi = 'Nếu bé nhìn chằm chằm vào khoảng không, hãy gác mọi việc lại ngay. Đưa bé lên giường trước khi bỏ lỡ "cửa sổ giấc ngủ".', title_zh = '别错过睡眠信号 🥱', body_zh = '如果宝宝两眼发直地盯着空处，马上放下手里的事。趁睡眠窗口还没过，带宝宝上床吧。' WHERE id = '05aab0a6-c49b-4d4d-bd26-b20d5c9af4d5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El mordedor salvador 🦷', body_es = '¿Intenta morderlo todo? Los mordedores de silicona fríos le aliviarán las encías al instante.', title_fr = 'L''anneau de dentition sauveur 🦷', body_fr = 'Il essaie de mordre dans tout ? Des anneaux de dentition en silicone réfrigérés soulageront aussitôt ses gencives.', title_hi = 'टीदर, आपका मददगार 🦷', body_hi = 'हर चीज़ काटने की कोशिश करता है? ठंडे किए हुए सिलिकॉन टीदर उसके मसूड़ों को तुरंत आराम देंगे।', title_id = 'Penyelamat saat tumbuh gigi 🦷', body_id = 'Ia mencoba menggigit semuanya? Teether silikon yang didinginkan akan langsung menenangkan gusinya.', title_ja = '歯固めが救世主 🦷', body_ja = 'なんでもかもうとしていますか？冷やしたシリコンの歯固めが、歯ぐきをすぐに楽にしてくれます。', title_ko = '구원자 치발기 🦷', body_ko = '무엇이든 깨물려고 하나요? 차갑게 한 실리콘 치발기가 잇몸을 바로 편안하게 해 줄 거예요.', title_nl = 'De bijtring als redder 🦷', body_nl = 'Probeert je baby overal in te bijten? Gekoelde siliconen bijtringen verzachten het tandvlees meteen.', title_pl = 'Gryzak na ratunek 🦷', body_pl = 'Próbuje gryźć wszystko? Schłodzone silikonowe gryzaki od razu przyniosą ulgę jego dziąsłom.', title_pt = 'O mordedor salvador 🦷', body_pt = 'Tenta morder tudo? Os mordedores de silicone frescos vão aliviar-lhe logo as gengivas.', title_sv = 'Bitringen räddar dagen 🦷', body_sv = 'Försöker barnet bita på allt? Kylda bitringar i silikon lindrar tandköttet direkt.', title_vi = 'Cứu tinh gặm nướu 🦷', body_vi = 'Bé cố cắn mọi thứ? Gặm nướu silicone đã làm mát sẽ giúp nướu bé dễ chịu ngay.', title_zh = '牙胶救星 🦷', body_zh = '什么都想咬？冰过的硅胶牙胶能马上舒缓宝宝的牙龈。' WHERE id = '0ecae509-0e89-4406-80e4-d01161b92754' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Te conozco! 🥰', body_es = '¿Cuando entras en la habitación te dedica una sonrisa especial, más emocionada y distinta? Sí, te distingue de todos y está enamorado de tu olor.', title_fr = 'Je te reconnais ! 🥰', body_fr = 'Quand vous entrez dans la pièce, il vous fait un sourire spécial, plus excité ? Oui, il vous distingue de tout le monde et il adore votre odeur !', title_hi = 'मैं आपको पहचानता हूँ! 🥰', body_hi = 'कमरे में आते ही वह आपको खास, ज़्यादा उत्साह भरी अलग मुस्कान देता है? हाँ, वह आपको सबसे अलग पहचानता है और आपकी खुशबू का दीवाना है!', title_id = 'Aku kenal Anda! 🥰', body_id = 'Saat Anda masuk kamar, ia tersenyum dengan cara yang istimewa dan lebih bersemangat? Ya, ia membedakan Anda dari semua orang dan jatuh cinta pada aroma Anda!', title_ja = 'ママだってわかるよ！🥰', body_ja = '部屋に入ると、あなたにだけ特別な、うれしそうな笑顔を見せてくれますか？そう、赤ちゃんはあなたをほかの誰とも区別していて、あなたのにおいが大好きなのです！', title_ko = '엄마를 알아요! 🥰', body_ko = '엄마가 방에 들어오면 더 신나고 특별한 미소를 짓나요? 맞아요, 아기는 엄마를 누구보다 알아보고 엄마 냄새를 정말 좋아해요!', title_nl = 'Ik ken jou! 🥰', body_nl = 'Lacht je baby speciaal, extra enthousiast naar je als je de kamer binnenkomt? Ja, jou herkent hij uit iedereen en hij is verliefd op jouw geur!', title_pl = 'Znam cię! 🥰', body_pl = 'Gdy wchodzisz do pokoju, uśmiecha się do ciebie wyjątkowo, z większą radością? Tak, odróżnia cię od wszystkich i uwielbia twój zapach!', title_pt = 'Eu conheço-te! 🥰', body_pt = 'Quando entra no quarto, ele sorri-lhe de forma especial, mais entusiasmada e diferente? Sim, distingue-a de todos e está apaixonado pelo seu cheiro!', title_sv = 'Jag känner igen dig! 🥰', body_sv = 'Ler barnet ett speciellt, mer upphetsat leende när du kommer in i rummet? Ja, barnet skiljer dig från alla andra och är förälskat i din doft!', title_vi = 'Con nhận ra mẹ! 🥰', body_vi = 'Khi mẹ bước vào phòng, bé cười với mẹ một nụ cười đặc biệt, háo hức hơn hẳn? Đúng vậy, bé phân biệt được mẹ với mọi người và mê mẩn mùi hương của mẹ!', title_zh = '我认识你！🥰', body_zh = '你一进房间，宝宝就对你露出格外兴奋、与众不同的笑容？没错，宝宝把你和别人区分开了，深深迷恋着你的气味！' WHERE id = '60bbb8df-cb46-4930-8422-5f0c6fa7daad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dedícate tiempo 🛋️', body_es = 'Cuando tu bebé duerma, dedica el tiempo a ti, no a las tareas de casa. La habitación puede seguir desordenada, pero recuperar tu energía es imprescindible.', title_fr = 'Prenez du temps pour vous 🛋️', body_fr = 'Quand bébé dort, consacrez ce temps à vous, pas aux tâches ménagères. La pièce peut rester en désordre, mais recharger vos batteries est indispensable.', title_hi = 'अपने लिए समय निकालिए 🛋️', body_hi = 'बच्चा सोए तो घर के कामों को नहीं, खुद को समय दीजिए। कमरा बिखरा रह सकता है, पर आपकी ऊर्जा लौटना ज़रूरी है।', title_id = 'Luangkan waktu untuk diri sendiri 🛋️', body_id = 'Saat si kecil tidur, luangkan waktu untuk diri sendiri, bukan pekerjaan rumah. Kamar boleh berantakan, tapi energi Anda harus pulih.', title_ja = '自分の時間をつくって 🛋️', body_ja = '赤ちゃんが寝ている間は、家事ではなく自分のために時間を使いましょう。部屋は散らかっていても大丈夫。でもあなたの元気の回復は欠かせません。', title_ko = '나를 위한 시간 🛋️', body_ko = '아이가 잘 때는 집안일이 아니라 나에게 시간을 쓰세요. 방은 어질러져 있어도 되지만 엄마의 에너지 회복은 꼭 필요해요.', title_nl = 'Maak tijd voor jezelf 🛋️', body_nl = 'Gebruik de tijd dat je baby slaapt voor jezelf, niet voor het huishouden. De kamer mag rommelig blijven, maar jij moet echt weer energie opdoen.', title_pl = 'Znajdź czas dla siebie 🛋️', body_pl = 'Gdy maluszek śpi, poświęć czas sobie, a nie obowiązkom domowym. W pokoju może zostać bałagan, ale twoja energia musi się odnowić.', title_pt = 'Reserve tempo para si 🛋️', body_pt = 'Quando o bebé dorme, reserve tempo para si e não para as tarefas da casa. O quarto pode ficar desarrumado, mas recuperar energia é indispensável.', title_sv = 'Ta tid för dig själv 🛋️', body_sv = 'När barnet sover, ta tid för dig själv i stället för hushållet. Rummet kan få vara stökigt, men din energi måste fyllas på.', title_vi = 'Dành thời gian cho mình 🛋️', body_vi = 'Khi bé ngủ, hãy dành thời gian cho bản thân thay vì việc nhà. Phòng có thể bừa bộn, nhưng mẹ nhất định phải được hồi sức.', title_zh = '留点时间给自己 🛋️', body_zh = '宝宝睡着时，别忙家务，把时间留给自己。房间乱一点没关系，但你的精力一定要恢复。' WHERE id = 'adbfecc6-7186-41fe-a870-83cf6809ec00' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La magia de la naturaleza ⛅', body_es = '¿Está muy inquieto y ningún juguete funciona? Mira Tiempo y ropa y sal enseguida al aire libre. La naturaleza es el mejor calmante.', title_fr = 'La magie de la nature ⛅', body_fr = 'Il est très agité et aucun jouet ne marche ? Consultez Météo et tenue et sortez-le tout de suite au grand air. La nature est le meilleur des calmants.', title_hi = 'प्रकृति का जादू ⛅', body_hi = 'बहुत बेचैन है? कोई खिलौना काम नहीं आ रहा? मौसम और कपड़े देखिए और उसे तुरंत खुली हवा में ले जाइए। प्रकृति सबसे अच्छी शांति देती है।', title_id = 'Keajaiban alam ⛅', body_id = 'Ia sangat rewel? Tidak ada mainan yang mempan? Cek Cuaca dan Pakaian, lalu segera ajak ia ke luar. Alam adalah penenang terbaik.', title_ja = '自然の魔法 ⛅', body_ja = 'ぐずぐずが続いて、どのおもちゃも効かない？「天気と服装」をチェックして、すぐに外へ連れ出しましょう。自然はいちばんの癒やしです。', title_ko = '자연의 마법 ⛅', body_ko = '많이 보채고 어떤 장난감도 소용없나요? 날씨와 옷차림을 확인하고 바로 바깥으로 나가 보세요. 자연이 최고의 진정제예요.', title_nl = 'De magie van de natuur ⛅', body_nl = 'Is je baby erg onrustig en helpt geen enkel speeltje? Kijk in Weer en kleding en ga meteen naar buiten. De natuur is het beste kalmeermiddel.', title_pl = 'Magia natury ⛅', body_pl = 'Jest bardzo niespokojny? Żadna zabawka nie działa? Sprawdź Pogodę i ubiór i od razu wyjdź z nim na dwór. Natura to najlepszy uspokajacz.', title_pt = 'A magia da natureza ⛅', body_pt = 'Está muito inquieto e nenhum brinquedo resulta? Veja o Tempo e Roupa e leve-o já para o ar livre. A natureza é o melhor calmante.', title_sv = 'Naturens magi ⛅', body_sv = 'Väldigt oroligt? Hjälper ingen leksak? Kolla Väder och kläder och gå ut med barnet direkt. Naturen är det bästa lugnande medlet.', title_vi = 'Phép màu của thiên nhiên ⛅', body_vi = 'Bé quấy khóc nhiều và chẳng đồ chơi nào có tác dụng? Xem Thời tiết và trang phục rồi đưa bé ra ngoài trời ngay. Thiên nhiên là liều thuốc xoa dịu tốt nhất.', title_zh = '大自然的魔力 ⛅', body_zh = '宝宝特别烦躁，什么玩具都不管用？查看天气穿衣，马上带宝宝去户外。大自然是最好的安抚剂。' WHERE id = 'ba61a641-e703-4b01-b161-601cf36add7a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué llora otra vez? 😭', body_es = 'Las crisis sin causa aparente agotan a cualquiera. No te desgastes: usa el Análisis del llanto y descubre el mensaje oculto en su voz.', title_fr = 'Pourquoi pleure-t-il encore ? 😭', body_fr = 'Les crises dont on ne trouve pas la cause épuisent. Ne vous fatiguez pas : utilisez l''Analyse des pleurs et découvrez le message caché dans sa voix.', title_hi = 'फिर क्यों रो रहा है? 😭', body_hi = 'जिन रोने के दौरों की वजह न मिले, वे थका देते हैं। खुद को मत थकाइए, क्राइंग एनालिसिस का इस्तेमाल कीजिए और उसकी आवाज़ में छिपा संदेश जानिए।', title_id = 'Kenapa menangis lagi? 😭', body_id = 'Tangisan yang tak diketahui sebabnya sungguh melelahkan. Jangan memaksakan diri, gunakan Analisis Tangisan dan temukan pesan tersembunyi dalam suaranya.', title_ja = 'どうしてまた泣いてるの？😭', body_ja = '理由のわからないぐずりは本当に疲れます。無理をしないで、「泣き声分析」を使って、泣き声に隠れたメッセージを見つけましょう。', title_ko = '왜 또 울까요? 😭', body_ko = '이유를 알 수 없는 울음은 정말 지치게 해요. 혼자 애쓰지 말고 울음 분석으로 아기 울음 속 숨은 메시지를 알아보세요.', title_nl = 'Waarom huilt hij nu weer? 😭', body_nl = 'Huilbuien zonder duidelijke oorzaak putten je uit. Maak jezelf niet moe, gebruik Huilanalyse en ontdek de verborgen boodschap in het huilen.', title_pl = 'Dlaczego znowu płacze? 😭', body_pl = 'Kryzysy, których przyczyny nie umiesz znaleźć, wykańczają. Nie męcz się, skorzystaj z Analizy płaczu i odkryj ukrytą wiadomość w jego głosie.', title_pt = 'Porque está outra vez a chorar? 😭', body_pt = 'As crises sem causa aparente esgotam qualquer um. Não se canse: use a Análise do Choro e descubra a mensagem escondida no choro dele.', title_sv = 'Varför gråter barnet igen? 😭', body_sv = 'Utbrott utan synbar orsak tar på krafterna. Slit inte ut dig, använd Gråtanalys och upptäck det dolda budskapet i barnets ljud.', title_vi = 'Sao bé lại khóc nữa rồi? 😭', body_vi = 'Những cơn khóc không rõ lý do khiến mẹ kiệt sức. Đừng tự làm mình mệt, hãy dùng Phân tích tiếng khóc và khám phá thông điệp ẩn trong tiếng khóc của bé.', title_zh = '怎么又哭了？😭', body_zh = '找不到原因的哭闹最让人心力交瘁。别累坏自己，用哭声分析，发现宝宝哭声里隐藏的信息吧。' WHERE id = 'e97550d4-794b-4a9e-94da-881338077d81' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una foto que detiene el tiempo 📸', title_fr = 'La photo qui arrête le temps 📸', title_hi = 'समय को थाम लेने वाली तस्वीर 📸', title_id = 'Foto yang menghentikan waktu 📸', title_ja = '時間を止める1枚 📸', title_ko = '시간을 멈추는 한 컷 📸', title_nl = 'Een foto die de tijd stilzet 📸', title_pl = 'Kadr, który zatrzymuje czas 📸', title_pt = 'Uma foto que para o tempo 📸', title_sv = 'Bilden som stoppar tiden 📸', title_vi = 'Khoảnh khắc ngưng đọng thời gian 📸', title_zh = '定格时光 📸' WHERE id = '1b92930f-874b-4bdc-b9d4-44b2ec744469' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder de las mamás 🤖', body_es = 'Mira a tu alrededor y siéntete orgullosa de haber llegado a estos 5 meses. Si tienes algún miedo, escribe a Anacan AI y recibe apoyo.', title_fr = 'La force des mamans 🤖', body_fr = 'Regardez autour de vous et soyez fière d''être arrivée à ces 5 mois. Si vous avez des craintes, écrivez à Anacan AI et trouvez du soutien.', title_hi = 'माँओं की ताकत 🤖', body_hi = 'कमरे में नज़र डालिए और गर्व कीजिए कि आप इन 5 महीनों तक कैसे पहुँचीं। कोई डर हो तो Anacan AI को लिखिए और सहारा पाइए।', title_id = 'Kekuatan para ibu 🤖', body_id = 'Lihat sekeliling dan banggalah karena Anda sudah sampai di bulan ke-5. Kalau ada yang Anda khawatirkan, tanyakan ke Anacan AI dan dapatkan dukungan.', title_ja = 'ママの力 🤖', body_ja = 'まわりを見渡して、ここまで5か月やってきたことを誇りに思ってください。不安なことがあれば、Anacan AIに相談してサポートを受けましょう。', title_ko = '엄마의 힘 🤖', body_ko = '주위를 둘러보며 5개월까지 온 자신을 자랑스러워하세요. 걱정되는 게 있다면 Anacan AI에게 물어 도움을 받으세요.', title_nl = 'De kracht van moeders 🤖', body_nl = 'Kijk om je heen en wees trots dat je deze 5 maanden zo bent doorgekomen. Maak je je ergens zorgen over? Schrijf naar Anacan AI en krijg steun.', title_pl = 'Siła mam 🤖', body_pl = 'Rozejrzyj się i bądź dumna, że dotarłaś do 5. miesiąca. Jeśli coś cię niepokoi, napisz do Anacan AI i otrzymaj wsparcie.', title_pt = 'A força das mães 🤖', body_pt = 'Olhe à sua volta e orgulhe-se de ter chegado a estes 5 meses. Se tiver algum receio, escreva ao Anacan AI e receba apoio.', title_sv = 'Mammornas kraft 🤖', body_sv = 'Se dig omkring och var stolt över hur ni har tagit er till de här 5 månaderna. Om något oroar dig, skriv till Anacan AI och få stöd.', title_vi = 'Sức mạnh của mẹ 🤖', body_vi = 'Hãy nhìn lại và tự hào vì mẹ đã cùng bé đi đến tháng thứ 5. Nếu có điều gì khiến mẹ lo lắng, hãy hỏi Anacan AI để được hỗ trợ.', title_zh = '妈妈的力量 🤖', body_zh = '环顾四周，为你们走到5个月而自豪吧。如果有任何担心，就问问Anacan AI，获得支持。' WHERE id = '5e32b8c3-c1c2-4dbd-a394-96bbfe39e0ed' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charla en pareja 🥂', body_es = 'Esta tarde recordad juntos los primeros días y reíos un rato. ¡Habéis recorrido un largo camino!', title_fr = 'Un moment à deux 🥂', body_fr = 'Ce soir, remémorez-vous les premiers jours avec votre conjoint et riez ensemble. Vous avez déjà parcouru un sacré chemin !', title_hi = 'साथी से दिल की बात 🥂', body_hi = 'आज शाम अपने साथी के साथ शुरुआती दिनों को याद करके हँसिए। आप दोनों ने एक लंबा सफ़र तय किया है!', title_id = 'Mengobrol bersama pasangan 🥂', body_id = 'Malam ini, kenang hari-hari pertama bersama pasangan dan tertawalah bersama. Kalian sudah melewati perjalanan yang panjang!', title_ja = 'パートナーと語り合おう 🥂', body_ja = '今夜はパートナーと最初の日々を思い出して、一緒に笑いましょう。ふたりとも長い道のりを歩んできました！', title_ko = '배우자와 이야기 나누기 🥂', body_ko = '오늘 저녁 배우자와 처음 며칠을 떠올리며 함께 웃어 보세요. 정말 먼 길을 함께 걸어왔어요!', title_nl = 'Praat met je partner 🥂', body_nl = 'Haal vanavond samen met je partner herinneringen op aan de eerste dagen en lach erom. Jullie hebben al een lange weg afgelegd!', title_pl = 'Porozmawiaj z partnerem 🥂', body_pl = 'Dziś wieczorem powspominaj z partnerem pierwsze dni i pośmiejcie się razem. Przeszliście długą drogę!', title_pt = 'Converse com o seu companheiro 🥂', body_pt = 'Esta noite, recorde os primeiros dias com o seu companheiro e riam-se juntos. Já fizeram um longo caminho!', title_sv = 'Prata med din partner 🥂', body_sv = 'I kväll, minns de första dagarna och skratta tillsammans med din partner. Ni har kommit en lång väg!', title_vi = 'Tâm sự cùng bố 🥂', body_vi = 'Tối nay, hãy cùng bố nhớ lại những ngày đầu và cười thật vui. Bố mẹ đã cùng nhau đi một chặng đường dài!', title_zh = '和伴侣聊聊 🥂', body_zh = '今晚和伴侣一起回忆最初的日子，笑一笑吧。你们已经走过了很长一段路！' WHERE id = 'af763c83-7a14-4218-b3c2-49cdc7255b18' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Echa la vista atrás a todos tus registros y gráficas de desarrollo. ¡Mira cuánto ha crecido tu peque y lo experta que te has vuelto tú!', body_fr = 'Retournez-vous sur toutes vos notes et vos courbes de croissance. Voyez comme il a grandi, et comme vous êtes devenue une pro !', body_hi = 'अपने सभी नोट्स और विकास चार्ट पर पीछे मुड़कर नज़र डालिए। देखिए वह कितना बड़ा हो गया है और आप कितनी माहिर बन गई हैं!', body_id = 'Lihat kembali semua catatan dan grafik perkembangan Anda. Lihat betapa ia sudah tumbuh, dan betapa mahirnya Anda sekarang!', body_ja = 'これまでの記録や成長グラフを振り返ってみましょう。赤ちゃんがどれほど大きくなったか、そしてあなたがどれほど頼もしくなったかがわかります！', body_ko = '그동안의 모든 기록과 성장 그래프를 돌아보세요. 아기가 얼마나 컸는지, 엄마는 얼마나 능숙해졌는지 보일 거예요!', body_nl = 'Kijk terug naar al je notities en groeicurves. Zie hoeveel je baby gegroeid is en hoe jij een echte prof bent geworden!', body_pl = 'Spójrz wstecz na wszystkie swoje zapiski i wykresy rozwoju. Zobacz, jak bardzo urósł maluszek, a ty stałaś się prawdziwą profesjonalistką!', body_pt = 'Olhe para trás, para todos os seus registos e gráficos de desenvolvimento. Veja o quanto ele cresceu e como a mãe se tornou uma profissional!', body_sv = 'Blicka tillbaka på alla dina anteckningar och utvecklingskurvor. Se hur mycket barnet har vuxit och hur proffsig du har blivit!', body_vi = 'Hãy nhìn lại tất cả ghi chép và biểu đồ phát triển. Xem bé đã lớn thế nào, còn mẹ đã trở nên chuyên nghiệp ra sao!', body_zh = '回头看看你所有的记录和成长曲线。看看宝宝长大了多少，你又变得多么专业！' WHERE id = '8b9fb477-8954-40e0-aa32-b586b125f806' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una noche de victoria 🪄', body_es = 'Esta noche pon en Cuentos inteligentes una historia llena de amor y celebrad vuestra victoria en pareja, como el gran equipo que sois.', title_fr = 'Une soirée de victoire 🪄', body_fr = 'Ce soir, dans les Contes intelligents, faites simplement écouter une histoire pleine d''amour et célébrez votre victoire en équipe avec votre conjoint !', title_hi = 'जीत की शाम 🪄', body_hi = 'आज शाम स्मार्ट कहानियों में बस एक प्यार भरी कहानी चलाइए और अपने साथी के साथ एक टीम के रूप में अपनी जीत का जश्न मनाइए!', title_id = 'Malam kemenangan 🪄', body_id = 'Malam ini, bacakan kisah penuh cinta dari Dongeng Pintar dan rayakan kemenangan kalian sebagai satu tim bersama pasangan!', title_ja = '勝利の夜 🪄', body_ja = '今夜は「スマートおはなし」で愛情いっぱいのお話を流して、パートナーとチームとしての勝利をお祝いしましょう！', title_ko = '승리의 저녁 🪄', body_ko = '오늘 저녁 스마트 동화에서 사랑 가득한 이야기를 들려주고 배우자와 한 팀으로서 이룬 승리를 축하하세요!', title_nl = 'Een feestelijke avond 🪄', body_nl = 'Laat vanavond in Slimme sprookjes een verhaal vol liefde voorlezen en vier samen met je partner jullie overwinning als team!', title_pl = 'Wieczór zwycięstwa 🪄', body_pl = 'Dziś wieczorem po prostu odtwórz w Mądrych bajkach historię pełną miłości i świętuj z partnerem wasze zwycięstwo jako drużyna!', title_pt = 'Uma noite de vitória 🪄', body_pt = 'Esta noite, ponha a tocar nas Histórias Inteligentes uma história cheia de amor e celebre a vitória com o seu companheiro, como uma equipa!', title_sv = 'Segerkväll 🪄', body_sv = 'I kväll, läs upp en saga full av kärlek i Smarta sagor och fira er seger som ett lag tillsammans med din partner!', title_vi = 'Buổi tối chiến thắng 🪄', body_vi = 'Tối nay, hãy phát một câu chuyện tràn đầy yêu thương trong Truyện cổ tích thông minh và cùng bố ăn mừng chiến thắng của cả đội!', title_zh = '胜利之夜 🪄', body_zh = '今晚在智能故事里播放一个充满爱的故事，和伴侣一起作为团队庆祝你们的胜利吧！' WHERE id = 'bd07ae62-d716-4470-a226-d2dc1c918f7c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El desorden de casa no se va a ir a ninguna parte. No te pongas a trabajar en cuanto se duerma. Sírvete un café calentito y pasa 10 minutos simplemente mirando la pared.', body_fr = 'Le désordre de la maison ne va pas s''envoler. Ne vous lancez pas dans le ménage dès qu''il s''endort. Servez-vous un café chaud et regardez simplement le mur pendant 10 minutes.', body_hi = 'घर का बिखराव कहीं नहीं भागेगा। उसके सोते ही काम में मत जुट जाइए। अपने लिए गरम कॉफ़ी डालिए और 10 मिनट बस दीवार को देखिए।', body_id = 'Rumah yang berantakan tidak akan ke mana-mana. Jangan langsung bekerja saat ia tidur. Tuang secangkir kopi hangat dan pandangi dinding saja selama 10 menit.', body_ja = '家の散らかりはどこにも逃げません。赤ちゃんが寝たらすぐに家事に取りかからないで。温かいコーヒーをいれて、10分間ただ壁を眺めてみましょう。', body_ko = '어질러진 집은 어디 가지 않아요. 아기가 자는 동안 바로 일을 시작하지 마세요. 따뜻한 커피 한 잔을 따르고 10분 동안 그냥 벽을 바라보세요.', body_nl = 'De rommel in huis loopt niet weg. Ga niet meteen aan de slag als je baby slaapt. Schenk een warme kop koffie in en staar 10 minuten gewoon naar de muur.', body_pl = 'Bałagan w domu nigdzie nie ucieknie. Gdy maluszek śpi, nie rzucaj się od razu do pracy. Nalej sobie ciepłej kawy i przez 10 minut po prostu popatrz w ścianę.', body_pt = 'A desarrumação da casa não vai fugir. Não se atire ao trabalho mal ele adormeça. Sirva-se de um café quente e passe 10 minutos simplesmente a olhar para a parede.', body_sv = 'Stöket hemma springer ingenstans. Kasta dig inte över sysslorna så fort barnet somnar. Häll upp en varm kopp kaffe och stirra bara in i väggen i 10 minuter.', body_vi = 'Việc nhà bừa bộn cũng chẳng chạy đi đâu. Đừng lao vào làm việc ngay khi bé ngủ. Hãy rót cho mình một tách cà phê nóng và chỉ ngồi ngắm bức tường trong 10 phút.', body_zh = '家里乱也跑不了。宝宝一睡着别急着干活。给自己倒杯热咖啡，就这么对着墙发呆10分钟吧。' WHERE id = '2668e59c-6b79-42c7-903c-24806c9559de' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'De una mano a otra 🧸', body_es = '¿Ya se pasa un juguete de una mano a la otra? ¡Es la prueba de que sus hemisferios cerebrales funcionan genial! Registra esta gran habilidad en el Seguimiento del desarrollo.', title_fr = 'D''une main à l''autre 🧸', body_fr = 'Il arrive à passer un jouet d''une main à l''autre ? C''est la preuve que les deux hémisphères de son cerveau fonctionnent très bien ! Notez cette grande compétence dans le Suivi de développement.', title_hi = 'एक हाथ से दूसरे हाथ तक 🧸', body_hi = 'क्या वह खिलौना एक हाथ से दूसरे हाथ में ले जा सकता है? यह इस बात का सबूत है कि उसके दिमाग के दोनों हिस्से बढ़िया काम कर रहे हैं! ग्रोथ ट्रैकर में इस बड़े हुनर को दर्ज कीजिए।', title_id = 'Dari tangan ke tangan 🧸', body_id = 'Ia bisa memindahkan mainan dari satu tangan ke tangan lain? Ini bukti kedua belahan otaknya bekerja dengan baik! Catat keterampilan besar ini di Pelacak Perkembangan.', title_ja = '手から手へ探検 🧸', body_ja = 'おもちゃを片方の手からもう片方の手へ持ちかえられますか？左右の脳がしっかり働いている証拠です！「発達トラッカー」にこの大きなできたを記録しましょう。', title_ko = '이 손에서 저 손으로 🧸', body_ko = '장난감을 한 손에서 다른 손으로 옮길 수 있나요? 좌뇌와 우뇌가 잘 협력하고 있다는 증거예요! 성장 기록에 이 큰 능력을 남겨 두세요.', title_nl = 'Van hand tot hand 🧸', body_nl = 'Kan je baby een speeltje van de ene naar de andere hand doorgeven? Dat bewijst dat beide hersenhelften goed samenwerken! Noteer deze grote vaardigheid in de Groeitracker.', title_pl = 'Z rączki do rączki 🧸', body_pl = 'Potrafi przełożyć zabawkę z jednej rączki do drugiej? To dowód, że półkule mózgu świetnie współpracują! Zapisz tę wielką umiejętność w Śledzeniu rozwoju.', title_pt = 'Descobertas de mão em mão 🧸', body_pt = 'Já consegue passar um brinquedo de uma mão para a outra? É a prova de que os hemisférios do cérebro funcionam muito bem! Assinale esta grande conquista no Registo de Desenvolvimento.', title_sv = 'Från hand till hand 🧸', body_sv = 'Kan barnet flytta en leksak från ena handen till den andra? Det är ett bevis på att hjärnhalvorna samarbetar utmärkt! Anteckna den här stora färdigheten i Utvecklingsspåraren.', title_vi = 'Chuyền tay khám phá 🧸', body_vi = 'Bé đã chuyền được đồ chơi từ tay này sang tay kia? Đây là bằng chứng hai bán cầu não của bé đang hoạt động rất tốt! Hãy ghi lại kỹ năng quan trọng này trong Theo dõi phát triển.', title_zh = '左右手传递 🧸', body_zh = '宝宝能把玩具从一只手换到另一只手了？这说明左右脑配合得很好！在发育追踪里记下这项重要技能吧。' WHERE id = '99274040-6797-4a0d-b6f8-4369e3e3436d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Comparte cómo te sientes 📝', body_es = '¿Hoy estás muy cansada o llena de energía? Escribe tus emociones con sinceridad en el Diario de ánimo. Desahogarte te sentará bien.', title_fr = 'Partagez votre humeur 📝', body_fr = 'Aujourd''hui, vous êtes épuisée ou pleine d''énergie ? Écrivez sincèrement vos émotions dans le Journal d''humeur. Vider votre cœur vous fera du bien.', title_hi = 'अपना मूड बाँटिए 📝', body_hi = 'आज बहुत थक गई हैं या ऊर्जा से भरी हैं? मूड डायरी में अपनी भावनाएँ सच्चे मन से लिखिए। मन हल्का करना आपके लिए अच्छा रहेगा।', title_id = 'Bagikan suasana hati Anda 📝', body_id = 'Hari ini sangat lelah atau justru penuh energi? Tuliskan perasaan Anda dengan jujur di Buku Harian Suasana Hati. Meluapkan isi hati akan membuat Anda lebih lega.', title_ja = '気持ちをシェアしよう 📝', body_ja = '今日はとても疲れていますか？それとも元気いっぱい？「気分日記」に気持ちを正直に書いてみましょう。吐き出すと心が軽くなります。', title_ko = '기분을 나눠 주세요 📝', body_ko = '오늘은 많이 지쳤나요, 아니면 기운이 넘치나요? 기분 일기에 감정을 솔직하게 적어 보세요. 마음을 털어놓으면 한결 나아질 거예요.', title_nl = 'Deel je gevoel 📝', body_nl = 'Ben je vandaag erg moe of juist vol energie? Schrijf je gevoelens eerlijk op in je Stemmingsdagboek. Je hart luchten doet je goed.', title_pl = 'Podziel się nastrojem 📝', body_pl = 'Jesteś dziś bardzo zmęczona czy pełna energii? Szczerze zapisz swoje emocje w Dzienniku nastroju. Wyrzucenie ich z siebie dobrze ci zrobi.', title_pt = 'Partilhe o seu estado de espírito 📝', body_pt = 'Hoje está muito cansada ou cheia de energia? Escreva com sinceridade as suas emoções no Diário de Humor. Desabafar vai fazer-lhe bem.', title_sv = 'Dela ditt humör 📝', body_sv = 'Är du väldigt trött i dag, eller full av energi? Skriv ärligt ner dina känslor i Humördagboken. Att lätta på hjärtat gör dig gott.', title_vi = 'Chia sẻ tâm trạng 📝', body_vi = 'Hôm nay mẹ thấy rất mệt hay tràn đầy năng lượng? Hãy viết cảm xúc thật lòng vào Nhật ký tâm trạng. Trút bầu tâm sự sẽ giúp mẹ nhẹ lòng hơn.', title_zh = '分享你的心情 📝', body_zh = '今天你是累坏了，还是精力充沛？在心情日记里真诚地写下感受。把心里话说出来会让你好受很多。' WHERE id = 'cbbe11e5-f7e4-422b-8d0e-cf2a181684c8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuentos con voz 🪄', body_es = 'Esta noche demos a la habitación una magia distinta. Crea en Cuentos inteligentes la historia de un gato valiente que vuela a la luna y haz divertida la rutina de dormir.', title_fr = 'Des histoires à écouter 🪄', body_fr = 'Ce soir, apportons une magie différente dans la chambre. Créez dans les Contes intelligents l''histoire d''un chat courageux qui s''envole vers la Lune et rendez la routine du coucher amusante.', title_hi = 'सुनने वाली कहानियाँ 🪄', body_hi = 'आज शाम कमरे में एक अलग जादू भरते हैं। स्मार्ट कहानियों में चाँद तक उड़ने वाली बहादुर बिल्ली की कहानी बनाकर सोने के रूटीन को मज़ेदार बनाइए।', title_id = 'Dongeng bersuara 🪄', body_id = 'Mari hadirkan keajaiban berbeda di kamar malam ini. Buat kisah kucing pemberani yang terbang ke bulan di Dongeng Pintar dan jadikan rutinitas tidur lebih seru.', title_ja = '音で楽しむお話 🪄', body_ja = '今夜は部屋にいつもと違う魔法をかけましょう。「スマートおはなし」で月へ飛んでいく勇敢なネコのお話をつくって、寝る前のルーティンを楽しくしましょう。', title_ko = '소리로 듣는 동화 🪄', body_ko = '오늘 저녁 방에 색다른 마법을 더해 봐요. 스마트 동화에서 달로 날아가는 용감한 고양이 이야기를 만들어 잠자리 루틴을 즐겁게 해 주세요.', title_nl = 'Voorleesverhalen 🪄', body_nl = 'Laten we vanavond een andere magie in de kamer brengen. Maak in Slimme sprookjes het verhaal van een dappere kat die naar de maan vliegt en maak de slaaproutine leuk.', title_pl = 'Bajki do słuchania 🪄', body_pl = 'Dodajmy dziś wieczorem do pokoju trochę innej magii. Stwórz w Mądrych bajkach historię o odważnym kocie lecącym na Księżyc i niech usypianie będzie zabawą.', title_pt = 'Histórias em áudio 🪄', body_pt = 'Esta noite, vamos trazer uma magia diferente para o quarto. Crie nas Histórias Inteligentes a história de um gato corajoso que voa até à Lua e torne a rotina de sono divertida.', title_sv = 'Ljudsagor 🪄', body_sv = 'Låt oss ge rummet en annan sorts magi i kväll. Gör sömnrutinen rolig genom att skapa sagan om den modiga katten som flyger till månen i Smarta sagor.', title_vi = 'Truyện kể bằng giọng nói 🪄', body_vi = 'Tối nay mình thêm chút phép màu khác vào căn phòng nhé. Tạo câu chuyện chú mèo dũng cảm bay lên Mặt Trăng trong Truyện cổ tích thông minh để giờ đi ngủ thêm vui.', title_zh = '有声故事 🪄', body_zh = '今晚给房间添一点不一样的魔法。在智能故事里创作一个勇敢小猫飞上月亮的故事，让睡前作息变得有趣。' WHERE id = '503f1c6e-f32e-42d4-96c5-cf663fbb57cd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calmante natural ⛅', body_es = '¿Está muy inquieto y no quiere estar en casa? Mira Tiempo y ropa y salid enseguida al parque. El aire fresco es la mejor medicina para los dos.', title_fr = 'Un calmant naturel ⛅', body_fr = 'Il est très agité et ne veut pas rester à la maison ? Consultez Météo et tenue et filez au parc. L''air frais est le meilleur remède pour vous deux.', title_hi = 'प्राकृतिक सुकून ⛅', body_hi = 'बहुत बेचैन है और घर में रहना नहीं चाहता? मौसम और कपड़े देखिए और तुरंत पार्क चलिए। ताज़ी हवा आप दोनों के लिए सबसे अच्छी दवा है।', title_id = 'Penenang alami ⛅', body_id = 'Ia sangat rewel dan tidak betah di rumah? Cek Cuaca dan Pakaian, lalu segera pergi ke taman. Udara segar adalah obat terbaik untuk kalian berdua.', title_ja = '自然のやすらぎ ⛅', body_ja = 'ぐずぐずして、家にいたがらない？「天気と服装」をチェックして、すぐに公園へ出かけましょう。新鮮な空気は2人にとっていちばんの薬です。', title_ko = '자연의 진정제 ⛅', body_ko = '많이 보채고 집에 있기 싫어하나요? 날씨와 옷차림을 확인하고 바로 공원으로 나가세요. 신선한 공기가 두 사람 모두에게 최고의 약이에요.', title_nl = 'Een natuurlijk kalmeermiddel ⛅', body_nl = 'Is je baby erg onrustig en wil hij niet binnen blijven? Kijk in Weer en kleding en ga meteen naar het park. Frisse lucht is het beste medicijn voor jullie allebei.', title_pl = 'Naturalne ukojenie ⛅', body_pl = 'Jest bardzo niespokojny i nie chce siedzieć w domu? Sprawdź Pogodę i ubiór i od razu idźcie do parku. Świeże powietrze to najlepsze lekarstwo dla was obojga.', title_pt = 'Um calmante natural ⛅', body_pt = 'Está muito inquieto e não quer ficar em casa? Veja o Tempo e Roupa e vá já para o parque. O ar puro é o melhor remédio para os dois.', title_sv = 'Naturligt lugn ⛅', body_sv = 'Väldigt oroligt och vill inte vara inne? Kolla Väder och kläder och gå direkt till parken. Frisk luft är den bästa medicinen för er båda.', title_vi = 'Liều xoa dịu tự nhiên ⛅', body_vi = 'Bé quấy khóc nhiều và không muốn ở trong nhà? Xem Thời tiết và trang phục rồi ra công viên ngay. Không khí trong lành là liều thuốc tốt nhất cho cả hai mẹ con.', title_zh = '天然安抚剂 ⛅', body_zh = '宝宝特别烦躁，不想待在家里？查看天气穿衣，马上去公园吧。新鲜空气是你们俩最好的良药。' WHERE id = 'b7efef49-9c1d-49fe-9e2d-4889969cd685' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Todo lo que pilla se lo lleva a la boca? 🤤', body_es = 'Es su manera de conocer el mundo. Solo asegúrate de que los objetos a su alrededor estén limpios y sean seguros.', title_fr = 'Il porte à la bouche tout ce qu''il attrape ? 🤤', body_fr = 'C''est sa façon de découvrir le monde. Veillez simplement à ce que les objets autour de lui soient propres et sans danger.', title_hi = 'हाथ में आई हर चीज़ मुँह में? 🤤', body_hi = 'यह उसका दुनिया को जानने का तरीका है। बस ध्यान रखिए कि आसपास की चीज़ें साफ़ और सुरक्षित हों।', title_id = 'Semua yang dipegang pasti masuk mulut? 🤤', body_id = 'Inilah caranya mengenal dunia. Cukup pastikan benda-benda di sekitarnya bersih dan aman.', title_ja = '手にしたものはなんでもお口へ？🤤', body_ja = 'これは世界を知るための方法です。まわりのものが清潔で安全かどうかだけ気をつけてあげましょう。', title_ko = '손에 잡히는 건 다 입으로 가져가나요? 🤤', body_ko = '세상을 알아 가는 아기만의 방법이에요. 주변 물건이 깨끗하고 안전한지만 신경 써 주세요.', title_nl = 'Gaat alles wat je baby pakt meteen de mond in? 🤤', body_nl = 'Zo leert je kleintje de wereld kennen. Let er gewoon op dat alles in de buurt schoon en veilig is.', title_pl = 'Wszystko, co złapie, ląduje w buzi? 🤤', body_pl = 'To jego sposób na poznawanie świata. Dbaj tylko o to, by przedmioty wokół niego były czyste i bezpieczne.', title_pt = 'Leva à boca tudo o que lhe vem parar às mãos? 🤤', body_pt = 'É a forma que ele tem de conhecer o mundo. Basta ter atenção para que os objetos à volta estejam limpos e sejam seguros.', title_sv = 'Hamnar allt barnet får tag i i munnen? 🤤', body_sv = 'Det är barnets sätt att lära känna världen. Se bara till att sakerna runt omkring är rena och säkra.', title_vi = 'Cầm được gì là bé cho ngay vào miệng? 🤤', body_vi = 'Đây là cách bé tìm hiểu thế giới. Mẹ chỉ cần chú ý giữ cho đồ vật xung quanh bé sạch sẽ và an toàn.', title_zh = '拿到什么都往嘴里放？🤤', body_zh = '这是宝宝认识世界的方式。只要确保身边的东西干净又安全就好。' WHERE id = 'fa1bb3e3-66d0-4cc7-8d63-61478e045e39' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cascada de babas 🤤', body_es = '¿Se le moja el cuello de la ropa a menudo? Prepara los mordedores de silicona.', title_fr = 'Une cascade de bave 🤤', body_fr = 'Son col est souvent mouillé ? Préparez des anneaux de dentition en silicone.', title_hi = 'लार का झरना 🤤', body_hi = 'उसका कॉलर बार-बार गीला होने लगा है? सिलिकॉन टीदर तैयार रखिए।', title_id = 'Air liur bak air terjun 🤤', body_id = 'Kerah bajunya sering basah? Siapkan teether silikon.', title_ja = 'よだれの滝 🤤', body_ja = 'えりがよくぬれるようになりましたか？シリコン製の歯固めを用意しましょう。', title_ko = '침이 폭포처럼 🤤', body_ko = '옷깃이 자주 젖기 시작했나요? 실리콘 치발기를 준비해 두세요.', title_nl = 'Een waterval van kwijl 🤤', body_nl = 'Is het kraagje vaak nat? Leg siliconen bijtringen klaar.', title_pl = 'Wodospad śliny 🤤', body_pl = 'Ubranko pod szyją często jest mokre? Przygotuj silikonowe gryzaki.', title_pt = 'Uma cascata de baba 🤤', body_pt = 'A gola anda sempre molhada? Prepare os mordedores de silicone.', title_sv = 'Dregelvattenfall 🤤', body_sv = 'Blir kragen ofta blöt? Ta fram bitringar i silikon.', title_vi = 'Thác nước dãi 🤤', body_vi = 'Cổ áo bé hay bị ướt? Hãy chuẩn bị sẵn gặm nướu silicone nhé.', title_zh = '口水瀑布 🤤', body_zh = '衣领经常湿湿的？准备好硅胶牙胶吧。' WHERE id = 'e3aafd70-c5f0-4254-ba79-e24f4dca3567' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El código del llanto 😭', body_es = '¿Los lloriqueos de la mañana son por hambre o por los dientes? No adivines: usa el Análisis del llanto y descubre enseguida lo que necesita.', title_fr = 'Le code des pleurs 😭', body_fr = 'Ses pleurnicheries du matin viennent de la faim ou des dents ? Ne devinez pas : faites écouter sa voix à l''Analyse des pleurs et trouvez tout de suite son besoin.', title_hi = 'रोने का कोड 😭', body_hi = 'सुबह की कुनमुनाहट भूख से है या दाँत निकलने से? अंदाज़ा मत लगाइए, क्राइंग एनालिसिस से उसकी आवाज़ सुनवाइए और तुरंत उसकी ज़रूरत जानिए।', title_id = 'Kode tangisan 😭', body_id = 'Rengekan pagi karena lapar atau tumbuh gigi? Jangan menebak, perdengarkan tangisannya ke Analisis Tangisan dan langsung ketahui kebutuhannya.', title_ja = '泣き声の暗号 😭', body_ja = '朝のぐずぐずは、お腹がすいたから？それとも歯が生えてくるから？推測しないで、「泣き声分析」に泣き声を聞かせて、すぐに必要なことを見つけましょう。', title_ko = '울음 암호 😭', body_ko = '아침에 칭얼대는 건 배고파서일까요, 이가 나서일까요? 추측하지 말고 울음 분석으로 소리를 들려주어 필요한 것을 바로 찾아보세요.', title_nl = 'De huilcode 😭', body_nl = 'Komt het ochtendgejammer door honger of door doorkomende tandjes? Raad niet, laat Huilanalyse luisteren en ontdek meteen wat je baby nodig heeft.', title_pl = 'Kod płaczu 😭', body_pl = 'Poranne marudzenie to z głodu czy przez ząbkowanie? Nie zgaduj, pozwól Analizie płaczu posłuchać dźwięku i od razu poznaj jego potrzebę.', title_pt = 'O código do choro 😭', body_pt = 'As queixinhas da manhã são de fome ou dos dentes? Não adivinhe: ponha a Análise do Choro a ouvir e descubra logo o que ele precisa.', title_sv = 'Gråtkoden 😭', body_sv = 'Beror morgongnället på hunger eller tänder? Gissa inte, låt Gråtanalys lyssna på ljudet och hitta behovet direkt.', title_vi = 'Giải mã tiếng khóc 😭', body_vi = 'Bé rên rỉ buổi sáng vì đói hay vì mọc răng? Đừng đoán, hãy cho Phân tích tiếng khóc nghe để biết ngay bé cần gì.', title_zh = '哭声密码 😭', body_zh = '早上的哼唧是饿了，还是在长牙？别猜了，用哭声分析听一听，马上找到宝宝的需求。' WHERE id = 'dcb350dc-49ff-4c0f-b6e7-e4777138873a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se te acaba la paciencia? 👨‍👧', body_es = 'Deja que esta noche papá se encargue por completo del peque, y tú ponte los auriculares y descansa.', title_fr = 'À bout de patience ? 👨‍👧', body_fr = 'Ce soir, laissez papa s''occuper entièrement de bébé, et vous, mettez vos écouteurs et reposez-vous.', title_hi = 'धैर्य खत्म हो रहा है? 👨‍👧', body_hi = 'आज शाम बच्चे को पूरी तरह पापा संभालें, और आप हेडफ़ोन लगाकर आराम कीजिए।', title_id = 'Kesabaran mulai habis? 👨‍👧', body_id = 'Malam ini, biar ayah yang sepenuhnya mengurus si kecil, sementara Anda memasang headphone dan beristirahat.', title_ja = 'イライラしていますか？👨‍👧', body_ja = '今夜は赤ちゃんのことはすべてパパにまかせて、あなたはヘッドホンをつけてのんびりしましょう。', title_ko = '인내심이 바닥났나요? 👨‍👧', body_ko = '오늘 저녁은 아이를 온전히 아빠에게 맡기고, 엄마는 이어폰을 끼고 쉬세요.', title_nl = 'Raakt je geduld op?  👨‍👧', body_nl = 'Laat papa vanavond helemaal voor de baby zorgen, en jij zet je koptelefoon op en rust uit.', title_pl = 'Kończy ci się cierpliwość? 👨‍👧', body_pl = 'Niech dziś wieczorem maluszkiem zajmie się w całości tata, a ty załóż słuchawki i odpocznij.', title_pt = 'Está a perder a paciência?  👨‍👧', body_pt = 'Esta noite, deixe o pai tratar do bebé por completo e ponha os auscultadores para descansar.', title_sv = 'Har tålamodet tagit slut?  👨‍👧', body_sv = 'Låt pappa ta hand om barnet helt och hållet i kväll, medan du sätter på hörlurarna och vilar.', title_vi = 'Mẹ hết kiên nhẫn rồi?  👨‍👧', body_vi = 'Tối nay hãy để bố lo hết cho bé, còn mẹ đeo tai nghe vào và nghỉ ngơi.', title_zh = '快没耐心了？👨‍👧', body_zh = '今晚就让爸爸全权照顾宝宝，你戴上耳机好好休息吧。' WHERE id = 'e9e20fa8-2ecc-4e20-8e3b-90ed8d74e1e4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Somos un equipo! 🌟', body_es = '¿Te sientes sola e incomprendida? Respira hondo. Eres la heroína más fuerte de estos días tormentosos y lo estás haciendo de maravilla.', title_fr = 'Nous sommes une équipe ! 🌟', body_fr = 'Vous vous sentez seule et incomprise ? Respirez profondément. Vous êtes la plus forte héroïne de ces journées agitées et vous vous en sortez parfaitement.', title_hi = 'हम एक टीम हैं! 🌟', body_hi = 'अकेली और अनसमझी महसूस कर रही हैं? गहरी साँस लीजिए। आप इन तूफ़ानी दिनों की सबसे मज़बूत हीरो हैं और बहुत बढ़िया काम कर रही हैं।', title_id = 'Kita satu tim! 🌟', body_id = 'Merasa sendirian dan tidak dipahami? Tarik napas dalam-dalam. Anda adalah pahlawan terkuat di hari-hari penuh badai ini, dan Anda melakukannya dengan sempurna.', title_ja = '私たちはチーム！🌟', body_ja = 'ひとりぼっちで、わかってもらえないと感じますか？深呼吸して。あなたはこの嵐のような日々のいちばん強いヒーローで、とてもよくやっています。', title_ko = '우리는 한 팀이에요! 🌟', body_ko = '외롭고 아무도 이해해 주지 않는 것 같나요? 깊게 숨을 쉬어 보세요. 이 폭풍 같은 날들의 가장 강한 영웅은 바로 엄마이고, 정말 잘하고 있어요.', title_nl = 'Wij zijn een team! 🌟', body_nl = 'Voel je je alleen en onbegrepen? Haal diep adem. Jij bent de sterkste heldin van deze stormachtige dagen en je doet het perfect.', title_pl = 'Jesteśmy drużyną! 🌟', body_pl = 'Czujesz się samotna i niezrozumiana? Weź głęboki oddech. Jesteś najsilniejszą bohaterką tych burzliwych dni i świetnie sobie radzisz.', title_pt = 'Somos uma equipa! 🌟', body_pt = 'Sente-se sozinha e incompreendida? Respire fundo. É a heroína mais forte destes dias tempestuosos e está a sair-se na perfeição.', title_sv = 'Vi är ett lag! 🌟', body_sv = 'Känner du dig ensam och missförstådd? Andas djupt. Du är den starkaste hjälten i de här stormiga dagarna och du gör ett perfekt jobb.', title_vi = 'Chúng mình là một đội! 🌟', body_vi = 'Mẹ thấy cô đơn và không ai hiểu mình? Hít thật sâu. Mẹ là người hùng mạnh mẽ nhất của những ngày giông bão này và mẹ đang làm rất tốt.', title_zh = '我们是一个团队！🌟', body_zh = '觉得孤单、没人理解？深呼吸。你是这段风雨日子里最坚强的英雄，而且做得非常好。' WHERE id = 'eb92cfef-308b-40f6-9214-f36986bb10ba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Le cuesta más dormirse? Comprueba los decibelios de la habitación con el Medidor de sonido. Apaga la tele y deja la habitación totalmente a oscuras.', body_fr = 'L''endormissement est devenu difficile ? Vérifiez les décibels de la pièce avec le Sonomètre. Coupez le son de la télévision et faites le noir complet dans la pièce.', body_hi = 'सोना मुश्किल हो गया है? साउंड मीटर से कमरे का डेसिबल जाँचिए। टीवी की आवाज़ बंद कीजिए और कमरे में पूरा अँधेरा कर दीजिए।', body_id = 'Ia makin sulit tertidur? Cek desibel kamar dengan Pengukur Suara. Matikan suara TV dan buat kamar benar-benar gelap.', body_ja = '寝つきが悪くなった？「サウンドメーター」で部屋の音量（デシベル）をチェックしましょう。テレビを消して、部屋を真っ暗にしましょう。', body_ko = '잠들기가 어려워졌나요? 소음 측정기로 방의 데시벨을 확인하세요. TV 소리를 끄고 방을 완전히 어둡게 해 주세요.', body_nl = 'Gaat in slaap vallen moeilijker? Controleer met de Geluidsmeter het aantal decibel in de kamer. Zet de tv uit en maak de kamer helemaal donker.', body_pl = 'Zasypianie stało się trudniejsze? Sprawdź decybele w pokoju Miernikiem dźwięku. Wycisz telewizor i całkowicie zaciemnij pokój.', body_pt = 'Adormecer ficou mais difícil? Verifique os decibéis do quarto com o Medidor de Som. Desligue o som da televisão e escureça bem o quarto.', body_sv = 'Har det blivit svårare att somna? Kolla rummets decibelnivå med Ljudmätaren. Stäng av ljudet på tv:n och gör rummet helt mörkt.', body_vi = 'Bé khó vào giấc hơn? Kiểm tra mức decibel trong phòng bằng Đo âm thanh. Tắt tiếng tivi và làm tối hẳn căn phòng.', body_zh = '入睡变难了？用噪音测量检查房间的分贝。关掉电视，让房间完全暗下来。' WHERE id = '20b556a3-1b9a-4c51-bc18-a68bea6af134' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Picor en las encías? 🦷', body_es = '¿Siempre tiene los dedos en la boca y babea mucho? Es hora de sacar los mordedores fríos.', title_fr = 'Des gencives qui démangent ? 🦷', body_fr = 'Il a toujours les doigts dans la bouche et bave beaucoup ? C''est le moment de sortir les anneaux de dentition réfrigérés.', title_hi = 'मसूड़ों में खुजली? 🦷', body_hi = 'उँगलियाँ हमेशा मुँह में हैं और बहुत लार टपक रही है? ठंडे टीदर इस्तेमाल करने का समय है।', title_id = 'Gusi gatal? 🦷', body_id = 'Jarinya terus di mulut dan air liurnya banyak? Saatnya mengeluarkan teether yang sudah didinginkan.', title_ja = '歯ぐきがむずむず？🦷', body_ja = '指がいつも口の中にあって、よだれがたくさん出ていますか？冷やした歯固めの出番です。', title_ko = '잇몸이 간지러워요? 🦷', body_ko = '손가락이 늘 입에 있고 침을 많이 흘리나요? 차갑게 한 치발기를 꺼낼 때예요.', title_nl = 'Jeukend tandvlees? 🦷', body_nl = 'Zitten de vingertjes steeds in de mond en kwijlt je baby veel? Tijd om de gekoelde bijtringen tevoorschijn te halen.', title_pl = 'Swędzące dziąsła? 🦷', body_pl = 'Paluszki ciągle w buzi i mnóstwo śliny? Czas sięgnąć po schłodzone gryzaki.', title_pt = 'Comichão nas gengivas? 🦷', body_pt = 'Tem sempre os dedos na boca e baba-se muito? É altura de usar mordedores frescos.', title_sv = 'Kliar det i gommen? 🦷', body_sv = 'Är fingrarna ständigt i munnen och dreglar barnet mycket? Dags att ta fram kylda bitringar.', title_vi = 'Ngứa nướu? 🦷', body_vi = 'Bé luôn đưa ngón tay vào miệng và chảy nhiều nước dãi? Đến lúc dùng gặm nướu đã làm mát rồi.', title_zh = '牙龈痒痒？🦷', body_zh = '手指总在嘴里，口水流个不停？是时候拿出冰过的牙胶了。' WHERE id = '5cbbbe44-8dae-45f7-8369-18aae825551b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te olvides de ti 🥑', body_es = '¿Por dar de comer a tu bebé te has quedado sin comer tú? Elige en Recetas saludables un plato con energía que se prepara en 10 minutos.', title_fr = 'Ne vous oubliez pas 🥑', body_fr = 'À force de nourrir bébé, vous en oubliez de manger ? Choisissez dans les Recettes saines un repas énergisant prêt en 10 minutes.', title_hi = 'खुद को मत भूलिए 🥑', body_hi = 'बच्चे का पेट भरते-भरते खुद भूखी रह गईं? सेहतमंद रेसिपी से 10 मिनट में बनने वाला कोई ऊर्जा भरा खाना चुनिए।', title_id = 'Jangan lupakan diri Anda 🥑', body_id = 'Sibuk memberi makan bayi sampai Anda sendiri lapar? Pilih makanan berenergi dari Resep Sehat yang siap dalam 10 menit.', title_ja = '自分のことも忘れずに 🥑', body_ja = '赤ちゃんにごはんをあげるのに夢中で、自分は食べていない？「ヘルシーレシピ」から10分でできる元気の出る食事を選びましょう。', title_ko = '나 자신을 잊지 마세요 🥑', body_ko = '아기를 먹이느라 정작 엄마는 굶었나요? 건강한 레시피에서 10분 만에 만들 수 있는 든든한 요리를 골라 보세요.', title_nl = 'Vergeet jezelf niet 🥑', body_nl = 'Vergeet je zelf te eten omdat je je baby voedt? Kies uit Gezonde recepten een energierijk gerecht dat in 10 minuten klaar is.', title_pl = 'Nie zapominaj o sobie 🥑', body_pl = 'Karmiąc maluszka, sama zostajesz głodna? Wybierz w Zdrowych przepisach energetyczny posiłek gotowy w 10 minut.', title_pt = 'Não se esqueça de si 🥑', body_pt = 'De tanto alimentar o bebé, ficou sem comer? Escolha nas Receitas Saudáveis uma refeição energética que se prepara em 10 minutos.', title_sv = 'Glöm inte dig själv 🥑', body_sv = 'Har du glömt att äta själv medan du matar barnet? Välj en energirik rätt från Hälsosamma recept som går att laga på 10 minuter.', title_vi = 'Đừng quên bản thân 🥑', body_vi = 'Mải cho bé ăn mà mẹ để mình đói? Hãy chọn một món ăn giàu năng lượng làm trong 10 phút từ Công thức lành mạnh.', title_zh = '别忘了自己 🥑', body_zh = '光顾着喂宝宝，自己饿着肚子？从健康食谱里挑一款10分钟就能做好的能量餐吧。' WHERE id = 'f00bd5bd-287a-46fb-8532-9655a797aab3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Nana de buenas noches 🎶', body_es = 'Ningún sonido calma tanto como la voz de mamá. Esta noche, simplemente abrázale contra tu pecho y cántale bajito su nana favorita.', title_fr = 'Berceuse du soir 🎶', body_fr = 'Aucun son n''apaise autant que la voix de maman. Ce soir, serrez-le simplement contre vous et chantez doucement sa berceuse préférée.', title_hi = 'रात की लोरी 🎶', body_hi = 'कोई भी आवाज़ माँ की आवाज़ जितना सुकून नहीं देती। आज शाम बस उसे सीने से लगाइए और धीरे से उसकी पसंदीदा लोरी गाइए।', title_id = 'Nina bobo malam 🎶', body_id = 'Tidak ada suara yang semenenangkan suara ibu. Malam ini, cukup dekap ia di dada dan nyanyikan pelan lagu kesukaannya.', title_ja = '夜の子守唄 🎶', body_ja = 'ママの声ほど心落ち着く音はありません。今夜はただ胸に抱きよせて、お気に入りの子守唄をそっと歌ってあげましょう。', title_ko = '밤의 자장가 🎶', body_ko = '엄마 목소리만큼 마음을 달래 주는 소리는 없어요. 오늘 저녁은 아기를 가슴에 꼭 안고 가장 좋아하는 자장가를 나지막이 불러 주세요.', title_nl = 'Een slaapliedje voor de nacht 🎶', body_nl = 'Geen geluid is zo rustgevend als mama''s stem. Houd je kleintje vanavond gewoon tegen je borst en zing zachtjes zijn lievelingsliedje.', title_pl = 'Kołysanka na noc 🎶', body_pl = 'Żaden dźwięk nie koi tak jak głos mamy. Dziś wieczorem po prostu przytul go do piersi i cichutko zaśpiewaj jego ulubioną kołysankę.', title_pt = 'Canção de embalar da noite 🎶', body_pt = 'Nenhum som acalma tanto como a voz da mãe. Esta noite, aconchegue-o ao peito e cante baixinho a canção de embalar de que ele mais gosta.', title_sv = 'Vaggvisa för natten 🎶', body_sv = 'Inget ljud lugnar så som mammas röst. I kväll, håll bara barnet tätt intill bröstet och sjung tyst den vaggvisa barnet tycker mest om.', title_vi = 'Lời ru ban đêm 🎶', body_vi = 'Không âm thanh nào xoa dịu bằng giọng mẹ. Tối nay chỉ cần ôm bé vào lòng và khẽ hát bài ru bé thích nhất.', title_zh = '晚安摇篮曲 🎶', body_zh = '没有什么声音比妈妈的声音更能安抚宝宝。今晚就把宝宝抱在怀里，轻轻唱宝宝最爱的摇篮曲吧。' WHERE id = '4d2be2fb-f7bc-4bd9-a340-7f3c456ff87c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hay juguetes por toda la habitación? 🌪️', body_es = '¿Hay juguetes por toda la habitación? No te estreses por tener la casa desordenada. Eres una madre estupenda y tu prioridad es tu bebé, no la limpieza.', title_fr = 'Des jouets partout dans la pièce ? 🌪️', body_fr = 'Des jouets partout dans la pièce ? Ne stressez pas parce que la maison est en désordre. Vous êtes une super maman, votre priorité, c''est votre bébé, pas le ménage.', title_hi = 'कमरे में हर जगह खिलौने? 🌪️', body_hi = 'कमरे में हर जगह खिलौने हैं? घर बिखरा है तो तनाव मत लीजिए। आप एक बेहतरीन माँ हैं, आपकी प्राथमिकता बच्चा है, सफ़ाई नहीं।', title_id = 'Mainan di setiap sudut ruangan? 🌪️', body_id = 'Mainan di setiap sudut ruangan? Jangan stres karena rumah berantakan. Anda ibu yang hebat, prioritas Anda adalah bayi, bukan kebersihan.', title_ja = '部屋中おもちゃだらけ？🌪️', body_ja = '部屋中おもちゃだらけ？家が散らかっていても気にしないで。あなたはすてきなママです。大切なのはお掃除ではなく赤ちゃんです。', title_ko = '방 안이 온통 장난감인가요? 🌪️', body_ko = '방 안이 온통 장난감인가요? 집이 어질러졌다고 스트레스받지 마세요. 당신은 훌륭한 엄마예요. 우선순위는 청소가 아니라 아기예요.', title_nl = 'Overal speelgoed in de kamer? 🌪️', body_nl = 'Overal speelgoed in de kamer? Geen stress om een rommelig huis. Je bent een geweldige mama, en je prioriteit is je baby, niet de schoonmaak.', title_pl = 'Wszędzie zabawki? 🌪️', body_pl = 'Wszędzie w pokoju zabawki? Nie stresuj się bałaganem w domu. Jesteś wspaniałą mamą, twoim priorytetem jest maluszek, a nie sprzątanie.', title_pt = 'Há brinquedos por todo o quarto? 🌪️', body_pt = 'Há brinquedos por todo o quarto? Não se stresse por a casa estar desarrumada. É uma ótima mãe: a sua prioridade é o bebé, não a limpeza.', title_sv = 'Leksaker överallt i rummet? 🌪️', body_sv = 'Leksaker överallt i rummet? Stressa inte över att det är stökigt hemma. Du är en fantastisk mamma, och det viktigaste är ditt barn, inte städningen.', title_vi = 'Đồ chơi khắp phòng? 🌪️', body_vi = 'Đồ chơi khắp phòng? Nhà bừa bộn cũng đừng căng thẳng. Mẹ là người mẹ tuyệt vời, ưu tiên của mẹ là bé chứ không phải việc dọn dẹp.', title_zh = '房间里到处是玩具？🌪️', body_zh = '房间里到处是玩具？别因为家里乱而焦虑。你是很棒的妈妈，你的首要任务是宝宝，不是打扫。' WHERE id = '57873aa1-acb0-439b-98e9-70fd8b575b47' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Estás preocupada? Entra en la Comunidad Anacan. Ver que otras mamás viven la misma falta de sueño y los mismos problemas te consolará.', body_fr = 'Vous êtes inquiète ? Rejoignez la Communauté Anacan. Voir que d''autres mamans vivent le même manque de sommeil et les mêmes difficultés vous réconfortera.', body_hi = 'चिंता हो रही है? Anacan कम्युनिटी में आइए। वहाँ माँओं को वही जागी रातें और मुश्किलें झेलते देखकर आपको तसल्ली मिलेगी।', body_id = 'Merasa cemas? Bergabunglah di Komunitas Anacan. Melihat ibu-ibu lain mengalami kurang tidur dan masalah yang sama akan menghibur Anda.', body_ja = '不安ですか？Anacanコミュニティに参加しましょう。ほかのママたちも同じ寝不足や悩みを抱えているとわかると、心がほっとします。', body_ko = '걱정되나요? Anacan 커뮤니티에 들어가 보세요. 다른 엄마들도 똑같은 잠 부족과 고민을 겪는다는 걸 알면 큰 위로가 될 거예요.', body_nl = 'Maak je je zorgen? Ga naar de Anacan Community. Zien dat andere moeders hetzelfde slaaptekort en dezelfde problemen hebben, zal je troosten.', body_pl = 'Martwisz się? Dołącz do Społeczności Anacan. Zobaczysz, że inne mamy przeżywają to samo niewyspanie i te same problemy, i poczujesz ulgę.', body_pt = 'Anda preocupada? Entre na Comunidade Anacan. Ver que outras mães vivem a mesma falta de sono e os mesmos problemas vai confortá-la.', body_sv = 'Orolig? Gå in i Anacans Community. Det tröstar att se att mammorna där har samma sömnbrist och samma problem.', body_vi = 'Mẹ đang lo lắng? Hãy vào Cộng đồng Anacan. Thấy các bà mẹ khác cũng trải qua những đêm mất ngủ và khó khăn giống mình sẽ giúp mẹ được an ủi.', body_zh = '心里不安？进入Anacan社区看看吧。看到其他妈妈也经历着同样的缺觉和烦恼，你会得到安慰。' WHERE id = 'bb854fb5-befa-49e1-bf95-4f811865fe4f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Acostumbrarse a la oscuridad 🌙', title_fr = 'S''habituer à l''obscurité 🌙', title_hi = 'अँधेरे की आदत 🌙', title_id = 'Terbiasa dengan gelap 🌙', title_ja = '暗さに慣れよう 🌙', title_ko = '어둠에 익숙해지기 🌙', title_nl = 'Wennen aan het donker 🌙', title_pl = 'Oswajanie z ciemnością 🌙', title_pt = 'Habituar-se ao escuro 🌙', title_sv = 'Vänja sig vid mörkret 🌙', title_vi = 'Làm quen với bóng tối 🌙', title_zh = '适应黑暗 🌙' WHERE id = '149c401f-2cba-4bc8-b3fb-54e3507ca6f5' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Se acaban las reservas 🛒', body_es = '¿Se han acabado los pañales o el aceite para bebé? No cargues tu cabeza con detalles: apúntalo en la Lista de la compra y que tu pareja lo compre al volver.', title_fr = 'Les réserves s''épuisent 🛒', body_fr = 'Plus de couches ou d''huile pour bébé ? Ne vous encombrez pas l''esprit avec ces détails : notez-les dans la Liste de courses pour que votre conjoint les achète en rentrant.', title_hi = 'सामान खत्म हो रहा है 🛒', body_hi = 'डायपर या बेबी ऑयल खत्म हो गया? छोटी-छोटी बातों से दिमाग मत थकाइए, शॉपिंग लिस्ट में लिखिए, आपके साथी आते समय ले आएँगे।', title_id = 'Persediaan menipis 🛒', body_id = 'Popok atau minyak bayi habis? Jangan bebani pikiran dengan hal kecil, tulis di Daftar Belanja dan biar pasangan Anda membelinya saat pulang.', title_ja = 'ストックが切れそう 🛒', body_ja = 'おむつやベビーオイルがなくなった？小さなことで頭を疲れさせないで。「買い物リスト」に書いておけば、パートナーが帰りに買ってきてくれます。', title_ko = '생필품이 떨어져 가요 🛒', body_ko = '기저귀나 베이비 오일이 떨어졌나요? 사소한 일로 머리 쓰지 말고 쇼핑 목록에 적어 두면 배우자가 오는 길에 사 올 거예요.', title_nl = 'De voorraad raakt op 🛒', body_nl = 'Luiers of babyolie op? Breek je hoofd niet over kleine dingen, zet het op je Boodschappenlijstje en laat je partner het op weg naar huis kopen.', title_pl = 'Zapasy się kończą 🛒', body_pl = 'Skończyły się pieluszki albo oliwka? Nie zaprzątaj sobie głowy drobiazgami, wpisz je na Listę zakupów, a partner kupi je po drodze.', title_pt = 'As reservas estão a acabar 🛒', body_pt = 'Acabaram as fraldas ou o óleo de bebé? Não canse a cabeça com pormenores, escreva na Lista de Compras e o seu companheiro compra-os no regresso.', title_sv = 'Förråden tar slut 🛒', body_sv = 'Har blöjorna eller babyoljan tagit slut? Belasta inte hjärnan med småsaker, skriv upp det i Inköpslistan så kan din partner köpa det på vägen hem.', title_vi = 'Đồ dùng sắp hết 🛒', body_vi = 'Hết tã hay dầu em bé rồi? Đừng bận tâm vì những việc nhỏ, cứ ghi vào Danh sách mua sắm để bố mua trên đường về.', title_zh = '存货快用完了 🛒', body_zh = '尿布还是婴儿油用完了？别为小事费脑筋，写进购物清单，让伴侣回家路上买。' WHERE id = '23720343-b8a6-4414-a95b-f2b2afa5cab1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Tienes mil preguntas sobre su desarrollo? En vez de pasar horas leyendo foros, escribe a Anacan AI y recibe una respuesta breve y científica.', body_fr = 'Mille questions sur son développement vous trottent dans la tête ? Plutôt que de lire des forums pendant des heures, écrivez à Anacan AI et obtenez une réponse courte et scientifique.', body_hi = 'दिमाग में विकास को लेकर हज़ारों सवाल हैं? घंटों फ़ोरम पढ़ने के बजाय Anacan AI को लिखिए और छोटा, वैज्ञानिक जवाब पाइए।', body_id = 'Ada ribuan pertanyaan tentang perkembangannya di kepala Anda? Daripada membaca forum berjam-jam, tanyakan ke Anacan AI dan dapatkan jawaban ilmiah yang singkat.', body_ja = '発達について頭の中が疑問でいっぱい？何時間も掲示板を読むより、Anacan AIに聞いて、短く科学的な答えを受け取りましょう。', body_ko = '성장에 관한 질문이 머릿속에 가득한가요? 몇 시간씩 커뮤니티 글을 읽는 대신 Anacan AI에게 물어 짧고 과학적인 답을 받아 보세요.', body_nl = 'Zit je hoofd vol met vragen over de ontwikkeling? Lees geen uren op forums, maar schrijf naar Anacan AI en krijg een kort, wetenschappelijk antwoord.', body_pl = 'Masz w głowie tysiące pytań o rozwój? Zamiast godzinami czytać fora, napisz do Anacan AI i dostań krótką, naukową odpowiedź.', body_pt = 'Tem mil perguntas sobre o desenvolvimento na cabeça? Em vez de passar horas a ler fóruns, escreva ao Anacan AI e receba uma resposta curta e científica.', body_sv = 'Har du tusentals frågor om utvecklingen i huvudet? I stället för att läsa forum i timmar, skriv till Anacan AI och få ett kort, vetenskapligt svar.', body_vi = 'Trong đầu có hàng nghìn câu hỏi về sự phát triển của bé? Thay vì đọc diễn đàn hàng giờ, hãy hỏi Anacan AI để nhận câu trả lời ngắn gọn, khoa học.', body_zh = '脑子里有成千上万个关于发育的问题？与其花几个小时看论坛，不如问问Anacan AI，获得简明的科学解答。' WHERE id = '77df7526-5d53-4e7e-8d03-ef3224240fd5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Para asegurarte de que tu bebé come lo suficiente y vigilar su digestión, registra cada cambio de pañal en Anacan.', body_fr = 'Pour vous assurer que bébé mange suffisamment et surveiller sa digestion, notez chaque change dans Anacan.', body_hi = 'बच्चे को पूरा पोषण मिल रहा है और पाचन ठीक है, यह जानने के लिए Anacan में हर डायपर बदलना दर्ज कीजिए।', body_id = 'Catat setiap ganti popok di Anacan untuk memastikan bayi cukup menyusu dan untuk memantau pencernaannya.', body_ja = '赤ちゃんが十分に飲めているか確かめ、消化の様子をチェックするために、おむつ替えのたびにAnacanに記録しましょう。', body_ko = '아기가 충분히 먹고 있는지 확인하고 소화 상태를 살피려면 Anacan에 기저귀 교체를 빠짐없이 기록하세요.', body_nl = 'Noteer elke luierverschoning in Anacan, zodat je zeker weet dat je baby genoeg binnenkrijgt en je de spijsvertering in de gaten houdt.', body_pl = 'Zapisuj w Anacan każdą zmianę pieluszki, by mieć pewność, że maluszek dobrze się najada, i kontrolować jego trawienie.', body_pt = 'Para ter a certeza de que o bebé se alimenta o suficiente e vigiar a digestão, registe no Anacan cada muda de fralda.', body_sv = 'Anteckna varje blöjbyte i Anacan för att vara säker på att barnet får i sig tillräckligt och för att hålla koll på matsmältningen.', body_vi = 'Để chắc chắn bé ăn đủ và theo dõi hệ tiêu hóa của bé, hãy ghi lại mỗi lần thay tã trong Anacan.', body_zh = '为了确认宝宝吃得够、消化正常，在Anacan里记录每一次换尿布吧。' WHERE id = 'ffb2dcc3-196c-4439-b233-ee14c9337ae5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fuerza de la unión 🛋️', body_es = 'Después de un día difícil, sentaos cara a cara tu pareja y tú y hablad. Apoyaros y sentiros un equipo reparte la carga a la mitad.', title_fr = 'La force de l''union 🛋️', body_fr = 'Après une journée difficile, asseyez-vous face à votre conjoint et parlez. Vous soutenir mutuellement et sentir l''esprit d''équipe allège la charge de moitié.', title_hi = 'साथ की ताकत 🛋️', body_hi = 'मुश्किल दिन के बाद अपने साथी के साथ आमने-सामने बैठकर दिल की बात कीजिए। एक-दूसरे का साथ और टीम की भावना बोझ आधा कर देती है।', title_id = 'Kekuatan kebersamaan 🛋️', body_id = 'Setelah hari yang berat, duduklah berhadapan dengan pasangan dan saling bercerita. Saling mendukung dan merasakan semangat tim membuat beban terbagi dua.', title_ja = '支え合う力 🛋️', body_ja = '大変な1日のあとは、パートナーと向き合って話しましょう。支え合い、チームだと感じることで、負担は半分になります。', title_ko = '함께하는 힘 🛋️', body_ko = '힘든 하루를 보낸 뒤 배우자와 마주 앉아 이야기를 나눠 보세요. 서로를 응원하고 한 팀임을 느끼면 짐이 절반으로 줄어요.', title_nl = 'De kracht van samen 🛋️', body_nl = 'Ga na een zware dag tegenover je partner zitten en praat je hart uit. Elkaar steunen en je een team voelen halveert de last.', title_pl = 'Siła wspólnoty 🛋️', body_pl = 'Po trudnym dniu usiądź z partnerem twarzą w twarz i porozmawiajcie. Wzajemne wsparcie i poczucie drużyny dzielą ciężar na pół.', title_pt = 'A força da união 🛋️', body_pt = 'Depois de um dia difícil, sente-se frente a frente com o seu companheiro e conversem. Apoiarem-se um ao outro e sentir o espírito de equipa divide o peso ao meio.', title_sv = 'Gemenskapens kraft 🛋️', body_sv = 'Efter en tuff dag, sätt er mittemot varandra och prata ut med din partner. Att stötta varandra och känna laganda halverar bördan.', title_vi = 'Sức mạnh của sự đồng lòng 🛋️', body_vi = 'Sau một ngày vất vả, hãy ngồi đối diện và tâm sự cùng bố. Cùng nâng đỡ nhau và cảm nhận tinh thần đồng đội sẽ giúp gánh nặng vơi đi một nửa.', title_zh = '团结的力量 🛋️', body_zh = '辛苦一天后，和伴侣面对面坐下聊聊。互相支持、感受团队精神，担子就轻了一半。' WHERE id = '297cb03f-f4bc-4fe0-aba8-dc539d62bcce' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Siéntete orgullosa de ti 👏', body_es = 'Mira atrás y recuerda el miedo que tenías las primeras semanas. ¡Y ahora mira con qué soltura lo llevas todo! ¡Eres increíble!', title_fr = 'Soyez fière de vous 👏', body_fr = 'Rappelez-vous comme vous aviez peur les premières semaines. Et maintenant, vous gérez tout comme une pro ! Vous êtes formidable !', title_hi = 'खुद पर गर्व कीजिए 👏', body_hi = 'पीछे मुड़कर याद कीजिए कि पहले हफ़्तों में आप कितनी डरी हुई थीं। और अब आप सब कुछ कितनी कुशलता से संभाल रही हैं! आप कमाल की हैं!', title_id = 'Banggalah pada diri Anda 👏', body_id = 'Ingat kembali betapa takutnya Anda di minggu-minggu pertama. Sekarang lihat betapa mahirnya Anda mengatur semuanya! Anda luar biasa!', title_ja = '自分をほめてあげて 👏', body_ja = '最初の数週間、どれほど不安だったかを思い出してみて。今ではなんでも頼もしくこなしています！あなたはすばらしい！', title_ko = '스스로를 자랑스러워하세요 👏', body_ko = '돌아보면 첫 몇 주 동안 얼마나 두려웠는지 기억나죠. 그런데 지금은 모든 걸 능숙하게 해내고 있어요! 정말 멋져요!', title_nl = 'Wees trots op jezelf 👏', body_nl = 'Denk terug aan hoe bang je was in de eerste weken. En kijk nu hoe professioneel je alles regelt! Je bent geweldig!', title_pl = 'Bądź z siebie dumna 👏', body_pl = 'Spójrz wstecz i przypomnij sobie, jak bałaś się w pierwszych tygodniach. A teraz zobacz, jak profesjonalnie wszystkim zarządzasz! Jesteś wspaniała!', title_pt = 'Orgulhe-se de si 👏', body_pt = 'Olhe para trás e lembre-se do medo que sentia nas primeiras semanas. E agora veja com que profissionalismo gere tudo! É fantástica!', title_sv = 'Var stolt över dig själv 👏', body_sv = 'Blicka tillbaka och minns hur rädd du var de första veckorna. Och se nu hur proffsigt du hanterar allt! Du är fantastisk!', title_vi = 'Hãy tự hào về mình 👏', body_vi = 'Nhìn lại, hãy nhớ những tuần đầu mẹ đã lo sợ thế nào. Còn giờ mẹ xoay xở mọi việc thật chuyên nghiệp! Mẹ thật tuyệt vời!', title_zh = '为自己骄傲 👏', body_zh = '回想一下最初几周你有多害怕。现在你把一切都处理得多么专业！你太棒了！' WHERE id = '3f28d490-5c17-44cf-b02a-a0a5ea44e564' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Quedan pocos días para descubrir sabores! 🥦', body_es = 'Prepárate para el próximo mes leyendo las primeras ideas de purés en la sección Recetas para bebés que empiezan con la alimentación complementaria.', title_fr = 'De délicieuses découvertes approchent ! 🥦', body_fr = 'Préparez le mois prochain en lisant les idées de premières purées dans la rubrique Recettes pour les bébés qui commencent la diversification.', title_hi = 'स्वादिष्ट खोजें बस करीब हैं! 🥦', body_hi = 'ऊपरी आहार शुरू करने वाले बच्चों के लिए रेसिपी सेक्शन में पहली प्यूरी के आइडिया पढ़कर अगले महीने की तैयारी कीजिए।', title_id = 'Petualangan rasa sudah dekat! 🥦', body_id = 'Bersiaplah untuk bulan depan dengan membaca ide puree pertama untuk bayi yang mulai MPASI di bagian Resep.', title_ja = 'おいしい発見はもうすぐ！🥦', body_ja = '離乳食を始める赤ちゃん向けに、「レシピ」セクションで最初のペーストのアイデアを読んで、来月の準備をしましょう。', title_ko = '맛있는 탐험이 곧 시작돼요! 🥦', body_ko = '레시피 섹션에서 이유식을 시작하는 아기를 위한 첫 퓌레 아이디어를 읽으며 다음 달을 준비해 보세요.', title_nl = 'Lekkere ontdekkingen komen eraan! 🥦', body_nl = 'Bereid je voor op de volgende maand en lees in het onderdeel Recepten de eerste ideeën voor hapjes voor baby''s die met bijvoeding beginnen.', title_pl = 'Smaczne odkrycia tuż-tuż! 🥦', body_pl = 'Przygotuj się na kolejny miesiąc: przeczytaj w sekcji Przepisy pomysły na pierwsze przeciery dla maluszków zaczynających rozszerzanie diety.', title_pt = 'Falta pouco para descobertas deliciosas! 🥦', body_pt = 'Prepare-se para o próximo mês lendo na secção Receitas as primeiras ideias de puré para bebés que começam a diversificação alimentar.', title_sv = 'Snart dags för goda upptäckter! 🥦', body_sv = 'Förbered dig inför nästa månad genom att läsa idéerna för de första puréerna i avsnittet Recept för barn som börjar med smakportioner.', title_vi = 'Sắp đến những khám phá ngon lành! 🥦', body_vi = 'Hãy chuẩn bị cho tháng tới bằng cách đọc các gợi ý món nghiền đầu tiên cho bé bắt đầu ăn dặm trong mục Công thức.', title_zh = '美味探索就要开始！🥦', body_zh = '看看食谱板块里适合开始吃辅食宝宝的第一批果泥菜泥创意，为下个月做好准备吧。' WHERE id = 'bdd2cc62-7f55-4558-bc57-531c376128b9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Giros sin ayuda 🤸‍♂️', body_es = '¿Ya se gira con facilidad de espaldas a boca abajo? Ponle sobre una alfombra amplia para que pueda mover sus músculos con libertad.', title_fr = 'Il se retourne tout seul 🤸‍♂️', body_fr = 'Il se retourne déjà facilement du dos sur le ventre ? Posez-le sur un grand tapis pour qu''il puisse bouger librement.', title_hi = 'खुद से पलटना 🤸‍♂️', body_hi = 'क्या वह अब आसानी से पीठ से पेट के बल पलट जाता है? उसे एक बड़े मैट पर रखिए ताकि वह अपनी मांसपेशियों को खुलकर हिला सके।', title_id = 'Berguling sendiri 🤸‍♂️', body_id = 'Ia sudah mudah berguling dari telentang ke tengkurap? Letakkan ia di atas alas yang luas agar ototnya bisa bergerak bebas.', title_ja = 'ひとりで寝返り 🤸‍♂️', body_ja = 'もう仰向けからうつぶせにすいすい寝返りしていますか？広いマットの上に寝かせて、自由に筋肉を動かせるようにしてあげましょう。', title_ko = '혼자서 뒤집기 🤸‍♂️', body_ko = '이제 등에서 배로 쉽게 뒤집나요? 넓은 매트 위에 눕혀 근육을 마음껏 움직일 수 있게 해 주세요.', title_nl = 'Zelf omrollen 🤸‍♂️', body_nl = 'Rolt je baby al makkelijk van rug naar buik? Leg hem op een groot kleed, zodat hij zijn spiertjes vrij kan bewegen.', title_pl = 'Samodzielne obroty 🤸‍♂️', body_pl = 'Już swobodnie przewraca się z pleców na brzuch? Połóż go na dużym dywanie, żeby mógł swobodnie ruszać mięśniami.', title_pt = 'Voltas sozinho 🤸‍♂️', body_pt = 'Já se vira facilmente de costas para a barriga? Ponha-o num tapete grande para poder mexer os músculos à vontade.', title_sv = 'Rullar på egen hand 🤸‍♂️', body_sv = 'Vänder sig barnet redan lätt från rygg till mage? Lägg det på en stor matta så att det kan röra musklerna fritt.', title_vi = 'Tự lật người 🤸‍♂️', body_vi = 'Bé đã lật từ ngửa sang sấp dễ dàng? Hãy đặt bé trên một tấm thảm rộng để bé tự do vận động cơ bắp.', title_zh = '自己翻身 🤸‍♂️', body_zh = '宝宝已经能轻松从仰躺翻到趴着了？把宝宝放在宽大的地垫上，让肌肉自由活动吧。' WHERE id = '6692c328-0a11-48ba-9a13-0443aeead27c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Crece tan rápido... Mientras duerme, captura sus rasgos dulces y tranquilos con la Sesión de fotos del bebé y guárdalos de recuerdo.', body_fr = 'Il grandit si vite... Pendant qu''il dort, photographiez ses doux traits paisibles avec la Séance photo bébé et gardez-en le souvenir.', body_hi = 'वह इतनी तेज़ी से बड़ा हो रहा है... सोते समय उसके प्यारे, शांत चेहरे को बेबी फ़ोटोशूट से कैद करके यादें सहेजिए।', body_id = 'Ia tumbuh begitu cepat... Abadikan wajahnya yang manis dan tenang saat tidur dengan Sesi Foto Bayi sebagai kenangan.', body_ja = '本当にあっという間に大きくなりますね...眠っている間のかわいくておだやかな顔を「ベビーフォトセッション」で撮って、思い出に残しましょう。', body_ko = '아기가 너무 빨리 자라요... 잠든 사이 그 사랑스럽고 평온한 얼굴을 아기 사진 촬영으로 찍어 추억으로 남기세요.', body_nl = 'Je baby groeit zo snel... Leg dat lieve, rustige slaapgezichtje vast met Babyfotoshoot en bewaar het als herinnering.', body_pl = 'Rośnie tak szybko... Uchwyć jego słodkie, spokojne rysy podczas snu w Sesji zdjęciowej dziecka i zachowaj je na pamiątkę.', body_pt = 'Cresce tão depressa... Enquanto dorme, fotografe aqueles traços doces e tranquilos com a Sessão Fotográfica do Bebé e guarde a recordação.', body_sv = 'Barnet växer så fort... Fånga de söta, lugna ansiktsdragen när det sover med Babyfotografering och spara minnet.', body_vi = 'Bé lớn nhanh quá... Khi bé ngủ, hãy dùng Chụp ảnh cho bé để lưu lại gương mặt ngọt ngào, bình yên ấy làm kỷ niệm.', body_zh = '宝宝长得太快了……趁宝宝睡着，用宝宝写真拍下那张甜美安详的小脸，留作纪念吧。' WHERE id = 'e22900db-05e9-4ef6-8e2b-3f0d3690dce5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hoy no se limpia 🛑', body_es = '¿Estás cansada? Díselo a tu pareja. Hoy no hay comida casera ni limpieza. ¡Hoy es el día de descanso y café de mamá!', title_fr = 'Pas de ménage aujourd''hui 🛑', body_fr = 'Fatiguée ? Dites-le à votre conjoint. Aujourd''hui, pas de cuisine, pas de ménage. Aujourd''hui, c''est le jour de repos et de café de maman !', title_hi = 'आज सफ़ाई की छुट्टी 🛑', body_hi = 'थक गई हैं? अपने साथी को बताइए। आज न घर का खाना, न सफ़ाई। आज माँ के आराम और कॉफ़ी का दिन है!', title_id = 'Hari ini tidak ada bersih-bersih 🛑', body_id = 'Lelah? Beri tahu pasangan Anda. Hari ini tidak ada masak, tidak ada bersih-bersih. Hari ini hari istirahat dan ngopi untuk Bunda!', title_ja = '今日はお掃除なし 🛑', body_ja = '疲れていますか？パートナーに伝えましょう。今日は手料理もお掃除もなし。今日はママの休息とコーヒーの日です！', title_ko = '오늘은 청소 금지 🛑', body_ko = '지쳤나요? 배우자에게 말하세요. 오늘은 집밥도 청소도 없어요. 오늘은 엄마가 쉬며 커피를 즐기는 날이에요!', title_nl = 'Vandaag geen schoonmaak 🛑', body_nl = 'Ben je moe? Zeg het tegen je partner. Vandaag geen kookwerk en geen schoonmaak. Vandaag is mama''s dag voor rust en koffie!', title_pl = 'Dziś bez sprzątania 🛑', body_pl = 'Jesteś zmęczona? Powiedz o tym partnerowi. Dziś bez gotowania i bez sprzątania. Dziś dzień odpoczynku i kawy dla mamy!', title_pt = 'Hoje não há limpezas 🛑', body_pt = 'Está cansada? Diga ao seu companheiro. Hoje não há comida caseira nem limpezas. Hoje é o dia de descanso e café da mãe!', title_sv = 'Ingen städning i dag 🛑', body_sv = 'Är du trött? Säg till din partner. I dag blir det ingen hemlagad mat och ingen städning. I dag är det mammas dag för vila och kaffe!', title_vi = 'Hôm nay không dọn dẹp 🛑', body_vi = 'Mẹ mệt rồi? Hãy nói với bố. Hôm nay không nấu nướng, không dọn dẹp. Hôm nay là ngày nghỉ ngơi và uống cà phê của mẹ!', title_zh = '今天不打扫 🛑', body_zh = '累了吗？告诉伴侣。今天不做饭、不打扫，今天是妈妈的休息和咖啡日！' WHERE id = 'b460ef96-b60f-4ef0-893f-50bb64397d11' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te escucha con atención y hace sonidos distintos? Está manteniendo un auténtico diálogo contigo. Responde a sus sonidos y fomenta esta comunicación.', body_fr = 'Il vous écoute attentivement et émet différents sons ? Il entame un vrai dialogue avec vous. Répondez à ses sons et encouragez cette communication.', body_hi = 'आपको ध्यान से सुनकर अलग-अलग आवाज़ें निकालता है? वह आपसे सच्ची बातचीत कर रहा है। उसकी आवाज़ों का जवाब दीजिए और इस बातचीत को बढ़ावा दीजिए।', body_id = 'Ia mendengarkan Anda dengan saksama dan mengeluarkan berbagai suara? Ia sedang benar-benar berdialog dengan Anda. Tanggapi suaranya dan dukung komunikasi ini.', body_ja = 'あなたの話をじっと聞いて、いろいろな声を出していますか？赤ちゃんはあなたと本当の会話をしています。声に応えて、このやりとりを応援してあげましょう。', body_ko = '엄마 말을 유심히 듣고 여러 소리를 내나요? 엄마와 진짜 대화를 나누는 중이에요. 아기 소리에 반응하며 이 소통을 응원해 주세요.', body_nl = 'Luistert je baby aandachtig naar je en maakt hij allerlei geluidjes? Dat is een echt gesprek. Reageer op zijn geluidjes en stimuleer deze communicatie.', body_pl = 'Uważnie cię słucha i wydaje różne dźwięki? Prowadzi z tobą prawdziwy dialog. Odpowiadaj na jego głos i wspieraj tę komunikację.', body_pt = 'Ouve-a com atenção e faz sons diferentes? Está a ter um verdadeiro diálogo consigo. Responda aos sons dele e incentive esta comunicação.', body_sv = 'Lyssnar barnet uppmärksamt på dig och gör olika ljud? Det för en riktig dialog med dig. Svara på ljuden och stötta den här kommunikationen.', body_vi = 'Bé chăm chú nghe mẹ và phát ra những âm thanh khác nhau? Bé đang thật sự trò chuyện với mẹ đấy. Hãy đáp lại và khuyến khích bé giao tiếp nhé.', body_zh = '宝宝专心听你说话，还发出各种声音？宝宝在和你真正地对话。回应宝宝的声音，鼓励这种交流吧。' WHERE id = 'f10c4519-156b-4eca-8117-28c233b11129' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Primeros intentos de sentarse 🪑', body_es = '¿Cuando le sientas con apoyo mantiene la cabeza y la espalda más rectas? Eso demuestra que sus músculos se fortalecen. Empieza con ratos cortos de sentarse con apoyo.', title_fr = 'Premiers essais pour s''asseoir 🪑', body_fr = 'Quand vous l''asseyez avec un soutien, il tient sa tête et son dos plus droits ? Cela montre que ses muscles se renforcent. Commencez de courts exercices d''assise soutenue.', title_hi = 'बैठने की पहली कोशिशें 🪑', body_hi = 'सहारा देकर बिठाने पर वह सिर और पीठ ज़्यादा सीधे रखता है? इससे पता चलता है कि मांसपेशियाँ मज़बूत हो रही हैं। सहारे के साथ बैठने का छोटा अभ्यास शुरू कीजिए।', title_id = 'Belajar duduk 🪑', body_id = 'Saat didudukkan dengan sandaran, kepala dan punggungnya lebih tegak? Ini tanda ototnya menguat. Mulailah latihan duduk bersandar dalam waktu singkat.', title_ja = 'おすわりへの第一歩 🪑', body_ja = '支えて座らせると、頭と背中をよりまっすぐ保てますか？筋肉が強くなってきた証拠です。短い時間から、支えておすわりの練習を始めましょう。', title_ko = '첫 앉기 도전 🪑', body_ko = '받쳐서 앉혔을 때 머리와 등을 더 꼿꼿이 세우나요? 근육이 튼튼해지고 있다는 뜻이에요. 짧게 받쳐 앉는 연습을 시작해 보세요.', title_nl = 'De eerste zitpogingen 🪑', body_nl = 'Houdt je baby het hoofdje en de rug rechter als je hem met steun laat zitten? Dat laat zien dat de spieren sterker worden. Begin met korte oefeningen in zitten met steun.', title_pl = 'Pierwsze próby siadania 🪑', body_pl = 'Gdy sadzasz go z podparciem, trzyma główkę i plecy prościej? To znak, że mięśnie się wzmacniają. Zacznij krótkie ćwiczenia siedzenia z podparciem.', title_pt = 'Primeiras tentativas de se sentar 🪑', body_pt = 'Quando o senta com apoio, segura a cabeça e as costas mais direitas? Isto mostra que os músculos estão a fortalecer-se. Comece pequenos treinos de sentar com apoio.', title_sv = 'De första sittförsöken 🪑', body_sv = 'Håller barnet huvudet och ryggen rakare när du sätter det med stöd? Det visar att musklerna blir starkare. Börja med korta övningar i att sitta med stöd.', title_vi = 'Những lần tập ngồi đầu tiên 🪑', body_vi = 'Khi được đỡ ngồi, bé giữ đầu và lưng thẳng hơn? Điều này cho thấy cơ bắp của bé đang cứng cáp. Hãy bắt đầu cho bé tập ngồi có hỗ trợ trong thời gian ngắn.', title_zh = '尝试坐起来 🪑', body_zh = '扶着坐时，宝宝的头和背挺得更直了？这说明肌肉变强壮了。开始做短时间的扶坐练习吧。' WHERE id = '01ae2fd5-6c02-4d2d-8691-089f2f85a502' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escapa de las cuatro paredes ☕', body_es = '¿La casa te agobia? Busca la cafetería más cercana donde se pueda entrar cómodamente con el carrito y tómate un café en otro ambiente.', title_fr = 'S''évader des quatre murs ☕', body_fr = 'Vous étouffez à la maison ? Trouvez le café le plus proche accessible en poussette et buvez un café dans un autre décor.', title_hi = 'चार दीवारों से छुट्टी ☕', body_hi = 'घर में घुटन हो रही है? सबसे नज़दीकी ऐसा कैफ़े ढूँढिए जहाँ स्ट्रॉलर के साथ आराम से जा सकें, और नए माहौल में कॉफ़ी पीजिए।', title_id = 'Kabur dari empat dinding ☕', body_id = 'Rumah terasa menyesakkan? Cari kafe terdekat yang mudah dimasuki dengan stroller dan nikmati kopi di suasana yang berbeda.', title_ja = '4つの壁から脱出 ☕', body_ja = '家にこもって息がつまりそう？ベビーカーで入りやすい近くのカフェを見つけて、いつもと違う場所でコーヒーを楽しみましょう。', title_ko = '네 벽에서 탈출 ☕', body_ko = '집이 답답하게 느껴지나요? 유모차로 편하게 들어갈 수 있는 가까운 카페를 찾아 새로운 분위기에서 커피를 마셔 보세요.', title_nl = 'Ontsnap uit je vier muren ☕', body_nl = 'Word je gek binnen? Zoek het dichtstbijzijnde café waar je makkelijk met de kinderwagen naar binnen kunt en drink je koffie eens ergens anders.', title_pl = 'Ucieczka z czterech ścian ☕', body_pl = 'Dom cię przytłacza? Znajdź najbliższą kawiarnię, do której łatwo wjechać wózkiem, i wypij kawę w innym otoczeniu.', title_pt = 'Fuga às quatro paredes ☕', body_pt = 'A casa está a sufocá-la? Encontre o café mais próximo onde se entre facilmente com o carrinho e beba um café num ambiente diferente.', title_sv = 'Fly från de fyra väggarna ☕', body_sv = 'Känns det trångt hemma? Hitta närmaste kafé dit du lätt kommer in med barnvagnen och drick kaffe i en annan miljö.', title_vi = 'Thoát khỏi bốn bức tường ☕', body_vi = 'Ở nhà mãi thấy ngột ngạt? Hãy tìm quán cà phê gần nhất có thể đẩy xe đẩy vào dễ dàng và thưởng thức cà phê ở một không gian mới.', title_zh = '逃离四面墙 ☕', body_zh = '在家闷得透不过气？找一家最近的、方便推婴儿车进去的咖啡馆，换个环境喝杯咖啡吧。' WHERE id = '3ae0359c-235f-4ea4-9a97-929da4740dc7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Si se frota los ojos y se queda con la mirada perdida, no esperes a la crisis. Oscurece la habitación ya y empieza la rutina de sueño.', body_fr = 'S''il se frotte les yeux et fixe le vide, n''attendez pas la crise. Assombrissez tout de suite la pièce et lancez la routine du coucher.', body_hi = 'अगर वह आँखें मलकर शून्य में देख रहा है, तो रोने के दौरे का इंतज़ार मत कीजिए। तुरंत कमरे में अँधेरा करके सोने का रूटीन शुरू कीजिए।', body_id = 'Kalau ia mengucek mata dan menatap kosong, jangan tunggu sampai rewel. Segera redupkan kamar dan mulai rutinitas tidur.', body_ja = '目をこすってぼーっとしていたら、ぐずりが爆発するのを待たないで。すぐに部屋を暗くして、ねんねのルーティンを始めましょう。', body_ko = '눈을 비비며 허공을 바라본다면 잠투정을 기다리지 마세요. 바로 방을 어둡게 하고 잠자리 루틴을 시작하세요.', body_nl = 'Wrijft je baby in de oogjes en staart hij in het niets? Wacht niet op een huilbui. Maak de kamer meteen donker en begin met de slaaproutine.', body_pl = 'Jeśli trze oczka i patrzy w pustkę, nie czekaj na kryzys. Od razu przyciemnij pokój i zacznij rytuał snu.', body_pt = 'Se esfrega os olhos e fica a olhar para o vazio, não espere pela crise. Escureça já o quarto e comece a rotina de sono.', body_sv = 'Gnuggar barnet ögonen och stirrar tomt ut i luften? Vänta inte på utbrottet. Gör rummet mörkt direkt och börja sömnrutinen.', body_vi = 'Nếu bé dụi mắt và nhìn vào khoảng không, đừng đợi đến lúc bé quấy. Hãy làm tối phòng ngay và bắt đầu nếp sinh hoạt trước khi ngủ.', body_zh = '如果宝宝揉着眼睛发呆，别等闹觉。马上调暗房间，开始睡前作息。' WHERE id = 'a66c05d0-980d-472a-8187-902f12cc0e87' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hambre o cansancio? 🧩', body_es = '¿Hagas lo que hagas, no se calla? Quizá solo esté muy cansado. Para salir de dudas, usa el Análisis del llanto y descubre la causa de su llanto.', title_fr = 'Faim ou fatigue ? 🧩', body_fr = 'Quoi que vous fassiez, il ne s''arrête pas de pleurer ? Il est peut-être simplement très fatigué. Pour en être sûre, utilisez l''Analyse des pleurs et découvrez la raison de ses pleurs.', title_hi = 'भूखा है या थका हुआ? 🧩', body_hi = 'कुछ भी कर लें, चुप नहीं हो रहा? शायद वह बस बहुत थक गया है। पक्का जानने के लिए क्राइंग एनालिसिस से आवाज़ के पीछे की वजह जानिए।', title_id = 'Lapar atau lelah? 🧩', body_id = 'Apa pun yang Anda lakukan, tangisnya tak berhenti? Mungkin ia hanya sangat lelah. Untuk memastikannya, gunakan Analisis Tangisan dan temukan penyebab di balik suaranya.', title_ja = 'お腹がすいた？それとも疲れた？🧩', body_ja = '何をしても泣きやまない？ただ疲れすぎているだけかもしれません。確かめるために「泣き声分析」を使って、泣き声の理由を見つけましょう。', title_ko = '배고픈 걸까요, 피곤한 걸까요? 🧩', body_ko = '무엇을 해도 울음을 그치지 않나요? 그냥 많이 피곤한 걸 수도 있어요. 확실히 알고 싶다면 울음 분석으로 울음의 이유를 알아보세요.', title_nl = 'Honger of moe? 🧩', body_nl = 'Stopt het huilen niet, wat je ook doet? Misschien is je baby gewoon heel moe. Gebruik Huilanalyse om zeker te weten wat erachter zit.', title_pl = 'Głodny czy zmęczony? 🧩', body_pl = 'Co byś nie robiła, nie przestaje płakać? Może jest po prostu bardzo zmęczony. Żeby mieć pewność, skorzystaj z Analizy płaczu i poznaj przyczynę.', title_pt = 'Fome ou cansaço? 🧩', body_pt = 'Faça o que fizer, não se cala? Talvez esteja apenas muito cansado. Para ter a certeza, use a Análise do Choro e descubra a causa por trás do choro.', title_sv = 'Hungrig eller trött? 🧩', body_sv = 'Tystnar barnet inte, vad du än gör? Det kanske bara är väldigt trött. För att vara säker, använd Gråtanalys och ta reda på orsaken bakom ljudet.', title_vi = 'Bé đói hay mệt? 🧩', body_vi = 'Làm gì bé cũng không nín? Có thể bé chỉ quá mệt. Để chắc chắn, hãy dùng Phân tích tiếng khóc và tìm ra lý do đằng sau tiếng khóc.', title_zh = '饿了还是累了？🧩', body_zh = '怎么做都不停哭？也许只是太累了。想确认的话，用哭声分析找出哭声背后的原因吧。' WHERE id = '5cacab5c-c142-4162-9118-942fa6678db3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Control del sonido 🤫', body_es = '¿Los ruidos repentinos le despiertan justo cuando se duerme? Mantén bajo control el nivel de ruido de la habitación con el Medidor de sonido.', title_fr = 'Contrôle du bruit 🤫', body_fr = 'Les bruits soudains le réveillent au moment de s''endormir ? Gardez le niveau sonore de la pièce sous contrôle avec le Sonomètre.', title_hi = 'आवाज़ पर नज़र 🤫', body_hi = 'सोते समय अचानक आवाज़ें उसे जगा देती हैं? साउंड मीटर से कमरे के शोर की सीमा पर नज़र रखिए।', title_id = 'Kontrol suara 🤫', body_id = 'Suara mendadak membangunkannya saat mulai tertidur? Jaga batas kebisingan kamar dengan Pengukur Suara.', title_ja = '音のチェック 🤫', body_ja = '寝入りばなに突然の音で起きてしまう？「サウンドメーター」で部屋の音の大きさをチェックしましょう。', title_ko = '소리 관리 🤫', body_ko = '잠들 때 갑작스러운 소리에 깨나요? 소음 측정기로 방의 소음 수준을 관리하세요.', title_nl = 'Geluidscontrole 🤫', body_nl = 'Wordt je baby bij het inslapen wakker van plotselinge geluiden? Houd met de Geluidsmeter het geluidsniveau in de kamer onder controle.', title_pl = 'Kontrola dźwięku 🤫', body_pl = 'Nagłe dźwięki budzą go przy zasypianiu? Kontroluj poziom hałasu w pokoju Miernikiem dźwięku.', title_pt = 'Controlo do som 🤫', body_pt = 'Os barulhos súbitos acordam-no quando está a adormecer? Mantenha o nível de ruído do quarto sob controlo com o Medidor de Som.', title_sv = 'Ljudkoll 🤫', body_sv = 'Väcker plötsliga ljud barnet när det håller på att somna? Håll koll på rummets ljudnivå med Ljudmätaren.', title_vi = 'Kiểm soát âm thanh 🤫', body_vi = 'Tiếng động đột ngột làm bé tỉnh giấc khi đang thiu thiu ngủ? Hãy kiểm soát độ ồn trong phòng bằng Đo âm thanh.', title_zh = '声音控制 🤫', body_zh = '快睡着时突然的声音会吵醒宝宝？用噪音测量把房间的噪音控制在限度内。' WHERE id = '92894378-2736-426b-99c1-d408f0e76945' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La energía de mamá 🔋', body_es = '¿Te quedas sin energía a media jornada? Busca en Recetas saludables un smoothie que te dé vitalidad y además apoye tu producción de leche.', title_fr = 'L''énergie de maman 🔋', body_fr = 'Plus d''énergie en milieu de journée ? Regardez dans les Recettes saines un smoothie qui soutiendra votre lactation et vous redonnera du tonus.', title_hi = 'माँ की ऊर्जा 🔋', body_hi = 'दिन के बीच में ही ऊर्जा खत्म? सेहतमंद रेसिपी में ऐसी स्मूदी की रेसिपी देखिए जो दूध बढ़ाने में मदद करे और आपको तरोताज़ा भी करे।', title_id = 'Energi Bunda 🔋', body_id = 'Energi habis di tengah hari? Lihat resep smoothie di Resep Sehat yang mendukung ASI sekaligus membuat Anda segar.', title_ja = 'ママのエネルギー 🔋', body_ja = 'お昼すぎにエネルギー切れ？「ヘルシーレシピ」で、母乳をサポートしながら元気をくれるスムージーのレシピをチェックしましょう。', title_ko = '엄마의 에너지 🔋', body_ko = '한낮에 기운이 다 빠졌나요? 건강한 레시피에서 모유에도 도움이 되고 기운도 북돋아 줄 스무디 레시피를 확인해 보세요.', title_nl = 'Energie voor mama 🔋', body_nl = 'Is je energie halverwege de dag op? Bekijk in Gezonde recepten een smoothie die je melkproductie ondersteunt en je weer fit maakt.', title_pl = 'Energia mamy 🔋', body_pl = 'W środku dnia brakuje ci energii? Zajrzyj do Zdrowych przepisów po smoothie, które wesprze laktację i doda ci wigoru.', title_pt = 'A energia da mãe 🔋', body_pt = 'A meio do dia ficou sem energia? Veja nas Receitas Saudáveis um smoothie que ajuda a produção de leite e a deixa revigorada.', title_sv = 'Mammas energi 🔋', body_sv = 'Har energin tagit slut mitt på dagen? Titta på ett smoothierecept i Hälsosamma recept som både stöttar mjölkproduktionen och piggar upp dig.', title_vi = 'Năng lượng của mẹ 🔋', body_vi = 'Giữa ngày mà mẹ đã cạn năng lượng? Xem công thức sinh tố trong Công thức lành mạnh, vừa hỗ trợ nguồn sữa, vừa giúp mẹ tỉnh táo.', title_zh = '妈妈的能量 🔋', body_zh = '一到中午就没电了？看看健康食谱里的奶昔，既能支持奶量，又能让你精神焕发。' WHERE id = 'aab86ddb-de4e-46b1-a168-2145a68d243b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Si al caer la tarde empieza a llorar sin motivo, prueba a calmarle con música clásica lenta o con ruido blanco.', body_fr = 'Pour les pleurs inexpliqués de fin d''après-midi, essayez de les calmer avec de la musique classique lente ou du bruit blanc.', body_hi = 'शाम को बिना वजह शुरू होने वाले रोने को धीमे क्लासिकल संगीत या व्हाइट नॉइज़ से शांत करके देखिए।', body_id = 'Coba redakan tangisan tanpa sebab yang muncul menjelang sore dengan musik klasik bertempo lambat atau white noise.', body_ja = '夕方から始まる理由のわからない泣きには、ゆったりしたクラシック音楽やホワイトノイズを試してみましょう。', body_ko = '늦은 오후에 시작되는 이유 없는 울음은 느린 클래식 음악이나 백색소음으로 달래 보세요.', body_nl = 'Probeer het onverklaarbare huilen aan het eind van de middag te stoppen met rustige klassieke muziek of witte ruis.', body_pl = 'Płacz bez powodu, który zaczyna się pod wieczór, spróbuj uciszyć spokojną muzyką klasyczną lub białym szumem.', body_pt = 'Experimente acalmar o choro sem motivo que começa ao fim da tarde com música clássica lenta ou ruído branco.', body_sv = 'Prova att bryta oförklarlig gråt som börjar på eftermiddagen med lugn klassisk musik eller vitt brus.', body_vi = 'Nếu bé khóc không rõ lý do vào chiều tối, hãy thử dỗ bé bằng nhạc cổ điển có tiết tấu chậm hoặc tiếng ồn trắng.', body_zh = '傍晚开始无缘无故地哭？试试用节奏舒缓的古典音乐或白噪音让宝宝平静下来。' WHERE id = '2f79ccaf-9886-4cc5-8de6-c8151fcbc753' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Al salir de paseo, que el tiempo no te engañe y tu bebé se resfríe. Usa el asistente Tiempo y ropa para decidir según las condiciones de fuera.', body_fr = 'Pour la promenade, ne vous laissez pas tromper par le temps et évitez que bébé prenne froid. Avec l''assistant Météo et tenue, choisissez ce qui convient au temps qu''il fait dehors.', body_hi = 'घूमने निकलते समय मौसम के धोखे में आकर बच्चे को सर्दी मत लगने दीजिए। मौसम और कपड़े टूल से बाहर के माहौल के हिसाब से फ़ैसला लीजिए।', body_id = 'Saat jalan-jalan, jangan sampai tertipu cuaca dan bayi masuk angin. Gunakan asisten Cuaca dan Pakaian untuk memilih yang sesuai dengan kondisi di luar.', body_ja = 'お散歩のとき、天気にだまされて赤ちゃんにかぜをひかせないように。「天気と服装」アシスタントで、外の環境に合った服装を選びましょう。', body_ko = '산책 나갈 때 날씨에 속아 아기가 감기 걸리지 않게 하세요. 날씨와 옷차림 도우미로 바깥 환경에 맞게 결정하세요.', body_nl = 'Laat je bij een wandeling niet misleiden door het weer, zodat je baby geen kou vat. Kies met de assistent Weer en kleding wat past bij het weer buiten.', body_pl = 'Wychodząc na spacer, nie daj się zwieść pogodzie, żeby maluszek się nie przeziębił. Z pomocnikiem Pogoda i ubiór podejmiesz decyzję dopasowaną do warunków.', body_pt = 'Ao sair para passear, não se deixe enganar pelo tempo e evite que o bebé se constipe. Com o assistente Tempo e Roupa, decida o que é mais adequado lá fora.', body_sv = 'Låt inte vädret lura dig så att barnet blir förkylt på promenaden. Fatta rätt beslut för förhållandena ute med Väder och kläder.', body_vi = 'Khi ra ngoài đi dạo, đừng để thời tiết đánh lừa khiến bé bị cảm lạnh. Hãy dùng Trợ lý thời tiết và trang phục để chọn cách phù hợp với điều kiện bên ngoài.', body_zh = '出门散步时别被天气骗了，让宝宝着凉。用天气穿衣助手，根据户外环境做出合适的选择。' WHERE id = '6ac04f2a-cb0e-47b2-91d7-757e201eec80' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Curiosidad por los sabores? 🍽️', body_es = '¿No quita ojo de tu plato mientras comes? Empiezan las señales de que está preparándose para los sólidos. Pero no tengas prisa, espera al 6.º mes.', title_fr = 'Curieux des saveurs ? 🍽️', body_fr = 'Quand vous mangez, il ne quitte pas votre assiette des yeux ? Les signes de préparation aux aliments solides apparaissent. Mais ne vous précipitez pas, attendez le 6e mois.', title_hi = 'स्वाद में दिलचस्पी? 🍽️', body_hi = 'आप खाते हैं तो वह आपकी प्लेट से नज़र नहीं हटाता? ठोस आहार के लिए तैयारी के संकेत शुरू हो रहे हैं। पर अभी जल्दबाज़ी मत कीजिए, 6वें महीने का इंतज़ार कीजिए।', title_id = 'Penasaran dengan rasa? 🍽️', body_id = 'Saat Anda makan, matanya tak lepas dari piring Anda? Tanda kesiapan makanan padat mulai muncul. Tapi jangan terburu-buru, tunggu bulan ke-6.', title_ja = '味に興味しんしん？🍽️', body_ja = 'あなたが食事をしているとき、お皿から目を離さない？離乳食の準備ができてきたサインです。でもまだあわてずに、生後6か月まで待ちましょう。', title_ko = '맛이 궁금한가요? 🍽️', body_ko = '엄마가 먹을 때 접시에서 눈을 떼지 않나요? 고형식 준비 신호가 나타나고 있어요. 하지만 아직 서두르지 말고 6개월까지 기다리세요.', title_nl = 'Nieuwsgierig naar smaken? 🍽️', body_nl = 'Houdt je baby zijn ogen op je bord gericht als je eet? De eerste tekenen van klaar zijn voor vast voedsel verschijnen. Maar haast je niet, wacht tot de 6e maand.', title_pl = 'Ciekawy smaków? 🍽️', body_pl = 'Gdy jesz, nie odrywa wzroku od twojego talerza? Pojawiają się oznaki gotowości do stałych pokarmów. Ale jeszcze się nie spiesz, poczekaj do 6. miesiąca.', title_pt = 'Curioso com os sabores? 🍽️', body_pt = 'Enquanto come, ele não tira os olhos do seu prato? Começam os sinais de preparação para os alimentos sólidos. Mas não se apresse, espere pelo 6.º mês.', title_sv = 'Nyfiken på smaker? 🍽️', body_sv = 'Släpper barnet inte din tallrik med blicken när du äter? Tecknen på att det är redo för fast föda börjar synas. Men skynda inte, vänta till 6:e månaden.', title_vi = 'Tò mò về hương vị? 🍽️', body_vi = 'Khi mẹ ăn, bé không rời mắt khỏi đĩa của mẹ? Dấu hiệu sẵn sàng ăn dặm đang xuất hiện. Nhưng đừng vội, hãy đợi đến tháng thứ 6.', title_zh = '对味道好奇？🍽️', body_zh = '你吃饭时宝宝目不转睛地盯着你的盘子？准备吃固体食物的迹象开始出现了。但先别着急，等到6个月再说。' WHERE id = 'e458b23e-9cff-4743-b31b-4ce87556944c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te ha sorprendido un nuevo movimiento de tu bebé? Entra en la Comunidad Anacan y comenta este descubrimiento con otras mamás.', body_fr = 'Un nouveau geste de votre bébé vous a surpris ? Rejoignez la Communauté Anacan et parlez de cette découverte avec d''autres mamans.', body_hi = 'बच्चे की किसी नई हरकत ने आपको हैरान कर दिया? Anacan कम्युनिटी में आइए और इस खोज पर दूसरी माँओं से चर्चा कीजिए।', body_id = 'Gerakan baru si kecil membuat Anda takjub? Bergabunglah di Komunitas Anacan dan diskusikan penemuan ini dengan ibu-ibu lain.', body_ja = '赤ちゃんの新しい動きにびっくりしましたか？Anacanコミュニティに参加して、この発見をほかのママたちと話し合いましょう。', body_ko = '아이의 새로운 행동에 놀라셨나요? Anacan 커뮤니티에 들어가 이 발견을 다른 엄마들과 이야기해 보세요.', body_nl = 'Verraste je kleintje je met iets nieuws? Ga naar de Anacan Community en bespreek deze ontdekking met andere moeders.', body_pl = 'Nowa umiejętność maluszka cię zaskoczyła? Dołącz do Społeczności Anacan i porozmawiaj o tym odkryciu z innymi mamami.', body_pt = 'Um movimento novo do bebé surpreendeu-a? Entre na Comunidade Anacan e fale desta descoberta com outras mães.', body_sv = 'Har en ny rörelse hos barnet överraskat dig? Gå in i Anacans Community och diskutera upptäckten med andra mammor.', body_vi = 'Bé có cử động mới khiến mẹ ngạc nhiên? Hãy vào Cộng đồng Anacan và trao đổi khám phá này với các bà mẹ khác.', body_zh = '宝宝的新动作让你惊喜了吗？进入Anacan社区，和其他妈妈聊聊这个新发现吧。' WHERE id = '25b7edd7-55ed-4b9f-b931-91fdbbe75fb4' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche dale a Cuentos inteligentes un encargo precioso: la historia de un hada que duerme sobre el arcoíris.', body_fr = 'Ce soir, confiez une jolie mission aux Contes intelligents : l''histoire d''une fée qui dort sur un arc-en-ciel.', body_hi = 'आज शाम स्मार्ट कहानियों को एक प्यारा काम दीजिए: इंद्रधनुष पर सोने वाली परी की कहानी।', body_id = 'Malam ini, beri Dongeng Pintar tugas yang indah: kisah peri yang tidur di atas pelangi.', body_ja = '今夜は「スマートおはなし」にすてきなお題を出しましょう：虹の上で眠る妖精のお話。', body_ko = '오늘 저녁 스마트 동화에 멋진 주제를 맡겨 보세요: 무지개 위에서 잠든 요정 이야기.', body_nl = 'Geef Slimme sprookjes vanavond een mooie opdracht: het verhaal van een fee die op de regenboog slaapt.', body_pl = 'Daj dziś wieczorem Mądrym bajkom piękne zadanie: historię o wróżce śpiącej na tęczy.', body_pt = 'Esta noite, dê às Histórias Inteligentes uma tarefa bonita: a história de uma fada que dorme em cima do arco-íris.', body_sv = 'Ge Smarta sagor ett fint uppdrag i kväll: sagan om fen som sover på regnbågen.', body_vi = 'Tối nay hãy giao cho Truyện cổ tích thông minh một nhiệm vụ thật đẹp: câu chuyện về nàng tiên ngủ trên cầu vồng.', body_zh = '今晚给智能故事一个美好的任务：讲一个睡在彩虹上的仙女的故事。' WHERE id = '6e3db4e0-169c-4b26-92b7-3281435ce439' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Hoy todo ha salido al revés? No te culpes. ¿Eres un robot? No. Acepta lo que sientes, perdónate y sonríe.', body_fr = 'Tout est allé de travers aujourd''hui ? Ne vous culpabilisez pas. Êtes-vous un robot ? Non. Acceptez vos émotions, pardonnez-vous et souriez.', body_hi = 'आज सब कुछ उल्टा हुआ? खुद को दोष मत दीजिए। क्या आप रोबोट हैं? नहीं। अपनी भावनाओं को स्वीकार कीजिए, खुद को माफ़ कीजिए और मुस्कुराइए।', body_id = 'Hari ini semuanya serba salah? Jangan menyalahkan diri sendiri. Apakah Anda robot? Bukan. Terima perasaan Anda, maafkan diri sendiri, dan tersenyumlah.', body_ja = '今日は何もかもうまくいかなかった？自分を責めないで。あなたはロボット？いいえ。自分の気持ちを受け入れて、自分を許して、ほほえんでください。', body_ko = '오늘 모든 게 꼬였나요? 자책하지 마세요. 당신이 로봇인가요? 아니에요. 감정을 받아들이고, 나를 용서하고, 미소 지으세요.', body_nl = 'Ging vandaag alles mis? Geef jezelf niet de schuld. Ben je een robot? Nee. Accepteer je gevoelens, vergeef jezelf en glimlach.', body_pl = 'Dziś wszystko poszło nie tak? Nie obwiniaj się. Jesteś robotem? Nie. Zaakceptuj swoje uczucia, wybacz sobie i się uśmiechnij.', body_pt = 'Hoje correu tudo mal? Não se culpe. É um robô? Não. Aceite o que sente, perdoe-se e sorria.', body_sv = 'Gick allt snett i dag? Skyll inte på dig själv. Är du en robot? Nej. Acceptera dina känslor, förlåt dig själv och le.', body_vi = 'Hôm nay mọi chuyện đều trục trặc? Đừng tự trách mình. Mẹ là robot sao? Không phải. Hãy chấp nhận cảm xúc, tha thứ cho bản thân và mỉm cười.', body_zh = '今天什么都不顺？别责怪自己。你是机器人吗？不是。接纳自己的情绪，原谅自己，笑一笑吧。' WHERE id = '91c0efe1-1cc1-4adc-a7d5-398c2cd0f5c8' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Si cuando tu bebé duerme tú también quieres caer rendida, encarga las demás tareas de casa a tu pareja.', body_fr = 'Si vous avez envie de vous écrouler pour dormir quand bébé dort, confiez les autres tâches de la maison à votre conjoint.', body_hi = 'अगर बच्चे के सोते समय आप भी बस लेटकर सो जाना चाहती हैं, तो घर के बाकी काम अपने साथी को सौंप दीजिए।', body_id = 'Kalau Anda juga ingin ikut tidur saat si kecil tidur, serahkan pekerjaan rumah lainnya kepada pasangan.', body_ja = '赤ちゃんが寝たら一緒に眠ってしまいたいなら、ほかの家事はパートナーにお願いしましょう。', body_ko = '아이가 잘 때 엄마도 쓰러져 자고 싶다면 남은 집안일은 배우자에게 맡기세요.', body_nl = 'Wil jij ook gewoon gaan slapen als je baby slaapt? Laat het andere werk in huis dan aan je partner over.', body_pl = 'Jeśli chcesz paść i zasnąć, gdy maluszek śpi, przekaż pozostałe domowe obowiązki partnerowi.', body_pt = 'Se quando o bebé dorme também só lhe apetece cair na cama, entregue as outras tarefas da casa ao seu companheiro.', body_sv = 'Vill du också slänga dig ner och sova när barnet sover? Lämna över de andra sysslorna hemma till din partner.', body_vi = 'Nếu bé ngủ và mẹ cũng chỉ muốn ngả lưng ngủ một giấc, hãy giao những việc nhà khác cho bố.', body_zh = '如果宝宝睡着时你也想倒头就睡，就把其他家务交给伴侣吧。' WHERE id = 'f295eaa8-f2fa-42e3-9941-4e98a42703f5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Niebla mental 📝', body_es = 'Los despistes forman parte del posparto. Usa a menudo la Lista de la compra para que no se te olvide nada.', title_fr = 'Le brouillard de mémoire 📝', body_fr = 'Les oublis font partie du post-partum. Utilisez activement la Liste de courses pour que rien ne vous échappe.', title_hi = 'याददाश्त का धुंधलापन 📝', body_hi = 'भूलना प्रसव के बाद के दौर का हिस्सा है। शॉपिंग लिस्ट का भरपूर इस्तेमाल कीजिए ताकि कुछ भी दिमाग से न निकले।', title_id = 'Kabut ingatan 📝', body_id = 'Mudah lupa adalah bagian dari masa pascapersalinan. Gunakan Daftar Belanja secara aktif agar tidak ada yang terlewat.', title_ja = '頭がぼんやり 📝', body_ja = 'もの忘れは産後によくあることです。何も忘れないように、「買い物リスト」をどんどん活用しましょう。', title_ko = '깜빡깜빡 엄마 머리 📝', body_ko = '건망증은 산후 시기의 자연스러운 일부예요. 쇼핑 목록을 적극 활용해 아무것도 놓치지 마세요.', title_nl = 'Geheugenmist 📝', body_nl = 'Vergeetachtigheid hoort bij de periode na de bevalling. Gebruik je Boodschappenlijstje actief, zodat je niets vergeet.', title_pl = 'Mgła w głowie 📝', body_pl = 'Zapominanie to część okresu poporodowego. Aktywnie korzystaj z Listy zakupów, żeby nic ci nie umknęło.', title_pt = 'Nevoeiro na memória 📝', body_pt = 'Os esquecimentos fazem parte do pós-parto. Use a Lista de Compras com frequência para não se esquecer de nada.', title_sv = 'Minnesdimma 📝', body_sv = 'Glömska är en del av tiden efter förlossningen. Använd Inköpslistan aktivt så att inget faller dig ur minnet.', title_vi = 'Sương mù trí nhớ 📝', body_vi = 'Hay quên là một phần của giai đoạn sau sinh. Hãy tích cực dùng Danh sách mua sắm để không quên điều gì.', title_zh = '记忆迷雾 📝', body_zh = '健忘是产后的一部分。多用购物清单，就不会忘事了。' WHERE id = 'ff9ff3bc-de2b-4add-9a4b-7f31e78329bd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Ponle delante de un espejo. Mirar su reflejo y hacer gorgoritos es una actividad perfecta y divertida para su desarrollo mental.', body_fr = 'Emmenez-le devant un miroir. Regarder son reflet et gazouiller, c''est une activité parfaite et amusante pour son développement intellectuel.', body_hi = 'उसे आईने के सामने ले जाइए। अपना अक्स देखकर किलकारी भरना उसके मानसिक विकास के लिए बढ़िया और मज़ेदार गतिविधि है।', body_id = 'Bawa ia ke depan cermin. Melihat bayangannya sendiri sambil berceloteh adalah aktivitas yang sempurna dan seru untuk perkembangan otaknya.', body_ja = '鏡の前に連れて行きましょう。自分の姿を見てクークー声を出すのは、心の発達にぴったりの楽しい遊びです。', body_ko = '아기를 거울 앞에 데려가 보세요. 거울 속 자신을 보며 옹알이하는 건 인지 발달에 아주 좋은 즐거운 놀이예요.', body_nl = 'Zet je baby voor de spiegel. Naar zijn eigen spiegelbeeld kijken en kirren is een perfecte en leuke activiteit voor zijn denkontwikkeling.', body_pl = 'Zanieś go przed lustro. Patrzenie na własne odbicie i gaworzenie to świetna i zabawna aktywność dla jego rozwoju umysłowego.', body_pt = 'Leve-o à frente do espelho. Olhar para o próprio reflexo e palrar é uma atividade perfeita e divertida para o desenvolvimento mental.', body_sv = 'Bär fram barnet till spegeln. Att titta på sin spegelbild och jollra är en perfekt och rolig aktivitet för den mentala utvecklingen.', body_vi = 'Hãy bế bé đến trước gương. Bé nhìn hình mình và ê a là một hoạt động vui và tuyệt vời cho sự phát triển trí tuệ.', body_zh = '带宝宝到镜子前。看着镜子里的自己咿咿呀呀，对宝宝的智力发育来说是完美又有趣的活动。' WHERE id = '05c1eaa2-4a23-478a-a816-f6e336bf8650' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charla de equipo 🥂', body_es = 'Abre el Diario de ánimo, deja atrás lo negativo de hoy y disfruta de ser un equipo con tu pareja.', title_fr = 'Discussion d''équipe 🥂', body_fr = 'Ouvrez le Journal d''humeur, laissez derrière vous la négativité du jour et savourez le bonheur de former une équipe avec votre conjoint.', title_hi = 'टीम की बातचीत 🥂', body_hi = 'मूड डायरी खोलिए, आज की नकारात्मकता को पीछे छोड़िए और अपने साथी के साथ टीम होने का आनंद लीजिए।', title_id = 'Obrolan tim 🥂', body_id = 'Buka Buku Harian Suasana Hati, tinggalkan hal negatif hari ini, dan nikmati kebersamaan sebagai satu tim dengan pasangan.', title_ja = 'チームで話そう 🥂', body_ja = '「気分日記」を開いて今日のモヤモヤは置いていき、パートナーとチームでいることを楽しみましょう。', title_ko = '팀 회의 🥂', body_ko = '기분 일기를 열고 오늘의 부정적인 감정은 뒤로한 채 배우자와 한 팀인 기쁨을 누려 보세요.', title_nl = 'Teamoverleg 🥂', body_nl = 'Open je Stemmingsdagboek, laat de negativiteit van vandaag achter je en geniet ervan om samen met je partner een team te zijn.', title_pl = 'Narada drużyny 🥂', body_pl = 'Otwórz Dziennik nastroju, zostaw za sobą smutki tego dnia i ciesz się tym, że z partnerem jesteście drużyną.', title_pt = 'Conversa de equipa 🥂', body_pt = 'Abra o Diário de Humor, deixe para trás o que hoje correu mal e aproveite o facto de serem uma equipa com o seu companheiro.', title_sv = 'Lagsnack 🥂', body_sv = 'Öppna Humördagboken, lämna dagens negativitet bakom dig och njut av att vara ett lag tillsammans med din partner.', title_vi = 'Trò chuyện cả đội 🥂', body_vi = 'Mở Nhật ký tâm trạng, bỏ lại những điều tiêu cực hôm nay và tận hưởng cảm giác là một đội cùng bố.', title_zh = '团队谈心 🥂', body_zh = '打开心情日记，把今天的负面情绪留在身后，和伴侣一起享受团队的感觉吧。' WHERE id = '5e7b7a68-8be5-48ad-9672-e4c1e4de4125' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Aumentan las babas y el picor de encías. Los aros de dentición limpios son tus mejores amigos.', body_fr = 'La bave et les démangeaisons des gencives augmentent. Des anneaux de dentition propres sont vos meilleurs amis.', body_hi = 'लार और मसूड़ों की खुजली बढ़ रही है। साफ़ टीथिंग रिंग अब आपकी सबसे करीबी दोस्त हैं।', body_id = 'Air liur dan gatal di gusi makin bertambah. Teether yang bersih adalah sahabat terdekat Anda.', body_ja = 'よだれと歯ぐきのむずむずが増えています。清潔な歯固めリングがいちばんの友達です。', body_ko = '침과 잇몸 가려움이 늘고 있나요? 깨끗한 치아발육기가 가장 가까운 친구예요.', body_nl = 'Het kwijlen en de jeuk aan het tandvlees nemen toe. Schone bijtringen zijn nu je beste vrienden.', body_pl = 'Ślinienie i swędzenie dziąseł się nasilają. Czyste gryzaki to teraz twoi najlepsi przyjaciele.', body_pt = 'A baba e a comichão nas gengivas aumentam. As argolas de dentição limpas são as suas melhores amigas.', body_sv = 'Dreglet och klådan i gommen ökar. Rena bitringar är din bästa vän.', body_vi = 'Nước dãi và ngứa nướu tăng lên. Vòng gặm nướu sạch sẽ là người bạn thân nhất của mẹ.', body_zh = '口水和牙龈痒越来越多了。干净的牙胶就是你最好的朋友。' WHERE id = 'd8a2fadb-f854-4f00-9556-bd2eb305be92' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Me ves? 🧸', body_es = 'Esconde un juguete bajo una manta. ¿Lo busca y lo encuentra? ¡Es un gran momento del desarrollo para entender que los objetos siguen existiendo!', title_fr = 'Tu me vois ? 🧸', body_fr = 'Cachez un jouet sous une couverture. Le cherche-t-il et le trouve-t-il ? C''est un superbe moment de développement pour comprendre la permanence de l''objet !', title_hi = 'आप मुझे देख रही हैं? 🧸', body_hi = 'खिलौने को कंबल के नीचे छिपाइए। क्या वह उसे ढूँढ लेता है? चीज़ों के स्थायी होने को समझने का यह शानदार पल है!', title_id = 'Bisa lihat aku? 🧸', body_id = 'Sembunyikan mainan di bawah selimut. Apakah ia mencari dan menemukannya? Ini momen perkembangan luar biasa untuk memahami bahwa benda tetap ada!', title_ja = 'わたしが見える？🧸', body_ja = 'おもちゃを毛布の下に隠してみましょう。探して見つけられるかな？見えなくてもものはあると理解する、すばらしい成長の瞬間です！', title_ko = '저 보여요? 🧸', body_ko = '장난감을 담요 밑에 숨겨 보세요. 찾아내나요? 대상 영속성을 이해하는 멋진 발달의 순간이에요!', title_nl = 'Zie je me? 🧸', body_nl = 'Verstop een speeltje onder een dekentje. Gaat je baby zoeken en vindt hij het? Een geweldig moment in het begrijpen dat dingen blijven bestaan!', title_pl = 'Widzisz mnie? 🧸', body_pl = 'Schowaj zabawkę pod kocykiem. Czy jej szuka i ją znajduje? To wspaniały moment w rozwoju, by zrozumieć stałość przedmiotu!', title_pt = 'Estás a ver-me? 🧸', body_pt = 'Esconda um brinquedo debaixo da manta. Ele procura-o e encontra-o? É um momento fantástico para perceber que os objetos continuam a existir!', title_sv = 'Ser du mig? 🧸', body_sv = 'Göm en leksak under en filt. Letar barnet efter den och hittar den? Det är ett fantastiskt utvecklingsögonblick för att förstå att föremål finns kvar!', title_vi = 'Mẹ có thấy con không? 🧸', body_vi = 'Giấu đồ chơi dưới chăn. Bé có tìm ra không? Đây là khoảnh khắc phát triển tuyệt vời để bé hiểu rằng đồ vật vẫn tồn tại dù không nhìn thấy!', title_zh = '看得见我吗？🧸', body_zh = '把玩具藏到毯子下面。宝宝会去找吗？这是理解物体恒存的精彩发育时刻！' WHERE id = '06a86ce4-2e7a-4f35-a865-7e585114d78f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'La mejor regla de los primeros meses: ¡la nana va por turnos! Esta noche tu bebé está en brazos de papá y tú descansas.', body_fr = 'La plus belle règle des premiers mois : la berceuse se chante à tour de rôle ! Ce soir, bébé est dans les bras de papa et vous vous reposez.', body_hi = 'पहले महीनों का सबसे अच्छा नियम: लोरी सुनाने की बारी बदलती रहनी चाहिए! आज शाम बच्चा पापा की गोद में है, और आप आराम कर रही हैं।', body_id = 'Aturan terbaik di bulan-bulan pertama: menyanyikan nina bobo harus bergantian! Malam ini bayi di pelukan ayah, Anda beristirahat.', body_ja = '最初の数か月のいちばんのルール：子守唄は交代制！今夜、赤ちゃんはパパの腕の中、あなたはひと休みです。', body_ko = '첫 몇 달의 가장 좋은 규칙: 자장가는 번갈아 불러요! 오늘 저녁은 아기가 아빠 품에 있고, 엄마는 쉬어요.', body_nl = 'De mooiste regel van de eerste maanden: slaapliedjes zingen gaat om beurten! Vanavond ligt je baby in papa''s armen en rust jij uit.', body_pl = 'Najpiękniejsza zasada pierwszych miesięcy: kołysanki śpiewa się na zmianę! Dziś wieczorem maluszek jest w ramionach taty, a ty odpoczywasz.', body_pt = 'A regra de ouro dos primeiros meses: a canção de embalar faz-se por turnos! Esta noite, o bebé está ao colo do pai e a mãe descansa.', body_sv = 'De första månadernas bästa regel: vaggvisan ska sjungas turvis! I kväll ligger barnet i pappas famn och du vilar.', body_vi = 'Quy tắc đẹp nhất của những tháng đầu: hát ru phải thay phiên nhau! Tối nay bé nằm trong vòng tay bố, còn mẹ nghỉ ngơi.', body_zh = '头几个月最美好的规则：唱摇篮曲要轮流来！今晚宝宝在爸爸怀里，你休息。' WHERE id = '478917cd-56f0-483c-b59c-a9eb5ad87e67' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Ponle en el carrito y sal a tomar aire fresco aunque sean 15 minutos. Los dos lo necesitáis.', body_fr = 'Installez-le dans sa poussette et sortez prendre l''air, ne serait-ce que 15 minutes. Vous en avez besoin tous les deux.', body_hi = 'उसे स्ट्रॉलर में बिठाइए और 15 मिनट के लिए ही सही, ताज़ी हवा में निकलिए। आप दोनों को हवा की ज़रूरत है।', body_id = 'Masukkan ia ke stroller dan keluarlah menghirup udara segar walau hanya 15 menit. Kalian berdua butuh udara segar.', body_ja = 'ベビーカーに乗せて、15分だけでも外の空気を吸いに出かけましょう。2人とも新鮮な空気が必要です。', body_ko = '아기를 유모차에 태우고 15분이라도 바깥바람을 쐬어 보세요. 두 사람 모두에게 신선한 공기가 필요해요.', body_nl = 'Leg je baby in de kinderwagen en ga naar buiten, al is het maar voor 15 minuten. Jullie hebben allebei frisse lucht nodig.', body_pl = 'Włóż go do wózka i wyjdź na świeże powietrze, choćby na 15 minut. Obojgu wam potrzebne jest powietrze.', body_pt = 'Ponha-o no carrinho e saia para apanhar ar fresco, nem que seja 15 minutos. Os dois precisam de ar.', body_sv = 'Lägg barnet i vagnen och gå ut i frisk luft, om så bara i 15 minuter. Ni behöver båda luft.', body_vi = 'Đặt bé vào xe đẩy và ra ngoài hít thở không khí trong lành, dù chỉ 15 phút. Cả hai mẹ con đều cần điều đó.', body_zh = '把宝宝放进婴儿车，哪怕出去15分钟呼吸新鲜空气也好。你们俩都需要。' WHERE id = 'b31044ce-8042-4a44-af14-b71856994efe' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Te mira con una gran sonrisa y hace sonidos nuevos. Ahora mismo te está dando el concierto más bonito, ¡escúchale con atención!', body_fr = 'Il vous regarde et émet de nouveaux sons avec un grand sourire. Il donne en ce moment le plus beau concert de la maison, écoutez bien !', body_hi = 'आपको देखकर बड़ी मुस्कान के साथ नई आवाज़ें निकालता है। वह इस समय कमरे में सबसे प्यारा कॉन्सर्ट दे रहा है, ध्यान से सुनिए!', body_id = 'Ia menatap Anda sambil mengeluarkan suara baru dengan senyum lebar. Ia sedang memberi konser terindah di kamar, dengarkan baik-baik!', body_ja = 'あなたを見て、満面の笑みで新しい声を出しています。今、部屋でいちばんすてきなコンサートを開いています。よく聞いてあげて！', body_ko = '엄마를 보며 활짝 웃고 새로운 소리를 내요. 지금 방 안에서 가장 아름다운 콘서트가 열리고 있어요, 귀 기울여 들어 보세요!', body_nl = 'Je baby kijkt je aan en maakt met een grote glimlach nieuwe geluidjes. Hij geeft nu het mooiste concert in de kamer, luister goed!', body_pl = 'Patrzy na ciebie z szerokim uśmiechem i wydaje nowe dźwięki. Właśnie daje w pokoju najpiękniejszy koncert, posłuchaj uważnie!', body_pt = 'Olha para si com um grande sorriso e faz sons novos. Está a dar o concerto mais bonito do quarto, ouça com atenção!', body_sv = 'Barnet tittar på dig och gör nya ljud med ett stort leende. Just nu ger det den vackraste konserten i rummet, lyssna noga!', body_vi = 'Bé nhìn mẹ, cười thật tươi và phát ra những âm thanh mới. Bé đang tổ chức buổi hòa nhạc tuyệt vời nhất ngay trong phòng đấy, hãy lắng nghe thật kỹ!', body_zh = '宝宝看着你，咧嘴大笑，发出新的声音。宝宝正在房间里开一场最美的音乐会，好好听吧！' WHERE id = '43a61a10-16d2-4518-b6bc-479ff5985526' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Baño templado, masaje y habitación a oscuras... No rompas nunca la rutina de sueño y tendréis noches tranquilas.', body_fr = 'Bain tiède, massage et pièce assombrie... Ne brisez jamais la routine du coucher pour passer des nuits paisibles.', body_hi = 'गुनगुना स्नान, मालिश और कमरे में अँधेरा... सोने का रूटीन कभी मत तोड़िए, ताकि आपकी रातें आराम से बीतें।', body_id = 'Mandi air hangat, pijat, dan kamar yang diredupkan... Jangan pernah melewatkan rutinitas tidur agar malam Anda tenang.', body_ja = 'ぬるめのお風呂、マッサージ、部屋を暗くする...夜をおだやかに過ごせるように、ねんねのルーティンは決して崩さないで。', body_ko = '따뜻한 목욕, 마사지, 어두운 방... 편안한 밤을 위해 잠자리 루틴은 절대 깨지 마세요.', body_nl = 'Een lauw badje, een massage en een verduisterde kamer... Doorbreek de slaaproutine nooit, zodat jullie nachten rustig verlopen.', body_pl = 'Ciepła kąpiel, masaż i przyciemniony pokój... Nigdy nie łam rytuału snu, a noce będą spokojne.', body_pt = 'Banho morno, massagem e quarto escurecido... Nunca quebre a rotina de sono, para ter noites tranquilas.', body_sv = 'Ett ljummet bad, massage och ett mörkt rum... Bryt aldrig sömnrutinen, så blir nätterna lugna.', body_vi = 'Tắm nước ấm, mát-xa và làm tối phòng... Đừng bao giờ phá vỡ nếp sinh hoạt trước khi ngủ để những đêm của mẹ được yên giấc.', body_zh = '温水澡、按摩、调暗房间……千万别打乱睡前作息，夜晚才能过得安稳。' WHERE id = 'd26efa64-1d4b-4147-ad2c-7a309dc2c5a4' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lista como un médico 🤖', body_es = 'En vez de leer noticias que asustan en internet, pregunta a Anacan AI tus dudas sobre la alimentación complementaria y quédate tranquila.', title_fr = 'Aussi malin qu''un médecin 🤖', body_fr = 'Plutôt que de lire des histoires effrayantes sur Internet, posez vos questions sur la diversification à Anacan AI et soyez rassurée.', title_hi = 'डॉक्टर जितना समझदार 🤖', body_hi = 'इंटरनेट पर डरावनी खबरें पढ़ने के बजाय ऊपरी आहार शुरू करने से जुड़े सवाल Anacan AI से पूछिए और निश्चिंत रहिए।', title_id = 'Cerdas seperti dokter 🤖', body_id = 'Daripada membaca berita menakutkan di internet, ajukan pertanyaan Anda tentang memulai MPASI ke Anacan AI dan tenangkan diri.', title_ja = 'お医者さんのように賢い 🤖', body_ja = 'ネットで怖い話を読むより、離乳食の始め方についての疑問はAnacan AIに聞いて、安心しましょう。', title_ko = '의사처럼 똑똑하게 🤖', body_ko = '인터넷에서 무서운 이야기를 읽는 대신 이유식 시작에 관한 질문을 Anacan AI에게 하고 마음을 놓으세요.', title_nl = 'Zo slim als een dokter 🤖', body_nl = 'Lees geen enge verhalen op internet, maar stel je vragen over de start met bijvoeding aan Anacan AI en ontspan.', title_pl = 'Mądry jak lekarz 🤖', body_pl = 'Zamiast czytać w internecie straszne historie, zadaj pytania o rozszerzanie diety Anacan AI i się uspokój.', title_pt = 'Inteligente como um médico 🤖', body_pt = 'Em vez de ler notícias assustadoras na internet, faça ao Anacan AI as suas perguntas sobre a diversificação alimentar e fique descansada.', title_sv = 'Smart som en läkare 🤖', body_sv = 'I stället för att läsa skrämmande nyheter på nätet, ställ dina frågor om övergången till smakportioner till Anacan AI och slappna av.', title_vi = 'Thông minh như bác sĩ 🤖', body_vi = 'Thay vì đọc những tin đáng sợ trên mạng, hãy hỏi Anacan AI về việc bắt đầu ăn dặm và yên tâm hơn nhé.', title_zh = '像医生一样聪明 🤖', body_zh = '与其在网上看吓人的消息，不如把关于添加辅食的问题交给Anacan AI，安心一点。' WHERE id = 'ddef2887-0bec-40c8-91a4-05edb188b86b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿A veces le abrigas poco y otras demasiado? No dudes más. Mira Tiempo y ropa y vístele con confianza.', body_fr = 'Parfois trop peu couvert, parfois trop chaudement habillé ? N''hésitez plus. Consultez Météo et tenue et habillez-le en toute confiance.', body_hi = 'कभी बहुत कम कपड़े, कभी बहुत गरम कपड़े पहना देती हैं? झिझकिए मत। मौसम और कपड़े देखिए और भरोसे से कपड़े पहनाइए।', body_id = 'Kadang terlalu tipis, kadang terlalu tebal pakaiannya? Jangan ragu. Cek Cuaca dan Pakaian dan pakaikan baju dengan percaya diri.', body_ja = '寒くさせすぎたり、厚着させすぎたりしていませんか？迷わないで。「天気と服装」をチェックして、自信をもって服を着せましょう。', body_ko = '가끔은 너무 얇게, 가끔은 너무 두껍게 입히나요? 망설이지 마세요. 날씨와 옷차림을 확인하고 자신 있게 입혀 주세요.', body_nl = 'Kleed je je baby soms te koud en soms te warm aan? Twijfel niet. Kijk in Weer en kleding en kleed hem met vertrouwen aan.', body_pl = 'Czasem ubierasz go za lekko, a czasem za ciepło? Nie wahaj się. Sprawdź Pogodę i ubiór i ubieraj go z pewnością.', body_pt = 'Umas vezes agasalha-o de menos, outras vezes de mais? Não hesite. Veja o Tempo e Roupa e vista-o com confiança.', body_sv = 'Klär du ibland barnet för tunt och ibland för varmt? Tveka inte. Kolla Väder och kläder och klä på barnet med trygghet.', body_vi = 'Lúc thì mặc cho bé quá mỏng, lúc lại quá ấm? Đừng do dự. Xem Thời tiết và trang phục rồi tự tin mặc đồ cho bé.', body_zh = '有时穿得太少，有时又穿得太多？别犹豫，查看天气穿衣，放心给宝宝穿吧。' WHERE id = '7bed8f71-075d-414c-be3c-9bf2c4a82ea3' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Crea en Cuentos inteligentes una historia especial para esta noche.', body_fr = 'Créez une histoire spéciale pour ce soir dans les Contes intelligents.', body_hi = 'स्मार्ट कहानियों में आज रात के लिए एक खास कहानी बनाइए।', body_id = 'Buat kisah istimewa untuk malam ini di Dongeng Pintar.', body_ja = '「スマートおはなし」で、今夜だけの特別なお話をつくりましょう。', body_ko = '스마트 동화에서 오늘 밤만을 위한 이야기를 만들어 보세요.', body_nl = 'Maak in Slimme sprookjes een speciaal verhaal voor vannacht.', body_pl = 'Stwórz w Mądrych bajkach wyjątkową historię na dzisiejszą noc.', body_pt = 'Crie uma história especial para esta noite nas Histórias Inteligentes.', body_sv = 'Skapa en speciell saga för kvällen i Smarta sagor.', body_vi = 'Hãy tạo một câu chuyện dành riêng cho đêm nay trong Truyện cổ tích thông minh.', body_zh = '在智能故事里为今晚创作一个专属故事吧。' WHERE id = '8f5769c4-aeb4-4cd1-acf0-052c7e0df753' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un festín para mamá 🥑', body_es = 'Con las prisas del día, no comas de pie. Prepara una ensalada fácil de Recetas saludables, siéntate y disfrútala.', title_fr = 'Un festin pour maman 🥑', body_fr = 'Dans la course du quotidien, ne déjeunez pas debout. Préparez une salade facile des Recettes saines, asseyez-vous et savourez-la.', title_hi = 'माँ के लिए दावत 🥑', body_hi = 'रोज़ की भागदौड़ में खड़े-खड़े लंच मत कीजिए। सेहतमंद रेसिपी से एक आसान सलाद बनाइए और बैठकर मज़े से खाइए।', title_id = 'Jamuan untuk Bunda 🥑', body_id = 'Jangan makan siang sambil berdiri di tengah kesibukan. Buat salad mudah dari Resep Sehat, lalu duduk dan nikmati.', title_ja = 'ママへのごちそう 🥑', body_ja = '毎日のバタバタの中で、お昼ごはんを立ったまま食べないで。「ヘルシーレシピ」からかんたんなサラダをつくって、座ってゆっくり味わいましょう。', title_ko = '엄마를 위한 한 상 🥑', body_ko = '바쁜 하루 속에서도 점심을 서서 먹지 마세요. 건강한 레시피에서 간단한 샐러드를 만들어 앉아서 맛있게 드세요.', title_nl = 'Een feestmaal voor mama 🥑', body_nl = 'Eet in de dagelijkse drukte niet staand je lunch. Maak een makkelijke salade uit Gezonde recepten, ga zitten en geniet ervan.', title_pl = 'Uczta dla mamy 🥑', body_pl = 'W codziennym biegu nie jedz obiadu na stojąco. Przygotuj prostą sałatkę ze Zdrowych przepisów, usiądź i zjedz ją z przyjemnością.', title_pt = 'Um banquete para a mãe 🥑', body_pt = 'Na correria do dia, não almoce de pé. Prepare uma salada fácil das Receitas Saudáveis, sente-se e coma com prazer.', title_sv = 'En fest för mamma 🥑', body_sv = 'Ät inte lunchen stående i vardagsstressen. Gör en enkel sallad från Hälsosamma recept, sätt dig ner och njut av maten.', title_vi = 'Bữa tiệc cho mẹ 🥑', body_vi = 'Đừng đứng ăn trưa giữa những bộn bề mỗi ngày. Hãy làm một món salad đơn giản từ Công thức lành mạnh, rồi ngồi xuống thưởng thức thật ngon miệng.', title_zh = '犒劳妈妈 🥑', body_zh = '再忙也别站着吃午饭。从健康食谱里做一份简单的沙拉，坐下来好好享用吧。' WHERE id = 'dcc95e44-9688-48db-a64f-a544e0720dec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuídate 🛋️', body_es = 'Cuando tu bebé duerma, dedica el tiempo a ti, no a las tareas de casa. La habitación puede seguir desordenada, pero tu energía tiene que recuperarse.', title_fr = 'Prenez soin de vous 🛋️', body_fr = 'Quand bébé dort, consacrez ce temps à vous, pas aux tâches ménagères. La pièce peut rester en désordre, mais votre énergie doit se recharger.', title_hi = 'अपना ख्याल रखिए 🛋️', body_hi = 'बच्चा सोए तो घर के कामों को नहीं, खुद को समय दीजिए। कमरा बिखरा रह सकता है, पर आपकी ऊर्जा लौटनी ज़रूरी है।', title_id = 'Jaga diri Anda 🛋️', body_id = 'Saat si kecil tidur, luangkan waktu untuk diri sendiri, bukan pekerjaan rumah. Kamar boleh berantakan, tapi energi Anda harus pulih.', title_ja = '自分を大切に 🛋️', body_ja = '赤ちゃんが寝ている間は、家事ではなく自分のために時間を使いましょう。部屋は散らかっていても大丈夫。でもあなたの元気は取り戻さなければなりません。', title_ko = '나를 지켜요 🛋️', body_ko = '아이가 잘 때는 집안일이 아니라 나에게 시간을 쓰세요. 방은 어질러져 있어도 되지만 엄마의 에너지는 회복되어야 해요.', title_nl = 'Zorg voor jezelf 🛋️', body_nl = 'Gebruik de tijd dat je baby slaapt voor jezelf, niet voor het huishouden. De kamer mag rommelig blijven, maar je energie moet weer worden aangevuld.', title_pl = 'Zadbaj o siebie 🛋️', body_pl = 'Gdy maluszek śpi, poświęć czas sobie, a nie obowiązkom domowym. W pokoju może zostać bałagan, ale twoja energia musi się odnowić.', title_pt = 'Proteja-se 🛋️', body_pt = 'Quando o bebé dorme, reserve tempo para si e não para as tarefas da casa. O quarto pode ficar desarrumado, mas a sua energia tem de ser recuperada.', title_sv = 'Skydda dig själv 🛋️', body_sv = 'När barnet sover, ta tid för dig själv i stället för hushållet. Rummet kan få vara stökigt, men din energi måste fyllas på.', title_vi = 'Hãy chăm sóc bản thân 🛋️', body_vi = 'Khi bé ngủ, hãy dành thời gian cho bản thân thay vì việc nhà. Phòng có thể bừa bộn, nhưng năng lượng của mẹ cần được phục hồi.', title_zh = '照顾好自己 🛋️', body_zh = '宝宝睡着时，别忙家务，把时间留给自己。房间乱一点没关系，但你的精力必须恢复。' WHERE id = '0b493cb3-45ff-4a4a-8782-40ce3d792d2c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Tira los juguetes y se queda mirando? 🎯', body_es = '¡Así aprende la gravedad y la relación causa-efecto! Devuélvele el juguete con paciencia.', title_fr = 'Il jette ses jouets et les regarde tomber ? 🎯', body_fr = 'C''est pour découvrir la gravité et la relation de cause à effet ! Rendez-lui son jouet avec patience.', title_hi = 'खिलौने गिराकर देखता है? 🎯', body_hi = 'इससे वह गुरुत्वाकर्षण और कारण-परिणाम का रिश्ता सीखता है! धैर्य से खिलौना वापस दीजिए।', title_id = 'Melempar mainan lalu memperhatikannya? 🎯', body_id = 'Ia sedang belajar tentang gravitasi serta sebab dan akibat! Kembalikan mainannya dengan sabar.', title_ja = 'おもちゃを床に落として見ている？🎯', body_ja = 'これは重力と原因と結果の関係を学んでいるのです！根気よくおもちゃを返してあげましょう。', title_ko = '장난감을 떨어뜨리고 바라보나요? 🎯', body_ko = '중력과 원인과 결과를 배우는 중이에요! 인내심을 갖고 장난감을 다시 건네주세요.', title_nl = 'Gooit je baby speeltjes op de grond en kijkt hij ze na? 🎯', body_nl = 'Zo leert hij over de zwaartekracht en over oorzaak en gevolg! Geef het speeltje geduldig terug.', title_pl = 'Rzuca zabawki i patrzy? 🎯', body_pl = 'Tak poznaje grawitację i związek przyczyny i skutku! Cierpliwie oddawaj mu zabawkę.', title_pt = 'Atira os brinquedos ao chão e fica a ver? 🎯', body_pt = 'É para aprender a gravidade e a relação de causa e efeito! Devolva-lhe o brinquedo com paciência.', title_sv = 'Kastar barnet leksakerna på golvet och tittar efter dem? 🎯', body_sv = 'Det är för att lära sig om tyngdkraften och orsak och verkan! Ge tillbaka leksaken med tålamod.', title_vi = 'Bé ném đồ chơi rồi nhìn theo? 🎯', body_vi = 'Bé đang học về trọng lực và quan hệ nhân quả đấy! Hãy kiên nhẫn đưa lại đồ chơi cho bé.', title_zh = '把玩具扔地上再看着？🎯', body_zh = '这是宝宝在学习重力和因果关系！耐心地把玩具还给宝宝吧。' WHERE id = '6c45dc56-f21e-446c-bca9-3243c5189d5e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No estás sola 💬', title_fr = 'Vous n''êtes pas seule 💬', title_hi = 'आप अकेली नहीं हैं 💬', title_id = 'Anda tidak sendirian 💬', title_ja = 'ひとりじゃない 💬', title_ko = '혼자가 아니에요 💬', title_nl = 'Je bent niet alleen 💬', title_pl = 'Nie jesteś sama 💬', title_pt = 'Não está sozinha 💬', title_sv = 'Du är inte ensam 💬', title_vi = 'Mẹ không đơn độc 💬', title_zh = '你并不孤单 💬' WHERE id = 'fe300d0f-4fab-4b71-8cf4-cb6e9825b2b9' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Preparando la alimentación complementaria 🥣', body_es = 'Falta poco para el 6.º mes. ¿Te interesan los primeros purés? Pregunta a Anacan AI la información básica sobre cómo empezar con la alimentación complementaria.', title_fr = 'Préparer la diversification 🥣', body_fr = 'Les 6 mois approchent. Vous vous intéressez aux premières purées ? Demandez à Anacan AI les informations de base sur la diversification.', title_hi = 'ऊपरी आहार की तैयारी 🥣', body_hi = '6वाँ महीना करीब है। पहली प्यूरी के बारे में जानना चाहती हैं? ऊपरी आहार शुरू करने की बुनियादी जानकारी Anacan AI से पूछिए।', title_id = 'Persiapan MPASI 🥣', body_id = 'Bulan ke-6 sudah dekat. Penasaran soal puree pertama? Tanyakan informasi dasar tentang memulai MPASI ke Anacan AI.', title_ja = '離乳食の準備 🥣', body_ja = 'もうすぐ生後6か月。最初のペーストが気になりますか？Anacan AIに離乳食の始め方の基本を聞いてみましょう。', title_ko = '이유식 준비 🥣', body_ko = '곧 6개월이에요. 첫 퓌레가 궁금한가요? Anacan AI에게 이유식 시작에 관한 기본 정보를 물어보세요.', title_nl = 'Voorbereiding op bijvoeding 🥣', body_nl = 'De 6e maand komt eraan. Benieuwd naar de eerste hapjes? Vraag Anacan AI naar de basis van de start met bijvoeding.', title_pl = 'Przygotowania do rozszerzania diety 🥣', body_pl = 'Do 6. miesiąca zostało niewiele. Interesują cię pierwsze przeciery? Zapytaj Anacan AI o podstawy rozszerzania diety.', title_pt = 'Preparar a diversificação alimentar 🥣', body_pt = 'Falta pouco para os 6 meses. Tem curiosidade sobre os primeiros purés? Pergunte ao Anacan AI o essencial sobre o início da diversificação alimentar.', title_sv = 'Förberedelser för smakportioner 🥣', body_sv = 'Det är inte långt kvar till 6:e månaden. Nyfiken på de första puréerna? Fråga Anacan AI om grunderna i övergången till smakportioner.', title_vi = 'Chuẩn bị ăn dặm 🥣', body_vi = 'Sắp tròn 6 tháng rồi. Mẹ đang tìm hiểu về những món nghiền đầu tiên? Hãy hỏi Anacan AI những thông tin cơ bản về việc bắt đầu ăn dặm.', title_zh = '辅食准备 🥣', body_zh = '快满6个月了。想了解第一批果泥菜泥吗？向Anacan AI问问添加辅食的基础知识吧。' WHERE id = '3cf67221-c8f7-4a51-b0e0-23076d4cd531' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fuerza de la unión 🥂', body_es = 'Esta noche comenta con tu pareja cómo habéis llegado a esta gran etapa. Como equipo, lo habéis hecho genial.', title_fr = 'La force de l''union 🥂', body_fr = 'Ce soir, parlez avec votre conjoint du chemin parcouru jusqu''à cette grande étape. En équipe, vous avez fait un travail formidable.', title_hi = 'साथ की ताकत 🥂', body_hi = 'आज शाम अपने साथी से बात कीजिए कि आप इस बड़े पड़ाव तक कैसे पहुँचे। एक टीम के रूप में आपने कमाल का काम किया है।', title_id = 'Kekuatan kebersamaan 🥂', body_id = 'Malam ini, bicarakan bersama pasangan bagaimana kalian sampai di tahap besar ini. Kalian sudah bekerja luar biasa sebagai satu tim.', title_ja = '支え合う力 🥂', body_ja = '今夜はパートナーと、この大きな節目にどうやってたどり着いたかを話し合いましょう。チームとして、すばらしい仕事をしてきました。', title_ko = '함께하는 힘 🥂', body_ko = '오늘 저녁 배우자와 이 큰 단계까지 어떻게 왔는지 이야기해 보세요. 한 팀으로 정말 멋지게 해냈어요.', title_nl = 'De kracht van samen 🥂', body_nl = 'Praat vanavond met je partner over hoe jullie deze grote mijlpaal hebben bereikt. Als team hebben jullie het geweldig gedaan.', title_pl = 'Siła wspólnoty 🥂', body_pl = 'Porozmawiaj dziś wieczorem z partnerem o tym, jak dotarliście do tego wielkiego etapu. Jako drużyna świetnie sobie poradziliście.', title_pt = 'A força da união 🥂', body_pt = 'Esta noite, fale com o seu companheiro sobre como chegaram a esta grande etapa. Como equipa, fizeram um trabalho fantástico.', title_sv = 'Gemenskapens kraft 🥂', body_sv = 'I kväll, prata med din partner om hur ni har tagit er till den här stora milstolpen. Ni har gjort ett fantastiskt jobb som lag.', title_vi = 'Sức mạnh của sự đồng lòng 🥂', body_vi = 'Tối nay, hãy cùng bố trò chuyện về hành trình đi đến cột mốc lớn này. Bố mẹ đã làm rất tuyệt vời với tư cách một đội.', title_zh = '团结的力量 🥂', body_zh = '今晚和伴侣聊聊你们是怎样走到这个重要阶段的。你们作为一个团队做得非常棒。' WHERE id = '9d27d38e-2ae9-4b74-ae13-5eaab2d9f776' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las crisis sin causa aparente agotan a cualquiera. 😭', body_es = 'No te desgastes: usa el Análisis del llanto y descubre el mensaje de su voz.', title_fr = 'Les crises sans cause apparente épuisent. 😭', body_fr = 'Ne vous fatiguez pas : utilisez l''Analyse des pleurs et découvrez le message caché dans sa voix.', title_hi = 'जिन रोने के दौरों की वजह न मिले, वे थका देते हैं 😭', body_hi = 'खुद को मत थकाइए, क्राइंग एनालिसिस का इस्तेमाल कीजिए और उसकी आवाज़ में छिपा संदेश जानिए।', title_id = 'Tangisan yang tak diketahui sebabnya sungguh melelahkan. 😭', body_id = 'Jangan memaksakan diri, gunakan Analisis Tangisan dan temukan pesan dalam suaranya.', title_ja = '理由のわからないぐずりは本当に疲れます。😭', body_ja = '無理をしないで、「泣き声分析」を使って泣き声のメッセージを見つけましょう。', title_ko = '이유를 알 수 없는 울음은 정말 지치게 해요. 😭', body_ko = '혼자 애쓰지 말고 울음 분석으로 아기 울음 속 메시지를 알아보세요.', title_nl = 'Huilbuien zonder duidelijke oorzaak putten je uit. 😭', body_nl = 'Maak jezelf niet moe, gebruik Huilanalyse en ontdek de boodschap in het huilen.', title_pl = 'Kryzysy bez znanej przyczyny wykańczają. 😭', body_pl = 'Nie męcz się, skorzystaj z Analizy płaczu i odkryj wiadomość ukrytą w jego głosie.', title_pt = 'As crises sem causa aparente esgotam qualquer um. 😭', body_pt = 'Não se canse: use a Análise do Choro e descubra a mensagem escondida no choro dele.', title_sv = 'Utbrott utan synbar orsak tar på krafterna. 😭', body_sv = 'Slit inte ut dig, använd Gråtanalys och upptäck budskapet i barnets ljud.', title_vi = 'Những cơn khóc không rõ lý do khiến mẹ kiệt sức. 😭', body_vi = 'Đừng tự làm mình mệt, hãy dùng Phân tích tiếng khóc và khám phá thông điệp trong tiếng khóc của bé.', title_zh = '找不到原因的哭闹最让人心力交瘁 😭', body_zh = '别累坏自己，用哭声分析，发现宝宝哭声里的信息吧。' WHERE id = '989db48b-e318-47e6-9019-f4f957b60d59' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡El cucú-tras es su juego favorito! 🙈', body_es = 'Tápate la cara con las manos, destápala y mira cómo se alegra. Descubre más juegos así en la sección Blog.', title_fr = 'Coucou-caché, son jeu préféré ! 🙈', body_fr = 'Cachez votre visage avec vos mains puis montrez-le, et regardez comme il est ravi. Découvrez d''autres jeux de ce genre dans la rubrique Blogs.', title_hi = 'झाँकी-झाँकी उसका पसंदीदा खेल है! 🙈', body_hi = 'हाथों से अपना चेहरा ढककर फिर खोलिए और देखिए वह कितना खुश होता है। ऐसे और खेल ब्लॉग सेक्शन में जानिए।', title_id = 'Cilukba adalah permainan favoritnya! 🙈', body_id = 'Tutup wajah Anda dengan tangan lalu buka, dan lihat betapa senangnya ia. Pelajari permainan lainnya di bagian Blog.', title_ja = 'いないいないばあが大好き！🙈', body_ja = '両手で顔を隠して、ぱっと見せてみて。赤ちゃんがどんなに喜ぶか見てみましょう。こんな遊びはブログでもっと見つけられます。', title_ko = '까꿍 놀이가 제일 좋아요! 🙈', body_ko = '손으로 얼굴을 가렸다가 보여 주며 아기가 얼마나 좋아하는지 지켜보세요. 이런 놀이를 블로그 섹션에서 더 알아보세요.', title_nl = 'Kiekeboe is favoriet! 🙈', body_nl = 'Bedek je gezicht met je handen, haal ze weg en zie hoe blij je baby wordt. Ontdek meer spelletjes in het onderdeel Blogs.', title_pl = 'Uwielbia zabawę w a kuku! 🙈', body_pl = 'Zasłaniaj i odsłaniaj twarz dłońmi i patrz, jak się cieszy. Więcej takich zabaw znajdziesz w sekcji Blog.', title_pt = 'O jogo do cucu é o preferido! 🙈', body_pt = 'Tape e destape o rosto com as mãos e veja como ele se alegra. Descubra mais jogos destes na secção Blogues.', title_sv = 'Tittut är favoritleken! 🙈', body_sv = 'Täck för ansiktet med händerna, ta bort dem och se hur glad barnet blir. Lär dig fler sådana lekar i avsnittet Bloggar.', title_vi = 'Ú òa là trò bé thích nhất! 🙈', body_vi = 'Lấy tay che mặt rồi mở ra và ngắm bé vui sướng thế nào. Tìm hiểu thêm nhiều trò chơi như vậy trong mục Blog nhé.', title_zh = '躲猫猫是最爱！🙈', body_zh = '用双手遮住脸再打开，看看宝宝有多开心。去博客板块了解更多这样的游戏吧。' WHERE id = 'a6d43603-e416-4760-8a3f-176e42bf2dc7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Nana de buenas noches 🎶', body_es = 'Ningún sonido calma tanto como la voz de mamá. Esta noche abrázale contra tu pecho y cántale bajito.', title_fr = 'Berceuse du soir 🎶', body_fr = 'Aucun son n''apaise autant que la voix de maman. Ce soir, serrez-le contre vous et chantez doucement.', title_hi = 'रात की लोरी 🎶', body_hi = 'कोई भी आवाज़ माँ की आवाज़ जितना सुकून नहीं देती। आज शाम उसे सीने से लगाइए और धीरे से गाइए।', title_id = 'Nina bobo malam 🎶', body_id = 'Tidak ada suara yang semenenangkan suara ibu. Malam ini, dekap ia di dada dan bernyanyilah pelan.', title_ja = '夜の子守唄 🎶', body_ja = 'ママの声ほど心落ち着く音はありません。今夜は胸に抱きよせて、そっと歌ってあげましょう。', title_ko = '밤의 자장가 🎶', body_ko = '엄마 목소리만큼 마음을 달래 주는 소리는 없어요. 오늘 저녁 아기를 가슴에 꼭 안고 나지막이 노래해 주세요.', title_nl = 'Een slaapliedje voor de nacht 🎶', body_nl = 'Geen geluid is zo rustgevend als mama''s stem. Houd je kleintje vanavond tegen je borst en zing zachtjes.', title_pl = 'Kołysanka na noc 🎶', body_pl = 'Żaden dźwięk nie koi tak jak głos mamy. Dziś wieczorem przytul go do piersi i cichutko mu zaśpiewaj.', title_pt = 'Canção de embalar da noite 🎶', body_pt = 'Nenhum som acalma tanto como a voz da mãe. Esta noite, aconchegue-o ao peito e cante baixinho.', title_sv = 'Vaggvisa för natten 🎶', body_sv = 'Inget ljud lugnar så som mammas röst. I kväll, håll barnet tätt intill bröstet och sjung tyst.', title_vi = 'Lời ru ban đêm 🎶', body_vi = 'Không âm thanh nào xoa dịu bằng giọng mẹ. Tối nay hãy ôm bé vào lòng và khẽ hát cho bé nghe.', title_zh = '晚安摇篮曲 🎶', body_zh = '没有什么声音比妈妈的声音更能安抚宝宝。今晚把宝宝抱在怀里，轻轻唱给宝宝听吧。' WHERE id = 'a85c19d5-09d8-4302-9d52-6f63acdaebee' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El desorden de la habitación no se va a ir a ninguna parte. No te pongas a trabajar en cuanto se duerma. Sírvete un café y descansa 10 minutos.', body_fr = 'Le désordre de la pièce ne va pas s''envoler. Ne vous lancez pas dans le ménage dès qu''il s''endort. Servez-vous un café et reposez-vous simplement 10 minutes.', body_hi = 'कमरे का बिखराव कहीं नहीं भागेगा। उसके सोते ही काम में मत जुट जाइए। अपने लिए कॉफ़ी डालिए और 10 मिनट बस आराम कीजिए।', body_id = 'Kamar yang berantakan tidak akan ke mana-mana. Jangan langsung bekerja saat ia tidur. Tuang secangkir kopi dan beristirahatlah 10 menit.', body_ja = '部屋の散らかりはどこにも逃げません。赤ちゃんが寝たらすぐに家事に取りかからないで。コーヒーをいれて、10分間ただのんびりしましょう。', body_ko = '어질러진 방은 어디 가지 않아요. 아기가 자는 동안 바로 일을 시작하지 마세요. 커피 한 잔을 따르고 10분만 그냥 쉬세요.', body_nl = 'De rommel in de kamer loopt niet weg. Ga niet meteen aan de slag als je baby slaapt. Schenk een kop koffie in en rust 10 minuten gewoon uit.', body_pl = 'Bałagan w pokoju nigdzie nie ucieknie. Gdy maluszek śpi, nie rzucaj się od razu do pracy. Nalej sobie kawy i przez 10 minut po prostu odpocznij.', body_pt = 'A desarrumação do quarto não vai fugir. Não se atire ao trabalho mal ele adormeça. Sirva-se de um café e descanse simplesmente 10 minutos.', body_sv = 'Stöket i rummet springer ingenstans. Kasta dig inte över sysslorna så fort barnet somnar. Häll upp en kopp kaffe och vila bara i 10 minuter.', body_vi = 'Căn phòng bừa bộn cũng chẳng chạy đi đâu. Đừng lao vào làm việc ngay khi bé ngủ. Hãy rót cho mình tách cà phê và chỉ nghỉ ngơi 10 phút.', body_zh = '房间乱也跑不了。宝宝一睡着别急着干活。给自己倒杯咖啡，安心休息10分钟吧。' WHERE id = '2fc6e816-81b8-4662-85f5-ea7fd4e748a8' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Filtra los ruidos 🤫', body_es = 'Los ruidos de la calle impiden el sueño profundo. Mira el Medidor de sonido y, si hace falta, usa ruido blanco.', title_fr = 'Filtrez les bruits 🤫', body_fr = 'Les bruits de la rue empêchent un sommeil profond. Consultez le Sonomètre et, si besoin, utilisez du bruit blanc.', title_hi = 'आवाज़ों को छानिए 🤫', body_hi = 'सड़क से आने वाली आवाज़ें गहरी नींद में बाधा डालती हैं। साउंड मीटर देखिए और ज़रूरत हो तो व्हाइट नॉइज़ चलाइए।', title_id = 'Saring kebisingan 🤫', body_id = 'Suara dari jalan bisa mengganggu tidur nyenyak. Cek Pengukur Suara dan gunakan white noise bila perlu.', title_ja = '音をシャットアウト 🤫', body_ja = '外からの音が深い眠りのじゃまになります。「サウンドメーター」を見て、必要ならホワイトノイズを使いましょう。', title_ko = '소음을 걸러 내요 🤫', body_ko = '바깥에서 들려오는 소리가 깊은 잠을 방해해요. 소음 측정기를 확인하고 필요하면 백색소음을 활용하세요.', title_nl = 'Filter de geluiden 🤫', body_nl = 'Geluiden van de straat verstoren de diepe slaap. Kijk op de Geluidsmeter en gebruik zo nodig witte ruis.', title_pl = 'Odfiltruj dźwięki 🤫', body_pl = 'Hałas z ulicy przeszkadza w głębokim śnie. Sprawdź Miernik dźwięku i w razie potrzeby włącz biały szum.', title_pt = 'Filtre os sons 🤫', body_pt = 'Os sons da rua atrapalham o sono profundo. Veja o Medidor de Som e, se for preciso, use ruído branco.', title_sv = 'Filtrera bort ljuden 🤫', body_sv = 'Ljud från gatan stör den djupa sömnen. Titta på Ljudmätaren och använd vitt brus om det behövs.', title_vi = 'Lọc bớt tiếng ồn 🤫', body_vi = 'Tiếng ồn ngoài đường làm bé khó ngủ sâu. Hãy xem Đo âm thanh và dùng tiếng ồn trắng nếu cần.', title_zh = '过滤噪音 🤫', body_zh = '街上的声音会打扰宝宝深睡。看看噪音测量，必要时用白噪音吧。' WHERE id = '8dd01cdf-8e98-4b6a-91ce-2edcc5e6a4df' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Filtra los ruidos 🤫', title_fr = 'Filtrez les bruits 🤫', title_hi = 'आवाज़ों को छानिए 🤫', title_id = 'Saring kebisingan 🤫', title_ja = '音をシャットアウト 🤫', title_ko = '소음을 걸러 내요 🤫', title_nl = 'Filter de geluiden 🤫', title_pl = 'Odfiltruj dźwięki 🤫', title_pt = 'Filtre os sons 🤫', title_sv = 'Filtrera bort ljuden 🤫', title_vi = 'Lọc bớt tiếng ồn 🤫', title_zh = '过滤噪音 🤫' WHERE id = 'a54926e2-dcf2-4ae7-b48f-de76a56a8b5a' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Vienen los dientes? 🦷', body_es = '¿Tiene dolor o hinchazón en la encía de abajo? Los primeros dientes pueden asomar hacia el 6.º mes.', title_fr = 'Les dents arrivent ? 🦷', body_fr = 'Douleur ou gonflement de la gencive inférieure ? Les premières dents peuvent apparaître vers le 6e mois.', title_hi = 'दाँत आने वाले हैं? 🦷', body_hi = 'नीचे के मसूड़ों में दर्द या सूजन है? पहले दाँत 6वें महीने के आसपास दिख सकते हैं।', title_id = 'Gigi sedang dalam perjalanan? 🦷', body_id = 'Gusi bawahnya sakit dan bengkak? Gigi pertama bisa muncul menjelang bulan ke-6.', title_ja = '歯が生えてくる？🦷', body_ja = '下の歯ぐきが痛そう、腫れている？最初の歯は生後6か月ごろに見えてくることがあります。', title_ko = '이가 나오고 있나요? 🦷', body_ko = '아래 잇몸에 통증이나 부기가 있나요? 첫니는 6개월 무렵에 보일 수 있어요.', title_nl = 'Tandjes onderweg? 🦷', body_nl = 'Pijn of zwelling aan het onderste tandvlees? De eerste tandjes kunnen rond de 6e maand verschijnen.', title_pl = 'Ząbki w drodze? 🦷', body_pl = 'Dolne dziąsło boli i jest opuchnięte? Pierwsze ząbki mogą pojawić się w okolicach 6. miesiąca.', title_pt = 'Vêm aí dentes? 🦷', body_pt = 'Há dor ou inchaço na gengiva de baixo? Os primeiros dentes podem aparecer perto do 6.º mês.', title_sv = 'Är tänderna på väg? 🦷', body_sv = 'Har barnet ont eller är det svullet i underkäkens tandkött? De första tänderna kan visa sig runt 6:e månaden.', title_vi = 'Răng sắp mọc rồi? 🦷', body_vi = 'Nướu dưới bị đau, sưng? Những chiếc răng đầu tiên có thể nhú ra vào khoảng tháng thứ 6.', title_zh = '牙齿要来了？🦷', body_zh = '下牙龈疼痛、肿胀？第一颗牙可能会在6个月左右冒出来。' WHERE id = '9bb7f096-5daa-4e1c-9f5e-688698945f7a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder del aire fresco 🌳', title_fr = 'Le pouvoir de l''air frais 🌳', title_hi = 'ताज़ी हवा की ताकत 🌳', title_id = 'Kekuatan udara segar 🌳', title_ja = '新鮮な空気の力 🌳', title_ko = '신선한 공기의 힘 🌳', title_nl = 'De kracht van frisse lucht 🌳', title_pl = 'Moc świeżego powietrza 🌳', title_pt = 'O poder do ar puro 🌳', title_sv = 'Den friska luftens kraft 🌳', title_vi = 'Sức mạnh của không khí trong lành 🌳', title_zh = '新鲜空气的力量 🌳' WHERE id = '3259939c-e2bd-4126-abc3-d15439051dda' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Experto en agarrar 👐', body_es = '¿Intenta agarrar objetos grandes con las dos manos a la vez? Compruébalo dándole una pelota blandita.', title_fr = 'Champion de la prise 👐', body_fr = 'Il essaie d''attraper de gros objets avec les deux mains à la fois ? Testez en lui donnant un ballon souple.', title_hi = 'पकड़ने में माहिर 👐', body_hi = 'दोनों हाथों से एक साथ बड़ी चीज़ें पकड़ने की कोशिश करता है? उसे एक नरम गेंद देकर आज़माइए।', title_id = 'Jago menggenggam 👐', body_id = 'Ia mencoba menggenggam benda besar dengan kedua tangan sekaligus? Coba berikan bola lembut.', title_ja = 'つかむの名人 👐', body_ja = '両手で同時に大きなものをつかもうとしていますか？やわらかいボールを渡して試してみましょう。', title_ko = '잡기 달인 👐', body_ko = '두 손으로 동시에 큰 물건을 잡으려 하나요? 말랑한 공을 건네 확인해 보세요.', title_nl = 'Meester in grijpen 👐', body_nl = 'Probeert je baby grote voorwerpen met twee handjes tegelijk te pakken? Probeer het uit met een zachte bal.', title_pl = 'Mistrz chwytania 👐', body_pl = 'Próbuje chwytać duże przedmioty obiema rączkami naraz? Sprawdź to, podając mu miękką piłkę.', title_pt = 'Mestre a agarrar 👐', body_pt = 'Tenta agarrar objetos grandes com as duas mãos ao mesmo tempo? Experimente dar-lhe uma bola macia.', title_sv = 'Mästare på att greppa 👐', body_sv = 'Försöker barnet greppa stora föremål med båda händerna samtidigt? Testa genom att ge det en mjuk boll.', title_vi = 'Bậc thầy cầm nắm 👐', body_vi = 'Bé cố dùng cả hai tay để cầm đồ vật lớn cùng lúc? Hãy thử đưa cho bé một quả bóng mềm.', title_zh = '抓握小能手 👐', body_zh = '宝宝在尝试用两只手同时抓大东西？给宝宝一个软球试试吧。' WHERE id = '382370f5-d970-4100-b0bc-f8460c0758ae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuentos con voz 🪄', body_es = 'Esta noche crea en Cuentos inteligentes la historia de un valiente caballero que ha crecido y ya tiene 6 meses.', title_fr = 'Des histoires à écouter 🪄', body_fr = 'Ce soir, créez dans les Contes intelligents l''histoire d''un chevalier courageux qui a grandi et a maintenant 6 mois.', title_hi = 'सुनने वाली कहानियाँ 🪄', body_hi = 'आज शाम स्मार्ट कहानियों में 6 महीने के हो चुके बहादुर योद्धा की कहानी बनाइए।', title_id = 'Dongeng bersuara 🪄', body_id = 'Malam ini, di Dongeng Pintar, buat kisah ksatria pemberani yang kini sudah berusia 6 bulan.', title_ja = '音で楽しむお話 🪄', body_ja = '今夜は「スマートおはなし」で、大きくなって生後6か月を迎えた勇敢な騎士のお話をつくりましょう。', title_ko = '소리로 듣는 동화 🪄', body_ko = '오늘 저녁 스마트 동화에서 자라서 6개월이 된 용감한 기사 이야기를 만들어 보세요.', title_nl = 'Voorleesverhalen 🪄', body_nl = 'Maak vanavond in Slimme sprookjes het verhaal van een dappere ridder die groot is geworden en nu 6 maanden is.', title_pl = 'Bajki do słuchania 🪄', body_pl = 'Dziś wieczorem stwórz w Mądrych bajkach historię o odważnym rycerzu, który urósł i ma już 6 miesięcy.', title_pt = 'Histórias em áudio 🪄', body_pt = 'Esta noite, crie nas Histórias Inteligentes a história de um cavaleiro corajoso que cresceu e já tem 6 meses.', title_sv = 'Ljudsagor 🪄', body_sv = 'Skapa sagan om den modiga riddaren som har vuxit och fyllt 6 månader i Smarta sagor i kväll.', title_vi = 'Truyện kể bằng giọng nói 🪄', body_vi = 'Tối nay, hãy tạo câu chuyện về chàng hiệp sĩ dũng cảm vừa lớn lên tròn 6 tháng trong Truyện cổ tích thông minh.', title_zh = '有声故事 🪄', body_zh = '今晚在智能故事里创作一个长到6个月的勇敢小骑士的故事吧。' WHERE id = 'ccbcf153-8cbf-48df-8422-b2c8e63c5f2d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La perfección no existe 🛑', body_es = '¿Hoy se te acabó la paciencia o quizá te enfadaste? No te sientas mal. Escribe lo que sientes en el Diario de ánimo y relájate.', title_fr = 'La perfection n''existe pas 🛑', body_fr = 'Aujourd''hui, vous avez perdu patience, peut-être vous êtes-vous énervée ? Ne vous sentez pas mal. Notez vos émotions dans le Journal d''humeur et détendez-vous.', title_hi = 'परफ़ेक्ट कोई नहीं 🛑', body_hi = 'आज धैर्य जवाब दे गया, शायद गुस्सा भी आया? बुरा मत मानिए। मूड डायरी में अपनी भावनाएँ लिखिए और आराम कीजिए।', title_id = 'Tidak ada yang sempurna 🛑', body_id = 'Hari ini kesabaran Anda menipis, mungkin Anda sempat marah? Jangan merasa bersalah. Tulis perasaan Anda di Buku Harian Suasana Hati dan tenangkan diri.', title_ja = '完璧なんてない 🛑', body_ja = '今日はがまんの限界で、イライラしてしまった？自分を責めないで。「気分日記」に気持ちを書いて、肩の力を抜きましょう。', title_ko = '완벽함은 없어요 🛑', body_ko = '오늘 인내심이 바닥나 화가 났나요? 자책하지 마세요. 기분 일기에 감정을 적고 마음을 편히 하세요.', title_nl = 'Perfectie bestaat niet 🛑', body_nl = 'Was je geduld vandaag op en werd je misschien boos? Voel je niet schuldig. Schrijf je gevoelens op in je Stemmingsdagboek en ontspan.', title_pl = 'Nie ma ideałów 🛑', body_pl = 'Dziś zabrakło ci cierpliwości, może się zdenerwowałaś? Nie czuj się źle. Zapisz swoje uczucia w Dzienniku nastroju i odpręż się.', title_pt = 'A perfeição não existe 🛑', body_pt = 'Hoje a paciência esgotou-se, talvez se tenha irritado? Não se sinta mal. Escreva o que sente no Diário de Humor e descanse.', title_sv = 'Ingen är perfekt 🛑', body_sv = 'Tog tålamodet slut i dag och kanske blev du arg? Må inte dåligt. Skriv ner dina känslor i Humördagboken och slappna av.', title_vi = 'Không có gì hoàn hảo 🛑', body_vi = 'Hôm nay mẹ hết kiên nhẫn, có thể đã nổi nóng? Đừng tự trách mình. Hãy viết cảm xúc vào Nhật ký tâm trạng và thư giãn nhé.', title_zh = '没有完美 🛑', body_zh = '今天没了耐心，也许还发了脾气？别难过。在心情日记里写下感受，放松一下吧。' WHERE id = '0e21a1c5-4a15-41e9-abfe-8342adaebb92' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Nana de papá 👨‍🍼', body_es = 'Con el Modo pareja, las notificaciones le llegan a tu pareja. Que esta noche sea él quien cante la nana para dormir.', title_fr = 'Une berceuse de papa 👨‍🍼', body_fr = 'Avec le mode Partenaire, les notifications vont à votre conjoint. Ce soir, c''est lui qui chante la berceuse pour l''endormissement.', title_hi = 'पापा की लोरी 👨‍🍼', body_hi = 'पार्टनर मोड में सूचनाएँ आपके साथी को जाने दीजिए। आज रात सोने से पहले लोरी वही गाएँ।', title_id = 'Nina bobo dari ayah 👨‍🍼', body_id = 'Di Mode Pasangan, biarkan notifikasi masuk ke pasangan Anda. Malam ini, biar ia yang menyanyikan nina bobo pengantar tidur.', title_ja = 'パパの子守唄 👨‍🍼', body_ja = '「パートナーモード」で通知をパートナーに届けましょう。今夜は寝かしつけの子守唄をパパにおまかせしましょう。', title_ko = '아빠의 자장가 👨‍🍼', body_ko = '파트너 모드에서는 알림이 배우자에게 가요. 오늘 밤 잠들기 전 자장가는 배우자가 불러 주게 하세요.', title_nl = 'Een slaapliedje van papa 👨‍🍼', body_nl = 'Laat in de Partnermodus de meldingen naar je partner gaan. Laat hem vanavond het slaapliedje zingen.', title_pl = 'Kołysanka od taty 👨‍🍼', body_pl = 'W trybie Partnera powiadomienia trafią do partnera. Dziś wieczorem niech to on zaśpiewa kołysankę na dobranoc.', title_pt = 'Uma canção de embalar do pai 👨‍🍼', body_pt = 'No Modo Parceiro, as notificações vão para o seu companheiro. Esta noite, é ele quem canta a canção de embalar para o bebé adormecer.', title_sv = 'Vaggvisa från pappa 👨‍🍼', body_sv = 'Låt aviseringarna gå till din partner i Partnerläget. I kväll får han sjunga vaggvisan inför sömnen.', title_vi = 'Lời ru của bố 👨‍🍼', body_vi = 'Ở Chế độ đối tác, thông báo sẽ được gửi đến bố. Tối nay hãy để bố hát ru đưa bé vào giấc ngủ.', title_zh = '爸爸的摇篮曲 👨‍🍼', body_zh = '开启伴侣模式，让通知发给伴侣。今晚让他来唱摇篮曲，帮宝宝入睡。' WHERE id = '31e88909-0b90-49e0-8727-857efb6836f3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Te estoy buscando! 👀', body_es = '¿Cuando sales de la habitación te busca con la mirada y llora? Puede que empiece poco a poco la ansiedad por separación. Dale seguridad.', title_fr = 'Je te cherche ! 👀', body_fr = 'Quand vous quittez la pièce, il vous cherche des yeux et pleure ? L''angoisse de séparation commence peut-être doucement. Rassurez-le.', title_hi = 'मैं आपको ढूँढ रहा हूँ! 👀', body_hi = 'कमरे से निकलते ही वह आँखों से आपको ढूँढता है और रोता है? अलगाव की बेचैनी धीरे-धीरे शुरू हो सकती है। उसे भरोसा दिलाइए।', title_id = 'Aku mencarimu! 👀', body_id = 'Saat Anda keluar kamar, matanya mencari Anda lalu menangis? Kecemasan berpisah mungkin perlahan mulai muncul. Berikan ia rasa aman.', title_ja = 'ママを探してるよ！👀', body_ja = '部屋を出ると、目であなたを探して泣きますか？分離不安が少しずつ始まっているのかもしれません。安心させてあげましょう。', title_ko = '엄마를 찾고 있어요! 👀', body_ko = '엄마가 방을 나가면 눈으로 찾으며 우나요? 분리불안이 서서히 시작될 수 있어요. 아기에게 안심을 주세요.', title_nl = 'Ik zoek jou! 👀', body_nl = 'Zoekt je baby je met de ogen en huilt hij als je de kamer uitgaat? Verlatingsangst kan langzaam beginnen. Geef hem vertrouwen.', title_pl = 'Szukam cię! 👀', body_pl = 'Gdy wychodzisz z pokoju, szuka cię wzrokiem i płacze? Może powoli zaczynać się lęk separacyjny. Daj mu poczucie bezpieczeństwa.', title_pt = 'Estou à tua procura! 👀', body_pt = 'Quando sai do quarto, procura-a com os olhos e chora? A ansiedade de separação pode estar a começar aos poucos. Dê-lhe segurança.', title_sv = 'Jag letar efter dig! 👀', body_sv = 'Letar barnet efter dig med blicken och gråter när du går ut ur rummet? Separationsångesten kan sakta börja. Ge barnet trygghet.', title_vi = 'Con đang tìm mẹ! 👀', body_vi = 'Khi mẹ ra khỏi phòng, bé đưa mắt tìm mẹ và khóc? Nỗi lo xa cách có thể đang dần bắt đầu. Hãy cho bé cảm giác an toàn.', title_zh = '我在找你！👀', body_zh = '你一离开房间，宝宝就用眼睛找你还哭？分离焦虑可能正在慢慢开始。给宝宝安全感吧。' WHERE id = 'a24757f2-97fa-405f-9959-e4c715aa8ed8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se te acaba la paciencia? Activa el Modo pareja. Deja que esta noche papá se encargue por completo del peque.', body_fr = 'À bout de patience ? Activez le mode Partenaire. Ce soir, laissez papa s''occuper entièrement de bébé.', body_hi = 'धैर्य खत्म हो रहा है? पार्टनर मोड चालू कीजिए। आज शाम बच्चे को पूरी तरह पापा संभालें।', body_id = 'Kesabaran mulai habis? Aktifkan Mode Pasangan. Malam ini, biar ayah yang sepenuhnya mengurus si kecil.', body_ja = 'イライラしていますか？「パートナーモード」をオンにしましょう。今夜は赤ちゃんのことはすべてパパにまかせましょう。', body_ko = '인내심이 바닥났나요? 파트너 모드를 켜세요. 오늘 저녁은 아이를 온전히 아빠에게 맡기세요.', body_nl = 'Raakt je geduld op? Zet de Partnermodus aan. Laat papa vanavond helemaal voor de baby zorgen.', body_pl = 'Kończy ci się cierpliwość? Włącz tryb Partnera. Niech dziś wieczorem maluszkiem zajmie się w całości tata.', body_pt = 'Está a perder a paciência? Ative o Modo Parceiro. Esta noite, deixe o pai tratar do bebé por completo.', body_sv = 'Har tålamodet tagit slut? Slå på Partnerläget. Låt pappa ta hand om barnet helt och hållet i kväll.', body_vi = 'Mẹ hết kiên nhẫn rồi? Hãy bật Chế độ đối tác. Tối nay để bố lo hết cho bé nhé.', body_zh = '快没耐心了？打开伴侣模式。今晚就让爸爸全权照顾宝宝吧。' WHERE id = '081951c6-0b7d-4045-b641-a4716f751a3d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Con qué puré de verduras empiezo? Pregunta a Anacan AI esta y otras dudas que te rondan y recibe información precisa.', body_fr = '« Par quelle purée de légumes commencer ? » Posez cette question et toutes les autres à Anacan AI pour obtenir une information précise.', body_hi = 'किस सब्ज़ी की प्यूरी से शुरुआत करूँ? यह और आपके मन के दूसरे सवाल Anacan AI से पूछिए और सटीक जानकारी पाइए।', body_id = '"Puree sayur apa yang pertama?" Tanyakan ini dan pertanyaan lain yang membuat Anda bingung ke Anacan AI, lalu dapatkan informasi yang tepat.', body_ja = '「最初はどの野菜のペーストから始めればいい？」この疑問もほかの疑問も、Anacan AIに聞いて正確な情報を受け取りましょう。', body_ko = '''어떤 채소 퓌레부터 시작할까?'' 이런 궁금증과 다른 질문들을 Anacan AI에게 물어 정확한 정보를 받아 보세요.', body_nl = 'Met welke groentehap begin ik? Stel deze en andere vragen aan Anacan AI en krijg precieze informatie.', body_pl = 'Od jakiego przecieru warzywnego zacząć? Zadaj to i inne nurtujące cię pytania Anacan AI i uzyskaj rzetelne informacje.', body_pt = '"Por que puré de legumes devo começar?" Faça ao Anacan AI esta e outras perguntas que a preocupam e receba informação precisa.', body_sv = 'Vilken grönsakspuré ska jag börja med? Ställ den här och andra frågor som du funderar på till Anacan AI och få exakt information.', body_vi = '"Nên bắt đầu với món rau củ nghiền nào trước?" Hãy hỏi Anacan AI câu này và những thắc mắc khác để nhận thông tin chính xác.', body_zh = '“第一口该从哪种蔬菜泥开始？”这个问题以及其他让你困惑的问题，都可以问Anacan AI，获得准确的信息。' WHERE id = 'b099b3d8-9148-450c-8795-4ab16ea72b2c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Control de decibelios 🤫', body_es = '¿Cuando tu bebé duerme, cualquier ruido de casa te asusta? Activa el Medidor de sonido y revisa la acústica de la habitación.', title_fr = 'Contrôle des décibels 🤫', body_fr = 'Chaque bruit vous fait sursauter quand bébé dort ? Activez le Sonomètre et vérifiez l''acoustique de la pièce.', title_hi = 'डेसिबल पर नज़र 🤫', body_hi = 'बच्चे के सोते समय घर की हर आवाज़ आपको डराती है? साउंड मीटर चालू कीजिए और कमरे की आवाज़ जाँचिए।', title_id = 'Kontrol desibel 🤫', body_id = 'Setiap suara di rumah membuat Anda cemas saat ia tidur? Aktifkan Pengukur Suara dan periksa akustik kamar.', title_ja = '音のチェック 🤫', body_ja = '赤ちゃんが寝ているとき、家の物音が気になってしまう？「サウンドメーター」をオンにして部屋の音をチェックしましょう。', title_ko = '데시벨 체크 🤫', body_ko = '아이가 잘 때 집 안의 모든 소리가 신경 쓰이나요? 소음 측정기를 켜고 방의 소리를 확인하세요.', title_nl = 'Decibelcontrole 🤫', body_nl = 'Schrik je van elk geluid in huis als je baby slaapt? Zet de Geluidsmeter aan en controleer de akoestiek van de kamer.', title_pl = 'Kontrola decybeli 🤫', body_pl = 'Gdy maluszek śpi, każdy dźwięk w domu cię przeraża? Włącz Miernik dźwięku i sprawdź akustykę pokoju.', title_pt = 'Controlo dos decibéis 🤫', body_pt = 'Quando o bebé dorme, qualquer barulho em casa a assusta? Ative o Medidor de Som e verifique a acústica do quarto.', title_sv = 'Decibelkoll 🤫', body_sv = 'Skrämmer varje ljud i huset dig när barnet sover? Aktivera Ljudmätaren och kolla rummets akustik.', title_vi = 'Kiểm soát decibel 🤫', body_vi = 'Bé ngủ mà tiếng động nào trong nhà cũng làm mẹ giật mình? Hãy bật Đo âm thanh và kiểm tra độ ồn trong phòng.', title_zh = '分贝控制 🤫', body_zh = '宝宝睡着时，家里一点声音都让你紧张？打开噪音测量，检查房间的声音环境。' WHERE id = '34eb8ef4-b7a5-4969-916d-abfccb27c775' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Casa desordenada, bebé feliz 🌪️', body_es = '¿Hay juguetes por toda la habitación? Más importante que la limpieza son 10 minutos de risas con tu peque.', title_fr = 'Maison en désordre, enfant heureux 🌪️', body_fr = 'Des jouets partout dans la pièce ? Ce n''est pas le ménage qui compte, mais les 10 minutes de sourires passées avec lui.', title_hi = 'बिखरा घर, खुश बच्चा 🌪️', body_hi = 'कमरे में हर जगह खिलौने हैं? सफ़ाई नहीं, उसके साथ हँसते हुए बिताए 10 मिनट ज़्यादा ज़रूरी हैं।', title_id = 'Rumah berantakan, anak bahagia 🌪️', body_id = 'Mainan di setiap sudut ruangan? Yang lebih penting bukan kebersihan, melainkan 10 menit penuh tawa bersamanya.', title_ja = '散らかった家、幸せな赤ちゃん 🌪️', body_ja = '部屋中おもちゃだらけ？お掃除よりも、赤ちゃんと笑顔で過ごす10分のほうがずっと大切です。', title_ko = '어질러진 집, 행복한 아이 🌪️', body_ko = '방 안이 온통 장난감인가요? 청소보다 아기와 함께 웃으며 보내는 10분이 더 소중해요.', title_nl = 'Rommelig huis, blij kind 🌪️', body_nl = 'Overal speelgoed in de kamer? Niet de schoonmaak, maar 10 vrolijke minuten samen met je baby zijn belangrijker.', title_pl = 'Bałagan w domu, szczęśliwe dziecko 🌪️', body_pl = 'Wszędzie w pokoju zabawki? Ważniejsze od sprzątania jest 10 radosnych minut spędzonych z maluszkiem.', title_pt = 'Casa desarrumada, bebé feliz 🌪️', body_pt = 'Há brinquedos por todo o quarto? Mais importante do que a limpeza são 10 minutos de sorrisos passados com ele.', title_sv = 'Stökigt hem, glatt barn 🌪️', body_sv = 'Leksaker överallt i rummet? Det är inte städningen som är viktigast, utan 10 glada minuter tillsammans med barnet.', title_vi = 'Nhà bừa bộn, bé hạnh phúc 🌪️', body_vi = 'Đồ chơi khắp phòng? Dọn dẹp không quan trọng bằng 10 phút vui vẻ mẹ dành cho bé.', title_zh = '家里乱，宝宝乐 🌪️', body_zh = '房间里到处是玩具？比起打扫，和宝宝一起欢笑的10分钟更重要。' WHERE id = 'da48ef6d-1a19-4a32-9bdc-d912779edf22' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Giros sin ayuda 🤸‍♂️', body_es = '¿Ya domina girarse de espaldas a boca abajo y de boca abajo a espaldas? ¡Registra este logro en el Seguimiento del desarrollo!', title_fr = 'Il se retourne tout seul 🤸‍♂️', body_fr = 'Il maîtrise parfaitement le retournement du dos au ventre et du ventre au dos ? Notez cette victoire dans le Suivi de développement !', title_hi = 'खुद से पलटना 🤸‍♂️', body_hi = 'पीठ से पेट और पेट से पीठ के बल पलटना पूरी तरह सीख गया? ग्रोथ ट्रैकर में इस जीत को दर्ज कीजिए!', title_id = 'Berguling sendiri 🤸‍♂️', body_id = 'Ia sudah benar-benar mahir berguling dari telentang ke tengkurap dan sebaliknya? Catat kemenangan ini di Pelacak Perkembangan!', title_ja = 'ひとりで寝返り 🤸‍♂️', body_ja = '仰向けからうつぶせ、うつぶせから仰向けへの寝返りをマスターしましたか？「発達トラッカー」にこの勝利を記録しましょう！', title_ko = '혼자서 뒤집기 🤸‍♂️', body_ko = '등에서 배로, 배에서 등으로 뒤집기를 완전히 익혔나요? 성장 기록에 이 승리를 남겨 두세요!', title_nl = 'Zelf omrollen 🤸‍♂️', body_nl = 'Rolt je baby helemaal zelf van rug naar buik en van buik naar rug? Noteer deze overwinning in de Groeitracker!', title_pl = 'Samodzielne obroty 🤸‍♂️', body_pl = 'Opanował już obroty z pleców na brzuch i z brzucha na plecy? Zapisz to zwycięstwo w Śledzeniu rozwoju!', title_pt = 'Voltas sozinho 🤸‍♂️', body_pt = 'Já domina as voltas de costas para a barriga e da barriga para as costas? Registe esta vitória no Registo de Desenvolvimento!', title_sv = 'Rullar på egen hand 🤸‍♂️', body_sv = 'Har barnet helt lärt sig att vända sig från rygg till mage och från mage till rygg? Anteckna den här segern i Utvecklingsspåraren!', title_vi = 'Tự lật người 🤸‍♂️', body_vi = 'Bé đã thành thạo lật từ ngửa sang sấp và từ sấp sang ngửa? Hãy ghi lại chiến công này trong Theo dõi phát triển!', title_zh = '自己翻身 🤸‍♂️', body_zh = '宝宝已经完全学会从仰躺翻到趴着、再从趴着翻回来了？在发育追踪里记下这次胜利吧！' WHERE id = 'ec6f8334-a2ec-4274-9ce3-07c0a3276622' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se frota los ojos? No esperes a la crisis de sueño: oscurece la habitación ya y empieza la rutina de la noche.', body_fr = 'Il se frotte les yeux ? N''attendez pas la crise de sommeil : assombrissez tout de suite la pièce et lancez la routine du soir.', body_hi = 'आँखें मल रहा है? नींद के संकट का इंतज़ार मत कीजिए, तुरंत कमरे में अँधेरा करके शाम का रूटीन शुरू कीजिए।', body_id = 'Ia mengucek mata? Jangan tunggu sampai rewel karena mengantuk, segera redupkan kamar dan mulai rutinitas malam.', body_ja = '目をこすっていますか？ぐずりが爆発するのを待たないで、すぐに部屋を暗くして夜のルーティンを始めましょう。', body_ko = '눈을 비비나요? 잠투정을 기다리지 말고 바로 방을 어둡게 해 저녁 루틴을 시작하세요.', body_nl = 'Wrijft je baby in de oogjes? Wacht niet op een slaapcrisis, maak de kamer meteen donker en begin met de avondroutine.', body_pl = 'Trze oczka? Nie czekaj na kryzys senny, od razu przyciemnij pokój i zacznij wieczorną rutynę.', body_pt = 'Esfrega os olhos? Não espere pela crise de sono: escureça já o quarto e comece a rotina da noite.', body_sv = 'Gnuggar barnet ögonen? Vänta inte på sömnkrisen, gör rummet mörkt direkt och starta kvällsrutinen.', body_vi = 'Bé dụi mắt? Đừng đợi đến lúc bé quấy vì buồn ngủ, hãy làm tối phòng ngay và bắt đầu nếp sinh hoạt buổi tối.', body_zh = '在揉眼睛？别等闹觉，马上调暗房间，开始晚间作息吧。' WHERE id = '27dc11b4-8fdd-4bba-a87f-5fa9b264f28d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Echa la vista atrás a todos tus registros. ¡Mira cuánto ha crecido tu peque y lo experta que te has vuelto! Sois un equipo estupendo.', body_fr = 'Retournez-vous sur toutes vos notes. Voyez comme il a grandi et comme vous êtes devenue une pro ! Vous formez une super équipe.', body_hi = 'अपने सभी नोट्स पर पीछे मुड़कर नज़र डालिए। देखिए वह कितना बड़ा हो गया है और आप कितनी माहिर बन गई हैं! आप एक शानदार टीम हैं।', body_id = 'Lihat kembali semua catatan Anda. Lihat betapa ia sudah tumbuh, dan betapa mahirnya Anda sekarang! Kalian tim yang hebat.', body_ja = 'これまでの記録をぜんぶ振り返ってみましょう。赤ちゃんがどれほど大きくなったか、あなたがどれほど頼もしくなったかがわかります！あなたたちは最高のチームです。', body_ko = '그동안의 모든 기록을 돌아보세요. 아기가 얼마나 컸는지, 엄마는 얼마나 능숙해졌는지 보일 거예요! 정말 멋진 팀이에요.', body_nl = 'Kijk terug naar al je notities. Zie hoeveel je baby gegroeid is en hoe jij een echte prof bent geworden! Jullie zijn een geweldig team.', body_pl = 'Spójrz wstecz na wszystkie swoje zapiski. Zobacz, jak bardzo urósł maluszek, a ty stałaś się prawdziwą profesjonalistką! Jesteście świetną drużyną.', body_pt = 'Olhe para trás, para todos os seus registos. Veja o quanto ele cresceu e como a mãe se tornou uma profissional! São uma ótima equipa.', body_sv = 'Blicka tillbaka på alla dina anteckningar. Se hur mycket barnet har vuxit och hur proffsig du har blivit! Ni är ett fantastiskt lag.', body_vi = 'Hãy nhìn lại tất cả ghi chép của mình. Xem bé đã lớn thế nào, còn mẹ đã trở nên chuyên nghiệp ra sao! Bố mẹ là một đội tuyệt vời.', body_zh = '回头看看你所有的记录。看看宝宝长大了多少，你又变得多么专业！你们是很棒的团队。' WHERE id = '788697fe-7a57-4c4c-a3dc-514298d952ed' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una noche de victoria 🥂', body_es = 'Esta noche, cuando tu bebé se duerma, sentaos cara a cara tu pareja y tú. ¡Disfrutad del orgullo de estos 180 días y daos un abrazo!', title_fr = 'Une soirée de victoire 🥂', body_fr = 'Ce soir, quand bébé dormira, asseyez-vous face à votre conjoint. Savourez la fierté de ces 180 jours et serrez-vous dans les bras !', title_hi = 'जीत की शाम 🥂', body_hi = 'आज शाम बच्चे के सोने के बाद अपने साथी के साथ आमने-सामने बैठिए। इन 180 दिनों पर गर्व कीजिए और एक-दूसरे को गले लगाइए!', title_id = 'Malam kemenangan 🥂', body_id = 'Malam ini, setelah si kecil tidur, duduklah berhadapan dengan pasangan. Rasakan bangganya 180 hari ini dan saling berpelukan!', title_ja = '勝利の夜 🥂', body_ja = '今夜は赤ちゃんが寝たら、パートナーと向き合って座りましょう。この180日間を誇りに思って、ぎゅっと抱き合いましょう！', title_ko = '승리의 저녁 🥂', body_ko = '오늘 저녁 아이가 잠든 뒤 배우자와 마주 앉으세요. 180일의 뿌듯함을 느끼며 서로를 꼭 안아 주세요!', title_nl = 'Een feestelijke avond 🥂', body_nl = 'Ga vanavond, als je baby slaapt, tegenover je partner zitten. Voel de trots van deze 180 dagen en omhels elkaar!', title_pl = 'Wieczór zwycięstwa 🥂', body_pl = 'Dziś wieczorem, gdy maluszek zaśnie, usiądź z partnerem twarzą w twarz. Poczujcie dumę z tych 180 dni i mocno się przytulcie!', title_pt = 'Uma noite de vitória 🥂', body_pt = 'Esta noite, depois de o bebé adormecer, sente-se frente a frente com o seu companheiro. Sintam o orgulho destes 180 dias e deem um abraço!', title_sv = 'Segerkväll 🥂', body_sv = 'I kväll, när barnet har somnat, sätt dig mittemot din partner. Känn stoltheten över de här 180 dagarna och krama varandra!', title_vi = 'Buổi tối chiến thắng 🥂', body_vi = 'Tối nay, sau khi bé ngủ, hãy ngồi đối diện với bố. Cùng tự hào về 180 ngày qua và ôm nhau thật chặt nhé!', title_zh = '胜利之夜 🥂', body_zh = '今晚宝宝睡着后，和伴侣面对面坐下。为这180天感到自豪，给彼此一个拥抱吧！' WHERE id = '7f7b88ee-089c-4ccc-9849-c2f4117d4833' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Durante 6 meses os habéis apoyado el uno al otro en las noches sin dormir. Abre el Diario de ánimo y da las gracias a tu pareja por este trabajo en equipo.', body_fr = 'Pendant 6 mois de nuits blanches, vous avez été le pilier l''un de l''autre. Ouvrez le Journal d''humeur et remerciez votre conjoint pour ce travail d''équipe.', body_hi = '6 महीने तक जागी रातों में आप एक-दूसरे का सहारा बने। मूड डायरी खोलिए और इस टीमवर्क के लिए अपने साथी को धन्यवाद कहिए।', body_id = 'Selama 6 bulan kalian saling menopang di malam-malam tanpa tidur. Buka Buku Harian Suasana Hati dan ucapkan terima kasih kepada pasangan atas kerja sama ini.', body_ja = '6か月間、眠れない夜を2人で支え合ってきました。「気分日記」を開いて、このチームワークにパートナーへありがとうを伝えましょう。', body_ko = '6개월 동안 잠 못 드는 밤마다 서로에게 버팀목이 되어 주었어요. 기분 일기를 열고 배우자에게 이 팀워크에 고마움을 전하세요.', body_nl = '6 maanden lang waren jullie elkaars steun in slapeloze nachten. Open je Stemmingsdagboek en bedank je partner voor dit teamwerk.', body_pl = 'Przez 6 miesięcy nieprzespanych nocy byliście dla siebie oparciem. Otwórz Dziennik nastroju i podziękuj partnerowi za tę drużynową pracę.', body_pt = 'Durante 6 meses, foram o apoio um do outro nas noites sem dormir. Abra o Diário de Humor e agradeça ao seu companheiro por este trabalho de equipa.', body_sv = 'I 6 månader har ni varit varandras stöd under de sömnlösa nätterna. Öppna Humördagboken och tacka din partner för lagarbetet.', body_vi = 'Suốt 6 tháng, bố mẹ đã là chỗ dựa cho nhau qua những đêm mất ngủ. Hãy mở Nhật ký tâm trạng và cảm ơn bố vì tinh thần đồng đội ấy.', body_zh = '这6个月的不眠之夜，你们一直互相支撑。打开心情日记，为这份团队合作感谢你的伴侣吧。' WHERE id = '2ecd0a8e-2817-4551-98e0-4276739c7da9' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La trona 🪑', body_es = '¿Estás pensando en comprar una trona? Echa un vistazo en la sección Productos recomendados a tronas ergonómicas y fáciles de limpiar.', title_fr = 'La chaise haute 🪑', body_fr = 'Vous pensez acheter une chaise haute ? Jetez un œil aux modèles ergonomiques et faciles à nettoyer dans la rubrique Produits recommandés.', title_hi = 'खाने की कुर्सी 🪑', body_hi = 'हाई चेयर खरीदने की सोच रही हैं? सुझाए गए प्रोडक्ट सेक्शन में आरामदायक और आसानी से साफ़ होने वाली कुर्सियाँ देखिए।', title_id = 'Kursi makan 🪑', body_id = 'Berencana membeli kursi makan bayi? Lihat kursi yang ergonomis dan mudah dibersihkan di bagian Produk Rekomendasi.', title_ja = '離乳食用のいす 🪑', body_ja = 'ベビーチェアの購入を考えていますか？「おすすめ商品」で、体にフィットして掃除しやすいいすをチェックしましょう。', title_ko = '이유식 의자 🪑', body_ko = '아기 식탁 의자를 살 계획인가요? 추천 제품 섹션에서 편하고 세척이 쉬운 의자를 살펴보세요.', title_nl = 'Een kinderstoel voor de eerste hapjes 🪑', body_nl = 'Denk je erover een kinderstoel te kopen? Bekijk in het onderdeel Aanbevolen producten ergonomische stoelen die makkelijk schoon te maken zijn.', title_pl = 'Krzesełko do karmienia 🪑', body_pl = 'Myślisz o kupnie krzesełka do karmienia? Zajrzyj do sekcji Polecane produkty i zobacz ergonomiczne krzesełka, które łatwo się czyści.', title_pt = 'Cadeira da papa 🪑', body_pt = 'Está a pensar comprar uma cadeira da papa? Veja na secção Produtos Recomendados cadeiras ergonómicas e fáceis de limpar.', title_sv = 'Matstol för smakportioner 🪑', body_sv = 'Funderar du på att köpa en matstol? Kika på ergonomiska stolar som är lätta att rengöra i avsnittet Rekommenderade produkter.', title_vi = 'Ghế ăn dặm 🪑', body_vi = 'Mẹ đang tính mua ghế ăn cho bé? Hãy xem những mẫu ghế tiện dụng, dễ lau chùi trong mục Sản phẩm gợi ý.', title_zh = '辅食餐椅 🪑', body_zh = '在考虑买餐椅吗？去推荐商品板块看看符合人体工学又好清洁的餐椅吧。' WHERE id = 'ce877206-0633-48d8-aa8f-9241cfab27c3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tormenta nocturna 😭', title_fr = 'La tempête de la nuit 😭', title_hi = 'रात का तूफ़ान 😭', title_id = 'Badai di malam hari 😭', title_ja = '夜の嵐 😭', title_ko = '한밤의 폭풍 😭', title_nl = 'Storm in de nacht 😭', title_pl = 'Nocna burza 😭', title_pt = 'A tempestade da noite 😭', title_sv = 'Nattens storm 😭', title_vi = 'Cơn bão ban đêm 😭', title_zh = '夜里的风暴 😭' WHERE id = 'c7c50614-edd2-448c-a9f6-e76579ba2f11' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un cuento nuevo por descubrir 📖', body_es = 'Hagamos que esta noche sea distinta. Crea una historia especial en Cuentos inteligentes y llena la habitación de magia.', title_fr = 'À la découverte d''un nouveau conte 📖', body_fr = 'Rendons cette soirée différente. Créez une histoire unique dans les Contes intelligents et remplissez la chambre de magie.', title_hi = 'नई कहानी की खोज 📖', body_hi = 'आज की रात को खास बनाइए। स्मार्ट कहानियों में एक खास कहानी बनाइए और कमरे को जादू से भर दीजिए।', title_id = 'Menjelajah dongeng baru 📖', body_id = 'Ayo buat malam ini berbeda. Buat kisah istimewa di Dongeng Pintar dan penuhi kamar dengan keajaiban.', title_ja = '新しいお話を見つけよう 📖', body_ja = '今夜はいつもと違う夜にしましょう。「スマートおはなし」で特別なお話をつくって、部屋を魔法でいっぱいにしましょう。', title_ko = '새로운 동화 탐험 📖', body_ko = '오늘 밤은 특별하게 보내요. 스마트 동화에서 나만의 이야기를 만들어 방을 마법으로 채워 보세요.', title_nl = 'Een nieuw sprookje ontdekken 📖', body_nl = 'Laten we van vanavond iets bijzonders maken. Maak in Slimme sprookjes een eigen verhaal en vul de kamer met magie.', title_pl = 'Odkryj nową bajkę 📖', body_pl = 'Niech ten wieczór będzie inny. Stwórz w Mądrych bajkach wyjątkową historię i wypełnij pokój magią.', title_pt = 'Uma nova história para descobrir 📖', body_pt = 'Vamos tornar esta noite diferente. Crie uma história especial nas Histórias Inteligentes e encha o quarto de magia.', title_sv = 'En ny saga att upptäcka 📖', body_sv = 'Låt oss göra kvällen annorlunda. Skapa en personlig saga i Smarta sagor och fyll rummet med magi.', title_vi = 'Khám phá truyện mới 📖', body_vi = 'Tối nay mình làm điều gì đó khác biệt nhé. Hãy tạo một câu chuyện riêng trong Truyện cổ tích thông minh và phủ căn phòng bằng phép màu.', title_zh = '发现新故事 📖', body_zh = '让今晚与众不同吧。在智能故事里创作一个专属故事，让房间充满魔法。' WHERE id = '1297700e-9cfd-4ca4-a9de-fc8b3c3e36fd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Antes de empezar con la alimentación complementaria, registra cada cambio de pañal en Anacan para asegurarte de que su digestión va bien.', body_fr = 'Avant de commencer la diversification, notez chaque change dans Anacan pour vous assurer que sa digestion fonctionne bien.', body_hi = 'ऊपरी आहार शुरू करने से पहले पाचन ठीक है, यह पक्का करने के लिए Anacan में हर डायपर बदलना दर्ज कीजिए।', body_id = 'Sebelum mulai MPASI, catat setiap ganti popok di Anacan untuk memastikan pencernaannya baik.', body_ja = '離乳食を始める前に、消化の調子が整っているか確かめるため、おむつ替えのたびにAnacanに記録しましょう。', body_ko = '이유식을 시작하기 전에 소화 상태가 괜찮은지 확인하려면 Anacan에 기저귀 교체를 빠짐없이 기록하세요.', body_nl = 'Noteer elke luierverschoning in Anacan, zodat je zeker weet dat de spijsvertering goed werkt voordat je met bijvoeding begint.', body_pl = 'Zanim zaczniesz rozszerzać dietę, zapisuj w Anacan każdą zmianę pieluszki, by mieć pewność, że trawienie działa jak należy.', body_pt = 'Antes de começar a diversificação alimentar, registe no Anacan cada muda de fralda para confirmar que a digestão está em ordem.', body_sv = 'Anteckna varje blöjbyte i Anacan för att vara säker på att matsmältningen fungerar som den ska innan ni börjar med smakportioner.', body_vi = 'Trước khi bắt đầu ăn dặm, hãy ghi lại mỗi lần thay tã trong Anacan để chắc chắn hệ tiêu hóa của bé hoạt động tốt.', body_zh = '开始添加辅食前，为了确认消化系统一切正常，在Anacan里记录每一次换尿布吧。' WHERE id = '9d58451e-ede3-4a05-ba21-dd4e0b7f4086' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Ya me siento! 🪑', body_es = '¿Sentado con apoyo ya tiene más seguridad? Anímale a sentarse apoyado en cojines, pero solo durante ratos cortos.', title_fr = 'Je m''assois ! 🪑', body_fr = 'Il est plus assuré quand il est assis avec un soutien ? Encouragez-le à s''asseoir calé par des coussins, mais peu de temps.', title_hi = 'मैं बैठ रहा हूँ! 🪑', body_hi = 'सहारे से बैठने पर अब वह ज़्यादा आत्मविश्वासी है? तकियों का सहारा देकर उसे बैठने के लिए प्रेरित कीजिए, पर थोड़ी देर के लिए।', title_id = 'Aku bisa duduk! 🪑', body_id = 'Ia sudah lebih percaya diri saat duduk bersandar? Dorong ia duduk dengan topangan bantal, tapi hanya sebentar.', title_ja = 'おすわりしてるよ！🪑', body_ja = '支えがあると、前より自信をもって座れていますか？クッションで支えて座る練習をさせてあげましょう。ただし短い時間だけです。', title_ko = '저 앉아요! 🪑', body_ko = '받쳐 앉을 때 이제 더 자신 있어 보이나요? 쿠션으로 받쳐 앉도록 도와주되 짧게만 해 주세요.', title_nl = 'Ik zit! 🪑', body_nl = 'Zit je baby al zekerder met steun? Moedig hem aan om te zitten met kussens als steun, maar kort.', title_pl = 'Siedzę! 🪑', body_pl = 'Siedząc z podparciem, jest już pewniejszy? Zachęcaj go do siedzenia, podpierając go poduszkami, ale tylko przez krótki czas.', title_pt = 'Estou sentado! 🪑', body_pt = 'Já se senta com mais confiança quando tem apoio? Incentive-o a sentar-se apoiado em almofadas, mas por pouco tempo.', title_sv = 'Jag sitter! 🪑', body_sv = 'Är barnet redan säkrare när det sitter med stöd? Uppmuntra det att sitta med kuddar som stöd, men bara en kort stund.', title_vi = 'Con ngồi được rồi! 🪑', body_vi = 'Khi được đỡ ngồi, bé đã tự tin hơn? Hãy chèn gối xung quanh để khuyến khích bé tập ngồi, nhưng chỉ trong thời gian ngắn.', title_zh = '我会坐啦！🪑', body_zh = '扶着坐时宝宝更有信心了？用枕头支撑着鼓励宝宝坐，但时间要短。' WHERE id = 'edc6faba-a997-408a-a40b-e590a39a3721' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Le cuesta más dormirse? Comprueba los decibelios de la habitación con el Medidor de sonido y déjala totalmente a oscuras.', body_fr = 'L''endormissement est devenu difficile ? Vérifiez les décibels de la pièce avec le Sonomètre et faites le noir complet.', body_hi = 'सोना मुश्किल हो गया है? साउंड मीटर से कमरे का डेसिबल जाँचिए और कमरे में पूरा अँधेरा कीजिए।', body_id = 'Ia makin sulit tertidur? Cek desibel kamar dengan Pengukur Suara dan buat kamar benar-benar gelap.', body_ja = '寝つきが悪くなった？「サウンドメーター」で部屋の音量（デシベル）をチェックして、部屋を真っ暗にしましょう。', body_ko = '잠들기가 어려워졌나요? 소음 측정기로 방의 데시벨을 확인하고 방을 완전히 어둡게 해 주세요.', body_nl = 'Gaat in slaap vallen moeilijker? Controleer met de Geluidsmeter het aantal decibel in de kamer en maak de kamer helemaal donker.', body_pl = 'Zasypianie stało się trudniejsze? Sprawdź decybele w pokoju Miernikiem dźwięku i całkowicie zaciemnij pokój.', body_pt = 'Adormecer ficou mais difícil? Verifique os decibéis do quarto com o Medidor de Som e escureça-o por completo.', body_sv = 'Har det blivit svårare att somna? Kolla rummets decibelnivå med Ljudmätaren och gör rummet helt mörkt.', body_vi = 'Bé khó vào giấc hơn? Kiểm tra mức decibel trong phòng bằng Đo âm thanh và làm tối hẳn căn phòng.', body_zh = '入睡变难了？用噪音测量检查房间的分贝，让房间完全暗下来。' WHERE id = '936424c3-1b30-4fc1-924e-920162d0d5bd' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Al salir de paseo, que el tiempo no te engañe y tu bebé pase frío. Usa el asistente Tiempo y ropa para decidir según las condiciones de fuera.', body_fr = 'Pour la promenade, ne vous laissez pas tromper par le temps et évitez qu''il prenne froid. Avec l''assistant Météo et tenue, choisissez ce qui convient au temps qu''il fait dehors.', body_hi = 'घूमने निकलते समय मौसम के धोखे में आकर ठंड मत लगने दीजिए। मौसम और कपड़े टूल से बाहर के माहौल के हिसाब से फ़ैसला लीजिए।', body_id = 'Saat jalan-jalan, jangan sampai tertipu cuaca dan masuk angin. Gunakan asisten Cuaca dan Pakaian untuk memilih yang sesuai dengan kondisi di luar.', body_ja = 'お散歩のとき、天気にだまされてかぜをひかせないように。「天気と服装」アシスタントで、外の環境に合った服装を選びましょう。', body_ko = '산책 나갈 때 날씨에 속아 감기 걸리지 않게 하세요. 날씨와 옷차림 도우미로 바깥 환경에 맞게 결정하세요.', body_nl = 'Laat je bij een wandeling niet misleiden door het weer, zodat je baby geen kou vat. Kies met de assistent Weer en kleding wat past bij het weer buiten.', body_pl = 'Wychodząc na spacer, nie daj się zwieść pogodzie, żeby maluszek nie zmarzł. Z pomocnikiem Pogoda i ubiór podejmiesz decyzję dopasowaną do warunków.', body_pt = 'Ao sair para passear, não se deixe enganar pelo tempo e evite constipações. Com o assistente Tempo e Roupa, decida o que é mais adequado lá fora.', body_sv = 'Låt inte vädret lura dig så att barnet blir kallt på promenaden. Fatta rätt beslut för förhållandena ute med Väder och kläder.', body_vi = 'Khi ra ngoài đi dạo, đừng để thời tiết đánh lừa khiến bé bị lạnh. Hãy dùng Trợ lý thời tiết và trang phục để chọn cách phù hợp với điều kiện bên ngoài.', body_zh = '出门散步时别被天气骗了，小心着凉。用天气穿衣助手，根据户外环境做出合适的选择。' WHERE id = '6dad4f0a-8c98-4797-a95f-50aab81d4662' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Te estoy buscando! 👀', body_es = '¿Empieza a llorar en cuanto sales de la habitación? La ansiedad por separación se está formando del todo. Solo tiene miedo de que no vuelvas. Dale seguridad con tu voz.', title_fr = 'Je te cherche ! 👀', body_fr = 'Il se met à pleurer dès que vous quittez la pièce ? L''angoisse de séparation se met en place. Il a simplement peur que vous ne reveniez pas. Rassurez-le avec votre voix.', title_hi = 'मैं आपको ढूँढ रहा हूँ! 👀', body_hi = 'कमरे से निकलते ही वह रोने लगता है? अलगाव की बेचैनी पूरी तरह आकार ले रही है। उसे बस डर है कि आप लौटकर नहीं आएँगी। अपनी आवाज़ से उसे भरोसा दिलाइए।', title_id = 'Aku mencarimu! 👀', body_id = 'Ia langsung menangis begitu Anda keluar kamar? Kecemasan berpisah sedang terbentuk sepenuhnya. Ia hanya takut Anda tidak akan kembali. Tenangkan ia dengan suara Anda.', title_ja = 'ママを探してるよ！👀', body_ja = '部屋を出たとたんに泣きはじめますか？分離不安がはっきりあらわれてきています。もう戻ってこないのではと怖いだけなのです。声をかけて安心させてあげましょう。', title_ko = '엄마를 찾고 있어요! 👀', body_ko = '엄마가 방을 나가는 순간 울기 시작하나요? 분리불안이 본격적으로 자리 잡는 중이에요. 엄마가 다시 돌아오지 않을까 봐 두려운 거예요. 목소리로 안심시켜 주세요.', title_nl = 'Ik zoek jou! 👀', body_nl = 'Begint je baby te huilen zodra je de kamer uitgaat? De verlatingsangst ontwikkelt zich volledig. Hij is gewoon bang dat je niet terugkomt. Geef hem vertrouwen met je stem.', title_pl = 'Szukam cię! 👀', body_pl = 'Zaczyna płakać, gdy tylko wyjdziesz z pokoju? Lęk separacyjny w pełni się kształtuje. Po prostu boi się, że już nie wrócisz. Daj mu poczucie bezpieczeństwa swoim głosem.', title_pt = 'Estou à tua procura! 👀', body_pt = 'Começa a chorar mal sai do quarto? A ansiedade de separação está a formar-se por completo. Ele só tem medo de que não volte. Dê-lhe segurança com a sua voz.', title_sv = 'Jag letar efter dig! 👀', body_sv = 'Börjar barnet gråta så fort du går ut ur rummet? Separationsångesten tar form på riktigt. Barnet är bara rädd att du inte ska komma tillbaka. Ge det trygghet med din röst.', title_vi = 'Con đang tìm mẹ! 👀', body_vi = 'Mẹ vừa ra khỏi phòng là bé khóc? Nỗi lo xa cách đang hình thành rõ rệt. Bé chỉ sợ mẹ sẽ không quay lại. Hãy dùng giọng nói của mẹ để trấn an bé.', title_zh = '我在找你！👀', body_zh = '你一离开房间宝宝就开始哭？分离焦虑正在完全形成。宝宝只是害怕你不会再回来。用你的声音给宝宝安全感吧。' WHERE id = 'affd2ecc-89d1-4649-8b63-63dfe9a1ced9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cambios en la digestión. 🧷', body_es = 'Con la alimentación complementaria cambiarán sus cacas. Registra cada cambio de pañal en Anacan para no perder de vista cómo va.', title_fr = 'Des changements côté digestion. 🧷', body_fr = 'Avec la diversification, ses selles vont changer. Notez chaque change dans Anacan pour garder un œil sur la situation.', title_hi = 'पाचन में बदलाव 🧷', body_hi = 'ऊपरी आहार के साथ मल त्याग बदलेगा। Anacan में हर डायपर बदलना दर्ज करके स्थिति पर नज़र रखिए।', title_id = 'Perubahan pada pencernaan. 🧷', body_id = 'Dengan MPASI, pola BAB-nya akan berubah. Pantau kondisinya dengan mencatat setiap ganti popok di Anacan.', title_ja = '消化の変化 🧷', body_ja = '離乳食が始まると、うんちも変わってきます。おむつ替えのたびにAnacanに記録して、様子を見守りましょう。', title_ko = '소화의 변화 🧷', body_ko = '이유식을 시작하면 변이 달라져요. Anacan에 기저귀 교체를 빠짐없이 기록하며 상태를 지켜보세요.', title_nl = 'Veranderingen in de spijsvertering. 🧷', body_nl = 'Met bijvoeding verandert de ontlasting. Noteer elke luierverschoning in Anacan en houd alles goed in de gaten.', title_pl = 'Zmiany w trawieniu. 🧷', body_pl = 'Wraz z rozszerzaniem diety zmienią się kupki. Zapisuj w Anacan każdą zmianę pieluszki i miej sytuację pod kontrolą.', title_pt = 'Mudanças na digestão. 🧷', body_pt = 'Com a diversificação alimentar, as fezes vão mudar. Registe no Anacan cada muda de fralda e esteja atenta.', title_sv = 'Förändringar i matsmältningen. 🧷', body_sv = 'Med smakportionerna kommer bajset att förändras. Håll koll på läget genom att anteckna varje blöjbyte i Anacan.', title_vi = 'Thay đổi ở hệ tiêu hóa. 🧷', body_vi = 'Khi ăn dặm, phân của bé sẽ thay đổi. Hãy ghi lại mỗi lần thay tã trong Anacan để theo dõi tình hình.', title_zh = '消化系统的变化 🧷', body_zh = '添加辅食后，宝宝的大便会发生变化。在Anacan里记录每一次换尿布，留意宝宝的状况。' WHERE id = 'c4e8f9e9-c94b-41fc-a23a-61a8c7026386' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿No se come el puré y lo escupe?', body_es = 'No te sientas torpe. Es una experiencia totalmente nueva para tu bebé, ten paciencia.', title_fr = 'Il refuse la purée et la recrache ?', body_fr = 'Ne vous sentez pas incapable. C''est une expérience toute nouvelle pour lui, soyez patiente.', title_hi = 'प्यूरी नहीं खाता और थूक देता है?', body_hi = 'खुद को नाकाबिल मत समझिए। यह उसके लिए बिल्कुल नया अनुभव है, धैर्य रखिए।', title_id = 'Ia tidak mau makan puree dan menyemburkannya?', body_id = 'Jangan merasa tidak becus. Ini pengalaman yang benar-benar baru baginya, bersabarlah.', title_ja = 'ペーストを食べずに、口から出してしまう？', body_ja = '自分はダメだなんて思わないで。赤ちゃんにとってはまったく新しい体験です。気長にいきましょう。', title_ko = '퓌레를 안 먹고 뱉어 내나요?', body_ko = '부족한 엄마라고 느끼지 마세요. 아기에게는 완전히 새로운 경험이니 인내심을 가져 주세요.', title_nl = 'Eet je baby de hap niet en spuugt hij hem uit?', body_nl = 'Voel je niet onhandig. Dit is een compleet nieuwe ervaring voor hem, heb geduld.', title_pl = 'Nie je przecieru i wypluwa go?', body_pl = 'Nie czuj, że sobie nie radzisz. To dla niego zupełnie nowe doświadczenie, bądź cierpliwa.', title_pt = 'Não come o puré e cospe-o?', body_pt = 'Não se sinta incapaz. É uma experiência totalmente nova para ele, tenha paciência.', title_sv = 'Äter barnet inte purén och spottar ut den?', body_sv = 'Känn dig inte otillräcklig. Det här är en helt ny upplevelse för barnet, ha tålamod.', title_vi = 'Bé không chịu ăn món nghiền và nhè ra?', body_vi = 'Đừng nghĩ mình vụng về. Đây là trải nghiệm hoàn toàn mới với bé, hãy kiên nhẫn nhé.', title_zh = '宝宝不吃果泥，还往外吐？', body_zh = '别觉得自己做得不好。这对宝宝来说是全新的体验，耐心一点。' WHERE id = '3bd59fce-abbd-4e13-ab2d-4379b5c89cac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuentos con voz 🪄', body_es = 'Esta noche crea un cuento en Cuentos inteligentes y termina el día de forma divertida.', title_fr = 'Des histoires à écouter 🪄', body_fr = 'Ce soir, terminez la journée en beauté en créant un conte dans les Contes intelligents.', title_hi = 'सुनने वाली कहानियाँ 🪄', body_hi = 'आज शाम स्मार्ट कहानियों में एक कहानी बनाकर दिन का मज़ेदार अंत कीजिए।', title_id = 'Dongeng bersuara 🪄', body_id = 'Malam ini, tutup hari dengan seru dengan membuat dongeng di Dongeng Pintar.', title_ja = '音で楽しむお話 🪄', body_ja = '今夜は「スマートおはなし」でお話をつくって、1日を楽しく締めくくりましょう。', title_ko = '소리로 듣는 동화 🪄', body_ko = '오늘 저녁 스마트 동화에서 이야기를 만들며 하루를 즐겁게 마무리하세요.', title_nl = 'Voorleesverhalen 🪄', body_nl = 'Maak vanavond een sprookje in Slimme sprookjes en sluit de dag gezellig af.', title_pl = 'Bajki do słuchania 🪄', body_pl = 'Zakończ dzień wesoło: stwórz dziś wieczorem bajkę w Mądrych bajkach.', title_pt = 'Histórias em áudio 🪄', body_pt = 'Esta noite, crie uma história nas Histórias Inteligentes e termine o dia de forma divertida.', title_sv = 'Ljudsagor 🪄', body_sv = 'Avsluta dagen på ett roligt sätt i kväll genom att skapa en saga i Smarta sagor.', title_vi = 'Truyện kể bằng giọng nói 🪄', body_vi = 'Tối nay hãy tạo một câu chuyện trong Truyện cổ tích thông minh để kết thúc ngày thật vui.', title_zh = '有声故事 🪄', body_zh = '今晚在智能故事里创作一个故事，开开心心地结束这一天吧。' WHERE id = '48005ac4-750b-4fca-b0cd-2711d3eb3c21' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Picor en las encías? 🦷', body_es = 'Durante la alimentación complementaria las molestias de la dentición también pueden aumentar. Usa gel para las encías siguiendo el consejo del médico.', title_fr = 'Des gencives qui démangent ? 🦷', body_fr = 'Pendant la diversification, les douleurs dentaires peuvent aussi augmenter. Utilisez un gel dentaire sur conseil du médecin.', title_hi = 'मसूड़ों में खुजली? 🦷', body_hi = 'ऊपरी आहार के दौर में दाँत निकलने का दर्द भी बढ़ सकता है। डॉक्टर की सलाह से टीथिंग जेल इस्तेमाल कीजिए।', title_id = 'Gusi gatal? 🦷', body_id = 'Di masa MPASI, rasa sakit tumbuh gigi juga bisa bertambah. Gunakan gel gigi sesuai saran dokter.', title_ja = '歯ぐきがむずむず？🦷', body_ja = '離乳食の時期には、歯が生えるときの痛みも増えることがあります。お医者さんのアドバイスのもとで歯ぐき用ジェルを使いましょう。', title_ko = '잇몸이 간지러워요? 🦷', body_ko = '이유식 시기에는 이앓이 통증도 심해질 수 있어요. 의사의 조언에 따라 잇몸 젤을 사용하세요.', title_nl = 'Jeukend tandvlees? 🦷', body_nl = 'Tijdens de bijvoeding kan ook de pijn van doorkomende tandjes toenemen. Gebruik tandgel op advies van de arts.', title_pl = 'Swędzące dziąsła? 🦷', body_pl = 'W czasie rozszerzania diety mogą nasilić się też bóle ząbkowania. Stosuj żel na ząbkowanie zgodnie z zaleceniem lekarza.', title_pt = 'Comichão nas gengivas? 🦷', body_pt = 'Durante a diversificação alimentar, as dores dos dentes também podem aumentar. Use gel para a dentição seguindo o conselho do médico.', title_sv = 'Kliar det i gommen? 🦷', body_sv = 'Under perioden med smakportioner kan tandsmärtorna också öka. Använd tandgel enligt läkarens råd.', title_vi = 'Ngứa nướu? 🦷', body_vi = 'Trong thời gian ăn dặm, cơn đau mọc răng cũng có thể tăng lên. Hãy dùng gel bôi nướu theo chỉ dẫn của bác sĩ.', title_zh = '牙龈痒痒？🦷', body_zh = '添加辅食期间，长牙的不适也可能加重。请在医生的建议下使用牙龈凝胶。' WHERE id = 'ae1cbea0-aaaf-49ff-9518-967813809e3b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿A tu peque no le gusta el puré de calabaza? Entra en la Comunidad Anacan y descubre las experiencias y recetas de otras mamás.', body_fr = 'Votre enfant n''aime pas la purée de potiron ? Rejoignez la Communauté Anacan pour découvrir l''expérience des mamans et leurs autres recettes.', body_hi = 'बच्चे को कद्दू की प्यूरी पसंद नहीं? Anacan कम्युनिटी में आइए और माँओं के अनुभव और अलग-अलग रेसिपी जानिए।', body_id = 'Si kecil tidak suka puree labu? Bergabunglah di Komunitas Anacan dan pelajari pengalaman serta resep lain dari para ibu.', body_ja = 'かぼちゃのペーストが好きじゃない？Anacanコミュニティに参加して、ママたちの経験やいろいろなレシピを知りましょう。', body_ko = '아이가 단호박 퓌레를 싫어하나요? Anacan 커뮤니티에 들어가 엄마들의 경험과 다양한 레시피를 알아보세요.', body_nl = 'Lust je kleintje geen pompoenhap? Ga naar de Anacan Community en ontdek de ervaringen en andere recepten van moeders.', body_pl = 'Maluszek nie lubi przecieru z dyni? Dołącz do Społeczności Anacan i poznaj doświadczenia mam oraz różne przepisy.', body_pt = 'O seu bebé não gosta do puré de abóbora? Entre na Comunidade Anacan e conheça as experiências e as receitas diferentes de outras mães.', body_sv = 'Gillar inte barnet pumpapuré? Gå in i Anacans Community och ta del av andra mammors erfarenheter och olika recept.', body_vi = 'Bé không thích bí đỏ nghiền? Hãy vào Cộng đồng Anacan để học hỏi kinh nghiệm và những công thức khác nhau của các bà mẹ.', body_zh = '宝宝不爱吃南瓜泥？进入Anacan社区，看看其他妈妈的经验和不同的食谱吧。' WHERE id = '4beff801-d69f-40c0-bed1-2e8938edb5f2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Si se frota los ojos y se queda con la mirada perdida, no esperes a la crisis. Oscurece la habitación ya y empieza la rutina de sueño.', body_fr = 'S''il se frotte les yeux et fixe le vide, n''attendez pas la crise. Assombrissez tout de suite la pièce et lancez la routine du coucher.', body_hi = 'अगर वह आँखें मलकर शून्य में देख रहा है, तो रोने के दौरे का इंतज़ार मत कीजिए। तुरंत कमरे में अँधेरा करके सोने का रूटीन शुरू कीजिए।', body_id = 'Kalau ia mengucek mata dan menatap kosong, jangan tunggu sampai rewel. Segera redupkan kamar dan mulai rutinitas tidur.', body_ja = '目をこすってぼーっとしていたら、ぐずりが爆発するのを待たないで。すぐに部屋を暗くして、ねんねのルーティンを始めましょう。', body_ko = '눈을 비비며 허공을 바라본다면 잠투정을 기다리지 마세요. 바로 방을 어둡게 하고 잠자리 루틴을 시작하세요.', body_nl = 'Wrijft je baby in de oogjes en staart hij in het niets? Wacht niet op een huilbui. Maak de kamer meteen donker en begin met de slaaproutine.', body_pl = 'Jeśli trze oczka i patrzy w pustkę, nie czekaj na kryzys. Od razu przyciemnij pokój i zacznij rytuał snu.', body_pt = 'Se esfrega os olhos e fica a olhar para o vazio, não espere pela crise. Escureça já o quarto e comece a rotina de sono.', body_sv = 'Gnuggar barnet ögonen och stirrar tomt ut i luften? Vänta inte på utbrottet. Gör rummet mörkt direkt och börja sömnrutinen.', body_vi = 'Nếu bé dụi mắt và nhìn vào khoảng không, đừng đợi đến lúc bé quấy. Hãy làm tối phòng ngay và bắt đầu nếp sinh hoạt trước khi ngủ.', body_zh = '如果宝宝揉着眼睛发呆，别等闹觉。马上调暗房间，开始睡前作息。' WHERE id = '7df7f58f-05e6-4afb-aa2c-73438e6504d4' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Intentos de sentarse sin apoyo 🪑', body_es = '¿Ya se apoya menos en los cojines? ¡Muy pronto se sentará sin ningún apoyo!', title_fr = 'S''asseoir sans soutien : les premiers essais 🪑', body_fr = 'Il s''appuie moins sur les coussins ? Très bientôt, il tiendra assis tout seul !', title_hi = 'बिना सहारे बैठने की कोशिशें 🪑', body_hi = 'अब तकियों पर कम टिकता है? बहुत जल्द वह बिल्कुल बिना सहारे बैठेगा!', title_id = 'Mencoba duduk tanpa sandaran 🪑', body_id = 'Ia sudah makin jarang bersandar ke bantal? Sebentar lagi ia akan duduk tanpa bantuan sama sekali!', title_ja = '支えなしでおすわりに挑戦 🪑', body_ja = 'もうクッションにあまり寄りかからなくなった？もうすぐ支えなしでおすわりできるようになります！', title_ko = '혼자 앉기 도전 🪑', body_ko = '이제 쿠션에 덜 기대나요? 곧 받침 없이 혼자 앉을 거예요!', title_nl = 'Zitpogingen zonder steun 🪑', body_nl = 'Leunt je baby al minder op de kussens? Heel binnenkort zit hij helemaal zonder steun!', title_pl = 'Próby siedzenia bez podparcia 🪑', body_pl = 'Coraz mniej opiera się o poduszki? Już niedługo będzie siedział całkiem bez podparcia!', title_pt = 'Tentativas de se sentar sem apoio 🪑', body_pt = 'Já se apoia menos nas almofadas? Muito em breve vai sentar-se sem apoio nenhum!', title_sv = 'Försök att sitta utan stöd 🪑', body_sv = 'Lutar sig barnet redan mindre mot kuddarna? Väldigt snart kommer det att sitta helt utan stöd!', title_vi = 'Tập ngồi không cần đỡ 🪑', body_vi = 'Bé đã ít dựa vào gối hơn? Sắp tới bé sẽ tự ngồi vững mà không cần đỡ!', title_zh = '尝试独坐 🪑', body_zh = '宝宝已经不那么依赖枕头了？很快就能完全独立坐稳啦！' WHERE id = '8afe4995-9e98-44a1-a9cc-5c970d87a396' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Comparte cómo te sientes 📝', body_es = '¿Hoy estás muy cansada? Escribe tus emociones con sinceridad en el Diario de ánimo. Desahogarte te sentará bien.', title_fr = 'Partagez votre humeur 📝', body_fr = 'Très fatiguée aujourd''hui ? Écrivez sincèrement vos émotions dans le Journal d''humeur. Vider votre cœur vous fera du bien.', title_hi = 'अपना मूड बाँटिए 📝', body_hi = 'आज बहुत थक गई हैं? मूड डायरी में अपनी भावनाएँ सच्चे मन से लिखिए। मन हल्का करना आपके लिए अच्छा रहेगा।', title_id = 'Bagikan suasana hati Anda 📝', body_id = 'Hari ini sangat lelah? Tuliskan perasaan Anda dengan jujur di Buku Harian Suasana Hati. Meluapkan isi hati akan membuat Anda lebih lega.', title_ja = '気持ちをシェアしよう 📝', body_ja = '今日はとても疲れていますか？「気分日記」に気持ちを正直に書いてみましょう。吐き出すと心が軽くなります。', title_ko = '기분을 나눠 주세요 📝', body_ko = '오늘 많이 지쳤나요? 기분 일기에 감정을 솔직하게 적어 보세요. 마음을 털어놓으면 한결 나아질 거예요.', title_nl = 'Deel je gevoel 📝', body_nl = 'Ben je vandaag erg moe? Schrijf je gevoelens eerlijk op in je Stemmingsdagboek. Je hart luchten doet je goed.', title_pl = 'Podziel się nastrojem 📝', body_pl = 'Jesteś dziś bardzo zmęczona? Szczerze zapisz swoje emocje w Dzienniku nastroju. Wyrzucenie ich z siebie dobrze ci zrobi.', title_pt = 'Partilhe o seu estado de espírito 📝', body_pt = 'Hoje está muito cansada? Escreva com sinceridade as suas emoções no Diário de Humor. Desabafar vai fazer-lhe bem.', title_sv = 'Dela ditt humör 📝', body_sv = 'Är du väldigt trött i dag? Skriv ärligt ner dina känslor i Humördagboken. Att lätta på hjärtat gör dig gott.', title_vi = 'Chia sẻ tâm trạng 📝', body_vi = 'Hôm nay mẹ mệt lắm à? Hãy viết cảm xúc thật lòng vào Nhật ký tâm trạng. Trút bầu tâm sự sẽ giúp mẹ dễ chịu hơn.', title_zh = '分享你的心情 📝', body_zh = '今天很累吗？在心情日记里真诚地写下感受。把心里话说出来会让你好受些。' WHERE id = '34c92908-0941-4c15-a946-75240f0ea7f7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hambre o gases? 😭', body_es = 'El paso a la alimentación complementaria puede causar estreñimiento o gases. Si hagas lo que hagas no se calla, usa el Análisis del llanto y descubre la causa.', title_fr = 'Il a faim ou des gaz ? 😭', body_fr = 'La diversification peut provoquer constipation ou gaz. Si rien ne le calme, utilisez l''Analyse des pleurs pour découvrir la raison de ses pleurs.', title_hi = 'भूखा है या गैस है? 😭', body_hi = 'ऊपरी आहार शुरू करने से कब्ज़ या गैस हो सकती है। कुछ भी करने पर चुप न हो, तो क्राइंग एनालिसिस से आवाज़ के पीछे की वजह जानिए।', title_id = 'Lapar atau kembung? 😭', body_id = 'Memulai MPASI bisa menyebabkan sembelit atau perut kembung. Kalau tangisnya tak berhenti apa pun yang Anda lakukan, gunakan Analisis Tangisan untuk menemukan penyebab di balik suaranya.', title_ja = 'お腹がすいてる？それともガス？😭', body_ja = '離乳食を始めると、便秘やガスが起こることがあります。何をしても泣きやまないなら、「泣き声分析」を使って泣き声の理由を見つけましょう。', title_ko = '배가 고픈 걸까요, 가스가 찬 걸까요? 😭', body_ko = '이유식을 시작하면 변비나 가스가 생길 수 있어요. 무엇을 해도 울음을 그치지 않는다면 울음 분석으로 울음의 이유를 찾아보세요.', title_nl = 'Honger of krampjes? 😭', body_nl = 'De overgang naar bijvoeding kan verstopping of krampjes geven. Stopt het huilen niet, wat je ook doet? Ontdek met Huilanalyse wat erachter zit.', title_pl = 'Głód czy gazy? 😭', body_pl = 'Rozszerzanie diety może powodować zaparcia lub gazy. Jeśli nic nie pomaga go uciszyć, skorzystaj z Analizy płaczu i znajdź przyczynę.', title_pt = 'Tem fome ou gases? 😭', body_pt = 'A diversificação alimentar pode causar obstipação ou gases. Se nada o acalma, use a Análise do Choro e descubra a causa por trás do choro.', title_sv = 'Ont i magen eller gaser? 😭', body_sv = 'Övergången till smakportioner kan ge förstoppning eller gaser. Om barnet inte tystnar vad du än gör, använd Gråtanalys och hitta orsaken bakom ljudet.', title_vi = 'Bé đau bụng hay bị đầy hơi? 😭', body_vi = 'Chuyển sang ăn dặm có thể gây táo bón hoặc đầy hơi. Nếu làm gì bé cũng không nín, hãy dùng Phân tích tiếng khóc để tìm lý do đằng sau tiếng khóc.', title_zh = '是肠绞痛还是胀气？😭', body_zh = '添加辅食可能引起便秘或胀气。如果怎么哄都哄不好，就用哭声分析找出哭声背后的原因吧。' WHERE id = 'cd45d0d2-bf31-47be-adf8-84c3b1895339' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'De una mano a otra 🧸', body_es = '¿Ya se pasa el juguete de una mano a otra con total soltura? Sus hemisferios cerebrales funcionan de maravilla. Dale objetos de distintas texturas.', title_fr = 'D''une main à l''autre 🧸', body_fr = 'Il passe un jouet d''une main à l''autre en toute aisance ? Les hémisphères de son cerveau fonctionnent parfaitement. Donnez-lui des objets de différentes textures.', title_hi = 'एक हाथ से दूसरे हाथ तक 🧸', body_hi = 'खिलौना एक हाथ से दूसरे हाथ में आसानी से ले जाता है? उसके दिमाग के दोनों हिस्से बढ़िया काम कर रहे हैं। उसे अलग-अलग बनावट वाली चीज़ें दीजिए।', title_id = 'Dari tangan ke tangan 🧸', body_id = 'Ia sudah lancar memindahkan mainan dari satu tangan ke tangan lain? Kedua belahan otaknya bekerja dengan sempurna. Berikan benda dengan berbagai tekstur.', title_ja = '手から手へ探検 🧸', body_ja = 'おもちゃを片方の手からもう片方へ自由に持ちかえていますか？左右の脳がしっかり働いています。いろいろな手ざわりのものを渡してあげましょう。', title_ko = '이 손에서 저 손으로 🧸', body_ko = '장난감을 한 손에서 다른 손으로 자유롭게 옮기나요? 좌뇌와 우뇌가 아주 잘 작동하고 있어요. 다양한 촉감의 물건을 건네 보세요.', title_nl = 'Van hand tot hand 🧸', body_nl = 'Geeft je baby een speeltje helemaal vrij door van de ene naar de andere hand? De hersenhelften werken perfect samen. Geef hem voorwerpen met verschillende texturen.', title_pl = 'Z rączki do rączki 🧸', body_pl = 'Swobodnie przekłada zabawkę z jednej rączki do drugiej? Półkule mózgu świetnie działają. Dawaj mu przedmioty o różnych fakturach.', title_pt = 'Descobertas de mão em mão 🧸', body_pt = 'Já passa o brinquedo de uma mão para a outra com toda a liberdade? Os hemisférios do cérebro funcionam na perfeição. Dê-lhe objetos com texturas diferentes.', title_sv = 'Från hand till hand 🧸', body_sv = 'Flyttar barnet leksaken helt fritt från ena handen till den andra? Hjärnhalvorna samarbetar perfekt. Ge barnet saker med olika texturer.', title_vi = 'Chuyền tay khám phá 🧸', body_vi = 'Bé chuyền đồ chơi từ tay này sang tay kia thật thoải mái? Hai bán cầu não đang phối hợp hoàn hảo. Hãy cho bé những đồ vật có chất liệu khác nhau.', title_zh = '左右手传递 🧸', body_zh = '宝宝能自如地把玩具从一只手换到另一只手了？左右脑配合得很好。给宝宝一些不同质地的东西摸摸吧。' WHERE id = '1f9cc7dc-a0b4-41a4-983b-794c5917ee08' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Las charlas se alargan! 🗣️', body_es = 'Los da-da-da y ba-ba-ba resuenan por toda la casa. Visita la sección Blog para leer más sobre su desarrollo del lenguaje.', title_fr = 'Les conversations s''allongent ! 🗣️', body_fr = 'Les « da-da-da » et « ba-ba-ba » résonnent dans la maison. Rendez-vous dans la rubrique Blogs pour en lire plus sur le développement de son langage.', title_hi = 'बातें लंबी हो रही हैं! 🗣️', body_hi = 'दा-दा-दा, बा-बा-बा की आवाज़ें घर में गूँज रही हैं। उसके भाषा विकास के बारे में और पढ़ने के लिए ब्लॉग सेक्शन देखिए।', title_id = 'Obrolan makin panjang! 🗣️', body_id = 'Suara da-da-da dan ba-ba-ba menggema di rumah. Kunjungi bagian Blog untuk membaca lebih banyak tentang perkembangan bahasanya.', title_ja = 'おしゃべりが長くなってきた！🗣️', body_ja = '「だーだーだ」「ばーばーば」の声が家中に響いています。言葉の発達についてもっと知るには、ブログをのぞいてみましょう。', title_ko = '대화가 길어져요! 🗣️', body_ko = '다-다-다, 바-바-바 소리가 집 안에 울려 퍼져요. 아기의 언어 발달에 대해 더 알고 싶다면 블로그 섹션을 방문하세요.', title_nl = 'De gesprekjes worden langer! 🗣️', body_nl = 'Da-da-da en ba-ba-ba klinken door het huis. Lees meer over zijn taalontwikkeling in het onderdeel Blogs.', title_pl = 'Rozmowy są coraz dłuższe! 🗣️', body_pl = 'Da-da-da, ba-ba-ba rozbrzmiewa w całym domu. Więcej o rozwoju mowy przeczytasz w sekcji Blog.', title_pt = 'As conversas estão a ficar mais longas! 🗣️', body_pt = 'Os sons da-da-da e ba-ba-ba ecoam pela casa. Para ler mais sobre o desenvolvimento da linguagem, visite a secção Blogues.', title_sv = 'Samtalen blir längre! 🗣️', body_sv = 'Da-da-da och ba-ba-ba ekar i hemmet. Besök avsnittet Bloggar för att läsa mer om barnets språkutveckling.', title_vi = 'Những cuộc trò chuyện dài hơn! 🗣️', body_vi = 'Tiếng "đa-đa-đa", "ba-ba-ba" vang khắp nhà. Hãy ghé mục Blog để đọc thêm về sự phát triển ngôn ngữ của bé.', title_zh = '聊得越来越久了！🗣️', body_zh = '家里回荡着“da-da-da”“ba-ba-ba”的声音。去博客板块，读读更多关于宝宝语言发育的内容吧。' WHERE id = '298934a2-9d12-42b8-8c9c-6098d3709ab4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'La mejor regla de los primeros meses: ¡la nana va por turnos! Esta noche tu bebé está en brazos de papá y tú descansas.', body_fr = 'La plus belle règle des premiers mois : la berceuse se chante à tour de rôle ! Ce soir, bébé est dans les bras de papa et vous vous reposez.', body_hi = 'पहले महीनों का सबसे अच्छा नियम: लोरी सुनाने की बारी बदलती रहनी चाहिए! आज शाम बच्चा पापा की गोद में है, और आप आराम कर रही हैं।', body_id = 'Aturan terbaik di bulan-bulan pertama: menyanyikan nina bobo harus bergantian! Malam ini bayi di pelukan ayah, Anda beristirahat.', body_ja = '最初の数か月のいちばんのルール：子守唄は交代制！今夜、赤ちゃんはパパの腕の中、あなたはひと休みです。', body_ko = '첫 몇 달의 가장 좋은 규칙: 자장가는 번갈아 불러요! 오늘 저녁은 아기가 아빠 품에 있고, 엄마는 쉬어요.', body_nl = 'De mooiste regel van de eerste maanden: slaapliedjes zingen gaat om beurten! Vanavond ligt je baby in papa''s armen en rust jij uit.', body_pl = 'Najpiękniejsza zasada pierwszych miesięcy: kołysanki śpiewa się na zmianę! Dziś wieczorem maluszek jest w ramionach taty, a ty odpoczywasz.', body_pt = 'A regra de ouro dos primeiros meses: a canção de embalar faz-se por turnos! Esta noite, o bebé está ao colo do pai e a mãe descansa.', body_sv = 'De första månadernas bästa regel: vaggvisan ska sjungas turvis! I kväll ligger barnet i pappas famn och du vilar.', body_vi = 'Quy tắc đẹp nhất của những tháng đầu: hát ru phải thay phiên nhau! Tối nay bé nằm trong vòng tay bố, còn mẹ nghỉ ngơi.', body_zh = '头几个月最美好的规则：唱摇篮曲要轮流来！今晚宝宝在爸爸怀里，你休息。' WHERE id = '89ff16e6-d11a-4deb-ae4f-1ba03e76271d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ya dice más claro sílabas como ba-ba o ma-ma? Responde a sus sonidos y fomenta esta comunicación.', body_fr = 'Il prononce plus clairement des syllabes comme « ba-ba » ou « ma-ma » ? Répondez à ses sons et encouragez cette communication.', body_hi = 'बा-बा, मा-मा जैसे अक्षर ज़्यादा साफ़ बोलता है? उसकी आवाज़ों का जवाब दीजिए और इस बातचीत को बढ़ावा दीजिए।', body_id = 'Ia mengucapkan suku kata seperti "ba-ba" dan "ma-ma" dengan lebih jelas? Tanggapi suaranya dan dukung komunikasi ini.', body_ja = '「ばーば」「まーま」のような音を、前よりはっきり言えるようになった？声に応えて、このやりとりを応援してあげましょう。', body_ko = '바바, 마마 같은 소리를 더 또렷하게 내나요? 아기 소리에 반응하며 이 소통을 응원해 주세요.', body_nl = 'Zegt je baby lettergrepen als ba-ba en ma-ma steeds duidelijker? Reageer op zijn geluidjes en stimuleer deze communicatie.', body_pl = 'Wyraźniej mówi sylaby jak ba-ba, ma-ma? Odpowiadaj na jego głos i wspieraj tę komunikację.', body_pt = 'Diz sílabas como ba-ba, ma-ma de forma mais clara? Responda aos sons dele e incentive esta comunicação.', body_sv = 'Säger barnet stavelser som ba-ba och ma-ma tydligare? Svara på ljuden och stötta den här kommunikationen.', body_vi = 'Bé nói những âm như "ba-ba", "ma-ma" rõ hơn? Hãy đáp lại và khuyến khích bé giao tiếp nhé.', body_zh = '宝宝说“ba-ba”“ma-ma”这样的音节更清楚了？回应宝宝的声音，鼓励这种交流吧。' WHERE id = '5378180a-aa43-4728-9384-08bbcf8838ee' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Después de un día difícil, sentaos cara a cara tu pareja y tú y hablad. Apoyaros reparte la carga a la mitad.', body_fr = 'Après une journée difficile, asseyez-vous face à votre conjoint et parlez. Vous soutenir mutuellement allège la charge de moitié.', body_hi = 'मुश्किल दिन के बाद अपने साथी के साथ आमने-सामने बैठकर दिल की बात कीजिए। एक-दूसरे का साथ बोझ आधा कर देता है।', body_id = 'Setelah hari yang berat, duduklah berhadapan dengan pasangan dan saling bercerita. Saling mendukung membuat beban terbagi dua.', body_ja = '大変な1日のあとは、パートナーと向き合って話しましょう。支え合うことで、負担は半分になります。', body_ko = '힘든 하루를 보낸 뒤 배우자와 마주 앉아 이야기를 나눠 보세요. 서로를 응원하면 짐이 절반으로 줄어요.', body_nl = 'Ga na een zware dag tegenover je partner zitten en praat je hart uit. Elkaar steunen halveert de last.', body_pl = 'Po trudnym dniu usiądź z partnerem twarzą w twarz i porozmawiajcie. Wzajemne wsparcie dzieli ciężar na pół.', body_pt = 'Depois de um dia difícil, sente-se frente a frente com o seu companheiro e conversem. Apoiarem-se um ao outro divide o peso ao meio.', body_sv = 'Efter en tuff dag, sätt er mittemot varandra och prata ut med din partner. Att stötta varandra halverar bördan.', body_vi = 'Sau một ngày vất vả, hãy ngồi đối diện và tâm sự cùng bố. Cùng nâng đỡ nhau sẽ giúp gánh nặng vơi đi một nửa.', body_zh = '辛苦一天后，和伴侣面对面坐下聊聊。互相支持，担子就轻了一半。' WHERE id = 'a4be80bb-cd06-42ba-b875-78d5a32af3ba' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Siéntete orgullosa de ti 👏', body_es = 'Mira atrás y recuerda el miedo que tenías las primeras semanas. ¡Y ahora eres toda una experta preparando purés!', title_fr = 'Soyez fière de vous 👏', body_fr = 'Rappelez-vous comme vous aviez peur les premières semaines. Et maintenant, vous êtes une maman pro des purées !', title_hi = 'खुद पर गर्व कीजिए 👏', body_hi = 'पीछे मुड़कर याद कीजिए कि पहले हफ़्तों में आप कितनी डरी हुई थीं। और अब आप प्यूरी बनाने वाली माहिर माँ हैं!', title_id = 'Banggalah pada diri Anda 👏', body_id = 'Ingat kembali betapa takutnya Anda di minggu-minggu pertama. Sekarang Anda ibu andal yang membuat puree!', title_ja = '自分をほめてあげて 👏', body_ja = '最初の数週間、どれほど不安だったかを思い出してみて。今ではペーストづくりもお手のもののママです！', title_ko = '스스로를 자랑스러워하세요 👏', body_ko = '돌아보면 첫 몇 주 동안 얼마나 두려웠는지 기억나죠. 그런데 지금은 퓌레를 척척 만드는 능숙한 엄마예요!', title_nl = 'Wees trots op jezelf 👏', body_nl = 'Denk terug aan hoe bang je was in de eerste weken. En nu ben je een echte prof die hapjes maakt!', title_pl = 'Bądź z siebie dumna 👏', body_pl = 'Spójrz wstecz i przypomnij sobie, jak bałaś się w pierwszych tygodniach. A teraz jesteś mamą-profesjonalistką od przecierów!', title_pt = 'Orgulhe-se de si 👏', body_pt = 'Olhe para trás e lembre-se do medo que sentia nas primeiras semanas. E agora é uma mãe profissional que já faz purés!', title_sv = 'Var stolt över dig själv 👏', body_sv = 'Blicka tillbaka och minns hur rädd du var de första veckorna. Och nu är du en proffsmamma som gör puréer!', title_vi = 'Hãy tự hào về mình 👏', body_vi = 'Nhìn lại, hãy nhớ những tuần đầu mẹ đã lo sợ thế nào. Còn giờ mẹ đã là một người mẹ chuyên nghiệp biết làm món nghiền!', title_zh = '为自己骄傲 👏', body_zh = '回想一下最初几周你有多害怕。现在你已经是会做辅食的专业妈妈了！' WHERE id = 'efa880a4-37d0-4521-93db-df2495a01243' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Nana de buenas noches 🎶', body_es = 'Ningún sonido calma tanto como la voz de mamá. Esta noche, simplemente abrázale contra tu pecho y cántale bajito.', title_fr = 'Berceuse du soir 🎶', body_fr = 'Aucun son n''apaise autant que la voix de maman. Ce soir, serrez-le simplement contre vous et chantez doucement.', title_hi = 'रात की लोरी 🎶', body_hi = 'कोई भी आवाज़ माँ की आवाज़ जितना सुकून नहीं देती। आज शाम बस उसे सीने से लगाइए और धीरे से गाइए।', title_id = 'Nina bobo malam 🎶', body_id = 'Tidak ada suara yang semenenangkan suara ibu. Malam ini, cukup dekap ia di dada dan bernyanyilah pelan.', title_ja = '夜の子守唄 🎶', body_ja = 'ママの声ほど心落ち着く音はありません。今夜はただ胸に抱きよせて、そっと歌ってあげましょう。', title_ko = '밤의 자장가 🎶', body_ko = '엄마 목소리만큼 마음을 달래 주는 소리는 없어요. 오늘 저녁은 아기를 가슴에 꼭 안고 나지막이 노래해 주세요.', title_nl = 'Een slaapliedje voor de nacht 🎶', body_nl = 'Geen geluid is zo rustgevend als mama''s stem. Houd je kleintje vanavond gewoon tegen je borst en zing zachtjes.', title_pl = 'Kołysanka na noc 🎶', body_pl = 'Żaden dźwięk nie koi tak jak głos mamy. Dziś wieczorem po prostu przytul go do piersi i cichutko mu zaśpiewaj.', title_pt = 'Canção de embalar da noite 🎶', body_pt = 'Nenhum som acalma tanto como a voz da mãe. Esta noite, aconchegue-o ao peito e cante baixinho.', title_sv = 'Vaggvisa för natten 🎶', body_sv = 'Inget ljud lugnar så som mammas röst. I kväll, håll bara barnet tätt intill bröstet och sjung tyst.', title_vi = 'Lời ru ban đêm 🎶', body_vi = 'Không âm thanh nào xoa dịu bằng giọng mẹ. Tối nay chỉ cần ôm bé vào lòng và khẽ hát cho bé nghe.', title_zh = '晚安摇篮曲 🎶', body_zh = '没有什么声音比妈妈的声音更能安抚宝宝。今晚就把宝宝抱在怀里，轻轻唱给宝宝听吧。' WHERE id = '5be2b9be-dabd-44b8-93f3-30aaaab56ccf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Intentos de gatear! 🐢', body_es = '¿Se gira boca abajo, se arrastra hacia atrás o intenta ponerse de rodillas? Añade ya estos momentos tan activos al Álbum del bebé.', title_fr = 'Premiers essais de quatre pattes ! 🐢', body_fr = 'Il roule sur le ventre, recule en rampant ou essaie de se mettre à genoux ? Ajoutez tout de suite ces moments de développement à l''Album de bébé.', title_hi = 'घुटनों के बल चलने की कोशिश! 🐢', body_hi = 'वह पेट के बल घूमता है, पीछे की ओर खिसकता है या घुटनों पर उठने की कोशिश करता है? विकास के इन चुलबुले पलों को तुरंत बेबी एल्बम में जोड़िए।', title_id = 'Mulai mencoba merangkak! 🐢', body_id = 'Ia berguling tengkurap, merayap mundur, atau mencoba bertumpu pada lutut? Segera tambahkan momen perkembangan aktif ini ke Album Bayi.', title_ja = 'はいはいに挑戦！🐢', body_ja = 'うつぶせでくるくる回ったり、後ろに進んだり、ひざで立とうとしたりしていますか？この活発な成長の瞬間を、すぐに「ベビーアルバム」に追加しましょう。', title_ko = '기어가기 도전! 🐢', body_ko = '배로 뒹굴거나 뒤로 밀려나거나 무릎으로 일어서려 하나요? 이 활발한 성장의 순간을 바로 아기 앨범에 추가하세요.', title_nl = 'Pogingen om te kruipen! 🐢', body_nl = 'Rolt je baby op de buik rond, schuift hij achteruit of probeert hij op zijn knieën te komen? Zet deze actieve momenten meteen in het Babyalbum.', title_pl = 'Próby raczkowania! 🐢', body_pl = 'Obraca się na brzuszku, pełza do tyłu albo próbuje stanąć na kolanach? Od razu dodaj te aktywne chwile rozwoju do Albumu dziecka.', title_pt = 'Tentativas de gatinhar! 🐢', body_pt = 'Rebola de barriga, arrasta-se para trás ou tenta pôr-se de joelhos? Junte já estes momentos ativos de desenvolvimento ao Álbum do Bebé.', title_sv = 'Försök att krypa! 🐢', body_sv = 'Rullar barnet på magen, ålar bakåt eller försöker resa sig upp på knäna? Lägg genast till de här aktiva utvecklingsstunderna i Babyalbumet.', title_vi = 'Tập bò! 🐢', body_vi = 'Bé lăn khi nằm sấp, trườn lùi hay cố chống gối lên? Hãy thêm ngay những khoảnh khắc phát triển năng động này vào Album của bé.', title_zh = '尝试爬行！🐢', body_zh = '宝宝趴着打转、往后退，或者想用膝盖撑起来？马上把这些活跃的成长瞬间加进宝宝相册吧。' WHERE id = '98621899-f977-46d0-ba01-3a49123c5aef' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Dudas sobre su desarrollo? 🤖', body_es = '«Mi bebé todavía no gatea, ¿es normal?»: plantea esta y otras preguntas a Anacan AI y recibe una respuesta experta.', title_fr = 'Des doutes sur son développement ? 🤖', body_fr = '« Mon bébé ne marche toujours pas à quatre pattes, est-ce normal ? » Posez cette question et les autres à Anacan AI et obtenez une réponse d''expert.', title_hi = 'विकास को लेकर उलझन है? 🤖', body_hi = 'मेरा बच्चा अभी तक घुटनों के बल नहीं चलता, क्या यह सामान्य है? यह और अपने दूसरे सवाल Anacan AI से पूछिए और विशेषज्ञ जवाब पाइए।', title_id = 'Ragu soal perkembangannya? 🤖', body_id = '"Bayiku belum merangkak, normalkah?" Tanyakan ini dan pertanyaan lainnya ke Anacan AI dan dapatkan jawaban ahli.', title_ja = '発達で気になることがありますか？🤖', body_ja = '「まだはいはいしないけど、大丈夫？」この疑問もほかの疑問も、Anacan AIに聞いて専門的な答えを受け取りましょう。', title_ko = '발달이 걱정되나요? 🤖', body_ko = '''우리 아기가 아직 안 기는데 괜찮을까?'' 이런 질문과 다른 궁금증을 Anacan AI에게 물어 전문적인 답을 받아 보세요.', title_nl = 'Twijfels over de ontwikkeling? 🤖', body_nl = 'Mijn baby kruipt nog steeds niet, is dat normaal? Stel deze en andere vragen aan Anacan AI en krijg een deskundig antwoord.', title_pl = 'Masz wątpliwości co do rozwoju? 🤖', body_pl = '„Mój maluszek jeszcze nie raczkuje, czy to normalne?” Zadaj to i inne pytania Anacan AI i otrzymaj odpowiedź eksperta.', title_pt = 'Tem dúvidas sobre o desenvolvimento? 🤖', body_pt = '"O meu bebé ainda não gatinha, é normal?" Faça esta e outras perguntas ao Anacan AI e receba uma resposta de especialista.', title_sv = 'Funderingar kring utvecklingen? 🤖', body_sv = 'Mitt barn kryper inte än, är det normalt? Ställ den här och dina andra frågor till Anacan AI och få ett expertsvar.', title_vi = 'Mẹ còn băn khoăn về sự phát triển của bé? 🤖', body_vi = '"Bé nhà mình vẫn chưa bò, có bình thường không?" Hãy hỏi Anacan AI câu này và những thắc mắc khác để nhận câu trả lời từ chuyên gia.', title_zh = '对发育有疑虑？🤖', body_zh = '“宝宝还不会爬，正常吗？”这个问题和其他疑问都可以问Anacan AI，获得专业解答。' WHERE id = 'f5a121b8-a795-4ca6-87d9-f17351b40bec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Crece tan rápido... Mientras duerme, captura sus rasgos dulces y tranquilos con la Sesión de fotos del bebé y guárdalos de recuerdo.', body_fr = 'Il grandit si vite... Pendant qu''il dort, photographiez ses doux traits paisibles avec la Séance photo bébé et gardez-en le souvenir.', body_hi = 'वह इतनी तेज़ी से बड़ा हो रहा है... सोते समय उसके प्यारे, शांत चेहरे को बेबी फ़ोटोशूट से कैद करके यादें सहेजिए।', body_id = 'Ia tumbuh begitu cepat... Abadikan wajahnya yang manis dan tenang saat tidur dengan Sesi Foto Bayi sebagai kenangan.', body_ja = '本当にあっという間に大きくなりますね...眠っている間のかわいくておだやかな顔を「ベビーフォトセッション」で撮って、思い出に残しましょう。', body_ko = '아기가 너무 빨리 자라요... 잠든 사이 그 사랑스럽고 평온한 얼굴을 아기 사진 촬영으로 찍어 추억으로 남기세요.', body_nl = 'Je baby groeit zo snel... Leg dat lieve, rustige slaapgezichtje vast met Babyfotoshoot en bewaar het als herinnering.', body_pl = 'Rośnie tak szybko... Uchwyć jego słodkie, spokojne rysy podczas snu w Sesji zdjęciowej dziecka i zachowaj je na pamiątkę.', body_pt = 'Cresce tão depressa... Enquanto dorme, fotografe aqueles traços doces e tranquilos com a Sessão Fotográfica do Bebé e guarde a recordação.', body_sv = 'Barnet växer så fort... Fånga de söta, lugna ansiktsdragen när det sover med Babyfotografering och spara minnet.', body_vi = 'Bé lớn nhanh quá... Khi bé ngủ, hãy dùng Chụp ảnh cho bé để lưu lại gương mặt ngọt ngào, bình yên ấy làm kỷ niệm.', body_zh = '宝宝长得太快了……趁宝宝睡着，用宝宝写真拍下那张甜美安详的小脸，留作纪念吧。' WHERE id = '07efb31a-2639-41f8-b1c7-f3807d010a8f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Tienes mil preguntas sobre la alimentación complementaria y cuándo darle agua? Escribe a Anacan AI y recibe consejos pediátricos precisos.', body_fr = 'Mille questions sur la diversification et l''eau vous trottent dans la tête ? Écrivez à Anacan AI et obtenez des conseils pédiatriques précis.', body_hi = 'ऊपरी आहार और पानी देने को लेकर मन में हज़ारों सवाल हैं? Anacan AI को लिखिए और बच्चों के डॉक्टर जैसी सटीक सलाह पाइए।', body_id = 'Ada ribuan pertanyaan di kepala Anda tentang MPASI dan pemberian air? Tanyakan ke Anacan AI dan dapatkan saran pediatri yang tepat.', body_ja = '離乳食や水の与え方について、頭の中が疑問でいっぱい？Anacan AIに聞いて、小児科医の視点からの正確なアドバイスを受け取りましょう。', body_ko = '이유식과 물 주기에 대한 질문이 머릿속에 가득한가요? Anacan AI에게 물어 정확한 소아과 조언을 받아 보세요.', body_nl = 'Zit je hoofd vol met vragen over bijvoeding en water geven? Schrijf naar Anacan AI en krijg precieze adviezen van een kinderarts.', body_pl = 'Masz w głowie tysiące pytań o rozszerzanie diety i podawanie wody? Napisz do Anacan AI i otrzymaj rzetelne porady pediatryczne.', body_pt = 'Tem mil perguntas na cabeça sobre a diversificação alimentar e a água? Escreva ao Anacan AI e receba conselhos pediátricos precisos.', body_sv = 'Har du tusentals frågor om smakportioner och att ge vatten? Skriv till Anacan AI och få exakta barnläkarråd.', body_vi = 'Trong đầu có hàng nghìn câu hỏi về ăn dặm và cho bé uống nước? Hãy hỏi Anacan AI để nhận lời khuyên nhi khoa chính xác.', body_zh = '关于添加辅食和喝水，你有成千上万个问题？问问Anacan AI，获得准确的儿科建议。' WHERE id = '7deb7b07-a963-4605-b27c-7714e980157d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Te conozco! 🥰', body_es = '¿Se refugia en ti cuando viene alguien desconocido a casa? No te preocupes, solo sabe distinguir a los suyos de los extraños. Es un desarrollo mental sano.', title_fr = 'Je te reconnais ! 🥰', body_fr = 'Il se réfugie contre vous quand un inconnu vient à la maison ? Pas d''inquiétude, il sait simplement distinguer ses proches des inconnus. C''est un signe de bon développement intellectuel.', title_hi = 'मैं आपको पहचानता हूँ! 🥰', body_hi = 'घर में कोई अनजान आए तो वह आपसे चिपक जाता है? डरिए मत, वह बस अपनों और अनजानों में फ़र्क करना सीख गया है। यह सेहतमंद मानसिक विकास है।', title_id = 'Aku kenal Anda! 🥰', body_id = 'Ia berlindung pada Anda saat ada orang asing datang? Jangan khawatir, ia hanya sudah bisa membedakan orang dekat dan orang asing. Ini tanda perkembangan otak yang sehat.', title_ja = 'ママだってわかるよ！🥰', body_ja = '知らない人が家に来ると、あなたにしがみつきますか？心配しないで、家族と知らない人を区別できるようになったのです。健やかな心の発達のしるしです。', title_ko = '엄마를 알아요! 🥰', body_ko = '낯선 사람이 오면 엄마에게 숨나요? 걱정 마세요, 익숙한 사람과 낯선 사람을 구별할 수 있게 된 거예요. 건강한 인지 발달이에요.', title_nl = 'Ik ken jou! 🥰', body_nl = 'Kruipt je baby tegen je aan als er een vreemde op bezoek komt? Geen zorgen, hij kan bekenden en vreemden nu gewoon van elkaar onderscheiden. Dat is een gezonde ontwikkeling.', title_pl = 'Znam cię! 🥰', body_pl = 'Gdy do domu przychodzi ktoś obcy, tuli się do ciebie? Nie bój się, po prostu odróżnia bliskich od obcych. To zdrowy rozwój umysłowy.', title_pt = 'Eu conheço-te! 🥰', body_pt = 'Quando chega um estranho a casa, ele refugia-se em si? Não se assuste, ele já distingue os próximos dos estranhos. É um desenvolvimento mental saudável.', title_sv = 'Jag känner igen dig! 🥰', body_sv = 'Söker barnet skydd hos dig när någon främmande kommer hem? Var inte rädd, barnet kan bara skilja på nära och främmande. Det är en sund mental utveckling.', title_vi = 'Con nhận ra mẹ! 🥰', body_vi = 'Khi có người lạ đến nhà, bé nép vào mẹ? Đừng lo, bé chỉ đang phân biệt được người thân với người lạ. Đây là sự phát triển trí tuệ khỏe mạnh.', title_zh = '我认识你！🥰', body_zh = '家里来了陌生人，宝宝就往你怀里躲？别担心，宝宝只是能分清亲人和陌生人了。这是健康的智力发育。' WHERE id = 'ab8df92e-4241-44fb-8ac7-10559ea60a6f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Un baño templado, un masaje suave y la habitación a oscuras... La rutina de sueño es la regla de oro.', body_fr = 'Un bain tiède, un massage doux et une pièce assombrie... La routine du coucher, c''est la règle d''or.', body_hi = 'गुनगुना स्नान, हल्की मालिश और कमरे में अँधेरा... सोने का रूटीन सुनहरा नियम है।', body_id = 'Mandi air hangat, pijatan lembut, dan kamar yang diredupkan... Rutinitas tidur adalah aturan emas.', body_ja = 'ぬるめのお風呂、やさしいマッサージ、部屋を暗くする...ねんねのルーティンは黄金のルールです。', body_ko = '따뜻한 목욕, 부드러운 마사지, 어두운 방... 잠자리 루틴은 황금 규칙이에요.', body_nl = 'Een lauw badje, een zachte massage en een verduisterde kamer... De slaaproutine is een gouden regel.', body_pl = 'Ciepła kąpiel, delikatny masaż i przyciemniony pokój... Rytuał snu to złota zasada.', body_pt = 'Um banho morno, uma massagem suave e o quarto escurecido... A rotina de sono é a regra de ouro.', body_sv = 'Ett ljummet bad, mjuk massage och ett mörkt rum... Sömnrutinen är den gyllene regeln.', body_vi = 'Tắm nước ấm, mát-xa nhẹ nhàng và làm tối phòng... Nếp sinh hoạt trước khi ngủ là quy tắc vàng.', body_zh = '温水澡、轻柔的按摩、调暗房间……睡前作息是黄金法则。' WHERE id = 'a8ca5021-abaf-413e-abe5-95d715e5127d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Descubriendo sabores nuevos! 🍎', body_es = '¿Qué fruta o verdura vas a probar hoy? Para inspirarte, no dejes de mirar las Recetas para bebés que empiezan con la alimentación complementaria.', title_fr = 'De nouvelles saveurs à découvrir ! 🍎', body_fr = 'Quel fruit ou légume allez-vous tester aujourd''hui ? Pour vous inspirer, consultez les Recettes pour bébés qui commencent la diversification.', title_hi = 'नए स्वादों की खोज! 🍎', body_hi = 'आज कौन सा फल या सब्ज़ी आज़माएँगी? प्रेरणा के लिए ऊपरी आहार शुरू करने वाले बच्चों की रेसिपी ज़रूर देखिए।', title_id = 'Petualangan rasa baru! 🍎', body_id = 'Buah atau sayur apa yang akan dicoba hari ini? Untuk inspirasi, lihat Resep untuk bayi yang mulai MPASI.', title_ja = '新しい味の発見！🍎', body_ja = '今日はどの果物や野菜を試しますか？アイデアがほしいときは、「離乳食を始める赤ちゃんのレシピ」をぜひ見てみましょう。', title_ko = '새로운 맛 탐험! 🍎', body_ko = '오늘은 어떤 과일이나 채소를 시도해 볼까요? 영감을 얻으려면 이유식을 시작하는 아기를 위한 레시피를 꼭 확인하세요.', title_nl = 'Nieuwe smaken ontdekken! 🍎', body_nl = 'Welke fruit- of groentesoort proberen jullie vandaag? Kijk voor inspiratie zeker bij de Recepten voor baby''s die met bijvoeding beginnen.', title_pl = 'Odkrywanie nowych smaków! 🍎', body_pl = 'Jaki owoc lub warzywo sprawdzicie dziś? Po inspirację koniecznie zajrzyj do Przepisów dla maluszków zaczynających rozszerzanie diety.', title_pt = 'Novos sabores para descobrir! 🍎', body_pt = 'Que fruta ou legume vai experimentar hoje? Para se inspirar, veja sem falta as Receitas para bebés em diversificação alimentar.', title_sv = 'Nya smakupptäckter! 🍎', body_sv = 'Vilken frukt eller grönsak ska ni testa i dag? Titta absolut i Recept för barn som börjar med smakportioner för inspiration.', title_vi = 'Khám phá hương vị mới! 🍎', body_vi = 'Hôm nay mẹ sẽ cho bé thử loại quả hay rau củ nào? Để có thêm ý tưởng, nhất định hãy xem Công thức cho bé bắt đầu ăn dặm.', title_zh = '探索新味道！🍎', body_zh = '今天要尝试哪种水果或蔬菜？想找灵感，一定要看看“辅食宝宝食谱”。' WHERE id = '17a57fd8-a4e1-4a40-b13f-cad6191dae2a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche crea en Cuentos inteligentes la historia de un niño valiente y listo.', body_fr = 'Ce soir, créez dans les Contes intelligents l''histoire d''un enfant courageux et malin.', body_hi = 'आज शाम स्मार्ट कहानियों में एक बहादुर और समझदार बच्चे की कहानी बनाइए।', body_id = 'Malam ini, di Dongeng Pintar, buat kisah tentang anak yang berani dan cerdas.', body_ja = '今夜は「スマートおはなし」で、勇敢でかしこい子どものお話をつくりましょう。', body_ko = '오늘 저녁 스마트 동화에서 용감하고 똑똑한 아이의 이야기를 만들어 보세요.', body_nl = 'Maak vanavond in Slimme sprookjes het verhaal van een dapper en slim kind.', body_pl = 'Dziś wieczorem stwórz w Mądrych bajkach historię o odważnym i mądrym dziecku.', body_pt = 'Esta noite, crie nas Histórias Inteligentes a história de uma criança corajosa e esperta.', body_sv = 'Skapa sagan om det modiga och kloka barnet i Smarta sagor i kväll.', body_vi = 'Tối nay hãy tạo câu chuyện về một em bé dũng cảm và thông minh trong Truyện cổ tích thông minh.', body_zh = '今晚在智能故事里创作一个勇敢又聪明的孩子的故事吧。' WHERE id = 'b98f5eb2-8b81-4c72-8526-61cc728e9e49' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Te mira e inventa sílabas distintas. Ahora mismo te está dando el concierto matutino más bonito, ¡escúchale con atención!', body_fr = 'Il vous regarde et invente différentes syllabes. Il vous donne en ce moment le plus beau concert du matin, écoutez bien !', body_hi = 'आपको देखकर अलग-अलग अक्षर बोलता है। वह इस समय कमरे में सबसे प्यारा सुबह का कॉन्सर्ट दे रहा है, ध्यान से सुनिए!', body_id = 'Ia menatap Anda sambil merangkai berbagai suku kata. Ia sedang memberi konser pagi terindah di kamar, dengarkan baik-baik!', body_ja = 'あなたを見て、いろいろな音を出しています。今、部屋でいちばんすてきな朝のコンサートを開いています。よく聞いてあげて！', body_ko = '엄마를 보며 여러 소리를 지어내요. 지금 방 안에서 가장 아름다운 아침 콘서트가 열리고 있어요, 귀 기울여 들어 보세요!', body_nl = 'Je baby kijkt je aan en verzint allerlei lettergrepen. Hij geeft nu het mooiste ochtendconcert in de kamer, luister goed!', body_pl = 'Patrzy na ciebie i wymyśla różne sylaby. Właśnie daje w pokoju najpiękniejszy poranny koncert, posłuchaj uważnie!', body_pt = 'Olha para si e inventa sílabas diferentes. Está a dar o mais bonito concerto da manhã, ouça com atenção!', body_sv = 'Barnet tittar på dig och hittar på olika stavelser. Just nu ger det den vackraste morgonkonserten i rummet, lyssna noga!', body_vi = 'Bé nhìn mẹ và bập bẹ những âm khác nhau. Bé đang tổ chức buổi hòa nhạc buổi sáng tuyệt vời nhất ngay trong phòng đấy, hãy lắng nghe thật kỹ!', body_zh = '宝宝看着你，发出各种音节。宝宝正在房间里开一场最美的早晨音乐会，好好听吧！' WHERE id = '0ced9920-5225-4ffc-81ba-de83e31f1bd2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lista como un médico 🤖', body_es = '¿Han cambiado sus cacas desde que toma sólidos? En vez de preocuparte, pregunta a Anacan AI si es normal.', title_fr = 'Aussi malin qu''un médecin 🤖', body_fr = 'Ses selles ont changé depuis le début des aliments solides ? Plutôt que de vous inquiéter, demandez à Anacan AI si c''est normal.', title_hi = 'डॉक्टर जितना समझदार 🤖', body_hi = 'ठोस आहार शुरू करने के बाद उसका मल बदल गया है? चिंता करने के बजाय Anacan AI से पूछिए कि यह सामान्य है या नहीं।', title_id = 'Cerdas seperti dokter 🤖', body_id = 'BAB-nya berubah setelah mulai makanan padat? Daripada panik, tanyakan ke Anacan AI apakah ini normal.', title_ja = 'お医者さんのように賢い 🤖', body_ja = '離乳食を始めてから、うんちが変わった？心配する前に、Anacan AIにこれが普通かどうか聞いてみましょう。', title_ko = '의사처럼 똑똑하게 🤖', body_ko = '고형식을 시작한 뒤 변이 달라졌나요? 걱정하기보다 Anacan AI에게 정상인지 물어보세요.', title_nl = 'Zo slim als een dokter 🤖', body_nl = 'Is de ontlasting veranderd sinds de start met vast voedsel? Raak niet in paniek, maar vraag Anacan AI of dat normaal is.', title_pl = 'Mądry jak lekarz 🤖', body_pl = 'Po przejściu na stałe pokarmy zmieniły się kupki? Zamiast się martwić, zapytaj Anacan AI, czy to normalne.', title_pt = 'Inteligente como um médico 🤖', body_pt = 'As fezes mudaram depois de começar os sólidos? Em vez de se alarmar, pergunte ao Anacan AI se é normal.', title_sv = 'Smart som en läkare 🤖', body_sv = 'Har bajset ändrats sedan ni började med fast föda? I stället för att oroa dig, fråga Anacan AI om det är normalt.', title_vi = 'Thông minh như bác sĩ 🤖', body_vi = 'Phân của bé thay đổi sau khi ăn dặm? Thay vì lo lắng, hãy hỏi Anacan AI xem điều đó có bình thường không.', title_zh = '像医生一样聪明 🤖', body_zh = '开始吃固体食物后，大便变了？与其担心，不如问问Anacan AI这是否正常。' WHERE id = 'db243270-0483-44d0-9aef-b63565c06a9e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Acostumbrarse a la oscuridad 🌙', title_fr = 'S''habituer à l''obscurité 🌙', title_hi = 'अँधेरे की आदत 🌙', title_id = 'Terbiasa dengan gelap 🌙', title_ja = '暗さに慣れよう 🌙', title_ko = '어둠에 익숙해지기 🌙', title_nl = 'Wennen aan het donker 🌙', title_pl = 'Oswajanie z ciemnością 🌙', title_pt = 'Habituar-se ao escuro 🌙', title_sv = 'Vänja sig vid mörkret 🌙', title_vi = 'Làm quen với bóng tối 🌙', title_zh = '适应黑暗 🌙' WHERE id = 'd88a96c2-0998-4bcd-a181-952127acf518' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de noche de papá 👨‍🍼', body_es = 'Ya tienes bastante con el cansancio del día. Esta tarde deja en manos de papá prepararle para dormir y ponerle el pijama, y tú simplemente mira.', title_fr = 'Le service de nuit de papa 👨‍🍼', body_fr = 'La fatigue de la journée vous suffit. En fin de journée, confiez à papa la préparation au coucher et la mise en pyjama, et contentez-vous de regarder.', title_hi = 'पापा की रात की ड्यूटी 👨‍🍼', body_hi = 'दिन की थकान आपके लिए काफ़ी है। शाम को बच्चे को सोने के लिए तैयार करना और पजामा पहनाना पापा को सौंप दीजिए और बस दूर से देखिए।', title_id = 'Giliran malam ayah 👨‍🍼', body_id = 'Lelah seharian sudah cukup bagi Anda. Serahkan persiapan tidur dan memakaikan piyama kepada ayah, dan cukup lihat dari jauh.', title_ja = 'パパの夜の当番 👨‍🍼', body_ja = '昼間の疲れだけでもう十分。夕方は寝る準備とパジャマのお着替えをパパにまかせて、あなたは見守るだけにしましょう。', title_ko = '아빠의 밤 당번 👨‍🍼', body_ko = '낮의 피로로 충분해요. 저녁에 아이를 재울 준비를 하고 잠옷을 입히는 일은 아빠에게 맡기고 곁에서 지켜보기만 하세요.', title_nl = 'Papa''s avonddienst 👨‍🍼', body_nl = 'De vermoeidheid van overdag is genoeg voor jou. Laat papa ''s avonds je baby klaarmaken voor bed en zijn pyjama aantrekken, en kijk gewoon toe.', title_pl = 'Nocna zmiana taty 👨‍🍼', body_pl = 'Wystarczy ci dziennego zmęczenia. Pod wieczór powierz tacie przygotowanie maluszka do snu i zakładanie piżamki, a sama tylko patrz z boku.', title_pt = 'O turno da noite do pai 👨‍🍼', body_pt = 'O cansaço do dia já chega. Ao fim do dia, deixe ao pai a tarefa de preparar o bebé para dormir e vestir-lhe o pijama, e limite-se a assistir.', title_sv = 'Pappas nattskift 👨‍🍼', body_sv = 'Dagens trötthet räcker för dig. Låt pappa ta hand om att göra barnet redo för sömnen och sätta på pyjamasen i kväll, och titta bara på från sidan.', title_vi = 'Ca đêm của bố 👨‍🍼', body_vi = 'Mệt mỏi ban ngày đã đủ với mẹ rồi. Chiều tối nay, hãy giao việc chuẩn bị cho bé đi ngủ và thay đồ ngủ cho bố, còn mẹ chỉ cần ngắm từ xa.', title_zh = '爸爸的夜班 👨‍🍼', body_zh = '白天的疲惫已经够你受了。今晚把哄睡准备和换睡衣的事交给爸爸，你只在一旁看着就好。' WHERE id = '08e4a521-2f7a-4298-b56b-2d48b11d0ee9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Manchas rebeldes 👗', title_fr = 'Des taches tenaces 👗', title_hi = 'ज़िद्दी दाग 👗', title_id = 'Noda yang membandel 👗', title_ja = 'しつこい汚れ 👗', title_ko = '지워지지 않는 얼룩 👗', title_nl = 'Hardnekkige vlekken 👗', title_pl = 'Uparte plamy 👗', title_pt = 'Nódoas teimosas 👗', title_sv = 'Envisa fläckar 👗', title_vi = 'Vết bẩn cứng đầu 👗', title_zh = '顽固的污渍 👗' WHERE id = '7d1bf85e-e587-4da1-8ee8-b719514d8f71' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Baño templado, masaje y habitación a oscuras... No rompas nunca la rutina de sueño y tendréis noches tranquilas.', body_fr = 'Bain tiède, massage et pièce assombrie... Ne brisez jamais la routine du coucher pour passer des nuits paisibles.', body_hi = 'गुनगुना स्नान, मालिश और कमरे में अँधेरा... सोने का रूटीन कभी मत तोड़िए, ताकि आपकी रातें आराम से बीतें।', body_id = 'Mandi air hangat, pijat, dan kamar yang diredupkan... Jangan pernah melewatkan rutinitas tidur agar malam Anda tenang.', body_ja = 'ぬるめのお風呂、マッサージ、部屋を暗くする...夜をおだやかに過ごせるように、ねんねのルーティンは決して崩さないで。', body_ko = '따뜻한 목욕, 마사지, 어두운 방... 편안한 밤을 위해 잠자리 루틴은 절대 깨지 마세요.', body_nl = 'Een lauw badje, een massage en een verduisterde kamer... Doorbreek de slaaproutine nooit, zodat jullie nachten rustig verlopen.', body_pl = 'Ciepła kąpiel, masaż i przyciemniony pokój... Nigdy nie łam rytuału snu, a noce będą spokojne.', body_pt = 'Banho morno, massagem e quarto escurecido... Nunca quebre a rotina de sono, para ter noites tranquilas.', body_sv = 'Ett ljummet bad, massage och ett mörkt rum... Bryt aldrig sömnrutinen, så blir nätterna lugna.', body_vi = 'Tắm nước ấm, mát-xa và làm tối phòng... Đừng bao giờ phá vỡ nếp sinh hoạt trước khi ngủ để những đêm của mẹ được yên giấc.', body_zh = '温水澡、按摩、调暗房间……千万别打乱睡前作息，夜晚才能过得安稳。' WHERE id = 'f06a8dcb-51df-4b58-a9ac-01e5154e736a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡Ya ha descubierto los dedos de sus pies y se los lleva a la boca! No te pierdas este momento tan gracioso y disfruta de su desarrollo.', body_fr = 'Il a découvert ses orteils et les porte à sa bouche ! Ne manquez pas ce moment drôle et savourez ses progrès.', body_hi = 'उसने अपने पैरों की उँगलियाँ खोज ली हैं और उन्हें मुँह में डाल रहा है! इस मज़ेदार पल को ज़रूर देखिए और उसके विकास का आनंद लीजिए।', body_id = 'Ia sudah menemukan jari kakinya dan memasukkannya ke mulut! Saksikan momen lucu ini dan nikmati perkembangannya.', body_ja = '自分の足の指を発見して、口に入れています！このおもしろい瞬間をしっかり見守って、成長を楽しみましょう。', body_ko = '이제 자기 발가락을 발견하고 입으로 가져가요! 이 귀여운 순간을 꼭 지켜보며 성장을 즐기세요.', body_nl = 'Je baby heeft de eigen teentjes ontdekt en stopt ze in de mond! Kijk zeker naar dit grappige moment en geniet van zijn ontwikkeling.', body_pl = 'Odkrył już swoje paluszki u stóp i wkłada je do buzi! Koniecznie obserwuj ten zabawny moment i ciesz się jego rozwojem.', body_pt = 'Já descobriu os dedos dos pés e leva-os à boca! Não perca este momento divertido e aproveite cada etapa do desenvolvimento.', body_sv = 'Barnet har redan upptäckt sina tår och stoppar dem i munnen! Titta absolut på det här roliga ögonblicket och njut av utvecklingen.', body_vi = 'Bé đã phát hiện ra ngón chân và đưa vào miệng! Nhất định hãy ngắm khoảnh khắc buồn cười này và tận hưởng sự phát triển của bé.', body_zh = '宝宝发现了自己的脚趾，还放进嘴里！一定要看看这个有趣的瞬间，享受宝宝的成长吧。' WHERE id = '19aba970-f2bf-4842-9b69-4aed1781aeec' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El amigo del espejo 👀', title_fr = 'Le copain du miroir 👀', title_hi = 'आईने वाला दोस्त 👀', title_id = 'Teman di dalam cermin 👀', title_ja = '鏡の中のお友達 👀', title_ko = '거울 속 친구 👀', title_nl = 'Een vriendje in de spiegel 👀', title_pl = 'Przyjaciel w lustrze 👀', title_pt = 'O amigo do espelho 👀', title_sv = 'Kompisen i spegeln 👀', title_vi = 'Người bạn trong gương 👀', title_zh = '镜子里的小伙伴 👀' WHERE id = 'f3bd302c-47f2-4428-b12d-4062c2445dfe' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La leche materna sigue siendo lo principal! 🍼', body_es = 'Aunque ya tome alimentación complementaria, usa el temporizador de tomas para asegurarte de que cubre su necesidad diaria de leche.', title_fr = 'Le lait maternel reste essentiel ! 🍼', body_fr = 'Malgré la diversification, lancez le minuteur de repas pour vous assurer que ses besoins quotidiens en lait sont couverts.', title_hi = 'माँ का दूध अब भी सबसे अहम है! 🍼', body_hi = 'ऊपरी आहार के बावजूद फ़ीडिंग टाइमर चालू करके पक्का कीजिए कि रोज़ की दूध की ज़रूरत पूरी हो रही है।', title_id = 'ASI tetap yang utama! 🍼', body_id = 'Meski sudah MPASI, nyalakan timer menyusui dan pastikan kebutuhan susu hariannya terpenuhi.', title_ja = '母乳・ミルクはまだ主役！🍼', body_ja = '離乳食を始めても、授乳タイマーを使って1日に必要なミルクの量をとれているか確かめましょう。', title_ko = '모유는 여전히 중요해요! 🍼', body_ko = '이유식을 하더라도 수유 타이머를 켜서 하루 수유량이 충분한지 확인하세요.', title_nl = 'Moedermelk is nog steeds de basis! 🍼', body_nl = 'Ook met bijvoeding: zet de voedingstimer aan en zorg ervoor dat je baby dagelijks genoeg melk krijgt.', title_pl = 'Mleko mamy wciąż jest podstawą! 🍼', body_pl = 'Mimo rozszerzania diety włączaj timer karmienia i upewnij się, że dzienne zapotrzebowanie na mleko jest zaspokojone.', title_pt = 'O leite materno continua a ser a base! 🍼', body_pt = 'Mesmo com a diversificação alimentar, ligue o temporizador de alimentação e confirme que as necessidades diárias de leite estão cobertas.', title_sv = 'Bröstmjölken är fortfarande grunden! 🍼', body_sv = 'Trots smakportionerna, se till att det dagliga mjölkbehovet täcks genom att starta matningstimern.', title_vi = 'Sữa mẹ vẫn là chính! 🍼', body_vi = 'Dù đã ăn dặm, hãy bật Hẹn giờ cho bú để chắc chắn bé được đáp ứng đủ nhu cầu sữa mỗi ngày.', title_zh = '母乳仍然是主角！🍼', body_zh = '即使添加了辅食，也要用喂养计时器确认宝宝每天的奶量需求得到满足。' WHERE id = '6b5eb8f2-b9ae-4f72-adf0-630e10588b7d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Buscas recetas de alimentación complementaria? Entra en la sección Recetas saludables y aprovéchalas.', body_fr = 'Vous cherchez des recettes pour la diversification ? Rendez-vous dans la rubrique Recettes saines et profitez-en.', body_hi = 'ऊपरी आहार की रेसिपी ढूँढ रही हैं? सेहतमंद रेसिपी सेक्शन खोलिए और फ़ायदा उठाइए।', body_id = 'Mencari resep MPASI? Buka bagian Resep Sehat dan manfaatkan.', body_ja = '離乳食のレシピを探していますか？「ヘルシーレシピ」セクションをのぞいて、役立ててください。', body_ko = '이유식 레시피를 찾고 있나요? 건강한 레시피 섹션에서 도움을 받아 보세요.', body_nl = 'Op zoek naar recepten voor bijvoeding? Ga naar het onderdeel Gezonde recepten en laat je inspireren.', body_pl = 'Szukasz przepisów na rozszerzanie diety? Zajrzyj do sekcji Zdrowe przepisy i skorzystaj z nich.', body_pt = 'Procura receitas para a diversificação alimentar? Entre na secção Receitas Saudáveis e aproveite.', body_sv = 'Letar du efter recept på smakportioner? Gå in i avsnittet Hälsosamma recept och ta del av dem.', body_vi = 'Mẹ đang tìm công thức ăn dặm? Hãy vào mục Công thức lành mạnh và tham khảo nhé.', body_zh = '在找辅食食谱？去健康食谱板块看看吧。' WHERE id = 'c2924eec-8b24-41b0-b28a-f63497f548c2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Cada vez intenta gatear más! 🐢', body_es = '¿Se arrastra hacia atrás boca abajo o intenta ponerse de rodillas? Inmortaliza estos momentos tan activos en el Álbum del bebé.', title_fr = 'Les essais de quatre pattes se multiplient ! 🐢', body_fr = 'Il recule en rampant sur le ventre ou essaie de se mettre à genoux ? Immortalisez ces moments de développement dans l''Album de bébé.', title_hi = 'घुटनों के बल चलने की कोशिशें बढ़ रही हैं! 🐢', body_hi = 'वह पेट के बल पीछे की ओर खिसकता है या घुटनों पर उठने की कोशिश करता है? विकास के इन चुलबुले पलों को बेबी एल्बम में हमेशा के लिए सहेजिए।', title_id = 'Usaha merangkak makin sering! 🐢', body_id = 'Ia merayap mundur saat tengkurap atau mencoba bertumpu pada lutut? Abadikan momen perkembangan aktif ini di Album Bayi.', title_ja = 'はいはいへの挑戦が増えてきた！🐢', body_ja = 'うつぶせで後ろに進んだり、ひざで立とうとしたりしていますか？この活発な成長の瞬間を「ベビーアルバム」に残しましょう。', title_ko = '기어가기 도전이 늘고 있어요! 🐢', body_ko = '배로 뒤로 밀려나거나 무릎으로 일어서려 하나요? 이 활발한 성장의 순간을 아기 앨범에 영원히 남기세요.', title_nl = 'Steeds meer kruippogingen! 🐢', body_nl = 'Schuift je baby op de buik achteruit of probeert hij op zijn knieën te komen? Leg deze actieve momenten vast in het Babyalbum.', title_pl = 'Coraz więcej prób raczkowania! 🐢', body_pl = 'Pełza na brzuszku do tyłu albo próbuje stanąć na kolanach? Uwiecznij te aktywne chwile rozwoju w Albumie dziecka.', title_pt = 'As tentativas de gatinhar aumentam! 🐢', body_pt = 'Arrasta-se para trás de barriga para baixo ou tenta pôr-se de joelhos? Eternize estes momentos ativos de desenvolvimento no Álbum do Bebé.', title_sv = 'Krypförsöken blir fler! 🐢', body_sv = 'Ålar barnet bakåt på magen eller försöker resa sig upp på knäna? Förevig de här aktiva utvecklingsstunderna i Babyalbumet.', title_vi = 'Bé tập bò nhiều hơn! 🐢', body_vi = 'Bé trườn lùi khi nằm sấp hay cố chống gối lên? Hãy lưu giữ những khoảnh khắc phát triển năng động này trong Album của bé.', title_zh = '爬行尝试越来越多！🐢', body_zh = '宝宝趴着往后退，或者想用膝盖撑起来？在宝宝相册里永久留下这些活跃的成长瞬间吧。' WHERE id = '2d910805-1ce0-44fc-88f6-f3f6dfe16cea' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Crear una buena rutina de sueño es muy importante. No rompas nunca la rutina y tendréis noches tranquilas.', body_fr = 'Mettre en place un bon rythme de sommeil est très important. Ne brisez jamais la routine pour passer des nuits paisibles.', body_hi = 'सही नींद का रूटीन बनाना बहुत ज़रूरी है। रूटीन कभी मत तोड़िए, ताकि आपकी रातें आराम से बीतें।', body_id = 'Membangun pola tidur yang baik sangat penting. Jangan pernah melewatkan rutinitasnya agar malam Anda tenang.', body_ja = 'きちんとした睡眠リズムをつくることはとても大切です。夜をおだやかに過ごせるように、ルーティンは決して崩さないで。', body_ko = '올바른 수면 습관을 만드는 건 정말 중요해요. 편안한 밤을 위해 루틴은 절대 깨지 마세요.', body_nl = 'Een goed slaapritme opbouwen is heel belangrijk. Doorbreek de routine nooit, zodat jullie nachten rustig verlopen.', body_pl = 'Ustalenie dobrego rytmu snu jest bardzo ważne. Nigdy nie łam rytuału, a noce będą spokojne.', body_pt = 'Criar uma boa rotina de sono é muito importante. Nunca quebre a rotina, para ter noites tranquilas.', body_sv = 'Det är väldigt viktigt att skapa en bra sömnrutin. Bryt aldrig rutinen, så blir nätterna lugna.', body_vi = 'Xây dựng nếp ngủ đúng cách rất quan trọng. Đừng bao giờ phá vỡ nếp sinh hoạt để những đêm của mẹ được yên giấc.', body_zh = '建立正确的睡眠作息非常重要。千万别打乱作息，夜晚才能过得安稳。' WHERE id = '21fef948-0fab-41a2-932d-5efc89cc4b78' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡FALTA 1 DÍA PARA LOS 200 DÍAS! 🎂', body_es = '¡Mañana cumple 200 días! ¿Has pensado cómo vais a celebrar esta cifra tan grande y bonita? ¡Empieza con los preparativos!', title_fr = 'J-1 AVANT LES 200 JOURS ! 🎂', body_fr = 'Demain, vous fêtez les 200 jours ! Avez-vous pensé à la façon de célébrer ce chiffre énorme et magnifique ? Commencez les préparatifs !', title_hi = '200 दिन में 1 दिन बाकी! 🎂', body_hi = 'कल आप 200 दिन पूरे कर लेंगे! इस बड़े और खूबसूरत आँकड़े का जश्न कैसे मनाएँगे, सोचा है? तैयारी शुरू कीजिए!', title_id = '1 HARI LAGI MENUJU 200 HARI! 🎂', body_id = 'Besok genap 200 hari! Sudah terpikir bagaimana merayakan angka besar dan indah ini? Mulai persiapannya!', title_ja = '200日まであと1日！🎂', body_ja = '明日で生後200日！この大きくてすてきな数字をどうお祝いするか考えましたか？準備を始めましょう！', title_ko = '200일까지 1일! 🎂', body_ko = '내일이면 200일이에요! 이 크고 멋진 숫자를 어떻게 기념할지 생각해 보셨나요? 준비를 시작하세요!', title_nl = 'NOG 1 DAG TOT 200 DAGEN! 🎂', body_nl = 'Morgen zijn jullie 200 dagen samen! Heb je al bedacht hoe je dit enorme, mooie getal gaat vieren? Begin met de voorbereidingen!', title_pl = 'DO 200 DNI ZOSTAŁ 1 DZIEŃ! 🎂', body_pl = 'Jutro mija wam 200 dni! Myślałaś już, jak uczcić tę ogromną i piękną liczbę? Zacznij przygotowania!', title_pt = 'FALTA 1 DIA PARA OS 200 DIAS! 🎂', body_pt = 'Amanhã fazem 200 dias! Já pensou em como vai celebrar este número enorme e bonito? Comece os preparativos!', title_sv = '1 DAG KVAR TILL 200 DAGAR! 🎂', body_sv = 'I morgon fyller barnet 200 dagar! Har du funderat på hur ni ska fira den här stora och fina siffran? Börja förbereda!', title_vi = 'CHỈ CÒN 1 NGÀY NỮA LÀ 200 NGÀY! 🎂', body_vi = 'Ngày mai là tròn 200 ngày! Mẹ đã nghĩ sẽ ăn mừng con số lớn và đẹp này thế nào chưa? Bắt đầu chuẩn bị thôi!', title_zh = '距离200天还有1天！🎂', body_zh = '明天就满200天啦！想好怎么庆祝这个了不起的数字了吗？开始准备吧！' WHERE id = '29cfcc36-87ce-4b4b-b753-dcd4b0ef2352' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Recuerda los miedos de los primeros días. Y ahora mírate: toda una experta en alimentación complementaria. ¡Siéntete orgullosa de ti!', body_fr = 'Rappelez-vous vos peurs des premiers jours. Et regardez-vous maintenant : une maman pro de la diversification. Soyez fière de vous !', body_hi = 'शुरुआती दिनों के अपने डर याद कीजिए। और अब देखिए, आप ऊपरी आहार देने वाली माहिर माँ बन गई हैं। खुद पर गर्व कीजिए!', body_id = 'Ingat ketakutan Anda di hari-hari pertama. Sekarang lihat, Anda sudah jadi ibu andal yang memberi MPASI. Banggalah pada diri sendiri!', body_ja = '最初のころの不安を思い出してみて。今では離乳食もこなすベテランママになりました。自分を誇りに思って！', body_ko = '처음 며칠의 두려움을 떠올려 보세요. 그리고 지금 이유식을 척척 하는 능숙한 엄마가 된 모습을 보세요. 스스로를 자랑스러워하세요!', body_nl = 'Denk terug aan je angsten in de eerste dagen. En kijk nu hoe je een echte prof bent geworden die hapjes geeft. Wees trots op jezelf!', body_pl = 'Przypomnij sobie swoje lęki z pierwszych dni. A teraz zobacz, jak stałaś się mamą-profesjonalistką, która rozszerza dietę. Bądź z siebie dumna!', body_pt = 'Lembre-se dos medos dos primeiros dias. E agora veja como se tornou uma mãe profissional que já faz a diversificação alimentar. Orgulhe-se de si!', body_sv = 'Minns dina rädslor från de första dagarna. Och se nu hur du har blivit en proffsmamma som ger smakportioner. Var stolt över dig själv!', body_vi = 'Hãy nhớ lại những nỗi lo của ngày đầu. Còn giờ hãy nhìn xem, mẹ đã thành người mẹ chuyên nghiệp cho bé ăn dặm. Hãy tự hào về mình!', body_zh = '回想一下最初那些日子的担忧。看看现在，你已经成为会添加辅食的专业妈妈了。为自己骄傲吧！' WHERE id = '01da84b5-ee27-4d08-b8e5-12f1d6a1b6e2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡200 DÍAS INCREÍBLES! 🎉', body_es = '¿Te lo puedes creer? ¡Lleváis justo 200 días recorriendo juntos este camino mágico! Celébralo con un sticker especial en la Sesión de fotos del bebé y compártelo en la Comunidad.', title_fr = '200 JOURS MAGNIFIQUES ! 🎉', body_fr = 'Vous y croyez ? Cela fait pile 200 jours que vous avancez ensemble sur ce chemin magique ! Célébrez ce moment avec un sticker spécial dans la Séance photo bébé et partagez-le dans la Communauté !', title_hi = 'शानदार 200 दिन! 🎉', body_hi = 'यकीन होता है? पूरे 200 दिन से आप साथ मिलकर यह जादुई सफ़र तय कर रहे हैं! बेबी फ़ोटोशूट में खास स्टिकर से इस पल को रोशन कीजिए और कम्युनिटी में शेयर कीजिए!', title_id = '200 HARI YANG LUAR BIASA! 🎉', body_id = 'Percaya tidak? Sudah tepat 200 hari kalian menapaki perjalanan ajaib ini bersama! Rayakan momen ini dengan stiker khusus di Sesi Foto Bayi dan bagikan di Komunitas!', title_ja = 'すばらしい200日！🎉', body_ja = '信じられますか？ちょうど200日間、この魔法のような道を一緒に歩んできました！「ベビーフォトセッション」の特別なステッカーでこの瞬間を彩って、コミュニティでシェアしましょう！', title_ko = '멋진 200일! 🎉', body_ko = '믿어지나요? 꼬박 200일 동안 이 마법 같은 길을 함께 걸어왔어요! 아기 사진 촬영에서 특별한 스티커로 이 순간을 빛내고 커뮤니티에 공유하세요!', title_nl = 'GEWELDIGE 200 DAGEN! 🎉', body_nl = 'Kun je het geloven? Al precies 200 dagen lopen jullie samen deze magische weg! Vier dit moment met een speciale sticker in Babyfotoshoot en deel het in de Community!', title_pl = 'WSPANIAŁE 200 DNI! 🎉', body_pl = 'Wierzysz w to? Od równych 200 dni razem idziecie tą magiczną drogą! Uświetnij tę chwilę specjalną naklejką w Sesji zdjęciowej dziecka i podziel się nią w Społeczności!', title_pt = '200 DIAS FANTÁSTICOS! 🎉', body_pt = 'Acredita? Há exatamente 200 dias que percorrem juntos este caminho mágico! Celebre o momento com um autocolante especial na Sessão Fotográfica do Bebé e partilhe-o na Comunidade!', title_sv = 'FANTASTISKA 200 DAGAR! 🎉', body_sv = 'Kan du tro det? I precis 200 dagar har ni gått den här magiska vägen tillsammans! Fira stunden med ett speciellt klistermärke i Babyfotografering och dela den i Community!', title_vi = '200 NGÀY TUYỆT VỜI! 🎉', body_vi = 'Mẹ tin được không? Đã tròn 200 ngày cả nhà cùng nhau bước trên hành trình kỳ diệu này! Hãy làm khoảnh khắc này thêm rực rỡ với nhãn dán đặc biệt trong Chụp ảnh cho bé và chia sẻ trong Cộng đồng!', title_zh = '精彩的200天！🎉', body_zh = '你敢相信吗？你们一起走过这段神奇的旅程已经整整200天了！在宝宝写真里用专属贴纸庆祝这一刻，分享到社区吧！' WHERE id = '87133947-89a5-414b-a6d4-637285ff301e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Disfruta del orgullo de estos 200 días. 🥂', body_es = 'Esta noche, cuando tu bebé se duerma, ¡no olvides celebrar con tu pareja esta gran victoria en equipo!', title_fr = 'Savourez la fierté de ces 200 jours. 🥂', body_fr = 'Ce soir, quand bébé dormira, n''oubliez pas de fêter cette grande victoire d''équipe avec votre conjoint !', title_hi = '200 दिनों पर गर्व कीजिए 🥂', body_hi = 'आज शाम बच्चे के सोने के बाद अपने साथी के साथ इस बड़ी टीम जीत का जश्न मनाना मत भूलिए!', title_id = 'Rasakan bangganya 200 hari. 🥂', body_id = 'Malam ini, setelah si kecil tidur, jangan lupa merayakan kemenangan besar kalian sebagai tim bersama pasangan!', title_ja = '200日を誇りに思って。🥂', body_ja = '今夜は赤ちゃんが寝たら、パートナーとこのチームの大きな勝利をお祝いするのを忘れずに！', title_ko = '200일의 뿌듯함을 누려요. 🥂', body_ko = '오늘 저녁 아이가 잠든 뒤 배우자와 함께 이 큰 팀의 승리를 축하하는 것도 잊지 마세요!', title_nl = 'Geniet van de trots van 200 dagen. 🥂', body_nl = 'Vergeet vanavond, als je baby slaapt, niet om deze grote overwinning als team met je partner te vieren!', title_pl = 'Poczujcie dumę z 200 dni. 🥂', body_pl = 'Dziś wieczorem, gdy maluszek zaśnie, nie zapomnij uczcić z partnerem tego wielkiego drużynowego zwycięstwa!', title_pt = 'Sinta o orgulho destes 200 dias. 🥂', body_pt = 'Esta noite, depois de o bebé adormecer, não se esqueça de celebrar com o seu companheiro esta grande vitória de equipa!', title_sv = 'Känn stoltheten över 200 dagar. 🥂', body_sv = 'I kväll, när barnet har somnat, glöm inte att fira den här stora lagsegern med din partner!', title_vi = 'Tự hào về 200 ngày. 🥂', body_vi = 'Tối nay, sau khi bé ngủ, đừng quên cùng bố ăn mừng chiến thắng lớn của cả đội nhé!', title_zh = '为200天骄傲 🥂', body_zh = '今晚宝宝睡着后，别忘了和伴侣一起庆祝这个团队大胜利！' WHERE id = 'e7927d9c-8cbd-4c7d-b3cf-e5df983f4169' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se le empapa toda la ropa del cuello en segundos? Las encías se están preparando. Usa baberos de silicona.', body_fr = 'Son col est trempé en quelques secondes ? Ses gencives se préparent. Utilisez des bavoirs en silicone.', body_hi = 'पूरा कॉलर सेकंडों में भीग जाता है? मसूड़े तैयारी कर रहे हैं। सिलिकॉन बिब इस्तेमाल कीजिए।', body_id = 'Kerah bajunya basah dalam hitungan detik? Gusinya sedang bersiap. Gunakan celemek silikon.', body_ja = 'えりが数秒でびしょぬれに？歯ぐきが準備をしています。シリコンのスタイを使いましょう。', body_ko = '옷깃이 몇 초 만에 다 젖나요? 잇몸이 준비 중이에요. 실리콘 턱받이를 사용하세요.', body_nl = 'Is het hele kraagje binnen een paar seconden nat? Het tandvlees maakt zich klaar. Gebruik siliconen slabbetjes.', body_pl = 'Ubranko pod szyją mokre w kilka sekund? Dziąsła się przygotowują. Używaj silikonowych śliniaków.', body_pt = 'A gola fica encharcada em segundos? As gengivas estão a preparar-se. Use babetes de silicone.', body_sv = 'Blir hela kragen blöt på några sekunder? Tandköttet förbereder sig. Använd haklappar i silikon.', body_vi = 'Cổ áo ướt sũng chỉ trong vài giây? Nướu bé đang chuẩn bị mọc răng. Hãy dùng yếm silicone nhé.', body_zh = '衣领几秒钟就湿透了？牙龈在做准备。用硅胶围兜吧。' WHERE id = '14f79c92-38f1-4965-a9d0-fbcb8e236840' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Después de un día difícil, sentaos cara a cara tu pareja y tú y hablad. Apoyaros reparte la carga a la mitad.', body_fr = 'Après une journée difficile, asseyez-vous face à votre conjoint et parlez. Vous soutenir mutuellement allège la charge de moitié.', body_hi = 'मुश्किल दिन के बाद अपने साथी के साथ आमने-सामने बैठकर दिल की बात कीजिए। एक-दूसरे का साथ बोझ आधा कर देता है।', body_id = 'Setelah hari yang berat, duduklah berhadapan dengan pasangan dan saling bercerita. Saling mendukung membuat beban terbagi dua.', body_ja = '大変な1日のあとは、パートナーと向き合って話しましょう。支え合うことで、負担は半分になります。', body_ko = '힘든 하루를 보낸 뒤 배우자와 마주 앉아 이야기를 나눠 보세요. 서로를 응원하면 짐이 절반으로 줄어요.', body_nl = 'Ga na een zware dag tegenover je partner zitten en praat je hart uit. Elkaar steunen halveert de last.', body_pl = 'Po trudnym dniu usiądź z partnerem twarzą w twarz i porozmawiajcie. Wzajemne wsparcie dzieli ciężar na pół.', body_pt = 'Depois de um dia difícil, sente-se frente a frente com o seu companheiro e conversem. Apoiarem-se um ao outro divide o peso ao meio.', body_sv = 'Efter en tuff dag, sätt er mittemot varandra och prata ut med din partner. Att stötta varandra halverar bördan.', body_vi = 'Sau một ngày vất vả, hãy ngồi đối diện và tâm sự cùng bố. Cùng nâng đỡ nhau sẽ giúp gánh nặng vơi đi một nửa.', body_zh = '辛苦一天后，和伴侣面对面坐下聊聊。互相支持，担子就轻了一半。' WHERE id = '173f7149-2567-449f-9693-a462d1148849' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Empieza el miedo a los extraños? 🙈', body_es = 'Si llora cuando no te ve o cuando ve a alguien desconocido, es parte de su desarrollo. Consúltalo con Anacan AI.', title_fr = 'La peur des inconnus commence ? 🙈', body_fr = 'S''il pleure quand il ne vous voit pas ou face à un inconnu, cela fait partie de son développement. Demandez conseil à Anacan AI à ce sujet.', title_hi = 'अनजान लोगों से डर शुरू हो रहा है? 🙈', body_hi = 'अगर वह आपको न देखकर या किसी अनजान को देखकर रोता है, तो यह विकास का हिस्सा है। इस बारे में Anacan AI से सलाह लीजिए।', title_id = 'Mulai takut orang asing? 🙈', body_id = 'Kalau ia menangis saat tidak melihat Anda atau melihat orang asing, ini bagian dari perkembangan. Konsultasikan dengan Anacan AI.', title_ja = '人見知りが始まった？🙈', body_ja = 'あなたが見えなかったり、知らない人を見たりして泣くのは、成長の一部です。Anacan AIに相談してみましょう。', title_ko = '낯가림이 시작됐나요? 🙈', body_ko = '엄마가 안 보이거나 낯선 사람을 보면 운다면 발달의 일부예요. Anacan AI와 이에 대해 상담해 보세요.', title_nl = 'Begint de angst voor vreemden? 🙈', body_nl = 'Huilt je baby als hij jou niet ziet of als hij een vreemde ziet? Dat hoort bij de ontwikkeling. Vraag Anacan AI om advies.', title_pl = 'Zaczyna się lęk przed obcymi? 🙈', body_pl = 'Jeśli płacze, gdy cię nie widzi albo gdy zobaczy kogoś obcego, to część rozwoju. Porozmawiaj o tym z Anacan AI.', title_pt = 'Começa o medo de estranhos? 🙈', body_pt = 'Se chora quando não a vê ou quando vê um estranho, faz parte do desenvolvimento. Aconselhe-se sobre isto com o Anacan AI.', title_sv = 'Börjar främlingsrädslan? 🙈', body_sv = 'Om barnet gråter när det inte ser dig eller när det ser någon främmande är det en del av utvecklingen. Rådfråga Anacan AI om det.', title_vi = 'Bé bắt đầu sợ người lạ? 🙈', body_vi = 'Nếu bé khóc khi không thấy mẹ hoặc khi gặp người lạ, đó là một phần của sự phát triển. Hãy hỏi ý kiến Anacan AI về điều này.', title_zh = '开始怕生了？🙈', body_zh = '看不到你或看到陌生人就哭，这是发育的一部分。和Anacan AI聊聊这个话题吧。' WHERE id = '1af66eec-0d7d-4dcd-9326-d4155d237a55' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Respuestas rápidas 🤖', body_es = '¿Algo te tiene hecha un lío? En vez de pasar horas leyendo foros, pregunta a Anacan AI y recibe una respuesta rápida.', title_fr = 'Des réponses rapides 🤖', body_fr = 'Quelque chose vous tracasse ? Plutôt que de lire des forums pendant des heures, posez votre question à Anacan AI et obtenez une réponse rapide.', title_hi = 'तुरंत जवाब 🤖', body_hi = 'कोई बात परेशान कर रही है? घंटों फ़ोरम पढ़ने के बजाय अपना सवाल Anacan AI से पूछिए और तुरंत जवाब पाइए।', title_id = 'Jawaban cepat 🤖', body_id = 'Ada yang membuat Anda bingung? Daripada membaca forum berjam-jam, ajukan pertanyaan ke Anacan AI dan dapatkan jawaban cepat.', title_ja = 'すぐに答えがわかる 🤖', body_ja = '何か気になることがありますか？何時間も掲示板を読むより、Anacan AIに質問して、すぐに答えを受け取りましょう。', title_ko = '빠른 답변 🤖', body_ko = '머릿속이 복잡한가요? 몇 시간씩 커뮤니티 글을 읽는 대신 Anacan AI에게 물어 빠르게 답을 받아 보세요.', title_nl = 'Snelle antwoorden 🤖', body_nl = 'Zit je ergens mee? Lees geen uren op forums, maar stel je vraag aan Anacan AI en krijg snel antwoord.', title_pl = 'Szybkie odpowiedzi 🤖', body_pl = 'Coś nie daje ci spokoju? Zamiast godzinami czytać fora, zadaj pytanie Anacan AI i szybko dostań odpowiedź.', title_pt = 'Respostas rápidas 🤖', body_pt = 'Há algo que a deixa confusa? Em vez de passar horas a ler fóruns, faça a pergunta ao Anacan AI e receba uma resposta rápida.', title_sv = 'Snabba svar 🤖', body_sv = 'Är det något som snurrar i huvudet? I stället för att läsa forum i timmar, ställ din fråga till Anacan AI och få ett snabbt svar.', title_vi = 'Câu trả lời nhanh chóng 🤖', body_vi = 'Có điều gì khiến mẹ băn khoăn? Thay vì đọc diễn đàn hàng giờ, hãy hỏi Anacan AI và nhận câu trả lời nhanh chóng.', title_zh = '快速解答 🤖', body_zh = '有什么让你困惑？与其花几个小时看论坛，不如把问题交给Anacan AI，快速获得答案。' WHERE id = '23068177-6d18-4649-91f5-5ac9ecb37933' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Boca abajo, intenta avanzar arrastrándose. Sus músculos se fortalecen día a día: ponle un juguete delante para animarle.', body_fr = 'Sur le ventre, il essaie de ramper vers l''avant. Ses muscles se renforcent de jour en jour, posez un jouet devant lui pour l''encourager.', body_hi = 'पेट के बल रहते हुए आगे खिसकने की कोशिश करता है। उसकी मांसपेशियाँ दिन-ब-दिन मज़बूत हो रही हैं, सामने खिलौना रखकर उसका हौसला बढ़ाइए।', body_id = 'Ia mencoba merayap maju saat tengkurap. Ototnya makin kuat setiap hari, letakkan mainan di depannya untuk menyemangatinya.', body_ja = 'うつぶせで前に進もうとしています。筋肉が日に日に強くなっています。目の前におもちゃを置いて応援してあげましょう。', body_ko = '엎드린 채 앞으로 기어가려고 해요. 근육이 날마다 튼튼해지고 있으니 앞에 장난감을 놓아 응원해 주세요.', body_nl = 'Je baby probeert op de buik vooruit te kruipen. De spiertjes worden elke dag sterker. Leg een speeltje voor hem neer en moedig hem aan.', body_pl = 'Leżąc na brzuszku, próbuje pełzać do przodu. Jego mięśnie z dnia na dzień są silniejsze, połóż przed nim zabawkę i zachęcaj go.', body_pt = 'De barriga para baixo, tenta rastejar para a frente. Os músculos estão cada dia mais fortes: ponha-lhe um brinquedo à frente para o incentivar.', body_sv = 'Barnet försöker åla framåt när det ligger på magen. Musklerna blir starkare för varje dag, lägg en leksak framför det som uppmuntran.', body_vi = 'Khi nằm sấp, bé cố trườn về phía trước. Cơ bắp của bé cứng cáp hơn từng ngày, hãy đặt đồ chơi trước mặt để khích lệ bé.', body_zh = '宝宝趴着时在尝试往前爬。肌肉一天比一天结实，在宝宝面前放个玩具鼓励一下吧。' WHERE id = '52b2efdc-0a49-4bfa-8a7e-21a3342254cb' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Si al caer la tarde empieza a llorar sin motivo, prueba a calmarle con música clásica lenta.', body_fr = 'Pour les pleurs inexpliqués de fin d''après-midi, essayez de les calmer avec de la musique classique lente.', body_hi = 'शाम को बिना वजह शुरू होने वाले रोने को धीमे क्लासिकल संगीत से शांत करके देखिए।', body_id = 'Coba redakan tangisan tanpa sebab yang muncul menjelang sore dengan musik klasik bertempo lambat.', body_ja = '夕方から始まる理由のわからない泣きには、ゆったりしたクラシック音楽を試してみましょう。', body_ko = '늦은 오후에 시작되는 이유 없는 울음은 느린 클래식 음악으로 달래 보세요.', body_nl = 'Probeer het onverklaarbare huilen aan het eind van de middag te stoppen met rustige klassieke muziek.', body_pl = 'Płacz bez powodu, który zaczyna się pod wieczór, spróbuj uciszyć spokojną muzyką klasyczną.', body_pt = 'Experimente acalmar o choro sem motivo que começa ao fim da tarde com música clássica lenta.', body_sv = 'Prova att bryta oförklarlig gråt som börjar på eftermiddagen med lugn klassisk musik.', body_vi = 'Nếu bé khóc không rõ lý do vào chiều tối, hãy thử dỗ bé bằng nhạc cổ điển có tiết tấu chậm.', body_zh = '傍晚开始无缘无故地哭？试试用节奏舒缓的古典音乐让宝宝平静下来。' WHERE id = '97716c97-1bb3-4784-acfc-a5f0354d1864' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Manos libres 👐', body_es = 'Boca abajo, ¿alcanza un juguete con una mano y se apoya en la otra? ¡Su equilibrio muscular está mejorando muchísimo!', title_fr = 'Les mains libres 👐', body_fr = 'Sur le ventre, il tend une main vers un jouet et s''appuie sur l''autre ? Son équilibre musculaire se perfectionne !', title_hi = 'हाथ आज़ाद हैं 👐', body_hi = 'पेट के बल रहते हुए एक हाथ से खिलौने की ओर बढ़ता है और दूसरे हाथ से सहारा लेता है? मांसपेशियों का संतुलन बेहतर हो रहा है!', title_id = 'Tangan makin bebas 👐', body_id = 'Saat tengkurap, ia meraih mainan dengan satu tangan sambil bertumpu pada tangan lainnya? Keseimbangan ototnya makin sempurna!', title_ja = '手が自由に 👐', body_ja = 'うつぶせのとき、片手でおもちゃに手を伸ばし、もう片方の手で体を支えていますか？筋肉のバランスがどんどん上手になっています！', title_ko = '자유로운 두 손 👐', body_ko = '엎드린 채 한 손으로 장난감에 손을 뻗고 다른 손으로 몸을 받치나요? 근육 균형이 완벽해지고 있어요!', title_nl = 'Handjes vrij 👐', body_nl = 'Reikt je baby op de buik met één hand naar een speeltje en steunt hij op de andere? Het spierevenwicht wordt steeds beter!', title_pl = 'Rączki są wolne 👐', body_pl = 'Leżąc na brzuszku, sięga jedną rączką po zabawkę, a drugą się podpiera? Równowaga mięśni staje się doskonała!', title_pt = 'Mãos livres 👐', body_pt = 'De barriga para baixo, estica uma mão para o brinquedo e apoia-se na outra? O equilíbrio muscular está a ficar perfeito!', title_sv = 'Händerna är fria 👐', body_sv = 'Sträcker sig barnet efter en leksak med ena handen och stöttar sig med den andra när det ligger på magen? Muskelbalansen blir allt bättre!', title_vi = 'Đôi tay tự do 👐', body_vi = 'Khi nằm sấp, bé dùng một tay với đồ chơi và tay kia chống đỡ? Khả năng giữ thăng bằng của cơ bắp đang hoàn thiện!', title_zh = '解放双手 👐', body_zh = '宝宝趴着时一只手去够玩具，另一只手撑着身体？肌肉平衡越来越好了！' WHERE id = '9c5c6958-af17-4420-aa80-95cd295c8995' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Hoy pasa el turno de mamá a tu pareja durante un rato. Deja que jueguen y tú estira las piernas y descansa.', body_fr = 'Aujourd''hui, passez le relais à votre conjoint pour un petit moment. Laissez-les jouer, et vous, allongez les jambes et reposez-vous.', body_hi = 'आज थोड़ी देर के लिए माँ की ड्यूटी अपने साथी को सौंप दीजिए। उन्हें खेलने दीजिए, और आप बस पैर फैलाकर आराम कीजिए।', body_id = 'Hari ini, serahkan giliran mengasuh kepada pasangan sebentar. Biarkan mereka bermain, sementara Anda selonjorkan kaki dan beristirahat.', body_ja = '今日は少しの間、育児をパートナーにバトンタッチしましょう。2人が遊んでいる間、あなたは足を伸ばしてのんびりしてください。', body_ko = '오늘은 잠시 육아 당번을 배우자에게 넘기세요. 둘이 노는 동안 엄마는 다리를 쭉 뻗고 쉬세요.', body_nl = 'Draag de mamadienst vandaag even over aan je partner. Laat ze samen spelen, en jij legt gewoon je benen omhoog en rust uit.', body_pl = 'Przekaż dziś na chwilę dyżur rodzica partnerowi. Niech się bawią, a ty po prostu wyciągnij nogi i odpocznij.', body_pt = 'Hoje, passe por pouco tempo o turno de mãe ao seu companheiro. Deixe-os brincar e simplesmente estique as pernas e descanse.', body_sv = 'Lämna över mammaskiftet till din partner en kort stund i dag. Låt dem leka medan du bara sträcker ut benen och vilar.', body_vi = 'Hôm nay hãy giao ca chăm bé cho bố một lúc. Để hai bố con chơi với nhau, còn mẹ chỉ cần duỗi chân và nghỉ ngơi.', body_zh = '今天把带娃的班暂时交给伴侣吧。让他们去玩，你只管把腿伸直好好休息。' WHERE id = 'acd2495b-eae5-4005-8f31-3fdfdc4738aa' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Tu peque se ha comido su puré, ¿y tú? Necesitas comer bien para recuperar energía. Hoy pide para ti una comida que te sacie.', body_fr = 'Il a mangé sa purée, et vous ? Pour retrouver votre énergie, vous devez bien vous nourrir. Aujourd''hui, commandez-vous un bon repas copieux.', body_hi = 'उसने अपनी प्यूरी खा ली, और आपने? ऊर्जा लौटाने के लिए आपको अच्छा खाना चाहिए। आज अपने लिए कोई पेट भरने वाला खाना ऑर्डर कीजिए।', body_id = 'Ia sudah menghabiskan puree-nya, bagaimana dengan Anda? Anda perlu makan dengan baik untuk memulihkan energi. Hari ini, pesanlah makanan yang mengenyangkan untuk diri sendiri.', body_ja = '赤ちゃんはペーストを食べました。あなたは？元気を取り戻すには、しっかり食べることが大切です。今日は自分のために、食べごたえのある食事を頼みましょう。', body_ko = '아기는 퓌레를 다 먹었는데 엄마는요? 에너지를 되찾으려면 잘 챙겨 먹어야 해요. 오늘은 나를 위해 든든한 식사를 주문하세요.', body_nl = 'Je baby heeft zijn hapje op, en jij? Om weer energie te krijgen moet je goed eten. Bestel vandaag een voedzame maaltijd voor jezelf.', body_pl = 'On zjadł swój przecier, a ty? Musisz dobrze się odżywiać, żeby odzyskać energię. Zamów dziś dla siebie sycący posiłek.', body_pt = 'Ele comeu o puré, e a mãe? Para recuperar energia, precisa de se alimentar bem. Hoje, encomende uma refeição reconfortante para si.', body_sv = 'Barnet har ätit sin puré, men du då? Du måste äta ordentligt för att få tillbaka energin. Beställ en mättande måltid åt dig själv i dag.', body_vi = 'Bé đã ăn hết món nghiền, còn mẹ thì sao? Mẹ cần ăn uống đầy đủ để phục hồi năng lượng. Hôm nay hãy đặt cho mình một bữa ăn thật no.', body_zh = '宝宝吃完了果泥，那你呢？想恢复体力，你也要吃好。今天给自己订一顿丰盛的饭吧。' WHERE id = '094a764e-f3f1-4dd1-8a87-04126b16323f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Te conozco 👀', body_es = '¿Cuando vienen visitas se pega a ti y las mira con recelo? Empieza la ansiedad por separación. Simplemente se siente seguro a tu lado, respétalo.', title_fr = 'Je te reconnais 👀', body_fr = 'Quand des invités viennent, il s''accroche à vous et les regarde bizarrement ? L''angoisse de séparation commence. Il se sent simplement en sécurité près de sa maman, respectez-le.', title_hi = 'मैं आपको पहचानता हूँ 👀', body_hi = 'घर में मेहमान आएँ तो वह आपसे चिपक जाता है और अजीब नज़र से देखता है? अलगाव की बेचैनी शुरू हो रही है। वह बस माँ के पास सुरक्षित महसूस करता है, इसे समझदारी से लीजिए।', title_id = 'Aku mengenalmu 👀', body_id = 'Saat ada tamu, ia menempel pada Anda dan menatap dengan heran? Kecemasan berpisah mulai muncul. Ia hanya merasa aman di dekat ibunya, hargai hal ini.', title_ja = 'ママだってわかるよ 👀', body_ja = 'お客さんが来ると、あなたにしがみついて不思議そうに見ていますか？分離不安が始まっています。ママのそばだと安心できるだけなので、その気持ちを大切にしてあげましょう。', title_ko = '엄마를 알아요 👀', body_ko = '손님이 오면 엄마에게 매달려 낯설게 쳐다보나요? 분리불안이 시작되고 있어요. 엄마 곁이 가장 안전하다고 느끼는 거니 이해해 주세요.', title_nl = 'Ik ken jou 👀', body_nl = 'Klampt je baby zich aan je vast en kijkt hij vreemd als er bezoek komt? De verlatingsangst begint. Bij zijn mama voelt hij zich gewoon veilig, respecteer dat.', title_pl = 'Znam cię 👀', body_pl = 'Gdy przychodzą goście, przykleja się do ciebie i dziwnie na nich patrzy? Zaczyna się lęk separacyjny. Po prostu przy mamie czuje się bezpiecznie, uszanuj to.', title_pt = 'Eu conheço-te 👀', body_pt = 'Quando há visitas, agarra-se a si e olha-as de forma estranha? A ansiedade de separação está a começar. Ele só se sente seguro perto da mãe, respeite isso.', title_sv = 'Jag känner igen dig 👀', body_sv = 'Klänger barnet på dig och tittar konstigt på gäster som kommer hem? Separationsångesten börjar. Barnet känner sig bara tryggt hos sin mamma, möt det med respekt.', title_vi = 'Con nhận ra mẹ 👀', body_vi = 'Khi có khách đến nhà, bé bám lấy mẹ và nhìn khách với ánh mắt lạ lẫm? Nỗi lo xa cách đang bắt đầu. Bé chỉ thấy an toàn khi ở bên mẹ, hãy tôn trọng điều đó.', title_zh = '我认识你 👀', body_zh = '家里来客人时，宝宝紧紧黏着你，警惕地看着别人？分离焦虑开始了。宝宝只是在妈妈身边才有安全感，请理解宝宝。' WHERE id = '734bd8a8-49ec-4c9f-bb8c-17a8d1fc50b6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche demos a Cuentos inteligentes un tema dulce: «La historia de la estrella más dulce que cayó del cielo». Que en la habitación solo se oiga este cuento.', body_fr = 'Ce soir, donnons un joli thème à l''outil Contes intelligents : « L''histoire de la plus douce étoile tombée du ciel ». Que seule la voix de ce conte emplisse la chambre.', body_hi = 'आज शाम स्मार्ट कहानियों को एक प्यारा विषय दीजिए: “आसमान से गिरे सबसे प्यारे तारे की कहानी”। कमरे में बस इसी कहानी की आवाज़ गूँजने दीजिए।', body_id = 'Malam ini, beri Dongeng Pintar tema yang manis: "Kisah bintang termanis yang jatuh dari langit". Biarkan hanya suara dongeng ini yang terdengar di kamar.', body_ja = '今夜は「スマートおはなし」にすてきなテーマを出しましょう：「空から落ちてきた、いちばんやさしい星のお話」。部屋にはこのお話の声だけが流れるようにしましょう。', body_ko = '오늘 저녁 스마트 동화 도구에 달콤한 주제를 줘 볼까요: “하늘에서 떨어진 가장 달콤한 별 이야기”. 방 안에 이 동화 소리만 가득하게 해 주세요.', body_nl = 'Geef de tool Slimme sprookjes vanavond een lief onderwerp: ''Het verhaal van het liefste sterretje dat uit de hemel viel''. Laat alleen het geluid van dit sprookje door de kamer klinken.', body_pl = 'Dajmy dziś wieczorem Mądrym bajkom słodki temat: „Historia najsłodszej gwiazdki, która spadła z nieba”. Niech w pokoju rozbrzmiewa tylko ta bajka.', body_pt = 'Esta noite, vamos dar às Histórias Inteligentes um tema doce: "A história da estrela mais doce que caiu do céu". Que só se ouça esta história no quarto.', body_sv = 'Låt oss ge Smarta sagor ett gulligt tema i kväll: ”Sagan om den sötaste stjärnan som föll från himlen”. Låt bara ljudet av den här sagan fylla rummet.', body_vi = 'Tối nay mình giao cho Truyện cổ tích thông minh một chủ đề ngọt ngào: "Câu chuyện về ngôi sao ngọt ngào nhất rơi xuống từ bầu trời". Hãy để chỉ có tiếng kể chuyện này vang trong phòng.', body_zh = '今晚给智能故事一个甜蜜的主题：“从天上掉下来的最甜的星星的故事”。让房间里只回荡着这个故事吧。' WHERE id = '740c028d-4797-4507-a894-816747e5301d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Ponle delante de un espejo. Ver cómo mira su reflejo con asombro y se ríe es una actividad estupenda y relajante.', body_fr = 'Emmenez-le devant un miroir. Le regarder contempler son reflet avec émerveillement et rire, c''est une activité géniale et apaisante.', body_hi = 'उसे आईने के सामने ले जाइए। अपना अक्स देखकर वह कैसे हैरानी से देखता और हँसता है, यह देखना बढ़िया और सुकून भरी गतिविधि है।', body_id = 'Bawa ia ke depan cermin. Melihatnya menatap bayangannya dengan takjub lalu tertawa adalah aktivitas yang seru dan menenangkan.', body_ja = '鏡の前に連れて行きましょう。自分の姿に驚いて笑う様子を見守るのは、楽しくて心がなごむ時間です。', body_ko = '아기를 거울 앞에 데려가 보세요. 거울 속 자신을 신기하게 바라보며 웃는 모습을 보는 건 즐겁고 마음이 편안해지는 시간이에요.', body_nl = 'Zet je baby voor de spiegel. Kijken hoe hij verbaasd naar zijn spiegelbeeld kijkt en lacht, is een fijne en rustgevende activiteit.', body_pl = 'Zanieś go przed lustro. Obserwowanie, jak ze zdumieniem patrzy na swoje odbicie i się śmieje, to świetne i kojące zajęcie.', body_pt = 'Leve-o à frente do espelho. Ver com que espanto ele olha para o próprio reflexo e se ri é uma atividade ótima e calmante.', body_sv = 'Bär fram barnet till spegeln. Att se hur förundrat det tittar på sin spegelbild och skrattar är en härlig och lugnande aktivitet.', body_vi = 'Hãy bế bé đến trước gương. Ngắm bé ngạc nhiên nhìn hình mình và bật cười là một hoạt động tuyệt vời và êm dịu.', body_zh = '带宝宝到镜子前。看着宝宝惊奇地望着镜中的自己并露出笑容，是一项美好又舒缓的活动。' WHERE id = '6496f6e2-60a8-4932-a5d1-b8cb0c9682cf' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Te oigo 🗣️', body_es = '¿Te escucha con atención e intenta repetir sílabas parecidas (ma-ma, ba-ba)? ¡Está hablando contigo! Respóndele con muchas sonrisas.', title_fr = 'Je t''entends 🗣️', body_fr = 'Il vous écoute attentivement et essaie de produire des syllabes semblables (ma-ma, ba-ba) ? Il vous parle ! Répondez-lui avec plein de sourires.', title_hi = 'मैं आपको सुन रहा हूँ 🗣️', body_hi = 'आपको ध्यान से सुनकर मिलते-जुलते अक्षर (मा-मा, बा-बा) बोलने की कोशिश करता है? वह आपसे बात कर रहा है! खूब मुस्कुराकर उसे जवाब दीजिए।', title_id = 'Aku mendengarmu 🗣️', body_id = 'Ia mendengarkan Anda dengan saksama dan mencoba menirukan suku kata (ma-ma, ba-ba)? Ia sedang berbicara dengan Anda! Balas dengan banyak senyuman.', title_ja = '聞こえてるよ 🗣️', body_ja = 'あなたの話をじっと聞いて、「まーま」「ばーば」のような似た音を出そうとしていますか？あなたとおしゃべりしているのです！たっぷりの笑顔で応えてあげましょう。', title_ko = '엄마 목소리가 들려요 🗣️', body_ko = '엄마 말을 유심히 듣고 비슷한 소리(마-마, 바-바)를 내려고 하나요? 엄마와 이야기하는 중이에요! 활짝 웃으며 대답해 주세요.', title_nl = 'Ik hoor je 🗣️', body_nl = 'Luistert je baby aandachtig naar je en probeert hij lettergrepen na te doen (ma-ma, ba-ba)? Hij praat met je! Antwoord hem met een grote glimlach.', title_pl = 'Słyszę cię 🗣️', body_pl = 'Uważnie cię słucha i próbuje wymawiać podobne sylaby (ma-ma, ba-ba)? Rozmawia z tobą! Odpowiadaj mu z szerokim uśmiechem.', title_pt = 'Estou a ouvir-te 🗣️', body_pt = 'Ouve-a com atenção e tenta fazer sílabas parecidas (ma-ma, ba-ba)? Está a falar consigo! Responda-lhe com muitos sorrisos.', title_sv = 'Jag hör dig 🗣️', body_sv = 'Lyssnar barnet uppmärksamt på dig och försöker säga liknande stavelser (ma-ma, ba-ba)? Det pratar med dig! Svara med massor av leenden.', title_vi = 'Con nghe thấy mẹ 🗣️', body_vi = 'Bé chăm chú nghe mẹ và cố phát ra những âm tương tự ("ma-ma", "ba-ba")? Bé đang nói chuyện với mẹ đấy! Hãy đáp lại bé bằng thật nhiều nụ cười.', title_zh = '我听到你啦 🗣️', body_zh = '宝宝专心听你说话，还想发出相似的音节（ma-ma、ba-ba）？宝宝在和你说话！多笑着回应宝宝吧。' WHERE id = '06cfdff1-da31-4945-b562-a0c104f43d15' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Ponle en el carrito y sal 20 minutos a tomar aire fresco. Os sentará genial a los dos.', body_fr = 'Installez-le dans sa poussette et sortez prendre l''air 20 minutes. Cela vous fera beaucoup de bien à tous les deux.', body_hi = 'उसे स्ट्रॉलर में बिठाइए और 20 मिनट ताज़ी हवा में निकलिए। आप दोनों को बहुत अच्छा लगेगा।', body_id = 'Masukkan ia ke stroller dan keluarlah menghirup udara segar selama 20 menit. Ini akan sangat baik untuk kalian berdua.', body_ja = 'ベビーカーに乗せて、20分ほど外の空気を吸いに出かけましょう。2人にとってとてもいい時間になります。', body_ko = '아기를 유모차에 태우고 20분 동안 바깥바람을 쐬어 보세요. 두 사람 모두에게 정말 좋을 거예요.', body_nl = 'Leg je baby in de kinderwagen en ga 20 minuten naar buiten. Dat doet jullie allebei heel goed.', body_pl = 'Włóż go do wózka i wyjdźcie na 20 minut na świeże powietrze. Obojgu dobrze wam to zrobi.', body_pt = 'Ponha-o no carrinho e saia 20 minutos para apanhar ar fresco. Vai fazer muito bem aos dois.', body_sv = 'Lägg barnet i vagnen och gå ut i frisk luft i 20 minuter. Det gör er båda väldigt gott.', body_vi = 'Đặt bé vào xe đẩy và ra ngoài hít thở không khí trong lành 20 phút. Điều đó rất tốt cho cả hai mẹ con.', body_zh = '把宝宝放进婴儿车，出去呼吸20分钟新鲜空气吧。对你们俩都很有好处。' WHERE id = '83caf542-3e86-4833-b9bd-0befb15b04d7' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sentarse sin apoyo 🪑', body_es = '¿Ya se sienta derecho sin cojines, aunque sea un ratito? Protégele por si se cae y sigue de cerca este desarrollo muscular.', title_fr = 'Assis sans soutien 🪑', body_fr = 'Il tient assis bien droit sans coussins, même peu de temps ? Restez à côté pour le sécuriser et observez attentivement ce progrès musculaire.', title_hi = 'बिना सहारे बैठना 🪑', body_hi = 'अब तकियों के बिना थोड़ी देर ही सही, सीधा बैठता है? उसकी सुरक्षा का ध्यान रखते हुए मांसपेशियों के इस विकास को ध्यान से देखिए।', title_id = 'Duduk tanpa sandaran 🪑', body_id = 'Ia sudah bisa duduk tegak tanpa bantal, walau sebentar? Jaga ia dari jatuh dan perhatikan perkembangan ototnya dengan cermat.', title_ja = '支えなしでおすわり 🪑', body_ja = '短い時間でも、クッションなしでまっすぐ座れるようになりましたか？安全に気をつけながら、この筋肉の発達をしっかり見守りましょう。', title_ko = '혼자 앉기 🪑', body_ko = '이제 쿠션 없이도 잠깐이나마 꼿꼿이 앉나요? 안전하게 지켜 주며 이 근육 발달을 유심히 지켜보세요.', title_nl = 'Zitten zonder steun 🪑', body_nl = 'Zit je baby al even rechtop zonder kussens? Blijf in de buurt om hem op te vangen en volg deze spierontwikkeling goed.', title_pl = 'Siedzenie bez podparcia 🪑', body_pl = 'Siedzi prosto bez poduszek, choćby przez chwilę? Asekuruj go i uważnie obserwuj ten rozwój mięśni.', title_pt = 'Sentar sem apoio 🪑', body_pt = 'Já se senta direito sem precisar de almofadas, nem que seja por pouco tempo? Mantenha-o protegido e acompanhe com atenção este desenvolvimento muscular.', title_sv = 'Sitter utan stöd 🪑', body_sv = 'Sitter barnet redan rakt utan kuddar, om så bara en kort stund? Följ den här muskelutvecklingen noga och se till att det är säkert.', title_vi = 'Ngồi không cần đỡ 🪑', body_vi = 'Bé đã ngồi thẳng mà không cần gối, dù chỉ trong thời gian ngắn? Hãy luôn che chắn an toàn và chăm chú theo dõi sự phát triển cơ bắp này.', title_zh = '独立坐 🪑', body_zh = '不靠枕头也能挺直坐一小会儿了？在一旁护着宝宝，仔细观察这项肌肉发育吧。' WHERE id = '4335b974-a43c-4ba3-b369-2006056301ed' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No comas de pie ni con prisas. 🥑', body_es = 'Prepárate una ensalada riquísima y dedica 15 minutos solo a ti.', title_fr = 'Ne déjeunez pas debout et à la va-vite. 🥑', body_fr = 'Préparez-vous une délicieuse salade et prenez 15 minutes rien que pour vous.', title_hi = 'दोपहर का खाना खड़े-खड़े और जल्दबाज़ी में मत खाइए 🥑', body_hi = 'अपने लिए एक स्वादिष्ट सलाद बनाइए और 15 मिनट सिर्फ़ खुद को दीजिए।', title_id = 'Jangan makan siang sambil berdiri dan terburu-buru. 🥑', body_id = 'Buat salad lezat untuk diri sendiri dan luangkan 15 menit hanya untuk Anda.', title_ja = 'お昼ごはんを立ったまま、急いで食べないで。🥑', body_ja = '自分のためにおいしいサラダをつくって、15分間だけ自分のための時間をとりましょう。', title_ko = '점심을 서서 급하게 먹지 마세요. 🥑', body_ko = '나를 위해 맛있는 샐러드를 만들고 15분만이라도 온전히 나에게 시간을 주세요.', title_nl = 'Eet je lunch niet staand en gehaast op. 🥑', body_nl = 'Maak een lekkere salade voor jezelf en neem 15 minuten alleen voor jezelf.', title_pl = 'Nie jedz obiadu na stojąco i w pośpiechu. 🥑', body_pl = 'Przygotuj sobie pyszną sałatkę i poświęć 15 minut tylko sobie.', title_pt = 'Não almoce de pé e à pressa. 🥑', body_pt = 'Prepare uma salada deliciosa para si e reserve 15 minutos só para si.', title_sv = 'Ät inte lunchen stående och i all hast. 🥑', body_sv = 'Gör en god sallad åt dig själv och ta 15 minuter bara för dig själv.', title_vi = 'Đừng đứng ăn trưa vội vàng. 🥑', body_vi = 'Hãy làm cho mình một đĩa salad ngon lành và dành riêng 15 phút cho bản thân.', title_zh = '午饭别站着匆匆吃 🥑', body_zh = '给自己做一份美味的沙拉，留15分钟只属于自己的时间吧。' WHERE id = '5bc047d7-1539-47af-a21f-c1df4aa3461d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El final de un día precioso. ✨', body_es = '¡Eres una madre muy fuerte! Escribe en el Diario de ánimo lo orgullosa que estás de ti, encuentra la calma con el Ruido blanco y duerme a gusto.', title_fr = 'La fin d''une belle journée. ✨', body_fr = 'Vous êtes une maman très forte ! Écrivez dans le Journal d''humeur que vous êtes fière de vous, trouvez la sérénité avec les Bruits blancs et passez une bonne nuit.', title_hi = 'एक खूबसूरत दिन का अंत ✨', body_hi = 'आप बहुत मज़बूत माँ हैं! मूड डायरी में लिखिए कि आपको खुद पर किस बात का गर्व है, व्हाइट नॉइज़ से सुकून पाइए और आराम से सोइए।', title_id = 'Akhir dari hari yang indah. ✨', body_id = 'Anda ibu yang sangat kuat! Tulis di Buku Harian Suasana Hati bahwa Anda bangga pada diri sendiri, temukan ketenangan dengan White Noise, dan tidurlah nyenyak.', title_ja = 'すてきな1日の終わりに。✨', body_ja = 'あなたはとても強いママです！「気分日記」に自分を誇りに思うことを書いて、「ホワイトノイズ」でやすらぎを見つけ、ぐっすり眠りましょう。', title_ko = '아름다운 하루의 끝. ✨', body_ko = '정말 강한 엄마예요! 기분 일기에 스스로가 자랑스러운 점을 적고, 백색소음으로 마음의 평화를 찾아 편안히 주무세요.', title_nl = 'Het einde van een mooie dag. ✨', body_nl = 'Je bent een heel sterke mama! Schrijf in je Stemmingsdagboek dat je trots bent op jezelf, vind rust met Witte ruis en slaap lekker.', title_pl = 'Koniec pięknego dnia. ✨', body_pl = 'Jesteś bardzo silną mamą! Zapisz w Dzienniku nastroju, z czego jesteś dumna, znajdź spokój przy Białym szumie i dobrze się wyśpij.', title_pt = 'O fim de um dia bonito. ✨', body_pt = 'É uma mãe muito forte! Escreva no Diário de Humor que se orgulha de si, encontre a calma com o Ruído Branco e durma descansada.', title_sv = 'Slutet på en fin dag. ✨', body_sv = 'Du är en väldigt stark mamma! Skriv i Humördagboken att du är stolt över dig själv, hitta ro med Vitt brus och sov gott.', title_vi = 'Kết thúc một ngày tốt đẹp. ✨', body_vi = 'Mẹ là một người mẹ thật mạnh mẽ! Hãy viết vào Nhật ký tâm trạng rằng mẹ tự hào về bản thân, tìm sự bình yên với Tiếng ồn trắng và ngủ một giấc thật ngon.', title_zh = '美好一天的结束 ✨', body_zh = '你是一位非常坚强的妈妈！在心情日记里写下你为自己骄傲的地方，用白噪音找到平静，好好睡一觉吧。' WHERE id = 'a649650d-baa3-4dab-9158-780252d27ef4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Recuerda tu falta de experiencia de los primeros días. Y ahora mira en qué madre tan experta te has convertido. ¡Siéntete orgullosa de ti!', body_fr = 'Rappelez-vous votre manque d''expérience des premiers jours. Et regardez la maman pro que vous êtes devenue. Soyez fière de vous !', body_hi = 'शुरुआती दिनों का अपना अनुभवहीनपन याद कीजिए। और अब देखिए, आप कितनी माहिर माँ बन गई हैं। खुद पर गर्व कीजिए!', body_id = 'Ingat betapa belum berpengalamannya Anda di hari-hari pertama. Sekarang lihat, Anda sudah jadi ibu yang andal. Banggalah pada diri sendiri!', body_ja = '最初のころの不慣れな日々を思い出してみて。今ではすっかり頼もしいママになりました。自分を誇りに思って！', body_ko = '처음 며칠의 서툴던 모습을 떠올려 보세요. 그리고 지금 얼마나 능숙한 엄마가 되었는지 보세요. 스스로를 자랑스러워하세요!', body_nl = 'Denk terug aan hoe onervaren je was in de eerste dagen. En kijk nu hoe je een echte prof als mama bent geworden. Wees trots op jezelf!', body_pl = 'Przypomnij sobie, jak brakowało ci doświadczenia w pierwszych dniach. A teraz zobacz, jaką profesjonalną mamą się stałaś. Bądź z siebie dumna!', body_pt = 'Lembre-se da sua inexperiência nos primeiros dias. E agora veja como se tornou uma mãe profissional. Orgulhe-se de si!', body_sv = 'Minns hur oerfaren du var de första dagarna. Och se nu vilken proffsmamma du har blivit. Var stolt över dig själv!', body_vi = 'Hãy nhớ lại những ngày đầu mẹ còn bỡ ngỡ. Còn giờ hãy nhìn xem mẹ đã thành một người mẹ chuyên nghiệp thế nào. Hãy tự hào về mình!', body_zh = '想想最初那些日子你有多没经验。看看现在，你已经成为专业妈妈了。为自己骄傲吧！' WHERE id = 'f5e18de7-aba2-4bda-84e9-b3a568ce950b' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lista te salva 🛒', body_es = '¿Se te ha olvidado algo con el ajetreo del día? No te calientes la cabeza: apunta todo lo que haga falta en casa en la Lista de la compra.', title_fr = 'La liste qui sauve 🛒', body_fr = 'Vous avez oublié quelque chose dans le tourbillon du quotidien ? Ne vous fatiguez pas : notez tout ce dont la maison a besoin dans la Liste de courses.', title_hi = 'लिस्ट आपकी मददगार है 🛒', body_hi = 'रोज़ की भागदौड़ में कुछ भूल गईं? दिमाग मत थकाइए, घर के लिए ज़रूरी हर चीज़ शॉपिंग लिस्ट में लिखिए।', title_id = 'Daftar adalah penyelamat 🛒', body_id = 'Ada yang terlupa di tengah kesibukan? Jangan bikin pusing, tulis semua kebutuhan rumah di Daftar Belanja.', title_ja = 'リストが救世主 🛒', body_ja = '毎日のバタバタで何か忘れてしまった？頭を疲れさせないで、家に必要なものはぜんぶ「買い物リスト」に書きましょう。', title_ko = '목록이 구원자예요 🛒', body_ko = '바쁜 하루 속에 뭔가를 잊으셨나요? 머리 아프게 고민하지 말고 집에 필요한 건 모두 쇼핑 목록에 적어 두세요.', title_nl = 'Een lijstje is je redding 🛒', body_nl = 'Iets vergeten in de dagelijkse drukte? Breek je hoofd er niet over, zet alles wat je in huis nodig hebt op je Boodschappenlijstje.', title_pl = 'Lista na ratunek 🛒', body_pl = 'W codziennym biegu o czymś zapomniałaś? Nie męcz głowy, wpisuj wszystko, czego potrzeba w domu, na Listę zakupów.', title_pt = 'A lista é uma salvação 🛒', body_pt = 'Na correria do dia, esqueceu-se de alguma coisa? Não canse a cabeça: escreva na Lista de Compras tudo o que faz falta em casa.', title_sv = 'Listan räddar dagen 🛒', body_sv = 'Har du glömt något i vardagsstressen? Belasta inte hjärnan, skriv upp allt ni behöver hemma i Inköpslistan.', title_vi = 'Danh sách là cứu tinh 🛒', body_vi = 'Bộn bề mỗi ngày khiến mẹ quên mất điều gì đó? Đừng bận tâm, hãy ghi mọi thứ cần cho nhà vào Danh sách mua sắm.', title_zh = '清单是救星 🛒', body_zh = '每天忙忙碌碌忘了什么？别费脑筋，把家里需要的东西都写进购物清单吧。' WHERE id = '4650c8e1-3011-45f0-9997-0c6decd79a65' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Seguimos la digestión. 🧷', body_es = 'Los alimentos sólidos cambian las cacas. Registra cada cambio de pañal en Anacan y analiza cómo reacciona tu bebé a los nuevos alimentos.', title_fr = 'On suit la digestion. 🧷', body_fr = 'Les aliments solides modifient les selles. Notez chaque change dans Anacan pour analyser la réaction de votre bébé aux nouveaux aliments.', title_hi = 'पाचन पर नज़र 🧷', body_hi = 'ठोस आहार से मल बदलता है। Anacan में हर डायपर बदलना दर्ज करके नए खानों पर बच्चे की प्रतिक्रिया समझिए।', title_id = 'Memantau pencernaan. 🧷', body_id = 'Makanan padat mengubah pola BAB-nya. Catat setiap ganti popok di Anacan dan amati reaksi bayi Anda terhadap makanan baru.', title_ja = '消化の様子を見守ろう。🧷', body_ja = '固形の食べ物でうんちが変わります。おむつ替えのたびにAnacanに記録して、新しい食べ物への赤ちゃんの反応を確かめましょう。', title_ko = '소화 과정 살피기 🧷', body_ko = '고형식은 변을 바꿔요. Anacan에 기저귀 교체를 빠짐없이 기록하며 새 음식에 대한 아기의 반응을 살펴보세요.', title_nl = 'We volgen de spijsvertering. 🧷', body_nl = 'Vast voedsel verandert de ontlasting. Noteer elke luierverschoning in Anacan en bekijk hoe je baby op nieuw eten reageert.', title_pl = 'Śledzimy trawienie. 🧷', body_pl = 'Stałe pokarmy zmieniają kupki. Zapisuj w Anacan każdą zmianę pieluszki i analizuj, jak maluszek reaguje na nowe pokarmy.', title_pt = 'Acompanhamos a digestão. 🧷', body_pt = 'Os alimentos sólidos mudam as fezes. Registe no Anacan cada muda de fralda e analise como o bebé reage aos novos alimentos.', title_sv = 'Vi följer matsmältningen. 🧷', body_sv = 'Fast föda förändrar bajset. Anteckna varje blöjbyte i Anacan och analysera hur barnet reagerar på den nya maten.', title_vi = 'Theo dõi quá trình tiêu hóa. 🧷', body_vi = 'Thức ăn đặc làm thay đổi phân của bé. Hãy ghi lại mỗi lần thay tã trong Anacan để phân tích phản ứng của bé với thực phẩm mới.', title_zh = '关注消化情况 🧷', body_zh = '固体食物会改变大便。在Anacan里记录每一次换尿布，了解宝宝对新食物的反应。' WHERE id = '8c057f2d-32f2-4561-9ca5-5bc651edddcc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hambre o cansancio? 😭', body_es = '¿Llora sin motivo y su llanto suena distinto? No hace falta agobiarse. Usa enseguida el Análisis del llanto y descubre el origen del problema.', title_fr = 'Faim ou fatigue ? 😭', body_fr = 'Il pleure sans raison et ses pleurs semblent différents ? Pas de panique. Faites tout de suite écouter ses pleurs à l''Analyse des pleurs et découvrez la source du problème.', title_hi = 'भूखा है या थका हुआ? 😭', body_hi = 'बिना वजह रो रहा है और आवाज़ अलग लग रही है? घबराने की ज़रूरत नहीं। तुरंत क्राइंग एनालिसिस से उसकी आवाज़ सुनवाइए और परेशानी की जड़ जानिए।', title_id = 'Lapar atau lelah? 😭', body_id = 'Ia menangis tanpa sebab dan suaranya terdengar berbeda? Tak perlu panik. Segera perdengarkan tangisannya ke Analisis Tangisan dan cari tahu akar masalahnya.', title_ja = 'お腹がすいた？それとも疲れた？😭', body_ja = '理由もなく泣いて、泣き声がいつもと違う？あわてなくて大丈夫。すぐに「泣き声分析」に泣き声を聞かせて、原因を知りましょう。', title_ko = '배고픈 걸까요, 피곤한 걸까요? 😭', body_ko = '이유 없이 울고 울음소리도 평소와 다른가요? 당황할 필요 없어요. 바로 울음 분석으로 소리를 들려주고 문제의 원인을 알아보세요.', title_nl = 'Honger of moe? 😭', body_nl = 'Huilt je baby zonder reden en klinkt het anders? Geen paniek. Laat Huilanalyse meteen luisteren en ontdek de oorzaak.', title_pl = 'Głodny czy zmęczony? 😭', body_pl = 'Płacze bez powodu, a jego głos brzmi inaczej? Nie panikuj. Od razu pozwól Analizie płaczu posłuchać dźwięku i poznaj źródło problemu.', title_pt = 'Fome ou cansaço? 😭', body_pt = 'Chora sem motivo e o choro soa diferente? Não há razão para alarme. Ponha já a Análise do Choro a ouvir e descubra a raiz do problema.', title_sv = 'Hungrig eller trött? 😭', body_sv = 'Gråter barnet utan anledning och låter annorlunda? Ingen anledning till panik. Låt Gråtanalys lyssna på ljudet direkt och ta reda på grundorsaken.', title_vi = 'Bé đói hay mệt? 😭', body_vi = 'Bé khóc không rõ lý do và tiếng khóc nghe khác lạ? Không cần hoảng hốt. Hãy cho Phân tích tiếng khóc nghe ngay và tìm ra gốc rễ vấn đề.', title_zh = '饿了还是累了？😭', body_zh = '宝宝无缘无故地哭，哭声还不太一样？不用慌。马上用哭声分析听一听，找出问题的根源。' WHERE id = '9fc39323-52a1-4045-aa65-bf5c16fac78f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Seguridad en casa! 🛡', body_es = '️ Cuanto más se mueve, más peligros hay. Mira nuestra lista de Productos recomendados para cierres de seguridad y protectores de esquinas.', title_fr = 'Sécurité à la maison ! 🛡', body_fr = '️Plus il bouge, plus les dangers augmentent. Consultez notre liste de Produits recommandés pour les bloque-portes et protections d''angle.', title_hi = 'घर में सुरक्षा के उपाय! 🛡', body_hi = '️वह जितना चलेगा-फिरेगा, खतरे भी उतने बढ़ेंगे। चाइल्ड लॉक और कॉर्नर गार्ड के लिए हमारी सुझाए गए प्रोडक्ट की सूची देखिए।', title_id = 'Keamanan di rumah! 🛡', body_id = '️ Makin aktif ia bergerak, makin banyak pula bahayanya. Lihat daftar Produk Rekomendasi kami untuk kunci pengaman anak dan pelindung sudut.', title_ja = 'おうちの安全対策！🛡', body_ja = '️ 動けるようになるほど、危険も増えます。チャイルドロックやコーナーガードは「おすすめ商品」リストでチェックしましょう。', title_ko = '집 안 안전 대책! 🛡', body_ko = '️ 아기가 많이 움직일수록 위험도 늘어나요. 안전 잠금장치와 모서리 보호대는 추천 제품 목록에서 확인하세요.', title_nl = 'Veiligheid in huis! 🛡', body_nl = '️ Hoe meer je baby beweegt, hoe meer gevaren er zijn. Bekijk in onze Aanbevolen producten kinderslotjes en hoekbeschermers.', title_pl = 'Bezpieczeństwo w domu! 🛡', body_pl = '️ Im więcej się rusza, tym więcej zagrożeń. Zajrzyj na naszą listę Polecanych produktów po blokady dla dzieci i osłonki na narożniki.', title_pt = 'Segurança em casa! 🛡', body_pt = '️ Quanto mais se mexe, maiores são os perigos. Veja na nossa lista de Produtos Recomendados os fechos de segurança e os protetores de cantos.', title_sv = 'Säkerhet i hemmet! 🛡', body_sv = '️ Ju mer barnet rör sig, desto fler faror. Kika i vår lista Rekommenderade produkter efter barnlås och kantskydd.', title_vi = 'Biện pháp an toàn trong nhà! 🛡', body_vi = '️ Bé càng vận động nhiều thì nguy hiểm càng tăng. Hãy xem danh sách Sản phẩm gợi ý để tìm khóa an toàn và miếng bọc góc cho trẻ.', title_zh = '居家安全措施！🛡', body_zh = '️ 宝宝越来越会动，危险也随之增加。去推荐商品清单里看看儿童安全锁和防撞角吧。' WHERE id = '05f5ce2b-27c1-4d94-b681-3d4e9ce809b6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hora de comer con las manos? 🥦', body_es = '¿Ya quiere coger la comida él solo? Para opciones seguras, echa un vistazo a las Recetas para bebés que empiezan con la alimentación complementaria.', title_fr = 'Place aux aliments à attraper ? 🥦', body_fr = 'Il veut déjà tenir sa nourriture tout seul ? Pour des options sûres, consultez les Recettes pour bébés qui commencent la diversification.', title_hi = 'फ़िंगर फ़ूड की ओर? 🥦', body_hi = 'वह अब खाना खुद पकड़ना चाहता है? सुरक्षित विकल्पों के लिए ऊपरी आहार शुरू करने वाले बच्चों की रेसिपी देखिए।', title_id = 'Saatnya finger food? 🥦', body_id = 'Ia sudah ingin memegang makanannya sendiri? Untuk pilihan yang aman, lihat Resep untuk bayi yang mulai MPASI.', title_ja = '手づかみ食べに挑戦？🥦', body_ja = 'もう自分で食べ物を持ちたがっていますか？安全なメニューは「離乳食を始める赤ちゃんのレシピ」でチェックしましょう。', title_ko = '핑거 푸드로 넘어갈까요? 🥦', body_ko = '이제 음식을 직접 잡고 싶어 하나요? 안전한 선택지를 위해 이유식을 시작하는 아기를 위한 레시피를 살펴보세요.', title_nl = 'Tijd voor vingervoedsel? 🥦', body_nl = 'Wil je baby het eten al zelf vastpakken? Kijk voor veilige opties bij de Recepten voor baby''s die met bijvoeding beginnen.', title_pl = 'Czas na jedzenie rączkami? 🥦', body_pl = 'Chce już sam trzymać jedzenie? Bezpieczne propozycje znajdziesz w Przepisach dla maluszków zaczynających rozszerzanie diety.', title_pt = 'Passar aos alimentos à mão? 🥦', body_pt = 'Já quer pegar sozinho na comida? Para opções seguras, espreite as Receitas para bebés em diversificação alimentar.', title_sv = 'Dags för fingermat? 🥦', body_sv = 'Vill barnet redan hålla i maten själv? Titta i Recept för barn som börjar med smakportioner efter säkra alternativ.', title_vi = 'Chuyển sang đồ ăn cầm tay? 🥦', body_vi = 'Bé đã muốn tự cầm đồ ăn? Hãy xem Công thức cho bé bắt đầu ăn dặm để có những lựa chọn an toàn.', title_zh = '开始吃手指食物？🥦', body_zh = '宝宝已经想自己拿着吃了？去“辅食宝宝食谱”里看看安全的选择吧。' WHERE id = 'a0d08200-8263-43d9-90a3-313dda8dadc9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Ejercicios para gatear! 🐢', body_es = '¿Se arrastra hacia atrás boca abajo o intenta ponerse de rodillas? Pregunta a Anacan AI por ejercicios útiles para ayudarle a gatear.', title_fr = 'Exercices de quatre pattes ! 🐢', body_fr = 'Il recule en rampant sur le ventre ou essaie de se mettre à genoux ? Demandez à Anacan AI des exercices utiles pour l''aider à marcher à quatre pattes.', title_hi = 'घुटनों के बल चलने का अभ्यास! 🐢', body_hi = 'वह पेट के बल पीछे की ओर खिसकता है या घुटनों पर उठने की कोशिश करता है? घुटनों के बल चलने में मदद करने वाली उपयोगी एक्सरसाइज़ Anacan AI से पूछिए।', title_id = 'Latihan merangkak! 🐢', body_id = 'Ia merayap mundur saat tengkurap atau mencoba bertumpu pada lutut? Tanyakan latihan yang bermanfaat untuk mendukung merangkak ke Anacan AI.', title_ja = 'はいはいの練習！🐢', body_ja = 'うつぶせで後ろに進んだり、ひざで立とうとしたりしていますか？はいはいを応援する役立つ練習を、Anacan AIに聞いてみましょう。', title_ko = '기어가기 연습! 🐢', body_ko = '배로 뒤로 밀려나거나 무릎으로 일어서려 하나요? 기어가기를 돕는 유용한 운동을 Anacan AI에게 물어보세요.', title_nl = 'Kruipoefeningen! 🐢', body_nl = 'Schuift je baby op de buik achteruit of probeert hij op zijn knieën te komen? Vraag Anacan AI naar handige oefeningen om het kruipen te stimuleren.', title_pl = 'Ćwiczenia raczkowania! 🐢', body_pl = 'Pełza na brzuszku do tyłu albo próbuje stanąć na kolanach? Zapytaj Anacan AI o przydatne ćwiczenia wspierające raczkowanie.', title_pt = 'Treinos para gatinhar! 🐢', body_pt = 'Arrasta-se para trás de barriga para baixo ou tenta pôr-se de joelhos? Pergunte ao Anacan AI que exercícios ajudam a gatinhar.', title_sv = 'Krypövningar! 🐢', body_sv = 'Ålar barnet bakåt på magen eller försöker resa sig upp på knäna? Fråga Anacan AI om nyttiga övningar som stöttar krypandet.', title_vi = 'Tập bò! 🐢', body_vi = 'Bé trườn lùi khi nằm sấp hay cố chống gối lên? Hãy hỏi Anacan AI những bài tập hữu ích để hỗ trợ bé tập bò.', title_zh = '爬行练习！🐢', body_zh = '宝宝趴着往后退，或者想用膝盖撑起来？向Anacan AI问问有助于爬行的练习吧。' WHERE id = 'ef507e65-7f14-47a2-8b48-8ce6e3e1fc96' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La leche materna sigue siendo lo principal! 🍼', body_es = 'Aunque ya tome alimentación complementaria, usa el temporizador de tomas para asegurarte de que cubre su necesidad diaria de leche.', title_fr = 'Le lait maternel reste essentiel ! 🍼', body_fr = 'Malgré la diversification, lancez le minuteur de repas pour vous assurer que ses besoins quotidiens en lait sont couverts.', title_hi = 'माँ का दूध अब भी सबसे अहम है! 🍼', body_hi = 'ऊपरी आहार के बावजूद फ़ीडिंग टाइमर चालू करके पक्का कीजिए कि रोज़ की दूध की ज़रूरत पूरी हो रही है।', title_id = 'ASI tetap yang utama! 🍼', body_id = 'Meski sudah MPASI, nyalakan timer menyusui dan pastikan kebutuhan susu hariannya terpenuhi.', title_ja = '母乳・ミルクはまだ主役！🍼', body_ja = '離乳食を始めても、授乳タイマーを使って1日に必要なミルクの量をとれているか確かめましょう。', title_ko = '모유는 여전히 중요해요! 🍼', body_ko = '이유식을 하더라도 수유 타이머를 켜서 하루 수유량이 충분한지 확인하세요.', title_nl = 'Moedermelk is nog steeds de basis! 🍼', body_nl = 'Ook met bijvoeding: zet de voedingstimer aan en zorg ervoor dat je baby dagelijks genoeg melk krijgt.', title_pl = 'Mleko mamy wciąż jest podstawą! 🍼', body_pl = 'Mimo rozszerzania diety włączaj timer karmienia i upewnij się, że dzienne zapotrzebowanie na mleko jest zaspokojone.', title_pt = 'O leite materno continua a ser a base! 🍼', body_pt = 'Mesmo com a diversificação alimentar, ligue o temporizador de alimentação e confirme que as necessidades diárias de leite estão cobertas.', title_sv = 'Bröstmjölken är fortfarande grunden! 🍼', body_sv = 'Trots smakportionerna, se till att det dagliga mjölkbehovet täcks genom att starta matningstimern.', title_vi = 'Sữa mẹ vẫn là chính! 🍼', body_vi = 'Dù đã ăn dặm, hãy bật Hẹn giờ cho bú để chắc chắn bé được đáp ứng đủ nhu cầu sữa mỗi ngày.', title_zh = '母乳仍然是主角！🍼', body_zh = '即使添加了辅食，也要用喂养计时器确认宝宝每天的奶量需求得到满足。' WHERE id = '52134c06-b272-4f5f-93b6-cf014fc0e867' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Una bomba de energía para mamás! 🥗', body_es = '¡Que tú también comas sano es imprescindible! Prepara con Recetas saludables una ensalada o un smoothie lleno de vitaminas que te dé energía.', title_fr = 'Une bombe d''énergie pour maman ! 🥗', body_fr = 'Votre alimentation saine compte aussi ! Préparez avec les Recettes saines une salade ou un smoothie plein de vitamines qui boostera votre énergie.', title_hi = 'माँओं के लिए ऊर्जा का खज़ाना! 🥗', body_hi = 'आपका सेहतमंद खाना भी ज़रूरी है! सेहतमंद रेसिपी से ऊर्जा बढ़ाने वाला विटामिन भरा सलाद या स्मूदी बनाइए।', title_id = 'Bom energi untuk Bunda! 🥗', body_id = 'Anda juga wajib makan sehat! Buat salad atau smoothie kaya vitamin dari Resep Sehat untuk menambah energi.', title_ja = 'ママのための元気チャージ！🥗', body_ja = 'あなたが健康的に食べることも大切です！「ヘルシーレシピ」から、元気が出るビタミンたっぷりのサラダやスムージーをつくりましょう。', title_ko = '엄마를 위한 에너지 폭탄! 🥗', body_ko = '엄마도 건강하게 먹어야 해요! 건강한 레시피에서 에너지를 높여 줄 비타민 가득한 샐러드나 스무디를 만들어 보세요.', title_nl = 'Een energiebom voor mama''s! 🥗', body_nl = 'Ook jij moet gezond eten! Maak uit Gezonde recepten een vitaminerijke salade of smoothie die je energie geeft.', title_pl = 'Bomba energii dla mam! 🥗', body_pl = 'Twoje zdrowe odżywianie też jest konieczne! Przygotuj ze Zdrowych przepisów witaminową sałatkę lub smoothie, które dodadzą ci energii.', title_pt = 'Uma bomba de energia para as mães! 🥗', body_pt = 'A sua alimentação saudável também é essencial! Prepare uma salada ou um smoothie cheio de vitaminas das Receitas Saudáveis para ganhar energia.', title_sv = 'Energibomb för mammor! 🥗', body_sv = 'Det är viktigt att du också äter hälsosamt! Gör en vitaminrik sallad eller smoothie från Hälsosamma recept som ger dig mer energi.', title_vi = 'Bom năng lượng cho mẹ! 🥗', body_vi = 'Mẹ cũng cần ăn uống lành mạnh! Hãy làm một món salad hay sinh tố giàu vitamin từ Công thức lành mạnh để tăng năng lượng.', title_zh = '妈妈的能量炸弹！🥗', body_zh = '你也一定要吃得健康！从健康食谱里做一份富含维生素的沙拉或奶昔，给自己补充能量吧。' WHERE id = '62cb9c93-e0de-4d15-8d33-e81c1723d1db' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche léele un cuento cortito simplemente con tu voz. La voz de mamá es la música favorita de tu bebé.', body_fr = 'Ce soir, lisez-lui simplement un petit conte avec votre propre voix. La voix de maman est la musique préférée de l''enfant.', body_hi = 'आज शाम बस अपनी आवाज़ में उसे एक छोटी कहानी सुनाइए। माँ की आवाज़ बच्चे का सबसे पसंदीदा संगीत है।', body_id = 'Malam ini, bacakan dongeng singkat dengan suara Anda sendiri. Suara ibu adalah musik favorit si kecil.', body_ja = '今夜は、あなた自身の声で短いお話を読んであげましょう。ママの声は、赤ちゃんがいちばん好きな音楽です。', body_ko = '오늘 저녁은 엄마 목소리로 짧은 동화를 읽어 주세요. 엄마 목소리는 아이가 가장 좋아하는 음악이에요.', body_nl = 'Lees je baby vanavond gewoon met je eigen stem een kort sprookje voor. Mama''s stem is zijn favoriete muziek.', body_pl = 'Dziś wieczorem po prostu przeczytaj maluszkowi własnym głosem krótką bajkę. Głos mamy to jego ulubiona muzyka.', body_pt = 'Esta noite, leia-lhe simplesmente uma história curta com a sua própria voz. A voz da mãe é a música preferida do bebé.', body_sv = 'I kväll, läs bara en kort saga för barnet med din egen röst. Mammas röst är barnets favoritmusik.', body_vi = 'Tối nay chỉ cần đọc cho bé một câu chuyện ngắn bằng chính giọng của mẹ. Giọng mẹ là bản nhạc bé yêu thích nhất.', body_zh = '今晚就用你自己的声音给宝宝读一个短短的故事吧。妈妈的声音是宝宝最爱的音乐。' WHERE id = 'f25f7637-e945-4232-a1c1-f7594c81a0b3' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'En cuanto se duerma, no corras a las tareas de casa. Siéntate en el sofá, tómate tu café y durante 10 minutos simplemente mira la pared y respira.', body_fr = 'Dès qu''il s''endort, ne courez pas vers les tâches ménagères. Asseyez-vous sur le canapé, buvez votre café et, pendant 10 minutes, regardez simplement le mur en respirant.', body_hi = 'बच्चे के सोते ही घर के कामों की ओर मत भागिए। सोफ़े पर बैठिए, अपनी कॉफ़ी पीजिए और 10 मिनट बस दीवार को देखते हुए साँस लीजिए।', body_id = 'Jangan langsung mengerjakan pekerjaan rumah begitu ia tidur. Duduklah di sofa, minum kopi, dan tarik napas sambil memandangi dinding selama 10 menit.', body_ja = '赤ちゃんが寝たらすぐに家事に走らないで。ソファに座ってコーヒーを飲み、10分間ただ壁を見つめて深呼吸しましょう。', body_ko = '아이가 잠들자마자 집안일로 달려가지 마세요. 소파에 앉아 커피를 마시며 10분 동안 그냥 벽을 바라보며 숨을 고르세요.', body_nl = 'Ren niet naar het huishouden zodra je baby slaapt. Ga op de bank zitten, drink je koffie en kijk 10 minuten gewoon naar de muur en adem.', body_pl = 'Gdy tylko maluszek zaśnie, nie biegnij do obowiązków. Usiądź na kanapie, wypij kawę i przez 10 minut po prostu patrz w ścianę i oddychaj.', body_pt = 'Mal o bebé adormeça, não corra para as tarefas da casa. Sente-se no sofá, beba o seu café e respire durante 10 minutos a olhar para a parede.', body_sv = 'Rusa inte till hushållet så fort barnet somnar. Sätt dig i soffan, drick ditt kaffe och stirra bara in i väggen och andas i 10 minuter.', body_vi = 'Bé vừa ngủ thì đừng vội lao vào việc nhà. Hãy ngồi xuống ghế sofa, nhâm nhi cà phê và chỉ ngắm bức tường, hít thở trong 10 phút.', body_zh = '宝宝一睡着别急着做家务。坐在沙发上，喝杯咖啡，就这么对着墙呼吸10分钟吧。' WHERE id = '74e14338-c8e1-4b5c-b426-24332f30b919' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mañanas caprichosas ☁️', body_es = '¿Esta mañana nada le parece bien? Pueden ser los dientes o un salto de desarrollo. Simplemente abrázale más y hazle sentir seguro.', title_fr = 'Matins grognons ☁️', body_fr = 'Rien ne lui convient ce matin ? Ce sont peut-être les dents ou un pic de développement. Câlinez-le simplement davantage et faites-le se sentir en sécurité.', title_hi = 'चिड़चिड़ी सुबहें ☁️', body_hi = 'आज सुबह किसी बात से खुश नहीं है? यह दाँत का दर्द या विकास की छलांग हो सकती है। उसे बस ज़्यादा गले लगाइए और सुरक्षित महसूस कराइए।', title_id = 'Pagi yang rewel ☁️', body_id = 'Pagi ini tidak ada yang membuatnya senang? Mungkin karena tumbuh gigi atau lompatan perkembangan. Cukup peluk ia lebih sering dan buat ia merasa aman.', title_ja = 'ご機嫌ななめの朝 ☁️', body_ja = '今朝は何をしても気に入らない？歯が生えてくる痛みか、成長の時期かもしれません。たっぷり抱っこして、安心させてあげましょう。', title_ko = '칭얼대는 아침 ☁️', body_ko = '오늘 아침 아무것도 마음에 들지 않나요? 이앓이 통증이나 발달 도약일 수 있어요. 더 많이 안아 주며 안심시켜 주세요.', title_nl = 'Mopperige ochtenden ☁️', body_nl = 'Is je baby vanochtend nergens tevreden mee? Het kunnen doorkomende tandjes of een sprongetje zijn. Knuffel hem gewoon wat meer en laat hem zich veilig voelen.', title_pl = 'Marudne poranki ☁️', body_pl = 'Dziś rano nic mu nie pasuje? To może być ból ząbkowania albo skok rozwojowy. Po prostu częściej go przytulaj i daj mu poczucie bezpieczeństwa.', title_pt = 'Manhãs rabugentas ☁️', body_pt = 'Esta manhã nada o contenta? Podem ser os dentes ou um salto de desenvolvimento. Dê-lhe mais colo e faça-o sentir-se seguro.', title_sv = 'Gnälliga morgnar ☁️', body_sv = 'Är barnet missnöjt med allt i morse? Det kan vara tandvärk eller ett utvecklingssprång. Krama det bara lite extra och låt det känna sig tryggt.', title_vi = 'Buổi sáng quấy khóc ☁️', body_vi = 'Sáng nay bé không hài lòng với điều gì cả? Có thể do đau răng hoặc bước nhảy phát triển. Chỉ cần ôm bé nhiều hơn và cho bé cảm giác an toàn.', title_zh = '闹脾气的早晨 ☁️', body_zh = '今天早上宝宝怎么都不满意？可能是长牙疼或者发育飞跃期。多抱抱宝宝，让宝宝感到安全吧。' WHERE id = 'bb4d4aaf-f143-4aa9-b4e0-7b7a4fc4ea1f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Juego de permanencia del objeto! 🧸', body_es = 'Esconde su juguete bajo una manta y deja que lo encuentre. Mientras jugáis a este juego de ingenio, captura su alegría con la Sesión de fotos del bebé.', title_fr = 'Le jeu de la permanence de l''objet ! 🧸', body_fr = 'Cachez son jouet sous une couverture et laissez-le le trouver. Pendant ce jeu d''éveil, capturez sa joie avec la Séance photo bébé.', title_hi = 'चीज़ों के बने रहने का खेल! 🧸', body_hi = 'उसका खिलौना किसी कपड़े के नीचे छिपाइए और उसे ढूँढने दीजिए। यह दिमागी खेल खेलते हुए बेबी फ़ोटोशूट से उसकी खुशी कैद कीजिए।', title_id = 'Permainan benda tetap ada! 🧸', body_id = 'Sembunyikan mainannya di bawah kain dan biarkan ia menemukannya. Saat memainkan permainan asah otak ini, abadikan kegembiraannya dengan Sesi Foto Bayi.', title_ja = '見えなくてもあるよ遊び！🧸', body_ja = 'おもちゃを布の下に隠して、見つけさせてあげましょう。この頭を使う遊びをしながら、喜ぶ姿を「ベビーフォトセッション」で撮りましょう。', title_ko = '대상 영속성 놀이! 🧸', body_ko = '장난감을 천 아래에 숨기고 찾게 해 주세요. 이 두뇌 놀이를 하는 동안 아기 사진 촬영으로 아기의 기쁨을 담아 보세요.', title_nl = 'Een spelletje over dingen die blijven bestaan! 🧸', body_nl = 'Verstop zijn speeltje onder een doek en laat hem het vinden. Leg zijn blijdschap tijdens dit slimme spelletje vast met Babyfotoshoot.', title_pl = 'Zabawa w stałość przedmiotu! 🧸', body_pl = 'Schowaj zabawkę pod kocykiem i pozwól mu ją znaleźć. Podczas tej mądrej zabawy uchwyć jego radość w Sesji zdjęciowej dziecka.', title_pt = 'O jogo da permanência dos objetos! 🧸', body_pt = 'Esconda o brinquedo debaixo de um pano e deixe-o encontrá-lo. Enquanto jogam este jogo de inteligência, fotografe a alegria dele com a Sessão Fotográfica do Bebé.', title_sv = 'Leken om att saker finns kvar! 🧸', body_sv = 'Göm leksaken under en filt och låt barnet hitta den. Fånga glädjen med Babyfotografering medan ni leker den här klurighetsleken.', title_vi = 'Trò chơi đồ vật vẫn tồn tại! 🧸', body_vi = 'Giấu đồ chơi dưới một tấm khăn và để bé tìm. Trong lúc chơi trò chơi trí tuệ này, hãy dùng Chụp ảnh cho bé để ghi lại niềm vui của bé.', title_zh = '物体恒存游戏！🧸', body_zh = '把玩具藏在布下面，让宝宝自己找出来。玩这个益智游戏时，用宝宝写真拍下宝宝开心的样子吧。' WHERE id = '6ac03f7c-34a8-46f5-96a4-c1aa521476a5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hay cosas del bebé por toda la casa? 🌪️', title_fr = 'Des affaires de bébé partout dans la maison ? 🌪️', title_hi = 'घर में हर जगह बच्चे का सामान? 🌪️', title_id = 'Barang bayi di setiap sudut rumah? 🌪️', title_ja = '家中に赤ちゃんグッズ？🌪️', title_ko = '집 안 곳곳에 아기 물건이 가득한가요? 🌪️', title_nl = 'Overal babyspullen in huis? 🌪️', title_pl = 'Wszędzie w domu rzeczy dziecka? 🌪️', title_pt = 'Há coisas do bebé por toda a casa? 🌪️', title_sv = 'Barnsaker överallt i hemmet? 🌪️', title_vi = 'Đồ của bé khắp nhà? 🌪️', title_zh = '家里到处都是宝宝的东西？🌪️' WHERE id = '746b1115-b7ff-4fd7-b04a-46935d1a6f43' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Si esta noche tu bebé no puede dormirse por la emoción de sus nuevas habilidades, pon el sonido del útero materno en Ruido blanco.', body_fr = 'Si ce soir votre bébé n''arrive pas à dormir, trop excité par ses nouvelles compétences, lancez le son du ventre maternel dans les Bruits blancs.', body_hi = 'अगर आज शाम नए हुनर के उत्साह में बच्चा सो नहीं पा रहा, तो व्हाइट नॉइज़ में गर्भ की आवाज़ चलाइए।', body_id = 'Jika malam ini si kecil tidak bisa tidur karena terlalu bersemangat dengan keterampilan barunya, putar suara rahim dari White Noise.', body_ja = '新しくできるようになったことに興奮して今夜眠れないなら、「ホワイトノイズ」から胎内の音を流してあげましょう。', body_ko = '새로 익힌 능력에 들떠 오늘 밤 잠들지 못한다면 백색소음에서 엄마 배 속 소리를 틀어 주세요.', body_nl = 'Kan je baby vanavond niet slapen van opwinding over zijn nieuwe vaardigheden? Zet in Witte ruis het baarmoedergeluid aan.', body_pl = 'Jeśli maluszek nie może dziś zasnąć z ekscytacji nowymi umiejętnościami, włącz w Białym szumie odgłosy z brzucha mamy.', body_pt = 'Se esta noite o bebé não consegue dormir com a excitação das novas conquistas, ponha no Ruído Branco o som do ventre materno.', body_sv = 'Om barnet inte kan somna i kväll för att det är så uppspelt av sina nya färdigheter, sätt på ljudet från livmodern i Vitt brus.', body_vi = 'Nếu tối nay bé không ngủ được vì háo hức với những kỹ năng mới, hãy bật âm thanh trong bụng mẹ từ mục Tiếng ồn trắng.', body_zh = '如果宝宝今晚因为学会新技能太兴奋而睡不着，就在白噪音里播放妈妈子宫里的声音吧。' WHERE id = 'bc99d2a9-e4a6-4af7-937f-bb0a7a91d292' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'A dormir con música 🛀', body_es = '¿La rutina de la noche se ha complicado? Pon música relajante de fondo durante el baño templado. La armonía del agua y la melodía calma hasta al peque más testarudo.', title_fr = 'S''endormir en musique 🛀', body_fr = 'La routine du soir devient difficile ? Pendant le bain tiède, mettez une musique apaisante en fond. L''harmonie de l''eau et de la mélodie adoucit même l''enfant le plus têtu.', title_hi = 'संगीत के साथ नींद की ओर 🛀', body_hi = 'शाम का रूटीन मुश्किल हो गया है? गुनगुने स्नान के समय पीछे सुकून भरा संगीत चलाइए। पानी और धुन का मेल सबसे ज़िद्दी बच्चे को भी शांत कर देता है।', title_id = 'Menuju tidur dengan musik 🛀', body_id = 'Rutinitas malam makin sulit? Putar musik yang menenangkan saat mandi air hangat. Perpaduan air dan melodi bisa meluluhkan anak yang paling keras kepala sekalipun.', title_ja = '音楽でねんねへ 🛀', body_ja = '夜のルーティンが大変になってきた？ぬるめのお風呂の間、静かな音楽を流しましょう。お湯とメロディーのハーモニーは、どんなにがんこな子もやわらげてくれます。', title_ko = '음악과 함께 꿈나라로 🛀', body_ko = '저녁 루틴이 힘들어졌나요? 따뜻한 물로 목욕할 때 잔잔한 음악을 틀어 주세요. 물과 멜로디의 조화가 고집 센 아이도 부드럽게 풀어 줘요.', title_nl = 'Met muziek naar dromenland 🛀', body_nl = 'Is de avondroutine lastiger geworden? Zet tijdens het lauwe badje rustgevende muziek op de achtergrond aan. Water en melodie samen kalmeren zelfs het koppigste kind.', title_pl = 'Zasypianie przy muzyce 🛀', body_pl = 'Wieczorna rutyna stała się trudna? Podczas ciepłej kąpieli włącz w tle kojącą muzykę. Harmonia wody i melodii uspokaja nawet najbardziej upartego malucha.', title_pt = 'Adormecer com música 🛀', body_pt = 'A rotina da noite ficou difícil? Durante o banho morno, ponha música calmante em fundo. A harmonia entre a água e a melodia acalma até o bebé mais teimoso.', title_sv = 'Musikalisk övergång till sömnen 🛀', body_sv = 'Har kvällsrutinen blivit svårare? Sätt på lugnande musik i bakgrunden när barnet badar ljummet. Vattnets och melodins harmoni mjukar upp även det envisaste barn.', title_vi = 'Vào giấc cùng âm nhạc 🛀', body_vi = 'Nếp sinh hoạt buổi tối trở nên khó khăn? Khi tắm nước ấm cho bé, hãy mở nhạc êm dịu làm nền. Sự hòa quyện giữa nước và giai điệu sẽ làm dịu cả em bé bướng bỉnh nhất.', title_zh = '伴着音乐入睡 🛀', body_zh = '晚间作息变难了？洗温水澡时放点舒缓的背景音乐。水声和旋律的和谐，连最倔的宝宝也能被安抚。' WHERE id = '30560050-23fa-4905-9bfc-f3082838579d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Experto en el escondite 🙈', body_es = 'Taparse la cara con las manos y jugar al cucú-tras es su actividad favorita de la tarde.', title_fr = 'Champion de cache-cache 🙈', body_fr = 'Se cacher le visage avec les mains pour jouer à coucou-caché, c''est son activité préférée du soir.', title_hi = 'लुका-छिपी का उस्ताद 🙈', body_hi = 'हाथों से चेहरा ढककर झाँकी-झाँकी खेलना उसकी शाम की सबसे पसंदीदा गतिविधि है।', title_id = 'Jago petak umpet 🙈', body_id = 'Menutup wajah dengan tangan dan bermain cilukba adalah aktivitas sore favoritnya.', title_ja = 'かくれんぼの名人 🙈', body_ja = '両手で顔を隠して「いないいないばあ」をするのが、夕方のいちばんのお気に入りです。', title_ko = '숨바꼭질 달인 🙈', body_ko = '손으로 얼굴을 가리고 까꿍 놀이를 하는 게 아기가 가장 좋아하는 저녁 놀이예요.', title_nl = 'Meester in verstoppertje 🙈', body_nl = 'Zijn gezichtje met zijn handjes bedekken en kiekeboe spelen is zijn favoriete avondactiviteit.', title_pl = 'Mistrz chowanego 🙈', body_pl = 'Zasłanianie buzi rączkami i zabawa w a kuku to jego ulubione wieczorne zajęcie.', title_pt = 'Mestre das escondidas 🙈', body_pt = 'Tapar o rosto com as mãos e brincar ao cucu é a sua atividade preferida ao fim do dia.', title_sv = 'Mästare på kurragömma 🙈', body_sv = 'Att täcka ansiktet med händerna och leka tittut är barnets favoritaktivitet på kvällen.', title_vi = 'Bậc thầy trốn tìm 🙈', body_vi = 'Lấy tay che mặt chơi ú òa là hoạt động buổi tối bé thích nhất.', title_zh = '躲猫猫高手 🙈', body_zh = '用小手捂住脸玩躲猫猫，是宝宝晚上最爱的活动。' WHERE id = 'bf07c6c2-b84c-44ed-9459-f26c37f0e099' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dudas pediátricas 🤖', title_fr = 'Des doutes pédiatriques 🤖', title_hi = 'बच्चे की सेहत को लेकर सवाल 🤖', title_id = 'Keraguan seputar kesehatan anak 🤖', title_ja = '育児の疑問 🤖', title_ko = '소아과 궁금증 🤖', title_nl = 'Twijfels over je kindje 🤖', title_pl = 'Pediatryczne wątpliwości 🤖', title_pt = 'Dúvidas pediátricas 🤖', title_sv = 'Barnmedicinska funderingar 🤖', title_vi = 'Băn khoăn về nhi khoa 🤖', title_zh = '儿科疑虑 🤖' WHERE id = '47b60c96-b788-4cad-9b79-643917c1b944' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Quién hace las tareas de casa? 🌪️', title_fr = 'Qui s''occupe du ménage ? 🌪️', title_hi = 'घर का काम कौन करेगा? 🌪️', title_id = 'Siapa yang mengurus rumah? 🌪️', title_ja = '家事は誰がする？🌪️', title_ko = '집안일은 누가 할까요? 🌪️', title_nl = 'Wie doet het huishouden? 🌪️', title_pl = 'Kto zajmie się domem? 🌪️', title_pt = 'Quem vai tratar da casa? 🌪️', title_sv = 'Vem tar hushållet? 🌪️', title_vi = 'Ai sẽ làm việc nhà? 🌪️', title_zh = '家务谁来做？🌪️' WHERE id = '295a4c1e-3bba-40c5-820d-04095aefe60e' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fase del «es mío» 🛑', body_es = '¿Se enfada cuando le quitas algo peligroso de las manos? En vez de prohibir, desvía su atención hacia otro juguete con más sonido y color y esquiva estas pequeñas crisis.', title_fr = 'La phase « C''est à moi ! » 🛑', body_fr = 'Il se fâche quand vous lui retirez un objet dangereux des mains ? Plutôt que d''interdire, détournez son attention vers un autre jouet plus sonore et coloré pour éviter ces petites crises.', title_hi = '''यह मेरा है'' वाली ज़िद 🛑', body_hi = 'उसके हाथ से कोई खतरनाक चीज़ लेने पर वह गुस्सा हो जाता है? मना करने के बजाय उसका ध्यान आवाज़ और रंगों वाले किसी दूसरे खिलौने की ओर मोड़िए और इन छोटे-छोटे दौरों से बचिए।', title_id = 'Fase "Ini punyaku!" 🛑', body_id = 'Ia marah saat Anda mengambil benda berbahaya dari tangannya? Daripada melarang, alihkan perhatiannya ke mainan lain yang lebih berbunyi dan berwarna untuk melewati drama kecil ini.', title_ja = '「ぼくの！わたしの！」の時期 🛑', body_ja = '危ないものを手から取り上げると怒りますか？ダメと言う代わりに、音が鳴るカラフルな別のおもちゃに気をそらして、小さなかんしゃくを乗り切りましょう。', title_ko = '''내 거야'' 고집 🛑', body_ko = '위험한 물건을 손에서 빼면 화를 내나요? 금지하는 대신 소리 나고 알록달록한 다른 장난감으로 관심을 돌려 이 작은 떼쓰기를 넘겨 보세요.', title_nl = 'Dat is van mij! 🛑', body_nl = 'Wordt je baby boos als je iets gevaarlijks uit zijn handjes pakt? Verbied het niet alleen, maar leid zijn aandacht af met een ander speeltje met meer geluid en kleur, en kom zo deze kleine crisisjes door.', title_pl = 'Upór: to moje 🛑', body_pl = 'Złości się, gdy zabierasz mu z rączki coś niebezpiecznego? Zamiast zakazywać, odwróć jego uwagę głośniejszą i bardziej kolorową zabawką i ominiesz te małe kryzysy.', title_pt = 'A teimosia do "É meu" 🛑', body_pt = 'Zanga-se quando lhe tira um objeto perigoso? Em vez de proibir, desvie a atenção dele para outro brinquedo mais barulhento e colorido e evite estas pequenas crises.', title_sv = 'Den är min-envisheten 🛑', body_sv = 'Blir barnet argt när du tar något farligt ur händerna på det? I stället för att förbjuda, led om uppmärksamheten till en annan leksak med mer ljud och färg, så slipper ni de små utbrotten.', title_vi = 'Giai đoạn "Của con!" 🛑', body_vi = 'Bé nổi giận khi mẹ lấy đi món đồ nguy hiểm khỏi tay? Thay vì cấm đoán, hãy hướng sự chú ý của bé sang một món đồ chơi khác nhiều âm thanh và màu sắc hơn để vượt qua những cơn quấy nhỏ này.', title_zh = '“这是我的！”阶段 🛑', body_zh = '从宝宝手里拿走危险物品时宝宝会生气？与其禁止，不如用另一个声音更响、颜色更鲜艳的玩具转移注意力，轻松化解这些小脾气。' WHERE id = '5b09b018-664d-4b58-86b9-31b6e1d3baf2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Nana de papá 👨‍🍼', body_es = 'Esta noche, todas las nanas y cuentos para dormir son tarea de papá.', title_fr = 'Une berceuse de papa 👨‍🍼', body_fr = 'Cette nuit, toutes les berceuses et tous les contes pour l''endormissement sont la mission de papa.', title_hi = 'पापा की लोरी 👨‍🍼', body_hi = 'आज रात सोने से पहले की सारी लोरियाँ और कहानियाँ पापा की ज़िम्मेदारी हैं।', title_id = 'Nina bobo dari ayah 👨‍🍼', body_id = 'Malam ini, semua nina bobo dan dongeng pengantar tidur menjadi tugas ayah.', title_ja = 'パパの子守唄 👨‍🍼', body_ja = '今夜のねんねのための子守唄とお話は、すべてパパの担当です。', title_ko = '아빠의 자장가 👨‍🍼', body_ko = '오늘 밤 잠들기 전 부르는 자장가와 동화는 모두 아빠 몫이에요.', title_nl = 'Een slaapliedje van papa 👨‍🍼', body_nl = 'Vannacht zijn alle slaapliedjes en sprookjes voor het slapengaan de taak van papa.', title_pl = 'Kołysanka od taty 👨‍🍼', body_pl = 'Dziś wieczorem wszystkie kołysanki i bajki na dobranoc to zadanie taty.', title_pt = 'Uma canção de embalar do pai 👨‍🍼', body_pt = 'Esta noite, todas as canções de embalar e histórias para adormecer ficam a cargo do pai.', title_sv = 'Vaggvisa från pappa 👨‍🍼', body_sv = 'I natt är alla vaggvisor och sagor inför sömnen pappas uppgift.', title_vi = 'Lời ru của bố 👨‍🍼', body_vi = 'Tối nay, tất cả bài hát ru và câu chuyện đưa bé vào giấc ngủ đều là nhiệm vụ của bố.', title_zh = '爸爸的摇篮曲 👨‍🍼', body_zh = '今晚哄睡时所有的摇篮曲和故事都交给爸爸。' WHERE id = 'ea9b5851-8f4a-4a19-990c-97e725808bb5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una obra de arte en el plato 🥦', body_es = '¿No se come el puré? A veces el problema no es el sabor, sino el aspecto. Con Recetas saludables crea caritas divertidas con verduras de colores y abre su apetito.', title_fr = 'Une œuvre d''art dans l''assiette 🥦', body_fr = 'Il ne mange pas sa purée ? Parfois, le problème n''est pas le goût mais l''aspect. Avec les Recettes saines, créez des visages amusants avec des légumes colorés pour lui ouvrir l''appétit.', title_hi = 'प्लेट में कलाकृति 🥦', body_hi = 'वह प्यूरी नहीं खाता? कभी-कभी समस्या स्वाद में नहीं, दिखावट में होती है। सेहतमंद रेसिपी की मदद से रंग-बिरंगी सब्ज़ियों से मज़ेदार चेहरे बनाइए और उसकी भूख जगाइए।', title_id = 'Karya seni di piring 🥦', body_id = 'Ia tidak mau makan puree? Kadang masalahnya bukan rasa, melainkan tampilan. Gunakan Resep Sehat untuk membuat wajah lucu dari sayuran warna-warni dan bangkitkan selera makannya.', title_ja = 'お皿の上のアート 🥦', body_ja = 'ペーストを食べない？味ではなく、見た目が問題のこともあります。「ヘルシーレシピ」を参考に、カラフルな野菜で楽しい顔をつくって食欲をそそりましょう。', title_ko = '접시 위의 예술 작품 🥦', body_ko = '퓌레를 안 먹나요? 때로는 맛이 아니라 모양이 문제예요. 건강한 레시피를 활용해 알록달록한 채소로 재미있는 얼굴을 만들어 입맛을 돋워 보세요.', title_nl = 'Een kunstwerk op het bord 🥦', body_nl = 'Eet je baby de hap niet? Soms zit het probleem niet in de smaak, maar in het uiterlijk. Maak met Gezonde recepten grappige gezichtjes van kleurige groenten en wek zijn eetlust.', title_pl = 'Dzieło sztuki na talerzu 🥦', body_pl = 'Nie chce jeść przecieru? Czasem problemem nie jest smak, tylko wygląd. Korzystając ze Zdrowych przepisów, ułóż z kolorowych warzyw zabawne buźki i pobudź jego apetyt.', title_pt = 'Uma obra de arte no prato 🥦', body_pt = 'Não come o puré? Às vezes o problema não é o sabor, é o aspeto. Com as Receitas Saudáveis, crie caras divertidas com legumes coloridos e abra-lhe o apetite.', title_sv = 'Ett konstverk på tallriken 🥦', body_sv = 'Äter barnet inte purén? Ibland är problemet inte smaken utan utseendet. Gör roliga ansikten av färgglada grönsaker med hjälp av Hälsosamma recept och väck aptiten.', title_vi = 'Tác phẩm nghệ thuật trên đĩa 🥦', body_vi = 'Bé không chịu ăn món nghiền? Đôi khi vấn đề không nằm ở hương vị mà ở hình thức. Hãy dùng Công thức lành mạnh để tạo những gương mặt vui nhộn từ rau củ nhiều màu sắc, giúp bé ăn ngon miệng hơn.', title_zh = '盘子里的艺术品 🥦', body_zh = '宝宝不吃果泥？有时问题不在味道，而在外观。用健康食谱里五颜六色的蔬菜摆出有趣的笑脸，打开宝宝的胃口吧。' WHERE id = '698ffa60-da73-4003-9656-db865993d1b5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sueño sensible 🤫', body_es = '¿En cuanto se duerme se sobresalta con el menor ruido? Revisa la acústica de la habitación con el Medidor de sonido y pon ruido blanco para neutralizar los ruidos de la ventana.', title_fr = 'Un sommeil sensible 🤫', body_fr = 'À peine endormi, il sursaute au moindre bruit ? Vérifiez l''acoustique de la pièce avec le Sonomètre et lancez un bruit blanc pour neutraliser les sons venant de la fenêtre.', title_hi = 'नींद में संवेदनशीलता 🤫', body_hi = 'सोते ही ज़रा सी खटखट पर चौंक जाता है? साउंड मीटर से कमरे की आवाज़ जाँचिए और खिड़की से आने वाली आवाज़ों को दबाने के लिए व्हाइट नॉइज़ चलाइए।', title_id = 'Tidur yang sensitif 🤫', body_id = 'Begitu tertidur, ia terkejut oleh ketukan sekecil apa pun? Cek akustik kamar dengan Pengukur Suara dan nyalakan white noise untuk meredam suara dari jendela.', title_ja = '眠りが浅い 🤫', body_ja = '寝ついたとたん、小さな物音にもびくっとする？「サウンドメーター」で部屋の音をチェックし、窓からの音を和らげるためにホワイトノイズを流しましょう。', title_ko = '예민한 잠 🤫', body_ko = '잠들자마자 작은 소리에도 깜짝 놀라나요? 소음 측정기로 방의 소리를 확인하고 창밖 소리를 막기 위해 백색소음을 틀어 주세요.', title_nl = 'Gevoelig voor geluid tijdens het slapen 🤫', body_nl = 'Schrikt je baby bij het inslapen van het kleinste tikje? Controleer met de Geluidsmeter de akoestiek van de kamer en zet witte ruis aan om geluiden van buiten te neutraliseren.', title_pl = 'Wrażliwy sen 🤫', body_pl = 'Gdy tylko zaśnie, wzdryga się na najmniejsze stuknięcie? Sprawdź akustykę pokoju Miernikiem dźwięku i włącz biały szum, by wyciszyć dźwięki zza okna.', title_pt = 'Sono sensível 🤫', body_pt = 'Mal adormece, assusta-se com o mais pequeno barulho? Verifique a acústica do quarto com o Medidor de Som e ligue ruído branco para neutralizar os sons que vêm da janela.', title_sv = 'Känslig sömn 🤫', body_sv = 'Rycker barnet till vid minsta knack så fort det har somnat? Kolla rummets akustik med Ljudmätaren och sätt på vitt brus för att dämpa ljud från fönstret.', title_vi = 'Giấc ngủ nhạy cảm 🤫', body_vi = 'Vừa chợp mắt, bé đã giật mình vì tiếng động nhỏ nhất? Hãy kiểm tra độ ồn trong phòng bằng Đo âm thanh và bật tiếng ồn trắng để át đi tiếng ồn từ cửa sổ.', title_zh = '睡眠敏感 🤫', body_zh = '刚睡着就被一点点声响惊醒？用噪音测量检查房间的声音环境，再播放白噪音盖过窗外的声音。' WHERE id = 'eec20c49-b219-4211-8916-1e602a8ceafb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El tono de voz de papá 📖', body_es = 'Esta noche creemos otro ambiente en la habitación. Crea en Cuentos inteligentes la historia de un valiente habitante del bosque y deja la lectura a la voz grave y tranquilizadora de papá.', title_fr = 'La voix de papa 📖', body_fr = 'Ce soir, créons une ambiance différente dans la chambre. Dans les Contes intelligents, créez l''histoire d''un courageux habitant de la forêt et confiez la lecture à la voix grave et rassurante de papa.', title_hi = 'पापा की आवाज़ 📖', body_hi = 'आज शाम कमरे में अलग माहौल बनाते हैं। स्मार्ट कहानियों में जंगल में रहने वाले एक बहादुर जीव की कहानी बनाइए और पढ़ने का काम पापा की गहरी, भरोसेमंद आवाज़ को सौंपिए।', title_id = 'Suara ayah 📖', body_id = 'Mari ciptakan suasana berbeda di kamar malam ini. Buat kisah tentang penghuni hutan yang pemberani di Dongeng Pintar, dan serahkan pembacaannya pada suara ayah yang berat dan menenangkan.', title_ja = 'パパの声 📖', body_ja = '今夜は部屋にいつもと違う雰囲気をつくりましょう。「スマートおはなし」で勇敢な森の住人のお話をつくって、読むのはパパの低くて安心できる声におまかせしましょう。', title_ko = '아빠의 목소리 📖', body_ko = '오늘 저녁 방 안에 색다른 분위기를 만들어 봐요. 스마트 동화에서 용감한 숲속 친구 이야기를 만들고 읽어 주는 건 아빠의 굵고 든든한 목소리에 맡기세요.', title_nl = 'Papa''s stem 📖', body_nl = 'Laten we vanavond een andere sfeer in de kamer maken. Maak in Slimme sprookjes een verhaal over een dappere bosbewoner en laat papa het met zijn diepe, geruststellende stem voorlezen.', title_pl = 'Głos taty 📖', body_pl = 'Stwórzmy dziś wieczorem w pokoju inną atmosferę. Stwórz w Mądrych bajkach historię o odważnym mieszkańcu lasu, a czytanie powierz głębokiemu, budzącemu zaufanie głosowi taty.', title_pt = 'O tom de voz do pai 📖', body_pt = 'Esta noite, vamos criar um ambiente diferente no quarto. Crie nas Histórias Inteligentes uma história sobre um corajoso habitante da floresta e deixe a leitura à voz grave e tranquilizadora do pai.', title_sv = 'Pappas röst 📖', body_sv = 'Låt oss skapa en annan stämning i rummet i kväll. Skapa en saga om en modig skogsinvånare i Smarta sagor och låt pappas djupa, trygga röst läsa den.', title_vi = 'Giọng nói của bố 📖', body_vi = 'Tối nay mình tạo một bầu không khí khác trong phòng nhé. Hãy tạo câu chuyện về một cư dân dũng cảm của khu rừng trong Truyện cổ tích thông minh và để giọng trầm ấm, vững chãi của bố đọc truyện.', title_zh = '爸爸的声音 📖', body_zh = '今晚给房间换一种氛围吧。在智能故事里创作一个勇敢的森林居民的故事，把朗读交给爸爸低沉又让人安心的声音。' WHERE id = 'a2641bfd-0346-425a-86be-0a5a6822a3d8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Más allá de las cuatro paredes ☕', body_es = 'La rutina de casa empieza a agobiarte. Haz algo distinto hoy. Elige una cafetería cercana donde puedas entrar cómodamente con el carrito y disfruta de un café.', title_fr = 'Au-delà des quatre murs ☕', body_fr = 'La routine à la maison commence à vous étouffer ? Changez un peu aujourd''hui : choisissez un café proche où entrer facilement avec la poussette et savourez votre boisson.', title_hi = 'चार दीवारों से बाहर ☕', body_hi = 'घर का रूटीन घुटन देने लगा है। आज कुछ अलग कीजिए। पास का कोई ऐसा कैफ़े चुनिए जहाँ स्ट्रॉलर के साथ आराम से जा सकें, और कॉफ़ी का मज़ा लीजिए।', title_id = 'Keluar dari empat dinding ☕', body_id = 'Rutinitas di rumah mulai menyesakkan. Lakukan sesuatu yang berbeda hari ini. Pilih kafe terdekat yang mudah dimasuki dengan stroller dan nikmati kopi Anda.', title_ja = '4つの壁の外へ ☕', body_ja = '家での毎日に息がつまりそう？今日はいつもと違うことをしましょう。近くでベビーカーで入りやすいカフェを選んで、コーヒーを楽しみましょう。', title_ko = '네 벽 밖으로 ☕', body_ko = '집 안의 일상이 답답해지기 시작했나요? 오늘은 색다르게 보내 보세요. 유모차로 편하게 들어갈 수 있는 근처 카페를 골라 커피를 즐기세요.', title_nl = 'Weg uit je vier muren ☕', body_nl = 'De routine thuis begint je te verstikken. Doe vandaag eens iets anders. Kies een café in de buurt waar je makkelijk met de kinderwagen naar binnen kunt en geniet van je koffie.', title_pl = 'Poza cztery ściany ☕', body_pl = 'Domowa rutyna zaczyna cię przytłaczać. Zrób dziś coś inaczej. Wybierz pobliską kawiarnię, do której łatwo wjedziesz wózkiem, i delektuj się kawą.', title_pt = 'Para lá das quatro paredes ☕', body_pt = 'A rotina em casa começou a sufocá-la. Hoje, faça algo diferente. Escolha um café perto onde entre facilmente com o carrinho e saboreie o seu café.', title_sv = 'Bort från de fyra väggarna ☕', body_sv = 'Har rutinen hemma börjat kännas kvävande? Gör något annorlunda i dag.  Välj ett kafé i närheten dit du lätt kommer in med barnvagnen och njut av kaffet.', title_vi = 'Ra khỏi bốn bức tường ☕', body_vi = 'Nếp sinh hoạt ở nhà bắt đầu khiến mẹ ngột ngạt. Hôm nay hãy đổi gió.  Chọn một quán cà phê gần nhà có thể đẩy xe đẩy vào dễ dàng và thưởng thức cà phê nhé.', title_zh = '走出家门 ☕', body_zh = '家里的日常开始让你喘不过气了。今天换个花样吧。找一家附近方便推婴儿车进去的咖啡馆，好好享受一杯咖啡。' WHERE id = 'ba28583a-a3f1-40f6-9657-b7b38af17c60' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tu peque avanza cada día🤏', body_es = '¿Intenta coger hasta la miga o la manchita más pequeña del suelo con el pulgar y el índice? ¡Su motricidad fina está en plena forma!', title_fr = 'Votre enfant progresse de jour en jour 🤏', body_fr = 'Il essaie d''attraper la moindre tache ou miette par terre entre le pouce et l''index ? Sa motricité fine est au top !', title_hi = 'आपका बच्चा हर दिन बढ़ रहा है 🤏', body_hi = 'ज़मीन पर पड़े सबसे छोटे कण या टुकड़े को भी अँगूठे और तर्जनी से उठाने की कोशिश करता है? बारीक मोटर स्किल्स कमाल पर हैं!', title_id = 'Si kecil berkembang setiap hari🤏', body_id = 'Ia mencoba mengambil noda atau remah terkecil di lantai dengan ibu jari dan telunjuk? Motorik halusnya sedang di puncak!', title_ja = '赤ちゃんは日々成長しています🤏', body_ja = '床の小さなシミやかけらまで、親指と人さし指でつまもうとしていますか？指先の細かい動きがぐんぐん発達しています！', title_ko = '아기는 날마다 자라고 있어요🤏', body_ko = '바닥의 아주 작은 얼룩이나 부스러기까지 엄지와 검지로 집으려 하나요? 소근육 발달이 최고조예요!', title_nl = 'Je kindje ontwikkelt zich elke dag🤏', body_nl = 'Probeert je baby zelfs het kleinste kruimeltje of vlekje op de vloer met duim en wijsvinger te pakken? De fijne motoriek is op zijn hoogtepunt!', title_pl = 'Twój maluszek rozwija się z każdym dniem 🤏', body_pl = 'Próbuje chwycić kciukiem i palcem wskazującym nawet najmniejszy paproch czy okruszek na podłodze? Motoryka mała jest u szczytu!', title_pt = 'O seu bebé evolui a cada dia🤏', body_pt = 'Tenta apanhar com o polegar e o indicador até a mais pequena mancha ou migalha no chão? A motricidade fina está no auge!', title_sv = 'Ditt barn utvecklas för varje dag🤏', body_sv = 'Försöker barnet plocka upp minsta fläck eller smula på golvet med tummen och pekfingret? Finmotoriken är på topp!', title_vi = 'Bé phát triển từng ngày🤏', body_vi = 'Bé cố nhặt cả vết bẩn hay mẩu vụn nhỏ nhất trên sàn bằng ngón cái và ngón trỏ? Kỹ năng vận động tinh đang ở đỉnh cao!', title_zh = '宝宝每天都在成长 🤏', body_zh = '宝宝想用拇指和食指捏起地上最小的污点和碎屑？精细动作正处在巅峰期！' WHERE id = 'ea94213c-026e-4de0-be12-a192e4d22b19' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escalando los muebles 🧗‍♂️', body_es = '¿Se agarra al sofá o a una silla para ponerse de pie? Los músculos de sus piernas se preparan para mantenerse en pie solo. Protégele, pero no frenes estos intentos de pequeño alpinista.', title_fr = 'Grimper sur les meubles 🧗‍♂️', body_fr = 'Il s''agrippe au canapé ou à une chaise pour se hisser ? Les muscles de ses jambes se préparent à la station debout. Protégez-le, mais n''empêchez pas ces essais d''alpiniste.', title_hi = 'फ़र्नीचर पर चढ़ना 🧗‍♂️', body_hi = 'सोफ़े या कुर्सी को पकड़कर खुद को ऊपर खींचता है? पैरों की मांसपेशियाँ खुद खड़े होने की तैयारी कर रही हैं। उसकी सुरक्षा कीजिए, पर इन नन्ही चढ़ाई की कोशिशों को मत रोकिए।', title_id = 'Memanjat perabot 🧗‍♂️', body_id = 'Ia berpegangan pada sofa atau kursi dan menarik tubuhnya ke atas? Otot kakinya bersiap untuk berdiri sendiri. Jaga ia, tapi jangan halangi usaha si pendaki kecil ini.', title_ja = '家具によじのぼる 🧗‍♂️', body_ja = 'ソファやいすにつかまって、体を引き上げていますか？脚の筋肉がひとりで立つ準備をしています。安全を守りつつ、この登山家の挑戦をじゃましないであげましょう。', title_ko = '가구 오르기 🧗‍♂️', body_ko = '소파나 의자를 잡고 몸을 끌어올리나요? 다리 근육이 혼자 서기를 준비하고 있어요. 안전하게 지켜 주되 이 꼬마 등반가의 도전을 막지 마세요.', title_nl = 'Op meubels klimmen 🧗‍♂️', body_nl = 'Trekt je baby zich op aan de bank of een stoel? De beenspieren maken zich klaar om zelf te staan. Bescherm hem, maar houd deze klimpogingen niet tegen.', title_pl = 'Wspinaczka po meblach 🧗‍♂️', body_pl = 'Łapie się kanapy i krzesła i podciąga się do góry? Mięśnie nóg szykują się do samodzielnego stania. Pilnuj go, ale nie przeszkadzaj w tych alpinistycznych próbach.', title_pt = 'Trepar aos móveis 🧗‍♂️', body_pt = 'Agarra-se ao sofá ou à cadeira para se pôr de pé? Os músculos das pernas preparam-se para ficar de pé sozinho. Proteja-o, mas não trave estas tentativas de alpinista.', title_sv = 'Klättrar på möblerna 🧗‍♂️', body_sv = 'Tar barnet tag i soffan eller en stol och drar sig upp? Benmusklerna förbereder sig för att stå själv. Skydda barnet, men hindra inte de här klätterförsöken.', title_vi = 'Trèo lên đồ đạc 🧗‍♂️', body_vi = 'Bé bám vào sofa, ghế để tự kéo người đứng lên? Cơ chân của bé đang chuẩn bị để tự đứng. Hãy bảo vệ bé, nhưng đừng cản trở những lần "leo núi" này.', title_zh = '攀爬家具 🧗‍♂️', body_zh = '宝宝扶着沙发、椅子把自己往上拉？腿部肌肉正在为独立站立做准备。保护好宝宝，但别阻止这些小小“登山家”的尝试。' WHERE id = '2ab7b4ab-59b4-4e96-8271-8ddcc86f1911' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tormenta nocturna 😭', body_es = '¿Se ha despertado llorando a media noche sin motivo? Descubre la causa con el Análisis del llanto y cálmale.', title_fr = 'La tempête de la nuit 😭', body_fr = 'Il s''est réveillé en pleurant au milieu de la nuit sans raison ? Trouvez la cause avec l''Analyse des pleurs et apaisez-le.', title_hi = 'रात का तूफ़ान 😭', body_hi = 'आधी रात को बिना वजह रोते हुए जाग गया? क्राइंग एनालिसिस से वजह जानिए और उसे शांत कीजिए।', title_id = 'Badai di malam hari 😭', body_id = 'Ia terbangun menangis di tengah malam tanpa sebab? Temukan penyebabnya dengan Analisis Tangisan dan tenangkan ia.', title_ja = '夜の嵐 😭', body_ja = '理由もなく夜中に泣いて起きた？「泣き声分析」で原因を見つけて、落ち着かせてあげましょう。', title_ko = '한밤의 폭풍 😭', body_ko = '한밤중에 이유 없이 울며 깼나요? 울음 분석으로 이유를 찾아 아기를 달래 주세요.', title_nl = 'Storm in de nacht 😭', body_nl = 'Werd je baby midden in de nacht zonder reden huilend wakker? Ontdek de oorzaak met Huilanalyse en kalmeer hem.', title_pl = 'Nocna burza 😭', body_pl = 'Obudził się w środku nocy z płaczem bez powodu? Znajdź przyczynę z Analizą płaczu i ukój go.', title_pt = 'A tempestade da noite 😭', body_pt = 'Acordou a chorar a meio da noite sem motivo aparente? Descubra a causa com a Análise do Choro e acalme-o.', title_sv = 'Nattens storm 😭', body_sv = 'Har barnet vaknat gråtande mitt i natten utan anledning? Hitta orsaken med Gråtanalys och lugna barnet.', title_vi = 'Cơn bão ban đêm 😭', body_vi = 'Bé thức giấc khóc giữa đêm mà không rõ lý do? Hãy dùng Phân tích tiếng khóc để tìm nguyên nhân và dỗ bé yên.', title_zh = '夜里的风暴 😭', body_zh = '宝宝半夜无缘无故哭着醒来？用哭声分析找出原因，让宝宝安心吧。' WHERE id = '82e71311-374a-4306-bcfc-4f69bc54da1b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te agotes la cabeza 🛒', body_es = '¿La falta de sueño te hace olvidar lo que hay que comprar? Apúntalo todo en la Lista de la compra y que tu pareja se encargue al volver.', title_fr = 'Ne vous fatiguez pas l''esprit 🛒', body_fr = 'Le manque de sommeil affaiblit votre mémoire et vous oubliez les courses ? Notez tout dans la Liste de courses, votre conjoint s''en chargera en rentrant.', title_hi = 'दिमाग मत थकाइए 🛒', body_hi = 'नींद की कमी से याददाश्त कमज़ोर हो गई है और बाज़ार का सामान भूल जाती हैं? सब कुछ शॉपिंग लिस्ट में लिखिए, आपके साथी आते समय ले आएँगे।', title_id = 'Jangan bikin pusing 🛒', body_id = 'Kurang tidur membuat Anda pelupa dan lupa apa yang harus dibeli di pasar? Tulis semuanya di Daftar Belanja, biar pasangan Anda yang mengurus saat pulang.', title_ja = '頭を休ませて 🛒', body_ja = '寝不足でもの忘れが増えて、スーパーで買うものを忘れてしまう？ぜんぶ「買い物リスト」に書いて、パートナーに帰りに買ってきてもらいましょう。', title_ko = '머리를 쉬게 하세요 🛒', body_ko = '잠이 부족해 기억력이 떨어지고 마트에서 살 것을 자꾸 잊나요? 모두 쇼핑 목록에 적어 두면 배우자가 오는 길에 해결할 거예요.', title_nl = 'Breek je hoofd er niet over 🛒', body_nl = 'Is je geheugen zwakker door slaaptekort en vergeet je wat je moet kopen? Zet alles op je Boodschappenlijstje en laat je partner het op weg naar huis regelen.', title_pl = 'Nie męcz głowy 🛒', body_pl = 'Przez niewyspanie słabnie pamięć i zapominasz, co kupić w sklepie? Wpisuj wszystko na Listę zakupów, a partner załatwi to w drodze do domu.', title_pt = 'Não canse a cabeça 🛒', body_pt = 'A falta de sono enfraqueceu-lhe a memória e esquece-se do que tem de comprar no supermercado? Escreva tudo na Lista de Compras e o seu companheiro trata disso no regresso.', title_sv = 'Belasta inte hjärnan 🛒', body_sv = 'Har sömnbristen försämrat minnet så att du glömmer vad du ska köpa i affären? Skriv upp allt i Inköpslistan, så fixar din partner det på vägen hem.', title_vi = 'Đừng bắt não làm việc quá sức 🛒', body_vi = 'Thiếu ngủ khiến mẹ hay quên và không nhớ cần mua gì ở siêu thị? Hãy ghi mọi thứ vào Danh sách mua sắm để bố lo trên đường về.', title_zh = '别让大脑太累 🛒', body_zh = '缺觉让你记性变差，总忘了超市要买什么？把一切都写进购物清单，让伴侣回家路上搞定吧。' WHERE id = 'c7aadd23-e889-42f2-a761-3f955cb9600f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La naturaleza es la mejor medicina ⛅', body_es = '¿Está muy inquieto y no hay forma de entretenerle? Abre la herramienta Tiempo y ropa, vístele según el tiempo y sal enseguida a pasear 20 minutos por el parque.', title_fr = 'La nature est le meilleur remède ⛅', body_fr = 'Il est très agité et rien ne l''occupe ? Ouvrez l''outil Météo et tenue, habillez-le selon le temps et emmenez-le tout de suite au parc pour 20 minutes de promenade.', title_hi = 'प्रकृति सबसे अच्छी दवा है ⛅', body_hi = 'बहुत बेचैन है और किसी चीज़ से नहीं बहलता? मौसम और कपड़े टूल खोलिए, मौसम के हिसाब से कपड़े पहनाइए और उसे तुरंत 20 मिनट पार्क में घुमाने ले जाइए।', title_id = 'Alam adalah obat terbaik ⛅', body_id = 'Ia sangat rewel dan tak bisa dialihkan dengan apa pun? Buka fitur Cuaca dan Pakaian, pakaikan baju sesuai cuaca, dan segera ajak ia jalan-jalan 20 menit ke taman.', title_ja = '自然はいちばんの薬 ⛅', body_ja = 'ぐずぐずが続いて、何をしても気がまぎれない？「天気と服装」ツールを開いて天気に合った服を着せ、すぐに20分ほど公園をお散歩しましょう。', title_ko = '자연이 최고의 약이에요 ⛅', body_ko = '많이 보채고 무엇으로도 달래지지 않나요? 날씨와 옷차림 도구를 열어 날씨에 맞게 입히고 바로 공원으로 20분 산책을 나가세요.', title_nl = 'De natuur is het beste medicijn ⛅', body_nl = 'Is je baby erg onrustig en kun je hem nergens mee afleiden? Open de tool Weer en kleding, kleed hem aan voor het weer en ga meteen 20 minuten wandelen in het park.', title_pl = 'Natura to najlepsze lekarstwo ⛅', body_pl = 'Jest bardzo niespokojny i nic go nie zajmuje? Otwórz narzędzie Pogoda i ubiór, ubierz go odpowiednio do pogody i od razu zabierz na 20-minutowy spacer po parku.', title_pt = 'A natureza é o melhor remédio ⛅', body_pt = 'Está muito inquieto e nada o distrai? Abra a ferramenta Tempo e Roupa, vista-o de acordo com o tempo e leve-o já 20 minutos a passear no parque.', title_sv = 'Naturen är den bästa medicinen ⛅', body_sv = 'Väldigt oroligt och går inte att avleda med något? Öppna Väder och kläder, klä barnet efter vädret och gå direkt ut på en 20 minuters promenad i parken.', title_vi = 'Thiên nhiên là liều thuốc tốt nhất ⛅', body_vi = 'Bé quấy khóc nhiều và không gì dỗ được? Mở công cụ Thời tiết và trang phục, mặc đồ hợp thời tiết cho bé và đưa bé đi dạo công viên 20 phút ngay nhé.', title_zh = '大自然是最好的良药 ⛅', body_zh = '宝宝特别烦躁，怎么都哄不好？打开天气穿衣工具，按天气给宝宝穿好衣服，马上去公园散步20分钟吧。' WHERE id = '4d7eb303-e249-46ed-8460-db2f0a519240' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lágrimas silenciosas 📝', body_es = '¿Hoy todo se te ha venido encima y tienes ganas de llorar? Es lo más natural... Escribe todo tu cansancio en el Diario de ánimo. Desahogarte te sentará bien.', title_fr = 'Des larmes silencieuses 📝', body_fr = 'Aujourd''hui, tout vous est tombé dessus et vous avez envie de pleurer ? C''est tellement naturel... Écrivez toute votre fatigue dans le Journal d''humeur. Vider votre cœur vous fera du bien.', title_hi = 'चुपचाप आँसू 📝', body_hi = 'आज सब कुछ भारी लगा और रोने का मन कर रहा है? यह बिल्कुल स्वाभाविक है... अपनी सारी थकान मूड डायरी में लिखिए। मन हल्का करना आपके लिए अच्छा रहेगा।', title_id = 'Air mata dalam diam 📝', body_id = 'Hari ini semuanya menimpa Anda dan Anda ingin menangis? Itu sangat wajar... Tuliskan semua rasa lelah Anda di Buku Harian Suasana Hati. Meluapkan isi hati akan membuat Anda lebih lega.', title_ja = '声にならない涙 📝', body_ja = '今日は何もかもがのしかかって、泣きたい気分？それはとても自然なことです...「気分日記」に疲れをぜんぶ書き出しましょう。吐き出すと心が軽くなります。', title_ko = '소리 없는 눈물 📝', body_ko = '오늘 모든 게 버거워서 울고 싶나요? 너무나 자연스러운 일이에요... 기분 일기에 쌓인 피로를 모두 적어 보세요. 마음을 털어놓으면 한결 나아질 거예요.', title_nl = 'Stille tranen 📝', body_nl = 'Kwam vandaag alles op je af en wil je huilen? Dat is zo normaal... Schrijf al je vermoeidheid op in je Stemmingsdagboek. Je hart luchten doet je goed.', title_pl = 'Ciche łzy 📝', body_pl = 'Dziś wszystko się na ciebie zwaliło i chce ci się płakać? To takie naturalne... Zapisz całe swoje zmęczenie w Dzienniku nastroju. Wyrzucenie tego z siebie dobrze ci zrobi.', title_pt = 'Lágrimas silenciosas 📝', body_pt = 'Hoje foi tudo demais e apetece-lhe chorar? É tão natural... Escreva todo o seu cansaço no Diário de Humor. Desabafar vai fazer-lhe bem.', title_sv = 'Tysta tårar 📝', body_sv = 'Kändes allt för mycket i dag och vill du gråta? Det är så naturligt... Skriv ner all din trötthet i Humördagboken. Att lätta på hjärtat gör dig gott.', title_vi = 'Những giọt nước mắt thầm lặng 📝', body_vi = 'Hôm nay mọi thứ dồn dập và mẹ chỉ muốn khóc? Điều đó tự nhiên lắm... Hãy viết hết mọi mệt mỏi vào Nhật ký tâm trạng. Trút bầu tâm sự sẽ giúp mẹ dễ chịu hơn.', title_zh = '无声的眼泪 📝', body_zh = '今天一切都压在你身上，想哭吗？这再正常不过了……把所有的疲惫写进心情日记吧。把心里话说出来会让你好受些。' WHERE id = '4dcbbcf9-87b6-44f2-9ce0-d8fdd1caacf7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Repite sus primeras sílabas 🗣️', body_es = '¿Repite a menudo sonidos como da-da o ba-ba? Está probando su aparato del habla. Repite sonriendo cada sílaba que diga para que aprenda a dialogar.', title_fr = 'Il répète ses premières syllabes 🗣️', body_fr = 'Il répète souvent des sons comme « da-da » ou « ba-ba » ? Il teste son appareil vocal. Répétez en souriant chaque syllabe qu''il prononce pour qu''il apprenne à dialoguer.', title_hi = 'पहले अक्षरों की दोहराई 🗣️', body_hi = 'दा-दा, बा-बा जैसी आवाज़ें बार-बार दोहराता है? वह अपनी बोलने की क्षमता आज़मा रहा है। उसके हर अक्षर को मुस्कुराकर दोहराइए, ताकि वह बातचीत करना सीखे।', title_id = 'Mengulang suku kata pertama 🗣️', body_id = 'Ia sering mengulang suara seperti "da-da" dan "ba-ba"? Ia sedang menguji alat bicaranya. Ulangi setiap suku katanya sambil tersenyum agar ia belajar berdialog.', title_ja = '最初の音のくり返し 🗣️', body_ja = '「だーだ」「ばーば」のような音をよくくり返していますか？話すための口の動きを試しているのです。言った音をほほえみながらまねして、会話のやりとりを教えてあげましょう。', title_ko = '첫 음절 반복하기 🗣️', body_ko = '다다, 바바 같은 소리를 자주 반복하나요? 발성 기관을 시험해 보는 중이에요. 아기가 내는 소리를 웃으며 따라 해 주면 대화하는 법을 배워요.', title_nl = 'De eerste lettergrepen herhalen 🗣️', body_nl = 'Herhaalt je baby vaak geluiden als da-da en ba-ba? Hij test zijn spraakorgaan. Herhaal elke lettergreep met een glimlach, zodat hij leert een gesprek te voeren.', title_pl = 'Powtarzanie pierwszych sylab 🗣️', body_pl = 'Często powtarza dźwięki jak da-da, ba-ba? Testuje swój aparat mowy. Z uśmiechem powtarzaj każdą sylabę, którą wypowie, żeby uczył się prowadzić dialog.', title_pt = 'Repetir as primeiras sílabas 🗣️', body_pt = 'Repete muitas vezes sons como da-da, ba-ba? Está a pôr à prova o aparelho da fala. Repita com um sorriso cada sílaba que ele diz para aprender a dialogar.', title_sv = 'Upprepar de första stavelserna 🗣️', body_sv = 'Upprepar barnet ofta ljud som da-da och ba-ba? Det testar sina talorgan. Upprepa varje stavelse barnet säger med ett leende, så lär det sig att föra en dialog.', title_vi = 'Lặp lại những âm tiết đầu tiên 🗣️', body_vi = 'Bé hay lặp lại những âm như "đa-đa", "ba-ba"? Bé đang thử bộ máy phát âm của mình. Hãy mỉm cười lặp lại từng âm bé nói để bé học cách trò chuyện.', title_zh = '重复第一批音节 🗣️', body_zh = '宝宝经常重复“da-da”“ba-ba”这样的声音？宝宝在测试自己的发音器官。笑着重复宝宝说的每个音节，帮宝宝学会对话吧。' WHERE id = 'e8e53d71-abc7-400d-80a7-8cf91f3339ab' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dudas pediátricas 🤖', body_es = '¿Es normal que el sueño se altere hacia el 8.º mes? En vez de buscar durante horas en internet, consulta a Anacan AI datos científicos concretos sobre la regresión del sueño de los 8 meses.', title_fr = 'Des doutes pédiatriques 🤖', body_fr = 'Est-il normal que le sommeil se dérègle vers le 8e mois ? Plutôt que de chercher des heures sur Internet, découvrez auprès d''Anacan AI des faits scientifiques précis sur la régression du sommeil du 8e mois.', title_hi = 'बच्चे की सेहत को लेकर सवाल 🤖', body_hi = 'क्या 8वें महीने के आसपास नींद का रूटीन बिगड़ना सामान्य है? घंटों इंटरनेट पर खोजने के बजाय Anacan AI से 8 महीने की स्लीप रिग्रेशन के ठोस वैज्ञानिक तथ्य जानिए।', title_id = 'Keraguan seputar kesehatan anak 🤖', body_id = 'Normalkah pola tidur kacau menjelang bulan ke-8? Daripada mencari di internet berjam-jam, pelajari fakta ilmiah yang jelas tentang regresi tidur bulan ke-8 di Anacan AI.', title_ja = '育児の疑問 🤖', body_ja = '生後8か月ごろに睡眠のリズムが乱れるのは普通？何時間もネットで調べるより、Anacan AIで8か月の睡眠退行について科学的な事実を知りましょう。', title_ko = '소아과 궁금증 🤖', body_ko = '8개월 무렵 수면 패턴이 흐트러지는 게 정상일까요? 몇 시간씩 인터넷을 검색하는 대신 Anacan AI에게 8개월 수면 퇴행에 관한 과학적 사실을 알아보세요.', title_nl = 'Twijfels over je kindje 🤖', body_nl = 'Is een verstoord slaapritme rond de 8e maand normaal? Zoek niet urenlang op internet, maar leer concrete wetenschappelijke feiten over de slaapregressie van 8 maanden van Anacan AI.', title_pl = 'Pediatryczne wątpliwości 🤖', body_pl = 'Czy to normalne, że w okolicach 8. miesiąca rytm snu się rozregulowuje? Zamiast godzinami szukać w internecie, poznaj od Anacan AI konkretne naukowe fakty o regresie snu w 8. miesiącu.', title_pt = 'Dúvidas pediátricas 🤖', body_pt = 'É normal o sono desregular-se perto do 8.º mês? Em vez de passar horas a pesquisar na internet, conheça no Anacan AI factos científicos concretos sobre a regressão do sono dos 8 meses.', title_sv = 'Barnmedicinska funderingar 🤖', body_sv = 'Är det normalt att sömnrutinen rubbas inför 8:e månaden? I stället för att söka på nätet i timmar, få konkreta vetenskapliga fakta om sömnregressionen vid 8 månader från Anacan AI.', title_vi = 'Băn khoăn về nhi khoa 🤖', body_vi = 'Giấc ngủ bị xáo trộn khi gần 8 tháng có bình thường không? Thay vì tìm kiếm hàng giờ trên mạng, hãy hỏi Anacan AI những thông tin khoa học cụ thể về thoái lui giấc ngủ tháng thứ 8.', title_zh = '儿科疑虑 🤖', body_zh = '快到8个月时睡眠作息被打乱正常吗？与其在网上搜几个小时，不如向Anacan AI了解关于8个月睡眠倒退的具体科学事实。' WHERE id = '27772b37-d653-4081-a4d8-e2d8e3036d19' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Melodía de la noche 🎶', body_es = 'Cuando se resista a dormirse, pon música clásica suave en la habitación. Las melodías calmarán fácilmente su sistema nervioso alterado.', title_fr = 'La mélodie du soir 🎶', body_fr = 'Quand il résiste au sommeil, diffusez une musique classique douce dans la chambre. Les ondes musicales apaiseront facilement son système nerveux tendu.', title_hi = 'शाम की धुन 🎶', body_hi = 'जब बच्चा सोने का विरोध करे, तो कमरे में हल्का क्लासिकल संगीत चलाइए। संगीत की लहरें उसके तनाव भरे तंत्रिका तंत्र को आसानी से शांत करेंगी।', title_id = 'Melodi malam 🎶', body_id = 'Saat ia menolak tidur, putar musik klasik yang lembut di kamar. Alunan musik akan dengan mudah menenangkan sarafnya yang tegang.', title_ja = '夜のメロディー 🎶', body_ja = 'なかなか寝ようとしないときは、部屋で静かなクラシック音楽を流しましょう。音楽の波が、高ぶった神経をやさしくほぐしてくれます。', title_ko = '저녁의 멜로디 🎶', body_ko = '아이가 잠들지 않으려 할 때 방에 잔잔한 클래식 음악을 틀어 주세요. 음악이 예민해진 신경을 부드럽게 풀어 줄 거예요.', title_nl = 'Een avondmelodie 🎶', body_nl = 'Verzet je baby zich tegen het slapengaan? Zet zachte klassieke muziek op in de kamer. De muziek kalmeert zijn gespannen zenuwstelsel heel gemakkelijk.', title_pl = 'Wieczorna melodia 🎶', body_pl = 'Gdy maluszek opiera się zasypianiu, włącz w pokoju spokojną muzykę klasyczną. Fale muzyki łatwo ukoją jego napięty układ nerwowy.', title_pt = 'Melodia da noite 🎶', body_pt = 'Quando o bebé resiste a adormecer, ponha a tocar música clássica suave no quarto. As ondas da música vão acalmar com facilidade o sistema nervoso tenso.', title_sv = 'Kvällsmelodi 🎶', body_sv = 'När barnet gör motstånd mot att somna, sätt på lätt klassisk musik i rummet. Musikens vågor mjukar lätt upp det spända nervsystemet.', title_vi = 'Giai điệu buổi tối 🎶', body_vi = 'Khi bé không chịu ngủ, hãy mở nhạc cổ điển nhẹ nhàng trong phòng. Những giai điệu ấy sẽ dễ dàng xoa dịu hệ thần kinh đang căng thẳng của bé.', title_zh = '晚间旋律 🎶', body_zh = '宝宝抗拒入睡时，在房间里放点轻柔的古典音乐。音乐能轻松舒缓宝宝紧张的神经系统。' WHERE id = 'e5b5ed3f-01d7-4566-8860-0dc049a710b5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Empiezan los juegos de imaginación 🧸', body_es = '¿Intenta dar de beber a su osito o a su muñeca? Su imaginación crece y empieza el juego simbólico. Disfruta observando a este pequeño director.', title_fr = 'Les débuts du jeu d''imagination 🧸', body_fr = 'Il essaie de donner à boire à son ours en peluche ou à sa poupée ? Son imagination se développe et les jeux symboliques commencent. Savourez le spectacle de ce petit metteur en scène.', title_hi = 'कल्पना के खेलों की शुरुआत 🧸', body_hi = 'अपने टेडी बियर या गुड़िया को पानी पिलाने की कोशिश करता है? उसकी कल्पना बढ़ रही है और प्रतीकात्मक खेल शुरू हो रहे हैं। दूर से इस नन्हे निर्देशक को देखने का आनंद लीजिए।', title_id = 'Awal permainan imajinasi 🧸', body_id = 'Ia mencoba memberi minum boneka beruang atau bonekanya? Imajinasinya berkembang dan permainan simbolis dimulai. Nikmati menonton sutradara kecil yang manis ini dari jauh.', title_ja = 'ごっこ遊びのはじまり 🧸', body_ja = 'くまのぬいぐるみやお人形にお水を飲ませようとしていますか？想像力が育ち、ごっこ遊びが始まっています。小さな監督さんを少し離れて見守りましょう。', title_ko = '상상 놀이의 시작 🧸', body_ko = '곰 인형이나 인형에게 물을 먹이려 하나요? 상상력이 자라며 상징 놀이가 시작되고 있어요. 이 귀여운 감독님을 곁에서 지켜보며 즐기세요.', title_nl = 'Het begin van fantasiespel 🧸', body_nl = 'Probeert je baby zijn teddybeer of pop water te geven? Zijn fantasie ontwikkelt zich en het symbolische spel begint. Geniet van een afstandje van deze lieve kleine regisseur.', title_pl = 'Początek zabaw w udawanie 🧸', body_pl = 'Próbuje dać pić misiowi albo lalce? Rozwija się wyobraźnia i zaczynają się zabawy symboliczne. Z przyjemnością obserwuj z boku tego słodkiego reżysera.', title_pt = 'O início das brincadeiras de faz de conta 🧸', body_pt = 'Tenta dar água ao ursinho ou à boneca? A imaginação está a desenvolver-se e começam as brincadeiras simbólicas. Aproveite para observar de longe este pequeno realizador.', title_sv = 'Början på fantasilekar 🧸', body_sv = 'Försöker barnet ge nallen eller dockan vatten att dricka? Fantasin utvecklas och de symboliska lekarna börjar. Njut av att titta på den här söta regissören från sidan.', title_vi = 'Khởi đầu của trò chơi tưởng tượng 🧸', body_vi = 'Bé cố cho gấu bông hay búp bê uống nước? Trí tưởng tượng của bé đang phát triển và các trò chơi biểu tượng bắt đầu. Hãy tận hưởng việc ngắm "đạo diễn" nhỏ đáng yêu này.', title_zh = '想象游戏的开始 🧸', body_zh = '宝宝在试着给小熊或娃娃喂水？想象力正在发展，象征性游戏开始了。在一旁欣赏这位可爱的小“导演”吧。' WHERE id = 'ea452c1a-6484-41b5-9042-60a3abcf409d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Con las prisas del día, no comas de pie. 🥑', body_es = 'Haces de todo para que coma bien. ¿Y tú? Prepárate un plato especial, que sacie y rico en hierro, solo para ti.', title_fr = 'Dans la course du quotidien, ne déjeunez pas debout. 🥑', body_fr = 'Vous faites tout pour bien le nourrir. Et vous ? Préparez-vous une assiette spéciale, copieuse et riche en fer.', title_hi = 'रोज़ की भागदौड़ में खड़े-खड़े लंच मत कीजिए 🥑', body_hi = 'उसका पेट भरने के लिए आप सब कुछ करती हैं। और खुद का? अपने लिए एक पेट भरने वाली, आयरन से भरपूर खास प्लेट तैयार कीजिए।', title_id = 'Jangan makan siang sambil berdiri di tengah kesibukan. 🥑', body_id = 'Anda melakukan segalanya agar ia kenyang. Bagaimana dengan Anda? Siapkan sepiring makanan istimewa yang mengenyangkan dan kaya zat besi untuk diri sendiri.', title_ja = '毎日のバタバタの中で、お昼ごはんを立ったまま食べないで。🥑', body_ja = '赤ちゃんにお腹いっぱい食べさせるために、なんでもしていますね。でもあなたは？自分のために、鉄分たっぷりで食べごたえのある特別なひと皿をつくりましょう。', title_ko = '바쁜 하루 속에서도 점심을 서서 먹지 마세요. 🥑', body_ko = '아기를 배불리 먹이려고 뭐든 하죠. 그런데 엄마는요? 나를 위해 든든하고 철분이 풍부한 특별한 한 접시를 준비하세요.', title_nl = 'Eet in de dagelijkse drukte niet staand je lunch. 🥑', body_nl = 'Je doet alles om je baby goed te laten eten. En jij? Maak een speciaal, voedzaam bord vol ijzer voor jezelf.', title_pl = 'W codziennym biegu nie jedz obiadu na stojąco. 🥑', body_pl = 'Robisz wszystko, żeby go nakarmić. A ty? Przygotuj dla siebie specjalny, sycący talerz bogaty w żelazo.', title_pt = 'Na correria do dia, não almoce de pé. 🥑', body_pt = 'Faz tudo para o alimentar. E a mãe? Prepare para si um prato especial, reconfortante e rico em ferro.', title_sv = 'Ät inte lunchen stående i vardagsstressen. 🥑', body_sv = 'Du gör allt för att barnet ska bli mätt. Men du själv då? Gör en speciell, mättande och järnrik tallrik åt dig själv.', title_vi = 'Đừng đứng ăn trưa giữa những bộn bề mỗi ngày. 🥑', body_vi = 'Mẹ làm mọi thứ để bé được no. Còn mẹ thì sao? Hãy chuẩn bị cho mình một đĩa ăn đặc biệt, no bụng và giàu sắt.', title_zh = '再忙也别站着吃午饭 🥑', body_zh = '你为了让宝宝吃饱想尽办法。那你自己呢？给自己做一盘丰盛、富含铁的专属餐吧。' WHERE id = '3a7b24a5-41c6-4c5d-a602-8a4582791ae2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Compartir lo que sientes 💬', body_es = '¿Te preocupa pensar «por qué mi bebé todavía no gatea»? Entra ya en la Comunidad Anacan. Lee historias reales de miles de mamás o pregunta, y verás que cada peque es único.', title_fr = 'Partager ses secrets 💬', body_fr = 'Vous vous inquiétez : « Pourquoi mon enfant ne marche-t-il pas encore à quatre pattes ? » Rejoignez tout de suite la Communauté Anacan. Lisez les vraies histoires de milliers de mamans ou posez une question, et voyez que chaque enfant est unique.', title_hi = 'मन की बात बाँटना 💬', body_hi = '''मेरा बच्चा अभी तक घुटनों के बल क्यों नहीं चलता?'' यह सोचकर परेशान हैं? तुरंत Anacan कम्युनिटी में आइए। हज़ारों माँओं की सच्ची कहानियाँ पढ़िए या सवाल पूछिए और देखिए कि हर बच्चा अनोखा है।', title_id = 'Berbagi rahasia 💬', body_id = 'Khawatir, "Kenapa anakku belum merangkak?" Segera masuk ke Komunitas Anacan. Baca kisah nyata ribuan ibu atau ajukan pertanyaan, dan lihat bahwa setiap anak itu unik.', title_ja = '気持ちを分かち合おう 💬', body_ja = '「どうしてうちの子はまだはいはいしないの？」と不安ですか？すぐにAnacanコミュニティに参加しましょう。何千人ものママのリアルな体験を読んだり質問したりすれば、どの子もそれぞれ違うとわかります。', title_ko = '속마음 나누기 💬', body_ko = '''우리 아이는 왜 아직 안 길까?'' 걱정되나요? 지금 Anacan 커뮤니티에 들어가 보세요. 수많은 엄마들의 실제 이야기를 읽거나 질문하며 모든 아이가 저마다 다르다는 걸 알게 될 거예요.', title_nl = 'Ervaringen delen 💬', body_nl = 'Maak je je zorgen waarom je kindje nog niet kruipt? Ga meteen naar de Anacan Community. Lees de echte verhalen van duizenden moeders of stel een vraag en zie dat elk kind uniek is.', title_pl = 'Dzielenie się sekretami 💬', body_pl = 'Martwisz się, dlaczego twój maluszek jeszcze nie raczkuje? Od razu zajrzyj do Społeczności Anacan. Przeczytaj prawdziwe historie tysięcy mam albo zadaj pytanie i przekonaj się, że każde dziecko jest wyjątkowe.', title_pt = 'Partilhar segredos 💬', body_pt = 'Anda preocupada a pensar "porque é que o meu bebé ainda não gatinha?" Entre já na Comunidade Anacan. Leia histórias reais de milhares de mães ou faça perguntas e veja que cada criança é única.', title_sv = 'Dela hemligheter 💬', body_sv = 'Oroar du dig och undrar varför ditt barn inte kryper än? Gå genast in i Anacans Community. Läs tusentals mammors verkliga berättelser eller ställ en fråga och se att varje barn är unikt.', title_vi = 'Chia sẻ tâm sự 💬', body_vi = 'Mẹ lo lắng: "Sao con mình vẫn chưa bò?" Hãy vào ngay Cộng đồng Anacan. Đọc câu chuyện thật của hàng nghìn bà mẹ hoặc đặt câu hỏi để thấy rằng mỗi em bé đều là duy nhất.', title_zh = '说说心里话 💬', body_zh = '在担心“我的宝宝为什么还不会爬”？马上进入Anacan社区。读读成千上万位妈妈的真实故事，或者提个问题，你会发现每个孩子都是独一无二的。' WHERE id = '61d3770b-ac23-4b61-a0c4-be4c333cc55a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ansiedad por separación 🥺', body_es = '¿Llora cuando sales de la habitación? Cree que ya no vas a volver. Dale seguridad con tu voz diciéndole siempre «estoy aquí».', title_fr = 'L''angoisse de séparation 🥺', body_fr = 'Il pleure quand vous quittez la pièce ? Il croit que vous ne reviendrez plus. Dites-lui toujours « Je suis là » pour le rassurer avec votre voix.', title_hi = 'अलगाव की बेचैनी 🥺', body_hi = 'आप कमरे से निकलती हैं तो वह पीछे से रोता है? उसे लगता है कि आप लौटकर नहीं आएँगी। ''मैं हमेशा यहीं हूँ'' कहकर अपनी आवाज़ से उसमें भरोसा जगाइए।', title_id = 'Kecemasan berpisah 🥺', body_id = 'Ia menangis saat Anda keluar kamar? Ia mengira Anda tidak akan kembali. Tanamkan rasa aman dengan suara Anda, katakan "Ibu di sini".', title_ja = '分離不安 🥺', body_ja = '部屋を出ると、あとを追って泣きますか？もう戻ってこないと思っているのです。いつも「ここにいるよ」と声をかけて、安心させてあげましょう。', title_ko = '분리불안 🥺', body_ko = '엄마가 방을 나가면 뒤따라 우나요? 엄마가 다시 돌아오지 않을 거라 생각하는 거예요. 늘 ''엄마 여기 있어''라고 말하며 목소리로 안심시켜 주세요.', title_nl = 'Verlatingsangst 🥺', body_nl = 'Huilt je baby als je de kamer uitgaat? Hij denkt dat je nooit meer terugkomt. Zeg altijd ''ik ben hier'' en geef hem met je stem een gevoel van veiligheid.', title_pl = 'Lęk separacyjny 🥺', body_pl = 'Płacze za tobą, gdy wychodzisz z pokoju? Myśli, że już nie wrócisz. Zawsze mów „jestem tutaj” i swoim głosem dawaj mu poczucie bezpieczeństwa.', title_pt = 'Ansiedade de separação 🥺', body_pt = 'Chora atrás de si quando sai do quarto? Ele pensa que não vai voltar. Diga sempre "estou aqui" e dê-lhe segurança com a sua voz.', title_sv = 'Separationsångest 🥺', body_sv = 'Gråter barnet efter dig när du går ut ur rummet? Det tror att du aldrig ska komma tillbaka. Säg alltid ''jag är här'' och ge barnet en känsla av trygghet med din röst.', title_vi = 'Nỗi lo xa cách 🥺', body_vi = 'Khi mẹ ra khỏi phòng, bé khóc theo? Bé nghĩ rằng mẹ sẽ không quay lại nữa. Hãy luôn nói "Mẹ ở đây" để giọng nói của mẹ cho bé cảm giác an toàn.', title_zh = '分离焦虑 🥺', body_zh = '你一离开房间，宝宝就在后面哭？宝宝以为你不会再回来了。常说“我在这儿”，用你的声音给宝宝安全感。' WHERE id = 'a8ecb50a-232f-401a-97bc-3fbfc63cc92b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sigue el picor de encías 🦷', body_es = '¿Lo muerde todo con fuerza y babea? Los mordedores fríos guardados en el congelador son los auténticos salvadores de estos días.', title_fr = 'Les gencives démangent toujours 🦷', body_fr = 'Il mâchouille tout avec force et bave beaucoup ? Les anneaux de dentition rafraîchis au congélateur sont les vrais sauveurs de ces journées.', title_hi = 'मसूड़ों की खुजली जारी है 🦷', body_hi = 'हर चीज़ ज़ोर से चबा रहा है और लार बह रही है? फ़्रीज़र में रखे ठंडे टीदर इन दिनों के असली मददगार हैं।', title_id = 'Gusi masih gatal 🦷', body_id = 'Ia mengunyah semua benda dengan kuat dan air liurnya menetes? Teether dingin yang disimpan di freezer adalah penyelamat sejati di hari-hari ini.', title_ja = '歯ぐきのむずむずが続く 🦷', body_ja = 'なんでも力いっぱいかんで、よだれが出ていますか？冷凍庫で冷やした歯固めが、この時期の本当の救世主です。', title_ko = '잇몸 가려움이 계속돼요 🦷', body_ko = '무엇이든 세게 깨물고 침을 흘리나요? 냉동실에 넣어 둔 시원한 치발기가 요즘의 진짜 구원자예요.', title_nl = 'Het tandvlees blijft jeuken 🦷', body_nl = 'Kauwt je baby fel op alles en kwijlt hij? Bijtringen die in de vriezer zijn gekoeld, zijn de echte redders van deze dagen.', title_pl = 'Swędzenie dziąseł trwa 🦷', body_pl = 'Mocno gryzie wszystko i leci mu ślinka? Chłodne gryzaki prosto z zamrażarki to prawdziwy ratunek w te dni.', title_pt = 'A comichão nas gengivas continua 🦷', body_pt = 'Mastiga tudo com força e baba-se? Os mordedores frescos guardados no congelador são os verdadeiros salvadores destes dias.', title_sv = 'Klådan i gommen fortsätter 🦷', body_sv = 'Tuggar barnet häftigt på allt och dreglar? Svala bitringar som har legat i frysen är de här dagarnas verkliga räddning.', title_vi = 'Nướu vẫn còn ngứa 🦷', body_vi = 'Bé gặm mọi thứ thật mạnh và chảy nhiều nước dãi? Gặm nướu mát được để trong ngăn đá chính là cứu tinh thực sự của những ngày này.', title_zh = '牙龈还在痒 🦷', body_zh = '什么都使劲啃，口水直流？在冰箱冷冻室里冰过的牙胶是这段日子真正的救星。' WHERE id = '6666dee6-8da7-4982-b6e5-9cdc982b4a75' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La responsabilidad de papá 👨‍🍼', body_es = 'No cargues tú sola con todos los despertares nocturnos. Despierta también a tu pareja: ser un equipo es repartir esta responsabilidad a partes iguales.', title_fr = 'La responsabilité de papa 👨‍🍼', body_fr = 'Ne gérez pas les réveils nocturnes toute seule. Réveillez aussi votre conjoint, car être une équipe, c''est partager cette responsabilité à parts égales.', title_hi = 'पापा की ज़िम्मेदारी 👨‍🍼', body_hi = 'रात में जागने का बोझ अकेले मत उठाइए। अपने साथी को भी जगाइए, क्योंकि टीम होने का मतलब है इस ज़िम्मेदारी को बराबर बाँटना।', title_id = 'Tanggung jawab ayah 👨‍🍼', body_id = 'Jangan tanggung sendiri saat ia terbangun di malam hari. Bangunkan juga pasangan Anda, karena menjadi tim berarti berbagi tanggung jawab ini secara adil.', title_ja = 'パパの役目 👨‍🍼', body_ja = '夜中に起きるのを、ひとりで抱えこまないで。パートナーも起こしましょう。チームとは、この責任を平等に分け合うことです。', title_ko = '아빠의 책임 👨‍🍼', body_ko = '밤에 깨는 일을 혼자 다 감당하지 마세요. 배우자도 깨우세요. 한 팀이 된다는 건 이 책임을 똑같이 나누는 거예요.', title_nl = 'Papa''s verantwoordelijkheid 👨‍🍼', body_nl = 'Draag het ''s nachts opstaan niet helemaal alleen. Maak je partner ook wakker, want een team zijn betekent deze verantwoordelijkheid eerlijk delen.', title_pl = 'Obowiązki taty 👨‍🍼', body_pl = 'Nie dźwigaj nocnych pobudek zupełnie sama. Obudź też partnera, bo bycie drużyną to równy podział tej odpowiedzialności.', title_pt = 'A responsabilidade do pai 👨‍🍼', body_pt = 'Não aguente sozinha todos os despertares noturnos. Acorde também o seu companheiro, porque ser uma equipa é dividir esta responsabilidade por igual.', title_sv = 'Pappas ansvar 👨‍🍼', body_sv = 'Ta inte nattuppvaknandena helt ensam. Väck din partner också, för att vara ett lag är att dela det här ansvaret lika.', title_vi = 'Trách nhiệm của bố 👨‍🍼', body_vi = 'Đừng một mình gánh hết những lần thức dậy ban đêm. Hãy gọi cả bố dậy, vì là một đội nghĩa là chia đều trách nhiệm này.', title_zh = '爸爸的责任 👨‍🍼', body_zh = '夜醒别全都自己扛。也叫醒你的伴侣，因为团队就是平分这份责任。' WHERE id = 'bedd9e86-f764-4777-9e49-e315e75433fd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Te encontré! 🙈', body_es = '¿Se ríe a carcajadas cuando te tapas la cara con las manos y juegas al cucú-tras? Ya entiende del todo que los objetos siguen existiendo. Haz que este juego forme parte de vuestra rutina diaria.', title_fr = 'Coucou, je t''ai trouvé ! 🙈', body_fr = 'Il rit aux éclats quand vous jouez à coucou-caché en vous cachant le visage avec les mains ? La notion de permanence de l''objet se met en place. Faites de ce jeu une partie de votre routine quotidienne.', title_hi = 'पकड़ लिया! 🙈', body_hi = 'हाथों से चेहरा ढककर झाँकी-झाँकी खेलने पर वह ज़ोर से खिलखिलाता है? चीज़ों के स्थायी होने की समझ पूरी तरह बन रही है। इस खेल को अपने रोज़ के रूटीन का हिस्सा बनाइए।', title_id = 'Ketemu! 🙈', body_id = 'Ia tertawa keras saat Anda menutup wajah dengan tangan dan bermain cilukba? Pemahaman bahwa benda tetap ada sudah terbentuk. Jadikan permainan ini bagian dari rutinitas harian.', title_ja = '見つけた！🙈', body_ja = '両手で顔を隠して「いないいないばあ」をすると、声をあげて笑いますか？見えなくてもものはあるという理解がしっかりできてきています。この遊びを毎日のルーティンに取り入れましょう。', title_ko = '찾았다! 🙈', body_ko = '손으로 얼굴을 가리고 까꿍 하면 소리 내어 깔깔 웃나요? 대상 영속성 개념이 완전히 자리 잡고 있어요. 이 놀이를 매일의 일과로 만들어 보세요.', title_nl = 'Gevonden! 🙈', body_nl = 'Schatert je baby het uit als je je gezicht met je handen bedekt en kiekeboe speelt? Hij begrijpt nu helemaal dat dingen blijven bestaan. Maak van dit spelletje een vast onderdeel van jullie dag.', title_pl = 'Znalazłem cię! 🙈', body_pl = 'Głośno się śmieje, gdy zasłaniasz twarz dłońmi i robisz a kuku? W pełni kształtuje się rozumienie stałości przedmiotu. Niech ta zabawa stanie się częścią waszej codziennej rutyny.', title_pt = 'Encontrei-te! 🙈', body_pt = 'Dá gargalhadas quando tapa o rosto com as mãos e faz cucu? A noção de permanência dos objetos está a ficar completa. Torne este jogo parte da rotina diária.', title_sv = 'Hittade dig! 🙈', body_sv = 'Skrattar barnet högt när du täcker ansiktet med händerna och leker tittut? Förståelsen för att föremål finns kvar tar form fullt ut. Gör leken till en del av er dagliga rutin.', title_vi = 'Ú òa, tìm thấy rồi! 🙈', body_vi = 'Bé cười thành tiếng khi mẹ lấy tay che mặt rồi "ú òa"? Bé đã hiểu hoàn toàn rằng đồ vật vẫn tồn tại dù không nhìn thấy. Hãy biến trò chơi này thành một phần của nếp sinh hoạt hằng ngày.', title_zh = '找到你啦！🙈', body_zh = '你用手遮住脸玩躲猫猫时，宝宝笑出声来？物体恒存的概念正在完全形成。把这个游戏变成每天的固定节目吧。' WHERE id = 'c36dcca2-2b51-424c-b39c-c98f7988d549' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Manchas rebeldes 👗', body_es = 'La etapa de la alimentación complementaria significa casa y ropa siempre manchadas. No te enfades. Usa baberos de silicona y disfruta de estos momentos tan cómicos y coloridos.', title_fr = 'Des taches tenaces 👗', body_fr = 'Diversification rime avec maison et vêtements constamment tachés. Ne vous énervez pas. Utilisez des bavoirs en silicone et profitez simplement de ces moments drôles et colorés.', title_hi = 'ज़िद्दी दाग 👗', body_hi = 'ऊपरी आहार के दौर का मतलब है घर और कपड़ों पर लगातार दाग। इससे परेशान मत होइए। सिलिकॉन बिब इस्तेमाल कीजिए और इन मज़ेदार, रंगीन पलों का बस आनंद लीजिए।', title_id = 'Noda yang membandel 👗', body_id = 'Masa MPASI berarti rumah dan pakaian selalu bernoda. Jangan kesal. Gunakan celemek silikon dan nikmati saja momen-momen lucu penuh warna ini.', title_ja = 'しつこい汚れ 👗', body_ja = '離乳食の時期は、家も服もいつも汚れるもの。イライラしないで。シリコンのスタイを使って、このおもしろくてカラフルな瞬間を楽しみましょう。', title_ko = '지워지지 않는 얼룩 👗', body_ko = '이유식 시기는 집과 옷이 늘 얼룩진다는 뜻이에요. 짜증 내지 마세요. 실리콘 턱받이를 쓰고 이 우스꽝스럽고 알록달록한 순간들을 즐기세요.', title_nl = 'Hardnekkige vlekken 👗', body_nl = 'De periode van bijvoeding betekent dat het huis en de kleren steeds vlekken krijgen. Word er niet boos om. Gebruik siliconen slabbetjes en geniet gewoon van deze grappige, kleurrijke momenten.', title_pl = 'Uparte plamy 👗', body_pl = 'Rozszerzanie diety oznacza ciągłe plamy w domu i na ubraniach. Nie denerwuj się tym. Używaj silikonowych śliniaków i po prostu ciesz się tymi zabawnymi, kolorowymi chwilami.', title_pt = 'Nódoas teimosas 👗', body_pt = 'A diversificação alimentar significa casa e roupa sempre manchadas. Não se irrite. Use babetes de silicone e aproveite estes momentos cómicos e coloridos.', title_sv = 'Envisa fläckar 👗', body_sv = 'Perioden med smakportioner betyder ständiga fläckar i hemmet och på kläderna. Bli inte irriterad. Använd haklappar i silikon och njut bara av de här komiska, färgglada stunderna.', title_vi = 'Vết bẩn cứng đầu 👗', body_vi = 'Giai đoạn ăn dặm nghĩa là nhà cửa và quần áo luôn lấm lem. Đừng bực mình. Hãy dùng yếm silicone và tận hưởng những khoảnh khắc hài hước, đầy màu sắc này.', title_zh = '顽固的污渍 👗', body_zh = '辅食阶段意味着家里和衣服总是脏兮兮。别为此生气。用硅胶围兜，尽情享受这些滑稽又多彩的时刻吧。' WHERE id = '3f339310-d600-43dc-81a3-1b609288885e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Deja de juzgarte. 🛑', body_es = '¿Hoy ha habido demasiada pantalla o la casa se ha quedado desordenada? Solo eres una persona cansada que hace lo mejor que puede.', title_fr = 'Arrêtez de vous juger. 🛑', body_fr = 'Trop d''écrans aujourd''hui, ou la maison est restée en désordre ? Vous êtes simplement une personne fatiguée qui fait de son mieux.', title_hi = 'खुद को दोष देना बंद कीजिए 🛑', body_hi = 'आज स्क्रीन टाइम ज़्यादा हो गया या घर बिखरा रह गया? आप बस एक थकी हुई इंसान हैं और अपनी पूरी कोशिश कर रही हैं।', title_id = 'Berhentilah menyalahkan diri. 🛑', body_id = 'Hari ini waktu layar terlalu banyak, atau rumah berantakan? Anda hanyalah manusia yang lelah, dan Anda sudah melakukan yang terbaik.', title_ja = '自分を責めるのはやめましょう。🛑', body_ja = '今日はスクリーンタイムが長かった？家が散らかったまま？あなたはただ疲れているだけで、精いっぱいやっています。', title_ko = '자책은 그만하세요. 🛑', body_ko = '오늘 화면 보는 시간이 길었거나 집이 어질러졌나요? 그저 지친 사람일 뿐이고, 최선을 다하고 있어요.', title_nl = 'Stop met jezelf verwijten maken. 🛑', body_nl = 'Was er vandaag veel schermtijd of bleef het huis rommelig? Je bent gewoon een vermoeid mens en je doet je uiterste best.', title_pl = 'Przestań się obwiniać. 🛑', body_pl = 'Dziś było za dużo czasu przed ekranem albo w domu został bałagan? Jesteś po prostu zmęczonym człowiekiem i robisz, co możesz najlepiej.', title_pt = 'Pare de se culpar. 🛑', body_pt = 'Hoje houve muito tempo de ecrã ou a casa ficou desarrumada? É apenas uma pessoa cansada que faz o melhor que pode.', title_sv = 'Sluta döma dig själv. 🛑', body_sv = 'Blev det mycket skärmtid i dag, eller är det stökigt hemma? Du är bara en trött människa som gör sitt allra bästa.', title_vi = 'Đừng tự trách mình nữa. 🛑', body_vi = 'Hôm nay bé xem màn hình nhiều, hay nhà cửa còn bừa bộn? Mẹ chỉ là một người đang mệt mỏi và mẹ đang cố gắng hết sức.', title_zh = '别再责怪自己了 🛑', body_zh = '今天看屏幕的时间太长，或者家里没收拾？你只是一个累了的普通人，而且已经尽了最大的努力。' WHERE id = '60071670-7fa4-4f9f-829f-892d281a9741' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juego de tirar cosas 🥄', body_es = '¿Tira el juguete desde la trona y espera a que lo recojas? Está descubriendo la gravedad y la relación causa-efecto. Arma de paciencia y sonríe.', title_fr = 'Le jeu du « je jette par terre » 🥄', body_fr = 'Il jette un jouet depuis sa chaise haute et attend que vous le ramassiez ? Il découvre la gravité et la relation de cause à effet. Armez-vous de patience et souriez.', title_hi = 'चीज़ें नीचे फेंकने का खेल 🥄', body_hi = 'खाने की कुर्सी से खिलौना नीचे फेंकता है और आपके उठाने का इंतज़ार करता है? वह गुरुत्वाकर्षण और कारण-परिणाम का रिश्ता खोज रहा है। धैर्य रखिए और मुस्कुराइए।', title_id = 'Permainan menjatuhkan barang 🥄', body_id = 'Ia menjatuhkan mainan dari kursi makan lalu menunggu Anda mengambilnya? Ia sedang mempelajari gravitasi serta sebab dan akibat. Kumpulkan kesabaran dan tersenyumlah.', title_ja = 'ものを落とす遊び 🥄', body_ja = 'ベビーチェアからおもちゃを落として、拾ってくれるのを待っていますか？重力と原因と結果の関係を発見しているのです。気長に、ほほえんであげましょう。', title_ko = '물건 떨어뜨리기 놀이 🥄', body_ko = '식탁 의자에서 장난감을 떨어뜨리고 엄마가 주워 주길 기다리나요? 중력과 원인과 결과를 발견하는 중이에요. 인내심을 갖고 미소 지어 주세요.', title_nl = 'Het spelletje dingen op de grond gooien 🥄', body_nl = 'Gooit je baby vanuit de kinderstoel speeltjes op de grond en wacht hij tot je ze opraapt? Hij ontdekt de zwaartekracht en oorzaak en gevolg. Verzamel je geduld en glimlach.', title_pl = 'Zabawa w zrzucanie 🥄', body_pl = 'Zrzuca zabawkę z krzesełka i czeka, aż ją podniesiesz? Odkrywa grawitację i związek przyczyny i skutku. Uzbrój się w cierpliwość i się uśmiechnij.', title_pt = 'O jogo de atirar coisas ao chão 🥄', body_pt = 'Atira o brinquedo da cadeira da papa e fica à espera que o apanhe? Está a descobrir a gravidade e a relação de causa e efeito. Ganhe paciência e sorria.', title_sv = 'Leken att kasta saker på golvet 🥄', body_sv = 'Kastar barnet leksaken på golvet från matstolen och väntar på att du ska plocka upp den? Det upptäcker tyngdkraften och orsak och verkan. Samla ditt tålamod och le.', title_vi = 'Trò chơi thả đồ xuống đất 🥄', body_vi = 'Bé ném đồ chơi từ ghế ăn xuống rồi đợi mẹ nhặt lên? Bé đang khám phá trọng lực và quan hệ nhân quả. Hãy kiên nhẫn và mỉm cười nhé.', title_zh = '扔东西游戏 🥄', body_zh = '宝宝从餐椅上把玩具扔到地上，等你捡起来？宝宝在探索重力和因果关系。耐住性子，笑一笑吧。' WHERE id = 'fe5cb47e-9f22-41f9-a236-1db4b224e518' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Acostumbrarse a la oscuridad 🌙', body_es = 'Para que se duerma antes, apaga todas las luces que sobran y las pantallas de la habitación. La melatonina se segrega más rápido solo en un ambiente tranquilo y oscuro.', title_fr = 'S''habituer à l''obscurité 🌙', body_fr = 'Pour l''aider à s''endormir plus vite, éteignez toutes les lumières superflues et les écrans de la pièce. La sécrétion de mélatonine ne s''accélère que dans un environnement calme et sombre.', title_hi = 'अँधेरे की आदत 🌙', body_hi = 'उसे जल्दी सुलाने के लिए कमरे की सारी अतिरिक्त लाइटें और स्क्रीन बंद कीजिए। मेलाटोनिन हार्मोन शांत और अँधेरे माहौल में ही तेज़ी से बनता है।', title_id = 'Terbiasa dengan gelap 🌙', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar di kamar. Hormon melatonin hanya diproduksi lebih cepat di lingkungan yang tenang dan gelap.', title_ja = '暗さに慣れよう 🌙', body_ja = '早く寝つけるように、部屋のよけいな明かりや画面はすべて消しましょう。メラトニンというホルモンは、静かで暗い環境でこそ分泌が進みます。', title_ko = '어둠에 익숙해지기 🌙', body_ko = '빨리 잠들 수 있도록 방의 불필요한 조명과 화면을 모두 끄세요. 멜라토닌 분비는 조용하고 어두운 환경에서만 빨라져요.', title_nl = 'Wennen aan het donker 🌙', body_nl = 'Doe alle extra lampjes en schermen in de kamer uit, zodat je baby sneller in slaap valt. Het hormoon melatonine wordt alleen in een rustige, donkere omgeving sneller aangemaakt.', title_pl = 'Oswajanie z ciemnością 🌙', body_pl = 'Aby szybciej zasnął, wyłącz w pokoju wszystkie dodatkowe światła i ekrany. Wydzielanie melatoniny przyspiesza tylko w spokojnym i ciemnym otoczeniu.', title_pt = 'Habituar-se ao escuro 🌙', body_pt = 'Para o ajudar a adormecer mais depressa, desligue todas as luzes desnecessárias e os ecrãs do quarto. A produção de melatonina só acelera num ambiente calmo e escuro.', title_sv = 'Vänja sig vid mörkret 🌙', body_sv = 'Släck alla onödiga lampor och skärmar i rummet så att barnet somnar fortare. Hormonet melatonin utsöndras snabbare bara i en lugn och mörk miljö.', title_vi = 'Làm quen với bóng tối 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt hết đèn và màn hình không cần thiết trong phòng. Hormone melatonin chỉ được tiết ra nhanh hơn trong môi trường yên tĩnh và tối.', title_zh = '适应黑暗 🌙', body_zh = '为了让宝宝更快入睡，关掉房间里所有多余的灯和屏幕。褪黑素只有在安静、黑暗的环境里才会加速分泌。' WHERE id = '28d590c8-c8a6-4c89-b78b-e70f2f482c0d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mañanas caprichosas ☁️', body_es = '¿En cuanto abre los ojos llora por todo y nada le parece bien? Puede que esté en pleno salto de crecimiento. Simplemente abrázale mucho y dale seguridad.', title_fr = 'Matins grognons ☁️', body_fr = 'Dès qu''il ouvre les yeux, il pleure pour tout et rien ne lui convient ? Il est peut-être en plein pic de croissance. Faites-lui simplement plein de câlins pour le rassurer.', title_hi = 'चिड़चिड़ी सुबहें ☁️', body_hi = 'आँख खुलते ही हर बात पर रोता है और किसी चीज़ से खुश नहीं? शायद वह विकास की छलांग के बीच में है। उसे बस खूब गले लगाइए और भरोसा दीजिए।', title_id = 'Pagi yang rewel ☁️', body_id = 'Begitu membuka mata, ia menangis karena apa saja dan tidak ada yang membuatnya senang? Mungkin ia sedang berada di tengah lompatan pertumbuhan. Cukup peluk ia sering-sering dan beri rasa aman.', title_ja = 'ご機嫌ななめの朝 ☁️', body_ja = '目を開けたとたん、何にでも泣いて、何も気に入らない？成長の時期の真っ最中なのかもしれません。たっぷり抱きしめて、安心させてあげましょう。', title_ko = '칭얼대는 아침 ☁️', body_ko = '눈을 뜨자마자 모든 것에 울고 아무것도 마음에 들지 않나요? 성장 급등기 한가운데일 수도 있어요. 많이 안아 주며 안심시켜 주세요.', title_nl = 'Mopperige ochtenden ☁️', body_nl = 'Huilt je baby om alles zodra hij wakker wordt en is hij nergens tevreden mee? Misschien zit hij midden in een groeisprong. Knuffel hem gewoon veel en geef hem vertrouwen.', title_pl = 'Marudne poranki ☁️', body_pl = 'Gdy tylko otworzy oczy, płacze o wszystko i nic mu nie pasuje? Może jest w samym środku skoku rozwojowego. Po prostu często go przytulaj i dawaj poczucie bezpieczeństwa.', title_pt = 'Manhãs rabugentas ☁️', body_pt = 'Mal abre os olhos, chora por tudo e nada o contenta? Talvez esteja em pleno salto de crescimento. Dê-lhe muitos abraços e segurança.', title_sv = 'Gnälliga morgnar ☁️', body_sv = 'Gråter barnet över allt och är missnöjt med allt så fort det öppnar ögonen? Kanske är det mitt i ett tillväxtsprång. Krama det bara massor och ge det trygghet.', title_vi = 'Buổi sáng quấy khóc ☁️', body_vi = 'Vừa mở mắt bé đã khóc vì mọi thứ và chẳng hài lòng điều gì? Có thể bé đang ở giữa bước nhảy tăng trưởng. Chỉ cần ôm bé thật nhiều và cho bé cảm giác an toàn.', title_zh = '闹脾气的早晨 ☁️', body_zh = '一睁眼就为什么都哭，什么都不满意？也许正处在生长飞跃期。多抱抱宝宝，给宝宝安全感吧。' WHERE id = '31783568-6230-449d-98c8-e7b1b046a34e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡En cuanto se duerma, no corras a vaciar el lavavajillas! 🛋️', body_es = 'Túmbate en el sofá, cierra los ojos y durante 15 minutos déjate llevar por ese silencio total y tan poco habitual en casa.', title_fr = 'Bébé dort ? Ne courez pas vider le lave-vaisselle ! 🛋️', body_fr = 'Allongez-vous sur le canapé, fermez les yeux et fondez pendant 15 minutes dans ce silence absolu et si rare de la maison.', title_hi = 'बच्चे के सोते ही डिशवॉशर खाली करने मत भागिए! 🛋️', body_hi = 'सोफ़े पर लेट जाइए, आँखें बंद कीजिए और 15 मिनट घर की उस दुर्लभ, पूरी खामोशी में खो जाइए।', title_id = 'Jangan buru-buru mengosongkan mesin cuci piring begitu ia tidur! 🛋️', body_id = 'Berbaringlah di sofa, pejamkan mata, dan larut dalam keheningan langka di rumah selama 15 menit.', title_ja = '赤ちゃんが寝ても、食洗機を片づけに走らないで！🛋️', body_ja = 'ソファに横になって目を閉じ、15分間、家の中のめったにない完全な静けさに身をゆだねましょう。', title_ko = '아이가 잠들자마자 식기세척기로 달려가지 마세요! 🛋️', body_ko = '소파에 누워 눈을 감고 15분 동안 집 안의 드물고 완벽한 고요 속에 녹아들어 보세요.', title_nl = 'Ren niet naar de vaatwasser zodra je baby slaapt! 🛋️', body_nl = 'Ga op de bank liggen, sluit je ogen en smelt 15 minuten weg in die zeldzame, volkomen stilte in huis.', title_pl = 'Gdy maluszek zaśnie, nie biegnij rozładowywać zmywarki! 🛋️', body_pl = 'Połóż się na kanapie, zamknij oczy i przez 15 minut rozpłyń się w tej rzadkiej, całkowitej ciszy w domu.', title_pt = 'Mal o bebé adormeça, não corra para esvaziar a máquina da loiça! 🛋️', body_pt = 'Deite-se no sofá, feche os olhos e, durante 15 minutos, deixe-se envolver por aquele silêncio raro e absoluto da casa.', title_sv = 'Rusa inte iväg och töm diskmaskinen så fort barnet somnar! 🛋️', body_sv = 'Lägg dig i soffan, blunda och smält in i den sällsynta, totala tystnaden i hemmet i 15 minuter.', title_vi = 'Bé vừa ngủ thì đừng vội dọn máy rửa bát! 🛋️', body_vi = 'Hãy nằm xuống sofa, nhắm mắt lại và tan chảy trong sự yên tĩnh hiếm hoi, tuyệt đối của căn nhà trong 15 phút.', title_zh = '宝宝一睡着，别急着去清空洗碗机！🛋️', body_zh = '躺在沙发上，闭上眼睛，花15分钟沉浸在家里难得的绝对宁静中吧。' WHERE id = '38c7f3dd-4cf4-4758-8006-37d59832bac8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reunión de equipo 🥂', body_es = 'Habéis superado un día difícil. Cuando tu bebé se duerma, preparaos un té tu pareja y tú y no olvidéis valoraros diciendo «somos un equipo estupendo».', title_fr = 'Réunion d''équipe 🥂', body_fr = 'Vous avez surmonté une journée difficile. Quand bébé dort, servez-vous un thé avec votre conjoint et n''oubliez pas de vous féliciter en vous disant : « Nous formons vraiment une super équipe. »', title_hi = 'टीम मीटिंग 🥂', body_hi = 'आपने एक मुश्किल दिन पार कर लिया। बच्चे के सोने के बाद अपने साथी के साथ चाय बनाइए और ''हम सच में एक बढ़िया टीम हैं'' कहकर एक-दूसरे की तारीफ़ करना मत भूलिए।', title_id = 'Rapat tim 🥂', body_id = 'Hari yang berat sudah berlalu. Setelah si kecil tidur, seduh teh bersama pasangan dan jangan lupa saling menghargai dengan berkata, "Kita benar-benar tim yang hebat."', title_ja = 'チーム会議 🥂', body_ja = '大変な1日を乗り越えました。赤ちゃんが寝たら、パートナーとお茶をいれて「私たち、本当にいいチームだね」とお互いをねぎらうのを忘れずに。', title_ko = '팀 회의 🥂', body_ko = '힘든 하루를 넘겼어요. 아이가 잠든 뒤 배우자와 차 한 잔을 따르고 ''우리 정말 멋진 팀이야''라며 서로를 칭찬하는 걸 잊지 마세요.', title_nl = 'Teamoverleg 🥂', body_nl = 'Jullie hebben een zware dag achter de rug. Schenk als je baby slaapt een kop thee in met je partner en vergeet niet elkaar te waarderen: wij zijn echt een geweldig team.', title_pl = 'Narada drużyny 🥂', body_pl = 'Macie za sobą trudny dzień. Gdy maluszek zaśnie, zaparzcie z partnerem herbatę i nie zapomnijcie docenić się nawzajem słowami: „Naprawdę jesteśmy świetną drużyną”.', title_pt = 'Reunião de equipa 🥂', body_pt = 'Deixaram para trás um dia difícil. Depois de o bebé adormecer, sirvam-se de um chá com o seu companheiro e não se esqueçam de se elogiar: "somos mesmo uma ótima equipa".', title_sv = 'Lagmöte 🥂', body_sv = 'Ni har tagit er igenom en tuff dag. När barnet har somnat, häll upp en kopp te med din partner och glöm inte att uppskatta varandra: vi är verkligen ett fantastiskt lag.', title_vi = 'Họp đội 🥂', body_vi = 'Bố mẹ đã vượt qua một ngày vất vả. Sau khi bé ngủ, hãy cùng bố pha một tách trà và đừng quên khen ngợi nhau: "Chúng mình thật sự là một đội tuyệt vời".', title_zh = '团队会议 🥂', body_zh = '你们熬过了艰难的一天。宝宝睡着后，和伴侣泡杯茶，别忘了互相肯定：“我们真是个好团队！”' WHERE id = '3b5314f5-fa59-44ed-9fa8-b6cf2bce9e2d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El amigo del espejo 👀', body_es = 'Ponle delante de un espejo. Mira con qué asombro observa su reflejo e intenta tocarlo. Es una actividad estupenda para que tome conciencia de sí mismo.', title_fr = 'Le copain du miroir 👀', body_fr = 'Emmenez-le devant le miroir. Regardez-le contempler son reflet avec émerveillement et essayer de le toucher. C''est une activité formidable pour la conscience de soi.', title_hi = 'आईने वाला दोस्त 👀', body_hi = 'उसे आईने के सामने ले जाइए। देखिए वह अपने अक्स को कितनी हैरानी से देखता है और छूने की कोशिश करता है। यह खुद को पहचानने के लिए शानदार गतिविधि है।', title_id = 'Teman di dalam cermin 👀', body_id = 'Bawa ia ke depan cermin. Lihat betapa takjubnya ia menatap bayangannya dan mencoba menyentuhnya. Ini aktivitas luar biasa untuk mengenali dirinya sendiri.', title_ja = '鏡の中のお友達 👀', body_ja = '鏡の前に連れて行きましょう。自分の姿にびっくりして、さわろうとする様子を見守って。自分を知るための、すばらしい遊びです。', title_ko = '거울 속 친구 👀', body_ko = '아기를 거울 앞에 데려가 보세요. 거울 속 자신을 신기하게 바라보고 만지려는 모습을 지켜보세요. 자아 인식에 아주 좋은 활동이에요.', title_nl = 'Een vriendje in de spiegel 👀', body_nl = 'Zet je baby voor de spiegel. Kijk hoe verbaasd hij naar zijn spiegelbeeld kijkt en het probeert aan te raken. Een geweldige activiteit om zichzelf te leren kennen.', title_pl = 'Przyjaciel w lustrze 👀', body_pl = 'Zanieś go przed lustro. Zobacz, jak ze zdumieniem patrzy na swoje odbicie i próbuje go dotknąć. To wspaniała aktywność, dzięki której uczy się rozpoznawać siebie.', title_pt = 'O amigo do espelho 👀', body_pt = 'Leve-o à frente do espelho. Veja com que espanto olha para o próprio reflexo e tenta tocar-lhe. É uma atividade fantástica para ganhar consciência de si.', title_sv = 'Kompisen i spegeln 👀', body_sv = 'Bär fram barnet till spegeln. Se hur förundrat det tittar på sin spegelbild och försöker röra vid den. Det är en fantastisk aktivitet för barnets självmedvetenhet.', title_vi = 'Người bạn trong gương 👀', body_vi = 'Hãy bế bé đến trước gương. Ngắm bé ngạc nhiên nhìn hình mình và cố chạm vào đó. Đây là một hoạt động tuyệt vời giúp bé nhận thức về bản thân.', title_zh = '镜子里的小伙伴 👀', body_zh = '带宝宝到镜子前。看看宝宝如何惊奇地望着镜中的自己，还想伸手去摸。这对宝宝的自我认知是很棒的活动。' WHERE id = '579d5966-d49f-4125-a264-8acd785d0a8d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reposición rápida 🛒', body_es = '¿Se acaba el aceite para bebé o las toallitas húmedas? La Lista de la compra te espera en la app. Apunta ahí lo que haga falta y que tu pareja lo compre al volver del trabajo.', title_fr = 'Réapprovisionnement express 🛒', body_fr = 'Plus beaucoup d''huile pour bébé ou de lingettes ? La Liste de courses vous attend dans l''application. Notez-y vos besoins, votre conjoint s''en chargera en rentrant du travail.', title_hi = 'झटपट सामान 🛒', body_hi = 'बेबी ऑयल या वेट वाइप्स खत्म होने वाले हैं? ऐप में शॉपिंग लिस्ट आपका इंतज़ार कर रही है। ज़रूरतें वहाँ लिखिए, आपके साथी काम से लौटते समय ले आएँगे।', title_id = 'Persediaan kilat 🛒', body_id = 'Minyak bayi atau tisu basah hampir habis? Daftar Belanja menunggu Anda di aplikasi. Catat kebutuhannya di sana, biar pasangan Anda membelinya saat pulang kerja.', title_ja = 'すばやく補充 🛒', body_ja = 'ベビーオイルやおしりふきがなくなりそう？アプリの「買い物リスト」が待っています。必要なものを書いておけば、パートナーが仕事帰りに買ってきてくれます。', title_ko = '빠른 보충 🛒', body_ko = '베이비 오일이나 물티슈가 떨어져 가나요? 앱의 쇼핑 목록이 기다리고 있어요. 필요한 것을 적어 두면 배우자가 퇴근길에 사 올 거예요.', title_nl = 'Snel aanvullen 🛒', body_nl = 'Is de babyolie of zijn de billendoekjes bijna op? Het Boodschappenlijstje wacht in de app. Zet erop wat je nodig hebt en laat je partner het op weg van zijn werk halen.', title_pl = 'Szybkie zaopatrzenie 🛒', body_pl = 'Kończy się oliwka dla dziecka albo chusteczki nawilżane? Lista zakupów czeka w aplikacji. Zapisz tam, czego potrzeba, a partner kupi to w drodze z pracy.', title_pt = 'Reabastecimento rápido 🛒', body_pt = 'Estão a acabar o óleo de bebé ou os toalhetes? A Lista de Compras espera por si na app. Aponte lá o que falta e o seu companheiro trata disso no regresso do trabalho.', title_sv = 'Snabb påfyllning 🛒', body_sv = 'Håller babyoljan eller våtservetterna på att ta slut? Inköpslistan väntar på dig i appen. Skriv upp det ni behöver där, så kan din partner handla på vägen hem från jobbet.', title_vi = 'Bổ sung nhanh 🛒', body_vi = 'Dầu em bé hay khăn ướt sắp hết? Danh sách mua sắm đang chờ mẹ trong ứng dụng. Hãy ghi những thứ cần mua vào đó để bố mua trên đường đi làm về.', title_zh = '快速补货 🛒', body_zh = '婴儿油或湿巾快用完了？应用里的购物清单在等你。把需要的东西记在那里，让伴侣下班回家时买回来。' WHERE id = '9099f274-aa9c-4fe9-8624-5cd611699d2d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Al salir de paseo, que el tiempo no te engañe y tu bebé pase frío. No decidas mirando por la ventana: con el asistente Tiempo y ropa acertarás con lo más adecuado para fuera.', body_fr = 'Pour la promenade, ne vous laissez pas tromper par le temps et évitez qu''il prenne froid. Ne décidez pas en regardant par la fenêtre : avec l''assistant Météo et tenue, choisissez précisément ce qui convient dehors.', body_hi = 'घूमने निकलते समय मौसम के धोखे में आकर उसे ठंड मत लगने दीजिए। खिड़की से देखकर फ़ैसला मत कीजिए, मौसम और कपड़े टूल से बाहर के माहौल के हिसाब से सटीक फ़ैसला लीजिए।', body_id = 'Saat jalan-jalan, jangan sampai tertipu cuaca dan ia masuk angin. Jangan putuskan hanya dengan melihat dari jendela, gunakan asisten Cuaca dan Pakaian untuk pilihan yang paling tepat.', body_ja = 'お散歩のとき、天気にだまされてかぜをひかせないように。窓の外を見て決めないで、「天気と服装」アシスタントで外の環境にいちばん合った服装を正確に選びましょう。', body_ko = '산책 나갈 때 날씨에 속아 감기 걸리지 않게 하세요. 창밖만 보고 정하지 말고 날씨와 옷차림 도우미로 바깥 환경에 가장 알맞은 선택을 정확하게 하세요.', body_nl = 'Laat je bij een wandeling niet misleiden door het weer, zodat je baby geen kou vat. Beslis niet door uit het raam te kijken, maar kies met de assistent Weer en kleding precies wat past bij het weer buiten.', body_pl = 'Wychodząc na spacer, nie daj się zwieść pogodzie, żeby maluszek nie zmarzł. Nie decyduj, patrząc przez okno: z pomocnikiem Pogoda i ubiór precyzyjnie wybierzesz to, co najlepiej pasuje do warunków.', body_pt = 'Ao sair para passear, não se deixe enganar pelo tempo e evite que ele se constipe. Não decida só por olhar pela janela: com o assistente Tempo e Roupa, escolha com precisão o que é mais adequado lá fora.', body_sv = 'Låt inte vädret lura dig så att barnet blir kallt på promenaden. Bestäm inte genom att titta ut genom fönstret, fatta det mest exakta beslutet för förhållandena ute med Väder och kläder.', body_vi = 'Khi ra ngoài đi dạo, đừng để thời tiết đánh lừa khiến bé bị lạnh. Đừng chỉ nhìn qua cửa sổ mà quyết định, hãy dùng Trợ lý thời tiết và trang phục để chọn chính xác cách phù hợp nhất với điều kiện bên ngoài.', body_zh = '出门时别被天气骗了，让宝宝着凉。别只看窗外就做决定，用天气穿衣助手准确地做出最适合户外环境的选择。' WHERE id = '1d706879-d02b-44cf-bac5-4f53776477d3' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Quiero comer yo solo! 🥦', body_es = '¿Ya no quiere el puré con cuchara, sino coger las verduras con sus manos? Apoya su independencia. Sí, todo se ensuciará, pero su desarrollo se acelerará.', title_fr = 'Je mange tout seul ! 🥦', body_fr = 'Il ne veut plus de purée à la cuillère mais préfère attraper les légumes avec ses mains ? Soutenez son autonomie. Oui, ça va salir, mais son développement va s''accélérer.', title_hi = 'मैं खुद खाऊँगा! 🥦', body_hi = 'अब वह चम्मच से प्यूरी नहीं, बल्कि अपने हाथों से सब्ज़ियाँ पकड़कर खाना चाहता है? उसकी आत्मनिर्भरता का साथ दीजिए। हाँ, आसपास गंदगी होगी, पर उसका विकास तेज़ होगा।', title_id = 'Aku mau makan sendiri! 🥦', body_id = 'Ia ingin makan sayur dengan tangannya sendiri, bukan puree dengan sendok? Dukung kemandiriannya. Ya, sekitarnya akan kotor, tapi perkembangannya akan lebih cepat.', title_ja = '自分で食べる！🥦', body_ja = 'スプーンでペーストを食べるより、野菜を自分の手で持って食べたがっていますか？自分でやりたい気持ちを応援しましょう。まわりは汚れますが、成長はぐんと進みます。', title_ko = '내가 먹을래요! 🥦', body_ko = '이제 숟가락으로 퓌레를 먹기보다 채소를 손으로 잡고 먹고 싶어 하나요? 자립심을 응원해 주세요. 주변은 지저분해지겠지만 발달은 빨라져요.', title_nl = 'Ik eet zelf! 🥦', body_nl = 'Wil je baby geen hapje meer van de lepel, maar groente zelf met zijn handje vastpakken en eten? Steun zijn zelfstandigheid. Ja, het wordt een boel troep, maar zijn ontwikkeling gaat sneller.', title_pl = 'Sam zjem! 🥦', body_pl = 'Zamiast przecieru z łyżeczki chce jeść warzywa, trzymając je własną rączką? Wspieraj jego samodzielność. Tak, będzie bałagan, ale rozwój przyspieszy.', title_pt = 'Eu como sozinho! 🥦', body_pt = 'Já não quer o puré à colher e prefere pegar nos legumes com a mão? Apoie a independência dele. Sim, vai sujar tudo à volta, mas o desenvolvimento acelera.', title_sv = 'Jag äter själv! 🥦', body_sv = 'Vill barnet redan äta grönsaker med egna händer i stället för puré med sked? Stötta självständigheten. Ja, det blir kladdigt runt omkring, men utvecklingen går fortare.', title_vi = 'Con tự ăn! 🥦', body_vi = 'Bé không muốn ăn món nghiền bằng thìa nữa mà muốn tự cầm rau củ bằng tay? Hãy ủng hộ sự tự lập của bé. Đúng, xung quanh sẽ bẩn, nhưng bé sẽ phát triển nhanh hơn.', title_zh = '我要自己吃！🥦', body_zh = '宝宝不想用勺子吃泥，而是想自己用手抓着蔬菜吃？支持宝宝的独立吧。没错，周围会弄脏，但宝宝的发育会更快。' WHERE id = 'acd7fb31-0c36-4f0b-9849-cf983e0b0e95' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El mundo mágico de los cuentos 🪄', body_es = 'Esta noche prueba algo totalmente distinto en Cuentos inteligentes. Adapta tu tono de voz al ritmo del cuento.', title_fr = 'Le monde magique du conte 🪄', body_fr = 'Ce soir, essayez quelque chose de tout à fait différent avec les Contes intelligents : adaptez le ton de votre voix au rythme de l''histoire.', title_hi = 'कहानी की जादुई दुनिया 🪄', body_hi = 'आज शाम स्मार्ट कहानियों में कुछ बिल्कुल अलग आज़माइए। अपनी आवाज़ का अंदाज़ कहानी की लय के हिसाब से ढालिए।', title_id = 'Dunia dongeng yang ajaib 🪄', body_id = 'Malam ini, coba sesuatu yang benar-benar berbeda di Dongeng Pintar. Sesuaikan nada suara Anda dengan irama dongengnya.', title_ja = 'お話の魔法の世界 🪄', body_ja = '今夜は「スマートおはなし」でまったく新しいことを試してみましょう。お話のリズムに合わせて、声のトーンを変えてみてください。', title_ko = '동화의 마법 세계 🪄', body_ko = '오늘 저녁 스마트 동화에서 완전히 새로운 걸 시도해 보세요. 목소리 톤을 이야기의 리듬에 맞춰 보세요.', title_nl = 'De magische wereld van sprookjes 🪄', body_nl = 'Probeer vanavond in Slimme sprookjes eens iets heel anders. Pas je stem aan het ritme van het sprookje aan.', title_pl = 'Magiczny świat bajki 🪄', body_pl = 'Spróbuj dziś wieczorem w Mądrych bajkach czegoś zupełnie innego. Dopasuj ton głosu do rytmu bajki.', title_pt = 'O mundo mágico das histórias 🪄', body_pt = 'Esta noite, experimente algo totalmente diferente nas Histórias Inteligentes. Ajuste o tom de voz ao ritmo da história.', title_sv = 'Sagans magiska värld 🪄', body_sv = 'Prova något helt annorlunda i Smarta sagor i kväll. Anpassa din röst efter sagans rytm.', title_vi = 'Thế giới kỳ diệu của truyện cổ tích 🪄', body_vi = 'Tối nay hãy thử một điều hoàn toàn khác trong Truyện cổ tích thông minh. Điều chỉnh giọng của mẹ theo nhịp điệu câu chuyện.', title_zh = '故事的魔法世界 🪄', body_zh = '今晚在智能故事里试试完全不同的玩法。让你的语调跟上故事的节奏吧。' WHERE id = 'e1819391-1d2d-450e-ac14-9ecfa65465d4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de noche de papá 👨‍🍼', body_es = 'Ya tienes bastante con el cansancio del día. Esta tarde deja en manos de papá prepararle para dormir y ponerle el pijama, y tú simplemente mira.', title_fr = 'Le service de nuit de papa 👨‍🍼', body_fr = 'La fatigue de la journée vous suffit. En fin de journée, confiez à papa la préparation au coucher et la mise en pyjama, et contentez-vous de regarder.', title_hi = 'पापा की रात की ड्यूटी 👨‍🍼', body_hi = 'दिन की थकान आपके लिए काफ़ी है। शाम को बच्चे को सोने के लिए तैयार करना और पजामा पहनाना पापा को सौंप दीजिए और बस दूर से देखिए।', title_id = 'Giliran malam ayah 👨‍🍼', body_id = 'Lelah seharian sudah cukup bagi Anda. Serahkan persiapan tidur dan memakaikan piyama kepada ayah, dan cukup lihat dari jauh.', title_ja = 'パパの夜の当番 👨‍🍼', body_ja = '昼間の疲れだけでもう十分。夕方は寝る準備とパジャマのお着替えをパパにまかせて、あなたは見守るだけにしましょう。', title_ko = '아빠의 밤 당번 👨‍🍼', body_ko = '낮의 피로로 충분해요. 저녁에 아이를 재울 준비를 하고 잠옷을 입히는 일은 아빠에게 맡기고 곁에서 지켜보기만 하세요.', title_nl = 'Papa''s avonddienst 👨‍🍼', body_nl = 'De vermoeidheid van overdag is genoeg voor jou. Laat papa ''s avonds je baby klaarmaken voor bed en zijn pyjama aantrekken, en kijk gewoon toe.', title_pl = 'Nocna zmiana taty 👨‍🍼', body_pl = 'Wystarczy ci dziennego zmęczenia. Pod wieczór powierz tacie przygotowanie maluszka do snu i zakładanie piżamki, a sama tylko patrz z boku.', title_pt = 'O turno da noite do pai 👨‍🍼', body_pt = 'O cansaço do dia já chega. Ao fim do dia, deixe ao pai a tarefa de preparar o bebé para dormir e vestir-lhe o pijama, e limite-se a assistir.', title_sv = 'Pappas nattskift 👨‍🍼', body_sv = 'Dagens trötthet räcker för dig. Låt pappa ta hand om att göra barnet redo för sömnen och sätta på pyjamasen i kväll, och titta bara på från sidan.', title_vi = 'Ca đêm của bố 👨‍🍼', body_vi = 'Mệt mỏi ban ngày đã đủ với mẹ rồi. Chiều tối nay, hãy giao việc chuẩn bị cho bé đi ngủ và thay đồ ngủ cho bố, còn mẹ chỉ cần ngắm từ xa.', title_zh = '爸爸的夜班 👨‍🍼', body_zh = '白天的疲惫已经够你受了。今晚把哄睡准备和换睡衣的事交给爸爸，你只在一旁看着就好。' WHERE id = 'd79d065c-4399-4ac9-8bd9-d4970a686fba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te preocupa su gráfica de talla y peso hacia el 8.º mes? En vez de leer artículos que asustan en internet, pide a Anacan AI una tabla precisa y con base científica.', body_fr = 'La courbe de taille et de poids vous inquiète à l''approche du 8e mois ? Plutôt que de lire des articles effrayants sur Internet, demandez à Anacan AI un tableau précis et fondé sur la science.', body_hi = '8वें महीने के आसपास बच्चे की लंबाई और वज़न का चार्ट आपको परेशान कर रहा है? इंटरनेट पर डरावने लेख पढ़ने के बजाय Anacan AI से सटीक और वैज्ञानिक तालिका माँगिए।', body_id = 'Grafik tinggi dan berat badannya menjelang bulan ke-8 membuat Anda khawatir? Daripada membaca artikel menakutkan di internet, minta tabel yang akurat dan berbasis ilmiah dari Anacan AI.', body_ja = '生後8か月ごろの身長と体重のグラフが気になりますか？ネットで怖い記事を読むより、Anacan AIに正確で科学的な成長の目安を聞いてみましょう。', body_ko = '8개월 무렵 아이의 키와 몸무게 그래프가 걱정되나요? 인터넷에서 무서운 글을 읽는 대신 Anacan AI에게 정확하고 과학적인 표를 요청하세요.', body_nl = 'Maak je je rond de 8e maand zorgen over de groeicurve van lengte en gewicht? Lees geen enge artikelen op internet, maar vraag Anacan AI om een precieze, wetenschappelijk onderbouwde tabel.', body_pl = 'Martwi cię siatka wzrostu i wagi maluszka w okolicach 8. miesiąca? Zamiast czytać w internecie straszne artykuły, poproś Anacan AI o dokładną tabelę opartą na nauce.', body_pt = 'Perto do 8.º mês, o gráfico de altura e peso do bebé preocupa-a? Em vez de ler artigos assustadores na internet, peça ao Anacan AI uma tabela precisa e com base científica.', body_sv = 'Oroar barnets längd- och viktkurva dig inför 8:e månaden? I stället för att läsa skrämmande artiklar på nätet, be Anacan AI om en exakt och vetenskapligt grundad tabell.', body_vi = 'Biểu đồ chiều cao và cân nặng của bé khi gần 8 tháng khiến mẹ lo lắng? Thay vì đọc những bài viết đáng sợ trên mạng, hãy hỏi Anacan AI một bảng số liệu chính xác, có cơ sở khoa học.', body_zh = '快到8个月时，宝宝的身高体重曲线让你担心？与其在网上看吓人的文章，不如向Anacan AI要一份准确、有科学依据的参考表。' WHERE id = 'ea309314-6720-4ddf-9fe1-7a4fb805b43f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Recupera energía 🍲', body_es = '¿Sientes el cansancio hasta en los huesos? Elige en Recetas saludables un smoothie especial que se prepara en 10 minutos, apoya tu producción de leche y te llena de vitalidad.', title_fr = 'Retrouvez votre énergie 🍲', body_fr = 'La fatigue vous pèse jusqu''aux os ? Choisissez dans les Recettes saines un smoothie spécial prêt en 10 minutes, qui soutiendra votre lactation et vous redonnera du tonus.', title_hi = 'अपनी ऊर्जा लौटाइए 🍲', body_hi = 'थकान हड्डियों तक उतर गई है? सेहतमंद रेसिपी से 10 मिनट में बनने वाली ऐसी खास स्मूदी चुनिए जो दूध बढ़ाने में मदद करे और आपको तरोताज़ा भी करे।', title_id = 'Pulihkan energi 🍲', body_id = 'Lelahnya terasa sampai ke tulang? Pilih smoothie istimewa dari Resep Sehat yang siap dalam 10 menit, mendukung ASI sekaligus membuat Anda segar.', title_ja = '元気を取り戻そう 🍲', body_ja = '疲れが体の芯までたまっている？「ヘルシーレシピ」から、10分でできて母乳もサポートし、元気もくれる特別なスムージーを選びましょう。', title_ko = '에너지를 되찾아요 🍲', body_ko = '피로가 뼛속까지 스몄나요? 건강한 레시피에서 10분 만에 만드는, 모유에도 도움이 되고 기운도 북돋아 줄 특별한 스무디를 골라 보세요.', title_nl = 'Laad je energie op 🍲', body_nl = 'Zit de vermoeidheid tot in je botten? Kies uit Gezonde recepten een speciale smoothie die in 10 minuten klaar is, je melkproductie ondersteunt en je weer fit maakt.', title_pl = 'Odzyskaj energię 🍲', body_pl = 'Zmęczenie daje ci się we znaki? Wybierz w Zdrowych przepisach specjalne smoothie gotowe w 10 minut, które wesprze laktację i doda ci wigoru.', title_pt = 'Recupere a energia 🍲', body_pt = 'O cansaço já lhe chegou aos ossos? Escolha nas Receitas Saudáveis um smoothie especial que se faz em 10 minutos, ajuda a produção de leite e a deixa revigorada.', title_sv = 'Fyll på din energi 🍲', body_sv = 'Sitter tröttheten i hela kroppen? Välj en speciell smoothie från Hälsosamma recept som är klar på 10 minuter och både stöttar mjölkproduktionen och piggar upp dig.', title_vi = 'Nạp lại năng lượng 🍲', body_vi = 'Mệt mỏi thấm vào tận xương? Hãy chọn một món sinh tố đặc biệt làm trong 10 phút từ Công thức lành mạnh, vừa hỗ trợ nguồn sữa, vừa giúp mẹ tỉnh táo.', title_zh = '恢复体力 🍲', body_zh = '累到骨子里了？从健康食谱里挑一款10分钟就能做好的特别奶昔，既能支持奶量，又能让你精神焕发。' WHERE id = '1c1e068a-2609-422f-991f-68ad50839ea3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Filtra los ruidos 🤫', body_es = 'La primera media hora después de dormirse es el momento más delicado. Comprueba el ambiente con el Medidor de sonido y evita ruidos repentinos de la habitación de al lado o de la tele.', title_fr = 'Filtrez les bruits 🤫', body_fr = 'La première demi-heure après l''endormissement est la plus sensible. Vérifiez l''ambiance avec le Sonomètre et évitez les bruits soudains venant de la pièce voisine ou de la télévision.', title_hi = 'आवाज़ों को छानिए 🤫', body_hi = 'सोने के बाद का पहला आधा घंटा सबसे नाज़ुक होता है। साउंड मीटर से माहौल जाँचिए और बगल के कमरे या टीवी से आने वाले अचानक शोर को रोकिए।', title_id = 'Saring kebisingan 🤫', body_id = 'Setengah jam pertama setelah tertidur adalah masa paling sensitif. Cek suasana dengan Pengukur Suara dan cegah suara mendadak dari kamar sebelah atau TV.', title_ja = '音をシャットアウト 🤫', body_ja = '寝ついてから最初の30分は、いちばん眠りが浅い時間です。「サウンドメーター」で環境をチェックし、隣の部屋やテレビからの急な音を防ぎましょう。', title_ko = '소음을 걸러 내요 🤫', body_ko = '잠든 직후 처음 30분이 가장 예민한 시간이에요. 소음 측정기로 환경을 확인하고 옆방이나 TV에서 나는 갑작스러운 소음을 막아 주세요.', title_nl = 'Filter de geluiden 🤫', body_nl = 'Het eerste halfuur na het inslapen is het gevoeligst. Controleer de omgeving met de Geluidsmeter en voorkom plotseling lawaai uit de kamer ernaast of van de tv.', title_pl = 'Odfiltruj dźwięki 🤫', body_pl = 'Pierwsze pół godziny po zaśnięciu to najwrażliwszy czas. Sprawdź otoczenie Miernikiem dźwięku i nie dopuść do nagłego hałasu z sąsiedniego pokoju czy telewizora.', title_pt = 'Filtre os sons 🤫', body_pt = 'A primeira meia hora depois de adormecer é o período mais sensível. Verifique o ambiente com o Medidor de Som e evite barulhos súbitos da divisão ao lado ou da televisão.', title_sv = 'Filtrera bort ljuden 🤫', body_sv = 'Den första halvtimmen efter att barnet har somnat är den känsligaste. Kolla miljön med Ljudmätaren och förhindra plötsligt oväsen från rummet bredvid eller tv:n.', title_vi = 'Lọc bớt tiếng ồn 🤫', body_vi = 'Nửa tiếng đầu sau khi bé ngủ là lúc nhạy cảm nhất. Hãy kiểm tra môi trường bằng Đo âm thanh và ngăn tiếng ồn đột ngột từ phòng bên hay tivi.', title_zh = '过滤噪音 🤫', body_zh = '入睡后的头半小时是最敏感的时候。用噪音测量检查环境，避免隔壁房间或电视突然发出声响。' WHERE id = '51badc42-c8bc-4aa3-b0b8-ec576b19fa07' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gateo con objetivo 🐢', body_es = 'Ya elige su objetivo y gatea rápido hacia él. Retira enseguida del suelo todos los objetos pequeños y peligrosos que pueda tragarse.', title_fr = 'Le quatre pattes avec un but 🐢', body_fr = 'Il choisit déjà sa cible et file vers elle à quatre pattes. Retirez tout de suite du sol tous les petits objets dangereux qu''il pourrait avaler.', title_hi = 'लक्ष्य की ओर रेंगना 🐢', body_hi = 'उसने अपना लक्ष्य चुन लिया है और तेज़ी से उसकी ओर रेंग रहा है। कमरे में फ़र्श पर पड़ी सारी छोटी, निगली जा सकने वाली खतरनाक चीज़ें तुरंत हटा दीजिए।', title_id = 'Merangkak dengan tujuan 🐢', body_id = 'Ia sudah memilih sasaran dan merangkak cepat ke arahnya. Segera singkirkan semua benda kecil berbahaya yang bisa tertelan dari lantai.', title_ja = '目的のあるはいはい 🐢', body_ja = 'もう目標を決めて、そこへ向かってすばやくはいはいしています。部屋の床にある、飲みこめる小さくて危ないものはすぐに片づけましょう。', title_ko = '목표가 있는 기어가기 🐢', body_ko = '이제 목표를 정하고 그쪽으로 빠르게 기어가요. 방바닥에 있는 작고 삼킬 수 있는 위험한 물건은 바로 치워 주세요.', title_nl = 'Kruipen met een doel 🐢', body_nl = 'Je baby kiest al een doel en kruipt er snel naartoe. Haal meteen alle kleine, gevaarlijke dingen die ingeslikt kunnen worden van de vloer.', title_pl = 'Raczkowanie do celu 🐢', body_pl = 'Wybiera już cel i szybko do niego raczkuje. Od razu usuń z poziomu podłogi wszystkie małe, niebezpieczne przedmioty, które mógłby połknąć.', title_pt = 'Gatinhar com um objetivo 🐢', body_pt = 'Já escolhe o alvo e gatinha depressa até ele. Retire já do chão todos os objetos pequenos e perigosos que possam ser engolidos.', title_sv = 'Målmedvetet krypande 🐢', body_sv = 'Barnet har redan valt sitt mål och kryper snabbt mot det. Plocka genast bort alla små, farliga saker som kan sväljas från golvnivå i rummet.', title_vi = 'Bò có mục tiêu 🐢', body_vi = 'Bé đã chọn được mục tiêu và bò thật nhanh về phía đó. Hãy dọn ngay mọi đồ vật nhỏ, nguy hiểm, có thể nuốt phải khỏi sàn nhà.', title_zh = '有目标地爬 🐢', body_zh = '宝宝已经会选好目标，飞快地爬过去了。马上把房间地面上所有能吞下去的危险小物件收起来。' WHERE id = '69f05aef-6a67-462b-8173-638d2cb174d5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te ha asustado un nuevo comportamiento de tu peque (por ejemplo, darse golpes con la cabeza en la pared)? Escribe en la Comunidad Anacan y lee cómo han pasado otras mamás esta etapa.', body_fr = 'Un nouveau comportement de votre enfant (par exemple, se cogner la tête contre le mur) vous a fait peur ? Écrivez dans la Communauté Anacan et lisez comment d''autres mamans ont traversé cette étape.', body_hi = 'बच्चे की किसी नई हरकत (जैसे दीवार पर सिर मारना) ने आपको डरा दिया? Anacan कम्युनिटी में लिखिए और पढ़िए कि दूसरी माँएँ इस दौर से कैसे गुज़रीं।', body_id = 'Gerakan baru si kecil (misalnya membenturkan kepala ke dinding) membuat Anda takut? Tulis di Komunitas Anacan dan baca bagaimana ibu-ibu lain melewati tahap ini.', body_ja = '赤ちゃんの新しい行動（たとえば頭を壁にぶつけるなど）にびっくりしましたか？Anacanコミュニティに投稿して、ほかのママたちがこの時期をどう乗り越えたか読んでみましょう。', body_ko = '아이의 새로운 행동(예: 벽에 머리 박기)에 놀라셨나요? Anacan 커뮤니티에 글을 남기고 다른 엄마들은 이 시기를 어떻게 지났는지 읽어 보세요.', body_nl = 'Schrok je van iets nieuws dat je kindje doet (bijvoorbeeld met zijn hoofd tegen de muur bonken)? Schrijf in de Anacan Community en lees hoe andere moeders deze fase doorkwamen.', body_pl = 'Nowe zachowanie maluszka (na przykład uderzanie główką o ścianę) cię przestraszyło? Napisz w Społeczności Anacan i przeczytaj, jak inne mamy przeszły przez ten etap.', body_pt = 'Um comportamento novo do bebé (por exemplo, bater com a cabeça na parede) assustou-a? Escreva na Comunidade Anacan e leia como outras mães passaram por esta fase.', body_sv = 'Blev du rädd av en ny rörelse hos barnet (till exempel att det slår huvudet i väggen)? Skriv i Anacans Community och läs hur andra mammor har tagit sig igenom den här fasen.', body_vi = 'Một hành động mới của bé (ví dụ đập đầu vào tường) khiến mẹ hoảng sợ? Hãy viết vào Cộng đồng Anacan và đọc xem các bà mẹ khác đã vượt qua giai đoạn này thế nào.', body_zh = '宝宝的新动作（比如用头撞墙）吓到你了？发到Anacan社区，看看其他妈妈是怎样度过这个阶段的。' WHERE id = '7405692f-45e1-45fa-9dd9-b527045b5e7d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pasos valientes 🧗‍♂️', body_es = '¿Se agarra al sofá e intenta soltar una mano? Su sentido del equilibrio se desarrolla muy rápido. Vigílale de cerca y observa con una sonrisa sus intentos sin miedo.', title_fr = 'Des pas courageux 🧗‍♂️', body_fr = 'Il se tient au canapé et essaie de lâcher une main ? Son sens de l''équilibre se développe vite. Observez ses essais intrépides avec le sourire, en le sécurisant à distance.', title_hi = 'हिम्मत भरे कदम 🧗‍♂️', body_hi = 'सोफ़ा पकड़कर एक हाथ छोड़ने की कोशिश करता है? उसका संतुलन तेज़ी से विकसित हो रहा है। दूर से उसकी सुरक्षा का ध्यान रखते हुए इन निडर कोशिशों को मुस्कुराकर देखिए।', title_id = 'Langkah-langkah berani 🧗‍♂️', body_id = 'Ia berpegangan pada sofa dan mencoba melepaskan satu tangan? Keseimbangannya berkembang pesat. Jaga dari dekat dan saksikan usahanya yang tanpa rasa takut sambil tersenyum.', title_ja = '勇気ある一歩 🧗‍♂️', body_ja = 'ソファにつかまって、片手を離そうとしていますか？バランス感覚がぐんぐん育っています。安全に気を配りながら、そのこわいもの知らずの挑戦を笑顔で見守りましょう。', title_ko = '용감한 발걸음 🧗‍♂️', body_ko = '소파를 잡고 한 손을 놓아 보려 하나요? 균형 감각이 빠르게 발달하고 있어요. 멀리서 안전하게 지켜 주며 이 겁 없는 도전을 미소로 바라봐 주세요.', title_nl = 'Dappere stapjes 🧗‍♂️', body_nl = 'Houdt je baby zich vast aan de bank en probeert hij één hand los te laten? Het evenwichtsgevoel ontwikkelt zich snel. Blijf op een afstandje in de buurt en kijk met een glimlach naar deze onbevreesde pogingen.', title_pl = 'Odważne kroki 🧗‍♂️', body_pl = 'Trzyma się kanapy i próbuje puścić jedną rączkę? Zmysł równowagi szybko się rozwija. Asekuruj z bliska te nieustraszone próby i obserwuj je z uśmiechem.', title_pt = 'Passos corajosos 🧗‍♂️', body_pt = 'Agarra-se ao sofá e tenta largar uma mão? O equilíbrio está a desenvolver-se depressa. Proteja-o à distância e acompanhe com um sorriso estas tentativas sem medo.', title_sv = 'Modiga steg 🧗‍♂️', body_sv = 'Håller barnet i soffan och försöker släppa med ena handen? Balanssinnet utvecklas snabbt. Följ de orädda försöken med ett leende och var redo att ta emot på avstånd.', title_vi = 'Những bước đi dũng cảm 🧗‍♂️', body_vi = 'Bé bám vào sofa và thử buông một tay? Khả năng giữ thăng bằng của bé đang phát triển nhanh. Hãy đứng gần che chắn và mỉm cười ngắm những nỗ lực không chút sợ hãi ấy.', title_zh = '勇敢的尝试 🧗‍♂️', body_zh = '宝宝扶着沙发，试着松开一只手？平衡感发展得很快。在不远处护着，笑着看宝宝这些无畏的尝试吧。' WHERE id = 'cad415e5-9ff2-468b-bfee-aaed538d25a0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Deja salir tus emociones 📝', body_es = '¿Te sientes muy sola e incomprendida? Es lo más natural. Anota tus sentimientos en el Diario de ánimo con sinceridad y sin filtros.', title_fr = 'Libérez vos émotions 📝', body_fr = 'Vous vous sentez très seule et incomprise ? C''est le sentiment le plus naturel qui soit. Notez sincèrement vos émotions, sans aucun filtre, dans le Journal d''humeur.', title_hi = 'भावनाओं को बाहर आने दीजिए 📝', body_hi = 'बहुत अकेली और अनसमझी महसूस कर रही हैं? यह सबसे स्वाभाविक एहसास है। मूड डायरी में अपनी भावनाएँ बिना किसी फ़िल्टर के, सच्चे मन से लिखिए।', title_id = 'Lepaskan perasaan Anda 📝', body_id = 'Merasa sangat sendirian dan tidak dipahami? Itu perasaan yang sangat wajar. Catat perasaan Anda dengan jujur, tanpa filter, di Buku Harian Suasana Hati.', title_ja = '気持ちを解き放とう 📝', body_ja = 'とても孤独で、わかってもらえないと感じますか？それはごく自然な気持ちです。「気分日記」に、飾らずに正直な気持ちを書きとめましょう。', title_ko = '감정을 자유롭게 풀어 주세요 📝', body_ko = '너무 외롭고 아무도 이해해 주지 않는 것 같나요? 가장 자연스러운 감정이에요. 기분 일기에 필터 없이 솔직하게 감정을 적어 보세요.', title_nl = 'Laat je gevoelens de vrije loop 📝', body_nl = 'Voel je je erg alleen en onbegrepen? Dat is een heel normaal gevoel. Schrijf je gevoelens zonder filter en eerlijk op in je Stemmingsdagboek.', title_pl = 'Uwolnij emocje 📝', body_pl = 'Czujesz się bardzo samotna i niezrozumiana? To najbardziej naturalne uczucie. Zapisz w Dzienniku nastroju swoje emocje szczerze, bez żadnych filtrów.', title_pt = 'Liberte as emoções 📝', body_pt = 'Sente-se muito sozinha e incompreendida? É o sentimento mais natural. Escreva no Diário de Humor o que sente, sem filtros e com sinceridade.', title_sv = 'Släpp fram känslorna 📝', body_sv = 'Känner du dig väldigt ensam och missförstådd? Det är den mest naturliga känslan. Skriv ärligt ner dina känslor i Humördagboken, helt utan filter.', title_vi = 'Giải phóng cảm xúc 📝', body_vi = 'Mẹ thấy thật cô đơn và không ai hiểu mình? Đó là cảm giác hết sức tự nhiên. Hãy ghi lại cảm xúc thật lòng, không chút che giấu, vào Nhật ký tâm trạng.', title_zh = '释放情绪 📝', body_zh = '觉得特别孤单、没人理解？这是再自然不过的感受。在心情日记里不加任何过滤，真诚地记下你的感受吧。' WHERE id = 'e2523211-afd7-48c7-8227-2ec7b0b2f0f7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El caos de casa 🌪️', body_es = '¿Hay juguetes por toda la habitación? Más importante que la limpieza son 10 minutos de risas con tu peque. Los juguetes seguirán ahí mañana, no te agotes.', title_fr = 'Le chaos de la maison 🌪️', body_fr = 'Des jouets partout dans la pièce ? Ce n''est pas le ménage qui compte, mais les 10 minutes de sourires passées avec lui. Les jouets seront encore là demain, ne vous épuisez pas.', title_hi = 'घर की अफ़रा-तफ़री 🌪️', body_hi = 'कमरे में हर जगह खिलौने हैं? सफ़ाई नहीं, उसके साथ हँसते हुए बिताए 10 मिनट ज़्यादा ज़रूरी हैं। खिलौने कल भी वहीं होंगे, खुद को मत थकाइए।', title_id = 'Rumah yang kacau 🌪️', body_id = 'Mainan di setiap sudut ruangan? Yang lebih penting bukan kebersihan, melainkan 10 menit penuh tawa bersamanya. Mainan itu besok juga masih di sana, jangan memaksakan diri.', title_ja = 'おうちのカオス 🌪️', body_ja = '部屋中おもちゃだらけ？お掃除よりも、赤ちゃんと笑顔で過ごす10分のほうがずっと大切です。おもちゃは明日もそこにあります。無理をしないで。', title_ko = '집 안의 혼돈 🌪️', body_ko = '방 안이 온통 장난감인가요? 청소보다 아기와 함께 웃으며 보내는 10분이 더 소중해요. 장난감은 내일도 그 자리에 있을 테니 무리하지 마세요.', title_nl = 'Chaos in huis 🌪️', body_nl = 'Overal speelgoed in de kamer? Niet de schoonmaak, maar 10 vrolijke minuten samen met je baby zijn belangrijker. Het speelgoed ligt er morgen ook nog, maak jezelf niet moe.', title_pl = 'Domowy chaos 🌪️', body_pl = 'Wszędzie w pokoju zabawki? Ważniejsze od sprzątania jest 10 radosnych minut spędzonych z maluszkiem. Zabawki jutro też tam będą, nie męcz się.', title_pt = 'O caos da casa 🌪️', body_pt = 'Há brinquedos por todo o quarto? Mais importante do que a limpeza são 10 minutos de sorrisos passados com ele. Os brinquedos amanhã continuam lá, não se canse.', title_sv = 'Kaos hemma 🌪️', body_sv = 'Leksaker överallt i rummet? Det är inte städningen som är viktigast, utan 10 glada minuter tillsammans med barnet. Leksakerna ligger kvar i morgon också, slit inte ut dig.', title_vi = 'Nhà cửa hỗn loạn 🌪️', body_vi = 'Đồ chơi khắp phòng? Dọn dẹp không quan trọng bằng 10 phút vui vẻ mẹ dành cho bé. Đồ chơi ngày mai vẫn ở đó, đừng làm mình mệt thêm.', title_zh = '家里一团乱 🌪️', body_zh = '房间里到处是玩具？比起打扫，和宝宝一起欢笑的10分钟更重要。玩具明天还在那儿，别累坏自己。' WHERE id = '16c8c619-fdcd-4a82-a21a-ff965106a15f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'A dormir con música 🛀', body_es = '¿La rutina de la noche se ha complicado? Pon música relajante de fondo durante el baño templado. La armonía del agua y la melodía calma hasta al peque más testarudo.', title_fr = 'S''endormir en musique 🛀', body_fr = 'La routine du soir devient difficile ? Pendant le bain tiède, mettez une musique apaisante en fond. L''harmonie de l''eau et de la mélodie adoucit même l''enfant le plus têtu.', title_hi = 'संगीत के साथ नींद की ओर 🛀', body_hi = 'शाम का रूटीन मुश्किल हो गया है? गुनगुने स्नान के समय पीछे सुकून भरा संगीत चलाइए। पानी और धुन का मेल सबसे ज़िद्दी बच्चे को भी शांत कर देता है।', title_id = 'Menuju tidur dengan musik 🛀', body_id = 'Rutinitas malam makin sulit? Putar musik yang menenangkan saat mandi air hangat. Perpaduan air dan melodi bisa meluluhkan anak yang paling keras kepala sekalipun.', title_ja = '音楽でねんねへ 🛀', body_ja = '夜のルーティンが大変になってきた？ぬるめのお風呂の間、静かな音楽を流しましょう。お湯とメロディーのハーモニーは、どんなにがんこな子もやわらげてくれます。', title_ko = '음악과 함께 꿈나라로 🛀', body_ko = '저녁 루틴이 힘들어졌나요? 따뜻한 물로 목욕할 때 잔잔한 음악을 틀어 주세요. 물과 멜로디의 조화가 고집 센 아이도 부드럽게 풀어 줘요.', title_nl = 'Met muziek naar dromenland 🛀', body_nl = 'Is de avondroutine lastiger geworden? Zet tijdens het lauwe badje rustgevende muziek op de achtergrond aan. Water en melodie samen kalmeren zelfs het koppigste kind.', title_pl = 'Zasypianie przy muzyce 🛀', body_pl = 'Wieczorna rutyna stała się trudna? Podczas ciepłej kąpieli włącz w tle kojącą muzykę. Harmonia wody i melodii uspokaja nawet najbardziej upartego malucha.', title_pt = 'Adormecer com música 🛀', body_pt = 'A rotina da noite ficou difícil? Durante o banho morno, ponha música calmante em fundo. A harmonia entre a água e a melodia acalma até o bebé mais teimoso.', title_sv = 'Musikalisk övergång till sömnen 🛀', body_sv = 'Har kvällsrutinen blivit svårare? Sätt på lugnande musik i bakgrunden när barnet badar ljummet. Vattnets och melodins harmoni mjukar upp även det envisaste barn.', title_vi = 'Vào giấc cùng âm nhạc 🛀', body_vi = 'Nếp sinh hoạt buổi tối trở nên khó khăn? Khi tắm nước ấm cho bé, hãy mở nhạc êm dịu làm nền. Sự hòa quyện giữa nước và giai điệu sẽ làm dịu cả em bé bướng bỉnh nhất.', title_zh = '伴着音乐入睡 🛀', body_zh = '晚间作息变难了？洗温水澡时放点舒缓的背景音乐。水声和旋律的和谐，连最倔的宝宝也能被安抚。' WHERE id = '724d9097-f64c-406e-8895-2982258b710d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las crisis sin causa aparente agotan a cualquiera. 😭', body_es = 'Las crisis sin causa aparente agotan a cualquiera. Deja de adivinar: usa el Análisis del llanto y descubre al instante el mensaje oculto (dolor, cansancio) detrás de su llanto.', title_fr = 'Les crises sans cause apparente épuisent. 😭', body_fr = 'Les crises dont on ne trouve pas la cause épuisent. Arrêtez de deviner : utilisez l''Analyse des pleurs pour découvrir tout de suite le message caché (douleur, fatigue) derrière ses pleurs.', title_hi = 'जिन रोने के दौरों की वजह न मिले, वे थका देते हैं 😭', body_hi = 'जिन रोने के दौरों की वजह न मिले, वे थका देते हैं। अंदाज़ा लगाना छोड़िए, क्राइंग एनालिसिस से आवाज़ के पीछे छिपा संदेश (दर्द, थकान) तुरंत जानिए।', title_id = 'Tangisan yang tak diketahui sebabnya sungguh melelahkan. 😭', body_id = 'Tangisan yang tak diketahui sebabnya sungguh melelahkan. Berhenti menebak, gunakan Analisis Tangisan dan langsung temukan pesan tersembunyi di balik suaranya (sakit, lelah).', title_ja = '理由のわからないぐずりは本当に疲れます。😭', body_ja = '理由のわからないぐずりは本当に疲れます。推測するのはやめて、「泣き声分析」を使って、泣き声に隠れたメッセージ（痛み、疲れ）をすぐに見つけましょう。', title_ko = '이유를 알 수 없는 울음은 정말 지치게 해요. 😭', body_ko = '이유를 알 수 없는 울음은 정말 지치게 해요. 추측은 그만하고 울음 분석으로 울음 속에 숨은 메시지(통증, 피로)를 바로 알아보세요.', title_nl = 'Huilbuien zonder duidelijke oorzaak putten je uit. 😭', body_nl = 'Huilbuien zonder duidelijke oorzaak putten je uit. Stop met raden, gebruik Huilanalyse en ontdek meteen de verborgen boodschap in het huilen (pijn, vermoeidheid).', title_pl = 'Kryzysy bez znanej przyczyny wykańczają. 😭', body_pl = 'Kryzysy, których przyczyny nie umiesz znaleźć, wykańczają. Przestań zgadywać, skorzystaj z Analizy płaczu i od razu odkryj ukrytą wiadomość (ból, zmęczenie) w jego głosie.', title_pt = 'As crises sem causa aparente esgotam qualquer um. 😭', body_pt = 'As crises sem causa aparente esgotam qualquer um. Deixe de adivinhar: use a Análise do Choro e descubra logo a mensagem escondida no choro (dor, cansaço).', title_sv = 'Utbrott utan synbar orsak tar på krafterna. 😭', body_sv = 'Utbrott utan synbar orsak tar på krafterna. Sluta gissa, använd Gråtanalys och upptäck direkt det dolda budskapet (smärta, trötthet) bakom ljudet.', title_vi = 'Những cơn khóc không rõ lý do khiến mẹ kiệt sức. 😭', body_vi = 'Những cơn khóc không rõ lý do khiến mẹ kiệt sức. Đừng đoán nữa, hãy dùng Phân tích tiếng khóc để phát hiện ngay thông điệp ẩn sau tiếng khóc (đau, mệt).', title_zh = '找不到原因的哭闹最让人心力交瘁 😭', body_zh = '找不到原因的哭闹最让人心力交瘁。别再猜了，用哭声分析马上找出声音背后的隐藏信息（疼痛、疲倦）。' WHERE id = '12b2ddaa-17a1-4692-8574-725c962b0e1b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Las cuatro paredes te agobian. Ponle en el carrito y sal a tomar aire fresco aunque sean 20 minutos. La calma de la naturaleza os sentará genial a tu bebé y a ti.', body_fr = 'Vous étouffez entre quatre murs ? Installez-le dans sa poussette et sortez prendre l''air, ne serait-ce que 20 minutes. La sérénité de la nature fera du bien à bébé comme à votre moral.', body_hi = 'चार दीवारें घुटन दे रही हैं। उसे स्ट्रॉलर में बिठाइए और 20 मिनट के लिए ही सही, ताज़ी हवा में निकलिए। प्रकृति का सुकून बच्चे और आपके मन, दोनों पर बढ़िया असर करेगा।', body_id = 'Empat dinding terasa menyesakkan. Masukkan ia ke stroller dan keluarlah menghirup udara segar walau hanya 20 menit. Ketenangan alam baik untuk bayi dan juga untuk kesehatan mental Anda.', body_ja = '4つの壁に息がつまりそう。ベビーカーに乗せて、20分だけでも外の空気を吸いに出かけましょう。自然のやすらぎは、赤ちゃんにもあなたの心にもとてもいい効果があります。', body_ko = '네 벽이 답답하게 느껴지나요? 아기를 유모차에 태우고 20분이라도 바깥바람을 쐬어 보세요. 자연의 평온함이 아기에게도 엄마의 마음에도 큰 도움이 될 거예요.', body_nl = 'Je vier muren verstikken je. Leg je baby in de kinderwagen en ga naar buiten, al is het maar voor 20 minuten. De rust van de natuur doet je baby en jouw gemoed heel goed.', body_pl = 'Cztery ściany cię przytłaczają. Włóż go do wózka i wyjdź na świeże powietrze, choćby na 20 minut. Spokój natury świetnie wpłynie i na maluszka, i na twoją psychikę.', body_pt = 'As quatro paredes estão a sufocá-la. Ponha-o no carrinho e saia para apanhar ar fresco, nem que seja 20 minutos. A calma da natureza faz muito bem ao bebé e ao seu equilíbrio emocional.', body_sv = 'De fyra väggarna kväver dig. Lägg barnet i vagnen och gå ut i frisk luft, om så bara i 20 minuter. Naturens ro gör både barnet och ditt psyke väldigt gott.', body_vi = 'Bốn bức tường khiến mẹ ngột ngạt. Đặt bé vào xe đẩy và ra ngoài hít thở không khí trong lành, dù chỉ 20 phút. Sự bình yên của thiên nhiên sẽ rất tốt cho cả bé lẫn tâm trạng của mẹ.', body_zh = '四面墙让你喘不过气。把宝宝放进婴儿车，哪怕出去20分钟呼吸新鲜空气也好。大自然的宁静对宝宝和你的心情都很有好处。' WHERE id = '19b095ff-5334-4011-abd1-b8df6c79520c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dedo que señala ☝️', body_es = '¿Señala con el dedo algo lejano y te mira? Te está diciendo «mírame» o «quiero eso». ¡Es un gran salto en la comunicación! Dile el nombre del objeto.', title_fr = 'Le doigt qui montre ☝️', body_fr = 'Il montre du doigt un objet éloigné puis vous regarde ? Il vous dit « regarde » ou « je veux ça ». C''est un grand bond dans la communication ! Dites-lui le nom de l''objet.', title_hi = 'इशारा करती उँगली ☝️', body_hi = 'दूर की किसी चीज़ की ओर उँगली से इशारा करके आपको देखता है? वह कह रहा है ''मुझे देखो'' या ''मुझे यह चाहिए''। बातचीत में यह बड़ी छलांग है! उसे उस चीज़ का नाम बताइए।', title_id = 'Jari menunjuk ☝️', body_id = 'Ia menunjuk benda yang jauh dengan jarinya lalu menatap Anda? Ia sedang berkata, "Lihat aku" atau "Aku mau itu". Lompatan besar dalam komunikasi! Sebutkan nama bendanya.', title_ja = '指さし ☝️', body_ja = '遠くのものを指さして、あなたを見ていますか？「見て」「あれがほしい」と伝えているのです。コミュニケーションの大きな飛躍です！そのものの名前を教えてあげましょう。', title_ko = '손가락으로 가리키기 ☝️', body_ko = '멀리 있는 물건을 손가락으로 가리키고 엄마를 바라보나요? ''이것 봐요'' 또는 ''이거 갖고 싶어요''라고 말하는 거예요. 소통의 큰 도약이에요! 그 물건의 이름을 말해 주세요.', title_nl = 'De wijsvinger ☝️', body_nl = 'Wijst je baby met zijn vinger naar iets verderop en kijkt hij je aan? Hij zegt: kijk eens of dat wil ik. Een grote sprong in de communicatie! Noem de naam van het ding.', title_pl = 'Palec wskazujący ☝️', body_pl = 'Pokazuje palcem odległy przedmiot i patrzy na ciebie? Mówi ci: „popatrz na mnie” albo „chcę to”. To wielki skok w komunikacji! Nazwij mu ten przedmiot.', title_pt = 'O dedo que aponta ☝️', body_pt = 'Aponta com o dedo para um objeto ao longe e olha para si? Está a dizer-lhe "olha para mim" ou "quero isto". É um grande salto na comunicação! Diga-lhe o nome do objeto.', title_sv = 'Pekfingret ☝️', body_sv = 'Pekar barnet med fingret på något långt bort och tittar på dig? Det säger ''titta på mig'' eller ''jag vill ha den''. Ett stort språng i kommunikationen! Säg vad saken heter.', title_vi = 'Ngón tay chỉ trỏ ☝️', body_vi = 'Bé chỉ tay vào đồ vật ở xa rồi nhìn mẹ? Bé đang nói "Mẹ nhìn này" hoặc "Con muốn cái đó". Đây là bước nhảy lớn trong giao tiếp! Hãy nói cho bé biết tên đồ vật.', title_zh = '用手指指东西 ☝️', body_zh = '宝宝用手指指着远处的东西再看向你？宝宝在说“看我”或“我想要那个”。这是沟通上的一大飞跃！告诉宝宝那个东西叫什么吧。' WHERE id = 'b6194099-d4e6-4061-b3f2-d6bc5cce0529' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Nana de buenas noches 🎶', body_es = 'Ninguna app ni sonido puede sustituir la nana de una madre. Esta noche, simplemente abrázale contra tu pecho y cántale bajito su nana favorita, la que le da seguridad.', title_fr = 'Berceuse du soir 🎶', body_fr = 'Aucune application ni aucun son ne remplace la berceuse d''une maman. Ce soir, serrez-le simplement contre vous et chantez doucement sa berceuse préférée, celle qui le rassure.', title_hi = 'रात की लोरी 🎶', body_hi = 'कोई भी ऐप या आवाज़ माँ की लोरी की जगह नहीं ले सकती। आज शाम बस उसे सीने से लगाइए और धीरे से उसकी पसंदीदा, भरोसा देने वाली लोरी गाइए।', title_id = 'Nina bobo malam 🎶', body_id = 'Tidak ada aplikasi atau suara yang bisa menggantikan nina bobo ibu. Malam ini, cukup dekap ia di dada dan nyanyikan pelan lagu kesukaannya yang menenangkan.', title_ja = '夜の子守唄 🎶', body_ja = 'どんなアプリも音も、ママの子守唄にはかないません。今夜はただ胸に抱きよせて、お気に入りの安心できる子守唄をそっと歌ってあげましょう。', title_ko = '밤의 자장가 🎶', body_ko = '어떤 앱도, 어떤 소리도 엄마의 자장가를 대신할 수 없어요. 오늘 저녁은 아기를 가슴에 꼭 안고 가장 좋아하는 포근한 자장가를 나지막이 불러 주세요.', title_nl = 'Een slaapliedje voor de nacht 🎶', body_nl = 'Geen app of geluid kan het slaapliedje van een moeder vervangen. Houd je kleintje vanavond gewoon tegen je borst en zing zachtjes zijn lievelingsliedje dat hem vertrouwen geeft.', title_pl = 'Kołysanka na noc 🎶', body_pl = 'Żadna aplikacja ani dźwięk nie zastąpi kołysanki mamy. Dziś wieczorem po prostu przytul go do piersi i cichutko zaśpiewaj jego ulubioną, dającą poczucie bezpieczeństwa kołysankę.', title_pt = 'Canção de embalar da noite 🎶', body_pt = 'Nenhuma app ou som substitui a canção de embalar da mãe. Esta noite, aconchegue-o ao peito e cante baixinho a canção de embalar de que ele mais gosta e que lhe dá segurança.', title_sv = 'Vaggvisa för natten 🎶', body_sv = 'Ingen app och inget ljud kan ersätta mammas vaggvisa. I kväll, håll bara barnet tätt intill bröstet och sjung tyst den trygga vaggvisa barnet tycker mest om.', title_vi = 'Lời ru ban đêm 🎶', body_vi = 'Không ứng dụng hay âm thanh nào thay được lời ru của mẹ. Tối nay chỉ cần ôm bé vào lòng và khẽ hát bài ru bé thích nhất, cho bé cảm giác an toàn.', title_zh = '晚安摇篮曲 🎶', body_zh = '没有任何应用或声音能取代妈妈的摇篮曲。今晚就把宝宝抱在怀里，轻轻唱宝宝最爱、最安心的那首摇篮曲吧。' WHERE id = 'b78498d9-706c-458c-aa0f-d6081c7746c6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Equipo de palmas 👏', body_es = '¿Muestra su alegría dando palmas? En cuanto veas este gran logro motor, haz un pequeño baile de la victoria en casa ¡y únete a él!', title_fr = 'Bravo, on tape dans les mains 👏', body_fr = 'Il exprime sa joie en tapant des mains ? Dès que vous voyez cette superbe réussite motrice, faites une petite danse de la victoire à la maison et accompagnez-le !', title_hi = 'ताली बजाओ 👏', body_hi = 'अपनी खुशी ताली बजाकर जताता है? मोटर स्किल्स की यह शानदार उपलब्धि देखते ही घर में एक छोटा जीत का नाच कीजिए और उसके साथ ताली बजाइए!', title_id = 'Tim tepuk tangan 👏', body_id = 'Ia menunjukkan kegembiraannya dengan bertepuk tangan? Begitu melihat pencapaian motorik yang hebat ini, lakukan tarian kemenangan kecil di rumah dan ajak ia ikut!', title_ja = 'パチパチチーム 👏', body_ja = 'うれしいとき、手をパチパチたたいて伝えますか？このすばらしい運動の成長を見たら、おうちで小さな勝利のダンスをして一緒に楽しみましょう！', title_ko = '짝짝짝 박수 👏', body_ko = '손뼉을 치며 기쁨을 표현하나요? 이 멋진 운동 발달을 보는 순간 집에서 작은 승리의 춤을 추며 함께해 주세요!', title_nl = 'Het klapteam 👏', body_nl = 'Laat je baby zijn blijdschap zien door in zijn handjes te klappen? Doe zodra je deze geweldige motorische prestatie ziet een klein overwinningsdansje en doe mee!', title_pl = 'Klaszczemy! 👏', body_pl = 'Okazuje radość, klaszcząc w rączki? Gdy tylko zobaczysz to wspaniałe osiągnięcie motoryczne, zatańcz w domu mały taniec zwycięstwa i przyłącz się do niego!', title_pt = 'A equipa das palminhas 👏', body_pt = 'Mostra a alegria batendo palmas? Assim que vir esta conquista motora fantástica, faça uma pequena dança da vitória em casa e junte-se a ele!', title_sv = 'Klappa-händerna-laget 👏', body_sv = 'Visar barnet sin glädje genom att klappa händerna? Så fort du ser den här fantastiska motoriska bedriften, gör en liten segerdans hemma och dansa med!', title_vi = 'Đội vỗ tay 👏', body_vi = 'Bé vỗ tay để thể hiện niềm vui? Ngay khi thấy thành tựu vận động tuyệt vời này, hãy nhảy một điệu mừng chiến thắng nho nhỏ và cùng vỗ tay với bé!', title_zh = '拍拍手 👏', body_zh = '宝宝开心时会拍手？看到这项精彩的动作发展的那一刻，在家跳一段小小的胜利舞，和宝宝一起庆祝吧！' WHERE id = 'd08b308d-00d3-45c9-9840-df7ac1047703' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apoyo de equipo 🥂', title_fr = 'Le soutien de l''équipe 🥂', title_hi = 'टीम का साथ 🥂', title_id = 'Dukungan tim 🥂', title_ja = 'チームで支え合う 🥂', title_ko = '팀의 응원 🥂', title_nl = 'Steun als team 🥂', title_pl = 'Wsparcie drużyny 🥂', title_pt = 'Apoio de equipa 🥂', title_sv = 'Lagstöd 🥂', title_vi = 'Đồng đội hỗ trợ 🥂', title_zh = '团队支持 🥂' WHERE id = '546e217e-8060-4a89-877d-29e71165dae1' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lista no es opcional, es imprescindible 🛒', body_es = '¡Que no se olviden los adornos para la fiesta de los 8 meses! No te calientes la cabeza: apúntalo todo ya en la Lista de la compra y coordínate con tu pareja.', title_fr = 'La liste n''est pas une option, c''est indispensable 🛒', body_fr = 'N''oubliez pas les décorations pour la fête des 8 mois ! Ne vous fatiguez pas l''esprit : notez tout de suite tout dans la Liste de courses et coordonnez-vous avec votre conjoint.', title_hi = 'लिस्ट ज़रूरी है, विकल्प नहीं 🛒', body_hi = '8 महीने की पार्टी की सजावट भूलनी नहीं चाहिए! दिमाग मत थकाइए, सब कुछ तुरंत शॉपिंग लिस्ट में लिखिए और अपने साथी के साथ मिलकर काम कीजिए।', title_id = 'Daftar itu bukan pilihan, tapi keharusan 🛒', body_id = 'Jangan sampai dekorasi untuk pesta 8 bulan terlupa! Jangan bikin pusing, segera tulis semuanya di Daftar Belanja dan berkoordinasilah dengan pasangan.', title_ja = 'リストは必須アイテム 🛒', body_ja = '8か月パーティーの飾りつけを忘れないように！頭を疲れさせないで、すぐにぜんぶ「買い物リスト」に書いて、パートナーと連携しましょう。', title_ko = '목록은 선택이 아니라 필수예요 🛒', body_ko = '8개월 파티에 필요한 장식을 잊지 마세요! 머리 아프게 고민하지 말고 모든 걸 바로 쇼핑 목록에 적어 배우자와 손발을 맞추세요.', title_nl = 'Een lijstje is geen optie, maar een must 🛒', body_nl = 'Vergeet de versiering voor het 8-maandenfeestje niet! Breek je hoofd er niet over, zet alles meteen op je Boodschappenlijstje en stem het af met je partner.', title_pl = 'Lista to nie opcja, to konieczność 🛒', body_pl = 'Nie zapomnij o dekoracjach na imprezę z okazji 8 miesięcy! Nie męcz głowy, od razu wpisz wszystko na Listę zakupów i działaj w zgodzie z partnerem.', title_pt = 'A lista não é opcional, é obrigatória 🛒', body_pt = 'Não se esqueça das decorações para a festa dos 8 meses! Não canse a cabeça: escreva já tudo na Lista de Compras e coordene-se com o seu companheiro.', title_sv = 'Listan är inte ett val, den är ett måste 🛒', body_sv = 'Glöm inte dekorationerna till 8-månadersfesten! Belasta inte hjärnan, skriv genast upp allt i Inköpslistan och samordna med din partner.', title_vi = 'Danh sách không chỉ cần mà là bắt buộc 🛒', body_vi = 'Đừng quên đồ trang trí cho bữa tiệc 8 tháng! Đừng bắt não làm việc quá sức, hãy ghi ngay mọi thứ vào Danh sách mua sắm và phối hợp cùng bố.', title_zh = '清单不是可有可无，而是必不可少 🛒', body_zh = '别忘了8个月派对要用的装饰！别费脑筋，马上把一切写进购物清单，和伴侣配合好吧。' WHERE id = 'dd6cc7ba-db6f-403b-93e6-2447dbb967dc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Caras conocidas 🥰', body_es = '¿Has visto esa sonrisa enorme y especial cuando entras en la habitación? Os distingue a ti y a tu pareja de todos los demás. Su amor incondicional es la mayor motivación.', title_fr = 'Des visages familiers 🥰', body_fr = 'Avez-vous vu ce grand sourire spécial sur son visage quand vous entrez dans la pièce ? Il vous distingue, vous et votre conjoint, de tout le monde. Cet amour sans condition est la plus grande des motivations.', title_hi = 'जाने-पहचाने चेहरे 🥰', body_hi = 'कमरे में आने पर उसके चेहरे पर वह बड़ी, खास मुस्कान देखी? वह आपको और आपके साथी को सबसे अलग पहचानता है। उसका यह बेशर्त प्यार सबसे बड़ी प्रेरणा है।', title_id = 'Wajah-wajah yang dikenal 🥰', body_id = 'Lihat senyum lebar dan istimewa di wajahnya saat Anda masuk kamar? Ia membedakan Anda dan pasangan dari semua orang. Cintanya yang tulus ini adalah motivasi terbesar.', title_ja = 'よく知っている顔 🥰', body_ja = '部屋に入ったとき、赤ちゃんの顔に浮かぶあの特別な満面の笑みを見ましたか？あなたとパートナーをほかの誰とも区別しています。このまっすぐな愛が、いちばんの原動力です。', title_ko = '익숙한 얼굴 🥰', body_ko = '방에 들어갈 때 아기 얼굴에 피어나는 그 크고 특별한 미소를 보셨나요? 아기는 엄마와 아빠를 누구보다 알아봐요. 이 의심 없는 사랑이 가장 큰 힘이에요.', title_nl = 'Bekende gezichten 🥰', body_nl = 'Zag je die grote, speciale glimlach toen je de kamer binnenkwam? Jou en je partner herkent hij uit iedereen. Zijn onvoorwaardelijke liefde is de grootste motivatie.', title_pl = 'Znajome twarze 🥰', body_pl = 'Widziałaś ten wielki, wyjątkowy uśmiech na jego buzi, gdy wchodzisz do pokoju? Odróżnia ciebie i twojego partnera od wszystkich innych. Ta bezwarunkowa miłość to największa motywacja.', title_pt = 'Caras conhecidas 🥰', body_pt = 'Já reparou naquele sorriso grande e especial quando entra no quarto? Ele distingue a mãe e o pai de todos os outros. Este amor sem condições é a maior motivação.', title_sv = 'Bekanta ansikten 🥰', body_sv = 'Har du sett det stora, speciella leendet när du kommer in i rummet? Barnet skiljer dig och din partner från alla andra. Den villkorslösa kärleken är den största motivationen.', title_vi = 'Gương mặt thân quen 🥰', body_vi = 'Mẹ có thấy nụ cười thật tươi, thật đặc biệt trên gương mặt bé khi mẹ bước vào phòng? Bé phân biệt bố mẹ với mọi người. Tình yêu vô điều kiện ấy là động lực lớn nhất.', title_zh = '熟悉的面孔 🥰', body_zh = '你一进房间，看到宝宝脸上那个大大的、特别的笑容了吗？宝宝把你和伴侣与其他人区分开了。这份毫无保留的爱就是最大的动力。' WHERE id = '7227b833-2ecd-472c-a074-7273a66732d9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las caras graciosas de papá 🤡', body_es = 'La forma más rápida de hacer reír al bebé es que papá haga ruidos y muecas raras. Esta noche descansa en segundo plano escuchando esas carcajadas.', title_fr = 'Les grimaces de papa 🤡', body_fr = 'Le moyen le plus rapide de faire rire bébé, ce sont les bruits et grimaces bizarres de papa. Ce soir, écoutez ces joyeux éclats de rire et reposez-vous en coulisses.', title_hi = 'पापा के मज़ेदार चेहरे 🤡', body_hi = 'बच्चे को हँसाने का सबसे तेज़ तरीका है पापा की अजीब आवाज़ें और चेहरे। आज शाम उन खिलखिलाहटों की आवाज़ सुनते हुए पीछे बैठकर आराम कीजिए।', title_id = 'Wajah lucu ayah 🤡', body_id = 'Cara tercepat membuat bayi tertawa adalah suara dan ekspresi aneh dari ayah. Dengarkan gelak tawa riang malam ini sambil beristirahat dari jauh.', title_ja = 'パパのおもしろい顔 🤡', body_ja = '赤ちゃんを笑わせるいちばんの近道は、パパが変な声や顔をすることです。今夜は楽しい笑い声を聞きながら、少し離れてのんびりしましょう。', title_ko = '아빠의 웃긴 표정 🤡', body_ko = '아기를 웃게 하는 가장 빠른 방법은 아빠의 이상한 소리와 표정이에요. 오늘 저녁 즐거운 웃음소리를 들으며 뒤에서 쉬세요.', title_nl = 'Papa''s gekke bekken 🤡', body_nl = 'De snelste manier om je baby aan het lachen te krijgen: papa die rare geluiden en gekke bekken maakt. Luister vanavond naar die vrolijke schaterlachjes en rust op de achtergrond uit.', title_pl = 'Śmieszne miny taty 🤡', body_pl = 'Najszybszy sposób, by rozśmieszyć maluszka, to dziwne dźwięki i miny taty. Dziś wieczorem odpoczywaj w tle i słuchaj tych radosnych salw śmiechu.', title_pt = 'As caretas do pai 🤡', body_pt = 'A forma mais rápida de fazer o bebé rir é o pai fazer sons e caretas estranhas. Ouça as gargalhadas desta noite e descanse em segundo plano.', title_sv = 'Pappas roliga miner 🤡', body_sv = 'Det snabbaste sättet att få barnet att skratta är när pappa gör konstiga ljud och miner. Lyssna på kvällens glada skratt och vila i bakgrunden.', title_vi = 'Những gương mặt hài hước của bố 🤡', body_vi = 'Cách nhanh nhất để bé cười là bố tạo ra những âm thanh và biểu cảm kỳ lạ. Tối nay hãy lắng nghe những tràng cười giòn tan và nghỉ ngơi ở hậu trường.', title_zh = '爸爸的鬼脸 🤡', body_zh = '逗宝宝笑最快的办法，就是爸爸发出怪声、做鬼脸。今晚就在一旁休息，听着那些欢快的笑声吧。' WHERE id = '90341333-a47d-4dc8-b1bb-8fcf07c769b0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te pierdas en los foros 🤖', body_es = '¿Te preguntas «¿puedo darle esto?» sobre la alimentación complementaria? No busques durante horas: deja que Anacan AI responda a tus dudas como un pediatra digital en tu bolsillo.', title_fr = 'Ne vous perdez pas dans les forums 🤖', body_fr = 'Vous vous demandez pour la diversification : « Est-ce que je peux lui donner ça ? » Ne cherchez pas pendant des heures, laissez Anacan AI répondre à vos questions comme un pédiatre numérique dans votre poche.', title_hi = 'फ़ोरम में मत खोइए 🤖', body_hi = 'ऊपरी आहार को लेकर ''क्या यह देना ठीक है?'' जैसा शक है? घंटों खोजने की ज़रूरत नहीं, Anacan AI आपकी जेब में डिजिटल बाल रोग विशेषज्ञ की तरह आपके सवालों के जवाब देगा।', title_id = 'Jangan tersesat di forum 🤖', body_id = 'Ragu, "Bolehkah ini diberikan?" soal MPASI? Jangan mencari berjam-jam, biar Anacan AI menjawab pertanyaan Anda seperti dokter anak digital di saku Anda.', title_ja = '掲示板で迷子にならないで 🤖', body_ja = '離乳食で「これをあげても大丈夫？」と迷っていますか？何時間も調べないで、ポケットの中のデジタル小児科医のように、Anacan AIに質問に答えてもらいましょう。', title_ko = '커뮤니티 글 속에서 헤매지 마세요 🤖', body_ko = '이유식을 하며 ''이걸 줘도 될까?'' 하고 고민되나요? 몇 시간씩 검색하지 말고 주머니 속 디지털 소아과 의사처럼 Anacan AI가 질문에 답하게 하세요.', title_nl = 'Verdwaal niet op forums 🤖', body_nl = 'Twijfel je bij bijvoeding: mag ik dit geven? Zoek niet urenlang, maar laat Anacan AI je vragen beantwoorden als een digitale kinderarts in je broekzak.', title_pl = 'Nie gub się na forach 🤖', body_pl = 'Masz wątpliwości przy rozszerzaniu diety, typu „czy mogę mu to dać?”. Nie szukaj godzinami, niech Anacan AI odpowiada na twoje pytania jak cyfrowy pediatra w kieszeni.', title_pt = 'Não se perca nos fóruns 🤖', body_pt = 'Tem dúvidas como "posso dar-lhe isto?" na diversificação alimentar? Não passe horas a pesquisar: deixe o Anacan AI responder às suas perguntas como um pediatra digital no bolso.', title_sv = 'Gå inte vilse i forumen 🤖', body_sv = 'Är du osäker på smakportionerna och undrar om du kan ge det här? Sök inte i timmar, låt Anacan AI svara på dina frågor som en digital barnläkare i fickan.', title_vi = 'Đừng lạc giữa diễn đàn 🤖', body_vi = 'Mẹ băn khoăn "Có cho bé ăn món này được không?" khi ăn dặm? Đừng tìm kiếm hàng giờ, hãy để Anacan AI trả lời như một bác sĩ nhi khoa kỹ thuật số trong túi của mẹ.', title_zh = '别在论坛里迷路 🤖', body_zh = '关于辅食，心里犯嘀咕“这个能给宝宝吃吗？”别花几个小时去搜，让Anacan AI像口袋里的数字儿科医生一样回答你的问题。' WHERE id = 'd4f1084b-2a25-422f-954c-038d4cf53bd2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un sitio para mamá ☕', body_es = '¿Estar en casa te ha dejado sin energía? En Lugares para mamás elige una cafetería tranquila donde puedas sentarte cómodamente con el carrito y regálate una pequeña cita.', title_fr = 'Un lieu pour maman ☕', body_fr = 'Rester à la maison vous a vidée de votre énergie ? Dans les Lieux adaptés aux mamans, choisissez un café calme où vous installer facilement avec la poussette et offrez-vous un petit rendez-vous.', title_hi = 'माँ के लिए जगह ☕', body_hi = 'घर में रहकर ऊर्जा खत्म हो गई? माँ के अनुकूल जगहों में से कोई शांत कैफ़े चुनिए जहाँ स्ट्रॉलर के साथ आराम से बैठ सकें, और खुद के लिए एक छोटी सी डेट प्लान कीजिए।', title_id = 'Tempat untuk Bunda ☕', body_id = 'Energi habis karena terus di rumah? Pilih kafe yang tenang dari Tempat Ramah Ibu, di mana Anda bisa duduk nyaman dengan stroller, dan buat kencan kecil untuk diri sendiri.', title_ja = 'ママのための場所 ☕', body_ja = '家にいてばかりで元気がなくなった？「ママにやさしいスポット」から、ベビーカーでゆったり座れる静かなカフェを選んで、自分にちょっとしたデートをプレゼントしましょう。', title_ko = '엄마를 위한 공간 ☕', body_ko = '집에만 있어 기운이 다 빠졌나요? 엄마 친화 장소에서 유모차와 함께 편히 앉을 수 있는 조용한 카페를 골라 나만의 작은 데이트를 즐겨 보세요.', title_nl = 'Een plek voor mama ☕', body_nl = 'Is je energie op van het thuiszitten? Kies in Mamavriendelijke plekken een rustig café waar je makkelijk met de kinderwagen kunt zitten en plan een kleine date met jezelf.', title_pl = 'Miejsce dla mamy ☕', body_pl = 'Siedzenie w domu odebrało ci energię? Wybierz w Miejscach przyjaznych mamom cichą kawiarnię, w której wygodnie usiądziesz z wózkiem, i zorganizuj sobie małą randkę.', title_pt = 'Um lugar para a mãe ☕', body_pt = 'Ficar em casa esgotou-lhe a energia? Escolha nos Locais Amigos das Mães um café tranquilo onde se sente à vontade com o carrinho e marque um pequeno encontro consigo própria.', title_sv = 'En plats för mamma ☕', body_sv = 'Har energin tagit slut av att vara hemma? Välj ett lugnt kafé bland Mammavänliga platser där du kan sitta bekvämt med barnvagnen och ordna en liten dejt med dig själv.', title_vi = 'Không gian cho mẹ ☕', body_vi = 'Ở nhà mãi khiến mẹ cạn năng lượng? Hãy chọn một quán cà phê yên tĩnh, có thể ngồi thoải mái với xe đẩy trong mục Địa điểm thân thiện với mẹ và tự tổ chức cho mình một buổi hẹn nho nhỏ.', title_zh = '妈妈的空间 ☕', body_zh = '一直待在家里，精力都耗光了？在妈妈友好场所里挑一家能推婴儿车进去、安安静静的咖啡馆，给自己安排一次小约会吧。' WHERE id = '11c30298-2c39-4c7f-bfc1-dcf22c8e2ebc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorando la papelera 🗑️', body_es = 'Todo lo que encuentra en el suelo o en el borde de la alfombra lo examina con enorme curiosidad. No te enfades quitándoselo todo, es un explorador. Solo vigila los objetos que pueda tragarse.', title_fr = 'Exploration de la poubelle 🗑️', body_fr = 'Tout ce qu''il trouve par terre ou au bord du tapis, il l''examine avec grand intérêt. Ne vous énervez pas à tout lui retirer des mains, c''est un explorateur. Faites simplement attention aux objets qu''il pourrait avaler.', title_hi = 'कूड़ेदान की खोजबीन 🗑️', body_hi = 'फ़र्श पर या कालीन के किनारे जो भी मिले, उसे बड़े ध्यान से परखता है। हर चीज़ उसके हाथ से छीनकर गुस्सा मत होइए, वह एक खोजी है। बस निगली जा सकने वाली चीज़ों से सावधान रहिए।', title_id = 'Penjelajah tempat sampah 🗑️', body_id = 'Apa pun yang ia temukan di lantai atau di tepi karpet, ia teliti dengan penuh rasa ingin tahu. Jangan kesal dan merebut semuanya, ia seorang penjelajah. Cukup waspadai benda yang bisa tertelan.', title_ja = 'ゴミ箱探検 🗑️', body_ja = '床やじゅうたんのはしで見つけたものを、興味しんしんで調べています。イライラしてぜんぶ取り上げないで、赤ちゃんは探検家なのです。飲みこめるものにだけ気をつけましょう。', title_ko = '쓰레기통 탐험 🗑️', body_ko = '바닥이나 카펫 가장자리에서 찾은 건 무엇이든 큰 호기심으로 살펴봐요. 모든 걸 빼앗으며 화내지 마세요, 아기는 탐험가니까요. 삼킬 수 있는 물건만 조심해 주세요.', title_nl = 'Speurtocht door de rommel 🗑️', body_nl = 'Alles wat je baby op de vloer of aan de rand van het kleed vindt, bekijkt hij vol nieuwsgierigheid. Pak niet alles af en word niet boos, hij is een ontdekkingsreiziger. Let alleen op dingen die hij kan inslikken.', title_pl = 'Odkrywca śmieci 🗑️', body_pl = 'Wszystko, co znajdzie na podłodze czy na brzegu dywanu, ogląda z wielką ciekawością. Nie denerwuj się i nie zabieraj mu wszystkiego, jest odkrywcą. Uważaj tylko na przedmioty, które mógłby połknąć.', title_pt = 'Exploração do caixote do lixo 🗑️', body_pt = 'Tudo o que encontra no chão ou na beira do tapete, examina com enorme curiosidade. Não se irrite a tirar-lhe tudo das mãos, ele é um explorador. Tenha apenas cuidado com objetos que possam ser engolidos.', title_sv = 'Upptäcktsfärd i papperskorgen 🗑️', body_sv = 'Vad barnet än hittar på golvet eller vid mattkanten undersöker det med stort intresse. Ta inte allt ifrån det och bli inte irriterad, det är en upptäcktsresande. Var bara uppmärksam på saker som kan sväljas.', title_vi = 'Khám phá thùng rác 🗑️', body_vi = 'Tìm thấy gì trên sàn hay mép thảm, bé cũng xem xét đầy hứng thú. Đừng bực mình giật mọi thứ khỏi tay bé, bé là một nhà thám hiểm. Chỉ cần cẩn thận với những vật có thể nuốt phải.', title_zh = '探索垃圾桶 🗑️', body_zh = '在地上、地毯边找到什么，宝宝都会饶有兴趣地研究。别生气地把东西全抢走，宝宝是个小探险家。只要留意能被吞下去的东西就好。' WHERE id = '66c8660e-b8ca-4046-9e3f-578e25572ec7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hoy en Cuentos inteligentes 🪄', body_es = 'Crea en Cuentos inteligentes la historia del gran héroe que dentro de unos días cumplirá 8 meses. Que solo este cuento mágico llene el silencio de la noche.', title_fr = 'Aujourd''hui dans les Contes intelligents 🪄', body_fr = 'Dans les Contes intelligents, créez l''histoire du grand héros qui aura 8 mois dans quelques jours. Que seule cette histoire magique remplisse le silence de la nuit.', title_hi = 'आज स्मार्ट कहानियों में 🪄', body_hi = 'स्मार्ट कहानियों में उस बड़े हीरो की कहानी बनाइए जो कुछ ही दिनों में 8 महीने का होने वाला है। रात की खामोशी को बस यही जादुई कहानी भरे।', title_id = 'Hari ini di Dongeng Pintar 🪄', body_id = 'Di Dongeng Pintar, buat kisah pahlawan besar yang beberapa hari lagi akan berusia 8 bulan. Biarkan hanya kisah ajaib ini yang mengisi keheningan malam.', title_ja = '今日の「スマートおはなし」🪄', body_ja = '「スマートおはなし」で、あと数日で生後8か月になる大きなヒーローのお話をつくりましょう。夜の静けさを、この魔法のお話だけで満たしましょう。', title_ko = '오늘의 스마트 동화 🪄', body_ko = '스마트 동화에서 며칠 뒤면 8개월이 되는 멋진 주인공의 이야기를 만들어 보세요. 밤의 고요를 이 마법 같은 이야기로만 채워 주세요.', title_nl = 'Vandaag in Slimme sprookjes 🪄', body_nl = 'Maak in Slimme sprookjes het verhaal van een grote held die over een paar dagen 8 maanden wordt. Laat alleen dit magische verhaal de stilte van de nacht vullen.', title_pl = 'Dziś w Mądrych bajkach 🪄', body_pl = 'Stwórz w Mądrych bajkach historię o wielkim bohaterze, który za kilka dni skończy 8 miesięcy. Niech tylko ta magiczna opowieść wypełni nocną ciszę.', title_pt = 'Hoje nas Histórias Inteligentes 🪄', body_pt = 'Crie nas Histórias Inteligentes a história do grande herói que daqui a poucos dias faz 8 meses. Que só esta história mágica encha o silêncio da noite.', title_sv = 'I dag i Smarta sagor 🪄', body_sv = 'Skapa sagan om den stora hjälten som fyller 8 månader om bara några dagar i Smarta sagor. Låt bara den här magiska sagan fylla nattens tystnad.', title_vi = 'Hôm nay trong Truyện cổ tích thông minh 🪄', body_vi = 'Hãy tạo trong Truyện cổ tích thông minh câu chuyện về người hùng lớn sẽ tròn 8 tháng chỉ sau vài ngày nữa. Hãy để câu chuyện kỳ diệu này lấp đầy sự tĩnh lặng của màn đêm.', title_zh = '今天的智能故事 🪄', body_zh = '在智能故事里创作一个再过几天就满8个月的小英雄的故事。让这个神奇的故事填满夜晚的宁静吧。' WHERE id = '8d417480-194b-431c-987a-b0b5216ea151' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Silencio y café 🤫', body_es = '¡Se ha dormido! En vez de vaciar la lavadora, siéntate en la penumbra de la habitación. Activa el Medidor de sonido para controlar el ambiente y aprecia 15 minutos de silencio.', title_fr = 'Silence et café 🤫', body_fr = 'Il dort ! Au lieu de vider la machine à laver, asseyez-vous dans la pénombre de la pièce. Activez le Sonomètre pour garder l''ambiance sous contrôle et savourez 15 minutes de silence.', title_hi = 'खामोशी और कॉफ़ी 🤫', body_hi = 'वह सो गया! अब वॉशिंग मशीन खाली करने के बजाय कमरे के अँधेरे में बैठिए। साउंड मीटर चालू करके माहौल पर नज़र रखिए और 15 मिनट की खामोशी की कद्र कीजिए।', title_id = 'Hening dan kopi 🤫', body_id = 'Ia sudah tidur! Daripada mengosongkan mesin cuci, duduklah di kamar yang gelap. Aktifkan Pengukur Suara untuk mengontrol suasana dan nikmati keheningan selama 15 menit.', title_ja = '静けさとコーヒー 🤫', body_ja = '寝てくれた！洗濯機を片づける代わりに、部屋の暗がりで座りましょう。「サウンドメーター」をオンにして環境をチェックし、15分間の静けさを大切に味わいましょう。', title_ko = '고요와 커피 🤫', body_ko = '아기가 잠들었어요! 이제 세탁기를 비우는 대신 방의 어둠 속에 앉아 보세요. 소음 측정기를 켜서 환경을 살피고 15분의 고요를 소중히 누리세요.', title_nl = 'Stilte en koffie 🤫', body_nl = 'Je baby slaapt! Ga in plaats van de wasmachine leeg te halen in de donkere kamer zitten. Zet de Geluidsmeter aan, houd de omgeving in de gaten en geniet 15 minuten van de stilte.', title_pl = 'Cisza i kawa 🤫', body_pl = 'Zasnął! Zamiast rozładowywać pralkę, usiądź w ciemnym pokoju. Włącz Miernik dźwięku, miej otoczenie pod kontrolą i doceń 15 minut ciszy.', title_pt = 'Silêncio e café 🤫', body_pt = 'Adormeceu! Agora, em vez de esvaziar a máquina da roupa, sente-se na penumbra do quarto. Ative o Medidor de Som, controle o ambiente e aproveite o valor de 15 minutos de silêncio.', title_sv = 'Tystnad och kaffe 🤫', body_sv = 'Barnet sover! I stället för att tömma tvättmaskinen, sätt dig i rummets mörker. Aktivera Ljudmätaren, håll koll på miljön och njut av värdet i 15 minuters tystnad.', title_vi = 'Tĩnh lặng và cà phê 🤫', body_vi = 'Bé ngủ rồi! Thay vì dọn máy giặt, hãy ngồi xuống trong bóng tối của căn phòng. Bật Đo âm thanh để kiểm soát môi trường và trân trọng 15 phút tĩnh lặng.', title_zh = '宁静与咖啡 🤫', body_zh = '宝宝睡着了！别急着清空洗衣机，在昏暗的房间里坐一会儿。打开噪音测量，掌控好环境，好好珍惜这15分钟的宁静吧。' WHERE id = '7a0d5b5d-2b7e-42a8-a73b-a50ead526d05' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La perfección no existe 🛑', body_es = '¿Hoy nada ha salido según lo previsto? No te culpes. Eres una madre real, no una ilusión con filtro de las redes sociales. Tu peque solo te necesita a ti.', title_fr = 'La perfection n''existe pas 🛑', body_fr = 'Rien ne s''est passé comme prévu aujourd''hui ? Ne vous culpabilisez pas. Vous êtes une vraie maman, pas une illusion filtrée des réseaux sociaux. Votre enfant n''a besoin que de vous.', title_hi = 'परफ़ेक्ट कोई नहीं 🛑', body_hi = 'आज कुछ भी योजना के मुताबिक नहीं हुआ? खुद को दोष मत दीजिए। आप एक असली माँ हैं, सोशल मीडिया का फ़िल्टर किया हुआ भ्रम नहीं। आपके बच्चे को बस आपकी ज़रूरत है।', title_id = 'Tidak ada yang sempurna 🛑', body_id = 'Hari ini tidak ada yang sesuai rencana? Jangan menyalahkan diri. Anda ibu yang nyata, bukan ilusi berfilter di media sosial. Anak Anda hanya membutuhkan Anda.', title_ja = '完璧なんてない 🛑', body_ja = '今日は何ひとつ計画どおりにいかなかった？自分を責めないで。あなたはリアルなママで、SNSのフィルター越しの幻ではありません。赤ちゃんに必要なのは、あなただけです。', title_ko = '완벽함은 없어요 🛑', body_ko = '오늘 아무것도 계획대로 되지 않았나요? 자책하지 마세요. 당신은 SNS 속 필터 씌운 환상이 아니라 진짜 엄마예요. 아이에게 필요한 건 오직 당신이에요.', title_nl = 'Perfectie bestaat niet 🛑', body_nl = 'Ging vandaag niets volgens plan? Geef jezelf niet de schuld. Je bent een echte moeder, geen gefilterde illusie van sociale media. Je kindje heeft alleen jou nodig.', title_pl = 'Nie ma ideałów 🛑', body_pl = 'Dziś nic nie poszło zgodnie z planem? Nie obwiniaj się. Jesteś prawdziwą mamą, a nie przefiltrowaną iluzją z mediów społecznościowych. Twoje dziecko potrzebuje tylko ciebie.', title_pt = 'A perfeição não existe 🛑', body_pt = 'Hoje nada correu como planeado? Não se culpe. É uma mãe real, não uma ilusão filtrada das redes sociais. O bebé só precisa de si.', title_sv = 'Ingen är perfekt 🛑', body_sv = 'Gick ingenting enligt planen i dag? Skyll inte på dig själv. Du är en riktig mamma, inte en filtrerad illusion på sociala medier. Barnet behöver bara dig.', title_vi = 'Không có gì hoàn hảo 🛑', body_vi = 'Hôm nay không gì diễn ra theo kế hoạch? Đừng tự trách mình. Mẹ là một người mẹ thật, không phải ảo ảnh qua bộ lọc trên mạng xã hội. Bé chỉ cần mẹ thôi.', title_zh = '没有完美 🛑', body_zh = '今天什么都没按计划进行？别责怪自己。你是一个真实的妈妈，不是社交媒体上加了滤镜的幻象。宝宝只需要你。' WHERE id = 'f72fbb7e-431d-4f4b-9a73-06637ff7bd68' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Suelta la carga emocional 📝', body_es = '¿Ha sido un día difícil? Desahógate escribiendo en el Diario de ánimo todo el estrés de hoy. Todas las madres pasan por estas crisis, no estás sola en absoluto.', title_fr = 'Déposez la charge émotionnelle 📝', body_fr = 'La journée a été difficile ? Videz votre cœur en écrivant tout le stress du jour dans le Journal d''humeur. Toutes les mamans vivent ces crises, vous n''êtes jamais seule.', title_hi = 'भावनाओं का बोझ उतारिए 📝', body_hi = 'मुश्किल दिन था? आज का सारा तनाव मूड डायरी में लिखकर मन हल्का कीजिए। सभी माँएँ ऐसे दौर से गुज़रती हैं, आप बिल्कुल अकेली नहीं हैं।', title_id = 'Lepaskan beban perasaan 📝', body_id = 'Hari yang berat? Tumpahkan semua stres hari ini di Buku Harian Suasana Hati. Semua ibu mengalami masa sulit ini, Anda sama sekali tidak sendirian.', title_ja = '心の荷物をおろそう 📝', body_ja = '大変な1日でしたか？「気分日記」に今日のストレスをぜんぶ書いて吐き出しましょう。どのママもこんな時期を経験しています。あなたは決してひとりではありません。', title_ko = '마음의 짐을 내려놓아요 📝', body_ko = '힘든 하루였나요? 기분 일기에 오늘의 스트레스를 모두 적으며 마음을 비워 보세요. 모든 엄마가 이런 고비를 겪어요, 결코 혼자가 아니에요.', title_nl = 'Gooi de emotionele last eruit 📝', body_nl = 'Was het een zware dag? Schrijf alle stress van vandaag op in je Stemmingsdagboek en lucht je hart. Alle moeders maken zulke crisissen mee, je bent nooit alleen.', title_pl = 'Zrzuć emocjonalny ciężar 📝', body_pl = 'Trudny dzień? Wyrzuć z siebie cały dzisiejszy stres, zapisując go w Dzienniku nastroju. Wszystkie mamy przeżywają takie kryzysy, nigdy nie jesteś sama.', title_pt = 'Largue o peso emocional 📝', body_pt = 'Foi um dia difícil? Desabafe escrevendo no Diário de Humor todo o stress de hoje. Todas as mães passam por estas crises, nunca está sozinha.', title_sv = 'Släpp den känslomässiga bördan 📝', body_sv = 'Har det varit en tuff dag? Lätta på hjärtat genom att skriva ner all dagens stress i Humördagboken. Alla mammor går igenom sådana kriser, du är aldrig ensam.', title_vi = 'Trút bỏ gánh nặng cảm xúc 📝', body_vi = 'Hôm nay là một ngày vất vả? Hãy trút hết căng thẳng hôm nay vào Nhật ký tâm trạng. Bà mẹ nào cũng trải qua những lúc thế này, mẹ không hề đơn độc.', title_zh = '卸下情绪的包袱 📝', body_zh = '今天很辛苦吗？把今天所有的压力都写进心情日记，释放出来吧。每个妈妈都会经历这样的时刻，你绝不是一个人。' WHERE id = '61ffa498-18cc-4858-987c-676f525f467c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mi juguete no lo doy! 🧸', body_es = '¿Protesta y llora a gritos cuando le quitas algo de las manos? Se desarrolla su sentido de la propiedad y de la individualidad. Es una etapa psicológica muy natural, no luches contra ella.', title_fr = 'Je ne donne pas mon jouet ! 🧸', body_fr = 'Il proteste et pleure fort quand vous lui prenez quelque chose des mains ? Son sens de la propriété et de l''individualité se développe. C''est une étape psychologique très naturelle, ne luttez pas.', title_hi = 'अपना खिलौना नहीं दूँगा! 🧸', body_hi = 'उसके हाथ से कुछ लेने पर वह विरोध करता है और ज़ोर से रोता है? उसमें ''मेरा'' और अपनी पहचान का एहसास विकसित हो रहा है। यह बहुत स्वाभाविक मानसिक दौर है, इससे लड़िए मत।', title_id = 'Mainanku tidak akan kuberikan! 🧸', body_id = 'Ia protes dan menangis keras saat Anda mengambil sesuatu dari tangannya? Rasa memiliki dan kepribadiannya sedang berkembang. Ini tahap psikologis yang sangat wajar, jangan dilawan.', title_ja = 'おもちゃは渡さない！🧸', body_ja = '手から何かを取り上げると、怒って大声で泣きますか？「自分のもの」という感覚と個性が育っています。とても自然な心の成長の段階なので、張り合わないで。', title_ko = '내 장난감은 안 줄래요! 🧸', body_ko = '손에서 무언가를 빼면 항의하며 크게 우나요? 소유와 자아 개념이 자라고 있어요. 아주 자연스러운 심리 발달 단계이니 맞서 싸우지 마세요.', title_nl = 'Mijn speeltje geef ik niet af! 🧸', body_nl = 'Protesteert je baby en huilt hij hard als je iets uit zijn handjes pakt? Het gevoel van bezit en eigenheid ontwikkelt zich. Dit is een heel normale psychologische fase, vecht er niet tegen.', title_pl = 'Nie oddam zabawki! 🧸', body_pl = 'Protestuje i głośno płacze, gdy coś mu zabierasz? Rozwija się poczucie własności i odrębności. To bardzo naturalny etap psychologiczny, nie walcz z nim.', title_pt = 'Não dou o meu brinquedo! 🧸', body_pt = 'Protesta e chora alto quando lhe tira alguma coisa das mãos? O sentido de posse e de individualidade está a desenvolver-se. É uma fase psicológica muito natural, não lute contra ela.', title_sv = 'Jag ger inte bort min leksak! 🧸', body_sv = 'Protesterar barnet och gråter högt när du tar något ifrån det? Känslan för ägande och den egna personen utvecklas. Det är en helt naturlig psykologisk fas, kämpa inte emot.', title_vi = 'Con không đưa đồ chơi đâu! 🧸', body_vi = 'Bé phản đối và khóc to khi mẹ lấy thứ gì đó khỏi tay? Ý thức về sở hữu và cái tôi của bé đang phát triển. Đây là giai đoạn tâm lý rất tự nhiên, đừng đối đầu với bé.', title_zh = '我的玩具不给你！🧸', body_zh = '从宝宝手里拿走东西时，宝宝会反抗、大哭？宝宝的物权意识和自我意识正在发展。这是非常自然的心理阶段，别和宝宝较劲。' WHERE id = 'c82d9568-ae94-4492-9789-4621c2dbcabc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mamá sana, bebé sano 🥑', body_es = 'Tus reservas de hierro y calcio se han agotado. Prepara con Recetas saludables un plato rápido y lleno de energía que te mantenga en pie, y date un premio.', title_fr = 'Maman en forme, bébé en forme 🥑', body_fr = 'Vos réserves de fer et de calcium sont épuisées. Préparez avec les Recettes saines un plat rapide et plein d''énergie qui vous tiendra debout, et faites-vous plaisir.', title_hi = 'सेहतमंद माँ, सेहतमंद बच्चा 🥑', body_hi = 'आपके शरीर में आयरन और कैल्शियम का भंडार खत्म हो गया है। सेहतमंद रेसिपी से जल्दी बनने वाला और आपको ताकत देने वाला ऊर्जा भरा खाना बनाइए और खुद को इनाम दीजिए।', title_id = 'Ibu sehat, bayi sehat 🥑', body_id = 'Cadangan zat besi dan kalsium Anda terkuras. Hadiahi diri Anda dengan memasak hidangan penuh energi dari Resep Sehat yang cepat dibuat dan membuat Anda tetap bertenaga.', title_ja = '元気なママ、元気な赤ちゃん 🥑', body_ja = '鉄分とカルシウムの蓄えが減っています。「ヘルシーレシピ」から、手早くできて元気を保てるエネルギーたっぷりの食事をつくって、自分にごほうびをあげましょう。', title_ko = '건강한 엄마, 건강한 아기 🥑', body_ko = '철분과 칼슘이 바닥났어요. 건강한 레시피에서 빨리 만들 수 있고 든든하게 버티게 해 줄 에너지 가득한 요리를 만들어 나에게 선물하세요.', title_nl = 'Gezonde mama, gezonde baby 🥑', body_nl = 'Je ijzer- en calciumvoorraad is op. Maak uit Gezonde recepten een snel, energierijk gerecht dat je op de been houdt en beloon jezelf.', title_pl = 'Zdrowa mama, zdrowy maluszek 🥑', body_pl = 'Twoje zapasy żelaza i wapnia się wyczerpały. Przygotuj ze Zdrowych przepisów szybki, pełen energii posiłek, który postawi cię na nogi, i nagródź się.', title_pt = 'Mãe saudável, bebé saudável 🥑', body_pt = 'As suas reservas de ferro e cálcio esgotaram-se. Prepare nas Receitas Saudáveis uma refeição rápida e cheia de energia que a mantenha de pé e recompense-se.', title_sv = 'Frisk mamma, friskt barn 🥑', body_sv = 'Dina järn- och kalciumförråd har tömts. Belöna dig själv med en energirik rätt från Hälsosamma recept som både går snabbt att laga och håller dig på benen.', title_vi = 'Mẹ khỏe, bé khỏe 🥑', body_vi = 'Dự trữ sắt và canxi của mẹ đã cạn. Hãy tự thưởng cho mình một món ăn giàu năng lượng, làm nhanh mà giúp mẹ khỏe khoắn từ Công thức lành mạnh.', title_zh = '妈妈健康，宝宝健康 🥑', body_zh = '你体内的铁和钙储备快耗尽了。从健康食谱里做一顿快手又能让你撑住的能量餐，犒劳一下自己吧。' WHERE id = 'bc11c415-3d46-43c3-a8ed-0a204516e9ce' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeña mente que pasa páginas 📖', body_es = '¿Pasa solo las páginas de los libros de cartón y reacciona a los dibujos? Su memoria visual funciona genial. Leed juntos y dile el nombre de los animales de los dibujos.', title_fr = 'Un petit esprit qui feuillette les livres 📖', body_fr = 'Il tourne seul les pages cartonnées des livres et réagit aux images ? Sa mémoire visuelle fonctionne très bien. Lisez avec lui et nommez les animaux des images.', title_hi = 'किताबों के पन्ने पलटती समझ 📖', body_hi = 'मोटे पन्नों वाली किताबों के पन्ने खुद पलटता है और तस्वीरों पर प्रतिक्रिया देता है? उसकी देखी चीज़ें याद रखने की क्षमता बढ़िया है। साथ में पढ़िए और तस्वीरों में जानवरों के नाम बताइए।', title_id = 'Si cerdas pembalik halaman 📖', body_id = 'Ia membalik halaman buku bergambar tebal dengan lancar dan bereaksi pada gambarnya? Memori visualnya bekerja dengan baik. Bacalah bersamanya dan sebutkan nama hewan di gambar.', title_ja = '絵本をめくる小さな知性 📖', body_ja = '厚紙の絵本のページを自分でめくって、絵に反応していますか？目で見て覚える力がよく育っています。一緒に読んで、絵の中の動物の名前を言ってあげましょう。', title_ko = '책장을 넘기는 꼬마 박사 📖', body_ko = '두꺼운 책장을 혼자 넘기며 그림에 반응하나요? 시각 기억력이 아주 좋아요. 함께 읽으며 그림 속 동물의 이름을 말해 주세요.', title_nl = 'Een slimmerik die bladzijden omslaat 📖', body_nl = 'Slaat je baby zelf de dikke bladzijden van een boekje om en reageert hij op de plaatjes? Zijn visuele geheugen werkt geweldig. Lees samen en noem de namen van de dieren op de plaatjes.', title_pl = 'Mądrala przewracający kartki 📖', body_pl = 'Samodzielnie przewraca grube kartki książeczek i reaguje na obrazki? Pamięć wzrokowa świetnie działa. Czytajcie razem i nazywaj zwierzątka na obrazkach.', title_pt = 'Uma mente que folheia livros 📖', body_pt = 'Vira sozinho as páginas dos livros de cartão e reage às imagens? A memória visual funciona muito bem. Leia com ele e diga o nome dos animais das imagens.', title_sv = 'Ett klokt huvud som bläddrar i böcker 📖', body_sv = 'Vänder barnet själv sidorna i böcker med tjocka blad och reagerar på bilderna? Det visuella minnet fungerar utmärkt. Läs tillsammans och säg vad djuren på bilderna heter.', title_vi = 'Trí thông minh lật sách 📖', body_vi = 'Bé tự lật trang sách bìa cứng và phản ứng với hình ảnh? Trí nhớ hình ảnh của bé hoạt động rất tốt. Hãy cùng bé đọc sách và gọi tên các con vật trong tranh.', title_zh = '翻书的小脑瓜 📖', body_zh = '宝宝能自己翻厚纸板书，还会对图片有反应？视觉记忆发展得很好。和宝宝一起读书，说出图片里动物的名字吧。' WHERE id = 'e386c8f2-240d-4f0f-adaf-e43ea496b8b2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una foto que detiene el tiempo 📸', body_es = 'Mientras juega tan a gusto en la habitación, abre la Sesión de fotos del bebé y guarda con una temática especial esta carita distinta y más mayor que se acerca al 8.º mes.', title_fr = 'La photo qui arrête le temps 📸', body_fr = 'Pendant qu''il joue tranquillement, ouvrez vite la Séance photo bébé et immortalisez avec un thème spécial ce visage qui a grandi à l''approche du 8e mois.', title_hi = 'समय को थाम लेने वाली तस्वीर 📸', body_hi = 'कमरे में प्यार से खेलते हुए तुरंत बेबी फ़ोटोशूट खोलिए और 8वें महीने के करीब पहुँचे इस बदले, बड़े होते चेहरे को खास थीम के साथ यादों में बसाइए।', title_id = 'Foto yang menghentikan waktu 📸', body_id = 'Saat ia bermain dengan manis di kamar, segera buka Sesi Foto Bayi dan abadikan wajahnya yang makin besar menjelang bulan ke-8 dengan tema khusus.', title_ja = '時間を止める1枚 📸', body_ja = '部屋でごきげんに遊んでいるうちに、すぐ「ベビーフォトセッション」を開いて、8か月に近づくこの大きくなった顔を特別なテーマで残しましょう。', title_ko = '시간을 멈추는 한 컷 📸', body_ko = '방에서 귀엽게 놀고 있을 때 바로 아기 사진 촬영을 열어 8개월을 앞두고 한층 자란 얼굴을 특별한 테마로 남겨 보세요.', title_nl = 'Een foto die de tijd stilzet 📸', body_nl = 'Speelt je baby lief in de kamer? Open meteen Babyfotoshoot en leg dit veranderde, grotere gezichtje rond de 8e maand vast met een speciaal thema.', title_pl = 'Kadr, który zatrzymuje czas 📸', body_pl = 'Gdy słodko bawi się w pokoju, od razu otwórz Sesję zdjęciową dziecka i uwiecznij w specjalnym motywie tę nową, dojrzalszą buzię w drodze do 8. miesiąca.', title_pt = 'Uma foto que para o tempo 📸', body_pt = 'Enquanto brinca docemente no quarto, abra já a Sessão Fotográfica do Bebé e guarde com um tema especial este rosto diferente e crescido, já perto dos 8 meses.', title_sv = 'Bilden som stoppar tiden 📸', body_sv = 'Öppna Babyfotografering direkt medan barnet leker så gulligt i rummet, och förevig det här annorlunda, äldre ansiktet inför 8:e månaden med ett speciellt tema.', title_vi = 'Khoảnh khắc ngưng đọng thời gian 📸', body_vi = 'Khi bé đang chơi ngoan trong phòng, hãy mở ngay Chụp ảnh cho bé và lưu giữ gương mặt đã lớn khác hẳn khi gần tròn 8 tháng với một chủ đề đặc biệt.', title_zh = '定格时光 📸', body_zh = '趁宝宝在房间里乖乖玩耍，马上打开宝宝写真，用特别的主题记下这张快满8个月、已经长大不少的小脸吧。' WHERE id = 'e418c384-8ae3-455b-af14-a223e6595751' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hace falta desahogarse 💬', body_es = '¿Te emociona pensar «no me puedo creer que ya vaya a cumplir 8 meses»? Comparte este sentimiento tan bonito y frágil con las mamás de la Comunidad Anacan.', title_fr = 'Besoin de vous confier 💬', body_fr = 'Penser « Je n''arrive pas à croire qu''il a déjà 8 mois » vous émeut ? Partagez ce sentiment beau et fragile avec les mamans de la Communauté Anacan.', title_hi = 'दिल की बात करना ज़रूरी है 💬', body_hi = '''यकीन नहीं होता कि वह 8 महीने का हो रहा है'' यह सोचकर भावुक हो जाती हैं? Anacan कम्युनिटी की माँओं के साथ यह प्यारा और नाज़ुक एहसास बाँटिए।', title_id = 'Butuh teman bercerita 💬', body_id = 'Pikiran "Aku tak percaya ia sudah hampir 8 bulan" membuat Anda terharu? Bagikan perasaan indah dan rapuh ini dengan para ibu di Komunitas Anacan.', title_ja = '話すことが必要なとき 💬', body_ja = '「もう8か月になるなんて信じられない」と思うと胸がいっぱいになりますか？Anacanコミュニティのママたちと、このすてきで切ない気持ちを分かち合いましょう。', title_ko = '마음을 나눌 시간 💬', body_ko = '''벌써 8개월이라니 믿기지 않아''라는 생각에 마음이 뭉클한가요? Anacan 커뮤니티의 엄마들과 이 아름답고 애틋한 마음을 나눠 보세요.', title_nl = 'Even je hart luchten 💬', body_nl = 'Word je emotioneel van de gedachte: ik kan niet geloven dat hij al 8 maanden wordt? Deel dit mooie, kwetsbare gevoel met de moeders in de Anacan Community.', title_pl = 'Czas się wygadać 💬', body_pl = 'Myśl „nie mogę uwierzyć, że ma już prawie 8 miesięcy” cię wzrusza? Podziel się tym pięknym, kruchym uczuciem z mamami w Społeczności Anacan.', title_pt = 'Precisa de desabafar 💬', body_pt = 'O pensamento "nem acredito que já vai fazer 8 meses" deixa-a emocionada? Partilhe este sentimento bonito e delicado com as mães da Comunidade Anacan.', title_sv = 'Ibland behöver man prata av sig 💬', body_sv = 'Blir du känslosam av tanken ''jag kan inte fatta att barnet redan fyller 8 månader''? Dela den här fina och sköra känslan med mammorna i Anacans Community.', title_vi = 'Cần được tâm sự 💬', body_vi = 'Ý nghĩ "Không thể tin là bé đã sắp 8 tháng" khiến mẹ xúc động? Hãy chia sẻ cảm xúc đẹp đẽ và mong manh này với các bà mẹ trong Cộng đồng Anacan.', title_zh = '需要倾诉一下 💬', body_zh = '“真不敢相信宝宝都快8个月了”，这个念头让你心里软软的？和Anacan社区的妈妈们分享这份美好又脆弱的感受吧。' WHERE id = '4068a45c-e5fe-4a82-8c4b-a81d556f97cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Prueba y error 🧱', body_es = 'Intenta poner un cubo de juguete encima de otro, pero se cae. Vuelve a probar con atención. Observa en silencio y con orgullo sus pequeños intentos de ingeniería.', title_fr = 'Essais et erreurs 🧱', body_fr = 'Il essaie d''empiler deux cubes, mais ils tombent. Il recommence avec attention. Observez en silence et avec fierté ses petits essais d''ingénieur.', title_hi = 'कोशिश और गलती 🧱', body_hi = 'दो खिलौना ब्लॉक एक के ऊपर एक रखने की कोशिश करता है, पर वे गिर जाते हैं। वह ध्यान से फिर कोशिश करता है। उसकी इन छोटी-छोटी इंजीनियरिंग और प्रयोग की कोशिशों को चुपचाप, गर्व से देखिए।', title_id = 'Coba dan gagal 🧱', body_id = 'Ia mencoba menumpuk dua balok mainan, tapi jatuh. Ia mencoba lagi dengan saksama. Saksikan usaha insinyur kecil ini diam-diam dengan penuh bangga.', title_ja = '試行錯誤 🧱', body_ja = '積み木を2つ重ねようとして、くずれてしまう。それでも注意深くまた挑戦します。この小さなエンジニアの実験を、静かに誇らしく見守りましょう。', title_ko = '시행착오 🧱', body_ko = '블록 두 개를 쌓으려다 무너져도 다시 조심스럽게 시도해요. 이 꼬마 엔지니어의 실험을 조용히, 뿌듯하게 지켜봐 주세요.', title_nl = 'Vallen en opstaan 🧱', body_nl = 'Je baby probeert twee blokken op elkaar te zetten, maar ze vallen om. Hij probeert het aandachtig opnieuw. Kijk stil en trots naar deze kleine bouw- en testpogingen.', title_pl = 'Próby i błędy 🧱', body_pl = 'Próbuje postawić jeden klocek na drugim, ale się przewracają. Uważnie próbuje znowu. Obserwuj w ciszy i z dumą te małe inżynierskie eksperymenty.', title_pt = 'Tentativa e erro 🧱', body_pt = 'Tenta pôr dois cubos um em cima do outro, mas caem. Volta a tentar com atenção. Acompanhe em silêncio e com orgulho estas pequenas tentativas de engenharia.', title_sv = 'Försök och misstag 🧱', body_sv = 'Barnet försöker stapla två leksaksklossar på varandra, men de ramlar. Det försöker igen, noggrant. Följ de här små ingenjörsförsöken tyst och stolt.', title_vi = 'Thử và sai 🧱', body_vi = 'Bé cố xếp hai khối đồ chơi chồng lên nhau, nhưng bị đổ. Bé chăm chú thử lại. Hãy lặng lẽ và tự hào ngắm những nỗ lực "kỹ sư" nhỏ bé này.', title_zh = '尝试与犯错 🧱', body_zh = '宝宝想把两块积木叠起来，可是倒了。宝宝认真地再试一次。默默地、骄傲地看着这些小小的工程与实验尝试吧。' WHERE id = '90c5ba08-9d91-4669-8b26-99e0b48d4cf2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baja las luces 🌙', body_es = 'Una hora antes de dormir, apaga todas las luces fuertes y las pantallas de casa. La melatonina se segrega rápido solo en un ambiente tranquilo y con poca luz.', title_fr = 'Baissez les lumières 🌙', body_fr = '1 heure avant le coucher, éteignez toutes les lumières vives et les écrans de la maison. La mélatonine n''est sécrétée rapidement que dans un environnement calme et peu éclairé.', title_hi = 'लाइटें धीमी कीजिए 🌙', body_hi = 'सोने से 1 घंटा पहले घर की सारी तेज़ लाइटें और स्क्रीन बंद कर दीजिए। मेलाटोनिन शांत और कम रोशनी वाले माहौल में ही तेज़ी से बनता है।', title_id = 'Redupkan lampu 🌙', body_id = 'Satu jam sebelum tidur, matikan semua lampu terang dan layar di rumah. Melatonin hanya diproduksi dengan cepat di lingkungan yang tenang dan redup.', title_ja = '明かりを落として 🌙', body_ja = '寝る1時間前には、家の強い明かりや画面をすべて消しましょう。メラトニンは、静かで明かりの少ない環境でこそどんどん分泌されます。', title_ko = '조명을 낮춰요 🌙', body_ko = '잠들기 1시간 전에 집 안의 밝은 조명과 화면을 모두 끄세요. 멜라토닌은 조용하고 어두운 환경에서만 빠르게 분비돼요.', title_nl = 'Doe de lichten zachter 🌙', body_nl = 'Doe 1 uur voor het slapengaan alle felle lampen en schermen in huis uit. Melatonine wordt alleen in een rustige omgeving met weinig licht snel aangemaakt.', title_pl = 'Przyciemnij światła 🌙', body_pl = 'Na godzinę przed snem wyłącz w domu wszystkie mocne światła i ekrany. Melatonina szybko się wydziela tylko w spokojnym, słabo oświetlonym otoczeniu.', title_pt = 'Baixe as luzes 🌙', body_pt = '1 hora antes de dormir, apague as luzes desnecessárias e os ecrãs da casa. A melatonina só é produzida depressa num ambiente calmo e com pouca luz.', title_sv = 'Dämpa ljuset 🌙', body_sv = 'Släck alla starka lampor och skärmar hemma 1 timme innan läggdags. Melatonin utsöndras snabbt bara i en lugn och svagt upplyst miljö.', title_vi = 'Giảm ánh sáng 🌙', body_vi = '1 tiếng trước giờ ngủ, hãy tắt hết đèn sáng và màn hình trong nhà. Melatonin chỉ được tiết ra nhanh trong môi trường yên tĩnh và ít ánh sáng.', title_zh = '调暗灯光 🌙', body_zh = '睡前1小时关掉家里所有的强光和屏幕。褪黑素只有在安静、光线昏暗的环境里才会快速分泌。' WHERE id = 'ed75b4ae-9703-498c-a857-64016faef6cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Quién hace las tareas de casa? 🌪️', body_es = '¿Te quedan cosas por hacer para la pequeña fiesta de mañana? Que esperen. Pide a tu compañero de equipo que hoy se encargue de las tareas de casa. Y tú descansa para mañana.', title_fr = 'Qui s''occupe du ménage ? 🌪️', body_fr = 'Il reste des choses à faire pour la petite fête de demain ? Laissez-les. Demandez à votre coéquipier de prendre en charge les tâches ménagères aujourd''hui. Vous, reposez-vous pour demain.', title_hi = 'घर का काम कौन करेगा? 🌪️', body_hi = 'कल के छोटे जश्न के लिए काम बाकी हैं? रहने दीजिए। अपने टीम साथी से कहिए कि आज घर के काम वे संभालें। और आप कल के लिए आराम कीजिए।', title_id = 'Siapa yang mengurus rumah? 🌪️', body_id = 'Masih ada pekerjaan untuk pesta kecil besok? Biarkan saja. Minta rekan tim Anda mengambil alih pekerjaan rumah hari ini. Anda istirahatlah untuk besok.', title_ja = '家事は誰がする？🌪️', body_ja = '明日の小さなお祝いのためにやることが残っている？そのままでいいんです。今日の家事はパートナーにお願いしましょう。あなたは明日に向けて休んでください。', title_ko = '집안일은 누가 할까요? 🌪️', body_ko = '내일 작은 파티를 위해 할 일이 남았나요? 그냥 두세요. 오늘 집안일은 팀 동료인 배우자에게 맡기고, 엄마는 내일을 위해 쉬세요.', title_nl = 'Wie doet het huishouden? 🌪️', body_nl = 'Blijft er werk liggen voor het kleine feestje van morgen? Laat het liggen. Vraag je teamgenoot om vandaag het huishouden op zich te nemen. En jij rust uit voor morgen.', title_pl = 'Kto zajmie się domem? 🌪️', body_pl = 'Zostało coś do zrobienia przed jutrzejszym małym przyjęciem? Niech zostanie. Poproś partnera z drużyny, żeby dziś przejął domowe obowiązki. A ty odpocznij przed jutrem.', title_pt = 'Quem vai tratar da casa? 🌪️', body_pt = 'Ainda há coisas por fazer para a pequena festa de amanhã? Deixe ficar. Peça ao seu parceiro de equipa que hoje se encarregue das tarefas da casa. E a mãe descansa para amanhã.', title_sv = 'Vem tar hushållet? 🌪️', body_sv = 'Finns det saker kvar att fixa inför morgondagens lilla fest? Låt dem vänta. Be din lagkamrat ta hand om hushållet i dag. Och du, vila inför i morgon.', title_vi = 'Ai sẽ làm việc nhà? 🌪️', body_vi = 'Còn việc phải làm cho bữa tiệc nhỏ ngày mai? Cứ để đó. Hãy nhờ người đồng đội của mình đảm nhận việc nhà hôm nay. Còn mẹ thì nghỉ ngơi cho ngày mai.', title_zh = '家务谁来做？🌪️', body_zh = '明天的小派对还有事没做完？就先放着吧。请你的队友今天把家务都揽下来，你好好休息，为明天养足精神。' WHERE id = '695238eb-b88d-4ffe-800b-82d23636ceb9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El baile de la victoria 🥂', body_es = 'Esta noche celebra con tu pareja el cansancio, las lágrimas y la alegría de estos 8 meses. Pon una vela en la mesa y aplaudid vuestra victoria como equipo inquebrantable.', title_fr = 'La danse de la victoire 🥂', body_fr = 'Ce soir, célébrez avec votre conjoint la fatigue, les larmes et la joie de ces 8 mois. Posez une bougie sur la table et applaudissez votre victoire d''équipe inébranlable !', title_hi = 'जीत का नाच 🥂', body_hi = '8 महीनों की थकान, आँसुओं और खुशियों का जश्न आज शाम अपने साथी के साथ मनाइए। मेज़ पर एक मोमबत्ती जलाइए और अपनी अटूट टीम की जीत पर ताली बजाइए!', title_id = 'Tarian kemenangan 🥂', body_id = 'Rayakan lelah, air mata, dan bahagia 8 bulan ini bersama pasangan malam ini. Nyalakan lilin di meja dan beri tepuk tangan untuk kemenangan tim kalian yang tak tergoyahkan!', title_ja = '勝利のダンス 🥂', body_ja = '8か月分の疲れも涙も喜びも、今夜はパートナーとお祝いしましょう。食卓にキャンドルをともして、ゆるぎないチームの勝利に拍手を！', title_ko = '승리의 춤 🥂', body_ko = '오늘 저녁 배우자와 함께 8개월의 피로와 눈물, 기쁨을 기념하세요. 식탁에 초를 켜고 흔들림 없는 팀의 승리에 박수를 보내세요!', title_nl = 'Een overwinningsdans 🥂', body_nl = 'Vier vanavond samen met je partner de vermoeidheid, de tranen en de vreugde van 8 maanden. Zet een kaars op tafel en juich voor jullie onwankelbare overwinning als team!', title_pl = 'Taniec zwycięstwa 🥂', body_pl = 'Uczcij dziś wieczorem z partnerem zmęczenie, łzy i radość tych 8 miesięcy. Zapal na stole świeczkę i oklaskujcie wasze niezachwiane drużynowe zwycięstwo!', title_pt = 'Dança da vitória 🥂', body_pt = 'Esta noite, celebre com o seu companheiro o cansaço, as lágrimas e a alegria destes 8 meses. Ponha uma vela na mesa e aplaudam a vitória da vossa equipa inabalável!', title_sv = 'Segerdans 🥂', body_sv = 'Fira 8 månader av trötthet, tårar och glädje tillsammans med din partner i kväll. Tänd ett ljus på bordet och applådera er orubbliga lagseger!', title_vi = 'Điệu nhảy chiến thắng 🥂', body_vi = 'Tối nay, hãy cùng bố ăn mừng 8 tháng mệt mỏi, nước mắt và niềm vui. Thắp một ngọn nến trên bàn và cùng vỗ tay cho chiến thắng của một đội không gì lay chuyển được!', title_zh = '胜利之舞 🥂', body_zh = '今晚和伴侣一起庆祝这8个月的疲惫、泪水和欢乐。在餐桌上点一支蜡烛，为你们坚不可摧的团队胜利鼓掌吧！' WHERE id = '393a7a2a-b162-45e4-9577-0e4f2d088bf3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mirando atrás 📈', body_es = '¡Cuánto camino ha recorrido tu peque! Aquel miedo frágil de los primeros días se ha convertido en una enorme confianza. ¡Has llegado a estos 8 meses con gran orgullo! ¡Eres realmente maravillosa!', title_fr = 'Un regard en arrière 📈', body_fr = 'Quel chemin votre enfant a parcouru ! Les peurs fragiles des premiers jours ont laissé place à une immense confiance. Vous avez traversé ces 8 mois avec une grande fierté ! Vous êtes vraiment formidable !', title_hi = 'पीछे मुड़कर देखें 📈', body_hi = 'आपके बच्चे ने कितना लंबा सफ़र तय किया है! शुरुआती दिनों के नाज़ुक डर की जगह अब एक बड़े भरोसे ने ले ली है। आपने ये 8 महीने बड़े गर्व से पूरे किए! आप सच में कमाल की हैं!', title_id = 'Menengok ke belakang 📈', body_id = 'Betapa jauh si kecil sudah melangkah! Ketakutan rapuh di hari-hari pertama kini berganti dengan rasa percaya diri yang besar. Anda melewati 8 bulan ini dengan penuh bangga! Anda sungguh sempurna!', title_ja = '振り返り 📈', body_ja = '赤ちゃんはなんて長い道のりを歩んできたのでしょう！最初のころのもろい不安は、今では大きな自信に変わりました。あなたはこの8か月を誇りをもって歩んできました！本当にすばらしい！', title_ko = '돌아보기 📈', body_ko = '아이가 얼마나 먼 길을 왔는지 보세요! 처음 며칠의 여린 두려움이 이제 커다란 자신감으로 바뀌었어요. 8개월을 당당하게 걸어왔어요! 정말 멋져요!', title_nl = 'Terugblik 📈', body_nl = 'Wat heeft je kindje een weg afgelegd! De kwetsbare angst van de eerste dagen heeft plaatsgemaakt voor enorm vertrouwen. Je bent deze 8 maanden met trots doorgekomen! Je bent echt geweldig!', title_pl = 'Spojrzenie wstecz 📈', body_pl = 'Jak długą drogę przeszedł twój maluszek! Kruchy lęk pierwszych dni ustąpił miejsca ogromnej pewności. Przeszłaś te 8 miesięcy z wielką dumą! Jesteś naprawdę wspaniała!', title_pt = 'Olhar para trás 📈', body_pt = 'Que caminho o bebé já percorreu! O medo frágil dos primeiros dias deu lugar a uma enorme confiança. Chegou a estes 8 meses com grande orgulho! É mesmo perfeita!', title_sv = 'En tillbakablick 📈', body_sv = 'Vilken väg ditt barn har gått! Den sköra rädslan från de första dagarna har nu ersatts av en enorm trygghet. Du har tagit dig igenom de här 8 månaderna med stor stolthet! Du är verkligen fantastisk!', title_vi = 'Nhìn lại chặng đường 📈', body_vi = 'Bé đã đi được một chặng đường dài! Nỗi sợ mong manh của những ngày đầu giờ đã thành niềm tin lớn lao. Mẹ đã đi qua 8 tháng này với niềm tự hào lớn! Mẹ thật sự tuyệt vời!', title_zh = '回顾 📈', body_zh = '宝宝走了多远的路啊！最初那些日子脆弱的恐惧，如今已经变成了巨大的自信。你满怀骄傲地走过了这8个月！你真的很了不起！' WHERE id = '4419f2fd-8e6f-4837-aa0e-9d571aac3895' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lista en tu bolsillo 🛒', body_es = 'Para encargar la tarta del primer año, echa un vistazo a las opciones de tartas en Anacan.', title_fr = 'La liste dans votre poche 🛒', body_fr = 'Pour commander le gâteau des 1 an, jetez un œil aux gâteaux proposés sur Anacan.', title_hi = 'आपकी जेब में लिस्ट 🛒', body_hi = 'पहले जन्मदिन का केक ऑर्डर करने के लिए Anacan में केक के विकल्प देखिए।', title_id = 'Daftar di saku Anda 🛒', body_id = 'Untuk memesan kue ulang tahun pertama, lihat pilihan kue di Anacan.', title_ja = 'ポケットの中のリスト 🛒', body_ja = '1歳のケーキを注文するなら、Anacanのケーキのラインナップをチェックしましょう。', title_ko = '주머니 속 목록 🛒', body_ko = '첫돌 케이크를 주문하려면 Anacan의 케이크 옵션을 살펴보세요.', title_nl = 'Een lijstje in je broekzak 🛒', body_nl = 'Bekijk de taartopties in Anacan om je taart voor de eerste verjaardag te bestellen.', title_pl = 'Lista w kieszeni 🛒', body_pl = 'Aby zamówić tort na roczek, zajrzyj do oferty tortów w Anacan.', title_pt = 'A lista no seu bolso 🛒', body_pt = 'Para encomendar o bolo do 1.º aniversário, veja as opções de bolos no Anacan.', title_sv = 'Listan i fickan 🛒', body_sv = 'Kika på tårtalternativen i Anacan för att beställa tårta till 1-årsdagen.', title_vi = 'Danh sách trong túi mẹ 🛒', body_vi = 'Để đặt bánh kem sinh nhật 1 tuổi, hãy xem các mẫu bánh trong Anacan nhé.', title_zh = '口袋里的清单 🛒', body_zh = '想订一周岁蛋糕，就去Anacan看看蛋糕的选择吧。' WHERE id = '2f4fbaac-dfe4-48b5-b844-6636c2bc201a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lista rápida 🛒', body_es = '¿Ayer se acabaron todas las reservas de casa? Abre la Lista de la compra, apunta en segundos la leche, la fruta y lo que falte, y envíalo al móvil de tu pareja.', title_fr = 'La liste express 🛒', body_fr = 'Toutes les réserves de la maison se sont épuisées hier ? Ouvrez la Liste de courses, notez en quelques secondes le lait, les fruits et ce qui manque, et envoyez-la sur le téléphone de votre conjoint.', title_hi = 'झटपट लिस्ट 🛒', body_hi = 'कल घर का सारा सामान खत्म हो गया? शॉपिंग लिस्ट खोलिए, दूध, फल और बाकी कमी वाली चीज़ें सेकंडों में लिखिए और अपने साथी के फ़ोन पर भेजिए।', title_id = 'Daftar kilat 🛒', body_id = 'Kemarin semua persediaan di rumah habis? Buka Daftar Belanja, catat susu, buah, dan kebutuhan lainnya dalam hitungan detik, lalu kirim ke ponsel pasangan Anda.', title_ja = 'すばやくリスト 🛒', body_ja = '昨日、家のストックがぜんぶ切れた？「買い物リスト」を開いて、牛乳、果物、そのほか足りないものを数秒で書き、パートナーのスマホに送りましょう。', title_ko = '빠른 목록 🛒', body_ko = '어제 집에 있던 생필품이 다 떨어졌나요? 쇼핑 목록을 열어 우유, 과일 등 필요한 것을 몇 초 만에 적고 배우자 휴대폰으로 보내세요.', title_nl = 'Een snel lijstje 🛒', body_nl = 'Was gisteren alle voorraad in huis op? Open je Boodschappenlijstje, zet melk, fruit en wat er verder ontbreekt er in een paar seconden op en stuur het naar de telefoon van je partner.', title_pl = 'Szybka lista 🛒', body_pl = 'Wczoraj skończyły się wszystkie zapasy w domu? Otwórz Listę zakupów, w kilka sekund zapisz mleko, owoce i inne braki i wyślij je na telefon partnera.', title_pt = 'Lista rápida 🛒', body_pt = 'Ontem acabaram-se as reservas todas em casa? Abra a Lista de Compras, aponte em segundos o leite, a fruta e o que mais faltar, e envie para o telemóvel do seu companheiro.', title_sv = 'Snabblista 🛒', body_sv = 'Tog alla förråd hemma slut i går? Öppna Inköpslistan, skriv upp mjölk, frukt och annat som fattas på några sekunder och skicka det till din partners telefon.', title_vi = 'Danh sách nhanh 🛒', body_vi = 'Hôm qua đồ dự trữ trong nhà hết sạch? Mở Danh sách mua sắm, ghi lại sữa, trái cây và những thứ còn thiếu chỉ trong vài giây rồi gửi đến điện thoại của bố.', title_zh = '快速清单 🛒', body_zh = '昨天家里的存货都用完了？打开购物清单，几秒钟记下牛奶、水果和其他缺的东西，发到伴侣的手机上吧。' WHERE id = '075bea5d-3ab7-4404-af70-89a3de20a0ff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El caos después del aniversario 🌪️', body_es = '¿La casa está patas arriba después de la fiesta de los 8 meses de ayer? No corras a limpiar. Dedica el día de hoy simplemente a descansar y a descubrir juguetes nuevos con tu peque de 8 meses.', title_fr = 'Le chaos d''après la fête 🌪️', body_fr = 'La maison est sens dessus dessous après la fête des 8 mois d''hier ? Ne vous précipitez pas sur le ménage. Consacrez simplement cette journée au repos et à la découverte des nouveaux jouets avec votre petit de 8 mois.', title_hi = 'जश्न के बाद की अफ़रा-तफ़री 🌪️', body_hi = 'कल की 8 महीने की पार्टी के बाद घर बिखरा पड़ा है? सफ़ाई के लिए मत भागिए। आज का दिन अपने 8 महीने के नन्हे के साथ बस आराम करने और नए खिलौने खोजने में बिताइए।', title_id = 'Kekacauan setelah perayaan 🌪️', body_id = 'Rumah berantakan setelah pesta 8 bulan kemarin? Jangan buru-buru bersih-bersih. Habiskan hari ini bersama si kecil yang baru 8 bulan hanya untuk beristirahat dan menjelajahi mainan baru.', title_ja = 'お祝いのあとのカオス 🌪️', body_ja = '昨日の8か月パーティーのあとで家がめちゃくちゃ？お掃除に走らないで。今日は8か月になった赤ちゃんと、のんびり新しいおもちゃを発見する日にしましょう。', title_ko = '기념일 뒤의 혼돈 🌪️', body_ko = '어제 8개월 파티 뒤로 집이 엉망인가요? 청소하러 달려가지 마세요. 오늘은 이제 막 8개월이 된 아기와 함께 쉬고 새 장난감을 탐색하는 데만 쓰세요.', title_nl = 'Chaos na het jubileum 🌪️', body_nl = 'Is het huis een puinhoop na het 8-maandenfeestje van gisteren? Ren niet naar de schoonmaak. Besteed deze dag met je nieuwe 8 maanden oude kleintje gewoon aan rust en het ontdekken van nieuwe speeltjes.', title_pl = 'Chaos po jubileuszu 🌪️', body_pl = 'Po wczorajszej imprezie z okazji 8 miesięcy w domu pobojowisko? Nie biegnij sprzątać. Poświęć dzisiejszy dzień ze swoim nowym 8-miesięcznym maluchem po prostu na odpoczynek i odkrywanie nowych zabawek.', title_pt = 'O caos depois da festa 🌪️', body_pt = 'Depois da festa dos 8 meses de ontem, a casa está virada do avesso? Não corra para as limpezas. Dedique o dia ao descanso e a descobrir brinquedos novos com o seu bebé de 8 meses.', title_sv = 'Kaoset efter jubileet 🌪️', body_sv = 'Är hemmet helt kaos efter gårdagens 8-månadersfest? Rusa inte iväg och städa. Ägna dagen åt vila och åt att upptäcka nya leksaker med din nyblivna 8-månadersbebis.', title_vi = 'Hỗn loạn sau ngày kỷ niệm 🌪️', body_vi = 'Sau bữa tiệc mừng 8 tháng hôm qua, nhà cửa bừa bộn? Đừng vội dọn dẹp. Hôm nay hãy dành trọn để nghỉ ngơi và khám phá đồ chơi mới cùng bé 8 tháng tuổi.', title_zh = '纪念日后的混乱 🌪️', body_zh = '昨天的8个月派对后家里一片狼藉？别急着打扫。今天就和你8个月大的小家伙一起休息、探索新玩具吧。' WHERE id = 'e32c4fc2-e649-4150-9d80-08ebdc4ae2e8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Control de los ruidos 🤫', body_es = 'La primera media hora después de dormirse es el momento más delicado. Comprueba el ambiente con el Medidor de sonido y evita ruidos repentinos, la tele o el ruido de la calle.', title_fr = 'Maîtriser les bruits 🤫', body_fr = 'La première demi-heure après l''endormissement est le moment le plus sensible. Vérifiez l''ambiance avec le Sonomètre et évitez les bruits soudains, la télévision ou les bruits de la rue.', title_hi = 'आवाज़ों पर काबू 🤫', body_hi = 'सोने के बाद का पहला आधा घंटा सबसे नाज़ुक समय है। साउंड मीटर से माहौल जाँचिए और अचानक शोर, टीवी या सड़क की आवाज़ से दूर रहिए।', title_id = 'Mengatur suara 🤫', body_id = 'Setengah jam pertama setelah tertidur adalah waktu paling sensitif. Cek suasana dengan Pengukur Suara dan jauhkan dari suara mendadak, TV, atau bising jalanan.', title_ja = '音のコントロール 🤫', body_ja = '寝ついてから最初の30分は、いちばん眠りが浅い時間です。「サウンドメーター」で環境をチェックし、急な物音やテレビ、外の音から遠ざけましょう。', title_ko = '소리 관리 🤫', body_ko = '잠든 직후 처음 30분이 가장 예민한 시간이에요. 소음 측정기로 환경을 확인하고 갑작스러운 소음, TV나 거리 소리를 피하세요.', title_nl = 'Geluiden onder controle 🤫', body_nl = 'Het eerste halfuur na het inslapen is het gevoeligst. Controleer de omgeving met de Geluidsmeter en vermijd plotseling lawaai van de tv of de straat.', title_pl = 'Kontrola dźwięków 🤫', body_pl = 'Pierwsze pół godziny po zaśnięciu to najwrażliwszy czas. Sprawdź otoczenie Miernikiem dźwięku i unikaj nagłego hałasu, telewizora czy odgłosów z ulicy.', title_pt = 'Controlo dos sons 🤫', body_pt = 'A primeira meia hora depois de adormecer é a altura mais sensível. Verifique o ambiente com o Medidor de Som e evite barulhos súbitos, da televisão ou da rua.', title_sv = 'Ljudkoll 🤫', body_sv = 'Den första halvtimmen efter att barnet har somnat är den känsligaste. Kolla miljön med Ljudmätaren och undvik plötsligt oväsen, tv eller ljud från gatan.', title_vi = 'Kiểm soát âm thanh 🤫', body_vi = 'Nửa tiếng đầu sau khi bé ngủ là lúc nhạy cảm nhất. Hãy kiểm tra môi trường bằng Đo âm thanh và tránh xa tiếng ồn đột ngột, tiếng tivi hay tiếng ồn ngoài đường.', title_zh = '控制声音 🤫', body_zh = '入睡后的头半小时是最敏感的时候。用噪音测量检查环境，远离突然的噪音、电视声和街上的声音。' WHERE id = '2c9fa500-5618-49b8-a232-965da7b82ef7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Te oigo 🗣️', body_es = '¿Te escucha con atención e intenta decir sílabas parecidas? ¡Está hablando contigo! Respóndele con muchas sonrisas y fomenta esta comunicación.', title_fr = 'Je t''entends 🗣️', body_fr = 'Il vous écoute attentivement et essaie de produire des syllabes semblables ? Il vous parle ! Répondez-lui avec plein de sourires et encouragez cette communication.', title_hi = 'मैं आपको सुन रहा हूँ 🗣️', body_hi = 'आपको ध्यान से सुनकर मिलते-जुलते अक्षर बोलने की कोशिश करता है? वह आपसे बात कर रहा है! खूब मुस्कुराकर उसे जवाब दीजिए और इस बातचीत को बढ़ावा दीजिए।', title_id = 'Aku mendengarmu 🗣️', body_id = 'Ia mendengarkan Anda dengan saksama dan mencoba menirukan suku kata? Ia sedang berbicara dengan Anda! Balas dengan banyak senyuman dan dukung komunikasi ini.', title_ja = '聞こえてるよ 🗣️', body_ja = 'あなたの話をじっと聞いて、似た音を出そうとしていますか？あなたとおしゃべりしているのです！たっぷりの笑顔で応えて、このやりとりを応援してあげましょう。', title_ko = '엄마 목소리가 들려요 🗣️', body_ko = '엄마 말을 유심히 듣고 비슷한 소리를 내려고 하나요? 엄마와 이야기하는 중이에요! 활짝 웃으며 대답하고 이 소통을 응원해 주세요.', title_nl = 'Ik hoor je 🗣️', body_nl = 'Luistert je baby aandachtig naar je en probeert hij lettergrepen na te doen? Hij praat met je! Antwoord hem met een grote glimlach en stimuleer deze communicatie.', title_pl = 'Słyszę cię 🗣️', body_pl = 'Uważnie cię słucha i próbuje wymawiać podobne sylaby? Rozmawia z tobą! Odpowiadaj mu z szerokim uśmiechem i zachęcaj do tej komunikacji.', title_pt = 'Estou a ouvir-te 🗣️', body_pt = 'Ouve-a com atenção e tenta fazer sílabas parecidas? Está a falar consigo! Responda-lhe com muitos sorrisos e incentive esta comunicação.', title_sv = 'Jag hör dig 🗣️', body_sv = 'Lyssnar barnet uppmärksamt på dig och försöker säga liknande stavelser? Det pratar med dig! Svara med massor av leenden och uppmuntra den här kommunikationen.', title_vi = 'Con nghe thấy mẹ 🗣️', body_vi = 'Bé chăm chú nghe mẹ và cố phát ra những âm tương tự? Bé đang nói chuyện với mẹ đấy! Hãy đáp lại bé bằng thật nhiều nụ cười và khuyến khích bé giao tiếp.', title_zh = '我听到你啦 🗣️', body_zh = '宝宝专心听你说话，还想发出相似的音节？宝宝在和你说话！多笑着回应宝宝，鼓励这种交流吧。' WHERE id = '87a20850-e59a-4ee2-81e8-79c4b5808e7b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hoy se te acabó la paciencia o quizá te enfadaste? 🛑', body_es = 'No te sientas mal. Aléjate de las ilusiones de internet. Eres una madre real y tienes que vivir tus emociones.', title_fr = 'À bout de patience aujourd''hui, peut-être énervée ? 🛑', body_fr = 'Ne vous sentez pas mal. Éloignez-vous des illusions d''Internet. Vous êtes une vraie maman, vous avez le droit de vivre vos émotions.', title_hi = 'आज धैर्य जवाब दे गया, शायद गुस्सा भी आया? 🛑', body_hi = 'बुरा मत मानिए। इंटरनेट के भ्रमों से दूर रहिए। आप एक असली माँ हैं, अपनी भावनाओं को जीना ठीक है।', title_id = 'Hari ini kesabaran Anda menipis, mungkin Anda sempat marah? 🛑', body_id = 'Jangan merasa bersalah. Jauhi ilusi di internet. Anda ibu yang nyata, dan Anda berhak merasakan emosi Anda.', title_ja = '今日はがまんの限界で、イライラしてしまった？🛑', body_ja = '自分を責めないで。ネットの理想像からは距離をおきましょう。あなたはリアルなママで、自分の気持ちを感じていいのです。', title_ko = '오늘 인내심이 바닥나 화가 났나요? 🛑', body_ko = '자책하지 마세요. 인터넷 속 환상에서 멀어지세요. 당신은 진짜 엄마이고, 감정을 느껴도 괜찮아요.', title_nl = 'Was je geduld vandaag op en werd je misschien boos?  🛑', body_nl = 'Voel je niet schuldig. Blijf weg van de illusies op internet. Je bent een echte moeder en je mag je emoties voelen.', title_pl = 'Dziś zabrakło ci cierpliwości, może się zdenerwowałaś? 🛑', body_pl = 'Nie czuj się źle. Odsuń się od internetowych iluzji. Jesteś prawdziwą mamą i masz prawo przeżywać swoje emocje.', title_pt = 'Hoje a paciência esgotou-se, talvez se tenha irritado?  🛑', body_pt = 'Não se sinta mal. Afaste-se das ilusões da internet. É uma mãe real e tem direito a viver as suas emoções.', title_sv = 'Tog tålamodet slut i dag och kanske blev du arg?  🛑', body_sv = 'Må inte dåligt. Håll dig borta från illusionerna på nätet. Du är en riktig mamma och du måste få känna dina känslor.', title_vi = 'Hôm nay mẹ hết kiên nhẫn, có thể đã nổi nóng?  🛑', body_vi = 'Đừng tự trách mình. Hãy tránh xa những ảo ảnh trên mạng. Mẹ là một người mẹ thật, mẹ cần được sống với cảm xúc của mình.', title_zh = '今天没了耐心，也许还发了脾气？🛑', body_zh = '别难过。远离网上的那些幻象。你是一个真实的妈妈，你有权利去感受自己的情绪。' WHERE id = '9c963f32-b147-4e84-aa9a-af699e50681f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lista como un médico 🤖', body_es = '¿Tienes dudas sobre las pautas de desarrollo después de los 8 meses? No te pierdas en internet: recibe de Anacan AI respuestas fiables, con base científica y avaladas por pediatras.', title_fr = 'Aussi malin qu''un médecin 🤖', body_fr = 'Des doutes sur les normes de développement après 8 mois ? Ne vous perdez pas sur Internet : obtenez d''Anacan AI une réponse fiable, scientifique et validée par des pédiatres.', title_hi = 'डॉक्टर जितना समझदार 🤖', body_hi = '8 महीने के बाद के विकास मानकों को लेकर शक है? इंटरनेट में मत खोइए, Anacan AI से भरोसेमंद, वैज्ञानिक और बाल रोग विशेषज्ञों से पुष्ट जवाब पाइए।', title_id = 'Cerdas seperti dokter 🤖', body_id = 'Ragu soal standar perkembangan setelah 8 bulan? Jangan tersesat di internet, dapatkan jawaban yang tepercaya, berbasis ilmiah, dan sesuai pandangan dokter anak dari Anacan AI.', title_ja = 'お医者さんのように賢い 🤖', body_ja = '8か月以降の発達の目安が気になりますか？ネットで迷子にならないで、Anacan AIから信頼できる、科学に基づいた、小児科医の視点の答えを受け取りましょう。', title_ko = '의사처럼 똑똑하게 🤖', body_ko = '8개월 이후의 발달 기준이 궁금한가요? 인터넷에서 헤매지 말고 Anacan AI에게서 믿을 수 있고 과학적이며 소아과 의사가 확인한 답을 받아 보세요.', title_nl = 'Zo slim als een dokter 🤖', body_nl = 'Twijfels over de ontwikkelingsnormen na 8 maanden? Verdwaal niet op internet, maar krijg een betrouwbaar, wetenschappelijk antwoord van Anacan AI dat door kinderartsen is goedgekeurd.', title_pl = 'Mądry jak lekarz 🤖', body_pl = 'Masz wątpliwości co do norm rozwoju po 8. miesiącu? Nie gub się w internecie, uzyskaj od Anacan AI wiarygodną, naukową odpowiedź potwierdzoną przez pediatrów.', title_pt = 'Inteligente como um médico 🤖', body_pt = 'Tem dúvidas sobre as normas de desenvolvimento depois dos 8 meses? Não se perca na internet: receba do Anacan AI respostas fiáveis, com base científica e validadas por pediatras.', title_sv = 'Smart som en läkare 🤖', body_sv = 'Är du osäker på utvecklingsnormerna efter 8 månader? Gå inte vilse på nätet, få pålitliga, vetenskapligt grundade och barnläkargodkända svar från Anacan AI.', title_vi = 'Thông minh như bác sĩ 🤖', body_vi = 'Mẹ băn khoăn về các mốc phát triển sau 8 tháng? Đừng lạc giữa mạng internet, hãy nhận câu trả lời đáng tin cậy, có cơ sở khoa học và được bác sĩ nhi khoa xác nhận từ Anacan AI.', title_zh = '像医生一样聪明 🤖', body_zh = '对8个月以后的发育标准有疑问？别在网上迷失方向，向Anacan AI获取可靠、有科学依据、经儿科医生认可的答案吧。' WHERE id = '0cf5cff8-d958-4ec0-b6df-6f78457976fd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Comer con los dedos 🥦', body_es = '¡Ya no quiere puré, sino coger las verduras con sus manos! Apoya sus intentos de comer solo y, aunque todo se ensucie, quédate siempre a su lado vigilando.', title_fr = 'Manger avec les doigts 🥦', body_fr = 'Il ne veut plus de purée mais préfère attraper les légumes avec ses mains ! Soutenez ses essais pour manger seul et, même si ça salit, restez toujours à côté de lui pour le surveiller.', title_hi = 'उँगलियों से खाना 🥦', body_hi = 'अब वह प्यूरी नहीं, बल्कि सब्ज़ियाँ अपने हाथों से पकड़ना चाहता है! खुद खाने की उसकी कोशिशों का साथ दीजिए, आसपास गंदगी हो तब भी उसके पास रहकर ज़रूर देखिए।', title_id = 'Makan dengan jari 🥦', body_id = 'Ia ingin memegang sayur dengan tangannya sendiri, bukan makan puree! Dukung usahanya makan sendiri, dan meski sekitarnya kotor, tetaplah di sampingnya dan awasi.', title_ja = '手づかみ食べ 🥦', body_ja = 'もうペーストではなく、野菜を自分の手で持ちたがっています！自分で食べようとする挑戦を応援しましょう。まわりが汚れても、必ずそばで見守ってください。', title_ko = '손으로 먹기 🥦', body_ko = '이제 퓌레보다 채소를 직접 손으로 잡고 싶어 해요! 스스로 먹으려는 시도를 응원하고, 주변이 지저분해져도 꼭 곁에서 지켜봐 주세요.', title_nl = 'Eten met de vingers 🥦', body_nl = 'Je baby wil geen hapjes meer, maar groente zelf vastpakken! Steun zijn pogingen om zelf te eten, ook al wordt het een boel troep, en blijf er altijd bij om toe te kijken.', title_pl = 'Jedzenie rączkami 🥦', body_pl = 'Już nie chce przecieru, tylko trzymać warzywa własną rączką! Wspieraj jego próby samodzielnego jedzenia i nawet jeśli będzie bałagan, koniecznie bądź obok i go pilnuj.', title_pt = 'Comer com os dedos 🥦', body_pt = 'Já não quer puré, quer pegar nos legumes com a própria mão! Apoie as tentativas de comer sozinho e, mesmo que se suje tudo à volta, fique sempre ao lado dele a vigiar.', title_sv = 'Äta med fingrarna 🥦', body_sv = 'Barnet vill inte längre ha puré utan vill hålla i grönsakerna själv! Stötta försöken att äta själv, och även om det blir kladdigt, stanna alltid bredvid och håll uppsikt.', title_vi = 'Tự ăn bằng tay 🥦', body_vi = 'Bé không muốn ăn món nghiền nữa mà muốn tự cầm rau củ bằng tay! Hãy ủng hộ những lần tự ăn của bé, và dù xung quanh có bẩn, nhất định phải ở bên cạnh theo dõi bé.', title_zh = '手指食物 🥦', body_zh = '宝宝已经不想只吃泥，而是想自己用手抓着蔬菜吃了！支持宝宝自主进食的尝试，哪怕周围弄脏，也一定要守在旁边看着。' WHERE id = '77b45217-21e4-402a-b5dd-d0ee28c29f05' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de noche de papá 👨‍🍼', body_es = 'No cargues tú sola con todos los despertares nocturnos. Despierta también a tu pareja: ser un equipo es repartir la responsabilidad a partes iguales. Esta noche, dormirle le toca a él.', title_fr = 'Le service de nuit de papa 👨‍🍼', body_fr = 'Ne gérez pas les réveils nocturnes toute seule. Réveillez aussi votre conjoint, être une équipe, c''est partager la responsabilité à parts égales. Cette nuit, c''est à lui de le rendormir.', title_hi = 'पापा की रात की ड्यूटी 👨‍🍼', body_hi = 'रात में जागने का बोझ अकेले मत उठाइए। अपने साथी को भी जगाइए, टीम होने का मतलब है ज़िम्मेदारी बराबर बाँटना। आज रात सुलाने की बारी उनकी है।', title_id = 'Giliran malam ayah 👨‍🍼', body_id = 'Jangan tanggung sendiri saat ia terbangun di malam hari. Bangunkan juga pasangan Anda, menjadi tim berarti berbagi tanggung jawab secara adil. Malam ini, menidurkan si kecil giliran dia.', title_ja = 'パパの夜の当番 👨‍🍼', body_ja = '夜中に起きるのを、ひとりで抱えこまないで。パートナーも起こしましょう。チームとは責任を平等に分け合うこと。今夜の寝かしつけはパートナーの番です。', title_ko = '아빠의 밤 당번 👨‍🍼', body_ko = '밤에 깨는 일을 혼자 다 감당하지 마세요. 배우자도 깨우세요, 한 팀이 된다는 건 책임을 똑같이 나누는 거예요. 오늘 밤 재우기는 배우자 차례예요.', title_nl = 'Papa''s avonddienst 👨‍🍼', body_nl = 'Draag het ''s nachts opstaan niet helemaal alleen. Maak je partner ook wakker, een team zijn betekent de verantwoordelijkheid eerlijk delen. Vannacht is het inslapen zijn taak.', title_pl = 'Nocna zmiana taty 👨‍🍼', body_pl = 'Nie dźwigaj nocnych pobudek zupełnie sama. Obudź też partnera, bycie drużyną to równy podział odpowiedzialności. Dziś usypianie należy do niego.', title_pt = 'O turno da noite do pai 👨‍🍼', body_pt = 'Não aguente sozinha todos os despertares noturnos. Acorde também o seu companheiro: ser uma equipa é dividir a responsabilidade por igual. Esta noite, a hora de deitar vai correr às mil maravilhas.', title_sv = 'Pappas nattskift 👨‍🍼', body_sv = 'Ta inte nattuppvaknandena helt ensam. Väck din partner också, att vara ett lag är att dela ansvaret lika. I natt är det hans tur att söva barnet.', title_vi = 'Ca đêm của bố 👨‍🍼', body_vi = 'Đừng một mình gánh hết những lần thức dậy ban đêm. Hãy gọi cả bố dậy, là một đội nghĩa là chia đều trách nhiệm. Tối nay việc ru bé ngủ là của bố.', title_zh = '爸爸的夜班 👨‍🍼', body_zh = '夜醒别全都自己扛。也叫醒你的伴侣，团队就是平分责任。今晚的哄睡交给他。' WHERE id = 'dd6d5f01-5a48-4f85-953e-c5e21662ae95' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se despierta gritando a media noche y no se calma? 😭', body_es = 'Usa el Análisis del llanto para saber si se trata solo de terrores nocturnos o de un dolor físico.', title_fr = 'Il se réveille en hurlant en pleine nuit et ne se calme pas ? 😭', body_fr = 'Faites écouter ses pleurs à l''Analyse des pleurs pour savoir s''il s''agit d''une simple terreur nocturne ou d''une douleur physique.', title_hi = 'आधी रात को चीखकर जागा और चुप नहीं हो रहा? 😭', body_hi = 'क्राइंग एनालिसिस से उसकी आवाज़ सुनवाइए और पता कीजिए कि यह बस नींद का डर (नाइट टेरर) है या शारीरिक दर्द।', title_id = 'Terbangun menjerit di tengah malam dan tak mau diam? 😭', body_id = 'Perdengarkan tangisannya ke Analisis Tangisan dan pastikan apakah itu hanya teror tidur atau rasa sakit fisik.', title_ja = '夜中に叫んで起きて、泣きやまない？😭', body_ja = '「泣き声分析」に泣き声を聞かせて、ただの夜驚症なのか、体の痛みなのかを確かめましょう。', title_ko = '한밤중에 비명을 지르며 깨서 그치지 않나요? 😭', body_ko = '울음 분석으로 소리를 들려주고 야경증인지 몸이 아픈 건지 확인해 보세요.', title_nl = 'Wordt je baby midden in de nacht schreeuwend wakker en stopt hij niet?  😭', body_nl = 'Laat Huilanalyse luisteren en ontdek of het gewoon een nachtmerrie is of lichamelijke pijn.', title_pl = 'W środku nocy budzi się z krzykiem i nie przestaje? 😭', body_pl = 'Pozwól Analizie płaczu posłuchać dźwięku i ustal, czy to tylko lęk nocny, czy ból fizyczny.', title_pt = 'Acordou a meio da noite aos gritos e não se cala?  😭', body_pt = 'Ponha a Análise do Choro a ouvir e confirme se é apenas um terror noturno ou uma dor física.', title_sv = 'Vaknar barnet skrikande mitt i natten och tystnar inte?  😭', body_sv = 'Låt Gråtanalys lyssna på ljudet och ta reda på om problemet bara är nattskräck eller fysisk smärta.', title_vi = 'Bé thức giấc la hét giữa đêm và không chịu nín?  😭', body_vi = 'Hãy cho Phân tích tiếng khóc nghe để biết chắc vấn đề chỉ là cơn hoảng sợ ban đêm hay là cơn đau thể chất.', title_zh = '半夜尖叫着醒来，怎么也哄不好？😭', body_zh = '用哭声分析听一听，弄清楚只是夜惊，还是身体上的疼痛。' WHERE id = '918fe7fd-3c85-49ee-b337-c52aba217614' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Bailando con la música 🎶', body_es = '¿Se balancea al ritmo cuando suena una música alegre? ¡La conexión entre oído y motricidad se está formando de maravilla! Pon una canción alegre y bailad juntos por la habitación.', title_fr = 'Il danse en musique 🎶', body_fr = 'Il se balance en rythme quand une musique joyeuse passe ? Le lien entre l''audition et la motricité se crée parfaitement ! Mettez une chanson gaie et dansez avec lui dans la pièce.', title_hi = 'संगीत पर नाच 🎶', body_hi = 'खुशनुमा संगीत बजने पर वह ताल पर झूमता है? सुनने और मोटर स्किल्स का तालमेल बढ़िया बन रहा है! कोई खुशनुमा गाना लगाइए और उसके साथ कमरे में नाचिए।', title_id = 'Menari mengikuti musik 🎶', body_id = 'Ia bergoyang mengikuti irama saat musik ceria diputar? Hubungan pendengaran dan motoriknya terbentuk dengan sempurna! Putar lagu ceria dan menarilah bersamanya di kamar.', title_ja = '音楽に合わせてダンス 🎶', body_ja = '楽しい音楽が流れると、リズムに合わせて体をゆらしますか？聞く力と体の動きがみごとにつながってきています！明るい曲をかけて、一緒に部屋で踊りましょう。', title_ko = '음악에 맞춰 춤을 🎶', body_ko = '신나는 음악이 나오면 리듬에 맞춰 몸을 흔드나요? 청각과 운동 능력이 멋지게 연결되고 있어요! 신나는 노래를 틀고 함께 방에서 춤춰 보세요.', title_nl = 'Dansen op muziek 🎶', body_nl = 'Wiegt je baby mee op het ritme als er vrolijke muziek klinkt? Gehoor en motoriek werken perfect samen! Zet een vrolijk liedje op en dans samen door de kamer.', title_pl = 'Taniec do muzyki 🎶', body_pl = 'Gdy gra wesoła muzyka, kołysze się w rytm? Połączenie słuchu i motoryki doskonale się kształtuje! Włącz wesołą piosenkę i zatańczcie razem w pokoju.', title_pt = 'Dançar ao som da música 🎶', body_pt = 'Quando toca uma música alegre, abana-se ao ritmo? A ligação entre audição e motricidade está a formar-se na perfeição! Ponha uma canção alegre e dance com ele pelo quarto.', title_sv = 'Dans till musiken 🎶', body_sv = 'Gungar barnet i takt när glad musik spelas? Kopplingen mellan hörsel och motorik tar perfekt form! Sätt på en glad låt och dansa med barnet i rummet.', title_vi = 'Nhảy theo nhạc 🎶', body_vi = 'Khi có nhạc vui, bé đung đưa theo nhịp? Mối liên kết giữa thính giác và vận động đang hình thành hoàn hảo! Hãy bật một bài hát vui nhộn và cùng bé nhảy khắp phòng.', title_zh = '随音乐起舞 🎶', body_zh = '欢快的音乐一响，宝宝就跟着节奏摇摆？听觉和动作的配合发展得很好！放一首欢快的歌，和宝宝一起在房间里跳舞吧。' WHERE id = 'b5dc2a4a-17b6-4c13-ad1b-8f6ccddc9f9b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Si ya ha comido, ahora te toca a ti.', body_es = 'Elige en Recetas saludables un tentempié con energía y recupera fuerzas tumbándote en el sofá al menos 10 minutos.', title_fr = 'Il a bien mangé, c''est votre tour.', body_fr = 'Choisissez un en-cas énergisant dans les Recettes saines et rechargez vos batteries en vous allongeant au moins 10 minutes sur le canapé.', title_hi = 'उसका पेट भर गया, अब आपकी बारी है।', body_hi = 'सेहतमंद रेसिपी से कोई ऊर्जा भरा स्नैक चुनिए और कम से कम 10 मिनट सोफ़े पर लेटकर अपनी ऊर्जा लौटाइए।', title_id = 'Kalau ia sudah kenyang, sekarang giliran Anda.', body_id = 'Pilih camilan berenergi dari Resep Sehat dan pulihkan energi Anda dengan berbaring di sofa setidaknya 10 menit.', title_ja = '赤ちゃんがお腹いっぱいなら、次はあなたの番。', body_ja = '「ヘルシーレシピ」から元気の出るおやつを選んで、せめて10分はソファに横になってエネルギーを取り戻しましょう。', title_ko = '아기가 배불리 먹었다면 이제 엄마 차례예요.', body_ko = '건강한 레시피에서 든든한 간식을 골라 먹고, 10분만이라도 소파에 누워 기운을 되찾으세요.', title_nl = 'Heeft je baby genoeg gegeten? Dan ben jij aan de beurt.', body_nl = 'Kies uit Gezonde recepten een energierijk tussendoortje en ga minstens 10 minuten op de bank liggen om weer op te laden.', title_pl = 'On najedzony, teraz twoja kolej.', body_pl = 'Wybierz w Zdrowych przepisach energetyczną przekąskę i odzyskaj siły, leżąc na kanapie choćby 10 minut.', title_pt = 'Se ele já está satisfeito, agora é a sua vez.', body_pt = 'Escolha um lanche energético nas Receitas Saudáveis e recupere a energia deitada no sofá, nem que seja 10 minutos.', title_sv = 'Är barnet mätt är det din tur.', body_sv = 'Välj ett energirikt mellanmål från Hälsosamma recept och fyll på din energi genom att ligga i soffan i minst 10 minuter.', title_vi = 'Bé no rồi thì đến lượt mẹ.', body_vi = 'Hãy chọn một món ăn nhẹ giàu năng lượng từ Công thức lành mạnh và nằm trên sofa ít nhất 10 phút để nạp lại năng lượng.', title_zh = '宝宝吃饱了，轮到你了。', body_zh = '从健康食谱里挑一款能量小食，至少在沙发上躺10分钟，恢复一下体力吧。' WHERE id = 'deba3d42-726a-4e83-bbbd-900d2aee20ad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Diario emocional 📝', body_es = 'Cuando te sientas sola y cansada, vuelca tus emociones en el Diario de ánimo. Todas las mujeres pasan por estos caminos tormentosos. ¡Eres fuerte y puedes con esto!', title_fr = 'Un journal des émotions 📝', body_fr = 'Quand vous vous sentez seule et fatiguée, déversez vos émotions dans le Journal d''humeur. Toutes les femmes passent par ces chemins tumultueux, vous êtes forte et vous y arriverez !', title_hi = 'भावनाओं की डायरी 📝', body_hi = 'जब अकेली और थकी हुई महसूस करें, तो अपनी भावनाएँ मूड डायरी में उड़ेल दीजिए। हर महिला इन तूफ़ानी रास्तों से गुज़रती है, आप मज़बूत हैं और आप यह कर सकती हैं!', title_id = 'Buku harian perasaan 📝', body_id = 'Saat merasa sendirian dan lelah, tuangkan perasaan Anda di Buku Harian Suasana Hati. Semua perempuan melewati jalan penuh badai ini, Anda kuat dan Anda pasti bisa!', title_ja = '気持ちの日記 📝', body_ja = 'ひとりぼっちで疲れたと感じたら、「気分日記」に気持ちを吐き出しましょう。どの女性もこの嵐のような道を通ります。あなたは強いし、きっと乗り越えられます！', title_ko = '마음 일기 📝', body_ko = '외롭고 지칠 때는 기분 일기에 감정을 쏟아 내세요. 모든 여성이 이 폭풍 같은 길을 지나요. 당신은 강하고, 해낼 수 있어요!', title_nl = 'Een gevoelsdagboek 📝', body_nl = 'Voel je je alleen en moe? Laat je gevoelens de vrije loop in je Stemmingsdagboek. Alle vrouwen gaan door deze stormen, je bent sterk en je kunt het!', title_pl = 'Dziennik emocji 📝', body_pl = 'Gdy czujesz się samotna i zmęczona, przelej swoje uczucia do Dziennika nastroju. Wszystkie kobiety przechodzą przez te burzliwe drogi, jesteś silna i dasz radę!', title_pt = 'Diário emocional 📝', body_pt = 'Quando se sentir sozinha e cansada, despeje o que sente no Diário de Humor. Todas as mulheres passam por estes caminhos tempestuosos: é forte e vai conseguir!', title_sv = 'Känslodagbok 📝', body_sv = 'När du känner dig ensam och trött, häll ut dina känslor i Humördagboken. Alla kvinnor går igenom de här stormiga vägarna, du är stark och du klarar det här!', title_vi = 'Nhật ký cảm xúc 📝', body_vi = 'Khi thấy cô đơn và mệt mỏi, hãy trút cảm xúc vào Nhật ký tâm trạng. Người phụ nữ nào cũng đi qua những chặng đường giông bão này, mẹ mạnh mẽ và mẹ làm được!', title_zh = '情绪日记 📝', body_zh = '觉得孤单又疲惫时，就把感受倾诉在心情日记里。每个女人都会走过这些风雨路，你很坚强，你一定能做到！' WHERE id = '7580f5d5-67e6-4fe8-b318-8dd1f6c00cd6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Sigue el picor de encías? 🦷', body_es = '¿Siempre tiene los dedos en la boca y babea mucho? Es hora de volver a sacar los mordedores del congelador.', title_fr = 'Les gencives démangent toujours ? 🦷', body_fr = 'Il a toujours les doigts dans la bouche et bave beaucoup ? C''est le moment de ressortir les anneaux de dentition rafraîchis au congélateur.', title_hi = 'मसूड़ों की खुजली जारी है? 🦷', body_hi = 'उँगलियाँ हमेशा मुँह में हैं और बहुत लार टपक रही है? फ़्रीज़र में रखी टीथिंग रिंग फिर से इस्तेमाल करने का समय है।', title_id = 'Gusi masih gatal? 🦷', body_id = 'Jarinya terus di mulut dan air liurnya banyak? Saatnya kembali mengeluarkan teether yang disimpan di freezer.', title_ja = '歯ぐきのむずむずが続いている？🦷', body_ja = '指がいつも口の中にあって、よだれがたくさん出ていますか？冷凍庫で冷やした歯固めの出番が、またやってきました。', title_ko = '잇몸 가려움이 계속되나요? 🦷', body_ko = '손가락이 늘 입에 있고 침을 많이 흘리나요? 냉동실에 넣어 둔 치발기를 다시 꺼낼 때예요.', title_nl = 'Jeukt het tandvlees nog steeds? 🦷', body_nl = 'Zitten de vingertjes steeds in de mond en kwijlt je baby veel? Tijd om de in de vriezer gekoelde bijtringen weer tevoorschijn te halen.', title_pl = 'Swędzenie dziąseł nie mija? 🦷', body_pl = 'Paluszki ciągle w buzi i mnóstwo śliny? Czas znowu sięgnąć po gryzaki schłodzone w zamrażarce.', title_pt = 'A comichão nas gengivas continua? 🦷', body_pt = 'Tem sempre os dedos na boca e baba-se muito? É altura de voltar aos mordedores guardados no congelador.', title_sv = 'Kliar det fortfarande i gommen? 🦷', body_sv = 'Är fingrarna ständigt i munnen och dreglar barnet mycket? Dags att ta fram bitringarna från frysen igen.', title_vi = 'Nướu vẫn còn ngứa? 🦷', body_vi = 'Bé luôn đưa ngón tay vào miệng và chảy nhiều nước dãi? Đến lúc lại lấy gặm nướu mát từ ngăn đá ra rồi.', title_zh = '牙龈还在痒？🦷', body_zh = '手指总在嘴里，口水流个不停？又该拿出冷冻室里冰过的牙胶了。' WHERE id = '90ae683e-61a6-4dd5-b894-186c95367ff3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ha llorado y ha estado inquieto todo el día? La solución es muy sencilla: mira Tiempo y ropa, súbele al carrito y sal enseguida al parque. La naturaleza es el calmante más rápido.', body_fr = 'Il a pleuré et s''est agité toute la journée ? La solution est simple : consultez Météo et tenue, installez-le dans la poussette et filez au parc. La nature est le calmant le plus rapide.', body_hi = 'दिनभर रोता और बेचैन रहा? उपाय बहुत आसान है: मौसम और कपड़े देखिए, स्ट्रॉलर में बिठाइए और तुरंत पार्क चलिए। प्रकृति सबसे जल्दी शांत करती है।', body_id = 'Ia menangis dan rewel seharian? Solusinya sangat sederhana: cek Cuaca dan Pakaian, dudukkan ia di stroller, dan segera pergi ke taman. Alam adalah penenang tercepat.', body_ja = '1日中泣いてぐずっていた？解決法はとてもシンプル：「天気と服装」を見て、ベビーカーに乗せ、すぐに公園へ。自然はいちばん早く落ち着かせてくれます。', body_ko = '하루 종일 울고 보챘나요? 해결책은 아주 간단해요: 날씨와 옷차림을 확인하고 유모차에 태워 바로 공원으로 나가세요. 자연이 가장 빠른 진정제예요.', body_nl = 'Heeft je baby de hele dag gehuild en was hij onrustig? De oplossing is simpel: kijk in Weer en kleding, zet hem in de kinderwagen en ga meteen naar het park. De natuur kalmeert het snelst.', body_pl = 'Cały dzień płakał i był niespokojny? Rozwiązanie jest bardzo proste: sprawdź Pogodę i ubiór, posadź go w wózku i od razu idźcie do parku. Natura uspokaja najszybciej.', body_pt = 'Chorou e esteve inquieto o dia todo? A solução é muito simples: veja o Tempo e Roupa, ponha-o no carrinho e vá já para o parque. A natureza é o calmante mais rápido.', body_sv = 'Har barnet gråtit och varit oroligt hela dagen? Lösningen är enkel: kolla Väder och kläder, lägg barnet i vagnen och gå direkt till parken. Naturen lugnar snabbast.', body_vi = 'Bé khóc và quấy cả ngày? Cách giải quyết rất đơn giản: xem Thời tiết và trang phục, đặt bé vào xe đẩy và ra công viên ngay. Thiên nhiên là cách xoa dịu nhanh nhất.', body_zh = '宝宝哭闹烦躁了一整天？办法很简单：看看天气穿衣，放进婴儿车，马上去公园。大自然是最快的安抚剂。' WHERE id = 'b9bfa71c-cf95-4768-adc9-c82fe1e676ac' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Juego de permanencia del objeto! 🧸', body_es = 'Esconde su juguete bajo una manta y deja que lo encuentre.', title_fr = 'Le jeu de la permanence de l''objet ! 🧸', body_fr = 'Cachez son jouet sous une couverture et laissez-le le trouver.', title_hi = 'चीज़ों के बने रहने का खेल! 🧸', body_hi = 'उसका खिलौना किसी कपड़े के नीचे छिपाइए और उसे ढूँढने दीजिए।', title_id = 'Permainan benda tetap ada! 🧸', body_id = 'Sembunyikan mainannya di bawah kain dan biarkan ia menemukannya.', title_ja = '見えなくてもあるよ遊び！🧸', body_ja = 'おもちゃを布の下に隠して、見つけさせてあげましょう。', title_ko = '대상 영속성 놀이! 🧸', body_ko = '장난감을 천 아래에 숨기고 찾게 해 주세요.', title_nl = 'Een spelletje over dingen die blijven bestaan! 🧸', body_nl = 'Verstop zijn speeltje onder een doek en laat hem het vinden.', title_pl = 'Zabawa w stałość przedmiotu! 🧸', body_pl = 'Schowaj zabawkę pod kocykiem i pozwól mu ją znaleźć.', title_pt = 'O jogo da permanência dos objetos! 🧸', body_pt = 'Esconda o brinquedo debaixo de um pano e deixe-o encontrá-lo.', title_sv = 'Leken om att saker finns kvar! 🧸', body_sv = 'Göm leksaken under en filt och låt barnet hitta den.', title_vi = 'Trò chơi đồ vật vẫn tồn tại! 🧸', body_vi = 'Hãy giấu đồ chơi của bé dưới một tấm khăn và để bé tự tìm.', title_zh = '物体恒存游戏！🧸', body_zh = '把宝宝的玩具藏在布下面，让宝宝自己找出来吧。' WHERE id = '0a0b2a9c-f56c-4830-8b42-dd0901fc3b1d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Grita cuando le quitas el juguete?🧸', body_es = 'Su sentido de la propiedad se hace más fuerte. Es una parte importante de la formación de su carácter.', title_fr = 'Il crie quand vous lui prenez son jouet ? 🧸', body_fr = 'Son sens de la propriété se renforce. C''est une partie importante de la formation de son caractère.', title_hi = 'खिलौना लेने पर चिल्लाता है? 🧸', body_hi = 'उसमें ''मेरा'' होने का एहसास मज़बूत हो रहा है। यह स्वभाव बनने का एक अहम हिस्सा है।', title_id = 'Menjerit saat mainannya diambil?🧸', body_id = 'Rasa memilikinya makin kuat. Ini bagian penting dari pembentukan karakternya.', title_ja = 'おもちゃを取り上げると叫ぶ？🧸', body_ja = '「自分のもの」という感覚が強くなっています。これは性格が形づくられる大切な一部です。', title_ko = '장난감을 빼면 소리를 지르나요?🧸', body_ko = '소유욕이 강해지고 있어요. 성격 형성의 중요한 부분이에요.', title_nl = 'Schreeuwt je baby als je zijn speeltje afpakt?🧸', body_nl = 'Het gevoel van bezit wordt sterker. Dat is een belangrijk onderdeel van de vorming van zijn karakter.', title_pl = 'Krzyczy, gdy zabierasz mu zabawkę? 🧸', body_pl = 'Poczucie własności się wzmacnia. To ważna część kształtowania się charakteru.', title_pt = 'Grita quando lhe tira o brinquedo das mãos?🧸', body_pt = 'O sentido de posse está a ficar mais forte. É uma parte importante da formação do carácter.', title_sv = 'Skriker barnet när du tar leksaken ifrån det?🧸', body_sv = 'Känslan för ägande blir starkare. Det är en viktig del av att karaktären formas.', title_vi = 'Bé la hét khi bị lấy đồ chơi?🧸', body_vi = 'Ý thức sở hữu của bé đang mạnh lên. Đây là một phần quan trọng trong quá trình hình thành tính cách.', title_zh = '拿走玩具就尖叫？🧸', body_zh = '宝宝的物权意识在增强。这是性格形成的重要一环。' WHERE id = '2e5279b4-ad3c-4da7-866e-49a5932c0601' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La leche materna sigue siendo lo principal! 🍼', body_es = 'Aunque ya tome alimentación complementaria, usa el temporizador de tomas para asegurarte de que cubre su necesidad diaria de leche.', title_fr = 'Le lait maternel reste essentiel ! 🍼', body_fr = 'Malgré la diversification, lancez le minuteur de repas pour vous assurer que ses besoins quotidiens en lait sont couverts.', title_hi = 'माँ का दूध अब भी सबसे अहम है! 🍼', body_hi = 'ऊपरी आहार के बावजूद फ़ीडिंग टाइमर चालू करके पक्का कीजिए कि रोज़ की दूध की ज़रूरत पूरी हो रही है।', title_id = 'ASI tetap yang utama! 🍼', body_id = 'Meski sudah MPASI, nyalakan timer menyusui dan pastikan kebutuhan susu hariannya terpenuhi.', title_ja = '母乳・ミルクはまだ主役！🍼', body_ja = '離乳食を始めても、授乳タイマーを使って1日に必要なミルクの量をとれているか確かめましょう。', title_ko = '모유는 여전히 중요해요! 🍼', body_ko = '이유식을 하더라도 수유 타이머를 켜서 하루 수유량이 충분한지 확인하세요.', title_nl = 'Moedermelk is nog steeds de basis! 🍼', body_nl = 'Ook met bijvoeding: zet de voedingstimer aan en zorg ervoor dat je baby dagelijks genoeg melk krijgt.', title_pl = 'Mleko mamy wciąż jest podstawą! 🍼', body_pl = 'Mimo rozszerzania diety włączaj timer karmienia i upewnij się, że dzienne zapotrzebowanie na mleko jest zaspokojone.', title_pt = 'O leite materno continua a ser a base! 🍼', body_pt = 'Mesmo com a diversificação alimentar, ligue o temporizador de alimentação e confirme que as necessidades diárias de leite estão cobertas.', title_sv = 'Bröstmjölken är fortfarande grunden! 🍼', body_sv = 'Trots smakportionerna, se till att det dagliga mjölkbehovet täcks genom att starta matningstimern.', title_vi = 'Sữa mẹ vẫn là chính! 🍼', body_vi = 'Dù đã ăn dặm, hãy bật Hẹn giờ cho bú để chắc chắn bé được đáp ứng đủ nhu cầu sữa mỗi ngày.', title_zh = '母乳仍然是主角！🍼', body_zh = '即使添加了辅食，也要用喂养计时器确认宝宝每天的奶量需求得到满足。' WHERE id = 'd2ac515d-c34a-47d7-a082-82f89c2863e8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Leed un libro juntos! 📖', body_es = 'Los libros con sonidos y colores le llaman mucho la atención. Enriquece todavía más estos momentos de lectura con los consejos del Blog.', title_fr = 'Lisez un livre ensemble ! 📖', body_fr = 'Les livres sonores et colorés attirent beaucoup son attention. Enrichissez encore ces moments de lecture éducatifs grâce aux conseils des Blogs.', title_hi = 'साथ मिलकर किताब पढ़िए! 📖', body_hi = 'आवाज़ वाली और रंगीन किताबें उसका ध्यान खूब खींचती हैं। किताब पढ़ने के इन सीख भरे पलों को ब्लॉग की सलाहों से और भी समृद्ध बनाइए।', title_id = 'Membaca buku bersama! 📖', body_id = 'Buku yang berbunyi dan berwarna sangat menarik perhatiannya. Perkaya momen membaca yang mendidik ini dengan tips dari Blog.', title_ja = '一緒に絵本を読もう！📖', body_ja = '音が出るカラフルな絵本は、赤ちゃんの注意をぐっと引きつけます。ブログのアドバイスで、絵本を読む学びの時間をもっと豊かにしましょう。', title_ko = '함께 책을 읽어요! 📖', body_ko = '소리 나는 알록달록한 책은 아기의 관심을 끌어요. 블로그의 팁으로 책 읽는 배움의 시간을 더 풍성하게 만들어 보세요.', title_nl = 'Lees samen een boekje! 📖', body_nl = 'Boekjes met geluid en kleur trekken echt zijn aandacht. Maak de leerzame momenten van het voorlezen nog rijker met de tips in de Blogs.', title_pl = 'Czytajcie razem książeczki! 📖', body_pl = 'Grające i kolorowe książeczki bardzo przyciągają jego uwagę. Wzbogać te pouczające chwile czytania poradami z Bloga.', title_pt = 'Leiam um livro juntos! 📖', body_pt = 'Os livros com sons e cores chamam-lhe muito a atenção. Enriqueça os momentos educativos da leitura com as sugestões dos Blogues.', title_sv = 'Läs böcker tillsammans! 📖', body_sv = 'Böcker med ljud och färger fångar verkligen barnets uppmärksamhet. Gör de lärorika lässtunderna ännu rikare med tipsen i Bloggar.', title_vi = 'Cùng nhau đọc sách! 📖', body_vi = 'Sách có âm thanh và nhiều màu sắc rất thu hút bé. Hãy làm phong phú thêm những giờ đọc sách bổ ích với các gợi ý trong mục Blog.', title_zh = '一起读书吧！📖', body_zh = '有声音、色彩丰富的书特别能吸引宝宝的注意力。用博客里的建议，让你们的亲子阅读时光更加丰富吧。' WHERE id = '31a887b1-fde3-4a67-a32c-13cc6764d41e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El temporizador de Anacan recuerda por ti el pecho derecho o izquierdo. ¡Empieza ya la toma con el temporizador!', body_fr = 'Le minuteur Anacan retient pour vous le sein droit ou gauche. Lancez maintenant la tétée avec le minuteur !', body_hi = 'Anacan टाइमर आपकी जगह दायाँ/बायाँ स्तन याद रखता है। अभी टाइमर के साथ फ़ीडिंग शुरू कीजिए!', body_id = 'Timer Anacan mengingat payudara kanan/kiri untuk Anda. Mulai menyusui sekarang dengan timer!', body_ja = 'Anacanのタイマーが、あなたの代わりに左右どちらのおっぱいかを覚えておいてくれます。今すぐタイマーで授乳を始めましょう！', body_ko = 'Anacan 타이머가 엄마 대신 왼쪽/오른쪽 가슴을 기억해 줘요. 지금 타이머로 수유를 시작하세요!', body_nl = 'De timer van Anacan onthoudt voor jou welke borst, links of rechts, aan de beurt is. Start de voeding nu met de timer!', body_pl = 'Timer Anacan zapamięta za ciebie, z której piersi karmiłaś: lewej czy prawej. Włącz teraz karmienie z timerem!', body_pt = 'O temporizador do Anacan lembra-se por si se foi o peito direito ou o esquerdo. Comece já a mamada com o temporizador!', body_sv = 'Anacan-timern kommer ihåg höger eller vänster bröst åt dig. Starta matningen med timern nu!', body_vi = 'Hẹn giờ của Anacan sẽ nhớ giúp mẹ bên ngực trái hay phải. Hãy bắt đầu cữ bú với hẹn giờ ngay bây giờ!', body_zh = 'Anacan计时器会替你记住左右侧乳房。现在就用计时器开始喂奶吧！' WHERE id = 'a82a604d-9504-4486-86ea-c38998236871' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Creamos el hábito de beber agua. 💧', body_es = 'No olvides ofrecerle agua junto con la alimentación complementaria. Descubre en Productos recomendados qué vasos de aprendizaje son más adecuados.', title_fr = 'On prend l''habitude de boire de l''eau. 💧', body_fr = 'N''oubliez pas de lui proposer de l''eau avec les repas solides. Découvrez quelles tasses d''apprentissage conviennent le mieux dans les Produits recommandés.', title_hi = 'पानी पीने की आदत डाल रहे हैं 💧', body_hi = 'ऊपरी आहार के साथ पानी देना मत भूलिए। कौन से सिप्पी कप ज़्यादा सही हैं, यह सुझाए गए प्रोडक्ट में देखिए।', title_id = 'Membangun kebiasaan minum air. 💧', body_id = 'Jangan lupa menawarkan air bersamaan dengan MPASI. Temukan botol minum yang paling cocok di Produk Rekomendasi.', title_ja = 'お水を飲む習慣をつけよう。💧', body_ja = '離乳食と一緒にお水をあげるのを忘れずに。どのストローマグが合うかは「おすすめ商品」で見つけましょう。', title_ko = '물 마시는 습관 만들기 💧', body_ko = '이유식과 함께 물을 주는 것도 잊지 마세요. 어떤 빨대컵이 알맞은지 추천 제품에서 찾아보세요.', title_nl = 'We leren water drinken. 💧', body_nl = 'Vergeet niet om naast de bijvoeding ook water aan te bieden. Vind in Aanbevolen producten welke drinkbekers het best passen.', title_pl = 'Uczymy się pić wodę. 💧', body_pl = 'Nie zapominaj podawać wody razem ze stałymi pokarmami. Jakie kubki niekapki są najlepsze, sprawdzisz w Polecanych produktach.', title_pt = 'Estamos a criar o hábito de beber água. 💧', body_pt = 'Não se esqueça de oferecer água juntamente com a comida. Descubra nos Produtos Recomendados os copos de aprendizagem mais adequados.', title_sv = 'Vi skapar en vana att dricka vatten. 💧', body_sv = 'Glöm inte att erbjuda vatten tillsammans med smakportionerna. Hitta vilka pipmuggar som passar bäst i Rekommenderade produkter.', title_vi = 'Tập thói quen uống nước. 💧', body_vi = 'Đừng quên cho bé uống nước cùng với bữa ăn dặm. Tìm loại cốc tập uống phù hợp nhất trong Sản phẩm gợi ý.', title_zh = '培养喝水的习惯 💧', body_zh = '吃辅食时别忘了给宝宝喝点水。去推荐商品里看看哪种学饮杯更合适吧。' WHERE id = 'd7cab28d-37d6-4301-8e4d-28dfd96b83ab' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ven, ven 👏', body_es = '¿Da palmas o abre los brazos hacia ti? Es una forma de comunicación maravillosa. Abrázale.', title_fr = 'Viens, viens 👏', body_fr = 'Il tape des mains ou vous tend les bras ? C''est une magnifique forme de communication. Serrez-le dans vos bras.', title_hi = 'आओ, आओ 👏', body_hi = 'ताली बजाता है या आपकी ओर बाँहें फैलाता है? यह बातचीत का शानदार तरीका है। उसे गले लगाइए।', title_id = 'Sini, sini 👏', body_id = 'Ia bertepuk tangan atau membuka lengannya ke arah Anda? Ini bentuk komunikasi yang luar biasa. Peluklah ia.', title_ja = 'おいで、おいで 👏', body_ja = '手をたたいたり、あなたに向かって両手を広げたりしていますか？すばらしいコミュニケーションです。ぎゅっと抱きしめてあげましょう。', title_ko = '이리 와, 이리 와 👏', body_ko = '손뼉을 치거나 엄마에게 두 팔을 벌리나요? 멋진 소통 방식이에요. 꼭 안아 주세요.', title_nl = 'Kom maar, kom maar 👏', body_nl = 'Klapt je baby in zijn handjes of strekt hij zijn armpjes naar je uit? Een geweldige vorm van communicatie. Knuffel hem.', title_pl = 'Chodź, chodź 👏', body_pl = 'Klaszcze w rączki albo wyciąga do ciebie ramionka? To wspaniała forma komunikacji. Przytul go.', title_pt = 'Anda, anda 👏', body_pt = 'Bate palmas ou abre os braços na sua direção? É uma forma de comunicação fantástica. Dê-lhe um abraço.', title_sv = 'Kom, kom 👏', body_sv = 'Klappar barnet händerna eller sträcker ut armarna mot dig? Det är en fantastisk form av kommunikation. Krama barnet.', title_vi = 'Lại đây nào 👏', body_vi = 'Bé vỗ tay hay giang tay về phía mẹ? Đây là một hình thức giao tiếp tuyệt vời. Hãy ôm bé vào lòng.', title_zh = '来，来 👏', body_zh = '宝宝在拍手，或者朝你张开双臂？这是很棒的交流方式。抱抱宝宝吧。' WHERE id = '6122dba2-692e-45e2-8027-9ab67ba2bf07' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Crece tan rápido... Mientras duerme, haz una foto de sus rasgos dulces y tranquilos y guárdala de recuerdo.', body_fr = 'Il grandit si vite... Pendant qu''il dort, prenez en photo ses doux traits paisibles et gardez-en le souvenir.', body_hi = 'वह इतनी तेज़ी से बड़ा हो रहा है... सोते समय उसके प्यारे, शांत चेहरे की तस्वीर लीजिए और यादों में सहेजिए।', body_id = 'Ia tumbuh begitu cepat... Foto wajahnya yang manis dan tenang saat tidur dan simpan sebagai kenangan.', body_ja = '本当にあっという間に大きくなりますね...眠っている間のかわいくておだやかな顔を写真に撮って、思い出に残しましょう。', body_ko = '아기가 너무 빨리 자라요... 잠든 사이 그 사랑스럽고 평온한 얼굴을 사진으로 찍어 추억으로 남기세요.', body_nl = 'Je baby groeit zo snel... Maak een foto van dat lieve, rustige slaapgezichtje en bewaar het als herinnering.', body_pl = 'Rośnie tak szybko... Zrób zdjęcie jego słodkiej, spokojnej buzi podczas snu i zachowaj je na pamiątkę.', body_pt = 'Cresce tão depressa... Enquanto dorme, fotografe aqueles traços doces e tranquilos e guarde a recordação.', body_sv = 'Barnet växer så fort... Fotografera de söta, lugna ansiktsdragen när det sover och spara minnet.', body_vi = 'Bé lớn nhanh quá... Khi bé ngủ, hãy chụp lại gương mặt ngọt ngào, bình yên ấy để làm kỷ niệm.', body_zh = '宝宝长得太快了……趁宝宝睡着，拍下那张甜美安详的小脸，留作纪念吧。' WHERE id = 'a73ae95c-98a0-4201-9af1-960893ecd116' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Tienes mil preguntas sobre su desarrollo? Escribe a Anacan AI y recibe consejos pediátricos precisos.', body_fr = 'Mille questions sur son développement vous trottent dans la tête ? Écrivez à Anacan AI et obtenez des conseils pédiatriques précis.', body_hi = 'दिमाग में विकास को लेकर हज़ारों सवाल हैं? Anacan AI को लिखिए और बाल रोग विशेषज्ञ जैसी सटीक सलाह पाइए।', body_id = 'Ada ribuan pertanyaan tentang perkembangannya di kepala Anda? Tanyakan ke Anacan AI dan dapatkan saran pediatri yang tepat.', body_ja = '発達について頭の中が疑問でいっぱい？Anacan AIに聞いて、小児科医の視点からの正確なアドバイスを受け取りましょう。', body_ko = '성장에 관한 질문이 머릿속에 가득한가요? Anacan AI에게 물어 정확한 소아과 조언을 받아 보세요.', body_nl = 'Zit je hoofd vol met vragen over de ontwikkeling? Schrijf naar Anacan AI en krijg precieze adviezen van een kinderarts.', body_pl = 'Masz w głowie tysiące pytań o rozwój? Napisz do Anacan AI i otrzymaj rzetelne porady pediatryczne.', body_pt = 'Tem mil perguntas sobre o desenvolvimento na cabeça? Escreva ao Anacan AI e receba conselhos pediátricos precisos.', body_sv = 'Har du tusentals frågor om utvecklingen i huvudet? Skriv till Anacan AI och få exakta barnläkarråd.', body_vi = 'Trong đầu có hàng nghìn câu hỏi về sự phát triển của bé? Hãy hỏi Anacan AI để nhận lời khuyên nhi khoa chính xác.', body_zh = '脑子里有成千上万个关于发育的问题？问问Anacan AI，获得准确的儿科建议。' WHERE id = 'b8c9eaea-1257-487d-8647-7c1cb6d70a3a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Preparando el día 250! 🌟', body_es = '¡Mañana llega una gran cifra! ¡250 días justos! Crea un pequeño ambiente de fiesta en casa y prepárate para sentir el orgullo de esta cifra.', title_fr = 'On prépare le 250e jour ! 🌟', body_fr = 'Demain, c''est un grand chiffre ! Pile 250 jours ! Créez une petite ambiance de fête à la maison et préparez-vous à savourer la fierté de ce chiffre.', title_hi = '250वें दिन की तैयारी! 🌟', body_hi = 'कल एक बड़ा आँकड़ा है! पूरे 250 दिन! घर में छोटा सा जश्न का माहौल बनाइए और इस आँकड़े पर गर्व महसूस करने के लिए तैयार हो जाइए।', title_id = 'Persiapan hari ke-250! 🌟', body_id = 'Besok angka yang besar! Tepat 250 hari! Ciptakan suasana pesta kecil di rumah dan bersiaplah merasakan bangganya angka ini.', title_ja = '250日目の準備！🌟', body_ja = '明日は大きな数字！ちょうど250日です！おうちに小さなお祝いムードをつくって、この数字を誇らしく迎える準備をしましょう。', title_ko = '250일 준비! 🌟', body_ko = '내일은 큰 숫자예요! 딱 250일! 집에 작은 축제 분위기를 만들고 이 숫자의 뿌듯함을 느낄 준비를 하세요.', title_nl = 'Voorbereiding op de 250e dag! 🌟', body_nl = 'Morgen is een groot getal! Precies 250 dagen! Breng een klein feestelijk sfeertje in huis en maak je klaar om trots te zijn op dit getal.', title_pl = 'Przygotowania do 250. dnia! 🌟', body_pl = 'Jutro wielka liczba! Równo 250 dni! Stwórz w domu małą świąteczną atmosferę i przygotuj się, by poczuć dumę z tej liczby.', title_pt = 'Preparar o dia 250! 🌟', body_pt = 'Amanhã é um número importante! 250 dias certos! Crie em casa um pequeno ambiente de festa e prepare-se para sentir o orgulho deste número.', title_sv = 'Förberedelser inför dag 250! 🌟', body_sv = 'I morgon är det en stor siffra! Precis 250 dagar! Skapa lite feststämning hemma och gör dig redo att känna stoltheten över den här siffran.', title_vi = 'Chuẩn bị cho ngày thứ 250! 🌟', body_vi = 'Ngày mai là một con số lớn! Tròn 250 ngày! Hãy tạo không khí lễ hội nho nhỏ trong nhà và sẵn sàng tự hào về con số này.', title_zh = '准备迎接第250天！🌟', body_zh = '明天是个大数字！整整250天！在家营造一点节日氛围，准备好为这个数字骄傲吧。' WHERE id = '19dff725-11f8-467a-b784-f2971b302ba0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hoy no se limpia 🛑', body_es = '¿Estás cansada? Díselo a tu pareja. Hoy no hay comida casera. ¡Hoy es el día de descanso de mamá!', title_fr = 'Pas de ménage aujourd''hui 🛑', body_fr = 'Fatiguée ? Dites-le à votre conjoint. Aujourd''hui, pas de cuisine. Aujourd''hui, c''est le jour de repos de maman !', title_hi = 'आज सफ़ाई की छुट्टी 🛑', body_hi = 'थक गई हैं? अपने साथी को बताइए। आज घर का खाना नहीं बनेगा। आज माँ की छुट्टी का दिन है!', title_id = 'Hari ini tidak ada bersih-bersih 🛑', body_id = 'Lelah? Beri tahu pasangan Anda. Hari ini tidak ada masak. Hari ini hari istirahat Bunda!', title_ja = '今日はお掃除なし 🛑', body_ja = '疲れていますか？パートナーに伝えましょう。今日は手料理はなし。今日はママの休日です！', title_ko = '오늘은 청소 금지 🛑', body_ko = '지쳤나요? 배우자에게 말하세요. 오늘은 집밥이 없어요. 오늘은 엄마가 쉬는 날이에요!', title_nl = 'Vandaag geen schoonmaak 🛑', body_nl = 'Ben je moe? Zeg het tegen je partner. Vandaag geen kookwerk. Vandaag is mama''s rustdag!', title_pl = 'Dziś bez sprzątania 🛑', body_pl = 'Jesteś zmęczona? Powiedz o tym partnerowi. Dziś bez gotowania. Dziś dzień odpoczynku mamy!', title_pt = 'Hoje não há limpezas 🛑', body_pt = 'Está cansada? Diga ao seu companheiro. Hoje não há comida caseira. Hoje é o dia de descanso da mãe!', title_sv = 'Ingen städning i dag 🛑', body_sv = 'Är du trött? Säg till din partner. I dag blir det ingen hemlagad mat. I dag är det mammas vilodag!', title_vi = 'Hôm nay không dọn dẹp 🛑', body_vi = 'Mẹ mệt rồi? Hãy nói với bố. Hôm nay không nấu nướng. Hôm nay là ngày nghỉ của mẹ!', title_zh = '今天不打扫 🛑', body_zh = '累了吗？告诉伴侣。今天不做饭。今天是妈妈的休息日！' WHERE id = 'c304b9f3-2045-4d2f-b423-1096223f0f83' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche crea en Cuentos inteligentes la historia de un niño valiente y listo y crea un ambiente tranquilo.', body_fr = 'Ce soir, créez une ambiance calme en imaginant dans les Contes intelligents l''histoire d''un enfant courageux et malin.', body_hi = 'आज शाम स्मार्ट कहानियों में एक बहादुर और समझदार बच्चे की कहानी बनाकर शांत माहौल तैयार कीजिए।', body_id = 'Malam ini, ciptakan suasana tenang dengan membuat kisah anak yang berani dan cerdas di Dongeng Pintar.', body_ja = '今夜は「スマートおはなし」で勇敢でかしこい子どものお話をつくって、おだやかな雰囲気をつくりましょう。', body_ko = '오늘 저녁 스마트 동화에서 용감하고 똑똑한 아이의 이야기를 만들어 차분한 분위기를 만들어 보세요.', body_nl = 'Maak vanavond in Slimme sprookjes het verhaal van een dapper en slim kind en zorg voor een rustige sfeer.', body_pl = 'Dziś wieczorem stwórz w Mądrych bajkach historię o odważnym i mądrym dziecku i zbuduj spokojną atmosferę.', body_pt = 'Esta noite, crie nas Histórias Inteligentes a história de uma criança corajosa e esperta e prepare um ambiente calmo.', body_sv = 'I kväll, skapa en lugn stämning genom att göra sagan om ett modigt och klokt barn i Smarta sagor.', body_vi = 'Tối nay hãy tạo câu chuyện về một em bé dũng cảm và thông minh trong Truyện cổ tích thông minh để có một không gian yên bình.', body_zh = '今晚在智能故事里创作一个勇敢又聪明的孩子的故事，营造安静的氛围吧。' WHERE id = 'e01d3a10-f5c2-40e8-8168-d7a86ab3c73d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Disfruta del orgullo de estos 250 días🥂', body_es = 'Esta noche, cuando tu bebé se duerma, ¡no olvides celebrar con tu pareja esta enorme victoria en equipo!', title_fr = 'Savourez la fierté de ces 250 jours 🥂', body_fr = 'Ce soir, quand bébé dormira, n''oubliez pas de fêter cette immense victoire d''équipe avec votre conjoint !', title_hi = '250 दिनों पर गर्व कीजिए 🥂', body_hi = 'आज शाम बच्चे के सोने के बाद अपने साथी के साथ इस बड़ी टीम जीत का जश्न मनाना मत भूलिए!', title_id = 'Rasakan bangganya 250 hari🥂', body_id = 'Malam ini, setelah si kecil tidur, jangan lupa merayakan kemenangan besar kalian sebagai tim bersama pasangan!', title_ja = '250日を誇りに思って🥂', body_ja = '今夜は赤ちゃんが寝たら、パートナーとこのチームの大きな勝利をお祝いするのを忘れずに！', title_ko = '250일의 뿌듯함을 누려요🥂', body_ko = '오늘 저녁 아이가 잠든 뒤 배우자와 함께 이 거대한 팀의 승리를 축하하는 것도 잊지 마세요!', title_nl = 'Geniet van de trots van 250 dagen🥂', body_nl = 'Vergeet vanavond, als je baby slaapt, niet om deze enorme overwinning als team met je partner te vieren!', title_pl = 'Poczujcie dumę z 250 dni 🥂', body_pl = 'Dziś wieczorem, gdy maluszek zaśnie, nie zapomnij uczcić z partnerem tego ogromnego drużynowego zwycięstwa!', title_pt = 'Sinta o orgulho destes 250 dias🥂', body_pt = 'Esta noite, depois de o bebé adormecer, não se esqueça de celebrar com o seu companheiro esta enorme vitória de equipa!', title_sv = 'Känn stoltheten över 250 dagar🥂', body_sv = 'I kväll, när barnet har somnat, glöm inte att fira den här enorma lagsegern med din partner!', title_vi = 'Tự hào về 250 ngày🥂', body_vi = 'Tối nay, sau khi bé ngủ, đừng quên cùng bố ăn mừng chiến thắng to lớn của cả đội nhé!', title_zh = '为250天骄傲 🥂', body_zh = '今晚宝宝睡着后，别忘了和伴侣一起庆祝这个了不起的团队胜利！' WHERE id = '561e1f8b-1a7d-4ace-9ef9-bd3f43b083d2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡250 DÍAS INCREÍBLES! 🎉', body_es = '¿Te lo puedes creer? ¡Lleváis justo 250 días recorriendo juntos este camino tormentoso y mágico! ¡Celébralo con un sticker especial en la Sesión de fotos del bebé!', title_fr = '250 JOURS MAGNIFIQUES ! 🎉', body_fr = 'Vous y croyez ? Cela fait pile 250 jours que vous avancez ensemble sur ce chemin agité et magique ! Célébrez ce moment avec un sticker spécial dans la Séance photo bébé !', title_hi = 'शानदार 250 दिन! 🎉', body_hi = 'यकीन होता है? पूरे 250 दिन से आप साथ मिलकर यह तूफ़ानी और जादुई सफ़र तय कर रहे हैं! बेबी फ़ोटोशूट में खास स्टिकर से इस पल को रोशन कीजिए!', title_id = '250 HARI YANG LUAR BIASA! 🎉', body_id = 'Percaya tidak? Sudah tepat 250 hari kalian menapaki perjalanan penuh badai dan keajaiban ini bersama! Rayakan momen ini dengan stiker khusus di Sesi Foto Bayi!', title_ja = 'すばらしい250日！🎉', body_ja = '信じられますか？ちょうど250日間、この嵐のような魔法の道を一緒に歩んできました！「ベビーフォトセッション」の特別なステッカーで、この瞬間を彩りましょう！', title_ko = '멋진 250일! 🎉', body_ko = '믿어지나요? 꼬박 250일 동안 이 폭풍 같고 마법 같은 길을 함께 걸어왔어요! 아기 사진 촬영에서 특별한 스티커로 이 순간을 빛내세요!', title_nl = 'GEWELDIGE 250 DAGEN! 🎉', body_nl = 'Kun je het geloven? Al precies 250 dagen lopen jullie samen deze stormachtige en magische weg! Vier dit moment met een speciale sticker in Babyfotoshoot!', title_pl = 'WSPANIAŁE 250 DNI! 🎉', body_pl = 'Wierzysz w to? Od równych 250 dni razem idziecie tą burzliwą i magiczną drogą! Uświetnij tę chwilę specjalną naklejką w Sesji zdjęciowej dziecka!', title_pt = '250 DIAS FANTÁSTICOS! 🎉', body_pt = 'Acredita? Há exatamente 250 dias que percorrem juntos este caminho tempestuoso e mágico! Celebre o momento com um autocolante especial na Sessão Fotográfica do Bebé!', title_sv = 'FANTASTISKA 250 DAGAR! 🎉', body_sv = 'Kan du tro det? I precis 250 dagar har ni gått den här stormiga och magiska vägen tillsammans! Fira stunden med ett speciellt klistermärke i Babyfotografering!', title_vi = '250 NGÀY TUYỆT VỜI! 🎉', body_vi = 'Mẹ tin được không? Đã tròn 250 ngày cả nhà cùng nhau bước trên hành trình đầy giông bão mà kỳ diệu này! Hãy làm khoảnh khắc này thêm rực rỡ với nhãn dán đặc biệt trong Chụp ảnh cho bé!', title_zh = '精彩的250天！🎉', body_zh = '你敢相信吗？你们一起走过这段风雨又神奇的旅程已经整整250天了！在宝宝写真里用专属贴纸庆祝这一刻吧！' WHERE id = '8f3f2d4b-5b88-42ed-95c1-db9f61e1f218' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Recuerda los miedos de los primeros días. ¡Y ahora eres la mamá de un peque que intenta ponerse de pie! ¡Siéntete orgullosa de ti!', body_fr = 'Rappelez-vous vos peurs des premiers jours. Et maintenant, vous êtes la maman d''un enfant qui essaie de se mettre debout ! Soyez fière de vous !', body_hi = 'शुरुआती दिनों के अपने डर याद कीजिए। और अब आप खड़े होने की कोशिश करते बच्चे की माँ हैं! खुद पर गर्व कीजिए!', body_id = 'Ingat ketakutan Anda di hari-hari pertama. Sekarang Anda ibu dari anak yang sedang belajar berdiri! Banggalah pada diri sendiri!', body_ja = '最初のころの不安を思い出してみて。今では立ち上がろうとしている赤ちゃんのママです！自分を誇りに思って！', body_ko = '처음 며칠의 두려움을 떠올려 보세요. 그리고 지금은 일어서려는 아이의 엄마예요! 스스로를 자랑스러워하세요!', body_nl = 'Denk terug aan je angsten in de eerste dagen. En nu ben je de mama van een kindje dat probeert te gaan staan! Wees trots op jezelf!', body_pl = 'Przypomnij sobie swoje lęki z pierwszych dni. A teraz jesteś mamą malucha, który próbuje wstawać! Bądź z siebie dumna!', body_pt = 'Lembre-se dos medos dos primeiros dias. E agora é mãe de um bebé que já tenta pôr-se de pé! Orgulhe-se de si!', body_sv = 'Minns dina rädslor från de första dagarna. Och nu är du mamma till ett barn som försöker resa sig upp! Var stolt över dig själv!', body_vi = 'Hãy nhớ lại những nỗi lo của ngày đầu. Còn giờ mẹ đã là mẹ của một em bé đang tập đứng! Hãy tự hào về mình!', body_zh = '回想一下最初那些日子的恐惧。看看现在，你已经是一个正在学站的宝宝的妈妈了！为自己骄傲吧！' WHERE id = 'e0e283b4-8f62-4d84-98d9-c186d1f67042' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Trampas en el suelo 🧸', body_es = 'Las habitaciones ya son su zona de exploración. Llega a todas partes arrastrándose. Es el momento perfecto para revisar la seguridad de la casa.', title_fr = 'Les pièges au sol 🧸', body_fr = 'Les pièces sont désormais sa zone d''exploration. Il va partout à quatre pattes. C''est le moment idéal pour vérifier la sécurité de la maison.', title_hi = 'फ़र्श पर छिपे खतरे 🧸', body_hi = 'अब कमरे उसके लिए खोज का मैदान हैं। वह खिसककर हर जगह पहुँच जाता है। घर की सुरक्षा पर नज़र डालने का यही सही समय है।', title_id = 'Jebakan di lantai 🧸', body_id = 'Kini setiap ruangan adalah zona penjelajahannya. Ia merayap ke mana-mana. Saatnya memeriksa keamanan rumah.', title_ja = '床のわな 🧸', body_ja = 'もう部屋は赤ちゃんの探検ゾーン。はいはいでどこへでも行けます。家の安全を見直すのにぴったりのタイミングです。', title_ko = '바닥의 함정 🧸', body_ko = '이제 집 안 모든 방이 아기의 탐험 구역이에요. 기어서 어디든 가요. 집 안 안전을 점검할 딱 좋은 때예요.', title_nl = 'Valkuilen op de vloer 🧸', body_nl = 'De kamers zijn nu één grote ontdekkingszone voor je baby. Kruipend komt hij overal. Hét moment om de veiligheid in huis na te lopen.', title_pl = 'Pułapki na podłodze 🧸', body_pl = 'Pokoje są teraz dla niego strefą odkryć. Raczkując, dociera wszędzie. To najwyższy czas, by sprawdzić bezpieczeństwo w domu.', title_pt = 'Armadilhas no chão 🧸', body_pt = 'Agora as divisões da casa são a sua zona de exploração. A rastejar, chega a todo o lado. É a altura ideal para rever a segurança da casa.', title_sv = 'Fällor på golvet 🧸', body_sv = 'Rummen är nu barnets upptäcktszon. Det kryper och tar sig överallt. Nu är det hög tid att gå igenom säkerheten i hemmet.', title_vi = 'Những cái bẫy trên sàn 🧸', body_vi = 'Giờ các căn phòng là khu vực khám phá của bé. Bé bò khắp nơi. Đây chính là lúc rà soát lại mức độ an toàn trong nhà.', title_zh = '地上的陷阱 🧸', body_zh = '现在房间就是宝宝的探索区。宝宝爬着哪儿都能去。是时候好好检查一下家里的安全了。' WHERE id = '01890bf6-ab5a-403c-96d2-696020ff0863' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Prueba de la gravedad 🥄', body_es = '¿Tira a propósito lo que tiene en la mano y te mira? Solo está aprendiendo la relación causa-efecto. Ten paciencia y únete al juego.', title_fr = 'Le test de la gravité 🥄', body_fr = 'Il fait exprès de lâcher ce qu''il tient et vous regarde ? Il apprend simplement la relation de cause à effet. Soyez patiente et entrez dans le jeu.', title_hi = 'गुरुत्वाकर्षण का टेस्ट 🥄', body_hi = 'हाथ की चीज़ जानबूझकर नीचे गिराकर आपको देखता है? वह बस कारण-परिणाम का रिश्ता सीख रहा है। धैर्य रखिए और खेल में शामिल हो जाइए।', title_id = 'Uji gravitasi 🥄', body_id = 'Ia sengaja menjatuhkan benda di tangannya lalu menatap Anda? Ia hanya sedang mempelajari sebab dan akibat. Bersabarlah dan ikut bermain.', title_ja = '重力テスト 🥄', body_ja = '手に持ったものをわざと落として、あなたを見ていますか？原因と結果の関係を学んでいるだけです。気長に、一緒に遊んであげましょう。', title_ko = '중력 실험 🥄', body_ko = '손에 든 걸 일부러 떨어뜨리고 엄마를 바라보나요? 원인과 결과를 배우는 중이에요. 인내심을 갖고 놀이에 함께해 주세요.', title_nl = 'De zwaartekrachttest 🥄', body_nl = 'Laat je baby expres iets vallen en kijkt hij je dan aan? Hij leert gewoon over oorzaak en gevolg. Heb geduld en doe mee met het spelletje.', title_pl = 'Test grawitacji 🥄', body_pl = 'Celowo rzuca to, co trzyma, na podłogę i patrzy na ciebie? Po prostu uczy się związku przyczyny i skutku. Bądź cierpliwa i przyłącz się do zabawy.', title_pt = 'Teste da gravidade 🥄', body_pt = 'Atira de propósito o que tem na mão e olha para si? Está apenas a aprender a relação de causa e efeito. Tenha paciência e entre no jogo.', title_sv = 'Tyngdkraftstestet 🥄', body_sv = 'Släpper barnet med flit det det håller i på golvet och tittar på dig? Det lär sig bara om orsak och verkan. Ha tålamod och var med i leken.', title_vi = 'Thử nghiệm trọng lực 🥄', body_vi = 'Bé cố tình thả đồ trong tay xuống đất rồi nhìn mẹ? Bé chỉ đang học về quan hệ nhân quả. Hãy kiên nhẫn và cùng chơi với bé.', title_zh = '重力测试 🥄', body_zh = '宝宝故意把手里的东西扔到地上再看着你？宝宝只是在学习因果关系。耐心一点，加入游戏吧。' WHERE id = '64b9a99f-59f6-4495-b5ab-9a4825037afc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La realidad del café frío ☕', body_es = '¿Hoy también se te ha enfriado el café? No pasa nada, eres una heroína que no para ni un momento. Escribe con humor el caos de hoy en el Diario de ánimo.', title_fr = 'La réalité du café froid ☕', body_fr = 'Votre café a encore refroidi aujourd''hui ? Ce n''est pas grave, vous êtes une héroïne qui ne s''arrête jamais. Racontez le chaos du jour avec humour dans le Journal d''humeur.', title_hi = 'ठंडी कॉफ़ी की सच्चाई ☕', body_hi = 'आज भी आपकी कॉफ़ी ठंडी हो गई? कोई बात नहीं, आप बिना रुके चलने वाली हीरो हैं। आज की अफ़रा-तफ़री को मज़ाकिया अंदाज़ में मूड डायरी में लिखिए।', title_id = 'Realita kopi yang dingin ☕', body_id = 'Hari ini kopi Anda dingin lagi? Tidak apa-apa, Anda pahlawan yang tak pernah berhenti bergerak. Tulis kekacauan hari ini dengan penuh humor di Buku Harian Suasana Hati.', title_ja = '冷めたコーヒーの現実 ☕', body_ja = '今日もコーヒーが冷めてしまった？大丈夫、あなたは休みなく動き続けるヒーローです。「気分日記」に今日のカオスをユーモアたっぷりに書いてみましょう。', title_ko = '식어 버린 커피의 현실 ☕', body_ko = '오늘도 커피가 식었나요? 괜찮아요, 쉬지 않고 움직이는 영웅이잖아요. 기분 일기에 오늘의 혼돈을 유머 있게 적어 보세요.', title_nl = 'De realiteit van koude koffie ☕', body_nl = 'Is je koffie vandaag weer koud geworden? Geeft niet, je bent een heldin die nooit stilstaat. Schrijf de chaos van vandaag met humor op in je Stemmingsdagboek.', title_pl = 'Rzeczywistość zimnej kawy ☕', body_pl = 'Dziś znowu wystygła ci kawa? Nic nie szkodzi, jesteś bohaterką w nieustannym ruchu. Opisz dzisiejszy chaos z humorem w Dzienniku nastroju.', title_pt = 'A realidade do café frio ☕', body_pt = 'Hoje o café voltou a arrefecer? Não faz mal, é uma heroína que nunca para. Escreva com humor no Diário de Humor o caos de hoje.', title_sv = 'Det kalla kaffets verklighet ☕', body_sv = 'Kallnade kaffet i dag igen? Det gör inget, du är en hjälte som aldrig står still. Skriv ner dagens kaos med humor i Humördagboken.', title_vi = 'Sự thật về tách cà phê nguội ☕', body_vi = 'Hôm nay cà phê của mẹ lại nguội? Không sao, mẹ là người hùng không ngừng nghỉ. Hãy viết lại sự hỗn loạn hôm nay một cách hài hước vào Nhật ký tâm trạng.', title_zh = '咖啡又凉了 ☕', body_zh = '今天咖啡又凉了？没关系，你是一刻不停的超级英雄。用幽默的口吻把今天的混乱写进心情日记吧。' WHERE id = 'b34bf0e6-4ffb-4b59-90eb-68d99299dee1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El lujo de una ducha a solas 🛀', body_es = 'Correr detrás de tu peque todo el día te ha dejado los brazos sin fuerzas. Pasa el turno a tu pareja y regálate 15 minutos de terapia de agua sin interrupciones.', title_fr = 'Le luxe d''une douche en solo 🛀', body_fr = 'Courir après lui toute la journée vous a épuisé les bras. Passez le relais à votre conjoint et offrez-vous 15 minutes de thérapie par l''eau sans interruption.', title_hi = 'अकेले नहाने का सुख 🛀', body_hi = 'दिनभर उसके पीछे भागते-भागते आपकी बाँहें थक गई हैं। अपने साथी को बारी सौंपिए और खुद को 15 मिनट की बिना रुकावट वाली जल थेरेपी तोहफ़े में दीजिए।', title_id = 'Mewahnya mandi sendirian 🛀', body_id = 'Mengejarnya seharian membuat lengan Anda lemas. Serahkan giliran kepada pasangan dan hadiahi diri Anda terapi air 15 menit tanpa gangguan.', title_ja = 'ひとりでシャワーのぜいたく 🛀', body_ja = '1日中赤ちゃんを追いかけて、腕がくたくた。パートナーにバトンタッチして、自分に15分間のじゃまされないシャワータイムをプレゼントしましょう。', title_ko = '혼자만의 샤워라는 사치 🛀', body_ko = '하루 종일 아기를 쫓아다니느라 팔에 힘이 다 빠졌죠. 배우자에게 당번을 넘기고 나에게 15분의 방해 없는 물 테라피를 선물하세요.', title_nl = 'De luxe van alleen douchen 🛀', body_nl = 'De hele dag achter je kleintje aan rennen heeft je armen uitgeput. Draag de dienst over aan je partner en geef jezelf 15 minuten ongestoorde watertherapie cadeau.', title_pl = 'Luksus samotnego prysznica 🛀', body_pl = 'Bieganie za nim cały dzień odebrało ci siły w rękach. Przekaż zmianę partnerowi i podaruj sobie 15 minut nieprzerwanej terapii wodą.', title_pt = 'O luxo de um duche sozinha 🛀', body_pt = 'Andar atrás dele o dia todo deixou-lhe os braços sem forças. Passe o turno ao seu companheiro e ofereça a si própria 15 minutos de terapia de água sem interrupções.', title_sv = 'Lyxen att duscha ensam 🛀', body_sv = 'Att springa efter barnet hela dagen har tagit all kraft ur armarna. Lämna över skiftet till din partner och ge dig själv 15 minuters ostörd vattenterapi.', title_vi = 'Đặc quyền được tắm một mình 🛀', body_vi = 'Chạy theo bé cả ngày khiến tay mẹ rã rời. Hãy giao ca cho bố và tặng mình 15 phút thư giãn với nước không bị ai làm phiền.', title_zh = '独自洗澡的奢侈 🛀', body_zh = '追着宝宝跑了一整天，胳膊都没劲了。把班交给伴侣，送自己15分钟不被打扰的淋浴时光吧。' WHERE id = '026d603e-c612-41a2-9525-f4d00f730669' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Paseos junto al sofá 🛋️', body_es = '¿Se agarra a los muebles para ponerse de pie y da pasitos de lado? Es el paso más grande hacia la independencia. No dejes de registrar este momento en el Seguimiento del desarrollo.', title_fr = 'Balades le long du canapé 🛋️', body_fr = 'Il se hisse en s''agrippant aux meubles et se déplace sur le côté ? C''est le plus grand pas vers l''autonomie. Notez absolument ce moment dans le Suivi de développement.', title_hi = 'सोफ़े के किनारे सैर 🛋️', body_hi = 'फ़र्नीचर पकड़कर खड़ा होता है और बगल में कदम बढ़ाता है? यह आत्मनिर्भरता की ओर सबसे बड़ा कदम है। ग्रोथ ट्रैकर में इस पल को ज़रूर दर्ज कीजिए।', title_id = 'Berjalan di tepi sofa 🛋️', body_id = 'Ia berdiri berpegangan pada perabot dan melangkah ke samping? Ini langkah terbesar menuju kemandirian. Jangan lupa catat momen ini di Pelacak Perkembangan.', title_ja = 'ソファ沿いのお散歩 🛋️', body_ja = '家具につかまって立ち上がり、横歩きしていますか？ひとりでできるへの、いちばん大きな一歩です。「発達トラッカー」にこの瞬間をぜひ記録しましょう。', title_ko = '소파 옆 걸음마 🛋️', body_ko = '가구를 잡고 일어서서 옆으로 걸음을 옮기나요? 독립을 향한 가장 큰 걸음이에요. 성장 기록에 이 순간을 꼭 남기세요.', title_nl = 'Langs de bank lopen 🛋️', body_nl = 'Trekt je baby zich op aan meubels en zet hij zijwaartse stapjes? Dat is de grootste stap naar zelfstandigheid. Noteer dit moment zeker in de Groeitracker.', title_pl = 'Spacery wzdłuż kanapy 🛋️', body_pl = 'Trzymając się mebli, wstaje i chodzi bokiem? To największy krok w stronę samodzielności. Koniecznie zapisz ten moment w Śledzeniu rozwoju.', title_pt = 'Passeios à beira do sofá 🛋️', body_pt = 'Agarra-se aos móveis para se pôr de pé e dá passinhos de lado? É o maior passo rumo à independência. Registe sem falta este momento no Registo de Desenvolvimento.', title_sv = 'Promenader längs soffan 🛋️', body_sv = 'Drar sig barnet upp med hjälp av möblerna och tar steg i sidled? Det är det största steget mot självständighet. Anteckna absolut ögonblicket i Utvecklingsspåraren.', title_vi = 'Men theo sofa 🛋️', body_vi = 'Bé bám vào đồ đạc để đứng lên và bước ngang? Đây là bước tiến lớn nhất hướng tới tự lập. Nhất định hãy ghi lại khoảnh khắc này trong Theo dõi phát triển.', title_zh = '扶着沙发走 🛋️', body_zh = '宝宝扶着家具站起来，还能横着挪步？这是迈向独立最大的一步。一定要在发育追踪里记下这一刻。' WHERE id = '1c49ef6a-c84a-47c7-a1bc-352a17833a3d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Reconoce su nombre! 🗣️', body_es = '¿Se gira a mirar cuando le llamas por su nombre desde otra habitación? Su oído y su comprensión van de maravilla. Háblale a menudo diciendo su nombre.', title_fr = 'Il reconnaît son prénom ! 🗣️', body_fr = 'Quand vous l''appelez depuis une autre pièce, il se retourne et regarde ? Son audition et sa compréhension se perfectionnent. Parlez-lui souvent en l''appelant par son prénom.', title_hi = 'अपना नाम पहचानता है! 🗣️', body_hi = 'दूसरे कमरे से नाम पुकारने पर मुड़कर देखता है? सुनने और समझने की क्षमता बढ़िया हो रही है। उसका नाम लेकर उससे अक्सर बातें कीजिए।', title_id = 'Ia mengenali namanya! 🗣️', body_id = 'Ia menoleh saat Anda memanggil namanya dari ruangan lain? Pendengaran dan pemahamannya makin sempurna. Sering-seringlah menyebut namanya saat mengobrol dengannya.', title_ja = '自分の名前がわかる！🗣️', body_ja = '別の部屋から名前を呼ぶと、振り向いて見ますか？聞く力と理解する力がぐんぐん育っています。名前を呼びながら、たくさん話しかけてあげましょう。', title_ko = '자기 이름을 알아요! 🗣️', body_ko = '다른 방에서 이름을 부르면 돌아보나요? 청각과 이해력이 멋지게 자라고 있어요. 이름을 자주 불러 주며 대화를 나눠 보세요.', title_nl = 'Hij herkent zijn naam! 🗣️', body_nl = 'Draait je baby zich om als je zijn naam vanuit een andere kamer roept? Gehoor en begrip worden steeds beter. Noem vaak zijn naam als je met hem praat.', title_pl = 'Zna swoje imię! 🗣️', body_pl = 'Gdy wołasz go po imieniu z innego pokoju, odwraca się i patrzy? Słuch i rozumienie są coraz lepsze. Często rozmawiaj z nim, używając jego imienia.', title_pt = 'Reconhece o nome! 🗣️', body_pt = 'Quando o chama pelo nome de outra divisão, vira-se e olha? A audição e a compreensão estão a ficar perfeitas. Converse com ele dizendo muitas vezes o nome dele.', title_sv = 'Barnet känner igen sitt namn! 🗣️', body_sv = 'Vänder sig barnet om och tittar när du ropar dess namn från ett annat rum? Hörseln och förståelsen blir allt bättre. Prata ofta med barnet och säg dess namn.', title_vi = 'Bé nhận ra tên mình! 🗣️', body_vi = 'Khi mẹ gọi tên từ phòng khác, bé quay lại nhìn? Thính giác và nhận thức của bé đang hoàn thiện. Hãy thường xuyên gọi tên khi trò chuyện với bé.', title_zh = '认得自己的名字了！🗣️', body_zh = '在另一个房间叫宝宝的名字，宝宝会转过头来看？听力和理解力越来越好了。和宝宝说话时多叫叫宝宝的名字吧。' WHERE id = 'b5c1158f-415c-414a-b3ec-c9879bf6e9d9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despertares nocturnos 🌙', body_es = '¿Con la llegada de los dientes ha empezado a despertarse a menudo por la noche? Ten paciencia, le molestan las encías. Hazle sentir que estás a su lado.', title_fr = 'Réveils nocturnes 🌙', body_fr = 'À l''approche des dents, il se réveille souvent la nuit ? Soyez patiente, ses gencives le font souffrir. Faites-lui sentir que vous êtes là.', title_hi = 'रात में जागना 🌙', body_hi = 'दाँत निकलने के समय रात में बार-बार जागने लगा है? धैर्य रखिए, मसूड़ों का दर्द उसे परेशान कर रहा है। उसे महसूस कराइए कि आप पास हैं।', title_id = 'Terbangun di malam hari 🌙', body_id = 'Menjelang tumbuh gigi, ia mulai sering terbangun di malam hari? Bersabarlah, nyeri gusi membuatnya tidak nyaman. Biarkan ia merasakan bahwa Anda ada di dekatnya.', title_ja = '夜中に起きる 🌙', body_ja = '歯が生えはじめるころ、夜中によく起きるようになりましたか？歯ぐきの痛みがつらいのです。気長に、そばにいることを感じさせてあげましょう。', title_ko = '밤에 깨는 아기 🌙', body_ko = '이가 나려는 무렵 밤에 자주 깨기 시작했나요? 잇몸 통증 때문에 힘든 거니 인내심을 가져 주세요. 곁에 있다는 걸 느끼게 해 주세요.', title_nl = '''s Nachts wakker 🌙', body_nl = 'Wordt je baby ''s nachts vaker wakker nu de tandjes eraan komen? Heb geduld, de pijn in het tandvlees zit hem dwars. Laat hem voelen dat je bij hem bent.', title_pl = 'Nocne pobudki 🌙', body_pl = 'Przy ząbkowaniu zaczął często budzić się w nocy? Bądź cierpliwa, dokuczają mu bolące dziąsła. Pokaż mu, że jesteś obok.', title_pt = 'Despertares noturnos 🌙', body_pt = 'Com os dentes a chegar, começou a acordar muitas vezes à noite? Tenha paciência, as dores nas gengivas incomodam-no. Mostre-lhe que está ao lado dele.', title_sv = 'Nattuppvaknanden 🌙', body_sv = 'Har barnet börjat vakna ofta på nätterna nu när tänderna är på väg? Ha tålamod, det är ont i tandköttet som stör. Låt barnet känna att du finns där.', title_vi = 'Thức giấc ban đêm 🌙', body_vi = 'Sắp mọc răng nên bé hay thức giấc ban đêm? Hãy kiên nhẫn, cơn đau nướu đang làm bé khó chịu. Hãy để bé cảm nhận mẹ luôn ở bên.', title_zh = '夜醒 🌙', body_zh = '快长牙时，夜里经常醒来？耐心一点，牙龈疼让宝宝不舒服。让宝宝感受到你就在身边。' WHERE id = '21f7df85-0fd1-4e90-a27b-52045487116f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un momento de calma ☕', body_es = 'El desorden de la habitación no se va a ir a ninguna parte. Mientras tu peque juega solo, no corras a limpiar. Siéntate en el sofá y no hagas nada durante 10 minutos.', title_fr = 'Un moment de calme ☕', body_fr = 'Le désordre de la pièce ne va pas s''envoler. Quand il joue seul, ne vous précipitez pas sur le ménage. Asseyez-vous sur le canapé et ne faites rien pendant 10 minutes.', title_hi = 'सुकून का पल ☕', body_hi = 'कमरे का बिखराव कहीं नहीं भागेगा। जब बच्चा अपने आप खेल रहा हो, तुरंत सफ़ाई में मत लगिए। सोफ़े पर बैठिए और 10 मिनट कुछ मत कीजिए।', title_id = 'Momen tenang ☕', body_id = 'Kamar yang berantakan tidak akan ke mana-mana. Saat ia bermain sendiri, jangan langsung bersih-bersih. Duduklah di sofa dan jangan lakukan apa-apa selama 10 menit.', title_ja = 'ほっとひと息 ☕', body_ja = '部屋の散らかりはどこにも逃げません。赤ちゃんがひとりで遊んでいる間に、すぐ片づけを始めないで。ソファに座って、10分間何もしないでいましょう。', title_ko = '고요한 순간 ☕', body_ko = '어질러진 방은 어디 가지 않아요. 아이가 혼자 노는 동안 바로 청소하러 가지 마세요. 소파에 앉아 10분 동안 아무것도 하지 마세요.', title_nl = 'Een moment van rust ☕', body_nl = 'De rommel in de kamer loopt niet weg. Ren niet meteen naar het schoonmaakwerk als je kleintje zelf speelt. Ga op de bank zitten en doe 10 minuten helemaal niets.', title_pl = 'Chwila ciszy ☕', body_pl = 'Bałagan w pokoju nigdzie nie ucieknie. Gdy maluszek bawi się sam, nie rzucaj się od razu do sprzątania. Usiądź na kanapie i przez 10 minut nic nie rób.', title_pt = 'Um momento de silêncio ☕', body_pt = 'A desarrumação do quarto não vai fugir. Enquanto o bebé brinca sozinho, não corra logo para as limpezas. Sente-se no sofá e não faça nada durante 10 minutos.', title_sv = 'En stund av stillhet ☕', body_sv = 'Stöket i rummet springer ingenstans. Rusa inte iväg och städa direkt medan barnet leker på egen hand. Sätt dig i soffan och gör ingenting i 10 minuter.', title_vi = 'Khoảnh khắc bình yên ☕', body_vi = 'Căn phòng bừa bộn cũng chẳng chạy đi đâu. Khi bé tự chơi, mẹ đừng vội lao vào dọn dẹp. Hãy ngồi xuống ghế sofa và không làm gì cả trong 10 phút.', title_zh = '片刻宁静 ☕', body_zh = '房间乱也跑不了。宝宝自己玩的时候，别急着去打扫。坐在沙发上，什么都不做10分钟吧。' WHERE id = 'b80481ba-8798-458c-83d8-f359b3802548' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuentos con voz 🎶', body_es = 'Ninguna app puede sustituir la nana de una madre. Esta noche, simplemente abrázale contra tu pecho y cántale bajito su nana favorita.', title_fr = 'Des histoires à écouter 🎶', body_fr = 'Aucune application ne remplace la berceuse d''une maman. Ce soir, serrez-le simplement contre vous et chantez doucement sa berceuse préférée.', title_hi = 'सुनने वाली कहानियाँ 🎶', body_hi = 'कोई भी ऐप माँ की लोरी की जगह नहीं ले सकता। आज शाम बस उसे सीने से लगाइए और धीरे से उसकी पसंदीदा लोरी गाइए।', title_id = 'Dongeng bersuara 🎶', body_id = 'Tidak ada aplikasi yang bisa menggantikan nina bobo seorang ibu. Malam ini, cukup dekap ia di dada dan nyanyikan pelan lagu kesukaannya.', title_ja = '音で楽しむお話 🎶', body_ja = 'どんなアプリも、ママの子守唄にはかないません。今夜はただ胸に抱きよせて、お気に入りの子守唄をそっと歌ってあげましょう。', title_ko = '소리로 듣는 동화 🎶', body_ko = '어떤 앱도 엄마의 자장가를 대신할 수 없어요. 오늘 밤은 아기를 가슴에 꼭 안고 가장 좋아하는 자장가를 나지막이 불러 주세요.', title_nl = 'Voorleesverhalen 🎶', body_nl = 'Geen app kan het slaapliedje van een moeder vervangen. Houd je kleintje vanavond gewoon tegen je borst en zing zachtjes zijn lievelingsliedje.', title_pl = 'Bajki do słuchania 🎶', body_pl = 'Żadna aplikacja nie zastąpi kołysanki mamy. Dziś wieczorem po prostu przytul go do piersi i cichutko zaśpiewaj jego ulubioną kołysankę.', title_pt = 'Histórias em áudio 🎶', body_pt = 'Nenhuma app substitui a canção de embalar da mãe. Esta noite, aconchegue-o ao peito e cante baixinho a canção de que ele mais gosta.', title_sv = 'Ljudsagor 🎶', body_sv = 'Ingen app kan ersätta mammas vaggvisa. I kväll, håll bara barnet tätt intill bröstet och sjung tyst den vaggvisa barnet tycker mest om.', title_vi = 'Truyện kể bằng giọng nói 🎶', body_vi = 'Không ứng dụng nào thay được lời ru của mẹ. Tối nay chỉ cần ôm bé vào lòng và khẽ hát bài ru bé thích nhất.', title_zh = '有声故事 🎶', body_zh = '没有任何应用能取代妈妈的摇篮曲。今晚就把宝宝抱在怀里，轻轻唱宝宝最爱的那首吧。' WHERE id = '125f59de-0644-435e-8593-de05b7cc7065' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Fiesta del puré 🥣', body_es = '¿Tiene la cara, la nariz y hasta el pelo llenos de comida? En vez de enfadarte, inmortaliza este momento tan tierno con la Sesión de fotos del bebé.', title_fr = 'La fête de la purée 🥣', body_fr = 'Son visage, son nez et même ses cheveux sont couverts de nourriture ? Au lieu de vous énerver, immortalisez ce moment adorable avec la Séance photo bébé.', title_hi = 'प्यूरी का उत्सव 🥣', body_hi = 'चेहरा, नाक, यहाँ तक कि बाल भी खाने से सने हैं? गुस्सा होने के बजाय इस प्यारे पल को बेबी फ़ोटोशूट से हमेशा के लिए सहेजिए।', title_id = 'Festival puree 🥣', body_id = 'Wajah, hidung, bahkan rambutnya belepotan makanan? Daripada kesal, abadikan momen menggemaskan ini dengan Sesi Foto Bayi.', title_ja = 'ペーストのお祭り 🥣', body_ja = '顔も鼻も、髪の毛までごはんだらけ？イライラする代わりに、このかわいい瞬間を「ベビーフォトセッション」で残しましょう。', title_ko = '퓌레 축제 🥣', body_ko = '얼굴, 코, 머리카락까지 음식 범벅인가요? 짜증 내는 대신 이 사랑스러운 순간을 아기 사진 촬영으로 영원히 남기세요.', title_nl = 'Een hapjesfestival 🥣', body_nl = 'Zit het eten op zijn gezicht, zijn neus en zelfs in zijn haar? Word niet boos, maar leg dit schattige moment voor altijd vast met Babyfotoshoot.', title_pl = 'Festiwal przecierów 🥣', body_pl = 'Buzia, nos, a nawet włosy całe w jedzeniu? Zamiast się denerwować, uwiecznij tę uroczą chwilę w Sesji zdjęciowej dziecka.', title_pt = 'Festival de puré 🥣', body_pt = 'O rosto, o nariz e até o cabelo ficaram cheios de comida? Em vez de se irritar, eternize este momento adorável com a Sessão Fotográfica do Bebé.', title_sv = 'Purépartaj 🥣', body_sv = 'Är ansiktet, näsan och till och med håret nedkladdat med mat? I stället för att bli irriterad, förevig det här gulliga ögonblicket med Babyfotografering.', title_vi = 'Lễ hội món nghiền 🥣', body_vi = 'Mặt, mũi, cả tóc của bé cũng dính đầy đồ ăn? Thay vì bực mình, hãy lưu giữ khoảnh khắc đáng yêu này bằng Chụp ảnh cho bé.', title_zh = '果泥派对 🥣', body_zh = '脸上、鼻子上，连头发上都沾满了食物？与其生气，不如用宝宝写真永久留住这个可爱的瞬间。' WHERE id = '63093c63-3ea0-4bb2-90bb-318617d51b7e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorando con las encías 🦷', body_es = '¿Lo muerde todo con fuerza y babea mucho? Controla el proceso en el Seguimiento de dentición. Los aros de dentición refrescantes son los salvadores de estos días.', title_fr = 'Exploration avec les gencives 🦷', body_fr = 'Il mâchouille tout avec force et bave beaucoup ? Suivez le processus dans le Suivi des dents. Les anneaux de dentition rafraîchissants sont les sauveurs de ces journées.', title_hi = 'मसूड़ों से खोजबीन 🦷', body_hi = 'हर चीज़ ज़ोर से चबा रहा है और लार बह रही है? दाँत निकलने के ट्रैकर में इस प्रक्रिया पर नज़र रखिए। ठंडक देने वाली टीथिंग रिंग इन दिनों की सबसे बड़ी मददगार हैं।', title_id = 'Menjelajah gusi 🦷', body_id = 'Ia mengunyah semua benda dengan kuat dan air liurnya menetes? Pantau prosesnya di Pelacak Tumbuh Gigi. Teether yang menyejukkan adalah penyelamat di hari-hari ini.', title_ja = '歯ぐきで探検 🦷', body_ja = 'なんでも力いっぱいかんで、よだれがたくさん出ていますか？「歯の生え始めトラッカー」で様子を管理しましょう。冷やせる歯固めリングがこの時期の救世主です。', title_ko = '잇몸으로 탐험 중 🦷', body_ko = '무엇이든 세게 깨물고 침을 흘리나요? 이앓이 기록에서 과정을 관리하세요. 시원한 치아발육기가 요즘의 구원자예요.', title_nl = 'Ontdekken met het tandvlees 🦷', body_nl = 'Kauwt je baby fel op alles en kwijlt hij? Houd alles bij in de Tandjestracker. Verkoelende bijtringen zijn de redders van deze dagen.', title_pl = 'Odkrywanie dziąsłami 🦷', body_pl = 'Mocno gryzie wszystko i leci mu ślinka? Śledź ten proces w narzędziu do śledzenia ząbkowania. Chłodzące gryzaki to ratunek w te dni.', title_pt = 'Exploração com as gengivas 🦷', body_pt = 'Mastiga tudo com força e baba-se? Acompanhe o processo no Registo de Dentição. As argolas de dentição refrescantes são as salvadoras destes dias.', title_sv = 'Upptäcktsfärd med tandköttet 🦷', body_sv = 'Tuggar barnet häftigt på allt och dreglar? Håll koll på förloppet i Tandspåraren. Kylande bitringar räddar de här dagarna.', title_vi = 'Khám phá bằng nướu 🦷', body_vi = 'Bé gặm mọi thứ thật mạnh và chảy nhiều nước dãi? Hãy theo dõi quá trình trong Theo dõi mọc răng. Vòng gặm nướu làm mát là cứu tinh của những ngày này.', title_zh = '用牙龈探索 🦷', body_zh = '什么都使劲啃，口水直流？用出牙追踪记录整个过程。冰凉的牙胶是这段日子的救星。' WHERE id = '104420b5-a415-4abb-81d8-7f7b520d18bd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te sientes sola y cansada? Respira hondo. Tu pareja y tú sois los héroes más fuertes de estos días tormentosos.', body_fr = 'Vous vous sentez seule et fatiguée ? Respirez profondément. Votre conjoint et vous êtes les héros les plus forts de ces journées agitées.', body_hi = 'अकेली और थकी हुई महसूस कर रही हैं? गहरी साँस लीजिए। आप और आपके साथी इन तूफ़ानी दिनों के सबसे मज़बूत हीरो हैं।', body_id = 'Merasa sendirian dan lelah? Tarik napas dalam-dalam. Anda dan pasangan adalah pahlawan terkuat di hari-hari penuh badai ini.', body_ja = 'ひとりぼっちで疲れていると感じますか？深呼吸して。あなたとパートナーは、この嵐のような日々のいちばん強いヒーローです。', body_ko = '외롭고 지쳤나요? 깊게 숨을 쉬어 보세요. 엄마와 배우자는 이 폭풍 같은 날들의 가장 강한 영웅이에요.', body_nl = 'Voel je je alleen en moe? Haal diep adem. Jij en je partner zijn de sterkste helden van deze stormachtige dagen.', body_pl = 'Czujesz się samotna i zmęczona? Weź głęboki oddech. Ty i twój partner jesteście najsilniejszymi bohaterami tych burzliwych dni.', body_pt = 'Sente-se sozinha e cansada? Respire fundo. A mãe e o pai são os heróis mais fortes destes dias tempestuosos.', body_sv = 'Känner du dig ensam och trött? Andas djupt. Du och din partner är de starkaste hjältarna i de här stormiga dagarna.', body_vi = 'Mẹ thấy cô đơn và mệt mỏi? Hít thật sâu. Bố mẹ chính là những người hùng mạnh mẽ nhất của những ngày giông bão này.', body_zh = '觉得孤单又疲惫？深呼吸。你和伴侣是这段风雨日子里最坚强的英雄。' WHERE id = 'c9c8946d-7797-4bd6-8476-9f649f770a6e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Crees que dedicas poco tiempo a tu bebé o que no llegas a las tareas de casa? Deja de juzgarte. Lo estás haciendo de maravilla.', body_fr = 'Vous pensez ne pas consacrer assez de temps à votre enfant ou ne pas venir à bout des tâches ménagères ? Arrêtez de vous juger. Vous vous en sortez parfaitement.', body_hi = 'सोचती हैं कि बच्चे को कम समय देती हैं या घर के काम पूरे नहीं कर पातीं? खुद को दोष देना बंद कीजिए। आप बहुत बढ़िया काम कर रही हैं।', body_id = 'Merasa kurang meluangkan waktu untuk si kecil atau tak sempat mengurus rumah? Berhentilah menyalahkan diri. Anda melakukannya dengan sempurna.', body_ja = '赤ちゃんとの時間が少ない、家事が追いつかないと思っていませんか？自分を責めるのはやめましょう。あなたはとてもよくやっています。', body_ko = '아이와 시간을 충분히 보내지 못하거나 집안일을 다 못 한다고 느끼나요? 자책은 그만하세요. 정말 잘하고 있어요.', body_nl = 'Denk je dat je te weinig tijd voor je kindje hebt of het huishouden niet bijhoudt? Stop met jezelf verwijten maken. Je doet het perfect.', body_pl = 'Myślisz, że poświęcasz maluszkowi za mało czasu albo nie nadążasz z obowiązkami domowymi? Przestań się obwiniać. Świetnie sobie radzisz.', body_pt = 'Acha que passa pouco tempo com o bebé ou que não dá conta das tarefas da casa? Pare de se culpar. Está a sair-se na perfeição.', body_sv = 'Tycker du att du ägnar för lite tid åt barnet eller inte hinner med hushållet? Sluta döma dig själv. Du gör ett perfekt jobb.', body_vi = 'Mẹ nghĩ mình dành quá ít thời gian cho bé, hay không kịp làm việc nhà? Đừng tự trách mình nữa. Mẹ đang làm rất tốt.', body_zh = '觉得陪宝宝的时间太少，或者家务做不完？别再责怪自己了。你做得非常好。' WHERE id = '9ff73499-a2bd-41b7-96fa-1ec2d780279f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tiempo y ropa ⛅', body_es = 'No le des vueltas a qué ponerle para salir. Mira la herramienta Tiempo y ropa, encuentra en segundos el conjunto ideal y sal a tomar aire fresco.', title_fr = 'Météo et tenue ⛅', body_fr = 'Ne vous cassez pas la tête pour savoir comment l''habiller pour sortir. Consultez l''outil Météo et tenue, trouvez la tenue idéale en quelques secondes et allez prendre l''air.', title_hi = 'मौसम और कपड़े ⛅', body_hi = 'बाहर जाते समय क्या पहनाएँ, यह मत सोचिए। मौसम और कपड़े टूल देखकर सेकंडों में सही कपड़े चुनिए और ताज़ी हवा में निकलिए।', title_id = 'Cuaca dan pakaian ⛅', body_id = 'Tak perlu bingung memilih pakaian saat akan keluar. Lihat fitur Cuaca dan Pakaian, temukan pakaian ideal dalam hitungan detik, lalu hirup udara segar.', title_ja = '天気と服装 ⛅', body_ja = 'おでかけのときに何を着せるか悩まないで。「天気と服装」ツールで理想の組み合わせを数秒で見つけて、外の空気を楽しみましょう。', title_ko = '날씨와 옷차림 ⛅', body_ko = '외출할 때 무엇을 입힐지 고민하지 마세요. 날씨와 옷차림 도구로 딱 맞는 옷차림을 몇 초 만에 찾고 신선한 바람을 쐬러 나가세요.', title_nl = 'Weer en kleding ⛅', body_nl = 'Pieker niet over wat je baby aan moet als jullie naar buiten gaan. Kijk in de tool Weer en kleding, vind in een paar seconden de ideale outfit en ga lekker naar buiten.', title_pl = 'Pogoda i ubiór ⛅', body_pl = 'Nie łam sobie głowy, w co go ubrać na dwór. Zajrzyj do narzędzia Pogoda i ubiór, w kilka sekund znajdź idealny zestaw i wyjdź na świeże powietrze.', title_pt = 'Tempo e roupa ⛅', body_pt = 'Não perca tempo a pensar no que vestir ao bebé para sair. Veja a ferramenta Tempo e Roupa, encontre em segundos a combinação ideal e vá apanhar ar fresco.', title_sv = 'Väder och kläder ⛅', body_sv = 'Fundera inte på vad barnet ska ha på sig ute. Titta i Väder och kläder, hitta den perfekta klädseln på några sekunder och gå ut i friska luften.', title_vi = 'Thời tiết và trang phục ⛅', body_vi = 'Đừng đau đầu nghĩ xem cho bé mặc gì khi ra ngoài. Hãy xem công cụ Thời tiết và trang phục, tìm bộ đồ lý tưởng trong vài giây và ra ngoài hít thở không khí trong lành.', title_zh = '天气与穿衣 ⛅', body_zh = '出门不用纠结给宝宝穿什么。看看天气穿衣工具，几秒钟就找到理想搭配，出去呼吸新鲜空气吧。' WHERE id = 'f8790842-2782-419a-aaaa-3c8c1fc497de' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Detectives de armarios 🕵️‍♂️', body_es = '¿Los armarios de la cocina son su objetivo favorito? Pon cacharros inofensivos en el armario de abajo y deja que descubra su propio tesoro y juegue durante horas.', title_fr = 'Les détectives des placards 🕵️‍♂️', body_fr = 'Les placards de la cuisine sont sa cible préférée ? Rangez de la vaisselle sans danger dans le placard du bas et laissez-le découvrir son trésor et jouer pendant des heures.', title_hi = 'अलमारी के जासूस 🕵️‍♂️', body_hi = 'रसोई की अलमारियाँ उसका सबसे पसंदीदा निशाना हैं? सुरक्षित बर्तन नीचे की अलमारी में रख दीजिए, उसे अपना खज़ाना खोजने दीजिए और घंटों खेलने दीजिए।', title_id = 'Detektif lemari 🕵️‍♂️', body_id = 'Lemari dapur adalah sasaran favoritnya? Taruh peralatan dapur yang aman di lemari bawah, biarkan ia menjelajahi harta karunnya dan bermain berjam-jam.', title_ja = '戸棚の探偵 🕵️‍♂️', body_ja = 'キッチンの戸棚がいちばんのお気に入り？安全な鍋や食器を下の戸棚にまとめて、自分だけの宝物を発見しながら何時間でも遊ばせてあげましょう。', title_ko = '수납장 탐정 🕵️‍♂️', body_ko = '주방 수납장이 아기가 가장 좋아하는 목표인가요? 안전한 그릇들을 아래 칸에 모아 두고 자기만의 보물을 찾아 몇 시간이고 놀게 해 주세요.', title_nl = 'Kastdetectives 🕵️‍♂️', body_nl = 'Zijn de keukenkastjes zijn favoriete doelwit? Zet onschuldig keukengerei in een onderste kastje en laat hem urenlang zijn schat ontdekken en spelen.', title_pl = 'Detektywi szafek 🕵️‍♂️', body_pl = 'Szafki w kuchni to jego ulubiony cel? Włóż do dolnej szafki bezpieczne garnki i miski i pozwól mu godzinami odkrywać swój skarb.', title_pt = 'Detetives dos armários 🕵️‍♂️', body_pt = 'Os armários da cozinha são o alvo preferido dele? Arrume loiça inofensiva no armário de baixo e deixe-o descobrir o seu tesouro e brincar durante horas.', title_sv = 'Skåpsdetektiver 🕵️‍♂️', body_sv = 'Är köksskåpen barnets favoritmål? Lägg ofarliga kastruller och skålar i ett nedre skåp och låt barnet upptäcka sin egen skatt och leka i timmar.', title_vi = 'Thám tử tủ bếp 🕵️‍♂️', body_vi = 'Tủ bếp là mục tiêu yêu thích của bé? Hãy xếp những bát đĩa an toàn vào tủ dưới, để bé khám phá "kho báu" của mình và chơi hàng giờ liền.', title_zh = '柜子侦探 🕵️‍♂️', body_zh = '厨房柜子是宝宝最喜欢的目标？把安全无害的锅碗放在下层柜子里，让宝宝去发现自己的宝藏，一玩就是几个小时。' WHERE id = 'bb4b0ba8-0880-4332-8a97-7715f01a7ba8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'También eres mujer 💄', body_es = 'Eres madre, eres protectora, pero también eres una persona. Mírate en el espejo, sonríe y hoy haz algo pequeño por ti.', title_fr = 'Vous êtes aussi une femme 💄', body_fr = 'Vous êtes maman, protectrice, mais vous êtes aussi une personne à part entière. Regardez-vous dans le miroir, souriez et faites-vous un petit plaisir aujourd''hui.', title_hi = 'आप एक महिला भी हैं 💄', body_hi = 'आप माँ हैं, रक्षक हैं, पर आप एक अलग इंसान भी हैं। आईने में खुद को देखकर मुस्कुराइए और आज अपने लिए कुछ छोटा सा कीजिए।', title_id = 'Anda juga seorang perempuan 💄', body_id = 'Anda seorang ibu dan pelindung, tapi Anda juga pribadi tersendiri. Tatap diri Anda di cermin, tersenyumlah, dan lakukan satu hal kecil untuk diri sendiri hari ini.', title_ja = 'あなたはひとりの女性でもある 💄', body_ja = 'あなたはママで、守る人。でも、ひとりの人間でもあります。鏡の中の自分にほほえんで、今日は自分のために小さなことをしてあげましょう。', title_ko = '당신은 여성이기도 해요 💄', body_ko = '엄마이고 보호자이지만, 당신은 한 사람이기도 해요. 거울 속 나를 보며 미소 짓고 오늘 나를 위한 작은 선물을 해 보세요.', title_nl = 'Je bent ook een vrouw 💄', body_nl = 'Je bent moeder en beschermer, maar je bent ook jezelf. Kijk in de spiegel, glimlach en doe vandaag iets kleins voor jezelf.', title_pl = 'Jesteś też kobietą 💄', body_pl = 'Jesteś mamą i opiekunką, ale też osobą. Spójrz na siebie w lustrze, uśmiechnij się i zrób dziś dla siebie mały gest.', title_pt = 'Também é mulher 💄', body_pt = 'É mãe, é protetora, mas também é uma pessoa. Olhe-se ao espelho, sorria e faça hoje um pequeno gesto por si.', title_sv = 'Du är också kvinna 💄', body_sv = 'Du är mamma och beskyddare, men du är också en egen person. Titta på dig själv i spegeln, le och gör något litet för dig själv i dag.', title_vi = 'Mẹ cũng là một người phụ nữ 💄', body_vi = 'Mẹ là người mẹ, người che chở, nhưng mẹ cũng là chính mình. Hãy nhìn vào gương, mỉm cười và hôm nay làm một điều nhỏ cho bản thân.', title_zh = '你也是一个女人 💄', body_zh = '你是妈妈，是守护者，但你也是你自己。看着镜子里的自己笑一笑，今天为自己做件小事吧。' WHERE id = 'c24149f4-cca2-46bd-ba68-2442b259ab90' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te pierdas en los foros 🤖', body_es = '¿Tienes dudas sobre su rutina de comidas? No busques durante horas: deja que Anacan AI responda a tus preguntas con la lógica de un pediatra de bolsillo.', title_fr = 'Ne vous perdez pas dans les forums 🤖', body_fr = 'Un doute sur sa routine de repas ? Ne cherchez pas pendant des heures, laissez Anacan AI répondre à vos questions avec la logique d''un pédiatre dans votre poche.', title_hi = 'फ़ोरम में मत खोइए 🤖', body_hi = 'खाने के रूटीन को लेकर कोई शक है? घंटों मत खोजिए, Anacan AI आपकी जेब के बाल रोग विशेषज्ञ की समझ से आपके सवालों के जवाब देगा।', title_id = 'Jangan tersesat di forum 🤖', body_id = 'Ragu soal rutinitas makannya? Jangan mencari berjam-jam, biar Anacan AI menjawab pertanyaan Anda dengan logika dokter anak di saku Anda.', title_ja = '掲示板で迷子にならないで 🤖', body_ja = '食事のリズムで気になることがありますか？何時間も調べないで、ポケットの中の小児科医のように、Anacan AIに質問に答えてもらいましょう。', title_ko = '커뮤니티 글 속에서 헤매지 마세요 🤖', body_ko = '식사 일과에 대해 고민되는 게 있나요? 몇 시간씩 검색하지 말고 주머니 속 소아과 의사처럼 Anacan AI가 질문에 답하게 하세요.', title_nl = 'Verdwaal niet op forums 🤖', body_nl = 'Twijfel je ergens over in het eetritme? Zoek niet urenlang, maar laat Anacan AI je vragen beantwoorden met de logica van een kinderarts in je broekzak.', title_pl = 'Nie gub się na forach 🤖', body_pl = 'Masz wątpliwości co do posiłków maluszka? Nie szukaj godzinami, niech Anacan AI odpowiada na twoje pytania z logiką pediatry w kieszeni.', title_pt = 'Não se perca nos fóruns 🤖', body_pt = 'Tem alguma dúvida sobre a rotina das refeições? Não passe horas a pesquisar: deixe o Anacan AI responder às suas perguntas com a lógica de um pediatra no bolso.', title_sv = 'Gå inte vilse i forumen 🤖', body_sv = 'Är du osäker på något i matrutinen? Sök inte i timmar, låt Anacan AI svara på dina frågor med en barnläkares logik, direkt i fickan.', title_vi = 'Đừng lạc giữa diễn đàn 🤖', body_vi = 'Mẹ băn khoăn điều gì về chuyện ăn uống của bé? Đừng tìm kiếm hàng giờ, hãy để Anacan AI trả lời với tư duy của một bác sĩ nhi khoa trong túi của mẹ.', title_zh = '别在论坛里迷路 🤖', body_zh = '对宝宝的饮食作息有疑问？别花几个小时去搜，让Anacan AI像口袋里的儿科医生一样回答你的问题。' WHERE id = '4283eae1-f0b6-489a-be21-28cec6201152' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora del cuento de papá 📖', body_es = 'Esta noche crea en Cuentos inteligentes la historia de una cabra valiente que escala montañas. Que la lea papá y tú disfruta de la calma.', title_fr = 'L''heure du livre avec papa 📖', body_fr = 'Ce soir, créez dans les Contes intelligents l''histoire de la chèvre courageuse qui grimpe dans les montagnes. Papa la lit, et vous, profitez de ce calme.', title_hi = 'पापा का किताब वाला समय 📖', body_hi = 'आज शाम स्मार्ट कहानियों में पहाड़ों पर चढ़ने वाली बहादुर बकरी की कहानी बनाइए। पापा पढ़ें, और आप इस सुकून को देखिए।', title_id = 'Jam baca ayah 📖', body_id = 'Malam ini, buat kisah kambing pemberani yang mendaki gunung di Dongeng Pintar. Biar ayah yang membacakan, Anda cukup menikmati ketenangannya.', title_ja = 'パパの絵本タイム 📖', body_ja = '今夜は「スマートおはなし」で、山を登る勇敢なヤギのお話をつくりましょう。読むのはパパ、あなたはこの静けさを見守りましょう。', title_ko = '아빠의 책 읽기 시간 📖', body_ko = '오늘 저녁 스마트 동화에서 산을 오르는 용감한 염소 이야기를 만들어 보세요. 아빠가 읽어 주고, 엄마는 이 고요함을 지켜보세요.', title_nl = 'Papa''s voorleesuurtje 📖', body_nl = 'Maak vanavond in Slimme sprookjes het verhaal van een dappere geit die de bergen in klimt. Laat papa voorlezen en geniet jij van de rust.', title_pl = 'Czytanie z tatą 📖', body_pl = 'Dziś wieczorem stwórz w Mądrych bajkach historię o odważnej kozie wspinającej się w góry. Niech czyta tata, a ty ciesz się tą ciszą.', title_pt = 'A hora do livro com o pai 📖', body_pt = 'Esta noite, crie nas Histórias Inteligentes a história da cabra corajosa que sobe as montanhas. Que seja o pai a ler, e a mãe a apreciar a calma.', title_sv = 'Pappas sagostund 📖', body_sv = 'Skapa sagan om den modiga geten som klättrar i bergen i Smarta sagor i kväll. Låt pappa läsa medan du njuter av lugnet.', title_vi = 'Giờ đọc sách của bố 📖', body_vi = 'Tối nay hãy tạo câu chuyện về chú dê dũng cảm leo núi trong Truyện cổ tích thông minh. Để bố đọc, còn mẹ tận hưởng sự yên bình này.', title_zh = '爸爸的故事时间 📖', body_zh = '今晚在智能故事里创作一个勇敢的小山羊爬山的故事。让爸爸来读，你只管享受这份宁静。' WHERE id = '743ea03a-9755-40d4-b4aa-1eb6cf8a7495' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Comer con los dedos 🥦', body_es = '¡Ya no quiere puré, sino coger las verduras con sus manos! Apoya sus intentos de comer solo, pero quédate siempre a su lado.', title_fr = 'Manger avec les doigts 🥦', body_fr = 'Il ne veut plus de purée mais préfère attraper les légumes avec ses mains ! Soutenez ses essais pour manger seul, mais restez toujours à côté de lui.', title_hi = 'उँगलियों से खाना 🥦', body_hi = 'अब वह प्यूरी नहीं, बल्कि सब्ज़ियाँ अपने हाथों से पकड़ना चाहता है! खुद खाने की उसकी कोशिशों का साथ दीजिए, पर उसके पास ज़रूर रहिए।', title_id = 'Makan dengan jari 🥦', body_id = 'Ia ingin memegang sayur dengan tangannya sendiri, bukan makan puree! Dukung usahanya makan sendiri, tapi tetaplah di sampingnya.', title_ja = '手づかみ食べ 🥦', body_ja = 'もうペーストではなく、野菜を自分の手で持ちたがっています！自分で食べようとする挑戦を応援しましょう。ただし必ずそばにいてください。', title_ko = '손으로 먹기 🥦', body_ko = '이제 퓌레보다 채소를 직접 손으로 잡고 싶어 해요! 스스로 먹으려는 시도를 응원하되 꼭 곁에 있어 주세요.', title_nl = 'Eten met de vingers 🥦', body_nl = 'Je baby wil geen hapjes meer, maar groente zelf vastpakken! Steun zijn pogingen om zelf te eten, maar blijf er altijd bij.', title_pl = 'Jedzenie rączkami 🥦', body_pl = 'Już nie chce przecieru, tylko trzymać warzywa własną rączką! Wspieraj jego próby samodzielnego jedzenia, ale koniecznie bądź obok.', title_pt = 'Comer com os dedos 🥦', body_pt = 'Já não quer puré, quer pegar nos legumes com a própria mão! Apoie as tentativas de comer sozinho, mas fique sempre ao lado dele.', title_sv = 'Äta med fingrarna 🥦', body_sv = 'Barnet vill inte längre ha puré utan vill hålla i grönsakerna själv! Stötta försöken att äta själv, men stanna alltid bredvid.', title_vi = 'Tự ăn bằng tay 🥦', body_vi = 'Bé không muốn ăn món nghiền nữa mà muốn tự cầm rau củ bằng tay! Hãy ủng hộ những lần tự ăn của bé, nhưng nhất định phải ở bên cạnh.', title_zh = '手指食物 🥦', body_zh = '宝宝已经不想只吃泥，而是想自己用手抓着蔬菜吃了！支持宝宝自主进食的尝试，但一定要守在旁边。' WHERE id = 'fc594ad6-91bd-4ee2-a759-0d1e76e468c0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Ha cambiado el color de las cacas? 💩', body_es = 'Con la alimentación complementaria es normal ver colores distintos. Pero si te preocupa, pregunta a Anacan AI cuál es la causa.', title_fr = 'La couleur des selles a changé ? 💩', body_fr = 'Avec la diversification, il est normal de voir des couleurs différentes. Mais si vous êtes inquiète, demandez-en la raison à Anacan AI.', title_hi = 'मल का रंग बदल गया? 💩', body_hi = 'ऊपरी आहार शुरू होने पर अलग रंग दिखना सामान्य है। पर अगर चिंता हो रही है, तो Anacan AI से इसकी वजह जानिए।', title_id = 'Warna tinja berubah? 💩', body_id = 'Wajar jika warnanya berbeda-beda saat mulai MPASI. Tapi jika Anda khawatir, cari tahu penyebabnya di Anacan AI.', title_ja = 'うんちの色が変わった？💩', body_ja = '離乳食を始めると、いろいろな色のうんちが出るのは普通のことです。でも心配なら、Anacan AIで理由を調べてみましょう。', title_ko = '변 색이 바뀌었나요? 💩', body_ko = '이유식을 시작하면 변 색이 달라지는 건 정상이에요. 하지만 걱정된다면 Anacan AI에게 그 이유를 알아보세요.', title_nl = 'Heeft de poep een andere kleur? 💩', body_nl = 'Met de overgang naar bijvoeding is het normaal om andere kleuren te zien. Maak je je toch zorgen? Ontdek de oorzaak met Anacan AI.', title_pl = 'Kupka zmieniła kolor? 💩', body_pl = 'Przy rozszerzaniu diety różne kolory kupki są normalne. Ale jeśli się niepokoisz, dowiedz się od Anacan AI, skąd to się bierze.', title_pt = 'As fezes mudaram de cor? 💩', body_pt = 'Com a diversificação alimentar, é normal ver cores diferentes. Mas, se ficou preocupada, descubra a causa com o Anacan AI.', title_sv = 'Har bajset bytt färg? 💩', body_sv = 'Det är normalt att se olika färger när ni går över till smakportioner. Men om du är orolig, ta reda på orsaken hos Anacan AI.', title_vi = 'Màu phân của bé thay đổi? 💩', body_vi = 'Khi bắt đầu ăn dặm, thấy phân có màu khác là điều bình thường. Nhưng nếu mẹ lo lắng, hãy hỏi Anacan AI để biết nguyên nhân.', title_zh = '大便颜色变了？💩', body_zh = '添加辅食后看到不同颜色的大便是正常的。但如果你担心，就向Anacan AI了解原因吧。' WHERE id = '8ee71700-bb17-4782-940b-c0fc02328f1a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Cuando se te acaba la paciencia, no te sientas mala madre. Este cansancio es natural.', body_fr = 'Quand vous êtes à bout de patience, ne vous sentez pas une mauvaise mère. Cette fatigue est naturelle.', body_hi = 'जब धैर्य जवाब देने लगे, तो खुद को बुरी माँ मत समझिए। यह थकान स्वाभाविक है।', body_id = 'Saat kesabaran menipis, jangan merasa jadi ibu yang buruk. Rasa lelah ini wajar.', body_ja = 'がまんの限界がきても、自分をダメなママだと思わないで。この疲れは自然なことです。', body_ko = '인내심이 바닥날 때 나쁜 엄마라고 느끼지 마세요. 이런 피로는 자연스러운 거예요.', body_nl = 'Voel je geen slechte moeder als je geduld opraakt. Deze vermoeidheid is heel normaal.', body_pl = 'Gdy kończy ci się cierpliwość, nie czuj się złą mamą. To zmęczenie jest naturalne.', body_pt = 'Quando a paciência se esgota, não se sinta má mãe. Este cansaço é natural.', body_sv = 'Känn dig inte som en dålig mamma när tålamodet tar slut. Den här tröttheten är naturlig.', body_vi = 'Khi hết kiên nhẫn, đừng nghĩ mình là người mẹ tồi. Sự mệt mỏi này là điều tự nhiên.', body_zh = '没耐心的时候，别觉得自己是个坏妈妈。这种疲惫是很自然的。' WHERE id = '9240cd01-c58e-42aa-be44-a4d2ac461bc2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dedícate tiempo. 🛁', body_es = 'Mientras tu peque duerme, cuida tu pelo y tu piel y descansa.', title_fr = 'Prenez du temps pour vous. 🛁', body_fr = 'Pendant que votre enfant dort, prenez soin de vos cheveux et de votre peau, et reposez-vous.', title_hi = 'अपने लिए समय निकालिए 🛁', body_hi = 'बच्चे के सोते समय अपने बालों और त्वचा की देखभाल कीजिए और आराम कीजिए।', title_id = 'Luangkan waktu untuk diri sendiri. 🛁', body_id = 'Saat si kecil tidur, rawat rambut dan kulit Anda, lalu beristirahatlah.', title_ja = '自分の時間をつくって。🛁', body_ja = '赤ちゃんが寝ている間に、髪や肌のお手入れをして、のんびりしましょう。', title_ko = '나를 위한 시간을 가지세요. 🛁', body_ko = '아이가 자는 동안 머리와 피부를 가꾸며 쉬어 보세요.', title_nl = 'Neem tijd voor jezelf. 🛁', body_nl = 'Verzorg je haar en je huid en rust uit terwijl je kindje slaapt.', title_pl = 'Znajdź czas dla siebie. 🛁', body_pl = 'Gdy maluszek śpi, zadbaj o włosy i skórę i odpocznij.', title_pt = 'Reserve tempo para si. 🛁', body_pt = 'Enquanto o bebé dorme, cuide do cabelo e da pele e descanse.', title_sv = 'Ta tid för dig själv. 🛁', body_sv = 'Medan barnet sover, ta hand om ditt hår och din hud och vila.', title_vi = 'Dành thời gian cho bản thân. 🛁', body_vi = 'Khi bé ngủ, hãy chăm sóc tóc và làn da của mình và nghỉ ngơi nhé.', title_zh = '留点时间给自己 🛁', body_zh = '趁宝宝睡觉，护理一下头发和皮肤，好好休息吧。' WHERE id = '03f6a4bb-fc20-440d-bf19-5a474e3fa7f6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubrimientos descalzo 👣', body_es = '¿No le gusta andar con calcetines por casa? El contacto de los nervios de la planta del pie con el suelo es perfecto para el desarrollo cerebral. ¡Deja que vaya libre!', title_fr = 'Explorations pieds nus 👣', body_fr = 'Il n''aime pas porter de chaussettes à la maison ? Le contact des nerfs de la plante des pieds avec le sol est excellent pour le développement du cerveau. Laissez-le libre !', title_hi = 'नंगे पैर खोज 👣', body_hi = 'घर में मोज़े पहनकर चलना पसंद नहीं करता? पैरों के तलवों की नसों का ज़मीन से संपर्क दिमाग के विकास के लिए बढ़िया है। उसे आज़ाद रहने दीजिए!', title_id = 'Menjelajah tanpa alas kaki 👣', body_id = 'Ia tidak suka memakai kaus kaki di rumah? Sentuhan saraf telapak kaki dengan lantai sangat baik untuk perkembangan otak. Biarkan ia bebas!', title_ja = 'はだしで探検 👣', body_ja = '家で靴下をはくのがきらい？足の裏が床にふれる刺激は、脳の発達にぴったりです。自由にさせてあげましょう！', title_ko = '맨발 탐험 👣', body_ko = '집에서 양말 신는 걸 싫어하나요? 발바닥 신경이 바닥에 닿는 건 두뇌 발달에 아주 좋아요. 자유롭게 두세요!', title_nl = 'Blootsvoets ontdekken 👣', body_nl = 'Houdt je baby er niet van om thuis sokken te dragen? Het contact van de zenuwen onder zijn voetjes met de vloer is perfect voor de hersenontwikkeling. Laat hem lekker vrij!', title_pl = 'Odkrycia na bosaka 👣', body_pl = 'Nie lubi chodzić po domu w skarpetkach? Kontakt nerwów w stópkach z podłożem jest świetny dla rozwoju mózgu. Pozwól mu na swobodę!', title_pt = 'Descobertas descalço 👣', body_pt = 'Não gosta de andar de meias em casa? O contacto dos nervos da planta do pé com o chão é perfeito para o desenvolvimento do cérebro. Deixe-o à vontade!', title_sv = 'Upptäckter barfota 👣', body_sv = 'Gillar barnet inte att gå i strumpor hemma? När nerverna under fötterna får kontakt med golvet är det perfekt för hjärnans utveckling. Låt barnet vara fritt!', title_vi = 'Khám phá bằng chân trần 👣', body_vi = 'Bé không thích đi tất trong nhà? Việc các dây thần kinh dưới lòng bàn chân tiếp xúc với mặt sàn rất tốt cho sự phát triển của não. Cứ để bé thoải mái!', title_zh = '光脚探索 👣', body_zh = '宝宝不爱在家穿袜子？脚底神经和地面的接触对大脑发育非常好。让宝宝自由一点吧！' WHERE id = '288682cf-7f40-402e-a594-adaf2cbbed34' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lista te salva la vida 🛒', body_es = '¿La niebla mental no te abandona? ¿Se acabó el jabón, queda poca fruta? Apúntalo antes de que se te olvide en la Lista de la compra y que tu pareja se encargue.', title_fr = 'La liste qui sauve la vie 🛒', body_fr = 'Le brouillard de mémoire ne vous quitte pas ? Plus de savon, presque plus de fruits ? Notez-les tout de suite dans la Liste de courses, votre conjoint s''en chargera.', title_hi = 'लिस्ट जान बचाती है 🛒', body_hi = 'याददाश्त का धुंधलापन पीछा नहीं छोड़ रहा? साबुन खत्म हो गया, फल कम हो गए? भूलने से पहले शॉपिंग लिस्ट में लिखिए, आपके साथी संभाल लेंगे।', title_id = 'Daftar menyelamatkan hidup 🛒', body_id = 'Kabut ingatan tak kunjung hilang? Sabun habis, buah tinggal sedikit? Tulis di Daftar Belanja sebelum lupa, biar pasangan Anda yang mengurus.', title_ja = 'リストは命綱 🛒', body_ja = '頭のもやもやが晴れない？せっけんがなくなった、果物が減ってきた？忘れないうちに「買い物リスト」に書いて、パートナーにおまかせしましょう。', title_ko = '목록이 살려 줘요 🛒', body_ko = '깜빡깜빡 머리가 여전한가요? 비누가 떨어지고 과일이 줄었나요? 잊기 전에 쇼핑 목록에 적어 두면 배우자가 해결할 거예요.', title_nl = 'Een lijstje redt levens 🛒', body_nl = 'Blijft die geheugenmist maar hangen? Is de zeep op en het fruit bijna? Zet het op je Boodschappenlijstje voordat je het vergeet en laat je partner het regelen.', title_pl = 'Lista ratuje życie 🛒', body_pl = 'Mgła w głowie nie odpuszcza? Skończyło się mydło, brakuje owoców? Od razu wpisz to na Listę zakupów, a partner się tym zajmie.', title_pt = 'A lista salva vidas 🛒', body_pt = 'O nevoeiro na memória não passa? Acabou o sabonete, há pouca fruta? Escreva logo na Lista de Compras e o seu companheiro trata disso.', title_sv = 'Listan räddar liv 🛒', body_sv = 'Släpper minnesdimman inte taget? Har tvålen tagit slut och frukten börjat tryta? Skriv upp det i Inköpslistan innan du glömmer, så fixar din partner det.', title_vi = 'Danh sách là cứu tinh 🛒', body_vi = 'Sương mù trí nhớ vẫn chưa buông tha mẹ? Hết xà phòng, sắp hết trái cây? Ghi ngay vào Danh sách mua sắm kẻo quên, để bố lo nhé.', title_zh = '清单是救命稻草 🛒', body_zh = '记忆迷雾还没散？香皂用完了，水果不多了？趁还记得写进购物清单，让伴侣去搞定吧。' WHERE id = '2951ca5f-9454-4562-9820-3bfb3531edfd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reunión de equipo 🥂', body_es = 'Esta noche, cuando tu bebé se duerma, abrid juntos el Diario de ánimo tu pareja y tú y reíos del caos de esta semana.', title_fr = 'Réunion d''équipe 🥂', body_fr = 'Ce soir, quand bébé dormira, ouvrez le Journal d''humeur avec votre conjoint et riez ensemble du chaos de cette semaine.', title_hi = 'टीम मीटिंग 🥂', body_hi = 'आज शाम बच्चे के सोने के बाद अपने साथी के साथ मूड डायरी खोलिए और इस हफ़्ते की अफ़रा-तफ़री पर साथ मिलकर हँसिए।', title_id = 'Rapat tim 🥂', body_id = 'Malam ini, setelah si kecil tidur, buka Buku Harian Suasana Hati bersama pasangan dan tertawakan kekacauan minggu ini bersama-sama.', title_ja = 'チーム会議 🥂', body_ja = '今夜は赤ちゃんが寝たら、パートナーと「気分日記」を開いて、今週のカオスを一緒に笑い飛ばしましょう。', title_ko = '팀 회의 🥂', body_ko = '오늘 저녁 아기가 잠든 뒤 배우자와 함께 기분 일기를 열고 이번 주의 혼돈을 함께 웃어넘겨 보세요.', title_nl = 'Teamoverleg 🥂', body_nl = 'Open vanavond, als je baby slaapt, samen met je partner het Stemmingsdagboek en lach samen om de chaos van deze week.', title_pl = 'Narada drużyny 🥂', body_pl = 'Dziś wieczorem, gdy maluszek zaśnie, otwórzcie z partnerem Dziennik nastroju i pośmiejcie się razem z chaosu tego tygodnia.', title_pt = 'Reunião de equipa 🥂', body_pt = 'Esta noite, depois de o bebé adormecer, abra o Diário de Humor com o seu companheiro e riam-se juntos do caos desta semana.', title_sv = 'Lagmöte 🥂', body_sv = 'I kväll, när barnet har somnat, öppna Humördagboken tillsammans med din partner och skratta åt veckans kaos tillsammans.', title_vi = 'Họp đội 🥂', body_vi = 'Tối nay, sau khi bé ngủ, hãy cùng bố mở Nhật ký tâm trạng và cùng cười về sự hỗn loạn của tuần này.', title_zh = '团队会议 🥂', body_zh = '今晚宝宝睡着后，和伴侣一起打开心情日记，为这一周的混乱一起笑一笑吧。' WHERE id = '5a72ebf7-bb71-45f2-8047-a9b0ffc32a13' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los dientes atacan de nuevo 🦷', body_es = 'El llanto sin motivo puede deberse a la presión en las encías. Actualiza el Seguimiento de dentición y saca los aros de dentición congelados.', title_fr = 'Les dents attaquent encore 🦷', body_fr = 'Les pleurs inexpliqués peuvent venir de la tension dans les gencives. Mettez à jour le Suivi des dents et sortez les anneaux de dentition du congélateur.', title_hi = 'दाँतों का फिर हमला 🦷', body_hi = 'बेवजह रोना मसूड़ों में खिंचाव की वजह से हो सकता है। दाँत निकलने का ट्रैकर अपडेट कीजिए और फ़्रीज़ की हुई टीथिंग रिंग निकालिए।', title_id = 'Gigi menyerang lagi 🦷', body_id = 'Tangisan tanpa sebab bisa jadi karena tekanan di gusi. Perbarui Pelacak Tumbuh Gigi dan keluarkan teether yang sudah dibekukan.', title_ja = '歯がまた攻めてきた 🦷', body_ja = '理由のわからない泣きは、歯ぐきの張りが原因かもしれません。「歯の生え始めトラッカー」を更新して、冷凍した歯固めリングを取り出しましょう。', title_ko = '이가 또 공격해요 🦷', body_ko = '이유 없는 울음은 잇몸의 압박 때문일 수 있어요. 이앓이 기록을 업데이트하고 얼려 둔 치아발육기를 꺼내세요.', title_nl = 'De tandjes vallen weer aan 🦷', body_nl = 'Onverklaarbaar huilen kan door spanning in het tandvlees komen. Werk de Tandjestracker bij en haal de bevroren bijtringen tevoorschijn.', title_pl = 'Ząbki znów atakują 🦷', body_pl = 'Płacz bez powodu może wynikać z napięcia w dziąsłach. Zaktualizuj narzędzie do śledzenia ząbkowania i wyjmij zamrożone gryzaki.', title_pt = 'Os dentes voltam ao ataque 🦷', body_pt = 'O choro sem motivo pode ser da pressão nas gengivas. Atualize o Registo de Dentição e tire do congelador as argolas de dentição.', title_sv = 'Tänderna anfaller igen 🦷', body_sv = 'Oförklarlig gråt kan bero på spänningar i tandköttet. Uppdatera Tandspåraren och ta fram de frysta bitringarna.', title_vi = 'Răng lại tấn công 🦷', body_vi = 'Những cơn khóc không rõ lý do có thể do nướu bị căng. Hãy cập nhật Theo dõi mọc răng và lấy vòng gặm nướu đông lạnh ra nhé.', title_zh = '牙齿又来捣乱了 🦷', body_zh = '无缘无故的哭闹可能是牙龈胀痛引起的。更新出牙追踪，拿出冰过的牙胶吧。' WHERE id = '06f3c3ab-79a9-4f2f-94ed-e08927cda8e1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La acústica de la habitación 🤫', body_es = '¿Al dormirse se despierta con el más mínimo ruidito? Comprueba el ambiente con el Medidor de sonido y ayuda a su sueño con un ruido blanco constante.', title_fr = 'L''acoustique de la chambre 🤫', body_fr = 'Au moment de s''endormir, il se réveille au moindre petit bruit ? Vérifiez l''ambiance avec le Sonomètre et soutenez son sommeil avec un bruit blanc continu.', title_hi = 'कमरे की आवाज़ 🤫', body_hi = 'सोते समय ज़रा सी खटखट पर भी जाग जाता है? साउंड मीटर से माहौल जाँचिए और लगातार चलने वाले व्हाइट नॉइज़ से उसकी नींद में मदद कीजिए।', title_id = 'Akustik kamar 🤫', body_id = 'Ia terbangun karena ketukan kecil saat mulai tertidur? Cek suasana dengan Pengukur Suara dan dukung tidurnya dengan white noise yang stabil.', title_ja = '部屋の音環境 🤫', body_ja = '寝入りばなに、小さな物音でも起きてしまう？「サウンドメーター」で環境をチェックして、一定のホワイトノイズで眠りをサポートしましょう。', title_ko = '방의 소리 환경 🤫', body_ko = '잠들 때 작은 소리에도 깨나요? 소음 측정기로 환경을 확인하고 일정한 백색소음으로 잠을 도와주세요.', title_nl = 'Akoestiek in de kamer 🤫', body_nl = 'Wordt je baby bij het inslapen zelfs van een klein tikje wakker? Controleer de omgeving met de Geluidsmeter en steun zijn slaap met constante witte ruis.', title_pl = 'Akustyka pokoju 🤫', body_pl = 'Przy zasypianiu budzi go nawet najmniejsze stuknięcie? Sprawdź otoczenie Miernikiem dźwięku i wspieraj jego sen stałym białym szumem.', title_pt = 'A acústica do quarto 🤫', body_pt = 'Ao adormecer, acorda com o mais pequeno estalido? Verifique o ambiente com o Medidor de Som e ajude-o a dormir com ruído branco constante.', title_sv = 'Rummets akustik 🤫', body_sv = 'Vaknar barnet av minsta knaster när det håller på att somna? Kolla miljön med Ljudmätaren och stötta sömnen med jämnt vitt brus.', title_vi = 'Âm thanh trong phòng 🤫', body_vi = 'Khi đang vào giấc, bé thức dậy dù chỉ vì một tiếng lách cách nhỏ? Hãy kiểm tra môi trường bằng Đo âm thanh và hỗ trợ giấc ngủ của bé bằng tiếng ồn trắng đều đặn.', title_zh = '房间的声音环境 🤫', body_zh = '快睡着时，一点点响声都会把宝宝吵醒？用噪音测量检查环境，用稳定的白噪音帮助宝宝入睡吧。' WHERE id = '8e728e0f-9970-4b3d-acfc-5e72bc0eb7af' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Señala con el dedo algo lejano y hace sonidos? ☝️', body_es = 'Te está diciendo «mírame» o «quiero eso». ¡Es un gran salto en la comunicación!', title_fr = 'Il montre du doigt un objet éloigné en faisant des sons ? ☝️', body_fr = 'Il vous dit « regarde » ou « je veux ça ». C''est un grand bond dans la communication !', title_hi = 'दूर की चीज़ की ओर इशारा करके आवाज़ निकालता है? ☝️', body_hi = 'वह आपसे कह रहा है ''मुझे देखो'' या ''मुझे यह चाहिए''। बातचीत में यह बड़ी छलांग है!', title_id = 'Ia menunjuk benda yang jauh dengan jarinya sambil bersuara? ☝️', body_id = 'Ia sedang berkata, "Lihat aku" atau "Aku mau itu". Lompatan besar dalam komunikasi!', title_ja = '遠くのものを指さして声を出していますか？☝️', body_ja = '「見て」「あれがほしい」と伝えているのです。コミュニケーションの大きな飛躍です！', title_ko = '멀리 있는 물건을 손가락으로 가리키며 소리를 내나요? ☝️', body_ko = '''이것 봐요'' 또는 ''이거 갖고 싶어요''라고 말하는 거예요. 소통의 큰 도약이에요!', title_nl = 'Wijst je baby naar iets verderop en maakt hij geluid? ☝️', body_nl = 'Hij zegt: kijk eens of dat wil ik. Een grote sprong in de communicatie!', title_pl = 'Pokazuje palcem odległy przedmiot i wydaje dźwięki? ☝️', body_pl = 'Mówi ci: „popatrz na mnie” albo „chcę to”. To wielki skok w komunikacji!', title_pt = 'Aponta com o dedo para um objeto ao longe e faz sons? ☝️', body_pt = 'Está a dizer-lhe "olha para mim" ou "quero isto". É um grande salto na comunicação!', title_sv = 'Pekar barnet på något långt bort och gör ljud? ☝️', body_sv = 'Det säger ''titta på mig'' eller ''jag vill ha den''. Ett stort språng i kommunikationen!', title_vi = 'Bé chỉ tay vào đồ vật ở xa và phát ra âm thanh? ☝️', body_vi = 'Bé đang nói "Mẹ nhìn này" hoặc "Con muốn cái đó". Đây là bước nhảy lớn trong giao tiếp!', title_zh = '宝宝用手指指着远处的东西发出声音？☝️', body_zh = '宝宝在对你说“看我”或“我想要那个”。这是沟通上的一大飞跃！' WHERE id = 'cefb8b22-0318-4268-adf8-8f7052ad66cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La ventana de sueño se estrecha 🥱', body_es = '¿Los despertares nocturnos te tienen agotada? Quizá esté pasando de 3 siestas a 2. Revisa de nuevo el intervalo entre sus siestas de día.', title_fr = 'La fenêtre de sommeil se resserre 🥱', body_fr = 'Les réveils nocturnes vous achèvent ? C''est peut-être le passage de 3 siestes à 2. Revoyez l''espacement de ses siestes de la journée.', title_hi = 'नींद की खिड़की छोटी हो रही है 🥱', body_hi = 'रात में बार-बार जागना आपको थका रहा है? शायद यह 3 झपकियों से 2 झपकियों पर जाने का दौर है। दिन की झपकियों के बीच के अंतर पर फिर से नज़र डालिए।', title_id = 'Jendela tidur makin sempit 🥱', body_id = 'Terbangun di malam hari membuat Anda kehabisan tenaga? Mungkin ini masa peralihan dari 3 kali tidur siang ke 2 kali. Tinjau kembali jarak antar tidur siangnya.', title_ja = 'ねんねのタイミングが短くなる 🥱', body_ja = '夜中に何度も起きてくたくた？お昼寝が3回から2回へ移る時期かもしれません。お昼寝の間隔を見直してみましょう。', title_ko = '수면 타이밍이 좁아지고 있어요 🥱', body_ko = '밤에 깨는 일로 녹초가 됐나요? 낮잠이 3번에서 2번으로 바뀌는 시기일 수도 있어요. 낮잠 간격을 다시 살펴보세요.', title_nl = 'Het slaapvenster wordt kleiner 🥱', body_nl = 'Putten de nachtelijke wakkere momenten je uit? Misschien is dit de overgang van 3 naar 2 slaapjes. Bekijk de tijd tussen de dutjes overdag opnieuw.', title_pl = 'Okno snu się zawęża 🥱', body_pl = 'Nocne pobudki cię wykańczają? Może to etap przejścia z 3 drzemek na 2. Przyjrzyj się na nowo odstępom między drzemkami w dzień.', title_pt = 'A janela de sono está a ficar mais curta 🥱', body_pt = 'Os despertares noturnos estão a dar cabo de si? Talvez seja a fase de passagem de 3 sestas para 2. Reveja o intervalo entre as sestas do dia.', title_sv = 'Sömnfönstret krymper 🥱', body_sv = 'Har nattuppvaknandena tagit all din kraft? Det kan vara övergången från 3 till 2 tupplurar. Se över tiderna mellan dagsluren igen.', title_vi = 'Cửa sổ giấc ngủ thu hẹp 🥱', body_vi = 'Những lần thức đêm làm mẹ kiệt sức? Có thể bé đang chuyển từ 3 giấc ngủ ngày sang 2 giấc. Hãy xem lại khoảng cách giữa các giấc ngủ ngày.', title_zh = '睡眠窗口在缩短 🥱', body_zh = '夜醒让你精疲力竭？也许正处在从3次小睡过渡到2次的阶段。重新看看白天小睡的间隔吧。' WHERE id = '2e4d0e7a-db8d-4408-9d88-01d37ed8b303' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Puré en el pelo 🤦‍♀️', body_es = '¿La hora de comer se convierte en un campo de batalla? Que toque la comida y la explore es desarrollo sensorial. No te fijes en las manchas.', title_fr = 'De la purée dans les cheveux 🤦‍♀️', body_fr = 'L''heure du repas tourne au champ de bataille ? Toucher et explorer la nourriture, c''est du développement sensoriel. Ne vous souciez pas des taches.', title_hi = 'बालों में प्यूरी 🤦‍♀️', body_hi = 'खाने का समय जंग का मैदान बन रहा है? बच्चे का खाने को छूना और खोजना उसके संवेदी विकास का हिस्सा है। दागों पर ध्यान मत दीजिए।', title_id = 'Puree di rambut 🤦‍♀️', body_id = 'Waktu makan berubah jadi medan perang? Menyentuh dan menjelajahi makanan adalah bagian dari perkembangan sensorinya. Jangan pedulikan nodanya.', title_ja = '髪の毛にペースト 🤦‍♀️', body_ja = 'ごはんの時間が戦場に？食べ物にさわって探検するのは、感覚の発達です。汚れは気にしないで。', title_ko = '머리카락에 퓌레가 🤦‍♀️', body_ko = '식사 시간이 전쟁터가 되나요? 아이가 음식을 만지고 탐색하는 건 감각 발달이에요. 얼룩은 신경 쓰지 마세요.', title_nl = 'Hapjes in zijn haar 🤦‍♀️', body_nl = 'Verandert etenstijd in een slagveld? Als je kindje het eten aanraakt en ontdekt, is dat zintuiglijke ontwikkeling. Let niet op de vlekken.', title_pl = 'Przecier we włosach 🤦‍♀️', body_pl = 'Posiłek zamienia się w pole bitwy? Dotykanie i odkrywanie jedzenia to rozwój sensoryczny. Nie przejmuj się plamami.', title_pt = 'Puré no cabelo 🤦‍♀️', body_pt = 'A hora da refeição transforma-se num campo de batalha? Tocar na comida e explorá-la é desenvolvimento sensorial. Não ligue às nódoas.', title_sv = 'Puré i håret 🤦‍♀️', body_sv = 'Blir måltiden ett slagfält? När barnet rör vid maten och utforskar den är det sensorisk utveckling. Bry dig inte om fläckarna.', title_vi = 'Món nghiền dính trên tóc 🤦‍♀️', body_vi = 'Giờ ăn biến thành chiến trường? Việc bé chạm vào và khám phá thức ăn là sự phát triển giác quan. Đừng bận tâm đến vết bẩn.', title_zh = '头发里的果泥 🤦‍♀️', body_zh = '吃饭时间变成了战场？宝宝摸食物、探索食物是感官发育的一部分。别在意那些污渍。' WHERE id = 'b19774b6-01ed-4a77-8052-5a03aef4ba22' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La naturaleza al rescate 🌳', body_es = '¿Está muy quejica y no quiere estar en casa? Consulta el asistente Tiempo y ropa y sal enseguida a dar una vuelta de 20 minutos por el parque.', title_fr = 'La nature à la rescousse 🌳', body_fr = 'Il est très grognon et ne tient pas en place à la maison ? Demandez conseil à l''assistant Météo et tenue et partez tout de suite pour 20 minutes au parc.', title_hi = 'प्रकृति बचाती है 🌳', body_hi = 'बहुत चिड़चिड़ा है और घर में टिकता नहीं? मौसम और कपड़े टूल से सलाह लीजिए और तुरंत 20 मिनट के लिए पार्क की सैर पर निकलिए।', title_id = 'Alam menyelamatkan 🌳', body_id = 'Ia sangat rewel dan tidak betah di rumah? Minta saran dari asisten Cuaca dan Pakaian dan segera jalan-jalan 20 menit ke taman.', title_ja = '自然が救ってくれる 🌳', body_ja = 'ぐずぐずして、家にいたがらない？「天気と服装」アシスタントでアドバイスをもらって、すぐに20分ほど公園へ出かけましょう。', title_ko = '자연이 구해 줘요 🌳', body_ko = '많이 칭얼대고 집에 있으려 하지 않나요? 날씨와 옷차림 도우미의 조언을 받아 바로 공원으로 20분 산책을 나가세요.', title_nl = 'De natuur schiet te hulp 🌳', body_nl = 'Is je baby erg zeurderig en wil hij niet binnen blijven? Vraag de assistent Weer en kleding om advies en ga meteen 20 minuten naar het park.', title_pl = 'Natura na ratunek 🌳', body_pl = 'Jest bardzo marudny i nie chce siedzieć w domu? Zajrzyj po radę do pomocnika Pogoda i ubiór i od razu wyjdźcie na 20 minut do parku.', title_pt = 'A natureza salva 🌳', body_pt = 'Está muito rabugento e não para quieto em casa? Peça conselho ao assistente Tempo e Roupa e saia já para 20 minutos de parque.', title_sv = 'Naturen räddar dagen 🌳', body_sv = 'Väldigt gnällig och vill inte vara inne? Ta hjälp av Väder och kläder och gå direkt ut på en 20 minuters tur i parken.', title_vi = 'Thiên nhiên giải cứu 🌳', body_vi = 'Bé quấy nhiều và không chịu ở trong nhà? Hãy hỏi Trợ lý thời tiết và trang phục rồi ra công viên 20 phút ngay nhé.', title_zh = '大自然来救场 🌳', body_zh = '宝宝特别爱闹，在家待不住？从天气穿衣助手那里获取建议，马上去公园走20分钟吧。' WHERE id = 'f1d99477-a71b-4368-b9eb-c5c699e49b39' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te compares 🛑', body_es = 'Olvida la frase «el bebé de fulanita ya anda». Cada peque tiene su propio ritmo de desarrollo. Desahógate en la Comunidad Anacan con mamás que piensan como tú.', title_fr = 'Ne vous comparez pas 🛑', body_fr = 'Oubliez la phrase « Le bébé d''Untel marche déjà ». Chaque enfant a son propre rythme de développement. Échangez avec des mamans qui pensent comme vous dans la Communauté Anacan.', title_hi = 'खुद की तुलना मत कीजिए 🛑', body_hi = '''फलाँ का बच्चा तो चलने भी लगा'' वाली बात भूल जाइए। हर बच्चे के विकास की रफ़्तार अनोखी होती है। Anacan कम्युनिटी में अपने जैसी सोच वाली माँओं से दिल की बात कीजिए।', title_id = 'Jangan membandingkan diri 🛑', body_id = 'Lupakan kalimat "Anak si anu sudah bisa jalan". Setiap anak punya tempo perkembangan yang unik. Mengobrollah dengan ibu-ibu yang sepemikiran di Komunitas Anacan.', title_ja = 'くらべないで 🛑', body_ja = '「〇〇ちゃんはもう歩いてる」という言葉は忘れましょう。成長のペースはどの子もそれぞれです。Anacanコミュニティで、あなたと同じ気持ちのママたちと話しましょう。', title_ko = '비교하지 마세요 🛑', body_ko = '''누구네 아이는 벌써 걷는대''라는 말은 잊으세요. 아이마다 발달 속도는 저마다 달라요. Anacan 커뮤니티에서 같은 마음의 엄마들과 이야기를 나눠 보세요.', title_nl = 'Vergelijk niet 🛑', body_nl = 'Vergeet de zin: het kindje van die-en-die loopt al. Elk kind ontwikkelt zich in zijn eigen tempo. Praat in de Anacan Community met moeders die net zo denken als jij.', title_pl = 'Nie porównuj się 🛑', body_pl = 'Zapomnij o zdaniu „dziecko tej i tej już chodzi”. Każde dziecko rozwija się we własnym tempie. Porozmawiaj z mamami, które myślą tak jak ty, w Społeczności Anacan.', title_pt = 'Não se compare 🛑', body_pt = 'Esqueça a frase "o filho de fulana já anda". Cada criança tem o seu próprio ritmo de desenvolvimento. Desabafe na Comunidade Anacan com mães que pensam como a senhora.', title_sv = 'Jämför inte dig själv 🛑', body_sv = 'Glöm meningen ''hennes barn går redan''. Varje barn utvecklas i sin egen takt. Prata med mammor som tänker som du i Anacans Community.', title_vi = 'Đừng so sánh 🛑', body_vi = 'Hãy quên câu "Con nhà người ta đã biết đi rồi". Mỗi em bé có nhịp phát triển riêng. Hãy tâm sự cùng những bà mẹ đồng cảm trong Cộng đồng Anacan.', title_zh = '别去比较 🛑', body_zh = '忘掉“某某家的孩子已经会走了”这句话吧。每个孩子的发育节奏都是独一无二的。在Anacan社区和想法相同的妈妈们聊聊吧。' WHERE id = '2958c07b-39da-4ecb-ac79-c0f1640a7d1a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'A la espera de la palabra «mamá» 🥰', body_es = 'Dice sílabas distintas. ¡Su primer «mamá» o «papá» consciente está muy cerca! Anímale respondiendo a sus sonidos con cariño.', title_fr = 'En attendant le mot « maman » 🥰', body_fr = 'Il prononce différentes syllabes. Son premier « maman » ou « papa » conscient est tout proche ! Répondez à ses sons avec amour pour l''encourager.', title_hi = '''माँ'' शब्द का इंतज़ार 🥰', body_hi = 'अलग-अलग अक्षर बोलता है। पहली बार सोच-समझकर ''माँ'' या ''पापा'' कहना बहुत करीब है! उसकी आवाज़ों का प्यार से जवाब देकर उसका हौसला बढ़ाइए।', title_id = 'Menanti kata "Ibu" 🥰', body_id = 'Ia mengeluarkan berbagai suku kata. Kata "Ibu" atau "Ayah" pertama yang disadari sudah sangat dekat! Tanggapi suaranya dengan penuh cinta dan beri ia semangat.', title_ja = '「ママ」を待ちわびて 🥰', body_ja = 'いろいろな音を出しています。初めての意味のある「ママ」や「パパ」はもうすぐです！声に愛情たっぷりに応えて、勇気づけてあげましょう。', title_ko = '''엄마'' 소리를 기다리며 🥰', body_ko = '여러 가지 소리를 내고 있나요? 의미 있는 첫 ''엄마''나 ''아빠''가 머지않았어요! 사랑으로 반응하며 용기를 북돋아 주세요.', title_nl = 'Wachten op ''mama'' 🥰', body_nl = 'Je baby maakt allerlei lettergrepen. Het eerste bewuste ''mama'' of ''papa'' is heel dichtbij! Reageer liefdevol op zijn geluidjes en moedig hem aan.', title_pl = 'W oczekiwaniu na „mama” 🥰', body_pl = 'Wymawia różne sylaby. Pierwsze świadome „mama” lub „tata” jest już bardzo blisko! Odpowiadaj z miłością na jego głos i dodawaj mu odwagi.', title_pt = 'À espera da palavra "mamã" 🥰', body_pt = 'Faz sílabas variadas. A primeira palavra "mamã" ou "papá" dita com intenção está muito perto! Responda com carinho aos sons dele e encoraje-o.', title_sv = 'Väntan på ordet mamma 🥰', body_sv = 'Barnet säger olika stavelser. Det första medvetna ''mamma'' eller ''pappa'' är väldigt nära! Uppmuntra barnet genom att svara på ljuden med kärlek.', title_vi = 'Chờ đợi tiếng "Mẹ" 🥰', body_vi = 'Bé phát ra nhiều âm tiết khác nhau. Tiếng "Mẹ" hay "Bố" có ý thức đầu tiên đã rất gần rồi! Hãy đáp lại bé bằng tình yêu để khích lệ bé.', title_zh = '期待那声“妈妈” 🥰', body_zh = '宝宝在发出各种音节。第一声有意识的“妈妈”或“爸爸”就快来了！满怀爱意地回应宝宝，给宝宝鼓励吧。' WHERE id = 'da431940-9d6b-4ed8-a933-fd80b83687d9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La música es alimento para el alma 🎶', body_es = 'Prueba a calmar con música clásica suave esas tormentas sin motivo que estallan al caer la tarde. Muchas veces este truco tan sencillo hace milagros.', title_fr = 'La musique nourrit l''âme 🎶', body_fr = 'Essayez de calmer les tempêtes inexpliquées de fin de journée avec une musique classique douce. Souvent, cette astuce toute simple fait des miracles.', title_hi = 'संगीत आत्मा का भोजन है 🎶', body_hi = 'शाम को अचानक उठने वाले बेवजह तूफ़ानों को हल्के क्लासिकल संगीत से शांत करके देखिए। अक्सर यह आसान तरकीब कमाल कर देती है।', title_id = 'Musik adalah makanan jiwa 🎶', body_id = 'Coba redakan badai tanpa sebab menjelang sore dengan musik klasik yang lembut. Sering kali trik sederhana ini membawa keajaiban.', title_ja = '音楽は心の栄養 🎶', body_ja = '夕方に突然始まる理由のわからない嵐には、静かなクラシック音楽を試してみましょう。このシンプルな方法が、たいてい奇跡を起こします。', title_ko = '음악은 마음의 양식 🎶', body_ko = '늦은 오후에 몰아치는 이유 없는 울음을 잔잔한 클래식 음악으로 달래 보세요. 이 간단한 방법이 기적을 만들 때가 많아요.', title_nl = 'Muziek is voedsel voor de ziel 🎶', body_nl = 'Probeer de onverklaarbare stormen aan het eind van de middag te stoppen met zachte klassieke muziek. Vaak doet dit simpele trucje wonderen.', title_pl = 'Muzyka to pokarm dla duszy 🎶', body_pl = 'Wieczorne burze bez powodu spróbuj uciszyć spokojną muzyką klasyczną. Często ten prosty trik czyni cuda.', title_pt = 'A música é o alimento da alma 🎶', body_pt = 'Experimente acalmar com música clássica suave as tempestades sem motivo que rebentam ao fim da tarde. Muitas vezes, este truque simples faz milagres.', title_sv = 'Musik är föda för själen 🎶', body_sv = 'Prova att bryta oförklarliga stormar på eftermiddagen med lätt klassisk musik. Ofta gör det här enkla knepet underverk.', title_vi = 'Âm nhạc là món ăn tinh thần 🎶', body_vi = 'Hãy thử dỗ những cơn quấy khóc không rõ lý do vào chiều tối bằng nhạc cổ điển nhẹ nhàng. Thường thì mẹo đơn giản này tạo nên điều kỳ diệu.', title_zh = '音乐是心灵的食粮 🎶', body_zh = '傍晚无缘无故的哭闹风暴，试试用轻柔的古典音乐平息。这个简单的小窍门常常有奇效。' WHERE id = 'f40e6c18-873e-481a-ba28-76a5634b977a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Vitaminas para mamá 🥑', body_es = 'Haces de todo para que coma bien. ¿Y tú? Elige en la sección Recetas saludables una comida ligera rica en hierro y calcio.', title_fr = 'Des vitamines pour maman 🥑', body_fr = 'Vous faites tout pour bien le nourrir. Et vous ? Choisissez dans les Recettes saines un déjeuner léger riche en fer et en calcium.', title_hi = 'माँ के लिए विटामिन 🥑', body_hi = 'उसका पेट भरने के लिए आप सब कुछ करती हैं। और आप? सेहतमंद रेसिपी सेक्शन से आयरन और कैल्शियम से भरपूर हल्का लंच चुनिए।', title_id = 'Vitamin untuk Bunda 🥑', body_id = 'Anda melakukan segalanya agar ia kenyang. Bagaimana dengan Anda? Pilih makan siang ringan yang kaya zat besi dan kalsium dari bagian Resep Sehat.', title_ja = 'ママのビタミン 🥑', body_ja = '赤ちゃんにお腹いっぱい食べさせるために、なんでもしていますね。でもあなたは？「ヘルシーレシピ」から、鉄分とカルシウムたっぷりの軽いランチを選びましょう。', title_ko = '엄마를 위한 비타민 🥑', body_ko = '아기를 배불리 먹이려고 뭐든 하죠. 그런데 엄마는요? 건강한 레시피 섹션에서 철분과 칼슘이 풍부한 가벼운 점심을 골라 보세요.', title_nl = 'Vitamines voor mama 🥑', body_nl = 'Je doet alles om je baby goed te laten eten. En jij? Kies in het onderdeel Gezonde recepten een lichte lunch vol ijzer en calcium.', title_pl = 'Witaminy dla mamy 🥑', body_pl = 'Robisz wszystko, żeby go nakarmić. A ty? Wybierz w sekcji Zdrowe przepisy lekki obiad bogaty w żelazo i wapń.', title_pt = 'Vitaminas para a mãe 🥑', body_pt = 'Faz tudo para o alimentar. E a mãe? Escolha na secção Receitas Saudáveis um almoço leve, rico em ferro e cálcio.', title_sv = 'Vitaminer till mamma 🥑', body_sv = 'Du gör allt för att barnet ska bli mätt. Men du själv då? Välj en lätt lunch rik på järn och kalcium i avsnittet Hälsosamma recept.', title_vi = 'Vitamin cho mẹ 🥑', body_vi = 'Mẹ làm mọi thứ để bé được no. Còn mẹ thì sao? Hãy chọn một bữa trưa nhẹ, giàu sắt và canxi từ mục Công thức lành mạnh.', title_zh = '妈妈的维生素 🥑', body_zh = '你为了让宝宝吃饱想尽办法。那你自己呢？从健康食谱里挑一份富含铁和钙的清淡午餐吧。' WHERE id = '0c385e87-5c02-4870-85f8-9ab052891af8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Aléjate de las pantallas 📱', body_es = 'Una hora antes de dormir por la noche, apaga todas las teles y pantallas de casa. La melatonina se segrega más rápido solo en un ambiente tranquilo y oscuro.', title_fr = 'Éloignez-vous des écrans 📱', body_fr = '1 heure avant le coucher, éteignez toutes les télévisions et tous les écrans de la maison. La sécrétion de mélatonine ne s''accélère que dans un environnement calme et sombre.', title_hi = 'स्क्रीन से दूर रहिए 📱', body_hi = 'रात की नींद से 1 घंटा पहले घर के सारे टीवी और स्क्रीन बंद कर दीजिए। मेलाटोनिन शांत और अँधेरे माहौल में ही तेज़ी से बनता है।', title_id = 'Jauhi layar 📱', body_id = 'Satu jam sebelum tidur malam, matikan semua TV dan layar di rumah. Produksi melatonin hanya meningkat di lingkungan yang tenang dan redup.', title_ja = '画面から離れよう 📱', body_ja = '夜寝る1時間前には、家のテレビや画面をすべて消しましょう。メラトニンは、静かで暗い環境でこそ分泌が進みます。', title_ko = '화면에서 멀어지기 📱', body_ko = '밤잠 1시간 전에 집 안의 TV와 화면을 모두 끄세요. 멜라토닌 분비는 조용하고 어두운 환경에서만 빨라져요.', title_nl = 'Weg van de schermen 📱', body_nl = 'Doe 1 uur voor de nachtslaap alle tv''s en schermen in huis uit. Melatonine wordt alleen in een rustige, donkere omgeving sneller aangemaakt.', title_pl = 'Odsuń się od ekranów 📱', body_pl = 'Na godzinę przed nocnym snem wyłącz w domu wszystkie telewizory i ekrany. Wydzielanie melatoniny przyspiesza tylko w spokojnym i ciemnym otoczeniu.', title_pt = 'Afaste-se dos ecrãs 📱', body_pt = '1 hora antes do sono da noite, desligue todas as televisões e ecrãs da casa. A produção de melatonina só acelera num ambiente calmo e escuro.', title_sv = 'Bort från skärmarna 📱', body_sv = 'Stäng av alla tv-apparater och skärmar hemma 1 timme före nattsömnen. Melatonin utsöndras snabbare bara i en lugn och mörk miljö.', title_vi = 'Tránh xa màn hình 📱', body_vi = '1 tiếng trước giấc ngủ đêm, hãy tắt hết tivi và màn hình trong nhà. Melatonin chỉ được tiết ra nhanh hơn trong môi trường yên tĩnh và tối.', title_zh = '远离屏幕 📱', body_zh = '夜间睡眠前1小时，关掉家里所有的电视和屏幕。褪黑素只有在安静、黑暗的环境里才会加速分泌。' WHERE id = 'effeac28-8d9e-4d0e-b754-fb4004990432' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cuál es el tema de esta noche?🪄', body_es = 'Esta noche, que la inteligencia artificial escriba el cuento: La ardillita que busca sus juguetes. Que solo tu voz cariñosa rompa el silencio de la noche.', title_fr = 'Quel est le thème de ce soir ? 🪄', body_fr = 'Ce soir, laissez l''intelligence artificielle écrire l''histoire : « Le petit écureuil qui cherche ses jouets ». Que seule votre voix tendre rompe le silence de la nuit.', title_hi = 'आज शाम की थीम क्या है? 🪄', body_hi = 'आज शाम कहानी AI लिखे: ''अपने खिलौने ढूँढती नन्ही गिलहरी''। रात की खामोशी को बस आपकी प्यार भरी आवाज़ तोड़े।', title_id = 'Apa tema malam ini?🪄', body_id = 'Malam ini, biar AI yang menulis ceritanya: Tupai kecil yang mencari mainannya. Biarkan hanya suara lembut Anda yang memecah keheningan malam.', title_ja = '今夜のテーマは？🪄', body_ja = '今夜はAIにお話を書いてもらいましょう：「おもちゃを探す小さなリス」。夜の静けさを破るのは、あなたのやさしい声だけに。', title_ko = '오늘 저녁의 주제는 무엇일까요?🪄', body_ko = '오늘 저녁은 AI가 이야기를 쓰게 해 보세요: 장난감을 찾는 꼬마 다람쥐. 밤의 고요는 엄마의 다정한 목소리만 깨우게 해 주세요.', title_nl = 'Wat is het thema vanavond?🪄', body_nl = 'Laat vanavond de AI het verhaal schrijven: een klein eekhoorntje dat zijn speeltjes zoekt. Laat alleen jouw lieve stem de stilte van de nacht doorbreken.', title_pl = 'Jaki temat na dziś wieczór? 🪄', body_pl = 'Dziś wieczorem niech bajkę napisze sztuczna inteligencja: Mała wiewiórka szukająca zabawek. Niech nocną ciszę przerywa tylko twój czuły głos.', title_pt = 'Qual é o tema desta noite?🪄', body_pt = 'Esta noite, deixe a inteligência artificial escrever a história: "O pequeno esquilo à procura dos seus brinquedos". Que só a sua voz carinhosa quebre o silêncio da noite.', title_sv = 'Vad har kvällen för tema?🪄', body_sv = 'Låt AI skriva sagan i kväll: Den lilla ekorren som letar efter sina leksaker. Låt bara din kärleksfulla röst bryta nattens tystnad.', title_vi = 'Tối nay chủ đề là gì?🪄', body_vi = 'Tối nay hãy để trí tuệ nhân tạo viết câu chuyện: "Chú sóc nhỏ đi tìm đồ chơi". Hãy để chỉ có giọng nói dịu dàng của mẹ phá vỡ sự tĩnh lặng của màn đêm.', title_zh = '今晚的主题是什么？🪄', body_zh = '今晚让AI来写故事：《寻找玩具的小松鼠》。让夜晚的宁静只被你温柔的声音打破吧。' WHERE id = '47fc8d5e-d99d-4104-9258-c8e18ad15266' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El lorito imitador 🦜', body_es = '¿Imita tu tos, tu risa o tus gestos con las manos? Eres el mejor espejo de la habitación. ¡Enséñale las expresiones más bonitas!', title_fr = 'Le petit perroquet imitateur 🦜', body_fr = 'Il imite votre toux, votre rire ou vos gestes ? Vous êtes son meilleur miroir. Montrez-lui les plus belles mimiques !', title_hi = 'नकल करने वाला तोता 🦜', body_hi = 'आपके खाँसने, हँसने या हाथ हिलाने की नकल करता है? कमरे में सबसे अच्छा आईना आप हैं। उसे सबसे प्यारे हाव-भाव सिखाइए!', title_id = 'Si burung beo peniru 🦜', body_id = 'Ia meniru batuk, tawa, atau gerakan tangan Anda? Andalah cermin terbaik di ruangan ini. Ajari ia ekspresi wajah yang paling indah!', title_ja = 'ものまねオウム 🦜', body_ja = 'あなたのせき、笑い声、手の動きをまねしていますか？部屋でいちばんの鏡はあなたです。すてきな表情をたくさん見せてあげましょう！', title_ko = '따라쟁이 앵무새 🦜', body_ko = '엄마의 기침, 웃음, 손짓을 따라 하나요? 방 안에서 가장 좋은 거울은 바로 엄마예요. 가장 예쁜 표정을 보여 주세요!', title_nl = 'Een papegaaitje dat alles nadoet 🦜', body_nl = 'Doet je baby je hoesten, je lach of je handgebaren na? Jij bent de beste spiegel in de kamer. Leer hem de mooiste gezichtsuitdrukkingen!', title_pl = 'Mała papużka naśladowczyni 🦜', body_pl = 'Naśladuje twój kaszel, śmiech albo gesty? To ty jesteś dla niego najlepszym lustrem. Pokazuj mu najpiękniejsze miny!', title_pt = 'O papagaio imitador 🦜', body_pt = 'Imita a sua tosse, o seu riso ou os seus gestos? No quarto, o melhor espelho é a mãe. Ensine-lhe as expressões mais bonitas!', title_sv = 'Den härmande papegojan 🦜', body_sv = 'Härmar barnet när du hostar, skrattar eller rör händerna? Du är den bästa spegeln i rummet. Lär barnet de finaste minerna!', title_vi = 'Chú vẹt bắt chước 🦜', body_vi = 'Bé bắt chước tiếng ho, tiếng cười hay cử chỉ tay của mẹ? Mẹ là tấm gương tốt nhất trong phòng. Hãy dạy bé những biểu cảm đẹp nhất!', title_zh = '学舌小鹦鹉 🦜', body_zh = '宝宝在模仿你咳嗽、大笑或者手势？你就是房间里最好的镜子。教宝宝最美的表情吧！' WHERE id = '856e1374-a46f-4ac4-b093-11e46392180f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Deja salir tus emociones 📝', body_es = '¿A veces solo quieres cerrar la puerta y llorar? Es de lo más normal... Escribir te sentará bien. Pasa tus emociones al Diario de ánimo.', title_fr = 'Libérez vos émotions 📝', body_fr = 'Parfois, vous avez juste envie de fermer la porte et de pleurer ? C''est tellement normal... Écrire vous fera du bien. Confiez vos émotions au Journal d''humeur.', title_hi = 'अपनी भावनाओं को बाहर आने दीजिए 📝', body_hi = 'कभी-कभी बस दरवाज़ा बंद करके रोने का मन करता है? यह बिल्कुल सामान्य है... लिखना आपके लिए अच्छा रहेगा। अपनी भावनाएँ मूड डायरी में उतार दीजिए।', title_id = 'Lepaskan perasaan Anda 📝', body_id = 'Kadang Anda hanya ingin menutup pintu dan menangis? Itu sangat wajar... Menulis akan membuat Anda lebih lega. Tuangkan perasaan Anda ke Buku Harian Suasana Hati.', title_ja = '気持ちを解き放とう 📝', body_ja = 'ときどき、ドアを閉めてただ泣きたくなる？それはとても普通のことです...書くと心が楽になります。気持ちを「気分日記」に書き写しましょう。', title_ko = '감정을 자유롭게 풀어 주세요 📝', body_ko = '가끔은 그냥 문을 닫고 울고 싶나요? 너무나 정상적인 일이에요... 글로 쓰면 한결 나아질 거예요. 기분 일기에 감정을 옮겨 보세요.', title_nl = 'Laat je gevoelens de vrije loop 📝', body_nl = 'Wil je soms gewoon de deur dichtdoen en huilen? Dat is zo normaal... Schrijven doet je goed. Zet je gevoelens in je Stemmingsdagboek.', title_pl = 'Uwolnij swoje uczucia 📝', body_pl = 'Czasem chcesz po prostu zamknąć drzwi i się wypłakać? To takie normalne... Pisanie dobrze ci zrobi. Przelej swoje uczucia do Dziennika nastroju.', title_pt = 'Liberte o que sente 📝', body_pt = 'Às vezes só lhe apetece fechar a porta e chorar? É tão normal... Escrever vai fazer-lhe bem. Passe o que sente para o Diário de Humor.', title_sv = 'Släpp fram dina känslor 📝', body_sv = 'Vill du ibland bara stänga dörren och gråta? Det är så normalt... Att skriva gör dig gott. För över dina känslor till Humördagboken.', title_vi = 'Hãy giải phóng cảm xúc 📝', body_vi = 'Đôi khi mẹ chỉ muốn đóng cửa lại và khóc? Điều đó bình thường lắm... Viết ra sẽ giúp mẹ dễ chịu hơn. Hãy chuyển cảm xúc vào Nhật ký tâm trạng.', title_zh = '释放你的感受 📝', body_zh = '有时候只想关上门哭一场？这太正常了……写下来会让你好受些。把感受写进心情日记吧。' WHERE id = 'e263bb82-67f5-4f23-9107-f117b8634a27' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Te está mirando 👀', body_es = 'Estés donde estés en la habitación, sus ojos están en ti. Eres su zona de seguridad. Cuando se te acabe la paciencia, recuerda su amor incondicional.', title_fr = 'Il vous regarde 👀', body_fr = 'Où que vous soyez dans la pièce, ses yeux sont sur vous. Vous êtes sa zone de sécurité. Quand votre patience s''épuise, souvenez-vous de cet amour inconditionnel.', title_hi = 'वह आपको देख रहा है 👀', body_hi = 'आप कमरे में कहीं भी हों, उसकी नज़रें आप पर ही रहती हैं। आप उसका सुरक्षित ठिकाना हैं। जब धैर्य जवाब दे, तो उसके इस बेशर्त प्यार को याद कीजिए।', title_id = 'Ia memandangi Anda 👀', body_id = 'Di mana pun Anda berada di kamar, matanya tertuju pada Anda. Anda adalah zona amannya. Saat kesabaran habis, ingatlah cintanya yang tulus ini.', title_ja = 'ママを見てる 👀', body_ja = '部屋のどこにいても、赤ちゃんの目はあなたを見ています。あなたは赤ちゃんの安心できる場所です。がまんの限界がきたら、このまっすぐな愛を思い出して。', title_ko = '아기가 엄마를 보고 있어요 👀', body_ko = '방 어디에 있든 아기의 눈은 엄마를 향해요. 엄마는 아기의 안전지대예요. 인내심이 바닥날 때 이 의심 없는 사랑을 떠올리세요.', title_nl = 'Hij kijkt naar jou 👀', body_nl = 'Waar je ook bent in de kamer, zijn ogen zijn op jou gericht. Jij bent zijn veilige plek. Denk aan zijn onvoorwaardelijke liefde als je geduld opraakt.', title_pl = 'On na ciebie patrzy 👀', body_pl = 'Gdziekolwiek jesteś w pokoju, jego oczy są zwrócone na ciebie. Jesteś jego strefą bezpieczeństwa. Gdy kończy ci się cierpliwość, pamiętaj o tej bezwarunkowej miłości.', title_pt = 'Ele está a olhar para si 👀', body_pt = 'Esteja onde estiver no quarto, os olhos dele estão em si. É a zona de segurança dele. Quando a paciência acabar, lembre-se deste amor sem condições.', title_sv = 'Barnet tittar på dig 👀', body_sv = 'Var du än är i rummet följer barnets blick dig. Du är dess trygga zon. När tålamodet tar slut, kom ihåg den här villkorslösa kärleken.', title_vi = 'Bé đang nhìn mẹ 👀', body_vi = 'Dù mẹ ở đâu trong phòng, ánh mắt bé vẫn hướng về mẹ. Mẹ là vùng an toàn của bé. Khi hết kiên nhẫn, hãy nhớ đến tình yêu vô điều kiện ấy.', title_zh = '宝宝在看着你 👀', body_zh = '不管你在房间哪里，宝宝的眼睛都看着你。你是宝宝的安全区。没耐心的时候，想想宝宝这份毫无保留的爱吧。' WHERE id = '3c29a397-ae21-4b66-9ae6-c3001d2f3e36' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte del desorden 🌪️', body_es = 'Esparce por todas partes todo lo que toca. Lo importante no es la limpieza, sino que tú descanses. Los juguetes seguirán ahí mañana, pero una mamá con energía hace falta ahora.', title_fr = 'L''art du désordre 🌪️', body_fr = 'Il éparpille tout ce avec quoi il joue. Ce n''est pas le ménage qui compte, mais votre repos. Les jouets seront encore là demain, mais c''est maintenant qu''il faut une maman en forme.', title_hi = 'बिखराव की कला 🌪️', body_hi = 'जिससे भी खेलता है, उसे चारों ओर बिखेर देता है। सफ़ाई नहीं, आपका आराम ज़रूरी है। खिलौने कल भी वहीं होंगे, पर तरोताज़ा माँ की ज़रूरत अभी है।', title_id = 'Seni kekacauan 🌪️', body_id = 'Ia menyebarkan semua mainannya ke mana-mana. Yang penting bukan kebersihan, melainkan istirahat Anda. Mainan itu besok juga masih di sana, tapi yang dibutuhkan sekarang adalah ibu yang bugar.', title_ja = '散らかしアート 🌪️', body_ja = '遊んだものをぜんぶまわりにばらまいています。大切なのはお掃除ではなく、あなたが休むことです。おもちゃは明日もそこにありますが、元気なママは今必要です。', title_ko = '어지르기의 예술 🌪️', body_ko = '가지고 노는 건 모두 사방에 흩어 놓아요. 청소보다 엄마의 휴식이 중요해요. 장난감은 내일도 그 자리에 있지만, 기운찬 엄마는 지금 필요해요.', title_nl = 'De kunst van rommel 🌪️', body_nl = 'Alles waarmee je baby speelt, ligt overal verspreid. Niet de schoonmaak, maar jouw rust is belangrijk. Het speelgoed ligt er morgen ook nog, maar een fitte mama is nu nodig.', title_pl = 'Sztuka bałaganu 🌪️', body_pl = 'Rozrzuca wokół wszystko, czym się bawi. Ważniejsze od sprzątania jest twoje odpoczywanie. Zabawki jutro też tam będą, ale wypoczęta mama potrzebna jest teraz.', title_pt = 'A arte da desarrumação 🌪️', body_pt = 'Espalha à volta tudo aquilo com que brinca. O importante não é a limpeza, é a mãe descansar. Os brinquedos amanhã continuam lá, mas uma mãe com energia faz falta agora.', title_sv = 'Konsten att stöka 🌪️', body_sv = 'Barnet sprider allt det leker med omkring sig. Det viktiga är inte städningen utan att du får vila. Leksakerna ligger kvar i morgon också, men en pigg mamma behövs nu.', title_vi = 'Nghệ thuật bừa bộn 🌪️', body_vi = 'Bé chơi gì cũng vứt khắp nơi. Điều quan trọng không phải là dọn dẹp mà là mẹ được nghỉ ngơi. Đồ chơi ngày mai vẫn ở đó, nhưng bé cần một người mẹ khỏe khoắn ngay lúc này.', title_zh = '凌乱的艺术 🌪️', body_zh = '宝宝玩什么都撒得到处都是。重要的不是打扫，而是你的休息。玩具明天还在那儿，但现在需要一个精神饱满的妈妈。' WHERE id = 'b3560b09-ab82-494c-a5e9-d6be5d4cb35a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El silencio de la noche 🤫', body_es = 'Si le molestan los coches o los ruidos de fuera, mantén siempre de fondo una fuente constante de ruido blanco.', title_fr = 'Le silence de la nuit 🤫', body_fr = 'Si les bruits de voitures ou de l''extérieur le dérangent, gardez absolument une source de bruit blanc continu en fond.', title_hi = 'रात की खामोशी 🤫', body_hi = 'अगर गाड़ियों या बाहर की आवाज़ें उसे परेशान करती हैं, तो पीछे लगातार चलने वाला व्हाइट नॉइज़ ज़रूर रखिए।', title_id = 'Keheningan malam 🤫', body_id = 'Jika suara mobil atau suara dari luar mengganggunya, pastikan ada sumber white noise yang terus menyala di latar belakang.', title_ja = '夜の静けさ 🤫', body_ja = '車や外の音が気になるようなら、ホワイトノイズを途切れずに流しておきましょう。', title_ko = '밤의 고요 🤫', body_ko = '자동차나 바깥 소리가 아기를 방해한다면 배경에 일정한 백색소음을 꼭 틀어 두세요.', title_nl = 'De stilte van de nacht 🤫', body_nl = 'Hebben auto''s of andere geluiden van buiten last van hem? Laat dan zeker een constante bron van witte ruis op de achtergrond aanstaan.', title_pl = 'Nocna cisza 🤫', body_pl = 'Jeśli przeszkadzają mu samochody lub hałas z zewnątrz, koniecznie miej w tle stałe źródło białego szumu.', title_pt = 'O silêncio da noite 🤫', body_pt = 'Se os carros ou os barulhos de fora o incomodam, mantenha sempre uma fonte constante de ruído branco em fundo.', title_sv = 'Nattens tystnad 🤫', body_sv = 'Om bilar eller ljud utifrån stör barnet, ha alltid en jämn källa till vitt brus i bakgrunden.', title_vi = 'Sự tĩnh lặng của màn đêm 🤫', body_vi = 'Nếu tiếng xe cộ hay tiếng ồn bên ngoài làm bé khó chịu, nhất định hãy duy trì một nguồn tiếng ồn trắng liên tục làm nền.', title_zh = '夜晚的宁静 🤫', body_zh = '如果汽车声或外面的声音打扰到宝宝，一定要在背景里放着持续的白噪音。' WHERE id = 'fe563692-e0de-40b2-aa34-9d6335348a54' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El salón de masajes de papá 💆‍♀️', body_es = 'Que tu pareja acueste al bebé y después te dé un masaje de 5 minutos para esos músculos del cuello tan agarrotados.', title_fr = 'Le salon de massage de papa 💆‍♀️', body_fr = 'Que votre conjoint couche bébé, puis qu''il vous offre 5 minutes de massage pour vos muscles du cou tout noués !', title_hi = 'पापा का मसाज पार्लर 💆‍♀️', body_hi = 'बच्चे को आपके साथी सुलाएँ, और फिर आपकी अकड़ी हुई गर्दन की मांसपेशियों के लिए 5 मिनट की मालिश करें!', title_id = 'Salon pijat ayah 💆‍♀️', body_id = 'Biarkan pasangan Anda yang menidurkan si kecil, lalu memberi pijatan 5 menit untuk otot leher Anda yang kaku!', title_ja = 'パパのマッサージサロン 💆‍♀️', body_ja = '赤ちゃんの寝かしつけはパートナーにまかせて、そのあとは、こわばったあなたの首のために5分間マッサージしてもらいましょう！', title_ko = '아빠의 마사지 숍 💆‍♀️', body_ko = '배우자가 아이를 재우게 하고, 그다음 뭉친 목 근육을 위해 5분 마사지를 해 달라고 하세요!', title_nl = 'Papa''s massagesalon 💆‍♀️', body_nl = 'Laat je partner de baby in slaap brengen en daarna 5 minuten je stijve nekspieren masseren!', title_pl = 'Salon masażu taty 💆‍♀️', body_pl = 'Niech partner uśpi maluszka, a potem zrobi ci 5-minutowy masaż spiętych mięśni karku!', title_pt = 'O salão de massagens do pai 💆‍♀️', body_pt = 'Que seja o seu companheiro a adormecer o bebé e depois a fazer-lhe uma massagem de 5 minutos ao pescoço tenso!', title_sv = 'Pappas massagesalong 💆‍♀️', body_sv = 'Låt din partner söva barnet och sedan ge dig en 5 minuters massage för dina spända nackmuskler!', title_vi = 'Tiệm mát-xa của bố 💆‍♀️', body_vi = 'Hãy để bố ru bé ngủ, rồi dành 5 phút mát-xa cho những cơ cổ đang căng cứng của mẹ!', title_zh = '爸爸的按摩室 💆‍♀️', body_zh = '让伴侣去哄宝宝睡觉，然后再给你僵硬的脖子按摩5分钟吧！' WHERE id = '268d0edd-f8c9-45fd-af24-4b1bd27e458d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Batallas a la hora de comer 🥣', body_es = '¿Aparta el puré? No le obligues a comer. Para no estropear su relación con la comida, convierte el momento en un juego y lee recetas alternativas en la comunidad.', title_fr = 'La guerre des repas 🥣', body_fr = 'Il repousse sa purée ? Ne le forcez pas. Pour ne pas abîmer sa relation à la nourriture, transformez le repas en jeu et lisez d''autres recettes dans la Communauté.', title_hi = 'खाने की जंग 🥣', body_hi = 'प्यूरी दूर धकेल देता है? ज़बरदस्ती मत खिलाइए। खाने से उसका रिश्ता न बिगड़े, इसलिए इसे खेल बनाइए और कम्युनिटी से दूसरी रेसिपी पढ़िए।', title_id = 'Perang di meja makan 🥣', body_id = 'Ia mendorong puree-nya menjauh? Jangan memaksa. Agar hubungannya dengan makanan tidak rusak, jadikan prosesnya permainan dan baca resep alternatif di Komunitas.', title_ja = 'ごはんバトル 🥣', body_ja = 'ペーストを押しのける？無理に食べさせないで。食べ物との関係をこわさないように遊びを取り入れて、コミュニティでほかのレシピも読んでみましょう。', title_ko = '식사 전쟁 🥣', body_ko = '퓌레를 밀어내나요? 억지로 먹이지 마세요. 음식에 대한 좋은 관계를 지키려면 식사를 놀이처럼 만들고 커뮤니티에서 다른 레시피도 읽어 보세요.', title_nl = 'Strijd aan tafel 🥣', body_nl = 'Duwt je baby de hap weg? Dwing hem niet. Maak er een spelletje van, zodat zijn relatie met eten niet verpest wordt, en lees andere recepten in de community.', title_pl = 'Wojny przy stole 🥣', body_pl = 'Odpycha przecier? Nie karm go na siłę. Żeby nie zepsuć jego stosunku do jedzenia, zamień posiłek w zabawę i poczytaj w Społeczności inne przepisy.', title_pt = 'Batalhas à mesa 🥣', body_pt = 'Afasta o puré? Não o obrigue a comer. Para não estragar a relação dele com a comida, transforme a refeição num jogo e leia receitas alternativas na comunidade.', title_sv = 'Matkrig 🥣', body_sv = 'Skjuter barnet undan purén? Tvinga inte i barnet maten. Gör måltiden till en lek så att relationen till maten inte förstörs, och läs andra recept i Community.', title_vi = 'Cuộc chiến giờ ăn 🥣', body_vi = 'Bé đẩy món nghiền ra xa? Đừng ép bé ăn. Để không làm hỏng mối quan hệ của bé với đồ ăn, hãy biến bữa ăn thành trò chơi và đọc các công thức thay thế từ cộng đồng.', title_zh = '吃饭大作战 🥣', body_zh = '宝宝把果泥推开？别强迫喂。为了不破坏宝宝和食物的关系，把吃饭变成游戏，再去社区看看其他食谱吧。' WHERE id = 'b1d60979-35c2-486a-9e3b-5e85d1d3dbdf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Su carácter se está formando 🌟', body_es = 'Ya deja claro lo que le gusta y lo que no quiere de ninguna manera. Cuando su testarudez te agote, recuerda que en realidad está construyendo su personalidad.', title_fr = 'Son caractère se forme 🌟', body_fr = 'Il montre déjà clairement ce qu''il aime et ce qu''il refuse catégoriquement. Quand son entêtement vous épuise, rappelez-vous qu''il est en train de construire sa personnalité.', title_hi = 'स्वभाव आकार ले रहा है 🌟', body_hi = 'उसे क्या पसंद है और क्या बिल्कुल नहीं चाहिए, यह वह अब साफ़ जताने लगा है। जब उसकी ज़िद आपको थकाए, तो याद रखिए कि असल में यह उसके व्यक्तित्व का निर्माण है।', title_id = 'Karakternya mulai terbentuk 🌟', body_id = 'Ia sudah menunjukkan apa yang ia suka dan apa yang sama sekali tidak ia mau. Saat keras kepalanya membuat Anda lelah, ingatlah bahwa sebenarnya ia sedang membangun kepribadiannya.', title_ja = '性格が育っています 🌟', body_ja = '何が好きで、何が絶対にいやか、もうはっきり示しています。がんこさに疲れたときは、それが実は人格づくりなのだと思い出してください。', title_ko = '성격이 자라고 있어요 🌟', body_ko = '무엇을 좋아하고 무엇을 절대 싫어하는지 이제 분명히 표현해요. 고집에 지칠 때는 그게 사실 자아를 쌓아 가는 과정이라는 걸 기억하세요.', title_nl = 'Zijn karakter vormt zich 🌟', body_nl = 'Je baby laat al duidelijk merken wat hij leuk vindt en wat hij absoluut niet wil. Word je moe van zijn koppigheid? Bedenk dan dat dit eigenlijk het bouwen van zijn persoonlijkheid is.', title_pl = 'Kształtuje się charakter 🌟', body_pl = 'Już wyraźnie pokazuje, co lubi, a czego zdecydowanie nie chce. Gdy jego upór cię męczy, pamiętaj, że tak naprawdę buduje swoją osobowość.', title_pt = 'O carácter está a formar-se 🌟', body_pt = 'Já deixa claro do que gosta e do que não quer de forma nenhuma. Quando a teimosia a cansar, lembre-se de que, na verdade, é a personalidade a construir-se.', title_sv = 'Personligheten tar form 🌟', body_sv = 'Barnet visar redan tydligt vad det gillar och vad det absolut inte vill ha. När envisheten tröttar ut dig, kom ihåg att det egentligen är personligheten som byggs upp.', title_vi = 'Tính cách đang hình thành 🌟', body_vi = 'Bé đã thể hiện rõ mình thích gì và tuyệt đối không muốn gì. Khi sự bướng bỉnh khiến mẹ mệt, hãy nhớ rằng thật ra bé đang xây dựng cá tính của mình.', title_zh = '性格正在形成 🌟', body_zh = '宝宝已经会表明自己喜欢什么、坚决不要什么了。当宝宝的倔强让你疲惫时，记住这其实是在塑造个性。' WHERE id = '73d0b947-9db1-4d57-a222-c8c22a2a895b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La amistad entre mamás 💬', body_es = 'Compartir las dificultades aligera la carga. En la Comunidad Anacan hay miles de mujeres que sienten lo mismo que tú. Desahogarse es gratis.', title_fr = 'L''amitié entre mamans 💬', body_fr = 'Partager les difficultés allège la charge. Dans la Communauté Anacan, des milliers de femmes ressentent la même chose que vous. Se confier, c''est gratuit.', title_hi = 'माँओं की दोस्ती 💬', body_hi = 'मुश्किलें बाँटने से बोझ कम होता है। Anacan कम्युनिटी में आप जैसी भावनाओं से गुज़र रही हज़ारों महिलाएँ हैं। दिल की बात करना मुफ़्त है।', title_id = 'Persahabatan para ibu 💬', body_id = 'Berbagi kesulitan meringankan beban. Di Komunitas Anacan, ada ribuan perempuan yang merasakan hal yang sama dengan Anda. Bercerita itu gratis.', title_ja = 'ママ友のつながり 💬', body_ja = '大変なことを分かち合うと、負担が軽くなります。Anacanコミュニティには、あなたと同じ気持ちの女性が何千人もいます。話すのは無料です。', title_ko = '엄마들의 우정 💬', body_ko = '어려움을 나누면 짐이 가벼워져요. Anacan 커뮤니티에는 같은 마음을 겪는 수많은 여성이 있어요. 이야기를 나누는 건 무료예요.', title_nl = 'Vriendschap tussen moeders 💬', body_nl = 'Moeilijkheden delen maakt de last lichter. In de Anacan Community zijn duizenden vrouwen die hetzelfde voelen als jij. Je hart luchten is gratis.', title_pl = 'Przyjaźń mam 💬', body_pl = 'Dzielenie się trudnościami zmniejsza ciężar. W Społeczności Anacan są tysiące kobiet, które czują to samo co ty. Rozmowa nic nie kosztuje.', title_pt = 'A amizade entre mães 💬', body_pt = 'Partilhar as dificuldades torna o peso mais leve. Na Comunidade Anacan há milhares de mulheres que sentem o mesmo. Desabafar é grátis.', title_sv = 'Vänskap mellan mammor 💬', body_sv = 'Att dela svårigheterna gör bördan lättare. I Anacans Community finns tusentals kvinnor som känner likadant som du. Det kostar inget att prata av sig.', title_vi = 'Tình bạn giữa các bà mẹ 💬', body_vi = 'Chia sẻ khó khăn giúp gánh nặng vơi đi. Trong Cộng đồng Anacan có hàng nghìn người phụ nữ đang trải qua cảm xúc giống mẹ. Tâm sự thì không mất phí.', title_zh = '妈妈们的友谊 💬', body_zh = '分享困难能减轻负担。Anacan社区里有成千上万位和你感受相同的女性。倾诉是免费的。' WHERE id = '9596d063-607c-465f-9e92-b73f9f6f0ece' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El consuelo de papá 🫂', body_es = 'No intentes resolver tú sola las crisis nocturnas. Implica también a tu pareja. A veces otro olor y otros brazos calman al bebé al instante.', title_fr = 'Le réconfort de papa 🫂', body_fr = 'N''essayez pas de gérer seule les crises nocturnes. Impliquez votre conjoint. Parfois, une autre odeur et d''autres bras apaisent bébé instantanément.', title_hi = 'पापा से मिलने वाला सुकून 🫂', body_hi = 'रात के रोने के दौरों को अकेले सँभालने की कोशिश मत कीजिए। अपने साथी को भी शामिल कीजिए। कभी-कभी अलग खुशबू और अलग गोद बच्चे को तुरंत शांत कर देती है।', title_id = 'Hiburan dari ayah 🫂', body_id = 'Jangan coba mengatasi drama malam sendirian. Libatkan pasangan Anda. Kadang aroma dan pelukan yang berbeda langsung menenangkan bayi.', title_ja = 'パパのなぐさめ 🫂', body_ja = '夜のぐずりをひとりで解決しようとしないで。パートナーにも加わってもらいましょう。違うにおいや抱っこで、すぐに落ち着くこともあります。', title_ko = '아빠의 위로 🫂', body_ko = '밤의 울음을 혼자 해결하려 하지 마세요. 배우자도 함께하게 하세요. 때로는 다른 냄새와 품이 아기를 바로 진정시켜요.', title_nl = 'Troost van papa 🫂', body_nl = 'Probeer nachtelijke huilbuien niet alleen op te lossen. Betrek je partner erbij. Soms kalmeren een andere geur en andere armen je baby meteen.', title_pl = 'Pocieszenie od taty 🫂', body_pl = 'Nie próbuj sama radzić sobie z nocnymi kryzysami. Włącz w to partnera. Czasem inny zapach i inne ramiona od razu uspokajają maluszka.', title_pt = 'O conforto do pai 🫂', body_pt = 'Não tente resolver sozinha as crises da noite. Envolva também o seu companheiro. Às vezes, um cheiro e um colo diferentes acalmam o bebé no momento.', title_sv = 'Tröst från pappa 🫂', body_sv = 'Försök inte lösa nattens kriser helt ensam. Ta med din partner i processen. Ibland lugnar en annan doft och en annan famn barnet direkt.', title_vi = 'Sự an ủi từ bố 🫂', body_vi = 'Đừng cố một mình xử lý những cơn quấy đêm. Hãy để bố cùng tham gia. Đôi khi một mùi hương và vòng tay khác giúp bé nín ngay lập tức.', title_zh = '来自爸爸的安慰 🫂', body_zh = '夜里的哭闹别想着一个人解决。让伴侣也参与进来。有时换一种气味、换一个怀抱，宝宝马上就能安静下来。' WHERE id = 'fb27143e-60bd-4519-b45e-80c5584417a4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Equipo de palmas 👏', body_es = '¿Muestra su alegría dando palmas? Registra este gran logro motor en el Seguimiento del desarrollo y haz un pequeño baile de la victoria en casa.', title_fr = 'Bravo, on tape dans les mains 👏', body_fr = 'Il exprime sa joie en tapant des mains ? Notez cette superbe réussite motrice dans le Suivi de développement et faites une petite danse de la victoire à la maison.', title_hi = 'ताली बजाओ 👏', body_hi = 'अपनी खुशी ताली बजाकर जताता है? मोटर स्किल्स की इस शानदार उपलब्धि को ग्रोथ ट्रैकर में दर्ज कीजिए और घर में एक छोटा जीत का नाच कीजिए।', title_id = 'Tim tepuk tangan 👏', body_id = 'Ia menunjukkan kegembiraannya dengan bertepuk tangan? Catat pencapaian motorik yang hebat ini di Pelacak Perkembangan dan lakukan tarian kemenangan kecil di rumah.', title_ja = 'パチパチチーム 👏', body_ja = 'うれしいとき、手をパチパチたたいていますか？このすばらしい運動の成長を「発達トラッカー」に記録して、おうちで小さな勝利のダンスをしましょう。', title_ko = '짝짝짝 박수 👏', body_ko = '손뼉을 치며 기쁨을 표현하나요? 이 멋진 운동 발달을 성장 기록에 남기고 집에서 작은 승리의 춤을 춰 보세요.', title_nl = 'Het klapteam 👏', body_nl = 'Laat je baby zijn blijdschap zien door in zijn handjes te klappen? Noteer deze geweldige motorische prestatie in de Groeitracker en doe thuis een klein overwinningsdansje.', title_pl = 'Klaszczemy! 👏', body_pl = 'Okazuje radość, klaszcząc w rączki? Zapisz to wspaniałe osiągnięcie motoryczne w Śledzeniu rozwoju i zatańcz w domu mały taniec zwycięstwa.', title_pt = 'A equipa das palminhas 👏', body_pt = 'Mostra a alegria batendo palmas? Registe esta conquista motora fantástica no Registo de Desenvolvimento e faça em casa uma pequena dança da vitória.', title_sv = 'Klappa-händerna-laget 👏', body_sv = 'Visar barnet sin glädje genom att klappa händerna? Anteckna den här fantastiska motoriska bedriften i Utvecklingsspåraren och gör en liten segerdans hemma.', title_vi = 'Đội vỗ tay 👏', body_vi = 'Bé vỗ tay để thể hiện niềm vui? Hãy ghi lại thành tựu vận động tuyệt vời này trong Theo dõi phát triển và nhảy một điệu mừng chiến thắng nho nhỏ ở nhà nhé.', title_zh = '拍拍手 👏', body_zh = '宝宝开心时会拍手？在发育追踪里记下这项精彩的动作发展，在家跳一段小小的胜利舞吧。' WHERE id = '4e869b86-0b42-4c4a-86f7-22a0999a3387' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisión rápida 🤖', body_es = '¿Qué se espera del desarrollo a los 9 meses? Olvídate de los artículos largos. Pregunta directamente a Anacan AI y recibe una respuesta con precisión de pediatra.', title_fr = 'Bilan express 🤖', body_fr = 'Que doit-il savoir faire à 9 mois ? Oubliez les longs articles. Posez directement votre question à Anacan AI et obtenez une réponse précise comme celle d''un pédiatre.', title_hi = 'झटपट चेकअप 🤖', body_hi = '9 महीने के विकास से क्या उम्मीदें हैं? लंबे लेख छोड़िए। अपना सवाल सीधे Anacan AI से पूछिए और बाल रोग विशेषज्ञ जैसा सटीक जवाब पाइए।', title_id = 'Cek cepat 🤖', body_id = 'Apa saja harapan perkembangan di usia 9 bulan? Lupakan artikel panjang. Tanyakan langsung ke Anacan AI dan dapatkan jawaban setepat dokter anak.', title_ja = 'すばやくチェック 🤖', body_ja = '生後9か月の発達の目安は？長い記事は読まなくて大丈夫。Anacan AIに直接質問して、小児科医のように正確な答えを受け取りましょう。', title_ko = '빠른 체크업 🤖', body_ko = '9개월 발달 기준은 무엇일까요? 긴 글은 넘기세요. Anacan AI에게 바로 물어 소아과 수준의 정확한 답을 받아 보세요.', title_nl = 'Een snelle check-up 🤖', body_nl = 'Wat mag je verwachten van de ontwikkeling bij 9 maanden? Vergeet die lange artikelen. Stel je vraag direct aan Anacan AI en krijg een antwoord met de precisie van een kinderarts.', title_pl = 'Szybki przegląd 🤖', body_pl = 'Czego można się spodziewać w rozwoju 9-miesięcznego maluszka? Daruj sobie długie artykuły. Zadaj pytanie bezpośrednio Anacan AI i dostań odpowiedź z precyzją pediatry.', title_pt = 'Check-up rápido 🤖', body_pt = 'O que se espera do desenvolvimento aos 9 meses? Esqueça os artigos longos. Faça a pergunta diretamente ao Anacan AI e receba uma resposta com precisão de pediatra.', title_sv = 'Snabb kontroll 🤖', body_sv = 'Vad kan man förvänta sig av utvecklingen vid 9 månader? Strunta i långa artiklar. Ställ din fråga direkt till Anacan AI och få ett svar med en barnläkares precision.', title_vi = 'Kiểm tra nhanh 🤖', body_vi = 'Những mốc phát triển cần có ở tháng thứ 9 là gì? Bỏ qua những bài viết dài dòng. Hãy hỏi thẳng Anacan AI và nhận câu trả lời chính xác như bác sĩ nhi khoa.', title_zh = '快速检查 🤖', body_zh = '9个月的发育标准是什么？别看长篇文章了。直接问Anacan AI，获得儿科级别的准确答案。' WHERE id = '72a32149-c4d7-4a45-b296-5cc7c5b673ad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Preparando el sueño 🛀', body_es = 'Un baño templado siempre funciona. No rompas nunca la rutina de la noche, porque le indica a su cerebro que es hora de dormir.', title_fr = 'Préparation au coucher 🛀', body_fr = 'Un bain tiède fonctionne toujours. Ne brisez jamais la routine du soir, car elle envoie à son cerveau le signal « c''est l''heure de dormir ».', title_hi = 'सोने की तैयारी 🛀', body_hi = 'गुनगुना स्नान हमेशा काम आता है। शाम का रूटीन कभी मत तोड़िए, क्योंकि यह उसके दिमाग को ''सोने का समय'' का संकेत देता है।', title_id = 'Persiapan tidur 🛀', body_id = 'Mandi air hangat selalu ampuh. Jangan pernah melewatkan rutinitas malam, karena ini memberi sinyal "waktunya tidur" ke otaknya.', title_ja = 'ねんねの準備 🛀', body_ja = 'ぬるめのお風呂はいつも効果的です。夜のルーティンは決して崩さないで。脳に「ねんねの時間だよ」というサインを送ってくれます。', title_ko = '잠자리 준비 🛀', body_ko = '따뜻한 목욕은 언제나 효과가 있어요. 저녁 루틴은 절대 깨지 마세요. 아기 뇌에 ''이제 잘 시간''이라는 신호를 주거든요.', title_nl = 'Klaar voor de nacht 🛀', body_nl = 'Een lauw badje werkt altijd. Doorbreek de avondroutine nooit, want die geeft zijn hersenen het signaal: tijd om te slapen.', title_pl = 'Przygotowanie do snu 🛀', body_pl = 'Ciepła kąpiel zawsze działa. Nigdy nie łam wieczornej rutyny, bo to dla jego mózgu sygnał, że czas spać.', title_pt = 'Preparar o sono 🛀', body_pt = 'Um banho morno resulta sempre. Nunca quebre a rotina da noite, porque é ela que diz ao cérebro do bebé que é hora de dormir.', title_sv = 'Förberedelser för sömnen 🛀', body_sv = 'Ett ljummet bad fungerar alltid. Bryt aldrig kvällsrutinen, för den signalerar till barnets hjärna att det är dags att sova.', title_vi = 'Chuẩn bị đi ngủ 🛀', body_vi = 'Tắm nước ấm lúc nào cũng hiệu quả. Đừng bao giờ phá vỡ nếp sinh hoạt buổi tối, vì đó là tín hiệu "đến giờ ngủ rồi" gửi đến não bé.', title_zh = '睡前准备 🛀', body_zh = '温水澡总是管用。千万别打乱晚间作息，因为这是在给宝宝的大脑发出“该睡觉了”的信号。' WHERE id = 'df74b674-d83b-4306-a6c3-1477bd965efe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Recuerdos juntos 📸', body_es = '¡Sonríe de una forma tan bonita! Antes de dormir, haz una foto de esa carita inocente: estos momentos no volverán.', title_fr = 'Des souvenirs partagés 📸', body_fr = 'Il sourit si joliment ! Avant qu''il s''endorme, photographiez ce visage innocent, ces moments ne reviendront pas.', title_hi = 'साझी यादें 📸', body_hi = 'वह कितनी प्यारी मुस्कान देता है! सोने से पहले उस मासूम चेहरे की तस्वीर लीजिए, ये पल फिर कभी लौटकर नहीं आएँगे।', title_id = 'Kenangan bersama 📸', body_id = 'Senyumnya begitu indah! Foto wajah polosnya sebelum tidur, momen ini tidak akan terulang lagi.', title_ja = '一緒の思い出 📸', body_ja = 'なんてすてきな笑顔！寝る前のその無邪気な顔を撮っておきましょう。この瞬間は二度と戻ってきません。', title_ko = '함께하는 추억 📸', body_ko = '아기가 정말 예쁘게 웃어요! 잠들기 전 그 순수한 얼굴을 찍어 두세요, 이 순간은 다시 오지 않아요.', title_nl = 'Herinneringen samen 📸', body_nl = 'Hij lacht zo mooi! Maak voor het slapengaan een foto van dat onschuldige gezichtje, deze momenten komen nooit meer terug.', title_pl = 'Wspólne wspomnienia 📸', body_pl = 'Tak pięknie się uśmiecha! Przed snem sfotografuj tę niewinną buzię, te chwile już nie wrócą.', title_pt = 'Recordações partilhadas 📸', body_pt = 'Sorri de forma tão bonita! Antes de adormecer, fotografe aquele rosto inocente: estes momentos não voltam.', title_sv = 'Gemensamma minnen 📸', body_sv = 'Barnet ler så fint! Fotografera det oskyldiga ansiktet innan det somnar, de här stunderna kommer aldrig tillbaka.', title_vi = 'Kỷ niệm chung 📸', body_vi = 'Bé cười đẹp quá! Hãy chụp lại gương mặt ngây thơ ấy trước khi bé ngủ, những khoảnh khắc này sẽ không quay lại nữa.', title_zh = '共同的回忆 📸', body_zh = '宝宝笑得多美啊！睡前拍下那张纯真的小脸吧，这些时刻不会再回来了。' WHERE id = '5e8f6838-89c2-40a6-940e-2ef8b752a179' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reserva de hierro 🥩', body_es = 'La anemia puede quitarle tanto el apetito como la energía. Revisa su rutina de comidas y, si hace falta, pregunta a Anacan AI por alimentos ricos en hierro.', title_fr = 'Réserve de fer 🥩', body_fr = 'L''anémie peut couper l''appétit et l''énergie de l''enfant. Passez en revue sa routine alimentaire et, si besoin, interrogez Anacan AI sur les aliments riches en fer.', title_hi = 'आयरन का भंडार 🥩', body_hi = 'खून की कमी बच्चे की भूख और ऊर्जा दोनों कम कर सकती है। उसके खाने के रूटीन पर नज़र डालिए और ज़रूरत हो तो Anacan AI से आयरन वाले खानों के बारे में पूछिए।', title_id = 'Cadangan zat besi 🥩', body_id = 'Anemia bisa mengurangi nafsu makan dan energinya. Tinjau rutinitas makannya dan, bila perlu, tanyakan tentang makanan kaya zat besi ke Anacan AI.', title_ja = '鉄分の蓄え 🥩', body_ja = '貧血は、赤ちゃんの食欲も元気も奪ってしまうことがあります。食事のリズムを見直して、必要ならAnacan AIに鉄分の多い食べ物について聞いてみましょう。', title_ko = '철분 충전 🥩', body_ko = '빈혈은 아이의 식욕과 기운을 떨어뜨릴 수 있어요. 식사 일과를 점검하고 필요하면 Anacan AI에게 철분이 풍부한 음식에 대해 물어보세요.', title_nl = 'De ijzervoorraad 🥩', body_nl = 'Bloedarmoede kan de eetlust en de energie van je kindje verminderen. Bekijk het eetritme en vraag zo nodig Anacan AI naar ijzerrijke voeding.', title_pl = 'Zapas żelaza 🥩', body_pl = 'Anemia może odebrać dziecku i apetyt, i energię. Przejrzyj jego posiłki i w razie potrzeby zapytaj Anacan AI o pokarmy bogate w żelazo.', title_pt = 'Reserva de ferro 🥩', body_pt = 'A anemia pode tirar ao bebé tanto o apetite como a energia. Reveja a rotina das refeições e, se for preciso, pergunte ao Anacan AI sobre alimentos ricos em ferro.', title_sv = 'Järnförrådet 🥩', body_sv = 'Blodbrist kan minska både barnets aptit och energi. Gå igenom matrutinen och fråga Anacan AI om järnrik mat om det behövs.', title_vi = 'Kho dự trữ sắt 🥩', body_vi = 'Thiếu máu có thể làm bé chán ăn và thiếu năng lượng. Hãy xem lại nếp ăn uống của bé và nếu cần, hỏi Anacan AI về các thực phẩm giàu sắt.', title_zh = '补铁 🥩', body_zh = '贫血会影响宝宝的食欲和精力。检查一下宝宝的饮食安排，必要时向Anacan AI问问富含铁的食物吧。' WHERE id = '912ca02c-47d0-4e27-8bdb-7afe9ba868be' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de decir adiós 👋', body_es = '¿Dice adiós con la mano cuando alguien se va de casa? ¡Es una señal muy tierna de desarrollo social! Anímale mucho.', title_fr = 'C''est l''heure du coucou-au revoir 👋', body_fr = 'Il fait au revoir de la main quand quelqu''un quitte la maison ? C''est un signe adorable de développement social ! Encouragez-le beaucoup.', title_hi = 'बाय-बाय का समय 👋', body_hi = 'कोई घर से जाता है तो हाथ हिलाकर बाय करता है? यह सामाजिक विकास का बहुत प्यारा संकेत है! उसका खूब हौसला बढ़ाइए।', title_id = 'Waktunya dadah 👋', body_id = 'Ia melambaikan tangan saat seseorang pergi dari rumah? Ini tanda perkembangan sosial yang sangat manis! Beri ia banyak semangat.', title_ja = 'バイバイの時間 👋', body_ja = '誰かが出かけるとき、手を振ってバイバイしますか？社会性が育っている、とてもかわいいサインです！たくさんほめてあげましょう。', title_ko = '빠이빠이 시간 👋', body_ko = '누군가 집을 나설 때 손을 흔들며 인사하나요? 사회성 발달의 아주 귀여운 신호예요! 많이 칭찬해 주세요.', title_nl = 'Tijd om dag te zwaaien 👋', body_nl = 'Zwaait je baby gedag als iemand weggaat? Dat is een heel lief teken van sociale ontwikkeling! Moedig hem veel aan.', title_pl = 'Czas na pa-pa 👋', body_pl = 'Macha rączką na pożegnanie, gdy ktoś wychodzi z domu? To bardzo słodki znak rozwoju społecznego! Często go zachęcaj.', title_pt = 'Hora do adeus 👋', body_pt = 'Quando alguém sai de casa, diz adeus com a mão? É um sinal muito doce de desenvolvimento social! Encoraje-o muito.', title_sv = 'Dags för hej-då 👋', body_sv = 'Vinkar barnet hej då när någon går hemifrån? Det är ett väldigt gulligt tecken på social utveckling! Uppmuntra det massor.', title_vi = 'Giờ vẫy tay tạm biệt 👋', body_vi = 'Khi có ai đó ra về, bé vẫy tay chào tạm biệt? Đây là dấu hiệu rất đáng yêu của sự phát triển xã hội! Hãy khích lệ bé thật nhiều.', title_zh = '拜拜时间 👋', body_zh = '有人离开家时，宝宝会挥手说拜拜？这是社交发育非常可爱的表现！多多鼓励宝宝吧。' WHERE id = '0135df6f-fe6e-4faf-9136-dc65b2b29e33' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de silencio ⛅', body_es = 'Cuando aumenta la tensión, lo que más ayuda es salir por la puerta. Mira el tiempo, pon a tu peque en el carrito y simplemente camina para despejar la mente.', title_fr = 'À la recherche du calme ⛅', body_fr = 'Quand la tension monte, le meilleur remède est de passer la porte. Vérifiez la météo, installez-le dans la poussette et videz-vous la tête en marchant.', title_hi = 'सुकून की तलाश ⛅', body_hi = 'तनाव बढ़े तो सबसे अच्छा उपाय है दरवाज़े से बाहर निकल जाना। मौसम देखिए, उसे स्ट्रॉलर में बिठाइए और बस चलते हुए अपना दिमाग हल्का कीजिए।', title_id = 'Mencari ketenangan ⛅', body_id = 'Saat ketegangan memuncak, penyelamat terbaik adalah keluar rumah. Cek cuaca, dudukkan ia di stroller, dan jernihkan pikiran dengan berjalan kaki.', title_ja = '静けさを求めて ⛅', body_ja = 'ストレスがたまったら、いちばんの救いは外に出ること。天気をチェックしてベビーカーに乗せ、ただ歩いて頭をすっきりさせましょう。', title_ko = '고요함을 찾아서 ⛅', body_ko = '긴장이 쌓일 때 가장 좋은 해결책은 문밖으로 나가는 거예요. 날씨를 확인하고 유모차에 태워 그냥 걸으며 머리를 비워 보세요.', title_nl = 'Op zoek naar rust ⛅', body_nl = 'Als de spanning stijgt, is de beste redding de deur uitgaan. Kijk naar het weer, zet je baby in de kinderwagen en maak je hoofd leeg door gewoon te wandelen.', title_pl = 'W poszukiwaniu ciszy ⛅', body_pl = 'Gdy narasta napięcie, najlepszym ratunkiem jest wyjście za drzwi. Sprawdź pogodę, włóż go do wózka i po prostu oczyść głowę spacerem.', title_pt = 'À procura de silêncio ⛅', body_pt = 'Quando a tensão aumenta, a melhor salvação é sair porta fora. Veja o tempo, ponha-o no carrinho e limpe a cabeça a caminhar.', title_sv = 'På jakt efter tystnad ⛅', body_sv = 'När spänningen stiger är den bästa räddningen att gå ut genom dörren. Kolla vädret, lägg barnet i vagnen och rensa huvudet genom att bara gå.', title_vi = 'Tìm kiếm sự tĩnh lặng ⛅', body_vi = 'Khi căng thẳng dâng cao, cách giải cứu tốt nhất là bước ra khỏi cửa. Xem thời tiết, đặt bé vào xe đẩy và chỉ cần đi bộ để đầu óc thư thái.', title_zh = '寻找宁静 ⛅', body_zh = '压力越来越大时，最好的办法就是走出家门。看看天气，把宝宝放进婴儿车，走一走，清空一下大脑吧。' WHERE id = '44260d05-153e-4b6b-b9dd-6f07fb02c462' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La ilusión de la perfección 🛑', body_es = '¿Hoy nada ha salido según lo previsto? No te culpes. Eres una madre real, no una ilusión con filtro de las redes sociales.', title_fr = 'L''illusion de la perfection 🛑', body_fr = 'Rien ne s''est passé comme prévu aujourd''hui ? Ne vous culpabilisez pas. Vous êtes une vraie maman, pas une illusion filtrée des réseaux sociaux.', title_hi = 'परफ़ेक्शन का भ्रम 🛑', body_hi = 'आज कुछ भी योजना के मुताबिक नहीं हुआ? खुद को दोष मत दीजिए। आप एक असली माँ हैं, सोशल मीडिया का फ़िल्टर किया हुआ भ्रम नहीं।', title_id = 'Ilusi kesempurnaan 🛑', body_id = 'Hari ini tidak ada yang sesuai rencana? Jangan menyalahkan diri. Anda ibu yang nyata, bukan ilusi berfilter di media sosial.', title_ja = '完璧という幻 🛑', body_ja = '今日は何ひとつ計画どおりにいかなかった？自分を責めないで。あなたはリアルなママで、SNSのフィルター越しの幻ではありません。', title_ko = '완벽함이라는 환상 🛑', body_ko = '오늘 아무것도 계획대로 되지 않았나요? 자책하지 마세요. 당신은 SNS 속 필터 씌운 환상이 아니라 진짜 엄마예요.', title_nl = 'De illusie van perfectie 🛑', body_nl = 'Ging vandaag niets volgens plan? Geef jezelf niet de schuld. Je bent een echte moeder, geen gefilterde illusie van sociale media.', title_pl = 'Iluzja perfekcji 🛑', body_pl = 'Dziś nic nie poszło zgodnie z planem? Nie obwiniaj się. Jesteś prawdziwą mamą, a nie przefiltrowaną iluzją z mediów społecznościowych.', title_pt = 'A ilusão da perfeição 🛑', body_pt = 'Hoje nada correu como planeado? Não se culpe. É uma mãe real, não uma ilusão filtrada das redes sociais.', title_sv = 'Perfektionens illusion 🛑', body_sv = 'Gick ingenting enligt planen i dag? Skyll inte på dig själv. Du är en riktig mamma, inte en filtrerad illusion på sociala medier.', title_vi = 'Ảo tưởng về sự hoàn hảo 🛑', body_vi = 'Hôm nay không gì diễn ra theo kế hoạch? Đừng tự trách mình. Mẹ là một người mẹ thật, không phải ảo ảnh qua bộ lọc trên mạng xã hội.', title_zh = '完美的幻象 🛑', body_zh = '今天什么都没按计划进行？别责怪自己。你是一个真实的妈妈，不是社交媒体上加了滤镜的幻象。' WHERE id = '67247d93-ddf7-4fcc-adef-5828dde725b4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Se olvidan las pequeñas cosas del día. 🛒', body_es = '¿Se acabaron los pañales o las toallitas? Apúntalo en la Lista de la compra y que tu pareja lo compre al volver del súper.', title_fr = 'On oublie les petits besoins du quotidien. 🛒', body_fr = 'Plus de couches, plus de lingettes ? Ajoutez-les à la Liste de courses, votre conjoint s''en chargera en revenant du supermarché.', title_hi = 'रोज़ की छोटी ज़रूरतें भूल जाती हैं 🛒', body_hi = 'डायपर खत्म हो गए या वेट वाइप्स? शॉपिंग लिस्ट में डालिए, आपके साथी बाज़ार से लौटते समय ले आएँगे।', title_id = 'Kebutuhan kecil sehari-hari sering terlupa. 🛒', body_id = 'Popok atau tisu basah habis? Masukkan ke Daftar Belanja, biar pasangan Anda membelinya saat pulang dari pasar.', title_ja = '毎日のこまごましたものを忘れがち。🛒', body_ja = 'おむつがなくなった？おしりふき？「買い物リスト」に入れて、パートナーに帰りに買ってきてもらいましょう。', title_ko = '매일 필요한 자잘한 것들을 잊게 돼요. 🛒', body_ko = '기저귀가 떨어졌나요, 물티슈인가요? 쇼핑 목록에 넣어 두면 배우자가 마트에서 오는 길에 해결할 거예요.', title_nl = 'Kleine dagelijkse benodigdheden raken vergeten. 🛒', body_nl = 'Zijn de luiers op, of de billendoekjes? Zet het op je Boodschappenlijstje en laat je partner het op de terugweg van de supermarkt regelen.', title_pl = 'Drobne codzienne potrzeby umykają. 🛒', body_pl = 'Skończyły się pieluszki czy chusteczki nawilżane? Wrzuć je na Listę zakupów, a partner kupi je w drodze ze sklepu.', title_pt = 'As pequenas necessidades do dia esquecem-se. 🛒', body_pt = 'Acabaram as fraldas ou os toalhetes? Ponha na Lista de Compras e o seu companheiro trata disso ao voltar do supermercado.', title_sv = 'Små vardagsbehov glöms bort. 🛒', body_sv = 'Har blöjorna eller våtservetterna tagit slut? Släng in det i Inköpslistan, så fixar din partner det på vägen hem från affären.', title_vi = 'Những nhu cầu nhỏ hằng ngày dễ bị quên. 🛒', body_vi = 'Hết tã hay khăn ướt? Thêm vào Danh sách mua sắm để bố mua trên đường từ siêu thị về.', title_zh = '日常小必需品总是忘记 🛒', body_zh = '尿布用完了，还是湿巾？丢进购物清单，让伴侣从超市回来时搞定吧。' WHERE id = '4e8edba3-fd16-4c28-a7ff-08ff9853211e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El paso a dos siestas 🥱', body_es = '¿Tu peque, que dormía 3 siestas al día, ahora se resiste a la última? ¡Se está haciendo mayor! Es hora de adaptar su horario de sueño a 2 siestas.', title_fr = 'Le passage à deux siestes 🥱', body_fr = 'Il faisait 3 siestes par jour et résiste maintenant à la dernière ? Il grandit ! C''est le moment d''adapter son planning à 2 siestes.', title_hi = 'दो झपकियों की ओर 🥱', body_hi = 'दिन में 3 बार सोने वाला बच्चा अब आखिरी झपकी का विरोध करता है? वह बड़ा हो रहा है! नींद के शेड्यूल को 2 झपकियों के हिसाब से ढालने का समय आ गया है।', title_id = 'Peralihan ke 2 kali tidur siang 🥱', body_id = 'Si kecil yang biasanya tidur siang 3 kali kini menolak tidur yang terakhir? Ia sedang tumbuh! Saatnya menyesuaikan jadwal menjadi 2 kali tidur siang.', title_ja = 'お昼寝2回への移行 🥱', body_ja = '1日3回お昼寝していた子が、最後のお昼寝をいやがるようになった？大きくなっている証拠です！お昼寝を2回に合わせるときがきました。', title_ko = '낮잠 2번으로 전환 🥱', body_ko = '하루 3번 낮잠 자던 아이가 이제 마지막 낮잠을 거부하나요? 아이가 자라고 있어요! 낮잠 일정을 2번으로 맞출 때가 왔어요.', title_nl = 'Over naar twee slaapjes 🥱', body_nl = 'Slaapt je kindje overdag 3 keer, maar verzet hij zich tegen het laatste slaapje? Hij wordt groot! Tijd om het slaapschema aan te passen naar 2 slaapjes.', title_pl = 'Przejście na dwie drzemki 🥱', body_pl = 'Maluszek, który w dzień spał 3 razy, opiera się ostatniej drzemce? Rośnie! Czas dostosować plan snu do 2 drzemek.', title_pt = 'Passar para duas sestas 🥱', body_pt = 'O bebé que dormia 3 sestas por dia já resiste à última? Está a crescer! É altura de adaptar o horário de sono a 2 sestas.', title_sv = 'Övergång till två tupplurar 🥱', body_sv = 'Gör barnet som sover 3 gånger om dagen redan motstånd mot den sista luren? Barnet växer! Dags att anpassa sömnschemat till 2 tupplurar.', title_vi = 'Chuyển sang 2 giấc ngủ ngày 🥱', body_vi = 'Bé vốn ngủ ngày 3 giấc giờ lại chống đối giấc cuối? Bé đang lớn đấy! Đến lúc điều chỉnh lịch ngủ thành 2 giấc rồi.', title_zh = '过渡到两次小睡 🥱', body_zh = '白天睡3觉的宝宝开始抗拒最后一觉了？宝宝在长大！是时候把作息调整成2次小睡了。' WHERE id = '5f49ad4f-107b-4550-adae-e4aab3aa9d5b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pasos valientes 🧗‍♂️', body_es = '¿Se agarra a los muebles e intenta soltar una mano? Su sentido del equilibrio se desarrolla. Dale la mano y un poquito de confianza.', title_fr = 'Des pas courageux 🧗‍♂️', body_fr = 'Il se tient à un meuble et essaie de lâcher une main ? Son sens de l''équilibre se développe. Tenez-lui la main et donnez-lui un peu de confiance.', title_hi = 'हिम्मत भरे कदम 🧗‍♂️', body_hi = 'फ़र्नीचर पकड़कर एक हाथ छोड़ने की कोशिश करता है? उसका संतुलन विकसित हो रहा है। उसका हाथ थामिए और उसे थोड़ा भरोसा दीजिए।', title_id = 'Langkah-langkah berani 🧗‍♂️', body_id = 'Ia berpegangan pada perabot dan mencoba melepaskan satu tangan? Keseimbangannya sedang berkembang. Pegang tangannya dan beri ia sedikit rasa aman.', title_ja = '勇気ある一歩 🧗‍♂️', body_ja = '家具につかまって、片手を離そうとしていますか？バランス感覚が育っています。手を握って、少し自信をつけてあげましょう。', title_ko = '용감한 발걸음 🧗‍♂️', body_ko = '가구를 잡고 한 손을 놓아 보려 하나요? 균형 감각이 발달하고 있어요. 손을 잡아 주며 작은 자신감을 북돋아 주세요.', title_nl = 'Dappere stapjes 🧗‍♂️', body_nl = 'Houdt je baby zich vast aan een meubel en probeert hij één hand los te laten? Het evenwichtsgevoel ontwikkelt zich. Pak zijn hand en geef hem een beetje vertrouwen.', title_pl = 'Odważne kroki 🧗‍♂️', body_pl = 'Trzyma się mebli i próbuje puścić jedną rączkę? Rozwija się zmysł równowagi. Złap go za rączkę i dodaj mu trochę pewności.', title_pt = 'Passos corajosos 🧗‍♂️', body_pt = 'Agarra-se aos móveis e tenta largar uma mão? O equilíbrio está a desenvolver-se. Dê-lhe a mão e um pouco de confiança.', title_sv = 'Modiga steg 🧗‍♂️', body_sv = 'Håller barnet i möblerna och försöker släppa med ena handen? Balanssinnet utvecklas. Håll barnets hand och ge det lite trygghet.', title_vi = 'Những bước đi dũng cảm 🧗‍♂️', body_vi = 'Bé bám vào đồ đạc và thử buông một tay? Khả năng giữ thăng bằng đang phát triển. Hãy nắm tay bé và cho bé thêm chút tự tin.', title_zh = '勇敢的尝试 🧗‍♂️', body_zh = '宝宝扶着家具，试着松开一只手？平衡感正在发展。牵着宝宝的手，给宝宝一点信心吧。' WHERE id = '7ee44a70-ee6e-4b49-a487-76ff5581f580' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charla de complicidad 🥂', body_es = 'Abre el Diario de ánimo y comenta con tu pareja cómo os han cambiado estos meses. Ser un equipo es la mayor fuerza.', title_fr = 'Un moment de complicité 🥂', body_fr = 'Ouvrez le Journal d''humeur et parlez avec votre conjoint de la façon dont ces mois vous ont changés. Former une équipe, c''est la plus grande des forces.', title_hi = 'साथ की बातचीत 🥂', body_hi = 'मूड डायरी खोलिए और अपने साथी से बात कीजिए कि इन महीनों ने आप दोनों को कैसे बदला। टीम होना सबसे बड़ी ताकत है।', title_id = 'Obrolan kebersamaan 🥂', body_id = 'Buka Buku Harian Suasana Hati dan bicarakan bersama pasangan bagaimana bulan-bulan ini telah mengubah kalian. Menjadi satu tim adalah kekuatan terbesar.', title_ja = '支え合う語らい 🥂', body_ja = '「気分日記」を開いて、この数か月で2人がどう変わったかをパートナーと話し合いましょう。チームでいることがいちばんの力です。', title_ko = '함께하는 대화 🥂', body_ko = '기분 일기를 열고 배우자와 이 몇 달이 두 사람을 어떻게 바꿨는지 이야기해 보세요. 한 팀이라는 게 가장 큰 힘이에요.', title_nl = 'Een gesprek als team 🥂', body_nl = 'Open je Stemmingsdagboek en praat met je partner over hoe deze maanden jullie hebben veranderd. Een team zijn is de grootste kracht.', title_pl = 'Rozmowa o wspólnocie 🥂', body_pl = 'Otwórz Dziennik nastroju i porozmawiaj z partnerem o tym, jak te miesiące was zmieniły. Bycie drużyną to największa siła.', title_pt = 'Conversa de união 🥂', body_pt = 'Abra o Diário de Humor e fale com o seu companheiro sobre como estes meses vos mudaram. Ser uma equipa é a maior força.', title_sv = 'Samtal om samhörighet 🥂', body_sv = 'Öppna Humördagboken och prata med din partner om hur de här månaderna har förändrat er. Att vara ett lag är den största styrkan.', title_vi = 'Trò chuyện đồng lòng 🥂', body_vi = 'Hãy mở Nhật ký tâm trạng và cùng bố trò chuyện xem những tháng qua đã thay đổi hai người thế nào. Là một đội chính là sức mạnh lớn nhất.', title_zh = '团结的对话 🥂', body_zh = '打开心情日记，和伴侣聊聊这几个月给你们带来了怎样的改变。团队就是最大的力量。' WHERE id = '97d44a72-2ca4-4c0f-b997-91c31aeabbef' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿A veces los miedos pueden contigo? Mira su ropa limpia, su barriguita llena y esos ojos que te sonríen. ¡Lo estás haciendo de maravilla!', body_fr = 'Les peurs vous submergent parfois ? Regardez ses vêtements propres, son ventre plein et ses yeux qui vous sourient. Vous faites un travail formidable !', body_hi = 'कभी-कभी डर आप पर हावी हो जाते हैं? उसके साफ़ कपड़ों, भरे पेट और आपको देखकर मुस्कुराती आँखों को देखिए। आप शानदार काम कर रही हैं!', body_id = 'Kadang rasa takut menguasai Anda? Lihat bajunya yang bersih, perutnya yang kenyang, dan matanya yang tersenyum pada Anda. Anda melakukannya dengan luar biasa!', body_ja = 'ときどき不安に押しつぶされそう？清潔な服、お腹いっぱいのお腹、あなたに笑いかける目を見てください。あなたはすばらしくよくやっています！', body_ko = '가끔 두려움에 휩싸이나요? 아기의 깨끗한 옷, 부른 배, 엄마를 보며 웃는 눈을 보세요. 정말 잘하고 있어요!', body_nl = 'Word je soms overmand door angst? Kijk naar zijn schone kleertjes, zijn volle buikje en de ogen die naar je lachen. Je doet het geweldig!', body_pl = 'Czasem lęki biorą górę? Spójrz na jego czyste ubranko, pełny brzuszek i oczy, które się do ciebie śmieją. Świetnie sobie radzisz!', body_pt = 'Às vezes os medos são mais fortes? Olhe para a roupa limpa dele, para a barriguinha cheia e para os olhos que lhe sorriem. Está a sair-se lindamente!', body_sv = 'Tar rädslorna ibland överhanden? Titta på barnets rena kläder, mätta mage och ögon som ler mot dig. Du gör ett fantastiskt jobb!', body_vi = 'Đôi khi nỗi lo lấn át mẹ? Hãy nhìn bộ quần áo sạch sẽ, chiếc bụng no tròn và đôi mắt đang cười với mẹ của bé. Mẹ đang làm rất tuyệt vời!', body_zh = '有时候恐惧会压倒你？看看宝宝干净的衣服、吃饱的小肚子，还有冲你笑的眼睛。你做得非常棒！' WHERE id = 'ff86bc54-face-4f54-a1de-cc0ec9cccbc2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Nana de buenas noches 🎶', body_es = 'Esta noche deja la habitación totalmente a oscuras. Nada de tecnología, solo tu voz en susurros.', title_fr = 'Berceuse du soir 🎶', body_fr = 'Ce soir, faites le noir complet dans la chambre. Aucune technologie, seulement votre voix qui chuchote.', title_hi = 'रात की लोरी 🎶', body_hi = 'आज शाम कमरे में पूरा अँधेरा कीजिए। कोई तकनीक नहीं, बस आपकी धीमी फुसफुसाती आवाज़।', title_id = 'Nina bobo malam 🎶', body_id = 'Malam ini, buat kamar benar-benar gelap. Tanpa teknologi apa pun, hanya bisikan suara Anda.', title_ja = '夜の子守唄 🎶', body_ja = '今夜は部屋を真っ暗にしましょう。デジタル機器はなし、あなたのささやき声だけで。', title_ko = '밤의 자장가 🎶', body_ko = '오늘 저녁은 방을 완전히 어둡게 해 주세요. 어떤 기기도 없이 엄마의 속삭이는 목소리만으로요.', title_nl = 'Een slaapliedje voor de nacht 🎶', body_nl = 'Maak de kamer vanavond helemaal donker. Geen technologie, alleen jouw fluisterende stem.', title_pl = 'Kołysanka na noc 🎶', body_pl = 'Dziś wieczorem całkowicie zaciemnij pokój. Żadnej technologii, tylko twój szept.', title_pt = 'Canção de embalar da noite 🎶', body_pt = 'Esta noite, deixe o quarto completamente escuro. Nenhuma tecnologia, só a sua voz em sussurro.', title_sv = 'Vaggvisa för natten 🎶', body_sv = 'Gör rummet helt mörkt i kväll. Ingen teknik, bara din viskande röst.', title_vi = 'Lời ru ban đêm 🎶', body_vi = 'Tối nay hãy làm tối hẳn căn phòng. Không công nghệ, chỉ có tiếng thì thầm của mẹ.', title_zh = '晚安摇篮曲 🎶', body_zh = '今晚让房间完全暗下来。不用任何科技产品，只有你轻声细语的声音。' WHERE id = '801186a2-f617-44a4-bfbe-39fa8b84707d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Cuando llore sin motivo, no pierdas los nervios. Apóyate en el Análisis del llanto para encontrar y resolver el problema por el camino más corto.', body_fr = 'Quand il pleure sans raison, ne perdez pas pied. Appuyez-vous sur l''Analyse des pleurs pour trouver rapidement le problème et le résoudre.', body_hi = 'बेवजह रोने पर घबराइए मत। क्राइंग एनालिसिस की मदद लीजिए और समस्या जल्दी पहचानकर हल कीजिए।', body_id = 'Jangan panik saat ia menangis tanpa sebab. Minta bantuan Analisis Tangisan untuk menemukan dan mengatasi masalahnya dengan cepat.', body_ja = '理由もなく泣くときも、あわてないで。「泣き声分析」の助けを借りて、すばやく原因を見つけて解決しましょう。', body_ko = '이유 없이 울 때 당황하지 마세요. 울음 분석의 도움을 받아 문제를 빠르게 찾아 해결하세요.', body_nl = 'Raak niet van slag als je baby zonder reden huilt. Vraag Huilanalyse om hulp en vind snel de oorzaak en de oplossing.', body_pl = 'Gdy płacze bez powodu, nie trać głowy. Skorzystaj z pomocy Analizy płaczu, szybko znajdź problem i go rozwiąż.', body_pt = 'Quando chora sem motivo, não perca a calma. Peça ajuda à Análise do Choro, descubra rapidamente o problema e resolva-o.', body_sv = 'Tappa inte fattningen när barnet gråter utan anledning. Ta hjälp av Gråtanalys och hitta och lös problemet den snabba vägen.', body_vi = 'Khi bé khóc không rõ lý do, đừng hoảng. Hãy nhờ Phân tích tiếng khóc hỗ trợ để nhanh chóng tìm ra và giải quyết vấn đề.', body_zh = '宝宝无缘无故地哭时，别慌了手脚。借助哭声分析，快速找出问题并解决吧。' WHERE id = 'bcabe7b8-3e78-42a9-bdf0-3f1883219079' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mirando atrás 📈', body_es = '¿Cuánto camino ha recorrido tu peque? Los nervios de los primeros días han dado paso a la confianza. ¡Has recorrido este camino con una gran victoria!', title_fr = 'Un regard en arrière 📈', body_fr = 'Quel chemin votre enfant a parcouru ! L''émotion des premiers jours a laissé place à la confiance. Vous avez fait ce chemin avec une grande victoire !', title_hi = 'पीछे मुड़कर देखें 📈', body_hi = 'आपके बच्चे ने कितना लंबा सफ़र तय किया है! शुरुआती दिनों की घबराहट की जगह अब भरोसे ने ले ली है। आपने यह रास्ता बड़ी जीत के साथ तय किया!', title_id = 'Menengok ke belakang 📈', body_id = 'Betapa jauh si kecil sudah melangkah? Kecemasan di hari-hari pertama kini berganti dengan rasa percaya diri. Anda melewati perjalanan ini dengan kemenangan besar!', title_ja = '振り返り 📈', body_ja = '赤ちゃんはなんて長い道のりを歩んできたのでしょう！最初のころのドキドキは、自信に変わりました。あなたはこの道を見事に歩んできました！', title_ko = '돌아보기 📈', body_ko = '아이가 얼마나 먼 길을 왔는지 보세요! 처음 며칠의 설렘과 긴장이 이제 자신감으로 바뀌었어요. 이 길을 멋지게 승리하며 걸어왔어요!', title_nl = 'Terugblik 📈', body_nl = 'Wat heeft je kindje een weg afgelegd! De spanning van de eerste dagen heeft plaatsgemaakt voor vertrouwen. Je bent deze weg als een echte winnaar gegaan!', title_pl = 'Spojrzenie wstecz 📈', body_pl = 'Jak długą drogę przeszedł twój maluszek! Ekscytacja pierwszych dni ustąpiła miejsca pewności. Przeszłaś tę drogę jak zwyciężczyni!', title_pt = 'Olhar para trás 📈', body_pt = 'Que caminho o bebé já percorreu! A ansiedade dos primeiros dias deu lugar à confiança. Fez este caminho com uma grande vitória!', title_sv = 'En tillbakablick 📈', body_sv = 'Vilken väg ditt barn har gått! Spänningen från de första dagarna har ersatts av trygghet. Du har gått den här vägen med stor seger!', title_vi = 'Nhìn lại chặng đường 📈', body_vi = 'Bé đã đi được một chặng đường dài! Sự hồi hộp của những ngày đầu giờ đã thành niềm tin. Mẹ đã đi qua chặng đường này thật thắng lợi!', title_zh = '回顾 📈', body_zh = '宝宝走了多远的路啊！最初的紧张已经变成了自信。你一路凯歌走到了今天！' WHERE id = '327e6e73-14c5-44c7-86f9-1b01671cc4cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un poco de romanticismo 💖', body_es = 'Esta noche celebra con tu pareja, a la luz de las velas, el cansancio y el orgullo de estos 9 meses. ¡Sois un equipo perfecto!', title_fr = 'Un peu de romantisme 💖', body_fr = 'Ce soir, célébrez aux chandelles avec votre conjoint la fatigue et la fierté de ces 9 mois. Vous formez une équipe parfaite !', title_hi = 'थोड़ा रोमांस 💖', body_hi = '9 महीनों की थकान और गर्व का जश्न आज शाम अपने साथी के साथ मोमबत्ती की रोशनी में मनाइए। आप एक परफ़ेक्ट टीम हैं!', title_id = 'Sedikit romantis 💖', body_id = 'Malam ini, rayakan lelah dan bangganya 9 bulan ini bersama pasangan di bawah cahaya lilin. Kalian tim yang sempurna!', title_ja = 'ちょっぴりロマンス 💖', body_ja = '9か月分の疲れと誇りを、今夜はパートナーとキャンドルの明かりの中でお祝いしましょう。あなたたちは完璧なチームです！', title_ko = '약간의 로맨스 💖', body_ko = '오늘 저녁 배우자와 함께 촛불 아래에서 9개월의 피로와 뿌듯함을 기념하세요. 두 사람은 완벽한 팀이에요!', title_nl = 'Een beetje romantiek 💖', body_nl = 'Vier vanavond bij kaarslicht samen met je partner de vermoeidheid en de trots van 9 maanden. Jullie zijn een perfect team!', title_pl = 'Odrobina romantyzmu 💖', body_pl = 'Uczcij dziś wieczorem z partnerem przy świecach zmęczenie i dumę tych 9 miesięcy. Jesteście idealną drużyną!', title_pt = 'Um pouco de romance 💖', body_pt = 'Esta noite, celebre à luz das velas com o seu companheiro o cansaço e o orgulho destes 9 meses. São uma equipa perfeita!', title_sv = 'Lite romantik 💖', body_sv = 'Fira 9 månaders trötthet och stolthet tillsammans med din partner i levande ljus i kväll. Ni är ett perfekt lag!', title_vi = 'Một chút lãng mạn 💖', body_vi = 'Tối nay, hãy cùng bố ăn mừng 9 tháng mệt mỏi và tự hào bên ánh nến. Bố mẹ là một đội hoàn hảo!', title_zh = '一点浪漫 💖', body_zh = '今晚和伴侣一起在烛光下庆祝这9个月的疲惫与骄傲吧。你们是完美的团队！' WHERE id = '4b865d9a-0f66-4cb0-98d0-deaa6f061766' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidad de energía 🍲', body_es = 'El cansancio se te mete en los huesos. Elige en Recetas saludables una comida con mucho hierro y proteínas que se prepara en 10 minutos y recupera fuerzas.', title_fr = 'Besoin d''énergie 🍲', body_fr = 'La fatigue vous pèse jusqu''aux os. Choisissez dans les Recettes saines un déjeuner prêt en 10 minutes, riche en fer et en protéines, et reprenez des forces.', title_hi = 'ऊर्जा की ज़रूरत 🍲', body_hi = 'थकान हड्डियों तक उतर रही है। सेहतमंद रेसिपी से 10 मिनट में बनने वाला आयरन और प्रोटीन से भरपूर लंच चुनिए और ताकत जुटाइए।', title_id = 'Kebutuhan energi 🍲', body_id = 'Lelahnya terasa sampai ke tulang. Pilih makan siang kaya zat besi dan protein dari Resep Sehat yang siap dalam 10 menit, dan kumpulkan tenaga.', title_ja = 'エネルギー補給 🍲', body_ja = '疲れが体の芯までたまっています。「ヘルシーレシピ」から10分でできる、鉄分とたんぱく質たっぷりのランチを選んで、力をたくわえましょう。', title_ko = '에너지가 필요해요 🍲', body_ko = '피로가 뼛속까지 스며들어요. 건강한 레시피에서 10분 만에 만드는 철분과 단백질이 가득한 점심을 골라 힘을 모으세요.', title_nl = 'Energie nodig 🍲', body_nl = 'De vermoeidheid zit tot in je botten. Kies uit Gezonde recepten een lunch vol ijzer en eiwit die in 10 minuten klaar is en kom weer op krachten.', title_pl = 'Zapotrzebowanie na energię 🍲', body_pl = 'Zmęczenie daje ci się we znaki. Wybierz w Zdrowych przepisach obiad gotowy w 10 minut, pełen żelaza i białka, i nabierz sił.', title_pt = 'Necessidade de energia 🍲', body_pt = 'O cansaço chega aos ossos. Escolha nas Receitas Saudáveis um almoço rico em ferro e proteína que se faz em 10 minutos e ganhe forças.', title_sv = 'Energibehov 🍲', body_sv = 'Tröttheten sitter i hela kroppen. Välj en lunch från Hälsosamma recept som är klar på 10 minuter och fyller på järn- och proteinförrådet, och samla kraft.', title_vi = 'Nhu cầu năng lượng 🍲', body_vi = 'Mệt mỏi thấm vào tận xương. Hãy chọn một bữa trưa giàu sắt và protein làm trong 10 phút từ Công thức lành mạnh để lấy lại sức.', title_zh = '能量需求 🍲', body_zh = '累到骨子里了。从健康食谱里挑一份10分钟就能做好、富含铁和蛋白质的午餐，补充力量吧。' WHERE id = '334b387f-4019-4208-b951-95f53c679a8b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Controla los ruidos 🤫', body_es = 'El ruido de casa interrumpe su sueño profundo. Estabiliza el sonido de fondo con el Medidor de sonido para que tú también descanses tranquila.', title_fr = 'Maîtrisez les bruits 🤫', body_fr = 'Les bruits de la maison perturbent son sommeil profond. Stabilisez le fond sonore grâce au Sonomètre pour que vous aussi puissiez vous reposer.', title_hi = 'आवाज़ों पर काबू 🤫', body_hi = 'घर का शोर उसकी गहरी नींद तोड़ रहा है। साउंड मीटर से पीछे की आवाज़ को स्थिर रखिए, ताकि आप भी आराम कर सकें।', title_id = 'Atur suara 🤫', body_id = 'Kebisingan di rumah mengganggu tidur nyenyaknya. Stabilkan suara latar dengan Pengukur Suara agar Anda juga bisa beristirahat dengan tenang.', title_ja = '音をコントロール 🤫', body_ja = '家の物音が深い眠りをじゃましています。「サウンドメーター」で背景の音を一定に保てば、あなたもゆっくり休めます。', title_ko = '소리를 관리해요 🤫', body_ko = '집 안 소음이 아기의 깊은 잠을 방해해요. 소음 측정기로 배경 소리를 안정시키면 엄마도 편히 쉴 수 있어요.', title_nl = 'Houd geluiden onder controle 🤫', body_nl = 'Lawaai in huis verstoort zijn diepe slaap. Houd de achtergrond stabiel met de Geluidsmeter, zodat jij ook rustig kunt uitrusten.', title_pl = 'Zapanuj nad dźwiękami 🤫', body_pl = 'Hałas w domu zakłóca jego głęboki sen. Ustabilizuj tło Miernikiem dźwięku, żebyś i ty mogła spokojnie odpocząć.', title_pt = 'Controle os sons 🤫', body_pt = 'O barulho da casa perturba-lhe o sono profundo. Estabilize o som de fundo com o Medidor de Som para que a mãe também descanse tranquila.', title_sv = 'Styr ljuden 🤫', body_sv = 'Oväsendet hemma stör barnets djupa sömn. Håll bakgrundsljudet jämnt med Ljudmätaren, så att du också kan vila i lugn och ro.', title_vi = 'Kiểm soát âm thanh 🤫', body_vi = 'Tiếng ồn trong nhà làm gián đoạn giấc ngủ sâu của bé. Hãy dùng Đo âm thanh để giữ âm thanh nền ổn định, để mẹ cũng được nghỉ ngơi thoải mái.', title_zh = '管理声音 🤫', body_zh = '家里的噪音会打扰宝宝深睡。用噪音测量让背景声音保持稳定，你也能安心休息。' WHERE id = '495a74f3-0952-464a-80e0-08b1cc46205c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder de la palabra «no» 🛑', body_es = '¿Ya aparta la comida que no le gusta y dice que no con la cabeza? ¡Su personalidad se está formando! Respeta su voluntad.', title_fr = 'La force du mot « non » 🛑', body_fr = 'Il repousse déjà les aliments qu''il n''aime pas et dit non en secouant la tête ? Sa personnalité se forme ! Respectez sa volonté.', title_hi = '''ना'' की ताकत 🛑', body_hi = 'अब नापसंद खाना दूर धकेल देता है और सिर हिलाकर ''ना'' कहता है? उसका व्यक्तित्व बन रहा है! उसकी इच्छा का सम्मान कीजिए।', title_id = 'Kekuatan kata "tidak" 🛑', body_id = 'Ia sudah menyingkirkan makanan yang tidak disukainya sambil menggeleng "tidak"? Kepribadiannya sedang terbentuk! Hargai kemauannya.', title_ja = '「いや」の力 🛑', body_ja = 'もう好きじゃない食べ物を押しのけて、首を振って「いや」と言いますか？人格が育っています！その意思を尊重してあげましょう。', title_ko = '''싫어''라는 말의 힘 🛑', body_ko = '싫어하는 음식을 밀어내고 고개를 저으며 싫다고 하나요? 성격이 만들어지고 있어요! 아기의 의사를 존중해 주세요.', title_nl = 'De kracht van het woordje nee 🛑', body_nl = 'Duwt je baby eten dat hij niet lust al weg en schudt hij nee met zijn hoofd? Zijn persoonlijkheid vormt zich! Respecteer zijn wil.', title_pl = 'Siła słowa „nie” 🛑', body_pl = 'Odpycha jedzenie, którego nie lubi, i kręcąc głową mówi „nie”? Kształtuje się jego osobowość! Szanuj jego wolę.', title_pt = 'O poder da palavra "não" 🛑', body_pt = 'Já afasta a comida de que não gosta e abana a cabeça a dizer que não? A personalidade está a formar-se! Respeite a vontade dele.', title_sv = 'Kraften i ordet nej 🛑', body_sv = 'Skjuter barnet redan undan mat det inte tycker om och skakar på huvudet för att säga nej? Personligheten tar form! Respektera barnets vilja.', title_vi = 'Sức mạnh của chữ "Không" 🛑', body_vi = 'Bé đẩy món không thích ra xa và lắc đầu nói "không"? Cá tính của bé đang hình thành! Hãy tôn trọng ý muốn của bé.', title_zh = '“不”的力量 🛑', body_zh = '宝宝会把不爱吃的东西推开，摇头说“不”了？个性正在形成！尊重宝宝的意愿吧。' WHERE id = '73c5a297-0a32-46fb-8b7c-4ca9aeac6cb1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ya tienes bastante con el cansancio del día. 👨‍🍼', body_es = 'Por la tarde, revolcarse por la habitación y jugar con el bebé es tarea exclusiva de papá.', title_fr = 'La fatigue de la journée vous suffit. 👨‍🍼', body_fr = 'En fin de journée, se rouler par terre et jouer avec bébé dans la chambre, c''est uniquement le rôle de papa.', title_hi = 'दिन की थकान आपके लिए काफ़ी है 👨‍🍼', body_hi = 'शाम को बच्चे के साथ कमरे में लोटपोट होना और खेलना सिर्फ़ पापा की ज़िम्मेदारी है।', title_id = 'Lelah seharian sudah cukup bagi Anda. 👨‍🍼', body_id = 'Menjelang malam, berguling-guling dan bermain bersama si kecil di kamar adalah tugas ayah seorang.', title_ja = '昼間の疲れだけでもう十分。👨‍🍼', body_ja = '夕方、部屋で赤ちゃんとごろごろ転がったり遊んだりするのは、パパだけの役目です。', title_ko = '낮의 피로로 충분해요. 👨‍🍼', body_ko = '저녁에 방에서 아기와 뒹굴며 노는 건 오롯이 아빠의 몫이에요.', title_nl = 'De vermoeidheid van overdag is genoeg voor jou. 👨‍🍼', body_nl = '''s Avonds met de baby over de vloer rollen en spelletjes doen is alleen papa''s taak.', title_pl = 'Wystarczy ci dziennego zmęczenia. 👨‍🍼', body_pl = 'Wieczorne turlanie się po pokoju i zabawy z maluszkiem to wyłącznie zadanie taty.', title_pt = 'O cansaço do dia já chega. 👨‍🍼', body_pt = 'Ao fim do dia, rebolar e brincar com o bebé no quarto é tarefa exclusiva do pai.', title_sv = 'Dagens trötthet räcker för dig. 👨‍🍼', body_sv = 'Att rulla runt och leka med barnet i rummet på kvällen är bara pappas uppgift.', title_vi = 'Mệt mỏi ban ngày đã đủ với mẹ rồi. 👨‍🍼', body_vi = 'Chiều tối nay, việc lăn lộn chơi đùa với bé trong phòng hoàn toàn là nhiệm vụ của bố.', title_zh = '白天的疲惫已经够你受了 👨‍🍼', body_zh = '傍晚陪宝宝在房间里打滚、玩游戏，就是爸爸一个人的任务。' WHERE id = '5238f2b7-2892-49ff-9220-f07d0cf3221d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La búsqueda del tesoro 🧺', body_es = 'Vaciar el cesto de la ropa o rebuscar en los armarios es su mayor diversión. Deja que juegue con libertad, así refuerza su motricidad.', title_fr = 'La chasse au trésor 🧺', body_fr = 'Vider le panier à linge ou fouiller dans les placards, c''est son plus grand divertissement. Laissez-le jouer librement, cela renforce sa motricité.', title_hi = 'खज़ाने की खोज 🧺', body_hi = 'कपड़ों की टोकरी खाली करना या अलमारियाँ खँगालना उसका सबसे बड़ा मनोरंजन है। उसे आज़ादी से खेलने दीजिए, इससे उसकी मोटर स्किल्स मज़बूत होती हैं।', title_id = 'Berburu harta karun 🧺', body_id = 'Mengosongkan keranjang baju atau mengobrak-abrik lemari adalah hiburan terbesarnya. Biarkan ia bermain bebas, ini menguatkan motoriknya.', title_ja = '宝探し 🧺', body_ja = '洗濯かごを空にしたり、戸棚をあさったりするのが最高の楽しみ。自由に遊ばせてあげましょう。運動能力が育ちます。', title_ko = '보물찾기 🧺', body_ko = '빨래 바구니를 비우거나 수납장을 뒤지는 게 가장 큰 즐거움이에요. 자유롭게 놀게 해 주세요, 운동 능력이 튼튼해져요.', title_nl = 'Op schattenjacht 🧺', body_nl = 'De wasmand leeghalen of in de kastjes graven is zijn grootste plezier. Laat hem vrij spelen, dat versterkt zijn motoriek.', title_pl = 'Poszukiwanie skarbów 🧺', body_pl = 'Opróżnianie kosza na pranie i przekopywanie szafek to jego największa rozrywka. Pozwól mu swobodnie się bawić, to wzmacnia jego motorykę.', title_pt = 'Caça ao tesouro 🧺', body_pt = 'Esvaziar o cesto da roupa ou remexer nos armários é a maior diversão dele. Deixe-o brincar à vontade, isto reforça a motricidade.', title_sv = 'Skattjakt 🧺', body_sv = 'Att tömma tvättkorgen eller rota i skåpen är barnets största nöje. Låt det leka fritt, det stärker motoriken.', title_vi = 'Truy tìm kho báu 🧺', body_vi = 'Lôi hết quần áo ra khỏi giỏ hay lục tung tủ là trò vui nhất của bé. Cứ để bé thoải mái chơi, điều này giúp tăng cường kỹ năng vận động.', title_zh = '寻宝游戏 🧺', body_zh = '把洗衣篮掏空、翻箱倒柜是宝宝最大的乐趣。让宝宝自由地玩吧，这能锻炼动作能力。' WHERE id = 'c89b6b27-fdbd-4cb8-a5cb-f7ddd8bc2ede' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No dudes en preguntar 🤖', body_es = '¿Qué especias se pueden usar en la comida del bebé? Pregunta al instante a Anacan AI todo lo que te genere dudas y quédate tranquila.', title_fr = 'N''hésitez pas à demander 🤖', body_fr = 'Quelles épices sont autorisées dans les repas de bébé ? Posez aussitôt à Anacan AI toutes les questions qui vous font hésiter et soyez rassurée.', title_hi = 'पूछने में झिझकिए मत 🤖', body_hi = 'बच्चे के खाने में कौन से मसाले डाल सकते हैं? जिस भी बात पर शक हो, तुरंत Anacan AI से पूछिए और निश्चिंत रहिए।', title_id = 'Jangan ragu bertanya 🤖', body_id = 'Bumbu apa saja yang boleh untuk makanan bayi? Tanyakan apa pun yang membuat Anda ragu ke Anacan AI saat itu juga, dan tenanglah.', title_ja = '遠慮せず聞いてみて 🤖', body_ja = '離乳食にはどんなスパイスを使っていい？迷ったことはなんでも、すぐにAnacan AIに聞いて安心しましょう。', title_ko = '망설이지 말고 물어보세요 🤖', body_ko = '아기 음식에 어떤 양념을 써도 될까요? 망설여지는 건 무엇이든 Anacan AI에게 바로 물어보고 마음을 놓으세요.', title_nl = 'Durf het te vragen 🤖', body_nl = 'Welke kruiden mogen in babyvoeding? Vraag alles waarover je twijfelt meteen aan Anacan AI en ontspan.', title_pl = 'Nie wahaj się pytać 🤖', body_pl = 'Jakie przyprawy są dozwolone w jedzeniu dla dziecka? Pytaj od razu Anacan AI o wszystko, co budzi twoje wątpliwości, i się uspokój.', title_pt = 'Não hesite em perguntar 🤖', body_pt = 'Que especiarias são permitidas na comida do bebé? Pergunte logo ao Anacan AI tudo o que lhe suscita dúvidas e fique descansada.', title_sv = 'Tveka inte att fråga 🤖', body_sv = 'Vilka kryddor är tillåtna i barnmat? Fråga Anacan AI direkt om allt du är osäker på och slappna av.', title_vi = 'Đừng ngại hỏi 🤖', body_vi = 'Được cho gia vị nào vào đồ ăn của bé? Mọi điều mẹ băn khoăn, hãy hỏi ngay Anacan AI để yên tâm hơn.', title_zh = '别不好意思问 🤖', body_zh = '宝宝的辅食里可以放哪些调料？有任何拿不准的事，马上问问Anacan AI，安心一点。' WHERE id = 'f0057ec1-cc62-4ea5-9364-5327660ddc30' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora de Cuentos inteligentes 🪄', body_es = 'Que esta noche haya otra historia: La nube mágica a la que le encanta dormir. Baja el tono de voz y crea el ambiente.', title_fr = 'L''heure des Contes intelligents 🪄', body_fr = 'Ce soir, une histoire différente : « Le nuage magique qui adore s''endormir ». Baissez le ton de votre voix et créez l''ambiance.', title_hi = 'स्मार्ट कहानी का समय 🪄', body_hi = 'आज शाम एक अलग कहानी हो: ''सोना पसंद करने वाला जादुई बादल''। अपनी आवाज़ धीमी कीजिए और माहौल बनाइए।', title_id = 'Waktunya Dongeng Pintar 🪄', body_id = 'Malam ini, kisah yang berbeda: Awan ajaib yang suka tidur. Pelankan suara Anda dan bangun suasananya.', title_ja = '「スマートおはなし」の時間 🪄', body_ja = '今夜はいつもと違うお話を：「ねんねが大好きな魔法の雲」。声のトーンを落として、雰囲気をつくりましょう。', title_ko = '스마트 동화 시간 🪄', body_ko = '오늘 저녁은 색다른 이야기로 해 봐요: 잠자는 걸 좋아하는 마법 구름. 목소리를 낮추고 분위기를 만들어 주세요.', title_nl = 'Tijd voor Slimme sprookjes 🪄', body_nl = 'Een ander verhaal vanavond: een magisch wolkje dat graag gaat slapen. Praat zachter en zorg voor de juiste sfeer.', title_pl = 'Czas na Mądre bajki 🪄', body_pl = 'Niech dziś wieczorem będzie inna historia: Magiczna chmurka, która lubi zasypiać. Ścisz głos i zbuduj atmosferę.', title_pt = 'Hora das Histórias Inteligentes 🪄', body_pt = 'Esta noite, uma história diferente: a nuvem mágica que adora adormecer. Baixe o tom de voz e crie o ambiente.', title_sv = 'Smart sagostund 🪄', body_sv = 'Låt det bli en annorlunda saga i kväll: Det magiska molnet som älskar att somna. Sänk rösten och skapa stämningen.', title_vi = 'Giờ cổ tích thông minh 🪄', body_vi = 'Tối nay hãy kể một câu chuyện khác: "Đám mây kỳ diệu thích đi ngủ". Hạ giọng xuống và tạo bầu không khí êm dịu.', title_zh = '智能故事时间 🪄', body_zh = '今晚换个故事吧：《爱睡觉的神奇云朵》。压低你的声音，营造好氛围。' WHERE id = '00632cb5-4d20-4f2d-9bf8-82242042667b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Comparte la carga emocional 💬', body_es = 'Entra en la Comunidad Anacan. A veces leer el comentario de una mamá que no conoces da más energía que un café.', title_fr = 'Partagez la charge émotionnelle 💬', body_fr = 'Rejoignez la Communauté Anacan. Parfois, lire le commentaire d''une maman que vous ne connaissez pas donne plus d''énergie qu''un café.', title_hi = 'मन का बोझ बाँटिए 💬', body_hi = 'Anacan कम्युनिटी में आइए। कभी-कभी किसी अनजान माँ की लिखी टिप्पणी पढ़ना कॉफ़ी से ज़्यादा ऊर्जा देता है।', title_id = 'Bagi beban perasaan 💬', body_id = 'Masuklah ke Komunitas Anacan. Kadang membaca komentar dari ibu yang tidak Anda kenal memberi energi lebih dari secangkir kopi.', title_ja = '心の荷物を分け合おう 💬', body_ja = 'Anacanコミュニティに参加しましょう。知らないママのひと言のコメントが、コーヒーよりも元気をくれることがあります。', title_ko = '마음의 짐을 나눠요 💬', body_ko = 'Anacan 커뮤니티에 들어가 보세요. 때로는 모르는 엄마가 남긴 댓글 하나가 커피보다 더 큰 힘을 줘요.', title_nl = 'Deel de emotionele last 💬', body_nl = 'Ga naar de Anacan Community. Soms geeft een reactie van een moeder die je niet kent meer energie dan koffie.', title_pl = 'Podziel się emocjonalnym ciężarem 💬', body_pl = 'Dołącz do Społeczności Anacan. Czasem przeczytanie komentarza nieznajomej mamy daje więcej energii niż kawa.', title_pt = 'Partilhe o peso emocional 💬', body_pt = 'Entre na Comunidade Anacan. Às vezes, ler o comentário de uma mãe que nem conhece dá mais energia do que um café.', title_sv = 'Dela den känslomässiga bördan 💬', body_sv = 'Gå in i Anacans Community. Ibland ger det mer energi än kaffe att läsa en kommentar från en mamma du inte känner.', title_vi = 'Chia sẻ gánh nặng tinh thần 💬', body_vi = 'Hãy vào Cộng đồng Anacan. Đôi khi đọc lời bình luận của một bà mẹ xa lạ còn tiếp thêm năng lượng hơn cả cà phê.', title_zh = '分担心理负担 💬', body_zh = '进入Anacan社区吧。有时读到一位素不相识的妈妈写的评论，比咖啡更能给你力量。' WHERE id = '61c9e192-532e-41bc-9ebb-f2c296bb0670' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Entrando en zonas peligrosas ⚡', body_es = 'Los enchufes y los cables le llaman la atención. Define bien las zonas prohibidas de casa y revisa otra vez la seguridad.', title_fr = 'Accès aux zones dangereuses ⚡', body_fr = 'Les prises et les câbles attirent son attention. Définissez les zones « interdites » de la maison et vérifiez à nouveau la sécurité.', title_hi = 'खतरनाक जगहों तक पहुँच ⚡', body_hi = 'बिजली के सॉकेट और तार उसका ध्यान खींच रहे हैं। घर में ''ना'' वाली जगहें तय कीजिए और सुरक्षा पर एक बार फिर नज़र डालिए।', title_id = 'Memasuki zona berbahaya ⚡', body_id = 'Stopkontak dan kabel menarik perhatiannya. Tentukan zona "Tidak boleh" di rumah dan periksa kembali keamanannya.', title_ja = '危ないエリアへ ⚡', body_ja = 'コンセントやケーブルに興味しんしん。家の中の「ダメ」ゾーンをはっきりさせて、安全対策をもう一度見直しましょう。', title_ko = '위험 구역 진입 ⚡', body_ko = '콘센트와 전선이 아기의 관심을 끌어요. 집 안의 ''안 돼'' 구역을 정하고 안전을 다시 한번 점검하세요.', title_nl = 'Toegang tot gevaarlijke zones ⚡', body_nl = 'Stopcontacten en snoeren trekken zijn aandacht. Bepaal de nee-zones in huis en loop de veiligheid nog eens na.', title_pl = 'Wejście do stref zagrożenia ⚡', body_pl = 'Gniazdka i kable przyciągają jego uwagę. Wyznacz w domu strefy „nie wolno” i jeszcze raz sprawdź zabezpieczenia.', title_pt = 'Entrada em zonas perigosas ⚡', body_pt = 'As tomadas e os cabos chamam-lhe a atenção. Defina bem as zonas proibidas da casa e reveja mais uma vez a segurança.', title_sv = 'In i farliga zoner ⚡', body_sv = 'Eluttag och kablar drar till sig barnets uppmärksamhet. Bestäm hemmets nej-zoner och gå igenom säkerheten en gång till.', title_vi = 'Lấn vào vùng nguy hiểm ⚡', body_vi = 'Ổ điện, dây cáp thu hút sự chú ý của bé. Hãy xác định rõ những "vùng cấm" trong nhà và rà soát lại an toàn một lần nữa.', title_zh = '进入危险区域 ⚡', body_zh = '插座和电线吸引了宝宝的注意。明确家里的“禁区”，再检查一遍安全措施吧。' WHERE id = '92c6be75-a837-4908-b755-b4ae97896380' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubrimientos con la pinza 🤏', body_es = '¡Encuentra y coge con la punta de los dedos hasta la pelusa más pequeña del suelo! Su motricidad fina está en plena forma.', title_fr = 'Explorer avec la pince 🤏', body_fr = 'Il trouve et ramasse du bout des doigts la moindre petite brindille par terre ! Sa motricité fine est au top.', title_hi = 'चिमटी जैसी पकड़ से खोज 🤏', body_hi = 'फ़र्श पर पड़ा सबसे छोटा तिनका भी उँगलियों के सिरों से ढूँढकर उठा लेता है! उसकी बारीक मोटर स्किल्स कमाल पर हैं।', title_id = 'Menjelajah dengan genggaman jepit 🤏', body_id = 'Ia menemukan dan memungut serpihan terkecil di lantai dengan ujung jarinya! Motorik halusnya sedang di puncak.', title_ja = 'つまむ力で探検 🤏', body_ja = '床の小さなごみまで、指先で見つけてつまんでいます！指先の細かい動きがぐんぐん発達しています。', title_ko = '집게 잡기로 탐험 🤏', body_ko = '바닥의 아주 작은 부스러기도 손가락 끝으로 찾아 집어 올려요! 소근육 발달이 최고조예요.', title_nl = 'Ontdekken met de pincetgreep 🤏', body_nl = 'Je baby vindt zelfs het kleinste pluisje op de vloer en pakt het op met zijn vingertopjes! Zijn fijne motoriek is op zijn hoogtepunt.', title_pl = 'Odkrycia chwytem pęsetowym 🤏', body_pl = 'Nawet najmniejszy paproch na podłodze znajduje i podnosi czubkami palców! Jego motoryka mała jest u szczytu.', title_pt = 'Descobertas com a pinça dos dedos 🤏', body_pt = 'Encontra e apanha com a ponta dos dedos até o mais pequeno resto no chão! A motricidade fina está no auge.', title_sv = 'Upptäckter med pincettgreppet 🤏', body_sv = 'Barnet hittar och plockar upp även det minsta strå på golvet med fingertopparna! Finmotoriken är på topp.', title_vi = 'Khám phá bằng kiểu cầm nhíp 🤏', body_vi = 'Bé tìm và nhặt được cả mẩu rác nhỏ nhất trên sàn bằng đầu ngón tay! Kỹ năng vận động tinh đang ở đỉnh cao.', title_zh = '用指尖捏取探索 🤏', body_zh = '地上最小的碎屑，宝宝都能用指尖找到并捡起来！精细动作正处在巅峰期。' WHERE id = '159ac401-c76f-42ec-b9e1-bb1a6d73130e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La calma de la noche 🛀', body_es = 'No cambies la rutina. El mismo baño de siempre, el mismo aceite de masaje y la misma habitación a oscuras son la llave de oro del sueño.', title_fr = 'La sérénité du soir 🛀', body_fr = 'Ne changez pas la routine. Le même bain, la même huile de massage et la même chambre sombre : voilà la clé d''or du sommeil.', title_hi = 'रात का सुकून 🛀', body_hi = 'रूटीन मत बदलिए। हमेशा वाला स्नान, वही मालिश का तेल और वही अँधेरा कमरा अच्छी नींद की सुनहरी चाबी है।', title_id = 'Ketenangan malam 🛀', body_id = 'Jangan ubah rutinitasnya. Mandi yang sama, minyak pijat yang sama, dan kamar gelap yang sama adalah kunci emas tidur.', title_ja = '夜のやすらぎ 🛀', body_ja = 'ルーティンは変えないで。いつもと同じお風呂、同じマッサージオイル、同じ暗い部屋が、ねんねの黄金の鍵です。', title_ko = '밤의 평온 🛀', body_ko = '루틴을 바꾸지 마세요. 늘 같은 목욕, 같은 마사지 오일, 같은 어두운 방이 잠의 황금 열쇠예요.', title_nl = 'De rust van de nacht 🛀', body_nl = 'Verander de routine niet. Steeds hetzelfde badje, dezelfde massageolie en dezelfde donkere kamer zijn de gouden sleutel tot slaap.', title_pl = 'Spokój nocy 🛀', body_pl = 'Nie zmieniaj rutyny. Ta sama co zawsze kąpiel, ta sama oliwka do masażu i ten sam ciemny pokój to złoty klucz do snu.', title_pt = 'A calma da noite 🛀', body_pt = 'Não mude a rotina. O mesmo banho de sempre, o mesmo óleo de massagem e o mesmo quarto escuro são a chave de ouro do sono.', title_sv = 'Nattens ro 🛀', body_sv = 'Ändra inte rutinen. Samma bad som alltid, samma massageolja och samma mörka rum är den gyllene nyckeln till sömnen.', title_vi = 'Sự bình yên của màn đêm 🛀', body_vi = 'Đừng thay đổi nếp sinh hoạt. Vẫn bồn tắm ấy, vẫn dầu mát-xa ấy và vẫn căn phòng tối ấy chính là chìa khóa vàng của giấc ngủ.', title_zh = '夜晚的宁静 🛀', body_zh = '别改变作息。同样的洗澡、同样的按摩油、同样黑暗的房间，就是好睡眠的金钥匙。' WHERE id = '306f7e64-ae54-408a-95b9-ac4f9c3c6684' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El síndrome de las cuatro paredes ☕', body_es = '¿La casa te agobia? Busca en Lugares para mamás el sitio más cercano donde tú puedas tomar el aire y tu bebé esté a gusto.', title_fr = 'Le syndrome des quatre murs ☕', body_fr = 'La maison vous oppresse ? Dans les Lieux adaptés aux mamans, trouvez l''endroit le plus proche où vous pourrez prendre l''air et où bébé sera à l''aise.', title_hi = 'चार दीवारों वाली घुटन ☕', body_hi = 'घर में घुटन हो रही है? माँ के अनुकूल जगहों में से सबसे नज़दीकी ऐसी जगह ढूँढिए जहाँ आपको ताज़ी हवा मिले और बच्चा भी आराम से रहे।', title_id = 'Sindrom empat dinding ☕', body_id = 'Rumah terasa sesak? Temukan tempat terdekat di Tempat Ramah Ibu di mana Anda bisa menghirup udara segar dan bayi juga nyaman.', title_ja = '4つの壁症候群 ☕', body_ja = '家にいると息がつまる？「ママにやさしいスポット」から、あなたは気分転換でき、赤ちゃんも快適に過ごせるいちばん近い場所を見つけましょう。', title_ko = '네 벽 증후군 ☕', body_ko = '집이 답답한가요? 엄마 친화 장소에서 엄마는 바람을 쐬고 아기도 편안할 수 있는 가장 가까운 곳을 찾아보세요.', title_nl = 'Het vier-murensyndroom ☕', body_nl = 'Word je gek binnen? Vind in Mamavriendelijke plekken de dichtstbijzijnde plek waar jij een frisse neus haalt en je baby het ook fijn heeft.', title_pl = 'Syndrom czterech ścian ☕', body_pl = 'Dom cię przytłacza? Znajdź w Miejscach przyjaznych mamom najbliższe miejsce, gdzie ty złapiesz oddech, a maluszkowi będzie wygodnie.', title_pt = 'O síndrome das quatro paredes ☕', body_pt = 'A casa está a sufocá-la? Encontre nos Locais Amigos das Mães o sítio mais próximo onde possa apanhar ar e o bebé fique confortável.', title_sv = 'Fyra väggar-syndromet ☕', body_sv = 'Känns det trångt hemma? Hitta närmaste ställe bland Mammavänliga platser där du kan få luft och barnet kan ha det bekvämt.', title_vi = 'Hội chứng bốn bức tường ☕', body_vi = 'Ở nhà khiến mẹ ngột ngạt? Hãy tìm trong Địa điểm thân thiện với mẹ nơi gần nhất để mẹ được hít thở không khí mới, còn bé được thoải mái.', title_zh = '四面墙综合征 ☕', body_zh = '在家闷得慌？在妈妈友好场所里找一个最近的地方，你能透透气，宝宝也待得舒服。' WHERE id = 'f3512bb1-5e87-4250-8249-5c396829b593' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Quién hace las tareas de casa? 🌪️', body_es = '¿El ruido de la aspiradora le asusta y las tareas se quedan sin hacer? Que esperen. Pide a tu compañero de equipo que hoy se encargue de las tareas de casa.', title_fr = 'Qui s''occupe du ménage ? 🌪️', body_fr = 'Le bruit de l''aspirateur lui fait peur et le ménage attend ? Laissez-le attendre. Demandez à votre coéquipier de prendre en charge les tâches ménagères aujourd''hui.', title_hi = 'घर का काम कौन करेगा? 🌪️', body_hi = 'वैक्यूम क्लीनर की आवाज़ उसे डराती है और काम रह जाते हैं? रहने दीजिए। अपने टीम साथी से कहिए कि आज घर के काम वे संभालें।', title_id = 'Siapa yang mengurus rumah? 🌪️', body_id = 'Suara penyedot debu membuatnya takut, pekerjaan menumpuk? Biarkan saja. Minta rekan tim Anda mengambil alih pekerjaan rumah hari ini.', title_ja = '家事は誰がする？🌪️', body_ja = '掃除機の音をこわがって、家事が残っている？そのままでいいんです。今日の家事はパートナーにお願いしましょう。', title_ko = '집안일은 누가 할까요? 🌪️', body_ko = '청소기 소리에 아기가 무서워해 일이 밀렸나요? 그냥 두세요. 오늘 집안일은 팀 동료인 배우자에게 맡기세요.', title_nl = 'Wie doet het huishouden? 🌪️', body_nl = 'Schrikt je baby van de stofzuiger en blijft er werk liggen? Laat het liggen. Vraag je teamgenoot om vandaag het huishouden op zich te nemen.', title_pl = 'Kto zajmie się domem? 🌪️', body_pl = 'Odgłos odkurzacza go straszy i obowiązki zostają? Niech zostaną. Poproś partnera z drużyny, żeby dziś przejął domowe obowiązki.', title_pt = 'Quem vai tratar da casa? 🌪️', body_pt = 'O barulho do aspirador assusta-o e as tarefas ficam por fazer? Deixe ficar. Peça ao seu parceiro de equipa que hoje se encarregue das tarefas da casa.', title_sv = 'Vem tar hushållet? 🌪️', body_sv = 'Skrämmer dammsugarens ljud barnet och sysslorna blir liggande? Låt dem ligga. Be din lagkamrat ta hand om hushållet i dag.', title_vi = 'Ai sẽ làm việc nhà? 🌪️', body_vi = 'Tiếng máy hút bụi làm bé sợ, việc nhà còn dang dở? Cứ để đó. Hãy nhờ người đồng đội của mình đảm nhận việc nhà hôm nay.', title_zh = '家务谁来做？🌪️', body_zh = '吸尘器的声音吓到宝宝，家务没做完？就先放着吧。请你的队友今天把家务都揽下来。' WHERE id = '1835b0bb-3338-4b12-9da9-167cd1643dc6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Diario emocional 📝', body_es = 'Cuando te sientas sola, vuelca tus emociones en el Diario de ánimo. Todas las mujeres pasan por este camino. Eres fuerte.', title_fr = 'Un journal des émotions 📝', body_fr = 'Quand vous vous sentez seule, déversez vos émotions dans le Journal d''humeur. Toutes les femmes passent par ces chemins, vous êtes forte.', title_hi = 'भावनाओं की डायरी 📝', body_hi = 'जब अकेली महसूस करें, तो अपनी भावनाएँ मूड डायरी में उड़ेल दीजिए। हर महिला इन रास्तों से गुज़रती है, आप मज़बूत हैं।', title_id = 'Buku harian perasaan 📝', body_id = 'Saat merasa sendirian, tuangkan perasaan Anda di Buku Harian Suasana Hati. Semua perempuan melewati jalan ini, Anda kuat.', title_ja = '気持ちの日記 📝', body_ja = 'ひとりぼっちだと感じたら、「気分日記」に気持ちを吐き出しましょう。どの女性もこの道を通ります。あなたは強い人です。', title_ko = '마음 일기 📝', body_ko = '외로울 때는 기분 일기에 감정을 쏟아 내세요. 모든 여성이 이 길을 지나요. 당신은 강해요.', title_nl = 'Een gevoelsdagboek 📝', body_nl = 'Voel je je alleen? Laat je gevoelens de vrije loop in je Stemmingsdagboek. Alle vrouwen gaan deze weg, je bent sterk.', title_pl = 'Dziennik emocji 📝', body_pl = 'Gdy czujesz się samotna, przelej swoje uczucia do Dziennika nastroju. Wszystkie kobiety przechodzą tę drogę, jesteś silna.', title_pt = 'Diário emocional 📝', body_pt = 'Quando se sentir sozinha, despeje o que sente no Diário de Humor. Todas as mulheres passam por estes caminhos: é forte.', title_sv = 'Känslodagbok 📝', body_sv = 'När du känner dig ensam, häll ut dina känslor i Humördagboken. Alla kvinnor går igenom de här vägarna, du är stark.', title_vi = 'Nhật ký cảm xúc 📝', body_vi = 'Khi thấy cô đơn, hãy trút cảm xúc vào Nhật ký tâm trạng. Người phụ nữ nào cũng đi qua những chặng đường này, mẹ mạnh mẽ lắm.', title_zh = '情绪日记 📝', body_zh = '觉得孤单时，就把感受倾诉在心情日记里。每个女人都会走过这些路，你很坚强。' WHERE id = 'be2205ed-6711-45b7-b2f3-ab21216eef54' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorando la papelera 🗑️', body_es = 'Todo lo que encuentra en el suelo lo examina con enorme curiosidad. No te enfades quitándoselo todo, es un explorador. Simplemente vigílale.', title_fr = 'Exploration de la poubelle 🗑️', body_fr = 'Tout ce qu''il trouve par terre, il l''examine avec grand intérêt. Ne vous énervez pas à tout lui retirer des mains, c''est un explorateur. Gardez simplement un œil sur lui.', title_hi = 'कूड़ेदान की खोजबीन 🗑️', body_hi = 'ज़मीन पर जो भी मिले, उसे बड़े ध्यान से परखता है। हर चीज़ उसके हाथ से छीनकर गुस्सा मत होइए, वह एक खोजी है। बस उस पर नज़र रखिए।', title_id = 'Penjelajah tempat sampah 🗑️', body_id = 'Apa pun yang ia temukan di lantai, ia teliti dengan penuh rasa ingin tahu. Jangan kesal dan merebut semuanya, ia seorang penjelajah. Cukup awasi saja.', title_ja = 'ゴミ箱探検 🗑️', body_ja = '床で見つけたものを、興味しんしんで調べています。イライラしてぜんぶ取り上げないで、赤ちゃんは探検家なのです。見守るだけにしましょう。', title_ko = '쓰레기통 탐험 🗑️', body_ko = '바닥에서 찾은 건 무엇이든 큰 호기심으로 살펴봐요. 모든 걸 빼앗으며 화내지 마세요, 아기는 탐험가니까요. 곁에서 지켜보기만 하세요.', title_nl = 'Speurtocht door de rommel 🗑️', body_nl = 'Alles wat je baby op de vloer vindt, bekijkt hij vol nieuwsgierigheid. Pak niet alles af en word niet boos, hij is een ontdekkingsreiziger. Houd hem gewoon in de gaten.', title_pl = 'Odkrywca śmieci 🗑️', body_pl = 'Wszystko, co znajdzie na podłodze, ogląda z wielką ciekawością. Nie denerwuj się i nie zabieraj mu wszystkiego, jest odkrywcą. Po prostu miej go na oku.', title_pt = 'Exploração do caixote do lixo 🗑️', body_pt = 'Tudo o que encontra no chão, examina com enorme curiosidade. Não se irrite a tirar-lhe tudo das mãos, ele é um explorador. Basta vigiá-lo.', title_sv = 'Upptäcktsfärd i papperskorgen 🗑️', body_sv = 'Vad barnet än hittar på golvet undersöker det med stort intresse. Ta inte allt ifrån det och bli inte irriterad, det är en upptäcktsresande. Håll bara uppsikt.', title_vi = 'Khám phá thùng rác 🗑️', body_vi = 'Tìm thấy gì trên sàn, bé cũng xem xét đầy hứng thú. Đừng bực mình giật mọi thứ khỏi tay bé, bé là một nhà thám hiểm. Chỉ cần để mắt đến bé thôi.', title_zh = '探索垃圾桶 🗑️', body_zh = '在地上找到什么，宝宝都会饶有兴趣地研究。别生气地把东西全抢走，宝宝是个小探险家。只要在旁边看好就行。' WHERE id = 'cd0245fe-8c0d-4f3e-ad23-05cff2186013' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El consuelo de papá 🫂', body_es = 'En los despertares nocturnos, que una vez te levantes tú y otra tu pareja. A veces lo único que calma al bebé son las caricias rítmicas de papá.', title_fr = 'Le réconfort de papa 🫂', body_fr = 'Pour les réveils nocturnes, levez-vous une fois chacun, vous et votre conjoint. Parfois, seules les caresses rythmées de papa font du bien à bébé.', title_hi = 'पापा से मिलने वाला सुकून 🫂', body_hi = 'रात में जागने पर एक बार आप उठिए, एक बार आपके साथी। कभी-कभी बच्चे को सिर्फ़ पापा का लयबद्ध सहलाना ही सुकून देता है।', title_id = 'Hiburan dari ayah 🫂', body_id = 'Saat ia terbangun di malam hari, gantian bangun dengan pasangan. Kadang hanya usapan berirama dari ayah yang bisa menenangkan bayi.', title_ja = 'パパのなぐさめ 🫂', body_ja = '夜中に起きたら、1回はあなた、1回はパートナーと交代で。パパのリズミカルななでなでがいちばん効くこともあります。', title_ko = '아빠의 위로 🫂', body_ko = '밤에 깰 때는 한 번은 엄마가, 한 번은 배우자가 일어나세요. 때로는 아빠의 리드미컬한 토닥임이 아기에게 딱 맞아요.', title_nl = 'Troost van papa 🫂', body_nl = 'Ga ''s nachts om de beurt eruit: de ene keer jij, de andere keer je partner. Soms helpt alleen het ritmische aaien van papa je baby.', title_pl = 'Pocieszenie od taty 🫂', body_pl = 'Przy nocnych pobudkach wstawajcie na zmianę: raz ty, raz partner. Czasem maluszkowi pomaga tylko rytmiczne głaskanie taty.', title_pt = 'O conforto do pai 🫂', body_pt = 'Nos despertares noturnos, levanta-se uma vez a mãe e outra vez o pai. Às vezes, só as carícias ritmadas do pai acalmam o bebé.', title_sv = 'Tröst från pappa 🫂', body_sv = 'Turas om att gå upp vid nattuppvaknandena, en gång du och en gång din partner. Ibland är det bara pappas rytmiska smekningar som hjälper barnet.', title_vi = 'Sự an ủi từ bố 🫂', body_vi = 'Khi bé thức đêm, lần này mẹ dậy, lần sau đến lượt bố. Đôi khi chỉ những cái vỗ về nhịp nhàng của bố mới giúp bé dễ chịu.', title_zh = '来自爸爸的安慰 🫂', body_zh = '夜醒时，你和伴侣轮流起来。有时只有爸爸有节奏的轻拍才能让宝宝安下心来。' WHERE id = '6ff5d725-a5bb-441a-a5ed-1b1b10bf2638' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que el tiempo no te engañe ⛅', body_es = 'Al salir de paseo, no decidas mirando por la ventana. Con la herramienta Tiempo y ropa encuentra el término medio perfecto para las capas de ropa.', title_fr = 'Ne vous fiez pas au temps ⛅', body_fr = 'Avant de sortir, ne décidez pas en regardant par la fenêtre. Avec l''outil Météo et tenue, trouvez le juste milieu pour l''habiller en plusieurs couches.', title_hi = 'मौसम के धोखे में मत आइए ⛅', body_hi = 'सैर पर निकलने से पहले खिड़की से देखकर फ़ैसला मत कीजिए। मौसम और कपड़े टूल से परतों में कपड़े पहनाने का सही संतुलन जानिए।', title_id = 'Jangan tertipu cuaca ⛅', body_id = 'Saat akan jalan-jalan, jangan putuskan hanya dengan melihat dari jendela. Temukan jumlah lapisan pakaian yang pas dengan fitur Cuaca dan Pakaian.', title_ja = '天気にだまされないで ⛅', body_ja = 'お散歩に行くとき、窓の外を見て決めないで。「天気と服装」ツールで、ちょうどいい重ね着を見つけましょう。', title_ko = '날씨에 속지 마세요 ⛅', body_ko = '산책 나갈 때 창밖만 보고 정하지 마세요. 날씨와 옷차림 도구로 겹쳐 입히기의 딱 알맞은 정도를 찾아보세요.', title_nl = 'Laat je niet misleiden door het weer ⛅', body_nl = 'Beslis voor een wandeling niet door uit het raam te kijken. Vind met de tool Weer en kleding het gouden midden voor het aantal laagjes.', title_pl = 'Nie daj się zwieść pogodzie ⛅', body_pl = 'Wychodząc na spacer, nie decyduj, patrząc przez okno. Z narzędziem Pogoda i ubiór znajdziesz złoty środek w ubieraniu na cebulkę.', title_pt = 'Não se deixe enganar pelo tempo ⛅', body_pt = 'Ao sair para passear, não decida só por olhar pela janela. Com a ferramenta Tempo e Roupa, encontre o meio-termo ideal nas camadas de roupa.', title_sv = 'Låt dig inte luras av vädret ⛅', body_sv = 'Bestäm inte genom att titta ut genom fönstret innan promenaden. Hitta den gyllene medelvägen för antalet lager med Väder och kläder.', title_vi = 'Đừng để thời tiết đánh lừa ⛅', body_vi = 'Khi đi dạo, đừng chỉ nhìn qua cửa sổ mà quyết định. Hãy dùng công cụ Thời tiết và trang phục để tìm cách mặc nhiều lớp vừa phải nhất.', title_zh = '别被天气骗了 ⛅', body_zh = '出门散步前别只看窗外就做决定。用天气穿衣工具，找到穿几层衣服的最佳平衡。' WHERE id = '77c04114-1662-45d9-9778-494a99f15f4f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mi juguete no lo doy! 🧸', body_es = '¿Protesta y llora cuando le quitas algo de las manos? Se desarrolla su sentido de la propiedad y de la individualidad. Es una etapa psicológica muy natural.', title_fr = 'Je ne donne pas mon jouet ! 🧸', body_fr = 'Il proteste et pleure quand vous lui prenez quelque chose des mains ? Son sens de la propriété et de l''individualité se développe. C''est une étape psychologique très naturelle.', title_hi = 'अपना खिलौना नहीं दूँगा! 🧸', body_hi = 'उसके हाथ से कुछ लेने पर विरोध करता है और रोता है? उसमें ''मेरा'' और अपनी पहचान का एहसास विकसित हो रहा है। यह बहुत स्वाभाविक मानसिक दौर है।', title_id = 'Mainanku tidak akan kuberikan! 🧸', body_id = 'Ia protes dan menangis saat Anda mengambil sesuatu dari tangannya? Rasa memiliki dan kepribadiannya sedang berkembang. Ini tahap psikologis yang sangat wajar.', title_ja = 'おもちゃは渡さない！🧸', body_ja = '手から何かを取り上げると、怒って泣きますか？「自分のもの」という感覚と個性が育っています。とても自然な心の成長の段階です。', title_ko = '내 장난감은 안 줄래요! 🧸', body_ko = '손에서 무언가를 빼면 항의하며 우나요? 소유와 자아 개념이 자라고 있어요. 아주 자연스러운 심리 발달 단계예요.', title_nl = 'Mijn speeltje geef ik niet af! 🧸', body_nl = 'Protesteert je baby en huilt hij als je iets uit zijn handjes pakt? Het gevoel van bezit en eigenheid ontwikkelt zich. Dit is een heel normale psychologische fase.', title_pl = 'Nie oddam zabawki! 🧸', body_pl = 'Protestuje i płacze, gdy coś mu zabierasz? Rozwija się poczucie własności i odrębności. To bardzo naturalny etap psychologiczny.', title_pt = 'Não dou o meu brinquedo! 🧸', body_pt = 'Protesta e chora quando lhe tira alguma coisa das mãos? O sentido de posse e de individualidade está a desenvolver-se. É uma fase psicológica muito natural.', title_sv = 'Jag ger inte bort min leksak! 🧸', body_sv = 'Protesterar barnet och gråter när du tar något ifrån det? Känslan för ägande och den egna personen utvecklas. Det är en helt naturlig psykologisk fas.', title_vi = 'Con không đưa đồ chơi đâu! 🧸', body_vi = 'Bé phản đối và khóc khi mẹ lấy thứ gì đó khỏi tay? Ý thức về sở hữu và cái tôi của bé đang phát triển. Đây là giai đoạn tâm lý rất tự nhiên.', title_zh = '我的玩具不给你！🧸', body_zh = '从宝宝手里拿走东西时，宝宝会反抗、大哭？宝宝的物权意识和自我意识正在发展。这是非常自然的心理阶段。' WHERE id = 'b630415b-1d8a-4088-bd37-659e6494cb2c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿No entiendes por qué su llanto suena raro? 😭', body_es = 'Usa enseguida el Análisis del llanto, descubre si son los dientes o los gases y quédate tranquila.', title_fr = 'Vous ne comprenez pas ce qui cloche dans ses pleurs ? 😭', body_fr = 'Faites tout de suite écouter ses pleurs à l''Analyse des pleurs, découvrez s''il s''agit des dents ou des gaz, et soyez rassurée.', title_hi = 'उसकी आवाज़ में कुछ अजीब है, समझ नहीं आ रहा? 😭', body_hi = 'तुरंत क्राइंग एनालिसिस से उसकी आवाज़ सुनवाइए, जानिए कि समस्या दाँत की है या गैस की, और निश्चिंत हो जाइए।', title_id = 'Tidak bisa memahami suaranya yang aneh? 😭', body_id = 'Segera perdengarkan tangisannya ke Analisis Tangisan, cari tahu apakah karena gigi atau perut kembung, lalu tenanglah.', title_ja = '泣き声の違いがわからない？😭', body_ja = 'すぐに「泣き声分析」に泣き声を聞かせて、原因が歯なのかガスなのかを知り、安心しましょう。', title_ko = '울음소리가 평소와 달라 이해가 안 되나요? 😭', body_ko = '바로 울음 분석으로 소리를 들려주고 이가 나서인지 가스 때문인지 알아보고 마음을 놓으세요.', title_nl = 'Begrijp je niet wat er vreemd klinkt aan zijn huilen?  😭', body_nl = 'Laat Huilanalyse meteen luisteren, ontdek of het de tandjes of krampjes zijn en stel jezelf gerust.', title_pl = 'Nie rozumiesz, co dziwnego jest w jego płaczu? 😭', body_pl = 'Od razu pozwól Analizie płaczu posłuchać dźwięku, sprawdź, czy to ząbki, czy gazy, i się uspokój.', title_pt = 'Não percebe o que há de estranho no choro dele?  😭', body_pt = 'Ponha já a Análise do Choro a ouvir, descubra se o problema são os dentes ou os gases e fique descansada.', title_sv = 'Förstår du inte vad som är konstigt med ljudet?  😭', body_sv = 'Låt Gråtanalys lyssna på ljudet direkt, ta reda på om problemet är tänderna eller gaser, och slappna av.', title_vi = 'Mẹ không hiểu tiếng khóc lạ của bé?  😭', body_vi = 'Hãy cho Phân tích tiếng khóc nghe ngay để biết vấn đề là do mọc răng hay đầy hơi và yên tâm hơn.', title_zh = '听不懂哭声里的异样？😭', body_zh = '马上用哭声分析听一听，弄清楚是长牙还是胀气，安心一点吧。' WHERE id = '5c4470d4-31c9-42e6-98b2-6ebad58cdce5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidad de silencio 🤫', body_es = 'Protege la calma de la habitación con el Medidor de sonido. El sueño interrumpido por la noche estropea su humor por la mañana, y también el tuyo.', title_fr = 'Besoin de silence 🤫', body_fr = 'Protégez le calme de la chambre avec le Sonomètre. Un sommeil interrompu la nuit gâche l''humeur du matin, la sienne comme la vôtre.', title_hi = 'खामोशी की ज़रूरत 🤫', body_hi = 'साउंड मीटर से कमरे की शांति बनाए रखिए। रात में टूटी नींद उसका और आपका, दोनों का सुबह का मूड बिगाड़ देती है।', title_id = 'Butuh keheningan 🤫', body_id = 'Jaga ketenangan kamar dengan Pengukur Suara. Tidur yang terputus di malam hari merusak suasana hatinya dan juga Anda di pagi hari.', title_ja = '静けさが必要 🤫', body_ja = '「サウンドメーター」で部屋の静けさを守りましょう。夜中に途切れた眠りは、赤ちゃんとあなたの朝のごきげんを左右します。', title_ko = '고요함이 필요해요 🤫', body_ko = '소음 측정기로 방의 고요함을 지켜 주세요. 밤에 끊긴 잠은 아기와 엄마의 아침 기분을 모두 망쳐요.', title_nl = 'Behoefte aan stilte 🤫', body_nl = 'Bescherm de rust in de kamer met de Geluidsmeter. Een onderbroken nachtrust verpest de ochtendstemming van hem én van jou.', title_pl = 'Potrzeba ciszy 🤫', body_pl = 'Chroń spokój w pokoju Miernikiem dźwięku. Przerwany nocny sen psuje poranny nastrój i jemu, i tobie.', title_pt = 'Necessidade de silêncio 🤫', body_pt = 'Proteja a calma do quarto com o Medidor de Som. O sono interrompido à noite estraga o humor da manhã, o dele e o seu.', title_sv = 'Behovet av tystnad 🤫', body_sv = 'Skydda lugnet i rummet med Ljudmätaren. Avbruten nattsömn förstör både barnets och ditt humör på morgonen.', title_vi = 'Cần sự yên tĩnh 🤫', body_vi = 'Hãy giữ yên tĩnh cho căn phòng bằng Đo âm thanh. Giấc ngủ đêm bị gián đoạn làm hỏng tâm trạng buổi sáng của cả bé lẫn mẹ.', title_zh = '需要安静 🤫', body_zh = '用噪音测量守护房间的安静。夜里睡眠被打断，宝宝和你第二天早上的心情都会受影响。' WHERE id = '906becee-91c7-4860-a453-bec23a80f855' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Bailando con la música 🎶', body_es = '¿Se balancea al ritmo cuando suena una música alegre? ¡Se crea la conexión entre oído y motricidad! Pon una canción alegre y baila con tu peque.', title_fr = 'Il danse en musique 🎶', body_fr = 'Il se balance en rythme quand une musique joyeuse passe ? Le lien entre l''audition et la motricité se crée ! Mettez une chanson gaie et dansez avec lui.', title_hi = 'संगीत पर नाच 🎶', body_hi = 'खुशनुमा संगीत बजने पर ताल पर झूमता है? सुनने और मोटर स्किल्स का तालमेल बन रहा है! कोई खुशनुमा गाना लगाइए और उसके साथ नाचिए।', title_id = 'Menari mengikuti musik 🎶', body_id = 'Ia bergoyang mengikuti irama saat musik ceria diputar? Hubungan pendengaran dan motoriknya sedang terbentuk! Putar lagu ceria dan menarilah bersamanya.', title_ja = '音楽に合わせてダンス 🎶', body_ja = '楽しい音楽が流れると、リズムに合わせて体をゆらしますか？聞く力と体の動きがつながってきています！明るい曲をかけて、一緒に踊りましょう。', title_ko = '음악에 맞춰 춤을 🎶', body_ko = '신나는 음악이 나오면 리듬에 맞춰 몸을 흔드나요? 청각과 운동 능력이 연결되고 있어요! 신나는 노래를 틀고 함께 춤춰 보세요.', title_nl = 'Dansen op muziek 🎶', body_nl = 'Wiegt je baby mee op het ritme als er vrolijke muziek klinkt? Gehoor en motoriek gaan samenwerken! Zet een vrolijk liedje op en dans samen.', title_pl = 'Taniec do muzyki 🎶', body_pl = 'Gdy gra wesoła muzyka, kołysze się w rytm? Tworzy się połączenie słuchu i motoryki! Włącz wesołą piosenkę i zatańczcie razem.', title_pt = 'Dançar ao som da música 🎶', body_pt = 'Quando toca uma música alegre, abana-se ao ritmo? A ligação entre audição e motricidade está a formar-se! Ponha uma canção alegre e dance com ele.', title_sv = 'Dans till musiken 🎶', body_sv = 'Gungar barnet i takt när glad musik spelas? Kopplingen mellan hörsel och motorik tar form! Sätt på en glad låt och dansa med barnet.', title_vi = 'Nhảy theo nhạc 🎶', body_vi = 'Khi có nhạc vui, bé đung đưa theo nhịp? Mối liên kết giữa thính giác và vận động đang hình thành! Hãy bật một bài hát vui nhộn và nhảy cùng bé.', title_zh = '随音乐起舞 🎶', body_zh = '欢快的音乐一响，宝宝就跟着节奏摇摆？听觉和动作的配合正在建立！放一首欢快的歌，和宝宝一起跳舞吧。' WHERE id = '93f3b238-cc16-44a9-888c-f9d77043f372' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pasa las páginas de los libros 📖', body_es = '¿Intenta pasar las páginas de los libros de cartón? Cómprale muchos libros de cuentos de colores y con texturas para tocar.', title_fr = 'Il feuillette les livres 📖', body_fr = 'Il essaie de tourner les pages cartonnées des livres ? Offrez-lui plein de livres de contes colorés et à toucher.', title_hi = 'किताबों के पन्ने पलटता है 📖', body_hi = 'मोटे पन्नों वाली किताबों के पन्ने पलटने की कोशिश करता है? उसके लिए खूब सारी रंगीन और छूकर महसूस करने वाली कहानी की किताबें लाइए।', title_id = 'Ia membalik halaman buku 📖', body_id = 'Ia mencoba membalik halaman buku bergambar tebal? Belikan ia banyak buku cerita yang berwarna dan bisa disentuh.', title_ja = '絵本をめくる 📖', body_ja = '厚紙の絵本のページをめくろうとしていますか？カラフルでさわって楽しめる絵本をたくさん用意してあげましょう。', title_ko = '책장을 넘겨요 📖', body_ko = '두꺼운 책장을 넘기려 하나요? 알록달록하고 만질 수 있는 그림책을 많이 마련해 주세요.', title_nl = 'Hij bladert door boekjes 📖', body_nl = 'Probeert je baby de dikke bladzijden van boekjes om te slaan? Koop veel kleurrijke voelboekjes voor hem.', title_pl = 'Przewraca kartki 📖', body_pl = 'Próbuje przewracać grube kartki książeczek? Kupuj mu dużo kolorowych książeczek z bajkami, które można dotykać.', title_pt = 'Folheia livros 📖', body_pt = 'Tenta virar as páginas dos livros de cartão? Compre-lhe muitos livros de histórias coloridos e para tocar.', title_sv = 'Bläddrar i böcker 📖', body_sv = 'Försöker barnet vända sidorna i böcker med tjocka blad? Köp massor av färgglada sagoböcker som går att känna på.', title_vi = 'Bé lật sách 📖', body_vi = 'Bé cố lật trang sách bìa cứng? Hãy mua cho bé thật nhiều sách truyện nhiều màu sắc, có thể sờ chạm.', title_zh = '翻书啦 📖', body_zh = '宝宝在试着翻厚纸板书？给宝宝多买些色彩丰富、可以触摸的故事书吧。' WHERE id = '334464c1-4599-4dd4-83dd-d57c384eb650' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡De los purés a los alimentos con trocitos! 🍲', body_es = '¿Ya puede comer alimentos que hay que masticar? Prueba las recetas de purés y sopas con texturas distintas de la sección para bebés que empiezan con la alimentación complementaria de nuestra app.', title_fr = 'Des purées aux morceaux ! 🍲', body_fr = 'Il peut déjà manger des aliments qui demandent à mâcher ? Essayez les recettes de purées et de soupes aux textures variées dans la rubrique Bébés qui commencent la diversification.', title_hi = 'प्यूरी से दानेदार खाने तक! 🍲', body_hi = 'अब वह चबाने वाला खाना खा सकता है? ऐप के ऊपरी आहार शुरू करने वाले बच्चों वाले सेक्शन में अलग बनावट वाली प्यूरी और सूप की रेसिपी आज़माइए।', title_id = 'Dari puree ke makanan bertekstur! 🍲', body_id = 'Ia sudah bisa makan makanan yang perlu dikunyah? Coba resep puree dan sup dengan tekstur berbeda di bagian Bayi yang Mulai MPASI di aplikasi kami.', title_ja = 'ペーストから粒のある食べ物へ！🍲', body_ja = 'もうかむ必要のある食べ物を食べられますか？アプリの「離乳食を始める赤ちゃん」セクションで、いろいろな食感のペーストやスープのレシピを試してみましょう。', title_ko = '퓌레에서 덩어리 있는 음식으로! 🍲', body_ko = '이제 씹어야 하는 음식도 먹을 수 있나요? 앱의 이유식을 시작하는 아기 섹션에서 다양한 질감의 퓌레와 수프 레시피를 시도해 보세요.', title_nl = 'Van gepureerd naar stukjes! 🍲', body_nl = 'Kan je baby al eten waarop gekauwd moet worden? Probeer in onze app de recepten voor hapjes en soepjes met andere texturen in het onderdeel Baby''s die met bijvoeding beginnen.', title_pl = 'Od przecierów do grudek! 🍲', body_pl = 'Może już jeść pokarmy, które trzeba gryźć? Wypróbuj przepisy na przeciery i zupy o różnej konsystencji w sekcji dla maluszków zaczynających rozszerzanie diety.', title_pt = 'Dos purés aos alimentos com pedaços! 🍲', body_pt = 'Já consegue comer alimentos que exigem mastigação? Experimente na secção para bebés em diversificação alimentar da nossa app receitas de purés e sopas com texturas diferentes.', title_sv = 'Från puréer till grövre mat! 🍲', body_sv = 'Kan barnet redan äta mat som behöver tuggas? Prova recepten på puréer och soppor med olika texturer i avsnittet för barn som börjar med smakportioner i appen.', title_vi = 'Từ món nghiền đến món lợn cợn! 🍲', body_vi = 'Bé đã ăn được những món cần nhai? Hãy thử các công thức món nghiền và súp với kết cấu khác nhau trong mục Cho bé bắt đầu ăn dặm của ứng dụng.', title_zh = '从泥糊到颗粒状食物！🍲', body_zh = '宝宝已经能吃需要咀嚼的食物了？去应用里“辅食宝宝”板块，试试不同质地的泥糊和汤的食谱吧。' WHERE id = 'd7009029-eb30-44cd-bedc-77f2ddcbdbe4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lista de la compra 🛒', body_es = '¿Se ha acabado el brócoli o la avena? Rellena ya la Lista de la compra y envía los pedidos al móvil de tu pareja.', title_fr = 'Liste de courses 🛒', body_fr = 'Plus de brocoli ou de flocons d''avoine pour ses repas ? Remplissez tout de suite la Liste de courses et envoyez-la sur le téléphone de votre conjoint.', title_hi = 'शॉपिंग लिस्ट 🛒', body_hi = 'खाने के लिए ब्रोकली या ओट्स खत्म हो गए? तुरंत शॉपिंग लिस्ट भरिए और ज़रूरतें अपने साथी के फ़ोन पर भेजिए।', title_id = 'Daftar Belanja 🛒', body_id = 'Brokoli atau oat untuk makanannya habis? Segera isi Daftar Belanja dan kirim kebutuhannya ke ponsel pasangan Anda.', title_ja = '買い物リスト 🛒', body_ja = 'ごはん用のブロッコリーやオートミールが切れた？すぐに「買い物リスト」に書いて、パートナーのスマホに送りましょう。', title_ko = '쇼핑 목록 🛒', body_ko = '이유식에 쓸 브로콜리나 오트밀이 떨어졌나요? 바로 쇼핑 목록을 채우고 배우자 휴대폰으로 보내세요.', title_nl = 'Boodschappenlijstje 🛒', body_nl = 'Is de broccoli of havermout op? Vul meteen je Boodschappenlijstje aan en stuur het naar de telefoon van je partner.', title_pl = 'Lista zakupów 🛒', body_pl = 'Skończyły się brokuły albo płatki owsiane? Od razu uzupełnij Listę zakupów i wyślij prośby na telefon partnera.', title_pt = 'Lista de Compras 🛒', body_pt = 'Acabaram os brócolos ou a aveia para a papa? Preencha já a Lista de Compras e envie os pedidos para o telemóvel do seu companheiro.', title_sv = 'Inköpslistan 🛒', body_sv = 'Har broccolin eller havregrynen tagit slut? Fyll genast i Inköpslistan och skicka det som behövs till din partners telefon.', title_vi = 'Danh sách mua sắm 🛒', body_vi = 'Hết bông cải xanh hay yến mạch để nấu cho bé? Điền ngay vào Danh sách mua sắm và gửi yêu cầu đến điện thoại của bố.', title_zh = '购物清单 🛒', body_zh = '做饭用的西兰花或燕麦用完了？马上填好购物清单，把需求发到伴侣的手机上吧。' WHERE id = 'f5716668-d412-4d80-9c29-0a69a23f4f4e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Saca los juguetes de la caja! 🧸', body_es = 'Le encanta sacar las cosas de la caja una a una y tirarlas. Captura este momento de descubrimiento tan divertido y caótico con la Sesión de fotos del bebé y recuérdalo con una sonrisa.', title_fr = 'Il sort ses jouets de la boîte ! 🧸', body_fr = 'Il adore sortir les objets de la boîte un par un et les jeter. Photographiez ce moment de découverte amusant et désordonné avec la Séance photo bébé pour vous en souvenir en riant.', title_hi = 'खिलौने डिब्बे से निकालता है! 🧸', body_hi = 'उसे डिब्बे से चीज़ें एक-एक करके निकालकर फेंकना पसंद है। खोज के इस मज़ेदार और बिखरे पल को बेबी फ़ोटोशूट से कैद कीजिए और मुस्कुराकर याद कीजिए।', title_id = 'Ia mengeluarkan mainan dari kotak! 🧸', body_id = 'Ia suka mengeluarkan barang dari kotak satu per satu lalu melemparnya. Abadikan momen penjelajahan yang seru dan berantakan ini dengan Sesi Foto Bayi, lalu kenang sambil tertawa.', title_ja = 'おもちゃを箱から出す！🧸', body_ja = '箱からものをひとつずつ出して放り投げるのが大好き。この楽しくて散らかった発見の瞬間を「ベビーフォトセッション」で撮って、笑顔で振り返りましょう。', title_ko = '장난감을 상자에서 꺼내요! 🧸', body_ko = '물건을 상자에서 하나씩 꺼내 던지는 걸 좋아해요. 이 즐겁고 어수선한 탐험의 순간을 아기 사진 촬영으로 담아 웃으며 추억하세요.', title_nl = 'Hij haalt zijn speeltjes uit de doos! 🧸', body_nl = 'Je baby haalt graag één voor één alles uit de doos en gooit het weg. Leg dit leuke, rommelige ontdekmoment vast met Babyfotoshoot en denk er later lachend aan terug.', title_pl = 'Wyjmuje zabawki z pudełka! 🧸', body_pl = 'Uwielbia wyjmować rzeczy z pudełka jedną po drugiej i je rozrzucać. Uchwyć tę zabawną, bałaganiarską chwilę odkryć w Sesji zdjęciowej dziecka i wspominaj ją z uśmiechem.', title_pt = 'Tira os brinquedos da caixa! 🧸', body_pt = 'Adora tirar as coisas da caixa uma a uma e atirá-las. Fotografe este momento de descoberta divertido e desarrumado com a Sessão Fotográfica do Bebé e recorde-o a rir.', title_sv = 'Plockar ut leksakerna ur lådan! 🧸', body_sv = 'Barnet älskar att plocka ut saker ur lådan en efter en och kasta dem. Fånga den här roliga och stökiga upptäcktsstunden med Babyfotografering och minns den med ett leende.', title_vi = 'Bé lấy đồ chơi ra khỏi hộp! 🧸', body_vi = 'Bé thích lấy từng món đồ ra khỏi hộp rồi ném đi. Hãy ghi lại khoảnh khắc khám phá vui nhộn, bừa bộn này bằng Chụp ảnh cho bé để mỉm cười nhớ lại.', title_zh = '把玩具从盒子里拿出来！🧸', body_zh = '宝宝喜欢把东西一件件从盒子里拿出来扔掉。用宝宝写真拍下这个有趣又凌乱的探索瞬间，以后笑着回忆吧。' WHERE id = '16369cf1-7620-428e-8c38-c6f5104fb5ab' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Los primeros pasos a la vuelta de la esquina? 🧗‍♂️', body_es = '¿Ya no le basta con ponerse de pie agarrado al sofá y camina a lo largo de la pared? Duplica las medidas de seguridad.', title_fr = 'Les premiers pas approchent ? 🧗‍♂️', body_fr = 'Il ne se contente plus de se hisser au canapé, il longe le mur ? Doublez les mesures de sécurité.', title_hi = 'पहले कदम बस आने वाले हैं? 🧗‍♂️', body_hi = 'सोफ़ा पकड़कर खड़े होने से संतुष्ट नहीं, दीवार के सहारे चलता है? सुरक्षा के उपाय दोगुने कर दीजिए।', title_id = 'Langkah pertama sudah dekat? 🧗‍♂️', body_id = 'Tidak puas hanya berdiri berpegangan pada sofa, kini ia berjalan menyusuri dinding? Tingkatkan langkah pengamanan dua kali lipat.', title_ja = '初めての一歩はもうすぐ？🧗‍♂️', body_ja = 'ソファにつかまって立つだけでは物足りず、壁づたいに歩いていますか？安全対策を2倍にしましょう。', title_ko = '첫걸음이 코앞인가요? 🧗‍♂️', body_ko = '소파를 잡고 일어서는 것으로 모자라 벽을 따라 걷나요? 안전 대책을 두 배로 늘리세요.', title_nl = 'De eerste stapjes in aantocht? 🧗‍♂️', body_nl = 'Trekt je baby zich niet alleen op aan de bank, maar loopt hij ook langs de muur? Verdubbel de veiligheidsmaatregelen.', title_pl = 'Pierwsze kroki tuż-tuż? 🧗‍♂️', body_pl = 'Nie wystarcza mu wstawanie przy kanapie, chodzi już wzdłuż ściany? Podwój środki bezpieczeństwa.', title_pt = 'Os primeiros passos estão à porta? 🧗‍♂️', body_pt = 'Já não se contenta em pôr-se de pé agarrado ao sofá e anda ao longo da parede? Redobre as medidas de segurança.', title_sv = 'De första stegen nära? 🧗‍♂️', body_sv = 'Nöjer sig barnet inte med att dra sig upp i soffan utan går längs väggen? Dubbla säkerhetsåtgärderna.', title_vi = 'Những bước đi đầu tiên đã gần kề? 🧗‍♂️', body_vi = 'Không chỉ bám sofa đứng lên, bé còn men theo tường mà đi? Hãy tăng gấp đôi các biện pháp an toàn.', title_zh = '第一步就要来了？🧗‍♂️', body_zh = '宝宝不满足于扶着沙发站起来，还会扶着墙走了？把安全措施加倍吧。' WHERE id = '912a7ba7-5cb9-41f1-9daa-dc1c800036eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirse con un cuento 🪄', body_es = 'Crea en Cuentos inteligentes la historia de unos animales valientes y adorables y convierte la habitación en un lugar mágico.', title_fr = 'S''endormir avec un conte 🪄', body_fr = 'Dans les Contes intelligents, créez l''histoire d''animaux courageux et adorables et transformez la chambre en un lieu magique.', title_hi = 'कहानी के साथ नींद 🪄', body_hi = 'स्मार्ट कहानियों में बहादुर और प्यारे जानवरों की कहानी बनाइए और कमरे को एक जादुई जगह में बदल दीजिए।', title_id = 'Tertidur bersama dongeng 🪄', body_id = 'Di Dongeng Pintar, buat kisah hewan-hewan yang berani dan menggemaskan, dan ubah kamar menjadi tempat yang ajaib.', title_ja = 'お話でねんね 🪄', body_ja = '「スマートおはなし」で、勇敢でかわいい動物たちのお話をつくって、部屋を魔法の場所に変えましょう。', title_ko = '동화와 함께 꿈나라로 🪄', body_ko = '스마트 동화에서 용감하고 사랑스러운 동물 이야기를 만들어 방을 마법의 공간으로 바꿔 보세요.', title_nl = 'Met een sprookje in slaap 🪄', body_nl = 'Maak in Slimme sprookjes het verhaal van dappere, lieve dieren en verander de kamer in een magische plek.', title_pl = 'Zasypianie z bajką 🪄', body_pl = 'Stwórz w Mądrych bajkach historię o odważnych i uroczych zwierzątkach i zamień pokój w magiczne miejsce.', title_pt = 'Adormecer com uma história 🪄', body_pt = 'Crie nas Histórias Inteligentes histórias de animais corajosos e adoráveis e transforme o quarto num lugar mágico.', title_sv = 'Somnar till en saga 🪄', body_sv = 'Skapa sagan om modiga och gulliga djur i Smarta sagor och förvandla rummet till en magisk plats.', title_vi = 'Vào giấc cùng truyện cổ tích 🪄', body_vi = 'Hãy tạo câu chuyện về những con vật dũng cảm, đáng yêu trong Truyện cổ tích thông minh và biến căn phòng thành một nơi kỳ diệu.', title_zh = '听着故事入睡 🪄', body_zh = '在智能故事里创作勇敢又可爱的动物的故事，把房间变成一个神奇的地方吧。' WHERE id = 'ec70551b-eda4-4e87-86a9-151235d2eb3e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Entiende tu tono de voz 🗣️', body_es = '¿Se detiene y te mira cuando dices «no» con voz seria? ¡Ya empieza a captar las emociones y los límites!', title_fr = 'Il comprend le ton de votre voix 🗣️', body_fr = 'Il s''arrête net et vous regarde quand vous dites « non » d''une voix ferme ? Il commence déjà à saisir les émotions et les interdits !', title_hi = 'वह आपकी आवाज़ का लहजा समझता है 🗣️', body_hi = 'सख्त आवाज़ में ''ना'' कहने पर वह रुककर आपको देखता है? वह अब भावनाओं और मनाही को समझने लगा है!', title_id = 'Ia memahami nada suara Anda 🗣️', body_id = 'Saat Anda berkata "tidak" dengan suara tegas, ia berhenti dan menatap Anda? Ia mulai memahami emosi dan larangan!', title_ja = '声のトーンがわかる 🗣️', body_ja = 'きっぱりした声で「ダメ」と言うと、動きを止めてあなたを見ますか？感情や「してはいけないこと」を理解しはじめています！', title_ko = '엄마의 말투를 알아들어요 🗣️', body_ko = '단호한 목소리로 ''안 돼''라고 하면 멈칫하며 엄마를 바라보나요? 이제 감정과 금지를 이해하기 시작했어요!', title_nl = 'Hij begrijpt de toon van je stem 🗣️', body_nl = 'Stopt je baby even en kijkt hij je aan als je streng nee zegt? Hij begint emoties en verboden al te begrijpen!', title_pl = 'Rozumie ton twojego głosu 🗣️', body_pl = 'Gdy mówisz poważnym głosem „nie”, zatrzymuje się i na ciebie patrzy? Zaczyna już rozumieć emocje i zakazy!', title_pt = 'Percebe o seu tom de voz 🗣️', body_pt = 'Quando diz "não" com voz séria, ele para e olha para si? Já começa a perceber as emoções e as proibições!', title_sv = 'Barnet förstår ditt tonfall 🗣️', body_sv = 'Stannar barnet upp och tittar på dig när du säger nej med allvarlig röst? Det börjar redan förstå känslor och förbud!', title_vi = 'Bé hiểu giọng điệu của mẹ 🗣️', body_vi = 'Khi mẹ nói "không" với giọng nghiêm, bé khựng lại và nhìn mẹ? Bé đã bắt đầu hiểu cảm xúc và những điều bị cấm!', title_zh = '听得懂你的语气 🗣️', body_zh = '你用严肃的语气说“不”时，宝宝会停下来看着你？宝宝已经开始理解情绪和禁止了！' WHERE id = '39498b75-8a2a-463e-a232-aa6ed7188810' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisión del desarrollo 🤖', body_es = '¿Crees que hay algún retraso en sus movimientos? Pide a Anacan AI información clara sobre las habilidades motoras a los 9 meses.', title_fr = 'Bilan de développement 🤖', body_fr = 'Vous pensez qu''il a du retard dans ses mouvements physiques ? Obtenez d''Anacan AI des informations claires sur la motricité à 9 mois.', title_hi = 'विकास की जाँच 🤖', body_hi = 'लगता है बच्चे की शारीरिक हरकतों में देरी है? Anacan AI से 9 महीने की मोटर स्किल्स के बारे में साफ़ जानकारी पाइए।', title_id = 'Cek perkembangan 🤖', body_id = 'Merasa gerakan fisiknya agak terlambat? Dapatkan informasi yang jelas tentang keterampilan motorik usia 9 bulan dari Anacan AI.', title_ja = '発達チェック 🤖', body_ja = '体の動きの発達が遅れているかもと心配ですか？Anacan AIで、生後9か月の運動能力についてわかりやすい情報を受け取りましょう。', title_ko = '발달 체크 🤖', body_ko = '아이의 신체 움직임이 늦다고 생각되나요? Anacan AI에게서 9개월 운동 능력에 대한 명확한 정보를 받아 보세요.', title_nl = 'Ontwikkelingscheck 🤖', body_nl = 'Denk je dat je kindje achterloopt met bewegen? Krijg van Anacan AI duidelijke informatie over de motorische vaardigheden bij 9 maanden.', title_pl = 'Kontrola rozwoju 🤖', body_pl = 'Wydaje ci się, że maluszek ma opóźnienia w rozwoju ruchowym? Uzyskaj od Anacan AI jasne informacje o umiejętnościach motorycznych 9-miesięcznego dziecka.', title_pt = 'Verificação do desenvolvimento 🤖', body_pt = 'Acha que há algum atraso nos movimentos do bebé? Receba do Anacan AI informação clara sobre as capacidades motoras aos 9 meses.', title_sv = 'Utvecklingskoll 🤖', body_sv = 'Tror du att barnet ligger efter i de fysiska rörelserna? Få tydlig information om motoriken vid 9 månader från Anacan AI.', title_vi = 'Kiểm tra sự phát triển 🤖', body_vi = 'Mẹ nghĩ bé chậm phát triển vận động? Hãy hỏi Anacan AI để có thông tin rõ ràng về kỹ năng vận động của bé 9 tháng.', title_zh = '发育检查 🤖', body_zh = '觉得宝宝的大动作发育有些落后？向Anacan AI获取关于9个月动作技能的清晰信息吧。' WHERE id = '6d030e22-f99a-4fa8-829a-d62a50ce76e0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Seguimos la digestión. 🧷', body_es = 'Los alimentos sólidos cambian las cacas. Registra cada cambio de pañal en Anacan y analiza la salud de tu bebé.', title_fr = 'On suit la digestion. 🧷', body_fr = 'Les aliments solides modifient les selles. Notez chaque change dans Anacan pour analyser la santé de votre bébé.', title_hi = 'पाचन पर नज़र 🧷', body_hi = 'ठोस आहार से मल बदलता है। Anacan में हर डायपर बदलना दर्ज करके बच्चे की सेहत का विश्लेषण कीजिए।', title_id = 'Memantau pencernaan. 🧷', body_id = 'Makanan padat mengubah pola BAB-nya. Catat setiap ganti popok di Anacan dan pantau kesehatan bayi Anda.', title_ja = '消化の様子を見守ろう。🧷', body_ja = '固形の食べ物でうんちが変わります。おむつ替えのたびにAnacanに記録して、赤ちゃんの健康をチェックしましょう。', title_ko = '소화 과정 살피기 🧷', body_ko = '고형식은 변을 바꿔요. Anacan에 기저귀 교체를 빠짐없이 기록하며 아기의 건강을 살펴보세요.', title_nl = 'We volgen de spijsvertering. 🧷', body_nl = 'Vast voedsel verandert de ontlasting. Noteer elke luierverschoning in Anacan en houd de gezondheid van je baby in de gaten.', title_pl = 'Śledzimy trawienie. 🧷', body_pl = 'Stałe pokarmy zmieniają kupki. Zapisuj w Anacan każdą zmianę pieluszki i analizuj zdrowie maluszka.', title_pt = 'Acompanhamos a digestão. 🧷', body_pt = 'Os alimentos sólidos mudam as fezes. Registe no Anacan cada muda de fralda e analise a saúde do bebé.', title_sv = 'Vi följer matsmältningen. 🧷', body_sv = 'Fast föda förändrar bajset. Anteckna varje blöjbyte i Anacan och analysera barnets hälsa.', title_vi = 'Theo dõi quá trình tiêu hóa. 🧷', body_vi = 'Thức ăn đặc làm thay đổi phân của bé. Hãy ghi lại mỗi lần thay tã trong Anacan để phân tích sức khỏe của bé.', title_zh = '关注消化情况 🧷', body_zh = '固体食物会改变大便。在Anacan里记录每一次换尿布，了解宝宝的健康状况。' WHERE id = 'e607d1aa-9be0-4388-9790-764a5c1e94da' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las molestias de la dentición 🦷', body_es = '¿Vuelve a tener las encías rojas y no para de babear? Prepara los mordedores fríos.', title_fr = 'Les douleurs dentaires 🦷', body_fr = 'Ses gencives sont de nouveau rouges et il bave sans arrêt ? Préparez les anneaux de dentition rafraîchis.', title_hi = 'दाँत निकलने का दर्द 🦷', body_hi = 'मसूड़े फिर से लाल हैं और लार रुक नहीं रही? ठंडे टीदर तैयार रखिए।', title_id = 'Nyeri tumbuh gigi 🦷', body_id = 'Gusinya memerah lagi dan air liurnya tak berhenti? Siapkan teether yang dingin.', title_ja = '歯が生えるときの痛み 🦷', body_ja = 'また歯ぐきが赤くなって、よだれが止まらない？冷たい歯固めを用意しましょう。', title_ko = '이앓이 통증 🦷', body_ko = '잇몸이 다시 빨개지고 침이 멈추지 않나요? 차가운 치발기를 준비하세요.', title_nl = 'Pijn door doorkomende tandjes 🦷', body_nl = 'Is het tandvlees weer rood en stopt het kwijlen niet? Leg de koude bijtringen klaar.', title_pl = 'Bóle ząbkowania 🦷', body_pl = 'Dziąsła znów są zaczerwienione, a ślinka ciągle leci? Przygotuj schłodzone gryzaki.', title_pt = 'Dores dos dentes 🦷', body_pt = 'As gengivas voltaram a ficar vermelhas e a baba não para? Prepare os mordedores frescos.', title_sv = 'Tandsmärtor 🦷', body_sv = 'Är gommen röd igen och slutar dreglet aldrig? Ta fram de kalla bitringarna.', title_vi = 'Cơn đau mọc răng 🦷', body_vi = 'Nướu bé lại đỏ và nước dãi chảy không ngừng? Hãy chuẩn bị gặm nướu mát nhé.', title_zh = '出牙疼 🦷', body_zh = '牙龈又红了，口水流个不停？准备好冰凉的牙胶吧。' WHERE id = '57fa0aeb-432f-4b34-915b-98422c100236' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El temporizador de Anacan recuerda por ti el pecho derecho o izquierdo. ¡Empieza ya la toma con el temporizador!', body_fr = 'Le minuteur Anacan retient pour vous le sein droit ou gauche. Lancez maintenant la tétée avec le minuteur !', body_hi = 'Anacan टाइमर आपकी जगह दायाँ/बायाँ स्तन याद रखता है। अभी टाइमर के साथ फ़ीडिंग शुरू कीजिए!', body_id = 'Timer Anacan mengingat payudara kanan/kiri untuk Anda. Mulai menyusui sekarang dengan timer!', body_ja = 'Anacanのタイマーが、あなたの代わりに左右どちらのおっぱいかを覚えておいてくれます。今すぐタイマーで授乳を始めましょう！', body_ko = 'Anacan 타이머가 엄마 대신 왼쪽/오른쪽 가슴을 기억해 줘요. 지금 타이머로 수유를 시작하세요!', body_nl = 'De timer van Anacan onthoudt voor jou welke borst, links of rechts, aan de beurt is. Start de voeding nu met de timer!', body_pl = 'Timer Anacan zapamięta za ciebie, z której piersi karmiłaś: lewej czy prawej. Włącz teraz karmienie z timerem!', body_pt = 'O temporizador do Anacan lembra-se por si se foi o peito direito ou o esquerdo. Comece já a mamada com o temporizador!', body_sv = 'Anacan-timern kommer ihåg höger eller vänster bröst åt dig. Starta matningen med timern nu!', body_vi = 'Hẹn giờ của Anacan sẽ nhớ giúp mẹ bên ngực trái hay phải. Hãy bắt đầu cữ bú với hẹn giờ ngay bây giờ!', body_zh = 'Anacan计时器会替你记住左右侧乳房。现在就用计时器开始喂奶吧！' WHERE id = 'bda23a3e-0646-4246-a5dc-febd245b2bb1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Mientras tu bebé duerme, pon el temporizador de sueño y comprueba en la gráfica si cumple el sueño diario recomendado para un bebé de 9 meses.', body_fr = 'Quand bébé dort, lancez le minuteur de sommeil et vérifiez sur le graphique s''il respecte la norme de sommeil quotidienne d''un bébé de 9 mois.', body_hi = 'बच्चे के सोते समय स्लीप टाइमर चालू कीजिए और चार्ट में देखिए कि आपका 9 महीने का बच्चा रोज़ की नींद का मानक पूरा कर रहा है या नहीं।', body_id = 'Saat bayi tidur, nyalakan Timer Tidur dan cek di grafik apakah ia memenuhi kebutuhan tidur harian bayi usia 9 bulan.', body_ja = '赤ちゃんが寝たら睡眠タイマーをオンにして、生後9か月の1日の睡眠の目安を満たしているかグラフで確認しましょう。', body_ko = '아기가 잘 때 수면 타이머를 켜고, 9개월 아기의 하루 권장 수면량을 지키고 있는지 그래프로 확인하세요.', body_nl = 'Zet de slaaptimer aan als je baby slaapt en controleer in de grafiek of hij de dagelijkse slaapnorm voor 9 maanden haalt.', body_pl = 'Gdy maluszek śpi, włącz timer snu i sprawdź na wykresie, czy przesypia dzienną normę dla 9-miesięcznego dziecka.', body_pt = 'Quando o bebé dormir, ligue o temporizador de sono e veja no gráfico se cumpre as horas de sono diárias de um bebé de 9 meses.', body_sv = 'Starta Sömntimern när barnet sover och kolla i diagrammet om din 9 månader gamla bebis följer den dagliga sömnnormen.', body_vi = 'Khi bé ngủ, hãy bật Bộ hẹn giờ ngủ và xem biểu đồ để biết bé 9 tháng có ngủ đủ thời lượng mỗi ngày không.', body_zh = '宝宝睡觉时打开睡眠计时器，从图表里看看你9个月的宝宝是否达到了每天的睡眠参考量。' WHERE id = 'e2296439-aad7-4bdf-a627-05d1e066a3d8' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Trepando al sillón 🧗‍♂️', body_es = '¿Ya no le basta con moverse por el suelo e intenta subirse a los muebles? ¡Qué desarrollo motor tan decidido! Vigílale siempre.', title_fr = 'Grimper sur le fauteuil 🧗‍♂️', body_fr = 'Se déplacer au sol ne lui suffit plus, il essaie de grimper sur les meubles ? Une motricité bien déterminée ! Surveillez-le absolument.', title_hi = 'कुर्सी पर चढ़ना 🧗‍♂️', body_hi = 'नीचे घूमना उसके लिए काफ़ी नहीं, फ़र्नीचर पर चढ़ने की कोशिश करता है? ज़बरदस्त मोटर विकास! उस पर ज़रूर नज़र रखिए।', title_id = 'Memanjat kursi 🧗‍♂️', body_id = 'Berjalan di bawah tak lagi cukup, ia mencoba naik ke atas perabot? Perkembangan motorik yang gigih! Pastikan selalu diawasi.', title_ja = 'ソファによじのぼる 🧗‍♂️', body_ja = '床を動きまわるだけでは物足りず、家具の上にのぼろうとしていますか？たくましい運動の発達です！必ず目を離さないで。', title_ko = '의자 오르기 🧗‍♂️', body_ko = '바닥을 돌아다니는 것으로 모자라 가구 위로 올라가려 하나요? 끈질긴 운동 발달이에요! 꼭 곁에서 지켜봐 주세요.', title_nl = 'Op de stoel klimmen 🧗‍♂️', body_nl = 'Is beneden rondlopen niet meer genoeg en probeert je baby op de meubels te klimmen? Een vastberaden motorische ontwikkeling! Houd hem altijd in de gaten.', title_pl = 'Wspinaczka na fotel 🧗‍♂️', body_pl = 'Nie wystarcza mu ruch na dole i próbuje wchodzić na meble? Uparty rozwój motoryczny! Koniecznie miej go na oku.', title_pt = 'Trepar ao sofá 🧗‍♂️', body_pt = 'Andar cá em baixo já não lhe chega e tenta subir para cima dos móveis? Um desenvolvimento motor persistente! Mantenha-o sempre sob vigilância.', title_sv = 'Klättrar upp i fåtöljen 🧗‍♂️', body_sv = 'Räcker det inte att röra sig på golvet, försöker barnet klättra upp på möblerna? En envis motorisk utveckling! Håll alltid uppsikt.', title_vi = 'Trèo lên ghế bành 🧗‍♂️', body_vi = 'Bò dưới sàn không đủ với bé, bé cố trèo lên đồ đạc? Sự phát triển vận động kiên trì! Nhất định phải luôn để mắt đến bé.', title_zh = '爬上扶手椅 🧗‍♂️', body_zh = '在地上活动已经满足不了宝宝，开始想爬到家具上面？动作发育真是锲而不舍！一定要看好宝宝。' WHERE id = '13322f59-d734-452d-8178-1ffb4e5e9f78' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ha llorado y ha estado inquieto todo el día? La solución es muy sencilla: mira Tiempo y ropa, súbele al carrito y sal enseguida al parque.', body_fr = 'Il a pleuré et s''est agité toute la journée ? La solution est simple : consultez Météo et tenue, installez-le dans la poussette et filez au parc.', body_hi = 'दिनभर रोता और बेचैन रहा? उपाय बहुत आसान है: मौसम और कपड़े देखिए, स्ट्रॉलर में बिठाइए और तुरंत पार्क चलिए।', body_id = 'Ia menangis dan rewel seharian? Solusinya sangat sederhana: cek Cuaca dan Pakaian, dudukkan ia di stroller, dan segera pergi ke taman.', body_ja = '1日中泣いてぐずっていた？解決法はとてもシンプル：「天気と服装」を見て、ベビーカーに乗せ、すぐに公園へ。', body_ko = '하루 종일 울고 보챘나요? 해결책은 아주 간단해요: 날씨와 옷차림을 확인하고 유모차에 태워 바로 공원으로 나가세요.', body_nl = 'Heeft je baby de hele dag gehuild en was hij onrustig? De oplossing is simpel: kijk in Weer en kleding, zet hem in de kinderwagen en ga meteen naar het park.', body_pl = 'Cały dzień płakał i był niespokojny? Rozwiązanie jest bardzo proste: sprawdź Pogodę i ubiór, posadź go w wózku i od razu idźcie do parku.', body_pt = 'Chorou e esteve inquieto o dia todo? A solução é muito simples: veja o Tempo e Roupa, ponha-o no carrinho e vá já para o parque.', body_sv = 'Har barnet gråtit och varit oroligt hela dagen? Lösningen är enkel: kolla Väder och kläder, lägg barnet i vagnen och gå direkt till parken.', body_vi = 'Bé khóc và quấy cả ngày? Cách giải quyết rất đơn giản: xem Thời tiết và trang phục, đặt bé vào xe đẩy và ra công viên ngay.', body_zh = '宝宝哭闹烦躁了一整天？办法很简单：看看天气穿衣，放进婴儿车，马上去公园。' WHERE id = 'b349c13b-d822-42ec-876c-d41ccb790846' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La acústica de la habitación 🤫', body_es = 'Mientras duerme, cualquier crujido le despierta. Analiza el ambiente con el Medidor de sonido y asegura un silencio sin interrupciones.', title_fr = 'L''acoustique de la chambre 🤫', body_fr = 'Pendant son sommeil, le moindre petit bruit le réveille. Analysez l''ambiance avec le Sonomètre et assurez un silence sans interruption.', title_hi = 'कमरे की आवाज़ 🤫', body_hi = 'सोते समय ज़रा सी चटक भी उसे जगा देती है। साउंड मीटर से माहौल का विश्लेषण कीजिए और लगातार खामोशी पक्की कीजिए।', title_id = 'Akustik kamar 🤫', body_id = 'Bunyi kecil saat tidur membuatnya terbangun. Analisis suasana dengan Pengukur Suara dan pastikan keheningan tanpa gangguan.', title_ja = '部屋の音環境 🤫', body_ja = '眠っているとき、小さなカチッという音でも起きてしまいます。「サウンドメーター」で環境をチェックして、途切れない静けさを守りましょう。', title_ko = '방의 소리 환경 🤫', body_ko = '잘 때 작은 소리 하나에도 깨요. 소음 측정기로 환경을 분석해 끊김 없는 고요를 만들어 주세요.', title_nl = 'Akoestiek in de kamer 🤫', body_nl = 'Een klein tikje maakt je baby wakker tijdens zijn slaap. Analyseer de omgeving met de Geluidsmeter en zorg voor ononderbroken stilte.', title_pl = 'Akustyka pokoju 🤫', body_pl = 'Podczas snu budzi go nawet ciche trzaśnięcie. Przeanalizuj otoczenie Miernikiem dźwięku i zapewnij nieprzerwaną ciszę.', title_pt = 'A acústica do quarto 🤫', body_pt = 'Durante o sono, um pequeno estalido acorda-o. Analise o ambiente com o Medidor de Som e garanta um silêncio sem interrupções.', title_sv = 'Rummets akustik 🤫', body_sv = 'Ett litet knäpp väcker barnet när det sover. Analysera miljön med Ljudmätaren och se till att det är tyst utan avbrott.', title_vi = 'Âm thanh trong phòng 🤫', body_vi = 'Một tiếng lách cách nhỏ cũng làm bé thức giấc. Hãy phân tích môi trường bằng Đo âm thanh và đảm bảo sự yên tĩnh liên tục.', title_zh = '房间的声音环境 🤫', body_zh = '睡觉时一点小响声都会吵醒宝宝。用噪音测量分析环境，保证不被打扰的安静。' WHERE id = 'e46eb59c-0196-4f8a-b3f3-e86458e1f828' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Sientes que no llegas? 💬', body_es = 'Entra ya en la Comunidad Anacan, lee los comentarios de apoyo de otras mamás y quédate tranquila.', title_fr = 'Vous ne vous sentez pas à la hauteur ? 💬', body_fr = 'Rejoignez tout de suite la Communauté Anacan, lisez les commentaires bienveillants des autres mamans et soyez rassurée.', title_hi = 'खुद को कमतर महसूस कर रही हैं? 💬', body_hi = 'तुरंत Anacan कम्युनिटी में आइए, दूसरी माँओं की हौसला बढ़ाने वाली टिप्पणियाँ पढ़िए और सुकून पाइए।', title_id = 'Merasa tidak cukup baik? 💬', body_id = 'Segera masuk ke Komunitas Anacan, baca komentar penuh dukungan dari ibu-ibu lain, dan tenanglah.', title_ja = '自分はダメだと感じますか？💬', body_ja = 'すぐにAnacanコミュニティに参加して、ほかのママたちの励ましのコメントを読んで、ほっとしましょう。', title_ko = '부족한 엄마 같다고 느끼나요? 💬', body_ko = '지금 Anacan 커뮤니티에 들어가 다른 엄마들의 응원 댓글을 읽으며 마음을 놓으세요.', title_nl = 'Voel je je tekortschieten? 💬', body_nl = 'Ga meteen naar de Anacan Community, lees de steunende reacties van andere moeders en ontspan.', title_pl = 'Czujesz, że nie dajesz rady? 💬', body_pl = 'Od razu zajrzyj do Społeczności Anacan, przeczytaj wspierające komentarze innych mam i poczuj ulgę.', title_pt = 'Sente que não é suficiente? 💬', body_pt = 'Entre já na Comunidade Anacan, leia os comentários de apoio de outras mães e fique mais tranquila.', title_sv = 'Känner du dig otillräcklig? 💬', body_sv = 'Gå genast in i Anacans Community, läs andra mammors stöttande kommentarer och slappna av.', title_vi = 'Mẹ thấy mình chưa đủ tốt? 💬', body_vi = 'Hãy vào ngay Cộng đồng Anacan, đọc những bình luận động viên từ các bà mẹ khác và thư thái hơn.', title_zh = '觉得自己做得不够好？💬', body_zh = '马上进入Anacan社区，读读其他妈妈的暖心评论，放松一下吧。' WHERE id = '3ab1636f-ed5f-47f5-93d7-4ac521edd386' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hoy todo ha salido patas arriba?', body_es = 'No pasa nada: si tu peque está bien comido y limpio, eres la mejor madre del mundo.', title_fr = 'Tout est sens dessus dessous aujourd''hui ?', body_fr = 'Ce n''est pas grave : si votre enfant a le ventre plein et qu''il est propre, vous êtes la meilleure maman du monde.', title_hi = 'आज सब कुछ उलट-पुलट हो गया?', body_hi = 'कोई बात नहीं, अगर आपका बच्चा भरे पेट और साफ़-सुथरा है, तो आप दुनिया की सबसे अच्छी माँ हैं।', title_id = 'Hari ini semuanya kacau balau?', body_id = 'Tidak apa-apa, kalau anak Anda kenyang dan bersih, Anda adalah ibu terbaik di dunia.', title_ja = '今日は何もかもめちゃくちゃだった？', body_ja = '大丈夫。赤ちゃんがお腹いっぱいで清潔なら、あなたは世界でいちばんのママです。', title_ko = '오늘 모든 게 엉망이었나요?', body_ko = '괜찮아요, 아이가 배부르고 깨끗하다면 당신은 세상에서 가장 좋은 엄마예요.', title_nl = 'Liep vandaag alles in de soep?', body_nl = 'Geeft niet: als je kindje een vol buikje heeft en schoon is, ben jij de beste moeder ter wereld.', title_pl = 'Dziś wszystko poszło na opak?', body_pl = 'Nic nie szkodzi, jeśli twoje dziecko jest najedzone i czyste, jesteś najlepszą mamą na świecie.', title_pt = 'Hoje ficou tudo de pernas para o ar?', body_pt = 'Não faz mal: se o bebé está alimentado e limpo, é a melhor mãe do mundo.', title_sv = 'Gick allt snett i dag?', body_sv = 'Det gör inget, är barnet mätt och rent är du världens bästa mamma.', title_vi = 'Hôm nay mọi thứ rối tung?', body_vi = 'Không sao cả, nếu bé no và sạch sẽ, mẹ chính là người mẹ tốt nhất thế giới.', title_zh = '今天一切都乱套了？', body_zh = '没关系，只要宝宝吃饱了、干干净净的，你就是世界上最好的妈妈。' WHERE id = '62964d86-1e07-4c7f-a135-52c48581ffc5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Aprende el nombre de las cosas 🧸', body_es = '¿Cuando le preguntas «¿dónde está la pelota?» la busca con la mirada y la encuentra? ¡Su comprensión va de maravilla! Jugad a decir el nombre de las cosas.', title_fr = 'Il apprend le nom des objets 🧸', body_fr = 'Quand vous demandez « Où est le ballon ? », il le cherche des yeux et le trouve ? Sa compréhension se perfectionne ! Jouez avec lui en nommant les objets.', title_hi = 'चीज़ों के नाम सीख रहा है 🧸', body_hi = '''गेंद कहाँ है?'' पूछने पर आँखों से ढूँढकर पता लगा लेता है? उसकी समझ बढ़िया हो रही है! चीज़ों के नाम लेकर उसके साथ खेल खेलिए।', title_id = 'Ia belajar nama benda 🧸', body_id = 'Saat ditanya "Bolanya di mana?", ia mencarinya dengan mata dan menemukannya? Pemahamannya makin sempurna! Mainkan permainan menyebut nama-nama benda bersamanya.', title_ja = 'ものの名前を覚えている 🧸', body_ja = '「ボールはどこ？」と聞くと、目で探して見つけますか？理解する力がぐんぐん育っています！ものの名前を言いながら一緒に遊びましょう。', title_ko = '물건 이름을 배워요 🧸', body_ko = '''공 어디 있어?'' 하고 물으면 눈으로 찾아내나요? 이해력이 멋지게 자라고 있어요! 물건 이름을 말하며 함께 놀아 주세요.', title_nl = 'Hij leert de namen van dingen 🧸', body_nl = 'Zoekt je baby met zijn ogen en vindt hij de bal als je vraagt: waar is de bal? Zijn begrip wordt steeds beter! Speel spelletjes waarbij je dingen bij hun naam noemt.', title_pl = 'Uczy się nazw przedmiotów 🧸', body_pl = 'Gdy pytasz „gdzie jest piłka?”, szuka jej wzrokiem i znajduje? Rozumienie jest coraz lepsze! Bawcie się w nazywanie przedmiotów.', title_pt = 'Aprende o nome das coisas 🧸', body_pt = 'Quando pergunta "onde está a bola?", ele procura-a com os olhos e encontra-a? A compreensão está a ficar perfeita! Faça jogos com ele dizendo o nome das coisas.', title_sv = 'Lär sig vad saker heter 🧸', body_sv = 'Letar barnet med blicken och hittar bollen när du frågar ''var är bollen?''? Förståelsen blir allt bättre! Lek lekar där ni säger vad saker heter.', title_vi = 'Bé học tên đồ vật 🧸', body_vi = 'Khi mẹ hỏi "Quả bóng đâu rồi?", bé đưa mắt tìm và thấy? Nhận thức của bé đang hoàn thiện! Hãy chơi với bé bằng cách gọi tên các đồ vật.', title_zh = '在学东西的名字 🧸', body_zh = '问宝宝“球在哪儿？”，宝宝会用眼睛去找并找到？认知能力越来越好了！和宝宝玩说出物品名字的游戏吧。' WHERE id = 'fa0817a9-00d2-41fc-bdcb-8fdae95932ff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Equilibrio sobre dos pies 🤸‍♂️', body_es = '¿Cuando le sujetas por las axilas se mantiene más derecho y firme sobre sus pies? ¡No dejes de registrar este reflejo básico de dar pasos en el Seguimiento del desarrollo!', title_fr = 'L''équilibre sur deux pieds 🤸‍♂️', body_fr = 'Quand vous le tenez sous les bras, il se tient plus droit et plus fort sur ses jambes ? Notez absolument ce réflexe de base de la marche dans le Suivi de développement !', title_hi = 'दोनों पैरों पर संतुलन 🤸‍♂️', body_hi = 'बगलों से पकड़ने पर पैरों पर ज़्यादा सीधा और मज़बूती से खड़ा होता है? ग्रोथ ट्रैकर में कदम बढ़ाने की इस बुनियादी प्रतिक्रिया को ज़रूर दर्ज कीजिए!', title_id = 'Seimbang di atas dua kaki 🤸‍♂️', body_id = 'Saat Anda memegang ketiaknya, ia berdiri lebih tegak dan kuat di atas kakinya? Jangan lupa catat refleks melangkah dasar ini di Pelacak Perkembangan!', title_ja = '2本の足でバランス 🤸‍♂️', body_ja = 'わきの下を支えると、前よりまっすぐ力強く足で立てますか？「発達トラッカー」に、この歩くための大切な反射をぜひ記録しましょう！', title_ko = '두 발로 균형 잡기 🤸‍♂️', body_ko = '겨드랑이를 잡아 주면 두 발로 더 꼿꼿하고 힘 있게 서나요? 성장 기록에 이 기본 걸음 반사를 꼭 남기세요!', title_nl = 'Balans op twee beentjes 🤸‍♂️', body_nl = 'Staat je baby rechter en sterker op zijn beentjes als je hem onder zijn armpjes vasthoudt? Noteer deze basisstapreflex zeker in de Groeitracker!', title_pl = 'Równowaga na dwóch nóżkach 🤸‍♂️', body_pl = 'Gdy trzymasz go pod pachami, stoi na nóżkach prościej i pewniej? Koniecznie zapisz ten podstawowy odruch kroczenia w Śledzeniu rozwoju!', title_pt = 'Equilíbrio nos dois pés 🤸‍♂️', body_pt = 'Quando o segura pelas axilas, fica de pé mais direito e com mais força? Registe sem falta no Registo de Desenvolvimento este reflexo base do passo!', title_sv = 'Balans på två ben 🤸‍♂️', body_sv = 'Står barnet rakare och starkare på benen när du håller det under armarna? Anteckna absolut den här grundläggande stegreflexen i Utvecklingsspåraren!', title_vi = 'Thăng bằng trên hai chân 🤸‍♂️', body_vi = 'Khi mẹ đỡ dưới nách, bé đứng thẳng và vững hơn trên đôi chân? Nhất định hãy ghi lại phản xạ bước đi nền tảng này trong Theo dõi phát triển!', title_zh = '双脚站立保持平衡 🤸‍♂️', body_zh = '扶着宝宝腋下时，宝宝的双脚站得更直、更有力了？一定要在发育追踪里记下这个基础的迈步反射！' WHERE id = '93f4fd0f-1f45-436c-b46b-7acc69d1b899' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora del cuento mágico 🪄', body_es = 'Dale color a la rutina de la noche con el cuento «Los secretos del pequeño héroe para dormirse» en Cuentos inteligentes.', title_fr = 'L''heure du conte magique 🪄', body_fr = 'Dans les Contes intelligents, mettez de la couleur dans la routine du soir avec l''histoire « Les secrets d''endormissement du petit héros ».', title_hi = 'जादुई कहानी का समय 🪄', body_hi = 'स्मार्ट कहानियों में ''नन्हे हीरो के सोने के राज़'' नाम की कहानी से शाम के रूटीन में रंग भरिए।', title_id = 'Waktunya dongeng ajaib 🪄', body_id = 'Warnai rutinitas malam dengan kisah "Rahasia tidur sang pahlawan kecil" di Dongeng Pintar.', title_ja = '魔法のお話タイム 🪄', body_ja = '「スマートおはなし」で「小さなヒーローのねんねのひみつ」というお話をつくって、夜のルーティンに彩りを添えましょう。', title_ko = '마법 같은 동화 시간 🪄', body_ko = '스마트 동화의 ''꼬마 영웅의 잠드는 비밀'' 이야기로 저녁 루틴에 색을 더해 보세요.', title_nl = 'Tijd voor een magisch sprookje 🪄', body_nl = 'Geef de avondroutine kleur met het verhaal ''De inslaapgeheimen van een kleine held'' in Slimme sprookjes.', title_pl = 'Czas na magiczną bajkę 🪄', body_pl = 'Dodaj kolorów wieczornej rutynie historią „Sekrety zasypiania małego bohatera” z Mądrych bajek.', title_pt = 'Hora da história mágica 🪄', body_pt = 'Dê cor à rotina da noite com a história "Os segredos do pequeno herói para adormecer" nas Histórias Inteligentes.', title_sv = 'Magisk sagostund 🪄', body_sv = 'Ge kvällsrutinen lite färg med sagan Den lilla hjältens hemligheter för att somna i Smarta sagor.', title_vi = 'Giờ cổ tích kỳ diệu 🪄', body_vi = 'Hãy thêm màu sắc cho nếp sinh hoạt buổi tối với câu chuyện "Bí mật đi ngủ của người hùng nhỏ" trong Truyện cổ tích thông minh.', title_zh = '神奇的故事时间 🪄', body_zh = '用智能故事里的《小英雄的入睡秘密》，给晚间作息增添一抹色彩吧。' WHERE id = 'b0bdf4f4-2902-43a5-876f-e99b39aef4f9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lista te salva la vida 🛒', body_es = 'Las necesidades de casa no se acaban nunca. No te calientes la cabeza: rellena la Lista de la compra y deja que papá sea el salvador al volver del trabajo.', title_fr = 'La liste qui sauve la vie 🛒', body_fr = 'Les besoins de la maison ne s''arrêtent jamais. Ne vous fatiguez pas : remplissez la Liste de courses et laissez papa jouer les sauveurs en rentrant du travail.', title_hi = 'लिस्ट जान बचाती है 🛒', body_hi = 'घर की रोज़ की ज़रूरतें कभी खत्म नहीं होतीं। दिमाग मत थकाइए, शॉपिंग लिस्ट भरिए और काम से लौटते पापा के मददगार बनने का इंतज़ार कीजिए।', title_id = 'Daftar menyelamatkan hidup 🛒', body_id = 'Kebutuhan rumah sehari-hari tak ada habisnya. Jangan bikin pusing, isi Daftar Belanja dan tunggu ayah pulang kerja sebagai penyelamat.', title_ja = 'リストは命綱 🛒', body_ja = '家で必要なものはいつまでもなくなりません。頭を疲れさせないで、「買い物リスト」を埋めて、仕事帰りのパパのヒーロー登場を待ちましょう。', title_ko = '목록이 살려 줘요 🛒', body_ko = '매일 필요한 집안 물건은 끝이 없어요. 머리 아프게 고민하지 말고 쇼핑 목록을 채운 뒤 퇴근하는 아빠가 구원자가 되길 기다리세요.', title_nl = 'Een lijstje redt levens 🛒', body_nl = 'Aan de dagelijkse benodigdheden in huis komt geen eind. Breek je hoofd er niet over, vul je Boodschappenlijstje en laat papa op weg van zijn werk de redder zijn.', title_pl = 'Lista ratuje życie 🛒', body_pl = 'Codzienne domowe potrzeby nigdy się nie kończą. Nie męcz głowy, uzupełnij Listę zakupów i czekaj, aż tata wróci z pracy i przyjdzie na ratunek.', title_pt = 'A lista salva vidas 🛒', body_pt = 'As necessidades diárias da casa nunca acabam. Não canse a cabeça: preencha a Lista de Compras e espere que o pai, ao voltar do trabalho, seja o salvador.', title_sv = 'Listan räddar liv 🛒', body_sv = 'Hemmets dagliga behov tar aldrig slut. Belasta inte hjärnan, fyll i Inköpslistan och vänta på att pappa ska bli räddaren när han kommer hem från jobbet.', title_vi = 'Danh sách là cứu tinh 🛒', body_vi = 'Đồ dùng hằng ngày trong nhà không bao giờ hết cần. Đừng bắt não làm việc quá sức, hãy điền vào Danh sách mua sắm và chờ bố đi làm về giải cứu.', title_zh = '清单是救命稻草 🛒', body_zh = '家里的日常需求永远没完没了。别费脑筋，填好购物清单，等下班回家的爸爸来救场吧。' WHERE id = 'c6da7887-a402-4a11-8fbf-8de4d7696325' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué le pregunto al médico? 🤖', body_es = '¿No sabes qué preguntar antes de la revisión mensual? Pide a Anacan AI una lista de control para la revisión de los 9 meses.', title_fr = 'Que demander au médecin ? 🤖', body_fr = 'Vous ne savez pas quoi demander avant la visite mensuelle ? Demandez à Anacan AI une liste de contrôle pour le bilan des 9 mois.', title_hi = 'डॉक्टर से क्या पूछूँ? 🤖', body_hi = 'महीने की जाँच पर जाने से पहले क्या पूछना है, पता नहीं? Anacan AI से 9 महीने के चेकअप की सूची माँगिए।', title_id = 'Apa yang perlu ditanyakan ke dokter? 🤖', body_id = 'Tidak tahu apa yang harus ditanyakan sebelum pemeriksaan bulanan? Minta daftar cek kesehatan 9 bulan dari Anacan AI.', title_ja = 'お医者さんに何を聞こう？🤖', body_ja = '毎月の健診の前に、何を質問すればいいかわからない？Anacan AIに生後9か月の健診チェックリストを頼んでみましょう。', title_ko = '의사에게 무엇을 물어볼까요? 🤖', body_ko = '월간 검진 전에 무엇을 물어야 할지 모르겠나요? Anacan AI에게 9개월 검진 체크리스트를 요청하세요.', title_nl = 'Wat vraag ik aan de arts? 🤖', body_nl = 'Weet je niet wat je moet vragen bij de maandelijkse controle? Vraag Anacan AI om een checklist voor de controle bij 9 maanden.', title_pl = 'O co zapytać lekarza? 🤖', body_pl = 'Nie wiesz, o co pytać przed comiesięczną wizytą kontrolną? Poproś Anacan AI o listę kontrolną na wizytę w 9. miesiącu.', title_pt = 'O que pergunto ao médico? 🤖', body_pt = 'Não sabe o que perguntar antes da consulta mensal? Peça ao Anacan AI a lista do check-up dos 9 meses.', title_sv = 'Vad ska jag fråga läkaren? 🤖', body_sv = 'Vet du inte vad du ska fråga inför månadskontrollen? Be Anacan AI om en checklista för 9-månaderskontrollen.', title_vi = 'Nên hỏi bác sĩ điều gì? 🤖', body_vi = 'Mẹ không biết nên hỏi gì trước buổi khám hằng tháng? Hãy nhờ Anacan AI lập danh sách kiểm tra cho bé 9 tháng.', title_zh = '该问医生什么？🤖', body_zh = '去月度体检前不知道该问些什么？向Anacan AI要一份9个月体检问题清单吧。' WHERE id = '1b15944e-9198-4fc4-b86d-0b17af6cdd00' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pequeño ayudante de casa 🧺', body_es = '¿Mientras doblas la ropa viene a «ayudarte» deshaciéndolo todo? No le apartes, dale un trapo para que participe.', title_fr = 'Le petit assistant de la maison 🧺', body_fr = 'Quand vous pliez le linge, il vient vous « aider » en défaisant tout ? Ne l''écartez pas, donnez-lui une serviette.', title_hi = 'घर का नन्हा मददगार 🧺', body_hi = 'आप कपड़े तह करती हैं और वह आकर सब बिखेरकर ''मदद'' करता है? उसे इस काम से दूर मत कीजिए, उसके हाथ में एक रूमाल दे दीजिए।', title_id = 'Asisten kecil di rumah 🧺', body_id = 'Saat Anda melipat baju, ia datang "membantu" dengan mengacak-acaknya? Jangan jauhkan ia, berikan saja sehelai handuk kecil.', title_ja = 'おうちの小さなお手伝いさん 🧺', body_ja = 'あなたが服をたたんでいると、来てちらかすことでお手伝いしてくれますか？仲間はずれにしないで、ハンカチを1枚渡してあげましょう。', title_ko = '집안의 꼬마 도우미 🧺', body_ko = '엄마가 빨래를 갤 때 와서 흐트러뜨리며 돕나요? 함께하지 못하게 막지 말고 손수건 하나를 건네주세요.', title_nl = 'Een kleine hulp in huis 🧺', body_nl = 'Komt je baby je ''helpen'' door alles weer door elkaar te gooien als je de was opvouwt? Houd hem er niet buiten, geef hem een doekje.', title_pl = 'Mały domowy pomocnik 🧺', body_pl = 'Gdy składasz ubrania, przychodzi „pomóc”, rozrzucając je? Nie odsuwaj go od tego, daj mu do rączki ręcznik.', title_pt = 'O pequeno ajudante da casa 🧺', body_pt = 'Enquanto dobra a roupa, ele vem ajudar... a desarrumar? Não o afaste, dê-lhe um pano para a mão.', title_sv = 'Hemmets lilla hjälpreda 🧺', body_sv = 'Hjälper barnet till genom att stöka till när du viker tvätt? Stäng inte ute det, ge det en handduk att hålla i.', title_vi = 'Người phụ việc nhỏ trong nhà 🧺', body_vi = 'Khi mẹ gấp quần áo, bé cũng đến "giúp" bằng cách làm tung hết? Đừng gạt bé ra, hãy đưa cho bé một chiếc khăn.', title_zh = '家里的小帮手 🧺', body_zh = '你叠衣服时，宝宝跑来把衣服弄乱“帮忙”？别把宝宝赶走，给宝宝一条毛巾吧。' WHERE id = '1eda7621-0a6a-4ff0-8efe-ec931b28a106' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Deja salir tus emociones 📝', body_es = 'Por la tarde, prepárate un café y escribe una nota breve en el Diario de ánimo comparando cómo te sientes ahora con los meses anteriores.', title_fr = 'Libérez vos émotions 📝', body_fr = 'En fin de journée, prenez un café et écrivez une petite note dans le Journal d''humeur en comparant vos émotions d''aujourd''hui à celles des mois passés.', title_hi = 'अपनी भावनाओं को बाहर आने दीजिए 📝', body_hi = 'शाम को अपनी कॉफ़ी लीजिए और पिछले महीनों से अपनी अभी की भावनाओं की तुलना करते हुए मूड डायरी में एक छोटा नोट लिखिए।', title_id = 'Lepaskan perasaan Anda 📝', body_id = 'Ambil kopi sore Anda dan tulis catatan kecil di Buku Harian Suasana Hati, bandingkan perasaan Anda di bulan-bulan lalu dengan sekarang.', title_ja = '気持ちを解き放とう 📝', body_ja = '夕方にコーヒーを手に、「気分日記」にこれまでの数か月と今の気持ちをくらべて、ちょっとしたメモを書きましょう。', title_ko = '감정을 자유롭게 풀어 주세요 📝', body_ko = '저녁 커피를 들고 기분 일기에 지난 몇 달과 지금의 감정을 비교하며 짧은 메모를 남겨 보세요.', title_nl = 'Laat je gevoelens de vrije loop 📝', body_nl = 'Pak ''s middags een koffie en schrijf een korte notitie in je Stemmingsdagboek waarin je je gevoelens van nu vergelijkt met die van de afgelopen maanden.', title_pl = 'Uwolnij emocje 📝', body_pl = 'Weź popołudniową kawę i napisz w Dzienniku nastroju krótką notkę, porównując obecne uczucia z tymi z minionych miesięcy.', title_pt = 'Liberte as emoções 📝', body_pt = 'Ao fim do dia, pegue num café e escreva uma pequena nota no Diário de Humor comparando o que sente agora com os meses passados.', title_sv = 'Släpp fram känslorna 📝', body_sv = 'Ta en kopp kaffe på eftermiddagen och skriv en kort anteckning i Humördagboken där du jämför dina känslor nu med de tidigare månaderna.', title_vi = 'Hãy giải phóng cảm xúc 📝', body_vi = 'Chiều nay hãy pha một tách cà phê và viết một ghi chú nhỏ vào Nhật ký tâm trạng, so sánh cảm xúc bây giờ với những tháng trước.', title_zh = '释放你的情绪 📝', body_zh = '傍晚端起咖啡，在心情日记里写一段小记录，比较一下过去几个月和现在的感受吧。' WHERE id = '59e058ca-af20-4537-9c74-8aa7eb175af6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuídate 🍲', body_es = 'Si tú estás sana, tu bebé también. Elige en Recetas saludables una ensalada ligera para mamá que se prepara en 10 minutos y cómetela.', title_fr = 'Prenez soin de vous 🍲', body_fr = 'Si vous êtes en forme, il l''est aussi. Choisissez dans les Recettes saines une salade légère pour maman, prête en 10 minutes, et mangez-la.', title_hi = 'अपना ख्याल रखिए 🍲', body_hi = 'आप सेहतमंद हैं, तो वह भी सेहतमंद है। सेहतमंद रेसिपी से 10 मिनट में बनने वाला हल्का ''माँ का सलाद'' चुनिए और खाइए।', title_id = 'Jaga diri Anda 🍲', body_id = 'Kalau Anda sehat, ia juga sehat. Pilih salad ringan untuk ibu dari Resep Sehat yang siap dalam 10 menit, lalu makanlah.', title_ja = '自分を大切に 🍲', body_ja = 'あなたが元気なら、赤ちゃんも元気。「ヘルシーレシピ」から10分でできる軽いママサラダを選んで、食べましょう。', title_ko = '나를 지켜요 🍲', body_ko = '엄마가 건강해야 아기도 건강해요. 건강한 레시피에서 10분 만에 만드는 가벼운 엄마 샐러드를 골라 드세요.', title_nl = 'Zorg voor jezelf 🍲', body_nl = 'Als jij gezond bent, is je baby dat ook. Kies uit Gezonde recepten een lichte mamasalade die in 10 minuten klaar is en eet hem op.', title_pl = 'Zadbaj o siebie 🍲', body_pl = 'Gdy ty jesteś zdrowa, on też jest zdrowy. Wybierz w Zdrowych przepisach lekką sałatkę dla mamy gotową w 10 minut i ją zjedz.', title_pt = 'Cuide de si 🍲', body_pt = 'Se a mãe está saudável, o bebé também está. Escolha nas Receitas Saudáveis uma salada leve de mãe que se faz em 10 minutos e coma.', title_sv = 'Ta hand om dig själv 🍲', body_sv = 'Mår du bra, mår barnet bra. Välj den lätta mammasalladen från Hälsosamma recept som är klar på 10 minuter och ät.', title_vi = 'Hãy chăm sóc bản thân 🍲', body_vi = 'Mẹ khỏe thì bé cũng khỏe. Hãy chọn món salad nhẹ dành cho mẹ làm trong 10 phút từ Công thức lành mạnh và thưởng thức nhé.', title_zh = '照顾好自己 🍲', body_zh = '你健康，宝宝才健康。从健康食谱里挑一份10分钟就能做好的清爽妈妈沙拉，吃起来吧。' WHERE id = '30a7e68c-862a-436f-a801-8270fce13b90' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baño templado, masaje y habitación a oscuras. 🛀', body_es = 'Mantener la rutina de sueño es el secreto básico para tener noches sin interrupciones.', title_fr = 'Bain tiède, massage et pièce assombrie. 🛀', body_fr = 'Préserver la routine du coucher, c''est le secret fondamental des nuits sans interruption.', title_hi = 'गुनगुना स्नान, मालिश और कमरे में अँधेरा 🛀', body_hi = 'सोने का रूटीन बनाए रखना बिना रुकावट वाली रातों का सबसे बुनियादी राज़ है।', title_id = 'Mandi air hangat, pijat, dan kamar yang diredupkan. 🛀', body_id = 'Menjaga rutinitas tidur adalah rahasia utama malam tanpa terbangun.', title_ja = 'ぬるめのお風呂、マッサージ、部屋を暗くする。🛀', body_ja = 'ねんねのルーティンを守ることが、途切れない夜のいちばんの基本のひみつです。', title_ko = '따뜻한 목욕, 마사지, 어두운 방. 🛀', body_ko = '잠자리 루틴을 지키는 것이 깨지 않는 밤의 가장 기본적인 비결이에요.', title_nl = 'Een lauw badje, een massage en een verduisterde kamer. 🛀', body_nl = 'De slaaproutine bewaken is het belangrijkste geheim van ononderbroken nachten.', title_pl = 'Ciepła kąpiel, masaż i przyciemniony pokój. 🛀', body_pl = 'Pilnowanie rytuału snu to podstawowy sekret nieprzerwanych nocy.', title_pt = 'Banho morno, massagem e quarto escurecido. 🛀', body_pt = 'Manter a rotina de sono é o segredo mais básico para noites sem interrupções.', title_sv = 'Ett ljummet bad, massage och ett mörkt rum. 🛀', body_sv = 'Att hålla fast vid sömnrutinen är den mest grundläggande hemligheten bakom nätter utan avbrott.', title_vi = 'Tắm nước ấm, mát-xa và làm tối phòng. 🛀', body_vi = 'Giữ nếp sinh hoạt trước khi ngủ là bí quyết cơ bản nhất cho những đêm ngủ trọn giấc.', title_zh = '温水澡、按摩、调暗房间 🛀', body_zh = '守护好睡前作息，是夜夜安睡最基本的秘诀。' WHERE id = '32607011-b168-4558-b64b-8c8947e8d9a9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sílabas distintas, intentos de frases enteras 🗣️', body_es = 'Habla largo y tendido en su propio idioma, como si construyera frases completas. ¡Escucha con atención al locutor más tierno de la habitación!', title_fr = 'Des syllabes variées, des essais de phrases 🗣️', body_fr = 'Il parle longuement dans sa propre langue, comme s''il faisait de vraies phrases. Écoutez bien le plus adorable présentateur de la maison !', title_hi = 'अलग-अलग अक्षर, पूरे वाक्य की कोशिश 🗣️', body_hi = 'लंबी-लंबी बातें करता है, मानो अपनी भाषा में पूरा वाक्य बना रहा हो। कमरे के सबसे प्यारे वक्ता को ध्यान से सुनिए!', title_id = 'Berbagai suku kata, mencoba kalimat utuh 🗣️', body_id = 'Ia berbicara panjang lebar dengan bahasanya sendiri, seolah sedang menyusun kalimat utuh. Dengarkan baik-baik penyiar termanis di ruangan ini!', title_ja = 'いろいろな音、文章みたいなおしゃべり 🗣️', body_ja = 'まるで文章を話しているかのように、自分の言葉で長々とおしゃべりしています。部屋でいちばんかわいいアナウンサーの話を、よく聞いてあげましょう！', title_ko = '다양한 음절, 문장 만들기 도전 🗣️', body_ko = '마치 완전한 문장을 만드는 것처럼 자기만의 언어로 길게 이야기해요. 방 안에서 가장 귀여운 아나운서의 말을 귀 기울여 들어 주세요!', title_nl = 'Allerlei lettergrepen, pogingen tot hele zinnen 🗣️', body_nl = 'Je baby praat lang in zijn eigen taal, alsof hij hele zinnen maakt. Luister goed naar de liefste nieuwslezer in de kamer!', title_pl = 'Różne sylaby i próby całych zdań 🗣️', body_pl = 'Mówi długo w swoim języku, jakby budował całe zdania. Posłuchaj uważnie najsłodszego spikera w pokoju!', title_pt = 'Sílabas diferentes, tentativas de frases completas 🗣️', body_pt = 'Fala longamente na sua própria língua, como se estivesse a fazer frases completas. Ouça com atenção o locutor mais doce do quarto!', title_sv = 'Olika stavelser, försök till hela meningar 🗣️', body_sv = 'Barnet pratar länge på sitt eget språk, som om det byggde hela meningar. Lyssna noga på rummets sötaste nyhetsuppläsare!', title_vi = 'Âm tiết mới, tập nói cả câu 🗣️', body_vi = 'Bé nói thật lâu bằng ngôn ngữ của riêng mình, cứ như đang nói cả câu. Hãy chăm chú lắng nghe "phát thanh viên" đáng yêu nhất trong phòng!', title_zh = '各种音节，尝试说完整的句子 🗣️', body_zh = '宝宝用自己的语言说个不停，就像在组织完整的句子。好好听听房间里这位最可爱的小播音员吧！' WHERE id = 'ca309c2b-9bd6-47c4-bfb8-da0eb88d4f08' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El sonido de la habitación 🤫', body_es = '¿Le cuesta más dormirse? Comprueba los decibelios de la habitación con el Medidor de sonido y baja la tele a un segundo plano.', title_fr = 'Le bruit de la chambre 🤫', body_fr = 'L''endormissement est devenu difficile ? Vérifiez les décibels de la pièce avec le Sonomètre et baissez le son de la télévision.', title_hi = 'कमरे की आवाज़ 🤫', body_hi = 'सोना मुश्किल हो गया है? साउंड मीटर से कमरे का डेसिबल जाँचिए और टीवी की आवाज़ धीमी कर दीजिए।', title_id = 'Suara di kamar 🤫', body_id = 'Ia makin sulit tertidur? Cek desibel kamar dengan Pengukur Suara dan kecilkan suara TV.', title_ja = '部屋の音 🤫', body_ja = '寝つきが悪くなった？「サウンドメーター」で部屋の音量（デシベル）をチェックして、テレビの音を小さくしましょう。', title_ko = '방 안의 소리 🤫', body_ko = '잠들기가 어려워졌나요? 소음 측정기로 방의 데시벨을 확인하고 TV 소리는 작게 줄여 주세요.', title_nl = 'Het geluid in de kamer 🤫', body_nl = 'Gaat in slaap vallen moeilijker? Controleer met de Geluidsmeter het aantal decibel in de kamer en zet het geluid van de tv zachter.', title_pl = 'Dźwięki w pokoju 🤫', body_pl = 'Zasypianie stało się trudniejsze? Sprawdź decybele w pokoju Miernikiem dźwięku i przycisz telewizor do tła.', title_pt = 'O som do quarto 🤫', body_pt = 'Adormecer ficou mais difícil? Verifique os decibéis do quarto com o Medidor de Som e baixe o som da televisão.', title_sv = 'Ljudet i rummet 🤫', body_sv = 'Har det blivit svårare att somna? Kolla rummets decibelnivå med Ljudmätaren och sänk ljudet på tv:n till bakgrundsnivå.', title_vi = 'Âm thanh trong phòng 🤫', body_vi = 'Bé khó vào giấc hơn? Kiểm tra mức decibel trong phòng bằng Đo âm thanh và vặn nhỏ tiếng tivi.', title_zh = '房间里的声音 🤫', body_zh = '入睡变难了？用噪音测量检查房间的分贝，把电视声调成背景音吧。' WHERE id = '3908e4ee-6364-4b5e-bf19-9883638e23db' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Después de un día difícil, sentaos cara a cara tu pareja y tú y hablad. Apoyaros reparte la carga a la mitad.', body_fr = 'Après une journée difficile, asseyez-vous face à votre conjoint et parlez. Vous soutenir mutuellement allège la charge de moitié.', body_hi = 'मुश्किल दिन के बाद अपने साथी के साथ आमने-सामने बैठकर दिल की बात कीजिए। एक-दूसरे का साथ बोझ आधा कर देता है।', body_id = 'Setelah hari yang berat, duduklah berhadapan dengan pasangan dan saling bercerita. Saling mendukung membuat beban terbagi dua.', body_ja = '大変な1日のあとは、パートナーと向き合って話しましょう。支え合うことで、負担は半分になります。', body_ko = '힘든 하루를 보낸 뒤 배우자와 마주 앉아 이야기를 나눠 보세요. 서로를 응원하면 짐이 절반으로 줄어요.', body_nl = 'Ga na een zware dag tegenover je partner zitten en praat je hart uit. Elkaar steunen halveert de last.', body_pl = 'Po trudnym dniu usiądź z partnerem twarzą w twarz i porozmawiajcie. Wzajemne wsparcie dzieli ciężar na pół.', body_pt = 'Depois de um dia difícil, sente-se frente a frente com o seu companheiro e conversem. Apoiarem-se um ao outro divide o peso ao meio.', body_sv = 'Efter en tuff dag, sätt er mittemot varandra och prata ut med din partner. Att stötta varandra halverar bördan.', body_vi = 'Sau một ngày vất vả, hãy ngồi đối diện và tâm sự cùng bố. Cùng nâng đỡ nhau sẽ giúp gánh nặng vơi đi một nửa.', body_zh = '辛苦一天后，和伴侣面对面坐下聊聊。互相支持，担子就轻了一半。' WHERE id = 'ce7b77f8-95b5-4071-bf35-61b06d785d85' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El equipo del «ven, ven» 👏', body_es = '¿Ha aprendido a hacer «ven, ven» con las manos? No dejes de grabar esta imitación tan tierna en vídeo y guárdala en tu álbum de recuerdos.', title_fr = 'Le geste « viens, viens » 👏', body_fr = 'Il a appris à faire « viens, viens » avec les mains ? Filmez absolument cette adorable imitation et ajoutez-la à votre album souvenirs.', title_hi = '''आओ-आओ'' का इशारा 👏', body_hi = 'हाथों से ''आओ-आओ'' का इशारा करना सीख गया? इस प्यारी नकल को ज़रूर वीडियो में रिकॉर्ड कीजिए और अपने यादों के एल्बम में जोड़िए।', title_id = 'Tim "sini-sini" 👏', body_id = 'Ia sudah belajar melambai "sini-sini" dengan tangannya? Rekam tiruan manis ini dalam video dan simpan di album kenangan Anda.', title_ja = 'おいでおいでチーム 👏', body_ja = '手で「おいでおいで」のしぐさを覚えましたか？このかわいいまねっこをぜひ動画に撮って、思い出のアルバムに入れましょう。', title_ko = '이리 와 손짓 👏', body_ko = '손으로 ''이리 와'' 하는 동작을 배웠나요? 이 귀여운 따라 하기를 꼭 영상으로 찍어 추억 앨범에 담아 두세요.', title_nl = 'Het kom-maar-team 👏', body_nl = 'Heeft je baby geleerd om met zijn handje ''kom maar'' te gebaren? Leg dit lieve nadoen zeker vast op video en zet het in je herinneringenalbum.', title_pl = 'Gest „chodź tu” 👏', body_pl = 'Nauczył się przywoływać rączką gestem „chodź, chodź”? Koniecznie nagraj to słodkie naśladowanie i dodaj do albumu wspomnień.', title_pt = 'A equipa do "anda cá" 👏', body_pt = 'Aprendeu a fazer "anda cá" com as mãos? Grave sem falta em vídeo esta imitação doce e guarde-a no seu álbum de recordações.', title_sv = 'Kom-hit-laget 👏', body_sv = 'Har barnet lärt sig att vinka kom hit med händerna? Filma absolut den här söta härmningen och lägg den i ert minnesalbum.', title_vi = 'Đội "lại đây" 👏', body_vi = 'Bé đã học được cách vẫy tay gọi "lại đây"? Nhất định hãy quay video động tác bắt chước đáng yêu này và lưu vào album kỷ niệm.', title_zh = '“过来过来”的手势 👏', body_zh = '宝宝学会用手比划“过来过来”了？一定要把这个可爱的模仿拍成视频，放进你的回忆相册！' WHERE id = 'fab0e5e3-a0d0-40d0-843b-ff548b4b816f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Las charlas se llenan de color! 🗣', body_es = '️ Para que sus tiernos diálogos de ma-ma y ba-ba sean también didácticos, lee los consejos sobre desarrollo del habla del Blog.', title_fr = 'Les conversations s''animent ! 🗣', body_fr = '️Pour rendre éducatifs ses adorables dialogues en « ma-ma » et « ba-ba », lisez les conseils sur le développement du langage dans les Blogs.', title_hi = 'बातें रंगीन हो रही हैं! 🗣', body_hi = '️मा-मा, बा-बा अक्षरों वाली उसकी प्यारी बातचीत को सीख भरा बनाने के लिए ब्लॉग में बोलने के विकास की सलाह पढ़िए।', title_id = 'Obrolan makin berwarna! 🗣', body_id = '️ ️ Untuk menjadikan obrolan manisnya dengan suku kata "ma-ma" dan "ba-ba" lebih mendidik, baca tips perkembangan bicara di Blog.', title_ja = 'おしゃべりがにぎやかに！🗣', body_ja = '️ 「まーま」「ばーば」で交わすかわいい会話を学びの時間にするために、ブログの言葉の発達のアドバイスを読んでみましょう。', title_ko = '대화가 다채로워져요! 🗣', body_ko = '️ 마-마, 바-바로 나누는 귀여운 대화를 배움의 시간으로 만들려면 블로그의 언어 발달 팁을 읽어 보세요.', title_nl = 'De gesprekjes worden kleurrijker! 🗣', body_nl = '️ Lees de tips over spraakontwikkeling in de Blogs om de lieve gesprekjes met ma-ma en ba-ba nog leerzamer te maken.', title_pl = 'Rozmowy są coraz barwniejsze! 🗣', body_pl = '️ Aby słodkie dialogi z sylabami ma-ma, ba-ba były też nauką, przeczytaj porady o rozwoju mowy na Blogu.', title_pt = 'As conversas estão mais animadas! 🗣', body_pt = '️ Para tornar educativos os diálogos doces com ma-ma e ba-ba, leia os conselhos sobre o desenvolvimento da fala nos Blogues.', title_sv = 'Samtalen blir allt rikare! 🗣', body_sv = '️ Läs tipsen om talutveckling i Bloggar för att göra de söta dialogerna med ma-ma och ba-ba lärorika.', title_vi = 'Những cuộc trò chuyện thêm sinh động! 🗣', body_vi = '️ Để những cuộc trò chuyện "ma-ma", "ba-ba" đáng yêu trở nên bổ ích, hãy đọc các lời khuyên về phát triển ngôn ngữ trong mục Blog.', title_zh = '对话越来越丰富了！🗣', body_zh = '️ 想让那些“ma-ma”“ba-ba”的甜蜜对话更有教育意义，就去博客读读语言发育的建议吧。' WHERE id = '0b91a5b0-1518-4473-b0bb-59cec89d7f6f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Prueba hoy las sopas que ayudan a aumentar la leche de la sección Recetas saludables para mujeres y recupera fuerzas.', body_fr = 'Essayez aujourd''hui les soupes favorisant la lactation de la rubrique Recettes saines pour les femmes et reprenez des forces.', body_hi = 'महिलाओं के लिए सेहतमंद रेसिपी सेक्शन के दूध बढ़ाने वाले सूप आज आज़माइए और खुद को ताकत दीजिए।', body_id = 'Coba sup pelancar ASI di bagian Resep Sehat untuk Perempuan hari ini dan kuatkan diri Anda.', body_ja = '「女性のためのヘルシーレシピ」の母乳によいスープを今日試して、体力をつけましょう。', body_ko = '여성을 위한 건강한 레시피 섹션에서 젖 분비를 돕는 수프를 오늘 시도해 보고 힘을 내세요.', body_nl = 'Probeer vandaag de soepen die de melkproductie bevorderen in het onderdeel Gezonde recepten voor vrouwen en geef jezelf een boost.', body_pl = 'Wypróbuj dziś zupy wspierające laktację z sekcji Zdrowe przepisy dla kobiet i nabierz sił.', body_pt = 'Experimente hoje as sopas que ajudam a produzir leite da secção Receitas Saudáveis para Mulheres e ganhe forças.', body_sv = 'Prova de mjölkökande sopporna i avsnittet Hälsosamma recept för kvinnor i dag och stärk dig själv.', body_vi = 'Hôm nay hãy thử các món súp lợi sữa trong mục Công thức lành mạnh cho phụ nữ và tiếp thêm sức cho mình.', body_zh = '今天试试女性健康食谱板块里的催奶汤，给自己补补力气吧。' WHERE id = 'ccbd5c11-509e-4b73-9eb1-b2f8b729e5b5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las crisis de llanto sin causa aparente agotan a cualquiera. 😭', body_es = 'No te desgastes: usa el Análisis del llanto y descubre el origen del problema.', title_fr = 'Les crises de pleurs sans cause apparente épuisent. 😭', body_fr = 'Ne vous fatiguez pas : utilisez l''Analyse des pleurs et découvrez la source du problème.', title_hi = 'जिन रोने के दौरों की वजह न मिले, वे थका देते हैं 😭', body_hi = 'खुद को मत थकाइए, क्राइंग एनालिसिस का इस्तेमाल कीजिए और परेशानी की जड़ जानिए।', title_id = 'Tangisan yang tak diketahui sebabnya sungguh melelahkan. 😭', body_id = 'Jangan memaksakan diri, gunakan Analisis Tangisan dan cari tahu akar masalahnya.', title_ja = '理由のわからない泣きは本当に疲れます。😭', body_ja = '無理をしないで、「泣き声分析」を使って原因を知りましょう。', title_ko = '이유를 알 수 없는 울음은 정말 지치게 해요. 😭', body_ko = '혼자 애쓰지 말고 울음 분석으로 문제의 원인을 알아보세요.', title_nl = 'Huilbuien zonder duidelijke oorzaak putten je uit. 😭', body_nl = 'Maak jezelf niet moe, gebruik Huilanalyse en ontdek de oorzaak.', title_pl = 'Ataki płaczu bez znanej przyczyny wykańczają. 😭', body_pl = 'Nie męcz się, skorzystaj z Analizy płaczu i poznaj źródło problemu.', title_pt = 'As crises de choro sem causa aparente esgotam qualquer um. 😭', body_pt = 'Não se canse: use a Análise do Choro e descubra a raiz do problema.', title_sv = 'Gråtutbrott utan synbar orsak tar på krafterna. 😭', body_sv = 'Slit inte ut dig, använd Gråtanalys och ta reda på grundorsaken.', title_vi = 'Những cơn khóc không rõ lý do khiến mẹ kiệt sức. 😭', body_vi = 'Đừng tự làm mình mệt, hãy dùng Phân tích tiếng khóc và tìm ra gốc rễ vấn đề.', title_zh = '找不到原因的哭闹最让人心力交瘁 😭', body_zh = '别累坏自己，用哭声分析找出问题的根源吧。' WHERE id = 'db929314-83ca-4372-8890-03ef676e68e5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Si esta noche tu bebé está alterado, pon el sonido del útero materno en Ruido blanco y cálmale al instante.', body_fr = 'Si votre bébé est trop excité ce soir, lancez le son du ventre maternel dans les Bruits blancs pour l''apaiser instantanément.', body_hi = 'अगर आज शाम बच्चा उत्साहित है, तो व्हाइट नॉइज़ में गर्भ की आवाज़ चलाकर उसे तुरंत शांत कीजिए।', body_id = 'Jika malam ini si kecil terlalu bersemangat, putar suara rahim dari White Noise untuk langsung menenangkannya.', body_ja = '今夜赤ちゃんが興奮しているなら、「ホワイトノイズ」から胎内の音を流して、すぐに落ち着かせてあげましょう。', body_ko = '오늘 밤 아기가 흥분해 있다면 백색소음에서 엄마 배 속 소리를 틀어 바로 진정시켜 주세요.', body_nl = 'Is je baby vanavond opgewonden? Zet in Witte ruis het baarmoedergeluid aan en kalmeer hem meteen.', body_pl = 'Jeśli maluszek jest dziś wieczorem podekscytowany, włącz w Białym szumie odgłosy z brzucha mamy i od razu go uspokój.', body_pt = 'Se esta noite o bebé está agitado, ponha no Ruído Branco o som do ventre materno e acalme-o no momento.', body_sv = 'Om barnet är uppspelt i kväll, lugna det direkt genom att sätta på ljudet från livmodern i Vitt brus.', body_vi = 'Nếu tối nay bé háo hức khó ngủ, hãy bật âm thanh trong bụng mẹ từ mục Tiếng ồn trắng để dỗ bé yên ngay.', body_zh = '如果宝宝今晚太兴奋，就在白噪音里播放妈妈子宫里的声音，让宝宝马上安静下来吧。' WHERE id = '72b7b721-7f37-4054-90fd-05ac29f9ff3c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirse con un cuento 🪄', body_es = 'Crea en Cuentos inteligentes la historia de unos animales valientes y adorables y convierte la habitación en un lugar mágico.', title_fr = 'S''endormir avec un conte 🪄', body_fr = 'Dans les Contes intelligents, créez l''histoire d''animaux courageux et adorables et transformez la chambre en un lieu magique.', title_hi = 'कहानी के साथ नींद 🪄', body_hi = 'स्मार्ट कहानियों में बहादुर और प्यारे जानवरों की कहानी बनाइए और कमरे को एक जादुई जगह में बदल दीजिए।', title_id = 'Tertidur bersama dongeng 🪄', body_id = 'Di Dongeng Pintar, buat kisah hewan-hewan yang berani dan menggemaskan, dan ubah kamar menjadi tempat yang ajaib.', title_ja = 'お話でねんね 🪄', body_ja = '「スマートおはなし」で、勇敢でかわいい動物たちのお話をつくって、部屋を魔法の場所に変えましょう。', title_ko = '동화와 함께 꿈나라로 🪄', body_ko = '스마트 동화에서 용감하고 사랑스러운 동물 이야기를 만들어 방을 마법의 공간으로 바꿔 보세요.', title_nl = 'Met een sprookje in slaap 🪄', body_nl = 'Maak in Slimme sprookjes het verhaal van dappere, lieve dieren en verander de kamer in een magische plek.', title_pl = 'Zasypianie z bajką 🪄', body_pl = 'Stwórz w Mądrych bajkach historię o odważnych i uroczych zwierzątkach i zamień pokój w magiczne miejsce.', title_pt = 'Adormecer com uma história 🪄', body_pt = 'Crie nas Histórias Inteligentes histórias de animais corajosos e adoráveis e transforme o quarto num lugar mágico.', title_sv = 'Somnar till en saga 🪄', body_sv = 'Skapa sagan om modiga och gulliga djur i Smarta sagor och förvandla rummet till en magisk plats.', title_vi = 'Vào giấc cùng truyện cổ tích 🪄', body_vi = 'Hãy tạo câu chuyện về những con vật dũng cảm, đáng yêu trong Truyện cổ tích thông minh và biến căn phòng thành một nơi kỳ diệu.', title_zh = '听着故事入睡 🪄', body_zh = '在智能故事里创作勇敢又可爱的动物的故事，把房间变成一个神奇的地方吧。' WHERE id = 'b335cc4c-9dc2-482d-a2f2-b6bcbf3a72f9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que el tiempo no te engañe ⛅', body_es = 'Al salir de paseo, no decidas mirando por la ventana. Con la herramienta Tiempo y ropa encuentra el término medio perfecto para las capas de ropa.', title_fr = 'Ne vous fiez pas au temps ⛅', body_fr = 'Avant de sortir, ne décidez pas en regardant par la fenêtre. Avec l''outil Météo et tenue, trouvez le juste milieu pour l''habiller en plusieurs couches.', title_hi = 'मौसम के धोखे में मत आइए ⛅', body_hi = 'सैर पर निकलने से पहले खिड़की से देखकर फ़ैसला मत कीजिए। मौसम और कपड़े टूल से परतों में कपड़े पहनाने का सही संतुलन जानिए।', title_id = 'Jangan tertipu cuaca ⛅', body_id = 'Saat akan jalan-jalan, jangan putuskan hanya dengan melihat dari jendela. Temukan jumlah lapisan pakaian yang pas dengan fitur Cuaca dan Pakaian.', title_ja = '天気にだまされないで ⛅', body_ja = 'お散歩に行くとき、窓の外を見て決めないで。「天気と服装」ツールで、ちょうどいい重ね着を見つけましょう。', title_ko = '날씨에 속지 마세요 ⛅', body_ko = '산책 나갈 때 창밖만 보고 정하지 마세요. 날씨와 옷차림 도구로 겹쳐 입히기의 딱 알맞은 정도를 찾아보세요.', title_nl = 'Laat je niet misleiden door het weer ⛅', body_nl = 'Beslis voor een wandeling niet door uit het raam te kijken. Vind met de tool Weer en kleding het gouden midden voor het aantal laagjes.', title_pl = 'Nie daj się zwieść pogodzie ⛅', body_pl = 'Wychodząc na spacer, nie decyduj, patrząc przez okno. Z narzędziem Pogoda i ubiór znajdziesz złoty środek w ubieraniu na cebulkę.', title_pt = 'Não se deixe enganar pelo tempo ⛅', body_pt = 'Ao sair para passear, não decida só por olhar pela janela. Com a ferramenta Tempo e Roupa, encontre o meio-termo ideal nas camadas de roupa.', title_sv = 'Låt dig inte luras av vädret ⛅', body_sv = 'Bestäm inte genom att titta ut genom fönstret innan promenaden. Hitta den gyllene medelvägen för antalet lager med Väder och kläder.', title_vi = 'Đừng để thời tiết đánh lừa ⛅', body_vi = 'Khi đi dạo, đừng chỉ nhìn qua cửa sổ mà quyết định. Hãy dùng công cụ Thời tiết và trang phục để tìm cách mặc nhiều lớp vừa phải nhất.', title_zh = '别被天气骗了 ⛅', body_zh = '出门散步前别只看窗外就做决定。用天气穿衣工具，找到穿几层衣服的最佳平衡。' WHERE id = '36d1de0a-5eb5-4e0f-98ce-a583a10b254e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El silencio de la noche 🤫', body_es = 'Si le molestan los coches o los ruidos de fuera, mantén siempre de fondo una fuente constante de ruido blanco.', title_fr = 'Le silence de la nuit 🤫', body_fr = 'Si les bruits de voitures ou de l''extérieur le dérangent, gardez absolument une source de bruit blanc continu en fond.', title_hi = 'रात की खामोशी 🤫', body_hi = 'अगर गाड़ियों या बाहर की आवाज़ें उसे परेशान करती हैं, तो पीछे लगातार चलने वाला व्हाइट नॉइज़ ज़रूर रखिए।', title_id = 'Keheningan malam 🤫', body_id = 'Jika suara mobil atau suara dari luar mengganggunya, pastikan ada sumber white noise yang terus menyala di latar belakang.', title_ja = '夜の静けさ 🤫', body_ja = '車や外の音が気になるようなら、ホワイトノイズを途切れずに流しておきましょう。', title_ko = '밤의 고요 🤫', body_ko = '자동차나 바깥 소리가 아기를 방해한다면 배경에 일정한 백색소음을 꼭 틀어 두세요.', title_nl = 'De stilte van de nacht 🤫', body_nl = 'Hebben auto''s of andere geluiden van buiten last van hem? Laat dan zeker een constante bron van witte ruis op de achtergrond aanstaan.', title_pl = 'Nocna cisza 🤫', body_pl = 'Jeśli przeszkadzają mu samochody lub hałas z zewnątrz, koniecznie miej w tle stałe źródło białego szumu.', title_pt = 'O silêncio da noite 🤫', body_pt = 'Se os carros ou os barulhos de fora o incomodam, mantenha sempre uma fonte constante de ruído branco em fundo.', title_sv = 'Nattens tystnad 🤫', body_sv = 'Om bilar eller ljud utifrån stör barnet, ha alltid en jämn källa till vitt brus i bakgrunden.', title_vi = 'Sự tĩnh lặng của màn đêm 🤫', body_vi = 'Nếu tiếng xe cộ hay tiếng ồn bên ngoài làm bé khó chịu, nhất định hãy duy trì một nguồn tiếng ồn trắng liên tục làm nền.', title_zh = '夜晚的宁静 🤫', body_zh = '如果汽车声或外面的声音打扰到宝宝，一定要在背景里放着持续的白噪音。' WHERE id = '14c6187e-df8b-47e8-b44f-9bc87c4b9143' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reserva de hierro 🥩', title_fr = 'Réserve de fer 🥩', title_hi = 'आयरन का भंडार 🥩', title_id = 'Cadangan zat besi 🥩', title_ja = '鉄分の蓄え 🥩', title_ko = '철분 충전 🥩', title_nl = 'De ijzervoorraad 🥩', title_pl = 'Zapas żelaza 🥩', title_pt = 'Reserva de ferro 🥩', title_sv = 'Järnförrådet 🥩', title_vi = 'Kho dự trữ sắt 🥩', title_zh = '补铁 🥩' WHERE id = '5b72c8ce-753e-4283-9bd2-18995d662a91' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Aprender cayendo y levantándose 🧗‍♂️', body_es = '¿Mientras camina agarrado al sofá se cae de culete y vuelve a levantarse? Está aprendiendo a esforzarse. Anímale sin alarmarte.', title_fr = 'Apprendre en tombant et en se relevant 🧗‍♂️', body_fr = 'En longeant le canapé, il tombe sur les fesses et se relève ? Il apprend à persévérer. Encouragez-le sans vous inquiéter.', title_hi = 'गिरकर उठना सीखना 🧗‍♂️', body_hi = 'सोफ़ा पकड़कर चलते हुए धम से बैठ जाता है और फिर उठता है? वह हार न मानना सीख रहा है। घबराए बिना उसका हौसला बढ़ाइए।', title_id = 'Belajar dari jatuh bangun 🧗‍♂️', body_id = 'Saat berjalan berpegangan pada sofa, ia jatuh terduduk lalu bangkit lagi? Ia sedang belajar pantang menyerah. Jangan panik, beri ia semangat.', title_ja = '転んで起きて学ぶ 🧗‍♂️', body_ja = 'ソファにつかまって歩いていて、しりもちをついてもまた立ち上がりますか？がんばることを学んでいます。あわてずに励ましてあげましょう。', title_ko = '넘어지고 일어서며 배워요 🧗‍♂️', body_ko = '소파를 잡고 걷다가 엉덩방아를 찧고 다시 일어나나요? 포기하지 않는 법을 배우는 중이에요. 놀라지 말고 용기를 북돋아 주세요.', title_nl = 'Leren met vallen en opstaan 🧗‍♂️', body_nl = 'Valt je baby op zijn billen als hij langs de bank loopt en staat hij weer op? Hij leert doorzetten. Raak niet in paniek en moedig hem aan.', title_pl = 'Nauka przez upadki 🧗‍♂️', body_pl = 'Chodząc przy kanapie, ląduje na pupie i znów wstaje? Uczy się wytrwałości. Bez paniki dodawaj mu odwagi.', title_pt = 'Aprender a cair e a levantar 🧗‍♂️', body_pt = 'Ao andar agarrado ao sofá, cai de rabo e volta a levantar-se? Está a aprender a persistir. Encoraje-o sem se alarmar.', title_sv = 'Lära sig genom att ramla och resa sig 🧗‍♂️', body_sv = 'Ramlar barnet på rumpan när det går längs soffan och reser sig igen? Det lär sig att kämpa. Uppmuntra det utan att oroa dig.', title_vi = 'Ngã rồi đứng dậy 🧗‍♂️', body_vi = 'Bé men theo sofa, ngã phịch xuống mông rồi lại đứng lên? Bé đang học cách kiên trì. Đừng hoảng, hãy khích lệ bé.', title_zh = '摔倒了再爬起来 🧗‍♂️', body_zh = '扶着沙发走时一屁股坐下，又重新站起来？宝宝在学习坚持。别紧张，鼓励宝宝吧。' WHERE id = '36c8e54c-04ef-4b47-9a2f-c0754b0990c9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las molestias de la dentición 🦷', body_es = '¿Vuelve a tener las encías rojas y no para de babear? Prepara los mordedores fríos.', title_fr = 'Les douleurs dentaires 🦷', body_fr = 'Ses gencives sont de nouveau rouges et il bave sans arrêt ? Préparez les anneaux de dentition rafraîchis.', title_hi = 'दाँत निकलने का दर्द 🦷', body_hi = 'मसूड़े फिर से लाल हैं और लार रुक नहीं रही? ठंडे टीदर तैयार रखिए।', title_id = 'Nyeri tumbuh gigi 🦷', body_id = 'Gusinya memerah lagi dan air liurnya tak berhenti? Siapkan teether yang dingin.', title_ja = '歯が生えるときの痛み 🦷', body_ja = 'また歯ぐきが赤くなって、よだれが止まらない？冷たい歯固めを用意しましょう。', title_ko = '이앓이 통증 🦷', body_ko = '잇몸이 다시 빨개지고 침이 멈추지 않나요? 차가운 치발기를 준비하세요.', title_nl = 'Pijn door doorkomende tandjes 🦷', body_nl = 'Is het tandvlees weer rood en stopt het kwijlen niet? Leg de koude bijtringen klaar.', title_pl = 'Bóle ząbkowania 🦷', body_pl = 'Dziąsła znów są zaczerwienione, a ślinka ciągle leci? Przygotuj schłodzone gryzaki.', title_pt = 'Dores dos dentes 🦷', body_pt = 'As gengivas voltaram a ficar vermelhas e a baba não para? Prepare os mordedores frescos.', title_sv = 'Tandsmärtor 🦷', body_sv = 'Är gommen röd igen och slutar dreglet aldrig? Ta fram de kalla bitringarna.', title_vi = 'Cơn đau mọc răng 🦷', body_vi = 'Nướu bé lại đỏ và nước dãi chảy không ngừng? Hãy chuẩn bị gặm nướu mát nhé.', title_zh = '出牙疼 🦷', body_zh = '牙龈又红了，口水流个不停？准备好冰凉的牙胶吧。' WHERE id = 'c0c6e209-b8c8-4325-bc8e-9d4231949abd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quiere lo que tú comes 🥣', body_es = '¿Intenta coger todo lo que hay en tu plato? Su interés por la comida está en lo más alto. Dale trocitos pequeños que pueda comer él solo con los dedos.', title_fr = 'Ce que vous mangez, il le veut aussi 🥣', body_fr = 'Il tend la main vers tout ce qu''il y a dans votre assiette ? Son intérêt pour la nourriture est au maximum. Donnez-lui de petits morceaux qu''il peut manger seul avec les doigts.', title_hi = 'आप जो खाएँ, वही उसे भी चाहिए 🥣', body_hi = 'आपकी प्लेट की हर चीज़ की ओर हाथ बढ़ाता है? खाने में उसकी दिलचस्पी चरम पर है। उसे ऐसे छोटे फ़िंगर फ़ूड दीजिए जो वह खुद खा सके।', title_id = 'Apa yang Anda makan, ia juga mau 🥣', body_id = 'Ia meraih semua yang ada di piring Anda? Minatnya pada makanan sedang memuncak. Beri ia finger food kecil yang bisa ia makan sendiri.', title_ja = 'ママが食べているものが気になる 🥣', body_ja = 'あなたのお皿のものにぜんぶ手を伸ばしますか？食べることへの興味が最高潮です。自分で食べられる小さな手づかみ食べのメニューをあげましょう。', title_ko = '엄마가 먹는 건 나도 먹고 싶어요 🥣', body_ko = '엄마 접시 위의 모든 것에 손을 뻗나요? 먹는 것에 대한 관심이 최고조예요. 혼자 먹을 수 있는 작은 핑거 푸드를 주세요.', title_nl = 'Wat jij eet, wil hij ook 🥣', body_nl = 'Grijpt je baby naar alles op jouw bord? Zijn interesse in eten is op zijn hoogtepunt. Geef hem kleine stukjes vingervoedsel die hij zelf kan eten.', title_pl = 'Chce tego, co ty jesz 🥣', body_pl = 'Sięga po wszystko z twojego talerza? Zainteresowanie jedzeniem jest u szczytu. Dawaj mu małe kawałki do samodzielnego jedzenia rączkami.', title_pt = 'Quer o que a mãe come 🥣', body_pt = 'Estica a mão para tudo o que está no seu prato? O interesse pela comida está no auge. Dê-lhe pequenos alimentos que possa comer sozinho com os dedos.', title_sv = 'Det du äter vill barnet också ha 🥣', body_sv = 'Sträcker sig barnet efter allt på din tallrik? Intresset för mat är på topp. Ge barnet små bitar fingermat som det kan äta själv.', title_vi = 'Mẹ ăn gì, bé cũng muốn 🥣', body_vi = 'Bé với tay lấy mọi thứ trên đĩa của mẹ? Sự hứng thú với đồ ăn đang ở đỉnh điểm. Hãy cho bé những miếng đồ ăn cầm tay nhỏ để bé tự ăn.', title_zh = '你吃什么，宝宝也想要 🥣', body_zh = '宝宝伸手去抓你盘子里的所有东西？对食物的兴趣正处在高峰。给宝宝一些能自己吃的小块手指食物吧。' WHERE id = '65f53c0c-e8ea-4257-8798-e79b9ed847be' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Diario emocional 📝', body_es = 'Cuando te sientas sola, vuelca tus emociones en el Diario de ánimo. Escribir te sentará bien.', title_fr = 'Un journal des émotions 📝', body_fr = 'Quand vous vous sentez seule, déversez vos émotions dans le Journal d''humeur. Écrire vous fera du bien.', title_hi = 'भावनाओं की डायरी 📝', body_hi = 'जब अकेली महसूस करें, तो अपनी भावनाएँ मूड डायरी में उड़ेल दीजिए। लिखना आपके लिए अच्छा रहेगा।', title_id = 'Buku harian perasaan 📝', body_id = 'Saat merasa sendirian, tuangkan perasaan Anda di Buku Harian Suasana Hati. Menulis akan membuat Anda lebih lega.', title_ja = '気持ちの日記 📝', body_ja = 'ひとりぼっちだと感じたら、「気分日記」に気持ちを吐き出しましょう。書くと心が楽になります。', title_ko = '마음 일기 📝', body_ko = '외로울 때는 기분 일기에 감정을 쏟아 내세요. 글로 쓰면 한결 나아질 거예요.', title_nl = 'Een gevoelsdagboek 📝', body_nl = 'Voel je je alleen? Laat je gevoelens de vrije loop in je Stemmingsdagboek. Schrijven doet je goed.', title_pl = 'Dziennik emocji 📝', body_pl = 'Gdy czujesz się samotna, przelej swoje uczucia do Dziennika nastroju. Pisanie dobrze ci zrobi.', title_pt = 'Diário emocional 📝', body_pt = 'Quando se sentir sozinha, despeje o que sente no Diário de Humor. Escrever vai fazer-lhe bem.', title_sv = 'Känslodagbok 📝', body_sv = 'När du känner dig ensam, häll ut dina känslor i Humördagboken. Att skriva gör dig gott.', title_vi = 'Nhật ký cảm xúc 📝', body_vi = 'Khi thấy cô đơn, hãy trút cảm xúc vào Nhật ký tâm trạng. Viết ra sẽ giúp mẹ dễ chịu hơn.', title_zh = '情绪日记 📝', body_zh = '觉得孤单时，就把感受倾诉在心情日记里。写下来会让你好受些。' WHERE id = 'bbfc7848-e7f7-4bfa-a960-a2aeb003f7a4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisión del desarrollo 🤖', body_es = '¿Tienes dudas sobre la alimentación complementaria? Pide a Anacan AI información sobre el menú de un bebé de 9 meses.', title_fr = 'Bilan de développement 🤖', body_fr = 'Des questions sur la diversification vous trottent dans la tête ? Demandez à Anacan AI des informations sur le menu d''un bébé de 9 mois.', title_hi = 'विकास की जाँच 🤖', body_hi = 'ऊपरी आहार को लेकर मन में सवाल हैं? Anacan AI से 9 महीने के बच्चे के मेन्यू के बारे में जानकारी माँगिए।', title_id = 'Cek perkembangan 🤖', body_id = 'Ada pertanyaan soal MPASI di kepala Anda? Minta informasi tentang menu bayi 9 bulan dari Anacan AI.', title_ja = '発達チェック 🤖', body_ja = '離乳食について疑問がありますか？Anacan AIに生後9か月の赤ちゃんの献立について聞いてみましょう。', title_ko = '발달 체크 🤖', body_ko = '이유식에 대한 질문이 머릿속에 가득한가요? Anacan AI에게 9개월 아기 식단에 대한 정보를 요청해 보세요.', title_nl = 'Ontwikkelingscheck 🤖', body_nl = 'Zit je hoofd vol met vragen over bijvoeding? Vraag Anacan AI om informatie over het menu voor een baby van 9 maanden.', title_pl = 'Kontrola rozwoju 🤖', body_pl = 'Masz w głowie pytania o rozszerzanie diety? Poproś Anacan AI o informacje na temat jadłospisu 9-miesięcznego maluszka.', title_pt = 'Verificação do desenvolvimento 🤖', body_pt = 'Tem perguntas na cabeça sobre a diversificação alimentar? Peça ao Anacan AI informação sobre a ementa de um bebé de 9 meses.', title_sv = 'Utvecklingskoll 🤖', body_sv = 'Har du frågor om smakportioner som snurrar i huvudet? Be Anacan AI om information om en meny för 9 månader gamla barn.', title_vi = 'Kiểm tra sự phát triển 🤖', body_vi = 'Mẹ có thắc mắc về ăn dặm? Hãy hỏi Anacan AI về thực đơn cho bé 9 tháng.', title_zh = '发育检查 🤖', body_zh = '关于辅食，脑子里有很多问题？向Anacan AI要一份9个月宝宝的食谱参考吧。' WHERE id = 'd2c3bcc6-5492-42b4-857f-d6ad8a442199' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora de Cuentos inteligentes 🪄', body_es = 'Que esta noche haya otra historia: La nube mágica a la que le encanta dormir. Baja el tono de voz y crea el ambiente.', title_fr = 'L''heure des Contes intelligents 🪄', body_fr = 'Ce soir, une histoire différente : « Le nuage magique qui adore s''endormir ». Baissez le ton de votre voix et créez l''ambiance.', title_hi = 'स्मार्ट कहानी का समय 🪄', body_hi = 'आज शाम एक अलग कहानी हो: ''सोना पसंद करने वाला जादुई बादल''। अपनी आवाज़ धीमी कीजिए और माहौल बनाइए।', title_id = 'Waktunya Dongeng Pintar 🪄', body_id = 'Malam ini, kisah yang berbeda: Awan ajaib yang suka tidur. Pelankan suara Anda dan bangun suasananya.', title_ja = '「スマートおはなし」の時間 🪄', body_ja = '今夜はいつもと違うお話を：「ねんねが大好きな魔法の雲」。声のトーンを落として、雰囲気をつくりましょう。', title_ko = '스마트 동화 시간 🪄', body_ko = '오늘 저녁은 색다른 이야기로 해 봐요: 잠자는 걸 좋아하는 마법 구름. 목소리를 낮추고 분위기를 만들어 주세요.', title_nl = 'Tijd voor Slimme sprookjes 🪄', body_nl = 'Een ander verhaal vanavond: een magisch wolkje dat graag gaat slapen. Praat zachter en zorg voor de juiste sfeer.', title_pl = 'Czas na Mądre bajki 🪄', body_pl = 'Niech dziś wieczorem będzie inna historia: Magiczna chmurka, która lubi zasypiać. Ścisz głos i zbuduj atmosferę.', title_pt = 'Hora das Histórias Inteligentes 🪄', body_pt = 'Esta noite, uma história diferente: a nuvem mágica que adora adormecer. Baixe o tom de voz e crie o ambiente.', title_sv = 'Smart sagostund 🪄', body_sv = 'Låt det bli en annorlunda saga i kväll: Det magiska molnet som älskar att somna. Sänk rösten och skapa stämningen.', title_vi = 'Giờ cổ tích thông minh 🪄', body_vi = 'Tối nay hãy kể một câu chuyện khác: "Đám mây kỳ diệu thích đi ngủ". Hạ giọng xuống và tạo bầu không khí êm dịu.', title_zh = '智能故事时间 🪄', body_zh = '今晚换个故事吧：《爱睡觉的神奇云朵》。压低你的声音，营造好氛围。' WHERE id = '69d7aa9d-fa7f-4594-a0de-a2ff1fbdebb6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Intenta guardar las cosas en su sitio 🧸', body_es = '¿Mete el juguete en la caja y lo vuelve a sacar? Está descubriendo los conceptos de «dentro» y «fuera».', title_fr = 'Il essaie de ranger les objets 🧸', body_fr = 'Il met un jouet dans la boîte puis le ressort ? Il découvre les notions de « dedans » et « dehors ».', title_hi = 'चीज़ें वापस जगह पर रखने की कोशिश 🧸', body_hi = 'खिलौना डिब्बे में डालकर फिर निकालता है? वह ''अंदर'' और ''बाहर'' की समझ खोज रहा है।', title_id = 'Mencoba mengembalikan barang ke tempatnya 🧸', body_id = 'Ia memasukkan mainan ke kotak lalu mengeluarkannya lagi? Ia sedang mempelajari konsep "di dalam" dan "di luar".', title_ja = 'ものを元の場所に戻そうとする 🧸', body_ja = 'おもちゃを箱に入れて、また出していますか？「中」と「外」の考え方を発見しています。', title_ko = '물건을 제자리에 넣어 보기 🧸', body_ko = '장난감을 상자에 넣었다가 다시 꺼내나요? ''안''과 ''밖''의 개념을 발견하는 중이에요.', title_nl = 'Pogingen om dingen op te ruimen 🧸', body_nl = 'Gooit je baby een speeltje in de doos en haalt hij het er weer uit? Hij ontdekt het begrip in en uit.', title_pl = 'Próby odkładania rzeczy na miejsce 🧸', body_pl = 'Wrzuca zabawkę do pudełka i znów ją wyjmuje? Odkrywa pojęcia „w środku” i „na zewnątrz”.', title_pt = 'Tentativas de arrumar as coisas no lugar 🧸', body_pt = 'Põe o brinquedo na caixa e volta a tirá-lo? Está a descobrir as noções de dentro e fora.', title_sv = 'Försök att lägga saker på plats 🧸', body_sv = 'Lägger barnet leksaken i lådan och plockar ut den igen? Det upptäcker begreppen i och ur.', title_vi = 'Tập cất đồ về chỗ cũ 🧸', body_vi = 'Bé bỏ đồ chơi vào hộp rồi lại lấy ra? Bé đang khám phá khái niệm "bên trong" và "bên ngoài".', title_zh = '尝试把东西放回原处 🧸', body_zh = '宝宝把玩具放进盒子再拿出来？宝宝在探索“里面”和“外面”的概念。' WHERE id = 'ae31e811-95f5-438c-9d8f-7b39b14eed84' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tormenta nocturna 😭', title_fr = 'La tempête de la nuit 😭', title_hi = 'रात का तूफ़ान 😭', title_id = 'Badai di malam hari 😭', title_ja = '夜の嵐 😭', title_ko = '한밤의 폭풍 😭', title_nl = 'Storm in de nacht 😭', title_pl = 'Nocna burza 😭', title_pt = 'A tempestade da noite 😭', title_sv = 'Nattens storm 😭', title_vi = 'Cơn bão ban đêm 😭', title_zh = '夜里的风暴 😭' WHERE id = '541b84ef-a3ed-43ff-8a33-aa153668c840' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Creamos el hábito de beber agua. 💧', body_es = 'No olvides ofrecerle agua junto con la alimentación complementaria. Descubre fácilmente en Productos recomendados qué vasos de aprendizaje son más adecuados.', title_fr = 'On prend l''habitude de boire de l''eau. 💧', body_fr = 'N''oubliez pas de lui proposer de l''eau avec les repas solides. Trouvez facilement les tasses d''apprentissage les mieux adaptées dans les Produits recommandés.', title_hi = 'पानी पीने की आदत डाल रहे हैं 💧', body_hi = 'ऊपरी आहार के साथ पानी देना मत भूलिए। कौन से सिप्पी कप ज़्यादा सही हैं, सुझाए गए प्रोडक्ट में आसानी से देखिए।', title_id = 'Membangun kebiasaan minum air. 💧', body_id = 'Jangan lupa menawarkan air bersamaan dengan MPASI. Temukan dengan mudah botol minum yang paling cocok di Produk Rekomendasi.', title_ja = 'お水を飲む習慣をつけよう。💧', body_ja = '離乳食と一緒にお水をあげるのを忘れずに。どのストローマグが合うかは「おすすめ商品」でかんたんに見つけられます。', title_ko = '물 마시는 습관 만들기 💧', body_ko = '이유식과 함께 물을 주는 것도 잊지 마세요. 어떤 빨대컵이 알맞은지 추천 제품에서 쉽게 찾아보세요.', title_nl = 'We leren water drinken. 💧', body_nl = 'Vergeet niet om naast de bijvoeding ook water aan te bieden. Vind in Aanbevolen producten makkelijk welke drinkbekers het best passen.', title_pl = 'Uczymy się pić wodę. 💧', body_pl = 'Nie zapominaj podawać wody razem ze stałymi pokarmami. Jakie kubki niekapki są najlepsze, łatwo sprawdzisz w Polecanych produktach.', title_pt = 'Estamos a criar o hábito de beber água. 💧', body_pt = 'Não se esqueça de oferecer água juntamente com a comida. Descubra facilmente nos Produtos Recomendados os copos de aprendizagem mais adequados.', title_sv = 'Vi skapar en vana att dricka vatten. 💧', body_sv = 'Glöm inte att erbjuda vatten tillsammans med smakportionerna. Hitta enkelt vilka pipmuggar som passar bäst i Rekommenderade produkter.', title_vi = 'Tập thói quen uống nước. 💧', body_vi = 'Đừng quên cho bé uống nước cùng với bữa ăn dặm. Dễ dàng tìm loại cốc tập uống phù hợp nhất trong Sản phẩm gợi ý.', title_zh = '培养喝水的习惯 💧', body_zh = '吃辅食时别忘了给宝宝喝点水。去推荐商品里轻松找到更合适的学饮杯吧。' WHERE id = 'ed4bee35-1ea6-4f7f-ba0b-bb5c2bd4f981' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El lorito imitador 🦜', body_es = '¿Imita tu tos o tu risa? Eres el mejor espejo de la habitación. ¡Enséñale las expresiones más bonitas!', title_fr = 'Le petit perroquet imitateur 🦜', body_fr = 'Il imite votre toux et votre rire ? Vous êtes son meilleur miroir. Montrez-lui les plus belles mimiques !', title_hi = 'नकल करने वाला तोता 🦜', body_hi = 'आपके खाँसने और हँसने की नकल करता है? कमरे में सबसे अच्छा आईना आप हैं। उसे सबसे प्यारे हाव-भाव सिखाइए!', title_id = 'Si burung beo peniru 🦜', body_id = 'Ia meniru batuk dan tawa Anda? Andalah cermin terbaik di ruangan ini. Ajari ia ekspresi wajah yang paling indah!', title_ja = 'ものまねオウム 🦜', body_ja = 'あなたのせきや笑い声をまねしていますか？部屋でいちばんの鏡はあなたです。すてきな表情をたくさん見せてあげましょう！', title_ko = '따라쟁이 앵무새 🦜', body_ko = '엄마의 기침이나 웃음을 따라 하나요? 방 안에서 가장 좋은 거울은 바로 엄마예요. 가장 예쁜 표정을 보여 주세요!', title_nl = 'Een papegaaitje dat alles nadoet 🦜', body_nl = 'Doet je baby je hoesten en je lach na? Jij bent de beste spiegel in de kamer. Leer hem de mooiste gezichtsuitdrukkingen!', title_pl = 'Mała papużka naśladowczyni 🦜', body_pl = 'Naśladuje twój kaszel i śmiech? To ty jesteś dla niego najlepszym lustrem. Pokazuj mu najpiękniejsze miny!', title_pt = 'O papagaio imitador 🦜', body_pt = 'Imita a sua tosse e o seu riso? No quarto, o melhor espelho é a mãe. Ensine-lhe as expressões mais bonitas!', title_sv = 'Den härmande papegojan 🦜', body_sv = 'Härmar barnet när du hostar och skrattar? Du är den bästa spegeln i rummet. Lär barnet de finaste minerna!', title_vi = 'Chú vẹt bắt chước 🦜', body_vi = 'Bé bắt chước tiếng ho, tiếng cười của mẹ? Mẹ là tấm gương tốt nhất trong phòng. Hãy dạy bé những biểu cảm đẹp nhất!', title_zh = '学舌小鹦鹉 🦜', body_zh = '宝宝在模仿你咳嗽、大笑？你就是房间里最好的镜子。教宝宝最美的表情吧！' WHERE id = '0b7b3ea8-6539-4606-ac0b-b0428466ace0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Una bomba de energía para mamás! 🥗', body_es = '¡Correr detrás de un bebé tan activo exige energía! Prepara con las Recetas saludables para mujeres una ensalada o un smoothie lleno de vitaminas.', title_fr = 'Une bombe d''énergie pour maman ! 🥗', body_fr = 'Courir après un bébé qui bouge demande de l''énergie ! Préparez une salade ou un smoothie plein de vitamines grâce aux Recettes saines pour les femmes.', title_hi = 'माँओं के लिए ऊर्जा का खज़ाना! 🥗', body_hi = 'चुलबुले बच्चे के पीछे भागने में ताकत लगती है! महिलाओं के लिए सेहतमंद रेसिपी से विटामिन भरा सलाद या स्मूदी बनाइए।', title_id = 'Bom energi untuk Bunda! 🥗', body_id = 'Mengejar bayi yang aktif butuh tenaga! Buat salad atau smoothie kaya vitamin dari Resep Sehat untuk Perempuan.', title_ja = 'ママのための元気チャージ！🥗', body_ja = '動きまわる赤ちゃんを追いかけるには体力が必要！「女性のためのヘルシーレシピ」からビタミンたっぷりのサラダやスムージーをつくりましょう。', title_ko = '엄마를 위한 에너지 폭탄! 🥗', body_ko = '활발한 아기를 쫓아다니려면 힘이 필요해요! 여성을 위한 건강한 레시피에서 비타민 가득한 샐러드나 스무디를 만들어 보세요.', title_nl = 'Een energiebom voor mama''s! 🥗', body_nl = 'Achter een beweeglijke baby aan rennen kost kracht! Maak uit Gezonde recepten voor vrouwen een vitaminerijke salade of smoothie.', title_pl = 'Bomba energii dla mam! 🥗', body_pl = 'Bieganie za ruchliwym maluszkiem wymaga siły! Przygotuj ze Zdrowych przepisów dla kobiet witaminową sałatkę lub smoothie.', title_pt = 'Uma bomba de energia para as mães! 🥗', body_pt = 'Andar atrás de um bebé tão ativo exige forças! Prepare uma salada ou um smoothie cheio de vitaminas das Receitas Saudáveis para Mulheres.', title_sv = 'Energibomb för mammor! 🥗', body_sv = 'Att springa efter ett barn i rörelse kräver kraft! Gör en vitaminrik sallad eller smoothie från Hälsosamma recept för kvinnor.', title_vi = 'Bom năng lượng cho mẹ! 🥗', body_vi = 'Chạy theo một em bé hiếu động cần nhiều sức lực! Hãy làm một món salad hay sinh tố giàu vitamin từ Công thức lành mạnh cho phụ nữ.', title_zh = '妈妈的能量炸弹！🥗', body_zh = '追着一个好动的宝宝跑需要体力！从女性健康食谱里做一份富含维生素的沙拉或奶昔吧。' WHERE id = '380bef16-ec45-4aa3-8cc8-5ea1cf489dc2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El salón de masajes de papá 💆‍♀️', body_es = 'Que tu pareja acueste al bebé y después te dé un masaje de hombros de 5 minutos para esos músculos del cuello tan agarrotados.', title_fr = 'Le salon de massage de papa 💆‍♀️', body_fr = 'Que votre conjoint couche bébé, puis qu''il vous offre 5 minutes de massage des épaules pour vos muscles du cou tout noués !', title_hi = 'पापा का मसाज पार्लर 💆‍♀️', body_hi = 'बच्चे को आपके साथी सुलाएँ, और फिर आपकी अकड़ी हुई गर्दन की मांसपेशियों के लिए 5 मिनट की कंधे की मालिश करें!', title_id = 'Salon pijat ayah 💆‍♀️', body_id = 'Biarkan pasangan Anda yang menidurkan si kecil, lalu memberi pijatan bahu 5 menit untuk otot leher Anda yang kaku!', title_ja = 'パパのマッサージサロン 💆‍♀️', body_ja = '赤ちゃんの寝かしつけはパートナーにまかせて、そのあとは、こわばったあなたの首のために5分間肩をもんでもらいましょう！', title_ko = '아빠의 마사지 숍 💆‍♀️', body_ko = '배우자가 아이를 재우게 하고, 그다음 뭉친 목 근육을 위해 5분 어깨 마사지를 해 달라고 하세요!', title_nl = 'Papa''s massagesalon 💆‍♀️', body_nl = 'Laat je partner de baby in slaap brengen en daarna 5 minuten je stijve nek- en schouderspieren masseren!', title_pl = 'Salon masażu taty 💆‍♀️', body_pl = 'Niech partner uśpi maluszka, a potem zrobi ci 5-minutowy masaż ramion na spięte mięśnie karku!', title_pt = 'O salão de massagens do pai 💆‍♀️', body_pt = 'Que seja o seu companheiro a adormecer o bebé e depois a fazer-lhe uma massagem de 5 minutos aos ombros e ao pescoço tenso!', title_sv = 'Pappas massagesalong 💆‍♀️', body_sv = 'Låt din partner söva barnet och sedan ge dig en 5 minuters axelmassage för dina spända nackmuskler!', title_vi = 'Tiệm mát-xa của bố 💆‍♀️', body_vi = 'Hãy để bố ru bé ngủ, rồi dành 5 phút mát-xa vai cho những cơ cổ đang căng cứng của mẹ!', title_zh = '爸爸的按摩室 💆‍♀️', body_zh = '让伴侣去哄宝宝睡觉，然后再给你僵硬的脖子和肩膀按摩5分钟吧！' WHERE id = 'a261deac-e213-48df-a6bd-e43793de79c9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El mundo mágico de los cuentos 🪄', title_fr = 'Le monde magique du conte 🪄', title_hi = 'कहानी की जादुई दुनिया 🪄', title_id = 'Dunia dongeng yang ajaib 🪄', title_ja = 'お話の魔法の世界 🪄', title_ko = '동화의 마법 세계 🪄', title_nl = 'De magische wereld van sprookjes 🪄', title_pl = 'Magiczny świat bajki 🪄', title_pt = 'O mundo mágico das histórias 🪄', title_sv = 'Sagans magiska värld 🪄', title_vi = 'Thế giới kỳ diệu của truyện cổ tích 🪄', title_zh = '故事的魔法世界 🪄' WHERE id = '5130988b-06fa-4ca0-8477-7c4e5105998f' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Disfruta comiendo solo! 🥦', body_es = 'Prepara con las Recetas para bebés que empiezan con la alimentación complementaria trocitos nutritivos y fáciles de coger con los dedos.', title_fr = 'Il adore manger tout seul ! 🥦', body_fr = 'Préparez avec les Recettes pour bébés qui commencent la diversification des aliments à attraper, faciles à tenir et nutritifs.', title_hi = 'खुद खाने का मज़ा ले रहा है! 🥦', body_hi = 'ऊपरी आहार शुरू करने वाले बच्चों की रेसिपी से आसानी से पकड़ में आने वाले, पौष्टिक फ़िंगर फ़ूड बनाइए।', title_id = 'Ia senang makan sendiri! 🥦', body_id = 'Siapkan finger food sehat yang mudah digenggam dari Resep untuk bayi yang mulai MPASI.', title_ja = '自分で食べるのが楽しい！🥦', body_ja = '「離乳食を始める赤ちゃんのレシピ」から、持ちやすくて栄養のある手づかみ食べのメニューをつくりましょう。', title_ko = '혼자 먹는 게 즐거워요! 🥦', body_ko = '이유식을 시작하는 아기를 위한 레시피에서 잡기 쉽고 영양 많은 핑거 푸드를 만들어 보세요.', title_nl = 'Hij eet graag zelf! 🥦', body_nl = 'Maak uit de Recepten voor baby''s die met bijvoeding beginnen gezond vingervoedsel dat makkelijk vast te pakken is.', title_pl = 'Lubi jeść sam! 🥦', body_pl = 'Przygotuj z Przepisów dla maluszków zaczynających rozszerzanie diety zdrowe przekąski, które łatwo chwycić rączką.', title_pt = 'Adora comer sozinho! 🥦', body_pt = 'Prepare, com as Receitas para bebés em diversificação alimentar, alimentos saudáveis e fáceis de agarrar com os dedos.', title_sv = 'Barnet njuter av att äta själv! 🥦', body_sv = 'Gör nyttig fingermat som är lätt att hålla i från Recept för barn som börjar med smakportioner.', title_vi = 'Bé thích tự ăn! 🥦', body_vi = 'Hãy làm những món ăn cầm tay bổ dưỡng, dễ cầm từ Công thức cho bé bắt đầu ăn dặm.', title_zh = '宝宝享受自己吃饭！🥦', body_zh = '从“辅食宝宝食谱”里做一些容易抓握、营养丰富的手指食物吧。' WHERE id = '87dbc3cb-466d-4628-b1df-07cce718a3ab' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Entiende órdenes sencillas! 🧠', body_es = '¿Cuando le dices «dame esto» te ofrece el juguete? Para apoyar este salto en su inteligencia, lee los artículos sobre desarrollo del Blog.', title_fr = 'Il comprend les consignes simples ! 🧠', body_fr = 'Quand vous dites « Donne-moi ça », il vous tend le jouet ? Pour soutenir ce bond intellectuel, lisez les articles d''éveil dans les Blogs.', title_hi = 'आसान बातें समझता है! 🧠', body_hi = '''यह मुझे दो'' कहने पर खिलौना आपकी ओर बढ़ाता है? समझ की इस छलांग का साथ देने के लिए ब्लॉग में विकास से जुड़े लेख पढ़िए।', title_id = 'Ia memahami perintah sederhana! 🧠', body_id = 'Saat Anda berkata "Berikan itu padaku", ia menyodorkan mainannya? Untuk mendukung lompatan kecerdasan ini, baca artikel perkembangan di Blog.', title_ja = 'かんたんな指示がわかる！🧠', body_ja = '「これちょうだい」と言うと、おもちゃを渡してくれますか？このかしこさの飛躍を応援するために、ブログの発達に関する記事を読んでみましょう。', title_ko = '간단한 말을 알아들어요! 🧠', body_ko = '''이거 줘'' 하면 장난감을 건네나요? 이 지능의 도약을 돕기 위해 블로그의 발달 관련 글을 읽어 보세요.', title_nl = 'Hij begrijpt eenvoudige opdrachten! 🧠', body_nl = 'Geeft je baby je zijn speeltje als je zegt: geef dat eens aan mij? Lees de artikelen over ontwikkeling in de Blogs om deze denksprong te ondersteunen.', title_pl = 'Rozumie proste polecenia! 🧠', body_pl = 'Gdy mówisz „daj mi to”, podaje ci zabawkę? Aby wspierać ten skok rozwojowy, przeczytaj artykuły o rozwoju na Blogu.', title_pt = 'Percebe ordens simples! 🧠', body_pt = 'Quando diz "dá-me isso", ele estende-lhe o brinquedo? Para apoiar este salto de inteligência, leia os artigos sobre desenvolvimento nos Blogues.', title_sv = 'Förstår enkla uppmaningar! 🧠', body_sv = 'Räcker barnet dig leksaken när du säger ''ge mig den''? Läs de utvecklande artiklarna i Bloggar för att stötta det här tankesprånget.', title_vi = 'Bé hiểu những yêu cầu đơn giản! 🧠', body_vi = 'Khi mẹ nói "Đưa cái này cho mẹ", bé đưa đồ chơi cho mẹ? Để hỗ trợ bước nhảy trí tuệ này, hãy đọc các bài viết về phát triển trong mục Blog.', title_zh = '听得懂简单指令了！🧠', body_zh = '你说“把这个给我”，宝宝会把玩具递给你？想支持这次智力飞跃，就去博客读读促进发育的文章吧。' WHERE id = '9b804616-ae80-4d37-b6a9-76004e3e5506' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La calma de la noche 🛀', body_es = 'Baño templado, masaje y habitación a oscuras. Mantener la rutina de sueño es el secreto básico para tener noches sin interrupciones.', title_fr = 'La sérénité du soir 🛀', body_fr = 'Bain tiède, massage et pièce assombrie. Préserver la routine du coucher, c''est le secret fondamental des nuits sans interruption.', title_hi = 'रात का सुकून 🛀', body_hi = 'गुनगुना स्नान, मालिश और कमरे में अँधेरा। सोने का रूटीन बनाए रखना बिना रुकावट वाली रातों का सबसे बुनियादी राज़ है।', title_id = 'Ketenangan malam 🛀', body_id = 'Mandi air hangat, pijat, dan kamar yang diredupkan. Menjaga rutinitas tidur adalah rahasia utama malam tanpa terbangun.', title_ja = '夜のやすらぎ 🛀', body_ja = 'ぬるめのお風呂、マッサージ、部屋を暗くする。ねんねのルーティンを守ることが、途切れない夜のいちばんの基本のひみつです。', title_ko = '밤의 평온 🛀', body_ko = '따뜻한 목욕, 마사지, 어두운 방. 잠자리 루틴을 지키는 것이 깨지 않는 밤의 가장 기본적인 비결이에요.', title_nl = 'De rust van de nacht 🛀', body_nl = 'Een lauw badje, een massage en een verduisterde kamer. De slaaproutine bewaken is het belangrijkste geheim van ononderbroken nachten.', title_pl = 'Spokój nocy 🛀', body_pl = 'Ciepła kąpiel, masaż i przyciemniony pokój. Pilnowanie rytuału snu to podstawowy sekret nieprzerwanych nocy.', title_pt = 'A calma da noite 🛀', body_pt = 'Banho morno, massagem e quarto escurecido. Manter a rotina de sono é o segredo mais básico para noites sem interrupções.', title_sv = 'Nattens ro 🛀', body_sv = 'Ett ljummet bad, massage och ett mörkt rum. Att hålla fast vid sömnrutinen är den mest grundläggande hemligheten bakom nätter utan avbrott.', title_vi = 'Sự bình yên của màn đêm 🛀', body_vi = 'Tắm nước ấm, mát-xa và làm tối phòng. Giữ nếp sinh hoạt trước khi ngủ là bí quyết cơ bản nhất cho những đêm ngủ trọn giấc.', title_zh = '夜晚的宁静 🛀', body_zh = '温水澡、按摩、调暗房间。守护好睡前作息，是夜夜安睡最基本的秘诀。' WHERE id = 'f2c9cd05-6f08-42dc-b88f-310abadaba89' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Todo lo que encuentra en el suelo lo examina con enorme curiosidad. 🗑️', body_es = 'No te enfades quitándoselo todo, es un explorador. Simplemente vigílale.', title_fr = 'Tout ce qu''il trouve par terre, il l''examine avec passion. 🗑️', body_fr = 'Ne vous énervez pas à tout lui retirer des mains, c''est un explorateur. Gardez simplement un œil sur lui.', title_hi = 'ज़मीन पर जो भी मिले, बड़े ध्यान से परखता है 🗑️', body_hi = 'हर चीज़ उसके हाथ से छीनकर गुस्सा मत होइए, वह एक खोजी है। बस उस पर नज़र रखिए।', title_id = 'Apa pun yang ia temukan di lantai, ia teliti dengan penuh rasa ingin tahu. 🗑️', body_id = 'Jangan kesal dan merebut semuanya, ia seorang penjelajah. Cukup awasi saja.', title_ja = '床で見つけたものを、興味しんしんで調べています。🗑️', body_ja = 'イライラしてぜんぶ取り上げないで、赤ちゃんは探検家なのです。見守るだけにしましょう。', title_ko = '바닥에서 찾은 건 무엇이든 큰 호기심으로 살펴봐요. 🗑️', body_ko = '모든 걸 빼앗으며 화내지 마세요, 아기는 탐험가니까요. 곁에서 지켜보기만 하세요.', title_nl = 'Alles wat je baby op de vloer vindt, bekijkt hij vol nieuwsgierigheid.  🗑️', body_nl = 'Pak niet alles af en word niet boos, hij is een ontdekkingsreiziger. Houd hem gewoon in de gaten.', title_pl = 'Wszystko, co znajdzie na podłodze, ogląda z wielką ciekawością. 🗑️', body_pl = 'Nie denerwuj się i nie zabieraj mu wszystkiego, jest odkrywcą. Po prostu miej go na oku.', title_pt = 'Tudo o que encontra no chão, examina com enorme curiosidade.  🗑️', body_pt = 'Não se irrite a tirar-lhe tudo das mãos, ele é um explorador. Basta vigiá-lo.', title_sv = 'Vad barnet än hittar på golvet undersöker det med stort intresse.  🗑️', body_sv = 'Ta inte allt ifrån det och bli inte irriterad, det är en upptäcktsresande. Håll bara uppsikt.', title_vi = 'Tìm thấy gì trên sàn, bé cũng xem xét đầy hứng thú.  🗑️', body_vi = 'Đừng bực mình giật mọi thứ khỏi tay bé, bé là một nhà thám hiểm. Chỉ cần để mắt đến bé thôi.', title_zh = '在地上找到什么都要研究一番 🗑️', body_zh = '别生气地把东西全抢走，宝宝是个小探险家。只要在旁边看好就行。' WHERE id = 'fad6626b-f1fb-4e8d-8e1a-679ccb7c1f85' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ha llorado y ha estado inquieto todo el día? La solución es muy sencilla: mira Tiempo y ropa, súbele al carrito y sal enseguida al parque.', body_fr = 'Il a pleuré et s''est agité toute la journée ? La solution est simple : consultez Météo et tenue, installez-le dans la poussette et filez au parc.', body_hi = 'दिनभर रोता और बेचैन रहा? उपाय बहुत आसान है: मौसम और कपड़े देखिए, स्ट्रॉलर में बिठाइए और तुरंत पार्क चलिए।', body_id = 'Ia menangis dan rewel seharian? Solusinya sangat sederhana: cek Cuaca dan Pakaian, dudukkan ia di stroller, dan segera pergi ke taman.', body_ja = '1日中泣いてぐずっていた？解決法はとてもシンプル：「天気と服装」を見て、ベビーカーに乗せ、すぐに公園へ。', body_ko = '하루 종일 울고 보챘나요? 해결책은 아주 간단해요: 날씨와 옷차림을 확인하고 유모차에 태워 바로 공원으로 나가세요.', body_nl = 'Heeft je baby de hele dag gehuild en was hij onrustig? De oplossing is simpel: kijk in Weer en kleding, zet hem in de kinderwagen en ga meteen naar het park.', body_pl = 'Cały dzień płakał i był niespokojny? Rozwiązanie jest bardzo proste: sprawdź Pogodę i ubiór, posadź go w wózku i od razu idźcie do parku.', body_pt = 'Chorou e esteve inquieto o dia todo? A solução é muito simples: veja o Tempo e Roupa, ponha-o no carrinho e vá já para o parque.', body_sv = 'Har barnet gråtit och varit oroligt hela dagen? Lösningen är enkel: kolla Väder och kläder, lägg barnet i vagnen och gå direkt till parken.', body_vi = 'Bé khóc và quấy cả ngày? Cách giải quyết rất đơn giản: xem Thời tiết và trang phục, đặt bé vào xe đẩy và ra công viên ngay.', body_zh = '宝宝哭闹烦躁了一整天？办法很简单：看看天气穿衣，放进婴儿车，马上去公园。' WHERE id = '3995ea79-4422-4b71-b376-6426966b7d85' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Si se frota los ojos y se queda con la mirada perdida, no esperes a la crisis. Oscurece la habitación ya y empieza la rutina de sueño.', body_fr = 'S''il se frotte les yeux et fixe le vide, n''attendez pas la crise. Assombrissez tout de suite la pièce et lancez la routine du coucher.', body_hi = 'अगर वह आँखें मलकर शून्य में देख रहा है, तो रोने के दौरे का इंतज़ार मत कीजिए। तुरंत कमरे में अँधेरा करके सोने का रूटीन शुरू कीजिए।', body_id = 'Kalau ia mengucek mata dan menatap kosong, jangan tunggu sampai rewel. Segera redupkan kamar dan mulai rutinitas tidur.', body_ja = '目をこすってぼーっとしていたら、ぐずりが爆発するのを待たないで。すぐに部屋を暗くして、ねんねのルーティンを始めましょう。', body_ko = '눈을 비비며 허공을 바라본다면 잠투정을 기다리지 마세요. 바로 방을 어둡게 하고 잠자리 루틴을 시작하세요.', body_nl = 'Wrijft je baby in de oogjes en staart hij in het niets? Wacht niet op een huilbui. Maak de kamer meteen donker en begin met de slaaproutine.', body_pl = 'Jeśli trze oczka i patrzy w pustkę, nie czekaj na kryzys. Od razu przyciemnij pokój i zacznij rytuał snu.', body_pt = 'Se esfrega os olhos e fica a olhar para o vazio, não espere pela crise. Escureça já o quarto e comece a rotina de sono.', body_sv = 'Gnuggar barnet ögonen och stirrar tomt ut i luften? Vänta inte på utbrottet. Gör rummet mörkt direkt och börja sömnrutinen.', body_vi = 'Nếu bé dụi mắt và nhìn vào khoảng không, đừng đợi đến lúc bé quấy. Hãy làm tối phòng ngay và bắt đầu nếp sinh hoạt trước khi ngủ.', body_zh = '如果宝宝揉着眼睛发呆，别等闹觉。马上调暗房间，开始睡前作息。' WHERE id = 'da354848-a7ac-41ba-9616-ccf0b8799a86' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Protesta y llora cuando le quitas algo de las manos? 🧸', body_es = 'Se desarrolla su sentido de la propiedad y de la individualidad. Es una etapa psicológica muy natural.', title_fr = 'Il proteste et pleure quand vous lui prenez quelque chose ? 🧸', body_fr = 'Son sens de la propriété et de l''individualité se développe. C''est une étape psychologique très naturelle.', title_hi = 'उसके हाथ से कुछ लेने पर विरोध करता है और रोता है? 🧸', body_hi = 'उसमें ''मेरा'' और अपनी पहचान का एहसास विकसित हो रहा है। यह बहुत स्वाभाविक मानसिक दौर है।', title_id = 'Ia protes dan menangis saat Anda mengambil sesuatu dari tangannya? 🧸', body_id = 'Rasa memiliki dan kepribadiannya sedang berkembang. Ini tahap psikologis yang sangat wajar.', title_ja = '手から何かを取り上げると、怒って泣きますか？🧸', body_ja = '「自分のもの」という感覚と個性が育っています。とても自然な心の成長の段階です。', title_ko = '손에서 무언가를 빼면 항의하며 우나요? 🧸', body_ko = '소유와 자아 개념이 자라고 있어요. 아주 자연스러운 심리 발달 단계예요.', title_nl = 'Protesteert je baby en huilt hij als je iets uit zijn handjes pakt? 🧸', body_nl = 'Het gevoel van bezit en eigenheid ontwikkelt zich. Dit is een heel normale psychologische fase.', title_pl = 'Protestuje i płacze, gdy coś mu zabierasz? 🧸', body_pl = 'Rozwija się poczucie własności i odrębności. To bardzo naturalny etap psychologiczny.', title_pt = 'Protesta e chora quando lhe tira alguma coisa das mãos? 🧸', body_pt = 'O sentido de posse e de individualidade está a desenvolver-se. É uma fase psicológica muito natural.', title_sv = 'Protesterar barnet och gråter när du tar något ifrån det? 🧸', body_sv = 'Känslan för ägande och den egna personen utvecklas. Det är en helt naturlig psykologisk fas.', title_vi = 'Bé phản đối và khóc khi mẹ lấy thứ gì đó khỏi tay? 🧸', body_vi = 'Ý thức về sở hữu và cái tôi của bé đang phát triển. Đây là giai đoạn tâm lý rất tự nhiên.', title_zh = '从宝宝手里拿走东西时，宝宝会反抗、大哭？🧸', body_zh = '宝宝的物权意识和自我意识正在发展。这是非常自然的心理阶段。' WHERE id = '049b837c-5a26-4c32-95e4-e745b4a3443b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Decimos adiós! 👋', body_es = '¿Ha aprendido a decir adiós con la mano a quien se va? Guarda ya este gesto consciente y tan tierno con la Sesión de fotos del bebé.', title_fr = 'On fait au revoir ! 👋', body_fr = 'Il a appris à faire au revoir de la main ? Immortalisez tout de suite ce geste conscient et adorable avec la Séance photo bébé.', title_hi = 'बाय-बाय कर रहे हैं! 👋', body_hi = 'जाने वालों के पीछे हाथ हिलाना सीख गया? उसकी इस समझदार और प्यारी हरकत को बेबी फ़ोटोशूट से तुरंत यादों में सहेजिए।', title_id = 'Kita dadah-dadah! 👋', body_id = 'Ia sudah belajar melambai pada orang yang pergi? Segera abadikan gerakan manis yang disadarinya ini dengan Sesi Foto Bayi.', title_ja = 'バイバイできるよ！👋', body_ja = '出かける人に手を振ってバイバイできるようになりましたか？このわかってしているかわいいしぐさを、すぐに「ベビーフォトセッション」で残しましょう。', title_ko = '빠이빠이 해요! 👋', body_ko = '떠나는 사람에게 손을 흔드는 법을 배웠나요? 이 의젓하고 귀여운 행동을 아기 사진 촬영으로 바로 남겨 두세요.', title_nl = 'We zwaaien dag! 👋', body_nl = 'Heeft je baby geleerd om mensen die weggaan na te zwaaien? Leg dit bewuste, lieve gebaar meteen vast met Babyfotoshoot.', title_pl = 'Robimy pa-pa! 👋', body_pl = 'Nauczył się machać na pożegnanie? Od razu uwiecznij ten świadomy i słodki gest w Sesji zdjęciowej dziecka.', title_pt = 'Estamos a dizer adeus! 👋', body_pt = 'Aprendeu a dizer adeus com a mão a quem se vai embora? Guarde já este gesto consciente e doce com a Sessão Fotográfica do Bebé.', title_sv = 'Vi vinkar hej då! 👋', body_sv = 'Har barnet lärt sig att vinka efter dem som går? Förevig den här medvetna och söta rörelsen direkt med Babyfotografering.', title_vi = 'Vẫy tay tạm biệt! 👋', body_vi = 'Bé đã học cách vẫy tay chào người ra về? Hãy lưu giữ ngay hành động có ý thức và đáng yêu này bằng Chụp ảnh cho bé.', title_zh = '拜拜啦！👋', body_zh = '宝宝学会朝离开的人挥手了？马上用宝宝写真留住这个有意识又可爱的动作吧。' WHERE id = '06a37325-84f4-4012-b4a0-ff317ba78e4c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Seguridad en casa! 🛡', body_es = '️ Cuanto más intenta ponerse de pie, más peligros hay. No dejes de mirar nuestra lista de Productos recomendados para cierres de seguridad y protectores de esquinas.', title_fr = 'Sécurité à la maison ! 🛡', body_fr = '️Plus il essaie de se mettre debout, plus les dangers augmentent. Consultez absolument notre liste de Produits recommandés pour les bloque-portes et protections d''angle.', title_hi = 'घर में सुरक्षा के उपाय! 🛡', body_hi = '️वह जितना खड़े होने की कोशिश करेगा, खतरे उतने बढ़ेंगे। चाइल्ड लॉक और कॉर्नर गार्ड के लिए हमारी सुझाए गए प्रोडक्ट की सूची ज़रूर देखिए।', title_id = 'Keamanan di rumah! 🛡', body_id = '️ ️ Makin ia berusaha berdiri, makin banyak pula bahayanya. Pastikan melihat daftar Produk Rekomendasi kami untuk kunci pengaman anak dan pelindung sudut.', title_ja = 'おうちの安全対策！🛡', body_ja = '️ 立ち上がろうとするほど、危険も増えます。チャイルドロックやコーナーガードは、「おすすめ商品」リストをぜひチェックしましょう。', title_ko = '집 안 안전 대책! 🛡', body_ko = '️ 아기가 일어서려 할수록 위험도 늘어나요. 안전 잠금장치와 모서리 보호대는 추천 제품 목록에서 꼭 확인하세요.', title_nl = 'Veiligheid in huis! 🛡', body_nl = '️ Hoe meer je baby probeert te gaan staan, hoe meer gevaren er zijn. Bekijk zeker in onze Aanbevolen producten kinderslotjes en hoekbeschermers.', title_pl = 'Bezpieczeństwo w domu! 🛡', body_pl = '️ Im bardziej próbuje wstawać, tym więcej zagrożeń. Koniecznie zajrzyj na naszą listę Polecanych produktów po blokady dla dzieci i osłonki na narożniki.', title_pt = 'Segurança em casa! 🛡', body_pt = '️ Quanto mais tenta pôr-se de pé, maiores são os perigos. Veja sem falta na nossa lista de Produtos Recomendados os fechos de segurança e os protetores de cantos.', title_sv = 'Säkerhet i hemmet! 🛡', body_sv = '️ Ju mer barnet försöker resa sig, desto fler faror. Kika absolut i vår lista Rekommenderade produkter efter barnlås och kantskydd.', title_vi = 'Biện pháp an toàn trong nhà! 🛡', body_vi = '️ Bé càng cố đứng dậy thì nguy hiểm càng tăng. Nhất định hãy xem danh sách Sản phẩm gợi ý để tìm khóa an toàn và miếng bọc góc cho trẻ.', title_zh = '居家安全措施！🛡', body_zh = '️ 宝宝越来越想站起来，危险也随之增加。一定要去推荐商品清单里看看儿童安全锁和防撞角。' WHERE id = '69b02f6b-1a0a-4f09-860a-f56dfb370b0a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lucha del agua 💧', body_es = '¿Quiere sujetar su vaso él solo, pero casi todo acaba encima? Aplaude sus intentos de independencia, para eso están las toallitas húmedas.', title_fr = 'La bataille de l''eau 💧', body_fr = 'Il veut tenir son gobelet tout seul pour boire, mais en renverse la plus grande partie sur lui ? Applaudissez ses efforts d''autonomie, les lingettes sont là pour ça.', title_hi = 'पानी की ज़िद 💧', body_hi = 'अपना कप खुद पकड़कर पीना चाहता है, पर ज़्यादातर पानी कपड़ों पर गिर जाता है? उसकी आत्मनिर्भरता की कोशिशों की तारीफ़ कीजिए, वेट वाइप्स इसी के लिए तो हैं।', title_id = 'Si keras kepala dan air 💧', body_id = 'Ia ingin memegang dan minum dari cangkirnya sendiri, tapi kebanyakan tumpah ke bajunya? Dukung usahanya untuk mandiri, toh tisu basah memang ada untuk itu.', title_ja = 'お水へのこだわり 💧', body_ja = '自分のコップを自分で持って飲みたいのに、ほとんどこぼしてしまう？自分でやりたい気持ちに拍手を。おしりふきはそのためにあるのです。', title_ko = '물컵 고집 💧', body_ko = '자기 컵을 혼자 들고 마시고 싶은데 대부분 옷에 쏟나요? 자립하려는 도전에 박수를 보내 주세요, 물티슈는 원래 그럴 때 쓰는 거예요.', title_nl = 'Zelf drinken 💧', body_nl = 'Wil je baby zelf zijn bekertje vasthouden en drinken, maar gaat het meeste over hem heen? Juich zijn pogingen tot zelfstandigheid toe, daar zijn billendoekjes toch voor.', title_pl = 'Wodny upór 💧', body_pl = 'Chce sam trzymać kubeczek i pić, ale większość wylewa na siebie? Oklaskuj jego próby samodzielności, chusteczki nawilżane i tak są od tego.', title_pt = 'A teimosia da água 💧', body_pt = 'Quer segurar o copo sozinho e beber, mas entorna quase tudo em cima de si? Aplauda as tentativas de independência, os toalhetes existem precisamente para isso.', title_sv = 'Vattenenvishet 💧', body_sv = 'Vill barnet hålla sin egen mugg och dricka själv, men det mesta hamnar på kläderna? Applådera försöken till självständighet, det är ju det våtservetter är till för.', title_vi = 'Cuộc chiến với cốc nước 💧', body_vi = 'Bé muốn tự cầm cốc uống nước nhưng phần lớn lại đổ ra người? Hãy cổ vũ những nỗ lực tự lập ấy, khăn ướt sinh ra là để dùng cho việc này mà.', title_zh = '喝水的倔强 💧', body_zh = '宝宝想自己拿杯子喝水，结果大半都洒在身上？为宝宝的独立尝试鼓掌吧，湿巾本来就是干这个的。' WHERE id = '249e422f-5203-4598-a063-3032744aab4c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora de recarga de la pareja 🔋', body_es = 'Durante el día le has dado toda tu energía a tu peque. Deja que tu pareja pase la tarde con el bebé y tú desconéctate.', title_fr = 'L''heure de recharge du partenaire 🔋', body_fr = 'Vous avez donné toute votre énergie à votre enfant pendant la journée. Ce soir, laissez votre conjoint passer la soirée avec lui, et vous, déconnectez-vous.', title_hi = 'साथी का रिचार्ज समय 🔋', body_hi = 'दिनभर आपने अपनी सारी ऊर्जा बच्चे को दी। आज शाम आपके जीवनसाथी बच्चे के साथ बिताएँ, और आप ऑफ़लाइन हो जाइए।', title_id = 'Jam isi ulang tenaga 🔋', body_id = 'Seharian Anda sudah memberikan seluruh energi untuk si kecil. Biarkan pasangan Anda menghabiskan malam ini bersamanya, dan Anda boleh offline.', title_ja = 'パートナーの充電タイム 🔋', body_ja = '昼間はすべてのエネルギーを赤ちゃんにそそぎました。今夜はパートナーに赤ちゃんと過ごしてもらい、あなたはオフラインになりましょう。', title_ko = '배우자의 충전 시간 🔋', body_ko = '낮 동안 모든 에너지를 아이에게 쏟았어요. 오늘 저녁은 배우자가 아이와 시간을 보내게 하고, 엄마는 오프라인이 되세요.', title_nl = 'Tijd om op te laden met je partner 🔋', body_nl = 'Je hebt overdag al je energie aan je kindje gegeven. Laat je partner vanavond met de baby doorbrengen, en jij gaat offline.', title_pl = 'Godzina ładowania baterii 🔋', body_pl = 'W ciągu dnia oddałaś maluszkowi całą swoją energię. Niech partner spędzi z nim ten wieczór, a ty bądź offline.', title_pt = 'A hora de recarregar com o companheiro 🔋', body_pt = 'Deu toda a sua energia ao bebé durante o dia. Deixe o seu companheiro passar a noite com ele e fique offline.', title_sv = 'Partnerns laddningstimme 🔋', body_sv = 'Du har gett barnet all din energi under dagen. Låt din partner tillbringa kvällen med barnet medan du är offline.', title_vi = 'Giờ sạc pin của bố 🔋', body_vi = 'Cả ngày mẹ đã dành hết năng lượng cho bé. Tối nay hãy để bố ở cùng bé, còn mẹ thì "ngoại tuyến" nhé.', title_zh = '伴侣的充电时间 🔋', body_zh = '白天你把所有精力都给了宝宝。今晚让伴侣陪宝宝，你下线休息吧。' WHERE id = '88ed955b-e80f-4226-9234-7112a99a4951' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los primeros segundos sin apoyo 🧗‍♂️', body_es = '¿De pie agarrado al sofá, de repente se suelta? ¡Está encontrando el equilibrio! Vigila con atención estos segundos cortos pero emocionantes.', title_fr = 'Les premières secondes sans appui 🧗‍♂️', body_fr = 'Debout en se tenant au canapé, il lâche soudain les mains ? Il trouve son équilibre ! Sécurisez attentivement ces quelques secondes courtes mais palpitantes.', title_hi = 'बिना सहारे के पहले सेकंड 🧗‍♂️', body_hi = 'सोफ़ा पकड़कर खड़े-खड़े अचानक हाथ छोड़ देता है? वह अपना संतुलन ढूँढ रहा है! इन छोटे पर रोमांचक सेकंडों में उसकी सुरक्षा का ध्यान रखिए।', title_id = 'Detik-detik pertama tanpa pegangan 🧗‍♂️', body_id = 'Saat berdiri berpegangan pada sofa, tiba-tiba ia melepaskan tangannya? Ia sedang menemukan keseimbangannya! Jaga dengan saksama detik-detik singkat yang mendebarkan ini.', title_ja = '支えなしの最初の数秒 🧗‍♂️', body_ja = 'ソファにつかまって立っているとき、急に手を離しますか？バランスを見つけているのです！この短くてドキドキする数秒を、しっかり見守りましょう。', title_ko = '받침 없는 첫 몇 초 🧗‍♂️', body_ko = '소파를 잡고 서 있다가 갑자기 손을 놓나요? 균형을 찾고 있어요! 이 짧지만 설레는 순간을 곁에서 잘 지켜 주세요.', title_nl = 'De eerste seconden zonder steun 🧗‍♂️', body_nl = 'Laat je baby ineens zijn handjes los als hij staat en zich aan de bank vasthoudt? Hij vindt zijn evenwicht! Blijf in deze korte maar spannende seconden goed in de buurt.', title_pl = 'Pierwsze sekundy bez podparcia 🧗‍♂️', body_pl = 'Stojąc przy kanapie, nagle puszcza rączki? Łapie równowagę! Uważnie asekuruj te krótkie, ale ekscytujące sekundy.', title_pt = 'Os primeiros segundos sem apoio 🧗‍♂️', body_pt = 'De pé agarrado ao sofá, larga de repente as mãos? Está a encontrar o equilíbrio! Proteja com atenção estes segundos curtos mas emocionantes.', title_sv = 'De första sekunderna utan stöd 🧗‍♂️', body_sv = 'Släpper barnet plötsligt händerna när det står och håller i soffan? Det hittar balansen! Var redo att ta emot under de här korta men spännande sekunderna.', title_vi = 'Những giây đầu tiên không cần bám 🧗‍♂️', body_vi = 'Đang bám sofa đứng, bé bỗng buông tay? Bé đang tìm lại thăng bằng! Hãy cẩn thận che chắn cho bé trong những giây ngắn ngủi mà đầy phấn khích này.', title_zh = '第一次不扶东西的几秒钟 🧗‍♂️', body_zh = '扶着沙发站着时突然松开了手？宝宝在找平衡！在旁边护好这短暂又激动人心的几秒钟吧。' WHERE id = 'd2dfb95a-94ec-43c1-97da-20aed6c6d0bb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dilema de qué cocinar 🍲', body_es = '¿Te has quedado sin ideas para el menú de alimentación complementaria? No te pierdas en internet. Pide a Anacan AI una lista de alimentos fáciles para comer con los dedos para un bebé de 10 meses.', title_fr = 'Le casse-tête du « qu''est-ce que je cuisine ? » 🍲', body_fr = 'Plus d''idées pour le menu de diversification ? Ne vous perdez pas sur Internet. Demandez à Anacan AI une liste d''aliments faciles à manger avec les doigts pour un bébé de 10 mois.', title_hi = 'क्या पकाऊँ, यही चिंता 🍲', body_hi = 'ऊपरी आहार के मेन्यू के आइडिया खत्म हो गए? इंटरनेट में मत खोइए। Anacan AI से 10 महीने के बच्चे के लिए आसान फ़िंगर फ़ूड की सूची माँगिए।', title_id = 'Bingung mau masak apa 🍲', body_id = 'Kehabisan ide menu MPASI? Jangan tersesat di internet. Minta daftar finger food yang mudah untuk bayi 10 bulan dari Anacan AI.', title_ja = '何をつくろう問題 🍲', body_ja = '離乳食の献立のアイデアが尽きた？ネットで迷子にならないで。Anacan AIに、生後10か月の赤ちゃん向けのかんたんな手づかみ食べリストを頼みましょう。', title_ko = '뭐 해 먹지 고민 🍲', body_ko = '이유식 메뉴 아이디어가 바닥났나요? 인터넷에서 헤매지 마세요. Anacan AI에게 10개월 아기를 위한 쉬운 핑거 푸드 목록을 요청하세요.', title_nl = 'Wat moet ik koken? 🍲', body_nl = 'Geen ideeën meer voor het bijvoedingsmenu? Verdwaal niet op internet. Vraag Anacan AI om een lijst met makkelijk vingervoedsel voor een baby van 10 maanden.', title_pl = 'Co ugotować? 🍲', body_pl = 'Kończą ci się pomysły na jadłospis przy rozszerzaniu diety? Nie gub się w internecie. Poproś Anacan AI o listę łatwych przekąsek do jedzenia rączkami dla 10-miesięcznego maluszka.', title_pt = 'O dilema do que cozinhar 🍲', body_pt = 'Ficou sem ideias para a ementa da diversificação alimentar? Não se perca na internet. Peça ao Anacan AI uma lista de alimentos fáceis para comer à mão para um bebé de 10 meses.', title_sv = 'Vad ska jag laga? 🍲', body_sv = 'Har idéerna till menyn med smakportioner tagit slut? Gå inte vilse på nätet. Be Anacan AI om en lista med enkel fingermat för en 10 månader gammal bebis.', title_vi = 'Nỗi lo "nấu gì đây" 🍲', body_vi = 'Cạn ý tưởng cho thực đơn ăn dặm? Đừng lạc giữa mạng internet. Hãy nhờ Anacan AI gợi ý danh sách món ăn cầm tay dễ làm cho bé 10 tháng.', title_zh = '“做什么吃”的烦恼 🍲', body_zh = '辅食菜单想不出新花样了？别在网上迷失方向。向Anacan AI要一份适合10个月宝宝的简单手指食物清单吧。' WHERE id = '80ecdccb-340a-49ab-94a9-ff073855c0a0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Se une a la conversación 🗣️', body_es = '¿Mientras hablas por teléfono, él también dice algo en su idioma y sube la voz? Su capacidad de comunicación se acelera, ¡hay un segundo locutor en la habitación!', title_fr = 'Il se joint à la conversation 🗣️', body_fr = 'Quand vous êtes au téléphone, il se met lui aussi à parler fort dans sa propre langue ? Ses capacités de communication s''accélèrent, il y a un deuxième orateur dans la pièce !', title_hi = 'बातचीत में शामिल होता है 🗣️', body_hi = 'आप फ़ोन पर बात करती हैं तो वह भी अपनी भाषा में कुछ कहकर आवाज़ ऊँची करता है? बातचीत की क्षमता तेज़ी से बढ़ रही है, कमरे में एक दूसरा वक्ता भी है!', title_id = 'Ikut mengobrol 🗣️', body_id = 'Saat Anda bicara di telepon, ia juga mengucapkan sesuatu dengan bahasanya sambil mengeraskan suara? Kemampuan komunikasinya melesat, kini ada pembicara kedua di ruangan!', title_ja = '会話に参加 🗣️', body_ja = 'あなたが電話で話していると、赤ちゃんも自分の言葉で何か言って声を大きくしますか？コミュニケーション力がぐんぐん育っています。部屋にもうひとりスピーカーがいます！', title_ko = '대화에 끼어들어요 🗣️', body_ko = '엄마가 통화할 때 아기도 자기 말로 뭔가를 크게 말하나요? 소통 능력이 빠르게 자라고 있어요, 방 안에 두 번째 스피커가 생겼네요!', title_nl = 'Hij praat mee 🗣️', body_nl = 'Zegt je baby in zijn eigen taal iets en praat hij harder als jij aan de telefoon bent? Zijn communicatievaardigheden gaan snel vooruit, er is een tweede spreker in de kamer!', title_pl = 'Włącza się do rozmowy 🗣️', body_pl = 'Gdy rozmawiasz przez telefon, on też coś mówi w swoim języku i podnosi głos? Umiejętności komunikacyjne przyspieszają, w pokoju jest drugi spiker!', title_pt = 'Entra na conversa 🗣️', body_pt = 'Enquanto fala ao telefone, ele também diz qualquer coisa na sua língua e levanta a voz? A capacidade de comunicação acelera: há um segundo orador no quarto!', title_sv = 'Barnet hänger med i samtalet 🗣️', body_sv = 'Säger barnet något på sitt eget språk och höjer rösten när du pratar i telefon? Kommunikationsförmågan tar fart, det finns en andra talare i rummet!', title_vi = 'Bé tham gia trò chuyện 🗣️', body_vi = 'Khi mẹ nói điện thoại, bé cũng nói gì đó bằng ngôn ngữ riêng và lên giọng? Kỹ năng giao tiếp đang tăng tốc, trong phòng có thêm một "diễn giả" nữa rồi!', title_zh = '加入聊天 🗣️', body_zh = '你打电话时，宝宝也用自己的语言大声说着什么？沟通能力突飞猛进，房间里多了一位“发言人”！' WHERE id = 'b8e6e605-baf6-44b6-9e44-842e0b7a0af0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se ha despertado gritando de repente? 😭', body_es = 'Pueden empezar los terrores nocturnos. Usa el Análisis del llanto y averigua si el problema es físico o psicológico.', title_fr = 'Il s''est réveillé en hurlant d''un coup ? 😭', body_fr = 'Les terreurs nocturnes peuvent commencer. Faites écouter ses pleurs à l''Analyse des pleurs pour savoir si le problème est physique ou psychologique.', title_hi = 'अचानक चीखकर जागा? 😭', body_hi = 'नींद का डर (नाइट टेरर) शुरू हो सकता है। क्राइंग एनालिसिस से उसकी आवाज़ सुनवाइए और पता कीजिए कि समस्या शारीरिक है या मानसिक।', title_id = 'Terbangun mendadak sambil menjerit? 😭', body_id = 'Teror tidur mungkin mulai muncul. Perdengarkan tangisannya ke Analisis Tangisan dan pastikan apakah masalahnya fisik atau psikologis.', title_ja = '突然叫んで起きた？😭', body_ja = '夜驚症が始まっているのかもしれません。「泣き声分析」に泣き声を聞かせて、原因が体なのか心なのかを確かめましょう。', title_ko = '갑자기 비명을 지르며 깼나요? 😭', body_ko = '야경증이 시작될 수 있어요. 울음 분석으로 소리를 들려주고 신체적인 문제인지 심리적인 문제인지 확인해 보세요.', title_nl = 'Ineens schreeuwend wakker? 😭', body_nl = 'Nachtmerries kunnen beginnen. Laat Huilanalyse luisteren en ontdek of het probleem lichamelijk of psychisch is.', title_pl = 'Nagle budzi się z krzykiem? 😭', body_pl = 'Mogą zaczynać się lęki nocne. Pozwól Analizie płaczu posłuchać dźwięku i ustal, czy problem jest fizyczny, czy psychiczny.', title_pt = 'Acordou de repente aos gritos? 😭', body_pt = 'Podem estar a começar os terrores noturnos. Ponha a Análise do Choro a ouvir e confirme se o problema é físico ou psicológico.', title_sv = 'Vaknade barnet plötsligt skrikande? 😭', body_sv = 'Nattskräck kan börja. Låt Gråtanalys lyssna på ljudet och ta reda på om problemet är fysiskt eller psykiskt.', title_vi = 'Bé bỗng thét lên rồi tỉnh giấc? 😭', body_vi = 'Có thể đó là chứng hoảng sợ ban đêm. Hãy cho Phân tích tiếng khóc nghe để biết chắc vấn đề là thể chất hay tâm lý.', title_zh = '突然尖叫着醒来？😭', body_zh = '可能是夜惊开始了。用哭声分析听一听，弄清楚问题是身体上的还是心理上的。' WHERE id = 'c9db13f9-8aff-4b71-a7fa-bdce47336917' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hambre o cansancio? 😭', body_es = 'Cuando llore sin motivo, no pierdas los nervios. Apóyate en el Análisis del llanto para encontrar y resolver el problema por el camino más corto.', title_fr = 'Faim ou fatigue ? 😭', body_fr = 'Quand il pleure sans raison, ne perdez pas pied. Appuyez-vous sur l''Analyse des pleurs pour trouver rapidement le problème et le résoudre.', title_hi = 'भूखा है या थका हुआ? 😭', body_hi = 'बेवजह रोने पर घबराइए मत। क्राइंग एनालिसिस की मदद लीजिए और समस्या जल्दी पहचानकर हल कीजिए।', title_id = 'Lapar atau lelah? 😭', body_id = 'Jangan panik saat ia menangis tanpa sebab. Minta bantuan Analisis Tangisan untuk menemukan dan mengatasi masalahnya dengan cepat.', title_ja = 'お腹がすいた？それとも疲れた？😭', body_ja = '理由もなく泣くときも、あわてないで。「泣き声分析」の助けを借りて、すばやく原因を見つけて解決しましょう。', title_ko = '배고픈 걸까요, 피곤한 걸까요? 😭', body_ko = '이유 없이 울 때 당황하지 마세요. 울음 분석의 도움을 받아 문제를 빠르게 찾아 해결하세요.', title_nl = 'Honger of moe? 😭', body_nl = 'Raak niet van slag als je baby zonder reden huilt. Vraag Huilanalyse om hulp en vind snel de oorzaak en de oplossing.', title_pl = 'Głodny czy zmęczony? 😭', body_pl = 'Gdy płacze bez powodu, nie trać głowy. Skorzystaj z pomocy Analizy płaczu, szybko znajdź problem i go rozwiąż.', title_pt = 'Fome ou cansaço? 😭', body_pt = 'Quando chora sem motivo, não perca a calma. Peça ajuda à Análise do Choro, descubra rapidamente o problema e resolva-o.', title_sv = 'Hungrig eller trött? 😭', body_sv = 'Tappa inte fattningen när barnet gråter utan anledning. Ta hjälp av Gråtanalys och hitta och lös problemet den snabba vägen.', title_vi = 'Bé đói hay mệt? 😭', body_vi = 'Khi bé khóc không rõ lý do, đừng hoảng. Hãy nhờ Phân tích tiếng khóc hỗ trợ để nhanh chóng tìm ra và giải quyết vấn đề.', title_zh = '饿了还是累了？😭', body_zh = '宝宝无缘无故地哭时，别慌了手脚。借助哭声分析，快速找出问题并解决吧。' WHERE id = '7a757f5f-8810-4a3e-a344-a9b3d9a89548' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El consuelo de papá 🫂', body_es = 'En los despertares nocturnos, que una vez te levantes tú y otra tu pareja. Repartid la carga a la mitad, como un equipo.', title_fr = 'Le réconfort de papa 🫂', body_fr = 'Pour les réveils nocturnes, levez-vous une fois chacun, vous et votre conjoint. Partagez la charge en deux, en équipe.', title_hi = 'पापा से मिलने वाला सुकून 🫂', body_hi = 'रात में जागने पर एक बार आप उठिए, एक बार आपके साथी। टीम बनकर बोझ को बराबर आधा बाँट लीजिए।', title_id = 'Hiburan dari ayah 🫂', body_id = 'Saat ia terbangun di malam hari, gantian bangun dengan pasangan. Bagi bebannya tepat setengah sebagai satu tim.', title_ja = 'パパのなぐさめ 🫂', body_ja = '夜中に起きたら、1回はあなた、1回はパートナーと交代で。チームとして、負担をきっちり半分に分けましょう。', title_ko = '아빠의 위로 🫂', body_ko = '밤에 깰 때는 한 번은 엄마가, 한 번은 배우자가 일어나세요. 한 팀으로서 짐을 정확히 절반씩 나누세요.', title_nl = 'Troost van papa 🫂', body_nl = 'Ga ''s nachts om de beurt eruit: de ene keer jij, de andere keer je partner. Verdeel de last als team helemaal eerlijk.', title_pl = 'Pocieszenie od taty 🫂', body_pl = 'Przy nocnych pobudkach wstawajcie na zmianę: raz ty, raz partner. Jako drużyna podzielcie ciężar dokładnie na pół.', title_pt = 'O conforto do pai 🫂', body_pt = 'Nos despertares noturnos, levanta-se uma vez a mãe e outra vez o pai. Dividam o peso ao meio, como uma equipa.', title_sv = 'Tröst från pappa 🫂', body_sv = 'Turas om att gå upp vid nattuppvaknandena, en gång du och en gång din partner. Dela bördan helt lika, som ett lag.', title_vi = 'Sự an ủi từ bố 🫂', body_vi = 'Khi bé thức đêm, lần này mẹ dậy, lần sau đến lượt bố. Hãy chia đôi gánh nặng như một đội thực thụ.', title_zh = '来自爸爸的安慰 🫂', body_zh = '夜醒时，你和伴侣轮流起来。作为一个团队，把担子完全平分吧。' WHERE id = 'cc7b8905-a439-46c1-8d92-ea81667052be' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Cuánto camino ha recorrido tu peque! 📈', body_es = 'Los nervios de los primeros días han dado paso a la confianza. Has recorrido este camino con una gran victoria, ¡eres increíble!', title_fr = 'Quel chemin votre enfant a parcouru ! 📈', body_fr = 'L''émotion des premiers jours a laissé place à la confiance. Vous avez fait ce chemin avec une grande victoire, vous êtes formidable !', title_hi = 'आपके बच्चे ने कितना लंबा सफ़र तय किया है! 📈', body_hi = 'शुरुआती दिनों की घबराहट की जगह अब भरोसे ने ले ली है। आपने यह रास्ता बड़ी जीत के साथ तय किया, आप कमाल की हैं!', title_id = 'Betapa jauh si kecil sudah melangkah! 📈', body_id = 'Kecemasan di hari-hari pertama kini berganti dengan rasa percaya diri. Anda melewati perjalanan ini dengan kemenangan besar, Anda luar biasa!', title_ja = '赤ちゃんはなんて長い道のりを歩んできたのでしょう！📈', body_ja = '最初のころのドキドキは、自信に変わりました。あなたはこの道を見事に歩んできました。あなたはすばらしい！', title_ko = '아이가 얼마나 먼 길을 왔는지 보세요! 📈', body_ko = '처음 며칠의 설렘과 긴장이 이제 자신감으로 바뀌었어요. 이 길을 멋지게 승리하며 걸어왔어요, 정말 멋져요!', title_nl = 'Wat heeft je kindje een weg afgelegd!  📈', body_nl = 'De spanning van de eerste dagen heeft plaatsgemaakt voor vertrouwen. Je bent deze weg als een echte winnaar gegaan, je bent geweldig!', title_pl = 'Jak długą drogę przeszedł twój maluszek! 📈', body_pl = 'Ekscytacja pierwszych dni ustąpiła miejsca pewności. Przeszłaś tę drogę jak zwyciężczyni, jesteś wspaniała!', title_pt = 'Que caminho o bebé já percorreu!  📈', body_pt = 'A ansiedade dos primeiros dias deu lugar à confiança. Fez este caminho com uma grande vitória, é fantástica!', title_sv = 'Vilken väg ditt barn har gått!  📈', body_sv = 'Spänningen från de första dagarna har ersatts av trygghet. Du har gått den här vägen med stor seger, du är fantastisk!', title_vi = 'Bé đã đi được một chặng đường dài!  📈', body_vi = 'Sự hồi hộp của những ngày đầu giờ đã thành niềm tin. Mẹ đã đi qua chặng đường này thật thắng lợi, mẹ thật tuyệt vời!', title_zh = '宝宝走了多远的路啊！📈', body_zh = '最初的紧张已经变成了自信。你一路凯歌走到了今天，你太棒了！' WHERE id = '19b97cb2-c4a1-4649-a316-a7b34bb3eed4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Interés por los libros 📖', body_es = 'Incluye libros de papel en la rutina de la noche. Ya intenta pasar las páginas él solo. Adapta tu tono de voz al ritmo del cuento.', title_fr = 'L''intérêt pour les livres 📖', body_fr = 'Intégrez de vrais livres à la routine du soir. Il essaie déjà de tourner les pages tout seul. Adaptez le ton de votre voix au rythme du conte.', title_hi = 'किताबों में दिलचस्पी 📖', body_hi = 'शाम के रूटीन में असली किताबें शामिल कीजिए। वह अब खुद पन्ने पलटने की कोशिश करता है। अपनी आवाज़ का अंदाज़ कहानी की रफ़्तार के हिसाब से ढालिए।', title_id = 'Tertarik pada buku 📖', body_id = 'Masukkan buku fisik ke dalam rutinitas malam. Ia sudah mencoba membalik halaman sendiri. Sesuaikan nada suara Anda dengan tempo dongengnya.', title_ja = '絵本への興味 📖', body_ja = '夜のルーティンに本物の絵本を取り入れましょう。もう自分でページをめくろうとしています。お話のテンポに合わせて、声のトーンを変えてみて。', title_ko = '책에 대한 관심 📖', body_ko = '저녁 루틴에 진짜 책을 더해 보세요. 이제 스스로 책장을 넘기려 해요. 목소리 톤을 이야기의 속도에 맞춰 주세요.', title_nl = 'Interesse in boekjes 📖', body_nl = 'Voeg echte boekjes toe aan de avondroutine. Je baby probeert de bladzijden al zelf om te slaan. Pas je stem aan het tempo van het verhaal aan.', title_pl = 'Zainteresowanie książkami 📖', body_pl = 'Włącz do wieczornej rutyny prawdziwe książeczki. Już sam próbuje przewracać kartki. Dopasuj ton głosu do tempa bajki.', title_pt = 'Interesse pelos livros 📖', body_pt = 'Junte livros de papel à rotina da noite. Ele já tenta virar as páginas sozinho. Ajuste o tom de voz ao ritmo da história.', title_sv = 'Intresse för böcker 📖', body_sv = 'Ta med riktiga böcker i kvällsrutinen. Barnet försöker redan vända sidorna själv. Anpassa din röst efter sagans tempo.', title_vi = 'Yêu thích sách 📖', body_vi = 'Hãy đưa sách giấy vào nếp sinh hoạt buổi tối. Bé đã tự cố lật trang. Điều chỉnh giọng của mẹ theo nhịp câu chuyện nhé.', title_zh = '对书感兴趣 📖', body_zh = '把实体书加入晚间作息吧。宝宝已经想自己翻页了。让你的语调跟上故事的节奏。' WHERE id = '63090d6e-b5fb-4db8-bce4-2e5749468a34' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidad de silencio 🤫', title_fr = 'Besoin de silence 🤫', title_hi = 'खामोशी की ज़रूरत 🤫', title_id = 'Butuh keheningan 🤫', title_ja = '静けさが必要 🤫', title_ko = '고요함이 필요해요 🤫', title_nl = 'Behoefte aan stilte 🤫', title_pl = 'Potrzeba ciszy 🤫', title_pt = 'Necessidade de silêncio 🤫', title_sv = 'Behovet av tystnad 🤫', title_vi = 'Cần sự yên tĩnh 🤫', title_zh = '需要安静 🤫' WHERE id = 'c131d97d-34fe-4f0d-ab19-20860829451c' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pediatra exprés 🤖', title_fr = 'Le pédiatre express 🤖', title_hi = 'झटपट बाल रोग सलाह 🤖', title_id = 'Dokter anak kilat 🤖', title_ja = 'すばやく小児科の知識 🤖', title_ko = '빠른 소아과 상담 🤖', title_nl = 'Een snelle kinderarts 🤖', title_pl = 'Szybki pediatra 🤖', title_pt = 'Pediatra rápido 🤖', title_sv = 'Snabb barnläkare 🤖', title_vi = 'Bác sĩ nhi khoa nhanh chóng 🤖', title_zh = '快速儿科咨询 🤖' WHERE id = '88b776b7-0d43-49f1-b31c-da27294feb6f' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La torre de comida se ha caído 🥣', body_es = '¿Tira a propósito la cuchara o la comida desde la trona y luego te mira? Está poniendo a prueba los límites y la gravedad. Conserva la paciencia.', title_fr = 'La tour de nourriture s''est effondrée 🥣', body_fr = 'Depuis sa chaise, il jette exprès sa cuillère ou sa nourriture par terre, puis vous regarde ? Il teste les limites et la gravité. Gardez votre patience.', title_hi = 'खाने की मीनार गिर गई 🥣', body_hi = 'अपनी कुर्सी से चम्मच या खाना जानबूझकर नीचे फेंकता है और फिर आपको देखता है? वह सीमाओं और गुरुत्वाकर्षण को परख रहा है। धैर्य बनाए रखिए।', title_id = 'Menara makanan runtuh 🥣', body_id = 'Ia sengaja menjatuhkan sendok atau makanan dari kursinya, lalu menatap Anda? Ia sedang menguji batasan dan gravitasi. Jaga kesabaran Anda.', title_ja = 'ごはんのタワーがくずれた 🥣', body_ja = 'ベビーチェアからスプーンやごはんをわざと落として、あなたを見ますか？境界線と重力をテストしているのです。がまん強くいきましょう。', title_ko = '음식 탑이 무너졌어요 🥣', body_ko = '의자에서 숟가락이나 음식을 일부러 떨어뜨리고 엄마를 바라보나요? 경계와 중력을 시험하는 중이에요. 인내심을 지켜 주세요.', title_nl = 'De eettoren is ingestort 🥣', body_nl = 'Gooit je baby expres zijn lepel of eten van zijn stoel en kijkt hij je daarna aan? Hij test grenzen en de zwaartekracht. Bewaar je geduld.', title_pl = 'Wieża z jedzenia runęła 🥣', body_pl = 'Celowo zrzuca z krzesełka łyżeczkę albo jedzenie, a potem patrzy na ciebie? Testuje granice i grawitację. Zachowaj cierpliwość.', title_pt = 'A torre de comida caiu 🥣', body_pt = 'Atira de propósito a colher ou a comida da cadeira e depois olha para si? Está a testar os limites e a gravidade. Mantenha a paciência.', title_sv = 'Mattornet rasade 🥣', body_sv = 'Kastar barnet med flit ner skeden eller maten från stolen och tittar sedan på dig? Det testar gränserna och tyngdkraften. Behåll ditt tålamod.', title_vi = 'Tháp đồ ăn sụp đổ 🥣', body_vi = 'Bé cố tình ném thìa hay đồ ăn từ ghế xuống đất rồi nhìn mẹ? Bé đang thử giới hạn và lực hấp dẫn. Hãy giữ bình tĩnh nhé.', title_zh = '食物高塔倒啦 🥣', body_zh = '宝宝故意从餐椅上把勺子或食物扔到地上，再看着你？宝宝在测试边界和重力。保持耐心吧。' WHERE id = '64ab60a5-a744-4f7e-a8a1-28b04eede9d6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tu cuerpo que cambia 👗', body_es = '¿Te entristece mirar tus formas en el espejo? Con ese cuerpo has creado a una persona. Escríbete un mensaje de agradecimiento en el Diario de ánimo.', title_fr = 'Votre corps qui change 👗', body_fr = 'Les courbes de votre corps dans le miroir vous rendent triste ? Avec ce corps, vous avez créé un être humain. Écrivez-vous un message de remerciement dans le Journal d''humeur.', title_hi = 'आपका बदलता शरीर 👗', body_hi = 'आईने में अपने शरीर को देखकर उदास होती हैं? आपने इसी शरीर से एक इंसान को जन्म दिया है। मूड डायरी में खुद को धन्यवाद का संदेश लिखिए।', title_id = 'Tubuh Anda yang berubah 👗', body_id = 'Sedih melihat lekuk tubuh Anda di cermin? Dengan tubuh itulah Anda menciptakan seorang manusia. Tulis pesan terima kasih untuk diri sendiri di Buku Harian Suasana Hati.', title_ja = '変わっていく体 👗', body_ja = '鏡に映る体のラインを見て落ちこんでいますか？あなたはその体でひとりの人間を生み出しました。「気分日記」に自分へのありがとうのメッセージを書きましょう。', title_ko = '변화한 몸 👗', body_ko = '거울 속 몸의 선을 보며 속상한가요? 그 몸으로 한 사람을 만들어 냈어요. 기분 일기에 나에게 고맙다는 메시지를 적어 보세요.', title_nl = 'Je veranderde lichaam 👗', body_nl = 'Word je verdrietig als je in de spiegel naar je lichaam kijkt? Met dat lichaam heb je een mens gemaakt. Schrijf een bedankje aan jezelf in je Stemmingsdagboek.', title_pl = 'Twoje zmieniające się ciało 👗', body_pl = 'Smucisz się, patrząc na linie ciała w lustrze? Tym ciałem stworzyłaś człowieka. Napisz w Dzienniku nastroju podziękowanie dla siebie.', title_pt = 'O seu corpo em mudança 👗', body_pt = 'Fica triste ao olhar para as linhas do seu corpo ao espelho? Foi com esse corpo que criou um ser humano. Escreva no Diário de Humor uma mensagem de agradecimento a si própria.', title_sv = 'Din kropp som förändras 👗', body_sv = 'Blir du ledsen när du ser kroppens linjer i spegeln? Med den kroppen har du skapat en människa. Skriv ett tackmeddelande till dig själv i Humördagboken.', title_vi = 'Cơ thể thay đổi của mẹ 👗', body_vi = 'Nhìn những đường nét cơ thể trong gương mà mẹ thấy buồn? Mẹ đã tạo ra một con người bằng chính cơ thể ấy. Hãy viết một lời cảm ơn gửi chính mình vào Nhật ký tâm trạng.', title_zh = '你变化的身体 👗', body_zh = '看着镜子里的身材线条感到难过？你用这具身体创造了一个生命。在心情日记里给自己写一句感谢的话吧。' WHERE id = 'cd288f90-d6da-4851-9b9a-2a8e15ba81fb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Heroína silenciosa 🤫', body_es = 'En cuanto se duerme, cada ruido de casa suena como una bomba. Mientras estabilizas el límite de la habitación con el Medidor de sonido, pisa tú también con suavidad.', title_fr = 'Le héros silencieux 🤫', body_fr = 'Au moment où il s''endort, chaque bruit de la maison résonne comme une explosion. Pendant que vous stabilisez le niveau sonore avec le Sonomètre, allégez aussi vos propres pas.', title_hi = 'खामोश हीरो 🤫', body_hi = 'उसके सोते ही घर की हर आवाज़ बम फटने जैसी लगती है। साउंड मीटर से कमरे की आवाज़ की सीमा तय करते हुए अपने कदम भी हल्के रखिए।', title_id = 'Pahlawan tanpa suara 🤫', body_id = 'Saat ia mulai tertidur, setiap suara di rumah terdengar seperti ledakan bom. Sambil menstabilkan batas suara kamar dengan Pengukur Suara, pelankan juga langkah Anda.', title_ja = '静かなヒーロー 🤫', body_ja = '寝ついたとたん、家のどんな音も爆発のように聞こえます。「サウンドメーター」で部屋の音を一定に保ちながら、あなたの足音もそっと軽くしましょう。', title_ko = '소리 없는 영웅 🤫', body_ko = '아기가 잠드는 순간 집 안의 모든 소리가 폭탄처럼 느껴지죠. 소음 측정기로 방의 소리 한도를 맞추면서 엄마의 발걸음도 살살 가볍게 해 주세요.', title_nl = 'Een stille heldin 🤫', body_nl = 'Zodra je baby in slaap valt, klinkt elk geluid in huis als een bom. Houd met de Geluidsmeter de kamer binnen de grens en zet ook zelf zachtere stappen.', title_pl = 'Cichy bohater 🤫', body_pl = 'Gdy tylko zaśnie, każdy dźwięk w domu brzmi jak wybuch bomby. Ustawiając limit w pokoju Miernikiem dźwięku, stąpaj też lżej.', title_pt = 'A heroína silenciosa 🤫', body_pt = 'Mal adormece, qualquer som da casa parece uma explosão. Enquanto estabiliza o limite do quarto com o Medidor de Som, ande também com passos leves.', title_sv = 'Den tysta hjälten 🤫', body_sv = 'Så fort barnet somnar låter varje ljud hemma som en bombexplosion. Medan du håller rummets ljudnivå jämn med Ljudmätaren, gå också lite lättare på foten.', title_vi = 'Người hùng thầm lặng 🤫', body_vi = 'Ngay khi bé ngủ, mọi tiếng động trong nhà đều như tiếng bom nổ. Khi điều chỉnh ngưỡng âm thanh trong phòng bằng Đo âm thanh, mẹ cũng nhớ bước chân nhẹ nhàng hơn nhé.', title_zh = '安静的英雄 🤫', body_zh = '宝宝刚睡着时，家里任何声音都像炸弹爆炸一样。用噪音测量稳定房间的音量上限，同时也放轻你自己的脚步吧。' WHERE id = '0e1a794c-f019-4037-b108-0a10db7b5f9f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Detective de armarios 🕵️‍♀️', body_es = '¿Todas las ollas de la cocina están en el suelo? Déjale, jugar con objetos inofensivos desarrolla su pensamiento lógico. Solo aparta las cosas afiladas.', title_fr = 'La détective des placards 🕵️‍♀️', body_fr = 'Toutes les casseroles de la cuisine sont par terre ? Laissez faire, jouer avec des objets sans danger développe sa pensée logique. Éloignez simplement les objets tranchants.', title_hi = 'अलमारी का जासूस 🕵️‍♀️', body_hi = 'रसोई के सारे बर्तन फ़र्श पर हैं? खेलने दीजिए, सुरक्षित चीज़ों से खेलना उसकी तार्किक सोच बढ़ाता है। बस नुकीली चीज़ें दूर रखिए।', title_id = 'Detektif lemari 🕵️‍♀️', body_id = 'Semua panci di dapur berserakan di lantai? Biarkan saja, bermain dengan benda yang aman mengembangkan kemampuan berpikir logisnya. Cukup jauhkan benda tajam.', title_ja = '戸棚の探偵 🕵️‍♀️', body_ja = 'キッチンの鍋がぜんぶ床に？遊ばせてあげましょう。安全なもので遊ぶことは、論理的に考える力を育てます。とがったものだけは遠ざけて。', title_ko = '수납장 탐정 🕵️‍♀️', body_ko = '주방의 냄비가 모두 바닥에 나와 있나요? 허락해 주세요, 안전한 물건으로 노는 건 논리적 사고를 키워 줘요. 날카로운 물건만 치워 두세요.', title_nl = 'Kastdetective 🕵️‍♀️', body_nl = 'Liggen alle pannen uit de keuken op de vloer? Laat maar, spelen met onschuldige spullen ontwikkelt zijn logisch denken. Leg alleen scherpe dingen buiten bereik.', title_pl = 'Detektyw szafek 🕵️‍♀️', body_pl = 'Wszystkie garnki z kuchni na podłodze? Pozwól mu, zabawa bezpiecznymi przedmiotami rozwija logiczne myślenie. Tylko odsuń ostre rzeczy.', title_pt = 'Detetive dos armários 🕵️‍♀️', body_pt = 'Os tachos da cozinha estão todos no chão? Deixe: brincar com objetos inofensivos desenvolve o raciocínio lógico. Afaste apenas os objetos afiados.', title_sv = 'Skåpsdetektiven 🕵️‍♀️', body_sv = 'Står alla kastruller från köket på golvet? Låt det vara, att leka med ofarliga saker utvecklar barnets logiska tänkande. Plocka bara undan vassa saker.', title_vi = 'Thám tử tủ bếp 🕵️‍♀️', body_vi = 'Nồi niêu trong bếp nằm hết dưới sàn? Cứ để bé chơi, chơi với những đồ vật an toàn giúp phát triển tư duy logic. Chỉ cần cất các vật sắc nhọn đi.', title_zh = '柜子侦探 🕵️‍♀️', body_zh = '厨房里的锅全到了地上？让宝宝玩吧，玩无害的物品能促进逻辑思维。只要把尖锐的东西拿开就好。' WHERE id = 'cb2d76e0-4e92-41f1-9153-3b4a29404a17' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Complicidad entre mamás 💬', body_es = '¿Te come la cabeza pensar «por qué mi bebé todavía no gatea»? Escríbelo en la Comunidad Anacan. Verás que cada peque tiene su propio ritmo perfecto.', title_fr = 'Confidences entre mamans 💬', body_fr = 'Des questions comme « Pourquoi mon enfant ne rampe-t-il toujours pas ? » vous rongent ? Écrivez dans la Communauté Anacan. Vous verrez que chaque enfant a son propre rythme parfait.', title_hi = 'माँओं का भरोसे का दायरा 💬', body_hi = '''मेरा बच्चा अभी तक क्यों नहीं खिसकता?'' जैसे सवाल आपको खाए जा रहे हैं? Anacan कम्युनिटी में लिखिए। आप देखेंगी कि हर बच्चे की अपनी परफ़ेक्ट रफ़्तार होती है।', title_id = 'Teman curhat para ibu 💬', body_id = 'Pertanyaan seperti "Kenapa anakku belum merayap?" terus menghantui? Tulis di Komunitas Anacan. Anda akan melihat bahwa setiap anak punya tempo sempurnanya sendiri.', title_ja = 'ママたちの打ち明け話 💬', body_ja = '「どうしてうちの子はまだはいはいしないの？」という疑問が頭から離れない？Anacanコミュニティに書きこんでみましょう。どの子にもその子だけの完璧なペースがあるとわかります。', title_ko = '엄마들의 속마음 나누기 💬', body_ko = '''우리 아이는 왜 아직 안 길까?'' 같은 질문이 머리를 떠나지 않나요? Anacan 커뮤니티에 글을 남겨 보세요. 모든 아이에게는 저마다의 완벽한 속도가 있다는 걸 알게 될 거예요.', title_nl = 'Moeders onder elkaar 💬', body_nl = 'Spookt de vraag door je hoofd waarom je kindje nog niet kruipt? Schrijf erover in de Anacan Community. Je zult zien dat elk kind zijn eigen perfecte tempo heeft.', title_pl = 'Mamy powierniczki 💬', body_pl = 'Nie dają ci spokoju pytania typu „dlaczego moje dziecko jeszcze nie raczkuje?”. Napisz w Społeczności Anacan. Zobaczysz, że każde dziecko ma swoje idealne tempo.', title_pt = 'A cumplicidade das mães 💬', body_pt = 'Perguntas como "porque é que o meu bebé ainda não rasteja?" não lhe saem da cabeça? Escreva na Comunidade Anacan. Vai ver que cada criança tem o seu ritmo perfeito.', title_sv = 'Mammornas förtroende 💬', body_sv = 'Äter frågor som ''varför kryper mitt barn fortfarande inte?'' upp dig? Skriv i Anacans Community. Du kommer att se att varje barn har sitt eget perfekta tempo.', title_vi = 'Tâm sự giữa các bà mẹ 💬', body_vi = 'Những câu hỏi như "Sao con mình vẫn chưa trườn?" cứ làm mẹ bận lòng? Hãy viết vào Cộng đồng Anacan. Mẹ sẽ thấy mỗi em bé đều có nhịp phát triển hoàn hảo của riêng mình.', title_zh = '妈妈们的知心话 💬', body_zh = '“我的宝宝为什么还不会爬”这样的问题一直在脑子里转？发到Anacan社区吧。你会发现每个孩子都有自己完美的节奏。' WHERE id = 'd194240e-ae66-4f32-83ef-39ade449ccb6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pediatra exprés 🤖', body_es = '¿Tiene pequeñas rojeces en el cuerpo? Antes de ir al médico, pide a Anacan AI información rápida sobre los signos de alergia alimentaria.', title_fr = 'Le pédiatre express 🤖', body_fr = 'Il a de petites rougeurs sur le corps ? Avant d''aller chez le médecin, obtenez rapidement d''Anacan AI des informations sur les signes d''allergie alimentaire.', title_hi = 'झटपट बाल रोग सलाह 🤖', body_hi = 'बच्चे के शरीर पर छोटे लाल दाने हैं? डॉक्टर के पास जाने से पहले Anacan AI से खाने की एलर्जी के लक्षणों के बारे में तुरंत जानकारी लीजिए।', title_id = 'Dokter anak kilat 🤖', body_id = 'Ada bintik-bintik merah kecil di tubuhnya? Sebelum ke dokter, dapatkan informasi cepat tentang tanda-tanda alergi makanan dari Anacan AI.', title_ja = 'すばやく小児科の知識 🤖', body_ja = '赤ちゃんの体に小さな赤いぽつぽつがある？お医者さんに行く前に、Anacan AIで食物アレルギーのサインについてすぐに調べましょう。', title_ko = '빠른 소아과 상담 🤖', body_ko = '아이 몸에 작은 붉은 반점이 있나요? 병원에 가기 전에 Anacan AI에게서 음식 알레르기 증상에 대한 정보를 빠르게 받아 보세요.', title_nl = 'Een snelle kinderarts 🤖', body_nl = 'Heeft je kindje kleine rode vlekjes op zijn lijfje? Krijg voordat je naar de arts gaat snel informatie van Anacan AI over de tekenen van voedselallergie.', title_pl = 'Szybki pediatra 🤖', body_pl = 'Na ciele maluszka pojawiły się drobne zaczerwienienia? Zanim pójdziesz do lekarza, szybko dowiedz się od Anacan AI o objawach alergii pokarmowej.', title_pt = 'Pediatra rápido 🤖', body_pt = 'O bebé tem pequenas vermelhidões no corpo? Antes de ir ao médico, receba rapidamente do Anacan AI informação sobre os sinais de alergia alimentar.', title_sv = 'Snabb barnläkare 🤖', body_sv = 'Har barnet små röda prickar på kroppen? Innan du går till läkaren, få snabb information om tecken på födoämnesallergi från Anacan AI.', title_vi = 'Bác sĩ nhi khoa nhanh chóng 🤖', body_vi = 'Trên người bé có những nốt đỏ nhỏ? Trước khi đi khám, hãy hỏi Anacan AI để nhanh chóng biết các dấu hiệu dị ứng thực phẩm.', title_zh = '快速儿科咨询 🤖', body_zh = '宝宝身上有些小红疹？去看医生之前，先向Anacan AI快速了解一下食物过敏的症状吧。' WHERE id = '12c2a250-54bd-4e0d-a366-20c820596148' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reacciona a su nombre 🗣️', body_es = 'Cuando le llamas, no solo te mira, sino que deja lo que está haciendo e intenta venir hacia ti.', title_fr = 'Il réagit à son prénom 🗣️', body_fr = 'Quand vous l''appelez, non seulement il regarde, mais il laisse même ce qu''il fait pour essayer de venir vers vous.', title_hi = 'नाम पर प्रतिक्रिया 🗣️', body_hi = 'पुकारने पर वह न सिर्फ़ देखता है, बल्कि अपना काम छोड़कर आपकी ओर आने की कोशिश भी करता है।', title_id = 'Bereaksi saat dipanggil 🗣️', body_id = 'Saat dipanggil, ia tak hanya menoleh, bahkan meninggalkan kegiatannya dan mencoba datang ke arah Anda.', title_ja = '名前に反応 🗣️', body_ja = '呼ぶと見るだけでなく、していることをやめてあなたのほうへ来ようとします。', title_ko = '이름에 반응해요 🗣️', body_ko = '이름을 부르면 바라볼 뿐 아니라 하던 일을 멈추고 엄마에게 오려고 해요.', title_nl = 'Hij reageert op zijn naam 🗣️', body_nl = 'Als je hem roept, kijkt hij niet alleen op, maar laat hij zelfs alles vallen en probeert hij naar je toe te komen.', title_pl = 'Reaguje na swoje imię 🗣️', body_pl = 'Gdy go wołasz, nie tylko patrzy, ale nawet przerywa zabawę i próbuje do ciebie przyjść.', title_pt = 'Reage ao nome 🗣️', body_pt = 'Quando o chama, não só olha como até larga o que está a fazer e tenta vir ter consigo.', title_sv = 'Reagerar på sitt namn 🗣️', body_sv = 'När du ropar tittar barnet inte bara upp, utan släpper till och med det det håller på med och försöker ta sig fram till dig.', title_vi = 'Phản ứng khi được gọi tên 🗣️', body_vi = 'Khi mẹ gọi, bé không chỉ nhìn mà còn bỏ dở việc đang làm để cố đi về phía mẹ.', title_zh = '对名字有反应 🗣️', body_zh = '叫宝宝的名字时，宝宝不仅会看过来，还会放下手里的事朝你过来。' WHERE id = '7b4d66d9-a24a-47b0-a1dd-7047f05e45ec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baja las luces 🌙', body_es = 'Una hora antes de dormir, apaga todas las luces fuertes y las pantallas de casa. La melatonina solo se segrega en un ambiente tranquilo y con poca luz.', title_fr = 'Baissez les lumières 🌙', body_fr = '1 heure avant le coucher, éteignez toutes les lumières vives et les écrans de la maison. La mélatonine n''est sécrétée que dans un environnement calme et peu éclairé.', title_hi = 'लाइटें धीमी कीजिए 🌙', body_hi = 'सोने से 1 घंटा पहले घर की सारी तेज़ लाइटें और स्क्रीन बंद कर दीजिए। मेलाटोनिन शांत और कम रोशनी वाले माहौल में ही बनता है।', title_id = 'Redupkan lampu 🌙', body_id = 'Satu jam sebelum tidur, matikan semua lampu terang dan layar di rumah. Melatonin hanya diproduksi di lingkungan yang tenang dan redup.', title_ja = '明かりを落として 🌙', body_ja = '寝る1時間前には、家の強い明かりや画面をすべて消しましょう。メラトニンは、静かで明かりの少ない環境でこそ分泌されます。', title_ko = '조명을 낮춰요 🌙', body_ko = '잠들기 1시간 전에 집 안의 밝은 조명과 화면을 모두 끄세요. 멜라토닌은 조용하고 어두운 환경에서만 분비돼요.', title_nl = 'Doe de lichten zachter 🌙', body_nl = 'Doe 1 uur voor het slapengaan alle felle lampen en schermen in huis uit. Melatonine wordt alleen in een rustige omgeving met weinig licht aangemaakt.', title_pl = 'Przyciemnij światła 🌙', body_pl = 'Na godzinę przed snem wyłącz w domu wszystkie mocne światła i ekrany. Melatonina wydziela się tylko w spokojnym, słabo oświetlonym otoczeniu.', title_pt = 'Baixe as luzes 🌙', body_pt = '1 hora antes de dormir, apague as luzes desnecessárias e os ecrãs da casa. A melatonina só é produzida num ambiente calmo e com pouca luz.', title_sv = 'Dämpa ljuset 🌙', body_sv = 'Släck alla starka lampor och skärmar hemma 1 timme innan läggdags. Melatonin utsöndras bara i en lugn och svagt upplyst miljö.', title_vi = 'Giảm ánh sáng 🌙', body_vi = '1 tiếng trước giờ ngủ, hãy tắt hết đèn sáng và màn hình trong nhà. Melatonin chỉ được tiết ra trong môi trường yên tĩnh và ít ánh sáng.', title_zh = '调暗灯光 🌙', body_zh = '睡前1小时关掉家里所有的强光和屏幕。褪黑素只有在安静、光线昏暗的环境里才会分泌。' WHERE id = 'c7423d2f-6f9f-452c-9de2-5dea29b29f93' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Libera tu conciencia 📝', body_es = '¿Piensas que hoy has jugado poco con tu peque? 10 minutos de calidad valen más que 1 hora con cansancio.', title_fr = 'Libérez votre conscience 📝', body_fr = 'Vous pensez ne pas avoir assez joué avec lui aujourd''hui ? 10 minutes de qualité valent mieux qu''1 heure de fatigue.', title_hi = 'मन का बोझ उतारिए 📝', body_hi = 'सोचती हैं कि आज उसके साथ कम खेलीं? अच्छे से बिताए 10 मिनट थकान भरे 1 घंटे से ज़्यादा कीमती हैं।', title_id = 'Lepaskan rasa bersalah 📝', body_id = 'Merasa hari ini kurang bermain dengannya? 10 menit yang berkualitas lebih berharga daripada 1 jam dalam keadaan lelah.', title_ja = '罪悪感を手放して 📝', body_ja = '「今日はあまり遊んであげられなかった」と思っていますか？質のいい10分は、疲れた1時間よりも価値があります。', title_ko = '죄책감을 내려놓아요 📝', body_ko = '''오늘 아이와 별로 못 놀아 줬어''라고 생각하나요? 지친 1시간보다 집중한 10분이 더 소중해요.', title_nl = 'Laat je schuldgevoel los 📝', body_nl = 'Denk je dat je vandaag te weinig met hem hebt gespeeld? 10 minuten echte aandacht zijn meer waard dan een vermoeid uur.', title_pl = 'Uwolnij sumienie 📝', body_pl = 'Myślisz, że dziś za mało się z nim bawiłaś? 10 dobrych minut jest cenniejsze niż zmęczona godzina.', title_pt = 'Liberte a consciência 📝', body_pt = 'Acha que hoje brincou pouco com ele? 10 minutos de qualidade valem mais do que 1 hora cansada.', title_sv = 'Släpp samvetet fritt 📝', body_sv = 'Tycker du att du har lekt för lite med barnet i dag? 10 minuter av kvalitet är värda mer än en trött timme.', title_vi = 'Hãy để lương tâm được nhẹ nhõm 📝', body_vi = 'Mẹ nghĩ hôm nay mình chơi với bé quá ít? 10 phút chất lượng quý hơn 1 tiếng mệt mỏi.', title_zh = '放下内疚 📝', body_zh = '觉得今天陪宝宝玩得太少了？高质量的10分钟，胜过疲惫的1小时。' WHERE id = '100bd53c-84e3-4c7e-8a31-2a287a02c440' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te estreses por el desorden de casa. 🌪️', body_es = 'Tu prioridad no es una casa perfecta, sino un bebé sano y feliz. Relájate.', title_fr = 'Pas de stress pour le désordre 🌪️', body_fr = 'Votre priorité n''est pas une maison parfaite, mais un bébé en bonne santé et heureux. Détendez-vous.', title_hi = 'घर बिखरा है तो तनाव मत लीजिए 🌪️', body_hi = 'आपकी प्राथमिकता एकदम सही घर नहीं, बल्कि एक सेहतमंद और खुश बच्चा है। आराम कीजिए।', title_id = 'Jangan stres karena rumah berantakan. 🌪️', body_id = 'Prioritas Anda bukan rumah yang sempurna, melainkan bayi yang sehat dan bahagia. Santai saja.', title_ja = '家が散らかっていても気にしないで。🌪️', body_ja = '大切なのは完璧な家ではなく、健康で幸せな赤ちゃんです。肩の力を抜きましょう。', title_ko = '집이 어질러져도 스트레스받지 마세요. 🌪️', body_ko = '가장 중요한 건 완벽한 집이 아니라 건강하고 행복한 아기예요. 편하게 마음먹으세요.', title_nl = 'Geen stress om een rommelig huis. 🌪️', body_nl = 'Je prioriteit is geen perfect huis, maar een gezonde en blije baby. Ontspan.', title_pl = 'Nie stresuj się bałaganem w domu. 🌪️', body_pl = 'Twoim priorytetem nie jest idealny dom, tylko zdrowy i szczęśliwy maluszek. Odpręż się.', title_pt = 'Não se stresse por a casa estar desarrumada. 🌪️', body_pt = 'A sua prioridade não é uma casa perfeita, é um bebé saudável e feliz. Relaxe.', title_sv = 'Stressa inte över att det är stökigt hemma. 🌪️', body_sv = 'Det viktigaste är inte ett perfekt hem utan ett friskt och glatt barn. Slappna av.', title_vi = 'Nhà bừa bộn cũng đừng căng thẳng. 🌪️', body_vi = 'Ưu tiên của mẹ không phải là một ngôi nhà hoàn hảo, mà là một em bé khỏe mạnh và hạnh phúc. Thư giãn đi mẹ.', title_zh = '家里乱也别焦虑 🌪️', body_zh = '你的首要任务不是完美的家，而是一个健康快乐的宝宝。放轻松。' WHERE id = '15b0ec22-2156-4080-ad64-7a588de85fc5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lluvia de risas 😂', body_es = '¿Responde a tus gestos cariñosos con sonoras carcajadas? No dejes de grabar ese sonido en vídeo.', title_fr = 'Des éclats de rire 😂', body_fr = 'Il répond à vos mimiques par de grands éclats de rire ? Filmez absolument ce son en vidéo.', title_hi = 'हँसी की गूँज 😂', body_hi = 'आपकी प्यारी हरकतों पर वह खिलखिलाकर हँसता है? इस आवाज़ को वीडियो में ज़रूर रिकॉर्ड कीजिए।', title_id = 'Gelak tawa riang 😂', body_id = 'Ia membalas tingkah lucu Anda dengan tawa keras? Jangan lupa rekam suara ini dalam video.', title_ja = '笑い声があふれる 😂', body_ja = 'あなたのかわいいしぐさに、声をあげて笑ってくれますか？この声をぜひ動画に残しておきましょう。', title_ko = '까르르 웃음소리 😂', body_ko = '엄마의 귀여운 행동에 소리 내어 깔깔 웃나요? 이 소리를 꼭 영상으로 남겨 두세요.', title_nl = 'Schaterlachjes 😂', body_nl = 'Reageert je kleintje met een luide schaterlach op je grappige gebaren? Leg dit geluid zeker vast op video.', title_pl = 'Salwy śmiechu 😂', body_pl = 'Na twoje słodkie zabawy odpowiada głośnym śmiechem? Koniecznie nagraj ten dźwięk na wideo.', title_pt = 'Ecos de gargalhadas 😂', body_pt = 'Responde aos seus gestos ternos com gargalhadas? Grave este som em vídeo sem falta.', title_sv = 'Skrattsalvor 😂', body_sv = 'Svarar barnet på dina gulliga påhitt med högljudda skratt? Spela absolut in det ljudet på video.', title_vi = 'Tiếng cười giòn tan 😂', body_vi = 'Bé đáp lại những trò đáng yêu của mẹ bằng tràng cười thành tiếng? Nhất định phải quay video lại âm thanh này nhé.', title_zh = '笑声不断 😂', body_zh = '你做个可爱的动作，宝宝就咯咯大笑？一定要把这笑声录成视频留下来。' WHERE id = 'f2dc5d57-91a4-45de-b81b-0b2998a8593b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una foto que detiene el tiempo 📸', body_es = 'Cada día parece un poco más niño y sus rasgos de bebé se van. Abre ya la Sesión de fotos del bebé y captura este cambio.', title_fr = 'La photo qui arrête le temps 📸', body_fr = 'Chaque jour, il ressemble un peu plus à un enfant et ses traits de bébé s''effacent. Ouvrez tout de suite la Séance photo bébé et immortalisez ce changement.', title_hi = 'समय को थाम लेने वाली तस्वीर 📸', body_hi = 'वह हर दिन थोड़ा और बच्चे जैसा दिखता है, शिशु वाली बनावट जा रही है। तुरंत बेबी फ़ोटोशूट खोलिए और उसके इस बदलाव को कैद कीजिए।', title_id = 'Foto yang menghentikan waktu 📸', body_id = 'Setiap hari ia makin terlihat seperti anak-anak, raut bayinya mulai menghilang. Segera buka Sesi Foto Bayi dan abadikan perubahannya.', title_ja = '時間を止める1枚 📸', body_ja = '日に日に赤ちゃんらしさが消えて、子どもらしい顔つきになっていきます。すぐに「ベビーフォトセッション」を開いて、この変化を写真に残しましょう。', title_ko = '시간을 멈추는 한 컷 📸', body_ko = '아기가 날마다 조금씩 더 어린이처럼 보이고 아기 티가 사라져 가요. 지금 바로 아기 사진 촬영을 열어 이 변화를 담아 두세요.', title_nl = 'Een foto die de tijd stilzet 📸', body_nl = 'Elke dag lijkt hij meer op een kind en verdwijnen de babytrekjes. Open meteen Babyfotoshoot en leg deze verandering vast.', title_pl = 'Kadr, który zatrzymuje czas 📸', body_pl = 'Z każdym dniem wygląda trochę bardziej jak dziecko, a niemowlęce rysy znikają. Od razu otwórz Sesję zdjęciową dziecka i uwiecznij tę przemianę.', title_pt = 'Uma foto que para o tempo 📸', body_pt = 'A cada dia parece um pouco mais uma criança e os traços de bebé vão desaparecendo. Abra já a Sessão Fotográfica do Bebé e fotografe esta mudança.', title_sv = 'Bilden som stoppar tiden 📸', body_sv = 'För varje dag ser barnet lite mer ut som ett barn och bebisdragen försvinner. Öppna Babyfotografering direkt och fånga den här förändringen.', title_vi = 'Khoảnh khắc ngưng đọng thời gian 📸', body_vi = 'Mỗi ngày bé trông càng giống một đứa trẻ hơn, nét em bé dần mất đi. Hãy mở ngay Chụp ảnh cho bé và ghi lại sự thay đổi này.', title_zh = '定格时光 📸', body_zh = '宝宝一天比一天更像个小孩子，婴儿的模样渐渐褪去。马上打开宝宝写真，记录下这些变化吧。' WHERE id = '42ea49cf-0e72-4699-aaf4-7633e9ea6a82' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dedo que señala está activo ☝️', body_es = 'Señala con el dedo un gato o un juguete lejano y reacciona. Es el nivel más alto para dirigir la atención.', title_fr = 'Le doigt qui montre est actif ☝️', body_fr = 'Il montre du doigt un chat ou un jouet éloigné et réagit. C''est le plus haut niveau d''attention partagée.', title_hi = 'इशारा करने वाली उँगली चालू है ☝️', body_hi = 'दूर की बिल्ली या खिलौने की ओर उँगली से इशारा करके प्रतिक्रिया देता है। यह ध्यान दिलाने का सबसे ऊँचा पड़ाव है।', title_id = 'Jari telunjuk aktif ☝️', body_id = 'Ia menunjuk kucing atau mainan yang jauh dengan jarinya dan bereaksi. Ini tahap tertinggi dalam mengarahkan perhatian.', title_ja = '指さしが活発に ☝️', body_ja = '遠くのネコやおもちゃを指さして反応していますか？注意を向けさせる力の、いちばん高い段階です。', title_ko = '손가락 가리키기 시작 ☝️', body_ko = '멀리 있는 고양이나 장난감을 손가락으로 가리키며 반응해요. 관심을 이끄는 능력의 가장 높은 단계예요.', title_nl = 'De wijsvinger is actief ☝️', body_nl = 'Je baby wijst met zijn vinger naar een kat of speeltje verderop en reageert. Dat is de hoogste fase van aandacht richten.', title_pl = 'Palec wskazujący w akcji ☝️', body_pl = 'Pokazuje palcem odległego kota albo zabawkę i reaguje. To najwyższy etap kierowania uwagi.', title_pt = 'O dedo que aponta está ativo ☝️', body_pt = 'Aponta com o dedo para o gato ou para um brinquedo ao longe e reage. É a fase mais avançada de direcionar a atenção.', title_sv = 'Pekfingret är aktivt ☝️', body_sv = 'Barnet pekar med fingret på katten eller leksaken långt bort och reagerar. Det är den högsta nivån av att styra uppmärksamheten.', title_vi = 'Ngón tay chỉ trỏ đã hoạt động ☝️', body_vi = 'Bé chỉ tay vào chú mèo hay đồ chơi ở xa và phản ứng. Đây là mức cao nhất của khả năng hướng sự chú ý.', title_zh = '开始用手指指东西 ☝️', body_zh = '宝宝用手指指着远处的猫或玩具，还会做出反应。这是引导注意力的最高阶段。' WHERE id = '29cc3dd1-d28b-45c9-93d7-58bfda48629c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Parque o casa? ⛅', body_es = 'Quieres salir, pero hace viento. Deja que el asistente Tiempo y ropa te diga no solo cuántos grados hace, sino también qué ponerle para que no le pase el viento.', title_fr = 'Parc ou maison ? ⛅', body_fr = 'Vous voulez sortir, mais il y a du vent ? L''assistant Météo et tenue vous indique non seulement la température, mais aussi quoi lui mettre pour le protéger du vent.', title_hi = 'पार्क या घर? ⛅', body_hi = 'बाहर जाना चाहती हैं, पर हवा चल रही है। मौसम और कपड़े टूल आपको सिर्फ़ तापमान ही नहीं, यह भी बताएगा कि हवा से बचाने वाले कौन से कपड़े पहनाएँ।', title_id = 'Taman atau rumah? ⛅', body_id = 'Ingin keluar, tapi berangin? Biarkan asisten Cuaca dan Pakaian memberi tahu bukan hanya suhunya, tapi juga pakaian tahan angin yang perlu dipakai.', title_ja = '公園？それともおうち？⛅', body_ja = '外に出たいけれど、風がある。「天気と服装」アシスタントが、気温だけでなく風を通さない服装まで教えてくれます。', title_ko = '공원일까요, 집일까요? ⛅', body_ko = '나가고 싶은데 바람이 부나요? 날씨와 옷차림 도우미가 기온뿐 아니라 바람을 막아 줄 옷차림까지 알려 줄 거예요.', title_nl = 'Park of thuis? ⛅', body_nl = 'Wil je naar buiten, maar waait het? Laat de assistent Weer en kleding je niet alleen vertellen hoeveel graden het is, maar ook wat je baby aan moet tegen de wind.', title_pl = 'Park czy dom? ⛅', body_pl = 'Chcesz wyjść, ale wieje? Niech pomocnik Pogoda i ubiór powie ci nie tylko, ile jest stopni, ale też w co go ubrać, żeby nie przewiało.', title_pt = 'Parque ou casa? ⛅', body_pt = 'Quer sair, mas está vento? Deixe o assistente Tempo e Roupa dizer-lhe não só quantos graus estão, mas também que roupa corta-vento lhe deve vestir.', title_sv = 'Park eller hemma? ⛅', body_sv = 'Vill ni gå ut, men det blåser? Låt Väder och kläder inte bara berätta hur många grader det är, utan också vilka vindtäta kläder barnet ska ha.', title_vi = 'Công viên hay ở nhà? ⛅', body_vi = 'Mẹ muốn ra ngoài nhưng trời có gió? Hãy để Trợ lý thời tiết và trang phục không chỉ cho biết nhiệt độ mà còn gợi ý nên mặc gì để chắn gió cho bé.', title_zh = '去公园还是待在家？⛅', body_zh = '想出门，可是外面有风？让天气穿衣助手不仅告诉你多少度，还告诉你该给宝宝穿什么防风的衣服。' WHERE id = '6eab5294-c731-4890-971d-ad01e35f7d7c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las caras graciosas de papá 🤡', body_es = 'La mejor forma de hacer reír al bebé es que papá haga ruidos raros. Guarda los momentos alegres de esta noche con la Sesión de fotos del bebé.', title_fr = 'Les grimaces de papa 🤡', body_fr = 'Le meilleur moyen de faire rire bébé, ce sont les bruits bizarres de papa. Immortalisez les joyeux moments de ce soir avec la Séance photo bébé.', title_hi = 'पापा के मज़ेदार चेहरे 🤡', body_hi = 'बच्चे को हँसाने का सबसे अच्छा तरीका है पापा की अजीब आवाज़ें। आज शाम के खुशी भरे पलों को बेबी फ़ोटोशूट से यादों में बसाइए।', title_id = 'Wajah lucu ayah 🤡', body_id = 'Cara terbaik membuat bayi tertawa adalah suara-suara aneh dari ayah. Abadikan momen ceria malam ini dengan Sesi Foto Bayi.', title_ja = 'パパのおもしろい顔 🤡', body_ja = '赤ちゃんを笑わせるいちばんの方法は、パパが変な声を出すこと。今夜の楽しい瞬間を「ベビーフォトセッション」で残しましょう。', title_ko = '아빠의 웃긴 표정 🤡', body_ko = '아기를 웃게 하는 가장 좋은 방법은 아빠의 이상한 소리예요. 오늘 저녁의 즐거운 순간을 아기 사진 촬영으로 남겨 두세요.', title_nl = 'Papa''s gekke bekken 🤡', body_nl = 'De beste manier om je baby aan het lachen te krijgen: papa die rare geluiden maakt. Leg de vrolijke momenten van vanavond vast met Babyfotoshoot.', title_pl = 'Śmieszne miny taty 🤡', body_pl = 'Najlepszy sposób, by rozśmieszyć maluszka, to dziwne dźwięki taty. Uwiecznij dzisiejsze wesołe chwile w Sesji zdjęciowej dziecka.', title_pt = 'As caretas do pai 🤡', body_pt = 'A melhor forma de fazer o bebé rir é o pai fazer sons estranhos. Guarde na memória os momentos alegres desta noite com a Sessão Fotográfica do Bebé.', title_sv = 'Pappas roliga miner 🤡', body_sv = 'Det bästa sättet att få barnet att skratta är när pappa gör konstiga ljud. Förevig kvällens glada stunder med Babyfotografering.', title_vi = 'Những gương mặt hài hước của bố 🤡', body_vi = 'Cách tốt nhất để bé cười là bố tạo ra những âm thanh kỳ lạ. Hãy lưu giữ những khoảnh khắc vui vẻ tối nay bằng Chụp ảnh cho bé.', title_zh = '爸爸的鬼脸 🤡', body_zh = '逗宝宝笑最好的办法就是爸爸发出怪声。用宝宝写真记下今晚这些欢乐的时刻吧。' WHERE id = 'edfb2fd4-70c3-4b15-b2d1-0fc891b31501' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Siempre pegado a mamá 🥰', body_es = 'Incluso cuando vas al baño, te espera detrás de la puerta llorando. La ansiedad por separación está en su punto máximo. Dale seguridad diciéndole cada vez «estoy aquí».', title_fr = 'Toujours collé à maman 🥰', body_fr = 'Même quand vous allez aux toilettes, il vous attend derrière la porte en pleurant. L''angoisse de séparation est à son maximum. Rassurez-le à chaque fois en disant « Je suis là ».', title_hi = 'माँ के पास रहने की ज़िद 🥰', body_hi = 'आप बाथरूम भी जाएँ, तो वह दरवाज़े के पीछे इंतज़ार करते हुए रोता है। अलगाव की बेचैनी चरम पर है। हर बार ''मैं यहीं हूँ'' कहकर उसे भरोसा दिलाइए।', title_id = 'Ingin selalu dekat ibu 🥰', body_id = 'Bahkan saat Anda ke toilet, ia menunggu di balik pintu sambil menangis. Kecemasan berpisah sedang di puncaknya. Beri ia rasa aman dengan selalu berkata "Ibu di sini".', title_ja = 'ママのそばにいたい 🥰', body_ja = 'トイレに行くときでさえ、ドアの向こうで待って泣いていますか？分離不安がピークです。そのたびに「ここにいるよ」と声をかけて、安心させてあげましょう。', title_ko = '엄마 곁에만 있을래요 🥰', body_ko = '화장실에 갈 때도 문 뒤에서 엄마를 기다리며 우나요? 분리불안이 최고조예요. 매번 ''엄마 여기 있어''라고 말하며 안심시켜 주세요.', title_nl = 'Steeds bij mama willen zijn 🥰', body_nl = 'Zelfs als je naar de wc gaat, wacht je baby huilend achter de deur. De verlatingsangst is op zijn hoogtepunt. Geef hem steeds vertrouwen door te zeggen: ik ben hier.', title_pl = 'Upór: tylko przy mamie 🥰', body_pl = 'Nawet gdy idziesz do toalety, czeka pod drzwiami i płacze. Lęk separacyjny jest u szczytu. Za każdym razem mów „jestem tutaj” i dawaj mu poczucie bezpieczeństwa.', title_pt = 'A teimosia de estar perto da mãe 🥰', body_pt = 'Até quando vai à casa de banho, ele fica à sua espera atrás da porta a chorar. A ansiedade de separação está no auge. Dê-lhe segurança dizendo sempre "estou aqui".', title_sv = 'Envisheten att vara nära mamma 🥰', body_sv = 'Även när du går på toaletten väntar barnet gråtande bakom dörren. Separationsångesten är på topp. Ge barnet trygghet varje gång genom att säga ''jag är här''.', title_vi = 'Lúc nào cũng muốn ở gần mẹ 🥰', body_vi = 'Ngay cả khi mẹ vào nhà vệ sinh, bé cũng đợi ngoài cửa và khóc. Nỗi lo xa cách đang ở đỉnh điểm. Mỗi lần như vậy, hãy nói "Mẹ ở đây" để bé yên tâm.', title_zh = '就要黏着妈妈 🥰', body_zh = '你连去洗手间，宝宝都在门外等着哭。分离焦虑正处在高峰。每次都说“我在这儿”，给宝宝安全感吧。' WHERE id = '9b064bbe-67b8-4d62-b3a0-30f79dc81515' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hoy en Cuentos inteligentes 🪄', body_es = 'Crea en Cuentos inteligentes una historia especial cuyo protagonista sea tu peque: El pequeño que se cansa de día y vuela a las estrellas de noche.', title_fr = 'Aujourd''hui dans les Contes intelligents 🪄', body_fr = 'Dans les Contes intelligents, créez une histoire spéciale dont votre enfant est le héros : « Le petit qui se fatigue le jour et s''envole vers les étoiles la nuit ».', title_hi = 'आज स्मार्ट कहानियों में 🪄', body_hi = 'स्मार्ट कहानियों में एक खास कहानी बनाइए जिसका हीरो आपका अपना बच्चा हो: ''दिन में थक जाने वाला और रात में तारों तक उड़ने वाला नन्हा''।', title_id = 'Hari ini di Dongeng Pintar 🪄', body_id = 'Di Dongeng Pintar, buat kisah istimewa dengan anak Anda sendiri sebagai pahlawannya: Si kecil yang lelah di siang hari dan terbang ke bintang-bintang di malam hari.', title_ja = '今日の「スマートおはなし」🪄', body_ja = '「スマートおはなし」で、あなたの赤ちゃんが主人公の特別なお話をつくりましょう：昼間は遊び疲れて、夜は星へ飛んでいく子のお話。', title_ko = '오늘의 스마트 동화 🪄', body_ko = '스마트 동화에서 우리 아이가 주인공인 특별한 이야기를 만들어 보세요: 낮에는 지치고 밤에는 별나라로 날아가는 아기.', title_nl = 'Vandaag in Slimme sprookjes 🪄', body_nl = 'Maak in Slimme sprookjes een speciaal verhaal met je eigen kindje als held: een kleintje dat overdag moe wordt en ''s nachts naar de sterren vliegt.', title_pl = 'Dziś w Mądrych bajkach 🪄', body_pl = 'Stwórz w Mądrych bajkach wyjątkową historię, której bohaterem jest twoje dziecko: Maluszek, który za dnia się męczy, a nocą leci do gwiazd.', title_pt = 'Hoje nas Histórias Inteligentes 🪄', body_pt = 'Crie nas Histórias Inteligentes uma história especial em que o herói é o seu próprio filho: o pequenino que de dia se cansa e de noite voa até às estrelas.', title_sv = 'I dag i Smarta sagor 🪄', body_sv = 'Skapa en speciell saga i Smarta sagor där ditt eget barn är hjälten: Den lilla som blir trött om dagarna och flyger till stjärnorna om nätterna.', title_vi = 'Hôm nay trong Truyện cổ tích thông minh 🪄', body_vi = 'Hãy tạo một câu chuyện đặc biệt trong Truyện cổ tích thông minh với nhân vật chính là bé nhà mình: "Em bé ban ngày mệt nhoài, ban đêm bay lên những vì sao".', title_zh = '今天的智能故事 🪄', body_zh = '在智能故事里创作一个以你的宝宝为主角的特别故事：《白天玩累了、晚上飞向星星的小宝贝》。' WHERE id = 'e77deeee-d612-4dac-bea4-ec9f16608958' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lista en tu bolsillo 🛒', body_es = '¿Se han acabado las manzanas para hacer compota? Confía la lista a tu pareja. Apúntalo en la Lista de la compra: el súper es cosa suya.', title_fr = 'La liste dans votre poche 🛒', body_fr = 'Plus de pommes pour la compote ? Confiez la liste à votre conjoint. Notez-les dans la Liste de courses, le supermarché, c''est son affaire.', title_hi = 'आपकी जेब में लिस्ट 🛒', body_hi = 'फ़्रूट प्यूरी बनाने के लिए सेब खत्म हो गए? लिस्ट बनाने का काम अपने साथी को सौंपिए। शॉपिंग लिस्ट में लिखिए, बाज़ार उनका काम है।', title_id = 'Daftar di saku Anda 🛒', body_id = 'Apel untuk membuat buah halus habis? Percayakan daftar belanja pada pasangan Anda. Tulis di Daftar Belanja, urusan pasar adalah tugasnya.', title_ja = 'ポケットの中のリスト 🛒', body_ja = 'フルーツペースト用のりんごが切れた？リストづくりはパートナーにおまかせ。「買い物リスト」に書いたら、買い出しはパートナーの担当です。', title_ko = '주머니 속 목록 🛒', body_ko = '과일 퓌레를 만들 사과가 떨어졌나요? 목록 관리는 배우자에게 맡기세요. 쇼핑 목록에 적어 두면 장보기는 배우자 몫이에요.', title_nl = 'Een lijstje in je broekzak 🛒', body_nl = 'Zijn de appels op voor het fruitprakje? Laat het lijstje aan je partner over. Zet het op je Boodschappenlijstje, de supermarkt is zijn taak.', title_pl = 'Lista w kieszeni 🛒', body_pl = 'Skończyły się jabłka na musik owocowy? Powierz listę partnerowi. Wpisz je na Listę zakupów, a sklep to już jego zadanie.', title_pt = 'A lista no seu bolso 🛒', body_pt = 'Acabaram as maçãs para fazer puré de fruta? Confie a lista ao seu companheiro. Escreva na Lista de Compras, o supermercado é com ele.', title_sv = 'Listan i fickan 🛒', body_sv = 'Har äpplena till fruktmoset tagit slut? Låt din partner ta hand om listan. Skriv upp det i Inköpslistan, affären är hans jobb.', title_vi = 'Danh sách trong túi mẹ 🛒', body_vi = 'Hết táo để làm táo nghiền? Hãy giao việc mua sắm cho bố. Ghi vào Danh sách mua sắm, còn đi chợ là việc của bố.', title_zh = '口袋里的清单 🛒', body_zh = '做果泥的苹果用完了？把清单交给伴侣吧。写进购物清单，去超市就是他的事了。' WHERE id = 'f0ba97cb-8dd2-4486-865e-1d22a5e551a6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Seguimos la digestión. 🧷', body_es = 'Los distintos alimentos sólidos cambian las cacas. Registra cada cambio de pañal en Anacan y analiza la salud de tu bebé.', title_fr = 'On suit la digestion. 🧷', body_fr = 'Les différents aliments solides modifient les selles. Notez chaque change dans Anacan pour analyser la santé de votre bébé.', title_hi = 'पाचन पर नज़र 🧷', body_hi = 'अलग-अलग ठोस आहार से मल बदलता है। Anacan में हर डायपर बदलना दर्ज करके बच्चे की सेहत का विश्लेषण कीजिए।', title_id = 'Memantau pencernaan. 🧷', body_id = 'Berbagai makanan padat mengubah pola BAB-nya. Catat setiap ganti popok di Anacan dan pantau kesehatan bayi Anda.', title_ja = '消化の様子を見守ろう。🧷', body_ja = 'いろいろな固形の食べ物でうんちが変わります。おむつ替えのたびにAnacanに記録して、赤ちゃんの健康をチェックしましょう。', title_ko = '소화 과정 살피기 🧷', body_ko = '다양한 고형식은 변을 바꿔요. Anacan에 기저귀 교체를 빠짐없이 기록하며 아기의 건강을 살펴보세요.', title_nl = 'We volgen de spijsvertering. 🧷', body_nl = 'Ander vast voedsel verandert de ontlasting. Noteer elke luierverschoning in Anacan en houd de gezondheid van je baby in de gaten.', title_pl = 'Śledzimy trawienie. 🧷', body_pl = 'Różne stałe pokarmy zmieniają kupki. Zapisuj w Anacan każdą zmianę pieluszki i analizuj zdrowie maluszka.', title_pt = 'Acompanhamos a digestão. 🧷', body_pt = 'Os diferentes alimentos sólidos mudam as fezes. Registe no Anacan cada muda de fralda e analise a saúde do bebé.', title_sv = 'Vi följer matsmältningen. 🧷', body_sv = 'Olika fast föda förändrar bajset. Anteckna varje blöjbyte i Anacan och analysera barnets hälsa.', title_vi = 'Theo dõi quá trình tiêu hóa. 🧷', body_vi = 'Mỗi loại thức ăn đặc khác nhau làm thay đổi phân của bé. Hãy ghi lại mỗi lần thay tã trong Anacan để phân tích sức khỏe của bé.', title_zh = '关注消化情况 🧷', body_zh = '不同的固体食物会改变大便。在Anacan里记录每一次换尿布，了解宝宝的健康状况。' WHERE id = '26bb2530-b202-43eb-9226-30863365843e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Noches difíciles 🥱', body_es = '¿Se resiste con todas sus fuerzas a dormirse? Quizá haya llegado el momento de quitar una de las siestas de día. Revisa la rutina.', title_fr = 'Des nuits difficiles 🥱', body_fr = 'Il résiste de toutes ses forces pour ne pas s''endormir ? Il est peut-être temps de supprimer une de ses siestes. Vérifiez la routine.', title_hi = 'ज़िद्दी रातें 🥱', body_hi = 'सोने से बचने के लिए पूरी ताकत से विरोध करता है? शायद दिन की एक झपकी कम करने का समय आ गया है। रूटीन जाँचिए।', title_id = 'Malam-malam yang alot 🥱', body_id = 'Ia melawan sekuat tenaga agar tidak tertidur? Mungkin sudah waktunya mengurangi satu kali tidur siang. Periksa rutinitasnya.', title_ja = '手ごわい夜 🥱', body_ja = '眠るまいと全力で抵抗していますか？お昼寝を1回減らすときがきたのかもしれません。ルーティンを見直しましょう。', title_ko = '고집스러운 밤 🥱', body_ko = '잠들지 않으려고 온 힘을 다해 버티나요? 낮잠 한 번을 줄일 때가 됐을 수도 있어요. 루틴을 점검해 보세요.', title_nl = 'Koppige nachten 🥱', body_nl = 'Verzet je baby zich met alle macht tegen het slapengaan? Misschien is het tijd om een van de dutjes overdag te schrappen. Bekijk de routine.', title_pl = 'Uparte noce 🥱', body_pl = 'Z całych sił opiera się zasypianiu? Może nadszedł czas, by zrezygnować z jednej drzemki w ciągu dnia. Sprawdź rutynę.', title_pt = 'Noites teimosas 🥱', body_pt = 'Resiste com todas as forças a adormecer? Pode ter chegado a altura de cortar uma das sestas do dia. Reveja a rotina.', title_sv = 'Envisa nätter 🥱', body_sv = 'Kämpar barnet emot med all kraft för att inte somna? Det kan vara dags att ta bort en av dagsluren. Se över rutinen.', title_vi = 'Những đêm bướng bỉnh 🥱', body_vi = 'Bé dồn hết sức để chống lại giấc ngủ? Có lẽ đã đến lúc bớt đi một giấc ngủ ngày. Hãy xem lại nếp sinh hoạt.', title_zh = '倔强的夜晚 🥱', body_zh = '宝宝用尽全力抗拒睡觉？可能是时候减掉一次白天小睡了。检查一下作息吧。' WHERE id = '32966fee-53d4-4975-ad1e-195457a2fa5c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un sitio para mamá ☕', body_es = 'Estar en casa te ha dejado sin energía. Elige en Lugares para mamás una cafetería con menú infantil donde puedas sentarte a gusto y dedícate tiempo.', title_fr = 'Un lieu pour maman ☕', body_fr = 'Rester à la maison vous a vidée de votre énergie. Dans les Lieux adaptés aux mamans, choisissez un café avec un menu enfant où vous installer confortablement, et prenez du temps pour vous.', title_hi = 'माँ के लिए जगह ☕', body_hi = 'घर में रहकर ऊर्जा खत्म हो गई है। माँ के अनुकूल जगहों में से बच्चों के मेन्यू वाला और आराम से बैठने लायक कोई कैफ़े चुनिए और अपने लिए समय निकालिए।', title_id = 'Tempat untuk Bunda ☕', body_id = 'Energi habis karena terus di rumah. Pilih kafe dari Tempat Ramah Ibu yang punya menu anak dan tempat duduk nyaman, lalu luangkan waktu untuk diri sendiri.', title_ja = 'ママのための場所 ☕', body_ja = '家にいてばかりで元気がなくなった？「ママにやさしいスポット」から、キッズメニューがあってゆったり座れるカフェを選んで、自分の時間をつくりましょう。', title_ko = '엄마를 위한 공간 ☕', body_ko = '집에만 있어 기운이 다 빠졌어요. 엄마 친화 장소에서 아이 메뉴가 있고 편히 앉을 수 있는 카페를 골라 나를 위한 시간을 가져 보세요.', title_nl = 'Een plek voor mama ☕', body_nl = 'Je energie is op van het thuiszitten. Kies in Mamavriendelijke plekken een café met een kindermenu waar je fijn kunt zitten en neem tijd voor jezelf.', title_pl = 'Miejsce dla mamy ☕', body_pl = 'Siedzenie w domu odebrało ci energię. Wybierz w Miejscach przyjaznych mamom kawiarnię z menu dla dzieci, w której wygodnie usiądziesz, i poświęć czas sobie.', title_pt = 'Um lugar para a mãe ☕', body_pt = 'Ficar em casa esgotou-lhe a energia. Escolha nos Locais Amigos das Mães um café com menu infantil onde se sente à vontade e reserve tempo para si.', title_sv = 'En plats för mamma ☕', body_sv = 'Har energin tagit slut av att vara hemma? Välj ett kafé bland Mammavänliga platser som har barnmeny och där du kan sitta bekvämt, och ta tid för dig själv.', title_vi = 'Không gian cho mẹ ☕', body_vi = 'Ở nhà mãi khiến mẹ cạn năng lượng. Hãy chọn một quán cà phê có thực đơn cho bé và chỗ ngồi thoải mái trong Địa điểm thân thiện với mẹ và dành thời gian cho bản thân.', title_zh = '妈妈的空间 ☕', body_zh = '在家待得精力都耗光了。在妈妈友好场所里挑一家有儿童菜单、能舒服坐下的咖啡馆，留点时间给自己吧。' WHERE id = 'b5660557-30c8-45a9-9c75-69616076d9ce' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Valórate 👏', body_es = 'No mires el desorden de la habitación, sino lo feliz que está hoy tu peque. Eres una madre estupenda, mucho más de lo que podría enseñar cualquier libro.', title_fr = 'Reconnaissez votre mérite 👏', body_fr = 'Ne regardez pas le désordre de la pièce, mais à quel point il est heureux aujourd''hui. Vous êtes une maman formidable, bien plus qu''aucun livre ne pourrait l''enseigner.', title_hi = 'खुद की तारीफ़ कीजिए 👏', body_hi = 'कमरे के बिखराव को नहीं, यह देखिए कि आज वह कितना खुश है। आप ऐसी बेहतरीन माँ हैं जैसा कोई किताब नहीं सिखा सकती।', title_id = 'Hargai diri Anda 👏', body_id = 'Jangan lihat kamar yang berantakan, lihatlah betapa bahagianya ia hari ini. Anda ibu yang hebat, lebih dari yang bisa diajarkan buku mana pun.', title_ja = '自分をほめてあげて 👏', body_ja = '部屋の散らかりではなく、今日の赤ちゃんの幸せそうな姿を見てください。あなたはどんな本も教えられないほど、すばらしいママです。', title_ko = '나를 칭찬해 주세요 👏', body_ko = '어질러진 방이 아니라 오늘 아기가 얼마나 행복했는지를 보세요. 당신은 어떤 책도 가르쳐 줄 수 없을 만큼 훌륭한 엄마예요.', title_nl = 'Waardeer jezelf 👏', body_nl = 'Kijk niet naar de rommel in de kamer, maar naar hoe blij je kindje vandaag was. Je bent een betere moeder dan welk boek ook je kan leren.', title_pl = 'Doceń siebie 👏', body_pl = 'Nie patrz na bałagan w pokoju, tylko na to, jak szczęśliwy jest dziś maluszek. Jesteś wspaniałą mamą, takiej żadna książka nie nauczy.', title_pt = 'Valorize-se 👏', body_pt = 'Não olhe para a desarrumação do quarto, olhe para como ele hoje está feliz. É uma mãe tão boa que nenhum livro o conseguiria ensinar.', title_sv = 'Uppskatta dig själv 👏', body_sv = 'Titta inte på stöket i rummet utan på hur glad barnet är i dag. Du är en bättre mamma än någon bok kan lära ut.', title_vi = 'Hãy ghi nhận chính mình 👏', body_vi = 'Đừng nhìn căn phòng bừa bộn, hãy nhìn xem hôm nay bé hạnh phúc thế nào. Mẹ là một người mẹ tuyệt vời hơn bất kỳ cuốn sách nào có thể dạy.', title_zh = '肯定自己 👏', body_zh = '别看房间有多乱，看看宝宝今天有多开心。你是一个任何书都教不出来的好妈妈。' WHERE id = '221ab24d-c8af-4cca-b9d8-b4eae15499d0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un cuerpecito que baila con la música 🎶', body_es = 'En cuanto oye un sonido rítmico en la tele o en el móvil, empieza a mover el culete. Se activa su percepción musical, ¡únete y bailad juntos!', title_fr = 'Un corps qui danse en musique 🎶', body_fr = 'Dès qu''il entend un son rythmé à la télévision ou sur le téléphone, il se met à remuer les fesses. Sa perception musicale s''éveille, dansez avec lui !', title_hi = 'संगीत पर नाचता शरीर 🎶', body_hi = 'टीवी या फ़ोन पर कोई लयबद्ध आवाज़ सुनते ही कूल्हे मटकाने लगता है। संगीत की समझ जाग रही है, उसके साथ नाचिए!', title_id = 'Tubuh yang menari mengikuti musik 🎶', body_id = 'Begitu mendengar irama dari TV atau ponsel, ia mulai menggoyangkan pantatnya. Kepekaan musiknya mulai bekerja, ikutlah menari bersamanya!', title_ja = '音楽に合わせて踊る体 🎶', body_ja = 'テレビやスマホからリズムのある音が聞こえると、すぐにおしりをふりはじめますか？音楽を感じる力が目覚めています。一緒に踊りましょう！', title_ko = '음악에 춤추는 몸 🎶', body_ko = 'TV나 휴대폰에서 리듬 있는 소리가 들리자마자 엉덩이를 흔들기 시작하나요? 음악 감각이 깨어나고 있어요, 함께 춤춰 주세요!', title_nl = 'Een lijfje dat danst op muziek 🎶', body_nl = 'Zodra je baby een ritmisch geluid hoort op de tv of telefoon, begint hij met zijn billetjes te wiebelen. Zijn gevoel voor muziek komt op gang, dans mee!', title_pl = 'Ciałko tańczy do muzyki 🎶', body_pl = 'Gdy tylko usłyszy rytmiczny dźwięk z telewizora lub telefonu, zaczyna kręcić pupą. Rusza odbiór muzyki, przyłącz się i tańczcie!', title_pt = 'Um corpo que dança ao som da música 🎶', body_pt = 'Mal ouve um som ritmado na televisão ou no telemóvel, começa a abanar o rabinho. A perceção musical está a funcionar: junte-se a ele e dancem!', title_sv = 'En kropp som dansar till musiken 🎶', body_sv = 'Så fort barnet hör ett rytmiskt ljud på tv:n eller telefonen börjar det vicka på rumpan. Musikkänslan vaknar, dansa med!', title_vi = 'Cơ thể nhún nhảy theo nhạc 🎶', body_vi = 'Vừa nghe thấy âm thanh có nhịp điệu trên tivi hay điện thoại, bé đã lắc mông theo. Khả năng cảm thụ âm nhạc đã khởi động, hãy cùng nhảy với bé!', title_zh = '随音乐摇摆的小身体 🎶', body_zh = '电视或手机里一传出有节奏的声音，宝宝就开始扭屁股。音乐感知启动了，和宝宝一起跳吧！' WHERE id = 'cdf44716-8a24-472d-9ff5-449bcc14a7fe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora del masaje 💆‍♂️', body_es = 'Cuando tu bebé se duerma, organizad una sesión de masaje de hombros tu pareja y tú para soltar el estrés del día. ¡Sois un equipo!', title_fr = 'L''heure du massage 💆‍♂️', body_fr = 'Quand bébé dort, organisez une séance de massage des épaules avec votre conjoint pour évacuer le stress de la journée. Vous êtes une équipe !', title_hi = 'मालिश का समय 💆‍♂️', body_hi = 'बच्चे के सोने के बाद दिन का तनाव उतारने के लिए अपने साथी के साथ कंधे की मालिश का सेशन रखिए। आप एक टीम हैं!', title_id = 'Waktu pijat 💆‍♂️', body_id = 'Setelah si kecil tidur, adakan sesi pijat bahu bersama pasangan untuk melepas stres hari ini. Kalian satu tim!', title_ja = 'マッサージタイム 💆‍♂️', body_ja = '赤ちゃんが寝たら、1日のストレスを流すためにパートナーと肩もみタイムをつくりましょう。あなたたちはチームです！', title_ko = '마사지 시간 💆‍♂️', body_ko = '아이가 잠든 뒤 배우자와 함께 어깨 마사지 시간을 가지며 하루의 스트레스를 풀어 보세요. 두 사람은 한 팀이에요!', title_nl = 'Tijd voor een massage 💆‍♂️', body_nl = 'Plan als je baby slaapt een schoudermassage met je partner om de stress van de dag kwijt te raken. Jullie zijn een team!', title_pl = 'Czas na masaż 💆‍♂️', body_pl = 'Gdy maluszek zaśnie, zróbcie sobie z partnerem sesję masażu ramion, by zrzucić stres całego dnia. Jesteście drużyną!', title_pt = 'Hora da massagem 💆‍♂️', body_pt = 'Depois de o bebé adormecer, organize com o seu companheiro uma sessão de massagem aos ombros para libertar o stress do dia. São uma equipa!', title_sv = 'Massagedags 💆‍♂️', body_sv = 'När barnet har somnat, ordna en stund med axelmassage tillsammans med din partner för att släppa dagens stress. Ni är ett lag!', title_vi = 'Giờ mát-xa 💆‍♂️', body_vi = 'Sau khi bé ngủ, hãy cùng bố mát-xa vai cho nhau để xua tan căng thẳng trong ngày. Bố mẹ là một đội!', title_zh = '按摩时间 💆‍♂️', body_zh = '宝宝睡着后，和伴侣一起来一场肩部按摩，释放一天的压力。你们是一个团队！' WHERE id = 'd3e69c0c-c087-4266-8819-3e9aa9fc132a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirse con un cuento 🪄', body_es = 'Crea en Cuentos inteligentes un fondo especial solo con música y sonidos de la naturaleza. Sin palabras, solo calma.', title_fr = 'S''endormir avec un conte 🪄', body_fr = 'Dans les Contes intelligents, créez une ambiance sonore spéciale faite uniquement de musique et de sons de la nature. Pas de mots, seulement la sérénité.', title_hi = 'कहानी के साथ नींद की ओर 🪄', body_hi = 'स्मार्ट कहानियों में सिर्फ़ संगीत और प्रकृति की आवाज़ों से एक खास पृष्ठभूमि बनाइए। कोई शब्द नहीं, बस सुकून।', title_id = 'Menuju tidur bersama dongeng 🪄', body_id = 'Di Dongeng Pintar, buat latar khusus yang hanya berisi musik dan suara alam. Tanpa kata-kata, hanya ketenangan.', title_ja = 'お話でねんねへ 🪄', body_ja = '「スマートおはなし」で、音楽と自然の音だけの特別なBGMをつくりましょう。言葉はなく、ただやすらぎがあるだけ。', title_ko = '동화와 함께 꿈나라로 🪄', body_ko = '스마트 동화에서 음악과 자연의 소리로만 이루어진 특별한 배경을 만들어 보세요. 말은 없고, 오직 평온함만 있어요.', title_nl = 'Met een sprookje naar dromenland 🪄', body_nl = 'Maak in Slimme sprookjes een speciale achtergrond van alleen muziek en natuurgeluiden. Geen woorden, alleen rust.', title_pl = 'Zasypianie z bajką 🪄', body_pl = 'Stwórz w Mądrych bajkach specjalne tło tylko z muzyki i odgłosów natury. Bez słów, sam spokój.', title_pt = 'Adormecer com uma história 🪄', body_pt = 'Crie nas Histórias Inteligentes um fundo especial feito só de música e sons da natureza. Sem palavras, só calma.', title_sv = 'Somna till en saga 🪄', body_sv = 'Skapa en speciell bakgrund i Smarta sagor med bara musik och naturljud. Inga ord, bara ro.', title_vi = 'Vào giấc cùng truyện cổ tích 🪄', body_vi = 'Hãy tạo trong Truyện cổ tích thông minh một bản nền đặc biệt chỉ gồm âm nhạc và âm thanh thiên nhiên. Không lời, chỉ có sự bình yên.', title_zh = '听着故事入睡 🪄', body_zh = '在智能故事里创作一段只有音乐和大自然声音的特别背景音。没有文字，只有宁静。' WHERE id = '33fb356d-029a-4c8c-bf0d-4b2ad8ed6777' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Vitaminas para mamá 🥑', body_es = 'Haces de todo para que coma bien. ¿Y tú? Elige en la sección Recetas saludables una comida ligera rica en hierro y calcio.', title_fr = 'Des vitamines pour maman 🥑', body_fr = 'Vous faites tout pour bien le nourrir. Et vous ? Choisissez dans les Recettes saines un déjeuner léger riche en fer et en calcium.', title_hi = 'माँ के लिए विटामिन 🥑', body_hi = 'उसका पेट भरने के लिए आप सब कुछ करती हैं। और आप? सेहतमंद रेसिपी सेक्शन से आयरन और कैल्शियम से भरपूर हल्का लंच चुनिए।', title_id = 'Vitamin untuk Bunda 🥑', body_id = 'Anda melakukan segalanya agar ia kenyang. Bagaimana dengan Anda? Pilih makan siang ringan yang kaya zat besi dan kalsium dari bagian Resep Sehat.', title_ja = 'ママのビタミン 🥑', body_ja = '赤ちゃんにお腹いっぱい食べさせるために、なんでもしていますね。でもあなたは？「ヘルシーレシピ」から、鉄分とカルシウムたっぷりの軽いランチを選びましょう。', title_ko = '엄마를 위한 비타민 🥑', body_ko = '아기를 배불리 먹이려고 뭐든 하죠. 그런데 엄마는요? 건강한 레시피 섹션에서 철분과 칼슘이 풍부한 가벼운 점심을 골라 보세요.', title_nl = 'Vitamines voor mama 🥑', body_nl = 'Je doet alles om je baby goed te laten eten. En jij? Kies in het onderdeel Gezonde recepten een lichte lunch vol ijzer en calcium.', title_pl = 'Witaminy dla mamy 🥑', body_pl = 'Robisz wszystko, żeby go nakarmić. A ty? Wybierz w sekcji Zdrowe przepisy lekki obiad bogaty w żelazo i wapń.', title_pt = 'Vitaminas para a mãe 🥑', body_pt = 'Faz tudo para o alimentar. E a mãe? Escolha na secção Receitas Saudáveis um almoço leve, rico em ferro e cálcio.', title_sv = 'Vitaminer till mamma 🥑', body_sv = 'Du gör allt för att barnet ska bli mätt. Men du själv då? Välj en lätt lunch rik på järn och kalcium i avsnittet Hälsosamma recept.', title_vi = 'Vitamin cho mẹ 🥑', body_vi = 'Mẹ làm mọi thứ để bé được no. Còn mẹ thì sao? Hãy chọn một bữa trưa nhẹ, giàu sắt và canxi từ mục Công thức lành mạnh.', title_zh = '妈妈的维生素 🥑', body_zh = '你为了让宝宝吃饱想尽办法。那你自己呢？从健康食谱里挑一份富含铁和钙的清淡午餐吧。' WHERE id = 'b44d4b2a-f3eb-4e26-aa50-0105efb5648c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de noche de papá 👨‍🍼', body_es = 'No cargues tú sola con todos los despertares nocturnos. Despierta también a tu pareja: ser un equipo es repartir la responsabilidad a partes iguales.', title_fr = 'Le service de nuit de papa 👨‍🍼', body_fr = 'Ne gérez pas les réveils nocturnes toute seule. Réveillez aussi votre conjoint, être une équipe, c''est partager la responsabilité à parts égales.', title_hi = 'पापा की रात की ड्यूटी 👨‍🍼', body_hi = 'रात में जागने का बोझ अकेले मत उठाइए। अपने साथी को भी जगाइए, टीम होने का मतलब है ज़िम्मेदारी बराबर बाँटना।', title_id = 'Giliran malam ayah 👨‍🍼', body_id = 'Jangan tanggung sendiri saat ia terbangun di malam hari. Bangunkan juga pasangan Anda, menjadi tim berarti berbagi tanggung jawab secara adil.', title_ja = 'パパの夜の当番 👨‍🍼', body_ja = '夜中に起きるのを、ひとりで抱えこまないで。パートナーも起こしましょう。チームとは責任を平等に分け合うことです。', title_ko = '아빠의 밤 당번 👨‍🍼', body_ko = '밤에 깨는 일을 혼자 다 감당하지 마세요. 배우자도 깨우세요, 한 팀이 된다는 건 책임을 똑같이 나누는 거예요.', title_nl = 'Papa''s avonddienst 👨‍🍼', body_nl = 'Draag het ''s nachts opstaan niet helemaal alleen. Maak je partner ook wakker, een team zijn betekent de verantwoordelijkheid eerlijk delen.', title_pl = 'Nocna zmiana taty 👨‍🍼', body_pl = 'Nie dźwigaj nocnych pobudek zupełnie sama. Obudź też partnera, bycie drużyną to równy podział odpowiedzialności.', title_pt = 'O turno da noite do pai 👨‍🍼', body_pt = 'Não aguente sozinha todos os despertares noturnos. Acorde também o seu companheiro: ser uma equipa é dividir a responsabilidade por igual.', title_sv = 'Pappas nattskift 👨‍🍼', body_sv = 'Ta inte nattuppvaknandena helt ensam. Väck din partner också, att vara ett lag är att dela ansvaret lika.', title_vi = 'Ca đêm của bố 👨‍🍼', body_vi = 'Đừng một mình gánh hết những lần thức dậy ban đêm. Hãy gọi cả bố dậy, là một đội nghĩa là chia đều trách nhiệm.', title_zh = '爸爸的夜班 👨‍🍼', body_zh = '夜醒别全都自己扛。也叫醒你的伴侣，团队就是平分责任。' WHERE id = 'f62c402c-4ba9-489a-b6de-dde4e1aa3aae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amistad en el parque 🌳', body_es = '¿Se aburre paseando en el carrito? Mira Tiempo y ropa y déjale libre en el parque para que toque la hierba y las hojas del suelo.', title_fr = 'L''amitié au parc 🌳', body_fr = 'La promenade en poussette l''ennuie ? Consultez Météo et tenue, puis laissez-le libre au parc pour toucher l''herbe et les feuilles.', title_hi = 'पार्क की दोस्ती 🌳', body_hi = 'स्ट्रॉलर में घूमना उसे उबाऊ लगता है? मौसम और कपड़े देखिए और पार्क में उसे ज़मीन की घास और पत्तियाँ छूने के लिए आज़ाद छोड़िए।', title_id = 'Bersahabat dengan taman 🌳', body_id = 'Bosan duduk di stroller? Cek Cuaca dan Pakaian, lalu biarkan ia bebas menyentuh rumput dan dedaunan di taman.', title_ja = '公園でのふれあい 🌳', body_ja = 'ベビーカーでのお散歩に飽きてきた？「天気と服装」をチェックして、公園で地面の草や葉っぱに自由にさわらせてあげましょう。', title_ko = '공원 친구 🌳', body_ko = '유모차 산책이 답답한가요? 날씨와 옷차림을 확인하고 공원에서 풀과 나뭇잎을 직접 만질 수 있게 자유롭게 풀어 주세요.', title_nl = 'Vriendschap in het park 🌳', body_nl = 'Vindt je baby rijden in de kinderwagen saai? Kijk in Weer en kleding en laat hem in het park vrij het gras en de blaadjes op de grond aanraken.', title_pl = 'Przyjaźń z parkiem 🌳', body_pl = 'Nudzi się w wózku? Sprawdź Pogodę i ubiór i pozwól mu swobodnie dotykać w parku trawy i liści na ziemi.', title_pt = 'Amizades no parque 🌳', body_pt = 'Passear no carrinho aborrece-o? Veja o Tempo e Roupa e, no parque, deixe-o à vontade para tocar na relva e nas folhas do chão.', title_sv = 'Vänskap i parken 🌳', body_sv = 'Tycker barnet att det är tråkigt att åka i vagnen? Kolla Väder och kläder och låt barnet fritt röra vid gräset och löven på marken i parken.', title_vi = 'Tình bạn ở công viên 🌳', body_vi = 'Ngồi xe đẩy làm bé thấy chán? Xem Thời tiết và trang phục rồi để bé tự do chạm vào cỏ, lá cây trên mặt đất ở công viên.', title_zh = '公园里的友谊 🌳', body_zh = '宝宝坐婴儿车觉得无聊？看看天气穿衣，在公园里放宝宝自由活动，摸摸地上的草和树叶吧。' WHERE id = '3e6ba90a-e6bd-4527-a0cb-94dcb9fecfac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Camina agarrado a la pared 🧗‍♀️', body_es = 'Dar pasitos de lado por el borde de los muebles es su ejercicio favorito. Es el momento perfecto para volver a revisar los protectores de seguridad y las esquinas afiladas.', title_fr = 'Il marche en se tenant au mur 🧗‍♀️', body_fr = 'Se déplacer sur le côté le long des meubles, c''est son exercice préféré. C''est le moment idéal pour vérifier à nouveau les protections de sécurité et les angles pointus.', title_hi = 'दीवार पकड़कर चलता है 🧗‍♀️', body_hi = 'फ़र्नीचर के किनारे-किनारे बगल में कदम बढ़ाना उसकी पसंदीदा कसरत है। सुरक्षा गार्ड और नुकीले कोनों को एक बार फिर जाँचने का सही समय है।', title_id = 'Berjalan berpegangan pada dinding 🧗‍♀️', body_id = 'Melangkah ke samping menyusuri tepi perabot adalah latihan favoritnya. Inilah saat yang tepat untuk memeriksa kembali pengaman dan sudut-sudut tajam.', title_ja = '壁づたいに歩く 🧗‍♀️', body_ja = '家具のふちに沿って横歩きするのがお気に入りの練習です。安全ガードやとがった角をもう一度チェックするのにぴったりのタイミングです。', title_ko = '벽을 잡고 걸어요 🧗‍♀️', body_ko = '가구 가장자리를 따라 옆으로 걷는 게 가장 좋아하는 운동이에요. 안전 보호대와 뾰족한 모서리를 다시 점검할 딱 좋은 때예요.', title_nl = 'Hij loopt langs de muur 🧗‍♀️', body_nl = 'Zijwaarts stapjes zetten langs de meubels is zijn favoriete oefening. Hét moment om de veiligheidsbeschermers en scherpe hoeken nog eens te controleren.', title_pl = 'Chodzi, trzymając się ściany 🧗‍♀️', body_pl = 'Chodzenie bokiem wzdłuż mebli to jego ulubione ćwiczenie. To idealny moment, by jeszcze raz sprawdzić zabezpieczenia i ostre narożniki.', title_pt = 'Anda agarrado à parede 🧗‍♀️', body_pt = 'Dar passinhos de lado ao longo dos móveis é o seu exercício preferido. É a altura certa para voltar a verificar as proteções de segurança e as esquinas afiadas.', title_sv = 'Går längs väggen med stöd 🧗‍♀️', body_sv = 'Att ta steg i sidled längs möblernas kanter är barnets favoritövning. Nu är det perfekt tid att kolla säkerhetsskydden och de vassa hörnen en gång till.', title_vi = 'Bám tường mà đi 🧗‍♀️', body_vi = 'Men theo mép đồ đạc bước ngang là bài tập yêu thích của bé. Đây chính là lúc kiểm tra lại các miếng bảo vệ an toàn và những góc nhọn.', title_zh = '扶着墙走 🧗‍♀️', body_zh = '沿着家具边横着挪步是宝宝最爱的运动。现在正是再检查一遍安全防护和尖锐边角的好时机。' WHERE id = 'd3bac322-3971-4b22-8636-d789ac7ce8db' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Decimos adiós 👋', body_es = '¡Cuando alguien sale por la puerta, dice adiós con la mano por iniciativa propia! Un reflejo social precioso.', title_fr = 'On fait au revoir 👋', body_fr = 'Quand quelqu''un passe la porte, il fait au revoir de la main de lui-même ! Un magnifique réflexe social.', title_hi = 'बाय-बाय कर रहे हैं 👋', body_hi = 'कोई दरवाज़े से निकले तो वह खुद ही हाथ हिलाकर बाय करता है! कितनी प्यारी सामाजिक प्रतिक्रिया है।', title_id = 'Kita dadah-dadah 👋', body_id = 'Saat seseorang keluar pintu, ia melambai sendiri untuk berpamitan! Refleks sosial yang indah.', title_ja = 'バイバイ 👋', body_ja = '誰かがドアから出ていくとき、自分から手を振ってバイバイしますか！すてきな社会性の反応です。', title_ko = '빠이빠이 해요 👋', body_ko = '누군가 문을 나설 때 스스로 손을 흔들며 인사해요! 멋진 사회성 반응이에요.', title_nl = 'We zwaaien dag 👋', body_nl = 'Als iemand de deur uitgaat, zwaait hij uit zichzelf gedag! Een mooie sociale reflex.', title_pl = 'Robimy pa-pa 👋', body_pl = 'Gdy ktoś wychodzi, sam z siebie macha mu na pożegnanie! Piękny odruch społeczny.', title_pt = 'Estamos a dizer adeus 👋', body_pt = 'Quando alguém sai pela porta, diz adeus com a mão por iniciativa própria! Um belo reflexo social.', title_sv = 'Vi vinkar hej då 👋', body_sv = 'När någon går ut genom dörren vinkar barnet hej då på eget initiativ! En fin social reflex.', title_vi = 'Vẫy tay tạm biệt 👋', body_vi = 'Khi có ai đó ra về, bé tự vẫy tay chào tạm biệt! Một phản xạ xã hội thật đẹp.', title_zh = '拜拜啦 👋', body_zh = '有人出门时，宝宝会主动挥手说拜拜！这是很棒的社交反射。' WHERE id = '6498b35b-aa8e-416f-9da1-2596c74b14d0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se ha despertado a media noche llorando sin motivo y sin parar? 😭', body_es = 'Abrázale con calma, no intentes despertarle. Usa el Análisis del llanto para estar segura.', title_fr = 'Il s''est réveillé en pleine nuit en pleurant sans raison et sans s''arrêter ? 😭', body_fr = 'Serrez-le doucement dans vos bras sans essayer de le réveiller. Faites écouter ses pleurs à l''Analyse des pleurs pour en avoir le cœur net.', title_hi = 'आधी रात को बिना वजह लगातार रोते हुए जागा? 😭', body_hi = 'चुपचाप गले लगाइए, जगाने की कोशिश मत कीजिए। क्राइंग एनालिसिस से उसकी आवाज़ सुनवाइए और पक्का कीजिए।', title_id = 'Terbangun di tengah malam dengan tangisan tanpa sebab dan tanpa henti? 😭', body_id = 'Peluk ia dengan tenang, jangan coba membangunkannya. Perdengarkan tangisannya ke Analisis Tangisan untuk memastikan.', title_ja = '夜中に理由もなく、泣きやまずに起きた？😭', body_ja = 'そっと抱きしめて、起こそうとしないで。「泣き声分析」に泣き声を聞かせて確かめましょう。', title_ko = '한밤중에 이유 없이 그치지 않고 울며 깼나요? 😭', body_ko = '조용히 안아 주고 깨우려 하지 마세요. 울음 분석으로 소리를 들려주어 확인해 보세요.', title_nl = 'Midden in de nacht wakker met onverklaarbaar, aanhoudend huilen? 😭', body_nl = 'Houd hem rustig vast en probeer hem niet wakker te maken. Laat Huilanalyse luisteren voor de zekerheid.', title_pl = 'Obudził się w środku nocy z płaczem bez powodu i bez przerwy? 😭', body_pl = 'Spokojnie go przytul, nie próbuj go budzić. Pozwól Analizie płaczu posłuchać dźwięku i się upewnij.', title_pt = 'Acordou a meio da noite a chorar sem motivo e sem parar? 😭', body_pt = 'Abrace-o com calma, não tente acordá-lo. Ponha a Análise do Choro a ouvir para ter a certeza.', title_sv = 'Har barnet vaknat mitt i natten och gråter utan anledning och utan uppehåll? 😭', body_sv = 'Krama barnet lugnt och försök inte väcka det. Låt Gråtanalys lyssna på ljudet för att vara säker.', title_vi = 'Bé thức giấc giữa đêm và khóc không ngừng không rõ lý do? 😭', body_vi = 'Hãy nhẹ nhàng ôm bé, đừng cố đánh thức bé. Cho Phân tích tiếng khóc nghe để biết chắc.', title_zh = '半夜无缘无故地醒来哭个不停？😭', body_zh = '轻轻抱住宝宝，别试图叫醒宝宝。用哭声分析听一听，确认一下吧。' WHERE id = 'b49f5612-c3e4-4568-8a0e-3494499a88d1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hace falta desahogarse 💬', body_es = '¿Te agobia pensar que nunca volverás a ser la de antes? Comparte este sentimiento pasajero con las mamás de la Comunidad Anacan, no estás sola.', title_fr = 'Besoin de vous confier 💬', body_fr = 'La pensée « Je ne redeviendrai jamais celle que j''étais » vous étouffe ? Partagez ce sentiment passager avec les mamans de la Communauté Anacan, vous n''êtes pas seule.', title_hi = 'दिल की बात करना ज़रूरी है 💬', body_hi = '''मैं फिर कभी पहले जैसी नहीं हो पाऊँगी'' यह सोच आपको घेर रही है? Anacan कम्युनिटी की माँओं के साथ यह गुज़र जाने वाला एहसास बाँटिए, आप अकेली नहीं हैं।', title_id = 'Butuh teman bercerita 💬', body_id = 'Pikiran "Aku tidak akan pernah bisa jadi diriku yang dulu" terasa menyesakkan? Bagikan perasaan sementara ini dengan para ibu di Komunitas Anacan, Anda tidak sendirian.', title_ja = '話すことが必要なとき 💬', body_ja = '「もう昔の自分には戻れない」という思いに押しつぶされそう？Anacanコミュニティのママたちと、この一時的な気持ちを分かち合いましょう。あなたはひとりではありません。', title_ko = '마음을 나눌 시간 💬', body_ko = '''다시는 예전의 나로 돌아갈 수 없을 거야''라는 생각에 답답한가요? Anacan 커뮤니티의 엄마들과 이 지나가는 감정을 나눠 보세요, 혼자가 아니에요.', title_nl = 'Even je hart luchten 💬', body_nl = 'Word je overmand door de gedachte: ik word nooit meer de oude? Deel dit voorbijgaande gevoel met de moeders in de Anacan Community, je bent niet alleen.', title_pl = 'Czas się wygadać 💬', body_pl = 'Przytłacza cię myśl, że już nigdy nie będziesz dawną sobą? Podziel się tym przemijającym uczuciem z mamami w Społeczności Anacan, nie jesteś sama.', title_pt = 'Precisa de desabafar 💬', body_pt = 'O pensamento "nunca mais vou ser quem era" está a sufocá-la? Partilhe este sentimento passageiro com as mães da Comunidade Anacan, não está sozinha.', title_sv = 'Ibland behöver man prata av sig 💬', body_sv = 'Kväver tanken ''jag kommer aldrig att bli mitt gamla jag igen'' dig? Dela den här övergående känslan med mammorna i Anacans Community, du är inte ensam.', title_vi = 'Cần được tâm sự 💬', body_vi = 'Ý nghĩ "Mình sẽ không bao giờ là mình như trước nữa" khiến mẹ ngột ngạt? Hãy chia sẻ cảm xúc thoáng qua này với các bà mẹ trong Cộng đồng Anacan, mẹ không đơn độc.', title_zh = '需要倾诉一下 💬', body_zh = '“我再也回不到从前的自己了”这个念头让你喘不过气？和Anacan社区的妈妈们分享这种暂时的情绪吧，你并不孤单。' WHERE id = 'fd05df6d-36c8-4c59-9212-7542837f9f4c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La nana de papá 👨‍🍼', body_es = 'Esta noche le toca a tu pareja superar la prueba de dormir al bebé él solo en la habitación.', title_fr = 'La berceuse de papa 👨‍🍼', body_fr = 'Ce soir, c''est à votre conjoint de relever le défi de l''endormir seul dans la chambre.', title_hi = 'पापा की लोरी 👨‍🍼', body_hi = 'आज शाम कमरे में अकेले सुलाने की चुनौती आपके साथी को पूरी करनी है।', title_id = 'Nina bobo dari ayah 👨‍🍼', body_id = 'Malam ini, ujian menidurkan si kecil sendirian di kamar harus dijalani oleh pasangan Anda.', title_ja = 'パパの子守唄 👨‍🍼', body_ja = '今夜は、部屋でひとりで寝かしつけるチャレンジにパートナーが挑戦する番です。', title_ko = '아빠의 자장가 👨‍🍼', body_ko = '오늘 저녁 방에서 혼자 아기를 재우는 도전은 배우자 몫이에요.', title_nl = 'Een slaapliedje van papa 👨‍🍼', body_nl = 'Vanavond mag je partner de proef doorstaan: de baby alleen in de kamer in slaap brengen.', title_pl = 'Kołysanka taty 👨‍🍼', body_pl = 'Dziś wieczorem to partner musi zmierzyć się z samodzielnym usypianiem maluszka w pokoju.', title_pt = 'A canção de embalar do pai 👨‍🍼', body_pt = 'Esta noite, é o seu companheiro quem tem de passar o teste de adormecer o bebé sozinho no quarto.', title_sv = 'Pappas vaggvisa 👨‍🍼', body_sv = 'I kväll ska din partner klara provet att söva barnet ensam i rummet.', title_vi = 'Lời ru của bố 👨‍🍼', body_vi = 'Tối nay, bố sẽ là người vượt qua thử thách một mình ru bé ngủ trong phòng.', title_zh = '爸爸的摇篮曲 👨‍🍼', body_zh = '今晚由伴侣来挑战独自在房间里哄宝宝睡觉。' WHERE id = '6032f94e-69e7-4802-b291-44567c9f71d1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Limpiar o descansar? 🛋️', body_es = 'Cuando tu bebé duerma, no corras al lavavajillas. Túmbate en el sofá, cierra los ojos y simplemente respira durante 15 minutos. ¿Eres un robot? No.', title_fr = 'Ménage ou repos ? 🛋️', body_fr = 'Quand bébé dort, ne courez pas vers le lave-vaisselle. Allongez-vous sur le canapé, fermez les yeux et respirez simplement pendant 15 minutes. Êtes-vous un robot ? Non.', title_hi = 'सफ़ाई या आराम? 🛋️', body_hi = 'बच्चे के सोते ही डिशवॉशर की ओर मत भागिए। सोफ़े पर लेट जाइए, आँखें बंद कीजिए और 15 मिनट बस साँस लीजिए। क्या आप रोबोट हैं? नहीं।', title_id = 'Bersih-bersih atau istirahat? 🛋️', body_id = 'Saat si kecil tidur, jangan buru-buru ke mesin cuci piring. Berbaringlah di sofa, pejamkan mata, dan cukup bernapas selama 15 menit. Apakah Anda robot? Bukan.', title_ja = 'お掃除？それとも休憩？🛋️', body_ja = '赤ちゃんが寝ても、食洗機に走らないで。ソファに横になって目を閉じ、15分間ただ呼吸しましょう。あなたはロボット？いいえ。', title_ko = '청소할까요, 쉴까요? 🛋️', body_ko = '아이가 잘 때 식기세척기로 달려가지 마세요. 소파에 누워 눈을 감고 15분 동안 숨만 쉬세요. 당신이 로봇인가요? 아니에요.', title_nl = 'Schoonmaken of uitrusten? 🛋️', body_nl = 'Ren niet naar de vaatwasser als je baby slaapt. Ga op de bank liggen, sluit je ogen en adem 15 minuten gewoon. Ben je een robot? Nee.', title_pl = 'Sprzątać czy odpocząć? 🛋️', body_pl = 'Gdy maluszek śpi, nie biegnij do zmywarki. Połóż się na kanapie, zamknij oczy i przez 15 minut po prostu oddychaj. Jesteś robotem? Nie.', title_pt = 'Limpar ou descansar? 🛋️', body_pt = 'Quando o bebé dorme, não corra para a máquina da loiça. Deite-se no sofá, feche os olhos e simplesmente respire durante 15 minutos. É um robô? Não.', title_sv = 'Städa eller vila? 🛋️', body_sv = 'Rusa inte till diskmaskinen när barnet sover. Lägg dig i soffan, blunda och bara andas i 15 minuter. Är du en robot? Nej.', title_vi = 'Dọn dẹp hay nghỉ ngơi? 🛋️', body_vi = 'Bé vừa ngủ thì đừng vội lao đến máy rửa bát. Hãy nằm xuống sofa, nhắm mắt lại và chỉ hít thở trong 15 phút. Mẹ là robot sao? Không phải.', title_zh = '打扫还是休息？🛋️', body_zh = '宝宝睡着时别急着去洗碗机那边。躺在沙发上，闭上眼睛，呼吸15分钟就好。你是机器人吗？不是。' WHERE id = '7b460d4a-b37e-465f-9c70-e137f59bcc07' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Empieza la batalla del «no» 🛑', body_es = 'Cuando le das algo que no le gusta, lo aparta moviendo la cabeza. Su voluntad se está formando. Intenta respetar sus pequeñas decisiones.', title_fr = 'La bataille du « non » commence 🛑', body_fr = 'Quand vous lui donnez quelque chose qu''il n''aime pas, il le repousse en secouant la tête. Sa volonté se forme. Essayez de respecter ses petites décisions.', title_hi = '''ना'' की जंग शुरू 🛑', body_hi = 'अब नापसंद चीज़ देने पर सिर हिलाकर दूर धकेल देता है। उसकी इच्छाशक्ति बन रही है। उसके छोटे-छोटे फ़ैसलों का सम्मान करने की कोशिश कीजिए।', title_id = 'Perang "tidak" dimulai 🛑', body_id = 'Kini saat diberi sesuatu yang tidak ia sukai, ia menggeleng dan mendorongnya. Kemauannya sedang terbentuk. Cobalah menghargai keputusan-keputusan kecilnya.', title_ja = '「いや」バトルの始まり 🛑', body_ja = '好きじゃないものをあげると、首を振って押しのけます。意思が育っています。その小さな決断を尊重してあげましょう。', title_ko = '''싫어'' 전쟁의 시작 🛑', body_ko = '싫어하는 걸 주면 이제 고개를 저으며 밀어내요. 의지가 생기고 있어요. 아기의 작은 결정을 존중해 주세요.', title_nl = 'De strijd om nee begint 🛑', body_nl = 'Geef je hem iets wat hij niet lust, dan schudt hij zijn hoofd en duwt hij het weg. Zijn wil vormt zich. Probeer zijn kleine beslissingen te respecteren.', title_pl = 'Zaczyna się wojna o „nie” 🛑', body_pl = 'Gdy dajesz mu coś, czego nie lubi, kręci głową i to odpycha. Kształtuje się jego wola. Staraj się szanować jego małe decyzje.', title_pt = 'Começa a batalha do "não" 🛑', body_pt = 'Quando lhe dá algo de que não gosta, já abana a cabeça e afasta-o. A vontade está a formar-se. Tente respeitar as pequenas decisões dele.', title_sv = 'Nej-kriget börjar 🛑', body_sv = 'När du ger barnet något det inte tycker om skakar det på huvudet och skjuter bort det. Viljan tar form. Försök att respektera barnets små beslut.', title_vi = 'Cuộc chiến chữ "Không" bắt đầu 🛑', body_vi = 'Giờ khi mẹ đưa thứ bé không thích, bé lắc đầu và đẩy ra. Ý chí của bé đang hình thành. Hãy cố gắng tôn trọng những quyết định nhỏ của bé.', title_zh = '“不”之战开始了 🛑', body_zh = '给宝宝不喜欢的东西时，宝宝会摇头推开。意志正在形成。试着尊重宝宝的小决定吧。' WHERE id = 'a1392cb5-508d-45a8-9d3d-1985c8d19958' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Control de los ruidos 🤫', body_es = 'La primera media hora después de dormirse es el momento más delicado. Comprueba el ambiente con el Medidor de sonido y evita los ruidos repentinos.', title_fr = 'Maîtriser les bruits 🤫', body_fr = 'La première demi-heure après l''endormissement est le moment le plus sensible. Vérifiez l''ambiance avec le Sonomètre et méfiez-vous des bruits soudains.', title_hi = 'आवाज़ों पर काबू 🤫', body_hi = 'सोने के बाद का पहला आधा घंटा सबसे नाज़ुक समय है। साउंड मीटर से माहौल जाँचिए और अचानक शोर से बचिए।', title_id = 'Mengatur suara 🤫', body_id = 'Setengah jam pertama setelah tertidur adalah waktu paling sensitif. Cek suasana dengan Pengukur Suara dan hindari suara bising mendadak.', title_ja = '音のコントロール 🤫', body_ja = '寝ついてから最初の30分は、いちばん眠りが浅い時間です。「サウンドメーター」で環境をチェックして、急な物音に気をつけましょう。', title_ko = '소리 관리 🤫', body_ko = '잠든 직후 처음 30분이 가장 예민한 시간이에요. 소음 측정기로 환경을 확인하고 갑작스러운 소음을 조심하세요.', title_nl = 'Geluiden onder controle 🤫', body_nl = 'Het eerste halfuur na het inslapen is het gevoeligst. Controleer de omgeving met de Geluidsmeter en pas op voor plotseling lawaai.', title_pl = 'Kontrola dźwięków 🤫', body_pl = 'Pierwsze pół godziny po zaśnięciu to najwrażliwszy czas. Sprawdź otoczenie Miernikiem dźwięku i uważaj na nagły hałas.', title_pt = 'Controlo dos sons 🤫', body_pt = 'A primeira meia hora depois de adormecer é a altura mais sensível. Verifique o ambiente com o Medidor de Som e cuidado com barulhos súbitos.', title_sv = 'Ljudkoll 🤫', body_sv = 'Den första halvtimmen efter att barnet har somnat är den känsligaste. Kolla miljön med Ljudmätaren och akta dig för plötsligt oväsen.', title_vi = 'Kiểm soát âm thanh 🤫', body_vi = 'Nửa tiếng đầu sau khi bé ngủ là lúc nhạy cảm nhất. Hãy kiểm tra môi trường bằng Đo âm thanh và cẩn thận với tiếng ồn đột ngột.', title_zh = '控制声音 🤫', body_zh = '入睡后的头半小时是最敏感的时候。用噪音测量检查环境，小心突然的噪音。' WHERE id = '2cc5ac97-f2b1-4c92-8852-fec32f54b311' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mamá sana, bebé sano 🥑', body_es = 'Tus reservas de hierro y calcio se han agotado. Prepara con Recetas saludables una ensalada rápida y llena de energía que te mantenga en pie.', title_fr = 'Maman en forme, bébé en forme 🥑', body_fr = 'Vos réserves de fer et de calcium sont épuisées. Préparez avec les Recettes saines une salade rapide et pleine d''énergie qui vous tiendra debout.', title_hi = 'सेहतमंद माँ, सेहतमंद बच्चा 🥑', body_hi = 'आपके शरीर में आयरन और कैल्शियम का भंडार खत्म हो गया है। सेहतमंद रेसिपी से जल्दी बनने वाला और आपको ताकत देने वाला ऊर्जा भरा सलाद बनाइए।', title_id = 'Ibu sehat, bayi sehat 🥑', body_id = 'Cadangan zat besi dan kalsium Anda terkuras. Buat salad penuh energi dari Resep Sehat yang cepat dibuat dan membuat Anda tetap bertenaga.', title_ja = '元気なママ、元気な赤ちゃん 🥑', body_ja = '鉄分とカルシウムの蓄えが減っています。「ヘルシーレシピ」から、手早くできて元気を保てるエネルギーたっぷりのサラダをつくりましょう。', title_ko = '건강한 엄마, 건강한 아기 🥑', body_ko = '철분과 칼슘이 바닥났어요. 건강한 레시피에서 빨리 만들 수 있고 든든하게 버티게 해 줄 에너지 가득한 샐러드를 만들어 보세요.', title_nl = 'Gezonde mama, gezonde baby 🥑', body_nl = 'Je ijzer- en calciumvoorraad is op. Maak uit Gezonde recepten een snelle, energierijke salade die je op de been houdt.', title_pl = 'Zdrowa mama, zdrowy maluszek 🥑', body_pl = 'Twoje zapasy żelaza i wapnia się wyczerpały. Przygotuj ze Zdrowych przepisów szybką, pełną energii sałatkę, która postawi cię na nogi.', title_pt = 'Mãe saudável, bebé saudável 🥑', body_pt = 'As suas reservas de ferro e cálcio esgotaram-se. Prepare nas Receitas Saudáveis uma salada rápida e cheia de energia que a mantenha de pé.', title_sv = 'Frisk mamma, friskt barn 🥑', body_sv = 'Dina järn- och kalciumförråd har tömts. Gör en energirik sallad från Hälsosamma recept som både går snabbt att laga och håller dig på benen.', title_vi = 'Mẹ khỏe, bé khỏe 🥑', body_vi = 'Dự trữ sắt và canxi của mẹ đã cạn. Hãy làm một món salad giàu năng lượng, làm nhanh mà giúp mẹ khỏe khoắn từ Công thức lành mạnh.', title_zh = '妈妈健康，宝宝健康 🥑', body_zh = '你体内的铁和钙储备快耗尽了。从健康食谱里做一份快手又能让你撑住的能量沙拉吧。' WHERE id = 'e0b42cd5-f681-4866-a7ec-b0b890444381' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hoy todo te ha puesto de los nervios?', body_es = 'Mientras tu bebé duerme, escribe lo que sientes en el Diario de ánimo. Mañana será un día nuevo y más bonito.', title_fr = 'Tout vous a agacée aujourd''hui ?', body_fr = 'Quand bébé dort, écrivez vos émotions dans le Journal d''humeur. Demain sera un nouveau jour, encore plus beau.', title_hi = 'आज हर बात पर गुस्सा आया?', body_hi = 'बच्चे के सोते समय मूड डायरी में अपनी भावनाएँ लिखिए। कल एक नया और बेहतर दिन होगा।', title_id = 'Hari ini semuanya membuat Anda kesal?', body_id = 'Saat si kecil tidur, tulis perasaan Anda di Buku Harian Suasana Hati. Besok akan menjadi hari baru yang lebih indah.', title_ja = '今日は何にでもイライラしてしまった？', body_ja = '赤ちゃんが寝ている間に、「気分日記」に気持ちを書きましょう。明日は新しい、もっとすてきな1日になります。', title_ko = '오늘 모든 게 짜증 났나요?', body_ko = '아이가 잘 때 기분 일기에 감정을 적어 보세요. 내일은 새롭고 더 좋은 하루가 될 거예요.', title_nl = 'Ergerde je je vandaag aan alles?', body_nl = 'Schrijf je gevoelens op in je Stemmingsdagboek als je baby slaapt. Morgen wordt een nieuwe, mooiere dag.', title_pl = 'Dziś wszystko cię denerwowało?', body_pl = 'Gdy maluszek śpi, zapisz swoje uczucia w Dzienniku nastroju. Jutro będzie nowy i piękniejszy dzień.', title_pt = 'Hoje irritou-se com tudo?', body_pt = 'Quando o bebé dormir, escreva o que sente no Diário de Humor. Amanhã será um dia novo e mais bonito.', title_sv = 'Har allt irriterat dig i dag?', body_sv = 'När barnet sover, skriv ner dina känslor i Humördagboken. I morgon blir en ny och finare dag.', title_vi = 'Hôm nay chuyện gì cũng khiến mẹ bực mình?', body_vi = 'Khi bé ngủ, hãy viết cảm xúc vào Nhật ký tâm trạng. Ngày mai sẽ là một ngày mới và tươi đẹp hơn.', title_zh = '今天对什么都很烦躁？', body_zh = '趁宝宝睡觉，在心情日记里写下你的感受。明天会是新的、更美好的一天。' WHERE id = '188836b2-55a8-4b14-87fe-653f4e05ae3e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Compra rápida 🛒', body_es = '¿Tu pareja sale del trabajo? Abre ya la Lista de la compra y envíale en segundos la leche, la fruta y lo que falte en casa.', title_fr = 'Des courses express 🛒', body_fr = 'Votre conjoint quitte le travail ? Ouvrez vite la Liste de courses et envoyez-lui en quelques secondes le lait, les fruits et ce qui manque à la maison.', title_hi = 'झटपट खरीदारी 🛒', body_hi = 'आपके साथी काम से निकल रहे हैं? तुरंत शॉपिंग लिस्ट खोलिए और दूध, फल और घर की बाकी कमी वाली चीज़ें सेकंडों में उन्हें भेज दीजिए।', title_id = 'Belanja kilat 🛒', body_id = 'Pasangan Anda baru pulang kerja? Segera buka Daftar Belanja dan kirim susu, buah, dan kebutuhan rumah lainnya kepadanya dalam hitungan detik.', title_ja = 'すばやくお買い物 🛒', body_ja = 'パートナーがもうすぐ仕事を終える？すぐに「買い物リスト」を開いて、牛乳、果物、そのほか家で足りないものを数秒で送りましょう。', title_ko = '빠른 장보기 🛒', body_ko = '배우자가 퇴근하나요? 바로 쇼핑 목록을 열어 우유, 과일 등 집에 필요한 것을 몇 초 만에 보내세요.', title_nl = 'Snel boodschappen doen 🛒', body_nl = 'Gaat je partner zo van zijn werk weg? Open meteen je Boodschappenlijstje en stuur hem in een paar seconden melk, fruit en wat er verder in huis ontbreekt.', title_pl = 'Szybkie zakupy 🛒', body_pl = 'Partner wychodzi z pracy? Od razu otwórz Listę zakupów i w kilka sekund wyślij mu mleko, owoce i inne domowe braki.', title_pt = 'Compras rápidas 🛒', body_pt = 'O seu companheiro está a sair do trabalho? Abra já a Lista de Compras e envie-lhe em segundos o leite, a fruta e o que mais faltar em casa.', title_sv = 'Snabbhandling 🛒', body_sv = 'Går din partner från jobbet? Öppna Inköpslistan direkt och skicka mjölk, frukt och annat som fattas hemma till honom på några sekunder.', title_vi = 'Mua sắm nhanh 🛒', body_vi = 'Bố sắp tan làm? Mở ngay Danh sách mua sắm, gửi cho bố sữa, trái cây và những thứ còn thiếu trong nhà chỉ trong vài giây.', title_zh = '快速购物 🛒', body_zh = '伴侣要下班了？马上打开购物清单，几秒钟就把牛奶、水果和家里缺的东西发给他。' WHERE id = '4d566d24-14b9-45b0-be5d-1940c1563ed9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Imitando a los mayores 🧹', body_es = '¿Mientras limpias la casa, coge un trapo e intenta hacer lo mismo? ¡Es tu espejo! Copia todo lo que haces.', title_fr = 'Imiter les grands 🧹', body_fr = 'Quand vous faites le ménage, il prend un chiffon et essaie de faire pareil ? C''est un miroir ! Il copie tout ce que vous faites.', title_hi = 'बड़ों की नकल 🧹', body_hi = 'आप घर पोंछती हैं तो वह भी कपड़ा लेकर वैसा ही करने की कोशिश करता है? वह आईना है! आप जो करती हैं, सब कॉपी करता है।', title_id = 'Meniru orang dewasa 🧹', body_id = 'Saat Anda mengelap rumah, ia juga mengambil lap dan mencoba melakukan hal yang sama? Ia adalah cermin! Ia meniru semua yang Anda lakukan.', title_ja = '大人のまねっこ 🧹', body_ja = 'あなたが家を拭いていると、赤ちゃんも布を持って同じことをしようとしますか？赤ちゃんは鏡です！あなたのすることをなんでもまねしています。', title_ko = '어른 따라 하기 🧹', body_ko = '엄마가 집을 닦을 때 아기도 천을 들고 똑같이 하려 하나요? 아기는 거울이에요! 엄마가 하는 모든 걸 따라 해요.', title_nl = 'De groten nadoen 🧹', body_nl = 'Pakt je baby ook een doekje en probeert hij hetzelfde te doen als jij aan het poetsen bent? Hij is een spiegel! Hij doet alles na wat jij doet.', title_pl = 'Naśladowanie dorosłych 🧹', body_pl = 'Gdy sprzątasz dom, on też bierze ściereczkę i próbuje robić to samo? Jest twoim lustrem! Kopiuje wszystko, co robisz.', title_pt = 'Imitar os crescidos 🧹', body_pt = 'Enquanto limpa a casa, ele pega num pano e tenta fazer o mesmo? É um espelho! Copia tudo o que faz.', title_sv = 'Härmar de vuxna 🧹', body_sv = 'Tar barnet en trasa och försöker göra likadant när du torkar av hemma? Det är en spegel! Det kopierar allt du gör.', title_vi = 'Bắt chước người lớn 🧹', body_vi = 'Khi mẹ lau nhà, bé cũng cầm khăn lên và cố làm theo? Bé là một tấm gương! Bé sao chép mọi điều mẹ làm.', title_zh = '模仿大人 🧹', body_zh = '你擦地时，宝宝也拿起抹布学着做？宝宝就是你的镜子！你做的每件事宝宝都会模仿。' WHERE id = 'fd0252a6-07bf-4750-bd4b-be91888e16f6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apoyo de equipo 🥂', body_es = 'Para quitaros de encima el cansancio del día, tomad un té tu pareja y tú y decíos «hoy también lo hemos conseguido».', title_fr = 'Le soutien de l''équipe 🥂', body_fr = 'Pour vous débarrasser de la fatigue de la journée, buvez un thé avec votre conjoint et dites-vous : « Aujourd''hui encore, on a réussi. »', title_hi = 'टीम का साथ 🥂', body_hi = 'दिनभर की थकान कंधों से उतारने के लिए अपने साथी के साथ चाय पीजिए और एक-दूसरे से कहिए, ''आज भी हमने कर दिखाया''।', title_id = 'Dukungan tim 🥂', body_id = 'Untuk melepas lelah seharian dari pundak Anda, minum teh bersama pasangan dan katakan satu sama lain, "Hari ini pun kita berhasil."', title_ja = 'チームで支え合う 🥂', body_ja = '1日の疲れを肩からおろすために、パートナーとお茶を飲んで「今日もがんばったね」と言い合いましょう。', title_ko = '팀의 응원 🥂', body_ko = '하루의 피로를 어깨에서 내려놓으려면 배우자와 차를 마시며 서로에게 ''오늘도 해냈어''라고 말해 주세요.', title_nl = 'Steun als team 🥂', body_nl = 'Drink samen met je partner een kop thee om de vermoeidheid van de dag van je af te schudden en zeg tegen elkaar: het is ons vandaag weer gelukt.', title_pl = 'Wsparcie drużyny 🥂', body_pl = 'Aby zrzucić z ramion zmęczenie całego dnia, napijcie się z partnerem herbaty i powiedzcie sobie: „Dziś też daliśmy radę”.', title_pt = 'Apoio de equipa 🥂', body_pt = 'Para tirar dos ombros o cansaço do dia, beba um chá com o seu companheiro e digam um ao outro: "hoje também conseguimos".', title_sv = 'Lagstöd 🥂', body_sv = 'För att skaka av dig hela dagens trötthet, drick te tillsammans med din partner och säg till varandra: vi klarade det i dag också.', title_vi = 'Đồng đội hỗ trợ 🥂', body_vi = 'Để trút bỏ mệt mỏi cả ngày khỏi đôi vai, hãy cùng bố uống trà và nói với nhau: "Hôm nay mình lại làm được rồi".', title_zh = '团队支持 🥂', body_zh = '为了卸下一整天的疲惫，和伴侣一起喝杯茶，对彼此说：“今天我们也做到了！”' WHERE id = 'a789d8f9-cc5b-43fd-8931-a3c5dbb78c75' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dudas pediátricas 🤖', body_es = '¿Cuánta cantidad debe comer un peque de 10 meses? No te agotes: pide a Anacan AI una tabla precisa y avalada por pediatras.', title_fr = 'Des doutes pédiatriques 🤖', body_fr = 'Quelle quantité doit manger un enfant de 10 mois ? Ne vous fatiguez pas, demandez à Anacan AI un tableau précis et validé par des pédiatres.', title_hi = 'बच्चे की सेहत को लेकर सवाल 🤖', body_hi = '10 महीने के बच्चे का खाना कितनी मात्रा में होना चाहिए? खुद को मत थकाइए, Anacan AI से सटीक और बाल रोग विशेषज्ञों से पुष्ट तालिका माँगिए।', title_id = 'Keraguan seputar kesehatan anak 🤖', body_id = 'Berapa porsi makan yang tepat untuk anak 10 bulan? Jangan bikin pusing, minta tabel yang akurat dan sesuai pandangan dokter anak dari Anacan AI.', title_ja = '育児の疑問 🤖', body_ja = '生後10か月の赤ちゃんの1回の量はどれくらい？無理をしないで、Anacan AIに正確で小児科医の視点の目安表を頼みましょう。', title_ko = '소아과 궁금증 🤖', body_ko = '10개월 아이의 한 끼 양은 얼마가 적당할까요? 고민하지 말고 Anacan AI에게 정확하고 소아과 의사가 확인한 표를 요청하세요.', title_nl = 'Twijfels over je kindje 🤖', body_nl = 'Hoe groot moet een portie zijn voor een kindje van 10 maanden? Maak jezelf niet moe, vraag Anacan AI om een precieze tabel die door kinderartsen is goedgekeurd.', title_pl = 'Pediatryczne wątpliwości 🤖', body_pl = 'Jak duże powinny być porcje 10-miesięcznego maluszka? Nie męcz się, poproś Anacan AI o dokładną tabelę potwierdzoną przez pediatrów.', title_pt = 'Dúvidas pediátricas 🤖', body_pt = 'Qual deve ser o tamanho das porções de um bebé de 10 meses? Não se canse: peça ao Anacan AI uma tabela precisa e validada por pediatras.', title_sv = 'Barnmedicinska funderingar 🤖', body_sv = 'Hur stora ska portionerna vara för ett barn på 10 månader? Slit inte ut dig, be Anacan AI om en exakt och barnläkargodkänd tabell.', title_vi = 'Băn khoăn về nhi khoa 🤖', body_vi = 'Khẩu phần ăn của bé 10 tháng nên là bao nhiêu? Đừng làm mình mệt, hãy nhờ Anacan AI một bảng chính xác, được bác sĩ nhi khoa xác nhận.', title_zh = '儿科疑虑 🤖', body_zh = '10个月宝宝的饭量应该是多少？别累坏自己，向Anacan AI要一份准确、经儿科医生认可的参考表吧。' WHERE id = 'ac527e8b-ca16-4272-b6ba-964f15ba419b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sigue el picor de encías 🦷', body_es = '¿Siempre tiene los dedos en la boca y lo muerde todo? Pueden estar llegando los dientes de atrás. Anótalo en el Seguimiento de dentición.', title_fr = 'Les gencives démangent toujours 🦷', body_fr = 'Il a toujours les doigts dans la bouche et ronge tout ? Les dents du fond arrivent peut-être. Notez la situation dans le Suivi des dents.', title_hi = 'मसूड़ों की खुजली जारी है 🦷', body_hi = 'उँगलियाँ हमेशा मुँह में हैं और हर चीज़ कुतरता है? पीछे के दाँत आने वाले हो सकते हैं। दाँत निकलने के ट्रैकर में स्थिति दर्ज कीजिए।', title_id = 'Gusi masih gatal 🦷', body_id = 'Jarinya terus di mulut dan ia menggigiti semua benda? Mungkin gigi belakang sedang tumbuh. Catat kondisinya di Pelacak Tumbuh Gigi.', title_ja = '歯ぐきのむずむずが続く 🦷', body_ja = '指がいつも口の中にあって、なんでもかじっていますか？奥歯が生えてくるのかもしれません。「歯の生え始めトラッカー」に記録しましょう。', title_ko = '잇몸 가려움이 계속돼요 🦷', body_ko = '손가락이 늘 입에 있고 무엇이든 갉아 대나요? 어금니가 나오고 있을 수 있어요. 이앓이 기록에 상태를 남겨 두세요.', title_nl = 'Het tandvlees blijft jeuken 🦷', body_nl = 'Zitten de vingertjes steeds in de mond en knaagt hij op alles? De kiezen kunnen eraan komen. Noteer het in de Tandjestracker.', title_pl = 'Swędzenie dziąseł trwa 🦷', body_pl = 'Paluszki ciągle w buzi i wszystko gryzie? Mogą być w drodze tylne ząbki. Zapisz to w narzędziu do śledzenia ząbkowania.', title_pt = 'A comichão nas gengivas continua 🦷', body_pt = 'Tem sempre os dedos na boca e rói tudo? Os dentes de trás podem estar a caminho. Registe a situação no Registo de Dentição.', title_sv = 'Klådan i gommen fortsätter 🦷', body_sv = 'Är fingrarna ständigt i munnen och gnager barnet på allt? Kindtänderna kan vara på väg. Anteckna läget i Tandspåraren.', title_vi = 'Nướu vẫn còn ngứa 🦷', body_vi = 'Bé luôn đưa ngón tay vào miệng và gặm mọi thứ? Có thể răng hàm đang sắp mọc. Hãy ghi lại tình trạng trong Theo dõi mọc răng.', title_zh = '牙龈还在痒 🦷', body_zh = '手指总在嘴里，什么都要啃？可能是后面的牙齿要出来了。在出牙追踪里记录一下吧。' WHERE id = 'e38208ca-c817-4de4-ba96-5a5ca4752901' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorando el tiempo ⛅', body_es = '¿No está claro qué tiempo hace fuera? Deja que la herramienta Tiempo y ropa te diga al instante la velocidad del viento que no se ve desde la ventana y el conjunto adecuado.', title_fr = 'Bulletin météo ⛅', body_fr = 'Le temps dehors n''est pas très clair ? L''outil Météo et tenue vous indique aussitôt la vitesse du vent, invisible depuis la fenêtre, et la bonne tenue.', title_hi = 'मौसम की जासूसी ⛅', body_hi = 'बाहर मौसम साफ़ नहीं है? मौसम और कपड़े टूल आपको खिड़की से न दिखने वाली हवा की रफ़्तार और सही कपड़े तुरंत बताएगा।', title_id = 'Mengintip cuaca ⛅', body_id = 'Cuaca di luar tidak jelas? Biarkan fitur Cuaca dan Pakaian langsung memberi tahu kecepatan angin yang tak terlihat dari jendela dan pakaian yang tepat.', title_ja = 'お天気チェック ⛅', body_ja = '外の天気がはっきりしない？「天気と服装」ツールが、窓からは見えない風の強さとぴったりの服装をすぐに教えてくれます。', title_ko = '날씨 탐색 ⛅', body_ko = '바깥 날씨가 애매한가요? 날씨와 옷차림 도구가 창밖으로는 보이지 않는 바람 세기와 알맞은 옷차림을 바로 알려 줄 거예요.', title_nl = 'Het weer verkennen ⛅', body_nl = 'Is het weer buiten niet helemaal duidelijk? Laat de tool Weer en kleding je meteen de windsnelheid vertellen die je niet vanuit het raam ziet, plus de juiste outfit.', title_pl = 'Rozpoznanie pogody ⛅', body_pl = 'Pogoda na dworze niepewna? Niech narzędzie Pogoda i ubiór od razu powie ci, jak mocno wieje wiatr, czego nie widać przez okno, i jaki zestaw wybrać.', title_pt = 'Exploração do tempo ⛅', body_pt = 'O tempo lá fora não está bem definido? Deixe a ferramenta Tempo e Roupa dizer-lhe na hora a velocidade do vento que não se vê da janela e a roupa certa.', title_sv = 'Väderspaning ⛅', body_sv = 'Är vädret ute osäkert? Låt Väder och kläder direkt berätta vindstyrkan som inte syns genom fönstret och rätt klädsel.', title_vi = 'Thám thính thời tiết ⛅', body_vi = 'Thời tiết bên ngoài không rõ ràng? Hãy để công cụ Thời tiết và trang phục cho mẹ biết ngay tốc độ gió mà nhìn qua cửa sổ không thấy được và bộ đồ phù hợp.', title_zh = '天气侦察 ⛅', body_zh = '外面天气说不准？让天气穿衣工具马上告诉你窗外看不到的风速和合适的搭配吧。' WHERE id = '0535564e-f2c8-4264-bd71-a94e3154d928' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tardes con música 🎶', body_es = 'La forma más fácil de calmar los lloriqueos de la tarde es poner su canción favorita y bailar abrazados.', title_fr = 'Soirées en musique 🎶', body_fr = 'Le moyen le plus simple de calmer les pleurnicheries de fin de journée, c''est de mettre sa chanson préférée et de danser en le serrant contre vous.', title_hi = 'संगीत भरी शामें 🎶', body_hi = 'शाम की चिड़चिड़ाहट दूर करने का सबसे आसान तरीका है उसका पसंदीदा गाना लगाना और उसे गले लगाकर नाचना।', title_id = 'Malam penuh musik 🎶', body_id = 'Cara termudah meredakan rengekan menjelang sore adalah memutar lagu kesukaannya lalu berdansa sambil berpelukan dengannya.', title_ja = '音楽のある夕方 🎶', body_ja = '夕方のぐずぐずをいちばんかんたんに解決する方法は、お気に入りの曲をかけて、抱きしめて一緒に踊ることです。', title_ko = '음악이 있는 저녁 🎶', body_ko = '늦은 오후의 칭얼거림을 달래는 가장 쉬운 방법은 좋아하는 노래를 틀고 꼭 안고 춤추는 거예요.', title_nl = 'Muzikale avonden 🎶', body_nl = 'De makkelijkste manier om het gezeur aan het eind van de middag op te lossen: zet zijn lievelingsliedje op en dans knuffelend met hem.', title_pl = 'Muzyczne wieczory 🎶', body_pl = 'Najprostszy sposób na wieczorne marudzenie to włączyć jego ulubioną piosenkę, przytulić go i razem zatańczyć.', title_pt = 'Noites com música 🎶', body_pt = 'A forma mais fácil de acalmar a rabugice do fim da tarde é pôr uma canção de que ele gosta e dançar abraçados.', title_sv = 'Musikaliska kvällar 🎶', body_sv = 'Det enklaste sättet att lösa gnället på eftermiddagen är att sätta på en låt barnet gillar, krama det och dansa tillsammans.', title_vi = 'Những buổi tối âm nhạc 🎶', body_vi = 'Cách dễ nhất để dỗ những cơn quấy chiều tối là bật bài hát bé thích, ôm bé và cùng nhảy.', title_zh = '音乐之夜 🎶', body_zh = '解决傍晚哭闹最简单的办法，就是放一首宝宝最爱的歌，抱着宝宝一起跳舞。' WHERE id = '51cec612-e243-435d-9b60-1e3269d69cee' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Se quita los zapatos 👟', body_es = '¿Vestirle se ha convertido en una lucha libre? Se quita él solo los calcetines y los zapatos. ¡Admira su motricidad!', title_fr = 'Il enlève ses chaussures tout seul 👟', body_fr = 'L''habillage s''est transformé en match de lutte ? Il retire lui-même ses chaussettes et ses chaussures. Admirez sa motricité !', title_hi = 'अपने जूते खुद उतारता है 👟', body_hi = 'कपड़े पहनाना अब कुश्ती बन गया है? वह अपने मोज़े और जूते खुद खींचकर उतार देता है। उसकी मोटर स्किल्स पर हैरान रह जाइए!', title_id = 'Ia melepas sepatunya sendiri 👟', body_id = 'Memakaikan baju kini seperti pertandingan gulat? Ia menarik lepas kaus kaki dan sepatunya sendiri. Kagumi keterampilan motoriknya!', title_ja = '自分で靴を脱ぐ 👟', body_ja = 'お着替えがレスリングの試合に？靴下や靴を自分で引っぱって脱いでいます。運動能力の成長に感心しましょう！', title_ko = '스스로 신발을 벗어요 👟', body_ko = '옷 입히기가 레슬링 경기가 됐나요? 양말과 신발을 스스로 잡아당겨 벗어요. 운동 능력에 감탄해 보세요!', title_nl = 'Hij trekt zijn schoenen uit 👟', body_nl = 'Is aankleden een soort worstelwedstrijd geworden? Hij trekt zelf zijn sokken en schoenen uit. Bewonder zijn motorische vaardigheid!', title_pl = 'Sam zdejmuje buciki 👟', body_pl = 'Ubieranie zamieniło się w zapasy? Sam ściąga skarpetki i buciki. Podziwiaj jego motorykę!', title_pt = 'Tira os próprios sapatos 👟', body_pt = 'Vesti-lo já se tornou uma luta livre? Ele próprio puxa e tira as meias e os sapatos. Admire a motricidade dele!', title_sv = 'Tar av sig skorna själv 👟', body_sv = 'Har påklädningen blivit en sorts brottning? Barnet drar själv av sig strumporna och skorna. Beundra motoriken!', title_vi = 'Bé tự cởi giày 👟', body_vi = 'Mặc đồ cho bé đã thành một trận đấu vật? Bé tự kéo tất và giày ra. Thật đáng ngưỡng mộ kỹ năng vận động của bé!', title_zh = '自己脱鞋 👟', body_zh = '穿衣服变成了摔跤比赛？宝宝已经会自己把袜子和鞋子拽下来了。为宝宝的动作能力赞叹吧！' WHERE id = '533a4ec1-68c0-4cf3-92cd-723b3f8c0979' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juegos de lógica 🧩', body_es = '¿Mete los juguetes en la caja y luego la vacía entera? Se desarrolla su lógica de «dentro» y «fuera». No interrumpas esta actividad.', title_fr = 'Jeux de logique 🧩', body_fr = 'Il met ses jouets dans une boîte, puis la vide entièrement ? Sa logique du « dedans » et du « dehors » se développe. N''empêchez pas cette activité.', title_hi = 'तर्क वाले खेल 🧩', body_hi = 'डिब्बे में खिलौने डालकर फिर सब खाली कर देता है? ''अंदर'' और ''बाहर'' की समझ विकसित हो रही है। इस गतिविधि को मत रोकिए।', title_id = 'Permainan logika 🧩', body_id = 'Ia memasukkan mainan ke kotak lalu mengeluarkan semuanya? Logika "di dalam" dan "di luar" sedang berkembang. Jangan halangi aktivitas ini.', title_ja = '考える遊び 🧩', body_ja = '箱におもちゃを入れては、ぜんぶ出してしまう？「中」と「外」の考え方が育っています。この遊びをじゃましないであげましょう。', title_ko = '논리 놀이 🧩', body_ko = '상자에 장난감을 넣었다가 다시 모두 쏟아 내나요? ''안''과 ''밖''의 논리가 자라고 있어요. 이 놀이를 막지 마세요.', title_nl = 'Logische spelletjes 🧩', body_nl = 'Gooit je baby speeltjes in een doos en haalt hij ze er daarna allemaal weer uit? Zijn logica van in en uit ontwikkelt zich. Houd hem niet tegen.', title_pl = 'Zabawy logiczne 🧩', body_pl = 'Wrzuca zabawki do pudełka, a potem wszystkie wysypuje? Rozwija się logika „w środku” i „na zewnątrz”. Nie przeszkadzaj mu w tym.', title_pt = 'Jogos de lógica 🧩', body_pt = 'Atira os brinquedos para dentro da caixa e depois esvazia-a toda? A lógica de dentro e fora está a desenvolver-se. Não interrompa esta atividade.', title_sv = 'Logiklekar 🧩', body_sv = 'Lägger barnet leksakerna i lådan och tömmer sedan ut alltihop? Logiken kring i och ur utvecklas. Hindra inte den här aktiviteten.', title_vi = 'Trò chơi tư duy 🧩', body_vi = 'Bé bỏ đồ chơi vào hộp rồi đổ hết ra? Tư duy về "bên trong" và "bên ngoài" đang phát triển. Đừng ngăn cản hoạt động này nhé.', title_zh = '逻辑游戏 🧩', body_zh = '宝宝把玩具扔进盒子，再全部倒出来？“里面”和“外面”的逻辑正在发展。别阻止这项活动。' WHERE id = '7bbccad8-a83a-493c-82e1-d823d261e04b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de noche de papá 👨‍🍼', body_es = 'No cargues tú sola con todos los despertares nocturnos. Despierta también a tu pareja: ser un equipo es repartir la responsabilidad a partes iguales.', title_fr = 'Le service de nuit de papa 👨‍🍼', body_fr = 'Ne gérez pas les réveils nocturnes toute seule. Réveillez aussi votre conjoint, être une équipe, c''est partager la responsabilité à parts égales.', title_hi = 'पापा की रात की ड्यूटी 👨‍🍼', body_hi = 'रात में जागने का बोझ अकेले मत उठाइए। अपने साथी को भी जगाइए, टीम होने का मतलब है ज़िम्मेदारी बराबर बाँटना।', title_id = 'Giliran malam ayah 👨‍🍼', body_id = 'Jangan tanggung sendiri saat ia terbangun di malam hari. Bangunkan juga pasangan Anda, menjadi tim berarti berbagi tanggung jawab secara adil.', title_ja = 'パパの夜の当番 👨‍🍼', body_ja = '夜中に起きるのを、ひとりで抱えこまないで。パートナーも起こしましょう。チームとは責任を平等に分け合うことです。', title_ko = '아빠의 밤 당번 👨‍🍼', body_ko = '밤에 깨는 일을 혼자 다 감당하지 마세요. 배우자도 깨우세요, 한 팀이 된다는 건 책임을 똑같이 나누는 거예요.', title_nl = 'Papa''s avonddienst 👨‍🍼', body_nl = 'Draag het ''s nachts opstaan niet helemaal alleen. Maak je partner ook wakker, een team zijn betekent de verantwoordelijkheid eerlijk delen.', title_pl = 'Nocna zmiana taty 👨‍🍼', body_pl = 'Nie dźwigaj nocnych pobudek zupełnie sama. Obudź też partnera, bycie drużyną to równy podział odpowiedzialności.', title_pt = 'O turno da noite do pai 👨‍🍼', body_pt = 'Não aguente sozinha todos os despertares noturnos. Acorde também o seu companheiro: ser uma equipa é dividir a responsabilidade por igual.', title_sv = 'Pappas nattskift 👨‍🍼', body_sv = 'Ta inte nattuppvaknandena helt ensam. Väck din partner också, att vara ett lag är att dela ansvaret lika.', title_vi = 'Ca đêm của bố 👨‍🍼', body_vi = 'Đừng một mình gánh hết những lần thức dậy ban đêm. Hãy gọi cả bố dậy, là một đội nghĩa là chia đều trách nhiệm.', title_zh = '爸爸的夜班 👨‍🍼', body_zh = '夜醒别全都自己扛。也叫醒你的伴侣，团队就是平分责任。' WHERE id = '84cdedf9-5de5-49c9-887b-6f8ccc988990' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubre un sitio para mamá ☕', body_es = 'Con tanto cansancio, tú también necesitas tomar el aire. Busca en Lugares para mamás una cafetería tranquila cerca y ve.', title_fr = 'Un lieu à découvrir pour maman ☕', body_fr = 'Avec toute cette fatigue, vous aussi avez besoin de prendre l''air. Trouvez un café calme près de chez vous dans les Lieux adaptés aux mamans et allez-y.', title_hi = 'माँ के लिए जगह की खोज ☕', body_hi = 'इतनी थकान के बीच आपको भी ताज़ी हवा चाहिए। माँ के अनुकूल जगहों में से पास का कोई शांत कैफ़े ढूँढिए और चली जाइए।', title_id = 'Menemukan tempat untuk Bunda ☕', body_id = 'Di tengah semua rasa lelah ini, Anda juga perlu menghirup udara segar. Temukan kafe tenang terdekat di Tempat Ramah Ibu dan pergilah.', title_ja = 'ママのための場所探し ☕', body_ja = 'こんなに疲れているからこそ、あなたも気分転換が必要です。「ママにやさしいスポット」で近くの静かなカフェを見つけて、出かけましょう。', title_ko = '엄마를 위한 장소 찾기 ☕', body_ko = '이렇게 지친 와중에도 엄마는 바람을 쐬어야 해요. 엄마 친화 장소에서 근처의 조용한 카페를 찾아가 보세요.', title_nl = 'Een plek ontdekken voor mama ☕', body_nl = 'Met al die vermoeidheid heb jij ook frisse lucht nodig. Zoek in Mamavriendelijke plekken een rustig café in de buurt en ga erheen.', title_pl = 'Odkryj miejsce dla mamy ☕', body_pl = 'Przy takim zmęczeniu ty też musisz złapać oddech. Znajdź w Miejscach przyjaznych mamom cichą kawiarnię w pobliżu i idź tam.', title_pt = 'Descobrir um lugar para a mãe ☕', body_pt = 'No meio de tanto cansaço, a mãe também precisa de apanhar ar. Encontre nos Locais Amigos das Mães um café tranquilo aqui perto e vá até lá.', title_sv = 'Hitta en plats för mamma ☕', body_sv = 'Mitt i all trötthet behöver du också luft. Hitta ett lugnt kafé i närheten bland Mammavänliga platser och gå dit.', title_vi = 'Khám phá địa điểm cho mẹ ☕', body_vi = 'Giữa bao mệt mỏi, mẹ cũng cần hít thở không khí mới. Hãy tìm một quán cà phê yên tĩnh gần nhà trong Địa điểm thân thiện với mẹ và đi thôi.', title_zh = '寻找妈妈的好去处 ☕', body_zh = '这么累的日子里，你也需要透透气。在妈妈友好场所里找一家附近安静的咖啡馆，去坐坐吧。' WHERE id = 'a4c45285-b9cc-4763-a80c-d694137bbb6a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Prueba y error 🧱', body_es = 'Intenta poner un cubo de juguete encima de otro, pero se cae. Vuelve a probar con atención. Observa en silencio sus pequeños intentos de ingeniería.', title_fr = 'Essais et erreurs 🧱', body_fr = 'Il essaie d''empiler deux cubes, mais ils tombent. Il recommence avec attention. Observez en silence ses petits essais d''ingénieur.', title_hi = 'कोशिश और गलती 🧱', body_hi = 'दो खिलौना ब्लॉक एक के ऊपर एक रखने की कोशिश करता है, पर वे गिर जाते हैं। वह ध्यान से फिर कोशिश करता है। उसकी इन छोटी-छोटी इंजीनियरिंग कोशिशों को चुपचाप देखिए।', title_id = 'Coba dan gagal 🧱', body_id = 'Ia mencoba menumpuk dua balok mainan, tapi jatuh. Ia mencoba lagi dengan saksama. Saksikan usaha insinyur kecil ini dengan diam-diam.', title_ja = '試行錯誤 🧱', body_ja = '積み木を2つ重ねようとして、くずれてしまう。それでも注意深くまた挑戦します。この小さなエンジニアの挑戦を、静かに見守りましょう。', title_ko = '시행착오 🧱', body_ko = '블록 두 개를 쌓으려다 무너져도 다시 조심스럽게 시도해요. 이 꼬마 엔지니어의 도전을 조용히 지켜봐 주세요.', title_nl = 'Vallen en opstaan 🧱', body_nl = 'Je baby probeert twee blokken op elkaar te zetten, maar ze vallen om. Hij probeert het aandachtig opnieuw. Kijk stil naar deze kleine bouwpogingen.', title_pl = 'Próby i błędy 🧱', body_pl = 'Próbuje postawić jeden klocek na drugim, ale się przewracają. Uważnie próbuje znowu. Obserwuj w ciszy te małe inżynierskie próby.', title_pt = 'Tentativa e erro 🧱', body_pt = 'Tenta pôr dois cubos um em cima do outro, mas caem. Volta a tentar com atenção. Acompanhe em silêncio estas pequenas tentativas de engenharia.', title_sv = 'Försök och misstag 🧱', body_sv = 'Barnet försöker stapla två leksaksklossar på varandra, men de ramlar. Det försöker igen, noggrant. Följ de här små ingenjörsförsöken i tystnad.', title_vi = 'Thử và sai 🧱', body_vi = 'Bé cố xếp hai khối đồ chơi chồng lên nhau, nhưng bị đổ. Bé chăm chú thử lại. Hãy lặng lẽ ngắm những nỗ lực "kỹ sư" nhỏ bé này.', title_zh = '尝试与犯错 🧱', body_zh = '宝宝想把两块积木叠起来，可是倒了。宝宝认真地再试一次。默默地看着这些小小的工程尝试吧。' WHERE id = '37e8bf23-2dc4-4b8c-8c8f-49146922ba57' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ideas de comidas 🍲', body_es = '¿Cansada de cocinar siempre lo mismo? Echa un vistazo en Recetas saludables a nuevos y ricos alimentos para comer con los dedos para peques de 10 meses.', title_fr = 'Idées de repas 🍲', body_fr = 'Fatiguée de cuisiner toujours la même chose ? Découvrez dans les Recettes saines de nouveaux aliments délicieux à manger avec les doigts pour les enfants de 10 mois.', title_hi = 'खाने के आइडिया 🍲', body_hi = 'एक ही चीज़ें पकाते-पकाते थक गईं? सेहतमंद रेसिपी में 10 महीने के बच्चों के लिए नए और स्वादिष्ट फ़िंगर फ़ूड देखिए।', title_id = 'Ide makanan 🍲', body_id = 'Bosan memasak yang itu-itu saja? Lihat finger food baru yang lezat untuk anak 10 bulan di Resep Sehat.', title_ja = 'ごはんのアイデア 🍲', body_ja = '同じものばかりつくるのに飽きてきた？「ヘルシーレシピ」で、生後10か月の赤ちゃん向けの新しくておいしい手づかみ食べメニューをチェックしましょう。', title_ko = '식사 아이디어 🍲', body_ko = '늘 같은 요리를 하느라 지쳤나요? 건강한 레시피에서 10개월 아기를 위한 새롭고 맛있는 핑거 푸드를 살펴보세요.', title_nl = 'Ideeën voor eten 🍲', body_nl = 'Ben je het zat om steeds hetzelfde te koken? Bekijk in Gezonde recepten nieuw en lekker vingervoedsel voor kindjes van 10 maanden.', title_pl = 'Pomysły na posiłki 🍲', body_pl = 'Masz dość gotowania ciągle tego samego? Zajrzyj do Zdrowych przepisów po nowe, smaczne przekąski do jedzenia rączkami dla 10-miesięcznych maluszków.', title_pt = 'Ideias para refeições 🍲', body_pt = 'Cansada de cozinhar sempre o mesmo? Espreite nas Receitas Saudáveis alimentos novos e deliciosos para comer à mão, para bebés de 10 meses.', title_sv = 'Matidéer 🍲', body_sv = 'Trött på att laga samma saker? Kika på ny och god fingermat för 10 månader gamla barn i Hälsosamma recept.', title_vi = 'Ý tưởng món ăn 🍲', body_vi = 'Mẹ chán nấu đi nấu lại những món cũ? Hãy xem các món ăn cầm tay mới, ngon miệng cho bé 10 tháng trong Công thức lành mạnh.', title_zh = '饮食灵感 🍲', body_zh = '总做一样的饭做烦了？去健康食谱看看适合10个月宝宝的新鲜美味手指食物吧。' WHERE id = '732cb07a-0e5f-4dc9-9d15-78470db05396' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Habitación tranquila, mente tranquila 🤫', body_es = 'Al preparaos para dormir hay que bajar los decibelios de la habitación. Comprueba con el Medidor de sonido el nivel de tu voz y del entorno.', title_fr = 'Chambre calme, esprit calme 🤫', body_fr = 'En préparant le coucher, il faut baisser le niveau sonore de la pièce. Vérifiez avec le Sonomètre le niveau de votre voix et des bruits ambiants.', title_hi = 'शांत कमरा, शांत मन 🤫', body_hi = 'सोने की तैयारी करते समय कमरे का डेसिबल कम करना ज़रूरी है। साउंड मीटर से अपनी आवाज़ और आसपास के शोर की सीमा जाँचिए।', title_id = 'Kamar tenang, pikiran tenang 🤫', body_id = 'Saat bersiap tidur, desibel di kamar perlu diturunkan. Cek batas suara Anda sendiri dan sekitarnya dengan Pengukur Suara.', title_ja = '静かな部屋、静かな心 🤫', body_ja = '寝る準備をするときは、部屋の音量（デシベル）を下げることが大切です。「サウンドメーター」で、あなたの声とまわりの音をチェックしましょう。', title_ko = '조용한 방, 차분한 마음 🤫', body_ko = '잠잘 준비를 할 때는 방의 데시벨을 낮춰야 해요. 소음 측정기로 엄마 목소리와 주변 소리의 한도를 확인하세요.', title_nl = 'Rustige kamer, rustig hoofd 🤫', body_nl = 'Bij het klaarmaken voor de nacht moet het aantal decibel in de kamer omlaag. Controleer met de Geluidsmeter het niveau van je eigen stem en van de omgeving.', title_pl = 'Cichy pokój, spokojna głowa 🤫', body_pl = 'Przy szykowaniu do snu trzeba obniżyć poziom decybeli w pokoju. Sprawdź Miernikiem dźwięku swój głos i hałas otoczenia.', title_pt = 'Quarto calmo, cabeça calma 🤫', body_pt = 'Ao preparar o sono, é preciso baixar os decibéis do quarto. Verifique com o Medidor de Som o limite da sua voz e do ambiente.', title_sv = 'Lugnt rum, lugn hjärna 🤫', body_sv = 'När ni gör er redo för sömnen behöver decibelnivån i rummet sänkas. Kolla din egen röst och omgivningens nivå med Ljudmätaren.', title_vi = 'Phòng yên tĩnh, đầu óc thư thái 🤫', body_vi = 'Khi chuẩn bị đi ngủ, cần giảm mức decibel trong phòng. Hãy dùng Đo âm thanh để kiểm tra giọng nói của mẹ và độ ồn xung quanh.', title_zh = '安静的房间，平静的大脑 🤫', body_zh = '准备睡觉时，要把房间里的分贝降下来。用噪音测量检查一下你自己的声音和周围环境的音量吧。' WHERE id = 'a387d51e-9e9d-455a-be61-4650ee6ffa63' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un cuento especial 🪄', body_es = 'Crea en Cuentos inteligentes la historia del héroe que dentro de solo 10 días será un poco más mayor y llena la habitación de magia.', title_fr = 'Un conte unique 🪄', body_fr = 'Dans les Contes intelligents, créez l''histoire du héros qui grandira dans seulement 10 jours et remplissez la chambre de magie.', title_hi = 'खास कहानी 🪄', body_hi = 'स्मार्ट कहानियों में उस हीरो की कहानी बनाइए जो बस 10 दिन बाद और बड़ा हो जाएगा, और कमरे को जादू से भर दीजिए।', title_id = 'Dongeng istimewa 🪄', body_id = 'Di Dongeng Pintar, buat kisah pahlawan yang 10 hari lagi akan bertambah besar, dan penuhi kamar dengan keajaiban.', title_ja = '特別なお話 🪄', body_ja = '「スマートおはなし」で、あと10日で大きくなるヒーローのお話をつくって、部屋を魔法で包みましょう。', title_ko = '특별한 동화 이야기 🪄', body_ko = '스마트 동화에서 딱 10일 뒤면 한 뼘 더 자랄 주인공의 이야기를 만들어 방을 마법으로 채워 보세요.', title_nl = 'Een eigen sprookje 🪄', body_nl = 'Maak in Slimme sprookjes het verhaal van een held die over maar 10 dagen weer groter wordt en vul de kamer met magie.', title_pl = 'Wyjątkowa bajka 🪄', body_pl = 'Stwórz w Mądrych bajkach historię o bohaterze, który już za 10 dni będzie starszy, i wypełnij pokój magią.', title_pt = 'Uma história especial 🪄', body_pt = 'Crie nas Histórias Inteligentes a história do herói que vai crescer daqui a apenas 10 dias e encha o quarto de magia.', title_sv = 'En personlig saga 🪄', body_sv = 'Fyll rummet med magi genom att skapa sagan om hjälten som blir större om bara 10 dagar i Smarta sagor.', title_vi = 'Câu chuyện cổ tích riêng 🪄', body_vi = 'Hãy tạo trong Truyện cổ tích thông minh câu chuyện về người hùng sẽ lớn thêm chỉ sau 10 ngày nữa và phủ căn phòng bằng phép màu.', title_zh = '专属故事 🪄', body_zh = '在智能故事里创作一个再过10天就要长大的小英雄的故事，让房间充满魔法吧。' WHERE id = '439ac8e3-ab5f-434a-bb69-d98dee8208cd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La foto de las risas 📸', body_es = 'Cada día se convierte en una personita más especial y tierna. Abre ya la Sesión de fotos del bebé, decórala con stickers y congela este momento tan alegre.', title_fr = 'La photo des sourires 📸', body_fr = 'Chaque jour, il devient une personne un peu plus différente et adorable. Ouvrez tout de suite la Séance photo bébé, décorez avec des stickers et figez ce moment joyeux.', title_hi = 'मुस्कानों की तस्वीर 📸', body_hi = 'वह हर दिन और भी अनोखा और प्यारा इंसान बन रहा है। तुरंत बेबी फ़ोटोशूट खोलिए, स्टिकर से सजाइए और इस खुशी भरे पल को थाम लीजिए।', title_id = 'Foto penuh tawa 📸', body_id = 'Setiap hari ia menjadi pribadi yang makin berbeda dan manis. Segera buka Sesi Foto Bayi, hiasi dengan stiker, dan bekukan momen ceria ini.', title_ja = '笑顔の写真 📸', body_ja = '赤ちゃんは日に日に個性豊かで、かわいい人になっていきます。すぐに「ベビーフォトセッション」を開いて、ステッカーで飾り、この楽しい瞬間を残しましょう。', title_ko = '웃음을 담은 사진 📸', body_ko = '아기가 날마다 더 특별하고 사랑스러운 사람이 되어 가요. 지금 바로 아기 사진 촬영을 열어 스티커로 꾸미고 이 즐거운 순간을 남겨 두세요.', title_nl = 'Een foto vol lachjes 📸', body_nl = 'Hij wordt elke dag een ander, lief mensje. Open meteen Babyfotoshoot, versier de foto met stickers en bevries dit vrolijke moment.', title_pl = 'Zdjęcie uśmiechów 📸', body_pl = 'Z każdym dniem staje się innym, słodszym człowiekiem. Od razu otwórz Sesję zdjęciową dziecka, ozdób zdjęcie naklejkami i zatrzymaj tę radosną chwilę.', title_pt = 'A foto dos sorrisos 📸', body_pt = 'Cada dia é uma pessoa mais diferente e mais doce. Abra já a Sessão Fotográfica do Bebé, decore com autocolantes e congele este momento alegre.', title_sv = 'Bilden av skratten 📸', body_sv = 'Barnet blir en annorlunda och sötare människa för varje dag. Öppna Babyfotografering direkt, dekorera med klistermärken och frys den glada stunden.', title_vi = 'Ảnh những nụ cười 📸', body_vi = 'Mỗi ngày bé lại thành một con người khác biệt và đáng yêu hơn. Hãy mở ngay Chụp ảnh cho bé, trang trí bằng nhãn dán và lưu giữ khoảnh khắc vui tươi này.', title_zh = '笑容快照 📸', body_zh = '宝宝每天都变得更独特、更可爱。马上打开宝宝写真，用贴纸装饰，定格这个欢乐的瞬间吧。' WHERE id = 'ff800946-b6d3-4e88-8699-fe114e37b692' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gestionar las emociones 📝', body_es = '¿Tienes los nervios a flor de piel y estás a punto de explotar? Vuelca todo el estrés en el Diario de ánimo y respira hondo.', title_fr = 'Gérer ses émotions 📝', body_fr = 'Vous avez les nerfs à vif, prête à exploser à tout moment ? Déversez tout votre stress dans le Journal d''humeur et respirez profondément.', title_hi = 'भावनाओं को संभालना 📝', body_hi = 'नसें तनी हुई हैं और किसी भी पल फट पड़ने को तैयार हैं? सारा तनाव मूड डायरी में उतार दीजिए और गहरी साँस लीजिए।', title_id = 'Mengelola emosi 📝', body_id = 'Saraf Anda tegang dan rasanya bisa meledak kapan saja? Tuangkan semua stres ke Buku Harian Suasana Hati dan tarik napas dalam-dalam.', title_ja = '気持ちをコントロール 📝', body_ja = '神経がぴりぴりして、今にも爆発しそう？「気分日記」にストレスをぜんぶ書き出して、深呼吸しましょう。', title_ko = '감정 다스리기 📝', body_ko = '신경이 곤두서서 금방이라도 폭발할 것 같나요? 기분 일기에 스트레스를 모두 옮겨 적고 깊게 숨을 쉬세요.', title_nl = 'Emoties beheersen 📝', body_nl = 'Staan je zenuwen strak gespannen en kun je elk moment ontploffen? Zet alle stress in je Stemmingsdagboek en adem diep in.', title_pl = 'Panowanie nad emocjami 📝', body_pl = 'Nerwy napięte jak struna i zaraz wybuchniesz? Przelej cały stres do Dziennika nastroju i weź głęboki oddech.', title_pt = 'Gerir as emoções 📝', body_pt = 'Tem os nervos à flor da pele e está prestes a explodir? Passe todo o stress para o Diário de Humor e respire fundo.', title_sv = 'Hantera känslorna 📝', body_sv = 'Är nerverna på helspänn och kan du explodera när som helst? För över all stress till Humördagboken och andas djupt.', title_vi = 'Kiểm soát cảm xúc 📝', body_vi = 'Thần kinh căng như dây đàn và mẹ có thể bùng nổ bất cứ lúc nào? Hãy trút hết căng thẳng vào Nhật ký tâm trạng và hít thở thật sâu.', title_zh = '管理情绪 📝', body_zh = '神经紧绷，随时可能爆发？把所有的压力写进心情日记，深呼吸吧。' WHERE id = '16cae145-7589-4ff6-ae2c-368fe115d232' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hacerse amigo de la oscuridad 🌙', body_es = 'Para que se duerma antes, añade a la rutina de la noche un momento de oscuridad. Apaga todas las luces que sobran en la habitación.', title_fr = 'Apprivoiser l''obscurité 🌙', body_fr = 'Pour l''aider à s''endormir plus vite, ajoutez l''obscurité à la routine du soir. Éteignez toutes les lumières superflues de la pièce.', title_hi = 'अँधेरे से दोस्ती 🌙', body_hi = 'उसे जल्दी सुलाने के लिए शाम के रूटीन में अँधेरे से पहचान जोड़िए। कमरे की सारी अतिरिक्त लाइटें बंद कीजिए।', title_id = 'Bersahabat dengan gelap 🌙', body_id = 'Agar ia lebih cepat tertidur, kenalkan suasana gelap dalam rutinitas malam. Matikan semua lampu tambahan di kamar.', title_ja = '暗さと仲よしに 🌙', body_ja = '早く寝つけるように、夜のルーティンに暗さに慣れる時間を取り入れましょう。部屋のよけいな明かりはすべて消しましょう。', title_ko = '어둠과 친해지기 🌙', body_ko = '빨리 잠들 수 있도록 저녁 루틴에 어둠에 익숙해지는 시간을 더하세요. 방의 불필요한 조명을 모두 끄세요.', title_nl = 'Vriendschap met het donker 🌙', body_nl = 'Voeg kennismaking met het donker toe aan de avondroutine, zodat je baby sneller in slaap valt. Doe alle extra lampjes in de kamer uit.', title_pl = 'Przyjaźń z ciemnością 🌙', body_pl = 'Aby szybciej zasypiał, dodaj do wieczornej rutyny oswajanie z ciemnością. Wyłącz w pokoju wszystkie dodatkowe światła.', title_pt = 'Fazer amizade com o escuro 🌙', body_pt = 'Para o ajudar a adormecer mais depressa, junte à rotina da noite um momento de habituação ao escuro. Apague todas as luzes desnecessárias do quarto.', title_sv = 'Vänskap med mörkret 🌙', body_sv = 'Lägg till en stund i mörker i kvällsrutinen så att barnet somnar fortare. Släck alla onödiga lampor i rummet.', title_vi = 'Làm bạn với bóng tối 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy thêm bước làm quen với bóng tối vào nếp sinh hoạt buổi tối. Tắt hết đèn không cần thiết trong phòng.', title_zh = '和黑暗做朋友 🌙', body_zh = '为了让宝宝更快入睡，在晚间作息里加入熟悉黑暗的环节。关掉房间里所有多余的灯。' WHERE id = '9b99e928-dd9a-40d6-9254-12459dac4a3d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reconoce las partes del cuerpo 👀', body_es = '¿Cuando le preguntas «¿dónde está tu nariz?» la toca con el dedo? ¡Su comprensión mental está en lo más alto!', title_fr = 'Il reconnaît les parties du corps 👀', body_fr = 'Quand vous demandez « Où est ton nez ? », il le touche du doigt pour le montrer ? Sa compréhension est au top !', title_hi = 'शरीर के अंग पहचानता है 👀', body_hi = '''तुम्हारी नाक कहाँ है?'' पूछने पर उँगली से छूकर दिखाता है? उसकी समझ चरम पर है!', title_id = 'Ia mengenali anggota tubuhnya 👀', body_id = 'Saat ditanya "Hidungnya di mana?", ia menyentuh dan menunjuknya dengan jari? Daya tangkapnya sedang di puncak!', title_ja = '体の部分がわかる 👀', body_ja = '「お鼻はどこ？」と聞くと、指でさわって教えてくれますか？理解する力が最高潮です！', title_ko = '몸의 부위를 알아요 👀', body_ko = '''코 어디 있어?'' 하고 물으면 손가락으로 만지며 가리키나요? 인지 능력이 최고조예요!', title_nl = 'Hij kent zijn lichaamsdelen 👀', body_nl = 'Raakt je baby zijn neus aan als je vraagt: waar is je neus? Zijn begrip is op zijn hoogtepunt!', title_pl = 'Zna części ciała 👀', body_pl = 'Gdy pytasz „gdzie jest twój nosek?”, dotyka go paluszkiem i pokazuje? Rozumienie jest u szczytu!', title_pt = 'Reconhece as partes do corpo 👀', body_pt = 'Quando pergunta "onde está o teu nariz?", ele toca-lhe com o dedo e mostra? A compreensão está no auge!', title_sv = 'Känner igen kroppsdelarna 👀', body_sv = 'Pekar barnet på näsan när du frågar ''var är din näsa?''? Den mentala förståelsen är på topp!', title_vi = 'Bé nhận biết các bộ phận cơ thể 👀', body_vi = 'Khi mẹ hỏi "Mũi con đâu?", bé lấy ngón tay chạm vào để chỉ? Khả năng nhận thức của bé đang ở đỉnh cao!', title_zh = '认识身体部位 👀', body_zh = '问宝宝“你的鼻子在哪儿？”，宝宝会用手指摸着指给你看？认知理解力正处在高峰！' WHERE id = 'ee2e2e79-277e-4a7f-9473-05aa36068880' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una noche de victoria 🥂', body_es = 'Esta noche, cuando tu bebé se duerma, brindad tu pareja y tú diciendo «somos un equipo estupendo». ¡Lo estáis haciendo de maravilla!', title_fr = 'Une soirée de victoire 🥂', body_fr = 'Ce soir, quand bébé dormira, portez un toast avec votre conjoint : « Nous formons une super équipe. » Vous faites vraiment un travail formidable !', title_hi = 'जीत की शाम 🥂', body_hi = 'आज शाम बच्चे के सोने के बाद अपने साथी से कहिए, ''हम एक बेहतरीन टीम हैं''। आप सच में शानदार काम कर रहे हैं!', title_id = 'Malam kemenangan 🥂', body_id = 'Malam ini, setelah si kecil tidur, bersulanglah bersama pasangan: "Kita tim yang hebat." Kalian benar-benar melakukan pekerjaan yang sempurna!', title_ja = '勝利の夜 🥂', body_ja = '今夜は赤ちゃんが寝たら、パートナーと「私たちは最高のチーム」と乾杯しましょう。あなたたちは本当にすばらしい仕事をしています！', title_ko = '승리의 저녁 🥂', body_ko = '오늘 저녁 아기가 잠든 뒤 배우자와 ''우리는 멋진 팀이야''라며 건배해 보세요. 정말 훌륭하게 해내고 있어요!', title_nl = 'Een feestelijke avond 🥂', body_nl = 'Proost vanavond, als je baby slaapt, met je partner: wij zijn een geweldig team. Jullie doen het echt perfect!', title_pl = 'Wieczór zwycięstwa 🥂', body_pl = 'Dziś wieczorem, gdy maluszek zaśnie, wznieście z partnerem toast: „Jesteśmy świetną drużyną”. Naprawdę wykonujecie wspaniałą pracę!', title_pt = 'Uma noite de vitória 🥂', body_pt = 'Esta noite, depois de o bebé adormecer, façam um brinde com o seu companheiro: "somos uma ótima equipa". Estão mesmo a fazer um trabalho perfeito!', title_sv = 'Segerkväll 🥂', body_sv = 'I kväll, när barnet har somnat, skåla med din partner och säg: vi är ett fantastiskt lag. Ni gör verkligen ett perfekt jobb!', title_vi = 'Buổi tối chiến thắng 🥂', body_vi = 'Tối nay sau khi bé ngủ, hãy cùng bố nâng ly: "Chúng mình là một đội tuyệt vời". Bố mẹ thật sự đang làm rất tốt!', title_zh = '胜利之夜 🥂', body_zh = '今晚宝宝睡着后，和伴侣举杯说一句：“我们是最棒的团队！”你们真的做得非常好！' WHERE id = '2cb20f11-aee5-456a-b969-c87733104c72' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sospechas de alergia 🤖', body_es = '¿Le has dado un alimento nuevo y le han salido rojeces en las mejillas? Antes de alarmarte, consulta a Anacan AI los primeros pasos.', title_fr = 'Soupçon d''allergie 🤖', body_fr = 'Vous lui avez donné un nouvel aliment et vous voyez des rougeurs sur ses joues ? Avant de paniquer, découvrez les premières étapes auprès d''Anacan AI.', title_hi = 'एलर्जी का शक 🤖', body_hi = 'नया खाना दिया और गालों पर लाली दिखी? घबराने से पहले Anacan AI से पहले कदम जानिए।', title_id = 'Curiga alergi 🤖', body_id = 'Memberi makanan baru lalu melihat kemerahan di pipinya? Sebelum panik, pelajari langkah pertama yang perlu dilakukan dari Anacan AI.', title_ja = 'アレルギーかも？🤖', body_ja = '新しい食べ物をあげたら、ほっぺが赤くなった？あわてる前に、Anacan AIで最初にすべきことを確認しましょう。', title_ko = '알레르기가 의심될 때 🤖', body_ko = '새 음식을 줬는데 볼이 빨개졌나요? 당황하기 전에 Anacan AI에게서 첫 대처 방법을 알아보세요.', title_nl = 'Vermoeden van allergie 🤖', body_nl = 'Gaf je iets nieuws te eten en zie je rode wangetjes? Lees bij Anacan AI wat de eerste stappen zijn voordat je in paniek raakt.', title_pl = 'Podejrzenie alergii 🤖', body_pl = 'Podałaś nowy pokarm i widzisz zaczerwienienie na policzkach? Zanim wpadniesz w panikę, dowiedz się od Anacan AI, jakie są pierwsze kroki.', title_pt = 'Suspeitas de alergia 🤖', body_pt = 'Deu-lhe um alimento novo e viu vermelhidão nas bochechas? Antes de entrar em pânico, conheça com o Anacan AI os primeiros passos.', title_sv = 'Misstänkt allergi 🤖', body_sv = 'Har du gett barnet en ny maträtt och sett rodnad på kinderna? Innan du får panik, ta reda på de första stegen hos Anacan AI.', title_vi = 'Băn khoăn về dị ứng 🤖', body_vi = 'Mẹ cho bé ăn món mới và thấy má bé ửng đỏ? Trước khi hoảng hốt, hãy hỏi Anacan AI những bước cần làm đầu tiên.', title_zh = '怀疑过敏 🤖', body_zh = '给宝宝吃了新食物，脸颊发红了？先别慌，向Anacan AI了解一下第一步该怎么做吧。' WHERE id = '57b926b9-28cb-4c4e-8863-8ce72241c9fe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Hora de salir! ⛅', body_es = 'Con la herramienta Tiempo y ropa encuentra en segundos el conjunto más adecuado para el tiempo que hace y sal a tomar aire fresco.', title_fr = 'C''est l''heure de sortir ⛅', body_fr = 'Avec l''outil Météo et tenue, trouvez en quelques secondes la tenue la plus adaptée au temps et allez prendre l''air.', title_hi = 'बाहर जाने का समय ⛅', body_hi = 'मौसम और कपड़े टूल से सेकंडों में मौसम के हिसाब से सबसे सही कपड़े चुनिए और ताज़ी हवा का आनंद लीजिए।', title_id = 'Waktunya jalan-jalan ⛅', body_id = 'Dengan fitur Cuaca dan Pakaian, temukan pakaian paling pas untuk cuaca hari ini dalam hitungan detik, lalu hirup udara segar.', title_ja = 'おでかけタイム ⛅', body_ja = '「天気と服装」ツールで、今日の天気にぴったりの服装を数秒で見つけて、外の空気を楽しみましょう。', title_ko = '외출할 시간 ⛅', body_ko = '날씨와 옷차림 도구로 오늘 날씨에 딱 맞는 옷차림을 몇 초 만에 찾고 신선한 바람을 쐬어 보세요.', title_nl = 'Tijd om naar buiten te gaan ⛅', body_nl = 'Vind met de tool Weer en kleding in een paar seconden de beste outfit voor het weer en ga lekker naar buiten.', title_pl = 'Czas wyjść na dwór ⛅', body_pl = 'Z narzędziem Pogoda i ubiór w kilka sekund znajdziesz zestaw najlepiej dopasowany do pogody i odetchniesz świeżym powietrzem.', title_pt = 'Hora de sair ⛅', body_pt = 'Com a ferramenta Tempo e Roupa, encontre em segundos a roupa ideal para o tempo e vá apanhar ar fresco.', title_sv = 'Dags att gå ut ⛅', body_sv = 'Hitta den bästa klädseln för vädret på några sekunder med Väder och kläder, och gå ut och få frisk luft.', title_vi = 'Đến giờ ra ngoài rồi ⛅', body_vi = 'Với công cụ Thời tiết và trang phục, mẹ tìm được bộ đồ hợp thời tiết nhất chỉ trong vài giây, rồi cùng bé hít thở không khí trong lành nhé.', title_zh = '出门时间到 ⛅', body_zh = '用天气穿衣工具，几秒钟就找到最适合今天天气的搭配，出去呼吸新鲜空气吧。' WHERE id = 'f8c399ff-a31e-4e77-a55d-5aab198bafaa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche, pasear a tu bebé por la habitación y ayudarle a echar los gases es tarea exclusiva de papá.', body_fr = 'Ce soir, promener bébé dans la pièce et lui faire faire son rot, c''est entièrement le rôle de papa.', body_hi = 'आज शाम कमरे में बच्चे को घुमाना और डकार दिलाना पूरी तरह पापा की ज़िम्मेदारी है।', body_id = 'Malam ini, menimang dan menyendawakan si kecil sepenuhnya jadi tugas ayah.', body_ja = '今夜、部屋で抱っこして歩いたり、げっぷをさせたりするのはパパの担当です。', body_ko = '오늘 저녁 방 안에서 아기를 안고 걷고 트림시키는 일은 온전히 아빠 몫이에요.', body_nl = 'Vanavond zijn rondlopen en boertjes laten helemaal de taak van papa.', body_pl = 'Dziś wieczorem noszenie maluszka po pokoju i odbijanie to wyłącznie zadanie taty.', body_pt = 'Esta noite, passear o bebé pelo quarto e pô-lo a arrotar fica inteiramente a cargo do pai.', body_sv = 'I kväll är det helt pappas uppgift att gå runt i rummet med barnet och hjälpa det att rapa.', body_vi = 'Tối nay, việc bế bé đi quanh phòng và vỗ ợ hơi hoàn toàn là nhiệm vụ của bố.', body_zh = '今晚抱着宝宝在房间里走动、拍嗝的任务，全部交给爸爸。' WHERE id = 'fb3d810e-9135-4194-bb47-9ce9e588d70c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche entra en Cuentos inteligentes, crea un cuento especial para tu peque y léeselo.', body_fr = 'Ce soir, ouvrez les Contes intelligents, créez une histoire rien que pour lui et lisez-la-lui.', body_hi = 'आज शाम स्मार्ट कहानियाँ खोलिए, उसके लिए एक खास कहानी बनाइए और पढ़कर सुनाइए।', body_id = 'Malam ini, buka Dongeng Pintar, buat dongeng istimewa khusus untuknya, lalu bacakan.', body_ja = '今夜は「スマートおはなし」を開いて、赤ちゃんだけの特別なお話をつくって読んであげましょう。', body_ko = '오늘 저녁 스마트 동화에 들어가 아기만을 위한 특별한 동화를 만들어 읽어 주세요.', body_nl = 'Open vanavond Slimme sprookjes, maak een speciaal sprookje voor je kleintje en lees het voor.', body_pl = 'Dziś wieczorem zajrzyj do Mądrych bajek, stwórz dla maluszka wyjątkową bajkę i ją przeczytaj.', body_pt = 'Esta noite, entre nas Histórias Inteligentes, crie uma história especial para o bebé e leia-lha.', body_sv = 'Gå in i Smarta sagor i kväll, skapa en alldeles egen saga till barnet och läs den.', body_vi = 'Tối nay, hãy vào Truyện cổ tích thông minh, tạo một câu chuyện đặc biệt dành riêng cho bé và đọc cho bé nghe nhé.', body_zh = '今晚打开智能故事，为宝宝创作一个专属故事，读给宝宝听吧。' WHERE id = '65cb82a7-67e0-48b5-80b8-74e806b2980e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fase del «quiero comer yo solo» 🥦', body_es = 'Quiere quitarte la cuchara de la mano. Deja que la coja. Se manchará, pero esta sensación de independencia es muy importante para tu peque.', title_fr = 'La phase « Je mange tout seul » 🥦', body_fr = 'Il veut vous prendre la cuillère des mains. Laissez-le faire. Il va se salir, mais ce sentiment d''autonomie est très important pour lui.', title_hi = '''मैं खुद खाऊँगा'' वाली ज़िद 🥦', body_hi = 'वह आपके हाथ से चम्मच लेना चाहता है। लेने दीजिए। कपड़े गंदे होंगे, पर आत्मनिर्भरता का यह एहसास उसके लिए बहुत ज़रूरी है।', title_id = 'Fase "Aku mau makan sendiri" 🥦', body_id = 'Ia ingin merebut sendok dari tangan Anda. Biarkan saja. Bajunya akan kotor, tapi rasa mandiri ini sangat penting baginya.', title_ja = '「自分で食べる！」の時期 🥦', body_ja = 'あなたの手からスプーンを取りたがっています。持たせてあげましょう。服は汚れますが、この「ひとりでできる」気持ちは赤ちゃんにとってとても大切です。', title_ko = '''내가 먹을래'' 고집 🥦', body_ko = '엄마 손에서 숟가락을 가져가고 싶어 해요. 가져가게 두세요. 옷은 더러워지겠지만 이 자립심은 아기에게 아주 중요해요.', title_nl = 'Ik wil zelf eten! 🥦', body_nl = 'Je baby wil de lepel van je afpakken. Laat hem maar. Hij wordt vies, maar dit gevoel van zelfstandigheid is heel belangrijk voor hem.', title_pl = 'Upór: sam zjem 🥦', body_pl = 'Chce wziąć od ciebie łyżeczkę. Pozwól mu. Ubrudzi się, ale to poczucie samodzielności jest dla niego bardzo ważne.', title_pt = 'A teimosia do "eu como sozinho" 🥦', body_pt = 'Quer tirar-lhe a colher da mão. Deixe-o. Vai sujar-se, mas este sentido de independência é muito importante para ele.', title_sv = 'Jag äter själv-envisheten 🥦', body_sv = 'Barnet vill ta skeden ur din hand. Låt det. Det blir kladdigt, men känslan av självständighet är väldigt viktig för barnet.', title_vi = 'Giai đoạn "Con tự ăn" 🥦', body_vi = 'Bé muốn giành thìa khỏi tay mẹ. Cứ để bé cầm. Người bé sẽ bẩn, nhưng cảm giác tự lập này rất quan trọng với bé.', title_zh = '“我要自己吃”阶段 🥦', body_zh = '宝宝想从你手里抢勺子。就让宝宝拿吧。会弄脏，但这种独立感对宝宝非常重要。' WHERE id = '9c11d140-acfd-48e4-9fef-141a9e34586d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Resolvámoslo juntas 💬', body_es = '¿Cansada de preguntarte «por qué hace esto mi peque»? Entra en la Comunidad Anacan y verás que en miles de casas pasa exactamente lo mismo.', title_fr = 'Trouvons la solution ensemble 💬', body_fr = 'Fatiguée de vous demander « Pourquoi mon enfant fait-il ça ? » Rejoignez la Communauté Anacan et voyez que dans des milliers de foyers, il se passe exactement la même chose !', title_hi = 'साथ मिलकर हल करें 💬', body_hi = '''मेरा बच्चा ऐसा क्यों करता है?'' पूछते-पूछते थक गईं? Anacan कम्युनिटी में आइए और देखिए कि हज़ारों घरों में बिल्कुल यही हो रहा है!', title_id = 'Mari atasi bersama 💬', body_id = 'Lelah dengan pertanyaan "Kenapa anakku begini?" Masuklah ke Komunitas Anacan dan lihat bahwa hal yang persis sama terjadi di ribuan rumah!', title_ja = '一緒に解決しよう 💬', body_ja = '「どうしてうちの子はこうなの？」という疑問に疲れていませんか？Anacanコミュニティに参加すれば、何千もの家庭でまったく同じことが起きているとわかります！', title_ko = '함께 해결해요 💬', body_ko = '''우리 아이는 왜 이럴까?''라는 질문에 지쳤나요? Anacan 커뮤니티에 들어가 보면 수많은 집에서 똑같은 일이 일어나고 있다는 걸 알게 될 거예요!', title_nl = 'Laten we het samen oplossen 💬', body_nl = 'Moe van de vraag: waarom doet mijn kindje zo? Ga naar de Anacan Community en zie dat in duizenden huizen precies hetzelfde gebeurt!', title_pl = 'Rozwiążmy to razem 💬', body_pl = 'Masz dość pytania „dlaczego moje dziecko tak robi?”. Zajrzyj do Społeczności Anacan i zobacz, że w tysiącach domów dzieje się dokładnie to samo!', title_pt = 'Vamos resolver juntas 💬', body_pt = 'Cansada da pergunta "porque é que o meu bebé faz isto?" Entre na Comunidade Anacan e veja que em milhares de casas se vive exatamente o mesmo!', title_sv = 'Vi löser det tillsammans 💬', body_sv = 'Trött på frågan ''varför gör mitt barn så här?''? Gå in i Anacans Community och se att precis samma sak händer i tusentals hem!', title_vi = 'Cùng nhau giải quyết 💬', body_vi = 'Mẹ đã mệt với câu hỏi "Sao con mình lại thế này?" Hãy vào Cộng đồng Anacan và thấy rằng hàng nghìn gia đình đang trải qua đúng điều đó!', title_zh = '一起来解决 💬', body_zh = '问“我的宝宝为什么会这样”问累了？进入Anacan社区看看，成千上万个家庭正在经历一模一样的事！' WHERE id = '7fd53d22-26ef-4c4c-83bb-d44647b94560' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Experto en agarrar 🧸', body_es = '¿Ya agarra los juguetes colgantes con total precisión? Su motricidad avanza de maravilla. Observa sus intentos con cariño y anímale.', title_fr = 'Champion de la prise 🧸', body_fr = 'Il attrape déjà les jouets suspendus avec précision ? Sa motricité se développe à merveille. Observez ses efforts avec amour et encouragez-le.', title_hi = 'पकड़ने में माहिर 🧸', body_hi = 'क्या अब वह लटके खिलौनों को एकदम सही पकड़ लेता है? उसकी मोटर स्किल्स शानदार ढंग से विकसित हो रही हैं। उसकी कोशिशों को प्यार से देखिए और हौसला बढ़ाइए।', title_id = 'Jago menggenggam 🧸', body_id = 'Ia sudah bisa meraih mainan gantung dengan tepat? Motoriknya berkembang luar biasa. Perhatikan usahanya dengan penuh kasih dan beri semangat.', title_ja = 'つかむの名人 🧸', body_ja = 'つるしたおもちゃを、もうしっかりつかめますか？運動能力がすばらしく発達しています。その挑戦を愛情たっぷりに見守り、応援してあげましょう。', title_ko = '잡기 달인 🧸', body_ko = '매달린 장난감을 이제 정확하게 잡나요? 소근육이 멋지게 발달하고 있어요. 아기의 시도를 사랑으로 지켜보고 응원해 주세요.', title_nl = 'Meester in grijpen 🧸', body_nl = 'Pakt je baby hangende speeltjes nu heel precies vast? De motoriek ontwikkelt zich geweldig. Kijk liefdevol naar die pogingen en moedig ze aan.', title_pl = 'Mistrz chwytania 🧸', body_pl = 'Już precyzyjnie łapie wiszące zabawki? Jego motoryka wspaniale się rozwija. Obserwuj te próby z miłością i zachęcaj go.', title_pt = 'Mestre a agarrar 🧸', body_pt = 'Já agarra os brinquedos pendurados com toda a precisão? A motricidade está a desenvolver-se de forma fantástica. Acompanhe e incentive estas tentativas com carinho.', title_sv = 'Mästare på att greppa 🧸', body_sv = 'Griper barnet redan hängande leksaker helt exakt? Motoriken utvecklas fantastiskt. Följ försöken med kärlek och uppmuntra dem.', title_vi = 'Bậc thầy cầm nắm 🧸', body_vi = 'Bé đã nắm trúng đồ chơi treo phía trên? Kỹ năng vận động của bé đang phát triển tuyệt vời. Hãy dõi theo và khích lệ bé bằng tất cả yêu thương nhé.', title_zh = '抓握小能手 🧸', body_zh = '宝宝已经能准确抓住挂着的玩具了？精细动作发育得真棒。满怀爱意地看着宝宝的每一次尝试，多多鼓励吧。' WHERE id = '09081d67-84a7-403e-b876-3cc97106eb52' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Paso al sueño 🛀', body_es = 'Un baño templado siempre funciona. No rompas nunca la rutina de la noche, porque le indica a su cerebro que ahora toca dormir.', title_fr = 'Vers le sommeil 🛀', body_fr = 'Un bain tiède fonctionne toujours. Ne brisez jamais la routine du soir, car elle envoie à son cerveau le signal « c''est l''heure de dormir ».', title_hi = 'नींद की ओर 🛀', body_hi = 'गुनगुना स्नान हमेशा काम आता है। शाम का रूटीन कभी मत तोड़िए, क्योंकि यह उसके दिमाग को ''अब सोने का समय है'' का संकेत देता है।', title_id = 'Menuju tidur 🛀', body_id = 'Mandi air hangat selalu ampuh. Jangan pernah melewatkan rutinitas malam, karena ini memberi sinyal "sekarang waktunya tidur" ke otaknya.', title_ja = 'ねんねへの切りかえ 🛀', body_ja = 'ぬるめのお風呂はいつも効果的です。夜のルーティンは決して崩さないで。脳に「今はねんねの時間だよ」というサインを送ってくれます。', title_ko = '꿈나라로 가는 길 🛀', body_ko = '따뜻한 목욕은 언제나 효과가 있어요. 저녁 루틴은 절대 깨지 마세요. 아기 뇌에 ''이제 잘 시간''이라는 신호를 주거든요.', title_nl = 'Op weg naar de nacht 🛀', body_nl = 'Een lauw badje werkt altijd. Doorbreek de avondroutine nooit, want die geeft zijn hersenen het signaal: nu is het slaaptijd.', title_pl = 'Przejście do snu 🛀', body_pl = 'Ciepła kąpiel zawsze działa. Nigdy nie łam wieczornej rutyny, bo to dla jego mózgu sygnał, że teraz czas spać.', title_pt = 'Passagem para o sono 🛀', body_pt = 'Um banho morno resulta sempre. Nunca quebre a rotina da noite, porque é ela que diz ao cérebro do bebé "agora é hora de dormir".', title_sv = 'Övergång till sömnen 🛀', body_sv = 'Ett ljummet bad fungerar alltid. Bryt aldrig kvällsrutinen, för den signalerar till barnets hjärna att det nu är dags att sova.', title_vi = 'Chuẩn bị vào giấc 🛀', body_vi = 'Tắm nước ấm lúc nào cũng hiệu quả. Đừng bao giờ phá vỡ nếp sinh hoạt buổi tối, vì đó là tín hiệu "giờ là lúc ngủ" gửi đến não bé.', title_zh = '过渡到睡眠 🛀', body_zh = '温水澡总是管用。千万别打乱晚间作息，因为这是在给宝宝的大脑发出“该睡觉了”的信号。' WHERE id = 'a6ef3f7c-7550-4712-8fc9-23c742a51744' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Aprender cayendo y levantándose 🧗‍♂️', body_es = 'De pie se cae de culete, se ríe y vuelve a levantarse. Estas caídas crean memoria muscular, no intervengas demasiado.', title_fr = 'Apprendre en tombant et en se relevant 🧗‍♂️', body_fr = 'Debout, il tombe sur les fesses, rit et se relève. Ces chutes créent sa mémoire musculaire, n''intervenez pas trop.', title_hi = 'गिरकर उठना सीखना 🧗‍♂️', body_hi = 'खड़े-खड़े धम से बैठ जाता है, हँसता है और फिर उठता है। ये गिरना मांसपेशियों की याददाश्त बनाता है, ज़रूरत से ज़्यादा दखल मत दीजिए।', title_id = 'Belajar dari jatuh bangun 🧗‍♂️', body_id = 'Saat berdiri, ia jatuh terduduk, tertawa, lalu bangkit lagi. Jatuh seperti ini membentuk memori otot, jangan terlalu banyak ikut campur.', title_ja = '転んで起きて学ぶ 🧗‍♂️', body_ja = '立っていて、しりもちをついて、笑って、また立ち上がる。この転び方が筋肉の記憶をつくります。手を出しすぎないようにしましょう。', title_ko = '넘어지고 일어서며 배워요 🧗‍♂️', body_ko = '서 있다가 엉덩방아를 찧고, 웃고, 다시 일어나요. 이렇게 넘어지며 근육 기억이 생기니 너무 많이 개입하지 마세요.', title_nl = 'Leren met vallen en opstaan 🧗‍♂️', body_nl = 'Als hij staat, valt hij op zijn billen, lacht hij en staat hij weer op. Dit vallen bouwt spiergeheugen op, grijp niet te veel in.', title_pl = 'Nauka przez upadki 🧗‍♂️', body_pl = 'Stojąc, ląduje na pupie, śmieje się i znów wstaje. Te upadki budują pamięć mięśniową, nie ingeruj za bardzo.', title_pt = 'Aprender a cair e a levantar 🧗‍♂️', body_pt = 'De pé, cai de rabo, ri-se e volta a levantar-se. Estas quedas criam memória muscular, não intervenha demasiado.', title_sv = 'Lära sig genom att ramla och resa sig 🧗‍♂️', body_sv = 'När barnet står ramlar det på rumpan, skrattar och reser sig igen. Fallen bygger upp muskelminnet, lägg dig inte i för mycket.', title_vi = 'Ngã rồi đứng dậy 🧗‍♂️', body_vi = 'Đang đứng, bé ngã phịch xuống mông, cười rồi lại đứng lên. Những cú ngã này tạo nên trí nhớ cơ bắp, đừng can thiệp quá nhiều.', title_zh = '摔倒了再爬起来 🧗‍♂️', body_zh = '宝宝站着站着一屁股坐下，笑一笑又站起来。这些摔倒在建立肌肉记忆，别过多干预。' WHERE id = 'd6154f3b-6df3-4af3-97e7-fdfd798b8cfb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Acostumbrarse a la oscuridad 🌙', title_fr = 'S''habituer à l''obscurité 🌙', title_hi = 'अँधेरे की आदत 🌙', title_id = 'Terbiasa dengan gelap 🌙', title_ja = '暗さに慣れよう 🌙', title_ko = '어둠에 익숙해지기 🌙', title_nl = 'Wennen aan het donker 🌙', title_pl = 'Oswajanie z ciemnością 🌙', title_pt = 'Habituar-se ao escuro 🌙', title_sv = 'Vänja sig vid mörkret 🌙', title_vi = 'Làm quen với bóng tối 🌙', title_zh = '适应黑暗 🌙' WHERE id = '2521dffb-415b-4bec-81f4-b18ee93644d8' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidad de silencio 🤫', body_es = '¿Al dormirse le despierta cualquier crujido? Analiza el ambiente con el Medidor de sonido y asegura un silencio sin interrupciones.', title_fr = 'Besoin de silence 🤫', body_fr = 'Au moment de s''endormir, le moindre petit bruit le réveille ? Analysez l''ambiance avec le Sonomètre et assurez un silence sans interruption.', title_hi = 'खामोशी की ज़रूरत 🤫', body_hi = 'सोते समय ज़रा सी चटक भी उसे जगा देती है? साउंड मीटर से माहौल का विश्लेषण कीजिए और लगातार खामोशी पक्की कीजिए।', title_id = 'Butuh keheningan 🤫', body_id = 'Bunyi kecil membangunkannya saat mulai tertidur? Analisis suasana dengan Pengukur Suara dan pastikan keheningan tanpa gangguan.', title_ja = '静けさが必要 🤫', body_ja = '寝入りばなに、小さなカチッという音で起きてしまう？「サウンドメーター」で環境をチェックして、途切れない静けさを守りましょう。', title_ko = '고요함이 필요해요 🤫', body_ko = '잠들 때 작은 소리 하나에도 깨나요? 소음 측정기로 환경을 분석해 끊김 없는 고요를 만들어 주세요.', title_nl = 'Behoefte aan stilte 🤫', body_nl = 'Wordt je baby bij het inslapen wakker van een klein tikje? Analyseer de omgeving met de Geluidsmeter en zorg voor ononderbroken stilte.', title_pl = 'Potrzeba ciszy 🤫', body_pl = 'Przy zasypianiu budzi go ciche trzaśnięcie? Przeanalizuj otoczenie Miernikiem dźwięku i zapewnij nieprzerwaną ciszę.', title_pt = 'Necessidade de silêncio 🤫', body_pt = 'Ao adormecer, um pequeno estalido acorda-o? Analise o ambiente com o Medidor de Som e garanta um silêncio sem interrupções.', title_sv = 'Behovet av tystnad 🤫', body_sv = 'Vaknar barnet av ett litet knäpp när det håller på att somna? Analysera miljön med Ljudmätaren och se till att det är tyst utan avbrott.', title_vi = 'Cần sự yên tĩnh 🤫', body_vi = 'Khi đang vào giấc, một tiếng lách cách nhỏ cũng làm bé thức dậy? Hãy phân tích môi trường bằng Đo âm thanh và đảm bảo sự yên tĩnh liên tục.', title_zh = '需要安静 🤫', body_zh = '快睡着时一点小响声就会吵醒宝宝？用噪音测量分析环境，保证不被打扰的安静。' WHERE id = '25903ac8-0fd6-44f0-92d8-c3e1bee035e5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Listas y despistes 🛒', body_es = '¿La niebla mental no te abandona? No pienses en las pequeñas compras de casa: apúntalas ya en la Lista de la compra y que tu pareja se encargue.', title_fr = 'Les listes contre les oublis 🛒', body_fr = 'Le brouillard de mémoire ne vous quitte pas ? Ne pensez plus aux petites courses de la maison : notez-les tout de suite dans la Liste de courses, votre conjoint s''en chargera.', title_hi = 'लिस्ट और भूलने की आदत 🛒', body_hi = 'याददाश्त का धुंधलापन पीछा नहीं छोड़ रहा? घर की छोटी खरीदारी के बारे में मत सोचिए, तुरंत शॉपिंग लिस्ट में डालिए, आपके साथी संभाल लेंगे।', title_id = 'Daftar dan mudah lupa 🛒', body_id = 'Kabut ingatan tak kunjung hilang? Jangan pikirkan belanja kecil untuk rumah, segera masukkan ke Daftar Belanja, biar pasangan Anda yang mengurus.', title_ja = 'リストともの忘れ 🛒', body_ja = '頭のもやもやが晴れない？家のこまごましたお買い物は考えないで、すぐに「買い物リスト」に入れて、パートナーにおまかせしましょう。', title_ko = '목록과 깜빡깜빡 🛒', body_ko = '깜빡깜빡 머리가 여전한가요? 집안의 자잘한 장보기는 고민하지 말고 바로 쇼핑 목록에 넣어 배우자가 해결하게 하세요.', title_nl = 'Lijstjes en vergeetachtigheid 🛒', body_nl = 'Blijft die geheugenmist maar hangen? Pieker niet over de kleine boodschappen, zet ze meteen op je Boodschappenlijstje en laat je partner het regelen.', title_pl = 'Listy i zapominanie 🛒', body_pl = 'Mgła w głowie nie odpuszcza? Nie myśl o drobnych domowych zakupach, od razu wrzuć je na Listę zakupów, a partner się tym zajmie.', title_pt = 'Listas e esquecimentos 🛒', body_pt = 'O nevoeiro na memória não passa? Não pense nas pequenas compras da casa: ponha-as já na Lista de Compras e o seu companheiro trata disso.', title_sv = 'Listor och glömska 🛒', body_sv = 'Släpper minnesdimman inte taget? Fundera inte på hemmets småinköp, släng genast in dem i Inköpslistan, så fixar din partner det.', title_vi = 'Danh sách và chứng hay quên 🛒', body_vi = 'Sương mù trí nhớ vẫn chưa buông tha mẹ? Đừng bận tâm chuyện mua sắm lặt vặt trong nhà, hãy ghi ngay vào Danh sách mua sắm để bố lo.', title_zh = '清单与健忘 🛒', body_zh = '记忆迷雾还没散？别再惦记家里那些零碎的采购，马上丢进购物清单，让伴侣去搞定吧。' WHERE id = '3a5c700f-e10c-4819-bba1-cddd9f951f4f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un abrazo de «te quiero» 🫂', body_es = '¿De repente viene, te abraza el cuello o te acaricia la cara? Ya muestra su amor físicamente. Disfruta de este momento.', title_fr = 'Le câlin « Je t''aime » 🫂', body_fr = 'Il vient soudain se jeter à votre cou ou vous caresser le visage ? Il montre désormais son amour physiquement. Savourez ce moment.', title_hi = '''आई लव यू'' वाली झप्पी 🫂', body_hi = 'अचानक आकर आपके गले से लिपट जाता है या आपका चेहरा सहलाता है? वह अब अपना प्यार शारीरिक रूप से जताता है। इस पल का आनंद लीजिए।', title_id = 'Pelukan "Aku sayang kamu" 🫂', body_id = 'Tiba-tiba ia datang memeluk leher Anda atau mengelus wajah Anda? Kini ia menunjukkan cintanya secara fisik. Nikmati momen ini.', title_ja = '「大好き」のハグ 🫂', body_ja = '急にやってきて首に抱きついたり、顔をなでたりしますか？もう体で愛情を伝えているのです。この瞬間をじっくり味わいましょう。', title_ko = '''사랑해'' 포옹 🫂', body_ko = '갑자기 와서 목을 끌어안거나 얼굴을 쓰다듬나요? 이제 몸으로 사랑을 표현해요. 이 순간을 마음껏 누리세요.', title_nl = 'Een ik-hou-van-je-knuffel 🫂', body_nl = 'Slaat je baby ineens zijn armpjes om je nek of aait hij je gezicht? Hij laat zijn liefde nu lichamelijk zien. Geniet van dit moment.', title_pl = 'Przytulas „kocham cię” 🫂', body_pl = 'Nagle przychodzi i obejmuje cię za szyję albo głaszcze po twarzy? Okazuje już miłość fizycznie. Delektuj się tą chwilą.', title_pt = 'O abraço "gosto de ti" 🫂', body_pt = 'De repente, vem abraçar-lhe o pescoço ou acariciar-lhe o rosto? Já mostra o seu amor de forma física. Saboreie este momento.', title_sv = 'Jag älskar dig-kramen 🫂', body_sv = 'Kommer barnet plötsligt och kramar dig om halsen eller smeker ditt ansikte? Det visar redan sin kärlek fysiskt. Njut av stunden.', title_vi = 'Cái ôm "Con yêu mẹ" 🫂', body_vi = 'Bé bất chợt đến ôm cổ hay vuốt má mẹ? Bé đã biết thể hiện tình yêu bằng hành động. Hãy tận hưởng khoảnh khắc này.', title_zh = '“我爱你”的拥抱 🫂', body_zh = '宝宝突然跑过来搂住你的脖子，或者摸摸你的脸？宝宝已经会用肢体表达爱了。好好享受这一刻吧。' WHERE id = '47b342b1-9525-44b6-b917-2eb642240cb2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lista de cosas que faltan no se acaba 🛒', body_es = '¿Con el caos del día se ha acabado el champú o los pañales? No lo guardes en la cabeza: apúntalo en la Lista de la compra y sincronízala con tu pareja.', title_fr = 'La liste des besoins n''en finit pas 🛒', body_fr = 'Dans le chaos du quotidien, plus de shampooing ou de couches ? Ne gardez pas tout en tête : notez-le dans la Liste de courses et synchronisez-la avec votre conjoint.', title_hi = 'ज़रूरतों की लिस्ट कभी खत्म नहीं होती 🛒', body_hi = 'रोज़ की अफ़रा-तफ़री में शैम्पू खत्म हुआ या डायपर? दिमाग में मत रखिए, शॉपिंग लिस्ट में लिखिए और अपने साथी के साथ सिंक कीजिए।', title_id = 'Daftar kebutuhan tak ada habisnya 🛒', body_id = 'Di tengah kekacauan sehari-hari, sampo atau popok habis? Jangan disimpan di kepala, tulis di Daftar Belanja dan sinkronkan dengan pasangan Anda.', title_ja = '必要なものリストは終わらない 🛒', body_ja = '毎日のカオスの中で、シャンプーやおむつが切れた？頭で覚えておかないで、「買い物リスト」に書いてパートナーと共有しましょう。', title_ko = '끝없는 필요 목록 🛒', body_ko = '정신없는 하루 속에 샴푸가 떨어졌나요, 기저귀인가요? 머릿속에 담아 두지 말고 쇼핑 목록에 적어 배우자와 공유하세요.', title_nl = 'Aan het lijstje komt geen eind 🛒', body_nl = 'Is in de dagelijkse chaos de shampoo of zijn de luiers op? Onthoud het niet, zet het op je Boodschappenlijstje en synchroniseer het met je partner.', title_pl = 'Lista potrzeb nie ma końca 🛒', body_pl = 'W codziennym chaosie skończył się szampon czy pieluszki? Nie trzymaj tego w głowie, wpisz na Listę zakupów i zsynchronizuj z partnerem.', title_pt = 'A lista de necessidades não acaba 🛒', body_pt = 'No caos do dia, acabou o champô ou as fraldas? Não guarde na cabeça: escreva na Lista de Compras e sincronize com o seu companheiro.', title_sv = 'Listan över behov tar aldrig slut 🛒', body_sv = 'Tog schampot eller blöjorna slut i vardagskaoset? Håll det inte i huvudet, skriv upp det i Inköpslistan och synka med din partner.', title_vi = 'Danh sách nhu cầu không bao giờ hết 🛒', body_vi = 'Giữa bộn bề hằng ngày, hết dầu gội hay tã rồi? Đừng cố nhớ trong đầu, hãy ghi vào Danh sách mua sắm và đồng bộ với bố.', title_zh = '需求清单永无止境 🛒', body_zh = '每天乱糟糟，洗发水还是尿布用完了？别靠脑子记，写进购物清单，和伴侣同步吧。' WHERE id = '09817e37-4e65-43f6-968c-dd333358e01e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de noche de papá 👨‍🍼', body_es = 'Ya tienes bastante con el cansancio del día. Por la tarde, preparar al bebé para dormir y leerle un cuento es tarea exclusiva de papá.', title_fr = 'Le service de nuit de papa 👨‍🍼', body_fr = 'La fatigue de la journée vous suffit. En fin de journée, préparer bébé pour la nuit et lui lire un conte, c''est uniquement le rôle de papa.', title_hi = 'पापा की रात की ड्यूटी 👨‍🍼', body_hi = 'दिन की थकान आपके लिए काफ़ी है। शाम को बच्चे को सोने के लिए तैयार करना और कहानी पढ़ना सिर्फ़ पापा का काम है।', title_id = 'Giliran malam ayah 👨‍🍼', body_id = 'Lelah seharian sudah cukup bagi Anda. Menjelang malam, menyiapkan si kecil tidur dan membacakan dongeng adalah tugas ayah seorang.', title_ja = 'パパの夜の当番 👨‍🍼', body_ja = '昼間の疲れだけでもう十分。夕方の寝かしつけの準備とお話の読み聞かせは、パパだけの役目です。', title_ko = '아빠의 밤 당번 👨‍🍼', body_ko = '낮의 피로로 충분해요. 저녁에 아기를 재울 준비를 하고 동화를 읽어 주는 건 오롯이 아빠 몫이에요.', title_nl = 'Papa''s avonddienst 👨‍🍼', body_nl = 'De vermoeidheid van overdag is genoeg voor jou. ''s Avonds de baby klaarmaken voor bed en een sprookje voorlezen is alleen papa''s taak.', title_pl = 'Nocna zmiana taty 👨‍🍼', body_pl = 'Wystarczy ci dziennego zmęczenia. Wieczorne przygotowanie maluszka do snu i czytanie bajki to wyłącznie zadanie taty.', title_pt = 'O turno da noite do pai 👨‍🍼', body_pt = 'O cansaço do dia já chega. Ao fim do dia, preparar o bebé para dormir e ler-lhe uma história é tarefa exclusiva do pai.', title_sv = 'Pappas nattskift 👨‍🍼', body_sv = 'Dagens trötthet räcker för dig. Att göra barnet redo för sömnen och läsa en saga på kvällen är bara pappas uppgift.', title_vi = 'Ca đêm của bố 👨‍🍼', body_vi = 'Mệt mỏi ban ngày đã đủ với mẹ rồi. Chiều tối nay, việc chuẩn bị cho bé đi ngủ và đọc truyện hoàn toàn là nhiệm vụ của bố.', title_zh = '爸爸的夜班 👨‍🍼', body_zh = '白天的疲惫已经够你受了。傍晚哄宝宝睡前准备和讲故事，就是爸爸一个人的任务。' WHERE id = '1f244347-1957-4238-988d-4563adba7bcd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En casa todo es un juguete 🥄', body_es = 'Los recipientes de plástico y las cucharas de madera le parecen más interesantes que el juguete más caro. Deja que explore libremente los utensilios de cocina.', title_fr = 'Tout est un jouet à la maison 🥄', body_fr = 'Les boîtes en plastique et les cuillères en bois l''intéressent plus que le jouet le plus cher. Laissez-le explorer librement les ustensiles de cuisine.', title_hi = 'घर की हर चीज़ खिलौना है 🥄', body_hi = 'प्लास्टिक के डिब्बे और लकड़ी के चम्मच उसके लिए सबसे महँगे खिलौने से भी ज़्यादा दिलचस्प हैं। उसे रसोई की चीज़ें आज़ादी से खोजने दीजिए।', title_id = 'Semua benda di rumah adalah mainan 🥄', body_id = 'Wadah plastik dan sendok kayu lebih menarik baginya daripada mainan termahal. Biarkan ia bebas menjelajahi peralatan dapur.', title_ja = '家にあるものはぜんぶおもちゃ 🥄', body_ja = 'プラスチックの容器や木のスプーンは、どんな高いおもちゃよりもおもしろいもの。キッチン用品を自由に探検させてあげましょう。', title_ko = '집 안의 모든 게 장난감 🥄', body_ko = '플라스틱 그릇과 나무 숟가락이 가장 비싼 장난감보다 더 재미있어요. 주방 물건을 자유롭게 탐색하게 해 주세요.', title_nl = 'Alles in huis is speelgoed 🥄', body_nl = 'Plastic bakjes en houten lepels vindt hij interessanter dan het duurste speelgoed. Laat hem vrij het keukengerei ontdekken.', title_pl = 'Wszystko w domu jest zabawką 🥄', body_pl = 'Plastikowe miski i drewniane łyżki są dla niego ciekawsze niż najdroższa zabawka. Pozwól mu swobodnie odkrywać kuchenne przedmioty.', title_pt = 'Tudo em casa é brinquedo 🥄', body_pt = 'As caixas de plástico e as colheres de pau são mais interessantes para ele do que o brinquedo mais caro. Deixe-o explorar à vontade os utensílios da cozinha.', title_sv = 'Allt hemma är leksaker 🥄', body_sv = 'Plastskålar och träskedar är mer spännande för barnet än den dyraste leksak. Låt det fritt utforska sakerna i köket.', title_vi = 'Mọi thứ trong nhà đều là đồ chơi 🥄', body_vi = 'Hộp nhựa và thìa gỗ còn thú vị với bé hơn cả món đồ chơi đắt tiền nhất. Cứ để bé thoải mái khám phá đồ dùng nhà bếp.', title_zh = '家里的一切都是玩具 🥄', body_zh = '对宝宝来说，塑料碗和木勺比最贵的玩具还有趣。让宝宝自由地探索厨房用品吧。' WHERE id = '9f618083-9332-44d7-8a8f-8ad3af6c22ac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El Análisis del llanto te ayuda 😭', body_es = '¿Se ha despertado a media noche y no se calla? Deja de adivinar: usa el Análisis del llanto y descubre la causa al instante.', title_fr = 'L''Analyse des pleurs à la rescousse 😭', body_fr = 'Il s''est réveillé en pleine nuit et ne se calme pas ? Arrêtez de deviner : utilisez l''Analyse des pleurs pour trouver tout de suite la cause.', title_hi = 'क्राइंग एनालिसिस आपकी मदद में 😭', body_hi = 'आधी रात को जागा और चुप नहीं हो रहा? अंदाज़ा लगाना छोड़िए, क्राइंग एनालिसिस से तुरंत वजह जानिए।', title_id = 'Analisis Tangisan siap membantu 😭', body_id = 'Terbangun di tengah malam dan tak mau diam? Berhenti menebak, gunakan Analisis Tangisan untuk langsung menemukan penyebabnya.', title_ja = '「泣き声分析」がお助け 😭', body_ja = '夜中に起きて泣きやまない？推測するのはやめて、「泣き声分析」を使ってすぐに原因を見つけましょう。', title_ko = '울음 분석이 도와줘요 😭', body_ko = '한밤중에 깨서 울음을 그치지 않나요? 추측은 그만하고 울음 분석으로 이유를 바로 찾아보세요.', title_nl = 'Huilanalyse helpt 😭', body_nl = 'Midden in de nacht wakker en stopt het huilen niet? Stop met raden en vind met Huilanalyse meteen de oorzaak.', title_pl = 'Analiza płaczu pomaga 😭', body_pl = 'Obudził się w środku nocy i nie przestaje płakać? Przestań zgadywać, skorzystaj z Analizy płaczu i od razu znajdź przyczynę.', title_pt = 'A Análise do Choro ajuda 😭', body_pt = 'Acordou a meio da noite e não se cala? Deixe de adivinhar: use a Análise do Choro e descubra logo a causa.', title_sv = 'Gråtanalys hjälper till 😭', body_sv = 'Har barnet vaknat mitt i natten och tystnar inte? Sluta gissa, använd Gråtanalys och hitta orsaken direkt.', title_vi = 'Phân tích tiếng khóc hỗ trợ 😭', body_vi = 'Bé thức giấc giữa đêm và không chịu nín? Đừng đoán nữa, hãy dùng Phân tích tiếng khóc để tìm ra nguyên nhân ngay.', title_zh = '哭声分析来帮忙 😭', body_zh = '半夜醒来哭个不停？别再猜了，用哭声分析马上找出原因吧。' WHERE id = '354e039c-3978-4aa3-a008-1a3a7bbe85a3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El aire fresco te salva 🌳', body_es = 'Si en casa la crisis va a más, mira Tiempo y ropa, súbele al carrito y sal enseguida al parque. La naturaleza es la forma más rápida de calmarle.', title_fr = 'L''air frais à la rescousse 🌳', body_fr = 'Si la crise monte à la maison, consultez Météo et tenue, installez-le dans la poussette et filez au parc. La nature est le moyen le plus rapide de l''apaiser.', title_hi = 'ताज़ी हवा सबसे बड़ी मददगार है 🌳', body_hi = 'अगर घर में रोने का दौर बढ़ रहा है, तो मौसम और कपड़े देखिए, स्ट्रॉलर में बिठाइए और तुरंत पार्क चलिए। प्रकृति उसे शांत करने का सबसे तेज़ तरीका है।', title_id = 'Udara segar adalah penyelamat 🌳', body_id = 'Kalau drama di rumah makin besar, cek Cuaca dan Pakaian, dudukkan ia di stroller, dan segera pergi ke taman. Alam adalah cara tercepat untuk menenangkannya.', title_ja = '新鮮な空気が救世主 🌳', body_ja = '家でぐずりが大きくなってきたら、「天気と服装」を見て、ベビーカーに乗せ、すぐに公園へ。自然は、いちばん早く落ち着かせてくれます。', title_ko = '신선한 공기가 구원자예요 🌳', body_ko = '집에서 울음이 커진다면 날씨와 옷차림을 확인하고 유모차에 태워 바로 공원으로 나가세요. 자연이 아기를 진정시키는 가장 빠른 길이에요.', title_nl = 'Frisse lucht is je redding 🌳', body_nl = 'Loopt de crisis thuis op? Kijk in Weer en kleding, zet je baby in de kinderwagen en ga meteen naar het park. De natuur kalmeert hem het snelst.', title_pl = 'Świeże powietrze ratuje 🌳', body_pl = 'Jeśli w domu narasta kryzys, sprawdź Pogodę i ubiór, posadź go w wózku i od razu idźcie do parku. Natura to najszybszy sposób, by się uspokoił.', title_pt = 'O ar puro é uma salvação 🌳', body_pt = 'Se a crise em casa está a crescer, veja o Tempo e Roupa, ponha-o no carrinho e vá já para o parque. A natureza é o caminho mais rápido para ele se acalmar.', title_sv = 'Frisk luft räddar dagen 🌳', body_sv = 'Om krisen växer hemma, kolla Väder och kläder, lägg barnet i vagnen och gå direkt till parken. Naturen är det snabbaste sättet att lugna barnet.', title_vi = 'Không khí trong lành là cứu tinh 🌳', body_vi = 'Nếu bé quấy khóc ngày càng dữ, hãy xem Thời tiết và trang phục, đặt bé vào xe đẩy và ra công viên ngay. Thiên nhiên là cách nhanh nhất giúp bé dịu lại.', title_zh = '新鲜空气是救星 🌳', body_zh = '如果家里的哭闹越来越厉害，看看天气穿衣，放进婴儿车，马上去公园。大自然是让宝宝平静下来最快的方法。' WHERE id = '8fb53566-815d-4365-b87c-c14288ebb122' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Caprichos al máximo ☁️', body_es = '¿Nada le parece bien y llora por todo? Puede ser un salto de crecimiento o la tensión de los dientes. Simplemente abrázale mucho.', title_fr = 'Les caprices au maximum ☁️', body_fr = 'Rien ne lui convient et il pleure pour tout ? C''est peut-être un pic de croissance ou les dents. Faites-lui simplement plein de câlins.', title_hi = 'चिड़चिड़ापन चरम पर ☁️', body_hi = 'किसी चीज़ से खुश नहीं, हर बात पर रोता है? यह विकास की छलांग या दाँत का दर्द हो सकता है। उसे बस खूब गले लगाइए।', title_id = 'Rewel di puncaknya ☁️', body_id = 'Tak ada yang membuatnya senang dan ia menangisi semuanya? Mungkin karena lompatan pertumbuhan atau tumbuh gigi. Cukup peluk ia sering-sering.', title_ja = 'ご機嫌ななめがピーク ☁️', body_ja = '何をしても気に入らず、なんにでも泣く？成長の時期か、歯が生えるむずむずかもしれません。たっぷり抱きしめてあげましょう。', title_ko = '칭얼거림 최고조 ☁️', body_ko = '아무것도 마음에 들지 않고 모든 것에 우나요? 성장 급등기나 이앓이 때문일 수 있어요. 많이 안아 주세요.', title_nl = 'Gezeur op zijn hoogtepunt ☁️', body_nl = 'Is je baby nergens tevreden mee en huilt hij om alles? Het kan een groeisprong of spanning door doorkomende tandjes zijn. Knuffel hem gewoon veel.', title_pl = 'Marudzenie u szczytu ☁️', body_pl = 'Nic mu nie pasuje, płacze o wszystko? To może być skok rozwojowy albo ząbkowanie. Po prostu często go przytulaj.', title_pt = 'Birras no auge ☁️', body_pt = 'Nada o contenta e chora por tudo? Pode ser um salto de crescimento ou a pressão dos dentes. Dê-lhe simplesmente muitos abraços.', title_sv = 'Gnället är på topp ☁️', body_sv = 'Är barnet missnöjt med allt och gråter över allt? Det kan vara ett tillväxtsprång eller spänningar från tänderna. Krama det bara massor.', title_vi = 'Quấy khóc đỉnh điểm ☁️', body_vi = 'Bé chẳng hài lòng điều gì, cái gì cũng khóc? Có thể do bước nhảy tăng trưởng hoặc đau răng. Chỉ cần ôm bé thật nhiều.', title_zh = '闹脾气到了顶点 ☁️', body_zh = '宝宝什么都不满意，什么都哭？可能是生长飞跃期或长牙不舒服。多抱抱宝宝吧。' WHERE id = 'c87df5f1-fbe2-4462-a617-a6649445ce77' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La calma de la noche 🪄', body_es = 'Crea en Cuentos inteligentes la historia de unos animales valientes y adorables y convierte la habitación en un lugar mágico.', title_fr = 'La sérénité de la nuit 🪄', body_fr = 'Dans les Contes intelligents, créez l''histoire d''animaux courageux et adorables et transformez la chambre en un lieu magique.', title_hi = 'रात का सुकून 🪄', body_hi = 'स्मार्ट कहानियों में बहादुर और प्यारे जानवरों की कहानी बनाइए और कमरे को एक जादुई जगह में बदल दीजिए।', title_id = 'Ketenangan malam 🪄', body_id = 'Di Dongeng Pintar, buat kisah hewan-hewan yang berani dan menggemaskan, dan ubah kamar menjadi tempat yang ajaib.', title_ja = '夜のやすらぎ 🪄', body_ja = '「スマートおはなし」で、勇敢でかわいい動物たちのお話をつくって、部屋を魔法の場所に変えましょう。', title_ko = '밤의 평온 🪄', body_ko = '스마트 동화에서 용감하고 사랑스러운 동물 이야기를 만들어 방을 마법의 공간으로 바꿔 보세요.', title_nl = 'De rust van de nacht 🪄', body_nl = 'Maak in Slimme sprookjes het verhaal van dappere, lieve dieren en verander de kamer in een magische plek.', title_pl = 'Spokój nocy 🪄', body_pl = 'Stwórz w Mądrych bajkach historię o odważnych i uroczych zwierzątkach i zamień pokój w magiczne miejsce.', title_pt = 'A calma da noite 🪄', body_pt = 'Crie nas Histórias Inteligentes histórias de animais corajosos e adoráveis e transforme o quarto num lugar mágico.', title_sv = 'Nattens ro 🪄', body_sv = 'Skapa sagan om modiga och gulliga djur i Smarta sagor och förvandla rummet till en magisk plats.', title_vi = 'Sự bình yên của màn đêm 🪄', body_vi = 'Hãy tạo câu chuyện về những con vật dũng cảm, đáng yêu trong Truyện cổ tích thông minh và biến căn phòng thành một nơi kỳ diệu.', title_zh = '夜晚的宁静 🪄', body_zh = '在智能故事里创作勇敢又可爱的动物的故事，把房间变成一个神奇的地方吧。' WHERE id = '361e96e8-a6ed-4fdf-a7bb-50e07abcec66' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Haces de todo para que coma bien. ¿Y tú?', body_es = 'Elige en la sección Recetas saludables una comida cargada de hierro y proteínas y recupera fuerzas.', title_fr = 'Vous faites tout pour bien le nourrir. Et vous ?', body_fr = 'Choisissez dans les Recettes saines un déjeuner riche en fer et en protéines et reprenez des forces.', title_hi = 'उसका पेट भरने के लिए आप सब कुछ करती हैं। और आप?', body_hi = 'सेहतमंद रेसिपी सेक्शन से आयरन और प्रोटीन से भरपूर लंच चुनिए और ताकत जुटाइए।', title_id = 'Anda melakukan segalanya agar ia kenyang. Bagaimana dengan Anda?', body_id = 'Pilih makan siang kaya zat besi dan protein dari bagian Resep Sehat, dan kumpulkan tenaga.', title_ja = '赤ちゃんにお腹いっぱい食べさせるために、なんでもしていますね。でもあなたは？', body_ja = '「ヘルシーレシピ」から、鉄分とたんぱく質たっぷりのランチを選んで、力をたくわえましょう。', title_ko = '아기를 배불리 먹이려고 뭐든 하죠. 그런데 엄마는요?', body_ko = '건강한 레시피 섹션에서 철분과 단백질이 가득한 점심을 골라 힘을 모으세요.', title_nl = 'Je doet alles om je baby goed te laten eten. En jij?', body_nl = 'Kies in het onderdeel Gezonde recepten een lunch vol ijzer en eiwit en kom weer op krachten.', title_pl = 'Robisz wszystko, żeby go nakarmić. A ty?', body_pl = 'Wybierz w sekcji Zdrowe przepisy obiad pełen żelaza i białka i nabierz sił.', title_pt = 'Faz tudo para o alimentar. E a mãe?', body_pt = 'Escolha na secção Receitas Saudáveis um almoço rico em ferro e proteína e ganhe forças.', title_sv = 'Du gör allt för att barnet ska bli mätt. Men du själv då?', body_sv = 'Välj en lunch rik på järn och protein i avsnittet Hälsosamma recept och samla kraft.', title_vi = 'Mẹ làm mọi thứ để bé được no. Còn mẹ thì sao?', body_vi = 'Hãy chọn một bữa trưa giàu sắt và protein từ mục Công thức lành mạnh để lấy lại sức.', title_zh = '你为了让宝宝吃饱想尽办法。那你自己呢？', body_zh = '从健康食谱板块里挑一份富含铁和蛋白质的午餐，补充力量吧。' WHERE id = 'a4baaa67-c9fb-4208-aab7-e7515b21f64f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pasa las páginas del libro 📖', body_es = '¿Ya pasa él solo las páginas de los libros de cartón? Registra este logro motor en el Seguimiento del desarrollo.', title_fr = 'Il tourne les pages 📖', body_fr = 'Il tourne entièrement seul les pages cartonnées des livres ? Notez cette victoire motrice dans le Suivi de développement.', title_hi = 'किताब के पन्ने पलट रहे हैं 📖', body_hi = 'मोटे पन्नों वाली किताबों के पन्ने पूरी तरह खुद पलटता है? ग्रोथ ट्रैकर में मोटर स्किल्स की इस जीत को दर्ज कीजिए।', title_id = 'Halaman buku dibalik 📖', body_id = 'Ia sudah membalik halaman buku bergambar tebal sepenuhnya sendiri? Catat kemenangan motorik ini di Pelacak Perkembangan.', title_ja = '絵本のページをめくる 📖', body_ja = '厚紙の絵本のページを、すっかり自分でめくれますか？「発達トラッカー」にこの運動の勝利を記録しましょう。', title_ko = '책장이 넘어가요 📖', body_ko = '두꺼운 책장을 완전히 혼자 넘기나요? 성장 기록에 이 운동 발달의 승리를 남겨 두세요.', title_nl = 'Bladzijden worden omgeslagen 📖', body_nl = 'Slaat je baby de dikke bladzijden van boekjes helemaal zelf om? Noteer deze motorische overwinning in de Groeitracker.', title_pl = 'Przewraca kartki książeczki 📖', body_pl = 'Sam przewraca grube kartki książeczek? Zapisz to motoryczne zwycięstwo w Śledzeniu rozwoju.', title_pt = 'As páginas do livro viram-se 📖', body_pt = 'Já vira completamente sozinho as páginas dos livros de cartão? Registe esta vitória motora no Registo de Desenvolvimento.', title_sv = 'Boksidorna vänds 📖', body_sv = 'Vänder barnet helt själv sidorna i böcker med tjocka blad? Anteckna den här motoriska segern i Utvecklingsspåraren.', title_vi = 'Lật từng trang sách 📖', body_vi = 'Bé đã tự lật hoàn toàn các trang sách bìa cứng? Hãy ghi lại chiến thắng vận động này trong Theo dõi phát triển.', title_zh = '翻书页 📖', body_zh = '宝宝已经能完全自己翻厚纸板书了？在发育追踪里记下这次动作上的胜利吧。' WHERE id = 'c58c8b30-4c95-4f60-98d7-d9580eb48a38' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hoy nada ha salido según lo previsto?', body_es = 'No te sientas culpable cuando tu bebé duerme. Eres una madre real, eres perfecta.', title_fr = 'Rien ne s''est passé comme prévu aujourd''hui ?', body_fr = 'Quand bébé dort, ne culpabilisez pas. Vous êtes une vraie maman, et vous êtes parfaite.', title_hi = 'आज कुछ भी योजना के मुताबिक नहीं हुआ?', body_hi = 'बच्चे के सोने पर अपराध-बोध मत पालिए। आप एक असली माँ हैं, आप परफ़ेक्ट हैं।', title_id = 'Hari ini tidak ada yang sesuai rencana?', body_id = 'Saat si kecil tidur, jangan tersiksa rasa bersalah. Anda ibu yang nyata, Anda sempurna.', title_ja = '今日は何ひとつ計画どおりにいかなかった？', body_ja = '赤ちゃんが寝ているときに、罪悪感をもたないで。あなたはリアルなママで、完璧です。', title_ko = '오늘 아무것도 계획대로 되지 않았나요?', body_ko = '아이가 잘 때 죄책감 느끼지 마세요. 당신은 진짜 엄마이고, 지금 그대로 완벽해요.', title_nl = 'Ging vandaag niets volgens plan?', body_nl = 'Voel je niet schuldig als je baby slaapt. Je bent een echte moeder, je bent perfect.', title_pl = 'Dziś nic nie poszło zgodnie z planem?', body_pl = 'Gdy maluszek śpi, nie miej wyrzutów sumienia. Jesteś prawdziwą mamą i jesteś idealna.', title_pt = 'Hoje nada correu como planeado?', body_pt = 'Não sinta remorsos enquanto o bebé dorme. É uma mãe real, é perfeita.', title_sv = 'Gick ingenting enligt planen i dag?', body_sv = 'Ha inget dåligt samvete när barnet sover. Du är en riktig mamma, och du är perfekt.', title_vi = 'Hôm nay không gì diễn ra theo kế hoạch?', body_vi = 'Khi bé ngủ, đừng cảm thấy tội lỗi. Mẹ là một người mẹ thật, và mẹ thật hoàn hảo.', title_zh = '今天什么都没按计划进行？', body_zh = '宝宝睡着时别有负罪感。你是一个真实的妈妈，你已经很完美了。' WHERE id = '2631ed9f-967a-4f12-9097-1f619f7f1e5f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lanzamientos con puntería ⚾', body_es = 'Intenta lanzar a propósito el juguete que tiene en la mano hacia un objetivo concreto. Su coordinación ojo-mano se desarrolla muy rápido.', title_fr = 'Des lancers ciblés ⚾', body_fr = 'Il essaie de lancer exprès son jouet vers une cible précise. Sa coordination œil-main se développe vite.', title_hi = 'निशाना लगाकर फेंकना ⚾', body_hi = 'हाथ का खिलौना जानबूझकर किसी खास निशाने पर फेंकने की कोशिश करता है। आँख और हाथ का तालमेल तेज़ी से विकसित हो रहा है।', title_id = 'Lemparan bertujuan ⚾', body_id = 'Ia sengaja mencoba melempar mainan di tangannya ke sasaran tertentu. Koordinasi mata dan tangannya berkembang pesat.', title_ja = 'ねらって投げる ⚾', body_ja = '手に持ったおもちゃを、わざと決まった的に向かって投げようとしています。目と手の協調がぐんぐん発達しています。', title_ko = '목표를 향한 던지기 ⚾', body_ko = '손에 든 장난감을 일부러 특정 목표를 향해 던지려 해요. 눈과 손의 협응력이 빠르게 발달하고 있어요.', title_nl = 'Gericht gooien ⚾', body_nl = 'Je baby probeert zijn speeltje expres naar een bepaald doel te gooien. De oog-handcoördinatie ontwikkelt zich snel.', title_pl = 'Rzuty do celu ⚾', body_pl = 'Celowo próbuje rzucić zabawkę w określony cel. Koordynacja oko-ręka szybko się rozwija.', title_pt = 'Lançamentos com pontaria ⚾', body_pt = 'Tenta de propósito atirar o brinquedo para um alvo concreto. A coordenação olho-mão está a desenvolver-se depressa.', title_sv = 'Målinriktade kast ⚾', body_sv = 'Barnet försöker med flit kasta leksaken mot ett bestämt mål. Koordinationen mellan öga och hand utvecklas snabbt.', title_vi = 'Ném có mục tiêu ⚾', body_vi = 'Bé cố tình ném đồ chơi về một mục tiêu nhất định. Khả năng phối hợp tay và mắt đang phát triển nhanh chóng.', title_zh = '有目标地扔 ⚾', body_zh = '宝宝故意把手里的玩具扔向某个目标。手眼协调能力发展得很快。' WHERE id = '34415812-3e31-43f2-99de-a1dd76bb1d9e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pediatra exprés 🤖', body_es = '¿Cuánto debe durar la siesta de mediodía de un bebé de 11 meses? Pregunta al instante a Anacan AI todo lo que te genere dudas y quédate tranquila.', title_fr = 'Le pédiatre express 🤖', body_fr = 'Combien de temps doit durer la sieste de l''après-midi d''un bébé de 11 mois ? Posez aussitôt à Anacan AI toutes les questions qui vous font hésiter et soyez rassurée.', title_hi = 'झटपट बाल रोग सलाह 🤖', body_hi = '11 महीने के बच्चे की दोपहर की नींद कितनी लंबी होनी चाहिए? जिस भी बात पर शक हो, तुरंत Anacan AI से पूछिए और निश्चिंत रहिए।', title_id = 'Dokter anak kilat 🤖', body_id = 'Berapa lama seharusnya tidur siang bayi 11 bulan? Tanyakan apa pun yang membuat Anda ragu ke Anacan AI saat itu juga, dan tenanglah.', title_ja = 'すばやく小児科の知識 🤖', body_ja = '生後11か月の赤ちゃんのお昼寝はどれくらい必要？迷ったことはなんでも、すぐにAnacan AIに聞いて安心しましょう。', title_ko = '빠른 소아과 상담 🤖', body_ko = '11개월 아기의 낮잠은 얼마나 자야 할까요? 망설여지는 건 무엇이든 Anacan AI에게 바로 물어보고 마음을 놓으세요.', title_nl = 'Een snelle kinderarts 🤖', body_nl = 'Hoe lang moet het middagslaapje van een baby van 11 maanden zijn? Vraag alles waarover je twijfelt meteen aan Anacan AI en ontspan.', title_pl = 'Szybki pediatra 🤖', body_pl = 'Ile powinna trwać popołudniowa drzemka 11-miesięcznego maluszka? Pytaj od razu Anacan AI o wszystko, co budzi twoje wątpliwości, i się uspokój.', title_pt = 'Pediatra rápido 🤖', body_pt = 'Quanto tempo deve durar a sesta da tarde de um bebé de 11 meses? Pergunte logo ao Anacan AI tudo o que lhe suscita dúvidas e fique descansada.', title_sv = 'Snabb barnläkare 🤖', body_sv = 'Hur lång ska eftermiddagsluren vara för en 11 månader gammal bebis? Fråga Anacan AI direkt om allt du är osäker på och slappna av.', title_vi = 'Bác sĩ nhi khoa nhanh chóng 🤖', body_vi = 'Giấc ngủ trưa của bé 11 tháng nên kéo dài bao lâu? Mọi điều mẹ băn khoăn, hãy hỏi ngay Anacan AI để yên tâm hơn.', title_zh = '快速儿科咨询 🤖', body_zh = '11个月宝宝的午睡应该多长？有任何拿不准的事，马上问问Anacan AI，安心一点。' WHERE id = 'ec7ed8d1-bb0f-4b34-a7a5-da3857dfd5d4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Entrando en zonas peligrosas ⚡', body_es = 'Ha crecido y ya llega a estantes a los que antes no llegaba. Vuelve a revisar la seguridad de casa (esquinas afiladas, objetos pesados).', title_fr = 'Accès aux zones dangereuses ⚡', body_fr = 'Il a encore grandi et atteint des étagères qu''il ne pouvait pas atteindre avant. Revoyez la sécurité de la maison (angles pointus, objets lourds).', title_hi = 'खतरनाक जगहों तक पहुँच ⚡', body_hi = 'उसकी लंबाई और बढ़ गई है और अब वह उन शेल्फ़ तक पहुँच जाता है जहाँ पहले नहीं पहुँचता था। घर की सुरक्षा (नुकीले कोने, भारी चीज़ें) पर फिर से नज़र डालिए।', title_id = 'Memasuki zona berbahaya ⚡', body_id = 'Tubuhnya makin tinggi dan kini ia bisa meraih rak yang dulu tak terjangkau. Tinjau kembali keamanan rumah (sudut tajam, benda berat).', title_ja = '危ないエリアへ ⚡', body_ja = '背が伸びて、前は届かなかった棚にも手が届くようになりました。家の安全（とがった角、重いもの）をもう一度見直しましょう。', title_ko = '위험 구역 진입 ⚡', body_ko = '키가 더 자라서 예전에 닿지 않던 선반에도 손이 닿아요. 집 안 안전(뾰족한 모서리, 무거운 물건)을 다시 점검하세요.', title_nl = 'Toegang tot gevaarlijke zones ⚡', body_nl = 'Je kindje is gegroeid en kan nu bij planken waar hij eerst niet bij kon. Loop de veiligheid in huis opnieuw na (scherpe hoeken, zware voorwerpen).', title_pl = 'Wejście do stref zagrożenia ⚡', body_pl = 'Urósł i sięga już półek, do których wcześniej nie dosięgał. Jeszcze raz przejrzyj bezpieczeństwo w domu (ostre narożniki, ciężkie przedmioty).', title_pt = 'Entrada em zonas perigosas ⚡', body_pt = 'Está mais alto e já chega às prateleiras onde antes não chegava. Volte a rever a segurança da casa (esquinas afiadas, objetos pesados).', title_sv = 'In i farliga zoner ⚡', body_sv = 'Barnet har blivit längre och når hyllor som det inte nådde förut. Gå igenom säkerheten i hemmet igen (vassa hörn, tunga föremål).', title_vi = 'Lấn vào vùng nguy hiểm ⚡', body_vi = 'Bé đã cao hơn và với tới những kệ trước đây chưa với được. Hãy rà soát lại an toàn trong nhà (góc nhọn, đồ vật nặng).', title_zh = '进入危险区域 ⚡', body_zh = '宝宝长高了，能够到以前够不着的架子了。重新检查一下家里的安全（尖锐边角、重物）吧。' WHERE id = '78c638dd-68ed-4cf9-acf9-6738b0e5ec7f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Prueba a calmar con música clásica suave esas tormentas sin motivo que estallan al caer la tarde. Muchas veces este truco tan sencillo hace milagros.', body_fr = 'Essayez de calmer les tempêtes inexpliquées de fin de journée avec une musique classique douce. Souvent, cette astuce toute simple fait des miracles.', body_hi = 'शाम को अचानक उठने वाले बेवजह तूफ़ानों को हल्के क्लासिकल संगीत से शांत करके देखिए। अक्सर यह आसान तरकीब कमाल कर देती है।', body_id = 'Coba redakan badai tanpa sebab menjelang sore dengan musik klasik yang lembut. Sering kali trik sederhana ini membawa keajaiban.', body_ja = '夕方に突然始まる理由のわからない嵐には、静かなクラシック音楽を試してみましょう。このシンプルな方法が、たいてい奇跡を起こします。', body_ko = '늦은 오후에 몰아치는 이유 없는 울음을 잔잔한 클래식 음악으로 달래 보세요. 이 간단한 방법이 기적을 만들 때가 많아요.', body_nl = 'Probeer de onverklaarbare stormen aan het eind van de middag te stoppen met zachte klassieke muziek. Vaak doet dit simpele trucje wonderen.', body_pl = 'Wieczorne burze bez powodu spróbuj uciszyć spokojną muzyką klasyczną. Często ten prosty trik czyni cuda.', body_pt = 'Experimente acalmar com música clássica suave as tempestades sem motivo que rebentam ao fim da tarde. Muitas vezes, este truque simples faz milagres.', body_sv = 'Prova att bryta oförklarliga stormar på eftermiddagen med lätt klassisk musik. Ofta gör det här enkla knepet underverk.', body_vi = 'Hãy thử dỗ những cơn quấy khóc không rõ lý do vào chiều tối bằng nhạc cổ điển nhẹ nhàng. Thường thì mẹo đơn giản này tạo nên điều kỳ diệu.', body_zh = '傍晚无缘无故的哭闹风暴，试试用轻柔的古典音乐平息。这个简单的小窍门常常有奇效。' WHERE id = '8a4a7da2-606f-4fbb-8668-101f2d47c03c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Encuentro mi juguete yo solo 🧸', body_es = '¿Encuentra el juguete que le has quitado de la vista y escondido detrás de algo? ¡Ya entiende del todo que los objetos siguen existiendo!', title_fr = 'Je retrouve mon jouet tout seul 🧸', body_fr = 'Il va chercher le jouet que vous avez caché derrière quelque chose, loin de ses yeux ? Il comprend parfaitement la permanence de l''objet !', title_hi = 'अपना खिलौना खुद ढूँढता हूँ 🧸', body_hi = 'जिस खिलौने को आपने नज़र से हटाकर किसी चीज़ के पीछे छिपाया, वह उसे जाकर ढूँढ लेता है? वह चीज़ों के स्थायी होने को पूरी तरह समझ रहा है!', title_id = 'Aku menemukan mainanku sendiri 🧸', body_id = 'Ia pergi dan menemukan mainan yang Anda sembunyikan dari pandangannya? Ia sudah sepenuhnya memahami bahwa benda tetap ada!', title_ja = 'おもちゃを自分で見つける 🧸', body_ja = '見えないところに隠したおもちゃを、ちゃんと探して見つけますか？見えなくてもものはあることを、しっかり理解しています！', title_ko = '장난감은 내가 찾아요 🧸', body_ko = '눈앞에서 치워 뒤에 숨긴 장난감을 찾아내나요? 대상 영속성을 완전히 이해하고 있어요!', title_nl = 'Ik vind mijn speeltje zelf 🧸', body_nl = 'Vindt je baby het speeltje terug als je het uit het zicht haalt en verstopt? Hij begrijpt nu helemaal dat dingen blijven bestaan!', title_pl = 'Sam znajduję zabawkę 🧸', body_pl = 'Znajduje zabawkę, którą schowałaś mu z oczu? W pełni rozumie stałość przedmiotu!', title_pt = 'Encontro sozinho o meu brinquedo 🧸', body_pt = 'Encontra o brinquedo que tirou da vista dele no sítio onde o escondeu? Já percebe por completo que os objetos continuam a existir!', title_sv = 'Jag hittar min leksak själv 🧸', body_sv = 'Letar barnet upp leksaken du tog ur sikte på stället där du gömde den? Det förstår fullt ut att föremål finns kvar!', title_vi = 'Con tự tìm đồ chơi 🧸', body_vi = 'Bé đi tìm và thấy món đồ chơi mẹ cất khỏi tầm mắt và giấu phía sau? Bé đã hiểu hoàn toàn rằng đồ vật vẫn tồn tại dù không nhìn thấy!', title_zh = '我自己能找到玩具 🧸', body_zh = '你把玩具从宝宝眼前拿走藏到后面，宝宝会去找出来？宝宝已经完全理解物体恒存了！' WHERE id = '0387bc9b-1c64-4eae-ac49-660cb56552f8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de noche de papá 👨‍🍼', body_es = 'No cargues tú sola con todos los despertares nocturnos. Despierta también a tu pareja: ser un equipo es repartir la responsabilidad a partes iguales.', title_fr = 'Le service de nuit de papa 👨‍🍼', body_fr = 'Ne gérez pas les réveils nocturnes toute seule. Réveillez aussi votre conjoint, être une équipe, c''est partager la responsabilité à parts égales.', title_hi = 'पापा की रात की ड्यूटी 👨‍🍼', body_hi = 'रात में जागने का बोझ अकेले मत उठाइए। अपने साथी को भी जगाइए, टीम होने का मतलब है ज़िम्मेदारी बराबर बाँटना।', title_id = 'Giliran malam ayah 👨‍🍼', body_id = 'Jangan tanggung sendiri saat ia terbangun di malam hari. Bangunkan juga pasangan Anda, menjadi tim berarti berbagi tanggung jawab secara adil.', title_ja = 'パパの夜の当番 👨‍🍼', body_ja = '夜中に起きるのを、ひとりで抱えこまないで。パートナーも起こしましょう。チームとは責任を平等に分け合うことです。', title_ko = '아빠의 밤 당번 👨‍🍼', body_ko = '밤에 깨는 일을 혼자 다 감당하지 마세요. 배우자도 깨우세요, 한 팀이 된다는 건 책임을 똑같이 나누는 거예요.', title_nl = 'Papa''s avonddienst 👨‍🍼', body_nl = 'Draag het ''s nachts opstaan niet helemaal alleen. Maak je partner ook wakker, een team zijn betekent de verantwoordelijkheid eerlijk delen.', title_pl = 'Nocna zmiana taty 👨‍🍼', body_pl = 'Nie dźwigaj nocnych pobudek zupełnie sama. Obudź też partnera, bycie drużyną to równy podział odpowiedzialności.', title_pt = 'O turno da noite do pai 👨‍🍼', body_pt = 'Não aguente sozinha todos os despertares noturnos. Acorde também o seu companheiro: ser uma equipa é dividir a responsabilidade por igual.', title_sv = 'Pappas nattskift 👨‍🍼', body_sv = 'Ta inte nattuppvaknandena helt ensam. Väck din partner också, att vara ett lag är att dela ansvaret lika.', title_vi = 'Ca đêm của bố 👨‍🍼', body_vi = 'Đừng một mình gánh hết những lần thức dậy ban đêm. Hãy gọi cả bố dậy, là một đội nghĩa là chia đều trách nhiệm.', title_zh = '爸爸的夜班 👨‍🍼', body_zh = '夜醒别全都自己扛。也叫醒你的伴侣，团队就是平分责任。' WHERE id = '6b5c2e80-bfa3-452b-805d-82d54c6b5d2d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Deja salir tus emociones 📝', body_es = 'Al acercarse el primer año, ¿sientes una tristeza extraña, esa sensación de «qué rápido ha crecido»? Pasa estas emociones al Diario de ánimo.', title_fr = 'Libérez vos émotions 📝', body_fr = 'À l''approche de ses 1 an, vous ressentez une étrange tristesse, ce sentiment qu''il a grandi si vite ? Confiez ces émotions au Journal d''humeur.', title_hi = 'अपनी भावनाओं को बाहर आने दीजिए 📝', body_hi = '1 साल करीब आते-आते मन में अजीब सी उदासी और ''कितनी जल्दी बड़ा हो गया'' का एहसास हो रहा है? इन भावनाओं को मूड डायरी में उतारिए।', title_id = 'Lepaskan perasaan Anda 📝', body_id = 'Makin dekat ke usia 1 tahun, muncul rasa sedih yang aneh, "Kok cepat sekali ia besar"? Tuangkan perasaan ini ke Buku Harian Suasana Hati.', title_ja = '気持ちを解き放とう 📝', body_ja = '1歳が近づくにつれ、「なんて早く大きくなったんだろう」と不思議な寂しさを感じていますか？その気持ちを「気分日記」に書き写しましょう。', title_ko = '감정을 자유롭게 풀어 주세요 📝', body_ko = '첫돌이 다가올수록 ''어쩜 이렇게 빨리 컸을까'' 하는 묘한 아쉬움이 드나요? 이 마음을 기분 일기에 옮겨 보세요.', title_nl = 'Laat je gevoelens de vrije loop 📝', body_nl = 'Voel je nu de eerste verjaardag nadert een vreemd soort verdriet, het gevoel: wat is hij snel groot geworden? Zet deze gevoelens in je Stemmingsdagboek.', title_pl = 'Uwolnij swoje uczucia 📝', body_pl = 'Im bliżej roczku, tym częściej czujesz dziwny smutek, że tak szybko urósł? Przelej te uczucia do Dziennika nastroju.', title_pt = 'Liberte o que sente 📝', body_pt = 'Com o 1.º aniversário a aproximar-se, sente uma tristeza estranha, aquele "cresceu tão depressa"? Passe estes sentimentos para o Diário de Humor.', title_sv = 'Släpp fram dina känslor 📝', body_sv = 'Har det väckts en konstig sorg inom dig nu när 1-årsdagen närmar sig, en känsla av hur fort barnet har vuxit? För över de här känslorna till Humördagboken.', title_vi = 'Hãy giải phóng cảm xúc 📝', body_vi = 'Càng gần sinh nhật 1 tuổi của bé, mẹ càng thấy nỗi buồn khó tả, cảm giác "sao con lớn nhanh thế"? Hãy viết những cảm xúc này vào Nhật ký tâm trạng.', title_zh = '释放你的感受 📝', body_zh = '宝宝快1岁了，心里涌起一种奇怪的伤感，觉得“怎么长得这么快”？把这些感受写进心情日记吧。' WHERE id = '89a2b668-b451-4cfe-a183-3183fc159297' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pausa del café de mamá ☕', body_es = 'El desorden de la habitación no se va a ir a ninguna parte, pero tu energía sí puede agotarse. Mientras tu peque juega solo, no corras a hacer tareas. Siéntate y tómate tu café.', title_fr = 'La pause café de maman ☕', body_fr = 'Le désordre de la pièce ne va pas s''envoler, mais votre énergie, elle, peut s''épuiser. Quand il joue seul, ne vous précipitez pas sur le ménage. Asseyez-vous et buvez votre café.', title_hi = 'माँ का कॉफ़ी ब्रेक ☕', body_hi = 'कमरे का बिखराव कहीं नहीं भागेगा, पर आपकी ऊर्जा खत्म हो सकती है। जब बच्चा अपने आप खेल रहा हो, तुरंत काम की ओर मत भागिए। बैठिए और अपनी कॉफ़ी पीजिए।', title_id = 'Rehat kopi Bunda ☕', body_id = 'Kamar yang berantakan tidak akan ke mana-mana, tapi energi Anda bisa habis. Saat ia bermain sendiri, jangan langsung bekerja. Duduklah dan nikmati kopi Anda.', title_ja = 'ママのコーヒーブレイク ☕', body_ja = '部屋の散らかりは逃げませんが、あなたのエネルギーは尽きてしまいます。赤ちゃんがひとりで遊んでいる間、すぐに家事に走らないで。座ってコーヒーを飲みましょう。', title_ko = '엄마의 커피 브레이크 ☕', body_ko = '어질러진 방은 어디 가지 않지만 엄마의 에너지는 바닥날 수 있어요. 아이가 혼자 노는 동안 바로 일하러 가지 마세요. 앉아서 커피를 마시세요.', title_nl = 'Mama''s koffiepauze ☕', body_nl = 'De rommel in de kamer loopt niet weg, maar jouw energie kan wel opraken. Ren niet meteen aan het werk als je kleintje zelf speelt. Ga zitten en drink je koffie.', title_pl = 'Przerwa na kawę dla mamy ☕', body_pl = 'Bałagan w pokoju nie ucieknie, ale twoja energia może się skończyć. Gdy maluszek bawi się sam, nie rzucaj się od razu do pracy. Usiądź i wypij kawę.', title_pt = 'A pausa para café da mãe ☕', body_pt = 'A desarrumação do quarto não foge, mas a sua energia pode acabar. Enquanto o bebé brinca sozinho, não corra logo para as tarefas. Sente-se e beba o seu café.', title_sv = 'Mammas kaffepaus ☕', body_sv = 'Stöket i rummet springer ingenstans, men din energi kan ta slut. Rusa inte till sysslorna så fort barnet leker på egen hand. Sätt dig ner och drick ditt kaffe.', title_vi = 'Giờ nghỉ cà phê của mẹ ☕', body_vi = 'Căn phòng bừa bộn chẳng chạy đi đâu, nhưng năng lượng của mẹ thì có thể cạn. Khi bé tự chơi, đừng vội lao vào làm việc. Hãy ngồi xuống và thưởng thức cà phê.', title_zh = '妈妈的咖啡时间 ☕', body_zh = '房间乱也跑不了，但你的精力会耗光。宝宝自己玩的时候，别急着去干活。坐下来喝杯咖啡吧。' WHERE id = 'd24d332c-e00e-4b7f-8dac-28439e172c26' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La leche materna sigue siendo lo principal! 🍼', body_es = 'La leche materna es importante hasta el primer año. Usa el temporizador de tomas para asegurarte de que cubre su necesidad diaria de leche.', title_fr = 'Le lait maternel reste essentiel ! 🍼', body_fr = 'Le lait maternel est important jusqu''à 1 an. Lancez le minuteur de repas pour vous assurer que ses besoins quotidiens en lait sont couverts.', title_hi = 'माँ का दूध अब भी सबसे अहम है! 🍼', body_hi = '1 साल तक माँ का दूध ज़रूरी है। फ़ीडिंग टाइमर चालू करके पक्का कीजिए कि रोज़ की दूध की ज़रूरत पूरी हो रही है।', title_id = 'ASI tetap yang utama! 🍼', body_id = 'ASI tetap penting hingga usia 1 tahun. Nyalakan timer menyusui dan pastikan kebutuhan susu hariannya terpenuhi.', title_ja = '母乳・ミルクはまだ主役！🍼', body_ja = '1歳までは母乳・ミルクが大切です。授乳タイマーを使って、1日に必要なミルクの量をとれているか確かめましょう。', title_ko = '모유는 여전히 중요해요! 🍼', body_ko = '첫돌까지는 모유가 중요해요. 수유 타이머를 켜서 하루 수유량이 충분한지 확인하세요.', title_nl = 'Moedermelk is nog steeds de basis! 🍼', body_nl = 'Tot 1 jaar is moedermelk belangrijk. Zet de voedingstimer aan en zorg ervoor dat je baby dagelijks genoeg melk krijgt.', title_pl = 'Mleko mamy wciąż jest podstawą! 🍼', body_pl = 'Do roczku mleko mamy jest bardzo ważne. Włączaj timer karmienia i upewnij się, że dzienne zapotrzebowanie na mleko jest zaspokojone.', title_pt = 'O leite materno continua a ser a base! 🍼', body_pt = 'O leite materno é importante até ao 1.º ano. Ligue o temporizador de alimentação e confirme que as necessidades diárias de leite estão cobertas.', title_sv = 'Bröstmjölken är fortfarande grunden! 🍼', body_sv = 'Bröstmjölken är viktig fram till 1 år. Starta matningstimern och se till att det dagliga mjölkbehovet täcks.', title_vi = 'Sữa mẹ vẫn là chính! 🍼', body_vi = 'Sữa mẹ rất quan trọng cho đến khi bé 1 tuổi. Hãy bật Hẹn giờ cho bú để chắc chắn bé được đáp ứng đủ nhu cầu sữa mỗi ngày.', title_zh = '母乳仍然是主角！🍼', body_zh = '1岁之前母乳很重要。用喂养计时器确认宝宝每天的奶量需求得到满足吧。' WHERE id = '8c48dfb8-f3cc-4402-82d4-4c81ed9fc15b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escapa de las cuatro paredes ⛅', body_es = '¿La casa te agobia? Mira Tiempo y ropa y déjale libre en el parque para que toque la hierba y las hojas del suelo.', title_fr = 'S''évader des quatre murs ⛅', body_fr = 'La maison vous oppresse ? Consultez Météo et tenue, puis laissez-le libre au parc pour toucher l''herbe et les feuilles.', title_hi = 'चार दीवारों से छुट्टी ⛅', body_hi = 'घर में घुटन हो रही है? मौसम और कपड़े देखिए और पार्क में उसे ज़मीन की घास और पत्तियाँ छूने के लिए आज़ाद छोड़िए।', title_id = 'Kabur dari empat dinding ⛅', body_id = 'Rumah terasa sesak? Cek Cuaca dan Pakaian, lalu biarkan ia bebas menyentuh rumput dan dedaunan di taman.', title_ja = '4つの壁から脱出 ⛅', body_ja = '家にいると息がつまる？「天気と服装」をチェックして、公園で地面の草や葉っぱに自由にさわらせてあげましょう。', title_ko = '네 벽에서 탈출 ⛅', body_ko = '집이 답답한가요? 날씨와 옷차림을 확인하고 공원에서 풀과 나뭇잎을 직접 만질 수 있게 자유롭게 풀어 주세요.', title_nl = 'Ontsnap uit je vier muren ⛅', body_nl = 'Word je gek binnen? Kijk in Weer en kleding en laat je kindje in het park vrij het gras en de blaadjes op de grond aanraken.', title_pl = 'Ucieczka z czterech ścian ⛅', body_pl = 'Dom cię przytłacza? Sprawdź Pogodę i ubiór i pozwól mu swobodnie dotykać w parku trawy i liści na ziemi.', title_pt = 'Fuga às quatro paredes ⛅', body_pt = 'A casa está a sufocá-la? Veja o Tempo e Roupa e, no parque, deixe-o à vontade para tocar na relva e nas folhas do chão.', title_sv = 'Fly från de fyra väggarna ⛅', body_sv = 'Känns det trångt hemma? Kolla Väder och kläder och låt barnet fritt röra vid gräset och löven på marken i parken.', title_vi = 'Thoát khỏi bốn bức tường ⛅', body_vi = 'Ở nhà khiến mẹ ngột ngạt? Xem Thời tiết và trang phục rồi để bé tự do chạm vào cỏ, lá cây trên mặt đất ở công viên.', title_zh = '逃离四面墙 ⛅', body_zh = '在家闷得慌？看看天气穿衣，在公园里放宝宝自由活动，摸摸地上的草和树叶吧。' WHERE id = '23c2a94e-cf0d-4f81-9604-79b4dcfb2460' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ayuda a vestirse 👕', body_es = '¿Cuando le pones la camiseta estira los brazos o levanta la pierna él solo? Está colaborando contigo. Anota esta pequeña ayuda en el Seguimiento del desarrollo.', title_fr = 'Il aide à s''habiller 👕', body_fr = 'Quand vous lui mettez son t-shirt, il tend les bras ou lève la jambe tout seul ? Il coopère avec vous. Notez ce petit coup de main dans le Suivi de développement.', title_hi = 'कपड़े पहनने में मदद करता है 👕', body_hi = 'कमीज़ पहनाते समय खुद बाँहें आगे बढ़ाता है या पैर उठाता है? वह आपका साथ दे रहा है। ग्रोथ ट्रैकर में इस छोटी मदद को दर्ज कीजिए।', title_id = 'Membantu saat berpakaian 👕', body_id = 'Saat dipakaikan baju, ia menjulurkan lengan atau mengangkat kakinya sendiri? Ia bekerja sama dengan Anda. Catat bantuan kecil ini di Pelacak Perkembangan.', title_ja = 'お着替えのお手伝い 👕', body_ja = 'シャツを着せるとき、自分から腕を伸ばしたり足を上げたりしますか？あなたと協力しているのです。「発達トラッカー」にこの小さなお手伝いを記録しましょう。', title_ko = '옷 입을 때 도와줘요 👕', body_ko = '옷을 입힐 때 스스로 팔을 내밀거나 다리를 드나요? 엄마와 협력하고 있어요. 성장 기록에 이 작은 도움을 남겨 두세요.', title_nl = 'Hij helpt mee met aankleden 👕', body_nl = 'Steekt je baby zelf zijn armpjes uit of tilt hij zijn been op als je hem aankleedt? Hij werkt met je samen. Noteer deze kleine hulp in de Groeitracker.', title_pl = 'Pomaga przy ubieraniu 👕', body_pl = 'Gdy zakładasz mu koszulkę, sam wyciąga rączki albo podnosi nóżkę? Współpracuje z tobą. Zapisz tę małą pomoc w Śledzeniu rozwoju.', title_pt = 'Ajuda a vestir-se 👕', body_pt = 'Quando lhe veste a camisola, ele estica os braços ou levanta o pé? Está a colaborar consigo. Registe esta pequena ajuda no Registo de Desenvolvimento.', title_sv = 'Hjälper till med påklädningen 👕', body_sv = 'Sträcker barnet själv fram armarna eller lyfter benet när du klär på det tröjan? Det samarbetar med dig. Anteckna den här lilla hjälpen i Utvecklingsspåraren.', title_vi = 'Bé giúp mẹ mặc đồ 👕', body_vi = 'Khi mẹ mặc áo cho bé, bé tự đưa tay ra hay nhấc chân lên? Bé đang hợp tác với mẹ đấy. Hãy ghi lại sự giúp đỡ nhỏ bé này trong Theo dõi phát triển.', title_zh = '穿衣服时会配合 👕', body_zh = '给宝宝穿上衣时，宝宝会自己伸出胳膊或抬起腿？宝宝在和你配合。在发育追踪里记下这个小小的帮忙吧。' WHERE id = '77a8c135-4a26-4877-9f24-fc51c941fb7a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hacerse amigo de la oscuridad 🌙', body_es = 'Para que se duerma antes, añade a la rutina de la noche un momento de oscuridad. Apaga todas las luces que sobran en la habitación.', title_fr = 'Apprivoiser l''obscurité 🌙', body_fr = 'Pour l''aider à s''endormir plus vite, ajoutez l''obscurité à la routine du soir. Éteignez toutes les lumières superflues de la pièce.', title_hi = 'अँधेरे से दोस्ती 🌙', body_hi = 'उसे जल्दी सुलाने के लिए शाम के रूटीन में अँधेरे से पहचान जोड़िए। कमरे की सारी अतिरिक्त लाइटें बंद कीजिए।', title_id = 'Bersahabat dengan gelap 🌙', body_id = 'Agar ia lebih cepat tertidur, kenalkan suasana gelap dalam rutinitas malam. Matikan semua lampu tambahan di kamar.', title_ja = '暗さと仲よしに 🌙', body_ja = '早く寝つけるように、夜のルーティンに暗さに慣れる時間を取り入れましょう。部屋のよけいな明かりはすべて消しましょう。', title_ko = '어둠과 친해지기 🌙', body_ko = '빨리 잠들 수 있도록 저녁 루틴에 어둠에 익숙해지는 시간을 더하세요. 방의 불필요한 조명을 모두 끄세요.', title_nl = 'Vriendschap met het donker 🌙', body_nl = 'Voeg kennismaking met het donker toe aan de avondroutine, zodat je baby sneller in slaap valt. Doe alle extra lampjes in de kamer uit.', title_pl = 'Przyjaźń z ciemnością 🌙', body_pl = 'Aby szybciej zasypiał, dodaj do wieczornej rutyny oswajanie z ciemnością. Wyłącz w pokoju wszystkie dodatkowe światła.', title_pt = 'Fazer amizade com o escuro 🌙', body_pt = 'Para o ajudar a adormecer mais depressa, junte à rotina da noite um momento de habituação ao escuro. Apague todas as luzes desnecessárias do quarto.', title_sv = 'Vänskap med mörkret 🌙', body_sv = 'Lägg till en stund i mörker i kvällsrutinen så att barnet somnar fortare. Släck alla onödiga lampor i rummet.', title_vi = 'Làm bạn với bóng tối 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy thêm bước làm quen với bóng tối vào nếp sinh hoạt buổi tối. Tắt hết đèn không cần thiết trong phòng.', title_zh = '和黑暗做朋友 🌙', body_zh = '为了让宝宝更快入睡，在晚间作息里加入熟悉黑暗的环节。关掉房间里所有多余的灯。' WHERE id = '9df28291-b590-4e7d-a861-feb0732398b2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te pierdas en los foros 🤖', body_es = '¿Has notado algo raro en sus movimientos? No busques durante horas en internet: pregunta directamente a Anacan AI y quédate tranquila.', title_fr = 'Ne vous perdez pas dans les forums 🤖', body_fr = 'Quelque chose vous semble étrange dans ses mouvements ? Ne cherchez pas des heures sur Internet, posez directement votre question à Anacan AI et soyez rassurée.', title_hi = 'फ़ोरम में मत खोइए 🤖', body_hi = 'बच्चे की हरकतों में कुछ अजीब लगा? घंटों इंटरनेट पर मत खोजिए, अपना सवाल सीधे Anacan AI से पूछिए और निश्चिंत हो जाइए।', title_id = 'Jangan tersesat di forum 🤖', body_id = 'Merasa ada yang aneh pada gerakannya? Jangan mencari di internet berjam-jam, tanyakan langsung ke Anacan AI dan tenangkan diri.', title_ja = '掲示板で迷子にならないで 🤖', body_ja = '赤ちゃんの動きで気になることがありましたか？何時間もネットで調べないで、Anacan AIに直接質問して安心しましょう。', title_ko = '커뮤니티 글 속에서 헤매지 마세요 🤖', body_ko = '아이의 움직임이 이상하게 느껴지나요? 몇 시간씩 인터넷을 검색하지 말고 Anacan AI에게 바로 물어 마음을 놓으세요.', title_nl = 'Verdwaal niet op forums 🤖', body_nl = 'Viel je iets vreemds op aan hoe je kindje beweegt? Zoek niet urenlang op internet, stel je vraag direct aan Anacan AI en word rustig.', title_pl = 'Nie gub się na forach 🤖', body_pl = 'Coś w ruchach maluszka wydaje ci się dziwne? Nie szukaj godzinami w internecie, zadaj pytanie bezpośrednio Anacan AI i się uspokój.', title_pt = 'Não se perca nos fóruns 🤖', body_pt = 'Notou algo estranho nos movimentos do bebé? Não passe horas a pesquisar na internet: faça a pergunta diretamente ao Anacan AI e fique descansada.', title_sv = 'Gå inte vilse i forumen 🤖', body_sv = 'Har du märkt något konstigt i barnets rörelser? Sök inte i timmar på nätet, ställ din fråga direkt till Anacan AI och lugna dig.', title_vi = 'Đừng lạc giữa diễn đàn 🤖', body_vi = 'Mẹ thấy có điều gì lạ trong cử động của bé? Đừng tìm kiếm trên mạng hàng giờ, hãy hỏi thẳng Anacan AI và yên tâm hơn.', title_zh = '别在论坛里迷路 🤖', body_zh = '觉得宝宝的动作有些奇怪？别在网上搜几个小时，直接问Anacan AI，安下心来吧。' WHERE id = '72f5aeb4-94f9-40bc-943e-fa87664da32b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Entiende el significado de las palabras 🗣️', body_es = 'Cuando le dices «trae la pelota», de verdad va a buscarla. Su vocabulario (las palabras que entiende) crece rápidamente. Háblale con frases más complejas.', title_fr = 'Il connaît le sens des mots 🗣️', body_fr = 'Quand vous dites « Apporte le ballon », il va vraiment le chercher. Son vocabulaire (les mots qu''il comprend) s''enrichit vite. Parlez-lui avec des phrases plus complexes.', title_hi = 'शब्दों का मतलब समझता है 🗣️', body_hi = '''गेंद लाओ'' कहने पर वह सच में जाकर गेंद ढूँढता है। उसकी शब्दावली (जो शब्द वह समझता है) तेज़ी से बढ़ रही है। उससे और लंबे वाक्यों में बात कीजिए।', title_id = 'Ia memahami arti kata 🗣️', body_id = 'Saat Anda berkata "Ambil bolanya", ia benar-benar pergi mencari bola. Kosakatanya (kata yang ia pahami) bertambah pesat. Ajak ia bicara dengan kalimat yang lebih panjang.', title_ja = '言葉の意味がわかる 🗣️', body_ja = '「ボール持ってきて」と言うと、本当にボールを探しに行きます。理解できる言葉がどんどん増えています。もっと長い文章で話しかけてあげましょう。', title_ko = '말의 뜻을 알아요 🗣️', body_ko = '''공 가져와'' 하면 정말 가서 공을 찾아요. 알아듣는 단어가 빠르게 늘고 있어요. 조금 더 긴 문장으로 이야기해 주세요.', title_nl = 'Hij kent de betekenis van woorden 🗣️', body_nl = 'Als je zegt: haal de bal eens, gaat hij echt naar de bal zoeken. Zijn woordenschat (de woorden die hij begrijpt) groeit snel. Praat met hem in moeilijkere zinnen.', title_pl = 'Rozumie znaczenie słów 🗣️', body_pl = 'Gdy mówisz „przynieś piłkę”, naprawdę idzie jej szukać. Zasób rozumianych słów szybko rośnie. Rozmawiaj z nim bardziej złożonymi zdaniami.', title_pt = 'Sabe o que as palavras significam 🗣️', body_pt = 'Quando diz "traz a bola", ele vai mesmo procurá-la. O vocabulário (as palavras que entende) aumenta depressa. Fale com ele em frases mais complexas.', title_sv = 'Barnet vet vad orden betyder 🗣️', body_sv = 'När du säger ''hämta bollen'' går barnet verkligen och letar efter bollen. Ordförrådet (orden barnet förstår) växer snabbt. Prata med barnet med mer avancerade meningar.', title_vi = 'Bé hiểu nghĩa của từ 🗣️', body_vi = 'Khi mẹ nói "Mang bóng lại đây", bé thật sự đi tìm quả bóng. Vốn từ bé hiểu được đang tăng nhanh. Hãy nói chuyện với bé bằng những câu phức tạp hơn.', title_zh = '听懂词语的意思 🗣️', body_zh = '你说“把球拿来”，宝宝真的会去找球。宝宝能听懂的词汇量增长得很快。和宝宝说话时用更复杂一点的句子吧。' WHERE id = 'c8b05bf8-0ed8-4eec-86f7-4cba168167e1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de Cuentos inteligentes🪄', body_es = 'Crea en Cuentos inteligentes la historia de un héroe que dentro de solo un mes cumplirá 1 año. Que solo este cuento rompa el silencio de la noche.', title_fr = 'L''heure des Contes intelligents 🪄', body_fr = 'Dans les Contes intelligents, créez l''histoire du héros qui aura 1 an dans seulement 1 mois. Que seul ce conte rompe le silence de la nuit.', title_hi = 'स्मार्ट कहानी का समय 🪄', body_hi = 'स्मार्ट कहानियों में उस हीरो की कहानी बनाइए जो बस 1 महीने बाद 1 साल का होने वाला है। रात की खामोशी को बस यही कहानी तोड़े।', title_id = 'Waktunya Dongeng Pintar🪄', body_id = 'Di Dongeng Pintar, buat kisah pahlawan yang sebulan lagi berusia 1 tahun. Biarkan hanya dongeng ini yang memecah keheningan malam.', title_ja = '「スマートおはなし」の時間🪄', body_ja = '「スマートおはなし」で、あと1か月で1歳になるヒーローのお話をつくりましょう。夜の静けさを破るのは、このお話だけに。', title_ko = '스마트 동화 시간🪄', body_ko = '스마트 동화에서 딱 1개월 뒤면 첫돌을 맞는 주인공의 이야기를 만들어 보세요. 밤의 고요는 이 동화만 깨우게 해 주세요.', title_nl = 'Tijd voor Slimme sprookjes🪄', body_nl = 'Maak in Slimme sprookjes het verhaal van een held die over maar 1 maand 1 jaar wordt. Laat alleen dit sprookje de stilte van de nacht doorbreken.', title_pl = 'Czas na Mądre bajki 🪄', body_pl = 'Stwórz w Mądrych bajkach historię o bohaterze, który za miesiąc skończy roczek. Niech nocną ciszę przerywa tylko ta bajka.', title_pt = 'Hora das Histórias Inteligentes🪄', body_pt = 'Crie nas Histórias Inteligentes a história do herói que daqui a apenas 1 mês faz 1 ano. Que só esta história quebre o silêncio da noite.', title_sv = 'Dags för Smarta sagor🪄', body_sv = 'Skapa sagan om hjälten som fyller 1 år om bara 1 månad i Smarta sagor. Låt bara den här sagan bryta nattens tystnad.', title_vi = 'Giờ Truyện cổ tích thông minh🪄', body_vi = 'Hãy tạo trong Truyện cổ tích thông minh câu chuyện về người hùng chỉ còn 1 tháng nữa là tròn 1 tuổi. Hãy để chỉ có câu chuyện này phá vỡ sự tĩnh lặng của màn đêm.', title_zh = '智能故事时间 🪄', body_zh = '在智能故事里创作一个再过1个月就满1岁的小英雄的故事。让夜晚的宁静只被这个故事打破吧。' WHERE id = 'f8aae6d9-1b70-4333-a55c-1937c871c533' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Adornos y globos para el primer cumpleaños? 🛒', body_es = 'No te calientes la cabeza: empieza ya a preparar la Lista de la compra.', title_fr = 'Des décorations et des ballons pour les 1 an ? 🛒', body_fr = 'Ne vous fatiguez pas l''esprit, commencez dès maintenant à préparer la Liste de courses.', title_hi = 'पहले जन्मदिन की सजावट और गुब्बारे चाहिए? 🛒', body_hi = 'दिमाग मत थकाइए, शॉपिंग लिस्ट अभी से तैयार करना शुरू कीजिए।', title_id = 'Dekorasi dan balon untuk persiapan 1 tahun? 🛒', body_id = 'Jangan bikin pusing, mulailah menyiapkan Daftar Belanja dari sekarang.', title_ja = '1歳の準備に必要な飾りや風船？🛒', body_ja = '頭を疲れさせないで、今から「買い物リスト」をつくりはじめましょう。', title_ko = '첫돌 준비에 필요한 장식과 풍선? 🛒', body_ko = '머리 아프게 고민하지 말고 지금부터 쇼핑 목록을 준비하세요.', title_nl = 'Versiering en ballonnen nodig voor de eerste verjaardag?  🛒', body_nl = 'Breek je hoofd er niet over, begin nu al met je Boodschappenlijstje.', title_pl = 'Dekoracje i balony na roczek? 🛒', body_pl = 'Nie męcz głowy, zacznij już teraz przygotowywać Listę zakupów.', title_pt = 'Decorações e balões para preparar o 1.º aniversário?  🛒', body_pt = 'Não canse a cabeça: comece já a preparar a Lista de Compras.', title_sv = 'Dekorationer och ballonger till 1-årsfesten?  🛒', body_sv = 'Belasta inte hjärnan, börja göra i ordning Inköpslistan redan nu.', title_vi = 'Đồ trang trí, bóng bay cho sinh nhật 1 tuổi?  🛒', body_vi = 'Đừng bắt não làm việc quá sức, hãy bắt đầu chuẩn bị Danh sách mua sắm ngay từ bây giờ.', title_zh = '一周岁准备需要的装饰和气球？🛒', body_zh = '别费脑筋，现在就开始准备购物清单吧。' WHERE id = '0ca61e8f-0ab9-48ea-85e7-af32b2be41a1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Intentos insistentes 🧗‍♂️', body_es = 'Intenta levantarse agarrado a los muebles aun con un juguete en la mano. Su capacidad de equilibrio se ha fortalecido muchísimo. Obsérvale sin intervenir.', title_fr = 'Des efforts obstinés 🧗‍♂️', body_fr = 'Un jouet à la main, il essaie de se hisser en s''agrippant aux meubles. Son équilibre s''est incroyablement renforcé. Observez-le de loin sans intervenir.', title_hi = 'ज़िद्दी कोशिशें 🧗‍♂️', body_hi = 'हाथ में खिलौना होते हुए भी फ़र्नीचर पकड़कर उठने की कोशिश करता है। उसका संतुलन कमाल का मज़बूत हो गया है। दखल दिए बिना दूर से देखिए।', title_id = 'Usaha pantang menyerah 🧗‍♂️', body_id = 'Sambil memegang mainan, ia mencoba berdiri berpegangan pada perabot. Keseimbangannya menguat luar biasa. Saksikan dari jauh tanpa ikut campur.', title_ja = 'あきらめない挑戦 🧗‍♂️', body_ja = 'おもちゃを持ったまま、家具につかまって立ち上がろうとしています。バランス感覚が驚くほど強くなっています。手を出さずに、少し離れて見守りましょう。', title_ko = '끈기 있는 도전 🧗‍♂️', body_ko = '장난감을 손에 쥔 채로 가구를 잡고 일어서려 해요. 균형 감각이 놀랍게 좋아졌어요. 개입하지 말고 곁에서 지켜보세요.', title_nl = 'Volhardende pogingen 🧗‍♂️', body_nl = 'Met een speeltje in zijn hand probeert hij zich op te trekken aan een meubel. Zijn evenwicht is ongelofelijk sterk geworden. Kijk van een afstandje toe zonder in te grijpen.', title_pl = 'Uparte próby 🧗‍♂️', body_pl = 'Z zabawką w rączce próbuje wstać, trzymając się mebli. Równowaga niesamowicie się wzmocniła. Obserwuj go z boku, nie ingerując.', title_pt = 'Tentativas persistentes 🧗‍♂️', body_pt = 'Com um brinquedo na mão, tenta pôr-se de pé agarrado aos móveis. O equilíbrio está incrivelmente mais forte. Observe de longe, sem intervir.', title_sv = 'Envisa försök 🧗‍♂️', body_sv = 'Barnet försöker dra sig upp i möblerna med en leksak i handen. Balansförmågan har blivit otroligt stark. Titta på från sidan utan att lägga dig i.', title_vi = 'Nỗ lực bền bỉ 🧗‍♂️', body_vi = 'Tay vẫn cầm đồ chơi, bé vẫn cố bám đồ đạc để đứng lên. Khả năng giữ thăng bằng đã mạnh lên đáng kinh ngạc. Hãy quan sát từ xa mà không can thiệp.', title_zh = '坚持不懈 🧗‍♂️', body_zh = '宝宝手里拿着玩具，还想扶着家具站起来。平衡能力变得非常强了。别干预，在一旁看着吧。' WHERE id = '519cad33-f5e8-4169-8f1d-93f4343568db' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Heroína silenciosa 🤫', body_es = 'En cuanto se duerme, cada ruido de casa suena como una bomba. Mientras estabilizas el límite de la habitación con el Medidor de sonido, pisa tú también con suavidad.', title_fr = 'Le héros silencieux 🤫', body_fr = 'Au moment où il s''endort, chaque bruit de la maison résonne comme une explosion. Pendant que vous stabilisez le niveau sonore avec le Sonomètre, allégez aussi vos propres pas.', title_hi = 'खामोश हीरो 🤫', body_hi = 'उसके सोते ही घर की हर आवाज़ बम फटने जैसी लगती है। साउंड मीटर से कमरे की आवाज़ की सीमा तय करते हुए अपने कदम भी हल्के रखिए।', title_id = 'Pahlawan tanpa suara 🤫', body_id = 'Saat ia mulai tertidur, setiap suara di rumah terdengar seperti ledakan bom. Sambil menstabilkan batas suara kamar dengan Pengukur Suara, pelankan juga langkah Anda.', title_ja = '静かなヒーロー 🤫', body_ja = '寝ついたとたん、家のどんな音も爆発のように聞こえます。「サウンドメーター」で部屋の音を一定に保ちながら、あなたの足音もそっと軽くしましょう。', title_ko = '소리 없는 영웅 🤫', body_ko = '아기가 잠드는 순간 집 안의 모든 소리가 폭탄처럼 느껴지죠. 소음 측정기로 방의 소리 한도를 맞추면서 엄마의 발걸음도 살살 가볍게 해 주세요.', title_nl = 'Een stille heldin 🤫', body_nl = 'Zodra je baby in slaap valt, klinkt elk geluid in huis als een bom. Houd met de Geluidsmeter de kamer binnen de grens en zet ook zelf zachtere stappen.', title_pl = 'Cichy bohater 🤫', body_pl = 'Gdy tylko zaśnie, każdy dźwięk w domu brzmi jak wybuch bomby. Ustawiając limit w pokoju Miernikiem dźwięku, stąpaj też lżej.', title_pt = 'A heroína silenciosa 🤫', body_pt = 'Mal adormece, qualquer som da casa parece uma explosão. Enquanto estabiliza o limite do quarto com o Medidor de Som, ande também com passos leves.', title_sv = 'Den tysta hjälten 🤫', body_sv = 'Så fort barnet somnar låter varje ljud hemma som en bombexplosion. Medan du håller rummets ljudnivå jämn med Ljudmätaren, gå också lite lättare på foten.', title_vi = 'Người hùng thầm lặng 🤫', body_vi = 'Ngay khi bé ngủ, mọi tiếng động trong nhà đều như tiếng bom nổ. Khi điều chỉnh ngưỡng âm thanh trong phòng bằng Đo âm thanh, mẹ cũng nhớ bước chân nhẹ nhàng hơn nhé.', title_zh = '安静的英雄 🤫', body_zh = '宝宝刚睡着时，家里任何声音都像炸弹爆炸一样。用噪音测量稳定房间的音量上限，同时也放轻你自己的脚步吧。' WHERE id = 'aa2fb7c9-acf7-4050-9102-4f2927091b95' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Complicidad entre mamás 💬', body_es = '¿Te agobia pensar «cómo organizo el cumpleaños»? Escribe en la Comunidad Anacan y recibe de otras mamás ideas creativas y para todos los bolsillos.', title_fr = 'Confidences entre mamans 💬', body_fr = 'La question « Comment organiser son anniversaire ? » vous épuise ? Écrivez dans la Communauté Anacan et recevez des mamans des idées créatives et adaptées à votre budget.', title_hi = 'माँओं का भरोसे का दायरा 💬', body_hi = '''जन्मदिन कैसे मनाऊँ?'' यह सोच आपको थका रही है? Anacan कम्युनिटी में लिखिए और माँओं से रचनात्मक, बजट के अनुकूल आइडिया पाइए।', title_id = 'Teman curhat para ibu 💬', body_id = 'Pikiran "Bagaimana merayakan ulang tahunnya?" membuat Anda lelah? Tulis di Komunitas Anacan dan dapatkan ide kreatif yang ramah anggaran dari para ibu.', title_ja = 'ママたちの打ち明け話 💬', body_ja = '「誕生日、どうしよう？」と考えて疲れていませんか？Anacanコミュニティに書きこんで、ママたちからクリエイティブで予算に合ったアイデアをもらいましょう。', title_ko = '엄마들의 속마음 나누기 💬', body_ko = '''생일 파티를 어떻게 하지?'' 하는 고민에 지쳤나요? Anacan 커뮤니티에 글을 남기고 엄마들에게서 창의적이고 예산에 맞는 아이디어를 받아 보세요.', title_nl = 'Moeders onder elkaar 💬', body_nl = 'Word je moe van de gedachte: hoe moet ik de verjaardag vieren? Schrijf in de Anacan Community en krijg creatieve ideeën van moeders die passen bij je budget.', title_pl = 'Mamy powierniczki 💬', body_pl = 'Męczy cię myśl, jak zorganizować urodziny? Napisz w Społeczności Anacan i zbierz od mam kreatywne pomysły dopasowane do budżetu.', title_pt = 'A cumplicidade das mães 💬', body_pt = 'O pensamento "como vou fazer a festa de anos?" está a cansá-la? Escreva na Comunidade Anacan e receba das mães ideias criativas e à medida do orçamento.', title_sv = 'Mammornas förtroende 💬', body_sv = 'Tröttar tanken ''hur ska jag ordna födelsedagen?'' ut dig? Skriv i Anacans Community och få kreativa idéer som passar budgeten från andra mammor.', title_vi = 'Tâm sự giữa các bà mẹ 💬', body_vi = 'Ý nghĩ "Tổ chức sinh nhật thế nào đây?" làm mẹ mệt mỏi? Hãy viết vào Cộng đồng Anacan và nhận những ý tưởng sáng tạo, vừa túi tiền từ các bà mẹ.', title_zh = '妈妈们的知心话 💬', body_zh = '“生日该怎么办？”这个念头让你很累？发到Anacan社区，从妈妈们那里获取有创意又省钱的点子吧。' WHERE id = '9cba5d69-92c6-472c-bb83-c5522d806018' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una foto que detiene el tiempo 📸', body_es = 'Cada día parece un poco más niño. Abre ya la Sesión de fotos del bebé y guarda para siempre este momento de baile tan espontáneo.', title_fr = 'La photo qui arrête le temps 📸', body_fr = 'Chaque jour, il ressemble un peu plus à un enfant. Ouvrez tout de suite la Séance photo bébé et immortalisez ce moment de danse spontanée.', title_hi = 'समय को थाम लेने वाली तस्वीर 📸', body_hi = 'वह हर दिन थोड़ा और बच्चे जैसा दिखता है। तुरंत बेबी फ़ोटोशूट खोलिए और उसके इस सहज नाच के पल को यादों में बसाइए।', title_id = 'Foto yang menghentikan waktu 📸', body_id = 'Setiap hari ia makin terlihat seperti anak-anak. Segera buka Sesi Foto Bayi dan abadikan momen tariannya yang polos ini.', title_ja = '時間を止める1枚 📸', body_ja = '日に日に子どもらしくなっていきます。すぐに「ベビーフォトセッション」を開いて、この自然なダンスの瞬間を残しましょう。', title_ko = '시간을 멈추는 한 컷 📸', body_ko = '아기가 날마다 조금씩 더 어린이처럼 보여요. 지금 바로 아기 사진 촬영을 열어 이 꾸밈없는 춤추는 순간을 남겨 두세요.', title_nl = 'Een foto die de tijd stilzet 📸', body_nl = 'Elke dag lijkt hij meer op een kind. Open meteen Babyfotoshoot en leg dit oprechte dansmoment vast.', title_pl = 'Kadr, który zatrzymuje czas 📸', body_pl = 'Z każdym dniem wygląda trochę bardziej jak dziecko. Od razu otwórz Sesję zdjęciową dziecka i uwiecznij ten szczery taneczny moment.', title_pt = 'Uma foto que para o tempo 📸', body_pt = 'A cada dia parece um pouco mais uma criança. Abra já a Sessão Fotográfica do Bebé e guarde na memória este momento de dança tão espontâneo.', title_sv = 'Bilden som stoppar tiden 📸', body_sv = 'För varje dag ser barnet lite mer ut som ett barn. Öppna Babyfotografering direkt och förevig den här äkta dansstunden.', title_vi = 'Khoảnh khắc ngưng đọng thời gian 📸', body_vi = 'Mỗi ngày bé trông càng giống một đứa trẻ hơn. Hãy mở ngay Chụp ảnh cho bé và lưu giữ khoảnh khắc bé nhảy múa hồn nhiên này.', title_zh = '定格时光 📸', body_zh = '宝宝一天比一天更像个小孩子了。马上打开宝宝写真，记下宝宝这段可爱的舞蹈吧。' WHERE id = 'f558e782-e140-4835-8b11-1d5f01a717bf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baile y ritmos 🎶', body_es = '¿Baila en cuanto oye un sonido rítmico en la tele o en el móvil? Su percepción musical está a pleno rendimiento, ¡únete y bailad juntos!', title_fr = 'Danse et rythmes 🎶', body_fr = 'Il danse dès qu''il entend un son rythmé à la télévision ou sur le téléphone ? Sa perception musicale est bien éveillée, dansez avec lui !', title_hi = 'नाच और ताल 🎶', body_hi = 'टीवी या फ़ोन पर कोई लयबद्ध आवाज़ सुनते ही नाचने लगता है? संगीत की समझ पूरी तरह जाग गई है, उसके साथ नाचिए!', title_id = 'Tarian dan irama 🎶', body_id = 'Begitu mendengar irama dari TV atau ponsel, ia langsung menari? Kepekaan musiknya sudah bekerja penuh, ikutlah menari bersamanya!', title_ja = 'ダンスとリズム 🎶', body_ja = 'テレビやスマホからリズムのある音が聞こえると、すぐに踊りだしますか？音楽を感じる力がすっかり目覚めています。一緒に踊りましょう！', title_ko = '춤과 리듬 🎶', body_ko = 'TV나 휴대폰에서 리듬 있는 소리가 들리자마자 춤을 추나요? 음악 감각이 완전히 깨어났어요, 함께 춤춰 주세요!', title_nl = 'Dans en ritme 🎶', body_nl = 'Begint je baby te dansen zodra hij een ritmisch geluid hoort op de tv of telefoon? Zijn gevoel voor muziek werkt helemaal, dans mee!', title_pl = 'Taniec i rytmy 🎶', body_pl = 'Gdy tylko usłyszy rytmiczny dźwięk z telewizora lub telefonu, tańczy? Odbiór muzyki działa pełną parą, przyłącz się i tańczcie!', title_pt = 'Dança e ritmos 🎶', body_pt = 'Mal ouve um som ritmado na televisão ou no telemóvel, começa a dançar? A perceção musical está a funcionar em pleno: junte-se a ele e dancem!', title_sv = 'Dans och rytmer 🎶', body_sv = 'Dansar barnet så fort det hör ett rytmiskt ljud på tv:n eller telefonen? Musikkänslan är fullt vaken, dansa med!', title_vi = 'Nhảy múa và nhịp điệu 🎶', body_vi = 'Vừa nghe thấy âm thanh có nhịp điệu trên tivi hay điện thoại là bé nhảy theo? Khả năng cảm thụ âm nhạc đã hoạt động hoàn toàn, hãy cùng nhảy với bé!', title_zh = '舞蹈与节奏 🎶', body_zh = '电视或手机里一传出有节奏的声音，宝宝就跳起舞来？音乐感知已经完全启动，和宝宝一起跳吧！' WHERE id = 'f56842a9-3a83-4016-8e93-a096810c45d3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mamá sana, bebé sano 🥑', body_es = 'Tus reservas de hierro y calcio se han agotado. Prepara con Recetas saludables una ensalada rápida y llena de energía que te mantenga en pie.', title_fr = 'Maman en forme, bébé en forme 🥑', body_fr = 'Vos réserves de fer et de calcium sont épuisées. Préparez avec les Recettes saines une salade rapide et pleine d''énergie qui vous tiendra debout.', title_hi = 'सेहतमंद माँ, सेहतमंद बच्चा 🥑', body_hi = 'आपके शरीर में आयरन और कैल्शियम का भंडार खत्म हो गया है। सेहतमंद रेसिपी से जल्दी बनने वाला और आपको ताकत देने वाला ऊर्जा भरा सलाद बनाइए।', title_id = 'Ibu sehat, bayi sehat 🥑', body_id = 'Cadangan zat besi dan kalsium Anda terkuras. Buat salad penuh energi dari Resep Sehat yang cepat dibuat dan membuat Anda tetap bertenaga.', title_ja = '元気なママ、元気な赤ちゃん 🥑', body_ja = '鉄分とカルシウムの蓄えが減っています。「ヘルシーレシピ」から、手早くできて元気を保てるエネルギーたっぷりのサラダをつくりましょう。', title_ko = '건강한 엄마, 건강한 아기 🥑', body_ko = '철분과 칼슘이 바닥났어요. 건강한 레시피에서 빨리 만들 수 있고 든든하게 버티게 해 줄 에너지 가득한 샐러드를 만들어 보세요.', title_nl = 'Gezonde mama, gezonde baby 🥑', body_nl = 'Je ijzer- en calciumvoorraad is op. Maak uit Gezonde recepten een snelle, energierijke salade die je op de been houdt.', title_pl = 'Zdrowa mama, zdrowy maluszek 🥑', body_pl = 'Twoje zapasy żelaza i wapnia się wyczerpały. Przygotuj ze Zdrowych przepisów szybką, pełną energii sałatkę, która postawi cię na nogi.', title_pt = 'Mãe saudável, bebé saudável 🥑', body_pt = 'As suas reservas de ferro e cálcio esgotaram-se. Prepare nas Receitas Saudáveis uma salada rápida e cheia de energia que a mantenha de pé.', title_sv = 'Frisk mamma, friskt barn 🥑', body_sv = 'Dina järn- och kalciumförråd har tömts. Gör en energirik sallad från Hälsosamma recept som både går snabbt att laga och håller dig på benen.', title_vi = 'Mẹ khỏe, bé khỏe 🥑', body_vi = 'Dự trữ sắt và canxi của mẹ đã cạn. Hãy làm một món salad giàu năng lượng, làm nhanh mà giúp mẹ khỏe khoắn từ Công thức lành mạnh.', title_zh = '妈妈健康，宝宝健康 🥑', body_zh = '你体内的铁和钙储备快耗尽了。从健康食谱里做一份快手又能让你撑住的能量沙拉吧。' WHERE id = '357cf8f4-8f26-47ee-9a7b-b3db1bd2898e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El lado divertido de papá 🤡', body_es = 'La mejor forma de hacer reír al bebé es que papá haga ruidos raros. Disfrutad juntos con tu peque de los momentos alegres de esta noche.', title_fr = 'Papa en mode rigolo 🤡', body_fr = 'Le meilleur moyen de faire rire bébé, ce sont les bruits bizarres de papa. Savourez ensemble ces joyeux moments du soir.', title_hi = 'पापा का मज़ेदार अंदाज़ 🤡', body_hi = 'बच्चे को हँसाने का सबसे अच्छा तरीका है पापा की अजीब आवाज़ें। आज शाम के खुशी भरे पलों का बच्चे के साथ मिलकर आनंद लीजिए।', title_id = 'Ayah yang lucu 🤡', body_id = 'Cara terbaik membuat bayi tertawa adalah suara-suara aneh dari ayah. Nikmati momen ceria malam ini bersama si kecil.', title_ja = 'パパのおちゃめな一面 🤡', body_ja = '赤ちゃんを笑わせるいちばんの方法は、パパが変な声を出すこと。今夜の楽しい瞬間を、赤ちゃんと一緒に味わいましょう。', title_ko = '아빠의 유쾌한 모습 🤡', body_ko = '아기를 웃게 하는 가장 좋은 방법은 아빠의 이상한 소리예요. 오늘 저녁의 즐거운 순간을 아이와 함께 마음껏 누리세요.', title_nl = 'Papa de grapjas 🤡', body_nl = 'De beste manier om je baby aan het lachen te krijgen: papa die rare geluiden maakt. Geniet vanavond samen met je kindje van deze vrolijke momenten.', title_pl = 'Zabawny tata 🤡', body_pl = 'Najlepszy sposób, by rozśmieszyć maluszka, to dziwne dźwięki taty. Ciesz się razem z maluszkiem dzisiejszymi wesołymi chwilami.', title_pt = 'O lado divertido do pai 🤡', body_pt = 'A melhor forma de fazer o bebé rir é o pai fazer sons estranhos. Aproveite com o bebé os momentos alegres desta noite.', title_sv = 'Pappas roliga sida 🤡', body_sv = 'Det bästa sättet att få barnet att skratta är när pappa gör konstiga ljud. Njut av kvällens glada stunder tillsammans med barnet.', title_vi = 'Bố vui tính 🤡', body_vi = 'Cách tốt nhất để bé cười là bố tạo ra những âm thanh kỳ lạ. Hãy cùng bé tận hưởng những khoảnh khắc vui vẻ tối nay.', title_zh = '爸爸的搞笑时刻 🤡', body_zh = '逗宝宝笑最好的办法就是爸爸发出怪声。今晚和宝宝一起尽情享受这些欢乐的时刻吧。' WHERE id = '7883fd83-494d-41a3-b42d-58d452de13d7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Paso total a los alimentos troceados! 🍲', body_es = 'Ya puede comer alimentos que hay que masticar. Prueba texturas nuevas con las Recetas para bebés que empiezan con la alimentación complementaria de nuestra app.', title_fr = 'Passage complet aux aliments en petits morceaux ! 🍲', body_fr = 'Il peut déjà manger des aliments qui demandent à mâcher. Essayez de nouvelles textures avec les Recettes pour bébés qui commencent la diversification de l''application.', title_hi = 'बारीक कटे खाने की ओर पूरा बदलाव! 🍲', body_hi = 'अब वह चबाने वाला खाना खा सकता है। ऐप में ऊपरी आहार शुरू करने वाले बच्चों की रेसिपी से नई बनावटें आज़माइए।', title_id = 'Beralih penuh ke makanan cincang! 🍲', body_id = 'Ia sudah bisa makan makanan yang perlu dikunyah. Coba tekstur baru dari Resep untuk bayi yang mulai MPASI di aplikasi kami.', title_ja = '細かく刻んだ食べ物へ完全移行！🍲', body_ja = 'もうかむ必要のある食べ物を食べられます。アプリの「離乳食を始める赤ちゃんのレシピ」で、新しい食感を試してみましょう。', title_ko = '잘게 썬 음식으로 완전히 전환! 🍲', body_ko = '이제 씹어야 하는 음식도 먹을 수 있어요. 앱의 이유식을 시작하는 아기를 위한 레시피에서 새로운 질감을 시도해 보세요.', title_nl = 'Helemaal over op kleingesneden eten! 🍲', body_nl = 'Je baby kan al eten waarop gekauwd moet worden. Probeer nieuwe texturen uit de Recepten voor baby''s die met bijvoeding beginnen in onze app.', title_pl = 'Pełne przejście na drobno krojone jedzenie! 🍲', body_pl = 'Może już jeść pokarmy, które trzeba gryźć. Wypróbuj nowe konsystencje z Przepisów dla maluszków zaczynających rozszerzanie diety w naszej aplikacji.', title_pt = 'Passagem completa aos alimentos picados! 🍲', body_pt = 'Já consegue comer alimentos que exigem mastigação. Experimente texturas novas nas Receitas para bebés em diversificação alimentar da nossa app.', title_sv = 'Helt över till finhackad mat! 🍲', body_sv = 'Barnet kan redan äta mat som behöver tuggas. Prova nya texturer från Recept för barn som börjar med smakportioner i appen.', title_vi = 'Chuyển hẳn sang đồ ăn thái nhỏ! 🍲', body_vi = 'Bé đã ăn được những món cần nhai. Hãy thử những kết cấu mới từ Công thức cho bé bắt đầu ăn dặm trong ứng dụng.', title_zh = '全面过渡到切碎的食物！🍲', body_zh = '宝宝已经能吃需要咀嚼的食物了。在应用里的“辅食宝宝食谱”中试试新的质地吧。' WHERE id = '981d8d60-ab26-4f64-a20b-eee1dc2fed12' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de juego independiente 🧸', body_es = 'Ya puede entretenerse solo con sus juguetes 10-15 minutos. Es señal de que su capacidad de atención aumenta. Vigílale de lejos y disfruta del silencio.', title_fr = 'L''heure du jeu en solo 🧸', body_fr = 'Il peut déjà s''occuper seul avec ses jouets pendant 10-15 minutes. Sa capacité d''attention s''allonge. Surveillez-le de loin et savourez le calme.', title_hi = 'अकेले खेलने का समय 🧸', body_hi = 'अब वह 10-15 मिनट अकेले अपने खिलौनों से खेल सकता है। इसका मतलब है उसका ध्यान टिकने का समय बढ़ रहा है। दूर से नज़र रखिए और खामोशी का आनंद लीजिए।', title_id = 'Waktu bermain mandiri 🧸', body_id = 'Kini ia bisa asyik sendiri dengan mainannya selama 10-15 menit. Ini tanda rentang perhatiannya makin panjang. Awasi dari jauh dan nikmati keheningannya.', title_ja = 'ひとり遊びの時間 🧸', body_ja = 'もう10-15分はひとりでおもちゃに夢中になれます。集中できる時間が長くなっているのです。少し離れて見守りながら、静けさを楽しみましょう。', title_ko = '혼자 노는 시간 🧸', body_ko = '이제 10-15분 동안 혼자 장난감을 가지고 놀 수 있어요. 집중하는 시간이 길어지고 있다는 뜻이에요. 곁에서 지켜보며 고요함을 즐기세요.', title_nl = 'Tijd voor zelfstandig spelen 🧸', body_nl = 'Je baby kan zich al 10-15 minuten alleen met zijn speeltjes vermaken. Zijn concentratie wordt langer. Houd hem van een afstandje in de gaten en geniet van de stilte.', title_pl = 'Czas na samodzielną zabawę 🧸', body_pl = 'Potrafi już przez 10-15 minut sam zająć się zabawkami. To wydłużanie się koncentracji. Pilnuj go z boku i delektuj się ciszą.', title_pt = 'Hora de brincar sozinho 🧸', body_pt = 'Já consegue entreter-se sozinho com os brinquedos durante 10-15 minutos. É a capacidade de concentração a aumentar. Vigie-o de longe e aproveite o silêncio.', title_sv = 'Stund för egen lek 🧸', body_sv = 'Barnet kan nu sysselsätta sig med sina leksaker själv i 10-15 minuter. Det betyder att koncentrationsförmågan blir längre. Håll uppsikt på avstånd och njut av tystnaden.', title_vi = 'Giờ chơi một mình 🧸', body_vi = 'Bé đã có thể tự chơi với đồ chơi trong 10-15 phút. Đây là dấu hiệu khả năng tập trung đang kéo dài. Hãy quan sát từ xa và tận hưởng sự yên tĩnh.', title_zh = '独立玩耍时间 🧸', body_zh = '宝宝已经能自己玩玩具10-15分钟了。这说明注意力在延长。在一旁看着，享受这份安静吧。' WHERE id = '74f02405-1cdd-401e-bb47-01d87997f231' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Tienes una pregunta? 🤖', body_es = '¿Te lías con dudas sobre el sueño, la alimentación o los gases? No pierdas tiempo en foros: escribe a Anacan AI y recibe una respuesta concreta y científica.', title_fr = 'Une question ? 🤖', body_fr = 'Sommeil, repas ou gaz, vous ne savez plus où donner de la tête ? Ne perdez pas de temps sur les forums : écrivez simplement à Anacan AI et obtenez une réponse scientifique précise.', title_hi = 'कोई सवाल है? 🤖', body_hi = 'नींद, फ़ीडिंग या गैस को लेकर उलझन में हैं? फ़ोरम में समय मत गँवाइए, बस Anacan AI को लिखिए और ठोस वैज्ञानिक जवाब पाइए।', title_id = 'Ada pertanyaan? 🤖', body_id = 'Bingung soal tidur, menyusui, atau perut kembung? Jangan buang waktu di forum, tanyakan saja ke Anacan AI dan dapatkan jawaban ilmiah yang jelas.', title_ja = '質問はありますか？🤖', body_ja = '睡眠、授乳、それともガスのことで頭がいっぱい？掲示板で時間をむだにせず、Anacan AIに聞いて、科学的な答えを受け取りましょう。', title_ko = '궁금한 게 있나요? 🤖', body_ko = '수면, 수유, 가스 때문에 머릿속이 복잡한가요? 커뮤니티 글을 뒤지느라 시간 낭비하지 말고 Anacan AI에게 물어 명확하고 과학적인 답을 받아 보세요.', title_nl = 'Heb je een vraag? 🤖', body_nl = 'Duizelt het je van vragen over slaap, voeding of krampjes? Verlies geen tijd op forums, schrijf gewoon naar Anacan AI en krijg een concreet, wetenschappelijk antwoord.', title_pl = 'Masz pytanie? 🤖', body_pl = 'Sen, karmienie czy kolki mieszają ci w głowie? Nie trać czasu na forach, po prostu napisz do Anacan AI i dostań konkretną, naukową odpowiedź.', title_pt = 'Tem uma dúvida? 🤖', body_pt = 'Sono, alimentação ou gases deixam-na baralhada? Não perca tempo em fóruns, escreva ao Anacan AI e receba uma resposta científica e concreta.', title_sv = 'Har du en fråga? 🤖', body_sv = 'Snurrar det i huvudet kring sömn, mat eller gaser? Slösa inte tid på forum, skriv bara till Anacan AI och få ett konkret, vetenskapligt svar.', title_vi = 'Mẹ có câu hỏi? 🤖', body_vi = 'Rối bời chuyện ngủ, ăn hay đầy hơi? Đừng mất thời gian trên các diễn đàn, chỉ cần hỏi Anacan AI để nhận câu trả lời khoa học, cụ thể.', title_zh = '有问题吗？🤖', body_zh = '睡眠、喂养还是胀气，让你一头雾水？别在论坛里浪费时间，直接问Anacan AI，获得明确的科学解答。' WHERE id = 'e8181dea-ccff-4ba2-ae33-93fa07ea8c28' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Parque o casa? ⛅', body_es = 'Quieres salir, pero hace viento. Deja que el asistente Tiempo y ropa te diga no solo la temperatura, sino también qué ponerle para que no le pase el viento.', title_fr = 'Parc ou maison ? ⛅', body_fr = 'Vous voulez sortir, mais il y a du vent ? L''assistant Météo et tenue vous indique non seulement la température, mais aussi quoi lui mettre pour le protéger du vent.', title_hi = 'पार्क या घर? ⛅', body_hi = 'बाहर जाना चाहती हैं, पर हवा चल रही है। मौसम और कपड़े टूल आपको सिर्फ़ तापमान ही नहीं, यह भी बताएगा कि हवा से बचाने वाले कौन से कपड़े पहनाएँ।', title_id = 'Taman atau rumah? ⛅', body_id = 'Ingin keluar, tapi berangin? Biarkan asisten Cuaca dan Pakaian memberi tahu bukan hanya suhunya, tapi juga pakaian tahan angin yang perlu dipakai.', title_ja = '公園？それともおうち？⛅', body_ja = '外に出たいけれど、風がある。「天気と服装」アシスタントが、気温だけでなく風を通さない服装まで教えてくれます。', title_ko = '공원일까요, 집일까요? ⛅', body_ko = '나가고 싶은데 바람이 부나요? 날씨와 옷차림 도우미가 기온뿐 아니라 바람을 막아 줄 옷차림까지 알려 줄 거예요.', title_nl = 'Park of thuis? ⛅', body_nl = 'Wil je naar buiten, maar waait het? Laat de assistent Weer en kleding je niet alleen de temperatuur vertellen, maar ook wat je baby aan moet tegen de wind.', title_pl = 'Park czy dom? ⛅', body_pl = 'Chcesz wyjść, ale wieje? Niech pomocnik Pogoda i ubiór powie ci nie tylko, jaka jest temperatura, ale też w co go ubrać, żeby nie przewiało.', title_pt = 'Parque ou casa? ⛅', body_pt = 'Quer sair, mas está vento? Deixe o assistente Tempo e Roupa dizer-lhe não só a temperatura, mas também que roupa corta-vento lhe deve vestir.', title_sv = 'Park eller hemma? ⛅', body_sv = 'Vill ni gå ut, men det blåser? Låt Väder och kläder inte bara berätta temperaturen, utan också vilka vindtäta kläder barnet ska ha.', title_vi = 'Công viên hay ở nhà? ⛅', body_vi = 'Mẹ muốn ra ngoài nhưng trời có gió? Hãy để Trợ lý thời tiết và trang phục không chỉ cho biết nhiệt độ mà còn gợi ý nên mặc gì để chắn gió cho bé.', title_zh = '去公园还是待在家？⛅', body_zh = '想出门，可是外面有风？让天气穿衣助手不仅告诉你温度，还告诉你该给宝宝穿什么防风的衣服。' WHERE id = '8d91b32b-a0f2-4a07-a181-da0b746268bc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Noches difíciles 🥱', body_es = '¿Se resiste con todas sus fuerzas a dormirse? Vuelve a revisar sus siestas de día y la rutina.', title_fr = 'Des nuits difficiles 🥱', body_fr = 'Il résiste de toutes ses forces pour ne pas s''endormir ? Revoyez ses siestes et sa routine.', title_hi = 'ज़िद्दी रातें 🥱', body_hi = 'सोने से बचने के लिए पूरी ताकत से विरोध करता है? दिन की झपकियाँ और रूटीन फिर से जाँचिए।', title_id = 'Malam-malam yang alot 🥱', body_id = 'Ia melawan sekuat tenaga agar tidak tertidur? Periksa kembali tidur siang dan rutinitasnya.', title_ja = '手ごわい夜 🥱', body_ja = '眠るまいと全力で抵抗していますか？お昼寝とルーティンをもう一度見直しましょう。', title_ko = '고집스러운 밤 🥱', body_ko = '잠들지 않으려고 온 힘을 다해 버티나요? 낮잠과 루틴을 다시 점검해 보세요.', title_nl = 'Koppige nachten 🥱', body_nl = 'Verzet je baby zich met alle macht tegen het slapengaan? Bekijk de dutjes overdag en de routine opnieuw.', title_pl = 'Uparte noce 🥱', body_pl = 'Z całych sił opiera się zasypianiu? Jeszcze raz sprawdź drzemki w ciągu dnia i rutynę.', title_pt = 'Noites teimosas 🥱', body_pt = 'Resiste com todas as forças a adormecer? Volte a rever as sestas do dia e a rotina.', title_sv = 'Envisa nätter 🥱', body_sv = 'Kämpar barnet emot med all kraft för att inte somna? Se över dagsluren och rutinen igen.', title_vi = 'Những đêm bướng bỉnh 🥱', body_vi = 'Bé dồn hết sức để chống lại giấc ngủ? Hãy xem lại các giấc ngủ ngày và nếp sinh hoạt của bé.', title_zh = '倔强的夜晚 🥱', body_zh = '宝宝用尽全力抗拒睡觉？重新检查一下白天小睡和作息吧。' WHERE id = '9890a3bf-dcd7-4d43-8ef7-e98ca087bf8e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Grandes emociones, cuerpo pequeño 🛑', body_es = '¿Cuando no consigue lo que quiere se tira al suelo o llora? Todavía no sabe gestionar sus emociones. Agáchate a su altura, háblale con calma y superad juntos la crisis.', title_fr = 'De grandes émotions dans un petit corps 🛑', body_fr = 'Quand il n''obtient pas ce qu''il veut, il se jette par terre ou pleure ? Il ne sait pas encore gérer ses émotions. Mettez-vous à sa hauteur et parlez-lui calmement pour passer ces crises.', title_hi = 'बड़ी भावनाएँ, छोटा शरीर 🛑', body_hi = 'मनचाहा न होने पर ज़मीन पर लोटता है या रोता है? वह अपनी भावनाएँ संभाल नहीं पाता। उसकी ऊँचाई तक झुककर शांति से बात कीजिए और इन दौरों से पार पाइए।', title_id = 'Emosi besar, tubuh kecil 🛑', body_id = 'Ia menjatuhkan diri ke lantai atau menangis saat keinginannya tak dituruti? Ia belum bisa mengelola perasaannya. Bungkukkan badan sejajar dengannya dan bicaralah dengan tenang untuk melewati dramanya.', title_ja = '大きな気持ち、小さな体 🛑', body_ja = '思いどおりにならないと、床にひっくり返ったり泣いたりしますか？まだ気持ちをコントロールできないのです。同じ目の高さまでかがんで、静かに話しかけてかんしゃくを乗り切りましょう。', title_ko = '큰 감정, 작은 몸 🛑', body_ko = '원하는 걸 얻지 못하면 바닥에 드러눕거나 우나요? 아직 감정을 다스리지 못해서예요. 아기 눈높이로 몸을 낮추고 차분히 이야기하며 떼쓰기를 넘겨 보세요.', title_nl = 'Grote gevoelens, klein lijfje 🛑', body_nl = 'Gooit je baby zich op de grond of huilt hij als hij zijn zin niet krijgt? Hij kan zijn gevoelens nog niet beheersen. Ga op zijn hoogte zitten en kom de buien door rustig te praten.', title_pl = 'Wielkie emocje, małe ciałko 🛑', body_pl = 'Gdy nie dostaje tego, czego chce, rzuca się na podłogę albo płacze? Nie umie jeszcze panować nad emocjami. Zniż się do jego poziomu i spokojnie z nim rozmawiaj, by przejść przez kryzys.', title_pt = 'Grandes emoções, corpo pequenino 🛑', body_pt = 'Quando não lhe fazem a vontade, atira-se ao chão ou chora? Ainda não consegue controlar as emoções. Baixe-se ao nível dele e fale com calma para ultrapassar as crises.', title_sv = 'Stora känslor, liten kropp 🛑', body_sv = 'Kastar sig barnet på golvet eller gråter när det inte får som det vill? Det kan inte hantera sina känslor. Böj dig ner till barnets nivå och prata lugnt för att ta er förbi utbrotten.', title_vi = 'Cảm xúc lớn, cơ thể nhỏ 🛑', body_vi = 'Không được như ý, bé lăn ra sàn hay khóc? Bé chưa biết kiểm soát cảm xúc. Hãy cúi xuống ngang tầm bé, nói chuyện nhẹ nhàng để giúp bé vượt qua những cơn quấy.', title_zh = '大情绪，小身体 🛑', body_zh = '得不到想要的东西就往地上一躺或者大哭？宝宝还不会控制情绪。蹲到和宝宝一样的高度，平静地和宝宝说话，帮宝宝度过这些崩溃时刻吧。' WHERE id = '395ddd9b-9009-4fec-ba6f-816d156ad432' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se ha despertado gritando de repente? 😭', body_es = 'Pueden ser terrores nocturnos. Usa el Análisis del llanto y averigua si el problema es físico o psicológico.', title_fr = 'Il s''est réveillé en hurlant d''un coup ? 😭', body_fr = 'C''est peut-être une terreur nocturne. Faites écouter ses pleurs à l''Analyse des pleurs pour savoir si le problème est physique ou psychologique.', title_hi = 'अचानक चीखकर जागा? 😭', body_hi = 'यह नींद का डर (नाइट टेरर) हो सकता है। क्राइंग एनालिसिस से उसकी आवाज़ सुनवाइए और पता कीजिए कि समस्या शारीरिक है या मानसिक।', title_id = 'Terbangun mendadak sambil menjerit? 😭', body_id = 'Mungkin ini teror tidur. Perdengarkan tangisannya ke Analisis Tangisan dan pastikan apakah masalahnya fisik atau psikologis.', title_ja = '突然叫んで起きた？😭', body_ja = '夜驚症かもしれません。「泣き声分析」に泣き声を聞かせて、原因が体なのか心なのかを確かめましょう。', title_ko = '갑자기 비명을 지르며 깼나요? 😭', body_ko = '야경증일 수 있어요. 울음 분석으로 소리를 들려주고 신체적인 문제인지 심리적인 문제인지 확인해 보세요.', title_nl = 'Ineens schreeuwend wakker? 😭', body_nl = 'Het kan een nachtmerrie zijn. Laat Huilanalyse luisteren en ontdek of het probleem lichamelijk of psychisch is.', title_pl = 'Nagle budzi się z krzykiem? 😭', body_pl = 'To może być lęk nocny. Pozwól Analizie płaczu posłuchać dźwięku i ustal, czy problem jest fizyczny, czy psychiczny.', title_pt = 'Acordou de repente aos gritos? 😭', body_pt = 'Pode ser um terror noturno. Ponha a Análise do Choro a ouvir e confirme se o problema é físico ou psicológico.', title_sv = 'Vaknade barnet plötsligt skrikande? 😭', body_sv = 'Det kan vara nattskräck. Låt Gråtanalys lyssna på ljudet och ta reda på om problemet är fysiskt eller psykiskt.', title_vi = 'Bé bỗng thét lên rồi tỉnh giấc? 😭', body_vi = 'Có thể đó là chứng hoảng sợ khi ngủ. Hãy cho Phân tích tiếng khóc nghe để biết chắc vấn đề là thể chất hay tâm lý.', title_zh = '突然尖叫着醒来？😭', body_zh = '可能是夜惊。用哭声分析听一听，弄清楚问题是身体上的还是心理上的。' WHERE id = 'd824145b-4905-49d1-9f4f-46ade8a730f8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡El significado del «no»! 🛑', body_es = '¿Cuando hace algo que no debe, ya mira cómo reaccionas? Consulta con Anacan AI los primeros pasos de la disciplina.', title_fr = 'Le sens du mot « non » ! 🛑', body_fr = 'Quand il fait quelque chose d''interdit, il regarde déjà votre réaction ? Demandez conseil à Anacan AI sur les premiers pas de la discipline.', title_hi = '''ना'' का मतलब! 🛑', body_hi = 'जो नहीं करना चाहिए, वह करते समय अब आपकी प्रतिक्रिया देखता है? अनुशासन के पहले कदमों के बारे में Anacan AI से सलाह लीजिए।', title_id = 'Arti kata "tidak"! 🛑', body_id = 'Saat melakukan sesuatu yang tidak boleh, kini ia melihat reaksi Anda? Konsultasikan langkah pertama disiplin dengan Anacan AI.', title_ja = '「ダメ」の意味！🛑', body_ja = 'してはいけないことをするとき、もうあなたの反応をうかがっていますか？しつけの最初の一歩について、Anacan AIに相談してみましょう。', title_ko = '''안 돼''라는 말의 의미! 🛑', body_ko = '하면 안 되는 일을 할 때 이제 엄마의 반응을 살피나요? 훈육의 첫걸음에 대해 Anacan AI와 상담해 보세요.', title_nl = 'De betekenis van nee! 🛑', body_nl = 'Kijkt je baby al naar je reactie als hij iets doet wat niet mag? Vraag Anacan AI om advies over de eerste stappen in opvoeden met grenzen.', title_pl = 'Znaczenie słowa „nie”! 🛑', body_pl = 'Gdy robi coś, czego nie powinien, już patrzy na twoją reakcję? Porozmawiaj z Anacan AI o pierwszych krokach w wyznaczaniu granic.', title_pt = 'O significado da palavra "não"! 🛑', body_pt = 'Quando faz algo que não deve, já olha para a sua reação? Aconselhe-se com o Anacan AI sobre os primeiros passos da disciplina.', title_sv = 'Vad ordet nej betyder! 🛑', body_sv = 'Tittar barnet redan efter din reaktion när det gör något det inte får? Rådfråga Anacan AI om de första stegen i att sätta gränser.', title_vi = 'Ý nghĩa của chữ "Không"! 🛑', body_vi = 'Khi làm điều không nên làm, bé đã biết nhìn phản ứng của mẹ? Hãy hỏi ý kiến Anacan AI về những bước đầu tiên trong việc dạy bé kỷ luật.', title_zh = '“不”的意思！🛑', body_zh = '宝宝做了不该做的事时，已经会看你的反应了？和Anacan AI聊聊管教的第一步吧。' WHERE id = 'a7923459-9b74-4330-949d-00e94d185768' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora del masaje 💆‍♂️', body_es = 'Cuando tu bebé se duerma, organizad una sesión de masaje de hombros tu pareja y tú para soltar el estrés del día. ¡Sois un equipo!', title_fr = 'L''heure du massage 💆‍♂️', body_fr = 'Quand bébé dort, organisez une séance de massage des épaules avec votre conjoint pour évacuer le stress de la journée. Vous êtes une équipe !', title_hi = 'मालिश का समय 💆‍♂️', body_hi = 'बच्चे के सोने के बाद दिन का तनाव उतारने के लिए अपने साथी के साथ कंधे की मालिश का सेशन रखिए। आप एक टीम हैं!', title_id = 'Waktu pijat 💆‍♂️', body_id = 'Setelah si kecil tidur, adakan sesi pijat bahu bersama pasangan untuk melepas stres hari ini. Kalian satu tim!', title_ja = 'マッサージタイム 💆‍♂️', body_ja = '赤ちゃんが寝たら、1日のストレスを流すためにパートナーと肩もみタイムをつくりましょう。あなたたちはチームです！', title_ko = '마사지 시간 💆‍♂️', body_ko = '아이가 잠든 뒤 배우자와 함께 어깨 마사지 시간을 가지며 하루의 스트레스를 풀어 보세요. 두 사람은 한 팀이에요!', title_nl = 'Tijd voor een massage 💆‍♂️', body_nl = 'Plan als je baby slaapt een schoudermassage met je partner om de stress van de dag kwijt te raken. Jullie zijn een team!', title_pl = 'Czas na masaż 💆‍♂️', body_pl = 'Gdy maluszek zaśnie, zróbcie sobie z partnerem sesję masażu ramion, by zrzucić stres całego dnia. Jesteście drużyną!', title_pt = 'Hora da massagem 💆‍♂️', body_pt = 'Depois de o bebé adormecer, organize com o seu companheiro uma sessão de massagem aos ombros para libertar o stress do dia. São uma equipa!', title_sv = 'Massagedags 💆‍♂️', body_sv = 'När barnet har somnat, ordna en stund med axelmassage tillsammans med din partner för att släppa dagens stress. Ni är ett lag!', title_vi = 'Giờ mát-xa 💆‍♂️', body_vi = 'Sau khi bé ngủ, hãy cùng bố mát-xa vai cho nhau để xua tan căng thẳng trong ngày. Bố mẹ là một đội!', title_zh = '按摩时间 💆‍♂️', body_zh = '宝宝睡着后，和伴侣一起来一场肩部按摩，释放一天的压力。你们是一个团队！' WHERE id = 'ec1173c9-8c5f-4b55-8ebd-5fdf69b08da1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Seguridad en casa! 🛡', body_es = '️ Cuanto más se mueve con libertad, más peligros hay. No dejes de mirar nuestra lista de Productos recomendados para cierres de seguridad y barreras de escalera.', title_fr = 'Sécurité à la maison ! 🛡', body_fr = '️Plus il se déplace librement, plus les dangers augmentent. Consultez absolument notre liste de Produits recommandés pour les bloque-portes et barrières d''escalier.', title_hi = 'घर में सुरक्षा के उपाय! 🛡', body_hi = '️वह जितना आज़ादी से चलेगा, खतरे उतने बढ़ेंगे। चाइल्ड लॉक और सीढ़ियों के गेट के लिए हमारी सुझाए गए प्रोडक्ट की सूची ज़रूर देखिए।', title_id = 'Keamanan di rumah! 🛡', body_id = '️ Makin bebas ia berjalan, makin banyak pula bahayanya. Pastikan melihat daftar Produk Rekomendasi kami untuk kunci pengaman anak dan pagar tangga.', title_ja = 'おうちの安全対策！🛡', body_ja = '️ 自由に歩きはじめると、危険も増えます。チャイルドロックやベビーゲートは、「おすすめ商品」リストをぜひチェックしましょう。', title_ko = '집 안 안전 대책! 🛡', body_ko = '️ 아기가 자유롭게 돌아다닐수록 위험도 늘어나요. 안전 잠금장치와 계단 안전문은 추천 제품 목록에서 꼭 확인하세요.', title_nl = 'Veiligheid in huis! 🛡', body_nl = '️ Hoe meer je baby vrij gaat lopen, hoe meer gevaren er zijn. Bekijk zeker in onze Aanbevolen producten kinderslotjes en traphekjes.', title_pl = 'Bezpieczeństwo w domu! 🛡', body_pl = '️ Im swobodniej zaczyna się poruszać, tym więcej zagrożeń. Koniecznie zajrzyj na naszą listę Polecanych produktów po blokady dla dzieci i bramki na schody.', title_pt = 'Segurança em casa! 🛡', body_pt = '️ Quanto mais anda à vontade, maiores são os perigos. Veja sem falta na nossa lista de Produtos Recomendados os fechos de segurança e os portões para escadas.', title_sv = 'Säkerhet i hemmet! 🛡', body_sv = '️ Ju mer barnet börjar gå fritt, desto fler faror. Kika absolut i vår lista Rekommenderade produkter efter barnlås och trappgrindar.', title_vi = 'Biện pháp an toàn trong nhà! 🛡', body_vi = '️ Bé càng đi lại tự do thì nguy hiểm càng tăng. Nhất định hãy xem danh sách Sản phẩm gợi ý để tìm khóa an toàn và cổng chắn cầu thang cho trẻ.', title_zh = '居家安全措施！🛡', body_zh = '️ 宝宝开始自由走动，危险也随之增加。一定要去推荐商品清单里看看儿童安全锁和楼梯门栏。' WHERE id = '510bccc7-40fa-4c0b-8d0b-8a3105fd00ea' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Después de la toma de la noche, pasa a papá el turno de leer el cuento y dormir al bebé, y tú échate una cabezadita.', body_fr = 'Après le repas du soir, confiez à papa la lecture et le coucher, et vous, faites une petite sieste.', body_hi = 'शाम की फ़ीडिंग के बाद किताब पढ़ने और सुलाने की बारी पापा को दीजिए, और आप थोड़ी झपकी ले लीजिए।', body_id = 'Setelah makan malam, serahkan giliran membaca buku dan menidurkan kepada ayah, sementara Anda tidur sejenak.', body_ja = '夜の授乳のあとは、絵本の読み聞かせと寝かしつけをパパにバトンタッチして、あなたは少しうとうとしましょう。', body_ko = '저녁 수유 후 책 읽기와 재우기 당번은 아빠에게 넘기고, 엄마는 잠깐 눈을 붙이세요.', body_nl = 'Geef na de avondvoeding de beurt voor voorlezen en in slaap brengen aan papa, en doe jij even een dutje.', body_pl = 'Po wieczornym karmieniu przekaż tacie czytanie i usypianie, a ty się zdrzemnij.', body_pt = 'Depois da refeição da noite, passe ao pai o turno de ler o livro e adormecer o bebé, e faça uma pequena sesta.', body_sv = 'Efter kvällsmatningen, lämna över bokläsningen och nattningen till pappa och ta en kort tupplur själv.', body_vi = 'Sau cữ ăn buổi tối, hãy giao việc đọc sách và ru ngủ cho bố, còn mẹ chợp mắt một chút nhé.', body_zh = '晚上喂完奶后，把读书和哄睡的班交给爸爸，你去小睡一会儿吧。' WHERE id = '959729c5-8ab6-4053-99ca-82aa5fdabc7e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Lo señala todo con el dedo índice! ☝', body_es = '️ En vez de decir «¿qué es eso?», lo señala todo con el dedo. Inmortaliza esta curiosidad en el Álbum del bebé.', title_fr = 'Il montre tout du doigt ! ☝', body_fr = '️Au lieu de dire « C''est quoi ? », il montre tout du doigt. Immortalisez cette curiosité dans l''Album de bébé.', title_hi = 'हर चीज़ तर्जनी से दिखाता है! ☝', body_hi = '️''वह क्या है?'' कहने के बजाय हर चीज़ उँगली से दिखाता है। उसकी इस जिज्ञासा को बेबी एल्बम में हमेशा के लिए सहेजिए।', title_id = 'Ia menunjuk semuanya dengan jari telunjuk! ☝', body_id = '️ Bukannya bertanya "Apa itu?", ia menunjuk semuanya dengan jari. Abadikan rasa ingin tahunya ini di Album Bayi.', title_ja = 'なんでも人さし指でさすよ！☝', body_ja = '️ 「あれなに？」と言う代わりに、なんでも指でさしています。この好奇心いっぱいの時期を「ベビーアルバム」に残しましょう。', title_ko = '검지로 모든 걸 가리켜요! ☝', body_ko = '️ ''저게 뭐야?''라고 말하는 대신 모든 걸 손가락으로 가리켜요. 이 호기심을 아기 앨범에 영원히 남기세요.', title_nl = 'Hij wijst alles aan met zijn wijsvinger! ☝', body_nl = '️ In plaats van ''wat is dat?'' te zeggen, wijst hij alles aan met zijn vinger. Leg deze nieuwsgierigheid vast in het Babyalbum.', title_pl = 'Wszystko pokazuje palcem wskazującym! ☝', body_pl = '️ Zamiast pytać „co to jest?”, pokazuje wszystko palcem. Uwiecznij tę ciekawość w Albumie dziecka.', title_pt = 'Aponta tudo com o dedo indicador! ☝', body_pt = '️ Em vez de dizer "o que é isto?", aponta tudo com o dedo. Eternize esta curiosidade no Álbum do Bebé.', title_sv = 'Pekar på allt med pekfingret! ☝', body_sv = '️ I stället för att säga ''vad är det?'' pekar barnet på allt med fingret. Förevig den här nyfikenheten i Babyalbumet.', title_vi = 'Bé chỉ mọi thứ bằng ngón trỏ! ☝', body_vi = '️ Thay vì hỏi "Cái gì đây?", bé chỉ tay vào mọi thứ. Hãy lưu giữ sự tò mò này của bé trong Album của bé.', title_zh = '什么都用食指指！☝', body_zh = '️ 宝宝不说“那是什么？”，而是什么都用手指去指。在宝宝相册里永久留下宝宝的这份好奇吧。' WHERE id = 'a478b2eb-eaec-4b54-813a-6f2ba55a5d14' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Control de los ruidos 🤫', body_es = 'La primera media hora después de dormirse es el momento más delicado. Comprueba el ambiente con el Medidor de sonido y evita los ruidos repentinos.', title_fr = 'Maîtriser les bruits 🤫', body_fr = 'La première demi-heure après l''endormissement est le moment le plus sensible. Vérifiez l''ambiance avec le Sonomètre et méfiez-vous des bruits soudains.', title_hi = 'आवाज़ों पर काबू 🤫', body_hi = 'सोने के बाद का पहला आधा घंटा सबसे नाज़ुक समय है। साउंड मीटर से माहौल जाँचिए और अचानक शोर से बचिए।', title_id = 'Mengatur suara 🤫', body_id = 'Setengah jam pertama setelah tertidur adalah waktu paling sensitif. Cek suasana dengan Pengukur Suara dan hindari suara bising mendadak.', title_ja = '音のコントロール 🤫', body_ja = '寝ついてから最初の30分は、いちばん眠りが浅い時間です。「サウンドメーター」で環境をチェックして、急な物音に気をつけましょう。', title_ko = '소리 관리 🤫', body_ko = '잠든 직후 처음 30분이 가장 예민한 시간이에요. 소음 측정기로 환경을 확인하고 갑작스러운 소음을 조심하세요.', title_nl = 'Geluiden onder controle 🤫', body_nl = 'Het eerste halfuur na het inslapen is het gevoeligst. Controleer de omgeving met de Geluidsmeter en pas op voor plotseling lawaai.', title_pl = 'Kontrola dźwięków 🤫', body_pl = 'Pierwsze pół godziny po zaśnięciu to najwrażliwszy czas. Sprawdź otoczenie Miernikiem dźwięku i uważaj na nagły hałas.', title_pt = 'Controlo dos sons 🤫', body_pt = 'A primeira meia hora depois de adormecer é a altura mais sensível. Verifique o ambiente com o Medidor de Som e cuidado com barulhos súbitos.', title_sv = 'Ljudkoll 🤫', body_sv = 'Den första halvtimmen efter att barnet har somnat är den känsligaste. Kolla miljön med Ljudmätaren och akta dig för plötsligt oväsen.', title_vi = 'Kiểm soát âm thanh 🤫', body_vi = 'Nửa tiếng đầu sau khi bé ngủ là lúc nhạy cảm nhất. Hãy kiểm tra môi trường bằng Đo âm thanh và cẩn thận với tiếng ồn đột ngột.', title_zh = '控制声音 🤫', body_zh = '入睡后的头半小时是最敏感的时候。用噪音测量检查环境，小心突然的噪音。' WHERE id = '97023662-0ba2-4bcd-aff7-bc7adf5883ba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Limpiar o descansar? 🛋️', body_es = 'Cuando tu bebé duerma, no corras al lavavajillas. Túmbate en el sofá, cierra los ojos y simplemente respira durante 15 minutos.', title_fr = 'Ménage ou repos ? 🛋️', body_fr = 'Quand bébé dort, ne courez pas vers le lave-vaisselle. Allongez-vous sur le canapé, fermez les yeux et respirez simplement pendant 15 minutes.', title_hi = 'सफ़ाई या आराम? 🛋️', body_hi = 'बच्चे के सोते ही डिशवॉशर की ओर मत भागिए। सोफ़े पर लेट जाइए, आँखें बंद कीजिए और 15 मिनट बस साँस लीजिए।', title_id = 'Bersih-bersih atau istirahat? 🛋️', body_id = 'Saat si kecil tidur, jangan buru-buru ke mesin cuci piring. Berbaringlah di sofa, pejamkan mata, dan cukup bernapas selama 15 menit.', title_ja = 'お掃除？それとも休憩？🛋️', body_ja = '赤ちゃんが寝ても、食洗機に走らないで。ソファに横になって目を閉じ、15分間ただ呼吸しましょう。', title_ko = '청소할까요, 쉴까요? 🛋️', body_ko = '아이가 잘 때 식기세척기로 달려가지 마세요. 소파에 누워 눈을 감고 15분 동안 숨만 쉬세요.', title_nl = 'Schoonmaken of uitrusten? 🛋️', body_nl = 'Ren niet naar de vaatwasser als je baby slaapt. Ga op de bank liggen, sluit je ogen en adem 15 minuten gewoon.', title_pl = 'Sprzątać czy odpocząć? 🛋️', body_pl = 'Gdy maluszek śpi, nie biegnij do zmywarki. Połóż się na kanapie, zamknij oczy i przez 15 minut po prostu oddychaj.', title_pt = 'Limpar ou descansar? 🛋️', body_pt = 'Quando o bebé dorme, não corra para a máquina da loiça. Deite-se no sofá, feche os olhos e simplesmente respire durante 15 minutos.', title_sv = 'Städa eller vila? 🛋️', body_sv = 'Rusa inte till diskmaskinen när barnet sover. Lägg dig i soffan, blunda och bara andas i 15 minuter.', title_vi = 'Dọn dẹp hay nghỉ ngơi? 🛋️', body_vi = 'Bé vừa ngủ thì đừng vội lao đến máy rửa bát. Hãy nằm xuống sofa, nhắm mắt lại và chỉ hít thở trong 15 phút.', title_zh = '打扫还是休息？🛋️', body_zh = '宝宝睡着时别急着去洗碗机那边。躺在沙发上，闭上眼睛，呼吸15分钟就好。' WHERE id = 'd02f135b-16bc-4fa9-978f-0e7d992c1ba4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Construye castillos con bloques 🧱', body_es = 'Intenta poner dos o tres cubos de juguete uno encima de otro. Observa en silencio sus pequeños intentos de ingeniería y aplaude.', title_fr = 'Il construit un château avec des cubes 🧱', body_fr = 'Il essaie d''empiler deux ou trois cubes. Observez en silence ses petits essais d''ingénieur et applaudissez-le.', title_hi = 'ब्लॉक से किला बनाता है 🧱', body_hi = 'दो या तीन खिलौना ब्लॉक एक के ऊपर एक रखने की कोशिश करता है। उसकी इन छोटी-छोटी इंजीनियरिंग कोशिशों को चुपचाप देखिए और तालियाँ बजाइए।', title_id = 'Membangun istana dari balok 🧱', body_id = 'Ia mencoba menumpuk dua atau tiga balok mainan. Saksikan usaha insinyur kecil ini dengan diam-diam, lalu beri tepuk tangan.', title_ja = '積み木でお城づくり 🧱', body_ja = '積み木を2つか3つ重ねようと挑戦しています。この小さなエンジニアの挑戦を静かに見守って、拍手を送りましょう。', title_ko = '블록으로 성을 쌓아요 🧱', body_ko = '블록 두세 개를 쌓아 올리려 해요. 이 꼬마 엔지니어의 도전을 조용히 지켜보며 박수를 보내 주세요.', title_nl = 'Hij bouwt een kasteel van blokken 🧱', body_nl = 'Je baby probeert twee of drie blokken op elkaar te zetten. Kijk stil naar deze kleine bouwpogingen en applaudisseer.', title_pl = 'Buduje zamek z klocków 🧱', body_pl = 'Próbuje postawić na sobie dwa lub trzy klocki. Obserwuj w ciszy te małe inżynierskie próby i bij brawo.', title_pt = 'Constrói castelos com blocos 🧱', body_pt = 'Tenta pôr dois ou três cubos uns em cima dos outros. Acompanhe em silêncio estas pequenas tentativas de engenharia e aplauda-o.', title_sv = 'Bygger slott av klossar 🧱', body_sv = 'Barnet försöker stapla två eller tre leksaksklossar på varandra. Följ de här små ingenjörsförsöken i tystnad och applådera.', title_vi = 'Xây lâu đài bằng khối gỗ 🧱', body_vi = 'Bé thử xếp hai, ba khối đồ chơi chồng lên nhau. Hãy lặng lẽ ngắm và vỗ tay cho những nỗ lực "kỹ sư" nhỏ bé này.', title_zh = '用积木搭城堡 🧱', body_zh = '宝宝在尝试把两三块积木叠起来。默默地看着这些小小的工程尝试，为宝宝鼓掌吧。' WHERE id = 'f12c7751-b89f-4d12-a843-8e331c338393' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Responde con el lenguaje corporal 🗣️', body_es = 'Cuando le dices «¿nos vamos?», levanta los brazos, o cuando dices «no», mueve la cabeza. Su capacidad de comprensión ha crecido muchísimo.', title_fr = 'Il répond avec son corps 🗣️', body_fr = 'Quand vous dites « On y va ? », il lève les bras, ou il secoue la tête pour dire « non ». Sa compréhension a fait un bond incroyable.', title_hi = 'हाव-भाव से जवाब 🗣️', body_hi = '''चलें?'' कहने पर बाँहें उठाता है या ''ना'' कहने पर सिर हिलाता है। उसकी समझने की क्षमता कमाल की बढ़ गई है।', title_id = 'Menjawab dengan bahasa tubuh 🗣️', body_id = 'Saat Anda bertanya "Ayo pergi?", ia mengangkat tangannya, atau menggeleng saat berkata "Tidak". Daya pahamnya meningkat luar biasa.', title_ja = '体で答える 🗣️', body_ja = '「行こうか？」と言うと両手を上げ、「ダメ」と言うと首を振ります。理解する力が驚くほど伸びています。', title_ko = '몸짓으로 대답해요 🗣️', body_ko = '''갈까?'' 하면 팔을 들고, ''안 돼'' 하면 고개를 저어요. 이해력이 놀랍도록 자랐어요.', title_nl = 'Antwoorden met lichaamstaal 🗣️', body_nl = 'Steekt je baby zijn armpjes omhoog als je zegt: zullen we gaan? Of schudt hij zijn hoofd als hij nee bedoelt? Zijn begrip is ongelofelijk gegroeid.', title_pl = 'Odpowiedź mową ciała 🗣️', body_pl = 'Gdy mówisz „idziemy?”, podnosi rączki, a gdy mówisz „nie”, kręci głową. Rozumienie niesamowicie wzrosło.', title_pt = 'Responde com a linguagem corporal 🗣️', body_pt = 'Quando diz "vamos?", levanta os braços, ou abana a cabeça a dizer que não. A capacidade de compreensão aumentou de forma incrível.', title_sv = 'Svarar med kroppsspråk 🗣️', body_sv = 'Barnet lyfter armarna när du säger ''ska vi gå?'' eller skakar på huvudet när du säger nej. Förståelsen har ökat otroligt mycket.', title_vi = 'Trả lời bằng ngôn ngữ cơ thể 🗣️', body_vi = 'Khi mẹ hỏi "Mình đi nhé?", bé giơ tay lên, hay lắc đầu khi muốn nói "Không". Khả năng hiểu của bé đã tăng lên đáng kinh ngạc.', title_zh = '用肢体语言回应 🗣️', body_zh = '你说“走吗？”，宝宝会举起双手；你说“不”，宝宝会摇头。理解能力提高得惊人。' WHERE id = '35ab2e31-1937-4e58-b764-83729c6e330a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Valórate 👏', body_es = 'No mires el desorden de la habitación, sino lo feliz que está hoy tu peque. Eres una madre estupenda, mucho más de lo que podría enseñar cualquier libro.', title_fr = 'Reconnaissez votre mérite 👏', body_fr = 'Ne regardez pas le désordre de la pièce, mais à quel point il est heureux aujourd''hui. Vous êtes une maman formidable, bien plus qu''aucun livre ne pourrait l''enseigner.', title_hi = 'खुद की तारीफ़ कीजिए 👏', body_hi = 'कमरे के बिखराव को नहीं, यह देखिए कि आज वह कितना खुश है। आप ऐसी बेहतरीन माँ हैं जैसा कोई किताब नहीं सिखा सकती।', title_id = 'Hargai diri Anda 👏', body_id = 'Jangan lihat kamar yang berantakan, lihatlah betapa bahagianya ia hari ini. Anda ibu yang hebat, lebih dari yang bisa diajarkan buku mana pun.', title_ja = '自分をほめてあげて 👏', body_ja = '部屋の散らかりではなく、今日の赤ちゃんの幸せそうな姿を見てください。あなたはどんな本も教えられないほど、すばらしいママです。', title_ko = '나를 칭찬해 주세요 👏', body_ko = '어질러진 방이 아니라 오늘 아기가 얼마나 행복했는지를 보세요. 당신은 어떤 책도 가르쳐 줄 수 없을 만큼 훌륭한 엄마예요.', title_nl = 'Waardeer jezelf 👏', body_nl = 'Kijk niet naar de rommel in de kamer, maar naar hoe blij je kindje vandaag was. Je bent een betere moeder dan welk boek ook je kan leren.', title_pl = 'Doceń siebie 👏', body_pl = 'Nie patrz na bałagan w pokoju, tylko na to, jak szczęśliwy jest dziś maluszek. Jesteś wspaniałą mamą, takiej żadna książka nie nauczy.', title_pt = 'Valorize-se 👏', body_pt = 'Não olhe para a desarrumação do quarto, olhe para como ele hoje está feliz. É uma mãe tão boa que nenhum livro o conseguiria ensinar.', title_sv = 'Uppskatta dig själv 👏', body_sv = 'Titta inte på stöket i rummet utan på hur glad barnet är i dag. Du är en bättre mamma än någon bok kan lära ut.', title_vi = 'Hãy ghi nhận chính mình 👏', body_vi = 'Đừng nhìn căn phòng bừa bộn, hãy nhìn xem hôm nay bé hạnh phúc thế nào. Mẹ là một người mẹ tuyệt vời hơn bất kỳ cuốn sách nào có thể dạy.', title_zh = '肯定自己 👏', body_zh = '别看房间有多乱，看看宝宝今天有多开心。你是一个任何书都教不出来的好妈妈。' WHERE id = '65a36f4e-0f24-45fe-a038-a2e61c778c81' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hoy en Cuentos inteligentes 🪄', body_es = 'Crea en Cuentos inteligentes una historia especial cuyo protagonista sea tu peque: El pequeño león que se prepara para cumplir un año.', title_fr = 'Aujourd''hui dans les Contes intelligents 🪄', body_fr = 'Dans les Contes intelligents, créez une histoire spéciale dont votre enfant est le héros : « Le petit lion qui se prépare pour ses 1 an ».', title_hi = 'आज स्मार्ट कहानियों में 🪄', body_hi = 'स्मार्ट कहानियों में एक खास कहानी बनाइए जिसका हीरो आपका अपना बच्चा हो: पहले जन्मदिन की तैयारी करता नन्हा शेर।', title_id = 'Hari ini di Dongeng Pintar 🪄', body_id = 'Di Dongeng Pintar, buat kisah istimewa dengan anak Anda sendiri sebagai pahlawannya: Singa kecil yang bersiap merayakan ulang tahun pertamanya.', title_ja = '今日の「スマートおはなし」🪄', body_ja = '「スマートおはなし」で、あなたの赤ちゃんが主人公の特別なお話をつくりましょう：1歳の誕生日を迎える準備をする小さなライオンのお話。', title_ko = '오늘의 스마트 동화 🪄', body_ko = '스마트 동화에서 우리 아이가 주인공인 특별한 이야기를 만들어 보세요: 첫돌을 준비하는 꼬마 사자.', title_nl = 'Vandaag in Slimme sprookjes 🪄', body_nl = 'Maak in Slimme sprookjes een speciaal verhaal met je eigen kindje als held: een klein leeuwtje dat zich klaarmaakt voor zijn eerste verjaardag.', title_pl = 'Dziś w Mądrych bajkach 🪄', body_pl = 'Stwórz w Mądrych bajkach wyjątkową historię, której bohaterem jest twoje dziecko: Mały lew szykujący się na roczek.', title_pt = 'Hoje nas Histórias Inteligentes 🪄', body_pt = 'Crie nas Histórias Inteligentes uma história especial em que o herói é o seu próprio filho: o pequeno leão que se prepara para fazer um ano.', title_sv = 'I dag i Smarta sagor 🪄', body_sv = 'Skapa en speciell saga i Smarta sagor där ditt eget barn är hjälten: Det lilla lejonet som gör sig redo för sin 1-årsdag.', title_vi = 'Hôm nay trong Truyện cổ tích thông minh 🪄', body_vi = 'Hãy tạo một câu chuyện đặc biệt trong Truyện cổ tích thông minh với nhân vật chính là bé nhà mình: "Chú sư tử nhỏ chuẩn bị tròn 1 tuổi".', title_zh = '今天的智能故事 🪄', body_zh = '在智能故事里创作一个以你的宝宝为主角的特别故事：《准备过一岁生日的小狮子》。' WHERE id = '7b75b0ec-d253-4e5a-bfac-9ff801269b5f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Miedos del primer año? 💬', body_es = '¿Te come la cabeza pensar «mi peque todavía no anda, ¿va con retraso?»? Escríbelo en la Comunidad Anacan. Verás que cada peque tiene su propio ritmo perfecto y que no estás sola.', title_fr = 'L''angoisse des 1 an ? 💬', body_fr = 'Des questions comme « Mon enfant ne marche pas encore, a-t-il du retard ? » vous rongent ? Écrivez dans la Communauté Anacan. Vous verrez que chaque enfant a son propre rythme parfait et que vous n''êtes pas seule.', title_hi = 'पहले साल की चिंता? 💬', body_hi = '''मेरा बच्चा अभी चलता नहीं, क्या देर हो रही है?'' जैसे सवाल आपको खाए जा रहे हैं? Anacan कम्युनिटी में लिखिए। आप देखेंगी कि हर बच्चे की अपनी परफ़ेक्ट रफ़्तार होती है और आप अकेली नहीं हैं।', title_id = 'Cemas menjelang 1 tahun? 💬', body_id = 'Pertanyaan seperti "Anakku belum bisa jalan, apakah terlambat?" terus menghantui? Tulis di Komunitas Anacan. Anda akan melihat bahwa setiap anak punya tempo sempurnanya sendiri dan Anda tidak sendirian.', title_ja = '1歳への不安？💬', body_ja = '「まだ歩かないけど、遅れているの？」という疑問が頭から離れない？Anacanコミュニティに書きこんでみましょう。どの子にもその子だけの完璧なペースがあり、あなたはひとりではないとわかります。', title_ko = '첫돌이 걱정되나요? 💬', body_ko = '''우리 아이가 아직 안 걷는데 늦은 걸까?'' 같은 질문이 머리를 떠나지 않나요? Anacan 커뮤니티에 글을 남겨 보세요. 모든 아이에게는 저마다의 완벽한 속도가 있고, 혼자가 아니라는 걸 알게 될 거예요.', title_nl = 'Zorgen rond de eerste verjaardag? 💬', body_nl = 'Spookt de vraag door je hoofd: mijn kindje loopt nog niet, is hij te laat? Schrijf erover in de Anacan Community. Je zult zien dat elk kind zijn eigen perfecte tempo heeft en dat je niet alleen bent.', title_pl = 'Obawy przed roczkiem? 💬', body_pl = 'Nie dają ci spokoju pytania typu „moje dziecko jeszcze nie chodzi, czy się spóźnia?”. Napisz w Społeczności Anacan. Zobaczysz, że każde dziecko ma swoje idealne tempo i nie jesteś sama.', title_pt = 'Medos do 1.º aniversário? 💬', body_pt = 'Perguntas como "o meu bebé ainda não anda, estará atrasado?" não lhe saem da cabeça? Escreva na Comunidade Anacan. Vai ver que cada criança tem o seu ritmo perfeito e que não está sozinha.', title_sv = 'Orolig inför 1 år? 💬', body_sv = 'Äter frågor som ''mitt barn går inte än, ligger det efter?'' upp dig? Skriv i Anacans Community. Du kommer att se att varje barn har sitt eget perfekta tempo och att du inte är ensam.', title_vi = 'Lo lắng khi bé sắp 1 tuổi? 💬', body_vi = 'Những câu hỏi như "Con mình chưa biết đi, có phải chậm không?" cứ làm mẹ bận lòng? Hãy viết vào Cộng đồng Anacan. Mẹ sẽ thấy mỗi em bé đều có nhịp phát triển hoàn hảo của riêng mình và mẹ không đơn độc.', title_zh = '一周岁的担忧？💬', body_zh = '“宝宝还不会走，是不是发育晚了？”这样的问题一直在脑子里转？发到Anacan社区吧。你会发现每个孩子都有自己完美的节奏，而你并不孤单。' WHERE id = '01302c3b-60e6-4b0a-8a88-e63349585527' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de noche de papá 👨‍🍼', body_es = 'No cargues tú sola con todos los despertares nocturnos. Despierta también a tu pareja: ser un equipo es repartir la responsabilidad a partes iguales.', title_fr = 'Le service de nuit de papa 👨‍🍼', body_fr = 'Ne gérez pas les réveils nocturnes toute seule. Réveillez aussi votre conjoint, être une équipe, c''est partager la responsabilité à parts égales.', title_hi = 'पापा की रात की ड्यूटी 👨‍🍼', body_hi = 'रात में जागने का बोझ अकेले मत उठाइए। अपने साथी को भी जगाइए, टीम होने का मतलब है ज़िम्मेदारी बराबर बाँटना।', title_id = 'Giliran malam ayah 👨‍🍼', body_id = 'Jangan tanggung sendiri saat ia terbangun di malam hari. Bangunkan juga pasangan Anda, menjadi tim berarti berbagi tanggung jawab secara adil.', title_ja = 'パパの夜の当番 👨‍🍼', body_ja = '夜中に起きるのを、ひとりで抱えこまないで。パートナーも起こしましょう。チームとは責任を平等に分け合うことです。', title_ko = '아빠의 밤 당번 👨‍🍼', body_ko = '밤에 깨는 일을 혼자 다 감당하지 마세요. 배우자도 깨우세요, 한 팀이 된다는 건 책임을 똑같이 나누는 거예요.', title_nl = 'Papa''s avonddienst 👨‍🍼', body_nl = 'Draag het ''s nachts opstaan niet helemaal alleen. Maak je partner ook wakker, een team zijn betekent de verantwoordelijkheid eerlijk delen.', title_pl = 'Nocna zmiana taty 👨‍🍼', body_pl = 'Nie dźwigaj nocnych pobudek zupełnie sama. Obudź też partnera, bycie drużyną to równy podział odpowiedzialności.', title_pt = 'O turno da noite do pai 👨‍🍼', body_pt = 'Não aguente sozinha todos os despertares noturnos. Acorde também o seu companheiro: ser uma equipa é dividir a responsabilidade por igual.', title_sv = 'Pappas nattskift 👨‍🍼', body_sv = 'Ta inte nattuppvaknandena helt ensam. Väck din partner också, att vara ett lag är att dela ansvaret lika.', title_vi = 'Ca đêm của bố 👨‍🍼', body_vi = 'Đừng một mình gánh hết những lần thức dậy ban đêm. Hãy gọi cả bố dậy, là một đội nghĩa là chia đều trách nhiệm.', title_zh = '爸爸的夜班 👨‍🍼', body_zh = '夜醒别全都自己扛。也叫醒你的伴侣，团队就是平分责任。' WHERE id = '51d3f88a-4baa-4ed5-b62c-e84a750f8166' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorando el tiempo ⛅', body_es = '¿No está claro qué tiempo hace fuera? Deja que la herramienta Tiempo y ropa te diga al instante la velocidad del viento y el conjunto adecuado.', title_fr = 'Bulletin météo ⛅', body_fr = 'Le temps dehors n''est pas très clair ? L''outil Météo et tenue vous indique aussitôt la vitesse du vent et la bonne tenue.', title_hi = 'मौसम की जासूसी ⛅', body_hi = 'बाहर मौसम साफ़ नहीं है? मौसम और कपड़े टूल आपको हवा की रफ़्तार और सही कपड़े तुरंत बताएगा।', title_id = 'Mengintip cuaca ⛅', body_id = 'Cuaca di luar tidak jelas? Biarkan fitur Cuaca dan Pakaian langsung memberi tahu kecepatan angin dan pakaian yang tepat.', title_ja = 'お天気チェック ⛅', body_ja = '外の天気がはっきりしない？「天気と服装」ツールが、風の強さとぴったりの服装をすぐに教えてくれます。', title_ko = '날씨 탐색 ⛅', body_ko = '바깥 날씨가 애매한가요? 날씨와 옷차림 도구가 바람 세기와 알맞은 옷차림을 바로 알려 줄 거예요.', title_nl = 'Het weer verkennen ⛅', body_nl = 'Is het weer buiten niet helemaal duidelijk? Laat de tool Weer en kleding je meteen de windsnelheid en de juiste outfit vertellen.', title_pl = 'Rozpoznanie pogody ⛅', body_pl = 'Pogoda na dworze niepewna? Niech narzędzie Pogoda i ubiór od razu powie ci, jak mocno wieje wiatr i jaki zestaw wybrać.', title_pt = 'Exploração do tempo ⛅', body_pt = 'O tempo lá fora não está bem definido? Deixe a ferramenta Tempo e Roupa dizer-lhe na hora a velocidade do vento e a roupa certa.', title_sv = 'Väderspaning ⛅', body_sv = 'Är vädret ute osäkert? Låt Väder och kläder direkt berätta vindstyrkan och rätt klädsel.', title_vi = 'Thám thính thời tiết ⛅', body_vi = 'Thời tiết bên ngoài không rõ ràng? Hãy để công cụ Thời tiết và trang phục cho mẹ biết ngay tốc độ gió và bộ đồ phù hợp.', title_zh = '天气侦察 ⛅', body_zh = '外面天气说不准？让天气穿衣工具马上告诉你风速和合适的搭配吧。' WHERE id = '984d2a76-5fec-4059-86ef-85671516c9b6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mamá sana, bebé sano 🥑', body_es = 'Tus reservas de hierro y calcio se han agotado. Prepara con Recetas saludables una ensalada rápida que te mantenga en pie.', title_fr = 'Maman en forme, bébé en forme 🥑', body_fr = 'Vos réserves de fer et de calcium sont épuisées. Préparez avec les Recettes saines une salade rapide qui vous tiendra debout.', title_hi = 'सेहतमंद माँ, सेहतमंद बच्चा 🥑', body_hi = 'आपके शरीर में आयरन और कैल्शियम का भंडार खत्म हो गया है। सेहतमंद रेसिपी से जल्दी बनने वाला और आपको ताकत देने वाला सलाद बनाइए।', title_id = 'Ibu sehat, bayi sehat 🥑', body_id = 'Cadangan zat besi dan kalsium Anda terkuras. Buat salad dari Resep Sehat yang cepat dibuat dan membuat Anda tetap bertenaga.', title_ja = '元気なママ、元気な赤ちゃん 🥑', body_ja = '鉄分とカルシウムの蓄えが減っています。「ヘルシーレシピ」から、手早くできて元気を保てるサラダをつくりましょう。', title_ko = '건강한 엄마, 건강한 아기 🥑', body_ko = '철분과 칼슘이 바닥났어요. 건강한 레시피에서 빨리 만들 수 있고 든든하게 버티게 해 줄 샐러드를 만들어 보세요.', title_nl = 'Gezonde mama, gezonde baby 🥑', body_nl = 'Je ijzer- en calciumvoorraad is op. Maak uit Gezonde recepten een snelle salade die je op de been houdt.', title_pl = 'Zdrowa mama, zdrowy maluszek 🥑', body_pl = 'Twoje zapasy żelaza i wapnia się wyczerpały. Przygotuj ze Zdrowych przepisów szybką sałatkę, która postawi cię na nogi.', title_pt = 'Mãe saudável, bebé saudável 🥑', body_pt = 'As suas reservas de ferro e cálcio esgotaram-se. Prepare nas Receitas Saudáveis uma salada rápida que a mantenha de pé.', title_sv = 'Frisk mamma, friskt barn 🥑', body_sv = 'Dina järn- och kalciumförråd har tömts. Gör en sallad från Hälsosamma recept som både går snabbt att laga och håller dig på benen.', title_vi = 'Mẹ khỏe, bé khỏe 🥑', body_vi = 'Dự trữ sắt và canxi của mẹ đã cạn. Hãy làm một món salad làm nhanh mà giúp mẹ khỏe khoắn từ Công thức lành mạnh.', title_zh = '妈妈健康，宝宝健康 🥑', body_zh = '你体内的铁和钙储备快耗尽了。从健康食谱里做一份快手又能让你撑住的沙拉吧。' WHERE id = '063ccb8e-7bd6-43e4-9c41-f30c172e10a7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una foto que detiene el tiempo 📸', body_es = 'Mientras juega tan a gusto en la habitación, abre ya la Sesión de fotos del bebé y captura su carácter de niño mayor.', title_fr = 'La photo qui arrête le temps 📸', body_fr = 'Pendant qu''il joue tranquillement, ouvrez vite la Séance photo bébé et immortalisez son caractère de grand.', title_hi = 'समय को थाम लेने वाली तस्वीर 📸', body_hi = 'कमरे में प्यार से खेलते हुए तुरंत बेबी फ़ोटोशूट खोलिए और उसके बड़े होते बच्चे वाले स्वभाव को कैद कीजिए।', title_id = 'Foto yang menghentikan waktu 📸', body_id = 'Saat ia bermain dengan manis di kamar, segera buka Sesi Foto Bayi dan abadikan karakternya yang kini sudah seperti anak besar.', title_ja = '時間を止める1枚 📸', body_ja = '部屋でごきげんに遊んでいるうちに、すぐ「ベビーフォトセッション」を開いて、すっかり子どもらしくなった個性を撮りましょう。', title_ko = '시간을 멈추는 한 컷 📸', body_ko = '방에서 귀엽게 놀고 있을 때 바로 아기 사진 촬영을 열어 한층 의젓해진 모습을 담아 보세요.', title_nl = 'Een foto die de tijd stilzet 📸', body_nl = 'Speelt je baby lief in de kamer? Open meteen Babyfotoshoot en leg het karakter van dit grote kind vast.', title_pl = 'Kadr, który zatrzymuje czas 📸', body_pl = 'Gdy słodko bawi się w pokoju, od razu otwórz Sesję zdjęciową dziecka i uwiecznij ten charakter dużego dziecka.', title_pt = 'Uma foto que para o tempo 📸', body_pt = 'Enquanto brinca docemente no quarto, abra já a Sessão Fotográfica do Bebé e fotografe este feitio de criança crescida.', title_sv = 'Bilden som stoppar tiden 📸', body_sv = 'Öppna Babyfotografering direkt medan barnet leker så gulligt i rummet och fånga den här stora barn-personligheten.', title_vi = 'Khoảnh khắc ngưng đọng thời gian 📸', body_vi = 'Khi bé đang chơi ngoan trong phòng, hãy mở ngay Chụp ảnh cho bé và lưu giữ dáng vẻ "đã lớn" này của bé.', title_zh = '定格时光 📸', body_zh = '趁宝宝在房间里乖乖玩耍，马上打开宝宝写真，拍下宝宝这副小大人的模样吧。' WHERE id = 'caa0a9a0-1a0d-4362-a446-9f103d33e564' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baja las luces 🌙', body_es = 'Una hora antes de dormir, apaga todas las luces fuertes y las pantallas de casa. La melatonina solo se segrega en un ambiente tranquilo y con poca luz.', title_fr = 'Baissez les lumières 🌙', body_fr = '1 heure avant le coucher, éteignez toutes les lumières vives et les écrans de la maison. La mélatonine n''est sécrétée que dans un environnement calme et peu éclairé.', title_hi = 'लाइटें धीमी कीजिए 🌙', body_hi = 'सोने से 1 घंटा पहले घर की सारी तेज़ लाइटें और स्क्रीन बंद कर दीजिए। मेलाटोनिन शांत और कम रोशनी वाले माहौल में ही बनता है।', title_id = 'Redupkan lampu 🌙', body_id = 'Satu jam sebelum tidur, matikan semua lampu terang dan layar di rumah. Melatonin hanya diproduksi di lingkungan yang tenang dan redup.', title_ja = '明かりを落として 🌙', body_ja = '寝る1時間前には、家の強い明かりや画面をすべて消しましょう。メラトニンは、静かで明かりの少ない環境でこそ分泌されます。', title_ko = '조명을 낮춰요 🌙', body_ko = '잠들기 1시간 전에 집 안의 밝은 조명과 화면을 모두 끄세요. 멜라토닌은 조용하고 어두운 환경에서만 분비돼요.', title_nl = 'Doe de lichten zachter 🌙', body_nl = 'Doe 1 uur voor het slapengaan alle felle lampen en schermen in huis uit. Melatonine wordt alleen in een rustige omgeving met weinig licht aangemaakt.', title_pl = 'Przyciemnij światła 🌙', body_pl = 'Na godzinę przed snem wyłącz w domu wszystkie mocne światła i ekrany. Melatonina wydziela się tylko w spokojnym, słabo oświetlonym otoczeniu.', title_pt = 'Baixe as luzes 🌙', body_pt = '1 hora antes de dormir, apague as luzes desnecessárias e os ecrãs da casa. A melatonina só é produzida num ambiente calmo e com pouca luz.', title_sv = 'Dämpa ljuset 🌙', body_sv = 'Släck alla starka lampor och skärmar hemma 1 timme innan läggdags. Melatonin utsöndras bara i en lugn och svagt upplyst miljö.', title_vi = 'Giảm ánh sáng 🌙', body_vi = '1 tiếng trước giờ ngủ, hãy tắt hết đèn sáng và màn hình trong nhà. Melatonin chỉ được tiết ra trong môi trường yên tĩnh và ít ánh sáng.', title_zh = '调暗灯光 🌙', body_zh = '睡前1小时关掉家里所有的强光和屏幕。褪黑素只有在安静、光线昏暗的环境里才会分泌。' WHERE id = '3cc5a97d-281f-41bf-8747-fbb71f040e65' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Prueba hoy las sopas que ayudan a aumentar la leche de la sección Recetas saludables para mujeres y recupera fuerzas.', body_fr = 'Essayez aujourd''hui les soupes favorisant la lactation de la rubrique Recettes saines pour les femmes et reprenez des forces.', body_hi = 'महिलाओं के लिए सेहतमंद रेसिपी सेक्शन के दूध बढ़ाने वाले सूप आज आज़माइए और खुद को ताकत दीजिए।', body_id = 'Coba sup pelancar ASI di bagian Resep Sehat untuk Perempuan hari ini dan kuatkan diri Anda.', body_ja = '「女性のためのヘルシーレシピ」の母乳によいスープを今日試して、体力をつけましょう。', body_ko = '여성을 위한 건강한 레시피 섹션에서 젖 분비를 돕는 수프를 오늘 시도해 보고 힘을 내세요.', body_nl = 'Probeer vandaag de soepen die de melkproductie bevorderen in het onderdeel Gezonde recepten voor vrouwen en geef jezelf een boost.', body_pl = 'Wypróbuj dziś zupy wspierające laktację z sekcji Zdrowe przepisy dla kobiet i nabierz sił.', body_pt = 'Experimente hoje as sopas que ajudam a produzir leite da secção Receitas Saudáveis para Mulheres e ganhe forças.', body_sv = 'Prova de mjölkökande sopporna i avsnittet Hälsosamma recept för kvinnor i dag och stärk dig själv.', body_vi = 'Hôm nay hãy thử các món súp lợi sữa trong mục Công thức lành mạnh cho phụ nữ và tiếp thêm sức cho mình.', body_zh = '今天试试女性健康食谱板块里的催奶汤，给自己补补力气吧。' WHERE id = '528b02c4-9d93-4cda-add4-eb9a04a4395a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El temporizador de Anacan recuerda por ti el pecho derecho o izquierdo. ¡Empieza ya la toma con el temporizador!', body_fr = 'Le minuteur Anacan retient pour vous le sein droit ou gauche. Lancez maintenant la tétée avec le minuteur !', body_hi = 'Anacan टाइमर आपकी जगह दायाँ/बायाँ स्तन याद रखता है। अभी टाइमर के साथ फ़ीडिंग शुरू कीजिए!', body_id = 'Timer Anacan mengingat payudara kanan/kiri untuk Anda. Mulai menyusui sekarang dengan timer!', body_ja = 'Anacanのタイマーが、あなたの代わりに左右どちらのおっぱいかを覚えておいてくれます。今すぐタイマーで授乳を始めましょう！', body_ko = 'Anacan 타이머가 엄마 대신 왼쪽/오른쪽 가슴을 기억해 줘요. 지금 타이머로 수유를 시작하세요!', body_nl = 'De timer van Anacan onthoudt voor jou welke borst, links of rechts, aan de beurt is. Start de voeding nu met de timer!', body_pl = 'Timer Anacan zapamięta za ciebie, z której piersi karmiłaś: lewej czy prawej. Włącz teraz karmienie z timerem!', body_pt = 'O temporizador do Anacan lembra-se por si se foi o peito direito ou o esquerdo. Comece já a mamada com o temporizador!', body_sv = 'Anacan-timern kommer ihåg höger eller vänster bröst åt dig. Starta matningen med timern nu!', body_vi = 'Hẹn giờ của Anacan sẽ nhớ giúp mẹ bên ngực trái hay phải. Hãy bắt đầu cữ bú với hẹn giờ ngay bây giờ!', body_zh = 'Anacan计时器会替你记住左右侧乳房。现在就用计时器开始喂奶吧！' WHERE id = 'a889d8c9-3ffc-4f2f-8c82-a33c81ad3e8d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cambian las siestas? 🥱', body_es = '¿Se resiste a una de sus dos siestas de día? Puede que haya llegado el momento de reajustar su horario de sueño de cara al primer año.', title_fr = 'Les siestes changent ? 🥱', body_fr = 'Il résiste à l''une de ses deux siestes ? À l''approche de ses 1 an, il est peut-être temps de réajuster son planning de sommeil.', title_hi = 'दिन की नींद बदल रही है? 🥱', body_hi = 'दिन की दो झपकियों में से एक का विरोध करता है? 1 साल के करीब नींद का शेड्यूल फिर से तय करने का समय आ सकता है।', title_id = 'Tidur siang berubah? 🥱', body_id = 'Ia menolak salah satu dari dua tidur siangnya? Menjelang 1 tahun, mungkin sudah waktunya menyesuaikan kembali jadwal tidurnya.', title_ja = 'お昼寝が変わる？🥱', body_ja = '2回のお昼寝のうち1回をいやがるようになった？1歳に向けて、睡眠のスケジュールを見直すときかもしれません。', title_ko = '낮잠이 바뀌고 있나요? 🥱', body_ko = '두 번의 낮잠 중 하나를 거부하나요? 첫돌을 앞두고 수면 일정을 다시 조정할 때가 됐을 수 있어요.', title_nl = 'Veranderen de dutjes overdag? 🥱', body_nl = 'Verzet je baby zich tegen een van de twee dutjes overdag? Rond de eerste verjaardag kan het tijd zijn om het slaapschema opnieuw aan te passen.', title_pl = 'Drzemki się zmieniają? 🥱', body_pl = 'Opiera się jednej z dwóch dziennych drzemek? Przed roczkiem może nadejść czas, by na nowo ułożyć plan snu.', title_pt = 'As sestas estão a mudar? 🥱', body_pt = 'Resiste a uma das duas sestas do dia? Perto do 1.º ano, pode ser altura de reajustar o horário de sono.', title_sv = 'Förändras dagsluren? 🥱', body_sv = 'Gör barnet motstånd mot en av de två dagsluren? Det kan vara dags att justera sömnschemat igen inför 1-årsdagen.', title_vi = 'Giấc ngủ ngày thay đổi? 🥱', body_vi = 'Bé chống lại một trong hai giấc ngủ ngày? Khi gần 1 tuổi, có lẽ đã đến lúc điều chỉnh lại lịch ngủ.', title_zh = '白天小睡在变化？🥱', body_zh = '宝宝开始抗拒白天两次小睡中的一次？快1岁了，可能是时候重新调整睡眠安排了。' WHERE id = '5c42ea20-5a84-467a-b408-412bcaaf8374' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Tiene su sitio en la mesa familiar! 🍲', body_es = 'Ya le encanta comer a la misma hora que vosotros. Descubre sabores para toda la familia en las Recetas para bebés que empiezan con la alimentación complementaria de nuestra app.', title_fr = 'Il a sa place à la table familiale ! 🍲', body_fr = 'Il adore désormais manger en même temps que vous. Découvrez des saveurs familiales dans les Recettes pour bébés qui commencent la diversification de l''application.', title_hi = 'परिवार की मेज़ पर उसकी अपनी जगह! 🍲', body_hi = 'अब उसे आपके साथ एक ही समय पर खाना पसंद है। ऐप में ऊपरी आहार शुरू करने वाले बच्चों की रेसिपी से पूरे परिवार के स्वाद खोजिए।', title_id = 'Ia punya tempat di meja makan keluarga! 🍲', body_id = 'Kini ia senang makan di waktu yang sama dengan Anda. Temukan hidangan keluarga di Resep untuk bayi yang mulai MPASI di aplikasi kami.', title_ja = '家族の食卓に自分の席！🍲', body_ja = 'もうあなたと同じ時間にごはんを食べるのが大好き。アプリの「離乳食を始める赤ちゃんのレシピ」で、家族みんなで楽しめる味を見つけましょう。', title_ko = '가족 식탁에 내 자리가 있어요! 🍲', body_ko = '이제 엄마와 같은 시간에 밥 먹는 걸 좋아해요. 앱의 이유식을 시작하는 아기를 위한 레시피에서 온 가족이 즐길 요리를 찾아보세요.', title_nl = 'Een eigen plekje aan de familietafel! 🍲', body_nl = 'Je baby eet nu graag op hetzelfde moment als jullie. Ontdek gerechten voor het hele gezin in de Recepten voor baby''s die met bijvoeding beginnen in onze app.', title_pl = 'Ma swoje miejsce przy rodzinnym stole! 🍲', body_pl = 'Lubi już jeść razem z wami. Odkryj rodzinne smaki w Przepisach dla maluszków zaczynających rozszerzanie diety w naszej aplikacji.', title_pt = 'Tem o seu lugar à mesa da família! 🍲', body_pt = 'Já gosta de comer à mesma hora que vocês. Descubra sabores para toda a família nas Receitas para bebés em diversificação alimentar da nossa app.', title_sv = 'En egen plats vid familjebordet! 🍲', body_sv = 'Barnet gillar redan att äta samtidigt som ni. Upptäck goda familjerätter i Recept för barn som börjar med smakportioner i appen.', title_vi = 'Bé có chỗ riêng trong bữa cơm gia đình! 🍲', body_vi = 'Giờ bé thích ăn cùng lúc với cả nhà. Hãy khám phá những món ngon cho cả gia đình từ Công thức cho bé bắt đầu ăn dặm trong ứng dụng.', title_zh = '家庭餐桌上有了宝宝的位置！🍲', body_zh = '宝宝已经喜欢和你们同时吃饭了。在应用里的“辅食宝宝食谱”中发现适合全家的美味吧。' WHERE id = 'b5252c17-b36e-4334-8221-0dc9210bbc77' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Pregunta a nuestro asistente Anacan AI, incluso de noche, dudas importantes como «¿cómo pasar a la leche de vaca después del primer año?» y recibe apoyo.', body_fr = 'Posez vos questions importantes, comme « Comment passer au lait de vache après 1 an ? », à notre assistant Anacan AI, même tard le soir, et trouvez du soutien.', body_hi = '''1 साल के बाद गाय के दूध पर कैसे जाएँ?'' जैसे ज़रूरी सवाल देर रात भी Anacan AI असिस्टेंट से पूछिए और सहायता पाइए।', body_id = 'Tanyakan pertanyaan penting seperti "Bagaimana beralih ke susu sapi setelah 1 tahun?" ke asisten Anacan AI, bahkan di malam hari, dan dapatkan dukungan.', body_ja = '「1歳以降、牛乳にはどう切りかえる？」のような大切な疑問も、夜中でもAnacan AIアシスタントに聞いて、サポートを受けましょう。', body_ko = '''첫돌 이후 우유로 어떻게 바꿀까?'' 같은 중요한 질문은 늦은 밤이라도 Anacan AI 도우미에게 물어 도움을 받으세요.', body_nl = 'Stel belangrijke vragen, zoals hoe je na 1 jaar overstapt op koemelk, zelfs ''s nachts aan onze assistent Anacan AI en krijg steun.', body_pl = 'Ważne pytania, jak „jak po roczku przejść na mleko krowie?”, możesz zadać naszemu asystentowi Anacan AI nawet w nocy i otrzymać wsparcie.', body_pt = 'Perguntas importantes como "como passar ao leite de vaca depois de 1 ano?", faça-as ao nosso assistente Anacan AI, mesmo a meio da noite, e receba apoio.', body_sv = 'Ställ viktiga frågor som ''hur går man över till komjölk efter 1 år?'' till vår assistent Anacan AI, även sent på natten, och få stöd.', body_vi = 'Những câu hỏi quan trọng như "Sau 1 tuổi chuyển sang sữa bò thế nào?", kể cả lúc nửa đêm, hãy hỏi trợ lý Anacan AI để được hỗ trợ.', body_zh = '“1岁以后怎样换成牛奶？”这样的重要问题，哪怕是深夜，也可以问问我们的Anacan AI助手，获得支持。' WHERE id = 'ee88eee3-00d7-4463-b0db-60b939d85d4e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dudas pediátricas 🤖', body_es = '¿Qué cambia en la alimentación de cara al primer año? No te agotes: pide a Anacan AI una lista precisa y avalada por pediatras.', title_fr = 'Des doutes pédiatriques 🤖', body_fr = 'Qu''est-ce qui change dans son alimentation à l''approche de ses 1 an ? Ne vous fatiguez pas, demandez à Anacan AI une liste précise et validée par des pédiatres.', title_hi = 'बच्चे की सेहत को लेकर सवाल 🤖', body_hi = '1 साल के करीब खाने में क्या बदलता है? खुद को मत थकाइए, Anacan AI से सटीक और बाल रोग विशेषज्ञों से पुष्ट सूची माँगिए।', title_id = 'Keraguan seputar kesehatan anak 🤖', body_id = 'Apa saja yang berubah dalam pola makan menjelang 1 tahun? Jangan bikin pusing, minta daftar yang akurat dan sesuai pandangan dokter anak dari Anacan AI.', title_ja = '育児の疑問 🤖', body_ja = '1歳に向けて、食事で何が変わる？無理をしないで、Anacan AIに正確で小児科医の視点のリストを頼みましょう。', title_ko = '소아과 궁금증 🤖', body_ko = '첫돌 무렵 식사에서 무엇이 달라질까요? 고민하지 말고 Anacan AI에게 정확하고 소아과 의사가 확인한 목록을 요청하세요.', title_nl = 'Twijfels over je kindje 🤖', body_nl = 'Wat verandert er rond de eerste verjaardag in de voeding? Maak jezelf niet moe, vraag Anacan AI om een precieze lijst die door kinderartsen is goedgekeurd.', title_pl = 'Pediatryczne wątpliwości 🤖', body_pl = 'Co zmienia się w żywieniu przed roczkiem? Nie męcz się, poproś Anacan AI o dokładną listę potwierdzoną przez pediatrów.', title_pt = 'Dúvidas pediátricas 🤖', body_pt = 'O que muda na alimentação perto do 1.º ano? Não se canse: peça ao Anacan AI uma lista precisa e validada por pediatras.', title_sv = 'Barnmedicinska funderingar 🤖', body_sv = 'Vad förändras i maten inför 1-årsdagen? Slit inte ut dig, be Anacan AI om en exakt och barnläkargodkänd lista.', title_vi = 'Băn khoăn về nhi khoa 🤖', body_vi = 'Khi bé gần 1 tuổi, chế độ ăn có gì thay đổi? Đừng làm mình mệt, hãy nhờ Anacan AI một danh sách chính xác, được bác sĩ nhi khoa xác nhận.', title_zh = '儿科疑虑 🤖', body_zh = '快1岁时，饮食上会有哪些变化？别累坏自己，向Anacan AI要一份准确、经儿科医生认可的清单吧。' WHERE id = '48047d55-0e81-4b9a-976d-56b580b1a7b7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apoyo de equipo 🥂', body_es = 'Para quitaros de encima el cansancio del día, tomad un té tu pareja y tú y decíos «hoy también lo hemos conseguido».', title_fr = 'Le soutien de l''équipe 🥂', body_fr = 'Pour vous débarrasser de la fatigue de la journée, buvez un thé avec votre conjoint et dites-vous : « Aujourd''hui encore, on a réussi. »', title_hi = 'टीम का साथ 🥂', body_hi = 'दिनभर की थकान कंधों से उतारने के लिए अपने साथी के साथ चाय पीजिए और एक-दूसरे से कहिए, ''आज भी हमने कर दिखाया''।', title_id = 'Dukungan tim 🥂', body_id = 'Untuk melepas lelah seharian dari pundak Anda, minum teh bersama pasangan dan katakan satu sama lain, "Hari ini pun kita berhasil."', title_ja = 'チームで支え合う 🥂', body_ja = '1日の疲れを肩からおろすために、パートナーとお茶を飲んで「今日もがんばったね」と言い合いましょう。', title_ko = '팀의 응원 🥂', body_ko = '하루의 피로를 어깨에서 내려놓으려면 배우자와 차를 마시며 서로에게 ''오늘도 해냈어''라고 말해 주세요.', title_nl = 'Steun als team 🥂', body_nl = 'Drink samen met je partner een kop thee om de vermoeidheid van de dag van je af te schudden en zeg tegen elkaar: het is ons vandaag weer gelukt.', title_pl = 'Wsparcie drużyny 🥂', body_pl = 'Aby zrzucić z ramion zmęczenie całego dnia, napijcie się z partnerem herbaty i powiedzcie sobie: „Dziś też daliśmy radę”.', title_pt = 'Apoio de equipa 🥂', body_pt = 'Para tirar dos ombros o cansaço do dia, beba um chá com o seu companheiro e digam um ao outro: "hoje também conseguimos".', title_sv = 'Lagstöd 🥂', body_sv = 'För att skaka av dig hela dagens trötthet, drick te tillsammans med din partner och säg till varandra: vi klarade det i dag också.', title_vi = 'Đồng đội hỗ trợ 🥂', body_vi = 'Để trút bỏ mệt mỏi cả ngày khỏi đôi vai, hãy cùng bố uống trà và nói với nhau: "Hôm nay mình lại làm được rồi".', title_zh = '团队支持 🥂', body_zh = '为了卸下一整天的疲惫，和伴侣一起喝杯茶，对彼此说：“今天我们也做到了！”' WHERE id = '56284941-dca4-4067-9e31-d61fc4ebeb63' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Cumple del todo órdenes sencillas! 🧠', body_es = 'Te entiende cuando le dices «dame la pelota» o «ven aquí». Lleva este salto intelectual aún más lejos con los artículos del Blog.', title_fr = 'Il suit parfaitement les consignes simples ! 🧠', body_fr = 'Quand vous dites « Donne-moi le ballon » ou « Viens ici », il vous comprend. Faites aller ce bond intellectuel encore plus loin avec les articles des Blogs.', title_hi = 'आसान बातें पूरी तरह मानता है! 🧠', body_hi = '''गेंद मुझे दो'', ''यहाँ आओ'' कहने पर वह आपको समझता है। ब्लॉग के लेखों से समझ की इस छलांग को और आगे बढ़ाइए।', title_id = 'Ia menjalankan perintah sederhana sepenuhnya! 🧠', body_id = 'Saat Anda berkata "Berikan bolanya padaku, ke sini", ia memahami Anda. Dukung lompatan kecerdasan ini lebih jauh dengan artikel di Blog.', title_ja = 'かんたんな指示をしっかりこなす！🧠', body_ja = '「ボールちょうだい」「こっちにおいで」と言うと、ちゃんとわかります。この知的な飛躍を、ブログの記事でさらに伸ばしてあげましょう。', title_ko = '간단한 말을 척척 따라요! 🧠', body_ko = '''공 줘'', ''이리 와'' 하면 알아들어요. 이 지적인 도약을 블로그의 글로 한 걸음 더 키워 주세요.', title_nl = 'Hij voert eenvoudige opdrachten helemaal uit! 🧠', body_nl = 'Als je zegt: geef mij de bal, kom eens hier, begrijpt hij je. Breng deze denksprong verder met de artikelen in de Blogs.', title_pl = 'W pełni wykonuje proste polecenia! 🧠', body_pl = 'Rozumie cię, gdy mówisz „daj mi piłkę” albo „chodź tu”. Wspieraj ten intelektualny skok artykułami z Bloga.', title_pt = 'Cumpre ordens simples na perfeição! 🧠', body_pt = 'Percebe-a quando diz "dá-me a bola" ou "anda cá". Leve este salto intelectual mais longe com os artigos dos Blogues.', title_sv = 'Följer enkla uppmaningar helt! 🧠', body_sv = 'Barnet förstår dig när du säger ''ge mig bollen'' eller ''kom hit''. Ta det här intellektuella språnget ännu längre med artiklarna i Bloggar.', title_vi = 'Làm theo trọn vẹn những yêu cầu đơn giản! 🧠', body_vi = 'Khi mẹ nói "Đưa bóng cho mẹ", "Lại đây nào", bé hiểu được. Hãy đưa bước nhảy trí tuệ này đi xa hơn nữa với các bài viết trong mục Blog.', title_zh = '能完全执行简单指令了！🧠', body_zh = '你说“把球给我”“过来”，宝宝都能听懂。用博客里的文章，让这次智力飞跃更进一步吧。' WHERE id = 'c69bf08f-8c53-4bb9-8c0e-a81edd03f90e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Solo 2 semanas! 🎈', body_es = '¡Solo faltan 14 días para su cumpleaños! Soplan vientos de nostalgia... Abre la Sesión de fotos del bebé, pon una al lado de otra la foto del día en que nació y la de hoy, y contempla cuánto ha crecido.', title_fr = 'Plus que 2 semaines ! 🎈', body_fr = 'Plus que 14 jours avant son anniversaire ! Un vent de nostalgie souffle... Ouvrez la Séance photo bébé, placez la photo de sa naissance à côté de celle d''aujourd''hui et admirez comme il a grandi.', title_hi = 'बस 2 हफ़्ते! 🎈', body_hi = 'जन्मदिन में बस 14 दिन बाकी! पुरानी यादों की हवा चल रही है... बेबी फ़ोटोशूट खोलिए, जन्म के दिन की और आज की तस्वीर साथ-साथ रखिए और उस शानदार बढ़त को देखिए।', title_id = 'Tinggal 2 minggu! 🎈', body_id = 'Tinggal 14 hari lagi menuju ulang tahunnya! Angin nostalgia berembus... Buka Sesi Foto Bayi, sandingkan foto hari kelahirannya dengan foto hari ini, dan saksikan pertumbuhannya yang luar biasa.', title_ja = 'あと2週間！🎈', body_ja = '誕生日まであと14日！なつかしい気持ちがこみあげます...「ベビーフォトセッション」を開いて、生まれた日と今日の写真を並べ、そのすばらしい成長を見てみましょう。', title_ko = '딱 2주! 🎈', body_ko = '생일까지 딱 14일 남았어요! 추억의 바람이 불어와요... 아기 사진 촬영을 열어 태어난 날의 사진과 오늘 사진을 나란히 놓고 그 놀라운 성장을 지켜보세요.', title_nl = 'Nog maar 2 weken! 🎈', body_nl = 'Nog maar 14 dagen tot de verjaardag! Er waait een nostalgisch briesje... Open Babyfotoshoot, zet een foto van zijn geboortedag naast een foto van vandaag en zie hoe geweldig hij is gegroeid.', title_pl = 'Tylko 2 tygodnie! 🎈', body_pl = 'Do urodzin zostało tylko 14 dni! Wieje wiatr nostalgii... Otwórz Sesję zdjęciową dziecka, ułóż obok siebie zdjęcie z dnia narodzin i dzisiejsze i zobacz, jak wspaniale urósł.', title_pt = 'Só 2 semanas! 🎈', body_pt = 'Faltam apenas 14 dias para o aniversário! Sopram ventos de nostalgia... Abra a Sessão Fotográfica do Bebé, ponha lado a lado a foto do dia em que nasceu e a de hoje e veja como cresceu de forma fantástica.', title_sv = 'Bara 2 veckor! 🎈', body_sv = 'Bara 14 dagar kvar till födelsedagen! Nostalgins vindar blåser... Öppna Babyfotografering, lägg en bild från födelsedagen bredvid en bild från i dag och se den fantastiska tillväxten.', title_vi = 'Chỉ còn 2 tuần! 🎈', body_vi = 'Chỉ còn 14 ngày nữa là đến sinh nhật! Nỗi nhớ ùa về... Hãy mở Chụp ảnh cho bé, đặt tấm ảnh ngày bé chào đời cạnh tấm ảnh hôm nay và ngắm nhìn bé đã lớn tuyệt vời thế nào.', title_zh = '只剩2周！🎈', body_zh = '离生日只剩14天了！怀旧之风吹起来了……打开宝宝写真，把出生那天和今天的照片放在一起，看看这了不起的成长吧。' WHERE id = '152edc3c-3a8c-41ee-81bb-0df222f2c1ea' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La responsabilidad nocturna de papá 👨‍🍼', body_es = 'Ya tienes bastante con el cansancio del día. Por la tarde, preparar al bebé para dormir y leerle un cuento es tarea de papá. Tú simplemente ponte los auriculares.', title_fr = 'La responsabilité nocturne de papa 👨‍🍼', body_fr = 'La fatigue de la journée vous suffit. En fin de journée, préparer bébé pour la nuit et lui lire un conte, c''est le rôle de papa. Vous, mettez simplement vos écouteurs.', title_hi = 'पापा की रात की ज़िम्मेदारी 👨‍🍼', body_hi = 'दिन की थकान आपके लिए काफ़ी है। शाम को बच्चे को सोने के लिए तैयार करना और कहानी पढ़ना पापा का काम है। और आप बस हेडफ़ोन लगा लीजिए।', title_id = 'Tanggung jawab malam ayah 👨‍🍼', body_id = 'Lelah seharian sudah cukup bagi Anda. Menjelang malam, menyiapkan si kecil tidur dan membacakan dongeng adalah tugas ayah. Anda cukup pasang headphone saja.', title_ja = 'パパの夜の役目 👨‍🍼', body_ja = '昼間の疲れだけでもう十分。夕方の寝かしつけの準備とお話の読み聞かせはパパの担当です。あなたはヘッドホンをつけるだけでOK。', title_ko = '아빠의 밤 당번 👨‍🍼', body_ko = '낮의 피로로 충분해요. 저녁에 아기를 재울 준비를 하고 동화를 읽어 주는 건 아빠 몫이에요. 엄마는 이어폰만 끼세요.', title_nl = 'Papa''s verantwoordelijkheid voor de nacht 👨‍🍼', body_nl = 'De vermoeidheid van overdag is genoeg voor jou. ''s Avonds de baby klaarmaken voor bed en een sprookje voorlezen is papa''s taak. Jij zet gewoon je koptelefoon op.', title_pl = 'Nocny dyżur taty 👨‍🍼', body_pl = 'Wystarczy ci dziennego zmęczenia. Wieczorne przygotowanie maluszka do snu i czytanie bajki to zadanie taty. A ty po prostu załóż słuchawki.', title_pt = 'A responsabilidade noturna do pai 👨‍🍼', body_pt = 'O cansaço do dia já chega. Ao fim do dia, preparar o bebé para dormir e ler-lhe uma história é tarefa do pai. A mãe só tem de pôr os auscultadores.', title_sv = 'Pappas nattansvar 👨‍🍼', body_sv = 'Dagens trötthet räcker för dig. Att göra barnet redo för sömnen och läsa en saga på kvällen är pappas uppgift. Och du, sätt bara på dig hörlurarna.', title_vi = 'Trách nhiệm ban đêm của bố 👨‍🍼', body_vi = 'Mệt mỏi ban ngày đã đủ với mẹ rồi. Chiều tối nay, việc chuẩn bị cho bé đi ngủ và đọc truyện là nhiệm vụ của bố. Còn mẹ chỉ cần đeo tai nghe vào.', title_zh = '爸爸的夜间责任 👨‍🍼', body_zh = '白天的疲惫已经够你受了。傍晚哄宝宝睡前准备和讲故事是爸爸的任务。你只管戴上耳机。' WHERE id = '87c2d4c6-8130-43a1-8ff7-fa406c018013' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Segundos sin apoyo 🧗‍♂️', body_es = '¿De pie agarrado al sofá, se suelta durante un momento? Está encontrando el equilibrio.', title_fr = 'Des secondes sans appui 🧗‍♂️', body_fr = 'Debout en se tenant au canapé, il lâche les mains quelques instants ? Il trouve son équilibre.', title_hi = 'बिना सहारे के सेकंड 🧗‍♂️', body_hi = 'सोफ़ा पकड़कर खड़े-खड़े थोड़ी देर के लिए हाथ छोड़ देता है? वह अपना संतुलन ढूँढ रहा है।', title_id = 'Detik-detik tanpa pegangan 🧗‍♂️', body_id = 'Saat berdiri berpegangan pada sofa, ia melepaskan tangannya sebentar? Ia sedang menemukan keseimbangannya.', title_ja = '支えなしの数秒 🧗‍♂️', body_ja = 'ソファにつかまって立っているとき、少しの間手を離しますか？バランスを見つけているのです。', title_ko = '받침 없는 몇 초 🧗‍♂️', body_ko = '소파를 잡고 서 있다가 잠깐씩 손을 놓나요? 균형을 찾고 있어요.', title_nl = 'Seconden zonder steun 🧗‍♂️', body_nl = 'Laat je baby even zijn handjes los als hij staat en zich aan de bank vasthoudt? Hij vindt zijn evenwicht.', title_pl = 'Sekundy bez podparcia 🧗‍♂️', body_pl = 'Stojąc przy kanapie, na chwilę puszcza rączki? Łapie równowagę.', title_pt = 'Segundos sem apoio 🧗‍♂️', body_pt = 'De pé agarrado ao sofá, larga as mãos por breves instantes? Está a encontrar o equilíbrio.', title_sv = 'Sekunder utan stöd 🧗‍♂️', body_sv = 'Släpper barnet händerna en kort stund när det står och håller i soffan? Det hittar balansen.', title_vi = 'Những giây không cần bám 🧗‍♂️', body_vi = 'Đang bám sofa đứng, bé buông tay trong chốc lát? Bé đang tìm lại thăng bằng.', title_zh = '不扶东西的几秒钟 🧗‍♂️', body_zh = '扶着沙发站着时会短暂地松开手？宝宝在找平衡。' WHERE id = 'd1325a58-5701-4db5-a92f-ca67116c5c21' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dilema de qué cocinar 🍲', body_es = '¿Te has quedado sin ideas para el menú de cara al primer año? Pide a Anacan AI una lista de alimentos fáciles que tu peque pueda coger y comer solo.', title_fr = 'Le casse-tête du « qu''est-ce que je cuisine ? » 🍲', body_fr = 'Plus d''idées de menu à l''approche de ses 1 an ? Demandez à Anacan AI une liste d''aliments faciles qu''il peut attraper et manger seul avec les doigts.', title_hi = 'क्या पकाऊँ, यही चिंता 🍲', body_hi = '1 साल के करीब मेन्यू के आइडिया खत्म हो गए? Anacan AI से ऐसे आसान फ़िंगर फ़ूड की सूची माँगिए जिन्हें बच्चा खुद पकड़कर खा सके।', title_id = 'Bingung mau masak apa 🍲', body_id = 'Kehabisan ide menu menjelang 1 tahun? Minta daftar finger food mudah yang bisa ia pegang dan makan sendiri dari Anacan AI.', title_ja = '何をつくろう問題 🍲', body_ja = '1歳に向けた献立のアイデアが尽きた？Anacan AIに、赤ちゃんが自分で持って食べられるかんたんな手づかみ食べリストを頼みましょう。', title_ko = '뭐 해 먹지 고민 🍲', body_ko = '첫돌 무렵 메뉴 아이디어가 바닥났나요? Anacan AI에게 아이가 혼자 집어 먹을 수 있는 쉬운 핑거 푸드 목록을 요청하세요.', title_nl = 'Wat moet ik koken? 🍲', body_nl = 'Geen ideeën meer voor het menu rond de eerste verjaardag? Vraag Anacan AI om een lijst met makkelijk vingervoedsel dat je kindje zelf kan pakken en eten.', title_pl = 'Co ugotować? 🍲', body_pl = 'Kończą ci się pomysły na jadłospis przed roczkiem? Poproś Anacan AI o listę łatwych przekąsek, które maluszek sam chwyci i zje.', title_pt = 'O dilema do que cozinhar 🍲', body_pt = 'Ficou sem ideias para a ementa perto do 1.º ano? Peça ao Anacan AI uma lista de alimentos fáceis que ele possa pegar e comer sozinho.', title_sv = 'Vad ska jag laga? 🍲', body_sv = 'Har idéerna till menyn inför 1-årsdagen tagit slut? Be Anacan AI om en lista med enkel fingermat som barnet kan hålla i och äta själv.', title_vi = 'Nỗi lo "nấu gì đây" 🍲', body_vi = 'Cạn ý tưởng cho thực đơn khi bé gần 1 tuổi? Hãy nhờ Anacan AI gợi ý danh sách món ăn cầm tay dễ làm để bé tự cầm ăn.', title_zh = '“做什么吃”的烦恼 🍲', body_zh = '快1岁了，菜单想不出新花样？向Anacan AI要一份宝宝能自己拿着吃的简单手指食物清单吧。' WHERE id = '3beff563-1e72-4a1f-8490-4e977c8b0b7a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hacerse amigo de la oscuridad 🌙', body_es = 'Para que se duerma antes, añade la oscuridad a la rutina de la noche. Apaga todas las luces que sobran y las pantallas de la habitación.', title_fr = 'Apprivoiser l''obscurité 🌙', body_fr = 'Pour l''aider à s''endormir plus vite, ajoutez l''obscurité à la routine du soir. Éteignez toutes les lumières superflues et les écrans de la pièce.', title_hi = 'अँधेरे से दोस्ती 🌙', body_hi = 'उसे जल्दी सुलाने के लिए शाम के रूटीन में अँधेरा जोड़िए। कमरे की सारी अतिरिक्त लाइटें और स्क्रीन बंद कीजिए।', title_id = 'Bersahabat dengan gelap 🌙', body_id = 'Agar ia lebih cepat tertidur, tambahkan suasana gelap dalam rutinitas malam. Matikan semua lampu tambahan dan layar di kamar.', title_ja = '暗さと仲よしに 🌙', body_ja = '早く寝つけるように、夜のルーティンに暗さを取り入れましょう。部屋のよけいな明かりや画面はすべて消しましょう。', title_ko = '어둠과 친해지기 🌙', body_ko = '빨리 잠들 수 있도록 저녁 루틴에 어둠을 더하세요. 방의 불필요한 조명과 화면을 모두 끄세요.', title_nl = 'Vriendschap met het donker 🌙', body_nl = 'Voeg donker toe aan de avondroutine, zodat je baby sneller in slaap valt. Doe alle extra lampjes en schermen in de kamer uit.', title_pl = 'Przyjaźń z ciemnością 🌙', body_pl = 'Aby szybciej zasypiał, dodaj do wieczornej rutyny ciemność. Wyłącz w pokoju wszystkie dodatkowe światła i ekrany.', title_pt = 'Fazer amizade com o escuro 🌙', body_pt = 'Para o ajudar a adormecer mais depressa, junte o escuro à rotina da noite. Apague todas as luzes desnecessárias e os ecrãs do quarto.', title_sv = 'Vänskap med mörkret 🌙', body_sv = 'Lägg till mörker i kvällsrutinen så att barnet somnar fortare. Släck alla onödiga lampor och skärmar i rummet.', title_vi = 'Làm bạn với bóng tối 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy thêm bóng tối vào nếp sinh hoạt buổi tối. Tắt hết đèn và màn hình không cần thiết trong phòng.', title_zh = '和黑暗做朋友 🌙', body_zh = '为了让宝宝更快入睡，在晚间作息里加入黑暗环节。关掉房间里所有多余的灯和屏幕。' WHERE id = 'eebfea92-7f8e-43d7-a45c-4a10e720b24c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Se une a la conversación 🗣️', body_es = '¿Mientras hablas, él también dice algo en su idioma y sube la voz? Su capacidad de comunicación se acelera, hay un segundo locutor en la habitación, ¡escúchale!', title_fr = 'Il se joint à la conversation 🗣️', body_fr = 'Quand vous parlez, il se met lui aussi à dire quelque chose dans sa langue en haussant la voix ? Ses capacités de communication s''accélèrent, il y a un deuxième orateur dans la pièce, écoutez-le bien !', title_hi = 'बातचीत में शामिल होता है 🗣️', body_hi = 'आप बात करती हैं तो वह भी अपनी भाषा में कुछ कहकर आवाज़ ऊँची करता है? बातचीत की क्षमता तेज़ी से बढ़ रही है, कमरे में एक दूसरा वक्ता भी है, उसे ज़रूर सुनिए!', title_id = 'Ikut mengobrol 🗣️', body_id = 'Saat Anda berbicara, ia juga mengucapkan sesuatu dengan bahasanya sambil mengeraskan suara? Kemampuan komunikasinya melesat, ada pembicara kedua di ruangan, dengarkan baik-baik!', title_ja = '会話に参加 🗣️', body_ja = 'あなたが話していると、赤ちゃんも自分の言葉で何か言って声を大きくしますか？コミュニケーション力がぐんぐん育っています。部屋にもうひとりスピーカーがいます。ぜひ聞いてあげて！', title_ko = '대화에 끼어들어요 🗣️', body_ko = '엄마가 말할 때 아기도 자기 말로 뭔가를 크게 말하나요? 소통 능력이 빠르게 자라고 있어요, 방 안에 두 번째 스피커가 생겼으니 꼭 들어 주세요!', title_nl = 'Hij praat mee 🗣️', body_nl = 'Zegt je baby in zijn eigen taal iets en praat hij harder als jij aan het praten bent? Zijn communicatievaardigheden gaan snel vooruit, er is een tweede spreker in de kamer, luister zeker naar hem!', title_pl = 'Włącza się do rozmowy 🗣️', body_pl = 'Gdy mówisz, on też coś mówi w swoim języku i podnosi głos? Umiejętności komunikacyjne przyspieszają, w pokoju jest drugi spiker, koniecznie go posłuchaj!', title_pt = 'Entra na conversa 🗣️', body_pt = 'Enquanto fala, ele também diz qualquer coisa na sua língua e levanta a voz? A capacidade de comunicação acelera: há um segundo orador no quarto, ouça-o sem falta!', title_sv = 'Barnet hänger med i samtalet 🗣️', body_sv = 'Säger barnet något på sitt eget språk och höjer rösten när du pratar? Kommunikationsförmågan tar fart, det finns en andra talare i rummet, lyssna absolut på den!', title_vi = 'Bé tham gia trò chuyện 🗣️', body_vi = 'Khi mẹ nói chuyện, bé cũng nói gì đó bằng ngôn ngữ riêng và lên giọng? Kỹ năng giao tiếp đang tăng tốc, trong phòng có thêm một "diễn giả" nữa, nhất định hãy lắng nghe bé nhé!', title_zh = '加入聊天 🗣️', body_zh = '你说话时，宝宝也用自己的语言大声说着什么？沟通能力突飞猛进，房间里多了一位“发言人”，一定要好好听听！' WHERE id = 'f8f9e691-e184-414d-9abe-ae0a3969929a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Intentos de comer con su propia cuchara! 🥄', body_es = '¿Ya intenta coger la cuchara y llevársela a la boca? Para apoyar estos momentos tan divertidos, elige alimentos adecuados en la sección para bebés que empiezan con la alimentación complementaria.', title_fr = 'Il essaie de manger avec sa cuillère ! 🥄', body_fr = 'Il essaie déjà de tenir la cuillère et de la porter à sa bouche ? Pour encourager ces moments amusants, choisissez des aliments adaptés dans la rubrique Bébés qui commencent la diversification.', title_hi = 'अपने चम्मच से खाने की कोशिश! 🥄', body_hi = 'वह अब चम्मच पकड़कर मुँह तक ले जाने की कोशिश करता है? इन मज़ेदार पलों का साथ देने के लिए ऊपरी आहार शुरू करने वाले बच्चों वाले सेक्शन से सही खाना चुनिए।', title_id = 'Mencoba makan dengan sendoknya sendiri! 🥄', body_id = 'Ia sudah mencoba memegang sendok dan memasukkannya ke mulut? Untuk mendukung momen seru ini, pilih makanan yang cocok dari bagian Bayi yang Mulai MPASI.', title_ja = '自分のスプーンで食べる挑戦！🥄', body_ja = 'もうスプーンを持って口に運ぼうとしていますか？この楽しい瞬間を応援するために、「離乳食を始める赤ちゃん」から合う食べ物を選びましょう。', title_ko = '내 숟가락으로 먹어 보기! 🥄', body_ko = '이제 숟가락을 잡고 입으로 가져가려 하나요? 이 즐거운 순간을 돕기 위해 이유식을 시작하는 아기 섹션에서 알맞은 음식을 골라 보세요.', title_nl = 'Pogingen om met zijn eigen lepel te eten! 🥄', body_nl = 'Probeert je baby al de lepel vast te pakken en naar zijn mond te brengen? Kies passend eten uit Baby''s die met bijvoeding beginnen om deze leuke momenten te ondersteunen.', title_pl = 'Próby jedzenia własną łyżeczką! 🥄', body_pl = 'Próbuje już trzymać łyżeczkę i wkładać ją do buzi? Aby wspierać te zabawne chwile, wybierz odpowiednie dania z sekcji dla maluszków zaczynających rozszerzanie diety.', title_pt = 'Tentativas de comer com a própria colher! 🥄', body_pt = 'Já tenta pegar na colher e levá-la à boca? Para apoiar estes momentos divertidos, escolha alimentos adequados na secção para bebés em diversificação alimentar.', title_sv = 'Försök att äta med egen sked! 🥄', body_sv = 'Försöker barnet redan hålla skeden och föra den till munnen? Välj passande mat i avsnittet för barn som börjar med smakportioner för att stötta de här roliga stunderna.', title_vi = 'Tập tự xúc ăn bằng thìa! 🥄', body_vi = 'Bé đã cố cầm thìa và đưa lên miệng? Để hỗ trợ những khoảnh khắc vui nhộn này, hãy chọn món phù hợp từ mục Cho bé bắt đầu ăn dặm.', title_zh = '尝试用自己的勺子吃饭！🥄', body_zh = '宝宝已经想自己拿着勺子往嘴里送了？为了支持这些有趣的时刻，从“辅食宝宝”板块挑选合适的食物吧。' WHERE id = '20db1e8e-1980-431d-800c-b7aa4ccf158b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirse con un cuento 🪄', body_es = 'Crea en Cuentos inteligentes un fondo especial solo con música y sonidos de la naturaleza. Sin palabras, solo calma.', title_fr = 'S''endormir avec un conte 🪄', body_fr = 'Dans les Contes intelligents, créez une ambiance sonore spéciale faite uniquement de musique et de sons de la nature. Pas de mots, seulement la sérénité.', title_hi = 'कहानी के साथ नींद की ओर 🪄', body_hi = 'स्मार्ट कहानियों में सिर्फ़ संगीत और प्रकृति की आवाज़ों से एक खास पृष्ठभूमि बनाइए। कोई शब्द नहीं, बस सुकून।', title_id = 'Menuju tidur bersama dongeng 🪄', body_id = 'Di Dongeng Pintar, buat latar khusus yang hanya berisi musik dan suara alam. Tanpa kata-kata, hanya ketenangan.', title_ja = 'お話でねんねへ 🪄', body_ja = '「スマートおはなし」で、音楽と自然の音だけの特別なBGMをつくりましょう。言葉はなく、ただやすらぎがあるだけ。', title_ko = '동화와 함께 꿈나라로 🪄', body_ko = '스마트 동화에서 음악과 자연의 소리로만 이루어진 특별한 배경을 만들어 보세요. 말은 없고, 오직 평온함만 있어요.', title_nl = 'Met een sprookje naar dromenland 🪄', body_nl = 'Maak in Slimme sprookjes een speciale achtergrond van alleen muziek en natuurgeluiden. Geen woorden, alleen rust.', title_pl = 'Zasypianie z bajką 🪄', body_pl = 'Stwórz w Mądrych bajkach specjalne tło tylko z muzyki i odgłosów natury. Bez słów, sam spokój.', title_pt = 'Adormecer com uma história 🪄', body_pt = 'Crie nas Histórias Inteligentes um fundo especial feito só de música e sons da natureza. Sem palavras, só calma.', title_sv = 'Somna till en saga 🪄', body_sv = 'Skapa en speciell bakgrund i Smarta sagor med bara musik och naturljud. Inga ord, bara ro.', title_vi = 'Vào giấc cùng truyện cổ tích 🪄', body_vi = 'Hãy tạo trong Truyện cổ tích thông minh một bản nền đặc biệt chỉ gồm âm nhạc và âm thanh thiên nhiên. Không lời, chỉ có sự bình yên.', title_zh = '听着故事入睡 🪄', body_zh = '在智能故事里创作一段只有音乐和大自然声音的特别背景音。没有文字，只有宁静。' WHERE id = '77cedc71-0d6f-45f7-a8a4-9ddfcd0a5be6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Besos llenos de amor 🥰', body_es = '¿Cuando le das un beso, se inclina hacia ti con los labios estirados o te deja la mejilla mojada? Sus besitos tienen la fuerza de borrar todo tu cansancio.', title_fr = 'Des bisous pleins d''amour 🥰', body_fr = 'Quand vous l''embrassez, il se penche vers vous en tendant les lèvres ou vous mouille la joue ? Ses petits bisous sont assez puissants pour effacer toute votre fatigue.', title_hi = 'प्यार भरी पप्पियाँ 🥰', body_hi = 'आप चूमती हैं तो वह भी आपकी ओर झुककर होंठ आगे करता है या आपका गाल गीला कर देता है? उसकी नन्ही पप्पियाँ आपकी सारी थकान मिटाने के लिए काफ़ी हैं।', title_id = 'Ciuman penuh cinta 🥰', body_id = 'Saat Anda menciumnya, ia ikut condong dan memonyongkan bibir atau membasahi pipi Anda? Ciuman kecilnya cukup kuat untuk menghapus semua rasa lelah Anda.', title_ja = '愛情たっぷりのキス 🥰', body_ja = 'あなたがキスをすると、赤ちゃんも顔を寄せて唇をとがらせたり、ほっぺをぬらしたりしますか？その小さなキスには、疲れをぜんぶ消してくれる力があります。', title_ko = '사랑 가득한 뽀뽀 🥰', body_ko = '엄마가 뽀뽀하면 아기도 몸을 기울여 입술을 내밀거나 볼을 촉촉하게 적시나요? 그 작은 뽀뽀는 모든 피로를 씻어 낼 만큼 강력해요.', title_nl = 'Kusjes vol liefde 🥰', body_nl = 'Buigt je baby zich naar je toe met getuite lipjes of geeft hij je een natte wang als je hem kust? Zijn kleine kusjes zijn sterk genoeg om al je vermoeidheid weg te vegen.', title_pl = 'Buziaki pełne miłości 🥰', body_pl = 'Gdy go całujesz, nachyla się do ciebie i wydyma usteczka albo mokro całuje cię w policzek? Jego małe buziaki mają moc, by zetrzeć całe twoje zmęczenie.', title_pt = 'Beijinhos cheios de amor 🥰', body_pt = 'Quando lhe dá um beijo, ele inclina-se para si e estica os lábios ou molha-lhe a bochecha? Os seus beijinhos são tão fortes que apagam todo o cansaço.', title_sv = 'Kärleksfulla pussar 🥰', body_sv = 'Lutar sig barnet fram och spetsar munnen eller blöter ner din kind när du pussar det? De små pussarna är starka nog att sudda ut all din trötthet.', title_vi = 'Những nụ hôn đầy yêu thương 🥰', body_vi = 'Khi mẹ hôn, bé cũng nghiêng người chu môi hay hôn ướt má mẹ? Những nụ hôn nhỏ xíu ấy đủ sức xóa tan mọi mệt mỏi của mẹ.', title_zh = '充满爱的亲亲 🥰', body_zh = '你亲宝宝时，宝宝也凑过来噘起小嘴，或者在你脸上留下湿湿的一吻？宝宝的小小亲亲足以抹去你所有的疲惫。' WHERE id = 'eca3e78d-00de-4e77-bade-43808f152e4f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las caras graciosas de papá 🤡', body_es = 'La mejor forma de hacer reír al bebé es que papá haga ruidos raros. Disfrutad juntos con tu peque de los momentos alegres de esta noche.', title_fr = 'Les grimaces de papa 🤡', body_fr = 'Le meilleur moyen de faire rire bébé, ce sont les bruits bizarres de papa. Savourez ensemble ces joyeux moments du soir.', title_hi = 'पापा के मज़ेदार चेहरे 🤡', body_hi = 'बच्चे को हँसाने का सबसे अच्छा तरीका है पापा की अजीब आवाज़ें। आज शाम के खुशी भरे पलों का बच्चे के साथ मिलकर आनंद लीजिए।', title_id = 'Wajah lucu ayah 🤡', body_id = 'Cara terbaik membuat bayi tertawa adalah suara-suara aneh dari ayah. Nikmati momen ceria malam ini bersama si kecil.', title_ja = 'パパのおもしろい顔 🤡', body_ja = '赤ちゃんを笑わせるいちばんの方法は、パパが変な声を出すこと。今夜の楽しい瞬間を、赤ちゃんと一緒に味わいましょう。', title_ko = '아빠의 웃긴 표정 🤡', body_ko = '아기를 웃게 하는 가장 좋은 방법은 아빠의 이상한 소리예요. 오늘 저녁의 즐거운 순간을 아이와 함께 마음껏 누리세요.', title_nl = 'Papa''s gekke bekken 🤡', body_nl = 'De beste manier om je baby aan het lachen te krijgen: papa die rare geluiden maakt. Geniet vanavond samen met je kindje van deze vrolijke momenten.', title_pl = 'Śmieszne miny taty 🤡', body_pl = 'Najlepszy sposób, by rozśmieszyć maluszka, to dziwne dźwięki taty. Ciesz się razem z maluszkiem dzisiejszymi wesołymi chwilami.', title_pt = 'As caretas do pai 🤡', body_pt = 'A melhor forma de fazer o bebé rir é o pai fazer sons estranhos. Aproveite com o bebé os momentos alegres desta noite.', title_sv = 'Pappas roliga miner 🤡', body_sv = 'Det bästa sättet att få barnet att skratta är när pappa gör konstiga ljud. Njut av kvällens glada stunder tillsammans med barnet.', title_vi = 'Những gương mặt hài hước của bố 🤡', body_vi = 'Cách tốt nhất để bé cười là bố tạo ra những âm thanh kỳ lạ. Hãy cùng bé tận hưởng những khoảnh khắc vui vẻ tối nay.', title_zh = '爸爸的鬼脸 🤡', body_zh = '逗宝宝笑最好的办法就是爸爸发出怪声。今晚和宝宝一起尽情享受这些欢乐的时刻吧。' WHERE id = '863a6afb-427b-4143-a527-2e01fe303116' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hace falta desahogarse 💬', body_es = '¿Te emociona pensar «no me puedo creer que ya vaya a cumplir 1 año»? Comparte este sentimiento tan bonito con las mamás de la Comunidad Anacan.', title_fr = 'Besoin de vous confier 💬', body_fr = 'Penser « Je n''arrive pas à croire qu''il a déjà 1 an » vous émeut ? Partagez ce beau sentiment avec les mamans de la Communauté Anacan.', title_hi = 'दिल की बात करना ज़रूरी है 💬', body_hi = '''यकीन नहीं होता कि वह 1 साल का हो गया'' यह सोचकर भावुक हो जाती हैं? Anacan कम्युनिटी की माँओं के साथ यह प्यारा एहसास बाँटिए।', title_id = 'Butuh teman bercerita 💬', body_id = 'Pikiran "Aku tak percaya ia sudah 1 tahun" membuat Anda terharu? Bagikan perasaan indah ini dengan para ibu di Komunitas Anacan.', title_ja = '話すことが必要なとき 💬', body_ja = '「もう1歳になるなんて信じられない」と思うと胸がいっぱいになりますか？Anacanコミュニティのママたちと、このすてきな気持ちを分かち合いましょう。', title_ko = '마음을 나눌 시간 💬', body_ko = '''벌써 첫돌이라니 믿기지 않아''라는 생각에 마음이 뭉클한가요? Anacan 커뮤니티의 엄마들과 이 아름다운 마음을 나눠 보세요.', title_nl = 'Even je hart luchten 💬', body_nl = 'Word je emotioneel van de gedachte: ik kan niet geloven dat hij al 1 jaar is? Deel dit mooie gevoel met de moeders in de Anacan Community.', title_pl = 'Czas się wygadać 💬', body_pl = 'Wzrusza cię myśl „nie mogę uwierzyć, że ma już roczek”? Podziel się tym pięknym uczuciem z mamami w Społeczności Anacan.', title_pt = 'Precisa de desabafar 💬', body_pt = 'O pensamento "nem acredito que já vai fazer 1 ano" deixa-a emocionada? Partilhe este sentimento bonito com as mães da Comunidade Anacan.', title_sv = 'Ibland behöver man prata av sig 💬', body_sv = 'Blir du känslosam av tanken ''jag kan inte fatta att barnet redan är 1 år''? Dela den här fina känslan med mammorna i Anacans Community.', title_vi = 'Cần được tâm sự 💬', body_vi = 'Ý nghĩ "Không thể tin là bé đã 1 tuổi rồi" khiến mẹ xúc động? Hãy chia sẻ cảm xúc đẹp đẽ này với các bà mẹ trong Cộng đồng Anacan.', title_zh = '需要倾诉一下 💬', body_zh = '“真不敢相信宝宝都1岁了”，这个念头让你心里软软的？和Anacan社区的妈妈们分享这份美好的感受吧。' WHERE id = 'b4676fcf-2967-4b49-adbd-12ebe6a54334' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Noches difíciles 🥱', body_es = '¿Se resiste con todas sus fuerzas a dormirse? Quizá haya llegado el momento de quitar una de las siestas de día. Revisa la rutina.', title_fr = 'Des nuits difficiles 🥱', body_fr = 'Il résiste de toutes ses forces pour ne pas s''endormir ? Il est peut-être temps de supprimer une de ses siestes. Vérifiez la routine.', title_hi = 'ज़िद्दी रातें 🥱', body_hi = 'सोने से बचने के लिए पूरी ताकत से विरोध करता है? शायद दिन की एक झपकी कम करने का समय आ गया है। रूटीन जाँचिए।', title_id = 'Malam-malam yang alot 🥱', body_id = 'Ia melawan sekuat tenaga agar tidak tertidur? Mungkin sudah waktunya mengurangi satu kali tidur siang. Periksa rutinitasnya.', title_ja = '手ごわい夜 🥱', body_ja = '眠るまいと全力で抵抗していますか？お昼寝を1回減らすときがきたのかもしれません。ルーティンを見直しましょう。', title_ko = '고집스러운 밤 🥱', body_ko = '잠들지 않으려고 온 힘을 다해 버티나요? 낮잠 한 번을 줄일 때가 됐을 수도 있어요. 루틴을 점검해 보세요.', title_nl = 'Koppige nachten 🥱', body_nl = 'Verzet je baby zich met alle macht tegen het slapengaan? Misschien is het tijd om een van de dutjes overdag te schrappen. Bekijk de routine.', title_pl = 'Uparte noce 🥱', body_pl = 'Z całych sił opiera się zasypianiu? Może nadszedł czas, by zrezygnować z jednej drzemki w ciągu dnia. Sprawdź rutynę.', title_pt = 'Noites teimosas 🥱', body_pt = 'Resiste com todas as forças a adormecer? Pode ter chegado a altura de cortar uma das sestas do dia. Reveja a rotina.', title_sv = 'Envisa nätter 🥱', body_sv = 'Kämpar barnet emot med all kraft för att inte somna? Det kan vara dags att ta bort en av dagsluren. Se över rutinen.', title_vi = 'Những đêm bướng bỉnh 🥱', body_vi = 'Bé dồn hết sức để chống lại giấc ngủ? Có lẽ đã đến lúc bớt đi một giấc ngủ ngày. Hãy xem lại nếp sinh hoạt.', title_zh = '倔强的夜晚 🥱', body_zh = '宝宝用尽全力抗拒睡觉？可能是时候减掉一次白天小睡了。检查一下作息吧。' WHERE id = '222d12a8-4347-4dce-afd7-4a0890721d0b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Revisemos la talla y el peso! 📏', body_es = 'Falta poco para la revisión del primer año. Actualiza los últimos datos en la sección Seguimiento del desarrollo, mira su gráfica de crecimiento sano y siéntete orgullosa.', title_fr = 'Vérifions la taille et le poids ! 📏', body_fr = 'La visite des 1 an approche. Mettez à jour les dernières données dans le Suivi de développement, regardez sa courbe de croissance et soyez fière.', title_hi = 'लंबाई और वज़न की बढ़त देखें! 📏', body_hi = '1 साल की जाँच में थोड़ा ही समय बचा है। ग्रोथ ट्रैकर सेक्शन में ताज़ा जानकारी अपडेट कीजिए, सेहतमंद विकास का चार्ट देखिए और गर्व महसूस कीजिए।', title_id = 'Yuk cek pertambahan tinggi dan berat badan! 📏', body_id = 'Pemeriksaan 1 tahun sudah dekat. Perbarui data terbaru di Pelacak Perkembangan, lalu lihat grafik pertumbuhan sehatnya dan rasakan bangganya.', title_ja = '身長と体重の伸びをチェック！📏', body_ja = '1歳健診がもうすぐです。「発達トラッカー」で最新の記録を更新して、健やかな成長グラフを見て誇らしい気持ちになりましょう。', title_ko = '키와 몸무게를 확인해요! 📏', body_ko = '첫돌 검진이 얼마 남지 않았어요. 성장 기록 섹션에서 최근 정보를 업데이트하고 건강한 성장 그래프를 보며 뿌듯함을 느껴 보세요.', title_nl = 'Laten we de groei in lengte en gewicht bekijken! 📏', body_nl = 'De controle bij 1 jaar komt eraan. Werk de laatste gegevens bij in de Groeitracker, bekijk de gezonde groeicurve en wees trots.', title_pl = 'Sprawdźmy wzrost i wagę! 📏', body_pl = 'Zbliża się wizyta kontrolna na roczek. Zaktualizuj najnowsze dane w sekcji Śledzenie rozwoju, spójrz na zdrowy wykres rozwoju i bądź dumna.', title_pt = 'Vamos ver a altura e o peso! 📏', body_pt = 'Falta pouco para a consulta do 1.º ano. Atualize os últimos dados no Registo de Desenvolvimento, veja o gráfico de crescimento saudável e orgulhe-se.', title_sv = 'Vi kollar längd och vikt! 📏', body_sv = 'Det är inte långt kvar till 1-årskontrollen. Uppdatera de senaste uppgifterna i Utvecklingsspåraren, titta på den sunda utvecklingskurvan och känn dig stolt.', title_vi = 'Cùng kiểm tra chiều cao và cân nặng! 📏', body_vi = 'Sắp đến buổi khám 1 tuổi rồi. Hãy cập nhật thông tin mới nhất trong mục Theo dõi phát triển, rồi ngắm biểu đồ phát triển khỏe mạnh của bé và tự hào nhé.', title_zh = '来看看身高体重的增长吧！📏', body_zh = '一周岁体检快到了。在发育追踪板块更新最新数据，看看宝宝健康的成长曲线，为宝宝骄傲吧。' WHERE id = '5047e51c-64dc-4fe5-bc38-0409a743d0f6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La torre de comida se ha caído 🥣', body_es = '¿Tira a propósito la cuchara al suelo y te mira? Está poniendo a prueba la gravedad y tu reacción. Conserva la paciencia, es una forma de juego.', title_fr = 'La tour de nourriture s''est effondrée 🥣', body_fr = 'Il jette exprès sa cuillère par terre et vous regarde ? Il teste la gravité et votre réaction. Gardez votre patience, c''est une forme de jeu.', title_hi = 'खाने की मीनार गिर गई 🥣', body_hi = 'चम्मच जानबूझकर नीचे गिराकर आपको देखता है? वह गुरुत्वाकर्षण और आपकी प्रतिक्रिया परख रहा है। धैर्य रखिए, यह एक तरह का खेल है।', title_id = 'Menara makanan runtuh 🥣', body_id = 'Ia sengaja menjatuhkan sendok lalu menatap Anda? Ia sedang menguji gravitasi dan reaksi Anda. Jaga kesabaran Anda, ini salah satu bentuk permainan.', title_ja = 'ごはんのタワーがくずれた 🥣', body_ja = 'スプーンをわざと落として、あなたを見ますか？重力とあなたの反応をテストしているのです。がまん強くいきましょう、これも遊びのひとつです。', title_ko = '음식 탑이 무너졌어요 🥣', body_ko = '숟가락을 일부러 떨어뜨리고 엄마를 바라보나요? 중력과 엄마의 반응을 시험하는 중이에요. 인내심을 지켜 주세요, 이것도 놀이예요.', title_nl = 'De eettoren is ingestort 🥣', body_nl = 'Gooit je baby zijn lepel expres op de grond en kijkt hij je dan aan? Hij test de zwaartekracht en jouw reactie. Bewaar je geduld, dit is een soort spelletje.', title_pl = 'Wieża z jedzenia runęła 🥣', body_pl = 'Celowo rzuca łyżeczkę na podłogę i patrzy na ciebie? Testuje grawitację i twoją reakcję. Zachowaj cierpliwość, to taki rodzaj zabawy.', title_pt = 'A torre de comida caiu 🥣', body_pt = 'Atira de propósito a colher ao chão e olha para si? Está a testar a gravidade e a sua reação. Mantenha a paciência, é uma forma de brincar.', title_sv = 'Mattornet rasade 🥣', body_sv = 'Släpper barnet med flit skeden på golvet och tittar på dig? Det testar tyngdkraften och din reaktion. Behåll ditt tålamod, det är en sorts lek.', title_vi = 'Tháp đồ ăn sụp đổ 🥣', body_vi = 'Bé cố tình ném thìa xuống đất rồi nhìn mẹ? Bé đang thử lực hấp dẫn và phản ứng của mẹ. Hãy giữ bình tĩnh, đây cũng là một kiểu trò chơi.', title_zh = '食物高塔倒啦 🥣', body_zh = '宝宝故意把勺子扔到地上再看着你？宝宝在测试重力和你的反应。保持耐心，这也是一种游戏。' WHERE id = '873f2996-36df-4d67-a2df-ec60f668be2f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hoy en Cuentos inteligentes 🪄', body_es = 'Crea en Cuentos inteligentes una historia especial cuyo protagonista sea tu propio peque.', title_fr = 'Aujourd''hui dans les Contes intelligents 🪄', body_fr = 'Dans les Contes intelligents, créez une histoire spéciale dont le héros est votre enfant.', title_hi = 'आज स्मार्ट कहानियों में 🪄', body_hi = 'स्मार्ट कहानियों में एक खास कहानी बनाइए जिसका हीरो आपका अपना बच्चा हो।', title_id = 'Hari ini di Dongeng Pintar 🪄', body_id = 'Di Dongeng Pintar, buat kisah istimewa dengan anak Anda sendiri sebagai pahlawannya.', title_ja = '今日の「スマートおはなし」🪄', body_ja = '「スマートおはなし」で、あなたの赤ちゃんが主人公の特別なお話をつくりましょう。', title_ko = '오늘의 스마트 동화 🪄', body_ko = '스마트 동화에서 우리 아이가 주인공인 특별한 이야기를 만들어 보세요.', title_nl = 'Vandaag in Slimme sprookjes 🪄', body_nl = 'Maak in Slimme sprookjes een speciaal verhaal met je eigen kindje als held.', title_pl = 'Dziś w Mądrych bajkach 🪄', body_pl = 'Stwórz w Mądrych bajkach wyjątkową historię, której bohaterem jest twoje dziecko.', title_pt = 'Hoje nas Histórias Inteligentes 🪄', body_pt = 'Crie nas Histórias Inteligentes uma história especial em que o herói é o seu próprio filho.', title_sv = 'I dag i Smarta sagor 🪄', body_sv = 'Skapa en speciell saga i Smarta sagor där ditt eget barn är hjälten.', title_vi = 'Hôm nay trong Truyện cổ tích thông minh 🪄', body_vi = 'Hãy tạo một câu chuyện đặc biệt trong Truyện cổ tích thông minh với nhân vật chính là chính bé nhà mình.', title_zh = '今天的智能故事 🪄', body_zh = '在智能故事里创作一个以你的宝宝为主角的特别故事吧。' WHERE id = '8cd57628-b75f-4445-8bc9-6b180e6572dc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Limpiar o descansar? 🛋️', body_es = 'Cuando tu bebé duerma, no corras al lavavajillas. Túmbate en el sofá, cierra los ojos y simplemente respira durante 15 minutos. ¿Eres un robot? No.', title_fr = 'Ménage ou repos ? 🛋️', body_fr = 'Quand bébé dort, ne courez pas vers le lave-vaisselle. Allongez-vous sur le canapé, fermez les yeux et respirez simplement pendant 15 minutes. Êtes-vous un robot ? Non.', title_hi = 'सफ़ाई या आराम? 🛋️', body_hi = 'बच्चे के सोते ही डिशवॉशर की ओर मत भागिए। सोफ़े पर लेट जाइए, आँखें बंद कीजिए और 15 मिनट बस साँस लीजिए। क्या आप रोबोट हैं? नहीं।', title_id = 'Bersih-bersih atau istirahat? 🛋️', body_id = 'Saat si kecil tidur, jangan buru-buru ke mesin cuci piring. Berbaringlah di sofa, pejamkan mata, dan cukup bernapas selama 15 menit. Apakah Anda robot? Bukan.', title_ja = 'お掃除？それとも休憩？🛋️', body_ja = '赤ちゃんが寝ても、食洗機に走らないで。ソファに横になって目を閉じ、15分間ただ呼吸しましょう。あなたはロボット？いいえ。', title_ko = '청소할까요, 쉴까요? 🛋️', body_ko = '아이가 잘 때 식기세척기로 달려가지 마세요. 소파에 누워 눈을 감고 15분 동안 숨만 쉬세요. 당신이 로봇인가요? 아니에요.', title_nl = 'Schoonmaken of uitrusten? 🛋️', body_nl = 'Ren niet naar de vaatwasser als je baby slaapt. Ga op de bank liggen, sluit je ogen en adem 15 minuten gewoon. Ben je een robot? Nee.', title_pl = 'Sprzątać czy odpocząć? 🛋️', body_pl = 'Gdy maluszek śpi, nie biegnij do zmywarki. Połóż się na kanapie, zamknij oczy i przez 15 minut po prostu oddychaj. Jesteś robotem? Nie.', title_pt = 'Limpar ou descansar? 🛋️', body_pt = 'Quando o bebé dorme, não corra para a máquina da loiça. Deite-se no sofá, feche os olhos e simplesmente respire durante 15 minutos. É um robô? Não.', title_sv = 'Städa eller vila? 🛋️', body_sv = 'Rusa inte till diskmaskinen när barnet sover. Lägg dig i soffan, blunda och bara andas i 15 minuter. Är du en robot? Nej.', title_vi = 'Dọn dẹp hay nghỉ ngơi? 🛋️', body_vi = 'Bé vừa ngủ thì đừng vội lao đến máy rửa bát. Hãy nằm xuống sofa, nhắm mắt lại và chỉ hít thở trong 15 phút. Mẹ là robot sao? Không phải.', title_zh = '打扫还是休息？🛋️', body_zh = '宝宝睡着时别急着去洗碗机那边。躺在沙发上，闭上眼睛，呼吸15分钟就好。你是机器人吗？不是。' WHERE id = '94b60a89-bc34-41d8-818c-174aa7ed663b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Detective de armarios 🕵️‍♀️', body_es = '¿Todas las ollas de la cocina están en el suelo? Jugar con objetos inofensivos desarrolla su pensamiento lógico. Deja que busque tesoros con libertad.', title_fr = 'La détective des placards 🕵️‍♀️', body_fr = 'Toutes les casseroles de la cuisine sont par terre ? Jouer avec des objets sans danger développe sa pensée logique. Laissez-le chercher librement ses trésors.', title_hi = 'अलमारी का जासूस 🕵️‍♀️', body_hi = 'रसोई के सारे बर्तन फ़र्श पर हैं? सुरक्षित चीज़ों से खेलना उसकी तार्किक सोच बढ़ाता है। उसे आज़ादी से खज़ाना खोजने दीजिए।', title_id = 'Detektif lemari 🕵️‍♀️', body_id = 'Semua panci di dapur berserakan di lantai? Bermain dengan benda yang aman mengembangkan kemampuan berpikir logisnya. Biarkan ia bebas berburu harta karun.', title_ja = '戸棚の探偵 🕵️‍♀️', body_ja = 'キッチンの鍋がぜんぶ床に？安全なもので遊ぶことは、論理的に考える力を育てます。自由に宝探しをさせてあげましょう。', title_ko = '수납장 탐정 🕵️‍♀️', body_ko = '주방의 냄비가 모두 바닥에 나와 있나요? 안전한 물건으로 노는 건 논리적 사고를 키워 줘요. 자유롭게 보물찾기를 하게 해 주세요.', title_nl = 'Kastdetective 🕵️‍♀️', body_nl = 'Liggen alle pannen uit de keuken op de vloer? Spelen met onschuldige spullen ontwikkelt zijn logisch denken. Laat hem vrij op schattenjacht gaan.', title_pl = 'Detektyw szafek 🕵️‍♀️', body_pl = 'Wszystkie garnki z kuchni na podłodze? Zabawa bezpiecznymi przedmiotami rozwija logiczne myślenie. Pozwól mu swobodnie szukać skarbów.', title_pt = 'Detetive dos armários 🕵️‍♀️', body_pt = 'Os tachos da cozinha estão todos no chão? Brincar com objetos inofensivos desenvolve o raciocínio lógico. Deixe-o caçar tesouros à vontade.', title_sv = 'Skåpsdetektiven 🕵️‍♀️', body_sv = 'Står alla kastruller från köket på golvet? Att leka med ofarliga saker utvecklar barnets logiska tänkande. Låt det fritt leta efter skatter.', title_vi = 'Thám tử tủ bếp 🕵️‍♀️', body_vi = 'Nồi niêu trong bếp nằm hết dưới sàn? Chơi với những đồ vật an toàn giúp phát triển tư duy logic. Cứ để bé thoải mái đi tìm "kho báu".', title_zh = '柜子侦探 🕵️‍♀️', body_zh = '厨房里的锅全到了地上？玩无害的物品能促进逻辑思维。让宝宝自由地去寻宝吧。' WHERE id = 'c7b84129-89ab-4610-b19f-84959d6194f9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un cuento especial 🪄', body_es = 'Crea en Cuentos inteligentes una historia especial cuyo protagonista sea tu propio peque.', title_fr = 'Un conte unique 🪄', body_fr = 'Dans les Contes intelligents, créez une histoire spéciale dont le héros est votre enfant.', title_hi = 'खास कहानी 🪄', body_hi = 'स्मार्ट कहानियों में एक खास कहानी बनाइए जिसका हीरो आपका अपना बच्चा हो।', title_id = 'Dongeng istimewa 🪄', body_id = 'Di Dongeng Pintar, buat kisah istimewa dengan anak Anda sendiri sebagai pahlawannya.', title_ja = '特別なお話 🪄', body_ja = '「スマートおはなし」で、あなたの赤ちゃんが主人公の特別なお話をつくりましょう。', title_ko = '특별한 동화 이야기 🪄', body_ko = '스마트 동화에서 우리 아이가 주인공인 특별한 이야기를 만들어 보세요.', title_nl = 'Een eigen sprookje 🪄', body_nl = 'Maak in Slimme sprookjes een speciaal verhaal met je eigen kindje als held.', title_pl = 'Wyjątkowa bajka 🪄', body_pl = 'Stwórz w Mądrych bajkach wyjątkową historię, której bohaterem jest twoje dziecko.', title_pt = 'Uma história especial 🪄', body_pt = 'Crie nas Histórias Inteligentes uma história especial em que o herói é o seu próprio filho.', title_sv = 'En personlig saga 🪄', body_sv = 'Skapa en speciell saga i Smarta sagor där ditt eget barn är hjälten.', title_vi = 'Câu chuyện cổ tích riêng 🪄', body_vi = 'Hãy tạo một câu chuyện đặc biệt trong Truyện cổ tích thông minh với nhân vật chính là chính bé nhà mình.', title_zh = '专属故事 🪄', body_zh = '在智能故事里创作一个以你的宝宝为主角的特别故事吧。' WHERE id = '3c7f679a-b11a-4f67-a3ae-5f350e93a451' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Complicidad entre mamás 💬', body_es = '¿Te agotan las preguntas como «por qué mi peque todavía no anda»? Entra en la Comunidad Anacan y verás que cada peque tiene su propio ritmo.', title_fr = 'Confidences entre mamans 💬', body_fr = 'Des questions comme « Pourquoi mon enfant ne marche-t-il toujours pas ? » vous épuisent ? Rejoignez la Communauté Anacan, vous verrez que chaque enfant a son propre rythme.', title_hi = 'माँओं का भरोसे का दायरा 💬', body_hi = '''मेरा बच्चा अभी तक क्यों नहीं चलता?'' जैसे सवाल आपको थका रहे हैं? Anacan कम्युनिटी में आइए, आप देखेंगी कि हर बच्चे की अपनी रफ़्तार होती है।', title_id = 'Teman curhat para ibu 💬', body_id = 'Lelah dengan pertanyaan seperti "Kenapa anakku belum juga berjalan?" Masuklah ke Komunitas Anacan, Anda akan melihat bahwa setiap anak punya temponya sendiri.', title_ja = 'ママたちの打ち明け話 💬', body_ja = '「どうしてうちの子はまだ歩かないの？」という疑問に疲れていませんか？Anacanコミュニティに参加すれば、どの子にもその子のペースがあるとわかります。', title_ko = '엄마들의 속마음 나누기 💬', body_ko = '''우리 아이는 왜 아직 안 걸을까?'' 같은 질문에 지쳤나요? Anacan 커뮤니티에 들어가 보면 아이마다 저마다의 속도가 있다는 걸 알게 될 거예요.', title_nl = 'Moeders onder elkaar 💬', body_nl = 'Word je moe van vragen als: waarom loopt mijn kindje nog niet? Ga naar de Anacan Community, dan zie je dat elk kind zijn eigen tempo heeft.', title_pl = 'Mamy powierniczki 💬', body_pl = 'Męczą cię pytania typu „dlaczego moje dziecko jeszcze nie chodzi?”. Zajrzyj do Społeczności Anacan, a zobaczysz, że każde dziecko ma swoje tempo.', title_pt = 'A cumplicidade das mães 💬', body_pt = 'Perguntas como "porque é que o meu bebé ainda não anda?" estão a cansá-la? Entre na Comunidade Anacan e vai ver que cada criança tem o seu ritmo.', title_sv = 'Mammornas förtroende 💬', body_sv = 'Tröttar frågor som ''varför går mitt barn fortfarande inte?'' ut dig? Gå in i Anacans Community, så ser du att varje barn har sitt eget tempo.', title_vi = 'Tâm sự giữa các bà mẹ 💬', body_vi = 'Những câu hỏi như "Sao con mình vẫn chưa biết đi?" làm mẹ mệt mỏi? Hãy vào Cộng đồng Anacan, mẹ sẽ thấy mỗi em bé đều có nhịp phát triển riêng.', title_zh = '妈妈们的知心话 💬', body_zh = '“我的宝宝为什么还不会走”这样的问题让你很累？进入Anacan社区，你会发现每个孩子都有自己的节奏。' WHERE id = '15436a4e-52bb-4539-9146-377403746da0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Eligiendo los primeros zapatos! 👟', body_es = '¡Los pasos van cada vez más rápido! No dejes de mirar nuestra lista de Productos recomendados para elegir sus primeros zapatos: ortopédicos, con suela blanda y que favorezcan el desarrollo del pie.', title_fr = 'Choisir ses premières chaussures ! 👟', body_fr = 'Les pas s''accélèrent ! Consultez absolument notre liste de Produits recommandés pour des premières chaussures orthopédiques à semelle souple qui soutiennent le développement de ses pieds.', title_hi = 'पहले जूतों का चुनाव! 👟', body_hi = 'कदम तेज़ हो रहे हैं! पैरों के विकास में मदद करने वाले, ऑर्थोपेडिक और नरम तलवे वाले पहले जूतों के लिए हमारी सुझाए गए प्रोडक्ट की सूची ज़रूर देखिए।', title_id = 'Memilih sepatu pertama! 👟', body_id = 'Langkahnya makin cepat! Pastikan melihat daftar Produk Rekomendasi kami untuk sepatu pertama yang ortopedis, bersol lembut, dan mendukung perkembangan kakinya.', title_ja = '初めての靴選び！👟', body_ja = '歩みがどんどん速くなっています！足の発達を支える、インソールがやわらかく形のしっかりした初めての靴は、「おすすめ商品」リストをぜひチェックしましょう。', title_ko = '첫 신발 고르기! 👟', body_ko = '걸음이 빨라지고 있어요! 발 발달을 돕는 편안하고 바닥이 부드러운 첫 신발은 추천 제품 목록에서 꼭 확인하세요.', title_nl = 'De eerste schoentjes kiezen! 👟', body_nl = 'De stapjes gaan sneller! Bekijk zeker in onze Aanbevolen producten de eerste orthopedische schoentjes met zachte zool die de ontwikkeling van zijn voetjes ondersteunen.', title_pl = 'Wybór pierwszych bucików! 👟', body_pl = 'Kroki są coraz szybsze! Koniecznie zajrzyj na naszą listę Polecanych produktów po pierwsze buciki z miękką podeszwą, ortopedyczne i wspierające rozwój stóp.', title_pt = 'A escolha dos primeiros sapatos! 👟', body_pt = 'Os passos estão a acelerar! Veja sem falta na nossa lista de Produtos Recomendados os primeiros sapatos ortopédicos e de sola macia que apoiam o desenvolvimento dos pés.', title_sv = 'Val av första skorna! 👟', body_sv = 'Stegen blir snabbare! Kika absolut i vår lista Rekommenderade produkter efter de första skorna, ortopediska och med mjuk sula, som stöttar fötternas utveckling.', title_vi = 'Chọn đôi giày đầu tiên! 👟', body_vi = 'Những bước đi đang nhanh hơn! Nhất định hãy xem danh sách Sản phẩm gợi ý để chọn đôi giày đầu tiên có đế mềm, chỉnh hình, hỗ trợ sự phát triển bàn chân của bé.', title_zh = '挑选第一双鞋！👟', body_zh = '脚步越来越快了！一定要去推荐商品清单里看看第一双鞋，选择有助于足部发育、符合矫形要求、鞋底柔软的款式。' WHERE id = '21394622-dd96-488a-a90a-b8f72d718390' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Seguridad en casa! 🛡', body_es = '️ Cuanto más se mueve con libertad, más peligros hay. Echa un vistazo a los Productos recomendados para cierres de seguridad y barreras de escalera.', title_fr = 'Sécurité à la maison ! 🛡', body_fr = '️Plus il se déplace librement, plus les dangers augmentent. Jetez un œil aux Produits recommandés pour les bloque-portes et barrières d''escalier.', title_hi = 'घर में सुरक्षा के उपाय! 🛡', body_hi = '️वह जितना आज़ादी से चलेगा, खतरे उतने बढ़ेंगे। चाइल्ड लॉक और सीढ़ियों के गेट के लिए सुझाए गए प्रोडक्ट देखिए।', title_id = 'Keamanan di rumah! 🛡', body_id = '️ Makin bebas ia berjalan, makin banyak pula bahayanya. Lihat Produk Rekomendasi untuk kunci pengaman anak dan pagar tangga.', title_ja = 'おうちの安全対策！🛡', body_ja = '️ 自由に歩きはじめると、危険も増えます。チャイルドロックやベビーゲートは、「おすすめ商品」をチェックしましょう。', title_ko = '집 안 안전 대책! 🛡', body_ko = '️ 아기가 자유롭게 걷기 시작할수록 위험도 늘어나요. 안전 잠금장치와 계단 안전문은 추천 제품에서 살펴보세요.', title_nl = 'Veiligheid in huis! 🛡', body_nl = '️ Hoe meer je baby vrij gaat lopen, hoe meer gevaren er zijn. Bekijk in de Aanbevolen producten kinderslotjes en traphekjes.', title_pl = 'Bezpieczeństwo w domu! 🛡', body_pl = '️ Im swobodniej zaczyna chodzić, tym więcej zagrożeń. Zajrzyj do Polecanych produktów po blokady dla dzieci i bramki na schody.', title_pt = 'Segurança em casa! 🛡', body_pt = '️ Quanto mais anda à vontade, maiores são os perigos. Espreite os Produtos Recomendados para fechos de segurança e portões para escadas.', title_sv = 'Säkerhet i hemmet! 🛡', body_sv = '️ Ju mer barnet börjar gå fritt, desto fler faror. Kika i Rekommenderade produkter efter barnlås och trappgrindar.', title_vi = 'Biện pháp an toàn trong nhà! 🛡', body_vi = '️ Bé càng đi lại tự do thì nguy hiểm càng tăng. Hãy xem Sản phẩm gợi ý để tìm khóa an toàn và cổng chắn cầu thang cho trẻ.', title_zh = '居家安全措施！🛡', body_zh = '️ 宝宝开始自由走动，危险也随之增加。去推荐商品里看看儿童安全锁和楼梯门栏吧。' WHERE id = 'c8d8ec20-b116-4c1f-93ec-b76e6f76a1b1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tu cuerpo que cambia 👗', body_es = '¿Te entristece mirar tus formas en el espejo? Con ese cuerpo has creado a una persona. Abrázate y recuerda lo fuerte que eres.', title_fr = 'Votre corps qui change 👗', body_fr = 'Les courbes de votre corps dans le miroir vous rendent triste ? Avec ce corps, vous avez créé un être humain. Prenez-vous dans les bras et rappelez-vous à quel point vous êtes forte.', title_hi = 'आपका बदलता शरीर 👗', body_hi = 'आईने में अपने शरीर को देखकर उदास होती हैं? आपने इसी शरीर से एक इंसान को जन्म दिया है। खुद को गले लगाइए और याद कीजिए कि आप कितनी मज़बूत हैं।', title_id = 'Tubuh Anda yang berubah 👗', body_id = 'Sedih melihat lekuk tubuh Anda di cermin? Dengan tubuh itulah Anda menciptakan seorang manusia. Peluk diri Anda dan ingatlah betapa kuatnya Anda.', title_ja = '変わっていく体 👗', body_ja = '鏡に映る体のラインを見て落ちこんでいますか？あなたはその体でひとりの人間を生み出しました。自分を抱きしめて、どれほど強いかを思い出してください。', title_ko = '변화한 몸 👗', body_ko = '거울 속 몸의 선을 보며 속상한가요? 그 몸으로 한 사람을 만들어 냈어요. 나를 꼭 안아 주며 내가 얼마나 강한지 기억하세요.', title_nl = 'Je veranderde lichaam 👗', body_nl = 'Word je verdrietig als je in de spiegel naar je lichaam kijkt? Met dat lichaam heb je een mens gemaakt. Omarm jezelf en bedenk hoe sterk je bent.', title_pl = 'Twoje zmieniające się ciało 👗', body_pl = 'Smucisz się, patrząc na linie ciała w lustrze? Tym ciałem stworzyłaś człowieka. Przytul się i przypomnij sobie, jak bardzo jesteś silna.', title_pt = 'O seu corpo em mudança 👗', body_pt = 'Fica triste ao olhar para as linhas do seu corpo ao espelho? Foi com esse corpo que criou um ser humano. Abrace-se e lembre-se de como é forte.', title_sv = 'Din kropp som förändras 👗', body_sv = 'Blir du ledsen när du ser kroppens linjer i spegeln? Med den kroppen har du skapat en människa. Krama dig själv och kom ihåg hur stark du är.', title_vi = 'Cơ thể thay đổi của mẹ 👗', body_vi = 'Nhìn những đường nét cơ thể trong gương mà mẹ thấy buồn? Mẹ đã tạo ra một con người bằng chính cơ thể ấy. Hãy ôm lấy bản thân và nhớ rằng mẹ mạnh mẽ biết bao.', title_zh = '你变化的身体 👗', body_zh = '看着镜子里的身材线条感到难过？你用这具身体创造了一个生命。抱抱自己，记住你有多么强大。' WHERE id = 'cbeda45d-85bc-4e45-b9c0-cc3c3d5c896b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Siempre pegado a mamá 🥰', body_es = 'Incluso cuando vas al baño, te espera detrás de la puerta llorando. La ansiedad por separación está en su punto máximo. Dale seguridad diciéndole cada vez «estoy aquí».', title_fr = 'Toujours collé à maman 🥰', body_fr = 'Même quand vous allez aux toilettes, il vous attend derrière la porte en pleurant. L''angoisse de séparation est à son maximum. Rassurez-le à chaque fois en disant « Je suis là ».', title_hi = 'माँ के पास रहने की ज़िद 🥰', body_hi = 'आप बाथरूम भी जाएँ, तो वह दरवाज़े के पीछे इंतज़ार करते हुए रोता है। अलगाव की बेचैनी चरम पर है। हर बार ''मैं यहीं हूँ'' कहकर उसे भरोसा दिलाइए।', title_id = 'Ingin selalu dekat ibu 🥰', body_id = 'Bahkan saat Anda ke toilet, ia menunggu di balik pintu sambil menangis. Kecemasan berpisah sedang di puncaknya. Beri ia rasa aman dengan selalu berkata "Ibu di sini".', title_ja = 'ママのそばにいたい 🥰', body_ja = 'トイレに行くときでさえ、ドアの向こうで待って泣いていますか？分離不安がピークです。そのたびに「ここにいるよ」と声をかけて、安心させてあげましょう。', title_ko = '엄마 곁에만 있을래요 🥰', body_ko = '화장실에 갈 때도 문 뒤에서 엄마를 기다리며 우나요? 분리불안이 최고조예요. 매번 ''엄마 여기 있어''라고 말하며 안심시켜 주세요.', title_nl = 'Steeds bij mama willen zijn 🥰', body_nl = 'Zelfs als je naar de wc gaat, wacht je baby huilend achter de deur. De verlatingsangst is op zijn hoogtepunt. Geef hem steeds vertrouwen door te zeggen: ik ben hier.', title_pl = 'Upór: tylko przy mamie 🥰', body_pl = 'Nawet gdy idziesz do toalety, czeka pod drzwiami i płacze. Lęk separacyjny jest u szczytu. Za każdym razem mów „jestem tutaj” i dawaj mu poczucie bezpieczeństwa.', title_pt = 'A teimosia de estar perto da mãe 🥰', body_pt = 'Até quando vai à casa de banho, ele fica à sua espera atrás da porta a chorar. A ansiedade de separação está no auge. Dê-lhe segurança dizendo sempre "estou aqui".', title_sv = 'Envisheten att vara nära mamma 🥰', body_sv = 'Även när du går på toaletten väntar barnet gråtande bakom dörren. Separationsångesten är på topp. Ge barnet trygghet varje gång genom att säga ''jag är här''.', title_vi = 'Lúc nào cũng muốn ở gần mẹ 🥰', body_vi = 'Ngay cả khi mẹ vào nhà vệ sinh, bé cũng đợi ngoài cửa và khóc. Nỗi lo xa cách đang ở đỉnh điểm. Mỗi lần như vậy, hãy nói "Mẹ ở đây" để bé yên tâm.', title_zh = '就要黏着妈妈 🥰', body_zh = '你连去洗手间，宝宝都在门外等着哭。分离焦虑正处在高峰。每次都说“我在这儿”，给宝宝安全感吧。' WHERE id = 'f38aba52-8d3a-44ad-96bf-7d9de570ef68' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La ilusión de la perfección 🛑', body_es = '¿Hoy nada ha salido según lo previsto? No te culpes. Eres una madre real, no una ilusión con filtro de las redes sociales.', title_fr = 'L''illusion de la perfection 🛑', body_fr = 'Rien ne s''est passé comme prévu aujourd''hui ? Ne vous culpabilisez pas. Vous êtes une vraie maman, pas une illusion filtrée des réseaux sociaux.', title_hi = 'परफ़ेक्शन का भ्रम 🛑', body_hi = 'आज कुछ भी योजना के मुताबिक नहीं हुआ? खुद को दोष मत दीजिए। आप एक असली माँ हैं, सोशल मीडिया का फ़िल्टर किया हुआ भ्रम नहीं।', title_id = 'Ilusi kesempurnaan 🛑', body_id = 'Hari ini tidak ada yang sesuai rencana? Jangan menyalahkan diri. Anda ibu yang nyata, bukan ilusi berfilter di media sosial.', title_ja = '完璧という幻 🛑', body_ja = '今日は何ひとつ計画どおりにいかなかった？自分を責めないで。あなたはリアルなママで、SNSのフィルター越しの幻ではありません。', title_ko = '완벽함이라는 환상 🛑', body_ko = '오늘 아무것도 계획대로 되지 않았나요? 자책하지 마세요. 당신은 SNS 속 필터 씌운 환상이 아니라 진짜 엄마예요.', title_nl = 'De illusie van perfectie 🛑', body_nl = 'Ging vandaag niets volgens plan? Geef jezelf niet de schuld. Je bent een echte moeder, geen gefilterde illusie van sociale media.', title_pl = 'Iluzja perfekcji 🛑', body_pl = 'Dziś nic nie poszło zgodnie z planem? Nie obwiniaj się. Jesteś prawdziwą mamą, a nie przefiltrowaną iluzją z mediów społecznościowych.', title_pt = 'A ilusão da perfeição 🛑', body_pt = 'Hoje nada correu como planeado? Não se culpe. É uma mãe real, não uma ilusão filtrada das redes sociais.', title_sv = 'Perfektionens illusion 🛑', body_sv = 'Gick ingenting enligt planen i dag? Skyll inte på dig själv. Du är en riktig mamma, inte en filtrerad illusion på sociala medier.', title_vi = 'Ảo tưởng về sự hoàn hảo 🛑', body_vi = 'Hôm nay không gì diễn ra theo kế hoạch? Đừng tự trách mình. Mẹ là một người mẹ thật, không phải ảo ảnh qua bộ lọc trên mạng xã hội.', title_zh = '完美的幻象 🛑', body_zh = '今天什么都没按计划进行？别责怪自己。你是一个真实的妈妈，不是社交媒体上加了滤镜的幻象。' WHERE id = '03283459-7c0f-4d41-9c06-406552e1c477' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Heroína silenciosa 🤫', body_es = 'En cuanto se duerme, cada ruido de casa suena como una bomba. Mientras estabilizas el límite de la habitación con el Medidor de sonido, pisa tú también con suavidad.', title_fr = 'Le héros silencieux 🤫', body_fr = 'Au moment où il s''endort, chaque bruit de la maison résonne comme une bombe. Pendant que vous stabilisez le niveau sonore avec le Sonomètre, allégez aussi vos propres pas.', title_hi = 'खामोश हीरो 🤫', body_hi = 'उसके सोते ही घर की हर आवाज़ बम जैसी लगती है। साउंड मीटर से कमरे की आवाज़ की सीमा तय करते हुए अपने कदम भी हल्के रखिए।', title_id = 'Pahlawan tanpa suara 🤫', body_id = 'Saat ia mulai tertidur, setiap suara di rumah terdengar seperti bom. Sambil menstabilkan batas suara kamar dengan Pengukur Suara, pelankan juga langkah Anda.', title_ja = '静かなヒーロー 🤫', body_ja = '寝ついたとたん、家のどんな音も爆発のように聞こえます。「サウンドメーター」で部屋の音を一定に保ちながら、あなたの足音もそっと軽くしましょう。', title_ko = '소리 없는 영웅 🤫', body_ko = '아기가 잠드는 순간 집 안의 모든 소리가 폭탄처럼 느껴지죠. 소음 측정기로 방의 소리 한도를 맞추면서 엄마의 발걸음도 살살 가볍게 해 주세요.', title_nl = 'Een stille heldin 🤫', body_nl = 'Zodra je baby in slaap valt, klinkt elk geluid in huis als een bom. Houd met de Geluidsmeter de kamer binnen de grens en zet ook zelf zachtere stappen.', title_pl = 'Cichy bohater 🤫', body_pl = 'Gdy tylko zaśnie, każdy dźwięk w domu brzmi jak bomba. Ustawiając limit w pokoju Miernikiem dźwięku, stąpaj też lżej.', title_pt = 'A heroína silenciosa 🤫', body_pt = 'Mal adormece, qualquer som da casa parece uma bomba. Enquanto estabiliza o limite do quarto com o Medidor de Som, ande também com passos leves.', title_sv = 'Den tysta hjälten 🤫', body_sv = 'Så fort barnet somnar låter varje ljud hemma som en bomb. Medan du håller rummets ljudnivå jämn med Ljudmätaren, gå också lite lättare på foten.', title_vi = 'Người hùng thầm lặng 🤫', body_vi = 'Ngay khi bé ngủ, mọi tiếng động trong nhà đều như tiếng bom. Khi điều chỉnh ngưỡng âm thanh trong phòng bằng Đo âm thanh, mẹ cũng nhớ bước chân nhẹ nhàng hơn nhé.', title_zh = '安静的英雄 🤫', body_zh = '宝宝刚睡着时，家里任何声音都像炸弹一样。用噪音测量稳定房间的音量上限，同时也放轻你自己的脚步吧。' WHERE id = '3843a02f-a85f-47a9-97ba-0e63677749e2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dedo que señala está activo ☝️', body_es = 'Señala con el dedo algo lejano y reacciona. Es el nivel más alto para dirigir la atención. Mirad juntos ese objeto.', title_fr = 'Le doigt qui montre est actif ☝️', body_fr = 'Il montre du doigt un objet éloigné et réagit. C''est le plus haut niveau d''attention partagée. Regardez cet objet avec lui.', title_hi = 'इशारा करने वाली उँगली चालू है ☝️', body_hi = 'दूर की चीज़ की ओर उँगली से इशारा करके प्रतिक्रिया देता है। यह ध्यान दिलाने का सबसे ऊँचा पड़ाव है। उसके साथ मिलकर उस चीज़ को देखिए।', title_id = 'Jari telunjuk aktif ☝️', body_id = 'Ia menunjuk benda yang jauh dengan jarinya dan bereaksi. Ini tahap tertinggi dalam mengarahkan perhatian. Lihatlah benda itu bersamanya.', title_ja = '指さしが活発に ☝️', body_ja = '遠くのものを指さして反応しています。注意を向けさせる力の、いちばん高い段階です。一緒にそのものを見てあげましょう。', title_ko = '손가락 가리키기 시작 ☝️', body_ko = '멀리 있는 물건을 손가락으로 가리키며 반응해요. 관심을 이끄는 능력의 가장 높은 단계예요. 함께 그 물건을 바라봐 주세요.', title_nl = 'De wijsvinger is actief ☝️', body_nl = 'Je baby wijst met zijn vinger naar iets verderop en reageert. Dat is de hoogste fase van aandacht richten. Kijk samen met hem naar dat ding.', title_pl = 'Palec wskazujący w akcji ☝️', body_pl = 'Pokazuje palcem odległy przedmiot i reaguje. To najwyższy etap kierowania uwagi. Popatrzcie na ten przedmiot razem.', title_pt = 'O dedo que aponta está ativo ☝️', body_pt = 'Aponta com o dedo para um objeto ao longe e reage. É a fase mais avançada de direcionar a atenção. Olhe com ele para esse objeto.', title_sv = 'Pekfingret är aktivt ☝️', body_sv = 'Barnet pekar med fingret på något långt bort och reagerar. Det är den högsta nivån av att styra uppmärksamheten. Titta på saken tillsammans med barnet.', title_vi = 'Ngón tay chỉ trỏ đã hoạt động ☝️', body_vi = 'Bé chỉ tay vào đồ vật ở xa và phản ứng. Đây là mức cao nhất của khả năng hướng sự chú ý. Hãy cùng bé nhìn về phía đồ vật đó.', title_zh = '开始用手指指东西 ☝️', body_zh = '宝宝用手指指着远处的东西，还会做出反应。这是引导注意力的最高阶段。和宝宝一起看看那个东西吧。' WHERE id = 'fde65599-b651-49fa-a50a-5b78bed58d9f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Puedo darle leche de vaca? 🥛', body_es = 'De cara al primer año, el menú cambia. Si tienes dudas sobre el paso a la leche de vaca o sobre alimentos como la miel, pregunta ya a Anacan AI.', title_fr = 'Puis-je donner du lait de vache ? 🥛', body_fr = 'À l''approche de ses 1 an, le menu change. Si vous vous posez des questions sur le passage au lait de vache ou sur des aliments comme le miel, demandez tout de suite à Anacan AI.', title_hi = 'क्या गाय का दूध दे सकती हूँ? 🥛', body_hi = '1 साल के करीब मेन्यू बदलता है। गाय के दूध पर जाने या शहद जैसे खानों को लेकर मन में सवाल हों, तो तुरंत Anacan AI से पूछिए।', title_id = 'Bolehkah memberi susu sapi? 🥛', body_id = 'Menunya berubah menjelang 1 tahun. Jika ada pertanyaan tentang beralih ke susu sapi atau makanan seperti madu, segera tanyakan ke Anacan AI.', title_ja = '牛乳をあげてもいい？🥛', body_ja = '1歳に向けて、献立が変わってきます。牛乳への切りかえや、はちみつなどの食べ物について疑問があれば、すぐにAnacan AIに聞きましょう。', title_ko = '우유를 줘도 될까요? 🥛', body_ko = '첫돌 무렵 메뉴가 달라져요. 우유로 바꾸는 시기나 꿀 같은 음식에 대해 궁금한 게 있다면 바로 Anacan AI에게 물어보세요.', title_nl = 'Mag ik koemelk geven? 🥛', body_nl = 'Rond de eerste verjaardag verandert het menu. Heb je vragen over de overstap op koemelk of over voedingsmiddelen zoals honing? Vraag het meteen aan Anacan AI.', title_pl = 'Czy mogę podać mleko krowie? 🥛', body_pl = 'Przed roczkiem jadłospis się zmienia. Jeśli masz pytania o przejście na mleko krowie albo o pokarmy takie jak miód, od razu zapytaj Anacan AI.', title_pt = 'Posso dar-lhe leite de vaca? 🥛', body_pt = 'Perto do 1.º ano, a ementa muda. Se tem dúvidas sobre a passagem ao leite de vaca ou alimentos como o mel, pergunte já ao Anacan AI.', title_sv = 'Kan jag ge komjölk? 🥛', body_sv = 'Menyn förändras inför 1-årsdagen. Om du har frågor om övergången till komjölk eller om mat som honung, fråga Anacan AI direkt.', title_vi = 'Cho bé uống sữa bò được chưa? 🥛', body_vi = 'Khi bé gần 1 tuổi, thực đơn sẽ thay đổi. Nếu mẹ có thắc mắc về việc chuyển sang sữa bò hay những thực phẩm như mật ong, hãy hỏi Anacan AI ngay.', title_zh = '可以喝牛奶了吗？🥛', body_zh = '快1岁时，菜单会发生变化。如果你对换成牛奶或者吃蜂蜜之类的食物有疑问，马上问问Anacan AI吧。' WHERE id = '069d21f4-a2ef-4d28-91bb-979c8ca3f3f6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Paseos y planes en familia! ☕', body_es = '¡Falta poco para el cumpleaños! Busca en Lugares para mamás cafeterías donde puedas entrar cómodamente con el carrito para quedar con amigos y familia.', title_fr = 'Sorties et projets en famille ! ☕', body_fr = 'L''anniversaire approche ! Trouvez dans les Lieux adaptés aux mamans des cafés où entrer facilement avec la poussette pour retrouver amis et famille.', title_hi = 'परिवार के साथ सैर और योजनाएँ! ☕', body_hi = 'जन्मदिन करीब है! दोस्तों और परिवार से मिलने के लिए ऐसे कैफ़े माँ के अनुकूल जगहों में ढूँढिए जहाँ स्ट्रॉलर के साथ आराम से जा सकें।', title_id = 'Jalan-jalan dan rencana keluarga! ☕', body_id = 'Ulang tahunnya sudah dekat! Temukan kafe yang mudah dimasuki dengan stroller untuk bertemu teman dan keluarga di Tempat Ramah Ibu.', title_ja = '家族でおでかけと計画！☕', body_ja = '誕生日はもうすぐ！友達や家族と会うために、ベビーカーで入りやすいカフェを「ママにやさしいスポット」で見つけましょう。', title_ko = '가족 나들이와 계획! ☕', body_ko = '생일이 얼마 남지 않았어요! 친구와 가족을 만날 때 유모차로 편하게 들어갈 수 있는 카페를 엄마 친화 장소에서 찾아보세요.', title_nl = 'Uitjes en plannen met het gezin! ☕', body_nl = 'De verjaardag is bijna daar! Vind in Mamavriendelijke plekken cafés waar je makkelijk met de kinderwagen naar binnen kunt om vrienden en familie te ontmoeten.', title_pl = 'Rodzinne wyjścia i plany! ☕', body_pl = 'Urodziny tuż-tuż! Znajdź w Miejscach przyjaznych mamom kawiarnie, do których łatwo wjedziesz wózkiem, by spotkać się z przyjaciółmi i rodziną.', title_pt = 'Passeios e planos em família! ☕', body_pt = 'O aniversário está quase a chegar! Encontre nos Locais Amigos das Mães cafés onde entre facilmente com o carrinho para estar com amigos e família.', title_sv = 'Familjeutflykter och planer! ☕', body_sv = 'Det är inte långt kvar till födelsedagen! Hitta kaféer bland Mammavänliga platser dit du lätt kommer in med barnvagnen för att träffa vänner och familj.', title_vi = 'Đi chơi và kế hoạch cùng gia đình! ☕', body_vi = 'Sắp đến sinh nhật rồi! Hãy tìm những quán cà phê có thể đẩy xe đẩy vào dễ dàng để gặp gỡ bạn bè và gia đình trong mục Địa điểm thân thiện với mẹ.', title_zh = '家庭出游和计划！☕', body_zh = '生日快到了！在妈妈友好场所里找一找能方便推婴儿车进去的咖啡馆，和亲朋好友聚一聚吧。' WHERE id = '6b37b92f-5c61-4852-9ace-caab2bda465b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora del masaje 💆‍♂️', body_es = 'Cuando tu bebé se duerma, organizad una sesión de masaje de hombros tu pareja y tú para soltar el estrés del día. ¡Sois un equipo!', title_fr = 'L''heure du massage 💆‍♂️', body_fr = 'Quand bébé dort, organisez une séance de massage des épaules avec votre conjoint pour évacuer le stress de la journée. Vous êtes une équipe !', title_hi = 'मालिश का समय 💆‍♂️', body_hi = 'बच्चे के सोने के बाद दिन का तनाव उतारने के लिए अपने साथी के साथ कंधे की मालिश का सेशन रखिए। आप एक टीम हैं!', title_id = 'Waktu pijat 💆‍♂️', body_id = 'Setelah si kecil tidur, adakan sesi pijat bahu bersama pasangan untuk melepas stres hari ini. Kalian satu tim!', title_ja = 'マッサージタイム 💆‍♂️', body_ja = '赤ちゃんが寝たら、1日のストレスを流すためにパートナーと肩もみタイムをつくりましょう。あなたたちはチームです！', title_ko = '마사지 시간 💆‍♂️', body_ko = '아이가 잠든 뒤 배우자와 함께 어깨 마사지 시간을 가지며 하루의 스트레스를 풀어 보세요. 두 사람은 한 팀이에요!', title_nl = 'Tijd voor een massage 💆‍♂️', body_nl = 'Plan als je baby slaapt een schoudermassage met je partner om de stress van de dag kwijt te raken. Jullie zijn een team!', title_pl = 'Czas na masaż 💆‍♂️', body_pl = 'Gdy maluszek zaśnie, zróbcie sobie z partnerem sesję masażu ramion, by zrzucić stres całego dnia. Jesteście drużyną!', title_pt = 'Hora da massagem 💆‍♂️', body_pt = 'Depois de o bebé adormecer, organize com o seu companheiro uma sessão de massagem aos ombros para libertar o stress do dia. São uma equipa!', title_sv = 'Massagedags 💆‍♂️', body_sv = 'När barnet har somnat, ordna en stund med axelmassage tillsammans med din partner för att släppa dagens stress. Ni är ett lag!', title_vi = 'Giờ mát-xa 💆‍♂️', body_vi = 'Sau khi bé ngủ, hãy cùng bố mát-xa vai cho nhau để xua tan căng thẳng trong ngày. Bố mẹ là một đội!', title_zh = '按摩时间 💆‍♂️', body_zh = '宝宝睡着后，和伴侣一起来一场肩部按摩，释放一天的压力。你们是一个团队！' WHERE id = 'fedb8c6b-7722-4e20-9134-1af5ae254e85' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un sitio para mamá ☕', body_es = 'Estar en casa te ha dejado sin energía. Elige en Lugares para mamás una cafetería con menú infantil donde puedas sentarte a gusto y dedícate tiempo.', title_fr = 'Un lieu pour maman ☕', body_fr = 'Rester à la maison vous a vidée de votre énergie. Dans les Lieux adaptés aux mamans, choisissez un café avec un menu enfant où vous installer confortablement, et prenez du temps pour vous.', title_hi = 'माँ के लिए जगह ☕', body_hi = 'घर में रहकर ऊर्जा खत्म हो गई है। माँ के अनुकूल जगहों में से बच्चों के मेन्यू वाला और आराम से बैठने लायक कोई कैफ़े चुनिए और अपने लिए समय निकालिए।', title_id = 'Tempat untuk Bunda ☕', body_id = 'Energi habis karena terus di rumah. Pilih kafe dari Tempat Ramah Ibu yang punya menu anak dan tempat duduk nyaman, lalu luangkan waktu untuk diri sendiri.', title_ja = 'ママのための場所 ☕', body_ja = '家にいてばかりで元気がなくなった？「ママにやさしいスポット」から、キッズメニューがあってゆったり座れるカフェを選んで、自分の時間をつくりましょう。', title_ko = '엄마를 위한 공간 ☕', body_ko = '집에만 있어 기운이 다 빠졌어요. 엄마 친화 장소에서 아이 메뉴가 있고 편히 앉을 수 있는 카페를 골라 나를 위한 시간을 가져 보세요.', title_nl = 'Een plek voor mama ☕', body_nl = 'Je energie is op van het thuiszitten. Kies in Mamavriendelijke plekken een café met een kindermenu waar je fijn kunt zitten en neem tijd voor jezelf.', title_pl = 'Miejsce dla mamy ☕', body_pl = 'Siedzenie w domu odebrało ci energię. Wybierz w Miejscach przyjaznych mamom kawiarnię z menu dla dzieci, w której wygodnie usiądziesz, i poświęć czas sobie.', title_pt = 'Um lugar para a mãe ☕', body_pt = 'Ficar em casa esgotou-lhe a energia. Escolha nos Locais Amigos das Mães um café com menu infantil onde se sente à vontade e reserve tempo para si.', title_sv = 'En plats för mamma ☕', body_sv = 'Har energin tagit slut av att vara hemma? Välj ett kafé bland Mammavänliga platser som har barnmeny och där du kan sitta bekvämt, och ta tid för dig själv.', title_vi = 'Không gian cho mẹ ☕', body_vi = 'Ở nhà mãi khiến mẹ cạn năng lượng. Hãy chọn một quán cà phê có thực đơn cho bé và chỗ ngồi thoải mái trong Địa điểm thân thiện với mẹ và dành thời gian cho bản thân.', title_zh = '妈妈的空间 ☕', body_zh = '在家待得精力都耗光了。在妈妈友好场所里挑一家有儿童菜单、能舒服坐下的咖啡馆，留点时间给自己吧。' WHERE id = '51bb1e4c-965f-4d69-b6e7-c79da0dce45c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Interés por los libros 📖', body_es = 'Incluye libros de papel en la rutina de la noche. Ya intenta pasar las páginas él solo. Adapta tu tono de voz al ritmo del cuento.', title_fr = 'L''intérêt pour les livres 📖', body_fr = 'Intégrez de vrais livres à la routine du soir. Il essaie déjà de tourner les pages tout seul. Adaptez le ton de votre voix au rythme du conte.', title_hi = 'किताबों में दिलचस्पी 📖', body_hi = 'शाम के रूटीन में असली किताबें शामिल कीजिए। वह अब खुद पन्ने पलटने की कोशिश करता है। अपनी आवाज़ का अंदाज़ कहानी की रफ़्तार के हिसाब से ढालिए।', title_id = 'Tertarik pada buku 📖', body_id = 'Masukkan buku fisik ke dalam rutinitas malam. Ia sudah mencoba membalik halaman sendiri. Sesuaikan nada suara Anda dengan tempo dongengnya.', title_ja = '絵本への興味 📖', body_ja = '夜のルーティンに本物の絵本を取り入れましょう。もう自分でページをめくろうとしています。お話のテンポに合わせて、声のトーンを変えてみて。', title_ko = '책에 대한 관심 📖', body_ko = '저녁 루틴에 진짜 책을 더해 보세요. 이제 스스로 책장을 넘기려 해요. 목소리 톤을 이야기의 속도에 맞춰 주세요.', title_nl = 'Interesse in boekjes 📖', body_nl = 'Voeg echte boekjes toe aan de avondroutine. Je baby probeert de bladzijden al zelf om te slaan. Pas je stem aan het tempo van het verhaal aan.', title_pl = 'Zainteresowanie książkami 📖', body_pl = 'Włącz do wieczornej rutyny prawdziwe książeczki. Już sam próbuje przewracać kartki. Dopasuj ton głosu do tempa bajki.', title_pt = 'Interesse pelos livros 📖', body_pt = 'Junte livros de papel à rotina da noite. Ele já tenta virar as páginas sozinho. Ajuste o tom de voz ao ritmo da história.', title_sv = 'Intresse för böcker 📖', body_sv = 'Ta med riktiga böcker i kvällsrutinen. Barnet försöker redan vända sidorna själv. Anpassa din röst efter sagans tempo.', title_vi = 'Yêu thích sách 📖', body_vi = 'Hãy đưa sách giấy vào nếp sinh hoạt buổi tối. Bé đã tự cố lật trang. Điều chỉnh giọng của mẹ theo nhịp câu chuyện nhé.', title_zh = '对书感兴趣 📖', body_zh = '把实体书加入晚间作息吧。宝宝已经想自己翻页了。让你的语调跟上故事的节奏。' WHERE id = '814176f3-c727-409b-b14a-fa62636170f1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un cuerpecito que baila con la música 🎶', body_es = 'En cuanto oye un sonido rítmico en la tele, mueve el culete. Se activa su percepción musical: únete y vivid juntos este momento tan especial.', title_fr = 'Un corps qui danse en musique 🎶', body_fr = 'Dès qu''il entend un son rythmé à la télévision, il remue les fesses. Sa perception musicale s''éveille, dansez avec lui et vivez ensemble ce moment magnifique.', title_hi = 'संगीत पर नाचता शरीर 🎶', body_hi = 'टीवी पर लयबद्ध आवाज़ सुनते ही कूल्हे मटकाने लगता है। संगीत की समझ जाग रही है, उसके साथ शामिल होकर यह शानदार पल साथ जिएँ।', title_id = 'Tubuh yang menari mengikuti musik 🎶', body_id = 'Begitu mendengar irama dari TV, ia menggoyangkan pantatnya. Kepekaan musiknya mulai bekerja, ikutlah menari dan nikmati momen luar biasa ini bersama.', title_ja = '音楽に合わせて踊る体 🎶', body_ja = 'テレビからリズムのある音が聞こえると、すぐにおしりをふります。音楽を感じる力が目覚めています。一緒に踊って、このすてきな瞬間を楽しみましょう。', title_ko = '음악에 춤추는 몸 🎶', body_ko = 'TV에서 리듬 있는 소리가 들리자마자 엉덩이를 흔들어요. 음악 감각이 깨어나고 있어요, 함께 춤추며 이 멋진 순간을 즐기세요.', title_nl = 'Een lijfje dat danst op muziek 🎶', body_nl = 'Zodra je baby een ritmisch geluid op de tv hoort, wiebelt hij met zijn billetjes. Zijn gevoel voor muziek komt op gang, dans mee en beleef dit geweldige moment samen.', title_pl = 'Ciałko tańczy do muzyki 🎶', body_pl = 'Gdy tylko usłyszy rytmiczny dźwięk z telewizora, kręci pupą. Rusza odbiór muzyki, przyłącz się i przeżyjcie razem tę wspaniałą chwilę.', title_pt = 'Um corpo que dança ao som da música 🎶', body_pt = 'Mal ouve um som ritmado na televisão, abana o rabinho. A perceção musical está a funcionar: junte-se a ele e vivam juntos este momento fantástico.', title_sv = 'En kropp som dansar till musiken 🎶', body_sv = 'Så fort barnet hör ett rytmiskt ljud på tv:n vickar det på rumpan. Musikkänslan vaknar, dansa med och upplev det här fantastiska ögonblicket tillsammans.', title_vi = 'Cơ thể nhún nhảy theo nhạc 🎶', body_vi = 'Vừa nghe thấy âm thanh có nhịp điệu trên tivi là bé lắc mông theo. Khả năng cảm thụ âm nhạc đã khởi động, hãy cùng bé tận hưởng khoảnh khắc tuyệt vời này.', title_zh = '随音乐摇摆的小身体 🎶', body_zh = '电视里一传出有节奏的声音，宝宝就扭起小屁股。音乐感知启动了，和宝宝一起享受这个美妙的时刻吧。' WHERE id = 'f73c2769-0def-42bc-93e0-9a021c41b271' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El temporizador de Anacan recuerda por ti el pecho derecho o izquierdo. ¡Empieza ya la toma con el temporizador!', body_fr = 'Le minuteur Anacan retient pour vous le sein droit ou gauche. Lancez maintenant la tétée avec le minuteur !', body_hi = 'Anacan टाइमर आपकी जगह दायाँ/बायाँ स्तन याद रखता है। अभी टाइमर के साथ फ़ीडिंग शुरू कीजिए!', body_id = 'Timer Anacan mengingat payudara kanan/kiri untuk Anda. Mulai menyusui sekarang dengan timer!', body_ja = 'Anacanのタイマーが、あなたの代わりに左右どちらのおっぱいかを覚えておいてくれます。今すぐタイマーで授乳を始めましょう！', body_ko = 'Anacan 타이머가 엄마 대신 왼쪽/오른쪽 가슴을 기억해 줘요. 지금 타이머로 수유를 시작하세요!', body_nl = 'De timer van Anacan onthoudt voor jou welke borst, links of rechts, aan de beurt is. Start de voeding nu met de timer!', body_pl = 'Timer Anacan zapamięta za ciebie, z której piersi karmiłaś: lewej czy prawej. Włącz teraz karmienie z timerem!', body_pt = 'O temporizador do Anacan lembra-se por si se foi o peito direito ou o esquerdo. Comece já a mamada com o temporizador!', body_sv = 'Anacan-timern kommer ihåg höger eller vänster bröst åt dig. Starta matningen med timern nu!', body_vi = 'Hẹn giờ của Anacan sẽ nhớ giúp mẹ bên ngực trái hay phải. Hãy bắt đầu cữ bú với hẹn giờ ngay bây giờ!', body_zh = 'Anacan计时器会替你记住左右侧乳房。现在就用计时器开始喂奶吧！' WHERE id = '4c628627-3074-421f-9cfc-318df363eaf0' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El final de un día increíble. ✨', body_es = '¡Eres una madre increíble y llevas 1 año siendo una auténtica heroína! Escribe en el Diario de ánimo lo orgullosa que estás de ti y duerme tranquila.', title_fr = 'La fin d''une journée magnifique. ✨', body_fr = 'Vous êtes une maman incroyable et, depuis 1 an, vous êtes une véritable héroïne ! Écrivez dans le Journal d''humeur que vous êtes fière de vous et dormez paisiblement.', title_hi = 'एक शानदार दिन का अंत ✨', body_hi = 'आप एक अद्भुत माँ हैं और 1 साल से सच्ची हीरो बनी हुई हैं! मूड डायरी में लिखिए कि आपको खुद पर कितना गर्व है, और चैन से सोइए।', title_id = 'Akhir dari hari yang luar biasa. ✨', body_id = 'Anda ibu yang luar biasa, dan sudah 1 tahun Anda menjalani perjuangan yang sesungguhnya! Tulis di Buku Harian Suasana Hati bahwa Anda bangga pada diri sendiri, lalu tidurlah nyenyak.', title_ja = 'すばらしい1日の終わりに。✨', body_ja = 'あなたはすばらしいママで、まる1年、本物のヒーローとしてがんばってきました！「気分日記」に自分を誇りに思うことを書いて、ぐっすり眠りましょう。', title_ko = '멋진 하루의 끝. ✨', body_ko = '당신은 놀라운 엄마이고 1년 동안 진정한 영웅이었어요! 기분 일기에 스스로가 자랑스러운 점을 적고 편안히 주무세요.', title_nl = 'Het einde van een geweldige dag. ✨', body_nl = 'Je bent een ongelofelijke moeder en al 1 jaar een echte heldin! Schrijf in je Stemmingsdagboek dat je trots bent op jezelf en slaap lekker.', title_pl = 'Koniec wspaniałego dnia. ✨', body_pl = 'Jesteś niesamowitą mamą i od roku dokonujesz prawdziwych bohaterstw! Zapisz w Dzienniku nastroju, z czego jesteś dumna, i śpij spokojnie.', title_pt = 'O fim de um dia fantástico. ✨', body_pt = 'É uma mãe incrível e há 1 ano que faz verdadeiras proezas de heroína! Escreva no Diário de Humor que se orgulha de si e durma descansada.', title_sv = 'Slutet på en fantastisk dag. ✨', body_sv = 'Du är en otrolig mamma och har gjort en riktig hjältebragd i 1 år! Skriv i Humördagboken att du är stolt över dig själv och sov gott.', title_vi = 'Kết thúc một ngày tuyệt vời. ✨', body_vi = 'Mẹ là một người mẹ phi thường và suốt 1 năm qua mẹ đã thực sự là người hùng! Hãy viết vào Nhật ký tâm trạng rằng mẹ tự hào về bản thân và ngủ thật ngon.', title_zh = '美好一天的结束 ✨', body_zh = '你是一位了不起的妈妈，这一年来你一直是真正的英雄！在心情日记里写下你为自己骄傲的地方，安心睡吧。' WHERE id = '99abcc3d-bec9-4537-89f9-92bfe6f4056c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baja las luces 🌙', body_es = 'Una hora antes de dormir, apaga todas las luces fuertes y las pantallas de casa. La melatonina solo se segrega en un ambiente tranquilo y con poca luz.', title_fr = 'Baissez les lumières 🌙', body_fr = '1 heure avant le coucher, éteignez toutes les lumières vives et les écrans de la maison. La mélatonine n''est sécrétée que dans un environnement calme et peu éclairé.', title_hi = 'लाइटें धीमी कीजिए 🌙', body_hi = 'सोने से 1 घंटा पहले घर की सारी तेज़ लाइटें और स्क्रीन बंद कर दीजिए। मेलाटोनिन शांत और कम रोशनी वाले माहौल में ही बनता है।', title_id = 'Redupkan lampu 🌙', body_id = 'Satu jam sebelum tidur, matikan semua lampu terang dan layar di rumah. Melatonin hanya diproduksi di lingkungan yang tenang dan redup.', title_ja = '明かりを落として 🌙', body_ja = '寝る1時間前には、家の強い明かりや画面をすべて消しましょう。メラトニンは、静かで明かりの少ない環境でこそ分泌されます。', title_ko = '조명을 낮춰요 🌙', body_ko = '잠들기 1시간 전에 집 안의 밝은 조명과 화면을 모두 끄세요. 멜라토닌은 조용하고 어두운 환경에서만 분비돼요.', title_nl = 'Doe de lichten zachter 🌙', body_nl = 'Doe 1 uur voor het slapengaan alle felle lampen en schermen in huis uit. Melatonine wordt alleen in een rustige omgeving met weinig licht aangemaakt.', title_pl = 'Przyciemnij światła 🌙', body_pl = 'Na godzinę przed snem wyłącz w domu wszystkie mocne światła i ekrany. Melatonina wydziela się tylko w spokojnym, słabo oświetlonym otoczeniu.', title_pt = 'Baixe as luzes 🌙', body_pt = '1 hora antes de dormir, apague as luzes desnecessárias e os ecrãs da casa. A melatonina só é produzida num ambiente calmo e com pouca luz.', title_sv = 'Dämpa ljuset 🌙', body_sv = 'Släck alla starka lampor och skärmar hemma 1 timme innan läggdags. Melatonin utsöndras bara i en lugn och svagt upplyst miljö.', title_vi = 'Giảm ánh sáng 🌙', body_vi = '1 tiếng trước giờ ngủ, hãy tắt hết đèn sáng và màn hình trong nhà. Melatonin chỉ được tiết ra trong môi trường yên tĩnh và ít ánh sáng.', title_zh = '调暗灯光 🌙', body_zh = '睡前1小时关掉家里所有的强光和屏幕。褪黑素只有在安静、光线昏暗的环境里才会分泌。' WHERE id = 'e7879bf6-3dca-4f0b-9981-d7f119d39235' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirse con un cuento 🪄', title_fr = 'S''endormir avec un conte 🪄', title_hi = 'कहानी के साथ नींद की ओर 🪄', title_id = 'Menuju tidur bersama dongeng 🪄', title_ja = 'お話でねんねへ 🪄', title_ko = '동화와 함께 꿈나라로 🪄', title_nl = 'Met een sprookje naar dromenland 🪄', title_pl = 'Zasypianie z bajką 🪄', title_pt = 'Adormecer com uma história 🪄', title_sv = 'Somna till en saga 🪄', title_vi = 'Vào giấc cùng truyện cổ tích 🪄', title_zh = '听着故事入睡 🪄' WHERE id = '14e209af-2489-4eb6-a1f0-be21be617768' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las molestias de la dentición 🦷', title_fr = 'Les douleurs dentaires 🦷', title_hi = 'दाँत निकलने का दर्द 🦷', title_id = 'Nyeri tumbuh gigi 🦷', title_ja = '歯が生えるときの痛み 🦷', title_ko = '이앓이 통증 🦷', title_nl = 'Pijn door doorkomende tandjes 🦷', title_pl = 'Bóle ząbkowania 🦷', title_pt = 'Dores dos dentes 🦷', title_sv = 'Tandsmärtor 🦷', title_vi = 'Cơn đau mọc răng 🦷', title_zh = '出牙疼 🦷' WHERE id = '0549edc6-63d2-4caa-a43c-f029f7f39465' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Control de los ruidos 🤫', body_es = 'La primera media hora después de dormirse es el momento más delicado. Comprueba el ambiente con el Medidor de sonido y evita los ruidos repentinos.', title_fr = 'Maîtriser les bruits 🤫', body_fr = 'La première demi-heure après l''endormissement est le moment le plus sensible. Vérifiez l''ambiance avec le Sonomètre et méfiez-vous des bruits soudains.', title_hi = 'आवाज़ों पर काबू 🤫', body_hi = 'सोने के बाद का पहला आधा घंटा सबसे नाज़ुक समय है। साउंड मीटर से माहौल जाँचिए और अचानक शोर से बचिए।', title_id = 'Mengatur suara 🤫', body_id = 'Setengah jam pertama setelah tertidur adalah waktu paling sensitif. Cek suasana dengan Pengukur Suara dan hindari suara bising mendadak.', title_ja = '音のコントロール 🤫', body_ja = '寝ついてから最初の30分は、いちばん眠りが浅い時間です。「サウンドメーター」で環境をチェックして、急な物音に気をつけましょう。', title_ko = '소리 관리 🤫', body_ko = '잠든 직후 처음 30분이 가장 예민한 시간이에요. 소음 측정기로 환경을 확인하고 갑작스러운 소음을 조심하세요.', title_nl = 'Geluiden onder controle 🤫', body_nl = 'Het eerste halfuur na het inslapen is het gevoeligst. Controleer de omgeving met de Geluidsmeter en pas op voor plotseling lawaai.', title_pl = 'Kontrola dźwięków 🤫', body_pl = 'Pierwsze pół godziny po zaśnięciu to najwrażliwszy czas. Sprawdź otoczenie Miernikiem dźwięku i uważaj na nagły hałas.', title_pt = 'Controlo dos sons 🤫', body_pt = 'A primeira meia hora depois de adormecer é a altura mais sensível. Verifique o ambiente com o Medidor de Som e cuidado com barulhos súbitos.', title_sv = 'Ljudkoll 🤫', body_sv = 'Den första halvtimmen efter att barnet har somnat är den känsligaste. Kolla miljön med Ljudmätaren och akta dig för plötsligt oväsen.', title_vi = 'Kiểm soát âm thanh 🤫', body_vi = 'Nửa tiếng đầu sau khi bé ngủ là lúc nhạy cảm nhất. Hãy kiểm tra môi trường bằng Đo âm thanh và cẩn thận với tiếng ồn đột ngột.', title_zh = '控制声音 🤫', body_zh = '入睡后的头半小时是最敏感的时候。用噪音测量检查环境，小心突然的噪音。' WHERE id = '1c81021a-496b-49c0-86bc-4bde92ff779d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Responde con el lenguaje corporal 🗣️', title_fr = 'Il répond avec son corps 🗣️', title_hi = 'हाव-भाव से जवाब 🗣️', title_id = 'Menjawab dengan bahasa tubuh 🗣️', title_ja = '体で答える 🗣️', title_ko = '몸짓으로 대답해요 🗣️', title_nl = 'Antwoorden met lichaamstaal 🗣️', title_pl = 'Odpowiedź mową ciała 🗣️', title_pt = 'Responde com a linguagem corporal 🗣️', title_sv = 'Svarar med kroppsspråk 🗣️', title_vi = 'Trả lời bằng ngôn ngữ cơ thể 🗣️', title_zh = '用肢体语言回应 🗣️' WHERE id = '262cbb13-eb12-4831-9fe5-37ece168bdfa' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El aire fresco te salva 🌳', body_es = 'Si en casa la crisis va a más, mira Tiempo y ropa, súbele al carrito y sal enseguida al parque. La naturaleza es la forma más rápida de calmarle.', title_fr = 'L''air frais à la rescousse 🌳', body_fr = 'Si la crise monte à la maison, consultez Météo et tenue, installez-le dans la poussette et filez au parc. La nature est le moyen le plus rapide de l''apaiser.', title_hi = 'ताज़ी हवा सबसे बड़ी मददगार है 🌳', body_hi = 'अगर घर में रोने का दौर बढ़ रहा है, तो मौसम और कपड़े देखिए, स्ट्रॉलर में बिठाइए और तुरंत पार्क चलिए। प्रकृति उसे शांत करने का सबसे तेज़ तरीका है।', title_id = 'Udara segar adalah penyelamat 🌳', body_id = 'Kalau drama di rumah makin besar, cek Cuaca dan Pakaian, dudukkan ia di stroller, dan segera pergi ke taman. Alam adalah cara tercepat untuk menenangkannya.', title_ja = '新鮮な空気が救世主 🌳', body_ja = '家でぐずりが大きくなってきたら、「天気と服装」を見て、ベビーカーに乗せ、すぐに公園へ。自然は、いちばん早く落ち着かせてくれます。', title_ko = '신선한 공기가 구원자예요 🌳', body_ko = '집에서 울음이 커진다면 날씨와 옷차림을 확인하고 유모차에 태워 바로 공원으로 나가세요. 자연이 아기를 진정시키는 가장 빠른 길이에요.', title_nl = 'Frisse lucht is je redding 🌳', body_nl = 'Loopt de crisis thuis op? Kijk in Weer en kleding, zet je baby in de kinderwagen en ga meteen naar het park. De natuur kalmeert hem het snelst.', title_pl = 'Świeże powietrze ratuje 🌳', body_pl = 'Jeśli w domu narasta kryzys, sprawdź Pogodę i ubiór, posadź go w wózku i od razu idźcie do parku. Natura to najszybszy sposób, by się uspokoił.', title_pt = 'O ar puro é uma salvação 🌳', body_pt = 'Se a crise em casa está a crescer, veja o Tempo e Roupa, ponha-o no carrinho e vá já para o parque. A natureza é o caminho mais rápido para ele se acalmar.', title_sv = 'Frisk luft räddar dagen 🌳', body_sv = 'Om krisen växer hemma, kolla Väder och kläder, lägg barnet i vagnen och gå direkt till parken. Naturen är det snabbaste sättet att lugna barnet.', title_vi = 'Không khí trong lành là cứu tinh 🌳', body_vi = 'Nếu bé quấy khóc ngày càng dữ, hãy xem Thời tiết và trang phục, đặt bé vào xe đẩy và ra công viên ngay. Thiên nhiên là cách nhanh nhất giúp bé dịu lại.', title_zh = '新鲜空气是救星 🌳', body_zh = '如果家里的哭闹越来越厉害，看看天气穿衣，放进婴儿车，马上去公园。大自然是让宝宝平静下来最快的方法。' WHERE id = '38f7fe28-84d1-4b40-8904-c7ef3e18b0f8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Construye castillos con bloques 🧱', body_es = 'Intenta poner dos o tres cubos de juguete uno encima de otro. Observa en silencio sus pequeños intentos de ingeniería y aplaude.', title_fr = 'Il construit un château avec des cubes 🧱', body_fr = 'Il essaie d''empiler deux ou trois cubes. Observez en silence ses petits essais d''ingénieur et applaudissez-le.', title_hi = 'ब्लॉक से किला बनाता है 🧱', body_hi = 'दो या तीन खिलौना ब्लॉक एक के ऊपर एक रखने की कोशिश करता है। उसकी इन छोटी-छोटी इंजीनियरिंग कोशिशों को चुपचाप देखिए और तालियाँ बजाइए।', title_id = 'Membangun istana dari balok 🧱', body_id = 'Ia mencoba menumpuk dua atau tiga balok mainan. Saksikan usaha insinyur kecil ini dengan diam-diam, lalu beri tepuk tangan.', title_ja = '積み木でお城づくり 🧱', body_ja = '積み木を2つか3つ重ねようと挑戦しています。この小さなエンジニアの挑戦を静かに見守って、拍手を送りましょう。', title_ko = '블록으로 성을 쌓아요 🧱', body_ko = '블록 두세 개를 쌓아 올리려 해요. 이 꼬마 엔지니어의 도전을 조용히 지켜보며 박수를 보내 주세요.', title_nl = 'Hij bouwt een kasteel van blokken 🧱', body_nl = 'Je baby probeert twee of drie blokken op elkaar te zetten. Kijk stil naar deze kleine bouwpogingen en applaudisseer.', title_pl = 'Buduje zamek z klocków 🧱', body_pl = 'Próbuje postawić na sobie dwa lub trzy klocki. Obserwuj w ciszy te małe inżynierskie próby i bij brawo.', title_pt = 'Constrói castelos com blocos 🧱', body_pt = 'Tenta pôr dois ou três cubos uns em cima dos outros. Acompanhe em silêncio estas pequenas tentativas de engenharia e aplauda-o.', title_sv = 'Bygger slott av klossar 🧱', body_sv = 'Barnet försöker stapla två eller tre leksaksklossar på varandra. Följ de här små ingenjörsförsöken i tystnad och applådera.', title_vi = 'Xây lâu đài bằng khối gỗ 🧱', body_vi = 'Bé thử xếp hai, ba khối đồ chơi chồng lên nhau. Hãy lặng lẽ ngắm và vỗ tay cho những nỗ lực "kỹ sư" nhỏ bé này.', title_zh = '用积木搭城堡 🧱', body_zh = '宝宝在尝试把两三块积木叠起来。默默地看着这些小小的工程尝试，为宝宝鼓掌吧。' WHERE id = '39697061-01f6-4b41-8098-183a43f25058' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Mientras tu bebé duerme, escribe lo que sientes en el Diario de ánimo. Mañana será un día nuevo y más bonito.', body_fr = 'Quand bébé dort, écrivez vos émotions dans le Journal d''humeur. Demain sera un nouveau jour, encore plus beau.', body_hi = 'बच्चे के सोते समय मूड डायरी में अपनी भावनाएँ लिखिए। कल एक नया और बेहतर दिन होगा।', body_id = 'Saat si kecil tidur, tulis perasaan Anda di Buku Harian Suasana Hati. Besok akan menjadi hari baru yang lebih indah.', body_ja = '赤ちゃんが寝ている間に、「気分日記」に気持ちを書きましょう。明日は新しい、もっとすてきな1日になります。', body_ko = '아이가 잘 때 기분 일기에 감정을 적어 보세요. 내일은 새롭고 더 좋은 하루가 될 거예요.', body_nl = 'Schrijf je gevoelens op in je Stemmingsdagboek als je baby slaapt. Morgen wordt een nieuwe, mooiere dag.', body_pl = 'Gdy maluszek śpi, zapisz swoje uczucia w Dzienniku nastroju. Jutro będzie nowy i piękniejszy dzień.', body_pt = 'Quando o bebé dormir, escreva o que sente no Diário de Humor. Amanhã será um dia novo e mais bonito.', body_sv = 'När barnet sover, skriv ner dina känslor i Humördagboken. I morgon blir en ny och finare dag.', body_vi = 'Khi bé ngủ, hãy viết cảm xúc vào Nhật ký tâm trạng. Ngày mai sẽ là một ngày mới và tươi đẹp hơn.', body_zh = '趁宝宝睡觉，在心情日记里写下你的感受。明天会是新的、更美好的一天。' WHERE id = 'c5294433-a84c-4be9-ad57-5744718366c9' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora de Cuentos inteligentes 🪄', title_fr = 'L''heure des Contes intelligents 🪄', title_hi = 'स्मार्ट कहानी का समय 🪄', title_id = 'Waktunya Dongeng Pintar 🪄', title_ja = '「スマートおはなし」の時間 🪄', title_ko = '스마트 동화 시간 🪄', title_nl = 'Tijd voor Slimme sprookjes 🪄', title_pl = 'Czas na Mądre bajki 🪄', title_pt = 'Hora das Histórias Inteligentes 🪄', title_sv = 'Smart sagostund 🪄', title_vi = 'Giờ cổ tích thông minh 🪄', title_zh = '智能故事时间 🪄' WHERE id = '569602c0-f0cf-4229-b498-984bfdabf097' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Control de los ruidos 🤫', body_es = 'La primera media hora después de dormirse es el momento más delicado. Comprueba el ambiente con el Medidor de sonido y evita los ruidos repentinos.', title_fr = 'Maîtriser les bruits 🤫', body_fr = 'La première demi-heure après l''endormissement est le moment le plus sensible. Vérifiez l''ambiance avec le Sonomètre et méfiez-vous des bruits soudains.', title_hi = 'आवाज़ों पर काबू 🤫', body_hi = 'सोने के बाद का पहला आधा घंटा सबसे नाज़ुक समय है। साउंड मीटर से माहौल जाँचिए और अचानक शोर से बचिए।', title_id = 'Mengatur suara 🤫', body_id = 'Setengah jam pertama setelah tertidur adalah waktu paling sensitif. Cek suasana dengan Pengukur Suara dan hindari suara bising mendadak.', title_ja = '音のコントロール 🤫', body_ja = '寝ついてから最初の30分は、いちばん眠りが浅い時間です。「サウンドメーター」で環境をチェックして、急な物音に気をつけましょう。', title_ko = '소리 관리 🤫', body_ko = '잠든 직후 처음 30분이 가장 예민한 시간이에요. 소음 측정기로 환경을 확인하고 갑작스러운 소음을 조심하세요.', title_nl = 'Geluiden onder controle 🤫', body_nl = 'Het eerste halfuur na het inslapen is het gevoeligst. Controleer de omgeving met de Geluidsmeter en pas op voor plotseling lawaai.', title_pl = 'Kontrola dźwięków 🤫', body_pl = 'Pierwsze pół godziny po zaśnięciu to najwrażliwszy czas. Sprawdź otoczenie Miernikiem dźwięku i uważaj na nagły hałas.', title_pt = 'Controlo dos sons 🤫', body_pt = 'A primeira meia hora depois de adormecer é a altura mais sensível. Verifique o ambiente com o Medidor de Som e cuidado com barulhos súbitos.', title_sv = 'Ljudkoll 🤫', body_sv = 'Den första halvtimmen efter att barnet har somnat är den känsligaste. Kolla miljön med Ljudmätaren och akta dig för plötsligt oväsen.', title_vi = 'Kiểm soát âm thanh 🤫', body_vi = 'Nửa tiếng đầu sau khi bé ngủ là lúc nhạy cảm nhất. Hãy kiểm tra môi trường bằng Đo âm thanh và cẩn thận với tiếng ồn đột ngột.', title_zh = '控制声音 🤫', body_zh = '入睡后的头半小时是最敏感的时候。用噪音测量检查环境，小心突然的噪音。' WHERE id = '6e25898e-24d8-4ca6-8cbe-71a271993d6f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidad de energía 🍲', title_fr = 'Besoin d''énergie 🍲', title_hi = 'ऊर्जा की ज़रूरत 🍲', title_id = 'Kebutuhan energi 🍲', title_ja = 'エネルギー補給 🍲', title_ko = '에너지가 필요해요 🍲', title_nl = 'Energie nodig 🍲', title_pl = 'Zapotrzebowanie na energię 🍲', title_pt = 'Necessidade de energia 🍲', title_sv = 'Energibehov 🍲', title_vi = 'Nhu cầu năng lượng 🍲', title_zh = '能量需求 🍲' WHERE id = 'f93e7290-30ca-44fe-a1e4-55044619c9a6' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de noche de papá 👨‍🍼', body_es = 'No cargues tú sola con todos los despertares nocturnos. Despierta también a tu pareja: ser un equipo es repartir la responsabilidad a partes iguales.', title_fr = 'Le service de nuit de papa 👨‍🍼', body_fr = 'Ne gérez pas les réveils nocturnes toute seule. Réveillez aussi votre conjoint, être une équipe, c''est partager la responsabilité à parts égales.', title_hi = 'पापा की रात की ड्यूटी 👨‍🍼', body_hi = 'रात में जागने का बोझ अकेले मत उठाइए। अपने साथी को भी जगाइए, टीम होने का मतलब है ज़िम्मेदारी बराबर बाँटना।', title_id = 'Giliran malam ayah 👨‍🍼', body_id = 'Jangan tanggung sendiri saat ia terbangun di malam hari. Bangunkan juga pasangan Anda, menjadi tim berarti berbagi tanggung jawab secara adil.', title_ja = 'パパの夜の当番 👨‍🍼', body_ja = '夜中に起きるのを、ひとりで抱えこまないで。パートナーも起こしましょう。チームとは責任を平等に分け合うことです。', title_ko = '아빠의 밤 당번 👨‍🍼', body_ko = '밤에 깨는 일을 혼자 다 감당하지 마세요. 배우자도 깨우세요, 한 팀이 된다는 건 책임을 똑같이 나누는 거예요.', title_nl = 'Papa''s avonddienst 👨‍🍼', body_nl = 'Draag het ''s nachts opstaan niet helemaal alleen. Maak je partner ook wakker, een team zijn betekent de verantwoordelijkheid eerlijk delen.', title_pl = 'Nocna zmiana taty 👨‍🍼', body_pl = 'Nie dźwigaj nocnych pobudek zupełnie sama. Obudź też partnera, bycie drużyną to równy podział odpowiedzialności.', title_pt = 'O turno da noite do pai 👨‍🍼', body_pt = 'Não aguente sozinha todos os despertares noturnos. Acorde também o seu companheiro: ser uma equipa é dividir a responsabilidade por igual.', title_sv = 'Pappas nattskift 👨‍🍼', body_sv = 'Ta inte nattuppvaknandena helt ensam. Väck din partner också, att vara ett lag är att dela ansvaret lika.', title_vi = 'Ca đêm của bố 👨‍🍼', body_vi = 'Đừng một mình gánh hết những lần thức dậy ban đêm. Hãy gọi cả bố dậy, là một đội nghĩa là chia đều trách nhiệm.', title_zh = '爸爸的夜班 👨‍🍼', body_zh = '夜醒别全都自己扛。也叫醒你的伴侣，团队就是平分责任。' WHERE id = '10a3d57b-5997-4410-8ceb-fa0dd3d4cee2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorando el tiempo ⛅', title_fr = 'Bulletin météo ⛅', title_hi = 'मौसम की जासूसी ⛅', title_id = 'Mengintip cuaca ⛅', title_ja = 'お天気チェック ⛅', title_ko = '날씨 탐색 ⛅', title_nl = 'Het weer verkennen ⛅', title_pl = 'Rozpoznanie pogody ⛅', title_pt = 'Exploração do tempo ⛅', title_sv = 'Väderspaning ⛅', title_vi = 'Thám thính thời tiết ⛅', title_zh = '天气侦察 ⛅' WHERE id = '9407d96f-ca5a-4378-a7c6-ee00256c457a' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hace falta desahogarse 💬', title_fr = 'Besoin de vous confier 💬', title_hi = 'दिल की बात करना ज़रूरी है 💬', title_id = 'Butuh teman bercerita 💬', title_ja = '話すことが必要なとき 💬', title_ko = '마음을 나눌 시간 💬', title_nl = 'Even je hart luchten 💬', title_pl = 'Czas się wygadać 💬', title_pt = 'Precisa de desabafar 💬', title_sv = 'Ibland behöver man prata av sig 💬', title_vi = 'Cần được tâm sự 💬', title_zh = '需要倾诉一下 💬' WHERE id = '3ed836ab-41d4-4203-a7c8-b9e7b1394cd2' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La calma de la noche 🛀', body_es = 'Baño templado, masaje y habitación a oscuras. Mantener la rutina de sueño es el secreto básico para tener noches sin interrupciones.', title_fr = 'La sérénité du soir 🛀', body_fr = 'Bain tiède, massage et pièce assombrie. Préserver la routine du coucher, c''est le secret fondamental des nuits sans interruption.', title_hi = 'रात का सुकून 🛀', body_hi = 'गुनगुना स्नान, मालिश और कमरे में अँधेरा। सोने का रूटीन बनाए रखना बिना रुकावट वाली रातों का सबसे बुनियादी राज़ है।', title_id = 'Ketenangan malam 🛀', body_id = 'Mandi air hangat, pijat, dan kamar yang diredupkan. Menjaga rutinitas tidur adalah rahasia utama malam tanpa terbangun.', title_ja = '夜のやすらぎ 🛀', body_ja = 'ぬるめのお風呂、マッサージ、部屋を暗くする。ねんねのルーティンを守ることが、途切れない夜のいちばんの基本のひみつです。', title_ko = '밤의 평온 🛀', body_ko = '따뜻한 목욕, 마사지, 어두운 방. 잠자리 루틴을 지키는 것이 깨지 않는 밤의 가장 기본적인 비결이에요.', title_nl = 'De rust van de nacht 🛀', body_nl = 'Een lauw badje, een massage en een verduisterde kamer. De slaaproutine bewaken is het belangrijkste geheim van ononderbroken nachten.', title_pl = 'Spokój nocy 🛀', body_pl = 'Ciepła kąpiel, masaż i przyciemniony pokój. Pilnowanie rytuału snu to podstawowy sekret nieprzerwanych nocy.', title_pt = 'A calma da noite 🛀', body_pt = 'Banho morno, massagem e quarto escurecido. Manter a rotina de sono é o segredo mais básico para noites sem interrupções.', title_sv = 'Nattens ro 🛀', body_sv = 'Ett ljummet bad, massage och ett mörkt rum. Att hålla fast vid sömnrutinen är den mest grundläggande hemligheten bakom nätter utan avbrott.', title_vi = 'Sự bình yên của màn đêm 🛀', body_vi = 'Tắm nước ấm, mát-xa và làm tối phòng. Giữ nếp sinh hoạt trước khi ngủ là bí quyết cơ bản nhất cho những đêm ngủ trọn giấc.', title_zh = '夜晚的宁静 🛀', body_zh = '温水澡、按摩、调暗房间。守护好睡前作息，是夜夜安睡最基本的秘诀。' WHERE id = '4c27d203-23f5-4e87-918e-d40df5e30875' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
