UPDATE public.mommy_day_notifications SET title_es = 'Dedícate tiempo. 🛁', title_fr = 'Prenez du temps pour vous. 🛁', title_hi = 'अपने लिए समय निकालिए 🛁', title_id = 'Luangkan waktu untuk diri sendiri. 🛁', title_ja = '自分の時間をつくって。🛁', title_ko = '나를 위한 시간을 가지세요. 🛁', title_nl = 'Neem tijd voor jezelf. 🛁', title_pl = 'Znajdź czas dla siebie. 🛁', title_pt = 'Reserve tempo para si. 🛁', title_sv = 'Ta tid för dig själv. 🛁', title_vi = 'Dành thời gian cho bản thân. 🛁', title_zh = '留点时间给自己 🛁' WHERE id = '9a073421-3e36-4699-bbbd-50a69e46f431' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pasa las páginas de los libros 📖', title_fr = 'Il feuillette les livres 📖', title_hi = 'किताबों के पन्ने पलटता है 📖', title_id = 'Ia membalik halaman buku 📖', title_ja = '絵本をめくる 📖', title_ko = '책장을 넘겨요 📖', title_nl = 'Hij bladert door boekjes 📖', title_pl = 'Przewraca kartki 📖', title_pt = 'Folheia livros 📖', title_sv = 'Bläddrar i böcker 📖', title_vi = 'Bé lật sách 📖', title_zh = '翻书啦 📖' WHERE id = '2cdeb7df-f4f5-4a75-ae9b-552210a168fe' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tardes con música 🎶', body_es = 'La forma más fácil de calmar los lloriqueos de la tarde es poner su canción favorita y bailar abrazados.', title_fr = 'Soirées en musique 🎶', body_fr = 'Le moyen le plus simple de calmer les pleurnicheries de fin de journée, c''est de mettre sa chanson préférée et de danser en le serrant contre vous.', title_hi = 'संगीत भरी शामें 🎶', body_hi = 'शाम की चिड़चिड़ाहट दूर करने का सबसे आसान तरीका है उसका पसंदीदा गाना लगाना और उसे गले लगाकर नाचना।', title_id = 'Malam penuh musik 🎶', body_id = 'Cara termudah meredakan rengekan menjelang sore adalah memutar lagu kesukaannya lalu berdansa sambil berpelukan dengannya.', title_ja = '音楽のある夕方 🎶', body_ja = '夕方のぐずぐずをいちばんかんたんに解決する方法は、お気に入りの曲をかけて、抱きしめて一緒に踊ることです。', title_ko = '음악이 있는 저녁 🎶', body_ko = '늦은 오후의 칭얼거림을 달래는 가장 쉬운 방법은 좋아하는 노래를 틀고 꼭 안고 춤추는 거예요.', title_nl = 'Muzikale avonden 🎶', body_nl = 'De makkelijkste manier om het gezeur aan het eind van de middag op te lossen: zet zijn lievelingsliedje op en dans knuffelend met hem.', title_pl = 'Muzyczne wieczory 🎶', body_pl = 'Najprostszy sposób na wieczorne marudzenie to włączyć jego ulubioną piosenkę, przytulić go i razem zatańczyć.', title_pt = 'Noites com música 🎶', body_pt = 'A forma mais fácil de acalmar a rabugice do fim da tarde é pôr uma canção de que ele gosta e dançar abraçados.', title_sv = 'Musikaliska kvällar 🎶', body_sv = 'Det enklaste sättet att lösa gnället på eftermiddagen är att sätta på en låt barnet gillar, krama det och dansa tillsammans.', title_vi = 'Những buổi tối âm nhạc 🎶', body_vi = 'Cách dễ nhất để dỗ những cơn quấy chiều tối là bật bài hát bé thích, ôm bé và cùng nhảy.', title_zh = '音乐之夜 🎶', body_zh = '解决傍晚哭闹最简单的办法，就是放一首宝宝最爱的歌，抱着宝宝一起跳舞。' WHERE id = 'beccb06c-7cf4-4f1a-9455-17d5b952ad96' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidad de silencio 🤫', body_es = 'Protege la calma de la habitación con el Medidor de sonido. El sueño interrumpido por la noche estropea su humor por la mañana, y también el tuyo.', title_fr = 'Besoin de silence 🤫', body_fr = 'Protégez le calme de la chambre avec le Sonomètre. Un sommeil interrompu la nuit gâche l''humeur du matin, la sienne comme la vôtre.', title_hi = 'खामोशी की ज़रूरत 🤫', body_hi = 'साउंड मीटर से कमरे की शांति बनाए रखिए। रात में टूटी नींद उसका और आपका, दोनों का सुबह का मूड बिगाड़ देती है।', title_id = 'Butuh keheningan 🤫', body_id = 'Jaga ketenangan kamar dengan Pengukur Suara. Tidur yang terputus di malam hari merusak suasana hatinya dan juga Anda di pagi hari.', title_ja = '静けさが必要 🤫', body_ja = '「サウンドメーター」で部屋の静けさを守りましょう。夜中に途切れた眠りは、赤ちゃんとあなたの朝のごきげんを左右します。', title_ko = '고요함이 필요해요 🤫', body_ko = '소음 측정기로 방의 고요함을 지켜 주세요. 밤에 끊긴 잠은 아기와 엄마의 아침 기분을 모두 망쳐요.', title_nl = 'Behoefte aan stilte 🤫', body_nl = 'Bescherm de rust in de kamer met de Geluidsmeter. Een onderbroken nachtrust verpest de ochtendstemming van hem én van jou.', title_pl = 'Potrzeba ciszy 🤫', body_pl = 'Chroń spokój w pokoju Miernikiem dźwięku. Przerwany nocny sen psuje poranny nastrój i jemu, i tobie.', title_pt = 'Necessidade de silêncio 🤫', body_pt = 'Proteja a calma do quarto com o Medidor de Som. O sono interrompido à noite estraga o humor da manhã, o dele e o seu.', title_sv = 'Behovet av tystnad 🤫', body_sv = 'Skydda lugnet i rummet med Ljudmätaren. Avbruten nattsömn förstör både barnets och ditt humör på morgonen.', title_vi = 'Cần sự yên tĩnh 🤫', body_vi = 'Hãy giữ yên tĩnh cho căn phòng bằng Đo âm thanh. Giấc ngủ đêm bị gián đoạn làm hỏng tâm trạng buổi sáng của cả bé lẫn mẹ.', title_zh = '需要安静 🤫', body_zh = '用噪音测量守护房间的安静。夜里睡眠被打断，宝宝和你第二天早上的心情都会受影响。' WHERE id = '0c97760a-2746-4ddf-ad12-5f44e1960612' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder de la palabra «no» 🛑', title_fr = 'La force du mot « non » 🛑', title_hi = '''ना'' की ताकत 🛑', title_id = 'Kekuatan kata "tidak" 🛑', title_ja = '「いや」の力 🛑', title_ko = '''싫어''라는 말의 힘 🛑', title_nl = 'De kracht van het woordje nee 🛑', title_pl = 'Siła słowa „nie” 🛑', title_pt = 'O poder da palavra "não" 🛑', title_sv = 'Kraften i ordet nej 🛑', title_vi = 'Sức mạnh của chữ "Không" 🛑', title_zh = '“不”的力量 🛑' WHERE id = '61d67656-ab73-4417-b42d-5e55ecf64b87' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juegos de lógica 🧩', body_es = '¿Mete los juguetes en la caja y luego la vacía entera? Se desarrolla su lógica de «dentro» y «fuera». No interrumpas esta actividad.', title_fr = 'Jeux de logique 🧩', body_fr = 'Il met ses jouets dans une boîte, puis la vide entièrement ? Sa logique du « dedans » et du « dehors » se développe. N''empêchez pas cette activité.', title_hi = 'तर्क वाले खेल 🧩', body_hi = 'डिब्बे में खिलौने डालकर फिर सब खाली कर देता है? ''अंदर'' और ''बाहर'' की समझ विकसित हो रही है। इस गतिविधि को मत रोकिए।', title_id = 'Permainan logika 🧩', body_id = 'Ia memasukkan mainan ke kotak lalu mengeluarkan semuanya? Logika "di dalam" dan "di luar" sedang berkembang. Jangan halangi aktivitas ini.', title_ja = '考える遊び 🧩', body_ja = '箱におもちゃを入れては、ぜんぶ出してしまう？「中」と「外」の考え方が育っています。この遊びをじゃましないであげましょう。', title_ko = '논리 놀이 🧩', body_ko = '상자에 장난감을 넣었다가 다시 모두 쏟아 내나요? ''안''과 ''밖''의 논리가 자라고 있어요. 이 놀이를 막지 마세요.', title_nl = 'Logische spelletjes 🧩', body_nl = 'Gooit je baby speeltjes in een doos en haalt hij ze er daarna allemaal weer uit? Zijn logica van in en uit ontwikkelt zich. Houd hem niet tegen.', title_pl = 'Zabawy logiczne 🧩', body_pl = 'Wrzuca zabawki do pudełka, a potem wszystkie wysypuje? Rozwija się logika „w środku” i „na zewnątrz”. Nie przeszkadzaj mu w tym.', title_pt = 'Jogos de lógica 🧩', body_pt = 'Atira os brinquedos para dentro da caixa e depois esvazia-a toda? A lógica de dentro e fora está a desenvolver-se. Não interrompa esta atividade.', title_sv = 'Logiklekar 🧩', body_sv = 'Lägger barnet leksakerna i lådan och tömmer sedan ut alltihop? Logiken kring i och ur utvecklas. Hindra inte den här aktiviteten.', title_vi = 'Trò chơi tư duy 🧩', body_vi = 'Bé bỏ đồ chơi vào hộp rồi đổ hết ra? Tư duy về "bên trong" và "bên ngoài" đang phát triển. Đừng ngăn cản hoạt động này nhé.', title_zh = '逻辑游戏 🧩', body_zh = '宝宝把玩具扔进盒子，再全部倒出来？“里面”和“外面”的逻辑正在发展。别阻止这项活动。' WHERE id = 'b58ae5cb-ec5b-400f-b490-16ff65c6cead' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
