UPDATE public.mommy_day_notifications SET title_es = '¿Quién hace las tareas de casa? 🌪️', title_fr = 'Qui s''occupe du ménage ? 🌪️', title_hi = 'घर का काम कौन करेगा? 🌪️', title_id = 'Siapa yang mengurus rumah? 🌪️', title_ja = '家事は誰がする？🌪️', title_ko = '집안일은 누가 할까요? 🌪️', title_nl = 'Wie doet het huishouden? 🌪️', title_pl = 'Kto zajmie się domem? 🌪️', title_pt = 'Quem vai tratar da casa? 🌪️', title_sv = 'Vem tar hushållet? 🌪️', title_vi = 'Ai sẽ làm việc nhà? 🌪️', title_zh = '家务谁来做？🌪️' WHERE id = 'd1cf73d9-421b-4ad1-b114-e5025146d5b2' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Diario emocional 📝', body_es = 'Cuando te sientas sola, vuelca tus emociones en el Diario de ánimo. Todas las mujeres pasan por este camino. Eres fuerte.', title_fr = 'Un journal des émotions 📝', body_fr = 'Quand vous vous sentez seule, déversez vos émotions dans le Journal d''humeur. Toutes les femmes passent par ces chemins, vous êtes forte.', title_hi = 'भावनाओं की डायरी 📝', body_hi = 'जब अकेली महसूस करें, तो अपनी भावनाएँ मूड डायरी में उड़ेल दीजिए। हर महिला इन रास्तों से गुज़रती है, आप मज़बूत हैं।', title_id = 'Buku harian perasaan 📝', body_id = 'Saat merasa sendirian, tuangkan perasaan Anda di Buku Harian Suasana Hati. Semua perempuan melewati jalan ini, Anda kuat.', title_ja = '気持ちの日記 📝', body_ja = 'ひとりぼっちだと感じたら、「気分日記」に気持ちを吐き出しましょう。どの女性もこの道を通ります。あなたは強い人です。', title_ko = '마음 일기 📝', body_ko = '외로울 때는 기분 일기에 감정을 쏟아 내세요. 모든 여성이 이 길을 지나요. 당신은 강해요.', title_nl = 'Een gevoelsdagboek 📝', body_nl = 'Voel je je alleen? Laat je gevoelens de vrije loop in je Stemmingsdagboek. Alle vrouwen gaan deze weg, je bent sterk.', title_pl = 'Dziennik emocji 📝', body_pl = 'Gdy czujesz się samotna, przelej swoje uczucia do Dziennika nastroju. Wszystkie kobiety przechodzą tę drogę, jesteś silna.', title_pt = 'Diário emocional 📝', body_pt = 'Quando se sentir sozinha, despeje o que sente no Diário de Humor. Todas as mulheres passam por estes caminhos: é forte.', title_sv = 'Känslodagbok 📝', body_sv = 'När du känner dig ensam, häll ut dina känslor i Humördagboken. Alla kvinnor går igenom de här vägarna, du är stark.', title_vi = 'Nhật ký cảm xúc 📝', body_vi = 'Khi thấy cô đơn, hãy trút cảm xúc vào Nhật ký tâm trạng. Người phụ nữ nào cũng đi qua những chặng đường này, mẹ mạnh mẽ lắm.', title_zh = '情绪日记 📝', body_zh = '觉得孤单时，就把感受倾诉在心情日记里。每个女人都会走过这些路，你很坚强。' WHERE id = '18cb3df2-de24-43c0-a3d0-160051dc5202' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ha llorado y ha estado inquieto todo el día? La solución es muy sencilla: mira Tiempo y ropa, súbele al carrito y sal enseguida al parque.', body_fr = 'Il a pleuré et s''est agité toute la journée ? La solution est simple : consultez Météo et tenue, installez-le dans la poussette et filez au parc.', body_hi = 'दिनभर रोता और बेचैन रहा? उपाय बहुत आसान है: मौसम और कपड़े देखिए, स्ट्रॉलर में बिठाइए और तुरंत पार्क चलिए।', body_id = 'Ia menangis dan rewel seharian? Solusinya sangat sederhana: cek Cuaca dan Pakaian, dudukkan ia di stroller, dan segera pergi ke taman.', body_ja = '1日中泣いてぐずっていた？解決法はとてもシンプル：「天気と服装」を見て、ベビーカーに乗せ、すぐに公園へ。', body_ko = '하루 종일 울고 보챘나요? 해결책은 아주 간단해요: 날씨와 옷차림을 확인하고 유모차에 태워 바로 공원으로 나가세요.', body_nl = 'Heeft je baby de hele dag gehuild en was hij onrustig? De oplossing is simpel: kijk in Weer en kleding, zet hem in de kinderwagen en ga meteen naar het park.', body_pl = 'Cały dzień płakał i był niespokojny? Rozwiązanie jest bardzo proste: sprawdź Pogodę i ubiór, posadź go w wózku i od razu idźcie do parku.', body_pt = 'Chorou e esteve inquieto o dia todo? A solução é muito simples: veja o Tempo e Roupa, ponha-o no carrinho e vá já para o parque.', body_sv = 'Har barnet gråtit och varit oroligt hela dagen? Lösningen är enkel: kolla Väder och kläder, lägg barnet i vagnen och gå direkt till parken.', body_vi = 'Bé khóc và quấy cả ngày? Cách giải quyết rất đơn giản: xem Thời tiết và trang phục, đặt bé vào xe đẩy và ra công viên ngay.', body_zh = '宝宝哭闹烦躁了一整天？办法很简单：看看天气穿衣，放进婴儿车，马上去公园。' WHERE id = 'c6a284e9-0bba-433f-9823-bcc74708dbd9' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Vitaminas para mamá 🥑', body_es = 'Haces de todo para que coma bien. ¿Y tú? Elige en la sección Recetas saludables una comida ligera rica en hierro y calcio.', title_fr = 'Des vitamines pour maman 🥑', body_fr = 'Vous faites tout pour bien le nourrir. Et vous ? Choisissez dans les Recettes saines un déjeuner léger riche en fer et en calcium.', title_hi = 'माँ के लिए विटामिन 🥑', body_hi = 'उसका पेट भरने के लिए आप सब कुछ करती हैं। और आप? सेहतमंद रेसिपी सेक्शन से आयरन और कैल्शियम से भरपूर हल्का लंच चुनिए।', title_id = 'Vitamin untuk Bunda 🥑', body_id = 'Anda melakukan segalanya agar ia kenyang. Bagaimana dengan Anda? Pilih makan siang ringan yang kaya zat besi dan kalsium dari bagian Resep Sehat.', title_ja = 'ママのビタミン 🥑', body_ja = '赤ちゃんにお腹いっぱい食べさせるために、なんでもしていますね。でもあなたは？「ヘルシーレシピ」から、鉄分とカルシウムたっぷりの軽いランチを選びましょう。', title_ko = '엄마를 위한 비타민 🥑', body_ko = '아기를 배불리 먹이려고 뭐든 하죠. 그런데 엄마는요? 건강한 레시피 섹션에서 철분과 칼슘이 풍부한 가벼운 점심을 골라 보세요.', title_nl = 'Vitamines voor mama 🥑', body_nl = 'Je doet alles om je baby goed te laten eten. En jij? Kies in het onderdeel Gezonde recepten een lichte lunch vol ijzer en calcium.', title_pl = 'Witaminy dla mamy 🥑', body_pl = 'Robisz wszystko, żeby go nakarmić. A ty? Wybierz w sekcji Zdrowe przepisy lekki obiad bogaty w żelazo i wapń.', title_pt = 'Vitaminas para a mãe 🥑', body_pt = 'Faz tudo para o alimentar. E a mãe? Escolha na secção Receitas Saudáveis um almoço leve, rico em ferro e cálcio.', title_sv = 'Vitaminer till mamma 🥑', body_sv = 'Du gör allt för att barnet ska bli mätt. Men du själv då? Välj en lätt lunch rik på järn och kalcium i avsnittet Hälsosamma recept.', title_vi = 'Vitamin cho mẹ 🥑', body_vi = 'Mẹ làm mọi thứ để bé được no. Còn mẹ thì sao? Hãy chọn một bữa trưa nhẹ, giàu sắt và canxi từ mục Công thức lành mạnh.', title_zh = '妈妈的维生素 🥑', body_zh = '你为了让宝宝吃饱想尽办法。那你自己呢？从健康食谱里挑一份富含铁和钙的清淡午餐吧。' WHERE id = '0955065c-ecf1-48ed-9f6f-735958386a41' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cambian las siestas? 🥱', title_fr = 'Les siestes changent ? 🥱', title_hi = 'दिन की नींद बदल रही है? 🥱', title_id = 'Tidur siang berubah? 🥱', title_ja = 'お昼寝が変わる？🥱', title_ko = '낮잠이 바뀌고 있나요? 🥱', title_nl = 'Veranderen de dutjes overdag? 🥱', title_pl = 'Drzemki się zmieniają? 🥱', title_pt = 'As sestas estão a mudar? 🥱', title_sv = 'Förändras dagsluren? 🥱', title_vi = 'Giấc ngủ ngày thay đổi? 🥱', title_zh = '白天小睡在变化？🥱' WHERE id = '1d781ae8-7800-48ae-b0ee-fe44c7f13291' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirse con un cuento 🪄', body_es = 'Crea en Cuentos inteligentes la historia de unos animales valientes y adorables y convierte la habitación en un lugar mágico.', title_fr = 'S''endormir avec un conte 🪄', body_fr = 'Dans les Contes intelligents, créez l''histoire d''animaux courageux et adorables et transformez la chambre en un lieu magique.', title_hi = 'कहानी के साथ नींद 🪄', body_hi = 'स्मार्ट कहानियों में बहादुर और प्यारे जानवरों की कहानी बनाइए और कमरे को एक जादुई जगह में बदल दीजिए।', title_id = 'Tertidur bersama dongeng 🪄', body_id = 'Di Dongeng Pintar, buat kisah hewan-hewan yang berani dan menggemaskan, dan ubah kamar menjadi tempat yang ajaib.', title_ja = 'お話でねんね 🪄', body_ja = '「スマートおはなし」で、勇敢でかわいい動物たちのお話をつくって、部屋を魔法の場所に変えましょう。', title_ko = '동화와 함께 꿈나라로 🪄', body_ko = '스마트 동화에서 용감하고 사랑스러운 동물 이야기를 만들어 방을 마법의 공간으로 바꿔 보세요.', title_nl = 'Met een sprookje in slaap 🪄', body_nl = 'Maak in Slimme sprookjes het verhaal van dappere, lieve dieren en verander de kamer in een magische plek.', title_pl = 'Zasypianie z bajką 🪄', body_pl = 'Stwórz w Mądrych bajkach historię o odważnych i uroczych zwierzątkach i zamień pokój w magiczne miejsce.', title_pt = 'Adormecer com uma história 🪄', body_pt = 'Crie nas Histórias Inteligentes histórias de animais corajosos e adoráveis e transforme o quarto num lugar mágico.', title_sv = 'Somnar till en saga 🪄', body_sv = 'Skapa sagan om modiga och gulliga djur i Smarta sagor och förvandla rummet till en magisk plats.', title_vi = 'Vào giấc cùng truyện cổ tích 🪄', body_vi = 'Hãy tạo câu chuyện về những con vật dũng cảm, đáng yêu trong Truyện cổ tích thông minh và biến căn phòng thành một nơi kỳ diệu.', title_zh = '听着故事入睡 🪄', body_zh = '在智能故事里创作勇敢又可爱的动物的故事，把房间变成一个神奇的地方吧。' WHERE id = '61536a43-b97b-4fe8-8f6a-f358141baefc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baja las luces 🌙', body_es = 'Una hora antes de dormir, apaga todas las luces fuertes y las pantallas de casa. La melatonina solo se segrega en un ambiente tranquilo y con poca luz.', title_fr = 'Baissez les lumières 🌙', body_fr = '1 heure avant le coucher, éteignez toutes les lumières vives et les écrans de la maison. La mélatonine n''est sécrétée que dans un environnement calme et peu éclairé.', title_hi = 'लाइटें धीमी कीजिए 🌙', body_hi = 'सोने से 1 घंटा पहले घर की सारी तेज़ लाइटें और स्क्रीन बंद कर दीजिए। मेलाटोनिन शांत और कम रोशनी वाले माहौल में ही बनता है।', title_id = 'Redupkan lampu 🌙', body_id = 'Satu jam sebelum tidur, matikan semua lampu terang dan layar di rumah. Melatonin hanya diproduksi di lingkungan yang tenang dan redup.', title_ja = '明かりを落として 🌙', body_ja = '寝る1時間前には、家の強い明かりや画面をすべて消しましょう。メラトニンは、静かで明かりの少ない環境でこそ分泌されます。', title_ko = '조명을 낮춰요 🌙', body_ko = '잠들기 1시간 전에 집 안의 밝은 조명과 화면을 모두 끄세요. 멜라토닌은 조용하고 어두운 환경에서만 분비돼요.', title_nl = 'Doe de lichten zachter 🌙', body_nl = 'Doe 1 uur voor het slapengaan alle felle lampen en schermen in huis uit. Melatonine wordt alleen in een rustige omgeving met weinig licht aangemaakt.', title_pl = 'Przyciemnij światła 🌙', body_pl = 'Na godzinę przed snem wyłącz w domu wszystkie mocne światła i ekrany. Melatonina wydziela się tylko w spokojnym, słabo oświetlonym otoczeniu.', title_pt = 'Baixe as luzes 🌙', body_pt = '1 hora antes de dormir, apague as luzes desnecessárias e os ecrãs da casa. A melatonina só é produzida num ambiente calmo e com pouca luz.', title_sv = 'Dämpa ljuset 🌙', body_sv = 'Släck alla starka lampor och skärmar hemma 1 timme innan läggdags. Melatonin utsöndras bara i en lugn och svagt upplyst miljö.', title_vi = 'Giảm ánh sáng 🌙', body_vi = '1 tiếng trước giờ ngủ, hãy tắt hết đèn sáng và màn hình trong nhà. Melatonin chỉ được tiết ra trong môi trường yên tĩnh và ít ánh sáng.', title_zh = '调暗灯光 🌙', body_zh = '睡前1小时关掉家里所有的强光和屏幕。褪黑素只有在安静、光线昏暗的环境里才会分泌。' WHERE id = '76e3844a-efe7-4daa-855a-4cfd4d92bfc9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lanzamientos con puntería ⚾', title_fr = 'Des lancers ciblés ⚾', title_hi = 'निशाना लगाकर फेंकना ⚾', title_id = 'Lemparan bertujuan ⚾', title_ja = 'ねらって投げる ⚾', title_ko = '목표를 향한 던지기 ⚾', title_nl = 'Gericht gooien ⚾', title_pl = 'Rzuty do celu ⚾', title_pt = 'Lançamentos com pontaria ⚾', title_sv = 'Målinriktade kast ⚾', title_vi = 'Ném có mục tiêu ⚾', title_zh = '有目标地扔 ⚾' WHERE id = 'b87394f8-5f2b-4eb7-a491-26b80560c8a3' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fase del «quiero comer yo solo» 🥦', body_es = 'Quiere quitarte la cuchara de la mano. Deja que la coja. Se manchará, pero esta sensación de independencia es muy importante para tu peque.', title_fr = 'La phase « Je mange tout seul » 🥦', body_fr = 'Il veut vous prendre la cuillère des mains. Laissez-le faire. Il va se salir, mais ce sentiment d''autonomie est très important pour lui.', title_hi = '''मैं खुद खाऊँगा'' वाली ज़िद 🥦', body_hi = 'वह आपके हाथ से चम्मच लेना चाहता है। लेने दीजिए। कपड़े गंदे होंगे, पर आत्मनिर्भरता का यह एहसास उसके लिए बहुत ज़रूरी है।', title_id = 'Fase "Aku mau makan sendiri" 🥦', body_id = 'Ia ingin merebut sendok dari tangan Anda. Biarkan saja. Bajunya akan kotor, tapi rasa mandiri ini sangat penting baginya.', title_ja = '「自分で食べる！」の時期 🥦', body_ja = 'あなたの手からスプーンを取りたがっています。持たせてあげましょう。服は汚れますが、この「ひとりでできる」気持ちは赤ちゃんにとってとても大切です。', title_ko = '''내가 먹을래'' 고집 🥦', body_ko = '엄마 손에서 숟가락을 가져가고 싶어 해요. 가져가게 두세요. 옷은 더러워지겠지만 이 자립심은 아기에게 아주 중요해요.', title_nl = 'Ik wil zelf eten! 🥦', body_nl = 'Je baby wil de lepel van je afpakken. Laat hem maar. Hij wordt vies, maar dit gevoel van zelfstandigheid is heel belangrijk voor hem.', title_pl = 'Upór: sam zjem 🥦', body_pl = 'Chce wziąć od ciebie łyżeczkę. Pozwól mu. Ubrudzi się, ale to poczucie samodzielności jest dla niego bardzo ważne.', title_pt = 'A teimosia do "eu como sozinho" 🥦', body_pt = 'Quer tirar-lhe a colher da mão. Deixe-o. Vai sujar-se, mas este sentido de independência é muito importante para ele.', title_sv = 'Jag äter själv-envisheten 🥦', body_sv = 'Barnet vill ta skeden ur din hand. Låt det. Det blir kladdigt, men känslan av självständighet är väldigt viktig för barnet.', title_vi = 'Giai đoạn "Con tự ăn" 🥦', body_vi = 'Bé muốn giành thìa khỏi tay mẹ. Cứ để bé cầm. Người bé sẽ bẩn, nhưng cảm giác tự lập này rất quan trọng với bé.', title_zh = '“我要自己吃”阶段 🥦', body_zh = '宝宝想从你手里抢勺子。就让宝宝拿吧。会弄脏，但这种独立感对宝宝非常重要。' WHERE id = '18eaf932-80c3-47ae-a394-f6ce083ef215' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hacerse amigo de la oscuridad 🌙', body_es = 'Para que se duerma antes, añade a la rutina de la noche un momento de oscuridad. Apaga todas las luces que sobran en la habitación.', title_fr = 'Apprivoiser l''obscurité 🌙', body_fr = 'Pour l''aider à s''endormir plus vite, ajoutez l''obscurité à la routine du soir. Éteignez toutes les lumières superflues de la pièce.', title_hi = 'अँधेरे से दोस्ती 🌙', body_hi = 'उसे जल्दी सुलाने के लिए शाम के रूटीन में अँधेरे से पहचान जोड़िए। कमरे की सारी अतिरिक्त लाइटें बंद कीजिए।', title_id = 'Bersahabat dengan gelap 🌙', body_id = 'Agar ia lebih cepat tertidur, kenalkan suasana gelap dalam rutinitas malam. Matikan semua lampu tambahan di kamar.', title_ja = '暗さと仲よしに 🌙', body_ja = '早く寝つけるように、夜のルーティンに暗さに慣れる時間を取り入れましょう。部屋のよけいな明かりはすべて消しましょう。', title_ko = '어둠과 친해지기 🌙', body_ko = '빨리 잠들 수 있도록 저녁 루틴에 어둠에 익숙해지는 시간을 더하세요. 방의 불필요한 조명을 모두 끄세요.', title_nl = 'Vriendschap met het donker 🌙', body_nl = 'Voeg kennismaking met het donker toe aan de avondroutine, zodat je baby sneller in slaap valt. Doe alle extra lampjes in de kamer uit.', title_pl = 'Przyjaźń z ciemnością 🌙', body_pl = 'Aby szybciej zasypiał, dodaj do wieczornej rutyny oswajanie z ciemnością. Wyłącz w pokoju wszystkie dodatkowe światła.', title_pt = 'Fazer amizade com o escuro 🌙', body_pt = 'Para o ajudar a adormecer mais depressa, junte à rotina da noite um momento de habituação ao escuro. Apague todas as luzes desnecessárias do quarto.', title_sv = 'Vänskap med mörkret 🌙', body_sv = 'Lägg till en stund i mörker i kvällsrutinen så att barnet somnar fortare. Släck alla onödiga lampor i rummet.', title_vi = 'Làm bạn với bóng tối 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy thêm bước làm quen với bóng tối vào nếp sinh hoạt buổi tối. Tắt hết đèn không cần thiết trong phòng.', title_zh = '和黑暗做朋友 🌙', body_zh = '为了让宝宝更快入睡，在晚间作息里加入熟悉黑暗的环节。关掉房间里所有多余的灯。' WHERE id = 'b55b3812-173b-489f-a2ae-d2c78611fd35' AND coalesce(title_es,'') = '' AND coalesc