UPDATE public.mommy_day_notifications SET title_es = 'Camina agarrado a la pared 🧗‍♀️', title_fr = 'Il marche en se tenant au mur 🧗‍♀️', title_hi = 'दीवार पकड़कर चलता है 🧗‍♀️', title_id = 'Berjalan berpegangan pada dinding 🧗‍♀️', title_ja = '壁づたいに歩く 🧗‍♀️', title_ko = '벽을 잡고 걸어요 🧗‍♀️', title_nl = 'Hij loopt langs de muur 🧗‍♀️', title_pl = 'Chodzi, trzymając się ściany 🧗‍♀️', title_pt = 'Anda agarrado à parede 🧗‍♀️', title_sv = 'Går längs väggen med stöd 🧗‍♀️', title_vi = 'Bám tường mà đi 🧗‍♀️', title_zh = '扶着墙走 🧗‍♀️' WHERE id = '8c12c251-a9b5-45cb-92ff-f145e2484025' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Control de los ruidos 🤫', body_es = 'La primera media hora después de dormirse es el momento más delicado. Comprueba el ambiente con el Medidor de sonido y evita los ruidos repentinos.', title_fr = 'Maîtriser les bruits 🤫', body_fr = 'La première demi-heure après l''endormissement est le moment le plus sensible. Vérifiez l''ambiance avec le Sonomètre et méfiez-vous des bruits soudains.', title_hi = 'आवाज़ों पर काबू 🤫', body_hi = 'सोने के बाद का पहला आधा घंटा सबसे नाज़ुक समय है। साउंड मीटर से माहौल जाँचिए और अचानक शोर से बचिए।', title_id = 'Mengatur suara 🤫', body_id = 'Setengah jam pertama setelah tertidur adalah waktu paling sensitif. Cek suasana dengan Pengukur Suara dan hindari suara bising mendadak.', title_ja = '音のコントロール 🤫', body_ja = '寝ついてから最初の30分は、いちばん眠りが浅い時間です。「サウンドメーター」で環境をチェックして、急な物音に気をつけましょう。', title_ko = '소리 관리 🤫', body_ko = '잠든 직후 처음 30분이 가장 예민한 시간이에요. 소음 측정기로 환경을 확인하고 갑작스러운 소음을 조심하세요.', title_nl = 'Geluiden onder controle 🤫', body_nl = 'Het eerste halfuur na het inslapen is het gevoeligst. Controleer de omgeving met de Geluidsmeter en pas op voor plotseling lawaai.', title_pl = 'Kontrola dźwięków 🤫', body_pl = 'Pierwsze pół godziny po zaśnięciu to najwrażliwszy czas. Sprawdź otoczenie Miernikiem dźwięku i uważaj na nagły hałas.', title_pt = 'Controlo dos sons 🤫', body_pt = 'A primeira meia hora depois de adormecer é a altura mais sensível. Verifique o ambiente com o Medidor de Som e cuidado com barulhos súbitos.', title_sv = 'Ljudkoll 🤫', body_sv = 'Den första halvtimmen efter att barnet har somnat är den känsligaste. Kolla miljön med Ljudmätaren och akta dig för plötsligt oväsen.', title_vi = 'Kiểm soát âm thanh 🤫', body_vi = 'Nửa tiếng đầu sau khi bé ngủ là lúc nhạy cảm nhất. Hãy kiểm tra môi trường bằng Đo âm thanh và cẩn thận với tiếng ồn đột ngột.', title_zh = '控制声音 🤫', body_zh = '入睡后的头半小时是最敏感的时候。用噪音测量检查环境，小心突然的噪音。' WHERE id = 'c7e52a2b-46d5-4446-b455-907f7523256e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de noche de papá 👨‍🍼', body_es = 'No cargues tú sola con todos los despertares nocturnos. Despierta también a tu pareja: ser un equipo es repartir la responsabilidad a partes iguales.', title_fr = 'Le service de nuit de papa 👨‍🍼', body_fr = 'Ne gérez pas les réveils nocturnes toute seule. Réveillez aussi votre conjoint, être une équipe, c''est partager la responsabilité à parts égales.', title_hi = 'पापा की रात की ड्यूटी 👨‍🍼', body_hi = 'रात में जागने का बोझ अकेले मत उठाइए। अपने साथी को भी जगाइए, टीम होने का मतलब है ज़िम्मेदारी बराबर बाँटना।', title_id = 'Giliran malam ayah 👨‍🍼', body_id = 'Jangan tanggung sendiri saat ia terbangun di malam hari. Bangunkan juga pasangan Anda, menjadi tim berarti berbagi tanggung jawab secara adil.', title_ja = 'パパの夜の当番 👨‍🍼', body_ja = '夜中に起きるのを、ひとりで抱えこまないで。パートナーも起こしましょう。チームとは責任を平等に分け合うことです。', title_ko = '아빠의 밤 당번 👨‍🍼', body_ko = '밤에 깨는 일을 혼자 다 감당하지 마세요. 배우자도 깨우세요, 한 팀이 된다는 건 책임을 똑같이 나누는 거예요.', title_nl = 'Papa''s avonddienst 👨‍🍼', body_nl = 'Draag het ''s nachts opstaan niet helemaal alleen. Maak je partner ook wakker, een team zijn betekent de verantwoordelijkheid eerlijk delen.', title_pl = 'Nocna zmiana taty 👨‍🍼', body_pl = 'Nie dźwigaj nocnych pobudek zupełnie sama. Obudź też partnera, bycie drużyną to równy podział odpowiedzialności.', title_pt = 'O turno da noite do pai 👨‍🍼', body_pt = 'Não aguente sozinha todos os despertares noturnos. Acorde também o seu companheiro: ser uma equipa é dividir a responsabilidade por igual.', title_sv = 'Pappas nattskift 👨‍🍼', body_sv = 'Ta inte nattuppvaknandena helt ensam. Väck din partner också, att vara ett lag är att dela ansvaret lika.', title_vi = 'Ca đêm của bố 👨‍🍼', body_vi = 'Đừng một mình gánh hết những lần thức dậy ban đêm. Hãy gọi cả bố dậy, là một đội nghĩa là chia đều trách nhiệm.', title_zh = '爸爸的夜班 👨‍🍼', body_zh = '夜醒别全都自己扛。也叫醒你的伴侣，团队就是平分责任。' WHERE id = '56403a92-c6d5-492f-b073-20bcd436f218' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Grandes emociones, cuerpo pequeño 🛑', title_fr = 'De grandes émotions dans un petit corps 🛑', title_hi = 'बड़ी भावनाएँ, छोटा शरीर 🛑', title_id = 'Emosi besar, tubuh kecil 🛑', title_ja = '大きな気持ち、小さな体 🛑', title_ko = '큰 감정, 작은 몸 🛑', title_nl = 'Grote gevoelens, klein lijfje 🛑', title_pl = 'Wielkie emocje, małe ciałko 🛑', title_pt = 'Grandes emoções, corpo pequenino 🛑', title_sv = 'Stora känslor, liten kropp 🛑', title_vi = 'Cảm xúc lớn, cơ thể nhỏ 🛑', title_zh = '大情绪，小身体 🛑' WHERE id = 'f47e2fcf-5030-43a8-a77b-79834cb3f95a' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidad de silencio 🤫', body_es = 'Protege la calma de la habitación con el Medidor de sonido. El sueño interrumpido por la noche estropea su humor por la mañana, y también el tuyo.', title_fr = 'Besoin de silence 🤫', body_fr = 'Protégez le calme de la chambre avec le Sonomètre. Un sommeil interrompu la nuit gâche l''humeur du matin, la sienne comme la vôtre.', title_hi = 'खामोशी की ज़रूरत 🤫', body_hi = 'साउंड मीटर से कमरे की शांति बनाए रखिए। रात में टूटी नींद उसका और आपका, दोनों का सुबह का मूड बिगाड़ देती है।', title_id = 'Butuh keheningan 🤫', body_id = 'Jaga ketenangan kamar dengan Pengukur Suara. Tidur yang terputus di malam hari merusak suasana hatinya dan juga Anda di pagi hari.', title_ja = '静けさが必要 🤫', body_ja = '「サウンドメーター」で部屋の静けさを守りましょう。夜中に途切れた眠りは、赤ちゃんとあなたの朝のごきげんを左右します。', title_ko = '고요함이 필요해요 🤫', body_ko = '소음 측정기로 방의 고요함을 지켜 주세요. 밤에 끊긴 잠은 아기와 엄마의 아침 기분을 모두 망쳐요.', title_nl = 'Behoefte aan stilte 🤫', body_nl = 'Bescherm de rust in de kamer met de Geluidsmeter. Een onderbroken nachtrust verpest de ochtendstemming van hem én van jou.', title_pl = 'Potrzeba ciszy 🤫', body_pl = 'Chroń spokój w pokoju Miernikiem dźwięku. Przerwany nocny sen psuje poranny nastrój i jemu, i tobie.', title_pt = 'Necessidade de silêncio 🤫', body_pt = 'Proteja a calma do quarto com o Medidor de Som. O sono interrompido à noite estraga o humor da manhã, o dele e o seu.', title_sv = 'Behovet av tystnad 🤫', body_sv = 'Skydda lugnet i rummet med Ljudmätaren. Avbruten nattsömn förstör både barnets och ditt humör på morgonen.', title_vi = 'Cần sự yên tĩnh 🤫', body_vi = 'Hãy giữ yên tĩnh cho căn phòng bằng Đo âm thanh. Giấc ngủ đêm bị gián đoạn làm hỏng tâm trạng buổi sáng của cả bé lẫn mẹ.', title_zh = '需要安静 🤫', body_zh = '用噪音测量守护房间的安静。夜里睡眠被打断，宝宝和你第二天早上的心情都会受影响。' WHERE id = 'a0e7f0f6-1438-4f75-acb4-559e4df47974' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un sitio para mamá ☕', title_fr = 'Un lieu pour maman ☕', title_hi = 'माँ के लिए जगह ☕', title_id = 'Tempat untuk Bunda ☕', title_ja = 'ママのための場所 ☕', title_ko = '엄마를 위한 공간 ☕', title_nl = 'Een plek voor mama ☕', title_pl = 'Miejsce dla mamy ☕', title_pt = 'Um lugar para a mãe ☕', title_sv = 'En plats för mamma ☕', title_vi = 'Không gian cho mẹ ☕', title_zh = '妈妈的空间 ☕' WHERE id = 'dfa800b1-6c2e-4bc9-b061-4b6d1df9eb95' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baile y ritmos 🎶', body_es = '¿Baila en cuanto oye un sonido rítmico en la tele o en el móvil? Su percepción musical está a pleno rendimiento, ¡únete y bailad juntos!', title_fr = 'Danse et rythmes 🎶', body_fr = 'Il danse dès qu''il entend un son rythmé à la télévision ou sur le téléphone ? Sa perception musicale est bien éveillée, dansez avec lui !', title_hi = 'नाच और ताल 🎶', body_hi = 'टीवी या फ़ोन पर कोई लयबद्ध आवाज़ सुनते ही नाचने लगता है? संगीत की समझ पूरी तरह जाग गई है, उसके साथ नाचिए!', title_id = 'Tarian dan irama 🎶', body_id = 'Begitu mendengar irama dari TV atau ponsel, ia langsung menari? Kepekaan musiknya sudah bekerja penuh, ikutlah menari bersamanya!', title_ja = 'ダンスとリズム 🎶', body_ja = 'テレビやスマホからリズムのある音が聞こえると、すぐに踊りだしますか？音楽を感じる力がすっかり目覚めています。一緒に踊りましょう！', title_ko = '춤과 리듬 🎶', body_ko = 'TV나 휴대폰에서 리듬 있는 소리가 들리자마자 춤을 추나요? 음악 감각이 완전히 깨어났어요, 함께 춤춰 주세요!', title_nl = 'Dans en ritme 🎶', body_nl = 'Begint je baby te dansen zodra hij een ritmisch geluid hoort op de tv of telefoon? Zijn gevoel voor muziek werkt helemaal, dans mee!', title_pl = 'Taniec i rytmy 🎶', body_pl = 'Gdy tylko usłyszy rytmiczny dźwięk z telewizora lub telefonu, tańczy? Odbiór muzyki działa pełną parą, przyłącz się i tańczcie!', title_pt = 'Dança e ritmos 🎶', body_pt = 'Mal ouve um som ritmado na televisão ou no telemóvel, começa a dançar? A perceção musical está a funcionar em pleno: junte-se a ele e dancem!', title_sv = 'Dans och rytmer 🎶', body_sv = 'Dansar barnet så fort det hör ett rytmiskt ljud på tv:n eller telefonen? Musikkänslan är fullt vaken, dansa med!', title_vi = 'Nhảy múa và nhịp điệu 🎶', body_vi = 'Vừa nghe thấy âm thanh có nhịp điệu trên tivi hay điện thoại là bé nhảy theo? Khả năng cảm thụ âm nhạc đã hoạt động hoàn toàn, hãy cùng nhảy với bé!', title_zh = '舞蹈与节奏 🎶', body_zh = '电视或手机里一传出有节奏的声音，宝宝就跳起舞来？音乐感知已经完全启动，和宝宝一起跳吧！' WHERE id = 'f34137b7-333a-47bb-8fab-66dd8be52bfb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Imitando a los mayores 🧹', body_es = '¿Mientras limpias la casa, coge un trapo e intenta hacer lo mismo? ¡Es tu espejo! Copia todo lo que haces.', title_fr = 'Imiter les grands 🧹', body_fr = 'Quand vous faites le ménage, il prend un chiffon et essaie de faire pareil ? C''est un miroir ! Il copie tout ce que vous faites.', title_hi = 'बड़ों की नकल 🧹', body_hi = 'आप घर पोंछती हैं तो वह भी कपड़ा लेकर वैसा ही करने की कोशिश करता है? वह आईना है! आप जो करती हैं, सब कॉपी करता है।', title_id = 'Meniru orang dewasa 🧹', body_id = 'Saat Anda mengelap rumah, ia juga mengambil lap dan mencoba melakukan hal yang sama? Ia adalah cermin! Ia meniru semua yang Anda lakukan.', title_ja = '大人のまねっこ 🧹', body_ja = 'あなたが家を拭いていると、赤ちゃんも布を持って同じことをしようとしますか？赤ちゃんは鏡です！あなたのすることをなんでもまねしています。', title_ko = '어른 따라 하기 🧹', body_ko = '엄마가 집을 닦을 때 아기도 천을 들고 똑같이 하려 하나요? 아기는 거울이에요! 엄마가 하는 모든 걸 따라 해요.', title_nl = 'De groten nadoen 🧹', body_nl = 'Pakt je baby ook een doekje en probeert hij hetzelfde te doen als jij aan het poetsen bent? Hij is een spiegel! Hij doet alles na wat jij doet.', title_pl = 'Naśladowanie dorosłych 🧹', body_pl = 'Gdy sprzątasz dom, on też bierze ściereczkę i próbuje robić to samo? Jest twoim lustrem! Kopiuje wszystko, co robisz.', title_pt = 'Imitar os crescidos 🧹', body_pt = 'Enquanto limpa a casa, ele pega num pano e tenta fazer o mesmo? É um espelho! Copia tudo o que faz.', title_sv = 'Härmar de vuxna 🧹', body_sv = 'Tar barnet en trasa och försöker göra likadant när du torkar av hemma? Det är en spegel! Det kopierar allt du gör.', title_vi = 'Bắt chước người lớn 🧹', body_vi = 'Khi mẹ lau nhà, bé cũng cầm khăn lên và cố làm theo? Bé là một tấm gương! Bé sao chép mọi điều mẹ làm.', title_zh = '模仿大人 🧹', body_zh = '你擦地时，宝宝也拿起抹布学着做？宝宝就是你的镜子！你做的每件事宝宝都会模仿。' WHERE id = '05e8d5ea-453b-4a35-a697-81e0b9ca911a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Parque o casa? ⛅', title_fr = 'Parc ou maison ? ⛅', title_hi = 'पार्क या घर? ⛅', title_id = 'Taman atau rumah? ⛅', title_ja = '公園？それともおうち？⛅', title_ko = '공원일까요, 집일까요? ⛅', title_nl = 'Park of thuis? ⛅', title_pl = 'Park czy dom? ⛅', title_pt = 'Parque ou casa? ⛅', title_sv = 'Park eller hemma? ⛅', title_vi = 'Công viên hay ở nhà? ⛅', title_zh = '去公园还是待在家？⛅' WHERE id = '13c2fa37-beb3-4b36-a1a9-4ba3fd32e6a0' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Noches difíciles 🥱', body_es = '¿Se resiste con todas sus fuerzas a dormirse? Vuelve a revisar sus siestas de día y la rutina.', title_fr = 'Des nuits difficiles 🥱', body_fr = 'Il résiste de toutes ses forces pour ne pas s''endormir ? Revoyez ses siestes et sa routine.', title_hi = 'ज़िद्दी रातें 🥱', body_hi = 'सोने से बचने के लिए पूरी ताकत से विरोध करता है? दिन की झपकियाँ और रूटीन फिर से जाँचिए।', title_id = 'Malam-malam yang alot 🥱', body_id = 'Ia melawan sekuat tenaga agar tidak tertidur? Periksa kembali tidur siang dan rutinitasnya.', title_ja = '手ごわい夜 🥱', body_ja = '眠るまいと全力で抵抗していますか？お昼寝とルーティンをもう一度見直しましょう。', title_ko = '고집스러운 밤 🥱', body_ko = '잠들지 않으려고 온 힘을 다해 버티나요? 낮잠과 루틴을 다시 점검해 보세요.', title_nl = 'Koppige nachten 🥱', body_nl = 'Verzet je baby zich met alle macht tegen het slapengaan? Bekijk de dutjes overdag en de routine opnieuw.', title_pl = 'Uparte noce 🥱', body_pl = 'Z całych sił opiera się zasypianiu? Jeszcze raz sprawdź drzemki w ciągu dnia i rutynę.', title_pt = 'Noites teimosas 🥱', body_pt = 'Resiste com todas as forças a adormecer? Volte a rever as sestas do dia e a rotina.', title_sv = 'Envisa nätter 🥱', body_sv = 'Kämpar barnet emot med all kraft för att inte somna? Se över dagsluren och rutinen igen.', title_vi = 'Những đêm bướng bỉnh 🥱', body_vi = 'Bé dồn hết sức để chống lại giấc ngủ? Hãy xem lại các giấc ngủ ngày và nếp sinh hoạt của bé.', title_zh = '倔强的夜晚 🥱', body_zh = '宝宝用尽全力抗拒睡觉？重新检查一下白天小睡和作息吧。' WHERE id = 'ecb2b9d1-a640-4303-b570-f3c7f463e0ab' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Limpiar o descansar? 🛋️', body_es = 'Cuando tu bebé duerma, no corras al lavavajillas. Túmbate en el sofá, cierra los ojos y simplemente respira durante 15 minutos.', title_fr = 'Ménage ou repos ? 🛋️', body_fr = 'Quand bébé dort, ne courez pas vers le lave-vaisselle. Allongez-vous sur le canapé, fermez les yeux et respirez simplement pendant 15 minutes.', title_hi = 'सफ़ाई या आराम? 🛋️', body_hi = 'बच्चे के सोते ही डिशवॉशर की ओर मत भागिए। सोफ़े पर लेट जाइए, आँखें बंद कीजिए और 15 मिनट बस साँस लीजिए।', title_id = 'Bersih-bersih atau istirahat? 🛋️', body_id = 'Saat si kecil tidur, jangan buru-buru ke mesin cuci piring. Berbaringlah di sofa, pejamkan mata, dan cukup bernapas selama 15 menit.', title_ja = 'お掃除？それとも休憩？🛋️', body_ja = '赤ちゃんが寝ても、食洗機に走らないで。ソファに横になって目を閉じ、15分間ただ呼吸しましょう。', title_ko = '청소할까요, 쉴까요? 🛋️', body_ko = '아이가 잘 때 식기세척기로 달려가지 마세요. 소파에 누워 눈을 감고 15분 동안 숨만 쉬세요.', title_nl = 'Schoonmaken of uitrusten? 🛋️', body_nl = 'Ren niet naar de vaatwasser als je baby slaapt. Ga op de bank liggen, sluit je ogen en adem 15 minuten gewoon.', title_pl = 'Sprzątać czy odpocząć? 🛋️', body_pl = 'Gdy maluszek śpi, nie biegnij do zmywarki. Połóż się na kanapie, zamknij oczy i przez 15 minut po prostu oddychaj.', title_pt = 'Limpar ou descansar? 🛋️', body_pt = 'Quando o bebé dorme, não corra para a máquina da loiça. Deite-se no sofá, feche os olhos e simplesmente respire durante 15 minutos.', title_sv = 'Städa eller vila? 🛋️', body_sv = 'Rusa inte till diskmaskinen när barnet sover. Lägg dig i soffan, blunda och bara andas i 15 minuter.', title_vi = 'Dọn dẹp hay nghỉ ngơi? 🛋️', body_vi = 'Bé vừa ngủ thì đừng vội lao đến máy rửa bát. Hãy nằm xuống sofa, nhắm mắt lại và chỉ hít thở trong 15 phút.', title_zh = '打扫还是休息？🛋️', body_zh = '宝宝睡着时别急着去洗碗机那边。躺在沙发上，闭上眼睛，呼吸15分钟就好。' WHERE id = '10934358-ef97-4dab-87ad-73a62aee1231' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Prueba y error 🧱', title_fr = 'Essais et erreurs 🧱', title_hi = 'कोशिश और गलती 🧱', title_id = 'Coba dan gagal 🧱', title_ja = '試行錯誤 🧱', title_ko = '시행착오 🧱', title_nl = 'Vallen en opstaan 🧱', title_pl = 'Próby i błędy 🧱', title_pt = 'Tentativa e erro 🧱', title_sv = 'Försök och misstag 🧱', title_vi = 'Thử và sai 🧱', title_zh = '尝试与犯错 🧱' WHERE id = '58866969-75c5-44cd-a308-210945d7a2af' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Diario emocional 📝', body_es = 'Cuando te sientas sola, vuelca tus emociones en el Diario de ánimo. Todas las mujeres pasan por este camino. Eres fuerte.', title_fr = 'Un journal des émotions 📝', body_fr = 'Quand vous vous sentez seule, déversez vos émotions dans le Journal d''humeur. Toutes les femmes passent par ces chemins, vous êtes forte.', title_hi = 'भावनाओं की डायरी 📝', body_hi = 'जब अकेली महसूस करें, तो अपनी भावनाएँ मूड डायरी में उड़ेल दीजिए। हर महिला इन रास्तों से गुज़रती है, आप मज़बूत हैं।', title_id = 'Buku harian perasaan 📝', body_id = 'Saat merasa sendirian, tuangkan perasaan Anda di Buku Harian Suasana Hati. Semua perempuan melewati jalan ini, Anda kuat.', title_ja = '気持ちの日記 📝', body_ja = 'ひとりぼっちだと感じたら、「気分日記」に気持ちを吐き出しましょう。どの女性もこの道を通ります。あなたは強い人です。', title_ko = '마음 일기 📝', body_ko = '외로울 때는 기분 일기에 감정을 쏟아 내세요. 모든 여성이 이 길을 지나요. 당신은 강해요.', title_nl = 'Een gevoelsdagboek 📝', body_nl = 'Voel je je alleen? Laat je gevoelens de vrije loop in je Stemmingsdagboek. Alle vrouwen gaan deze weg, je bent sterk.', title_pl = 'Dziennik emocji 📝', body_pl = 'Gdy czujesz się samotna, przelej swoje uczucia do Dziennika nastroju. Wszystkie kobiety przechodzą tę drogę, jesteś silna.', title_pt = 'Diário emocional 📝', body_pt = 'Quando se sentir sozinha, despeje o que sente no Diário de Humor. Todas as mulheres passam por estes caminhos: é forte.', title_sv = 'Känslodagbok 📝', body_sv = 'När du känner dig ensam, häll ut dina känslor i Humördagboken. Alla kvinnor går igenom de här vägarna, du är stark.', title_vi = 'Nhật ký cảm xúc 📝', body_vi = 'Khi thấy cô đơn, hãy trút cảm xúc vào Nhật ký tâm trạng. Người phụ nữ nào cũng đi qua những chặng đường này, mẹ mạnh mẽ lắm.', title_zh = '情绪日记 📝', body_zh = '觉得孤单时，就把感受倾诉在心情日记里。每个女人都会走过这些路，你很坚强。' WHERE id = '94a9a306-04fb-42bb-9962-95b473b02f89' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una foto que detiene el tiempo 📸', title_fr = 'La photo qui arrête le temps 📸', title_hi = 'समय को थाम लेने वाली तस्वीर 📸', title_id = 'Foto yang menghentikan waktu 📸', title_ja = '時間を止める1枚 📸', title_ko = '시간을 멈추는 한 컷 📸', title_nl = 'Een foto die de tijd stilzet 📸', title_pl = 'Kadr, który zatrzymuje czas 📸', title_pt = 'Uma foto que para o tempo 📸', title_sv = 'Bilden som stoppar tiden 📸', title_vi = 'Khoảnh khắc ngưng đọng thời gian 📸', title_zh = '定格时光 📸' WHERE id = '12139491-dd07-42f8-b056-98645d9880be' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
