UPDATE public.mommy_day_notifications SET title_es = 'Hora de juego independiente 🧸', title_fr = 'L''heure du jeu en solo 🧸', title_hi = 'अकेले खेलने का समय 🧸', title_id = 'Waktu bermain mandiri 🧸', title_ja = 'ひとり遊びの時間 🧸', title_ko = '혼자 노는 시간 🧸', title_nl = 'Tijd voor zelfstandig spelen 🧸', title_pl = 'Czas na samodzielną zabawę 🧸', title_pt = 'Hora de brincar sozinho 🧸', title_sv = 'Stund för egen lek 🧸', title_vi = 'Giờ chơi một mình 🧸', title_zh = '独立玩耍时间 🧸' WHERE id = '78f8f713-17f3-46f4-83f8-9cdbfd0c9894' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorando el tiempo ⛅', body_es = '¿No está claro qué tiempo hace fuera? Deja que la herramienta Tiempo y ropa te diga al instante la velocidad del viento y el conjunto adecuado.', title_fr = 'Bulletin météo ⛅', body_fr = 'Le temps dehors n''est pas très clair ? L''outil Météo et tenue vous indique aussitôt la vitesse du vent et la bonne tenue.', title_hi = 'मौसम की जासूसी ⛅', body_hi = 'बाहर मौसम साफ़ नहीं है? मौसम और कपड़े टूल आपको हवा की रफ़्तार और सही कपड़े तुरंत बताएगा।', title_id = 'Mengintip cuaca ⛅', body_id = 'Cuaca di luar tidak jelas? Biarkan fitur Cuaca dan Pakaian langsung memberi tahu kecepatan angin dan pakaian yang tepat.', title_ja = 'お天気チェック ⛅', body_ja = '外の天気がはっきりしない？「天気と服装」ツールが、風の強さとぴったりの服装をすぐに教えてくれます。', title_ko = '날씨 탐색 ⛅', body_ko = '바깥 날씨가 애매한가요? 날씨와 옷차림 도구가 바람 세기와 알맞은 옷차림을 바로 알려 줄 거예요.', title_nl = 'Het weer verkennen ⛅', body_nl = 'Is het weer buiten niet helemaal duidelijk? Laat de tool Weer en kleding je meteen de windsnelheid en de juiste outfit vertellen.', title_pl = 'Rozpoznanie pogody ⛅', body_pl = 'Pogoda na dworze niepewna? Niech narzędzie Pogoda i ubiór od razu powie ci, jak mocno wieje wiatr i jaki zestaw wybrać.', title_pt = 'Exploração do tempo ⛅', body_pt = 'O tempo lá fora não está bem definido? Deixe a ferramenta Tempo e Roupa dizer-lhe na hora a velocidade do vento e a roupa certa.', title_sv = 'Väderspaning ⛅', body_sv = 'Är vädret ute osäkert? Låt Väder och kläder direkt berätta vindstyrkan och rätt klädsel.', title_vi = 'Thám thính thời tiết ⛅', body_vi = 'Thời tiết bên ngoài không rõ ràng? Hãy để công cụ Thời tiết và trang phục cho mẹ biết ngay tốc độ gió và bộ đồ phù hợp.', title_zh = '天气侦察 ⛅', body_zh = '外面天气说不准？让天气穿衣工具马上告诉你风速和合适的搭配吧。' WHERE id = 'a72fe5b0-0907-43fb-b4ef-fc4dd880fecd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de noche de papá 👨‍🍼', body_es = 'No cargues tú sola con todos los despertares nocturnos. Despierta también a tu pareja: ser un equipo es repartir la responsabilidad a partes iguales.', title_fr = 'Le service de nuit de papa 👨‍🍼', body_fr = 'Ne gérez pas les réveils nocturnes toute seule. Réveillez aussi votre conjoint, être une équipe, c''est partager la responsabilité à parts égales.', title_hi = 'पापा की रात की ड्यूटी 👨‍🍼', body_hi = 'रात में जागने का बोझ अकेले मत उठाइए। अपने साथी को भी जगाइए, टीम होने का मतलब है ज़िम्मेदारी बराबर बाँटना।', title_id = 'Giliran malam ayah 👨‍🍼', body_id = 'Jangan tanggung sendiri saat ia terbangun di malam hari. Bangunkan juga pasangan Anda, menjadi tim berarti berbagi tanggung jawab secara adil.', title_ja = 'パパの夜の当番 👨‍🍼', body_ja = '夜中に起きるのを、ひとりで抱えこまないで。パートナーも起こしましょう。チームとは責任を平等に分け合うことです。', title_ko = '아빠의 밤 당번 👨‍🍼', body_ko = '밤에 깨는 일을 혼자 다 감당하지 마세요. 배우자도 깨우세요, 한 팀이 된다는 건 책임을 똑같이 나누는 거예요.', title_nl = 'Papa''s avonddienst 👨‍🍼', body_nl = 'Draag het ''s nachts opstaan niet helemaal alleen. Maak je partner ook wakker, een team zijn betekent de verantwoordelijkheid eerlijk delen.', title_pl = 'Nocna zmiana taty 👨‍🍼', body_pl = 'Nie dźwigaj nocnych pobudek zupełnie sama. Obudź też partnera, bycie drużyną to równy podział odpowiedzialności.', title_pt = 'O turno da noite do pai 👨‍🍼', body_pt = 'Não aguente sozinha todos os despertares noturnos. Acorde também o seu companheiro: ser uma equipa é dividir a responsabilidade por igual.', title_sv = 'Pappas nattskift 👨‍🍼', body_sv = 'Ta inte nattuppvaknandena helt ensam. Väck din partner också, att vara ett lag är att dela ansvaret lika.', title_vi = 'Ca đêm của bố 👨‍🍼', body_vi = 'Đừng một mình gánh hết những lần thức dậy ban đêm. Hãy gọi cả bố dậy, là một đội nghĩa là chia đều trách nhiệm.', title_zh = '爸爸的夜班 👨‍🍼', body_zh = '夜醒别全都自己扛。也叫醒你的伴侣，团队就是平分责任。' WHERE id = 'bac8ff9b-6338-4b34-a5d6-84b7aefd251c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Encuentro mi juguete yo solo 🧸', title_fr = 'Je retrouve mon jouet tout seul 🧸', title_hi = 'अपना खिलौना खुद ढूँढता हूँ 🧸', title_id = 'Aku menemukan mainanku sendiri 🧸', title_ja = 'おもちゃを自分で見つける 🧸', title_ko = '장난감은 내가 찾아요 🧸', title_nl = 'Ik vind mijn speeltje zelf 🧸', title_pl = 'Sam znajduję zabawkę 🧸', title_pt = 'Encontro sozinho o meu brinquedo 🧸', title_sv = 'Jag hittar min leksak själv 🧸', title_vi = 'Con tự tìm đồ chơi 🧸', title_zh = '我自己能找到玩具 🧸' WHERE id = 'c1daed2c-e22f-4c5a-8534-4ff90b6b866e' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Después de un día difícil, sentaos cara a cara tu pareja y tú y hablad. Apoyaros reparte la carga a la mitad.', body_fr = 'Après une journée difficile, asseyez-vous face à votre conjoint et parlez. Vous soutenir mutuellement allège la charge de moitié.', body_hi = 'मुश्किल दिन के बाद अपने साथी के साथ आमने-सामने बैठकर दिल की बात कीजिए। एक-दूसरे का साथ बोझ आधा कर देता है।', body_id = 'Setelah hari yang berat, duduklah berhadapan dengan pasangan dan saling bercerita. Saling mendukung membuat beban terbagi dua.', body_ja = '大変な1日のあとは、パートナーと向き合って話しましょう。支え合うことで、負担は半分になります。', body_ko = '힘든 하루를 보낸 뒤 배우자와 마주 앉아 이야기를 나눠 보세요. 서로를 응원하면 짐이 절반으로 줄어요.', body_nl = 'Ga na een zware dag tegenover je partner zitten en praat je hart uit. Elkaar steunen halveert de last.', body_pl = 'Po trudnym dniu usiądź z partnerem twarzą w twarz i porozmawiajcie. Wzajemne wsparcie dzieli ciężar na pół.', body_pt = 'Depois de um dia difícil, sente-se frente a frente com o seu companheiro e conversem. Apoiarem-se um ao outro divide o peso ao meio.', body_sv = 'Efter en tuff dag, sätt er mittemot varandra och prata ut med din partner. Att stötta varandra halverar bördan.', body_vi = 'Sau một ngày vất vả, hãy ngồi đối diện và tâm sự cùng bố. Cùng nâng đỡ nhau sẽ giúp gánh nặng vơi đi một nửa.', body_zh = '辛苦一天后，和伴侣面对面坐下聊聊。互相支持，担子就轻了一半。' WHERE id = '04429520-36d1-489e-8ec7-309a2c08ae92' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Entiende el significado de las palabras 🗣️', title_fr = 'Il connaît le sens des mots 🗣️', title_hi = 'शब्दों का मतलब समझता है 🗣️', title_id = 'Ia memahami arti kata 🗣️', title_ja = '言葉の意味がわかる 🗣️', title_ko = '말의 뜻을 알아요 🗣️', title_nl = 'Hij kent de betekenis van woorden 🗣️', title_pl = 'Rozumie znaczenie słów 🗣️', title_pt = 'Sabe o que as palavras significam 🗣️', title_sv = 'Barnet vet vad orden betyder 🗣️', title_vi = 'Bé hiểu nghĩa của từ 🗣️', title_zh = '听懂词语的意思 🗣️' WHERE id = '05fff0e7-029c-401c-bfab-497bbc099997' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lista en tu bolsillo 🛒', body_es = '¿Con el caos del día se ha acabado el champú o los pañales? No lo guardes en la cabeza: apúntalo en la Lista de la compra y sincronízala con tu pareja.', title_fr = 'La liste dans votre poche 🛒', body_fr = 'Dans le chaos du quotidien, plus de shampooing ou de couches ? Ne gardez pas tout en tête : notez-le dans la Liste de courses et synchronisez-la avec votre conjoint.', title_hi = 'आपकी जेब में लिस्ट 🛒', body_hi = 'रोज़ की अफ़रा-तफ़री में शैम्पू खत्म हुआ या डायपर? दिमाग में मत रखिए, शॉपिंग लिस्ट में लिखिए और अपने साथी के साथ सिंक कीजिए।', title_id = 'Daftar di saku Anda 🛒', body_id = 'Di tengah kekacauan sehari-hari, sampo atau popok habis? Jangan disimpan di kepala, tulis di Daftar Belanja dan sinkronkan dengan pasangan Anda.', title_ja = 'ポケットの中のリスト 🛒', body_ja = '毎日のカオスの中で、シャンプーやおむつが切れた？頭で覚えておかないで、「買い物リスト」に書いてパートナーと共有しましょう。', title_ko = '주머니 속 목록 🛒', body_ko = '정신없는 하루 속에 샴푸가 떨어졌나요, 기저귀인가요? 머릿속에 담아 두지 말고 쇼핑 목록에 적어 배우자와 공유하세요.', title_nl = 'Een lijstje in je broekzak 🛒', body_nl = 'Is in de dagelijkse chaos de shampoo of zijn de luiers op? Onthoud het niet, zet het op je Boodschappenlijstje en synchroniseer het met je partner.', title_pl = 'Lista w kieszeni 🛒', body_pl = 'W codziennym chaosie skończył się szampon czy pieluszki? Nie trzymaj tego w głowie, wpisz na Listę zakupów i zsynchronizuj z partnerem.', title_pt = 'A lista no seu bolso 🛒', body_pt = 'No caos do dia, acabou o champô ou as fraldas? Não guarde na cabeça: escreva na Lista de Compras e sincronize com o seu companheiro.', title_sv = 'Listan i fickan 🛒', body_sv = 'Tog schampot eller blöjorna slut i vardagskaoset? Håll det inte i huvudet, skriv upp det i Inköpslistan och synka med din partner.', title_vi = 'Danh sách trong túi mẹ 🛒', body_vi = 'Giữa bộn bề hằng ngày, hết dầu gội hay tã rồi? Đừng cố nhớ trong đầu, hãy ghi vào Danh sách mua sắm và đồng bộ với bố.', title_zh = '口袋里的清单 🛒', body_zh = '每天乱糟糟，洗发水还是尿布用完了？别靠脑子记，写进购物清单，和伴侣同步吧。' WHERE id = 'ec4b2f26-3631-4fed-9578-c9539a35a5c0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Entiende tu tono de voz 🗣️', body_es = '¿Se detiene y te mira cuando dices «no» con voz seria? ¡Ya empieza a captar las emociones y los límites!', title_fr = 'Il comprend le ton de votre voix 🗣️', body_fr = 'Il s''arrête net et vous regarde quand vous dites « non » d''une voix ferme ? Il commence déjà à saisir les émotions et les interdits !', title_hi = 'वह आपकी आवाज़ का लहजा समझता है 🗣️', body_hi = 'सख्त आवाज़ में ''ना'' कहने पर वह रुककर आपको देखता है? वह अब भावनाओं और मनाही को समझने लगा है!', title_id = 'Ia memahami nada suara Anda 🗣️', body_id = 'Saat Anda berkata "tidak" dengan suara tegas, ia berhenti dan menatap Anda? Ia mulai memahami emosi dan larangan!', title_ja = '声のトーンがわかる 🗣️', body_ja = 'きっぱりした声で「ダメ」と言うと、動きを止めてあなたを見ますか？感情や「してはいけないこと」を理解しはじめています！', title_ko = '엄마의 말투를 알아들어요 🗣️', body_ko = '단호한 목소리로 ''안 돼''라고 하면 멈칫하며 엄마를 바라보나요? 이제 감정과 금지를 이해하기 시작했어요!', title_nl = 'Hij begrijpt de toon van je stem 🗣️', body_nl = 'Stopt je baby even en kijkt hij je aan als je streng nee zegt? Hij begint emoties en verboden al te begrijpen!', title_pl = 'Rozumie ton twojego głosu 🗣️', body_pl = 'Gdy mówisz poważnym głosem „nie”, zatrzymuje się i na ciebie patrzy? Zaczyna już rozumieć emocje i zakazy!', title_pt = 'Percebe o seu tom de voz 🗣️', body_pt = 'Quando diz "não" com voz séria, ele para e olha para si? Já começa a perceber as emoções e as proibições!', title_sv = 'Barnet förstår ditt tonfall 🗣️', body_sv = 'Stannar barnet upp och tittar på dig när du säger nej med allvarlig röst? Det börjar redan förstå känslor och förbud!', title_vi = 'Bé hiểu giọng điệu của mẹ 🗣️', body_vi = 'Khi mẹ nói "không" với giọng nghiêm, bé khựng lại và nhìn mẹ? Bé đã bắt đầu hiểu cảm xúc và những điều bị cấm!', title_zh = '听得懂你的语气 🗣️', body_zh = '你用严肃的语气说“不”时，宝宝会停下来看着你？宝宝已经开始理解情绪和禁止了！' WHERE id = 'ceb1c77d-c486-4755-b204-47ec200fcd34' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora del masaje 💆‍♂️', body_es = 'Cuando tu bebé se duerma, organizad una sesión de masaje de hombros tu pareja y tú para soltar el estrés del día. ¡Sois un equipo!', title_fr = 'L''heure du massage 💆‍♂️', body_fr = 'Quand bébé dort, organisez une séance de massage des épaules avec votre conjoint pour évacuer le stress de la journée. Vous êtes une équipe !', title_hi = 'मालिश का समय 💆‍♂️', body_hi = 'बच्चे के सोने के बाद दिन का तनाव उतारने के लिए अपने साथी के साथ कंधे की मालिश का सेशन रखिए। आप एक टीम हैं!', title_id = 'Waktu pijat 💆‍♂️', body_id = 'Setelah si kecil tidur, adakan sesi pijat bahu bersama pasangan untuk melepas stres hari ini. Kalian satu tim!', title_ja = 'マッサージタイム 💆‍♂️', body_ja = '赤ちゃんが寝たら、1日のストレスを流すためにパートナーと肩もみタイムをつくりましょう。あなたたちはチームです！', title_ko = '마사지 시간 💆‍♂️', body_ko = '아이가 잠든 뒤 배우자와 함께 어깨 마사지 시간을 가지며 하루의 스트레스를 풀어 보세요. 두 사람은 한 팀이에요!', title_nl = 'Tijd voor een massage 💆‍♂️', body_nl = 'Plan als je baby slaapt een schoudermassage met je partner om de stress van de dag kwijt te raken. Jullie zijn een team!', title_pl = 'Czas na masaż 💆‍♂️', body_pl = 'Gdy maluszek zaśnie, zróbcie sobie z partnerem sesję masażu ramion, by zrzucić stres całego dnia. Jesteście drużyną!', title_pt = 'Hora da massagem 💆‍♂️', body_pt = 'Depois de o bebé adormecer, organize com o seu companheiro uma sessão de massagem aos ombros para libertar o stress do dia. São uma equipa!', title_sv = 'Massagedags 💆‍♂️', body_sv = 'När barnet har somnat, ordna en stund med axelmassage tillsammans med din partner för att släppa dagens stress. Ni är ett lag!', title_vi = 'Giờ mát-xa 💆‍♂️', body_vi = 'Sau khi bé ngủ, hãy cùng bố mát-xa vai cho nhau để xua tan căng thẳng trong ngày. Bố mẹ là một đội!', title_zh = '按摩时间 💆‍♂️', body_zh = '宝宝睡着后，和伴侣一起来一场肩部按摩，释放一天的压力。你们是一个团队！' WHERE id = '9e145532-f5a6-48ed-a07c-a3e9fc574858' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
