UPDATE public.mommy_day_notifications SET title_es = 'Juegos de lógica 🧩', title_fr = 'Jeux de logique 🧩', title_hi = 'तर्क वाले खेल 🧩', title_id = 'Permainan logika 🧩', title_ja = '考える遊び 🧩', title_ko = '논리 놀이 🧩', title_nl = 'Logische spelletjes 🧩', title_pl = 'Zabawy logiczne 🧩', title_pt = 'Jogos de lógica 🧩', title_sv = 'Logiklekar 🧩', title_vi = 'Trò chơi tư duy 🧩', title_zh = '逻辑游戏 🧩' WHERE id = '0a5f0553-0fcd-480d-a18f-a3ecfcfe950c' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hace falta desahogarse 💬', title_fr = 'Besoin de vous confier 💬', title_hi = 'दिल की बात करना ज़रूरी है 💬', title_id = 'Butuh teman bercerita 💬', title_ja = '話すことが必要なとき 💬', title_ko = '마음을 나눌 시간 💬', title_nl = 'Even je hart luchten 💬', title_pl = 'Czas się wygadać 💬', title_pt = 'Precisa de desabafar 💬', title_sv = 'Ibland behöver man prata av sig 💬', title_vi = 'Cần được tâm sự 💬', title_zh = '需要倾诉一下 💬' WHERE id = '66b4bd9b-8226-4190-94c7-9d50f8db6c34' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeña mente que pasa páginas 📖', title_fr = 'Un petit esprit qui feuillette les livres 📖', title_hi = 'किताबों के पन्ने पलटती समझ 📖', title_id = 'Si cerdas pembalik halaman 📖', title_ja = '絵本をめくる小さな知性 📖', title_ko = '책장을 넘기는 꼬마 박사 📖', title_nl = 'Een slimmerik die bladzijden omslaat 📖', title_pl = 'Mądrala przewracający kartki 📖', title_pt = 'Uma mente que folheia livros 📖', title_sv = 'Ett klokt huvud som bläddrar i böcker 📖', title_vi = 'Trí thông minh lật sách 📖', title_zh = '翻书的小脑瓜 📖' WHERE id = '80e6be85-6917-46a0-b283-acc653cca6c1' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baja las luces 🌙', body_es = 'Una hora antes de dormir, apaga todas las luces fuertes y las pantallas de casa. La melatonina solo se segrega en un ambiente tranquilo y con poca luz.', title_fr = 'Baissez les lumières 🌙', body_fr = '1 heure avant le coucher, éteignez toutes les lumières vives et les écrans de la maison. La mélatonine n''est sécrétée que dans un environnement calme et peu éclairé.', title_hi = 'लाइटें धीमी कीजिए 🌙', body_hi = 'सोने से 1 घंटा पहले घर की सारी तेज़ लाइटें और स्क्रीन बंद कर दीजिए। मेलाटोनिन शांत और कम रोशनी वाले माहौल में ही बनता है।', title_id = 'Redupkan lampu 🌙', body_id = 'Satu jam sebelum tidur, matikan semua lampu terang dan layar di rumah. Melatonin hanya diproduksi di lingkungan yang tenang dan redup.', title_ja = '明かりを落として 🌙', body_ja = '寝る1時間前には、家の強い明かりや画面をすべて消しましょう。メラトニンは、静かで明かりの少ない環境でこそ分泌されます。', title_ko = '조명을 낮춰요 🌙', body_ko = '잠들기 1시간 전에 집 안의 밝은 조명과 화면을 모두 끄세요. 멜라토닌은 조용하고 어두운 환경에서만 분비돼요.', title_nl = 'Doe de lichten zachter 🌙', body_nl = 'Doe 1 uur voor het slapengaan alle felle lampen en schermen in huis uit. Melatonine wordt alleen in een rustige omgeving met weinig licht aangemaakt.', title_pl = 'Przyciemnij światła 🌙', body_pl = 'Na godzinę przed snem wyłącz w domu wszystkie mocne światła i ekrany. Melatonina wydziela się tylko w spokojnym, słabo oświetlonym otoczeniu.', title_pt = 'Baixe as luzes 🌙', body_pt = '1 hora antes de dormir, apague as luzes desnecessárias e os ecrãs da casa. A melatonina só é produzida num ambiente calmo e com pouca luz.', title_sv = 'Dämpa ljuset 🌙', body_sv = 'Släck alla starka lampor och skärmar hemma 1 timme innan läggdags. Melatonin utsöndras bara i en lugn och svagt upplyst miljö.', title_vi = 'Giảm ánh sáng 🌙', body_vi = '1 tiếng trước giờ ngủ, hãy tắt hết đèn sáng và màn hình trong nhà. Melatonin chỉ được tiết ra trong môi trường yên tĩnh và ít ánh sáng.', title_zh = '调暗灯光 🌙', body_zh = '睡前1小时关掉家里所有的强光和屏幕。褪黑素只有在安静、光线昏暗的环境里才会分泌。' WHERE id = '70d7d4ed-5c06-44bc-99e5-3871d07a9510' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
