UPDATE public.mommy_day_notifications SET title_es = 'Pediatra exprés 🤖', title_fr = 'Le pédiatre express 🤖', title_hi = 'झटपट बाल रोग सलाह 🤖', title_id = 'Dokter anak kilat 🤖', title_ja = 'すばやく小児科の知識 🤖', title_ko = '빠른 소아과 상담 🤖', title_nl = 'Een snelle kinderarts 🤖', title_pl = 'Szybki pediatra 🤖', title_pt = 'Pediatra rápido 🤖', title_sv = 'Snabb barnläkare 🤖', title_vi = 'Bác sĩ nhi khoa nhanh chóng 🤖', title_zh = '快速儿科咨询 🤖' WHERE id = '005096a2-1549-4208-a331-7e39e1da9587' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El lado divertido de papá 🤡', body_es = 'La mejor forma de hacer reír al bebé es que papá haga ruidos raros. Disfrutad juntos con tu peque de los momentos alegres de esta noche.', title_fr = 'Papa en mode rigolo 🤡', body_fr = 'Le meilleur moyen de faire rire bébé, ce sont les bruits bizarres de papa. Savourez ensemble ces joyeux moments du soir.', title_hi = 'पापा का मज़ेदार अंदाज़ 🤡', body_hi = 'बच्चे को हँसाने का सबसे अच्छा तरीका है पापा की अजीब आवाज़ें। आज शाम के खुशी भरे पलों का बच्चे के साथ मिलकर आनंद लीजिए।', title_id = 'Ayah yang lucu 🤡', body_id = 'Cara terbaik membuat bayi tertawa adalah suara-suara aneh dari ayah. Nikmati momen ceria malam ini bersama si kecil.', title_ja = 'パパのおちゃめな一面 🤡', body_ja = '赤ちゃんを笑わせるいちばんの方法は、パパが変な声を出すこと。今夜の楽しい瞬間を、赤ちゃんと一緒に味わいましょう。', title_ko = '아빠의 유쾌한 모습 🤡', body_ko = '아기를 웃게 하는 가장 좋은 방법은 아빠의 이상한 소리예요. 오늘 저녁의 즐거운 순간을 아이와 함께 마음껏 누리세요.', title_nl = 'Papa de grapjas 🤡', body_nl = 'De beste manier om je baby aan het lachen te krijgen: papa die rare geluiden maakt. Geniet vanavond samen met je kindje van deze vrolijke momenten.', title_pl = 'Zabawny tata 🤡', body_pl = 'Najlepszy sposób, by rozśmieszyć maluszka, to dziwne dźwięki taty. Ciesz się razem z maluszkiem dzisiejszymi wesołymi chwilami.', title_pt = 'O lado divertido do pai 🤡', body_pt = 'A melhor forma de fazer o bebé rir é o pai fazer sons estranhos. Aproveite com o bebé os momentos alegres desta noite.', title_sv = 'Pappas roliga sida 🤡', body_sv = 'Det bästa sättet att få barnet att skratta är när pappa gör konstiga ljud. Njut av kvällens glada stunder tillsammans med barnet.', title_vi = 'Bố vui tính 🤡', body_vi = 'Cách tốt nhất để bé cười là bố tạo ra những âm thanh kỳ lạ. Hãy cùng bé tận hưởng những khoảnh khắc vui vẻ tối nay.', title_zh = '爸爸的搞笑时刻 🤡', body_zh = '逗宝宝笑最好的办法就是爸爸发出怪声。今晚和宝宝一起尽情享受这些欢乐的时刻吧。' WHERE id = '9089b5ba-67c3-48ba-a5c3-8e428c87d9ec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La calma de la noche 🛀', body_es = 'Baño templado, masaje y habitación a oscuras. Mantener la rutina de sueño es el secreto básico para tener noches sin interrupciones.', title_fr = 'La sérénité du soir 🛀', body_fr = 'Bain tiède, massage et pièce assombrie. Préserver la routine du coucher, c''est le secret fondamental des nuits sans interruption.', title_hi = 'रात का सुकून 🛀', body_hi = 'गुनगुना स्नान, मालिश और कमरे में अँधेरा। सोने का रूटीन बनाए रखना बिना रुकावट वाली रातों का सबसे बुनियादी राज़ है।', title_id = 'Ketenangan malam 🛀', body_id = 'Mandi air hangat, pijat, dan kamar yang diredupkan. Menjaga rutinitas tidur adalah rahasia utama malam tanpa terbangun.', title_ja = '夜のやすらぎ 🛀', body_ja = 'ぬるめのお風呂、マッサージ、部屋を暗くする。ねんねのルーティンを守ることが、途切れない夜のいちばんの基本のひみつです。', title_ko = '밤의 평온 🛀', body_ko = '따뜻한 목욕, 마사지, 어두운 방. 잠자리 루틴을 지키는 것이 깨지 않는 밤의 가장 기본적인 비결이에요.', title_nl = 'De rust van de nacht 🛀', body_nl = 'Een lauw badje, een massage en een verduisterde kamer. De slaaproutine bewaken is het belangrijkste geheim van ononderbroken nachten.', title_pl = 'Spokój nocy 🛀', body_pl = 'Ciepła kąpiel, masaż i przyciemniony pokój. Pilnowanie rytuału snu to podstawowy sekret nieprzerwanych nocy.', title_pt = 'A calma da noite 🛀', body_pt = 'Banho morno, massagem e quarto escurecido. Manter a rotina de sono é o segredo mais básico para noites sem interrupções.', title_sv = 'Nattens ro 🛀', body_sv = 'Ett ljummet bad, massage och ett mörkt rum. Att hålla fast vid sömnrutinen är den mest grundläggande hemligheten bakom nätter utan avbrott.', title_vi = 'Sự bình yên của màn đêm 🛀', body_vi = 'Tắm nước ấm, mát-xa và làm tối phòng. Giữ nếp sinh hoạt trước khi ngủ là bí quyết cơ bản nhất cho những đêm ngủ trọn giấc.', title_zh = '夜晚的宁静 🛀', body_zh = '温水澡、按摩、调暗房间。守护好睡前作息，是夜夜安睡最基本的秘诀。' WHERE id = '47368a03-c0f0-4e5c-a343-b4577d2ffa64' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
