UPDATE public.mommy_day_notifications SET title_es = 'Sueño sensible 🤫', title_fr = 'Un sommeil sensible 🤫', title_hi = 'नींद में संवेदनशीलता 🤫', title_id = 'Tidur yang sensitif 🤫', title_ja = '眠りが浅い 🤫', title_ko = '예민한 잠 🤫', title_nl = 'Gevoelig voor geluid tijdens het slapen 🤫', title_pl = 'Wrażliwy sen 🤫', title_pt = 'Sono sensível 🤫', title_sv = 'Känslig sömn 🤫', title_vi = 'Giấc ngủ nhạy cảm 🤫', title_zh = '睡眠敏感 🤫' WHERE id = '1e376436-3f0d-4a14-a96b-e1c16c40c937' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Estoy hablando! 🗣️', body_es = '¿Inventa sílabas como ba-ba o ma-ma? Abre el Seguimiento del desarrollo, registra este gran salto en el lenguaje y háblale mucho.', title_fr = 'Je parle ! 🗣️', body_fr = 'Il invente des syllabes comme « ba-ba » ou « ma-ma » ? Ouvrez le Suivi de développement, notez ce grand bond du langage et parlez-lui beaucoup.', title_hi = 'मैं बोल रहा हूँ! 🗣️', body_hi = 'बा-बा, मा-मा जैसे अक्षर बोलने लगा है? ग्रोथ ट्रैकर खोलिए, भाषा की इस बड़ी छलांग को दर्ज कीजिए और उससे खूब बातें कीजिए।', title_id = 'Aku sedang bicara! 🗣️', body_id = 'Ia mulai mengoceh "ba-ba" atau "ma-ma"? Buka Pelacak Perkembangan, catat lompatan bahasa yang besar ini, dan ajak ia banyak mengobrol.', title_ja = 'おしゃべりしてるよ！🗣️', body_ja = '「ばーば」「まーま」みたいな音を出していますか？「発達トラッカー」を開いて、この大きな言葉の成長を記録し、たくさん話しかけてあげましょう。', title_ko = '저 말하고 있어요! 🗣️', body_ko = '바바, 마마 같은 소리를 지어내나요? 성장 기록을 열어 이 큰 언어 도약을 기록하고 아기와 많이 이야기해 주세요.', title_nl = 'Ik praat! 🗣️', body_nl = 'Brabbelt je baby lettergrepen als ba-ba en ma-ma? Open de Groeitracker, noteer deze grote taalsprong en praat veel met je kleintje.', title_pl = 'Mówię! 🗣️', body_pl = 'Wymyśla sylaby jak ba-ba, ma-ma? Otwórz Śledzenie rozwoju, zapisz ten wielki skok w rozwoju mowy i dużo z nim rozmawiaj.', title_pt = 'Estou a falar! 🗣️', body_pt = 'Inventa sílabas como ba-ba, ma-ma? Abra o Registo de Desenvolvimento, assinale este grande salto na linguagem e converse muito com ele.', title_sv = 'Jag pratar! 🗣️', body_sv = 'Hittar barnet på stavelser som ba-ba och ma-ma? Öppna Utvecklingsspåraren, anteckna det här stora språksprånget och prata massor med barnet.', title_vi = 'Con đang nói đấy! 🗣️', body_vi = 'Bé bập bẹ những âm như "ba-ba", "ma-ma"? Mở Theo dõi phát triển, ghi lại bước tiến ngôn ngữ lớn này và trò chuyện với bé thật nhiều nhé.', title_zh = '我会说话啦！🗣️', body_zh = '宝宝在发“ba-ba”“ma-ma”这样的音节吗？打开发育追踪，记下这次语言上的大飞跃，多和宝宝说说话吧。' WHERE id = '0fa7eced-c60c-4055-8da1-5df4e54ec1ce' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
