UPDATE public.mommy_day_notifications SET title_es = 'Hoy en Cuentos inteligentes 🪄', title_fr = 'Aujourd''hui dans les Contes intelligents 🪄', title_hi = 'आज स्मार्ट कहानियों में 🪄', title_id = 'Hari ini di Dongeng Pintar 🪄', title_ja = '今日の「スマートおはなし」🪄', title_ko = '오늘의 스마트 동화 🪄', title_nl = 'Vandaag in Slimme sprookjes 🪄', title_pl = 'Dziś w Mądrych bajkach 🪄', title_pt = 'Hoje nas Histórias Inteligentes 🪄', title_sv = 'I dag i Smarta sagor 🪄', title_vi = 'Hôm nay trong Truyện cổ tích thông minh 🪄', title_zh = '今天的智能故事 🪄' WHERE id = 'e7bfaacc-c0cc-4b36-8687-477371b3bc3d' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Deja salir tus emociones 📝', title_fr = 'Libérez vos émotions 📝', title_hi = 'अपनी भावनाओं को बाहर आने दीजिए 📝', title_id = 'Lepaskan perasaan Anda 📝', title_ja = '気持ちを解き放とう 📝', title_ko = '감정을 자유롭게 풀어 주세요 📝', title_nl = 'Laat je gevoelens de vrije loop 📝', title_pl = 'Uwolnij emocje 📝', title_pt = 'Liberte as emoções 📝', title_sv = 'Släpp fram känslorna 📝', title_vi = 'Hãy giải phóng cảm xúc 📝', title_zh = '释放你的情绪 📝' WHERE id = '2859fc00-366b-44b7-ba24-815b9b659125' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un momento de calma ☕', body_es = 'El desorden de la habitación no se va a ir a ninguna parte. Mientras tu peque juega solo, tómate tu café y disfruta de la tranquilidad.', title_fr = 'Un moment de calme ☕', body_fr = 'Le désordre ne va pas s''envoler. Pendant que votre enfant joue seul, buvez simplement votre café et savourez le calme de la pièce.', title_hi = 'सुकून का पल ☕', body_hi = 'कमरे का बिखराव कहीं नहीं भागेगा। जब बच्चा अपने आप खेल रहा हो, बस अपनी कॉफ़ी पीजिए और कमरे की शांति का आनंद लीजिए।', title_id = 'Momen tenang ☕', body_id = 'Ruangan yang berantakan tidak akan ke mana-mana. Selagi si kecil bermain sendiri, nikmati kopi Anda dan ketenangan ruangan.', title_ja = 'ほっとひと息 ☕', body_ja = '部屋の散らかりはどこにも逃げません。赤ちゃんがひとりで遊んでいる間は、コーヒーを飲んで静かな時間を楽しみましょう。', title_ko = '고요한 순간 ☕', body_ko = '어질러진 방은 어디 가지 않아요. 아이가 혼자 노는 동안 커피를 마시며 방의 고요함을 즐겨 보세요.', title_nl = 'Een moment van rust ☕', body_nl = 'De rommel in de kamer loopt niet weg. Terwijl je kleintje zelf speelt, drink je gewoon je koffie en geniet je van de stilte.', title_pl = 'Chwila ciszy ☕', body_pl = 'Bałagan w pokoju nigdzie nie ucieknie. Gdy maluszek bawi się sam, po prostu wypij kawę i ciesz się ciszą.', title_pt = 'Um momento de silêncio ☕', body_pt = 'A desarrumação do quarto não vai fugir. Enquanto o bebé brinca sozinho, beba o seu café e aproveite a calma do quarto.', title_sv = 'En stund av stillhet ☕', body_sv = 'Stöket i rummet springer ingenstans. Medan barnet leker på egen hand, drick bara ditt kaffe och njut av lugnet.', title_vi = 'Khoảnh khắc bình yên ☕', body_vi = 'Căn phòng bừa bộn cũng chẳng chạy đi đâu. Trong lúc bé tự chơi, mẹ cứ nhâm nhi cà phê và tận hưởng sự yên tĩnh nhé.', title_zh = '片刻宁静 ☕', body_zh = '房间乱一点也跑不了。趁宝宝自己玩的时候，安心喝杯咖啡，享受这份安静吧。' WHERE id = '19b9faef-1d59-42d5-bcb0-12290f627a1f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Aguanta más tiempo boca abajo? 🐢', body_es = 'Sus músculos se fortalecen día a día. Pon juguetes de colores delante de tu bebé y haz que sea aún más divertido.', title_fr = 'Il reste plus longtemps sur le ventre ? 🐢', body_fr = 'Ses muscles se renforcent de jour en jour. Posez un jouet coloré devant lui pour rendre ce moment encore plus amusant.', title_hi = 'पेट के बल ज़्यादा देर रहता है? 🐢', body_hi = 'उसकी मांसपेशियाँ दिन-ब-दिन मज़बूत हो रही हैं। उसके सामने रंगीन खिलौने रखकर इसे और भी मज़ेदार बनाइए।', title_id = 'Lebih lama tengkurap? 🐢', body_id = 'Ototnya makin kuat dari hari ke hari. Letakkan mainan berwarna di depannya agar prosesnya makin seru.', title_ja = 'うつぶせの時間が長くなった？ 🐢', body_ja = '筋肉が日に日に強くなっています。目の前にカラフルなおもちゃを置いて、もっと楽しい時間にしましょう。', title_ko = '엎드려 있는 시간이 길어졌나요? 🐢', body_ko = '근육이 날마다 튼튼해지고 있어요. 앞에 알록달록한 장난감을 놓아 이 시간을 더 즐겁게 만들어 주세요.', title_nl = 'Langer op de buik? 🐢', body_nl = 'De spiertjes worden elke dag sterker. Leg een kleurig speeltje voor je baby neer en maak het nog leuker.', title_pl = 'Dłużej leży na brzuszku? 🐢', body_pl = 'Jego mięśnie z dnia na dzień są silniejsze. Połóż przed nim kolorową zabawkę, a będzie jeszcze weselej.', title_pt = 'Fica mais tempo de barriga para baixo?  🐢', body_pt = 'Os músculos estão cada dia mais fortes. Torne este momento ainda mais divertido pondo um brinquedo colorido à frente dele.', title_sv = 'Ligger längre på magen? 🐢', body_sv = 'Musklerna blir starkare för varje dag. Gör det ännu roligare genom att lägga en färgglad leksak framför barnet.', title_vi = 'Bé nằm sấp được lâu hơn?  🐢', body_vi = 'Cơ bắp của bé khỏe lên từng ngày. Hãy đặt đồ chơi nhiều màu sắc trước mặt bé để việc này thêm vui nhé.', title_zh = '趴着的时间更长了？🐢', body_zh = '宝宝的肌肉一天比一天有力。在宝宝面前放个彩色玩具，让练习变得更有趣吧。' WHERE id = '290cd0a7-b2db-4a34-8b28-f8d9bbc37b62' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
