UPDATE public.mommy_day_notifications SET title_es = 'La responsabilidad de papá 👨‍🍼', title_fr = 'La responsabilité de papa 👨‍🍼', title_hi = 'पापा की ज़िम्मेदारी 👨‍🍼', title_id = 'Tanggung jawab ayah 👨‍🍼', title_ja = 'パパの役目 👨‍🍼', title_ko = '아빠의 책임 👨‍🍼', title_nl = 'Papa''s verantwoordelijkheid 👨‍🍼', title_pl = 'Obowiązki taty 👨‍🍼', title_pt = 'A responsabilidade do pai 👨‍🍼', title_sv = 'Pappas ansvar 👨‍🍼', title_vi = 'Trách nhiệm của bố 👨‍🍼', title_zh = '爸爸的责任 👨‍🍼' WHERE id = 'f7c61cc4-7a2d-48d0-bf89-ec947a89cd75' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cascada de babas 🤤', body_es = '¿Se le moja el cuello de la ropa a menudo? Ten siempre a mano un mordedor de silicona.', title_fr = 'Une cascade de bave 🤤', body_fr = 'Son col est souvent mouillé ? Gardez toujours un anneau de dentition en silicone à portée de main.', title_hi = 'लार का झरना 🤤', body_hi = 'उसका कॉलर बार-बार गीला होने लगा है? हाथ के पास हमेशा एक सिलिकॉन टीदर रखिए।', title_id = 'Air liur bak air terjun 🤤', body_id = 'Kerah bajunya sering basah? Selalu siapkan teether silikon di dekat Anda.', title_ja = 'よだれの滝 🤤', body_ja = 'えりがよくぬれるようになりましたか？シリコン製の歯固めを必ず手元に置いておきましょう。', title_ko = '침이 폭포처럼 🤤', body_ko = '옷깃이 자주 젖기 시작했나요? 손 닿는 곳에 실리콘 치발기를 꼭 준비해 두세요.', title_nl = 'Een waterval van kwijl 🤤', body_nl = 'Is het kraagje vaak nat? Houd zeker een siliconen bijtring bij de hand.', title_pl = 'Wodospad śliny 🤤', body_pl = 'Ubranko pod szyją często jest mokre? Zawsze miej pod ręką silikonowy gryzak.', title_pt = 'Uma cascata de baba 🤤', body_pt = 'A gola anda sempre molhada? Tenha sempre à mão um mordedor de silicone.', title_sv = 'Dregelvattenfall 🤤', body_sv = 'Blir kragen ofta blöt? Ha alltid en bitring i silikon nära till hands.', title_vi = 'Thác nước dãi 🤤', body_vi = 'Cổ áo bé hay bị ướt? Mẹ nhớ luôn để sẵn một chiếc gặm nướu silicone bên mình nhé.', title_zh = '口水瀑布 🤤', body_zh = '衣领经常湿湿的？手边一定要备好硅胶牙胶。' WHERE id = '431c0c7a-2968-4edd-9882-df9a926adf72' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ha sido un día difícil? Escribe con sinceridad todo tu cansancio en el Diario de ánimo.', body_fr = 'La journée a été difficile ? Écrivez sincèrement toute votre fatigue dans le Journal d''humeur.', body_hi = 'आज का दिन मुश्किल था? अपनी सारी थकान मूड डायरी में सच्चे मन से लिख दीजिए।', body_id = 'Hari yang berat? Tuliskan semua rasa lelah Anda dengan jujur di Buku Harian Suasana Hati.', body_ja = '大変な1日でしたか？「気分日記」に疲れた気持ちを正直に書いてみましょう。', body_ko = '힘든 하루였나요? 기분 일기에 쌓인 피로를 솔직하게 적어 보세요.', body_nl = 'Was het een zware dag? Schrijf al je vermoeidheid eerlijk op in je Stemmingsdagboek.', body_pl = 'Trudny dzień? Szczerze opisz całe swoje zmęczenie w Dzienniku nastroju.', body_pt = 'Foi um dia difícil? Escreva com sinceridade todo o seu cansaço no Diário de Humor.', body_sv = 'Har det varit en tung dag? Skriv ärligt ner all din trötthet i Humördagboken.', body_vi = 'Hôm nay là một ngày vất vả? Hãy viết hết mọi mệt mỏi của mình vào Nhật ký tâm trạng một cách chân thật nhé.', body_zh = '今天很辛苦吗？把所有的疲惫真诚地写进心情日记吧。' WHERE id = '0140116f-1e50-4656-93a0-277a1645b1ba' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se acaban los pañales o las toallitas? Añádelos ya a la Lista de la compra y tu pareja recibirá un aviso en su móvil.', body_fr = 'Plus de couches ou de lingettes ? Ajoutez-les tout de suite à la Liste de courses pour qu''une notification arrive sur le téléphone de votre conjoint.', body_hi = 'डायपर या वेट वाइप्स खत्म हो रहे हैं? भूलने से पहले शॉपिंग लिस्ट में जोड़िए, ताकि आपके साथी के फ़ोन पर सूचना पहुँच जाए।', body_id = 'Popok atau tisu basah mau habis? Segera tambahkan ke Daftar Belanja, dan notifikasi akan dikirim ke ponsel pasangan Anda.', body_ja = 'おむつやおしりふきがなくなりそう？忘れないうちに「買い物リスト」に追加すれば、パートナーのスマホに通知が届きます。', body_ko = '기저귀나 물티슈가 떨어져 가나요? 잊기 전에 쇼핑 목록에 추가하면 배우자 휴대폰으로 알림이 가요.', body_nl = 'Bijna geen luiers of billendoekjes meer? Zet ze meteen op je Boodschappenlijstje, dan krijgt je partner een melding op zijn telefoon.', body_pl = 'Kończą się pieluszki albo chusteczki nawilżane? Od razu dodaj je do Listy zakupów, a partner dostanie powiadomienie na telefon.', body_pt = 'Estão a acabar as fraldas ou os toalhetes? Junte-os já à Lista de Compras e o seu companheiro recebe uma notificação no telemóvel.', body_sv = 'Håller blöjorna eller våtservetterna på att ta slut? Lägg till dem i Inköpslistan innan du glömmer, så får din partner en notis i telefonen.', body_vi = 'Sắp hết tã hay khăn ướt? Thêm ngay vào Danh sách mua sắm kẻo quên, thông báo sẽ được gửi đến điện thoại của bố.', body_zh = '尿布或湿巾快用完了？趁还记得加进购物清单，让通知直接发到伴侣手机上。' WHERE id = '1f632261-0ec6-4f1f-be74-71aaaaf4c706' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
