UPDATE public.mommy_day_notifications SET title_es = '¡Mi juguete no lo doy! 🧸', title_fr = 'Je ne donne pas mon jouet ! 🧸', title_hi = 'अपना खिलौना नहीं दूँगा! 🧸', title_id = 'Mainanku tidak akan kuberikan! 🧸', title_ja = 'おもちゃは渡さない！🧸', title_ko = '내 장난감은 안 줄래요! 🧸', title_nl = 'Mijn speeltje geef ik niet af! 🧸', title_pl = 'Nie oddam zabawki! 🧸', title_pt = 'Não dou o meu brinquedo! 🧸', title_sv = 'Jag ger inte bort min leksak! 🧸', title_vi = 'Con không đưa đồ chơi đâu! 🧸', title_zh = '我的玩具不给你！🧸' WHERE id = '09d17b10-a60b-4930-b773-b0f5bb7e0366' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Comparte tu experiencia 💬', body_es = '¿Te preguntas si solo te pasa a ti? Entra en la Comunidad Anacan y desahógate con mamás que sienten lo mismo.', title_fr = 'Partagez votre expérience 💬', body_fr = 'Vous vous demandez : « Suis-je la seule dans ce cas ? » Rejoignez la Communauté Anacan et échangez avec des mamans qui ressentent la même chose.', title_hi = 'अपना अनुभव बाँटिए 💬', body_hi = 'सोचती हैं, ''क्या सिर्फ़ मैं ही ऐसी हूँ?'' Anacan कम्युनिटी में आइए और ऐसी ही भावनाओं से गुज़र रही माँओं से दिल की बात कीजिए।', title_id = 'Bagikan pengalaman Anda 💬', body_id = 'Pernah berpikir, "Apa cuma aku yang begini?" Bergabunglah di Komunitas Anacan dan mengobrol dengan ibu-ibu yang merasakan hal serupa.', title_ja = '経験をシェアしよう 💬', body_ja = '「こんなふうに感じるのは私だけ？」と思っていませんか？Anacanコミュニティに参加して、同じ気持ちのママたちと話してみましょう。', title_ko = '경험을 나눠요 💬', body_ko = '''나만 이런 걸까?'' 하고 생각하나요? Anacan 커뮤니티에 들어와 같은 마음을 겪는 엄마들과 이야기를 나눠 보세요.', title_nl = 'Deel je ervaring 💬', body_nl = 'Denk je weleens: ben ik de enige die zich zo voelt? Ga naar de Anacan Community en praat met moeders die hetzelfde voelen.', title_pl = 'Podziel się doświadczeniem 💬', body_pl = 'Zastanawiasz się, czy tylko ty tak masz? Dołącz do Społeczności Anacan i porozmawiaj z mamami, które czują to samo.', title_pt = 'Partilhe a sua experiência 💬', body_pt = 'Pergunta-se se é só consigo? Entre na Comunidade Anacan e desabafe com mães que sentem o mesmo.', title_sv = 'Dela din erfarenhet 💬', body_sv = 'Undrar du om det bara är du som känner så här? Gå in i Anacans Community och prata med mammor som känner likadant.', title_vi = 'Chia sẻ trải nghiệm 💬', body_vi = 'Mẹ tự hỏi "Chẳng lẽ chỉ mình mình thế này?" Hãy vào Cộng đồng Anacan và tâm sự với những bà mẹ có cùng cảm xúc.', title_zh = '分享你的经历 💬', body_zh = '总在想“是不是只有我这样”？加入Anacan社区，和有同样感受的妈妈们聊聊吧。' WHERE id = '1c68be5f-505e-4c46-be58-571a7196e98d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se frota los ojos o se tira de las orejas? No esperes a la crisis de sueño: oscurece la habitación ya y empieza la rutina de la noche.', body_fr = 'Il se frotte les yeux, se tire les oreilles ? N''attendez pas la crise de sommeil : assombrissez tout de suite la pièce et lancez la routine du soir.', body_hi = 'आँखें मल रहा है, कान खींच रहा है? नींद के संकट का इंतज़ार मत कीजिए, तुरंत कमरे में अँधेरा करके शाम का रूटीन शुरू कीजिए।', body_id = 'Ia mengucek mata atau menarik telinga? Jangan tunggu sampai rewel karena mengantuk, segera redupkan kamar dan mulai rutinitas malam.', body_ja = '目をこすったり、耳を引っぱったりしていますか？ぐずりが爆発する前に、すぐに部屋を暗くして夜のルーティンを始めましょう。', body_ko = '눈을 비비고 귀를 잡아당기나요? 잠투정이 시작되기 전에 바로 방을 어둡게 하고 저녁 루틴을 시작하세요.', body_nl = 'Wrijft je baby in de oogjes of trekt hij aan de oortjes? Wacht niet op een slaapcrisis, maak de kamer meteen donker en begin met de avondroutine.', body_pl = 'Trze oczka, ciągnie się za uszko? Nie czekaj na kryzys senny, od razu przyciemnij pokój i zacznij wieczorną rutynę.', body_pt = 'Esfrega os olhos, puxa as orelhas? Não espere pela crise de sono: escureça já o quarto e comece a rotina da noite.', body_sv = 'Gnuggar barnet ögonen eller drar i örat? Vänta inte på sömnkrisen, gör rummet mörkt direkt och starta kvällsrutinen.', body_vi = 'Bé dụi mắt, kéo tai? Đừng đợi đến lúc bé quấy vì buồn ngủ, hãy tắt bớt đèn ngay và bắt đầu nếp sinh hoạt buổi tối.', body_zh = '宝宝在揉眼睛、拽耳朵？别等到闹觉才行动，马上调暗房间，开始晚间作息吧。' WHERE id = '4b6ccde7-7cce-4142-8822-fa952592f465' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Campeón de las vueltas 🤸‍♂️', body_es = '¿Intenta girarse de espaldas a boca abajo y de boca abajo a espaldas? Nunca le dejes solo en la cama y disfruta de esta etapa tan movida.', title_fr = 'Champion du retournement 🤸‍♂️', body_fr = 'Il essaie de passer du dos au ventre et du ventre au dos ? Ne le laissez jamais seul sur le lit et profitez de cette période pleine de mouvement.', title_hi = 'पलटने का चैंपियन 🤸‍♂️', body_hi = 'पीठ से पेट के बल और पेट से पीठ के बल पलटने की कोशिश कर रहा है? उसे बिस्तर पर कभी अकेला मत छोड़िए और इस चुलबुले दौर का आनंद लीजिए।', title_id = 'Juara berguling 🤸‍♂️', body_id = 'Ia mencoba berguling dari telentang ke tengkurap dan sebaliknya? Jangan pernah meninggalkannya sendirian di kasur, dan nikmati masa aktif ini.', title_ja = '寝返りチャンピオン 🤸‍♂️', body_ja = '仰向けからうつぶせ、うつぶせから仰向けに寝返りしようとしていますか？ベッドの上にひとりにしないよう気をつけて、この活発な時期を楽しみましょう。', title_ko = '뒤집기 챔피언 🤸‍♂️', body_ko = '등에서 배로, 배에서 등으로 뒤집기를 시도하나요? 침대 위에 절대 혼자 두지 말고 이 활발한 시기를 마음껏 즐기세요.', title_nl = 'Kampioen omrollen 🤸‍♂️', body_nl = 'Probeert je baby van rug naar buik en van buik naar rug te rollen? Laat hem nooit alleen op het bed liggen en geniet van deze beweeglijke fase.', title_pl = 'Mistrz obrotów 🤸‍♂️', body_pl = 'Próbuje przewracać się z pleców na brzuch i z brzucha na plecy? Nigdy nie zostawiaj go samego na łóżku i ciesz się tym ruchliwym etapem.', title_pt = 'Campeão das voltas 🤸‍♂️', body_pt = 'Experimenta virar-se de costas para a barriga e da barriga para as costas? Nunca o deixe sozinho na cama e aproveite esta fase tão ativa.', title_sv = 'Rullmästare 🤸‍♂️', body_sv = 'Försöker barnet vända sig från rygg till mage och från mage till rygg? Lämna det aldrig ensamt i sängen och njut av den här livliga perioden.', title_vi = 'Nhà vô địch lật người 🤸‍♂️', body_vi = 'Bé đang thử lật từ ngửa sang sấp và từ sấp sang ngửa? Tuyệt đối đừng để bé một mình trên giường, và hãy tận hưởng giai đoạn hiếu động này nhé.', title_zh = '翻身冠军 🤸‍♂️', body_zh = '宝宝在尝试从仰躺翻到趴着，再从趴着翻回来？千万别把宝宝单独留在床上，好好享受这个活泼好动的阶段吧。' WHERE id = '7b3662bc-d715-468b-a32f-326c023ef66e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La perfección no existe 🛑', title_fr = 'La perfection n''existe pas 🛑', title_hi = 'परफ़ेक्ट कोई नहीं 🛑', title_id = 'Tidak ada yang sempurna 🛑', title_ja = '完璧なんてない 🛑', title_ko = '완벽함은 없어요 🛑', title_nl = 'Perfectie bestaat niet 🛑', title_pl = 'Nie ma ideałów 🛑', title_pt = 'A perfeição não existe 🛑', title_sv = 'Ingen är perfekt 🛑', title_vi = 'Không có gì hoàn hảo 🛑', title_zh = '没有完美 🛑' WHERE id = '63daef22-cfd1-421f-8f7d-267873d17f9e' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorando el tiempo ⛅', body_es = '¿No está claro qué tiempo hace fuera? Deja que la herramienta Tiempo y ropa te diga al instante la velocidad del viento que no se ve desde la ventana y el conjunto adecuado.', title_fr = 'Bulletin météo ⛅', body_fr = 'Le temps dehors n''est pas très clair ? L''outil Météo et tenue vous indique aussitôt la vitesse du vent, invisible depuis la fenêtre, et la bonne tenue.', title_hi = 'मौसम की जासूसी ⛅', body_hi = 'बाहर मौसम साफ़ नहीं है? मौसम और कपड़े टूल आपको खिड़की से न दिखने वाली हवा की रफ़्तार और सही कपड़े तुरंत बताएगा।', title_id = 'Mengintip cuaca ⛅', body_id = 'Cuaca di luar tidak jelas? Biarkan fitur Cuaca dan Pakaian langsung memberi tahu kecepatan angin yang tak terlihat dari jendela dan pakaian yang tepat.', title_ja = 'お天気チェック ⛅', body_ja = '外の天気がはっきりしない？「天気と服装」ツールが、窓からは見えない風の強さとぴったりの服装をすぐに教えてくれます。', title_ko = '날씨 탐색 ⛅', body_ko = '바깥 날씨가 애매한가요? 날씨와 옷차림 도구가 창밖으로는 보이지 않는 바람 세기와 알맞은 옷차림을 바로 알려 줄 거예요.', title_nl = 'Het weer verkennen ⛅', body_nl = 'Is het weer buiten niet helemaal duidelijk? Laat de tool Weer en kleding je meteen de windsnelheid vertellen die je niet vanuit het raam ziet, plus de juiste outfit.', title_pl = 'Rozpoznanie pogody ⛅', body_pl = 'Pogoda na dworze niepewna? Niech narzędzie Pogoda i ubiór od razu powie ci, jak mocno wieje wiatr, czego nie widać przez okno, i jaki zestaw wybrać.', title_pt = 'Exploração do tempo ⛅', body_pt = 'O tempo lá fora não está bem definido? Deixe a ferramenta Tempo e Roupa dizer-lhe na hora a velocidade do vento que não se vê da janela e a roupa certa.', title_sv = 'Väderspaning ⛅', body_sv = 'Är vädret ute osäkert? Låt Väder och kläder direkt berätta vindstyrkan som inte syns genom fönstret och rätt klädsel.', title_vi = 'Thám thính thời tiết ⛅', body_vi = 'Thời tiết bên ngoài không rõ ràng? Hãy để công cụ Thời tiết và trang phục cho mẹ biết ngay tốc độ gió mà nhìn qua cửa sổ không thấy được và bộ đồ phù hợp.', title_zh = '天气侦察 ⛅', body_zh = '外面天气说不准？让天气穿衣工具马上告诉你窗外看不到的风速和合适的搭配吧。' WHERE id = '523ef85e-fa2f-49a1-b3f9-34f2d35d22a1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No tienes que llegar a todo. 🌸', body_es = 'Para esos ojitos llenos de amor que te miran, eres la persona más perfecta del mundo.', title_fr = 'Vous n''êtes pas obligée de tout faire. 🌸', body_fr = 'Pour ces yeux pleins d''amour qui vous regardent, vous êtes la personne la plus parfaite au monde.', title_hi = 'आपको सब कुछ अकेले नहीं करना है 🌸', body_hi = 'आपको निहारती बच्चे की उन प्यार भरी आँखों के लिए आप दुनिया की सबसे परफ़ेक्ट इंसान हैं।', title_id = 'Anda tidak harus mengerjakan semuanya. 🌸', body_id = 'Bagi mata penuh cinta bayi Anda yang menatap Anda, Anda adalah sosok paling sempurna di dunia.', title_ja = 'ぜんぶこなさなくていいんです。🌸', body_ja = 'あなたを愛情たっぷりの目で見つめる赤ちゃんにとって、あなたは世界でいちばん完璧な存在です。', title_ko = '모든 걸 다 해낼 필요는 없어요. 🌸', body_ko = '사랑 가득한 눈으로 엄마를 바라보는 아기에게 엄마는 세상에서 가장 완벽한 존재예요.', title_nl = 'Je hoeft niet alles te doen. 🌸', body_nl = 'Voor die liefdevolle oogjes die naar je kijken, ben jij het meest perfecte wezen ter wereld.', title_pl = 'Nie musisz wszystkiego ogarniać. 🌸', body_pl = 'Dla tych pełnych miłości oczu maluszka, które na ciebie patrzą, jesteś najwspanialszą istotą na świecie.', title_pt = 'Não tem de dar conta de tudo. 🌸', body_pt = 'Para aqueles olhos cheios de amor que a fitam, é o ser mais perfeito do mundo.', title_sv = 'Du behöver inte hinna med allt. 🌸', body_sv = 'För barnets kärleksfulla ögon som tittar på dig är du den mest perfekta människan i världen.', title_vi = 'Mẹ không cần phải lo hết mọi thứ. 🌸', body_vi = 'Với đôi mắt đầy yêu thương đang nhìn mẹ, bé coi mẹ là người hoàn hảo nhất trên đời.', title_zh = '你不必面面俱到 🌸', body_zh = '在宝宝那双满含爱意望着你的眼睛里，你就是世界上最完美的人。' WHERE id = '0aded6bb-b0fa-4cac-b297-4311bcd7f798' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Se quita los zapatos 👟', body_es = '¿Vestirle se ha convertido en una lucha libre? Se quita él solo los calcetines y los zapatos. ¡Admira su motricidad!', title_fr = 'Il enlève ses chaussures tout seul 👟', body_fr = 'L''habillage s''est transformé en match de lutte ? Il retire lui-même ses chaussettes et ses chaussures. Admirez sa motricité !', title_hi = 'अपने जूते खुद उतारता है 👟', body_hi = 'कपड़े पहनाना अब कुश्ती बन गया है? वह अपने मोज़े और जूते खुद खींचकर उतार देता है। उसकी मोटर स्किल्स पर हैरान रह जाइए!', title_id = 'Ia melepas sepatunya sendiri 👟', body_id = 'Memakaikan baju kini seperti pertandingan gulat? Ia menarik lepas kaus kaki dan sepatunya sendiri. Kagumi keterampilan motoriknya!', title_ja = '自分で靴を脱ぐ 👟', body_ja = 'お着替えがレスリングの試合に？靴下や靴を自分で引っぱって脱いでいます。運動能力の成長に感心しましょう！', title_ko = '스스로 신발을 벗어요 👟', body_ko = '옷 입히기가 레슬링 경기가 됐나요? 양말과 신발을 스스로 잡아당겨 벗어요. 운동 능력에 감탄해 보세요!', title_nl = 'Hij trekt zijn schoenen uit 👟', body_nl = 'Is aankleden een soort worstelwedstrijd geworden? Hij trekt zelf zijn sokken en schoenen uit. Bewonder zijn motorische vaardigheid!', title_pl = 'Sam zdejmuje buciki 👟', body_pl = 'Ubieranie zamieniło się w zapasy? Sam ściąga skarpetki i buciki. Podziwiaj jego motorykę!', title_pt = 'Tira os próprios sapatos 👟', body_pt = 'Vesti-lo já se tornou uma luta livre? Ele próprio puxa e tira as meias e os sapatos. Admire a motricidade dele!', title_sv = 'Tar av sig skorna själv 👟', body_sv = 'Har påklädningen blivit en sorts brottning? Barnet drar själv av sig strumporna och skorna. Beundra motoriken!', title_vi = 'Bé tự cởi giày 👟', body_vi = 'Mặc đồ cho bé đã thành một trận đấu vật? Bé tự kéo tất và giày ra. Thật đáng ngưỡng mộ kỹ năng vận động của bé!', title_zh = '自己脱鞋 👟', body_zh = '穿衣服变成了摔跤比赛？宝宝已经会自己把袜子和鞋子拽下来了。为宝宝的动作能力赞叹吧！' WHERE id = '5b3dc48b-525e-45b8-ba47-dd1abb851741' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'En los despertares nocturnos, que una vez te levantes tú y otra tu pareja. Repartid la carga a la mitad, como un equipo.', body_fr = 'Pour les réveils nocturnes, levez-vous une fois chacun, vous et votre conjoint. Partagez la charge en deux, en équipe.', body_hi = 'रात में जागने पर एक बार आप उठिए, एक बार आपके साथी। टीम बनकर बोझ को बराबर आधा बाँट लीजिए।', body_id = 'Saat ia terbangun di malam hari, gantian bangun dengan pasangan. Bagi bebannya tepat setengah sebagai satu tim.', body_ja = '夜中に起きたら、1回はあなた、1回はパートナーと交代で。チームとして、負担をきっちり半分に分けましょう。', body_ko = '밤에 깰 때는 한 번은 엄마가, 한 번은 배우자가 일어나세요. 한 팀으로서 짐을 정확히 절반씩 나누세요.', body_nl = 'Ga ''s nachts om de beurt eruit: de ene keer jij, de andere keer je partner. Verdeel de last als team helemaal eerlijk.', body_pl = 'Przy nocnych pobudkach wstawajcie na zmianę: raz ty, raz partner. Jako drużyna podzielcie ciężar dokładnie na pół.', body_pt = 'Nos despertares noturnos, levanta-se uma vez a mãe e outra vez o pai. Dividam o peso ao meio, como uma equipa.', body_sv = 'Turas om att gå upp vid nattuppvaknandena, en gång du och en gång din partner. Dela bördan helt lika, som ett lag.', body_vi = 'Khi bé thức đêm, lần này mẹ dậy, lần sau đến lượt bố. Hãy chia đôi gánh nặng như một đội thực thụ.', body_zh = '夜醒时，你和伴侣轮流起来。作为一个团队，把担子完全平分吧。' WHERE id = 'cd7f1c0e-ee93-462d-ae3c-cb3021a5d6c8' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un cuento nuevo por descubrir 📖', body_es = 'Hagamos que esta noche sea distinta. Crea en Cuentos inteligentes la historia de una sirena que explora el fondo del mar y llena la habitación de magia.', title_fr = 'À la découverte d''un nouveau conte 📖', body_fr = 'Rendons cette soirée différente. Dans les Contes intelligents, créez l''histoire d''une sirène qui explore les fonds marins et remplissez la chambre de magie.', title_hi = 'नई कहानी की खोज 📖', body_hi = 'आज की रात को खास बनाइए। स्मार्ट कहानियों में समुद्र के नीचे खोज पर निकली जलपरी की कहानी बनाइए और कमरे को जादू से भर दीजिए।', title_id = 'Menjelajah dongeng baru 📖', body_id = 'Ayo buat malam ini berbeda. Di Dongeng Pintar, buat kisah putri duyung yang menjelajah bawah laut dan penuhi kamar dengan keajaiban.', title_ja = '新しいお話を見つけよう 📖', body_ja = '今夜はいつもと違う夜にしましょう。「スマートおはなし」で海の底を探検する人魚のお話をつくって、部屋を魔法でいっぱいにしましょう。', title_ko = '새로운 동화 탐험 📖', body_ko = '오늘 밤은 특별하게 보내요. 스마트 동화에서 바닷속을 탐험하는 인어 이야기를 만들어 방을 마법으로 채워 보세요.', title_nl = 'Een nieuw sprookje ontdekken 📖', body_nl = 'Laten we van vanavond iets bijzonders maken. Maak in Slimme sprookjes het verhaal van een zeemeermin die de onderwaterwereld ontdekt en vul de kamer met magie.', title_pl = 'Odkryj nową bajkę 📖', body_pl = 'Niech ten wieczór będzie inny. W Mądrych bajkach stwórz historię o syrence odkrywającej podwodny świat i wypełnij pokój magią.', title_pt = 'Uma nova história para descobrir 📖', body_pt = 'Vamos tornar esta noite diferente. Nas Histórias Inteligentes, crie a história de uma sereia a explorar o fundo do mar e encha o quarto de magia.', title_sv = 'En ny saga att upptäcka 📖', body_sv = 'Låt oss göra kvällen annorlunda. Skapa sagan om sjöjungfrun som utforskar havets djup i Smarta sagor och fyll rummet med magi.', title_vi = 'Khám phá truyện mới 📖', body_vi = 'Tối nay hãy làm điều gì đó khác biệt. Trong Truyện cổ tích thông minh, tạo câu chuyện nàng tiên cá khám phá đáy biển và phủ căn phòng bằng phép màu nhé.', title_zh = '发现新故事 📖', body_zh = '让今晚与众不同吧。在智能故事里创作一个美人鱼探索海底的故事，让房间充满魔法。' WHERE id = '658bd674-cc84-4d51-8a7e-822b9255b9d7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No tiene hambre, ¿entonces qué es? 🧩', body_es = '¿Hagas lo que hagas, no se calma? Deja de adivinar: usa el Análisis del llanto para escucharle y descubre al instante qué le pasa.', title_fr = 'Il n''a pas faim, alors pourquoi ? 🧩', body_fr = 'Rien ne le calme ? Arrêtez de deviner : faites écouter ses pleurs à l''Analyse des pleurs et découvrez tout de suite ce qui ne va pas.', title_hi = 'भूखा नहीं है, तो फिर क्यों? 🧩', body_hi = 'कुछ भी कर लें, वह शांत नहीं हो रहा? अंदाज़ा लगाना छोड़िए, क्राइंग एनालिसिस टूल से उसकी आवाज़ सुनवाइए और तुरंत जानिए कि परेशानी क्या है।', title_id = 'Tidak lapar, lalu kenapa? 🧩', body_id = 'Apa pun yang Anda lakukan, ia tetap tidak tenang? Berhenti menebak-nebak, perdengarkan tangisannya ke Analisis Tangisan dan langsung ketahui masalahnya.', title_ja = 'お腹はすいていないのに、どうして？🧩', body_ja = '何をしても泣きやまない？あれこれ推測するのはやめて、「泣き声分析」に泣き声を聞かせて、原因をすぐに見つけましょう。', title_ko = '배고픈 게 아니라면 왜일까요? 🧩', body_ko = '무엇을 해도 진정하지 않나요? 추측은 그만하고 울음 분석으로 소리를 들려주어 무엇이 문제인지 바로 알아보세요.', title_nl = 'Geen honger, maar wat dan? 🧩', body_nl = 'Wordt je baby niet rustig, wat je ook doet? Stop met raden, laat Huilanalyse naar het huilen luisteren en ontdek meteen wat er aan de hand is.', title_pl = 'Nie jest głodny, to o co chodzi? 🧩', body_pl = 'Nic nie pomaga go uspokoić? Przestań zgadywać, pozwól Analizie płaczu posłuchać dźwięku i od razu sprawdź, w czym problem.', title_pt = 'Não tem fome, então porquê? 🧩', body_pt = 'Faça o que fizer, não se acalma? Deixe de adivinhar: ponha a Análise do Choro a ouvir e descubra logo qual é o problema.', title_sv = 'Inte hungrig, men varför då? 🧩', body_sv = 'Lugnar sig barnet inte, vad du än gör? Sluta gissa, låt Gråtanalys lyssna på ljudet och ta reda på vad problemet är direkt.', title_vi = 'Không đói, vậy sao bé khóc? 🧩', body_vi = 'Làm gì bé cũng không nín? Đừng đoán nữa, hãy cho Phân tích tiếng khóc nghe và biết ngay vấn đề là gì.', title_zh = '不饿，那是为什么？🧩', body_zh = '怎么哄都哄不好？别再猜了，用哭声分析听一听，立刻找出问题所在。' WHERE id = 'b8b57297-f4b4-4473-87af-9acfeee74dd3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un mundo de colores nuevos 👀', body_es = 'Ya ve los colores de forma más viva y nítida. Enséñale juguetes con colores contrastados.', title_fr = 'Un nouveau monde de couleurs 👀', body_fr = 'Il voit désormais les couleurs de façon plus vive et plus nette. Montrez-lui des jouets aux couleurs contrastées.', title_hi = 'नए रंगों की दुनिया 👀', body_hi = 'अब वह रंगों को ज़्यादा साफ़ और चटक देखता है। उसे गहरे विपरीत रंगों वाले खिलौने दिखाइए।', title_id = 'Dunia warna baru 👀', body_id = 'Kini ia melihat warna dengan lebih hidup dan jelas. Tunjukkan mainan dengan warna kontras.', title_ja = '新しい色の世界 👀', body_ja = '赤ちゃんはもう色をよりはっきり鮮やかに見ています。コントラストの強い色のおもちゃを見せてあげましょう。', title_ko = '새로운 색의 세상 👀', body_ko = '이제 색을 더 선명하고 정확하게 볼 수 있어요. 대비가 뚜렷한 색의 장난감을 보여 주세요.', title_nl = 'Een wereld vol nieuwe kleuren 👀', body_nl = 'Je baby ziet kleuren nu levendiger en scherper. Laat speeltjes in contrasterende kleuren zien.', title_pl = 'Świat nowych kolorów 👀', body_pl = 'Widzi już kolory żywiej i wyraźniej. Pokazuj mu zabawki w kontrastowych kolorach.', title_pt = 'Um mundo de cores novas 👀', body_pt = 'Já vê as cores de forma mais viva e nítida. Mostre-lhe brinquedos de cores contrastantes.', title_sv = 'En värld av nya färger 👀', body_sv = 'Barnet ser nu färgerna mer levande och tydligt. Visa leksaker i kontrasterande färger.', title_vi = 'Thế giới sắc màu mới 👀', body_vi = 'Giờ bé đã nhìn thấy màu sắc sống động và rõ nét hơn. Hãy cho bé xem đồ chơi có màu tương phản nhé.', title_zh = '多彩的新世界 👀', body_zh = '宝宝现在看到的颜色更鲜艳、更清晰了。给宝宝看看对比强烈的彩色玩具吧。' WHERE id = '9ce62e84-5124-421b-bdd6-3fa7c590aa1a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
