UPDATE public.mommy_day_notifications SET title_es = 'La perfección no existe 🛑', title_fr = 'La perfection n''existe pas 🛑', title_hi = 'परफ़ेक्ट कोई नहीं 🛑', title_id = 'Tidak ada yang sempurna 🛑', title_ja = '完璧なんてない 🛑', title_ko = '완벽함은 없어요 🛑', title_nl = 'Perfectie bestaat niet 🛑', title_pl = 'Nie ma ideałów 🛑', title_pt = 'A perfeição não existe 🛑', title_sv = 'Ingen är perfekt 🛑', title_vi = 'Không có gì hoàn hảo 🛑', title_zh = '没有完美 🛑' WHERE id = 'd8b0e257-5429-4bf7-b2a7-1bb116658651' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorando el tiempo ⛅', title_fr = 'Bulletin météo ⛅', title_hi = 'मौसम की जासूसी ⛅', title_id = 'Mengintip cuaca ⛅', title_ja = 'お天気チェック ⛅', title_ko = '날씨 탐색 ⛅', title_nl = 'Het weer verkennen ⛅', title_pl = 'Rozpoznanie pogody ⛅', title_pt = 'Exploração do tempo ⛅', title_sv = 'Väderspaning ⛅', title_vi = 'Thám thính thời tiết ⛅', title_zh = '天气侦察 ⛅' WHERE id = 'a36ee256-d6c9-4345-a732-3a052e7dd260' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te olvides de ti 🍲', body_es = 'Si tu bebé ya ha comido, ahora te toca a ti. Elige en Recetas saludables un tentempié lleno de energía que se prepara en 10 minutos y cuídate.', title_fr = 'Ne vous oubliez pas 🍲', body_fr = 'Bébé a bien mangé, c''est votre tour. Choisissez dans les Recettes saines un en-cas énergisant prêt en 10 minutes et prenez soin de vous.', title_hi = 'खुद को मत भूलिए 🍲', body_hi = 'बच्चे का पेट भर गया, अब आपकी बारी है। सेहतमंद रेसिपी से 10 मिनट में बनने वाला कोई ऊर्जा भरा स्नैक चुनिए और अपना ख्याल रखिए।', title_id = 'Jangan lupakan diri Anda 🍲', body_id = 'Kalau bayi sudah kenyang, sekarang giliran Anda. Pilih camilan penambah energi dari Resep Sehat yang siap dalam 10 menit, dan rawat diri Anda.', title_ja = '自分のことも忘れずに 🍲', body_ja = '赤ちゃんがお腹いっぱいになったら、次はあなたの番。「ヘルシーレシピ」から10分でできる元気の出るおやつを選んで、自分をいたわりましょう。', title_ko = '나 자신도 잊지 마세요 🍲', body_ko = '아기가 배불리 먹었다면 이제 엄마 차례예요. 건강한 레시피에서 10분 만에 만드는 든든한 간식을 골라 나를 챙겨 주세요.', title_nl = 'Vergeet jezelf niet 🍲', body_nl = 'Is je baby verzadigd? Dan ben jij aan de beurt. Kies uit Gezonde recepten een energierijk tussendoortje dat in 10 minuten klaar is en zorg goed voor jezelf.', title_pl = 'Nie zapominaj o sobie 🍲', body_pl = 'Maluszek najedzony, teraz twoja kolej. Wybierz w Zdrowych przepisach energetyczną przekąskę gotową w 10 minut i zadbaj o siebie.', title_pt = 'Não se esqueça de si 🍲', body_pt = 'Se o bebé já está satisfeito, agora é a sua vez. Escolha nas Receitas Saudáveis um lanche cheio de energia que se faz em 10 minutos e cuide de si.', title_sv = 'Glöm inte dig själv 🍲', body_sv = 'Är barnet mätt är det din tur. Välj ett energirikt mellanmål från Hälsosamma recept som är klart på 10 minuter och ta hand om dig.', title_vi = 'Đừng quên bản thân 🍲', body_vi = 'Bé no rồi thì đến lượt mẹ. Chọn một món ăn nhẹ giàu năng lượng làm trong 10 phút từ Công thức lành mạnh và chăm sóc bản thân nhé.', title_zh = '别忘了自己 🍲', body_zh = '宝宝吃饱了，现在轮到你了。从健康食谱里挑一款10分钟就能做好的能量小食，好好照顾自己。' WHERE id = 'b42e7a75-4fab-45bd-89fe-f334b8181757' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tiempo de papá y bebé 🫂', body_es = 'Los papás también necesitan contacto piel con piel con el bebé. Por la tarde déjales a solas: ellos crean vínculo y tú descansas.', title_fr = 'Moment papa-bébé 🫂', body_fr = 'Les papas aussi ont besoin de contact peau à peau avec bébé. Le soir, laissez-les en tête-à-tête : ils créent un lien et vous vous reposez.', title_hi = 'पापा और बच्चे का समय 🫂', body_hi = 'पापा को भी बच्चे के साथ त्वचा से त्वचा का संपर्क करना चाहिए। शाम को उन्हें अकेले साथ समय बिताने दीजिए, ताकि उनका रिश्ता गहरा हो और आप आराम कर सकें।', title_id = 'Waktu ayah dan bayi 🫂', body_id = 'Ayah juga perlu kontak kulit dengan bayi. Di sore hari, biarkan mereka berdua saja: ikatan mereka menguat, dan Anda bisa beristirahat.', title_ja = 'パパとの時間 🫂', body_ja = 'パパも赤ちゃんと肌と肌でふれあうことが大切です。夕方は2人きりの時間をつくってあげましょう。きずなが深まり、あなたも休めます。', title_ko = '아빠와 아기 시간 🫂', body_ko = '아빠도 아기와 살을 맞대는 시간이 필요해요. 저녁에는 둘만의 시간을 주세요. 아빠와 아기는 유대를 쌓고, 엄마는 쉴 수 있어요.', title_nl = 'Tijd voor papa en baby 🫂', body_nl = 'Ook papa''s hebben huid-op-huidcontact met de baby nodig. Laat ze ''s avonds samen, zodat zij een band opbouwen en jij uitrust.', title_pl = 'Czas taty z maluszkiem 🫂', body_pl = 'Tata też powinien mieć kontakt skóra do skóry z maluszkiem. Wieczorem zostaw ich sam na sam: oni zbudują więź, a ty odpoczniesz.', title_pt = 'Tempo de pai e filho 🫂', body_pt = 'Os pais também precisam de contacto pele com pele com o bebé. Ao fim do dia, deixe-os a sós: eles criam laços e a mãe descansa.', title_sv = 'Pappa-barn-tid 🫂', body_sv = 'Även pappor behöver hudkontakt med barnet. Låt dem vara på tu man hand på kvällen, så knyter de an och du får vila.', title_vi = 'Giờ của bố và bé 🫂', body_vi = 'Bố cũng cần tiếp xúc da kề da với bé. Buổi tối hãy để hai bố con ở riêng với nhau, vừa để bố con gắn kết, vừa để mẹ được nghỉ ngơi.', title_zh = '父子时光 🫂', body_zh = '爸爸也需要和宝宝肌肤相亲。晚上让他们单独相处，他们能培养感情，你也能休息一下。' WHERE id = 'cf65b961-f3be-4509-9af3-0b6c17f757e7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorando el tiempo ⛅', title_fr = 'Bulletin météo ⛅', title_hi = 'मौसम की जासूसी ⛅', title_id = 'Mengintip cuaca ⛅', title_ja = 'お天気チェック ⛅', title_ko = '날씨 탐색 ⛅', title_nl = 'Het weer verkennen ⛅', title_pl = 'Rozpoznanie pogody ⛅', title_pt = 'Exploração do tempo ⛅', title_sv = 'Väderspaning ⛅', title_vi = 'Thám thính thời tiết ⛅', title_zh = '天气侦察 ⛅' WHERE id = '489a0197-f1e2-44a5-bece-55d85fa323ae' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Regresión del sueño? 🤖', body_es = '¿De repente se despierta más por la noche? Puede ser un salto de desarrollo. Pregunta a Anacan AI sobre la regresión del sueño de los 4-5 meses.', title_fr = 'Régression du sommeil ? 🤖', body_fr = 'Les réveils nocturnes se multiplient soudain ? C''est peut-être un pic de développement. Renseignez-vous auprès d''Anacan AI sur la régression du sommeil de 4-5 mois.', title_hi = 'नींद में गिरावट? 🤖', body_hi = 'अचानक रात में जागना बढ़ गया है? शायद यह विकास की छलांग है। Anacan AI से 4-5 महीने की स्लीप रिग्रेशन के बारे में जानिए।', title_id = 'Regresi tidur? 🤖', body_id = 'Tiba-tiba ia lebih sering terbangun di malam hari? Mungkin ini lompatan perkembangan. Cari tahu tentang regresi tidur usia 4-5 bulan di Anacan AI.', title_ja = '睡眠退行？🤖', body_ja = '急に夜中に起きる回数が増えた？発達の一時期かもしれません。Anacan AIで生後4-5か月の睡眠退行について調べてみましょう。', title_ko = '수면 퇴행인가요? 🤖', body_ko = '갑자기 밤에 깨는 일이 늘었나요? 발달 도약일 수도 있어요. Anacan AI에게 4-5개월 수면 퇴행에 대해 알아보세요.', title_nl = 'Slaapregressie? 🤖', body_nl = 'Wordt je baby ''s nachts ineens vaker wakker? Misschien is het een sprongetje. Vraag Anacan AI naar de slaapregressie van 4-5 maanden.', title_pl = 'Regres snu? 🤖', body_pl = 'Nagle częściej budzi się w nocy? Może to skok rozwojowy. Dowiedz się od Anacan AI więcej o regresie snu w 4-5 miesiącu.', title_pt = 'Regressão do sono? 🤖', body_pt = 'De repente acorda mais vezes à noite? Pode ser um salto de desenvolvimento. Saiba mais sobre a regressão do sono dos 4-5 meses no Anacan AI.', title_sv = 'Sömnregression? 🤖', body_sv = 'Har nattuppvaknandena plötsligt blivit fler? Det kan vara ett utvecklingssprång. Läs om sömnregressionen vid 4-5 månader hos Anacan AI.', title_vi = 'Thoái lui giấc ngủ? 🤖', body_vi = 'Bé bỗng thức đêm nhiều hơn? Có thể đó là một bước nhảy phát triển. Hãy hỏi Anacan AI về thoái lui giấc ngủ ở tháng thứ 4-5.', title_zh = '睡眠倒退？🤖', body_zh = '夜醒突然变多了？可能是发育飞跃期。向Anacan AI了解一下4-5个月的睡眠倒退吧。' WHERE id = '0ed5ca13-9d93-489b-99e3-a198862dd467' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Me está mirando! 📸', body_es = 'Estés donde estés en la habitación, te sigue con la mirada.', title_fr = 'Il me regarde ! 📸', body_fr = 'Où que vous soyez dans la pièce, il vous suit des yeux.', title_hi = 'वह मुझे देख रहा है! 📸', body_hi = 'आप कमरे में कहीं भी हों, उसकी नज़रें आपका पीछा करती रहती हैं।', title_id = 'Ia sedang memandangiku! 📸', body_id = 'Di mana pun Anda berada di dalam kamar, matanya terus mengikuti Anda.', title_ja = 'ママを見てる！📸', body_ja = '部屋のどこにいても、赤ちゃんの目があなたを追いかけています。', title_ko = '저 엄마를 보고 있어요! 📸', body_ko = '방 어디에 있든 아기가 눈으로 엄마를 따라와요.', title_nl = 'Ik kijk naar jou! 📸', body_nl = 'Waar je ook bent in de kamer, je baby volgt je met de oogjes.', title_pl = 'Patrzy na mnie! 📸', body_pl = 'Gdziekolwiek jesteś w pokoju, śledzi cię wzrokiem.', title_pt = 'Está a olhar para mim! 📸', body_pt = 'Esteja onde estiver no quarto, segue-a com os olhos.', title_sv = 'Barnet tittar på mig! 📸', body_sv = 'Var du än är i rummet följer barnet dig med blicken.', title_vi = 'Bé đang nhìn mẹ kìa! 📸', body_vi = 'Dù mẹ ở góc nào trong phòng, đôi mắt bé vẫn dõi theo mẹ.', title_zh = '宝宝在看我！📸', body_zh = '不管你走到房间哪里，宝宝的眼睛都跟着你转。' WHERE id = '450e1ee4-0ee2-4568-acc9-22677b87903d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Solo 10 minutos 🛀', body_es = 'Tu bebé duerme y por fin llega el silencio. En vez de vaciar el lavavajillas, métete bajo el agua caliente y escucha su sonido durante 10 minutos.', title_fr = 'Juste 10 minutes 🛀', body_fr = 'Bébé dort et le calme est revenu. Au lieu de vider le lave-vaisselle, glissez-vous sous l''eau chaude et écoutez le bruit de l''eau pendant 10 minutes.', title_hi = 'बस 10 मिनट 🛀', body_hi = 'बच्चा सो गया और आपको भी सुकून मिला। डिशवॉशर खाली करने के बजाय गुनगुने पानी के नीचे खड़ी होइए और 10 मिनट पानी की आवाज़ सुनिए।', title_id = 'Cukup 10 menit 🛀', body_id = 'Bayi sudah tidur dan suasana akhirnya hening. Daripada mengosongkan mesin cuci piring, mandilah air hangat dan dengarkan suara air selama 10 menit.', title_ja = 'たった10分だけ 🛀', body_ja = '赤ちゃんが眠って、静けさが戻ってきました。食洗機を片づける代わりに、温かいシャワーを浴びて10分間お湯の音に耳を傾けましょう。', title_ko = '딱 10분만 🛀', body_ko = '아이가 잠들고 드디어 고요해졌어요. 식기세척기를 비우는 대신 따뜻한 물 아래에서 10분 동안 물소리를 들어 보세요.', title_nl = 'Maar 10 minuten 🛀', body_nl = 'Je baby slaapt en het is eindelijk stil. Ga in plaats van de vaatwasser uit te ruimen onder een warme douche en luister 10 minuten naar het water.', title_pl = 'Tylko 10 minut 🛀', body_pl = 'Maluszek zasnął, nastała cisza. Zamiast rozładowywać zmywarkę, wejdź pod ciepły prysznic i przez 10 minut słuchaj szumu wody.', title_pt = 'Só 10 minutos 🛀', body_pt = 'O bebé adormeceu e o silêncio chegou. Em vez de esvaziar a máquina da loiça, vá para debaixo de água quente e ouça o som da água durante 10 minutos.', title_sv = 'Bara 10 minuter 🛀', body_sv = 'Barnet sover och det har blivit tyst. I stället för att tömma diskmaskinen, ställ dig i en varm dusch och lyssna på vattnet i 10 minuter.', title_vi = 'Chỉ 10 phút thôi 🛀', body_vi = 'Bé ngủ rồi, mẹ cũng được yên tĩnh. Thay vì dọn máy rửa bát, hãy tắm nước ấm và lắng nghe tiếng nước chảy trong 10 phút.', title_zh = '只要10分钟 🛀', body_zh = '宝宝睡着了，你终于迎来片刻安静。别急着清空洗碗机，去冲个热水澡，听10分钟流水声吧。' WHERE id = '696eaa28-30b3-4a02-87e3-0cd00d185f07' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lista en tu bolsillo 🛒', title_fr = 'La liste dans votre poche 🛒', title_hi = 'आपकी जेब में लिस्ट 🛒', title_id = 'Daftar di saku Anda 🛒', title_ja = 'ポケットの中のリスト 🛒', title_ko = '주머니 속 목록 🛒', title_nl = 'Een lijstje in je broekzak 🛒', title_pl = 'Lista w kieszeni 🛒', title_pt = 'A lista no seu bolso 🛒', title_sv = 'Listan i fickan 🛒', title_vi = 'Danh sách trong túi mẹ 🛒', title_zh = '口袋里的清单 🛒' WHERE id = '9fedc843-d647-418d-b31f-ad9bf956e849' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidad de silencio 🤫', title_fr = 'Besoin de silence 🤫', title_hi = 'खामोशी की ज़रूरत 🤫', title_id = 'Butuh keheningan 🤫', title_ja = '静けさが必要 🤫', title_ko = '고요함이 필요해요 🤫', title_nl = 'Behoefte aan stilte 🤫', title_pl = 'Potrzeba ciszy 🤫', title_pt = 'Necessidade de silêncio 🤫', title_sv = 'Behovet av tystnad 🤫', title_vi = 'Cần sự yên tĩnh 🤫', title_zh = '需要安静 🤫' WHERE id = 'ac1c42c5-b375-4935-bfbe-c3b0f8da74a1' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No cargues tú sola con todos los despertares nocturnos. Despierta también a tu pareja: ser un equipo es repartir la responsabilidad a partes iguales.', body_fr = 'Ne gérez pas les réveils nocturnes toute seule. Réveillez aussi votre conjoint, être une équipe, c''est partager la responsabilité à parts égales.', body_hi = 'रात में जागने का बोझ अकेले मत उठाइए। अपने साथी को भी जगाइए, टीम होने का मतलब है ज़िम्मेदारी बराबर बाँटना।', body_id = 'Jangan tanggung sendiri saat ia terbangun di malam hari. Bangunkan juga pasangan Anda, menjadi tim berarti berbagi tanggung jawab secara adil.', body_ja = '夜中に起きるのを、ひとりで抱えこまないで。パートナーも起こしましょう。チームとは責任を平等に分け合うことです。', body_ko = '밤에 깨는 일을 혼자 다 감당하지 마세요. 배우자도 깨우세요, 한 팀이 된다는 건 책임을 똑같이 나누는 거예요.', body_nl = 'Draag het ''s nachts opstaan niet helemaal alleen. Maak je partner ook wakker, een team zijn betekent de verantwoordelijkheid eerlijk delen.', body_pl = 'Nie dźwigaj nocnych pobudek zupełnie sama. Obudź też partnera, bycie drużyną to równy podział odpowiedzialności.', body_pt = 'Não aguente sozinha todos os despertares noturnos. Acorde também o seu companheiro: ser uma equipa é dividir a responsabilidade por igual.', body_sv = 'Ta inte nattuppvaknandena helt ensam. Väck din partner också, att vara ett lag är att dela ansvaret lika.', body_vi = 'Đừng một mình gánh hết những lần thức dậy ban đêm. Hãy gọi cả bố dậy, là một đội nghĩa là chia đều trách nhiệm.', body_zh = '夜醒别全都自己扛。也叫醒你的伴侣，团队就是平分责任。' WHERE id = 'ee6a7a57-d3a9-4c19-bc94-5bb7b56c8f9c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dilema de qué cocinar 🍲', title_fr = 'Le casse-tête du « qu''est-ce que je cuisine ? » 🍲', title_hi = 'क्या पकाऊँ, यही चिंता 🍲', title_id = 'Bingung mau masak apa 🍲', title_ja = '何をつくろう問題 🍲', title_ko = '뭐 해 먹지 고민 🍲', title_nl = 'Wat moet ik koken? 🍲', title_pl = 'Co ugotować? 🍲', title_pt = 'O dilema do que cozinhar 🍲', title_sv = 'Vad ska jag laga? 🍲', title_vi = 'Nỗi lo "nấu gì đây" 🍲', title_zh = '“做什么吃”的烦恼 🍲' WHERE id = '4e5540da-110f-46b1-a6fe-0833314d27a6' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un cuento especial 🪄', title_fr = 'Un conte unique 🪄', title_hi = 'खास कहानी 🪄', title_id = 'Dongeng istimewa 🪄', title_ja = '特別なお話 🪄', title_ko = '특별한 동화 이야기 🪄', title_nl = 'Een eigen sprookje 🪄', title_pl = 'Wyjątkowa bajka 🪄', title_pt = 'Uma história especial 🪄', title_sv = 'En personlig saga 🪄', title_vi = 'Câu chuyện cổ tích riêng 🪄', title_zh = '专属故事 🪄' WHERE id = '7d3efca9-83bd-4ef7-a064-007baae56a2f' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Somos un equipo! 🌟', body_es = '¿Agotada de tanto despertarte por la noche? No dudes en despertar a papá. Ser un equipo es repartir la carga con amor.', title_fr = 'Nous sommes une équipe ! 🌟', body_fr = 'Épuisée par les réveils nocturnes ? N''hésitez pas à réveiller papa. Être une équipe, c''est partager la charge avec amour.', title_hi = 'हम एक टीम हैं! 🌟', body_hi = 'रात में बार-बार जागने से थक गई हैं? पापा को जगाने में झिझकिए मत। टीम होने का मतलब है प्यार से बोझ बाँटना।', title_id = 'Kita satu tim! 🌟', body_id = 'Lelah karena sering terbangun di malam hari? Jangan ragu membangunkan ayah. Menjadi satu tim berarti berbagi beban dengan penuh cinta.', title_ja = '私たちはチーム！🌟', body_ja = '夜中の授乳で疲れていますか？遠慮せずパパを起こしましょう。チームとは、愛情をもって負担を分け合うことです。', title_ko = '우리는 한 팀이에요! 🌟', body_ko = '밤에 깨는 일로 지쳤나요? 아빠를 깨우는 걸 망설이지 마세요. 한 팀이 된다는 건 짐을 사랑으로 나누는 거예요.', title_nl = 'Wij zijn een team! 🌟', body_nl = 'Moe van het ''s nachts opstaan? Aarzel niet om papa wakker te maken. Een team zijn betekent de last met liefde delen.', title_pl = 'Jesteśmy drużyną! 🌟', body_pl = 'Jesteś zmęczona nocnymi pobudkami? Nie bój się obudzić taty. Być drużyną to dzielić ciężar z miłością.', title_pt = 'Somos uma equipa! 🌟', body_pt = 'Cansada de acordar à noite? Não hesite em acordar o pai. Ser uma equipa é partilhar o peso com amor.', title_sv = 'Vi är ett lag! 🌟', body_sv = 'Trött på nattuppvaknandena? Tveka inte att väcka pappa. Att vara ett lag är att dela bördan med kärlek.', title_vi = 'Chúng mình là một đội! 🌟', body_vi = 'Mệt vì phải thức dậy ban đêm? Đừng ngại gọi bố dậy. Là một đội nghĩa là cùng nhau chia sẻ gánh nặng bằng yêu thương.', title_zh = '我们是一个团队！🌟', body_zh = '夜里频繁醒来让你筋疲力尽？别不好意思叫醒爸爸。团队就是用爱分担重任。' WHERE id = '27873a53-69de-4c27-a20c-c15256739b9a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Al salir de paseo, que el tiempo no te engañe y tu bebé se resfríe. Con el asistente Tiempo y ropa elige fácilmente lo mejor para las condiciones de fuera.', body_fr = 'Pour la promenade, ne vous laissez pas tromper par le temps et évitez qu''il prenne froid. Avec l''assistant Météo et tenue, choisissez facilement ce qui convient le mieux dehors.', body_hi = 'घूमने निकलते समय मौसम के धोखे में आकर सर्दी मत लगने दीजिए। मौसम और कपड़े टूल से बाहर के माहौल के हिसाब से आसानी से सही फ़ैसला लीजिए।', body_id = 'Saat jalan-jalan, jangan sampai tertipu cuaca dan si kecil masuk angin. Dengan asisten Cuaca dan Pakaian, Anda bisa dengan mudah memilih yang paling pas untuk kondisi di luar.', body_ja = 'お散歩のときは、天気にだまされてかぜをひかせないように。「天気と服装」アシスタントで、外の環境にぴったりの服装をかんたんに選びましょう。', body_ko = '산책 나갈 때 날씨에 속아 감기 걸리지 않게 하세요. 날씨와 옷차림 도우미로 바깥 환경에 가장 알맞은 선택을 쉽게 하세요.', body_nl = 'Laat je bij een wandeling niet misleiden door het weer, zodat je baby geen kou vat. Kies met de assistent Weer en kleding makkelijk wat het best past bij het weer buiten.', body_pl = 'Wychodząc na spacer, nie daj się zwieść pogodzie, żeby maluszek się nie przeziębił. Z pomocnikiem Pogoda i ubiór łatwo podejmiesz najlepszą decyzję.', body_pt = 'Ao sair para passear, não se deixe enganar pelo tempo e evite constipações. Com o assistente Tempo e Roupa, decida facilmente o que é mais adequado lá fora.', body_sv = 'Låt inte vädret lura dig så att barnet blir förkylt på promenaden. Med Väder och kläder fattar du enkelt det bästa beslutet för förhållandena ute.', body_vi = 'Khi ra ngoài đi dạo, đừng để thời tiết đánh lừa khiến bé bị cảm lạnh. Với Trợ lý thời tiết và trang phục, mẹ dễ dàng chọn được cách phù hợp nhất với điều kiện bên ngoài.', body_zh = '出门散步时别被天气骗了，小心着凉。用天气穿衣助手，轻松做出最适合户外环境的选择。' WHERE id = '77e7ae70-0ff1-4b56-a2eb-2e4ed43e460c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Modo «cógeme en brazos» 🛋️', body_es = '¿No quiere bajarse de tus brazos? No es que esté mimado, necesita tu olor. Abrázale fuerte, estos días pasan volando.', title_fr = 'Il ne veut que les bras 🛋️', body_fr = 'Il ne veut pas quitter vos bras ? Ce n''est pas un caprice, il a besoin de votre odeur. Serrez-le fort, ces jours passeront vite.', title_hi = 'बस गोद चाहिए 🛋️', body_hi = 'गोद से उतरना नहीं चाहता? यह लाड़-प्यार नहीं, उसे आपकी खुशबू की ज़रूरत है। उसे कसकर गले लगाइए, ये दिन जल्दी बीत जाएँगे।', title_id = 'Maunya digendong terus 🛋️', body_id = 'Ia tidak mau lepas dari pelukan Anda? Ini bukan manja, ia butuh aroma Anda. Peluk ia erat-erat, hari-hari ini akan cepat berlalu.', title_ja = '抱っこしてモード 🛋️', body_ja = '腕の中から離れたがらない？これは甘やかしではなく、ママのにおいが必要なのです。ぎゅっと抱きしめてあげて。こんな日々はあっという間に過ぎていきます。', title_ko = '안아 달라는 고집 🛋️', body_ko = '품에서 내려오려 하지 않나요? 버릇이 나빠진 게 아니라 엄마의 냄새가 필요한 거예요. 꼭 안아 주세요, 이 시간은 금방 지나가요.', title_nl = 'Alleen maar op schoot 🛋️', body_nl = 'Wil je baby niet uit je armen? Dat is geen verwennen, je kleintje heeft jouw geur nodig. Knuffel hem stevig, deze dagen gaan snel voorbij.', title_pl = 'Upór: tylko na rączki 🛋️', body_pl = 'Nie chce zejść z twoich rąk? To nie rozpieszczenie, potrzebuje twojego zapachu. Przytul go mocno, te dni szybko miną.', title_pt = 'A teimosia do colo 🛋️', body_pt = 'Não quer sair do seu colo? Não é mimo, precisa do seu cheiro. Abrace-o bem, estes dias passam depressa.', title_sv = 'Envis kramvilja 🛋️', body_sv = 'Vill barnet inte lämna din famn? Det är inte bortskämdhet, barnet behöver din doft. Håll det tätt intill dig, de här dagarna går fort.', title_vi = 'Chỉ đòi bế thôi 🛋️', body_vi = 'Bé không muốn rời vòng tay mẹ? Đây không phải là được chiều hư, bé cần mùi hương của mẹ. Hãy ôm bé thật chặt, những ngày này sẽ qua nhanh lắm.', title_zh = '只要抱抱 🛋️', body_zh = '宝宝不肯离开你的怀抱？这不是被宠坏了，而是需要你的气味。紧紧抱着宝宝吧，这些日子转眼就会过去。' WHERE id = '82b46290-c3d6-4ad5-8d94-600e0311ba33' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Control de decibelios 🤫', body_es = '¿Cuando tu bebé duerme, cualquier ruido de casa te asusta? Activa el Medidor de sonido, revisa la acústica de la habitación y protege su sueño.', title_fr = 'Contrôle des décibels 🤫', body_fr = 'Chaque bruit vous fait sursauter quand bébé dort ? Activez le Sonomètre, vérifiez l''acoustique de la pièce et protégez son sommeil.', title_hi = 'डेसिबल पर नज़र 🤫', body_hi = 'बच्चे के सोते समय घर की हर आवाज़ आपको डराती है? साउंड मीटर चालू कीजिए और कमरे की आवाज़ जाँचकर उसकी नींद की रक्षा कीजिए।', title_id = 'Kontrol desibel 🤫', body_id = 'Setiap suara di rumah membuat Anda cemas saat ia tidur? Aktifkan Pengukur Suara, periksa akustik kamar, dan lindungi tidurnya.', title_ja = '音のチェック 🤫', body_ja = '赤ちゃんが寝ているとき、家の物音が気になってしまう？「サウンドメーター」をオンにして部屋の音をチェックし、眠りを守りましょう。', title_ko = '데시벨 체크 🤫', body_ko = '아이가 잘 때 집 안의 모든 소리가 신경 쓰이나요? 소음 측정기를 켜고 방의 소리를 확인해 아기의 잠을 지켜 주세요.', title_nl = 'Decibelcontrole 🤫', body_nl = 'Schrik je van elk geluid in huis als je baby slaapt? Zet de Geluidsmeter aan, controleer de akoestiek van de kamer en bescherm zijn slaap.', title_pl = 'Kontrola decybeli 🤫', body_pl = 'Gdy maluszek śpi, każdy dźwięk w domu cię przeraża? Włącz Miernik dźwięku, sprawdź akustykę pokoju i chroń jego sen.', title_pt = 'Controlo dos decibéis 🤫', body_pt = 'Quando o bebé dorme, qualquer barulho em casa a assusta? Ative o Medidor de Som, verifique a acústica do quarto e proteja o sono dele.', title_sv = 'Decibelkoll 🤫', body_sv = 'Skrämmer varje ljud i huset dig när barnet sover? Aktivera Ljudmätaren, kolla rummets akustik och skydda sömnen.', title_vi = 'Kiểm soát decibel 🤫', body_vi = 'Bé ngủ mà tiếng động nào trong nhà cũng làm mẹ giật mình? Hãy bật Đo âm thanh, kiểm tra độ ồn trong phòng và bảo vệ giấc ngủ của bé.', title_zh = '分贝控制 🤫', body_zh = '宝宝睡着时，家里一点声音都让你紧张？打开噪音测量，检查房间的声音环境，守护宝宝的睡眠。' WHERE id = '5817fca0-3cbb-4276-a47d-9383c042597d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mira todo lo que eres capaz de hacer! 💖', body_es = 'Mírate a los ojos cansados en el espejo y sonríe. ¡Estás criando un milagro sin ningún manual de instrucciones!', title_fr = 'Tout ce dont vous êtes capable ! 💖', body_fr = 'Regardez vos yeux fatigués dans le miroir et souriez. Vous élevez un petit miracle sans aucun mode d''emploi !', title_hi = 'आप क्या-क्या कर लेती हैं! 💖', body_hi = 'आईने में अपनी थकी आँखों को देखिए और मुस्कुराइए। आप बिना किसी निर्देश पुस्तिका के एक चमत्कार को बड़ा कर रही हैं!', title_id = 'Lihat betapa hebatnya Anda! 💖', body_id = 'Tatap mata lelah Anda di cermin dan tersenyumlah. Anda membesarkan sebuah keajaiban tanpa buku panduan apa pun!', title_ja = 'こんなにたくさんできるなんて！💖', body_ja = '鏡に映る疲れた目を見て、ほほえんでみて。あなたは説明書もなしに、ひとつの奇跡を育てているのです！', title_ko = '정말 많은 걸 해내고 있어요! 💖', body_ko = '거울 속 지친 눈을 보며 미소 지어 보세요. 설명서 하나 없이 기적을 키우고 있잖아요!', title_nl = 'Wat kun jij veel! 💖', body_nl = 'Kijk in de spiegel naar je vermoeide ogen en glimlach. Jij voedt een wonder op zonder handleiding!', title_pl = 'Ile ty potrafisz! 💖', body_pl = 'Spójrz w lustrze w swoje zmęczone oczy i się uśmiechnij. Wychowujesz cud bez żadnej instrukcji obsługi!', title_pt = 'Olhe só o que consegue fazer! 💖', body_pt = 'Olhe para os seus olhos cansados ao espelho e sorria. Está a criar um milagre sem nenhum manual de instruções!', title_sv = 'Så mycket du klarar! 💖', body_sv = 'Titta på dina trötta ögon i spegeln och le. Du uppfostrar ett mirakel utan någon bruksanvisning!', title_vi = 'Mẹ giỏi quá đi! 💖', body_vi = 'Hãy nhìn đôi mắt mệt mỏi của mình trong gương và mỉm cười. Mẹ đang nuôi lớn một phép màu mà chẳng cần cuốn sách hướng dẫn nào!', title_zh = '你真的很厉害！💖', body_zh = '看着镜子里疲惫的双眼，笑一笑吧。你没有任何说明书，却在养育一个奇迹！' WHERE id = 'df219eb3-fe33-48d7-81df-3e2d39df4620' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal va la rutina? 📈', body_es = 'Analiza las estadísticas de los últimos días en el Seguimiento de tomas y el Temporizador de sueño.', title_fr = 'Comment va le rythme ? 📈', body_fr = 'Analysez les statistiques des derniers jours en consultant le Suivi des repas et le minuteur de sommeil.', title_hi = 'रूटीन कैसा चल रहा है? 📈', body_hi = 'फ़ीडिंग ट्रैकर और स्लीप टाइमर देखकर पिछले दिनों के आँकड़ों का विश्लेषण कीजिए।', title_id = 'Bagaimana rutinitasnya? 📈', body_id = 'Lihat Pelacak Menyusui dan Timer Tidur, lalu tinjau statistik beberapa hari terakhir.', title_ja = '生活リズムはどうですか？📈', body_ja = '授乳記録ツールと睡眠タイマーを見て、ここ数日の記録を振り返りましょう。', title_ko = '일과는 잘 되고 있나요? 📈', body_ko = '수유 기록과 수면 타이머를 보며 최근 며칠의 통계를 살펴보세요.', title_nl = 'Hoe gaat het met het ritme? 📈', body_nl = 'Analyseer de cijfers van de afgelopen dagen in de Voedingstracker en de Slaaptimer.', title_pl = 'Jak idzie rytm dnia? 📈', body_pl = 'Przeanalizuj statystyki z ostatnich dni w narzędziu do śledzenia karmienia i timerze snu.', title_pt = 'Como vai a rotina? 📈', body_pt = 'Analise as estatísticas dos últimos dias no Registo de Alimentação e no temporizador de sono.', title_sv = 'Hur går rutinen? 📈', body_sv = 'Analysera statistiken för de senaste dagarna i Matningskoll och Sömntimern.', title_vi = 'Nếp sinh hoạt thế nào rồi? 📈', body_vi = 'Hãy xem Theo dõi cữ bú và Bộ hẹn giờ ngủ để phân tích số liệu những ngày gần đây.', title_zh = '作息进行得怎么样？📈', body_zh = '查看喂养记录和睡眠计时器，分析一下最近几天的数据吧。' WHERE id = '132a3a1b-1001-4fec-a775-7883117a6988' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Su rutina de sueño ha cambiado de repente? Antes de preocuparte, pide a Anacan AI información y consejos sobre la regresión del sueño de los 5 meses.', body_fr = 'Son rythme de sommeil a changé d''un coup ? Avant de vous inquiéter, demandez à Anacan AI des informations et des conseils sur la régression du sommeil de 5 mois.', body_hi = 'नींद का रूटीन अचानक बदल गया? चिंता करने से पहले Anacan AI से 5 महीने की स्लीप रिग्रेशन के बारे में जानकारी और सलाह लीजिए।', body_id = 'Pola tidurnya tiba-tiba berubah? Sebelum panik, cari informasi dan saran tentang regresi tidur usia 5 bulan di Anacan AI.', body_ja = '急に睡眠のリズムが変わった？心配する前に、Anacan AIで生後5か月の睡眠退行について情報とアドバイスを受け取りましょう。', body_ko = '수면 패턴이 갑자기 바뀌었나요? 걱정하기 전에 Anacan AI에게 5개월 수면 퇴행에 대한 정보와 조언을 받아 보세요.', body_nl = 'Is het slaapritme ineens veranderd? Raak niet in paniek, maar vraag Anacan AI om informatie en tips over de slaapregressie van 5 maanden.', body_pl = 'Rytm snu nagle się zmienił? Zanim zaczniesz się martwić, zapytaj Anacan AI o regres snu w 5. miesiącu i poproś o radę.', body_pt = 'O sono mudou de repente? Antes de se alarmar, peça ao Anacan AI informação e conselhos sobre a regressão do sono dos 5 meses.', body_sv = 'Har sömnrutinen plötsligt ändrats? Innan du oroar dig, få information och råd om sömnregressionen vid 5 månader från Anacan AI.', body_vi = 'Giấc ngủ của bé bỗng thay đổi? Trước khi lo lắng, hãy hỏi Anacan AI để biết thông tin và lời khuyên về thoái lui giấc ngủ ở tháng thứ 5.', body_zh = '睡眠作息突然变了？先别慌，向Anacan AI了解5个月睡眠倒退的信息和建议。' WHERE id = '1325aee8-211f-49a3-af39-fd0cef6023c0' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ropa con manchas 👗', body_es = 'Alimentación complementaria significa que todo se mancha. No te enfades: usa baberos de silicona y disfruta de estos momentos tan graciosos.', title_fr = 'Des vêtements tachés 👗', body_fr = 'Diversification rime avec taches partout. Ne vous énervez pas, utilisez des bavoirs en silicone et profitez de ces moments drôles.', title_hi = 'दाग वाले कपड़े 👗', body_hi = 'ऊपरी आहार का मतलब है हर जगह गंदगी। इससे परेशान मत होइए, सिलिकॉन बिब इस्तेमाल कीजिए और इन मज़ेदार पलों का आनंद लीजिए।', title_id = 'Baju penuh noda 👗', body_id = 'MPASI berarti semuanya jadi kotor. Jangan kesal, gunakan celemek silikon dan nikmati momen-momen lucu ini.', title_ja = '汚れた服 👗', body_ja = '離乳食が始まると、あちこち汚れるもの。イライラしないで、シリコンのスタイを使って、このおもしろい瞬間を楽しみましょう。', title_ko = '얼룩진 옷 👗', body_ko = '이유식은 곧 사방이 더러워진다는 뜻이에요. 짜증 내지 말고 실리콘 턱받이를 쓰며 이 웃긴 순간들을 즐기세요.', title_nl = 'Kleren vol vlekken 👗', body_nl = 'Bijvoeding betekent dat alles vies wordt. Word er niet boos om, gebruik siliconen slabbetjes en geniet van deze grappige momenten.', title_pl = 'Ubranka w plamach 👗', body_pl = 'Rozszerzanie diety oznacza bałagan wszędzie. Nie denerwuj się, używaj silikonowych śliniaków i ciesz się tymi zabawnymi chwilami.', title_pt = 'Roupa manchada 👗', body_pt = 'Diversificação alimentar significa sujidade por todo o lado. Não se irrite: use babetes de silicone e aproveite estes momentos divertidos.', title_sv = 'Fläckiga kläder 👗', body_sv = 'Smakportioner betyder att det blir smutsigt överallt. Bli inte irriterad, använd haklappar i silikon och njut av de här roliga stunderna.', title_vi = 'Quần áo lấm lem 👗', body_vi = 'Ăn dặm nghĩa là chỗ nào cũng bẩn. Đừng bực mình, hãy dùng yếm silicone và tận hưởng những khoảnh khắc buồn cười này.', title_zh = '沾满污渍的衣服 👗', body_zh = '添加辅食就意味着到处脏兮兮。别为此生气，用硅胶围兜，享受这些好笑的时刻吧。' WHERE id = 'e0613a64-c64f-491d-8c87-72276f72849e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Se acaban las reservas 🛒', body_es = '¿Hacen falta verduras nuevas para los purés? Apúntalas en la Lista de la compra y que tu pareja compre productos frescos al volver del trabajo.', title_fr = 'Les réserves s''épuisent 🛒', body_fr = 'Besoin de nouveaux légumes pour les purées ? Notez-les dans la Liste de courses pour que votre conjoint achète des produits frais en rentrant du travail.', title_hi = 'सामान खत्म हो रहा है 🛒', body_hi = 'प्यूरी के लिए नई सब्ज़ियाँ चाहिए? शॉपिंग लिस्ट में लिखिए, ताकि आपके साथी काम से लौटते समय ताज़ा सामान ले आएँ।', title_id = 'Persediaan menipis 🛒', body_id = 'Butuh sayuran baru untuk puree? Tulis di Daftar Belanja, biar pasangan Anda membeli bahan segar saat pulang kerja.', title_ja = 'ストックが切れそう 🛒', body_ja = 'ペースト用の新しい野菜が必要？「買い物リスト」に書いておけば、パートナーが仕事帰りに新鮮な食材を買ってきてくれます。', title_ko = '생필품이 떨어져 가요 🛒', body_ko = '퓌레에 쓸 새 채소가 필요한가요? 쇼핑 목록에 적어 두면 배우자가 퇴근길에 신선한 재료를 사 올 거예요.', title_nl = 'De voorraad raakt op 🛒', body_nl = 'Nieuwe groenten nodig voor de hapjes? Zet ze op je Boodschappenlijstje, dan koopt je partner op weg van zijn werk verse producten.', title_pl = 'Zapasy się kończą 🛒', body_pl = 'Potrzebne nowe warzywa na przeciery? Wpisz je na Listę zakupów, a partner kupi świeże produkty w drodze z pracy.', title_pt = 'As reservas estão a acabar 🛒', body_pt = 'Precisa de legumes novos para os purés? Escreva-os na Lista de Compras e o seu companheiro compra produtos frescos no regresso do trabalho.', title_sv = 'Förråden tar slut 🛒', body_sv = 'Behöver du nya grönsaker till puréerna? Skriv upp dem i Inköpslistan, så kan din partner köpa färska varor på vägen hem från jobbet.', title_vi = 'Đồ dùng sắp hết 🛒', body_vi = 'Cần thêm rau củ để làm món nghiền? Ghi vào Danh sách mua sắm để bố mua đồ tươi trên đường đi làm về.', title_zh = '存货快用完了 🛒', body_zh = '做菜泥需要新的蔬菜？写进购物清单，让伴侣下班路上买些新鲜的回来。' WHERE id = 'e67730b8-4981-4bba-b868-fe6cf9b7e3da' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Déjale jugar con la comida! 🥦', body_es = 'Deja que toque la comida, la aplaste y la explore. ¡Captura estos momentos dulces y caóticos con la Sesión de fotos del bebé y guárdalos de recuerdo!', title_fr = 'Laissez-le jouer avec la nourriture ! 🥦', body_fr = 'Laissez-le toucher, écraser et explorer sa nourriture. Immortalisez ces moments adorables et salissants avec la Séance photo bébé !', title_hi = 'खाने से खेलने दीजिए! 🥦', body_hi = 'उसे खाने को छूने, मसलने और खोजने दीजिए। इन प्यारे और बिखरे पलों को बेबी फ़ोटोशूट से कैद करके यादों में सहेजिए!', title_id = 'Biarkan ia bermain dengan makanan! 🥦', body_id = 'Biarkan ia menyentuh, meremas, dan menjelajahi makanannya. Abadikan momen manis dan berantakan ini dengan Sesi Foto Bayi!', title_ja = '食べ物で遊ばせてあげて！🥦', body_ja = '食べ物にさわって、つぶして、探検させてあげましょう。このかわいくて散らかった瞬間を「ベビーフォトセッション」で撮って、思い出に残しましょう！', title_ko = '음식으로 놀게 해 주세요! 🥦', body_ko = '음식을 만지고, 으깨고, 탐색하게 해 주세요. 이 귀엽고 엉망진창인 순간을 아기 사진 촬영으로 찍어 추억으로 남기세요!', title_nl = 'Laat je baby met eten spelen! 🥦', body_nl = 'Laat hem het eten aanraken, fijnknijpen en ontdekken. Leg deze lieve, rommelige momenten vast met Babyfotoshoot en bewaar ze als herinnering!', title_pl = 'Pozwól mu bawić się jedzeniem! 🥦', body_pl = 'Niech dotyka jedzenia, rozgniata je i odkrywa. Uchwyć te słodkie, bałaganiarskie chwile w Sesji zdjęciowej dziecka i zachowaj je na pamiątkę!', title_pt = 'Deixe-o brincar com a comida! 🥦', body_pt = 'Deixe-o tocar, esmagar e explorar a comida. Fotografe estes momentos doces e desarrumados com a Sessão Fotográfica do Bebé e guarde-os na memória!', title_sv = 'Låt barnet leka med maten! 🥦', body_sv = 'Låt barnet röra vid maten, klämma på den och utforska den. Fånga de här söta och kladdiga stunderna med Babyfotografering och spara dem som minnen!', title_vi = 'Cứ để bé nghịch đồ ăn! 🥦', body_vi = 'Hãy để bé chạm, bóp nát và khám phá đồ ăn. Ghi lại những khoảnh khắc đáng yêu, bừa bộn này bằng Chụp ảnh cho bé để lưu giữ trong ký ức!', title_zh = '让宝宝玩食物吧！🥦', body_zh = '让宝宝去摸、去捏、去探索食物。用宝宝写真拍下这些甜蜜又凌乱的时刻，留作回忆吧！' WHERE id = 'a134dfa9-2e73-4246-a281-0577e4411534' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche, bañar al bebé y prepararle para dormir es tarea de papá.', body_fr = 'Ce soir, donner le bain à bébé et le préparer pour la nuit, c''est le travail de papa.', body_hi = 'आज शाम बच्चे को नहलाना और सोने के लिए तैयार करना पापा का काम है।', body_id = 'Malam ini, memandikan si kecil dan menyiapkannya tidur adalah tugas ayah.', body_ja = '今夜は赤ちゃんのお風呂と寝る準備はパパの担当です。', body_ko = '오늘 저녁 아이를 목욕시키고 재울 준비를 하는 건 아빠 몫이에요.', body_nl = 'Vanavond zijn het badje en klaarmaken voor bed de taak van papa.', body_pl = 'Dziś wieczorem kąpiel i przygotowanie maluszka do snu to zadanie taty.', body_pt = 'Esta noite, dar banho ao bebé e prepará-lo para dormir é tarefa do pai.', body_sv = 'I kväll är det pappas uppgift att bada barnet och göra det redo för sömnen.', body_vi = 'Tối nay, việc tắm cho bé và chuẩn bị cho bé đi ngủ là nhiệm vụ của bố.', body_zh = '今晚给宝宝洗澡、哄睡前准备都是爸爸的工作。' WHERE id = 'f998fac0-0a6b-42d2-b200-7a956f147c9a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño explorador 👣', body_es = '¡Ya ha descubierto los dedos de sus pies e intenta llevárselos a la boca!', title_fr = 'Petit explorateur 👣', body_fr = 'Il a découvert ses orteils et essaie de les porter à sa bouche !', title_hi = 'नन्हा खोजी 👣', body_hi = 'उसने अपने पैरों की उँगलियाँ खोज ली हैं और उन्हें मुँह में डालने की कोशिश कर रहा है!', title_id = 'Penjelajah kecil 👣', body_id = 'Ia sudah menemukan jari kakinya dan mencoba memasukkannya ke mulut!', title_ja = '小さな探検家 👣', body_ja = '自分の足の指を発見して、口に入れようとしています！', title_ko = '꼬마 탐험가 👣', body_ko = '이제 자기 발가락을 발견하고 입으로 가져가려 해요!', title_nl = 'Een kleine ontdekkingsreiziger 👣', body_nl = 'Je baby heeft de eigen teentjes ontdekt en probeert ze in de mond te stoppen!', title_pl = 'Mały odkrywca 👣', body_pl = 'Odkrył już swoje paluszki u stóp i próbuje wkładać je do buzi!', title_pt = 'Pequeno explorador 👣', body_pt = 'Já descobriu os dedos dos pés e tenta levá-los à boca!', title_sv = 'Liten upptäcktsresande 👣', body_sv = 'Barnet har redan upptäckt sina tår och försöker stoppa dem i munnen!', title_vi = 'Nhà thám hiểm nhỏ 👣', body_vi = 'Bé đã phát hiện ra ngón chân và đang cố đưa vào miệng!', title_zh = '小小探险家 👣', body_zh = '宝宝已经发现了自己的脚趾，还想把它们放进嘴里！' WHERE id = 'aff9ba8d-8d8a-4d80-9363-09474c73609e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorando el tiempo ⛅', body_es = '¿No está claro qué tiempo hace fuera? Deja que la herramienta Tiempo y ropa te diga al instante la velocidad del viento que no se ve desde la ventana y el conjunto adecuado, y sal de paseo sin dudar.', title_fr = 'Bulletin météo ⛅', body_fr = 'Le temps dehors n''est pas très clair ? L''outil Météo et tenue vous indique aussitôt la vitesse du vent, invisible depuis la fenêtre, et la bonne tenue : sortez vous promener sans hésiter.', title_hi = 'मौसम की जासूसी ⛅', body_hi = 'बाहर मौसम साफ़ नहीं है? मौसम और कपड़े टूल आपको खिड़की से न दिखने वाली हवा की रफ़्तार और सही कपड़े तुरंत बताएगा, बेझिझक सैर पर निकलिए।', title_id = 'Mengintip cuaca ⛅', body_id = 'Cuaca di luar tidak jelas? Biarkan fitur Cuaca dan Pakaian langsung memberi tahu kecepatan angin yang tak terlihat dari jendela dan pakaian yang tepat, lalu jalan-jalanlah tanpa ragu.', title_ja = 'お天気チェック ⛅', body_ja = '外の天気がはっきりしない？「天気と服装」ツールが、窓からは見えない風の強さとぴったりの服装をすぐに教えてくれます。迷わずお散歩に出かけましょう。', title_ko = '날씨 탐색 ⛅', body_ko = '바깥 날씨가 애매한가요? 날씨와 옷차림 도구가 창밖으로는 보이지 않는 바람 세기와 알맞은 옷차림을 바로 알려 줄 테니 망설임 없이 산책을 나가세요.', title_nl = 'Het weer verkennen ⛅', body_nl = 'Is het weer buiten niet helemaal duidelijk? Laat de tool Weer en kleding je meteen de windsnelheid vertellen die je niet vanuit het raam ziet, plus de juiste outfit, en ga zonder twijfel wandelen.', title_pl = 'Rozpoznanie pogody ⛅', body_pl = 'Pogoda na dworze niepewna? Narzędzie Pogoda i ubiór od razu powie ci, jak mocno wieje wiatr, czego nie widać przez okno, i jaki zestaw wybrać. Wychodź na spacer bez wahania.', title_pt = 'Exploração do tempo ⛅', body_pt = 'O tempo lá fora não está bem definido? Deixe a ferramenta Tempo e Roupa dizer-lhe na hora a velocidade do vento que não se vê da janela e a roupa certa, e saia a passear sem hesitar.', title_sv = 'Väderspaning ⛅', body_sv = 'Är vädret ute osäkert? Låt Väder och kläder direkt berätta vindstyrkan som inte syns genom fönstret och rätt klädsel, och gå ut på promenad utan att tveka.', title_vi = 'Thám thính thời tiết ⛅', body_vi = 'Thời tiết bên ngoài không rõ ràng? Hãy để công cụ Thời tiết và trang phục cho mẹ biết ngay tốc độ gió mà nhìn qua cửa sổ không thấy được và bộ đồ phù hợp, rồi yên tâm ra ngoài đi dạo.', title_zh = '天气侦察 ⛅', body_zh = '外面天气说不准？让天气穿衣工具马上告诉你窗外看不到的风速和合适的搭配，放心出门散步吧。' WHERE id = '856b771b-5997-4eed-bc26-8b35541184c6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La atracción por las escaleras 🧗‍♂️', body_es = 'Si en casa hay escaleras o sitios altos, va directo hacia ellos. Ha llegado el momento de instalar barreras de seguridad.', title_fr = 'L''attrait des escaliers 🧗‍♂️', body_fr = 'S''il y a des escaliers ou des endroits en hauteur à la maison, il veut y aller. C''est vraiment le moment d''installer des barrières de sécurité.', title_hi = 'सीढ़ियों का आकर्षण 🧗‍♂️', body_hi = 'अगर घर में सीढ़ियाँ या ऊँची जगहें हैं, तो वह उनकी ओर लपकता है। सेफ़्टी गेट लगाने का सही समय आ गया है।', title_id = 'Tertarik pada tangga 🧗‍♂️', body_id = 'Kalau di rumah ada tangga atau tempat tinggi, ia akan berusaha ke sana. Inilah saatnya memasang pagar pengaman.', title_ja = '階段に夢中 🧗‍♂️', body_ja = '家に階段や高いところがあると、そこへ向かっていきます。ベビーゲートを取りつけるときがやってきました。', title_ko = '계단에 대한 호기심 🧗‍♂️', body_ko = '집에 계단이나 높은 곳이 있다면 그쪽으로 가려고 해요. 안전문을 설치할 때가 왔어요.', title_nl = 'Nieuwsgierig naar de trap 🧗‍♂️', body_nl = 'Zijn er een trap of hoge plekken in huis? Dan wil je baby daar naartoe. Nu is echt het moment om traphekjes te plaatsen.', title_pl = 'Ciekawość schodów 🧗‍♂️', body_pl = 'Jeśli w domu są schody lub wysokie miejsca, ciągnie go tam. Nadszedł czas, by zamontować bramki zabezpieczające.', title_pt = 'O fascínio pelas escadas 🧗‍♂️', body_pt = 'Se em casa há escadas ou sítios altos, ele tenta lá chegar. Chegou mesmo a altura de instalar portões de segurança.', title_sv = 'Lockelsen i trappan 🧗‍♂️', body_sv = 'Om ni har trappor eller höga ställen hemma dras barnet dit. Nu är det verkligen dags att sätta upp säkerhetsgrindar.', title_vi = 'Sức hút của cầu thang 🧗‍♂️', body_vi = 'Nếu nhà có cầu thang hay chỗ cao, bé sẽ tìm cách tiến về phía đó. Đã đến lúc lắp cổng chắn an toàn rồi.', title_zh = '对楼梯好奇 🧗‍♂️', body_zh = '如果家里有楼梯或高处，宝宝就会想往那儿去。是时候安装安全门栏了。' WHERE id = '38581365-03a6-48aa-a7b4-923dde40764d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Quedan tareas pendientes? Que esperen. 🌪️', body_es = 'Pide a tu pareja que hoy se encargue de las tareas de casa. Tú descansa.', title_fr = 'Le ménage attend ? Laissez-le attendre. 🌪️', body_fr = 'Demandez à votre conjoint de prendre en charge les tâches ménagères aujourd''hui. Vous, reposez-vous.', title_hi = 'काम रह गए? रहने दीजिए 🌪️', body_hi = 'अपने जीवनसाथी से कहिए कि आज घर के काम वे संभालें। आप आराम कीजिए।', title_id = 'Pekerjaan menumpuk? Biarkan saja. 🌪️', body_id = 'Minta pasangan Anda mengambil alih pekerjaan rumah hari ini. Anda beristirahatlah.', title_ja = '家事が残っている？そのままでいいんです。🌪️', body_ja = '今日の家事はパートナーにお願いしましょう。あなたは休んでください。', title_ko = '일이 밀렸나요? 그냥 두세요. 🌪️', body_ko = '오늘 집안일은 배우자에게 맡기세요. 엄마는 쉬세요.', title_nl = 'Blijft er werk liggen? Laat het liggen.  🌪️', body_nl = 'Vraag je partner om vandaag het huishouden op zich te nemen. En jij rust uit.', title_pl = 'Obowiązki zostają? Niech zostaną. 🌪️', body_pl = 'Poproś partnera, żeby dziś przejął domowe obowiązki. A ty odpocznij.', title_pt = 'As tarefas ficam por fazer? Deixe ficar.  🌪️', body_pt = 'Peça ao seu companheiro que hoje se encarregue das tarefas da casa. A mãe descansa.', title_sv = 'Blir sysslorna liggande? Låt dem ligga.  🌪️', body_sv = 'Be din partner ta hand om hushållet i dag. Du ska vila.', title_vi = 'Việc còn dang dở? Cứ để đó.  🌪️', body_vi = 'Hãy nhờ bố đảm nhận việc nhà hôm nay. Mẹ nghỉ ngơi đi.', title_zh = '家务没做完？就先放着吧 🌪️', body_zh = '请你的伴侣今天把家务都揽下来。你好好休息。' WHERE id = 'dffa4555-16c2-4705-a09e-e04f9ae6d25d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Si algún detalle de su desarrollo te preocupa, incluso de noche, pregunta a nuestro asistente Anacan AI y recibe apoyo experto.', body_fr = 'Si un détail de son développement vous inquiète, même tard le soir, interrogez notre assistant Anacan AI et obtenez le soutien d''un expert.', body_hi = 'विकास से जुड़ी कोई भी बात परेशान करे, तो देर रात भी Anacan AI असिस्टेंट से पूछिए और विशेषज्ञ सहायता पाइए।', body_id = 'Tanyakan detail perkembangan apa pun yang membuat Anda khawatir ke asisten Anacan AI, bahkan di malam hari, dan dapatkan dukungan ahli.', body_ja = '発達で気になることがあれば、夜中でもAnacan AIアシスタントに聞いて、専門的なサポートを受けましょう。', body_ko = '걱정되는 발달 문제가 있다면 늦은 밤이라도 Anacan AI 도우미에게 물어 전문적인 도움을 받으세요.', body_nl = 'Maak je je zorgen over iets in de ontwikkeling? Vraag het zelfs ''s nachts aan onze assistent Anacan AI en krijg deskundige steun.', body_pl = 'Jeśli niepokoi cię jakikolwiek szczegół rozwoju, nawet w nocy zapytaj naszego asystenta Anacan AI i otrzymaj wsparcie eksperta.', body_pt = 'Qualquer pormenor do desenvolvimento que a preocupe, mesmo a meio da noite, pergunte ao nosso assistente Anacan AI e receba apoio especializado.', body_sv = 'Fråga vår assistent Anacan AI om allt i utvecklingen som oroar dig, även sent på natten, och få expertstöd.', body_vi = 'Bất kỳ chi tiết nào về sự phát triển khiến mẹ lo lắng, kể cả lúc nửa đêm, hãy hỏi trợ lý Anacan AI để nhận hỗ trợ từ chuyên gia.', body_zh = '任何让你担心的发育细节，哪怕是深夜，都可以问问我们的Anacan AI助手，获得专业支持。' WHERE id = '1d119442-bc5b-4f46-a607-68533220e425' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fase del «¡dame mi juguete!» 🧸', body_es = 'Cuando le quitas algo de las manos, reacciona con fuerza y llora. Su sentido de la propiedad ya se está formando del todo. En vez de prohibir, desvía su atención hacia otra cosa.', title_fr = 'La phase « Rends-moi mon jouet ! » 🧸', body_fr = 'Quand vous lui prenez quelque chose des mains, il réagit vivement et pleure. Son sens de la propriété est désormais bien formé. Plutôt que d''interdire, détournez son attention.', title_hi = '''मेरा खिलौना दो!'' वाली ज़िद 🧸', body_hi = 'उसके हाथ से कुछ लेने पर तीखी प्रतिक्रिया देता है और रोता है। ''मेरा'' होने का एहसास अब पूरी तरह बन रहा है। मना करने के बजाय उसका ध्यान कहीं और मोड़िए।', title_id = 'Fase "Kembalikan mainanku!" 🧸', body_id = 'Saat Anda mengambil sesuatu dari tangannya, ia bereaksi keras dan menangis. Rasa memilikinya sudah terbentuk sepenuhnya. Daripada melarang, alihkan perhatiannya ke hal lain.', title_ja = '「おもちゃ返して！」の時期 🧸', body_ja = '手から何かを取り上げると、激しく反応して泣きますか？「自分のもの」という感覚がしっかり育っています。ダメと言う代わりに、気をそらしてあげましょう。', title_ko = '''내 장난감 줘!'' 고집 🧸', body_ko = '손에서 무언가를 빼면 격하게 반응하며 울어요. 소유 개념이 완전히 자리 잡고 있어요. 금지하기보다 관심을 다른 곳으로 돌려 주세요.', title_nl = 'Geef mijn speeltje! 🧸', body_nl = 'Pak je iets uit zijn handjes, dan reageert hij fel en huilt hij. Het gevoel van bezit is nu helemaal gevormd. Verbied het niet alleen, maar leid zijn aandacht af.', title_pl = 'Upór: oddaj moją zabawkę! 🧸', body_pl = 'Gdy coś mu zabierasz, reaguje ostro i płacze. Poczucie własności w pełni się kształtuje. Zamiast zakazywać, odwróć jego uwagę.', title_pt = 'A teimosia do "dá-me o meu brinquedo!" 🧸', body_pt = 'Quando lhe tira alguma coisa das mãos, reage com força e chora. O sentido de posse está a formar-se por completo. Em vez de proibir, desvie a atenção dele para outra coisa.', title_sv = 'Ge mig min leksak!-envisheten 🧸', body_sv = 'När du tar något ifrån barnet reagerar det häftigt och gråter. Känslan för ägande tar nu form fullt ut. I stället för att förbjuda, led om uppmärksamheten.', title_vi = 'Giai đoạn "Trả đồ chơi cho con!" 🧸', body_vi = 'Khi mẹ lấy thứ gì đó khỏi tay, bé phản ứng gay gắt và khóc. Ý thức sở hữu đã hình thành hoàn chỉnh. Thay vì cấm đoán, hãy hướng sự chú ý của bé sang thứ khác.', title_zh = '“把我的玩具给我！”阶段 🧸', body_zh = '从宝宝手里拿走东西时，宝宝反应激烈还大哭。物权意识已经完全形成。与其禁止，不如转移宝宝的注意力。' WHERE id = 'e83a5069-7214-47ea-9051-6406495d5723' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Después de un día difícil, sentaos cara a cara tu pareja y tú y hablad. Apoyaros reparte la carga a la mitad.', body_fr = 'Après une journée difficile, asseyez-vous face à votre conjoint et parlez. Vous soutenir mutuellement allège la charge de moitié.', body_hi = 'मुश्किल दिन के बाद अपने साथी के साथ आमने-सामने बैठकर दिल की बात कीजिए। एक-दूसरे का साथ बोझ आधा कर देता है।', body_id = 'Setelah hari yang berat, duduklah berhadapan dengan pasangan dan saling bercerita. Saling mendukung membuat beban terbagi dua.', body_ja = '大変な1日のあとは、パートナーと向き合って話しましょう。支え合うことで、負担は半分になります。', body_ko = '힘든 하루를 보낸 뒤 배우자와 마주 앉아 이야기를 나눠 보세요. 서로를 응원하면 짐이 절반으로 줄어요.', body_nl = 'Ga na een zware dag tegenover je partner zitten en praat je hart uit. Elkaar steunen halveert de last.', body_pl = 'Po trudnym dniu usiądź z partnerem twarzą w twarz i porozmawiajcie. Wzajemne wsparcie dzieli ciężar na pół.', body_pt = 'Depois de um dia difícil, sente-se frente a frente com o seu companheiro e conversem. Apoiarem-se um ao outro divide o peso ao meio.', body_sv = 'Efter en tuff dag, sätt er mittemot varandra och prata ut med din partner. Att stötta varandra halverar bördan.', body_vi = 'Sau một ngày vất vả, hãy ngồi đối diện và tâm sự cùng bố. Cùng nâng đỡ nhau sẽ giúp gánh nặng vơi đi một nửa.', body_zh = '辛苦一天后，和伴侣面对面坐下聊聊。互相支持，担子就轻了一半。' WHERE id = '5f3d97d0-e211-488f-bb05-dd9ccce213a3' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisión del desarrollo 🤖', title_fr = 'Bilan de développement 🤖', title_hi = 'विकास की जाँच 🤖', title_id = 'Cek perkembangan 🤖', title_ja = '発達チェック 🤖', title_ko = '발달 체크 🤖', title_nl = 'Ontwikkelingscheck 🤖', title_pl = 'Kontrola rozwoju 🤖', title_pt = 'Verificação do desenvolvimento 🤖', title_sv = 'Utvecklingskoll 🤖', title_vi = 'Kiểm tra sự phát triển 🤖', title_zh = '发育检查 🤖' WHERE id = '92cb503c-c013-47cb-ab12-416c047b2693' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escalando los muebles 🧗‍♂️', title_fr = 'Grimper sur les meubles 🧗‍♂️', title_hi = 'फ़र्नीचर पर चढ़ना 🧗‍♂️', title_id = 'Memanjat perabot 🧗‍♂️', title_ja = '家具によじのぼる 🧗‍♂️', title_ko = '가구 오르기 🧗‍♂️', title_nl = 'Op meubels klimmen 🧗‍♂️', title_pl = 'Wspinaczka po meblach 🧗‍♂️', title_pt = 'Trepar aos móveis 🧗‍♂️', title_sv = 'Klättrar på möblerna 🧗‍♂️', title_vi = 'Trèo lên đồ đạc 🧗‍♂️', title_zh = '攀爬家具 🧗‍♂️' WHERE id = 'e0d7037f-df25-46a9-8fd2-5b2b39c1432d' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Nana de buenas noches 🎶', body_es = 'Ninguna app ni sonido puede sustituir la nana de una madre. Esta noche, simplemente abrázale contra tu pecho y cántale bajito su nana favorita, la que le da seguridad.', title_fr = 'Berceuse du soir 🎶', body_fr = 'Aucune application ni aucun son ne remplace la berceuse d''une maman. Ce soir, serrez-le simplement contre vous et chantez doucement sa berceuse préférée, celle qui le rassure.', title_hi = 'रात की लोरी 🎶', body_hi = 'कोई भी ऐप या आवाज़ माँ की लोरी की जगह नहीं ले सकती। आज शाम बस उसे सीने से लगाइए और धीरे से उसकी पसंदीदा, भरोसा देने वाली लोरी गाइए।', title_id = 'Nina bobo malam 🎶', body_id = 'Tidak ada aplikasi atau suara yang bisa menggantikan nina bobo ibu. Malam ini, cukup dekap ia di dada dan nyanyikan pelan lagu kesukaannya yang menenangkan.', title_ja = '夜の子守唄 🎶', body_ja = 'どんなアプリも音も、ママの子守唄にはかないません。今夜はただ胸に抱きよせて、お気に入りの安心できる子守唄をそっと歌ってあげましょう。', title_ko = '밤의 자장가 🎶', body_ko = '어떤 앱도, 어떤 소리도 엄마의 자장가를 대신할 수 없어요. 오늘 저녁은 아기를 가슴에 꼭 안고 가장 좋아하는 포근한 자장가를 나지막이 불러 주세요.', title_nl = 'Een slaapliedje voor de nacht 🎶', body_nl = 'Geen app of geluid kan het slaapliedje van een moeder vervangen. Houd je kleintje vanavond gewoon tegen je borst en zing zachtjes zijn lievelingsliedje dat hem vertrouwen geeft.', title_pl = 'Kołysanka na noc 🎶', body_pl = 'Żadna aplikacja ani dźwięk nie zastąpi kołysanki mamy. Dziś wieczorem po prostu przytul go do piersi i cichutko zaśpiewaj jego ulubioną, dającą poczucie bezpieczeństwa kołysankę.', title_pt = 'Canção de embalar da noite 🎶', body_pt = 'Nenhuma app ou som substitui a canção de embalar da mãe. Esta noite, aconchegue-o ao peito e cante baixinho a canção de embalar de que ele mais gosta e que lhe dá segurança.', title_sv = 'Vaggvisa för natten 🎶', body_sv = 'Ingen app och inget ljud kan ersätta mammas vaggvisa. I kväll, håll bara barnet tätt intill bröstet och sjung tyst den trygga vaggvisa barnet tycker mest om.', title_vi = 'Lời ru ban đêm 🎶', body_vi = 'Không ứng dụng hay âm thanh nào thay được lời ru của mẹ. Tối nay chỉ cần ôm bé vào lòng và khẽ hát bài ru bé thích nhất, cho bé cảm giác an toàn.', title_zh = '晚安摇篮曲 🎶', body_zh = '没有任何应用或声音能取代妈妈的摇篮曲。今晚就把宝宝抱在怀里，轻轻唱宝宝最爱、最安心的那首摇篮曲吧。' WHERE id = '6007d88c-cdbb-46d0-9b99-4e7bdd857418' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Diario emocional 📝', body_es = 'Cuando te sientas sola, vuelca tus emociones en el Diario de ánimo. Todas las mujeres pasan por este camino. Eres fuerte.', title_fr = 'Un journal des émotions 📝', body_fr = 'Quand vous vous sentez seule, déversez vos émotions dans le Journal d''humeur. Toutes les femmes passent par ces chemins, vous êtes forte.', title_hi = 'भावनाओं की डायरी 📝', body_hi = 'जब अकेली महसूस करें, तो अपनी भावनाएँ मूड डायरी में उड़ेल दीजिए। हर महिला इन रास्तों से गुज़रती है, आप मज़बूत हैं।', title_id = 'Buku harian perasaan 📝', body_id = 'Saat merasa sendirian, tuangkan perasaan Anda di Buku Harian Suasana Hati. Semua perempuan melewati jalan ini, Anda kuat.', title_ja = '気持ちの日記 📝', body_ja = 'ひとりぼっちだと感じたら、「気分日記」に気持ちを吐き出しましょう。どの女性もこの道を通ります。あなたは強い人です。', title_ko = '마음 일기 📝', body_ko = '외로울 때는 기분 일기에 감정을 쏟아 내세요. 모든 여성이 이 길을 지나요. 당신은 강해요.', title_nl = 'Een gevoelsdagboek 📝', body_nl = 'Voel je je alleen? Laat je gevoelens de vrije loop in je Stemmingsdagboek. Alle vrouwen gaan deze weg, je bent sterk.', title_pl = 'Dziennik emocji 📝', body_pl = 'Gdy czujesz się samotna, przelej swoje uczucia do Dziennika nastroju. Wszystkie kobiety przechodzą tę drogę, jesteś silna.', title_pt = 'Diário emocional 📝', body_pt = 'Quando se sentir sozinha, despeje o que sente no Diário de Humor. Todas as mulheres passam por estes caminhos: é forte.', title_sv = 'Känslodagbok 📝', body_sv = 'När du känner dig ensam, häll ut dina känslor i Humördagboken. Alla kvinnor går igenom de här vägarna, du är stark.', title_vi = 'Nhật ký cảm xúc 📝', body_vi = 'Khi thấy cô đơn, hãy trút cảm xúc vào Nhật ký tâm trạng. Người phụ nữ nào cũng đi qua những chặng đường này, mẹ mạnh mẽ lắm.', title_zh = '情绪日记 📝', body_zh = '觉得孤单时，就把感受倾诉在心情日记里。每个女人都会走过这些路，你很坚强。' WHERE id = '0ffbde04-3193-4b21-aa17-136db5de3c72' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidad de silencio 🤫', body_es = 'Protege la calma de la habitación con el Medidor de sonido. El sueño interrumpido por la noche estropea su humor por la mañana, y también el tuyo.', title_fr = 'Besoin de silence 🤫', body_fr = 'Protégez le calme de la chambre avec le Sonomètre. Un sommeil interrompu la nuit gâche l''humeur du matin, la sienne comme la vôtre.', title_hi = 'खामोशी की ज़रूरत 🤫', body_hi = 'साउंड मीटर से कमरे की शांति बनाए रखिए। रात में टूटी नींद उसका और आपका, दोनों का सुबह का मूड बिगाड़ देती है।', title_id = 'Butuh keheningan 🤫', body_id = 'Jaga ketenangan kamar dengan Pengukur Suara. Tidur yang terputus di malam hari merusak suasana hatinya dan juga Anda di pagi hari.', title_ja = '静けさが必要 🤫', body_ja = '「サウンドメーター」で部屋の静けさを守りましょう。夜中に途切れた眠りは、赤ちゃんとあなたの朝のごきげんを左右します。', title_ko = '고요함이 필요해요 🤫', body_ko = '소음 측정기로 방의 고요함을 지켜 주세요. 밤에 끊긴 잠은 아기와 엄마의 아침 기분을 모두 망쳐요.', title_nl = 'Behoefte aan stilte 🤫', body_nl = 'Bescherm de rust in de kamer met de Geluidsmeter. Een onderbroken nachtrust verpest de ochtendstemming van hem én van jou.', title_pl = 'Potrzeba ciszy 🤫', body_pl = 'Chroń spokój w pokoju Miernikiem dźwięku. Przerwany nocny sen psuje poranny nastrój i jemu, i tobie.', title_pt = 'Necessidade de silêncio 🤫', body_pt = 'Proteja a calma do quarto com o Medidor de Som. O sono interrompido à noite estraga o humor da manhã, o dele e o seu.', title_sv = 'Behovet av tystnad 🤫', body_sv = 'Skydda lugnet i rummet med Ljudmätaren. Avbruten nattsömn förstör både barnets och ditt humör på morgonen.', title_vi = 'Cần sự yên tĩnh 🤫', body_vi = 'Hãy giữ yên tĩnh cho căn phòng bằng Đo âm thanh. Giấc ngủ đêm bị gián đoạn làm hỏng tâm trạng buổi sáng của cả bé lẫn mẹ.', title_zh = '需要安静 🤫', body_zh = '用噪音测量守护房间的安静。夜里睡眠被打断，宝宝和你第二天早上的心情都会受影响。' WHERE id = '7cdfa7f4-2c92-497d-9290-43caf53d8a56' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
