UPDATE public.mommy_day_notifications SET title_es = 'No dudes en preguntar 🤖', title_fr = 'N''hésitez pas à demander 🤖', title_hi = 'पूछने में झिझकिए मत 🤖', title_id = 'Jangan ragu bertanya 🤖', title_ja = '遠慮せず聞いてみて 🤖', title_ko = '망설이지 말고 물어보세요 🤖', title_nl = 'Durf het te vragen 🤖', title_pl = 'Nie wahaj się pytać 🤖', title_pt = 'Não hesite em perguntar 🤖', title_sv = 'Tveka inte att fråga 🤖', title_vi = 'Đừng ngại hỏi 🤖', title_zh = '别不好意思问 🤖' WHERE id = '0dcb1657-4eeb-47c5-a193-84ed106d43bc' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de juego independiente 🧸', title_fr = 'L''heure du jeu en solo 🧸', title_hi = 'अकेले खेलने का समय 🧸', title_id = 'Waktu bermain mandiri 🧸', title_ja = 'ひとり遊びの時間 🧸', title_ko = '혼자 노는 시간 🧸', title_nl = 'Tijd voor zelfstandig spelen 🧸', title_pl = 'Czas na samodzielną zabawę 🧸', title_pt = 'Hora de brincar sozinho 🧸', title_sv = 'Stund för egen lek 🧸', title_vi = 'Giờ chơi một mình 🧸', title_zh = '独立玩耍时间 🧸' WHERE id = '15bfc39a-e833-4e38-b7fc-bc13ef473b00' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se detiene y te mira cuando dices «no» con voz seria? ¡Ya empieza a captar las emociones y los límites!', body_fr = 'Il s''arrête net et vous regarde quand vous dites « non » d''une voix ferme ? Il commence déjà à saisir les émotions et les interdits !', body_hi = 'सख्त आवाज़ में ''ना'' कहने पर वह रुककर आपको देखता है? वह अब भावनाओं और मनाही को समझने लगा है!', body_id = 'Saat Anda berkata "tidak" dengan suara tegas, ia berhenti dan menatap Anda? Ia mulai memahami emosi dan larangan!', body_ja = 'きっぱりした声で「ダメ」と言うと、動きを止めてあなたを見ますか？感情や「してはいけないこと」を理解しはじめています！', body_ko = '단호한 목소리로 ''안 돼''라고 하면 멈칫하며 엄마를 바라보나요? 이제 감정과 금지를 이해하기 시작했어요!', body_nl = 'Stopt je baby even en kijkt hij je aan als je streng nee zegt? Hij begint emoties en verboden al te begrijpen!', body_pl = 'Gdy mówisz poważnym głosem „nie”, zatrzymuje się i na ciebie patrzy? Zaczyna już rozumieć emocje i zakazy!', body_pt = 'Quando diz "não" com voz séria, ele para e olha para si? Já começa a perceber as emoções e as proibições!', body_sv = 'Stannar barnet upp och tittar på dig när du säger nej med allvarlig röst? Det börjar redan förstå känslor och förbud!', body_vi = 'Khi mẹ nói "không" với giọng nghiêm, bé khựng lại và nhìn mẹ? Bé đã bắt đầu hiểu cảm xúc và những điều bị cấm!', body_zh = '你用严肃的语气说“不”时，宝宝会停下来看着你？宝宝已经开始理解情绪和禁止了！' WHERE id = '99045f34-6450-4abd-856c-64fd61405e7b' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Prueba a calmar con música clásica suave esas tormentas sin motivo que estallan al caer la tarde. Muchas veces este truco tan sencillo hace milagros.', body_fr = 'Essayez de calmer les tempêtes inexpliquées de fin de journée avec une musique classique douce. Souvent, cette astuce toute simple fait des miracles.', body_hi = 'शाम को अचानक उठने वाले बेवजह तूफ़ानों को हल्के क्लासिकल संगीत से शांत करके देखिए। अक्सर यह आसान तरकीब कमाल कर देती है।', body_id = 'Coba redakan badai tanpa sebab menjelang sore dengan musik klasik yang lembut. Sering kali trik sederhana ini membawa keajaiban.', body_ja = '夕方に突然始まる理由のわからない嵐には、静かなクラシック音楽を試してみましょう。このシンプルな方法が、たいてい奇跡を起こします。', body_ko = '늦은 오후에 몰아치는 이유 없는 울음을 잔잔한 클래식 음악으로 달래 보세요. 이 간단한 방법이 기적을 만들 때가 많아요.', body_nl = 'Probeer de onverklaarbare stormen aan het eind van de middag te stoppen met zachte klassieke muziek. Vaak doet dit simpele trucje wonderen.', body_pl = 'Wieczorne burze bez powodu spróbuj uciszyć spokojną muzyką klasyczną. Często ten prosty trik czyni cuda.', body_pt = 'Experimente acalmar com música clássica suave as tempestades sem motivo que rebentam ao fim da tarde. Muitas vezes, este truque simples faz milagres.', body_sv = 'Prova att bryta oförklarliga stormar på eftermiddagen med lätt klassisk musik. Ofta gör det här enkla knepet underverk.', body_vi = 'Hãy thử dỗ những cơn quấy khóc không rõ lý do vào chiều tối bằng nhạc cổ điển nhẹ nhàng. Thường thì mẹo đơn giản này tạo nên điều kỳ diệu.', body_zh = '傍晚无缘无故的哭闹风暴，试试用轻柔的古典音乐平息。这个简单的小窍门常常有奇效。' WHERE id = 'dc953aca-0624-4e7e-a96b-11f2b35b9a14' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
