UPDATE public.mommy_day_notifications SET title_es = 'Caprichos al máximo ☁️', title_fr = 'Les caprices au maximum ☁️', title_hi = 'चिड़चिड़ापन चरम पर ☁️', title_id = 'Rewel di puncaknya ☁️', title_ja = 'ご機嫌ななめがピーク ☁️', title_ko = '칭얼거림 최고조 ☁️', title_nl = 'Gezeur op zijn hoogtepunt ☁️', title_pl = 'Marudzenie u szczytu ☁️', title_pt = 'Birras no auge ☁️', title_sv = 'Gnället är på topp ☁️', title_vi = 'Quấy khóc đỉnh điểm ☁️', title_zh = '闹脾气到了顶点 ☁️' WHERE id = 'd9ba76c2-3830-4eb2-b0e8-55a4c6a2f75e' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Nana de buenas noches 🎶', body_es = 'Ningún sonido calma tanto como la voz de mamá. Esta noche, simplemente abrázale contra tu pecho y cántale bajito.', title_fr = 'Berceuse du soir 🎶', body_fr = 'Aucun son n''apaise autant que la voix de maman. Ce soir, serrez-le simplement contre vous et chantez doucement.', title_hi = 'रात की लोरी 🎶', body_hi = 'कोई भी आवाज़ माँ की आवाज़ जितना सुकून नहीं देती। आज शाम बस उसे सीने से लगाइए और धीरे से गाइए।', title_id = 'Nina bobo malam 🎶', body_id = 'Tidak ada suara yang semenenangkan suara ibu. Malam ini, cukup dekap ia di dada dan bernyanyilah pelan.', title_ja = '夜の子守唄 🎶', body_ja = 'ママの声ほど心落ち着く音はありません。今夜はただ胸に抱きよせて、そっと歌ってあげましょう。', title_ko = '밤의 자장가 🎶', body_ko = '엄마 목소리만큼 마음을 달래 주는 소리는 없어요. 오늘 저녁은 아기를 가슴에 꼭 안고 나지막이 노래해 주세요.', title_nl = 'Een slaapliedje voor de nacht 🎶', body_nl = 'Geen geluid is zo rustgevend als mama''s stem. Houd je kleintje vanavond gewoon tegen je borst en zing zachtjes.', title_pl = 'Kołysanka na noc 🎶', body_pl = 'Żaden dźwięk nie koi tak jak głos mamy. Dziś wieczorem po prostu przytul go do piersi i cichutko mu zaśpiewaj.', title_pt = 'Canção de embalar da noite 🎶', body_pt = 'Nenhum som acalma tanto como a voz da mãe. Esta noite, aconchegue-o ao peito e cante baixinho.', title_sv = 'Vaggvisa för natten 🎶', body_sv = 'Inget ljud lugnar så som mammas röst. I kväll, håll bara barnet tätt intill bröstet och sjung tyst.', title_vi = 'Lời ru ban đêm 🎶', body_vi = 'Không âm thanh nào xoa dịu bằng giọng mẹ. Tối nay chỉ cần ôm bé vào lòng và khẽ hát cho bé nghe.', title_zh = '晚安摇篮曲 🎶', body_zh = '没有什么声音比妈妈的声音更能安抚宝宝。今晚就把宝宝抱在怀里，轻轻唱给宝宝听吧。' WHERE id = 'ed11b132-51fc-4e86-99e0-021b6675020e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisión del desarrollo 🤖', title_fr = 'Bilan de développement 🤖', title_hi = 'विकास की जाँच 🤖', title_id = 'Cek perkembangan 🤖', title_ja = '発達チェック 🤖', title_ko = '발달 체크 🤖', title_nl = 'Ontwikkelingscheck 🤖', title_pl = 'Kontrola rozwoju 🤖', title_pt = 'Verificação do desenvolvimento 🤖', title_sv = 'Utvecklingskoll 🤖', title_vi = 'Kiểm tra sự phát triển 🤖', title_zh = '发育检查 🤖' WHERE id = '07f52bf7-1174-455b-9c35-8391687a69fe' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de juego independiente 🧸', title_fr = 'L''heure du jeu en solo 🧸', title_hi = 'अकेले खेलने का समय 🧸', title_id = 'Waktu bermain mandiri 🧸', title_ja = 'ひとり遊びの時間 🧸', title_ko = '혼자 노는 시간 🧸', title_nl = 'Tijd voor zelfstandig spelen 🧸', title_pl = 'Czas na samodzielną zabawę 🧸', title_pt = 'Hora de brincar sozinho 🧸', title_sv = 'Stund för egen lek 🧸', title_vi = 'Giờ chơi một mình 🧸', title_zh = '独立玩耍时间 🧸' WHERE id = '9d72a4f6-eac7-46c3-b9e9-ae6e482ce533' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Prueba a calmar con música clásica suave esas tormentas sin motivo que estallan al caer la tarde. Muchas veces este truco tan sencillo hace milagros.', body_fr = 'Essayez de calmer les tempêtes inexpliquées de fin de journée avec une musique classique douce. Souvent, cette astuce toute simple fait des miracles.', body_hi = 'शाम को अचानक उठने वाले बेवजह तूफ़ानों को हल्के क्लासिकल संगीत से शांत करके देखिए। अक्सर यह आसान तरकीब कमाल कर देती है।', body_id = 'Coba redakan badai tanpa sebab menjelang sore dengan musik klasik yang lembut. Sering kali trik sederhana ini membawa keajaiban.', body_ja = '夕方に突然始まる理由のわからない嵐には、静かなクラシック音楽を試してみましょう。このシンプルな方法が、たいてい奇跡を起こします。', body_ko = '늦은 오후에 몰아치는 이유 없는 울음을 잔잔한 클래식 음악으로 달래 보세요. 이 간단한 방법이 기적을 만들 때가 많아요.', body_nl = 'Probeer de onverklaarbare stormen aan het eind van de middag te stoppen met zachte klassieke muziek. Vaak doet dit simpele trucje wonderen.', body_pl = 'Wieczorne burze bez powodu spróbuj uciszyć spokojną muzyką klasyczną. Często ten prosty trik czyni cuda.', body_pt = 'Experimente acalmar com música clássica suave as tempestades sem motivo que rebentam ao fim da tarde. Muitas vezes, este truque simples faz milagres.', body_sv = 'Prova att bryta oförklarliga stormar på eftermiddagen med lätt klassisk musik. Ofta gör det här enkla knepet underverk.', body_vi = 'Hãy thử dỗ những cơn quấy khóc không rõ lý do vào chiều tối bằng nhạc cổ điển nhẹ nhàng. Thường thì mẹo đơn giản này tạo nên điều kỳ diệu.', body_zh = '傍晚无缘无故的哭闹风暴，试试用轻柔的古典音乐平息。这个简单的小窍门常常有奇效。' WHERE id = 'adb7bf26-343c-4ba5-8233-149cdef6b1f2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Se quita los zapatos 👟', body_es = '¿Vestirle se ha convertido en una lucha libre? Se quita él solo los calcetines y los zapatos. ¡Admira su motricidad!', title_fr = 'Il enlève ses chaussures tout seul 👟', body_fr = 'L''habillage s''est transformé en match de lutte ? Il retire lui-même ses chaussettes et ses chaussures. Admirez sa motricité !', title_hi = 'अपने जूते खुद उतारता है 👟', body_hi = 'कपड़े पहनाना अब कुश्ती बन गया है? वह अपने मोज़े और जूते खुद खींचकर उतार देता है। उसकी मोटर स्किल्स पर हैरान रह जाइए!', title_id = 'Ia melepas sepatunya sendiri 👟', body_id = 'Memakaikan baju kini seperti pertandingan gulat? Ia menarik lepas kaus kaki dan sepatunya sendiri. Kagumi keterampilan motoriknya!', title_ja = '自分で靴を脱ぐ 👟', body_ja = 'お着替えがレスリングの試合に？靴下や靴を自分で引っぱって脱いでいます。運動能力の成長に感心しましょう！', title_ko = '스스로 신발을 벗어요 👟', body_ko = '옷 입히기가 레슬링 경기가 됐나요? 양말과 신발을 스스로 잡아당겨 벗어요. 운동 능력에 감탄해 보세요!', title_nl = 'Hij trekt zijn schoenen uit 👟', body_nl = 'Is aankleden een soort worstelwedstrijd geworden? Hij trekt zelf zijn sokken en schoenen uit. Bewonder zijn motorische vaardigheid!', title_pl = 'Sam zdejmuje buciki 👟', body_pl = 'Ubieranie zamieniło się w zapasy? Sam ściąga skarpetki i buciki. Podziwiaj jego motorykę!', title_pt = 'Tira os próprios sapatos 👟', body_pt = 'Vesti-lo já se tornou uma luta livre? Ele próprio puxa e tira as meias e os sapatos. Admire a motricidade dele!', title_sv = 'Tar av sig skorna själv 👟', body_sv = 'Har påklädningen blivit en sorts brottning? Barnet drar själv av sig strumporna och skorna. Beundra motoriken!', title_vi = 'Bé tự cởi giày 👟', body_vi = 'Mặc đồ cho bé đã thành một trận đấu vật? Bé tự kéo tất và giày ra. Thật đáng ngưỡng mộ kỹ năng vận động của bé!', title_zh = '自己脱鞋 👟', body_zh = '穿衣服变成了摔跤比赛？宝宝已经会自己把袜子和鞋子拽下来了。为宝宝的动作能力赞叹吧！' WHERE id = 'c22aaf03-7bb2-467b-9c9d-ca82637af893' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dilema de qué cocinar 🍲', title_fr = 'Le casse-tête du « qu''est-ce que je cuisine ? » 🍲', title_hi = 'क्या पकाऊँ, यही चिंता 🍲', title_id = 'Bingung mau masak apa 🍲', title_ja = '何をつくろう問題 🍲', title_ko = '뭐 해 먹지 고민 🍲', title_nl = 'Wat moet ik koken? 🍲', title_pl = 'Co ugotować? 🍲', title_pt = 'O dilema do que cozinhar 🍲', title_sv = 'Vad ska jag laga? 🍲', title_vi = 'Nỗi lo "nấu gì đây" 🍲', title_zh = '“做什么吃”的烦恼 🍲' WHERE id = 'b60defb6-6a44-41ab-8087-7dec23cd3f5c' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mamá sana, bebé sano 🥑', body_es = 'Tus reservas de hierro y calcio se han agotado. Prepara con Recetas saludables una ensalada rápida que te mantenga en pie.', title_fr = 'Maman en forme, bébé en forme 🥑', body_fr = 'Vos réserves de fer et de calcium sont épuisées. Préparez avec les Recettes saines une salade rapide qui vous tiendra debout.', title_hi = 'सेहतमंद माँ, सेहतमंद बच्चा 🥑', body_hi = 'आपके शरीर में आयरन और कैल्शियम का भंडार खत्म हो गया है। सेहतमंद रेसिपी से जल्दी बनने वाला और आपको ताकत देने वाला सलाद बनाइए।', title_id = 'Ibu sehat, bayi sehat 🥑', body_id = 'Cadangan zat besi dan kalsium Anda terkuras. Buat salad dari Resep Sehat yang cepat dibuat dan membuat Anda tetap bertenaga.', title_ja = '元気なママ、元気な赤ちゃん 🥑', body_ja = '鉄分とカルシウムの蓄えが減っています。「ヘルシーレシピ」から、手早くできて元気を保てるサラダをつくりましょう。', title_ko = '건강한 엄마, 건강한 아기 🥑', body_ko = '철분과 칼슘이 바닥났어요. 건강한 레시피에서 빨리 만들 수 있고 든든하게 버티게 해 줄 샐러드를 만들어 보세요.', title_nl = 'Gezonde mama, gezonde baby 🥑', body_nl = 'Je ijzer- en calciumvoorraad is op. Maak uit Gezonde recepten een snelle salade die je op de been houdt.', title_pl = 'Zdrowa mama, zdrowy maluszek 🥑', body_pl = 'Twoje zapasy żelaza i wapnia się wyczerpały. Przygotuj ze Zdrowych przepisów szybką sałatkę, która postawi cię na nogi.', title_pt = 'Mãe saudável, bebé saudável 🥑', body_pt = 'As suas reservas de ferro e cálcio esgotaram-se. Prepare nas Receitas Saudáveis uma salada rápida que a mantenha de pé.', title_sv = 'Frisk mamma, friskt barn 🥑', body_sv = 'Dina järn- och kalciumförråd har tömts. Gör en sallad från Hälsosamma recept som både går snabbt att laga och håller dig på benen.', title_vi = 'Mẹ khỏe, bé khỏe 🥑', body_vi = 'Dự trữ sắt và canxi của mẹ đã cạn. Hãy làm một món salad làm nhanh mà giúp mẹ khỏe khoắn từ Công thức lành mạnh.', title_zh = '妈妈健康，宝宝健康 🥑', body_zh = '你体内的铁和钙储备快耗尽了。从健康食谱里做一份快手又能让你撑住的沙拉吧。' WHERE id = '17b19954-1449-474d-a0b9-d199021947cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de noche de papá 👨‍🍼', body_es = 'No cargues tú sola con todos los despertares nocturnos. Despierta también a tu pareja: ser un equipo es repartir la responsabilidad a partes iguales.', title_fr = 'Le service de nuit de papa 👨‍🍼', body_fr = 'Ne gérez pas les réveils nocturnes toute seule. Réveillez aussi votre conjoint, être une équipe, c''est partager la responsabilité à parts égales.', title_hi = 'पापा की रात की ड्यूटी 👨‍🍼', body_hi = 'रात में जागने का बोझ अकेले मत उठाइए। अपने साथी को भी जगाइए, टीम होने का मतलब है ज़िम्मेदारी बराबर बाँटना।', title_id = 'Giliran malam ayah 👨‍🍼', body_id = 'Jangan tanggung sendiri saat ia terbangun di malam hari. Bangunkan juga pasangan Anda, menjadi tim berarti berbagi tanggung jawab secara adil.', title_ja = 'パパの夜の当番 👨‍🍼', body_ja = '夜中に起きるのを、ひとりで抱えこまないで。パートナーも起こしましょう。チームとは責任を平等に分け合うことです。', title_ko = '아빠의 밤 당번 👨‍🍼', body_ko = '밤에 깨는 일을 혼자 다 감당하지 마세요. 배우자도 깨우세요, 한 팀이 된다는 건 책임을 똑같이 나누는 거예요.', title_nl = 'Papa''s avonddienst 👨‍🍼', body_nl = 'Draag het ''s nachts opstaan niet helemaal alleen. Maak je partner ook wakker, een team zijn betekent de verantwoordelijkheid eerlijk delen.', title_pl = 'Nocna zmiana taty 👨‍🍼', body_pl = 'Nie dźwigaj nocnych pobudek zupełnie sama. Obudź też partnera, bycie drużyną to równy podział odpowiedzialności.', title_pt = 'O turno da noite do pai 👨‍🍼', body_pt = 'Não aguente sozinha todos os despertares noturnos. Acorde também o seu companheiro: ser uma equipa é dividir a responsabilidade por igual.', title_sv = 'Pappas nattskift 👨‍🍼', body_sv = 'Ta inte nattuppvaknandena helt ensam. Väck din partner också, att vara ett lag är att dela ansvaret lika.', title_vi = 'Ca đêm của bố 👨‍🍼', body_vi = 'Đừng một mình gánh hết những lần thức dậy ban đêm. Hãy gọi cả bố dậy, là một đội nghĩa là chia đều trách nhiệm.', title_zh = '爸爸的夜班 👨‍🍼', body_zh = '夜醒别全都自己扛。也叫醒你的伴侣，团队就是平分责任。' WHERE id = 'ab2f1bd1-caf0-41b5-b8ae-89ec60663539' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baja las luces 🌙', title_fr = 'Baissez les lumières 🌙', title_hi = 'लाइटें धीमी कीजिए 🌙', title_id = 'Redupkan lampu 🌙', title_ja = '明かりを落として 🌙', title_ko = '조명을 낮춰요 🌙', title_nl = 'Doe de lichten zachter 🌙', title_pl = 'Przyciemnij światła 🌙', title_pt = 'Baixe as luzes 🌙', title_sv = 'Dämpa ljuset 🌙', title_vi = 'Giảm ánh sáng 🌙', title_zh = '调暗灯光 🌙' WHERE id = '24b47242-9a10-48f7-a928-0a19449b984a' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hace falta desahogarse 💬', title_fr = 'Besoin de vous confier 💬', title_hi = 'दिल की बात करना ज़रूरी है 💬', title_id = 'Butuh teman bercerita 💬', title_ja = '話すことが必要なとき 💬', title_ko = '마음을 나눌 시간 💬', title_nl = 'Even je hart luchten 💬', title_pl = 'Czas się wygadać 💬', title_pt = 'Precisa de desabafar 💬', title_sv = 'Ibland behöver man prata av sig 💬', title_vi = 'Cần được tâm sự 💬', title_zh = '需要倾诉一下 💬' WHERE id = '1ba81e06-af3c-43ed-b2c1-9d0d1b231a26' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hoy en Cuentos inteligentes 🪄', body_es = 'Crea en Cuentos inteligentes la historia de unos animales valientes y adorables y convierte la habitación en un lugar mágico.', title_fr = 'Aujourd''hui dans les Contes intelligents 🪄', body_fr = 'Dans les Contes intelligents, créez l''histoire d''animaux courageux et adorables et transformez la chambre en un lieu magique.', title_hi = 'आज स्मार्ट कहानियों में 🪄', body_hi = 'स्मार्ट कहानियों में बहादुर और प्यारे जानवरों की कहानी बनाइए और कमरे को एक जादुई जगह में बदल दीजिए।', title_id = 'Hari ini di Dongeng Pintar 🪄', body_id = 'Di Dongeng Pintar, buat kisah hewan-hewan yang berani dan menggemaskan, dan ubah kamar menjadi tempat yang ajaib.', title_ja = '今日の「スマートおはなし」🪄', body_ja = '「スマートおはなし」で、勇敢でかわいい動物たちのお話をつくって、部屋を魔法の場所に変えましょう。', title_ko = '오늘의 스마트 동화 🪄', body_ko = '스마트 동화에서 용감하고 사랑스러운 동물 이야기를 만들어 방을 마법의 공간으로 바꿔 보세요.', title_nl = 'Vandaag in Slimme sprookjes 🪄', body_nl = 'Maak in Slimme sprookjes het verhaal van dappere, lieve dieren en verander de kamer in een magische plek.', title_pl = 'Dziś w Mądrych bajkach 🪄', body_pl = 'Stwórz w Mądrych bajkach historię o odważnych i uroczych zwierzątkach i zamień pokój w magiczne miejsce.', title_pt = 'Hoje nas Histórias Inteligentes 🪄', body_pt = 'Crie nas Histórias Inteligentes histórias de animais corajosos e adoráveis e transforme o quarto num lugar mágico.', title_sv = 'I dag i Smarta sagor 🪄', body_sv = 'Skapa sagan om modiga och gulliga djur i Smarta sagor och förvandla rummet till en magisk plats.', title_vi = 'Hôm nay trong Truyện cổ tích thông minh 🪄', body_vi = 'Hãy tạo câu chuyện về những con vật dũng cảm, đáng yêu trong Truyện cổ tích thông minh và biến căn phòng thành một nơi kỳ diệu.', title_zh = '今天的智能故事 🪄', body_zh = '在智能故事里创作勇敢又可爱的动物的故事，把房间变成一个神奇的地方吧。' WHERE id = '5d958416-87e8-44f2-8b6e-cde98e63822d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
