UPDATE public.mommy_day_notifications SET title_es = 'Dudas pediátricas 🤖', title_fr = 'Des doutes pédiatriques 🤖', title_hi = 'बच्चे की सेहत को लेकर सवाल 🤖', title_id = 'Keraguan seputar kesehatan anak 🤖', title_ja = '育児の疑問 🤖', title_ko = '소아과 궁금증 🤖', title_nl = 'Twijfels over je kindje 🤖', title_pl = 'Pediatryczne wątpliwości 🤖', title_pt = 'Dúvidas pediátricas 🤖', title_sv = 'Barnmedicinska funderingar 🤖', title_vi = 'Băn khoăn về nhi khoa 🤖', title_zh = '儿科疑虑 🤖' WHERE id = '89373578-8a41-4cd9-bcef-3a5786b1f576' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un abrazo de «te quiero» 🫂', body_es = '¿De repente viene, te abraza el cuello o te acaricia la cara? Ya muestra su amor físicamente. Disfruta de este momento.', title_fr = 'Le câlin « Je t''aime » 🫂', body_fr = 'Il vient soudain se jeter à votre cou ou vous caresser le visage ? Il montre désormais son amour physiquement. Savourez ce moment.', title_hi = '''आई लव यू'' वाली झप्पी 🫂', body_hi = 'अचानक आकर आपके गले से लिपट जाता है या आपका चेहरा सहलाता है? वह अब अपना प्यार शारीरिक रूप से जताता है। इस पल का आनंद लीजिए।', title_id = 'Pelukan "Aku sayang kamu" 🫂', body_id = 'Tiba-tiba ia datang memeluk leher Anda atau mengelus wajah Anda? Kini ia menunjukkan cintanya secara fisik. Nikmati momen ini.', title_ja = '「大好き」のハグ 🫂', body_ja = '急にやってきて首に抱きついたり、顔をなでたりしますか？もう体で愛情を伝えているのです。この瞬間をじっくり味わいましょう。', title_ko = '''사랑해'' 포옹 🫂', body_ko = '갑자기 와서 목을 끌어안거나 얼굴을 쓰다듬나요? 이제 몸으로 사랑을 표현해요. 이 순간을 마음껏 누리세요.', title_nl = 'Een ik-hou-van-je-knuffel 🫂', body_nl = 'Slaat je baby ineens zijn armpjes om je nek of aait hij je gezicht? Hij laat zijn liefde nu lichamelijk zien. Geniet van dit moment.', title_pl = 'Przytulas „kocham cię” 🫂', body_pl = 'Nagle przychodzi i obejmuje cię za szyję albo głaszcze po twarzy? Okazuje już miłość fizycznie. Delektuj się tą chwilą.', title_pt = 'O abraço "gosto de ti" 🫂', body_pt = 'De repente, vem abraçar-lhe o pescoço ou acariciar-lhe o rosto? Já mostra o seu amor de forma física. Saboreie este momento.', title_sv = 'Jag älskar dig-kramen 🫂', body_sv = 'Kommer barnet plötsligt och kramar dig om halsen eller smeker ditt ansikte? Det visar redan sin kärlek fysiskt. Njut av stunden.', title_vi = 'Cái ôm "Con yêu mẹ" 🫂', body_vi = 'Bé bất chợt đến ôm cổ hay vuốt má mẹ? Bé đã biết thể hiện tình yêu bằng hành động. Hãy tận hưởng khoảnh khắc này.', title_zh = '“我爱你”的拥抱 🫂', body_zh = '宝宝突然跑过来搂住你的脖子，或者摸摸你的脸？宝宝已经会用肢体表达爱了。好好享受这一刻吧。' WHERE id = '276fc8e9-ee3f-4392-a41a-de859475f6f7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El consuelo de papá 🫂', body_es = 'En los despertares nocturnos, que una vez te levantes tú y otra tu pareja. Repartid la carga a la mitad, como un equipo.', title_fr = 'Le réconfort de papa 🫂', body_fr = 'Pour les réveils nocturnes, levez-vous une fois chacun, vous et votre conjoint. Partagez la charge en deux, en équipe.', title_hi = 'पापा से मिलने वाला सुकून 🫂', body_hi = 'रात में जागने पर एक बार आप उठिए, एक बार आपके साथी। टीम बनकर बोझ को बराबर आधा बाँट लीजिए।', title_id = 'Hiburan dari ayah 🫂', body_id = 'Saat ia terbangun di malam hari, gantian bangun dengan pasangan. Bagi bebannya tepat setengah sebagai satu tim.', title_ja = 'パパのなぐさめ 🫂', body_ja = '夜中に起きたら、1回はあなた、1回はパートナーと交代で。チームとして、負担をきっちり半分に分けましょう。', title_ko = '아빠의 위로 🫂', body_ko = '밤에 깰 때는 한 번은 엄마가, 한 번은 배우자가 일어나세요. 한 팀으로서 짐을 정확히 절반씩 나누세요.', title_nl = 'Troost van papa 🫂', body_nl = 'Ga ''s nachts om de beurt eruit: de ene keer jij, de andere keer je partner. Verdeel de last als team helemaal eerlijk.', title_pl = 'Pocieszenie od taty 🫂', body_pl = 'Przy nocnych pobudkach wstawajcie na zmianę: raz ty, raz partner. Jako drużyna podzielcie ciężar dokładnie na pół.', title_pt = 'O conforto do pai 🫂', body_pt = 'Nos despertares noturnos, levanta-se uma vez a mãe e outra vez o pai. Dividam o peso ao meio, como uma equipa.', title_sv = 'Tröst från pappa 🫂', body_sv = 'Turas om att gå upp vid nattuppvaknandena, en gång du och en gång din partner. Dela bördan helt lika, som ett lag.', title_vi = 'Sự an ủi từ bố 🫂', body_vi = 'Khi bé thức đêm, lần này mẹ dậy, lần sau đến lượt bố. Hãy chia đôi gánh nặng như một đội thực thụ.', title_zh = '来自爸爸的安慰 🫂', body_zh = '夜醒时，你和伴侣轮流起来。作为一个团队，把担子完全平分吧。' WHERE id = '6d6ea5dd-3811-42ae-a92c-4f0473fafb88' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sospechas de alergia 🤖', body_es = '¿Le has dado un alimento nuevo y le han salido rojeces en las mejillas? Antes de alarmarte, consulta a Anacan AI los primeros pasos.', title_fr = 'Soupçon d''allergie 🤖', body_fr = 'Vous lui avez donné un nouvel aliment et vous voyez des rougeurs sur ses joues ? Avant de paniquer, découvrez les premières étapes auprès d''Anacan AI.', title_hi = 'एलर्जी का शक 🤖', body_hi = 'नया खाना दिया और गालों पर लाली दिखी? घबराने से पहले Anacan AI से पहले कदम जानिए।', title_id = 'Curiga alergi 🤖', body_id = 'Memberi makanan baru lalu melihat kemerahan di pipinya? Sebelum panik, pelajari langkah pertama yang perlu dilakukan dari Anacan AI.', title_ja = 'アレルギーかも？🤖', body_ja = '新しい食べ物をあげたら、ほっぺが赤くなった？あわてる前に、Anacan AIで最初にすべきことを確認しましょう。', title_ko = '알레르기가 의심될 때 🤖', body_ko = '새 음식을 줬는데 볼이 빨개졌나요? 당황하기 전에 Anacan AI에게서 첫 대처 방법을 알아보세요.', title_nl = 'Vermoeden van allergie 🤖', body_nl = 'Gaf je iets nieuws te eten en zie je rode wangetjes? Lees bij Anacan AI wat de eerste stappen zijn voordat je in paniek raakt.', title_pl = 'Podejrzenie alergii 🤖', body_pl = 'Podałaś nowy pokarm i widzisz zaczerwienienie na policzkach? Zanim wpadniesz w panikę, dowiedz się od Anacan AI, jakie są pierwsze kroki.', title_pt = 'Suspeitas de alergia 🤖', body_pt = 'Deu-lhe um alimento novo e viu vermelhidão nas bochechas? Antes de entrar em pânico, conheça com o Anacan AI os primeiros passos.', title_sv = 'Misstänkt allergi 🤖', body_sv = 'Har du gett barnet en ny maträtt och sett rodnad på kinderna? Innan du får panik, ta reda på de första stegen hos Anacan AI.', title_vi = 'Băn khoăn về dị ứng 🤖', body_vi = 'Mẹ cho bé ăn món mới và thấy má bé ửng đỏ? Trước khi hoảng hốt, hãy hỏi Anacan AI những bước cần làm đầu tiên.', title_zh = '怀疑过敏 🤖', body_zh = '给宝宝吃了新食物，脸颊发红了？先别慌，向Anacan AI了解一下第一步该怎么做吧。' WHERE id = '87b2db95-d589-400c-8cce-c78da82f0fee' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
