UPDATE public.mommy_day_notifications SET title_es = 'Hora del masaje 💆‍♂️', title_fr = 'L''heure du massage 💆‍♂️', title_hi = 'मालिश का समय 💆‍♂️', title_id = 'Waktu pijat 💆‍♂️', title_ja = 'マッサージタイム 💆‍♂️', title_ko = '마사지 시간 💆‍♂️', title_nl = 'Tijd voor een massage 💆‍♂️', title_pl = 'Czas na masaż 💆‍♂️', title_pt = 'Hora da massagem 💆‍♂️', title_sv = 'Massagedags 💆‍♂️', title_vi = 'Giờ mát-xa 💆‍♂️', title_zh = '按摩时间 💆‍♂️' WHERE id = '6ca7a3a7-3202-4bdf-87de-b43d04388374' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Control de los ruidos 🤫', body_es = 'La primera media hora después de dormirse es el momento más delicado. Comprueba el ambiente con el Medidor de sonido y evita los ruidos repentinos.', title_fr = 'Maîtriser les bruits 🤫', body_fr = 'La première demi-heure après l''endormissement est le moment le plus sensible. Vérifiez l''ambiance avec le Sonomètre et méfiez-vous des bruits soudains.', title_hi = 'आवाज़ों पर काबू 🤫', body_hi = 'सोने के बाद का पहला आधा घंटा सबसे नाज़ुक समय है। साउंड मीटर से माहौल जाँचिए और अचानक शोर से बचिए।', title_id = 'Mengatur suara 🤫', body_id = 'Setengah jam pertama setelah tertidur adalah waktu paling sensitif. Cek suasana dengan Pengukur Suara dan hindari suara bising mendadak.', title_ja = '音のコントロール 🤫', body_ja = '寝ついてから最初の30分は、いちばん眠りが浅い時間です。「サウンドメーター」で環境をチェックして、急な物音に気をつけましょう。', title_ko = '소리 관리 🤫', body_ko = '잠든 직후 처음 30분이 가장 예민한 시간이에요. 소음 측정기로 환경을 확인하고 갑작스러운 소음을 조심하세요.', title_nl = 'Geluiden onder controle 🤫', body_nl = 'Het eerste halfuur na het inslapen is het gevoeligst. Controleer de omgeving met de Geluidsmeter en pas op voor plotseling lawaai.', title_pl = 'Kontrola dźwięków 🤫', body_pl = 'Pierwsze pół godziny po zaśnięciu to najwrażliwszy czas. Sprawdź otoczenie Miernikiem dźwięku i uważaj na nagły hałas.', title_pt = 'Controlo dos sons 🤫', body_pt = 'A primeira meia hora depois de adormecer é a altura mais sensível. Verifique o ambiente com o Medidor de Som e cuidado com barulhos súbitos.', title_sv = 'Ljudkoll 🤫', body_sv = 'Den första halvtimmen efter att barnet har somnat är den känsligaste. Kolla miljön med Ljudmätaren och akta dig för plötsligt oväsen.', title_vi = 'Kiểm soát âm thanh 🤫', body_vi = 'Nửa tiếng đầu sau khi bé ngủ là lúc nhạy cảm nhất. Hãy kiểm tra môi trường bằng Đo âm thanh và cẩn thận với tiếng ồn đột ngột.', title_zh = '控制声音 🤫', body_zh = '入睡后的头半小时是最敏感的时候。用噪音测量检查环境，小心突然的噪音。' WHERE id = '0c27441c-12ef-47a7-9dc7-2b5ead6dd4a7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pediatra exprés 🤖', title_fr = 'Le pédiatre express 🤖', title_hi = 'झटपट बाल रोग सलाह 🤖', title_id = 'Dokter anak kilat 🤖', title_ja = 'すばやく小児科の知識 🤖', title_ko = '빠른 소아과 상담 🤖', title_nl = 'Een snelle kinderarts 🤖', title_pl = 'Szybki pediatra 🤖', title_pt = 'Pediatra rápido 🤖', title_sv = 'Snabb barnläkare 🤖', title_vi = 'Bác sĩ nhi khoa nhanh chóng 🤖', title_zh = '快速儿科咨询 🤖' WHERE id = 'cee8912e-bf87-4d52-b0d0-309e7583f3e5' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Valórate 👏', body_es = 'No mires el desorden de la habitación, sino lo feliz que está hoy tu peque. Eres una madre estupenda, mucho más de lo que podría enseñar cualquier libro.', title_fr = 'Reconnaissez votre mérite 👏', body_fr = 'Ne regardez pas le désordre de la pièce, mais à quel point il est heureux aujourd''hui. Vous êtes une maman formidable, bien plus qu''aucun livre ne pourrait l''enseigner.', title_hi = 'खुद की तारीफ़ कीजिए 👏', body_hi = 'कमरे के बिखराव को नहीं, यह देखिए कि आज वह कितना खुश है। आप ऐसी बेहतरीन माँ हैं जैसा कोई किताब नहीं सिखा सकती।', title_id = 'Hargai diri Anda 👏', body_id = 'Jangan lihat kamar yang berantakan, lihatlah betapa bahagianya ia hari ini. Anda ibu yang hebat, lebih dari yang bisa diajarkan buku mana pun.', title_ja = '自分をほめてあげて 👏', body_ja = '部屋の散らかりではなく、今日の赤ちゃんの幸せそうな姿を見てください。あなたはどんな本も教えられないほど、すばらしいママです。', title_ko = '나를 칭찬해 주세요 👏', body_ko = '어질러진 방이 아니라 오늘 아기가 얼마나 행복했는지를 보세요. 당신은 어떤 책도 가르쳐 줄 수 없을 만큼 훌륭한 엄마예요.', title_nl = 'Waardeer jezelf 👏', body_nl = 'Kijk niet naar de rommel in de kamer, maar naar hoe blij je kindje vandaag was. Je bent een betere moeder dan welk boek ook je kan leren.', title_pl = 'Doceń siebie 👏', body_pl = 'Nie patrz na bałagan w pokoju, tylko na to, jak szczęśliwy jest dziś maluszek. Jesteś wspaniałą mamą, takiej żadna książka nie nauczy.', title_pt = 'Valorize-se 👏', body_pt = 'Não olhe para a desarrumação do quarto, olhe para como ele hoje está feliz. É uma mãe tão boa que nenhum livro o conseguiria ensinar.', title_sv = 'Uppskatta dig själv 👏', body_sv = 'Titta inte på stöket i rummet utan på hur glad barnet är i dag. Du är en bättre mamma än någon bok kan lära ut.', title_vi = 'Hãy ghi nhận chính mình 👏', body_vi = 'Đừng nhìn căn phòng bừa bộn, hãy nhìn xem hôm nay bé hạnh phúc thế nào. Mẹ là một người mẹ tuyệt vời hơn bất kỳ cuốn sách nào có thể dạy.', title_zh = '肯定自己 👏', body_zh = '别看房间有多乱，看看宝宝今天有多开心。你是一个任何书都教不出来的好妈妈。' WHERE id = '52450380-67b2-4414-9193-af2b18f7264a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Después de un día difícil, sentaos cara a cara tu pareja y tú y hablad. Apoyaros reparte la carga a la mitad.', body_fr = 'Après une journée difficile, asseyez-vous face à votre conjoint et parlez. Vous soutenir mutuellement allège la charge de moitié.', body_hi = 'मुश्किल दिन के बाद अपने साथी के साथ आमने-सामने बैठकर दिल की बात कीजिए। एक-दूसरे का साथ बोझ आधा कर देता है।', body_id = 'Setelah hari yang berat, duduklah berhadapan dengan pasangan dan saling bercerita. Saling mendukung membuat beban terbagi dua.', body_ja = '大変な1日のあとは、パートナーと向き合って話しましょう。支え合うことで、負担は半分になります。', body_ko = '힘든 하루를 보낸 뒤 배우자와 마주 앉아 이야기를 나눠 보세요. 서로를 응원하면 짐이 절반으로 줄어요.', body_nl = 'Ga na een zware dag tegenover je partner zitten en praat je hart uit. Elkaar steunen halveert de last.', body_pl = 'Po trudnym dniu usiądź z partnerem twarzą w twarz i porozmawiajcie. Wzajemne wsparcie dzieli ciężar na pół.', body_pt = 'Depois de um dia difícil, sente-se frente a frente com o seu companheiro e conversem. Apoiarem-se um ao outro divide o peso ao meio.', body_sv = 'Efter en tuff dag, sätt er mittemot varandra och prata ut med din partner. Att stötta varandra halverar bördan.', body_vi = 'Sau một ngày vất vả, hãy ngồi đối diện và tâm sự cùng bố. Cùng nâng đỡ nhau sẽ giúp gánh nặng vơi đi một nửa.', body_zh = '辛苦一天后，和伴侣面对面坐下聊聊。互相支持，担子就轻了一半。' WHERE id = 'fda065c2-2893-4c1e-858b-19c095a29529' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
