UPDATE public.mommy_day_notifications SET title_es = '¿Parque o casa? ⛅', title_fr = 'Parc ou maison ? ⛅', title_hi = 'पार्क या घर? ⛅', title_id = 'Taman atau rumah? ⛅', title_ja = '公園？それともおうち？⛅', title_ko = '공원일까요, 집일까요? ⛅', title_nl = 'Park of thuis? ⛅', title_pl = 'Park czy dom? ⛅', title_pt = 'Parque ou casa? ⛅', title_sv = 'Park eller hemma? ⛅', title_vi = 'Công viên hay ở nhà? ⛅', title_zh = '去公园还是待在家？⛅' WHERE id = 'fa9c7680-afc6-4095-9ec3-d56ad432d989' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Control de los ruidos 🤫', title_fr = 'Maîtriser les bruits 🤫', title_hi = 'आवाज़ों पर काबू 🤫', title_id = 'Mengatur suara 🤫', title_ja = '音のコントロール 🤫', title_ko = '소리 관리 🤫', title_nl = 'Geluiden onder controle 🤫', title_pl = 'Kontrola dźwięków 🤫', title_pt = 'Controlo dos sons 🤫', title_sv = 'Ljudkoll 🤫', title_vi = 'Kiểm soát âm thanh 🤫', title_zh = '控制声音 🤫' WHERE id = '5ae1647c-ec81-4db7-838c-66f57619dd06' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tardes con música 🎶', body_es = 'La forma más fácil de calmar los lloriqueos de la tarde es poner su canción favorita y bailar abrazados.', title_fr = 'Soirées en musique 🎶', body_fr = 'Le moyen le plus simple de calmer les pleurnicheries de fin de journée, c''est de mettre sa chanson préférée et de danser en le serrant contre vous.', title_hi = 'संगीत भरी शामें 🎶', body_hi = 'शाम की चिड़चिड़ाहट दूर करने का सबसे आसान तरीका है उसका पसंदीदा गाना लगाना और उसे गले लगाकर नाचना।', title_id = 'Malam penuh musik 🎶', body_id = 'Cara termudah meredakan rengekan menjelang sore adalah memutar lagu kesukaannya lalu berdansa sambil berpelukan dengannya.', title_ja = '音楽のある夕方 🎶', body_ja = '夕方のぐずぐずをいちばんかんたんに解決する方法は、お気に入りの曲をかけて、抱きしめて一緒に踊ることです。', title_ko = '음악이 있는 저녁 🎶', body_ko = '늦은 오후의 칭얼거림을 달래는 가장 쉬운 방법은 좋아하는 노래를 틀고 꼭 안고 춤추는 거예요.', title_nl = 'Muzikale avonden 🎶', body_nl = 'De makkelijkste manier om het gezeur aan het eind van de middag op te lossen: zet zijn lievelingsliedje op en dans knuffelend met hem.', title_pl = 'Muzyczne wieczory 🎶', body_pl = 'Najprostszy sposób na wieczorne marudzenie to włączyć jego ulubioną piosenkę, przytulić go i razem zatańczyć.', title_pt = 'Noites com música 🎶', body_pt = 'A forma mais fácil de acalmar a rabugice do fim da tarde é pôr uma canção de que ele gosta e dançar abraçados.', title_sv = 'Musikaliska kvällar 🎶', body_sv = 'Det enklaste sättet att lösa gnället på eftermiddagen är att sätta på en låt barnet gillar, krama det och dansa tillsammans.', title_vi = 'Những buổi tối âm nhạc 🎶', body_vi = 'Cách dễ nhất để dỗ những cơn quấy chiều tối là bật bài hát bé thích, ôm bé và cùng nhảy.', title_zh = '音乐之夜 🎶', body_zh = '解决傍晚哭闹最简单的办法，就是放一首宝宝最爱的歌，抱着宝宝一起跳舞。' WHERE id = '2e177a88-e995-4df3-ae19-8a1044979006' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
