UPDATE public.mommy_day_notifications SET title_es = '¿Tienes una pregunta? 🤖', title_fr = 'Une question ? 🤖', title_hi = 'कोई सवाल है? 🤖', title_id = 'Ada pertanyaan? 🤖', title_ja = '質問はありますか？🤖', title_ko = '궁금한 게 있나요? 🤖', title_nl = 'Heb je een vraag? 🤖', title_pl = 'Masz pytanie? 🤖', title_pt = 'Tem uma dúvida? 🤖', title_sv = 'Har du en fråga? 🤖', title_vi = 'Mẹ có câu hỏi? 🤖', title_zh = '有问题吗？🤖' WHERE id = 'ff08789a-eee1-4756-9d40-5ac5e65f75a9' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baja las luces 🌙', body_es = 'Una hora antes de dormir, apaga todas las luces fuertes y las pantallas de casa. La melatonina solo se segrega en un ambiente tranquilo y con poca luz.', title_fr = 'Baissez les lumières 🌙', body_fr = '1 heure avant le coucher, éteignez toutes les lumières vives et les écrans de la maison. La mélatonine n''est sécrétée que dans un environnement calme et peu éclairé.', title_hi = 'लाइटें धीमी कीजिए 🌙', body_hi = 'सोने से 1 घंटा पहले घर की सारी तेज़ लाइटें और स्क्रीन बंद कर दीजिए। मेलाटोनिन शांत और कम रोशनी वाले माहौल में ही बनता है।', title_id = 'Redupkan lampu 🌙', body_id = 'Satu jam sebelum tidur, matikan semua lampu terang dan layar di rumah. Melatonin hanya diproduksi di lingkungan yang tenang dan redup.', title_ja = '明かりを落として 🌙', body_ja = '寝る1時間前には、家の強い明かりや画面をすべて消しましょう。メラトニンは、静かで明かりの少ない環境でこそ分泌されます。', title_ko = '조명을 낮춰요 🌙', body_ko = '잠들기 1시간 전에 집 안의 밝은 조명과 화면을 모두 끄세요. 멜라토닌은 조용하고 어두운 환경에서만 분비돼요.', title_nl = 'Doe de lichten zachter 🌙', body_nl = 'Doe 1 uur voor het slapengaan alle felle lampen en schermen in huis uit. Melatonine wordt alleen in een rustige omgeving met weinig licht aangemaakt.', title_pl = 'Przyciemnij światła 🌙', body_pl = 'Na godzinę przed snem wyłącz w domu wszystkie mocne światła i ekrany. Melatonina wydziela się tylko w spokojnym, słabo oświetlonym otoczeniu.', title_pt = 'Baixe as luzes 🌙', body_pt = '1 hora antes de dormir, apague as luzes desnecessárias e os ecrãs da casa. A melatonina só é produzida num ambiente calmo e com pouca luz.', title_sv = 'Dämpa ljuset 🌙', body_sv = 'Släck alla starka lampor och skärmar hemma 1 timme innan läggdags. Melatonin utsöndras bara i en lugn och svagt upplyst miljö.', title_vi = 'Giảm ánh sáng 🌙', body_vi = '1 tiếng trước giờ ngủ, hãy tắt hết đèn sáng và màn hình trong nhà. Melatonin chỉ được tiết ra trong môi trường yên tĩnh và ít ánh sáng.', title_zh = '调暗灯光 🌙', body_zh = '睡前1小时关掉家里所有的强光和屏幕。褪黑素只有在安静、光线昏暗的环境里才会分泌。' WHERE id = 'ea466226-d28d-4765-94f7-982ef3a85a8e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
