UPDATE public.mommy_day_notifications SET title_es = 'La responsabilidad de papá 👨‍🍼', body_es = 'Ya tienes bastante con el cansancio del día. Esta tarde deja en manos de papá prepararle para dormir y ponerle el pijama, y tú simplemente mira.', title_fr = 'La responsabilité de papa 👨‍🍼', body_fr = 'La fatigue de la journée vous suffit. En fin de journée, confiez à papa la préparation au coucher et la mise en pyjama, et contentez-vous de regarder.', title_hi = 'पापा की ज़िम्मेदारी 👨‍🍼', body_hi = 'दिन की थकान आपके लिए काफ़ी है। शाम को बच्चे को सोने के लिए तैयार करना और पजामा पहनाना पापा को सौंप दीजिए और बस दूर से देखिए।', title_id = 'Tanggung jawab ayah 👨‍🍼', body_id = 'Lelah seharian sudah cukup bagi Anda. Serahkan persiapan tidur dan memakaikan piyama kepada ayah, dan cukup lihat dari jauh.', title_ja = 'パパの役目 👨‍🍼', body_ja = '昼間の疲れだけでもう十分。夕方は寝る準備とパジャマのお着替えをパパにまかせて、あなたは見守るだけにしましょう。', title_ko = '아빠의 책임 👨‍🍼', body_ko = '낮의 피로로 충분해요. 저녁에 아이를 재울 준비를 하고 잠옷을 입히는 일은 아빠에게 맡기고 곁에서 지켜보기만 하세요.', title_nl = 'Papa''s verantwoordelijkheid 👨‍🍼', body_nl = 'De vermoeidheid van overdag is genoeg voor jou. Laat papa ''s avonds je baby klaarmaken voor bed en zijn pyjama aantrekken, en kijk gewoon toe.', title_pl = 'Obowiązki taty 👨‍🍼', body_pl = 'Wystarczy ci dziennego zmęczenia. Pod wieczór powierz tacie przygotowanie maluszka do snu i zakładanie piżamki, a sama tylko patrz z boku.', title_pt = 'A responsabilidade do pai 👨‍🍼', body_pt = 'O cansaço do dia já chega. Ao fim do dia, deixe ao pai a tarefa de preparar o bebé para dormir e vestir-lhe o pijama, e limite-se a assistir.', title_sv = 'Pappas ansvar 👨‍🍼', body_sv = 'Dagens trötthet räcker för dig. Låt pappa ta hand om att göra barnet redo för sömnen och sätta på pyjamasen i kväll, och titta bara på från sidan.', title_vi = 'Trách nhiệm của bố 👨‍🍼', body_vi = 'Mệt mỏi ban ngày đã đủ với mẹ rồi. Chiều tối nay, hãy giao việc chuẩn bị cho bé đi ngủ và thay đồ ngủ cho bố, còn mẹ chỉ cần ngắm từ xa.', title_zh = '爸爸的责任 👨‍🍼', body_zh = '白天的疲惫已经够你受了。今晚把哄睡准备和换睡衣的事交给爸爸，你只在一旁看着就好。' WHERE id = '7aba0d06-67c9-4fba-811b-47eacf1ff2d7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tormenta nocturna 😭', title_fr = 'La tempête de la nuit 😭', title_hi = 'रात का तूफ़ान 😭', title_id = 'Badai di malam hari 😭', title_ja = '夜の嵐 😭', title_ko = '한밤의 폭풍 😭', title_nl = 'Storm in de nacht 😭', title_pl = 'Nocna burza 😭', title_pt = 'A tempestade da noite 😭', title_sv = 'Nattens storm 😭', title_vi = 'Cơn bão ban đêm 😭', title_zh = '夜里的风暴 😭' WHERE id = 'c3b0f127-530e-4b11-9687-7c0bcb24de5f' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El caos de casa 🌪️', body_es = '¿Hay juguetes por toda la habitación? Más importante que la limpieza son 10 minutos de risas con tu peque. Los juguetes seguirán ahí mañana, no te agotes.', title_fr = 'Le chaos de la maison 🌪️', body_fr = 'Des jouets partout dans la pièce ? Ce n''est pas le ménage qui compte, mais les 10 minutes de sourires passées avec lui. Les jouets seront encore là demain, ne vous épuisez pas.', title_hi = 'घर की अफ़रा-तफ़री 🌪️', body_hi = 'कमरे में हर जगह खिलौने हैं? सफ़ाई नहीं, उसके साथ हँसते हुए बिताए 10 मिनट ज़्यादा ज़रूरी हैं। खिलौने कल भी वहीं होंगे, खुद को मत थकाइए।', title_id = 'Rumah yang kacau 🌪️', body_id = 'Mainan di setiap sudut ruangan? Yang lebih penting bukan kebersihan, melainkan 10 menit penuh tawa bersamanya. Mainan itu besok juga masih di sana, jangan memaksakan diri.', title_ja = 'おうちのカオス 🌪️', body_ja = '部屋中おもちゃだらけ？お掃除よりも、赤ちゃんと笑顔で過ごす10分のほうがずっと大切です。おもちゃは明日もそこにあります。無理をしないで。', title_ko = '집 안의 혼돈 🌪️', body_ko = '방 안이 온통 장난감인가요? 청소보다 아기와 함께 웃으며 보내는 10분이 더 소중해요. 장난감은 내일도 그 자리에 있을 테니 무리하지 마세요.', title_nl = 'Chaos in huis 🌪️', body_nl = 'Overal speelgoed in de kamer? Niet de schoonmaak, maar 10 vrolijke minuten samen met je baby zijn belangrijker. Het speelgoed ligt er morgen ook nog, maak jezelf niet moe.', title_pl = 'Domowy chaos 🌪️', body_pl = 'Wszędzie w pokoju zabawki? Ważniejsze od sprzątania jest 10 radosnych minut spędzonych z maluszkiem. Zabawki jutro też tam będą, nie męcz się.', title_pt = 'O caos da casa 🌪️', body_pt = 'Há brinquedos por todo o quarto? Mais importante do que a limpeza são 10 minutos de sorrisos passados com ele. Os brinquedos amanhã continuam lá, não se canse.', title_sv = 'Kaos hemma 🌪️', body_sv = 'Leksaker överallt i rummet? Det är inte städningen som är viktigast, utan 10 glada minuter tillsammans med barnet. Leksakerna ligger kvar i morgon också, slit inte ut dig.', title_vi = 'Nhà cửa hỗn loạn 🌪️', body_vi = 'Đồ chơi khắp phòng? Dọn dẹp không quan trọng bằng 10 phút vui vẻ mẹ dành cho bé. Đồ chơi ngày mai vẫn ở đó, đừng làm mình mệt thêm.', title_zh = '家里一团乱 🌪️', body_zh = '房间里到处是玩具？比起打扫，和宝宝一起欢笑的10分钟更重要。玩具明天还在那儿，别累坏自己。' WHERE id = '39972a4c-ff8f-4f23-abf0-aefe71b44bb9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Acostumbrarse a la oscuridad 🌙', body_es = 'Para que se duerma antes, apaga todas las luces que sobran y las pantallas de la habitación. La melatonina se segrega más rápido solo en un ambiente tranquilo y oscuro.', title_fr = 'S''habituer à l''obscurité 🌙', body_fr = 'Pour l''aider à s''endormir plus vite, éteignez toutes les lumières superflues et les écrans de la pièce. La sécrétion de mélatonine ne s''accélère que dans un environnement calme et sombre.', title_hi = 'अँधेरे की आदत 🌙', body_hi = 'उसे जल्दी सुलाने के लिए कमरे की सारी अतिरिक्त लाइटें और स्क्रीन बंद कीजिए। मेलाटोनिन हार्मोन शांत और अँधेरे माहौल में ही तेज़ी से बनता है।', title_id = 'Terbiasa dengan gelap 🌙', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar di kamar. Hormon melatonin hanya diproduksi lebih cepat di lingkungan yang tenang dan gelap.', title_ja = '暗さに慣れよう 🌙', body_ja = '早く寝つけるように、部屋のよけいな明かりや画面はすべて消しましょう。メラトニンというホルモンは、静かで暗い環境でこそ分泌が進みます。', title_ko = '어둠에 익숙해지기 🌙', body_ko = '빨리 잠들 수 있도록 방의 불필요한 조명과 화면을 모두 끄세요. 멜라토닌 분비는 조용하고 어두운 환경에서만 빨라져요.', title_nl = 'Wennen aan het donker 🌙', body_nl = 'Doe alle extra lampjes en schermen in de kamer uit, zodat je baby sneller in slaap valt. Het hormoon melatonine wordt alleen in een rustige, donkere omgeving sneller aangemaakt.', title_pl = 'Oswajanie z ciemnością 🌙', body_pl = 'Aby szybciej zasnął, wyłącz w pokoju wszystkie dodatkowe światła i ekrany. Wydzielanie melatoniny przyspiesza tylko w spokojnym i ciemnym otoczeniu.', title_pt = 'Habituar-se ao escuro 🌙', body_pt = 'Para o ajudar a adormecer mais depressa, desligue todas as luzes desnecessárias e os ecrãs do quarto. A produção de melatonina só acelera num ambiente calmo e escuro.', title_sv = 'Vänja sig vid mörkret 🌙', body_sv = 'Släck alla onödiga lampor och skärmar i rummet så att barnet somnar fortare. Hormonet melatonin utsöndras snabbare bara i en lugn och mörk miljö.', title_vi = 'Làm quen với bóng tối 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt hết đèn và màn hình không cần thiết trong phòng. Hormone melatonin chỉ được tiết ra nhanh hơn trong môi trường yên tĩnh và tối.', title_zh = '适应黑暗 🌙', body_zh = '为了让宝宝更快入睡，关掉房间里所有多余的灯和屏幕。褪黑素只有在安静、黑暗的环境里才会加速分泌。' WHERE id = '6417fc2a-8680-4b6d-9b78-5b97074e6a4c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Te oigo 🗣️', title_fr = 'Je t''entends 🗣️', title_hi = 'मैं आपको सुन रहा हूँ 🗣️', title_id = 'Aku mendengarmu 🗣️', title_ja = '聞こえてるよ 🗣️', title_ko = '엄마 목소리가 들려요 🗣️', title_nl = 'Ik hoor je 🗣️', title_pl = 'Słyszę cię 🗣️', title_pt = 'Estou a ouvir-te 🗣️', title_sv = 'Jag hör dig 🗣️', title_vi = 'Con nghe thấy mẹ 🗣️', title_zh = '我听到你啦 🗣️' WHERE id = '986722e4-1562-4f18-a164-dd6f65efe855' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Las cuatro paredes te agobian. Ponle en el carrito y sal a tomar aire fresco aunque sean 20 minutos. La calma de la naturaleza os sentará genial a tu bebé y a ti.', body_fr = 'Vous étouffez entre quatre murs ? Installez-le dans sa poussette et sortez prendre l''air, ne serait-ce que 20 minutes. La sérénité de la nature fera du bien à bébé comme à votre moral.', body_hi = 'चार दीवारें घुटन दे रही हैं। उसे स्ट्रॉलर में बिठाइए और 20 मिनट के लिए ही सही, ताज़ी हवा में निकलिए। प्रकृति का सुकून बच्चे और आपके मन, दोनों पर बढ़िया असर करेगा।', body_id = 'Empat dinding terasa menyesakkan. Masukkan ia ke stroller dan keluarlah menghirup udara segar walau hanya 20 menit. Ketenangan alam baik untuk bayi dan juga untuk kesehatan mental Anda.', body_ja = '4つの壁に息がつまりそう。ベビーカーに乗せて、20分だけでも外の空気を吸いに出かけましょう。自然のやすらぎは、赤ちゃんにもあなたの心にもとてもいい効果があります。', body_ko = '네 벽이 답답하게 느껴지나요? 아기를 유모차에 태우고 20분이라도 바깥바람을 쐬어 보세요. 자연의 평온함이 아기에게도 엄마의 마음에도 큰 도움이 될 거예요.', body_nl = 'Je vier muren verstikken je. Leg je baby in de kinderwagen en ga naar buiten, al is het maar voor 20 minuten. De rust van de natuur doet je baby en jouw gemoed heel goed.', body_pl = 'Cztery ściany cię przytłaczają. Włóż go do wózka i wyjdź na świeże powietrze, choćby na 20 minut. Spokój natury świetnie wpłynie i na maluszka, i na twoją psychikę.', body_pt = 'As quatro paredes estão a sufocá-la. Ponha-o no carrinho e saia para apanhar ar fresco, nem que seja 20 minutos. A calma da natureza faz muito bem ao bebé e ao seu equilíbrio emocional.', body_sv = 'De fyra väggarna kväver dig. Lägg barnet i vagnen och gå ut i frisk luft, om så bara i 20 minuter. Naturens ro gör både barnet och ditt psyke väldigt gott.', body_vi = 'Bốn bức tường khiến mẹ ngột ngạt. Đặt bé vào xe đẩy và ra ngoài hít thở không khí trong lành, dù chỉ 20 phút. Sự bình yên của thiên nhiên sẽ rất tốt cho cả bé lẫn tâm trạng của mẹ.', body_zh = '四面墙让你喘不过气。把宝宝放进婴儿车，哪怕出去20分钟呼吸新鲜空气也好。大自然的宁静对宝宝和你的心情都很有好处。' WHERE id = '2eb3f64d-4f32-4bfb-81ca-c75ffc798fd6' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El mundo mágico de los cuentos 🪄', title_fr = 'Le monde magique du conte 🪄', title_hi = 'कहानी की जादुई दुनिया 🪄', title_id = 'Dunia dongeng yang ajaib 🪄', title_ja = 'お話の魔法の世界 🪄', title_ko = '동화의 마법 세계 🪄', title_nl = 'De magische wereld van sprookjes 🪄', title_pl = 'Magiczny świat bajki 🪄', title_pt = 'O mundo mágico das histórias 🪄', title_sv = 'Sagans magiska värld 🪄', title_vi = 'Thế giới kỳ diệu của truyện cổ tích 🪄', title_zh = '故事的魔法世界 🪄' WHERE id = 'e607fc1e-dfa8-4735-b945-f39209fa5d8a' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gateo con objetivo 🐢', title_fr = 'Le quatre pattes avec un but 🐢', title_hi = 'लक्ष्य की ओर रेंगना 🐢', title_id = 'Merangkak dengan tujuan 🐢', title_ja = '目的のあるはいはい 🐢', title_ko = '목표가 있는 기어가기 🐢', title_nl = 'Kruipen met een doel 🐢', title_pl = 'Raczkowanie do celu 🐢', title_pt = 'Gatinhar com um objetivo 🐢', title_sv = 'Målmedvetet krypande 🐢', title_vi = 'Bò có mục tiêu 🐢', title_zh = '有目标地爬 🐢' WHERE id = 'f2202a7a-5edc-4209-b790-4083df0975d2' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡PREPARANDO EL ANIVERSARIO! 🎂', body_es = '¡Dentro de solo 9 días cumplirá 7 meses! ¿Has pensado en una temática distinta o una tarta especial para este mes? Empieza ya los preparativos para no dejarlo para el último día.', title_fr = 'ON PRÉPARE LA FÊTE ! 🎂', body_fr = 'Dans seulement 9 jours, il aura 7 mois ! Avez-vous pensé à un thème différent ou à un gâteau spécial pour ce mois-ci ? Commencez les préparatifs dès maintenant pour ne pas vous retrouver au dernier moment.', title_hi = 'जश्न की तैयारी! 🎂', body_hi = 'बस 9 दिन बाद वह 7 महीने का हो जाएगा! इस महीने के लिए कोई अलग थीम या खास केक सोचा है? तैयारी अभी से शुरू कीजिए, ताकि आखिरी दिन तक न टले।', title_id = 'PERSIAPAN HARI ISTIMEWA! 🎂', body_id = 'Tinggal 9 hari lagi ia genap 7 bulan! Sudah memikirkan tema berbeda atau kue khusus untuk bulan ini? Mulai persiapannya sekarang agar tidak mepet.', title_ja = 'お祝いの準備！🎂', body_ja = 'あと9日で生後7か月！今月のための特別なテーマやケーキは考えましたか？ぎりぎりにならないよう、今から準備を始めましょう。', title_ko = '기념일 준비! 🎂', body_ko = '딱 9일 뒤면 7개월이 돼요! 이번 달을 위한 색다른 콘셉트나 특별한 케이크를 생각해 보셨나요? 마지막 날까지 미루지 말고 지금 준비를 시작하세요.', title_nl = 'VOORBEREIDING OP HET JUBILEUM! 🎂', body_nl = 'Over maar 9 dagen wordt je baby 7 maanden! Heb je al een ander thema of een speciale taart bedacht voor deze maand? Begin nu al, zodat het niet op het laatste moment hoeft.', title_pl = 'PRZYGOTOWANIA DO JUBILEUSZU! 🎂', body_pl = 'Już za 9 dni skończy 7 miesięcy! Myślałaś o innym motywie albo specjalnym torcie na ten miesiąc? Zacznij przygotowania już teraz, żeby nie zostawiać ich na ostatnią chwilę.', title_pt = 'PREPARAR A DATA ESPECIAL! 🎂', body_pt = 'Daqui a apenas 9 dias faz 7 meses! Já pensou num tema diferente ou num bolo especial para este mês? Comece já os preparativos para não deixar tudo para o último dia.', title_sv = 'FÖRBEREDELSER INFÖR JUBILEET! 🎂', body_sv = 'Om bara 9 dagar fyller barnet 7 månader! Har du funderat på ett speciellt tema eller en speciell tårta för den här månaden? Börja förbereda redan nu så att inget blir till sista dagen.', title_vi = 'CHUẨN BỊ MỪNG KỶ NIỆM! 🎂', body_vi = 'Chỉ 9 ngày nữa là bé tròn 7 tháng! Mẹ đã nghĩ đến một chủ đề khác biệt hay bánh kem đặc biệt cho tháng này chưa? Hãy chuẩn bị ngay từ bây giờ để không bị dồn vào phút chót.', title_zh = '准备庆祝！🎂', body_zh = '再过9天宝宝就满7个月了！这个月想好特别的主题或蛋糕了吗？现在就开始准备，别拖到最后一天。' WHERE id = '05e938a0-adb4-413b-992b-19bbd78f0925' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rumbo al medio año 📈', body_es = '¿Te lo puedes creer? ¡Falta muy poco para que cumpla 6 meses! Abre el Seguimiento del desarrollo y repasa con orgullo el increíble camino que habéis recorrido hasta ahora.', title_fr = 'Bientôt six mois 📈', body_fr = 'Vous y croyez ? Les 6 mois approchent à grands pas ! Ouvrez le Suivi de développement et parcourez avec fierté l''incroyable chemin accompli jusqu''ici.', title_hi = 'आधे साल की ओर 📈', body_hi = 'यकीन होता है? 6 महीने पूरे होने में बस थोड़ा ही समय बाकी है! ग्रोथ ट्रैकर खोलिए और इस महीने तक के अपने शानदार सफ़र को गर्व से देखिए।', title_id = 'Menuju setengah tahun 📈', body_id = 'Percaya tidak? Sebentar lagi genap 6 bulan! Buka Pelacak Perkembangan dan lihat dengan bangga perjalanan luar biasa yang sudah Anda lalui hingga bulan ini.', title_ja = 'もうすぐハーフバースデー 📈', body_ja = '信じられますか？生後6か月まであと少し！「発達トラッカー」を開いて、ここまで歩んできたすばらしい道のりを誇らしく振り返りましょう。', title_ko = '곧 반년 📈', body_ko = '믿어지나요? 곧 6개월이 돼요! 성장 기록을 열고 지금까지 걸어온 놀라운 길을 뿌듯하게 살펴보세요.', title_nl = 'Op weg naar een half jaar 📈', body_nl = 'Kun je het geloven? Je baby is bijna 6 maanden! Open de Groeitracker en bekijk vol trots de ongelofelijke weg die jullie tot nu toe hebben afgelegd.', title_pl = 'W stronę pół roczku 📈', body_pl = 'Wierzysz w to? Już niedługo minie 6. miesiąc! Otwórz Śledzenie rozwoju i z dumą przejrzyj niesamowitą drogę, którą przeszliście.', title_pt = 'Rumo ao meio ano 📈', body_pt = 'Acredita? Falta muito pouco para os 6 meses! Abra o Registo de Desenvolvimento e veja com orgulho o caminho incrível que fizeram até aqui.', title_sv = 'Snart ett halvår 📈', body_sv = 'Kan du tro det? Det är inte långt kvar tills barnet fyller 6 månader! Öppna Utvecklingsspåraren och gå stolt igenom den otroliga vägen ni har gått fram till nu.', title_vi = 'Sắp tròn nửa tuổi 📈', body_vi = 'Mẹ tin được không? Chỉ còn ít ngày nữa là bé tròn 6 tháng! Mở Theo dõi phát triển và tự hào nhìn lại chặng đường tuyệt vời đến tháng này.', title_zh = '快满半岁了 📈', body_zh = '你敢相信吗？宝宝快满6个月了！打开发育追踪，自豪地回顾一下你们走过的不可思议的路吧。' WHERE id = '0a102f68-6cd0-452b-9fa2-0aa24ccb1814' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El baile de la victoria 💖', title_fr = 'La danse de la victoire 💖', title_hi = 'जीत का नाच 💖', title_id = 'Tarian kemenangan 💖', title_ja = '勝利のダンス 💖', title_ko = '승리의 춤 💖', title_nl = 'Een overwinningsdans 💖', title_pl = 'Taniec zwycięstwa 💖', title_pt = 'Dança da vitória 💖', title_sv = 'Segerdans 💖', title_vi = 'Điệu nhảy chiến thắng 💖', title_zh = '胜利之舞 💖' WHERE id = '0eb89ca2-1605-4f92-8c61-0198a966afb1' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡SOLO 3 DÍAS PARA LOS 7 MESES! 🎂', body_es = '¿Está lista la tarta? ¿Has elegido la ropa? Queda muy poco para los 7 meses. ¡Planea celebrar este bonito aniversario con una pequeña sesión de fotos en casa!', title_fr = 'PLUS QUE 3 JOURS AVANT LES 7 MOIS ! 🎂', body_fr = 'Le gâteau est commandé ? Les tenues sont choisies ? Les 7 mois approchent à grands pas. Prévoyez de célébrer ce bel anniversaire avec une petite séance photo à la maison !', title_hi = '7 महीने में बस 3 दिन! 🎂', body_hi = 'केक का ऑर्डर तैयार है? कपड़े चुन लिए? 7 महीने पूरे होने में बहुत कम समय बचा है। इस प्यारे पड़ाव को घर पर एक छोटे फ़ोटोशूट के साथ मनाने की योजना बनाइए!', title_id = 'TINGGAL 3 HARI MENUJU 7 BULAN! 🎂', body_id = 'Pesanan kue sudah siap? Baju sudah dipilih? Genap 7 bulan sudah dekat. Rencanakan merayakan momen indah ini dengan sesi foto kecil di rumah!', title_ja = '7か月まであと3日！🎂', body_ja = 'ケーキの注文はすみましたか？服は選びましたか？7か月まであと少し。このすてきな記念日を、おうちでのちょっとしたフォトセッションでお祝いする計画を立てましょう！', title_ko = '7개월까지 딱 3일! 🎂', body_ko = '케이크 주문은 됐나요? 옷은 골랐나요? 7개월이 정말 얼마 남지 않았어요. 이 멋진 기념일을 집에서 작은 사진 촬영으로 축하해 보세요!', title_nl = 'NOG MAAR 3 DAGEN TOT 7 MAANDEN! 🎂', body_nl = 'Is de taart besteld? Zijn de kleertjes gekozen? Je baby is bijna 7 maanden. Vier dit mooie jubileum met een kleine fotoshoot thuis!', title_pl = 'TYLKO 3 DNI DO 7 MIESIĘCY! 🎂', body_pl = 'Tort zamówiony? Ubranka wybrane? Do 7 miesięcy zostało bardzo niewiele. Zaplanuj uczczenie tego pięknego jubileuszu małą sesją zdjęciową w domu!', title_pt = 'SÓ FALTAM 3 DIAS PARA OS 7 MESES! 🎂', body_pt = 'A encomenda do bolo está pronta? A roupa já está escolhida? Falta muito pouco para os 7 meses. Planeie celebrar esta data bonita com uma pequena sessão fotográfica em casa!', title_sv = 'BARA 3 DAGAR KVAR TILL 7 MÅNADER! 🎂', body_sv = 'Är tårtan beställd? Är kläderna valda? Det är inte långt kvar tills barnet fyller 7 månader. Planera att fira jubileet med en liten fotografering hemma!', title_vi = 'CHỈ 3 NGÀY NỮA LÀ TRÒN 7 THÁNG! 🎂', body_vi = 'Bánh kem đã đặt chưa? Quần áo đã chọn chưa? Sắp đến ngày bé tròn 7 tháng rồi. Hãy lên kế hoạch mừng kỷ niệm đẹp này bằng một buổi chụp ảnh nho nhỏ tại nhà nhé!', title_zh = '距离7个月只剩3天！🎂', body_zh = '蛋糕订好了吗？衣服选好了吗？离满7个月没几天了。计划在家拍一组小写真，庆祝这个美好的纪念日吧！' WHERE id = '1175cce8-f8b8-4dcc-a8b2-c864d9349ad6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Faltan 10 días para el primer año! 🎂', body_es = '¡La emoción crece! Tarta de cumpleaños, ropa, lista de invitados... Ordena tus ideas apuntándolo todo en la sección de notas especiales del Diario de ánimo.', title_fr = 'Plus que 10 jours avant ses 1 an ! 🎂', body_fr = 'L''excitation monte ! Gâteau d''anniversaire, tenues, liste des invités... Mettez de l''ordre dans vos idées en notant tout dans la section notes spéciales du Journal d''humeur.', title_hi = 'पहले जन्मदिन में 10 दिन बाकी! 🎂', body_hi = 'उत्साह बढ़ रहा है! जन्मदिन का केक, कपड़े, मेहमानों की सूची... सब कुछ मूड डायरी के खास नोट्स सेक्शन में लिखकर अपने विचार व्यवस्थित कीजिए।', title_id = '10 hari lagi menuju 1 tahun! 🎂', body_id = 'Makin berdebar! Kue ulang tahun, baju, daftar tamu... Rapikan pikiran Anda dengan menulis semuanya di bagian catatan khusus Buku Harian Suasana Hati.', title_ja = '1歳まであと10日！🎂', body_ja = 'ワクワクが高まります！誕生日ケーキ、服、ゲストリスト...「気分日記」の特別メモ欄にぜんぶ書いて、考えを整理しましょう。', title_ko = '첫돌까지 10일! 🎂', body_ko = '설렘이 커져요! 생일 케이크, 옷, 손님 목록... 기분 일기의 특별 메모 섹션에 모두 적으며 생각을 정리해 보세요.', title_nl = 'Nog 10 dagen tot de eerste verjaardag! 🎂', body_nl = 'De spanning stijgt! Verjaardagstaart, kleertjes, gastenlijst... Zet alles in het onderdeel speciale notities van je Stemmingsdagboek en orden je gedachten.', title_pl = 'Do roczku zostało 10 dni! 🎂', body_pl = 'Emocje rosną! Tort urodzinowy, ubranka, lista gości... Zbierz myśli, zapisując wszystko w specjalnej sekcji notatek Dziennika nastroju.', title_pt = 'FALTAM 10 DIAS PARA O 1.º ANIVERSÁRIO! 🎂', body_pt = 'A emoção aumenta! Bolo de aniversário, roupa, lista de convidados... Organize as ideias escrevendo tudo na secção de notas especiais do Diário de Humor.', title_sv = '10 dagar kvar till 1 år! 🎂', body_sv = 'Spänningen stiger! Födelsedagstårta, kläder, gästlista... Samla tankarna genom att skriva upp allt i avsnittet för särskilda anteckningar i Humördagboken.', title_vi = 'Còn 10 ngày nữa là tròn 1 tuổi! 🎂', body_vi = 'Càng lúc càng háo hức! Bánh sinh nhật, trang phục, danh sách khách mời... Hãy ghi hết vào phần ghi chú đặc biệt của Nhật ký tâm trạng để sắp xếp suy nghĩ.', title_zh = '距离一周岁还有10天！🎂', body_zh = '越来越激动了！生日蛋糕、服装、宾客名单……把一切写进心情日记的专属笔记区，理清思路吧。' WHERE id = '11e743be-fb20-462f-8c74-07c143992d51' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Faltan 10 días para los 10 meses! 🎈', body_es = '¡Faltan 10 días para el aniversario! Elige ya los marcos especiales en la herramienta Sesión de fotos del bebé y planifícalo todo.', title_fr = 'Plus que 10 jours avant les 10 mois ! 🎈', body_fr = 'Plus que 10 jours avant le grand jour ! Choisissez et prévoyez dès maintenant les cadres spéciaux dans l''outil Séance photo bébé.', title_hi = '10 महीने में 10 दिन बाकी! 🎈', body_hi = 'खास दिन में 10 दिन बाकी! बेबी फ़ोटोशूट टूल में खास फ़्रेम अभी से चुनकर प्लान बनाइए।', title_id = '10 hari lagi menuju 10 bulan! 🎈', body_id = '10 hari lagi menuju hari istimewa! Pilih dan rencanakan bingkai khusus di Sesi Foto Bayi dari sekarang.', title_ja = '10か月まであと10日！🎈', body_ja = '記念日まであと10日！「ベビーフォトセッション」で、特別なフレームを今から選んで計画を立てましょう。', title_ko = '10개월까지 10일! 🎈', body_ko = '기념일까지 10일 남았어요! 아기 사진 촬영 도구에서 특별한 프레임을 미리 골라 계획해 보세요.', title_nl = 'Nog 10 dagen tot 10 maanden! 🎈', body_nl = 'Nog 10 dagen tot het jubileum! Kies en plan nu al de speciale kaders in de tool Babyfotoshoot.', title_pl = 'Do 10 miesięcy zostało 10 dni! 🎈', body_pl = 'Do jubileuszu zostało 10 dni! Już teraz wybierz specjalne ramki w Sesji zdjęciowej dziecka i zaplanuj zdjęcia.', title_pt = 'FALTAM 10 DIAS PARA OS 10 MESES! 🎈', body_pt = 'Faltam 10 dias para a data especial! Escolha já na Sessão Fotográfica do Bebé as molduras especiais e planeie tudo.', title_sv = '10 dagar kvar till 10 månader! 🎈', body_sv = '10 dagar kvar till jubileet! Välj och planera redan nu speciella ramar i Babyfotografering.', title_vi = 'Còn 10 ngày nữa là tròn 10 tháng! 🎈', body_vi = 'Còn 10 ngày nữa là đến ngày kỷ niệm! Hãy chọn trước những khung ảnh đặc biệt trong công cụ Chụp ảnh cho bé và lên kế hoạch ngay nhé.', title_zh = '距离10个月还有10天！🎈', body_zh = '距离纪念日还有10天！现在就在宝宝写真里挑选专属相框，提前规划吧。' WHERE id = '19eac11a-ecf7-498d-85e1-95d4f484d466' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡6 MESES CUMPLIDOS! ¡MEDIO AÑO! 🎉', body_es = '¡Enhorabuena! Lleváis justo {milestone_days} días criando este milagro. ¡Crea ya una foto especial de este día en la Sesión de fotos del bebé y compártela en la Comunidad Anacan!', title_fr = 'PILE 6 MOIS ! UN DEMI-ANNIVERSAIRE ! 🎉', body_fr = 'Félicitations ! Cela fait exactement {milestone_days} jours que vous élevez ce petit miracle. Créez tout de suite une photo spéciale pour ce jour dans la Séance photo bébé et partagez-la dans la Communauté Anacan !', title_hi = 'पूरे 6 महीने! आधा साल! 🎉', body_hi = 'बधाई हो! पूरे {milestone_days} दिन से आप इस चमत्कार को बड़ा कर रही हैं। तुरंत बेबी फ़ोटोशूट में इस खास दिन की तस्वीर बनाइए और Anacan कम्युनिटी में शेयर कीजिए!', title_id = 'GENAP 6 BULAN! SETENGAH TAHUN! 🎉', body_id = 'Selamat! Sudah tepat {milestone_days} hari Anda membesarkan keajaiban ini. Buat foto khusus untuk hari istimewa ini di Sesi Foto Bayi dan bagikan di Komunitas Anacan!', title_ja = '祝・6か月！ハーフバースデー！🎉', body_ja = 'おめでとうございます！ちょうど{milestone_days}日、この奇跡を育ててきました。今すぐ「ベビーフォトセッション」でこの日だけの特別な写真をつくって、Anacanコミュニティでシェアしましょう！', title_ko = '드디어 6개월! 반년! 🎉', body_ko = '축하해요! 꼬박 {milestone_days}일 동안 이 기적을 키워 왔어요. 지금 바로 아기 사진 촬영에서 이 특별한 날을 위한 사진을 만들어 Anacan 커뮤니티에 공유하세요!', title_nl = 'PRECIES 6 MAANDEN! EEN HALF JAAR! 🎉', body_nl = 'Gefeliciteerd! Al precies {milestone_days} dagen voeden jullie dit wonder op. Maak meteen een speciale foto van deze dag in Babyfotoshoot en deel hem in de Anacan Community!', title_pl = 'RÓWNO 6 MIESIĘCY! PÓŁ ROCZKU! 🎉', body_pl = 'Gratulacje! Od równych {milestone_days} dni wychowujesz ten cud. Od razu stwórz w Sesji zdjęciowej dziecka wyjątkowe zdjęcie na ten dzień i podziel się nim w Społeczności Anacan!', title_pt = '6 MESES FEITOS! MEIO ANO! 🎉', body_pt = 'Parabéns! Há exatamente {milestone_days} dias que cria este milagre. Crie já na Sessão Fotográfica do Bebé uma foto especial para este dia e partilhe-a na Comunidade Anacan!', title_sv = '6 MÅNADER! ETT HALVÅR! 🎉', body_sv = 'Grattis! I precis {milestone_days} dagar har du fått det här miraklet att växa. Skapa direkt en speciell bild för den här dagen i Babyfotografering och dela den i Anacans Community!', title_vi = 'TRÒN 6 THÁNG! TRÒN NỬA TUỔI! 🎉', body_vi = 'Chúc mừng! Đã tròn {milestone_days} ngày bố mẹ nuôi lớn phép màu này. Hãy tạo ngay một tấm ảnh đặc biệt cho ngày hôm nay trong Chụp ảnh cho bé và chia sẻ trong Cộng đồng Anacan!', title_zh = '满6个月！半岁啦！🎉', body_zh = '恭喜！你已经养育这个奇迹整整{milestone_days}天了。马上在宝宝写真里为这个特别的日子制作一张专属照片，分享到Anacan社区吧！' WHERE id = '1ac47b8c-1167-4ac1-a522-104b832c25b0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Solo 20 días para el primer año! 🎂', body_es = '¡Cómo vuela el tiempo! Empieza a tomar notas para las invitaciones del cumpleaños, las listas y las pequeñas sorpresas.', title_fr = 'Plus que 20 jours avant ses 1 an ! 🎂', body_fr = 'Comme le temps passe vite ! Commencez à prendre des notes pour les invitations, les listes et les petites surprises de l''anniversaire.', title_hi = 'पहले जन्मदिन में बस 20 दिन! 🎂', body_hi = 'समय कितनी तेज़ी से उड़ता है! जन्मदिन के न्योते, सूचियों और छोटे सरप्राइज़ के लिए नोट्स बनाना शुरू कीजिए।', title_id = 'Tinggal 20 hari menuju 1 tahun! 🎂', body_id = 'Betapa cepatnya waktu berlalu! Mulailah mencatat untuk undangan ulang tahun, daftar, dan kejutan-kejutan kecil.', title_ja = '1歳まであと20日！🎂', body_ja = '時間はなんて早く過ぎるのでしょう！誕生日の招待状、リスト、ちょっとしたサプライズのためのメモをつけはじめましょう。', title_ko = '첫돌까지 딱 20일! 🎂', body_ko = '시간이 정말 빨리 흘러요! 생일 초대장, 목록, 작은 깜짝 선물을 위한 메모를 시작해 보세요.', title_nl = 'Nog maar 20 dagen tot de eerste verjaardag! 🎂', body_nl = 'Wat vliegt de tijd! Begin met notities voor de uitnodigingen, de lijstjes en kleine verrassingen voor de verjaardag.', title_pl = 'Tylko 20 dni do roczku! 🎂', body_pl = 'Jak ten czas leci! Zacznij notować pomysły na zaproszenia urodzinowe, listy i małe niespodzianki.', title_pt = 'SÓ FALTAM 20 DIAS PARA O 1.º ANIVERSÁRIO! 🎂', body_pt = 'Como o tempo voa! Comece a tomar notas para os convites de aniversário, as listas e as pequenas surpresas.', title_sv = 'Bara 20 dagar kvar till 1 år! 🎂', body_sv = 'Vad tiden flyger! Börja anteckna inför inbjudningar, listor och små överraskningar till födelsedagen.', title_vi = 'Chỉ còn 20 ngày nữa là tròn 1 tuổi! 🎂', body_vi = 'Thời gian trôi nhanh quá! Hãy bắt đầu ghi chú cho thiệp mời sinh nhật, các danh sách và những bất ngờ nho nhỏ.', title_zh = '距离一周岁只剩20天！🎂', body_zh = '时间过得真快！开始为生日邀请函、清单和小惊喜做些记录吧。' WHERE id = '1bed0d5c-444a-48fc-8e21-35fd8fff35b5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡7 MESES CUMPLIDOS! 🎉', body_es = '¡Es increíble! Lleváis justo 7 meses criando juntos este milagro. ¡Inmortaliza ya este día en la Sesión de fotos del bebé y compártelo en la Comunidad!', title_fr = 'PILE 7 MOIS ! 🎉', body_fr = 'C''est incroyable ! Cela fait pile 7 mois que vous élevez ce petit miracle en équipe. Immortalisez tout de suite ce jour dans la Séance photo bébé et partagez-le dans la Communauté !', title_hi = 'पूरे 7 महीने! 🎉', body_hi = 'यकीन नहीं होता! पूरे 7 महीने से आप एक टीम बनकर इस चमत्कार को बड़ा कर रहे हैं। तुरंत बेबी फ़ोटोशूट में इस दिन को यादगार बनाइए और कम्युनिटी में शेयर कीजिए!', title_id = 'GENAP 7 BULAN! 🎉', body_id = 'Luar biasa! Sudah tepat 7 bulan kalian membesarkan keajaiban ini sebagai satu tim. Abadikan hari ini di Sesi Foto Bayi dan bagikan di Komunitas!', title_ja = '祝・7か月！🎉', body_ja = '信じられない！まる7か月、チームとしてこの奇跡を育ててきました。今すぐ「ベビーフォトセッション」でこの日を残して、コミュニティでシェアしましょう！', title_ko = '드디어 7개월! 🎉', body_ko = '믿기지 않아요! 꼬박 7개월 동안 한 팀으로 이 기적을 키워 왔어요. 지금 바로 아기 사진 촬영으로 이날을 영원히 남기고 커뮤니티에 공유하세요!', title_nl = 'PRECIES 7 MAANDEN! 🎉', body_nl = 'Ongelofelijk! Al precies 7 maanden voeden jullie als team dit wonder op. Leg deze dag meteen vast in Babyfotoshoot en deel hem in de Community!', title_pl = 'RÓWNO 7 MIESIĘCY! 🎉', body_pl = 'To niesamowite! Od równych 7 miesięcy jako drużyna wychowujecie ten cud. Od razu uwiecznij ten dzień w Sesji zdjęciowej dziecka i podziel się nim w Społeczności!', title_pt = '7 MESES FEITOS! 🎉', body_pt = 'É incrível! Há 7 meses certos que criam este milagre como uma equipa. Eternize já este dia na Sessão Fotográfica do Bebé e partilhe-o na Comunidade!', title_sv = '7 MÅNADER! 🎉', body_sv = 'Otroligt! I precis 7 månader har ni som ett lag fått det här miraklet att växa. Förevig dagen direkt i Babyfotografering och dela den i Community!', title_vi = 'TRÒN 7 THÁNG! 🎉', body_vi = 'Thật khó tin! Đã tròn 7 tháng bố mẹ cùng nhau nuôi lớn phép màu này. Hãy lưu giữ ngày hôm nay ngay trong Chụp ảnh cho bé và chia sẻ trong Cộng đồng!', title_zh = '满7个月啦！🎉', body_zh = '太不可思议了！你们作为一个团队，已经养育这个奇迹整整7个月了。马上用宝宝写真记录下这一天，分享到社区吧！' WHERE id = '347526cf-7568-4464-ab1e-f2a4e4f4b799' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡5 MESES CUMPLIDOS! 🎉', body_es = '¡Es increíble! Lleváis justo {milestone_days} días, 5 meses enteros, criando juntos este milagro. ¡Inmortaliza ya este día especial con la Sesión de fotos del bebé!', title_fr = 'PILE 5 MOIS ! 🎉', body_fr = 'C''est incroyable ! Cela fait exactement {milestone_days} jours, pile 5 mois, que vous élevez ce petit miracle en équipe. Immortalisez tout de suite ce jour spécial avec la Séance photo bébé !', title_hi = 'पूरे 5 महीने! 🎉', body_hi = 'यकीन नहीं होता! पूरे {milestone_days} दिन, यानी पूरे 5 महीने से आप एक टीम बनकर इस चमत्कार को बड़ा कर रहे हैं। तुरंत बेबी फ़ोटोशूट से इस खास दिन को यादगार बनाइए!', title_id = 'GENAP 5 BULAN! 🎉', body_id = 'Luar biasa! Sudah tepat {milestone_days} hari, genap 5 bulan, kalian membesarkan keajaiban ini sebagai satu tim. Abadikan hari istimewa ini di Sesi Foto Bayi sekarang juga!', title_ja = '祝・5か月！🎉', body_ja = '信じられない！ちょうど{milestone_days}日、まる5か月、チームとしてこの奇跡を育ててきました。今すぐ「ベビーフォトセッション」で、この特別な日を残しましょう！', title_ko = '드디어 5개월! 🎉', body_ko = '믿기지 않아요! 꼬박 {milestone_days}일, 딱 5개월 동안 한 팀으로 이 기적을 키워 왔어요. 지금 바로 아기 사진 촬영으로 이 특별한 날을 영원히 남기세요!', title_nl = 'PRECIES 5 MAANDEN! 🎉', body_nl = 'Ongelofelijk! Al precies {milestone_days} dagen, 5 hele maanden, voeden jullie als team dit wonder op. Leg deze bijzondere dag meteen vast met Babyfotoshoot!', title_pl = 'RÓWNO 5 MIESIĘCY! 🎉', body_pl = 'To niesamowite! Od równych {milestone_days} dni, pełnych 5 miesięcy, jako drużyna wychowujecie ten cud. Od razu uwiecznij ten wyjątkowy dzień w Sesji zdjęciowej dziecka!', title_pt = '5 MESES FEITOS! 🎉', body_pt = 'É incrível! Há exatamente {milestone_days} dias, 5 meses certos, que criam este milagre como uma equipa. Eternize já este dia especial na Sessão Fotográfica do Bebé!', title_sv = '5 MÅNADER! 🎉', body_sv = 'Otroligt! I precis {milestone_days} dagar, hela 5 månader, har ni som ett lag fått det här miraklet att växa. Förevig den speciella dagen direkt med Babyfotografering!', title_vi = 'TRÒN 5 THÁNG! 🎉', body_vi = 'Thật khó tin! Đã tròn {milestone_days} ngày, tức trọn 5 tháng bố mẹ cùng nhau nuôi lớn phép màu này. Hãy lưu giữ ngày đặc biệt này ngay với Chụp ảnh cho bé!', title_zh = '满5个月啦！🎉', body_zh = '太不可思议了！你们作为一个团队，已经养育这个奇迹整整{milestone_days}天，满满5个月了。马上用宝宝写真记录下这个特别的日子吧！' WHERE id = '3e771dfa-0468-483a-a4d1-a848e1eff82d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Preparando los 8 meses! 🎂', body_es = '¡Atención! Dentro de solo 10 días tu peque cumple 8 meses. Mira en el Seguimiento del desarrollo todo el camino recorrido. Ve pensando ya en encargar una pequeña tarta en Anacan para este mini aniversario.', title_fr = 'On prépare les 8 mois ! 🎂', body_fr = 'Attention ! Dans seulement 10 jours, votre petit aura pile 8 mois ! Regardez le chemin parcouru dans le Suivi de développement. Pour ce mini-anniversaire, pensez dès maintenant à commander un petit gâteau sur Anacan.', title_hi = '8वें महीने की तैयारी! 🎂', body_hi = 'ध्यान दीजिए! बस 10 दिन बाद आपका नन्हा पूरे 8 महीने का हो जाएगा! ग्रोथ ट्रैकर में अपना तय किया सफ़र देखिए। इस छोटे जश्न के लिए अभी से Anacan से छोटा केक ऑर्डर करने के बारे में सोचिए।', title_id = 'Persiapan bulan ke-8! 🎂', body_id = 'Perhatian! Tinggal 10 hari lagi si kecil genap 8 bulan! Lihat perjalanan yang sudah dilalui di Pelacak Perkembangan. Pertimbangkan memesan kue kecil dari Anacan untuk perayaan mini ini.', title_ja = '8か月の準備！🎂', body_ja = 'お知らせです！あと10日で赤ちゃんはちょうど生後8か月！「発達トラッカー」でここまでの道のりを見てみましょう。このミニ記念日のために、Anacanで小さなケーキの注文を今から考えてみては？', title_ko = '8개월 준비! 🎂', body_ko = '주목! 딱 10일 뒤면 아기가 8개월이 돼요! 성장 기록에서 지금까지 걸어온 길을 돌아보세요. 이 작은 기념일을 위해 Anacan에서 작은 케이크 주문을 미리 생각해 보세요.', title_nl = 'Voorbereiding op 8 maanden! 🎂', body_nl = 'Let op! Over maar 10 dagen wordt je kleintje precies 8 maanden! Bekijk in de Groeitracker de weg die jullie hebben afgelegd. Denk nu al na over een kleine taart van Anacan voor dit mini-jubileum.', title_pl = 'Przygotowania do 8. miesiąca! 🎂', body_pl = 'Uwaga! Już za 10 dni maluszek skończy równo 8 miesięcy! Spójrz w Śledzeniu rozwoju na drogę, którą przeszliście. Już teraz pomyśl o zamówieniu w Anacan małego tortu na ten mini jubileusz.', title_pt = 'Preparar os 8 meses! 🎂', body_pt = 'Atenção! Daqui a apenas 10 dias, o pequenino faz 8 meses certos! Veja no Registo de Desenvolvimento o caminho que já fizeram. Pense desde já em encomendar no Anacan um pequeno bolo para esta mini celebração.', title_sv = 'Förberedelser inför 8 månader! 🎂', body_sv = 'Obs! Om bara 10 dagar fyller den lilla 8 månader! Titta på vägen ni har gått i Utvecklingsspåraren. Fundera redan nu på att beställa en liten tårta från Anacan till det här minijubileet.', title_vi = 'Chuẩn bị cho tháng thứ 8! 🎂', body_vi = 'Chú ý! Chỉ 10 ngày nữa là bé tròn 8 tháng! Hãy nhìn lại chặng đường đã qua trong Theo dõi phát triển. Mẹ có thể nghĩ đến việc đặt một chiếc bánh kem nhỏ từ Anacan cho dịp kỷ niệm nho nhỏ này ngay từ bây giờ.', title_zh = '准备迎接8个月！🎂', body_zh = '注意！再过10天宝宝就满8个月了！在发育追踪里看看你们走过的路。为这个小纪念日，现在就考虑在Anacan订个小蛋糕吧。' WHERE id = '4bcc0503-2fe9-4f95-83e9-1eb9c7b5e773' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mañana es el gran día! 🎉', body_es = '¡9 meses justos! ¿Has preparado la ropa? Libera memoria en el móvil, ¡mañana necesitarás mucho espacio para la Sesión de fotos del bebé!', title_fr = 'Demain, c''est le grand jour ! 🎉', body_fr = 'Pile 9 mois ! Les tenues sont prêtes ? Libérez de la mémoire sur votre téléphone, il faudra beaucoup de place demain pour la Séance photo bébé !', title_hi = 'कल बड़ा दिन है! 🎉', body_hi = 'पूरे 9 महीने! कपड़े तैयार कर लिए? फ़ोन की मेमोरी खाली कीजिए, कल बेबी फ़ोटोशूट के लिए खूब जगह चाहिए होगी!', title_id = 'Besok hari besar! 🎉', body_id = 'Tepat 9 bulan! Bajunya sudah disiapkan? Kosongkan memori ponsel, besok Anda butuh banyak ruang untuk Sesi Foto Bayi!', title_ja = '明日は大切な日！🎉', body_ja = 'ちょうど9か月！服の準備はできましたか？スマホの容量をあけておきましょう。明日の「ベビーフォトセッション」にはたくさんの空きが必要です！', title_ko = '내일이 큰 날이에요! 🎉', body_ko = '딱 9개월! 옷은 준비했나요? 휴대폰 저장 공간을 비워 두세요, 내일 아기 사진 촬영에 공간이 많이 필요할 거예요!', title_nl = 'Morgen is de grote dag! 🎉', body_nl = 'Precies 9 maanden! Heb je de kleertjes klaargelegd? Maak ruimte vrij op je telefoon, morgen heb je veel plek nodig voor Babyfotoshoot!', title_pl = 'Jutro wielki dzień! 🎉', body_pl = 'Równo 9 miesięcy! Ubranka przygotowane? Wyczyść pamięć telefonu, jutro do Sesji zdjęciowej dziecka potrzeba będzie mnóstwo miejsca!', title_pt = 'Amanhã é o grande dia! 🎉', body_pt = '9 meses certos! Já preparou a roupa? Liberte memória no telemóvel, amanhã vai precisar de muito espaço para a Sessão Fotográfica do Bebé!', title_sv = 'I morgon är den stora dagen! 🎉', body_sv = 'Precis 9 månader! Har du gjort i ordning kläderna? Töm telefonens minne, i morgon behövs massor av plats för Babyfotografering!', title_vi = 'Ngày mai là ngày trọng đại! 🎉', body_vi = 'Tròn 9 tháng! Mẹ đã chuẩn bị quần áo chưa? Hãy dọn bộ nhớ điện thoại, ngày mai sẽ cần nhiều chỗ cho Chụp ảnh cho bé!', title_zh = '明天就是大日子！🎉', body_zh = '整整9个月！衣服准备好了吗？清理一下手机内存，明天的宝宝写真需要很多空间！' WHERE id = '55476184-e000-441a-91f6-32b219ce5489' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡5 días para los 9 meses! 🎈', body_es = '¡Queda muy poco para el aniversario! Tarta, pequeños adornos o simplemente la ropa más bonita en casa... Acelera los preparativos para la Sesión de fotos del bebé.', title_fr = 'Plus que 5 jours avant les 9 mois ! 🎈', body_fr = 'Le grand jour approche ! Un gâteau, quelques petites décorations ou simplement les plus jolies tenues à la maison... Accélérez les préparatifs pour la Séance photo bébé.', title_hi = '9 महीने में 5 दिन! 🎈', body_hi = 'खास दिन बहुत करीब है! केक, छोटी सजावट या बस घर पर सबसे सुंदर कपड़े... बेबी फ़ोटोशूट की तैयारी तेज़ कीजिए।', title_id = '5 hari menuju 9 bulan! 🎈', body_id = 'Perayaan sudah sangat dekat! Kue, dekorasi kecil, atau cukup baju terbaik di rumah... Percepat persiapan untuk Sesi Foto Bayi.', title_ja = '9か月まであと5日！🎈', body_ja = '記念日まであと少し！ケーキ、ちょっとした飾りつけ、それともおうちでいちばんすてきな服...「ベビーフォトセッション」の準備をスピードアップしましょう。', title_ko = '9개월까지 5일! 🎈', body_ko = '기념일이 코앞이에요! 케이크, 작은 장식, 아니면 집에 있는 가장 예쁜 옷만으로도 충분해요... 아기 사진 촬영 준비를 서둘러 보세요.', title_nl = 'Nog 5 dagen tot 9 maanden! 🎈', body_nl = 'Het jubileum is bijna daar! Een taart, kleine versieringen of gewoon de mooiste kleertjes thuis... Versnel de voorbereidingen voor Babyfotoshoot.', title_pl = '5 dni do 9 miesięcy! 🎈', body_pl = 'Do jubileuszu zostało bardzo niewiele! Tort, małe dekoracje albo po prostu najpiękniejsze ubranka w domu... Przyspiesz przygotowania do Sesji zdjęciowej dziecka.', title_pt = 'FALTAM 5 DIAS PARA OS 9 MESES! 🎈', body_pt = 'Falta muito pouco para a data especial! Bolo, pequenas decorações ou só a roupa mais bonita de casa... Acelere os preparativos para a Sessão Fotográfica do Bebé.', title_sv = '5 dagar kvar till 9 månader! 🎈', body_sv = 'Det är väldigt nära jubileet nu! Tårta, små dekorationer eller bara de finaste kläderna hemma... Skynda på förberedelserna inför Babyfotografering.', title_vi = 'Còn 5 ngày nữa là tròn 9 tháng! 🎈', body_vi = 'Sắp đến ngày kỷ niệm rồi! Bánh kem, đồ trang trí nho nhỏ hay chỉ là những bộ đồ đẹp nhất ở nhà... Hãy đẩy nhanh việc chuẩn bị cho buổi Chụp ảnh cho bé.', title_zh = '距离9个月还有5天！🎈', body_zh = '纪念日就快到了！蛋糕、小装饰，或者只是在家穿上最漂亮的衣服……加快宝宝写真的准备吧。' WHERE id = '5626563e-1119-4751-a2d2-ad651cb7961b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Últimos 5 días para los 8 meses! 🎈', body_es = '¡La emoción crece! Dentro de solo 5 días tu peque cumple 8 meses. Si estás pensando en encargar una tarta especial o planear una temática, no lo dejes para el último día.', title_fr = 'Plus que 5 jours avant les 8 mois ! 🎈', body_fr = 'L''excitation monte ! Dans seulement 5 jours, votre petit aura 8 mois ! Si vous pensez commander un gâteau spécial ou prévoir un thème, n''attendez pas le dernier jour.', title_hi = '8 महीने में आखिरी 5 दिन! 🎈', body_hi = 'उत्साह बढ़ रहा है! बस 5 दिन बाद आपका नन्हा 8 महीने का हो जाएगा! अगर खास केक ऑर्डर करने या थीम प्लान करने की सोच रही हैं, तो इसे आखिरी दिन पर मत छोड़िए।', title_id = '5 hari terakhir menuju 8 bulan! 🎈', body_id = 'Makin berdebar! Tinggal 5 hari lagi si kecil genap 8 bulan! Kalau berencana memesan kue khusus atau menyiapkan tema, jangan tunda sampai hari terakhir.', title_ja = '8か月まであと5日！🎈', body_ja = 'ワクワクが高まります！あと5日で赤ちゃんは生後8か月！特別なケーキの注文やテーマの計画を考えているなら、ぎりぎりまで待たないで。', title_ko = '8개월까지 마지막 5일! 🎈', body_ko = '설렘이 커져요! 딱 5일 뒤면 아기가 8개월이 돼요! 특별한 케이크 주문이나 콘셉트 계획을 생각 중이라면 마지막 날까지 미루지 마세요.', title_nl = 'Nog 5 dagen tot 8 maanden! 🎈', body_nl = 'De spanning stijgt! Over maar 5 dagen wordt je kleintje 8 maanden! Wil je een speciale taart bestellen of een thema plannen? Wacht daar niet mee tot de laatste dag.', title_pl = 'Ostatnie 5 dni do 8 miesięcy! 🎈', body_pl = 'Emocje rosną! Już za 5 dni maluszek skończy 8 miesięcy! Jeśli myślisz o zamówieniu specjalnego tortu lub zaplanowaniu motywu, nie zostawiaj tego na ostatni dzień.', title_pt = 'ÚLTIMOS 5 DIAS PARA OS 8 MESES! 🎈', body_pt = 'A emoção aumenta! Daqui a apenas 5 dias, o pequenino faz 8 meses! Se está a pensar encomendar um bolo especial ou planear uma festa temática, não deixe para o último dia.', title_sv = 'De sista 5 dagarna till 8 månader! 🎈', body_sv = 'Spänningen stiger! Om bara 5 dagar fyller den lilla 8 månader! Om du funderar på att beställa en speciell tårta eller planera ett tema, spara det inte till sista dagen.', title_vi = 'Còn 5 ngày nữa là tròn 8 tháng! 🎈', body_vi = 'Càng lúc càng háo hức! Chỉ 5 ngày nữa là bé tròn 8 tháng! Nếu mẹ định đặt bánh kem đặc biệt hay lên kế hoạch tiệc theo chủ đề, đừng để đến ngày cuối nhé.', title_zh = '距离8个月只剩5天！🎈', body_zh = '越来越激动了！再过5天宝宝就满8个月了！如果想订特别的蛋糕或策划主题庆祝，别拖到最后一天。' WHERE id = '5d8608e7-e1cb-4a71-9c73-7f6dde65adfe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El baile de la victoria 💖', body_es = 'Esta noche celebra con tu pareja el cansancio y el orgullo de estos 11 meses. ¡Estáis en la recta final hacia el primer año!', title_fr = 'La danse de la victoire 💖', body_fr = 'Ce soir, célébrez avec votre conjoint la fatigue et la fierté de ces 11 mois. Vous êtes dans la dernière ligne droite avant ses 1 an !', title_hi = 'जीत का नाच 💖', body_hi = '11 महीनों की थकान और गर्व का जश्न आज शाम अपने साथी के साथ मनाइए। 1 साल की ओर आप आखिरी पड़ाव पर हैं!', title_id = 'Tarian kemenangan 💖', body_id = 'Malam ini, rayakan lelah dan bangganya 11 bulan ini bersama pasangan. Kalian sudah di jalur terakhir menuju 1 tahun!', title_ja = '勝利のダンス 💖', body_ja = '11か月分の疲れと誇りを、今夜はパートナーとお祝いしましょう。1歳に向けて、いよいよラストスパートです！', title_ko = '승리의 춤 💖', body_ko = '오늘 저녁 배우자와 함께 11개월의 피로와 뿌듯함을 기념하세요. 첫돌을 향한 마지막 직선 코스예요!', title_nl = 'Een overwinningsdans 💖', body_nl = 'Vier vanavond samen met je partner de vermoeidheid en de trots van 11 maanden. Jullie zitten op het laatste rechte stuk naar de eerste verjaardag!', title_pl = 'Taniec zwycięstwa 💖', body_pl = 'Uczcij dziś wieczorem z partnerem zmęczenie i dumę tych 11 miesięcy. Jesteście na ostatniej prostej do roczku!', title_pt = 'Dança da vitória 💖', body_pt = 'Esta noite, celebre com o seu companheiro o cansaço e o orgulho destes 11 meses. Estão na reta final rumo ao 1.º aniversário!', title_sv = 'Segerdans 💖', body_sv = 'Fira 11 månaders trötthet och stolthet tillsammans med din partner i kväll. Ni är på upploppet mot 1-årsdagen!', title_vi = 'Điệu nhảy chiến thắng 💖', body_vi = 'Tối nay, hãy cùng bố ăn mừng 11 tháng mệt mỏi và tự hào. Bố mẹ đang ở chặng nước rút cuối cùng đến sinh nhật 1 tuổi!', title_zh = '胜利之舞 💖', body_zh = '今晚和伴侣一起庆祝这11个月的疲惫与骄傲吧。你们已经进入迈向一周岁的最后冲刺！' WHERE id = '6ef8817b-2854-4da4-969a-fe13d344017a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Preparando los 10 meses! 🎂', body_es = '¡Atención! Dentro de solo 10 días tu peque cumple 10 meses. ¡No olvides encargar una tarta especial para celebrar el paso a los meses de dos cifras!', title_fr = 'On prépare les 10 mois ! 🎂', body_fr = 'Attention ! Dans seulement 10 jours, votre petit aura 10 mois ! N''oubliez pas de commander un gâteau spécial pour fêter le passage aux mois à deux chiffres !', title_hi = '10वें महीने की तैयारी! 🎂', body_hi = 'ध्यान दीजिए! बस 10 दिन बाद आपका नन्हा 10 महीने का हो जाएगा! दो अंकों वाले महीनों में कदम रखने के लिए खास केक ऑर्डर करना मत भूलिए!', title_id = 'Persiapan 10 bulan! 🎂', body_id = 'Perhatian! Tinggal 10 hari lagi si kecil genap 10 bulan! Jangan lupa memesan kue khusus untuk menyambut bulan berangka dua digit!', title_ja = '10か月の準備！🎂', body_ja = 'お知らせです！あと10日で赤ちゃんは生後10か月！2けたの月齢を迎えるお祝いに、特別なケーキを注文するのを忘れずに！', title_ko = '10개월 준비! 🎂', body_ko = '주목! 딱 10일 뒤면 아기가 10개월이 돼요! 두 자릿수 개월로 넘어가는 기념으로 특별한 케이크 주문을 잊지 마세요!', title_nl = 'Voorbereiding op 10 maanden! 🎂', body_nl = 'Let op! Over maar 10 dagen wordt je kleintje 10 maanden! Vergeet niet een speciale taart te bestellen voor de overgang naar de maanden met twee cijfers!', title_pl = 'Przygotowania do 10 miesięcy! 🎂', body_pl = 'Uwaga! Już za 10 dni maluszek skończy 10 miesięcy! Nie zapomnij zamówić specjalnego tortu na przejście do dwucyfrowych miesięcy!', title_pt = 'Preparar os 10 meses! 🎂', body_pt = 'Atenção! Daqui a apenas 10 dias, o pequenino faz 10 meses! Não se esqueça de encomendar um bolo especial para a passagem aos meses de dois dígitos!', title_sv = 'Förberedelser inför 10 månader! 🎂', body_sv = 'Obs! Om bara 10 dagar fyller den lilla 10 månader! Glöm inte att beställa en speciell tårta för övergången till de tvåsiffriga månaderna!', title_vi = 'Chuẩn bị cho tháng thứ 10! 🎂', body_vi = 'Chú ý! Chỉ 10 ngày nữa là bé tròn 10 tháng! Đừng quên đặt một chiếc bánh kem đặc biệt mừng bé bước sang tháng tuổi có hai chữ số!', title_zh = '准备迎接10个月！🎂', body_zh = '注意！再过10天宝宝就满10个月了！迈入两位数月龄，别忘了订一个特别的蛋糕！' WHERE id = '761f9ba9-87d1-4b16-a40a-f1ec2385a5fd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡FALTA 1 DÍA PARA EL ANIVERSARIO! 🎈', body_es = '¡Mañana es el gran día! ¿Está lista la tarta de los 5 meses y planchada la ropa? Abre la herramienta Sesión de fotos del bebé y haz ya unas fotos de prueba.', title_fr = 'J-1 AVANT LE GRAND JOUR ! 🎈', body_fr = 'Demain, c''est le grand jour ! Le gâteau des 5 mois est prêt, les tenues sont repassées ? Ouvrez l''outil Séance photo bébé et faites dès maintenant quelques photos d''essai !', title_hi = 'खास दिन में 1 दिन बाकी! 🎈', body_hi = 'कल बड़ा दिन है! 5 महीने पूरे होने का केक तैयार है, कपड़े इस्त्री हो गए? बेबी फ़ोटोशूट टूल खोलकर अभी से टेस्ट फ़ोटो लीजिए!', title_id = '1 HARI LAGI MENUJU HARI ISTIMEWA! 🎈', body_id = 'Besok hari besar! Kue untuk 5 bulan sudah siap, bajunya sudah disetrika? Buka Sesi Foto Bayi dan ambil foto percobaan dari sekarang!', title_ja = '記念日まであと1日！🎈', body_ja = '明日は大切な日！5か月のケーキは準備できた？服にアイロンはかけた？「ベビーフォトセッション」を開いて、今のうちにテスト撮影をしておきましょう！', title_ko = '기념일까지 1일! 🎈', body_ko = '내일이 큰 날이에요! 5개월 케이크는 준비됐고 옷은 다려 두셨나요? 아기 사진 촬영 도구를 열어 지금 미리 테스트 사진을 찍어 보세요!', title_nl = 'NOG 1 DAG TOT HET JUBILEUM! 🎈', body_nl = 'Morgen is de grote dag! Is de taart voor 5 maanden klaar en zijn de kleertjes gestreken? Open Babyfotoshoot en maak nu al wat proeffoto''s!', title_pl = 'DO JUBILEUSZU ZOSTAŁ 1 DZIEŃ! 🎈', body_pl = 'Jutro wielki dzień! Tort na 5 miesięcy gotowy, ubranka wyprasowane? Otwórz Sesję zdjęciową dziecka i zrób próbne zdjęcia już teraz!', title_pt = 'FALTA 1 DIA PARA A DATA ESPECIAL! 🎈', body_pt = 'Amanhã é o grande dia! O bolo dos 5 meses está pronto e a roupa passada a ferro? Abra a Sessão Fotográfica do Bebé e tire já umas fotos de ensaio!', title_sv = '1 DAG KVAR TILL JUBILEET! 🎈', body_sv = 'I morgon är den stora dagen! Är tårtan till 5-månadersdagen klar och kläderna strukna? Öppna Babyfotografering och ta några provbilder redan nu!', title_vi = 'CHỈ CÒN 1 NGÀY NỮA! 🎈', body_vi = 'Ngày mai là ngày trọng đại! Bánh kem mừng tròn 5 tháng đã sẵn sàng, quần áo đã là phẳng chưa? Mở công cụ Chụp ảnh cho bé và chụp thử vài tấm ngay từ bây giờ nhé!', title_zh = '距离纪念日还有1天！🎈', body_zh = '明天就是大日子！5个月的蛋糕准备好了吗，衣服熨好了吗？现在就打开宝宝写真，先拍几张试拍照吧！' WHERE id = '792511a4-1d02-4324-a33c-59bacedb4645' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Nueva etapa: ¡la alimentación complementaria! 🥣', body_es = '¡Ya tiene 6 meses! Es hora de conocer los purés de verduras. Pide a Anacan AI información sobre la regla de prueba de 3 días (para detectar alergias).', title_fr = 'Nouvelle étape : la diversification ! 🥣', body_fr = '6 mois révolus ! C''est le moment de découvrir les purées de légumes. Renseignez-vous auprès d''Anacan AI sur la règle des 3 jours d''essai (pour vérifier les allergies).', title_hi = 'नया दौर: ऊपरी आहार! 🥣', body_hi = '6 महीने पूरे हो गए! अब सब्ज़ियों की प्यूरी से पहचान का समय है। Anacan AI से 3 दिन के ट्रायल नियम (एलर्जी जाँचने के लिए) के बारे में जानिए।', title_id = 'Babak baru: MPASI! 🥣', body_id = 'Genap 6 bulan! Sudah waktunya berkenalan dengan puree sayur. Cari tahu tentang aturan uji coba 3 hari (untuk mengecek alergi) di Anacan AI.', title_ja = '新しいステージ：離乳食！🥣', body_ja = '6か月を迎えました！いよいよ野菜のペーストを始めるときです。アレルギーを確かめるための「3日間ルール」について、Anacan AIで調べてみましょう。', title_ko = '새로운 시기: 이유식! 🥣', body_ko = '6개월이 됐어요! 이제 채소 퓌레를 맛볼 시간이에요. Anacan AI에게 (알레르기 확인을 위한) 3일 시도 규칙에 대해 알아보세요.', title_nl = 'Een nieuwe fase: bijvoeding! 🥣', body_nl = '6 maanden! Tijd om kennis te maken met groentehapjes. Vraag Anacan AI naar de 3-dagenregel (om op allergie te letten).', title_pl = 'Nowy etap: rozszerzanie diety! 🥣', body_pl = 'Minęło 6 miesięcy! Czas poznać przeciery warzywne. Dowiedz się od Anacan AI o zasadzie 3-dniowej próby (do sprawdzania alergii).', title_pt = 'Uma nova fase: a diversificação alimentar! 🥣', body_pt = 'Fez 6 meses! Chegou a altura de conhecer os purés de legumes. Peça ao Anacan AI informação sobre a regra dos 3 dias de teste (para verificar alergias).', title_sv = 'En ny period: smakportioner! 🥣', body_sv = '6 månader är fyllda! Nu är det dags att bekanta sig med grönsakspuréer. Läs om 3-dagarsregeln (för att upptäcka allergi) hos Anacan AI.', title_vi = 'Giai đoạn mới: Ăn dặm! 🥣', body_vi = 'Bé đã tròn 6 tháng! Đến lúc làm quen với rau củ nghiền rồi. Hãy hỏi Anacan AI về quy tắc thử 3 ngày (để kiểm tra dị ứng).', title_zh = '新阶段：添加辅食！🥣', body_zh = '满6个月啦！是时候认识蔬菜泥了。向Anacan AI了解一下“3天试吃原则”（用来检查过敏）吧。' WHERE id = '7d616a8c-c926-4291-9221-42ee50e15fd5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El mundo mágico de los cuentos 🪄', body_es = 'Crea en Cuentos inteligentes la historia del gran héroe que dentro de solo 5 días cumplirá 9 meses.', title_fr = 'Le monde magique des contes 🪄', body_fr = 'Dans les Contes intelligents, créez l''histoire du grand héros qui aura 9 mois dans seulement 5 jours.', title_hi = 'जादुई कहानियों की दुनिया 🪄', body_hi = 'स्मार्ट कहानियों में उस बड़े हीरो की कहानी बनाइए जो बस 5 दिन बाद 9 महीने का होने वाला है।', title_id = 'Dunia dongeng ajaib 🪄', body_id = 'Di Dongeng Pintar, buat kisah pahlawan besar yang 5 hari lagi akan berusia 9 bulan.', title_ja = '魔法のお話の世界 🪄', body_ja = '「スマートおはなし」で、あと5日で生後9か月になる大きなヒーローのお話をつくりましょう。', title_ko = '마법 같은 동화 세상 🪄', body_ko = '스마트 동화에서 딱 5일 뒤면 9개월이 되는 멋진 주인공의 이야기를 만들어 보세요.', title_nl = 'De magische sprookjeswereld 🪄', body_nl = 'Maak in Slimme sprookjes het verhaal van een grote held die over maar 5 dagen 9 maanden wordt.', title_pl = 'Magiczny świat bajek 🪄', body_pl = 'Stwórz w Mądrych bajkach historię o wielkim bohaterze, który już za 5 dni skończy 9 miesięcy.', title_pt = 'O mundo mágico das histórias 🪄', body_pt = 'Crie nas Histórias Inteligentes a história do grande herói que daqui a apenas 5 dias faz 9 meses.', title_sv = 'Sagans magiska värld 🪄', body_sv = 'Skapa sagan om den stora hjälten som fyller 9 månader om bara 5 dagar i Smarta sagor.', title_vi = 'Thế giới cổ tích kỳ diệu 🪄', body_vi = 'Hãy tạo trong Truyện cổ tích thông minh câu chuyện về người hùng lớn sẽ tròn 9 tháng chỉ sau 5 ngày nữa.', title_zh = '神奇的故事世界 🪄', body_zh = '在智能故事里创作一个再过5天就满9个月的小英雄的故事吧。' WHERE id = '8750f5ee-e089-418c-9d9b-a881ca3441c3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡9 meses cumplidos! 🎂', body_es = '¡Enhorabuena! Han pasado 9 meses justos desde el parto. ¡Creció 9 meses en tu vientre y otros 9 en tus brazos! Celebra este gran momento y comparte el recuerdo en la comunidad.', title_fr = 'Pile 9 mois ! 🎂', body_fr = 'Félicitations ! Cela fait pile 9 mois depuis la naissance. Il a grandi 9 mois dans votre ventre et 9 mois dans vos bras ! Célébrez ce moment magnifique et partagez ce souvenir dans la Communauté !', title_hi = 'पूरे 9 महीने! 🎂', body_hi = 'बधाई हो! जन्म के बाद पूरे 9 महीने बीत गए। वह 9 महीने आपके गर्भ में और 9 महीने आपकी गोद में बड़ा हुआ! इस शानदार पल का जश्न मनाइए और यह याद कम्युनिटी में शेयर कीजिए!', title_id = 'Genap 9 bulan! 🎂', body_id = 'Selamat! Sudah tepat 9 bulan sejak kelahirannya. Ia tumbuh 9 bulan di rahim Anda, dan 9 bulan dalam pelukan Anda! Rayakan momen luar biasa ini dan bagikan kenangannya di Komunitas!', title_ja = '祝・9か月！🎂', body_ja = 'おめでとうございます！生まれてからちょうど9か月。お腹の中で9か月、腕の中で9か月育ちました！このすばらしい瞬間をお祝いして、コミュニティで思い出をシェアしましょう！', title_ko = '드디어 9개월! 🎂', body_ko = '축하해요! 태어난 지 딱 9개월이 지났어요. 엄마 배 속에서 9개월, 엄마 품에서 9개월을 자랐어요! 이 멋진 순간을 기념하고 커뮤니티에 추억을 공유하세요!', title_nl = 'Precies 9 maanden! 🎂', body_nl = 'Gefeliciteerd! Sinds de geboorte zijn er precies 9 maanden voorbij. 9 maanden groeide hij in je buik, 9 maanden in je armen! Vier dit geweldige moment en deel je herinnering in de community!', title_pl = 'Równo 9 miesięcy! 🎂', body_pl = 'Gratulacje! Od porodu minęło równo 9 miesięcy. Rósł 9 miesięcy w twoim łonie i 9 miesięcy w twoich ramionach! Uczcij tę wspaniałą chwilę i podziel się wspomnieniem w Społeczności!', title_pt = '9 meses feitos! 🎂', body_pt = 'Parabéns! Passaram 9 meses certos desde o nascimento. Cresceu 9 meses na sua barriga e 9 meses no seu colo! Celebre este momento fantástico e partilhe a recordação na comunidade!', title_sv = '9 månader! 🎂', body_sv = 'Grattis! Det har gått precis 9 månader sedan förlossningen. Barnet växte 9 månader i din mage och 9 månader i din famn! Fira det här fantastiska ögonblicket och dela minnet i Community!', title_vi = 'Tròn 9 tháng! 🎂', body_vi = 'Chúc mừng! Đã tròn 9 tháng kể từ ngày bé chào đời. Bé lớn lên 9 tháng trong bụng mẹ và 9 tháng trong vòng tay mẹ! Hãy ăn mừng khoảnh khắc tuyệt vời này và chia sẻ kỷ niệm trong cộng đồng!', title_zh = '满9个月啦！🎂', body_zh = '恭喜！宝宝出生已经整整9个月了。宝宝在你肚子里长了9个月，又在你怀里长了9个月！庆祝这个美好的时刻，在社区里分享这份回忆吧！' WHERE id = '8be43b5a-b4b9-49ba-b74f-59b204783156' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mañana es el gran día! 🎉', body_es = '¿Preparada? ¡Mañana cumple 11 meses! ¡Último mes para el primer año! Prepara un rincón y una ropa diferentes para la Sesión de fotos del bebé.', title_fr = 'Demain, c''est le grand jour ! 🎉', body_fr = 'Prête ? Demain, il aura pile 11 mois ! Plus que 1 mois avant ses 1 an ! Préparez un coin et une tenue différents pour la Séance photo bébé.', title_hi = 'कल बड़ा दिन है! 🎉', body_hi = 'तैयार हैं? कल पूरे 11 महीने हो रहे हैं! 1 साल में बस आखिरी 1 महीना! बेबी फ़ोटोशूट के लिए एक अलग कोना और कपड़े तैयार कीजिए।', title_id = 'Besok hari besar! 🎉', body_id = 'Siap? Besok ia genap 11 bulan! Tinggal 1 bulan terakhir menuju 1 tahun! Siapkan sudut dan baju yang berbeda untuk Sesi Foto Bayi.', title_ja = '明日は大切な日！🎉', body_ja = '準備はいい？明日でちょうど11か月！1歳まであと1か月！「ベビーフォトセッション」のために、いつもと違うコーナーと服を用意しましょう。', title_ko = '내일이 큰 날이에요! 🎉', body_ko = '준비됐나요? 내일이면 딱 11개월이에요! 첫돌까지 마지막 1개월! 아기 사진 촬영을 위해 색다른 공간과 옷을 준비해 보세요.', title_nl = 'Morgen is de grote dag! 🎉', body_nl = 'Klaar? Morgen wordt hij precies 11 maanden! Nog 1 maand tot de eerste verjaardag! Zoek een ander hoekje en andere kleertjes voor Babyfotoshoot.', title_pl = 'Jutro wielki dzień! 🎉', body_pl = 'Gotowa? Jutro mija równo 11 miesięcy! Ostatni miesiąc do roczku! Przygotuj do Sesji zdjęciowej dziecka nowy kącik i strój.', title_pt = 'Amanhã é o grande dia! 🎉', body_pt = 'Está preparada? Amanhã faz 11 meses certos! Último mês até ao 1.º aniversário! Prepare um cantinho e uma roupa diferentes para a Sessão Fotográfica do Bebé.', title_sv = 'I morgon är den stora dagen! 🎉', body_sv = 'Är ni redo? I morgon fyller barnet 11 månader! 1 månad kvar till 1-årsdagen! Gör i ordning ett speciellt hörn och speciella kläder till Babyfotografering.', title_vi = 'Ngày mai là ngày trọng đại! 🎉', body_vi = 'Sẵn sàng chưa? Ngày mai bé tròn 11 tháng! Chỉ còn 1 tháng nữa là tròn 1 tuổi! Hãy chuẩn bị một góc chụp và trang phục khác biệt cho buổi Chụp ảnh cho bé.', title_zh = '明天就是大日子！🎉', body_zh = '准备好了吗？明天宝宝就满11个月了！离一周岁只剩最后1个月！为宝宝写真准备一个特别的角落和服装吧。' WHERE id = '932e2f32-ffee-4b5c-9d10-16c135453b42' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿HAS ENCARGADO LA TARTA? 🎂', body_es = '¡Dentro de solo 5 días tu peque cumple 5 meses! Completa ya tu pedido de una tarta o un conjunto especial con temática de 5 meses.', title_fr = 'AVEZ-VOUS COMMANDÉ LE GÂTEAU ? 🎂', body_fr = 'Dans seulement 5 jours, votre petit aura 5 mois ! Finalisez dès maintenant votre commande de gâteau ou de tenue spéciale sur le thème des 5 mois !', title_hi = 'केक ऑर्डर कर दिया? 🎂', body_hi = 'बस 5 दिन बाद आपका नन्हा 5 महीने का हो जाएगा! 5वें महीने की थीम वाले खास केक या कपड़ों का ऑर्डर अभी पूरा कीजिए!', title_id = 'SUDAH PESAN KUE? 🎂', body_id = 'Tinggal 5 hari lagi si kecil genap 5 bulan! Segera selesaikan pesanan kue atau baju khusus bertema Bulan ke-5!', title_ja = 'ケーキは注文しましたか？🎂', body_ja = 'あと5日で赤ちゃんは生後5か月！5か月テーマの特別なケーキや衣装の注文を、今すぐすませましょう！', title_ko = '케이크 주문하셨나요? 🎂', body_ko = '딱 5일 뒤면 아기가 5개월이 돼요! 5개월 테마 케이크나 옷 주문을 지금 바로 마무리하세요!', title_nl = 'AL EEN TAART BESTELD? 🎂', body_nl = 'Over maar 5 dagen wordt je kleintje 5 maanden! Rond nu meteen je bestelling af voor een speciale taart of outfit in het thema 5 maanden!', title_pl = 'ZAMÓWIŁAŚ TORT? 🎂', body_pl = 'Już za 5 dni maluszek skończy 5 miesięcy! Od razu złóż zamówienie na specjalny tort lub strój z motywem 5. miesiąca!', title_pt = 'JÁ ENCOMENDOU O BOLO? 🎂', body_pt = 'Daqui a apenas 5 dias, o pequenino faz 5 meses! Conclua já a encomenda do bolo ou da roupa especial com o tema do 5.º mês!', title_sv = 'HAR DU BESTÄLLT TÅRTAN? 🎂', body_sv = 'Om bara 5 dagar fyller den lilla 5 månader! Slutför genast din beställning av en speciell tårta eller outfit med 5-månaderstema!', title_vi = 'MẸ ĐÃ ĐẶT BÁNH KEM CHƯA? 🎂', body_vi = 'Chỉ 5 ngày nữa là bé tròn 5 tháng! Hãy hoàn tất ngay đơn đặt bánh kem hoặc trang phục đặc biệt theo chủ đề tháng thứ 5 nhé!', title_zh = '蛋糕订好了吗？🎂', body_zh = '再过5天宝宝就满5个月啦！赶快完成5个月主题蛋糕或服装的订单吧！' WHERE id = '9ee15fcc-d37a-4d63-9556-1032868e91e8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Primeras señales rumbo a los 11 meses! 🎈', body_es = '¡Atención! Dentro de solo 20 días cumplirá 11 meses y empezaremos una gran cuenta atrás hacia su primer año. ¡Sonríe!', title_fr = 'Les premiers signes des 11 mois ! 🎈', body_fr = 'Attention ! Dans seulement 20 jours, il aura 11 mois et nous commencerons le grand compte à rebours vers ses 1 an. Souriez !', title_hi = '11 महीने की ओर पहले संकेत! 🎈', body_hi = 'ध्यान दीजिए! बस 20 दिन बाद वह 11 महीने का हो जाएगा और हम 1 साल की ओर बड़ी उलटी गिनती शुरू करेंगे। मुस्कुराइए!', title_id = 'Sinyal pertama menuju 11 bulan! 🎈', body_id = 'Perhatian! Tinggal 20 hari lagi ia genap 11 bulan, dan kita akan memulai hitung mundur besar menuju 1 tahun. Tersenyumlah!', title_ja = '11か月に向けた最初のお知らせ！🎈', body_ja = 'お知らせです！あと20日で生後11か月、そして1歳に向けた大きなカウントダウンが始まります。ほほえんで！', title_ko = '11개월을 향한 첫 신호! 🎈', body_ko = '주목! 딱 20일 뒤면 11개월이 되고, 첫돌을 향한 큰 카운트다운이 시작돼요. 웃으며 맞이해요!', title_nl = 'De eerste signalen richting 11 maanden! 🎈', body_nl = 'Let op! Over maar 20 dagen wordt hij 11 maanden en begint het grote aftellen naar de eerste verjaardag. Glimlach!', title_pl = 'Pierwsze sygnały przed 11. miesiącem! 🎈', body_pl = 'Uwaga! Już za 20 dni skończy 11 miesięcy, a my zaczniemy wielkie odliczanie do roczku. Uśmiechnij się!', title_pt = 'Primeiros sinais rumo aos 11 meses! 🎈', body_pt = 'Atenção! Daqui a apenas 20 dias faz 11 meses e vamos começar uma grande contagem decrescente para o 1.º aniversário. Sorria!', title_sv = 'De första signalerna inför 11 månader! 🎈', body_sv = 'Obs! Om bara 20 dagar fyller barnet 11 månader och vi börjar den stora nedräkningen mot 1-årsdagen. Le!', title_vi = 'Những tín hiệu đầu tiên hướng tới tháng thứ 11! 🎈', body_vi = 'Chú ý! Chỉ 20 ngày nữa là bé tròn 11 tháng và chúng mình sẽ bắt đầu đếm ngược lớn đến sinh nhật đầu tiên. Hãy mỉm cười nhé!', title_zh = '迈向11个月的第一个信号！🎈', body_zh = '注意！再过20天宝宝就满11个月了，我们将开始迈向一周岁的大倒计时。笑一个吧！' WHERE id = 'a0c5dfe0-02f0-4961-8b06-219cd57dde9d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Empiezan los preparativos del primer año! 🎈', body_es = 'Hemos dejado atrás los 11 meses. ¡Dentro de solo 30 días es su primer cumpleaños! ¿Una temática, un local o simplemente celebrarlo en casa? Empieza poco a poco a planificar.', title_fr = 'Les préparatifs des 1 an commencent ! 🎈', body_fr = 'Les 11 mois sont derrière nous. Dans seulement 30 jours, c''est son Premier Anniversaire ! Un thème, un lieu, ou simplement une fête à la maison ? Commencez doucement à vous organiser.', title_hi = 'पहले जन्मदिन की भागदौड़ शुरू! 🎈', body_hi = '11 महीने पूरे हो गए। बस 30 दिन बाद पहला जन्मदिन है! थीम, जगह, या बस घर पर जश्न? धीरे-धीरे योजना बनाना शुरू कीजिए।', title_id = 'Kesibukan 1 tahun dimulai! 🎈', body_id = 'Kita sudah melewati 11 bulan. Tinggal 30 hari lagi menuju Ulang Tahun Pertama! Tema, tempat, atau cukup dirayakan di rumah? Mulailah merencanakan perlahan.', title_ja = '1歳の準備がスタート！🎈', body_ja = '11か月を迎えました。あと30日で初めての誕生日！テーマを決める？会場を選ぶ？それともおうちでお祝い？少しずつ計画を始めましょう。', title_ko = '첫돌 준비가 시작돼요! 🎈', body_ko = '11개월을 지나왔어요. 딱 30일 뒤면 첫 생일이에요! 콘셉트, 장소, 아니면 집에서 소박하게? 천천히 계획을 시작해 보세요.', title_nl = 'De drukte voor de eerste verjaardag begint! 🎈', body_nl = '11 maanden achter de rug. Over maar 30 dagen is de Eerste Verjaardag! Een thema, een locatie of gewoon thuis vieren? Begin langzaam met plannen.', title_pl = 'Zaczyna się gorączka roczku! 🎈', body_pl = '11 miesięcy za nami. Już za 30 dni pierwsze urodziny! Motyw, miejsce czy po prostu świętowanie w domu? Powoli zacznij planować.', title_pt = 'Começa a azáfama do 1.º aniversário! 🎈', body_pt = 'Deixámos para trás os 11 meses. Daqui a apenas 30 dias é o primeiro aniversário! Uma festa temática, um espaço, ou simplesmente celebrar em casa? Comece aos poucos a planear.', title_sv = '1-årsstressen börjar! 🎈', body_sv = 'Nu har vi lagt 11 månader bakom oss. Om bara 30 dagar är det första födelsedagen! Tema, lokal eller bara ett firande hemma? Börja sakta planera.', title_vi = 'Rộn ràng chuẩn bị sinh nhật 1 tuổi! 🎈', body_vi = 'Bé đã qua tháng thứ 11. Chỉ 30 ngày nữa là Sinh nhật đầu tiên! Tiệc theo chủ đề, ở nhà hàng hay chỉ ăn mừng ở nhà? Hãy bắt đầu lên kế hoạch từ từ nhé.', title_zh = '一周岁的忙碌开始了！🎈', body_zh = '11个月已经过去了。再过30天就是宝宝的第一个生日！主题派对、找个场地，还是就在家庆祝？慢慢开始计划吧。' WHERE id = 'a70ebacf-44d0-4367-babf-09742bda8fa8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Energía para mamá 🍲', body_es = 'Para la celebración de mañana necesitas energía. Elige en Recetas saludables un tentempié que sacie y descansa.', title_fr = 'De l''énergie pour maman 🍲', body_fr = 'Vous aurez besoin d''énergie pour la fête de demain. Choisissez un en-cas nourrissant dans les Recettes saines et reposez-vous.', title_hi = 'माँ के लिए ऊर्जा 🍲', body_hi = 'कल के जश्न के लिए आपको ऊर्जा चाहिए। सेहतमंद रेसिपी से कोई पेट भरने वाला स्नैक चुनिए और आराम कीजिए।', title_id = 'Energi untuk Bunda 🍲', body_id = 'Anda butuh tenaga untuk perayaan besok. Pilih camilan yang mengenyangkan dari Resep Sehat dan beristirahatlah.', title_ja = 'ママのためのエネルギー 🍲', body_ja = '明日のお祝いのためにエネルギーが必要です。「ヘルシーレシピ」から食べごたえのあるおやつを選んで、ひと休みしましょう。', title_ko = '엄마를 위한 에너지 🍲', body_ko = '내일 기념일을 위해 에너지가 필요해요. 건강한 레시피에서 든든한 간식을 골라 쉬어 가세요.', title_nl = 'Energie voor mama 🍲', body_nl = 'Voor het jubileum van morgen heb je energie nodig. Kies uit Gezonde recepten een voedzaam tussendoortje en rust uit.', title_pl = 'Energia dla mamy 🍲', body_pl = 'Na jutrzejszy jubileusz potrzebujesz energii. Wybierz w Zdrowych przepisach sycącą przekąskę i odpocznij.', title_pt = 'Energia para a mãe 🍲', body_pt = 'Vai precisar de energia para a festa de amanhã. Escolha nas Receitas Saudáveis um lanche que sacie e descanse.', title_sv = 'Energi till mamma 🍲', body_sv = 'Du behöver energi inför morgondagens jubileum. Välj ett mättande mellanmål från Hälsosamma recept och vila.', title_vi = 'Năng lượng cho mẹ 🍲', body_vi = 'Mẹ cần năng lượng cho ngày kỷ niệm ngày mai. Hãy chọn một món ăn nhẹ no lâu từ Công thức lành mạnh và nghỉ ngơi nhé.', title_zh = '妈妈的能量 🍲', body_zh = '明天的纪念日需要精力。从健康食谱里挑一款顶饱的小食，休息一下吧。' WHERE id = 'a9165256-d8d7-431e-ac72-e7ef065f4e1f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Espíritu de unión 🥂', body_es = 'Abre el Diario de ánimo y recordad tu pareja y tú los primeros días entre risas. ¡No habéis llegado a estos 11 meses sin esfuerzo!', title_fr = 'L''esprit d''équipe 🥂', body_fr = 'Ouvrez le Journal d''humeur, remémorez-vous les premiers jours avec votre conjoint et riez ensemble. Vous n''êtes pas arrivés à ces 11 mois facilement !', title_hi = 'साथ की भावना 🥂', body_hi = 'मूड डायरी खोलिए और अपने साथी के साथ शुरुआती दिनों को याद करके हँसिए। आप इन 11 महीनों तक आसानी से नहीं पहुँचे हैं!', title_id = 'Semangat kebersamaan 🥂', body_id = 'Buka Buku Harian Suasana Hati, kenang hari-hari pertama bersama pasangan, dan tertawalah bersama. Kalian tidak sampai di bulan ke-11 ini dengan mudah!', title_ja = '支え合う心 🥂', body_ja = '「気分日記」を開いて、パートナーと最初のころを思い出して笑い合いましょう。この11か月は、決してかんたんな道のりではありませんでした！', title_ko = '함께하는 마음 🥂', body_ko = '기분 일기를 열고 배우자와 처음 며칠을 떠올리며 함께 웃어 보세요. 이 11개월은 결코 쉽게 온 게 아니에요!', title_nl = 'Samen sterk 🥂', body_nl = 'Open je Stemmingsdagboek, haal met je partner herinneringen op aan de eerste dagen en lach erom. Deze 11 maanden kwamen jullie niet zomaar door!', title_pl = 'Duch wspólnoty 🥂', body_pl = 'Otwórz Dziennik nastroju, powspominaj z partnerem pierwsze dni i pośmiejcie się razem. Nie dotarliście do tych 11 miesięcy łatwo!', title_pt = 'O espírito de união 🥂', body_pt = 'Abra o Diário de Humor, recorde os primeiros dias com o seu companheiro e riam-se juntos. Não foi fácil chegar a estes 11 meses!', title_sv = 'Samhörighetens anda 🥂', body_sv = 'Öppna Humördagboken, minns de första dagarna och skratta tillsammans med din partner. Ni har inte tagit er till de här 11 månaderna lätt!', title_vi = 'Tinh thần đồng lòng 🥂', body_vi = 'Hãy mở Nhật ký tâm trạng và cùng bố nhớ lại những ngày đầu, cười thật vui. Bố mẹ đã đi đến tháng thứ 11 này đâu có dễ dàng!', title_zh = '团结的精神 🥂', body_zh = '打开心情日记，和伴侣一起回忆最初的日子，笑一笑吧。你们走到这11个月可不容易！' WHERE id = 'aac354e5-8061-403a-8cf7-d00ce05e4093' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡11 meses cumplidos! 🎂', body_es = '¡Enhorabuena! ¡Han pasado 11 meses justos desde el parto! Elige ya el sticker de 11 meses en la Sesión de fotos del bebé y comparte esta alegría en la Comunidad Anacan.', title_fr = 'Pile 11 mois ! 🎂', body_fr = 'Félicitations ! Cela fait pile 11 mois depuis la naissance ! Choisissez tout de suite le sticker 11 mois dans la Séance photo bébé et partagez cette joie dans la Communauté Anacan !', title_hi = 'पूरे 11 महीने! 🎂', body_hi = 'बधाई हो! जन्म के बाद पूरे 11 महीने बीत गए! तुरंत बेबी फ़ोटोशूट में 11 महीने का स्टिकर चुनिए और यह खुशी Anacan कम्युनिटी में शेयर कीजिए!', title_id = 'Genap 11 bulan! 🎂', body_id = 'Selamat! Sudah tepat 11 bulan sejak kelahirannya! Pilih stiker 11 bulan di Sesi Foto Bayi sekarang juga dan bagikan kebahagiaan ini di Komunitas Anacan!', title_ja = '祝・11か月！🎂', body_ja = 'おめでとうございます！生まれてからちょうど11か月！すぐに「ベビーフォトセッション」で11か月のステッカーを選んで、この喜びをAnacanコミュニティでシェアしましょう！', title_ko = '드디어 11개월! 🎂', body_ko = '축하해요! 태어난 지 딱 11개월이 지났어요! 지금 바로 아기 사진 촬영에서 11개월 스티커를 골라 이 기쁨을 Anacan 커뮤니티에 공유하세요!', title_nl = 'Precies 11 maanden! 🎂', body_nl = 'Gefeliciteerd! Sinds de geboorte zijn er precies 11 maanden voorbij! Kies meteen de 11-maandensticker in Babyfotoshoot en deel deze vreugde in de Anacan Community!', title_pl = 'Równo 11 miesięcy! 🎂', body_pl = 'Gratulacje! Od porodu minęło równo 11 miesięcy! Od razu wybierz w Sesji zdjęciowej dziecka naklejkę na 11 miesięcy i podziel się tą radością w Społeczności Anacan!', title_pt = '11 meses feitos! 🎂', body_pt = 'Parabéns! Passaram 11 meses certos desde o nascimento! Escolha já o autocolante dos 11 meses na Sessão Fotográfica do Bebé e partilhe esta alegria na Comunidade Anacan!', title_sv = '11 månader! 🎂', body_sv = 'Grattis! Det har gått precis 11 månader sedan förlossningen! Välj direkt 11-månaders klistermärket i Babyfotografering och dela glädjen i Anacans Community!', title_vi = 'Tròn 11 tháng! 🎂', body_vi = 'Chúc mừng! Đã tròn 11 tháng kể từ ngày bé chào đời! Hãy chọn ngay nhãn dán 11 tháng trong Chụp ảnh cho bé và chia sẻ niềm vui này trong Cộng đồng Anacan!', title_zh = '满11个月啦！🎂', body_zh = '恭喜！宝宝出生已经整整11个月了！马上在宝宝写真里选一张11个月贴纸，把这份喜悦分享到Anacan社区吧！' WHERE id = 'ad9c3e79-16bb-44a7-9f37-6f5935a4494c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡RUMBO AL 5.º MES! 🎂', body_es = '¡Atención! Dentro de solo 10 días llega el gran día: ¡cumple 5 meses! ¿No te habrás olvidado de encargar una tarta especial o de planear una temática? ¡Empieza ya los preparativos!', title_fr = 'BIENTÔT 5 MOIS ! 🎂', body_fr = 'Attention ! Dans seulement 10 jours, c''est le grand jour : les 5 mois ! Vous n''avez pas oublié de commander un gâteau spécial ou de prévoir un thème ? Commencez les préparatifs dès maintenant !', title_hi = '5वाँ महीना करीब! 🎂', body_hi = 'ध्यान दीजिए! बस 10 दिन बाद बड़ा दिन है, पूरे 5 महीने! खास केक ऑर्डर करना या थीम प्लान करना तो नहीं भूलीं? अभी से तैयारी शुरू कीजिए!', title_id = 'MENUJU BULAN KE-5! 🎂', body_id = 'Perhatian! Tinggal 10 hari lagi menuju hari besar: genap 5 bulan! Sudah ingat memesan kue khusus atau merencanakan tema? Mulai persiapannya dari sekarang!', title_ja = 'もうすぐ5か月！🎂', body_ja = 'お知らせです！あと10日で大切な日、5か月のお祝いです！特別なケーキの注文やテーマの準備、忘れていませんか？今から準備を始めましょう！', title_ko = '곧 5개월! 🎂', body_ko = '주목! 딱 10일 뒤면 큰 날, 5개월이 돼요! 특별한 케이크 주문이나 콘셉트 계획을 잊지 않으셨죠? 지금부터 준비를 시작하세요!', title_nl = 'OP NAAR 5 MAANDEN! 🎂', body_nl = 'Let op! Over maar 10 dagen is de grote dag: 5 maanden! Heb je al een speciale taart besteld of een thema gepland? Begin nu al met de voorbereidingen!', title_pl = 'ZBLIŻA SIĘ 5. MIESIĄC! 🎂', body_pl = 'Uwaga! Już za 10 dni wielki dzień: mija 5. miesiąc! Nie zapomniałaś zamówić specjalnego tortu albo zaplanować motywu? Zacznij przygotowania już teraz!', title_pt = 'RUMO AO 5.º MÊS! 🎂', body_pt = 'Atenção! Daqui a apenas 10 dias é o grande dia: faz 5 meses! Não se esqueceu de encomendar um bolo especial ou de planear uma festa temática? Comece já os preparativos!', title_sv = 'SNART 5 MÅNADER! 🎂', body_sv = 'Obs! Om bara 10 dagar är det den stora dagen, barnet fyller 5 månader! Har du väl inte glömt att beställa en speciell tårta eller planera ett tema? Börja förbereda redan nu!', title_vi = 'SẮP TRÒN 5 THÁNG! 🎂', body_vi = 'Chú ý! Chỉ 10 ngày nữa là đến ngày trọng đại: bé tròn 5 tháng! Mẹ không quên đặt bánh kem đặc biệt hay lên kế hoạch tiệc theo chủ đề chứ? Bắt đầu chuẩn bị ngay từ bây giờ nhé!', title_zh = '快满5个月啦！🎂', body_zh = '注意！再过10天就是大日子，宝宝满5个月！别忘了订个特别的蛋糕或策划一个主题庆祝。现在就开始准备吧！' WHERE id = 'b25cbe8a-634a-4863-b56c-19ebbb878905' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡8 meses increíbles! 🎉🎂', body_es = '¡ENHORABUENA! Lleváis justo {milestone_days} días recorriendo juntos este camino milagroso. Ya tiene 8 meses enteros. ¡Celebra ya este día especial y compártelo con orgullo en la Comunidad Anacan!', title_fr = '8 mois magnifiques ! 🎉🎂', body_fr = 'FÉLICITATIONS ! Cela fait exactement {milestone_days} jours que vous avancez ensemble sur ce chemin merveilleux ! Il a maintenant pile 8 mois. Célébrez tout de suite ce jour spécial et partagez-le fièrement dans la Communauté Anacan !', title_hi = 'शानदार 8 महीने! 🎉🎂', body_hi = 'बधाई हो! पूरे {milestone_days} दिन से आप साथ मिलकर यह चमत्कारी सफ़र तय कर रहे हैं! वह अब पूरे 8 महीने का है। तुरंत इस खास दिन का जश्न मनाइए और Anacan कम्युनिटी में गर्व से शेयर कीजिए!', title_id = '8 bulan yang luar biasa! 🎉🎂', body_id = 'SELAMAT! Sudah tepat {milestone_days} hari kalian menapaki perjalanan ajaib ini bersama! Kini ia genap 8 bulan. Rayakan hari istimewa ini dan bagikan dengan bangga di Komunitas Anacan!', title_ja = 'すばらしい8か月！🎉🎂', body_ja = 'おめでとうございます！ちょうど{milestone_days}日、この奇跡の道を一緒に歩んできました！赤ちゃんはもうまる8か月。すぐにこの特別な日をお祝いして、Anacanコミュニティで誇らしくシェアしましょう！', title_ko = '멋진 8개월! 🎉🎂', body_ko = '축하해요! 꼬박 {milestone_days}일 동안 이 기적 같은 길을 함께 걸어왔어요! 아기는 이제 딱 8개월이에요. 지금 바로 이 특별한 날을 축하하고 Anacan 커뮤니티에 자랑스럽게 공유하세요!', title_nl = 'Geweldige 8 maanden! 🎉🎂', body_nl = 'GEFELICITEERD! Al precies {milestone_days} dagen lopen jullie samen deze wonderlijke weg! Je kleintje is nu precies 8 maanden. Vier deze bijzondere dag meteen en deel hem trots in de Anacan Community!', title_pl = 'Wspaniałe 8 miesięcy! 🎉🎂', body_pl = 'GRATULACJE! Od równych {milestone_days} dni razem idziecie tą cudowną drogą! Maluszek ma już równo 8 miesięcy. Od razu uczcij ten wyjątkowy dzień i z dumą podziel się nim w Społeczności Anacan!', title_pt = '8 meses fantásticos! 🎉🎂', body_pt = 'PARABÉNS! Há exatamente {milestone_days} dias que percorrem juntos este caminho milagroso! Ele já tem 8 meses certos. Celebre já este dia especial e partilhe-o com orgulho na Comunidade Anacan!', title_sv = 'Fantastiska 8 månader! 🎉🎂', body_sv = 'GRATTIS! I precis {milestone_days} dagar har ni gått den här mirakulösa vägen tillsammans! Barnet är nu hela 8 månader. Fira den speciella dagen direkt och dela den stolt i Anacans Community!', title_vi = '8 tháng tuyệt vời! 🎉🎂', body_vi = 'CHÚC MỪNG! Đã tròn {milestone_days} ngày cả nhà cùng nhau bước trên hành trình kỳ diệu này! Bé đã tròn 8 tháng. Hãy ăn mừng ngày đặc biệt này ngay và tự hào chia sẻ trong Cộng đồng Anacan!', title_zh = '精彩的8个月！🎉🎂', body_zh = '恭喜！你们一起走过这段奇迹般的旅程已经整整{milestone_days}天了！宝宝已经满8个月啦。马上庆祝这个特别的日子，骄傲地分享到Anacan社区吧！' WHERE id = 'b4769acb-82a0-480e-b58f-3017d46b37a4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Solo 5 días para los 10 meses! 🎂', body_es = '¡Queda muy poco para la gran cifra! Es el momento perfecto para preparar la tarta y la ropa de los 10 meses. ¡Os acercáis paso a paso a su primer cumpleaños!', title_fr = 'Plus que 5 jours avant les 10 mois ! 🎂', body_fr = 'Le grand chiffre approche ! C''est le moment idéal pour préparer le gâteau et les tenues des 10 mois. Vous vous rapprochez pas à pas de son premier anniversaire !', title_hi = '10 महीने में बस 5 दिन! 🎂', body_hi = 'बड़े आँकड़े में बहुत कम समय बचा है! 10 महीने का केक और कपड़े तैयार करने का यही सही समय है। आप कदम-दर-कदम पहले जन्मदिन के करीब पहुँच रहे हैं!', title_id = 'Tinggal 5 hari menuju 10 bulan! 🎂', body_id = 'Angka besar sudah sangat dekat! Saatnya menyiapkan kue dan baju 10 bulan. Selangkah demi selangkah Anda makin dekat ke ulang tahun pertama!', title_ja = '10か月まであと5日！🎂', body_ja = '大きな数字まであと少し！10か月のケーキと服を準備するのにぴったりのタイミングです。1歳の誕生日に一歩ずつ近づいています！', title_ko = '10개월까지 딱 5일! 🎂', body_ko = '큰 숫자가 코앞이에요! 10개월 케이크와 옷을 준비하기 딱 좋은 때예요. 첫 생일에 한 걸음씩 다가가고 있어요!', title_nl = 'Nog maar 5 dagen tot 10 maanden! 🎂', body_nl = 'Het grote getal is bijna daar! Hét moment om de taart en de kleertjes voor 10 maanden klaar te maken. Stap voor stap komen jullie dichter bij de eerste verjaardag!', title_pl = 'Tylko 5 dni do 10 miesięcy! 🎂', body_pl = 'Do wielkiej liczby zostało bardzo niewiele! To idealny moment, by przygotować tort i ubranka na 10 miesięcy. Krok po kroku zbliżacie się do pierwszych urodzin!', title_pt = 'SÓ FALTAM 5 DIAS PARA OS 10 MESES! 🎂', body_pt = 'Falta muito pouco para o grande número! É a altura ideal para preparar o bolo e a roupa dos 10 meses. Estão a aproximar-se, passo a passo, do primeiro aninho!', title_sv = 'Bara 5 dagar kvar till 10 månader! 🎂', body_sv = 'Det är väldigt nära den stora siffran nu! Nu är det perfekt tid att förbereda 10-månaderstårtan och kläderna. Steg för steg närmar ni er första födelsedagen!', title_vi = 'Chỉ 5 ngày nữa là tròn 10 tháng! 🎂', body_vi = 'Sắp đến con số lớn rồi! Đây là lúc chuẩn bị bánh kem và trang phục mừng 10 tháng. Bố mẹ đang từng bước tiến gần đến sinh nhật đầu tiên!', title_zh = '距离10个月只剩5天！🎂', body_zh = '大数字就快到了！现在正是准备10个月蛋糕和服装的好时机。你们正一步步接近一周岁！' WHERE id = 'b67edfc6-e141-41a3-866c-78583fe5c77b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Solo faltan 15 días para el primer año! 🎈', body_es = '¡Soplan vientos de nostalgia! ¿Recuerdas aquel primer día al salir de la maternidad? ¡Y ahora preparáis su primer año! Pon su primera foto y la de ahora una al lado de la otra en la Sesión de fotos del bebé.', title_fr = 'Plus que 15 jours avant ses 1 an ! 🎈', body_fr = 'Un vent de nostalgie souffle ! Vous vous souvenez du premier jour où vous avez quitté la maternité ? Et maintenant, vous préparez ses 1 an ! Dans la Séance photo bébé, placez sa première photo à côté de celle d''aujourd''hui !', title_hi = 'पहले जन्मदिन में बस 15 दिन बाकी! 🎈', body_hi = 'पुरानी यादों की हवा चल रही है! अस्पताल से निकलने का वह पहला दिन याद है? और अब आप पहले जन्मदिन की तैयारी कर रही हैं! बेबी फ़ोटोशूट में उसकी पहली और अभी की तस्वीर साथ-साथ रखिए!', title_id = 'Tinggal 15 hari menuju 1 tahun! 🎈', body_id = 'Angin nostalgia berembus! Ingat hari pertama Anda pulang dari rumah sakit bersalin? Kini Anda bersiap menyambut 1 tahun! Sandingkan foto pertamanya dengan foto sekarang di Sesi Foto Bayi!', title_ja = '1歳まであと15日！🎈', body_ja = 'なつかしい気持ちがこみあげます！産院から帰ったあの最初の日を覚えていますか？今では1歳の準備をしています！「ベビーフォトセッション」で、最初の写真と今の写真を並べてみましょう！', title_ko = '첫돌까지 딱 15일! 🎈', body_ko = '추억의 바람이 불어와요! 산부인과에서 퇴원하던 첫날이 기억나나요? 이제 첫돌을 준비하고 있어요! 아기 사진 촬영에서 처음 사진과 지금 사진을 나란히 놓아 보세요!', title_nl = 'Nog maar 15 dagen tot de eerste verjaardag! 🎈', body_nl = 'Er waait een nostalgisch briesje! Weet je nog die eerste dag dat jullie het ziekenhuis verlieten? En nu maken jullie je klaar voor de eerste verjaardag! Zet in Babyfotoshoot zijn eerste en zijn huidige foto naast elkaar!', title_pl = 'Do roczku zostało tylko 15 dni! 🎈', body_pl = 'Wieje wiatr nostalgii! Pamiętasz ten pierwszy dzień, gdy wychodziłaś ze szpitala? A teraz szykujesz się na roczek! Ułóż w Sesji zdjęciowej dziecka jego pierwsze i obecne zdjęcie obok siebie!', title_pt = 'SÓ FALTAM 15 DIAS PARA O 1.º ANIVERSÁRIO! 🎈', body_pt = 'Sopram ventos de nostalgia! Lembra-se do primeiro dia em que saíram da maternidade? E agora estão a preparar o 1.º aniversário! Ponha lado a lado na Sessão Fotográfica do Bebé a primeira foto e a de agora!', title_sv = 'Bara 15 dagar kvar till 1 år! 🎈', body_sv = 'Nostalgins vindar blåser! Minns du den första dagen när ni lämnade BB? Och nu förbereder ni 1-årsdagen! Lägg barnets första bild och en bild från i dag bredvid varandra i Babyfotografering!', title_vi = 'Chỉ còn 15 ngày nữa là tròn 1 tuổi! 🎈', body_vi = 'Nỗi nhớ ùa về! Mẹ còn nhớ ngày đầu tiên rời nhà hộ sinh không? Giờ mẹ đã chuẩn bị mừng bé tròn 1 tuổi! Hãy đặt tấm ảnh đầu tiên và tấm ảnh bây giờ của bé cạnh nhau trong Chụp ảnh cho bé!', title_zh = '距离一周岁只剩15天！🎈', body_zh = '怀旧之风吹起来了！还记得你们从医院回家的第一天吗？现在你们正在准备一周岁了！在宝宝写真里把宝宝的第一张照片和现在的照片放在一起吧！' WHERE id = 'b86239c1-4a1c-48b3-b49a-3fd4a012ebae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Atención! ¡Solo faltan 10 días para los 9 meses! 🎂', body_es = 'Es el momento de ir pensando en una pequeña tarta o una temática familiar para este aniversario especial.', title_fr = 'Attention ! Plus que 10 jours avant les 9 mois ! 🎂', body_fr = 'C''est le moment de penser dès maintenant à un petit gâteau ou à un thème familial pour cet anniversaire spécial.', title_hi = 'ध्यान दीजिए! 9 महीने पूरे होने में बस 10 दिन बाकी! 🎂', body_hi = 'इस खास पड़ाव के लिए अभी से छोटे केक या पारिवारिक थीम के बारे में सोचने का समय है।', title_id = 'Perhatian! Tinggal 10 hari lagi menuju genap 9 bulan! 🎂', body_id = 'Saatnya memikirkan kue kecil atau tema keluarga untuk perayaan istimewa ini dari sekarang.', title_ja = 'お知らせ！9か月まであと10日！🎂', body_ja = 'この特別な記念日のために、小さなケーキや家族でのお祝いのテーマを今から考えておきましょう。', title_ko = '주목! 9개월까지 딱 10일 남았어요! 🎂', body_ko = '이 특별한 기념일을 위해 작은 케이크나 가족 콘셉트를 지금부터 생각해 볼 때예요.', title_nl = 'Let op! Nog maar 10 dagen tot 9 maanden!  🎂', body_nl = 'Tijd om nu al na te denken over een kleine taart of een familiethema voor dit bijzondere jubileum.', title_pl = 'Uwaga! Do 9 miesięcy zostało tylko 10 dni! 🎂', body_pl = 'To dobry moment, by już teraz pomyśleć o małym torcie lub rodzinnym motywie na ten wyjątkowy jubileusz.', title_pt = 'Atenção! Faltam só 10 dias para os 9 meses!  🎂', body_pt = 'É altura de pensar desde já num pequeno bolo ou numa festa em família para esta data especial.', title_sv = 'Obs! Bara 10 dagar kvar till 9 månader!  🎂', body_sv = 'Nu är det dags att fundera på en liten tårta eller ett familjetema till det här speciella jubileet.', title_vi = 'Chú ý! Chỉ còn 10 ngày nữa là bé tròn 9 tháng!  🎂', body_vi = 'Đây là lúc nghĩ đến một chiếc bánh kem nhỏ hay một chủ đề gia đình cho dịp kỷ niệm đặc biệt này.', title_zh = '注意！距离满9个月只剩10天！🎂', body_zh = '是时候为这个特别的纪念日考虑一个小蛋糕或家庭庆祝主题了。' WHERE id = 'bda4f100-98ac-4f09-9fa3-a50d4e42eedd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡FALTAN 10 DÍAS PARA EL MEDIO AÑO! 🎂', body_es = '¡Prepárate! Dentro de justo 10 días tu peque cumple 6 meses, ¡medio año! Es el momento perfecto para encargar la tarta de medio año y elegir un conjunto especial.', title_fr = 'PLUS QUE 10 JOURS AVANT LES 6 MOIS ! 🎂', body_fr = 'Préparez-vous ! Dans pile 10 jours, votre petit aura 6 mois, son demi-anniversaire ! C''est le moment idéal pour commander le gâteau et choisir une tenue spéciale !', title_hi = 'आधे साल में 10 दिन बाकी! 🎂', body_hi = 'तैयार हो जाइए! ठीक 10 दिन बाद आपका नन्हा 6 महीने, यानी आधे साल का हो जाएगा! हाफ़-बर्थडे केक ऑर्डर करने और खास कपड़े चुनने का यही सही समय है!', title_id = '10 HARI LAGI MENUJU SETENGAH TAHUN! 🎂', body_id = 'Bersiaplah! Tepat 10 hari lagi si kecil genap 6 bulan, alias setengah tahun! Inilah saat yang tepat untuk memesan kue setengah tahun dan memilih baju istimewa!', title_ja = 'ハーフバースデーまであと10日！🎂', body_ja = '準備しましょう！ちょうど10日後、赤ちゃんは生後6か月、ハーフバースデーを迎えます！ハーフバースデーケーキの注文や特別な衣装を選ぶのにぴったりのタイミングです！', title_ko = '반년까지 10일! 🎂', body_ko = '준비하세요! 딱 10일 뒤면 아기가 6개월, 즉 반년이 돼요! 반년 케이크를 주문하고 특별한 옷을 고르기에 딱 좋은 때예요!', title_nl = 'NOG 10 DAGEN TOT EEN HALF JAAR! 🎂', body_nl = 'Maak je klaar! Over precies 10 dagen wordt je kleintje 6 maanden, een half jaar! Het is hét moment om een halfjaartaart te bestellen en een speciale outfit te kiezen!', title_pl = 'DO PÓŁ ROCZKU ZOSTAŁO 10 DNI! 🎂', body_pl = 'Przygotuj się! Za równe 10 dni maluszek skończy 6 miesięcy, czyli pół roczku! To idealny moment, by zamówić tort na pół roczku i wybrać specjalny strój!', title_pt = 'FALTAM 10 DIAS PARA O MEIO ANO! 🎂', body_pt = 'Prepare-se! Daqui a 10 dias certos, o pequenino faz 6 meses, ou seja, meio ano! É a altura ideal para encomendar o bolo do meio ano e escolher uma roupa especial!', title_sv = '10 DAGAR KVAR TILL HALVÅRET! 🎂', body_sv = 'Gör er redo! Om precis 10 dagar fyller den lilla 6 månader, alltså ett halvår! Nu är det perfekt tid att beställa halvårstårtan och välja speciella kläder!', title_vi = 'CÒN 10 NGÀY NỮA LÀ TRÒN NỬA TUỔI! 🎂', body_vi = 'Chuẩn bị nhé! Đúng 10 ngày nữa bé tròn 6 tháng, tức là tròn nửa tuổi! Đây là lúc thích hợp để đặt bánh kem mừng nửa tuổi và chọn trang phục đặc biệt!', title_zh = '距离半岁还有10天！🎂', body_zh = '准备好！整整10天后，宝宝就满6个月，也就是半岁啦！现在正是订半岁蛋糕、挑选特别服装的好时机！' WHERE id = 'c09a3abb-6f75-4a5a-99d6-fbc4e4f2425f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora del masaje 💆‍♂️', body_es = 'Cuando tu bebé se duerma, daos un masaje de hombros tu pareja y tú para soltar el estrés del día. ¡Tenéis que estar con energía para la bonita victoria de mañana!', title_fr = 'L''heure du massage 💆‍♂️', body_fr = 'Quand bébé dort, offrez-vous un massage des épaules mutuel avec votre conjoint pour évacuer le stress de la journée. Il faut être en forme pour la belle victoire de demain !', title_hi = 'मालिश का समय 💆‍♂️', body_hi = 'बच्चे के सोने के बाद दिन का तनाव उतारने के लिए अपने साथी के साथ एक-दूसरे के कंधों की मालिश कीजिए। कल की खूबसूरत जीत के लिए ऊर्जा से भरपूर रहिए!', title_id = 'Waktu pijat 💆‍♂️', body_id = 'Setelah si kecil tidur, saling pijat bahu bersama pasangan untuk melepas stres hari ini. Pastikan Anda bertenaga untuk kemenangan indah besok!', title_ja = 'マッサージタイム 💆‍♂️', body_ja = '赤ちゃんが寝たら、1日のストレスを流すためにパートナーと肩をもみ合いましょう。明日のすてきな勝利のために、元気をためておいて！', title_ko = '마사지 시간 💆‍♂️', body_ko = '아이가 잠든 뒤 배우자와 서로 어깨 마사지를 해 주며 하루의 스트레스를 풀어 보세요. 내일의 멋진 승리를 위해 꼭 기운을 충전하세요!', title_nl = 'Tijd voor een massage 💆‍♂️', body_nl = 'Geef elkaar als je baby slaapt een schoudermassage om de stress van de dag kwijt te raken. Zorg dat je energie hebt voor de mooie overwinning van morgen!', title_pl = 'Czas na masaż 💆‍♂️', body_pl = 'Gdy maluszek zaśnie, zróbcie sobie z partnerem nawzajem masaż ramion, by zrzucić stres całego dnia. Na jutrzejsze piękne zwycięstwo koniecznie musisz mieć energię!', title_pt = 'Hora da massagem 💆‍♂️', body_pt = 'Depois de o bebé adormecer, façam uma massagem nos ombros um ao outro para libertar o stress do dia. Tenham energia para a bela vitória de amanhã!', title_sv = 'Massagedags 💆‍♂️', body_sv = 'När barnet har somnat, ge varandra en axelmassage tillsammans med din partner för att släppa dagens stress. Se till att ha energi inför morgondagens fina seger!', title_vi = 'Giờ mát-xa 💆‍♂️', body_vi = 'Sau khi bé ngủ, hãy cùng bố mát-xa vai cho nhau để xua tan căng thẳng trong ngày. Nhất định phải tràn đầy năng lượng cho chiến thắng tuyệt vời ngày mai!', title_zh = '按摩时间 💆‍♂️', body_zh = '宝宝睡着后，和伴侣互相按按肩膀，释放一天的压力。为了明天美好的胜利，一定要养足精神！' WHERE id = 'c96d26d0-5fe0-42f4-a1a7-44abd71bd8d8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mañana cumple 8 meses! 📸', body_es = '¿Preparada? ¡Mañana es el gran día! ¡8 meses justos! Libera memoria en el móvil, mañana necesitarás mucho espacio para la Sesión de fotos del bebé. Plancha ya la ropa.', title_fr = 'Demain, 8 mois ! 📸', body_fr = 'Prête ? Demain, c''est le grand jour ! Pile 8 mois ! Libérez de la mémoire sur votre téléphone, il faudra beaucoup de place demain pour la Séance photo bébé. Repassez les tenues dès maintenant.', title_hi = 'कल 8 महीने! 📸', body_hi = 'तैयार हैं? कल बड़ा दिन है! पूरे 8 महीने! फ़ोन की मेमोरी खाली कीजिए, कल बेबी फ़ोटोशूट के लिए खूब जगह चाहिए होगी। कपड़े अभी से इस्त्री कर लीजिए।', title_id = 'Besok genap 8 bulan! 📸', body_id = 'Siap? Besok hari besar! Tepat 8 bulan! Kosongkan memori ponsel, besok Anda butuh banyak ruang untuk Sesi Foto Bayi. Setrika bajunya dari sekarang.', title_ja = '明日で8か月！📸', body_ja = '準備はいい？明日は大切な日、ちょうど8か月！スマホの容量をあけておきましょう。明日の「ベビーフォトセッション」には、たくさんの空きが必要です。服は今のうちにアイロンを。', title_ko = '내일이면 8개월! 📸', body_ko = '준비됐나요? 내일이 큰 날이에요! 딱 8개월! 휴대폰 저장 공간을 비워 두세요, 내일 아기 사진 촬영에 공간이 많이 필요할 거예요. 옷은 지금 미리 다려 두세요.', title_nl = 'Morgen 8 maanden! 📸', body_nl = 'Klaar? Morgen is de grote dag! Precies 8 maanden! Maak ruimte vrij op je telefoon, morgen heb je veel plek nodig voor Babyfotoshoot. Strijk de kleertjes nu alvast.', title_pl = 'Jutro 8 miesięcy! 📸', body_pl = 'Gotowa? Jutro wielki dzień! Równo 8 miesięcy! Wyczyść pamięć telefonu, jutro do Sesji zdjęciowej dziecka potrzeba będzie mnóstwo miejsca. Już teraz wyprasuj ubranka.', title_pt = 'Amanhã faz 8 meses! 📸', body_pt = 'Está preparada? Amanhã é o grande dia! 8 meses certos! Liberte memória no telemóvel, amanhã vai precisar de muito espaço para a Sessão Fotográfica do Bebé. Passe já a roupa a ferro.', title_sv = 'I morgon är det 8 månader! 📸', body_sv = 'Är ni redo? I morgon är den stora dagen! Precis 8 månader! Rensa telefonens minne, i morgon behövs massor av plats för Babyfotografering. Stryk kläderna redan nu.', title_vi = 'Ngày mai bé tròn 8 tháng! 📸', body_vi = 'Sẵn sàng chưa? Ngày mai là ngày trọng đại! Tròn 8 tháng! Hãy dọn bộ nhớ điện thoại, ngày mai sẽ cần nhiều chỗ cho Chụp ảnh cho bé. Là sẵn quần áo từ bây giờ nhé.', title_zh = '明天就满8个月！📸', body_zh = '准备好了吗？明天就是大日子！整整8个月！清理一下手机内存，明天的宝宝写真需要很多空间。现在就把衣服熨好吧。' WHERE id = 'd3b0f81b-e9b4-4b00-883d-9e8bb86131bc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Solo 5 días para el primer año! 🎈', body_es = '¡La cuenta atrás está a punto de terminar! ¡Su primer cumpleaños! Adornos, pequeños invitados... Entra en la Comunidad Anacan y pide a otras mamás ideas creativas para la fiesta del primer año.', title_fr = 'Plus que 5 jours avant ses 1 an ! 🎈', body_fr = 'Le compte à rebours touche à sa fin ! Son Premier Anniversaire ! Décorations, petits invités... Rejoignez la Communauté Anacan et trouvez auprès des mamans des idées créatives pour la fête des 1 an.', title_hi = '1 साल में बस 5 दिन! 🎈', body_hi = 'उलटी गिनती खत्म होने वाली है! पहला जन्मदिन! सजावट, नन्हे मेहमान... Anacan कम्युनिटी में आइए और माँओं से पहले जन्मदिन की पार्टी के लिए रचनात्मक आइडिया पाइए।', title_id = 'Tinggal 5 hari menuju 1 tahun! 🎈', body_id = 'Hitung mundur hampir selesai! Ulang Tahun Pertama! Dekorasi, tamu-tamu kecil... Masuklah ke Komunitas Anacan dan dapatkan ide kreatif dari para ibu untuk pesta 1 tahun.', title_ja = '1歳まであと5日！🎈', body_ja = 'カウントダウンももうすぐ終わり！初めての誕生日！飾りつけ、小さなゲストたち...Anacanコミュニティに参加して、ママたちから1歳パーティーのクリエイティブなアイデアをもらいましょう。', title_ko = '첫돌까지 딱 5일! 🎈', body_ko = '카운트다운이 거의 끝났어요! 첫 생일이에요! 장식, 꼬마 손님들... Anacan 커뮤니티에 들어가 엄마들에게서 첫돌 파티를 위한 창의적인 아이디어를 받아 보세요.', title_nl = 'Nog maar 5 dagen tot de eerste verjaardag! 🎈', body_nl = 'Het aftellen is bijna voorbij! De Eerste Verjaardag! Versiering, kleine gasten... Ga naar de Anacan Community en krijg van moeders creatieve ideeën voor het feestje van 1 jaar.', title_pl = 'Tylko 5 dni do roczku! 🎈', body_pl = 'Odliczanie dobiega końca! Pierwsze urodziny! Dekoracje, mali goście... Zajrzyj do Społeczności Anacan i zbierz od mam kreatywne pomysły na przyjęcie z okazji roczku.', title_pt = 'SÓ FALTAM 5 DIAS PARA O 1.º ANIVERSÁRIO! 🎈', body_pt = 'A contagem decrescente está quase a terminar! O primeiro aniversário! Decorações, pequenos convidados... Entre na Comunidade Anacan e receba das mães ideias criativas para a festa do 1.º ano.', title_sv = 'Bara 5 dagar kvar till 1 år! 🎈', body_sv = 'Nedräkningen är nästan slut! Första födelsedagen! Dekorationer, små gäster... Gå in i Anacans Community och få kreativa idéer till 1-årsfesten från andra mammor.', title_vi = 'Chỉ còn 5 ngày nữa là tròn 1 tuổi! 🎈', body_vi = 'Cuộc đếm ngược sắp kết thúc! Sinh nhật đầu tiên! Đồ trang trí, những vị khách nhí... Hãy vào Cộng đồng Anacan để nhận những ý tưởng sáng tạo cho bữa tiệc 1 tuổi từ các bà mẹ.', title_zh = '距离一周岁只剩5天！🎈', body_zh = '倒计时快结束了！第一个生日！装饰、小客人……进入Anacan社区，从妈妈们那里获取一周岁派对的创意点子吧。' WHERE id = 'd58a373d-b464-4fff-9b8e-74a104499618' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡10 meses y {milestone_days} días increíbles! 🎉', body_es = '¡Enhorabuena! Lleváis justo {milestone_days} días, 10 meses enteros, criando este milagro.', title_fr = '10 mois et {milestone_days} jours magnifiques ! 🎉', body_fr = 'Félicitations ! Cela fait exactement {milestone_days} jours, pile 10 mois, que vous élevez ce petit miracle.', title_hi = 'शानदार 10 महीने और {milestone_days} दिन! 🎉', body_hi = 'बधाई हो! पूरे {milestone_days} दिन, यानी पूरे 10 महीने से आप इस चमत्कार को बड़ा कर रही हैं।', title_id = '10 bulan dan {milestone_days} hari yang luar biasa! 🎉', body_id = 'Selamat! Sudah tepat {milestone_days} hari, genap 10 bulan, Anda membesarkan keajaiban ini.', title_ja = 'すばらしい10か月と{milestone_days}日！🎉', body_ja = 'おめでとうございます！ちょうど{milestone_days}日、まる10か月、この奇跡を育ててきました。', title_ko = '멋진 10개월, 그리고 {milestone_days}일! 🎉', body_ko = '축하해요! 꼬박 {milestone_days}일, 딱 10개월 동안 이 기적을 키워 왔어요.', title_nl = 'Geweldige 10 maanden en {milestone_days} dagen! 🎉', body_nl = 'Gefeliciteerd! Al precies {milestone_days} dagen, 10 hele maanden, voeden jullie dit wonder op.', title_pl = 'Wspaniałe 10 miesięcy i {milestone_days} dni! 🎉', body_pl = 'Gratulacje! Od równych {milestone_days} dni, pełnych 10 miesięcy, wychowujesz ten cud.', title_pt = '10 meses e {milestone_days} dias fantásticos! 🎉', body_pt = 'Parabéns! Há exatamente {milestone_days} dias, 10 meses certos, que cria este milagre.', title_sv = 'Fantastiska 10 månader och {milestone_days} dagar! 🎉', body_sv = 'Grattis! I precis {milestone_days} dagar, hela 10 månader, har du fått det här miraklet att växa.', title_vi = '10 tháng và {milestone_days} ngày tuyệt vời! 🎉', body_vi = 'Chúc mừng! Đã tròn {milestone_days} ngày, trọn 10 tháng bố mẹ nuôi lớn phép màu này.', title_zh = '精彩的10个月和{milestone_days}天！🎉', body_zh = '恭喜！你已经养育这个奇迹整整{milestone_days}天，满满10个月了。' WHERE id = 'dd2f968e-d28b-4ab1-9758-59cda94c35f6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡{milestone_days} días de emoción! 🌟', body_es = '¡Mañana es un gran aniversario doble! ¡10 meses y {milestone_days} días! Crea un pequeño ambiente de fiesta en casa y libera memoria en el móvil.', title_fr = '{milestone_days} jours d''émotions ! 🌟', body_fr = 'Demain, c''est un grand double anniversaire ! À la fois 10 mois et {milestone_days} jours ! Créez une petite ambiance de fête à la maison et libérez de la mémoire sur votre téléphone.', title_hi = '{milestone_days} दिनों का उत्साह! 🌟', body_hi = 'कल बड़ा, दोहरा जश्न है! 10 महीने भी और {milestone_days} दिन भी! घर में छोटा सा जश्न का माहौल बनाइए और फ़ोन की मेमोरी खाली कीजिए।', title_id = 'Debaran {milestone_days} hari! 🌟', body_id = 'Besok perayaan besar, dua sekaligus! Genap 10 bulan dan {milestone_days} hari! Ciptakan suasana pesta kecil di rumah dan kosongkan memori ponsel Anda.', title_ja = '{milestone_days}日のワクワク！🌟', body_ja = '明日は大きなダブル記念日！10か月と{milestone_days}日！おうちに小さなお祝いムードをつくって、スマホの容量をあけておきましょう。', title_ko = '{milestone_days}일의 설렘! 🌟', body_ko = '내일은 크고 겹경사인 기념일이에요! 10개월이자 {milestone_days}일! 집에 작은 축제 분위기를 만들고 휴대폰 저장 공간을 비워 두세요.', title_nl = 'Spanning voor {milestone_days} dagen! 🌟', body_nl = 'Morgen is een groot, dubbel jubileum! Zowel 10 maanden als {milestone_days} dagen! Breng een klein feestelijk sfeertje in huis en maak ruimte vrij op je telefoon.', title_pl = 'Ekscytacja {milestone_days} dni! 🌟', body_pl = 'Jutro wielki, podwójny jubileusz! I 10 miesięcy, i {milestone_days} dni! Stwórz w domu małą świąteczną atmosferę i wyczyść pamięć telefonu.', title_pt = '{milestone_days} dias de emoção! 🌟', body_pt = 'Amanhã é uma grande data a dobrar! 10 meses e {milestone_days} dias! Crie em casa um pequeno ambiente de festa e liberte memória no telemóvel.', title_sv = '{milestone_days} dagar av förväntan! 🌟', body_sv = 'I morgon är det ett stort dubbeljubileum! Både 10 månader och {milestone_days} dagar! Skapa lite feststämning hemma och rensa telefonens minne.', title_vi = '{milestone_days} ngày háo hức! 🌟', body_vi = 'Ngày mai là ngày kỷ niệm lớn, nhân đôi! Vừa tròn 10 tháng, vừa tròn {milestone_days} ngày! Hãy tạo không khí lễ hội nho nhỏ trong nhà và dọn bộ nhớ điện thoại nhé.', title_zh = '{milestone_days}天的激动！🌟', body_zh = '明天是个双重纪念日！既是10个月，又是{milestone_days}天！在家营造一点节日氛围，清理一下手机内存吧。' WHERE id = 'df82eb33-3f1e-407f-b436-e4b5c122a87e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡FALTAN 5 DÍAS PARA EL MEDIO AÑO! 🎈', body_es = '¡Solo 5 días para el medio año! ¿Tienes listo el pedido de la tarta? Elige ya los marcos especiales de 6 meses en la herramienta Sesión de fotos del bebé y planifícalo todo.', title_fr = 'PLUS QUE 5 JOURS AVANT LES 6 MOIS ! 🎈', body_fr = 'Plus que 5 jours avant le demi-anniversaire ! Votre commande de gâteau est prête ? Choisissez dès maintenant les cadres spéciaux 6 mois dans l''outil Séance photo bébé.', title_hi = 'आधे साल में 5 दिन बाकी! 🎈', body_hi = 'आधे साल में बस 5 दिन! केक का ऑर्डर तैयार है? बेबी फ़ोटोशूट टूल में 6 महीने के खास फ़्रेम अभी से चुनकर प्लान बनाइए।', title_id = '5 HARI LAGI MENUJU SETENGAH TAHUN! 🎈', body_id = 'Tinggal 5 hari menuju setengah tahun! Pesanan kue sudah siap? Pilih dan rencanakan bingkai khusus 6 bulan di Sesi Foto Bayi dari sekarang.', title_ja = 'ハーフバースデーまであと5日！🎈', body_ja = 'ハーフバースデーまであと5日！ケーキの注文はすみましたか？「ベビーフォトセッション」で6か月用の特別なフレームを今から選んで、計画を立てましょう。', title_ko = '반년까지 5일! 🎈', body_ko = '반년까지 딱 5일! 케이크 주문은 준비됐나요? 아기 사진 촬영 도구에서 특별한 6개월 프레임을 미리 골라 계획해 보세요.', title_nl = 'NOG 5 DAGEN TOT EEN HALF JAAR! 🎈', body_nl = 'Nog maar 5 dagen tot een half jaar! Is je taartbestelling klaar? Kies en plan nu al de speciale 6-maandenkaders in de tool Babyfotoshoot.', title_pl = 'DO PÓŁ ROCZKU ZOSTAŁO 5 DNI! 🎈', body_pl = 'Tylko 5 dni do pół roczku! Tort zamówiony? Już teraz wybierz specjalne ramki na 6 miesięcy w Sesji zdjęciowej dziecka i zaplanuj zdjęcia.', title_pt = 'FALTAM 5 DIAS PARA O MEIO ANO! 🎈', body_pt = 'Só faltam 5 dias para o meio ano! A encomenda do bolo está pronta? Escolha já na Sessão Fotográfica do Bebé as molduras especiais dos 6 meses e planeie tudo.', title_sv = '5 DAGAR KVAR TILL HALVÅRET! 🎈', body_sv = 'Bara 5 dagar kvar till halvåret! Är tårtbeställningen klar? Välj och planera redan nu speciella 6-månadersramar i Babyfotografering.', title_vi = 'CÒN 5 NGÀY NỮA LÀ TRÒN NỬA TUỔI! 🎈', body_vi = 'Chỉ 5 ngày nữa là bé tròn nửa tuổi! Mẹ đã đặt bánh kem chưa? Hãy chọn trước những khung ảnh đặc biệt mừng 6 tháng trong công cụ Chụp ảnh cho bé và lên kế hoạch ngay nhé.', title_zh = '距离半岁还有5天！🎈', body_zh = '离半岁只剩5天！蛋糕订好了吗？现在就在宝宝写真里挑选专属的6个月相框，提前规划吧。' WHERE id = 'e6e852b1-bfb4-4197-aa7b-70b6b2367f30' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Solo faltan 10 días para los 11 meses! 🎂', body_es = '¡Es increíble! Dentro de justo 10 días tu peque cumple 11 meses. ¡Es el momento perfecto para empezar a pensar en los planes de su primer cumpleaños!', title_fr = 'Plus que 10 jours avant les 11 mois ! 🎂', body_fr = 'C''est incroyable ! Dans pile 10 jours, votre petit aura 11 mois. C''est le moment idéal pour commencer à penser à la fête de ses 1 an !', title_hi = '11 महीने में बस 10 दिन बाकी! 🎂', body_hi = 'यकीन नहीं होता! ठीक 10 दिन बाद आपका नन्हा 11 महीने का हो जाएगा। अब पहले जन्मदिन की योजना के बारे में सोचना शुरू करने का सही समय है!', title_id = 'Tinggal 10 hari menuju 11 bulan! 🎂', body_id = 'Luar biasa! Tepat 10 hari lagi si kecil genap 11 bulan. Inilah saat yang tepat untuk mulai memikirkan rencana ulang tahun pertamanya!', title_ja = '11か月まであと10日！🎂', body_ja = '信じられない！ちょうど10日後、赤ちゃんは生後11か月。1歳の誕生日の計画を考えはじめるのにぴったりのタイミングです！', title_ko = '11개월까지 딱 10일! 🎂', body_ko = '믿기지 않아요! 딱 10일 뒤면 아기가 11개월이 돼요. 이제 첫돌 계획을 생각하기 시작할 딱 좋은 때예요!', title_nl = 'Nog maar 10 dagen tot 11 maanden! 🎂', body_nl = 'Ongelofelijk! Over precies 10 dagen wordt je kleintje 11 maanden. Hét moment om na te denken over plannen voor de eerste verjaardag!', title_pl = 'Tylko 10 dni do 11 miesięcy! 🎂', body_pl = 'To niesamowite! Za równe 10 dni maluszek skończy 11 miesięcy. To idealny moment, by zacząć myśleć o planach na pierwsze urodziny!', title_pt = 'SÓ FALTAM 10 DIAS PARA OS 11 MESES! 🎂', body_pt = 'É incrível! Daqui a 10 dias certos, o pequenino faz 11 meses. É a altura ideal para começar a pensar nos planos para o 1.º aniversário!', title_sv = 'Bara 10 dagar kvar till 11 månader! 🎂', body_sv = 'Otroligt! Om precis 10 dagar fyller den lilla 11 månader. Nu är det perfekt tid att börja fundera på planerna för 1-årsdagen!', title_vi = 'Chỉ còn 10 ngày nữa là tròn 11 tháng! 🎂', body_vi = 'Thật khó tin! Đúng 10 ngày nữa bé tròn 11 tháng. Đây là lúc thích hợp để bắt đầu nghĩ đến kế hoạch sinh nhật 1 tuổi!', title_zh = '距离11个月只剩10天！🎂', body_zh = '太不可思议了！整整10天后宝宝就满11个月了。现在正是开始考虑一周岁生日计划的好时机！' WHERE id = 'e8d1cc1f-b4b8-4874-a0cc-8f10d75b5769' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Solo 25 días para el primer año! 🎈', body_es = '¡La cuenta atrás ha empezado oficialmente! ¿Has pensado en el lugar y la ropa para la sesión de fotos del primer año? ¡Acelera los preparativos!', title_fr = 'Plus que 25 jours avant ses 1 an ! 🎈', body_fr = 'Le compte à rebours a officiellement commencé ! Avez-vous pensé au lieu et aux tenues pour la séance photo des 1 an ? Accélérez les préparatifs !', title_hi = 'पहले जन्मदिन में बस 25 दिन! 🎈', body_hi = 'उलटी गिनती आधिकारिक रूप से शुरू हो गई! पहले जन्मदिन के फ़ोटोशूट के लिए जगह और कपड़ों के बारे में सोचा है? तैयारी तेज़ कीजिए!', title_id = 'Tinggal 25 hari menuju 1 tahun! 🎈', body_id = 'Hitung mundur resmi dimulai! Sudah memikirkan tempat dan baju untuk sesi foto 1 tahun? Percepat persiapannya!', title_ja = '1歳まであと25日！🎈', body_ja = 'カウントダウンが正式にスタート！1歳のフォトセッションの場所と服は考えましたか？準備をスピードアップしましょう！', title_ko = '첫돌까지 딱 25일! 🎈', body_ko = '카운트다운이 공식적으로 시작됐어요! 첫돌 사진 촬영 장소와 옷은 생각해 보셨나요? 준비를 서두르세요!', title_nl = 'Nog maar 25 dagen tot de eerste verjaardag! 🎈', body_nl = 'Het aftellen is officieel begonnen! Heb je al nagedacht over een locatie en kleertjes voor de fotoshoot van 1 jaar? Versnel de voorbereidingen!', title_pl = 'Tylko 25 dni do roczku! 🎈', body_pl = 'Odliczanie oficjalnie się zaczęło! Myślałaś już o miejscu i stroju na sesję zdjęciową z okazji roczku? Przyspiesz przygotowania!', title_pt = 'SÓ FALTAM 25 DIAS PARA O 1.º ANIVERSÁRIO! 🎈', body_pt = 'A contagem decrescente começou oficialmente! Já pensou no local e na roupa para a sessão fotográfica do 1.º aniversário? Acelere os preparativos!', title_sv = 'Bara 25 dagar kvar till 1 år! 🎈', body_sv = 'Nedräkningen har officiellt börjat! Har du funderat på plats och kläder för 1-årsfotograferingen? Skynda på förberedelserna!', title_vi = 'Chỉ còn 25 ngày nữa là tròn 1 tuổi! 🎈', body_vi = 'Cuộc đếm ngược đã chính thức bắt đầu! Mẹ đã nghĩ đến địa điểm và trang phục cho buổi chụp ảnh 1 tuổi chưa? Hãy đẩy nhanh việc chuẩn bị nhé!', title_zh = '距离一周岁只剩25天！🎈', body_zh = '倒计时正式开始！一周岁写真的场地和服装想好了吗？加快准备吧！' WHERE id = 'ef821341-2506-439d-8346-fbafb2b792ff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡ÚLTIMOS PREPARATIVOS! 📸', body_es = '¡Mañana es el gran día! ¿Está lista la tarta del medio año? Prepara la ropa más bonita para la Sesión de fotos del bebé, ¡mañana haremos muchísimas fotos!', title_fr = 'DERNIERS PRÉPARATIFS ! 📸', body_fr = 'Demain, c''est le grand jour ! Le gâteau des 6 mois est prêt ? Préparez les plus jolies tenues pour la Séance photo bébé, demain on va faire plein de photos !', title_hi = 'आखिरी तैयारियाँ! 📸', body_hi = 'कल बड़ा दिन है! आधे साल का केक तैयार है? बेबी फ़ोटोशूट के लिए सबसे प्यारे कपड़े तैयार रखिए, कल ढेर सारी तस्वीरें लेंगे!', title_id = 'PERSIAPAN TERAKHIR! 📸', body_id = 'Besok hari besar! Kue setengah tahun sudah siap? Siapkan baju terbaik untuk Sesi Foto Bayi, besok kita akan banyak berfoto!', title_ja = '最後の準備！📸', body_ja = '明日は大切な日！ハーフバースデーケーキは準備できましたか？「ベビーフォトセッション」のためにいちばんかわいい服を用意して。明日はたくさん写真を撮りましょう！', title_ko = '마지막 준비! 📸', body_ko = '내일이 큰 날이에요! 반년 케이크는 준비됐나요? 아기 사진 촬영을 위해 가장 예쁜 옷을 준비하세요, 내일은 사진을 많이 찍을 거예요!', title_nl = 'DE LAATSTE VOORBEREIDINGEN! 📸', body_nl = 'Morgen is de grote dag! Is de halfjaartaart klaar? Leg de mooiste kleertjes klaar voor Babyfotoshoot, morgen maken we veel foto''s!', title_pl = 'OSTATNIE PRZYGOTOWANIA! 📸', body_pl = 'Jutro wielki dzień! Tort na pół roczku gotowy? Przygotuj najpiękniejsze ubranka do Sesji zdjęciowej dziecka, jutro zrobimy mnóstwo zdjęć!', title_pt = 'ÚLTIMOS PREPARATIVOS! 📸', body_pt = 'Amanhã é o grande dia! O bolo do meio ano está pronto? Prepare a roupa mais bonita para a Sessão Fotográfica do Bebé, amanhã vamos tirar muitas fotos!', title_sv = 'SISTA FÖRBEREDELSERNA! 📸', body_sv = 'I morgon är den stora dagen! Är halvårstårtan klar? Ta fram de finaste kläderna till Babyfotografering, i morgon blir det många bilder!', title_vi = 'NHỮNG CHUẨN BỊ CUỐI CÙNG! 📸', body_vi = 'Ngày mai là ngày trọng đại! Bánh kem mừng nửa tuổi đã sẵn sàng chưa? Hãy chuẩn bị những bộ đồ đẹp nhất cho buổi Chụp ảnh cho bé, ngày mai mình sẽ chụp thật nhiều ảnh!', title_zh = '最后的准备！📸', body_zh = '明天就是大日子！半岁蛋糕准备好了吗？为宝宝写真准备好最漂亮的衣服，明天我们要拍很多照片！' WHERE id = 'febb037e-33e6-4760-bc42-cae9b6c70a8a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
COMMIT;
